MultiLanguageQuestData['ru'][4447] = {title = "Оскверненный ночной дракон", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil}
MultiLanguageQuestData['ru'][4448] = {title = "Оскверненный ночной дракон", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil}
MultiLanguageQuestData['ru'][4449] = {title = "Попался!", objective = "Убейте 8 геологов из клана Черного Железа и принесите 15 отрезов шелка тому, кто заперт в отхожем месте в Тлеющем ущелье.", description = "Эй! Эй, ты, там! Иди скорей сюда! \n\nПомоги мне! Я спасался бегством от дворфов Черного Железа и попытался спрятаться от них здесь. Проклятые геологи со своей проклятой магией! Они увидели, что я здесь прячусь, и заперли меня здесь! Проучи, проучи этих проклятых геологов! И... это... добудь мне несколько лоскутков шелка... так... вдруг пригодится...", progress = "Я тут уже целый день торчу! Достань мне шелку... э-э... в смысле... геологов! Пусть узнают, что такой мой... в смысле... твой гнев!", completion = "О, какое облегчение! Как я рад, Томпсон! Тебе удалось отомстить проклятым геологам? Их наглость не знала границ, однако. Не знаю как благодарить тебя! Ты это... погоди минутку, мне тут надо закончить некоторые дела...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][4450] = {title = "Учетная книга из Танариса", objective = "Возьмите учетную книгу Кринкеля Сталлера и найдите все перечисленные в ней вещи. Затем отнесите их и книгу Кринкелю Сталлеру в Танарис.", description = "Ты знаешь, мне это кое-что напоминает.\n\nНе хочешь закончить за меня одну работенку, за которую я взялся в Танарисе? Это пара пустяков...\n\nКринкель Сталлинн из Прибамбасска искал какие-то вещи – некоторые здесь, в Тлеющем ущелье, а некоторые в других местах. Может, глянешь на список? Ты наверняка сможешь что-нибудь найти.\n\nЕсли тебе это интересно, я просуну его учетную книгу под дверь. Отнесешь ее ему вместе с разыскиваемыми вещами, когда соберешь их все.", progress = "Да-да? Чем я могу помочь тебе, |3-6(гном)? Я ужасно занят, у меня полно капризных клиентов, которым вынь да положь немедленно их заказ.Так что давай пошустрей со своими делами. Не хочу показаться грубым, но у меня совершенно нет времени на пустую болтовню!", completion = "Ого, да ты смог выполнить эту работу! Прекрасно. Полагаю, теперь ты попросишь меня выковать для тебя что-нибудь. \n\nУ меня есть превосходное оружие и доспехи. Благодарю тебя, |3-6(Чернокнижник)! \n\nДумаю, ты заслужил... хммм... что-нибудь полезное.", rewards = "Заряженный грозовой разрядникРемень отпораВы получите:\n\n"}
MultiLanguageQuestData['ru'][4451] = {title = "Ключ к свободе", objective = "Найдите дверь в Тлеющем ущелье, к которой подходит ключ от дома Грязнули.", description = "Маленький медный ключик выглядит совершенно непритязательно. Единственное, что выдает его значимость, – надпись, выгравированная на бородке: \n\n\"Служебные помещения Черного Железа – изготовление дубликатов строжайше запрещено\".\n\nУ вас нет ни малейшего представления, что это за ключ и куда ведет открываемая им дверь.", progress = "*кашель* Кто там? Не видите что ли, занято!", completion = "Вот те на! Чтоб мне провалиться! Ты нашел ключ! Я знал, что проклятые дворфы Черного Железа спрятали его, после того как заперли меня в этой дыре! О, благодарю тебя, Томпсон! Скорее открой дверь и выпусти старика Локида на свободу!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][4461] = {title = "Гнилой кнутокорень", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil}
