MultiLanguageQuestData['ru'][4463] = {title = "Манускрипт размышления", objective = "Принеси все составляющие, смертный.\n\nКроме того, я потребую с тебя тридцать золотых за создание этой безделушки.", description = nil, progress = "Принеси все составляющие, смертный.\n\nКроме того, я потребую с тебя тридцать золотых за создание этой безделушки.", completion = "Забирай свою безделушку, неразумная тварь. Оставь меня в покое!", rewards = nil}
MultiLanguageQuestData['ru'][4464] = {title = "Оскверненный песнецвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil}
