MultiLanguageQuestData['ru'][7504] = {title = "Святая Болонья: О чем не говорит Свет", objective = "Верните книгу законным владельцам.", description = "Том помечен печатью Читальни.", progress = "Вы ее нашли!", completion = "Отличная работа, |3-6(нежить). Если найдете еще какие-то книги, несите их нам, не раздумывая.\n\nСо временем мы подбираем все новые награды за возвращение пропавших экземпляров!", rewards = "Вы получите:\n\nКоролевская печать Эльдре'Таласа"}
MultiLanguageQuestData['ru'][7505] = {title = "Ледяной шок и вы", objective = "Верните книгу законным владельцам.", description = "Том помечен печатью Читальни.", progress = "Вы ее нашли!", completion = "Отличная работа, |3-6(орк). Если найдете еще какие-то книги, несите их нам, не раздумывая.\n\nСо временем мы подбираем все новые награды за возвращение пропавших экземпляров!", rewards = "Вы получите:\n\nКоролевская печать Эльдре'Таласа"}
MultiLanguageQuestData['ru'][7506] = {title = "Изумрудный Сон", objective = "Верните книгу законным владельцам.", description = "Том помечен печатью Читальни.", progress = "Вы ее нашли!", completion = "Отличная работа, |3-6(ночной эльф). Если найдете еще какие-то книги, несите их нам, не раздумывая.\n\nСо временем мы подбираем все новые награды за возвращение пропавших экземпляров!", rewards = "Вы получите:\n\nКоролевская печать Эльдре'Таласа"}
MultiLanguageQuestData['ru'][7507] = {title = "Nostro's Compendium", objective = "Return Nostro's Compendium of Dragon Slaying to the Athenaeum.", description = "Вы обнаружили нечто очень важное. Эта книга не похожа ни на одну из тех, которые вам доводилось видеть раньше.\n\nТакое впечатление, как будто кому-то удалось испортить печать Читальни. Текст искажен и читается с трудом.", progress = "О, одна из наших лучших компиляций! Я ее уже лет триста не мог отыскать...", completion = "На черном рынке ты мог бы получить за эту книгу немало золота, Ишт! Тем более, что защитная печать теперь сломана, так что тайны драконоборчества доступны любому, кому хватит любопытства, чтобы овладеть знаниями, сокрытыми на священных страницах!\n\nВозможно, ты заслуживаешь ценной награды... Точнее, награды, которую придется добывать ценой громадных усилий!\n\n*Лидрос ухмыляется.*", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7508] = {title = "Ковка Кель-Серрара", objective = "Отдайте тусклый и плоский эльфийский клинок сказителю Лидросу.", description = "Если хотите взять на себя эту задачу, отнесите тусклый клинок Лидросу.", progress = "Отлично! Ну-с, начнем...", completion = "Если тебе удастся войти в логово драконицы, раскали клинок в ее огненном дыхании, а потом остуди в ее собственной крови. И тогда клинок будет навеки твоим.", rewards = nil}
MultiLanguageQuestData['ru'][7509] = {title = "The Forging of Quel'Serrar", objective = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\n\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\n\nDo this and Quel'Serrar will be yours.", description = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.\n\nSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.\n\nPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade.", progress = "Быть может, в один прекрасный день радужным клинком будет владеть другой...", completion = "*Лидрос бормочет нечто невнятное.*\n\nНу, |3-6(Воин), вот тебе клинок Кель-Серрар, как и было обещано.", rewards = "Вы получите:\n\nКель'Серрар"}
MultiLanguageQuestData['ru'][7541] = {title = "Служба Орде", objective = "Нашим ученым нужно время, чтобы изучить принесенную тобой подвеску. Но за то, что ты сделал для Орды, я хочу наградить тебя этим знаком.\n\nСпасибо, Томпсон, твой поступок делает честь тебе и полезен нам.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо преданностиОбруч Одинокого Дерева\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][7562] = {title = "Мор'зул Вестник Крови", objective = "Поговорите с Мор'зулом Вестником Крови у Алтаря Бурь в Пылающих степях.", description = "Ты хорошо <изучил/изучила> темные искусства и <обрел/обрела> такую власть над существам из других миров, что... быть может, пришло время подчинить себе одного из знаменитых коней погибели.\n\nВызвать его в наш мир нелегко, для этого потребуется великая сила и большие затраты, но если ты хочешь владеть таким скакуном, поговори с Мор'зулом Вестником Крови. Он разбил лагерь рядом с Алтарем Бурь в Пылающих степях.\n\nСтупай, <имя>. Задание рискованное, но такие чернокнижники как ты не страшатся опасностей.", progress = nil, completion = "Привет тебе, Душавдушу, и добро пожаловать. Ты пришел сюда ради Алтаря Бурь? Может быть, ты хочешь овладеть его силой ради тайных целей…\n\nИли... просто хочешь поговорить со мной? Да, кажется именно так.\n\nТы хочешь обуздать коня погибели? Нелегкая цель. На это уйдет немало крови, пота и... золота, конечно. Впрочем, конь погибели Зорота стоит того, поэтому слушай...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7563] = {title = "Ярость крови", objective = "Принесите 30 бутылок крови яростных зверей Мор'зулу Вестнику Крови в Пылающие степи.", description = "Кони погибели живут в другом мире, на огненных равнинах Зорота, и чтобы подчинить себе одного из них, необходимы могущественные руны. Я могу начертать эти руны на пергаменте, но для этого нужны особые чернила.\n\nВ далеких Зимних Ключах живут зверосовы. Некогда они были чистыми существами, но демоническое влияние Теснины Зловещего Шепота лишило их разума, и они бродят по снегам в полном безумии.\n\nИз их крови я и сделаю чернила. Остается ее добыть.", progress = "Ты уже видел бешеных отродий, Вилфред? Эти твари исполнены магии, и почти вся она сосредоточена у них в крови.", completion = "А, замечательно. Я переработаю эту кровь в чернила и сделаю обещанный тебе пергамент. Может, я немножко оставлю себе, говорят, вкус у нее необыкновенный...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7564] = {title = "Дикоглаз", objective = "Принесите ларец Крови Горзиеки Дикоглазу в Алтарь Бурь, что в Пылающих степях.", description = "Мой слуга, Горзиеки, довольно опытный алхимик. Он сможет приготовить чернила, о которых шла речь. Я уже подготовил принесенную тобой кровь; отнеси ее Горзиеки, пусть приступает к работе.", progress = "Ты что-то принес? Уж не большого ли и сочного паука? Или таракана? Хоть бы живого... Мне так нравится, когда они еще шевелятся во рту...", completion = "А, это кровь. Наверняка от мастера Морзула. Он ее обожает, и любит, когда она проливается. Я же предпочитаю, чтобы она текла по жилам маленького грызуна. Тогда она остается теплой... до употребления.\n\nВ этой крови заключена великая сила. Наверное, Морзул хочет создать еще один пергамент для призыва коня погибели! Ух, как интересно!\n\nКоли так, то проводить ритуал будешь ты и... тебе понадобится не только кровь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7581] = {title = "Тюремные кандалы", objective = "Отправляйтесь в Забытый Город, что в Фераласе и добудьте 15 порций крови сатиров из племени Исчадий Природы, что живут в Квартале Криводревов. Вернитесь к Дайо из Гниющего Шрама по выполнении поручения.", description = "Ты <должен/должна> добыть у младших демонов кандалы для стражника ужаса.\n\nКровь сатира из племени Буйного Нрава, что живут в Забытом Городе, для этого сгодится. Свернувшаяся кровь скрепит осколки Хедерины и даст силу кристаллической тюрьме.", progress = "Подойдет только кровь сатиров из племени Исчадий Природы.", completion = "Ах, просто замечательно! Эта кровь подавит магическое сопротивление стражника ужаса.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7582] = {title = "Тюремная камера", objective = "Отправляйтесь к Теснине Зловещего Шепота в Зимних ключах и добудьте 5 слез Хедерины у демонов Хедерины, что населяют эту теснину. Вернитесь к Дайо из Гниющего Шрама по выполнении поручения.", description = "Демоны Хедерины, что живут у подножия горы Хиджал, выделяют яды Скверны, которые вызревают и твердеют, образуя антимагические кристаллы. Они известны как слезы Хедерины.\n\nДаже чудовищная сила стражника ужаса не сможет разбить стены тюрьмы, сделанной из этого материала.\n\nОтправляйся в Теснину Зловещего Шепота в Зимних ключах, и добудь этих слез.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7583] = {title = "Подавление", objective = "Отправляйтесь в Гниющий шрам и и найдите командира стражников ужаса.\n\nПри помощи светящегося кристалла заточения поймайте командира стражников ужаса. Будьте готовы к отчаянным атакам и сопротивлению, поскольку демон будет пытаться избежать заточения.\n\nЕсли вы добьетесь успеха, отнесите пленного стражника ужаса Дайо в Гниющий шрам.", description = "Темница готова. Теперь самое трудное дело.\n\nТы <должен/должна> найти и схватить командира стражников ужаса в Гниющем шраме при помощи этой хрустальной темницы.\n\nОсторожнее! Стражник ужаса -коварный и смертельный враг, он будет пытаться уничтожить тебя, как только ты начнешь обряд заточения. Он будет отчаянно отбиваться, пытаясь избежать плена.\n\nОн будет смотреть только на тебя, <имя>. Потому я рекомендую взять с собой друзей, которые не дадут ему погубить тебя!", progress = "Ну? Как?", completion = "Ты сделал все, как я просил. Теперь ты готов воспринять знание о том, как призывать и контролировать тварей.", rewards = "Вы изучите:\n\nПризыв стража ужаса\n\nВы также получите:\n\nФолиант Жертвоприношения"}
MultiLanguageQuestData['ru'][7601] = {title = "Что хочет Ниби", objective = "Поговорите с Бесенком в Оскверненном лесу.", description = "Если хочешь научиться у меня призывать инфернала-слугу, ты <должен/должна> убить Крошиуса и добыть из его пылающих останков огненное ядро. Но это не так просто, как кажется. Крошиус чуть не дотла сгорел. Тебе придется снова воспламенить его тело и поднять его из праха. Но для этого тебе придется добыть другие ингредиенты из других демонических сущностей.\n\nМой бес по имени Бесенок покажет тебе дорогу.", progress = nil, completion = "Ох, опять двадцать пять...", rewards = nil}
MultiLanguageQuestData['ru'][7602] = {title = "Безупречная субстанция Скверны", objective = "Бесенок из Оскверненного леса просит вас принести ему три порции безупречной субстанции скверны из трех различных мест.\n\nБезупречной субстанцией в Азшаре владеют сатиры из племени Легаши. В Джеденаре она есть у джеженарских легионеров. Стражи Скверны в Выжженных землях владеют этой субстанцией в своих краях.\n\nДобудьте три типа безупречной субстанции Скверны и возвращайтесь к Бесенку в Оскверненный лес.", description = "Если ты намереваешлся воскресить Крошиуса, тебе понадобится пламя Скверны. Я могу зажечь его, но для этого потребуются кое-какие ингредиенты.\n\nТебе придется принести мне безупречной субстанции Скверны из трех краев нашего мира.\n\nПервый тип субстанции ты найдешь у сатиров из племени Легаши, что в Азшаре. Второй тип – у джеденарских легионеров, а третий можно добыть у стражей Скверны в Выжженных землях.\n\nПринеси мне по порции каждой субстанции, и я зажгу пламя скверны, что позволит тебе оживить Крошиуса.", progress = "Ты только никому не говори, что Ниби дурак.", completion = "Одну минуточку, и я сотворю из всех трех субстанций пламя Скверны.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7603] = {title = "Огненное ядро Крошиуса", objective = "Обыщите долину Рваных Ран в Оскверненном лесу и найдите останки Крошиуса. Когда вы их найдете, поднесите к ним пламень Скверны и подождите, пока Крошиус не восстанет из праха. Когда инфернал очнется, убейте его и возьмите из его тела огненное ядро Крошиуса.\n\nПринесите огненное ядро Крошиуса Ниби Всемогущему в Оскверненный лес.", description = "Крошиус лежит грудой праха на северо-востоке отсюда, в долине Рваных Ран. Возьми этот пламень Скверны и воспламени его останки. Пламя оживит павшего инфернала.\n\nПосле этого он наверняка пришибет и тебя, и твоего приспешника.\n\nЕсли каким-то чудом тебе удастся уложить Крошиуса, возьми его огненное ядро и принеси Ниби.", progress = "Ты заблудился, что ли?", completion = "Сделка есть сделка! Бери это и быстро записывай. У меня нет времени! На нас прет мое самое величайшее творение!", rewards = "Вы изучите:\n\nПризыв инфернала\n\nВы также получите:\n\nОсколок Зеленого Пламени"}
MultiLanguageQuestData['ru'][7604] = {title = "Заключение договора", objective = "Подпишите договор с представителем Братства Тория Локтосом Зловещим Торговцем, если вам нужен чертеж Сульфурона.", description = "<Нижеподписавшийся/Нижеподписавшаяся> со всей ответственностью заявляет, что сульфуронский слиток, переданный <им/ею> братству Тория (ООО \"БТ\"), является подлинником. <Нижеподписавшийся/Нижеподписавшаяся> также подтверждает, что ООО \"БТ\" не несет никакой ответственности за любой вред, могущий последовать в результате неосторожного обращения с Сульфурасом, как то: использование Сульфураса в качестве материала для ковки; самостоятельные разработки; попытки воспроизведения; продажа и употребление в пищу.\n\nПодпись под договором автоматически означает согласие <подписавшегося/подписавшейся> со всеми условиями, перечисленными в документе.\n\n_______________\n\nПодпись", progress = "Стало быть, ты согласен со всеми условиями?", completion = "С тобой приятно иметь дело, Мечищит!\n\nОт имени ООО \"БТ\" я желаю тебе удачи в поисках Сульфураса!", rewards = "Вы получите:\n\nЧертеж: сульфуронский молот"}
MultiLanguageQuestData['ru'][7621] = {title = "Предупреждение", objective = "Жрец, ты стоишь на пороге серьезных испытаний, которым подвергнешься для проверки твоих способностей.\n\nПослушай, что я скажу тебе.\n\nЗапомни, ты должен проходить испытания самостоятельно. Пусть твои союзники отойдут на безопасное расстояние и ждут, не вмешиваясь. Любое вмешательство может повлечь за собой самую строгую кару.\n\nСудьба привела сюда тебя и только тебя. Вступи в битву с честью. Да пребудет с тобой Свет.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][7622] = {title = "Баланс Света и Тьмы", objective = "Спасите жизни 50 крестьян прежде, чем 15 из них будут убиты. Поговорите с Эрис Тайнопламень по выполнении задания.\n\nЧисло погибших крестьян можно узнать, посмотрев на Колья Смерти.", description = "Тебе предстоит сделать то, что оказалось не под силу мне – спасти крестьян, погибших во время бегства из Стратхольма.\n\nОни выйдут на свет, и ты <должен/должна> защитить их. Если ты не сможешь спасти слишком многих, мы продолжим влачить наше проклятое существование.\n\nЭто настоящее испытание для всех твоих способностей. Да поможет тебе Свет, <имя>.", progress = nil, completion = "Твоя смелость и упорства не имеют себе равных, жрец. Ты обрел право владеть расщепителем Нордрассила. Тебе осталось исполнить лишь одно: найти Око Тени. Найди его, даже если тебе придется обыскать весь мир.", rewards = "Вы получите:\n\nЩепка Нордрассила"}
MultiLanguageQuestData['ru'][7623] = {title = "Лорд Гиблопуст", objective = "Купите зелья Теней у Горзиеки в Алтаре Бурь, что в Пылающих степях.\n\nПриняв зелья, пройдите через Джеденар в Оскверненном лесу и поговорите с лордом Гиблопустом, который находится в Оплоте Теней.", description = "Морзул говорит, что ты хочешь открыть портал в Зорот. Раз так, тебе не обойтись без зоротианской звездной пыли. А ее нелегко найти в Азероте!\n\nОна может быть лишь у одного существа – лорда Гиблопуста из Джеденара, сердца Совета Теней! Поговори с ним, вдруг он поделится звездной пылью.\n\nВпрочем, отправляясь в Джеденар, тебе необходимо принять злое обличье, чтобы добраться до Совета Теней. Значит, тебе нужны мои зелья Теней, а они недешевы...", progress = nil, completion = "Мое терпение бесконечно, |3-6(Чернокнижник). Но это не значит, что я уделю тебе больше секунды времени...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7624] = {title = "Улатек Предатель", objective = "Сразитесь с Улатеком и принесите сердце предателя лорду Гиблопусту в Джеденар.", description = "Хочешь заслужить мою милость? Что ж, тогда убей, кого я укажу.\n\nМой слуга, Улатек, пресмыкается передо мной, а тем временем умышляет против меня вместе с лордом Хел'нуратом из Зорота. Хел'нурат хочет низвергнуть меня и захватить власть, а Улатек – его шпион...\n\nДокажи, что служишь мне, а не моим противникам. Вступи в бой с Улатеком в его собственном доме, Оплоте Теней на западе. Передай ему, что мне известна его тайна. Вот увидишь, он затрясется от страха. Принеси мне сердце предателя!", progress = "Я уже чувствую вкус сердца Улатека на губах. Как сладка плоть предателя...", completion = "Ах, великолепно! Полежав с недельку, оно обретет ни с чем не сравнимый вкус! Может быть, мне послать за головой Улатека и поставить себе на обеденный стол?..\n\nТы оказал мне услугу, |3-6(Чернокнижник), и я уже терпимей отношусь к тебе. Немного терпимей.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7625] = {title = "Зоротианская звездная пыль", objective = "Купите зоротианскую звездную пыль у Ур'Дана из Оплота Теней в Джеденаре, что в Оскверненном лесу. Отнесите ее Горзиеки Дикоглазу в Пылающие степи.", description = "Так ты <явился/явилась> в поисках зоротианской звездной пыли? Ты хочешь открыть портал в Зорот, владения моего соперника Хелнурата? Уж не одного ли из его драгоценных коней погибели ты хочешь украсть?\n\nОтлично. У моего слуги, Ур'Дана, есть большой запас зоротианской звездной пыли. Обращайся к нему... если денег хватит.", progress = "Ты уже побывал в Джеденаре? Удалось получить звездную пыль у лорда Гиблопуста?", completion = "Вот она! Даже не верится! Должно быть, ты заключил большую сделку с Повелителем ужаса или заплатил огромную сумму, или и то, и другое!\n\nМор'зул скоро получит чернила и сделает для тебя пергамент с рунами. Ты откроешь портал в Зорот и украдешь одного из знаменитых коней погибели!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7626] = {title = "Колокол Детмуры", objective = "Отнесите 2 эликсира энергии Тьмы Горзиеки Дикоглазу в Пылающие степи.", description = "Колокол Детмуры назвали в честь Детмуры Темноглазой. Это один из трех предметов, необходимых для создания круга Великого призыва. Сопряженный с Колесом и Свечой, он предоставит в твое распоряжение огромный запас магической энергии.\n\nМой слуга Горзиеки может создать такой колокол, но ему понадобится много эликсиров энергии Тьмы. Добудь их у алхимика и отнеси Горзиеки.", progress = "Ты несешь мне эликсиры, Нидза? Морзул говорит, что тебе нужен Колокол Детмуры, а на его создание нужно много темной силы!", completion = "Отлично! Надеюсь, достать эликсиры было не слишком сложно. Иногда алхимики очень ревниво относятся к своим творениям…\n\nЯ сделаю колокол и отдам его, когда ты будешь готов провести ритуал.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7627] = {title = "Колесо Черного Похода", objective = "Отнесите 6 больших блестящих осколка и 25 кусков руды черного железа Дикоглазу в Пылающие степи.", description = "Колесо Черного Похода содержит в себе и направляет черную силу, необходимую для создания круга Великого призыва. Горзиеки может создать это колесо, но ему понадобятся большие сверкающие осколки, которые получают зачаровыватели, и руда черного железа, которую может добыть опытный горняк.\n\nПринеси моему слуге все необходимое.", progress = "Колесо Черного Похода трудно сделать, и для него нужно много составляющих. Ты уже их собрал?", completion = "Ага, вот они! Я слышал,что черное железо добывают лишь в глубинах Черной горы, да и осколки не даром тебе достались. Меня всегда поражает целеустремленность чернокнижников. Кабы все эти силы, да на поимку жуков, такой пир бы получился!\n\nПрости, отступил от темы. Я сделаю колесо и отдам его, когда ты будешь готов провести ритуал.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7628] = {title = "Свеча Судного дня", objective = "Принесите 3 куска чешуи черного дракона Горзики Дикоглазу в Пылающие степи.", description = "Свеча Судного дня хранит в себе огонь, который опаляет всех, желающих прервать твой ритуал. Зажигая свечу при создании круга Великого призыва, ты сожжешь всех упрямых демонов!\n\nВпрочем, сдержать этот огонь довольно трудно, и для этого нужна чешуя черного дракона. Купи ее у мастера снятия шкур и принеси Горзиеки Дикоглазу.", progress = "Ты несешь мне чешую дракона, Вилфред? Я и браться не буду за изготовление свечи, пока не получу ее... а то весь лагерь может взлететь на воздух!", completion = "А, хорошо. При помощи чешуек я смогу обуздать пламя свечи. Теперь я возьмусь за работу, и отдам тебе свечу, когда ты будешь готов провести ритуал.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7629] = {title = "Доставка беса", objective = "Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзики Дикоглазу.", description = "Для подготовки пергамента Мор'зула осталось сделать только одно – напитать бумагу зоротианской звездной пылью. И... боюсь, здесь этого не сделать. Мне не хватит оборудования!\n\nВпрочем, я знаю об одной лаборатории, где есть все необходимое. Она находится в Некроситете, на острове Каэр Дарроу, в Чумных землях.\n\nЯ туда отправиться не смогу, но у меня есть идея. Возьми эту бутылку. В ней сидит довольно умный бес. Выпусти его в алхимической лаборатории, и он напитает пергамент звездной пылью.", progress = "Ты уже побывал в Некроситете? Напитал ли бес пергамент звездной пылью?", completion = "Славно. Д'живи создал пергамент. Как тебе Некроситет? Правда, там ужасно интересно? А какие там жуки... Говорят, вкуснейшие!\n\nСпасибо тебе, Нидза, спасибо, что вернул мой флакон. Он у меня давно... и не продается!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7630] = {title = "Арканит", objective = "Принесите 1 арканитовый слиток Горзики в Пылающие степи.", description = "Итак, колокол, колесо и свеча готовы. Осталось создать черный магнит. Он понадобится во время ритуала, поддерживать прочие объекты, на случай, если они подведут.\n\nДля создания магнита мне понадобится арканит. У тебя его нет? Коли так, поищи его у алхимика.\n\nПринеси мне арканит, и я создам черный магнит.", progress = "И где арканит, Нидза? Как только ты его принесешь, я сделаю тебе черный магнит.", completion = "Ты принес его! Отлично! Теперь я могу создать магнит. Когда ты начнешь ритуал создания круга Великого призыва, тебе понадобится магнит, чтобы уж точно довести его до конца!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7631] = {title = "Зоротианский конь погибели", objective = "Прочтите инструкции Мор'зула. Призовите зоротианского коня погибели, одолейте его и подчините его дух.\n\nПрилагается предмет: \n", description = "Все готово. Пришло время провести ритуал создания круга Великого призыва и воспользоваться пергаментом с рунами, начертанными зоротианской звездной пылью... И отрыть портал в Зорот.\n\nВсе инструкции по проведению ритуала я записал в тот свиток. Изучи его внимательно, потому что следует делать все в точности так, как написано, или успеха не добиться.\n\nУдачи, <имя>. И да попадут души твоих врагов в твой мешочек осколков.", progress = nil, completion = "Дух ксоротианского коня погибели повержен. Хотя он в ярости, вы чувствуете, что душа его принадлежит вам…\n\nОна нашептывает темные слова, благодаря которым вы постигаете, как вызывать коня погибели.", rewards = "Вы изучите:\n\nКонь погибели\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][7632] = {title = "Древний лист", objective = "Найдите хозяина древнего окаменелого древесного листа. Удачи, <имя>, мир велик.", description = "Кожица листа светится ярко-зеленым. Его поверхность очень морщиниста, на ней видны многочисленные прожилки и бороздки.\n\nЕсли задуматься, то этот лист – наверняка нечто очень древнее и могущественное.\n\nМожет, поискать, кому он принадлежит?", progress = "*Вартус кряхтит.*", completion = "Еще бы мне не узнать собственный лист! Смотри-ка! В великолепном состоянии.\n\nОчень мило с твоей стороны вернуть его, |3-6(Охотник).\n\nВозможно, ты сможешь сослужить нам службу, а мы – тебе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7633] = {title = "Посвящение", objective = "Твоя преданность и искренность не остались незамечены, |3-6(Охотник).\n\nМы – Дерева, защитники этого некогда великого леса. Наши тела погибли 10 000 лет назад, когда Архимонд и Пылающий Легион прошли по горе Хиджал. Однако, души наши не погибли.\n\nЕсть у нас несколько заданий для тебя. Если ты их выполнишь, тебе будут открыты тайны Дерев.\n\nЗнай – если выполнишь их, просто возвращайся к этой скале, и мы ответим на твой зов.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][7634] = {title = "Перетянутый жилами лист древня", objective = "Хастат Древний просит вас принести ему жилу взрослого синего дракона. По выполнении задания возвращайтесь к Хастату в Оскверненный лес.", description = "Приветствую тебя, <класс>. Я Хастат, древо мудрости. Я храню память тысячелетий.\n\nЕсли один из моих листьев свернуть надлежащим образом, он будет служить колчаном, подобных которым не было уже 10 000 лет. Если к этому колчану в пару получить еще и лук Древ, то силе их равных не будет.\n\nПринеси мне жил взрослого синего дракона, и получишь колчан.", progress = "С возвращением, юный |3-6(Охотник).", completion = "Да защитят мои листья твои стрелы! Да не ведают они промаха! Да сгинут враги нашего мира!", rewards = "Вы получите:\n\nПеретянутый жилами лист древня"}
MultiLanguageQuestData['ru'][7635] = {title = "Подходящая тетива", objective = "Стома Древний просит вас принести ему жилу взрослого черного дракона. Добыв жилу, возвращайтесь к Стоме в Оскверненный лес.", description = "Вартус, конечно, предложил тебе посох для лука Дерев, но наложить чары на тетиву, без которой лук – не лук, могу только я.\n\nЭто простое дело, совсем плевое. Убей взрослого черного дракона и добудь из него жилу. Принеси мне эту жилу, и я зачарую ее так, что тетива для лука из нее будет, считай, вечной.", progress = "Я уверен, что ты без труда найдешь и убьешь черного дракона, Борро. Не отнимай у меня времени пустой болтовней.", completion = "Это был самый мерзостный из драконов. Жила просто смердит злом.\n\nПодожди немного – я очищу ее и наложу соотвествующие чары.", rewards = "Вы получите:\n\nЗачарованная жила черного дракона"}
MultiLanguageQuestData['ru'][7636] = {title = "Ветвь ходячего Древа", objective = "Вы должны найти и уничтожить следующих четверых демонических разносчиков порчи:\n\nСимон Совратительницу.\n\nКлинфрана Безумного.\n\nСоленора Убийцу.\n\nАрториуса Судьбоносного.\n\nУничтожьте этих тварей и возвращайтесь к Вартусу Древнему в Оскверненный лес с их головами.\n\nВ поисках местонахождения этих демонов сверяйтесь с окаменевшей корой.\n\nВы ОБЯЗАНЫ выполнить это задание в одиночку.", description = "Тайные слуги Пылающего Легиона все еще строят козни в нашем мире, <класс>. Они оскверняют все, к чему прикасаются. Природа чахнет и стенает от их присутствия.\n\nТы <должен/должна> выследить этих демонических разносчиков порчи, <имя>. Помни – ты <должен/должна> лично разобраться с ними – иначе сбегут. Пока ты <один/одна>, они будут пытаться уничтожить тебя. Ты <должен/должна> сразить их, обратить их надменность в ничтожество!\n\nЯ дам тебе кусок моей коры. Письмена на ней приведут тебя к нашим врагам. Принеси мне их головы.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nДревний резной рунический посох"}
MultiLanguageQuestData['ru'][7637] = {title = "Жертва необходима", objective = "Доберитесь до Стальгорна и получите курильницу экзорцизма у верховного жреца Рохана. За курильницу нужно будет внести плату в размере 150 золотых.", description = "Чтобы подготовиться к этому заданию, ты <должен/должна> сначала показать умение жертвовать и умение судить... в первую очередь – жертвовать.\n\nДля выполнения задания ты <должен/должна> получить курильницу экзорцизма у верховного жреца Рохана. Несмотря на то, что ее использование будет продиктовано благими намерениями и существенными причинами, за нее должна быть предложена соответственная компенсация.\n\nОтправляйся в Стальгорн и поговори с верховным жрецом. Если возьмешь с собой достаточно звонкой монеты, чтобы компенсировать ему потерю курильницы, ты проявишь должную готовность к жертвам.\n\nА теперь иди, <имя>, время терять нельзя.", progress = "Приветствую тебя, благородный паладин! Я наполнил свою верную курильницу свежайшими благовониями и трижды благословил ее специально для тебя. Твое пожертвование поможет нам здесь, в Стальгорне, не только изготовить новую курильницу, но также пополнить оскудевающие запасы пищи для наших нужд.", completion = "Да пребудут на тебе все благословения, друг мой паладин! Твой дар далеко превосходит наши нужды. Твоя жертва не только поможет восстановить утраченное, но также позволит нам помочь самым бедным жителям Стальгорна.\n\nА теперь дай-ка я удостоверюсь, что как следует подготовил эту курильницу для твоих будущих свершений.", rewards = nil}
MultiLanguageQuestData['ru'][7638] = {title = "Лорд Грейсон Тенелом", objective = "Поговорите с лордом Грейсоном Тенеломом в Соборном квартале Штормграда.", description = "Пришло твое время, <имя>, узнать о том, как найти то, что ты, без сомнения, хочешь заполучить уже в течение некоторого времени... твоего рыцарского коня.\n\nПоговори с лордом Грейсоном Тенеломом здесь, в Соборном квартале Штормграда. Именно он не только раскроет тебе все секреты самого верного паладинского скакуна, но и поможет разобраться в задачах, которые встанут перед тобой, прежде чем ты сможешь раздобыть своего собственного коня.\n\nЯ желаю тебе всего наилучшего в этом испытании. Во имя Света, <мой благородный брат/моя благородная сестра>!", progress = nil, completion = "Я рад видеть тебя, Палдосий. Я знаю, что ты желаешь раздобыть рыцарского коня, и вот наконец время пришло.\n\nТы, конечно, должен будешь пройти разнообразные испытания, но самое главное – это твоя решимость преодолеть множество препятствий, что встанут перед тобой. Это не учебные задачи – ты уже явно перерос их. Тебе придется вырвать своего будущего скакуна из лап того зла, борьбе с которым ты посвятил свою жизнь.\n\nРешай же, твое время пришло!", rewards = nil}
MultiLanguageQuestData['ru'][7639] = {title = "Демонстрация истинного правосудия", objective = "Принесите курильницу экзорцизма лорду Грейсону Тенелому в храмовый квартал Штормграда.", description = "Прими эту курильницу и будь <благословен/благословенна>. Я сам применял ее в нескольких обрядах экзорцизма, и она хорошо послужит тебе в грядущих тяжких испытаниях.\n\nНыне возвращайся к лорду Грейсону Тенелому в Штормград, <имя>. Он даст тебе поручение.", progress = "С возвращением, Палдосий. Вы принесли курильницу экзорцизма?", completion = "Да, это она. Не раз вам придется совершать этот обряд и не раз вам придется в ходе него жертвовать собой. Я рад, что вы готовы к этому. Жертвенность – важнейшая составляющая, без которой не выполнить долга паладина... но не мне говорить вам об этом.\n\nА теперь, Палдосий, вам придется проявить истинное правосудие в ваших делах. И эта курильница послужит вашим сосудом для оказания помощи истерзанным духам утраченной нами земли.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7640] = {title = "Изгнание призраков из Долины Ужаса", objective = "Используйте курильницу экзорцизма для вызова из-под земли призраков, мучающих долину Ужаса. Когда убьете 25 духов долины Ужаса, вернитесь к лорду Грейсону Тенелому в храмовый квартал Штормграда.", description = "Я добавил в курильницу щепотку зараженной земли Долины Ужаса, что в Восточных Чумных землях. Ты <должен/должна> будешь использовать курильницу для поиска мест, которые несут на себе признаки беспокойного поведения потусторонних сил. Ищи зеленое свечение, исходящее из-под земли – так физический мир проявляет себя, мучимый миром потусторонним, и используй курильницу для вызова из-под земли злых духов.\n\nКогда свершишь суд над призраками, я поставлю перед тобой новую задачу.", progress = "Приятно вновь увидеться с тобой, Палдосий. Завершена ли твоя работа в Долине Ужаса?", completion = "Отличная работа, Палдосий. Свершить суд Света над теми, кто обитает во тьме – задача, к выполнению которой мы должны подходить с рвением и усердием. Именно это ты и свершил благодаря своей жертве в Стальгорне и правосудию над духами Долины Ужаса.\n\nТвои следующие шаги вновь потребуют от тебя и жертвенности, и умения вершить правосудие: ведь тебе нужно будет вернуть дух рыцарского коня, который служит сейчас рыцарю смерти, известному как Темный Губитель.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7641] = {title = "Работа Гриманда Элмора", objective = "Поговорите с Гримандом Элмором в Квартале Дворфов Штормграда.", description = "Без особого чепрака рыцарский конь паладина ничем не отличается от обычного скакуна. Чепрак для твоего скакуна не только должен быть изготовлен из наилучших материалов, но в силу сопутствующих обстоятельств нужно, чтобы он еще был в достаточной мере настроен на призрачный мир.\n\nНо все по порядку, <имя> – сначала нужно изготовить чепрак. В Квартале Дворфов Штормграда проживает один из самых лучших современных мастеров – Гриманд Элмор. Он берет за свою работу недешево, но качество его работы – как раз то, что нам нужно. Поговори с ним.", progress = nil, completion = "Привет-привет, паренек – лорд Победитель Тени известил меня заранее о том, что ты придешь со мной повидаться. Я с удовольствием сделаю чепрак, какой тебе нужен, но это будет нелегко, да и обойдется недешево. Я об этом говорю открыто и в первую очередь.\n\nНо, скажу я тебе – и Грейсон поддержит меня в этом утверждении – лучшего чепрака, чем изготовленный мной, ты во всем Азероте не найдешь!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7642] = {title = "Сбор необходимого", objective = "Принесите Гриманду Элмору в Квартал дворфов Штормграда 40 отрезов рунической ткани, 6 арканитовых слитков, 10 цветков слезы Артаса, 5 сосудов со святой водой из Стратхольма и 150 золотых монет.", description = "Для чепрака тебе понадобятся четыре вещи: руническая ткань для подкладки, арканитовые слитки для покрытия, цветки слезы Артаса для настройки на призрачный мир и святая вода из Стратхольма для духовного укрепления. На самом деле, вещей понадобится пять... если считать золото для меня. Эта плата – за весь мой труд, а также седло и стремена ручной работы.\n\nКогда наберешь все это, я смогу изготовить твой чепрак. А пока ты ищешь необходимое, я приступлю к работе.", progress = "А, это ты, Палдосий. Я не смогу закончить изготовление чепрака без тех вещей, о которых я тебе говорил. Удалось ли тебе собрать все?", completion = "Это... да, это именно то, что нужно. А ты весьма находчивый паладин, не так ли?\n\nЛадненько, давай-ка закончим с твоим чепраком!", rewards = nil}
MultiLanguageQuestData['ru'][7643] = {title = "Дух древнего коня", objective = "Купите лошадиный корм для духа древнего коня у Меридет Карлсон в Южнобережье.\n\nУбейте Тендриса Криводрева в башне Забытого Города в Фераласе и освободите духа. Накормите духа кормом и получите благословление для арканитового чепрака.", description = "Твоему чепраку нужно особое благословение, а его можно получить только у подходящего духа. Такой дух обитает, например, в башне Забытого Города – это Дух древнего коня. Сейчас его удерживает в плену Тендрис Криводрев. Убей эту тварь, чтобы освободить духа, <имя>.\n\nТолько имей в виду, что просто освободить – недостаточно. Тебе нужно сначала умилостивить духа, чтобы получить его благословение. Для этого понадобится особый лошадиный корм. Ты найдешь его в Южнобережье, если поговоришь с Меридет Карлсон.", progress = "Дух древнего коня внимательно взирает на вас – так, словно ждет чего-то.", completion = "Дух древнего коня обнюхал корм и чинно захрустел им. Насытившись, дух благосклонно позволил вам накинуть чепрак ему на спину.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7644] = {title = "Благословенный арканитовый чепрак", objective = "Вернитесь с благословенным арканитовым чепраком к лорду Грейсону Тенелому в храмовый квартал Штормграда.", description = "После того как чепрак наброшен на спину духу древнего коня, он начинает чуть заметно светиться. На миг кажется, будто все вокруг звенит от напряжения и магической мощи... а потом чепрак исчезает со спины коня. Теперь он в вашем заплечном мешке.\n\nОчевидно, чепрак получил благословение. Теперь, согласно наставлениям лорда Победителя Тени, вам следует вернуться с этим чепраком к нему в Штормград.", progress = "Отхилюотпорю, ты вернулся! Ну что, удалось тебе справиться с Меридет Карлсон и Тендрисом Тенеломом? Честно говоря, даже и не знаю, кто из них опаснее...", completion = "Тебе пришлось немало постранствовать, друг мой! И вот наконец твой чепрак готов к последнему шагу, который тебе придется предпринять.\n\nЭтот чепрак пригодится тебе, чтобы седлать своего скакуна, когда труд искупления будет завершен. Однако до этого тебе снова придется вступить в тяжкую борьбу. Твой час близок!\n\nПеред этим нам нужно изготовить еще один, последний предмет. Надеюсь, твой пыл еще не иссяк?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7645] = {title = "Сытный манный лошадиный корм", objective = "Принесите 20 cытных манных печений – ключевых составляющих сытного манного лошадиного корма – Меридет Карлсон в Южнобережье в предгорьях Хилсбрада. Продается печенье только в Серебряном Рассвете.\n\nКроме того, понадобится дать ей 50 золотых, чтобы успокоить ее ущемленное самолюбие.", description = "Серебряная Длань посчитала меня ЧОКНУТОЙ, когда я сказала, что могу сделать особый конский корм, который насытит призрачных лошадей. ВСЕ считали меня чокнутой! Пришло время отыграться!\n\nЯ сделаю, что тебе надо, ПАЛАДИН... ЗАЩИТНИК, тоже мне... Но обойдется это недешево. Мне понадобится сытное манное печенье, которое продают только в Серебряном Рассвете. Кроме того я требую – да, ТРЕБУЮ, золото в качестве компенсации за перенесенные страдания!\n\nПосмотрим, многим ли ты можешь пожертвовать, ПАЛАДИН.", progress = "Да, я доказала, что ты неправ? Все они ошибались! Я БЫЛА ПРАВА ВСЕ ЭТО ВРЕМЯ!!!", completion = "ДА, КТО...стоп, ты и золото мне даешь? Лично ты не называл меня чокнутой – а они дразнили меня сдвинутой, слетевшей с катушек... И ты хочешь искупить зло, причиненное не тобой?\n\nЯ... я недооценила тебя, Палдосий. Если тебе понадобится еще корм для коней, обращайся. Я сделаю его бесплатно. Спасибо... благородный паладин.\n\nНо деньги я себе оставлю – я не настолько чокнутая, чтобы отказаться от целого состояния.", rewards = "Вы получите:\n\nСытный манный лошадиный корм"}
MultiLanguageQuestData['ru'][7646] = {title = "Магический кристалл", objective = "Принесите азеротский алмаз и безупречный черный алмаз лорду Грейсону Тенелому в Соборный квартал Штормграда.", description = "Теперь мы должны сконструировать магический кристалл – так начнется твой подвиг и освобождение плененного духа зловещего рыцарского коня. Собственно, кристалл уже почти готов. Катализатором для него послужила курильница, которую ты <использовал/использовала>, изгоняя духов из долины Ужаса; осталось только сделать подходящую подставку для нашего прибора.\n\nДа, и еще нужны последние два компонента – азеротский алмаз и безупречный черный алмаз. Эти два камня станут маяком, пронзающим тьму!", progress = "Ты продвинулся уже так далеко, Отхилюотпорю. Твой последний акт жертвования мирскими вещами станет залогом одного из твоих величайших достижений. Я это чувствую всем своим существом!", completion = "Отличные камни, Отхилюотпорю. Последние фрагменты теперь установлены на свои места. Наконец-то, пришло твое время!\n\nВ глубине Главного склепа в Некроситете покоятся останки многих существ. Среди них есть кости и некогда благородного рыцарского коня. Призрачный дух скакуна теперь служит рыцарю смерти Темному Терзателю. Ты победишь Терзателя и свершишь правый суд над его несчастным конем. Только ты, Отхилюотпорю, можешь даровать душе скакуна искупление и избавить ее от мук ужасного служения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7647] = {title = "Суд и расплата", objective = "Используйте магический кристалл в центре подвала Великого оссуария в Некроситете. Победите вызванных духов, а затем – рыцаря смерти Темного Терзателя, который появится после поражения духов.\n\nВерните падшему скакуну Темного Терзателя его спасенную душу и покройте его благословенным зачарованным чепраком.", description = "Возьми эту сумку – в ней собраны предметы, которые понадобятся тебе для выполнения задания.\n\nИспользуй магический кристалл в самом сердце подвала Великого оссуария для вызова проклятых духов, над которыми нужно свершить суд. Во время испытания рассчитывай силы – духи могут оказаться сильнее, чем ты думаешь. После гибели духов появится сам рыцарь смерти. Срази его и верни потерянную душу рыцарского коня. Только тогда, <имя>, ты сможешь принести ей избавление и возложить чепрак на твоего нового скакуна.\n\nЖелаю удачи!", progress = "Дух зловещего рыцарского коня смотрит на вас тоскливым взором. В его мертвых глазах уже давно погас огонь надежды.", completion = "Искорка жизни, давно покинувшей бедного зверя, сверкает в его глазах, когда ваша рука возвращает ему его спасенную душу. Вы покрываете спину скакуна чепраком и чувствуете всплеск святой силы – правосудие свершилось! Конь тыкается носом в вашу руку, как будто благодаря за избавление от груза ужасного прошлого. Вы чувствуете, что теперь у вас появился верный друг.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7648] = {title = "Шедевр Гриманда", objective = "Покажите арканитовый чепрак лорду Грейсону Тенелому в храмовом квартале Штормграда.", description = "*Гриманд утирает пот со лба, сияя от гордости.*\n\nГотово, <друг мой/моя леди>. Это одно из моих лучших изделий – не хуже, чем тот чепрак, что я собственноручно смастерил для лорда Победителя Тени, когда он отправлялся за своим конем. Благодарю тебя за доверие.\n\nНесомненно, и сам Грейсон захочет полюбоваться на мою работу. Покажи ему чепрак и передай мою искреннюю благодарность за его достойные дела.", progress = "А вы неплохо показали себя, Палдосий. Как только чепрак будет готов, вы отправитесь на следующий подвиг.", completion = "Великолепная работа! С возрастом мастерство Гриманда растет. А его изделия были одними из лучших еще в те времена, когда он делал чепрак для моего коня!\n\nЭтот чепрак слишком хорош для обычного скакуна, но нам предстоит иметь дело с необычным животным. Тебе предстоит оседлать паладинского коня, и поэтому для чепрака нужно получить особое благословение. Ступай.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][7649] = {title = "\"Зачарованная ториевая броня\", том I", objective = "Верните книгу законным владельцам.", description = "Том помечен печатью Читальни.", progress = "Вы ее нашли!", completion = "Молодец, мой мальчик!\n\n*Сказитель Лидрос выдирает из книги одну страницу.*\n\nВот, этот чертеж тебе наверняка пригодится!", rewards = "Вы получите:\n\nЧертеж: зачарованная ториевая кираса"}
MultiLanguageQuestData['ru'][7650] = {title = "\"Зачарованная ториевая броня\", том II", objective = "Верните книгу законным владельцам.", description = "Том помечен печатью Читальни.", progress = "Вы ее нашли!", completion = "Молодец, мой мальчик!\n\n*Сказитель Лидрос выдирает из книги одну страницу.*\n\nВот, этот чертеж тебе наверняка пригодится!", rewards = "Вы получите:\n\nЧертеж: зачарованные ториевые поножи"}
MultiLanguageQuestData['ru'][7651] = {title = "\"Зачарованная ториевая броня\", том III", objective = "Верните книгу законным владельцам.", description = "Том помечен печатью Читальни.", progress = "Вы ее нашли!", completion = "Молодец, мой мальчик!\n\n*Сказитель Лидрос выдирает из книги одну страницу.*\n\nВот, этот чертеж тебе наверняка пригодится!", rewards = "Вы получите:\n\nЧертеж: зачарованный ториевый шлем"}
MultiLanguageQuestData['ru'][7652] = {title = "Выгодная сделка", objective = "Отлично, сударь у меня для вас деловое предложение. Я тут хочу продать несколько чертежей имперских латных доспехов, и мне необходим покупатель. В обмен я хочу получить слитки тория. Как вам мое предложение?", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][7653] = {title = "Имперский латный пояс", objective = "За чертежи пояса я прошу 20 слитков тория.", description = nil, progress = "За чертежи пояса я прошу 20 слитков тория.", completion = "С тобой приятно иметь дело. \n\nИ пожалуйста, Хагрим, сотри это выражение недовольства со своего лица.", rewards = "Вы получите:\n\nЧертеж: имперский латный пояс"}
MultiLanguageQuestData['ru'][7654] = {title = "Имперские латные сапоги", objective = "За чертежи этих сапог я хочу как минимум 40 слитков тория. Точно, 40. Ну не плачь, сынок, хочешь носовой платок?\n\n*Деротайн смеется.*", description = nil, progress = "За чертежи этих сапог я хочу как минимум 40 слитков тория. Точно, 40. Ну не плачь, сынок, хочешь носовой платок?\n\n*Деротайн смеется.*", completion = "С тобой приятно иметь дело. \n\nИ, пожалуйста, Дэломар, сотри это выражение недовольства со своего лица.", rewards = "Вы получите:\n\nЧертеж: имперские латные сапоги"}
MultiLanguageQuestData['ru'][7655] = {title = "Имперские латные наручи", objective = "Для изготовления наручей мне понадобится 20 слитков тория…\n\nС тобой все в порядке, сынок? Что-то ты покраснел...", description = nil, progress = "Для изготовления наручей мне понадобится 20 слитков тория…\n\nС тобой все в порядке, сынок? Что-то ты покраснел...", completion = "С тобой приятно иметь дело. \n\nИ, пожалуйста, Хагрим, сотри это выражение недовольства со своего лица.", rewards = "Вы получите:\n\nЧертеж: имперские латные наручи"}
MultiLanguageQuestData['ru'][7656] = {title = "Имперский латный нагрудник", objective = "Для чертежей нагрудного доспеха мне нужно будет 60 слитков тория. \n\nИ что ты опять ноешь? Опять будешь жаловаться своим божкам, спрашивая, почему они отреклись от тебя?! Держись, приятель! Никто и никогда не говорил, что жизнь справедлива.", description = nil, progress = "Для чертежей нагрудного доспеха мне нужно будет 60 слитков тория. \n\nИ что ты опять ноешь? Опять будешь жаловаться своим божкам, спрашивая, почему они отреклись от тебя?! Держись, приятель! Никто и никогда не говорил, что жизнь справедлива.", completion = "С тобой приятно иметь дело. \n\nИ, пожалуйста, Дэломар, сотри это выражение недовольства со своего лица.", rewards = "Вы получите:\n\nЧертеж: имперский латный нагрудник"}
MultiLanguageQuestData['ru'][7657] = {title = "Имперский латный шлем", objective = "С тебя 50 слитков тория, и чертежи шлема – твои.", description = nil, progress = "С тебя 50 слитков тория, и чертежи шлема – твои.", completion = "С тобой приятно иметь дело. \n\nИ пожалуйста, Дигризли, сотри это выражение недовольства со своего лица.", rewards = "Вы получите:\n\nЧертеж: имперский латный шлем"}
