MultiLanguageQuestData['ru'][7659] = {title = "Имперские латные наплечники", objective = "За чертежи наплечников я прошу 20 слитков тория.", description = nil, progress = "За чертежи наплечников я прошу 20 слитков тория.", completion = "С тобой приятно иметь дело. \n\nИ, пожалуйста, Хагрим, сотри это выражение недовольства со своего лица.", rewards = "Вы получите:\n\nЧертеж: имперские латные наплечники"}
