MultiLanguageQuestData['ru'][7662] = {title = "Новый кодо – бирюзовый", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОгромный бурый кодоОгромный серый кодоОгромный белый кодо"}
