MultiLanguageQuestData['ru'][8383] = {title = "Помни Альтеракскую долину!", objective = "Битва в Альтеракской долине идет, не утихая! Давно ли ты вступал в бой, Драккард?", description = nil, progress = "Битва в Альтеракской долине идет, не утихая! Давно ли ты вступал в бой, Драккард?", completion = "Ты – гордость Альянса, Драккард. Если не сдаваться и не отступать, вскоре мы одержим победу над Ордой!", rewards = nil}
