MultiLanguageQuestData['ru'][8387] = {title = "Вторжение в Альтеракскую долину", objective = "Битва за Альтерак продолжается! Возвращайся в Альтеракскую долину и выгони наглых захватчиков с исконных земель клана Северного Волка, Ксаер!", description = nil, progress = "Битва за Альтерак продолжается! Возвращайся в Альтеракскую долину и выгони наглых захватчиков с исконных земель клана Северного Волка, Ксаер!", completion = "Отличная работа, Ксаер! Тебе есть, чем гордиться. Еще немного, и мы вышвырнем Альянс из Альтерака!", rewards = nil}
MultiLanguageQuestData['ru'][8388] = {title = "Великая честь", objective = "Многие храбрые воины стараются брать с тебя пример, бросаясь в бой против Альянса. Что нового тебе встретилось в странствиях?", description = nil, progress = "Многие храбрые воины стараются брать с тебя пример, бросаясь в бой против Альянса. Что нового тебе встретилось в странствиях?", completion = "Твоих подвигов во имя Орды не счесть. Приятно видеть, что твой дух по-прежнему крепок.", rewards = nil}
MultiLanguageQuestData['ru'][8389] = {title = "Битва за ущелье Песни Войны", objective = "Битва в Ущелье Песни Войны идет, не прекращаясь. Внеси свой вклад в изгнание часовых из клана Среброкрылых с наших земель!", description = nil, progress = "Битва в Ущелье Песни Войны идет, не прекращаясь. Внеси свой вклад в изгнание часовых из клана Среброкрылых с наших земель!", completion = "Молодчина, |3-6(Друид)! Благодаря тебе и таким как ты Орда вернет себе Ущелье Песни Войны!", rewards = nil}
