MultiLanguageQuestData['ru'][8404] = {title = "Битва за ущелье Песни Войны", objective = "Помни, что битва в Ущелье Песни Войны идет не только за деревья. На самом деле мы сражаемся за сохранение естественной границы между Ясеневым лесом и Степями. Что нового на фронте?", description = nil, progress = "Помни, что битва в Ущелье Песни Войны идет не только за деревья. На самом деле мы сражаемся за сохранение естественной границы между Ясеневым лесом и Степями. Что нового на фронте?", completion = "Отличная работа, Джиролама. Благодаря тебе, граничный лес Ясеневого леса простоял еще день.", rewards = nil}
