MultiLanguageQuestData['ru'][8408] = {title = "Битва за ущелье Песни Войны", objective = "Помни, что битва в Ущелье Песни Войны идет не только за деревья. На самом деле мы сражаемся за сохранение естественной границы между Ясеневым лесом и Степями. Что нового на фронте?", description = nil, progress = "Помни, что битва в Ущелье Песни Войны идет не только за деревья. На самом деле мы сражаемся за сохранение естественной границы между Ясеневым лесом и Степями. Что нового на фронте?", completion = "Отличная работа, Ахей. Благодаря тебе, граничный лес Ясеневого леса простоял еще день.", rewards = nil}
MultiLanguageQuestData['ru'][8409] = {title = "Поломанные бочки", objective = "Вернитесь к Янке Зовущей Тьму на фестиваль Плетеного человека на Тирисфальских лугах.", description = "Тухлые яйца успешно подброшены в бочку, и весь эль Южнобережья теперь безнадежно испорчен.\n\nОтправляйтесь назад, к Янке Зовущей Тьму, на фестиваль Плетеного человека на Тирисфальских лугах, и доложите о своем успехе.", progress = nil, completion = "Ха-ха! Вот теперь-то вы продемонстрировали настоящий дух Тыквовина, вернее, дух ОТРЕКШИХСЯ!!!\n\n*Янка Зовущая Тьму смеется и потирает руки.*\n\nЗамечательно, что в Южнобережье теперь будут пить испорченный эль, а то и вовсе никакого. А вы – вот, угощайтесь. Надеюсь, вам все понравится!", rewards = "Вы получите:\n\nТыквовинская конфета"}
MultiLanguageQuestData['ru'][8410] = {title = "Покорение стихий", objective = "Соберите образцы воздуха, огня, земли и воды по поручению Бат'ры Стража Ветра.", description = "Бат'ра Страж Ветра ищет шамана вроде тебя. Принеси ему по образцу каждой из стихий, чтобы доказать свое мастерство.\n\nБат'ру можно отыскать на востоке от Мельницы Таррен. Иди вдоль реки на север до руин. Там-то Бат'ра и разбил лагерь.", progress = "Что ты мне принес, |3-6(Шаман)?", completion = "Отлично, дружище. Теперь поболтаем.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8411] = {title = "Покорение Стихий", objective = "Принесите стихии Земли, Воздуха, Огня и Воды Бат'ре Стражу Ветра.", description = "Добро пожаловать, <класс>. Расклад такой: ты несешь мне стихии и только потом я с тобой говорю.\n\nМне нужны от тебя Огонь, Воздух, Вода и Земля. Только потом я тебе буду доверять, дружище. Надо удостовериться, что ты не совсем дундук.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8412] = {title = "Тотем духов", objective = "Принесите части тотема Духа Бат'ре Стражу Ветра.", description = "Духи стихий здешних мест меня невзлюбили.\n\nТы знаешь о тотемах больше других, а мне без защитного тотема духов не обойтись. Стихии у нас уже есть, теперь нужно что-то более близкое к природе, первобытное.\n\nВ Западных Чумных землях можно добыть когти медведей и глаза пауков. Падальщики едят и тех, и других, поэтому у них в желудках может быть и то, и другое.", progress = "Духи знают, что делают, а они пытаются убить меня! Надеюсь, ты несешь мне нужные части.", completion = "Отлично, дружище! Попробуем...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8413] = {title = "Вуду", objective = "Принесите вудуистские перья Бат'ре Стражу Ветра.", description = "Силы этого тотема духов не достаточно. Нам нужна магия вуду, чтобы сделать верную защиту.\n\nТролли из затонувшего храма делают перья, насыщенные магией вуду. Ступай туда и убей Гашера, Миджана, Золо, Хукку, Зул'Лора и Лоро. Тогда нам хватит магии на настоящий тотем духов.", progress = "И где перья, дружище?", completion = "Пора этому троллю хорошенько вздремнуть! За мной присмотрит тотем духов.\n\nТебе понадобилось много времени, чтобы собрать все части. Ты хочешь что-нибудь за труды?", rewards = "Азуритовые кулачные перчаткиЗверопосохВам дадут возможность выбрать одну из следующих наград:\n\nВлюбленный водный дух\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][8414] = {title = "Борьба со злом", objective = "Принесите 20 камней Плети приспешников верховному жрецу Тель'данису в Западные Чумные земли.", description = "Привет тебе, <класс>. Отрадно видеть рыцаря вроде тебя в сих безотрадных землях.\n\nМы рассчитваем на твою помощь в борьбе с беконечными полчищами нежити. Собери побольше камней Плети и отнеси их верховному жрецу Тель'данису. Он охраняет гробницу Утера неподалеку отсюда.\n\nКамни Плети находят лишь те, кто получил Жетон Серебряного Рассвета. Если у тебя нет амулета, поговори с офицером Чистосердой.", progress = "Какое зло ты принес мне?", completion = "Исцелять камень Плети от зла рискованно, ведь может явиться нежить со всех сторон света. Но ты предан делу Света, и я не боюсь за тебя, Борвег…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8415] = {title = "Лагерь Промозглого Ветра", objective = "Обратитесь к командиру Ашламу Отважному Кулаку в Лагерь Промозглого Ветра.", description = "Командиру Ашламу Отважному Кулаку нужен паладин, не уступающий тебе честью и доблестью, <имя>. Командир живет в Лагере Промозглого Ветра в южной части Западных Чумных земель. Найди его и помоги делу Света!", progress = nil, completion = "Отлично, |3-6(Паладин)! Посмотрим, из какого теста ты сделан.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8416] = {title = "Бездействующие камни Плети", objective = "Отнесите бездействующий камень командиру Ашламу Неутомимому на Берег Промозглого Ветра.", description = "Камни очищены от зла, <имя>.\n\nЯ в курсе планов командира Ашлама, и ему понадобится всего лишь один бездействующий камень. Отнеси его, и да сгорит Плеть в праведном огне.", progress = "Удалось ли Тельданису очистить камни Плети?", completion = "Ты выполнил мой приказ без лишних слов, Борвег.\n\nПохоже, тебе можно верить. Пожалуй, я поделюсь с тобой своим планом.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8417] = {title = "Неупокоенный дух", objective = "Поговорите с павшим героем Орды у входа в Выжженные земли.", description = "По Выжженным землям бродит неупокоенный дух одного из величайших героев Орды. Честь воина прочнее смертного тела, так что тебе не помешает поговорить с ним.", progress = nil, completion = "Итак, ты хочешь избавить меня от боли. Жаль, что меня нельзя просто-напросто зарубить, но к сожалению, не все так просто...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8418] = {title = "Создание камня силы", objective = "Добудьте янтарные, синие и зеленые вудуистские перья у троллей из Затонувшего храма.", description = "Теперь мы сможем создать оружие против нежити из бездействующих камней Плети. Задание непростое. Магией, способной вынудить зло обратиться против самого себя, владеют лишь тролли из затонувшего храма.\n\nВ храме есть тролли по имени Ранокол, Миджан, Золо, Хукку, Зул'Лор и Лоро. Не стоит их жалеть... они давно пали и их души запятнаны злом.", progress = "Тебе удалось убить проклятых троллей?", completion = "Великолепно. Я сказал бы, что удивлен, но я ни на минуту не сомневался, что ты не подведешь нас.\n\nМне выпала честь вручить тебе один из священных камней силы. Пользуйся им во благо.", rewards = "Клинок из светосталиВам дадут возможность выбрать одну из следующих наград:\n\nСвященная сфераРыцарский перстень\n\nВы также получите:\n\nСвященный камень мощи"}
MultiLanguageQuestData['ru'][8419] = {title = "Просьба беса", objective = "Принесите отрез ткани Скверны Бесенку в Оскверненный лес.", description = "С тобой хочет встретиться один бес из Оскверненного леса по имени Бесенок. Это довольно странно, поскольку он попросил тебя принести отрез ткани Скверны в залог доброй воли. Ты весьма <могущественный чернокнижник/могущественная чернокнижница> и наверняка знаешь, что ткань Скверны таскают с собой сатиры из Оскверненного леса.\n\nБесенок живет на севере от водопада Отравленной Крови. Говорят, в это время года там очень красиво.", progress = "Ты принес мне ткань Скверны?", completion = "Ой, спасибо, добренький |3-6(Чернокнижник)!\n\n*Бесенок подносит ткань к лицу.*\n\nКак мне нравится ее касаться! Она так славно обжигает кожу и внушает злобные мысли...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8420] = {title = "Пробирает!", objective = "Принесите отрез ткани Скверны Бесенку в Оскверненный лес.", description = "Может, ты и не <ожидал/ожидала> услышать это от беса, но мне хочется завести питомца. Правда-правда. Это же нечестно – у Ниби есть я, а у меня нет никого!\n\nМне даже не надо живого питомца. Мне нужно что-нибудь, из чего я бы мог его себе сделать – например, ткань Скверны. У сатиров тут, в Оскверненном лесу, ткань Скверны-то имеется, так что просто убивай их, пока не найдешь ткань. Звучит не так уж и ужасно, правда?", progress = "Где моя ткань Скверны?", completion = "Ого! Добрая ты. Особенно для чернокнижнцы!\n\n*Бесенок прижимает ткань к лицу.*\n\nКак же мне нравится это ощущение, как чудесно пощипывает кожу, и как зло волной проходит по всему нутру...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8421] = {title = "Бросовый материал", objective = "Принесите 10 кусков гнилой древесины и 4 порции экстракта Отравленной Крови Бесенку в Оскверненный лес.", description = "Теперь, когда у меня есть ткань Скверны, я могу начать изготовление собственного питомца.\n\nНо ему нужны глазки! Может, сумеешь оторвать кусочек гнилой древесины от железного дерева, и я вырежу из нее прелестные глазки? Деревья эти можно найти в Железнолесье.\n\nА еще мне понадобится немного экстракта Отравленной Крови, чтобы мой питомец приобрел демонический запах. Этот экстракт можно добыть из нечистых слизнюков, а они ошиваются прямо по соседству со мной и Ниби.", progress = "Ну, все принес?", completion = "Лучшего и не надо!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8422] = {title = "Тролли Пера", objective = "Принесите 6 вудуистских перьев троллей из затонувшего храма.", description = "Мой питомец почти готов. Осталось набить его.\n\nТолько вудуистские перья с троллей затонувшего храма помогут делу. Их зовут Ранокол, Миджан, Золо, Хукку, Зул'Лор и Лоро. Убей их. Перебей их всех! \n\nЭто непростое дело, <имя>, потому я заплачу тебе за услугу, дав тебе кое-что из барахла Ниби – ему это все равно, наверное, не нужно.", progress = "Ты принес перья? Мою куколку надо набить!", completion = "Отлично, теперь мой питомец закончен! \n\n*Бесенок быстро набивает куколку и с демонической горячностью обнимает ее.*\n\nОго, какой побочный эффект у этих вудуистских перьев...", rewards = "Одеяния служенияПожинатель душВам дадут возможность выбрать одну из следующих наград:\n\nОсколок Бездны\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][8423] = {title = "Воинское испытание", objective = "Убейте 7 зловепрей в Выжженных землях и вернитесь к павшему герою Орды.", description = "*Герой окидывает тебя взглядом.*\n\nНет сомнений, ты <класс>. У меня для тебя есть почетная задача, но сначала необходимо испытать твою силу.\n\nГоворят, что Рексар проверял остроту своих клинков, убивая зловепря одним быстрым ударом. Теперь же я проверю твою силу, отправив тебя на охоту за зловепрями.", progress = nil, completion = "Мне не нужны доказательства твоих подвигов, |3-6(Воин). Достаточно того, что я вижу решимость в чертах твоего лица.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8424] = {title = "Война против Приверженцев Тени", objective = "Убейте приверженцев тени в Выжженных землях и вернитесь к павшему герою Орды.", description = "Постоянное присутствие Приверженцев Тени в Выжженных землях причиняет мне сильную боль. Их темные ритуалы и заклинания вызывают мучения, каких я не ведал при жизни.\n\nЧерез тебя я могу передать мое собственное послание боли. Иди и неси мой гнев.", progress = nil, completion = "Тебе уже удалось умерить мою боль и тем самым почтить меня. Благодарю тебя, |3-6(Воин).", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8425] = {title = "Вудуистские перья", objective = "Принесите вудуистские перья павшему герою Орды, забрав их у троллей в Затонувшем храме.", description = "Благодаря твоей чести я обрел частицу покоя. Неправильно было бы ничего не предложить взамен.\n\nПри жизни мое оружие и доспехи были великолепны, но теперь они для меня бесполезны. Быть может, тебе они послужат лучше.\n\nОтправляйся к затонувшему храму и уничтожь троллей-охранников Ранокола, Миджана, Золо, Хукку, Зул'Лора и Лоро. У них хранятся магические перья, которые могут восстановить мое материальное тело на достаточно долгое время, чтобы я мог вручить тебе награду.", progress = "Ты уже назад – так быстро? Для тебя и меня время течет по-разному, быть может, для тебя это и вправду было долгое путешествие...", completion = "Наконец-то я вновь могу почувствовать холодное прикосновение стали, пусть даже на несколько мгновений.", rewards = "Остростальные наплечникиЩиток ЯростиВам дадут возможность выбрать одну из следующих наград:\n\nБриллиантовая фляжка\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][8426] = {title = "Битва за ущелье Песни Войны", objective = "Принесите 3 почетных знака ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.", description = "Битва со Среброкрылыми часовыми за ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.\n\nНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!", progress = "Ты несешь вести из Ущелья Песни Войны?", completion = "Великолепно! Ты показал, чего стоишь, выступив против врага в Ущелье Песни Войны! Да разнесутся вести о твоих подвигах по всем нашим землям.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8427] = {title = "Битва за ущелье Песни Войны", objective = "Принесите 3 почетных знака ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.", description = "Битва со Среброкрылыми часовыми за ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.\n\nНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!", progress = "Ты несешь вести из Ущелья Песни Войны?", completion = "Великолепно! Ты показал, чего стоишь, выступив против врага в Ущелье Песни Войны! Да разнесутся вести о твоих подвигах по всем нашим землям.", rewards = "Вы получите:\n\n"}
