MultiLanguageQuestData['ru'][8436] = {title = "Завоевание Низины Арати", objective = "Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.", description = "Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.\n\nВ низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, <имя>!", progress = "Какие вести из Низины Арати, |3-6(Разбойник)?", completion = "Контроль над ресурсами Низины Арати - важнейшее дело! Ты молодец, Шишгарип.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8437] = {title = "Завоевание Низины Арати", objective = "Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.", description = "Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.\n\nВ низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, <имя>!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8438] = {title = "Завоевание Низины Арати", objective = "Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.", description = "Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.\n\nВ низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, <имя>!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8439] = {title = "Завоевание Низины Арати", objective = "Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.", description = "Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.\n\nВ низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, <имя>!", progress = "Какие вести из Низины Арати, |3-6(Охотник)?", completion = "Контроль над ресурсами Низины Арати - важнейшее дело! Ты молодец, Дулозалепи.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8440] = {title = "Завоевание Низины Арати", objective = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине битвы. Низина Арати должна отойти к нам!", description = nil, progress = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине битвы. Низина Арати должна отойти к нам!", completion = "Отличная работа, Сенжин! Пока Низина Арати в наших руках, припасов нам хватит.", rewards = nil}
MultiLanguageQuestData['ru'][8441] = {title = "Завоевание Низины Арати", objective = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине сражения. Низина Арати должна отойти к нам!", description = nil, progress = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине сражения. Низина Арати должна отойти к нам!", completion = "Отличная работа, Сенжин! Пока Низина Арати в наших руках, припасов нам хватит.", rewards = nil}
MultiLanguageQuestData['ru'][8442] = {title = "Завоевание Низины Арати", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][8443] = {title = "Завоевание Низины Арати", objective = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине битвы. Низина Арати должна отойти к нам!", description = nil, progress = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине битвы. Низина Арати должна отойти к нам!", completion = "Отличная работа, Дэдоутсайд! Пока Низина Арати в наших руках, припасов нам хватит.", rewards = nil}
MultiLanguageQuestData['ru'][8446] = {title = "Под покровом кошмара", objective = "Найдите того, кто сможет осознать значение поглощенного кошмарами предмета.\n\nМожет быть, вам сможет помочь могущественный друид.", description = "Эта вещь так и сочится порчей.\n\nМожет быть, существует связь между ней и драконами, вылетающими из Сна. Кто-то должен разобраться, что делать с этой штукой. Может, тебе обратиться к друидам с Лунной поляны или из крепости Кенария?", progress = "Да, |3-6(дворф)?", completion = "Я должен очистить этот предмет от скверны. Тогда, быть может, мне удастся понять, почему в последнее время я не могу проникнуть в Сон. Давай.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8447] = {title = "Пробуждение легенд", objective = "Дождитесь, пока хранитель Ремул с Лунной поляны очистит поглощенный кошмарами предмет.", description = "Воды озера Элуне'ара смоют кошмары, поглотившие этот предмет. Это займет совсем немного времени. Подожди, <имя>.", progress = nil, completion = "Возьми это кольцо, Эффект. Оно помогло Малфуриону, а теперь поможет тебе...", rewards = "Вы получите:\n\nПерстень-печатка Малфуриона"}
MultiLanguageQuestData['ru'][8460] = {title = "Союзник Древобрюхов", objective = "Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 6 воинов, 6 землепроходцев и 6 садовников из племени Мертвого Леса. Выполнив поручение, возвращайтесь в южную часть Оскверненного леса к Изумрудному святилищу.", description = "Фурболги Древобрюхов – единственное фурболгское племя, не затронутое порчей. Однако нынче многие расы без разбору убивают всех фурболгов подряд. И потому фурболгов Древобрюхов осталось так мало.\n\nХочешь заслужить доверие? Изгони из Оскверненного леса пораженных порчей фурболгов Мертвого Леса, и в один прекрасный день мы признаем тебя <союзником/союзницей>. Ты найдешь первое племя Мертвого Леса – воинов, землепроходцев и садовников – к западу от меня.", progress = "Запомни, Канц. Если хочешь заслужить наше доверие, прояви себя.", completion = "Мы сильно страдаем от того, что случилось в прошлом. Спасибо за все, что ты сделал для защиты Древобрюхов. И в знак начала нашей дружбы, прими этот скромный подарок.", rewards = "Жилет хранителя землиПояс стража логоваВы получите:\n\n"}
MultiLanguageQuestData['ru'][8461] = {title = "Северные фурболги Мертвого Леса", objective = "Нафиэн просит вас убить 6 дозорных, 6 мстителей и 6 шаманов из племени Мертвого Леса. По выполнении возвращайтесь на север Оскверненного леса ко входу в крепость Древобрюхов.", description = "Прямо на юго-западе отсюда расположен лагерь фурболгов Мертвого Леса. В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги стали настоящей угрозой.\n\nПлемя Мертвого Леса злобное, но это все действие скверны, поразившей их разум. Они враждебны не от природы, но тут уж ничего не поделать. Мне невыносимо тяжело сражаться против собратьев.\n\nПрошу тебя, <имя>, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается.", progress = nil, completion = "Чую, что ты вернулся с победой. Победа... какое пустое слово, если подумать о том, что еще надо сделать. Как бы то ни было, ты доказал, что достоин нашего доверия.\n\nНе сразу фурболги Крепости Древобрюхов начнут относиться к тебе без враждебности в этой берлоге. Но твое упорство пробьет стену любой подозрительности, которую мои братья могут питать к тебе. Пока ты не предашь нас и не поднимешь на нас оружия, мы будем находить общий язык.", rewards = "Поножи фурболгаШлем землепроходцаВы получите:\n\n"}
MultiLanguageQuestData['ru'][8462] = {title = "Беседа с Нафиэном", objective = "Отправляйтесь на север по главной дороге в Оскверненном лесу и поговорите с фурболгом по имени Нафиэн. Он стоит на страже у входа в крепость Древобрюхов.", description = "Кто знает, может ты справишься с еще более страшной угрозой, что нынче нависла над нами, кланом Древобрюхов. Ты уже <сумел/сумела> показать здесь свою доблесть...\n\nЕще один мой сородич стоит на страже у входа в Крепость Древобрюхов, по этой дороге дальше к северу. Его зовут Нафиен. Он может показаться тебе злобной грязной тварью, но ты его не бойся. Он всего лишь ищет помощи против злых сил, что угрожают нашему дому.", progress = nil, completion = "Ага... ветер принес мне весть о чужаке не из нашего племени, который ищет союза с фурболгами Крепости Древобрюхов. Добро пожаловать – но знай, мое племя не доверяет чужакам.\n\nВремена сейчас смутные, и мы можем доверять только тем, кто вместе с нами сражается с осквернителями наших краев... тем, кто доказал нам свою верность. А те, кому мы не доверяем, встретят откровенную враждебность, как только войдут в крепость.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8463] = {title = "Нестабильные кристаллы маны", objective = "Верните 6 нестабильных кристаллов маны Аэльдону Озаренному Солнцем на площади Соколиных Крыльев.", description = "Шайка Презренных не так давно похитила из одного из наших волшебных святилищ запас нестабильных кристаллов маны. А эти кристаллы при неправильном обращении могут взрываться с такой силой, что ее хватит, чтобы проломить городскую стену!\n\nТак вот, <имя>, меня не волнует, если эти кристаллы взорвутся у них - пусть хоть все повзрываются, - но этот эпизод выставляет моих подчиненных не в лучшем свете!\n\nПринеси мне все оставшиеся похищенные кристаллы, сколько найдешь - возможно, они до сих пор в своей упаковке.", progress = "Ну что, удалось тебе отыскать похищенное?", completion = "Отличная работа, Скуфопал!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8464] = {title = "Боевые действия в деревне Зимней Спячки", objective = "Убейте 8 шаманов, 8 дозорных и 8 ведмедей из племени Зимней Спячки по просьбе Сальфы. Он ждет у входа в Крепость Древобрюхов в Зимних Ключах.", description = "Клан Древобрюхов готов постоять за себя, <имя>. В то время как мы позволяем свободно ходить среди нас тем, кому мы доверяем, мы стараемся по возможности избегать общения с другими племенами фурболгов. \n\nПлемя Зимней Спячки в последнее время становится все более враждебным к нам. Они, похоже, впали в состояние ярости, всецело поглощенные собственным страхом и ненавистью ко всему, чего они не понимают. \n\nЯ вынужден просить вас пробить брешь в их рядах для уменьшения угрозы для нас. Ищите их в деревне Зимней Спячки далеко на восток отсюда.", progress = nil, completion = "Спасибо за то, что вы сделали, как ни печально все это. Примите это в качестве знака нашей благодарности. \n\nЯ бы очень просил вас не прекращать оказывать нам помощь, Томпсон. У нас слишком мало союзников, которых мы можем призвать, и без вашей помощи опасность для моего племени была бы слишком велика, чтобы мы могли справиться с нею в одиночку.", rewards = "Перчатки хранителя землиПерчатки землепроходцаЖилет Стража логоваМедвежье облачениеВы получите:\n\n"}
MultiLanguageQuestData['ru'][8465] = {title = "Разговор с Сальфой", objective = "Пройдите через Крепость Древобрюхов и выйдите к Зимним Ключам. Поговорите с Сальфой, который стоит на страже у входа в Крепость Древобрюхов.", description = "Порча расползается не только от фурболгов Мертвого Леса с юга, но и с востока, от фурболгов из племени Зимней Спячки, что в Зимних Ключах. Если хочешь еще нам помочь, поговори с Сальфой по другую сторону берлоги, у входа в Зимние Ключи. Иди туда по левой тропке.\n\nОсторожнее – если мои тамошние сородичи сочтут, что ты – недобрый гость или ненавистный враг, они на тебя нападут. Иди так быстро, как можешь, чтобы избежать стычки. Убьешь кого из Древобрюхов, пусть даже защищаясь – вызовешь еще большую враждебность.", progress = nil, completion = "Привет тебе, |3-6(Маг) – я тут и страж, и глашатай Древобрюхов в Зимних Ключах, и защитник моего племени.\n\nНаши сородичи из племени Зимней Спячки в этой холодной земле подпали под ту же власть порчи, что и фурболги Оскверненного леса. Если ты пришел помочь фурболгам из крепости Древобрюхов, то мы рады принять твое предложение.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8466] = {title = "Перья для Гразла", objective = "Хотя я уже тебе доверяю, заслужить доверие моих подозрительных соплеменников тебе еще только предстоит. Тут я смогу тебе помочь.\n\nУ некоторых фурболгов Мертвого Леса есть характерные головные уборы, которые могут послужить доказательством уменьшения их числа. Приноси мне перья из всех головных уборов, какие только сможешь добыть, и с каждыми очередными пятью штуками доверие к тебе в племени Древобрюхов будет возрастать.", description = nil, progress = "Хотя я уже тебе доверяю, заслужить доверие моих подозрительных соплеменников тебе еще только предстоит. Тут я смогу тебе помочь.\n\nУ некоторых фурболгов Мертвого Леса есть характерные головные уборы, которые могут послужить доказательством уменьшения их числа. Приноси мне перья из всех головных уборов, какие только сможешь добыть, и с каждыми очередными пятью штуками доверие к тебе в племени Древобрюхов будет возрастать.", completion = "Хорошая работа, Тиотенши! Я уж постараюсь, чтобы мои сородичи узнали о твоих делах.\n\nНе забывай приносить мне все перья, что добудешь. Я возьму все, сколько принесешь.", rewards = nil}
MultiLanguageQuestData['ru'][8467] = {title = "Перья для Нафиэна", objective = "Хотя я уже тебе доверяю, заслужить доверие моих соплеменников тебе еще только предстоит. Тут я смогу тебе помочь.\n\nУ некоторых фурболгов Мертвого Леса есть характерные головные уборы, которые могут послужить доказательством уменьшения их числа. Приноси мне перья из всех головных уборов, какие только сможешь добыть, и с каждыми очередными пятью штуками доверие к тебе в племени Древобрюхов будет возрастать.", description = nil, progress = "Хотя я уже тебе доверяю, заслужить доверие моих соплеменников тебе еще только предстоит. Тут я смогу тебе помочь.\n\nУ некоторых фурболгов Мертвого Леса есть характерные головные уборы, которые могут послужить доказательством уменьшения их числа. Приноси мне перья из всех головных уборов, какие только сможешь добыть, и с каждыми очередными пятью штуками доверие к тебе в племени Древобрюхов будет возрастать.", completion = "Хорошая работа, Профессия! Я уж постараюсь, чтобы мои сородичи узнали о твоих делах.\n\nНе забывай приносить мне все перья, что добудешь. Я возьму все, сколько принесешь.", rewards = nil}
MultiLanguageQuestData['ru'][8468] = {title = "Разыскивается: Таэлис Ненасытный", objective = "Принесите голову Таэлиса сержанту Ка'рену на площадь Соколиных Крыльев в лесах Вечной Песни.", description = "Город Луносвет назначает награду за голову Таэлиса Ненасытного, известного главаря Презренных. Он разыскивается за то, что неоднократно совершал преступления против жителей Луносвета, в том числе убил двух городских стражников.\n\nОтносительно награды обращайтесь к сержанту Ка'рену.", progress = "Ты хочешь мне что-то показать?", completion = "Наконец-то этот негодяй, Таэлис, получил по заслугам! Молодец, Тсой. Теперь-то Презренные присмиреют хотя бы на время!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8469] = {title = "Бусы для Сальфы", objective = "Ты заслужил мое доверие Орканавт, теперь осталось проделать то же самое с моим крайне недоверчивым племенем. Для этого придется потрудиться.\n\nПлемя Зимней Спячки, как известно, носит особые бусы, чтобы защищаться от злых духов. Бусы не оправдали свое предназначение, поскольку все племя подверглось порче. Принеси мне бусы, которые носят падшие фурболги. Твой авторитет в племени будет расти с каждыми принесенными бусами.", description = nil, progress = "Ты заслужил мое доверие Орканавт, теперь осталось проделать то же самое с моим крайне недоверчивым племенем. Для этого придется потрудиться.\n\nПлемя Зимней Спячки, как известно, носит особые бусы, чтобы защищаться от злых духов. Бусы не оправдали свое предназначение, поскольку все племя подверглось порче. Принеси мне бусы, которые носят падшие фурболги. Твой авторитет в племени будет расти с каждыми принесенными бусами.", completion = "Ты снова доказал свою доблесть! Я позабочусь о том, чтобы о твоих деяниях узнало все наше племя.\n\nНе забывай приносить мне бусы Зимней Спячки. О каждом твоем успехе я расскажу своим сородичам.", rewards = nil}
MultiLanguageQuestData['ru'][8470] = {title = "Ритуальный тотем Мертвого Леса", objective = "Отнесите ритуальный тотем Мертвого Леса в Крепость Древобрюхов и посмотрите, не пригодится ли этот предмет кому из тамошних фурболгов. Фурболги Крепости Древобрюхов не станут говорить с вами – разве что их отношение к вам нейтральное или лучше.", description = "Вы нашли один из ритуальных тотемов фурболгов клана Мертвого Леса. Сам тотем совершенно неописуемой конструкции, и от него исходит ощутимое чувство отчаяния. Если есть предмет, который мог бы стать олицетворением порчи, снедающей фурболгов Мертвого Леса – то вот он.\n\nОдин из фурболгов в крепости Древобрюхов мог бы найти применение этому предмету... конечно, если вы уже добились достаточного доверия от них, чтобы они снизошли до разговора с вами.", progress = "Да, |3-6(Охотник), чем могу тебе помочь? Ты ходишь среди нас беспечно, хотя это не слишком-то правильно. Я чую что-то... что-то тревожное...", completion = "Тотем... похоже, один из мертволесских, но от него прямо несет разложением. В этом предмете явственно ощущается то, что обратило наших собратьев против нас.\n\nТы мудро поступил, принеся его нам, Томпсон. Возможно, изучив его и проведя обряды, мы сможем узнать, что отравило разум наших сородичей. Благодарю тебя, друг, – прими эти дары в благодарность за твою находку.", rewards = "Вы получите:\n\nСильнейшее зелье маныСильнейшее лечебное зелье"}
MultiLanguageQuestData['ru'][8471] = {title = "Ритуальный тотем Зимней Спячки", objective = "Отнесите ритуальный тотем Зимней Спячки в берлогу Древобрюхов и отдайте его фурболгу, который им заинтересуется. Никто из племени Древобрюхов не заговорит с вами, пока вы не завоюете себе среди них достойную репутацию.", description = "Вы нашли один из ритуальных тотемов Зимней Спячки. Сам тотем представляет собой неописуемую конструкцию, которая испускает почти осязаемые волны страха и отчаяния. Если такую вещь носят все фурболги, то понятно, что довело их до такого состояния.\n\nКто-нибудь из фурболгов логова Древобрюхов наверняка разберется с этой вещью... однако фурболги будут говорить только с теми, кому достаточно доверяют.", progress = "Охотник – ты пришел к нам с миром, но я вижу, что у тебя очень важная цель. Важная не только для фурболгов, но и для твоих соплеменников, |3-6(орк). О чем ты хочешь нам поведать?", completion = "Эта вещь... она имеет форму ритуального тотема Зимней Спячки, однако этот тотем был испорчен непостижимыми для меня силами. Так или иначе, в нем присутсвует именно та энергия, которая заставила племя Зимней Спячки обратиться против нас.\n\nС твоей стороны было очень мудро принести его нам, Томпсон. Мы тщательно его изучим и, будем надеяться, найдем способ исцелить наших собратьев.\n\nМы благодарны тебе, и просим тебя принять это за твои услуги.", rewards = "Вы получите:\n\nСильнейшее зелье маныСильнейшее лечебное зелье"}
MultiLanguageQuestData['ru'][8472] = {title = "Серьезная неполадка", objective = "Соберите 6 волшебных сердечников с волшебных часовых, которые бродят по руинам Луносвета, и принесите их магистру Джаронису на площадь Соколиных Крыльев в лесах Вечной Песни.", description = "Волшебные часовые, которых наши предки изготовили, чтобы охранять город, в последнее время пришли в полную негодность. Они уже не признают в нас своих хозяев и нападают, как только увидят!\n\nОни созданы много лет назад, но волшебные сердечники, на которых они работают, все еще вполне пригодны. Собери эти сердечники и принеси мне, чтобы я мог пустить их в дело. Часовые бродят по разрушенным кварталам Луносвета, на северо-западе.", progress = "Ну что, Сиданс, удалось тебе собрать волшебные сердечники?", completion = "Молодец, Сиданс! Теперь, когда наши волшебные святилища не работают в полную силу, эти энергетические сердечники очень сильно поспособствуют решению наших проблем.", rewards = "Легкое шелковое одеяниеЗеленый плетеный поясМягкий кожаный жилетВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8473] = {title = "Печальное задание", objective = "Убейте 10 высохших хранителей лесов в Выжженной роще. Вернитесь к Ларанне Речной Ветер в башне к северо-западу от Выжженной рощи в лесах Вечной Песни.", description = "Трудные ныне времена, <имя>. Очень не хотелось нам сжигать леса вдоль границы Призрачных земель, но иначе никак не удавалось предотвратить распространение Плети.\n\nА вот теперь древни, которые в течение многих лет были нашими друзьями, пытаются восстановить леса вдоль Выжженной рощи.\n\nНам так и не удалось убедить наших бывших союзников прекратить эти попытки. Мне очень горько тебя об этом просить, <класс>, но тебе придется пустить в ход единственное оставшееся у нас средство – силу.", progress = "Даже боюсь спрашивать, Туаг... задание выполнено?", completion = "Значит, дело сделано... Будь прокляты эти времена, вынудившие нас пойти на крайние меры... и будь проклята Плеть!\n\nЗапомни, Скуфопал: мы должны защищать свои земли во что бы то ни стало! И мы победим!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8474] = {title = "Подвеска Старого Белоствола", objective = "Отыщите того, кто мог изготовить подвеску Старого Белоствола. Возможно, он подскажет, что это за предмет?", description = "На подвеске выгравированы инициалы: ЛРВ. Возможно, они помогут вам найти создателя подвески...", progress = "Ты хочешь мне что-то показать?", completion = "О-о... эта подвеска... Я подарила ее Старому Белостволу, после того как его народ помог нам отстроить нашу деревню.\n\nБоюсь, это означает, что он...\n\n*Эльфийка откашливается и берет себя в руки.*\n\nСпасибо, что принес мне эту вещь, Скуфопал. Я хотела бы попросить тебя об одной услуге...", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8475] = {title = "Тропа Мертвых", objective = "Убейте 8 чумных мародеров и вернитесь к следопыту Джеле на Тропе Мертвых в лесах Вечной Песни.", description = "Полоса выжженной земли, которая тянется через леса Вечной Песни, как постоянное напоминание о том дне, когда Артас привел Плеть в наш возлюбленный город...\n\nЭто хуже, чем бельмо на глазу: даже теперь по ней в Луносвет приходят прислужники Плети из Призрачных земель.\n\nСтупай, <имя>, и помоги моим воинам убивать лишенную разума нежить, которая приходит Тропой Мертвых.", progress = nil, completion = "Разумеется, Плеть еще нескоро отступится от нас, но все же оборонять Тропу Мертвых необходимо, и мы благодарны за любую помощь!", rewards = "Черный кожаный жилетПлетеные перчатки стража воротПоножи стражаВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8476] = {title = "Угроза Амани", objective = "Убейте 5 аманийских берсерков и 5 аманийских метателей топоров по просьбе лейтенанта Вестницы Зари из обители Странников, что в лесах Вечной Песни.", description = "Наши владения – это не обширные королевства людей или орков. То, что ты видишь перед собой, <имя>, – это, считай, и есть все земли, что принадлежат нам на Азероте.\n\nИ пока мы не сумеем добраться до Запределья, мы должны любой ценой защищать то немногое, что имеем.\n\nОднако у наших нецивилизованных соседей на юго-востоке, троллей из племени Амани, явно имеется свое мнение насчет того, кому принадлежат эти земли. Мы больше не можем терпеть их ежедневные набеги! Отправляйся в их поселения, Зеб'Вату и Тор'Вату, и научи их уму-разуму!", progress = nil, completion = "Молодец, Скуфопал! Чем больше у нас будет таких, как ты, то тем быстрее мы вернем нашим землям прежнее великолепие.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8477] = {title = "Молот копьедела", objective = "Найдите в Тор'Вате к юго-востоку от обители Странников копьедела Отембе и принесите его молот Аратель Кузне Солнца в обитель Странников, что в лесах Вечной Песни.", description = "Между троллями Амани и син'дорай существует многовековая неприязнь и открытая вражда. Однако же это не мешает мне оценить работу коллеги-оружейника, <имя>.\n\nМне уже попадались изделия троллей Амани, и должна признаться, что это очень качественные вещи. Ходят слухи, что Отембе Создатель Копий владеет волшебным молотом, таким легким и хорошо уравновешенным, что он позволяет работать очень ловко и эффективно.\n\nЕсли ты принесешь мне этот инструмент, я сделаю тебе оружие.", progress = "Ну что, Расул, ты принес мне молот Отембе?", completion = "Да, Расул, слухи не лгали! Этот молот - легкий, и в то же время мощный. Теперь я смогу завершить несколько начатых и не оконченных мною вещей! И, разумеется, первая же из них - твоя!", rewards = "Меч СтранникаГладкий металлический посохКарманный нож следопытаВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8479] = {title = "Зул'Марош", objective = "Принесите Вень'яши, пленному троллю в Тор'Вате, голову вождя Зул'Мароша. Вождя можно найти в Зеб'Вате, за озером Элрендар.", description = "Поди-ка поближе. Да не боись, не укусит тебя Вень'яши!\n\nМы, тролли из племени Черного Копья – смертельные враги Амани, как и ваш народ. Их старшой, Зул'Марош – очень злой тролль. Он отравил меня и оставил подыхать в этой клетке.\n\nСмерти я не боюсь, нет. Я смотрел смерти в глаза, и смеюсь над нею!\n\nНо я не смогу умереть спокойно. Пусть Зул'Марош тоже умрет! Он там, за озером, в Зеб'Вате. Я буду сопротивляться яду, пока ты не принесешь мне его башку!", progress = "Ну что, принес голову Зул'Мароша?", completion = "О да! Наконец-то Зул'Марош получил по заслугам! Он сжег деревню Вень'яши. Я убил много Амани, прежде чем меня затолкали в эту клетку! Я спрятал кое-что в песке – это будет мой дар тебе.\n\nОх... яд расходится по жилам... Пора мне помирать...", rewards = "Лук Вень'яшиЖезл худуВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8480] = {title = "Потерянное оружие", objective = "Принесите 8 комплектов оружия син'дорай Велендрису Белому Рассвету в лесах Вечной Песни.", description = "Презренные смелеют с каждым днем, <имя>! Они уже расхрабрились настолько, что захватили причал Солнечного Паруса!\n\nА что самое неприятное - когда нас атаковали, нам пришлось оставить там большую часть нашего оружия. Добудь же его, чтобы мы могли показать этим подонкам, кто здесь хозяин!", progress = "Ну что, тебе удалось собрать потерянное оружие?", completion = "Отлично, Витаминро! Зададим жару этим Презренным!", rewards = "Ржавая палицаРжавый син'дорайский мечВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8481] = {title = "Корень всех зол", objective = "Установите факел призыва демона у входа в пещеру Гролнара в деревне фурболгов Зимней Спячки. Сразите демона и добудьте сущность Зандивиуса для Горна Одноглаза из Крепости Древобрюхов.", description = "<имя>, спасибо тебе за то, что <нашел/нашла> способ вырвать корень зла из душ племени Зимней Спячки – уничтожить демона, овладевшего ими!\n\nОтнеси этот факел к входу в пещеру Гролнара и поставь его там. Это заставит демона появиться. Вот тогда ты со своими союзниками нападешь на него! Только сущность погибшего демона поможет начать долгий процесс исцеления племени Зимней Спячки... и спасения Крепости Древобрюхов.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЗащита Древобрюхов"}
MultiLanguageQuestData['ru'][8482] = {title = "Обличающие документы", objective = "Отнесите обличающие документы Аэльдону Озаренному Солнцем на площадь Соколиных Крыльев в лесах Вечной Песни.", description = "В документах содержатся подробные карты стратегически важных объектов в лесах Вечной Песни. Прилагается также план волшебного святилища. Кроме того, присутствует множество заметок на неизвестном вам языке.\n\nПоскольку все эти документы вы нашли у дарнасского шпиона, пожалуй, стоит отнести их капитану стражи – Аэльдону Озаренному Солнцем.", progress = "Ты мне что-то принес? Дай-ка взглянуть...", completion = "Все это было у ночного эльфа? Точно? Язык-то явно дворфийский...\n\nНасколько я понимаю из письма, тот, кто его написал, не сам устроил аварию, но был прислан сюда, чтобы понаблюдать за ее результатами. Тут сказано, что наша работа опасна и безрассудна... но кто же это?\n\nНу разумеется! Тот посланец из Стальгорна! Глупо было доверяться тому, кто служит Альянсу.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8483] = {title = "Дворфийский шпион", objective = "Принесите голову геолога Стража Наковальни Аэльдону Озаренному Солнцем на площадь Соколиных Крыльев в лесах Вечной Песни.", description = "Слушай, <имя>. Ситуация очень деликатная. Мы вычислили шпиона, но убить его открыто не можем. Не можем мы и попытаться его схватить - слишком велик риск, что уйдет.\n\nПрошу тебя: пойди в Северное святилище, найди там геолога Стража Наковальни и убей его. Только тихо: мы не хотим, чтобы пошли разговоры, что мы допустили в свой город шпиона.\n\nПринеси мне в доказательство его голову. Пусть стальгорнцы знают, что к син'дорай соваться опасно.", progress = "Ну что, удалось тебе разобраться с этим прохвостом?", completion = "Ага, дело сделано! Отличная работа.\n\nПредводителю следопытов уже обо всем сообщили - поверь мне, дворфы дорого заплатят за предательство.\n\nСегодня ты оказал большую услугу своему народу, Аукциониус!", rewards = "Клеймор кровавого ястребаДлинный ножВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8484] = {title = "Знак мира", objective = "Отнесите мирное приношение Древобрюхов королю Магни Бронзобороду в Стальгорн.", description = "Твои подвиги выше любых похвал, <имя>. И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир.\n\nПрошу – отнеси этот дар королю дворфов, что живет в железной горе – вроде бы вы зовете этот город Стальгорном. В былые времена он пытался заключить с нами союз от имени Альянса. Так что теперь достойно будет, чтобы ты <завершил/завершила> труды Альянса по установлению мира с нами.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8485] = {title = "Знак мира", objective = "Отнесите мирное приношение Древобрюхов Шоку Нарнсу в Оргриммар.", description = "Твои подвиги выше любых похвал, <имя>. И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир.\n\nПрошу – отнеси этот дар вождю орков, что живет в Дуротаре. Кажется, вы называете его город Оргриммаром. В былые времена он пытался заключить с нами союз от имени Орды. Так что теперь достойно будет, чтобы ты <завершил/завершила> труды Орды по установлению мира с нами.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8486] = {title = "Магическая нестабильность", objective = "Убейте 5 магических призраков и 5 волшебных охотников по просьбе хранительницы энергии Велании.", description = "Ну наконец-то этот олух Кайданис прислал хоть кого-то!\n\nЯ предупреждала о том, как опасно перегружать Западное святилище! И вот теперь один из энергетических конвертеров уничтожен, а из святилища лезут чародейские призраки!\n\nМне нужна твоя помощь, чтобы разобраться с этими существами, прежде чем мы отправим туда ремонтников. Времени в обрез!", progress = nil, completion = "Спасибо, Тсой. Теперь, когда ситуация под контролем, можно отправить туда рабочих и все наладить. Надеюсь, там ничего серьезного...", rewards = "Клинок Хранителя энергииТрость ВеланииВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8487] = {title = "Зараженная почва", objective = "Соберите 8 проб зараженной земли для ученицы Мирведы в Восточном святилище, что в лесах Вечной Песни.", description = "Пока Артас и его армия Плети не проложили здесь свой гибельный путь к Луносвету, это было действующее волшебное святилище.\n\nА теперь от него не больше проку, чем от любой другой части Тропы Мертвых. Почва заражена, это место кишит нежитью, энергия силовых линий полностью искажена.\n\nИ теперь я хочу знать, <имя>, обратимо ли это искажение или нет. Собери образцы почвы, чтобы я могла изучить их. Возможно, со временем мы сумеем все исправить?", progress = "Ну что, Пригопыпа, готовы ли образцы, которые я просила?", completion = "Отлично! Я обработаю эти образцы заклятием усиления, чтобы мне было удобнее исследовать порчу.", rewards = "Следующее заклинание будет наложено на вас:\n\nЗадание - ученица Мирведа - тестовая почва\n\nВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8488] = {title = "Неожиданный результат", objective = "Защитите ученицу Мирведу от Плети, напавшей из засады.", description = "Что-то не так, <имя>. Я чувствую присутствие Плети! Готовься сражаться!", progress = "Ну что, все? Они разбежались?", completion = "Нет, Гейзен, мои надежды тщетны... Сама природа этой почвы изменилась. Спасибо тебе за помощь. Напоследок окажи мне, пожалуйста, еще одну услугу.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8489] = {title = "Невредимый преобразователь", objective = "Принесите хранительнице энергии Велании невредимый чародейский преобразователь.Кажется, перед вами один из чародейских преобразователей, о которых говорила хранительница энергии Велания. Огонь его не коснулся, так что он может ей пригодиться.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Кажется, перед вами один из чародейских преобразователей, о которых говорила хранительница энергии Велания. Огонь его не коснулся, так что он может ей пригодиться.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8490] = {title = "Усиление обороны", objective = "Установите заряженный кристалл рядом с восточным руническим камнем и в течение одной минуты обороняйте его от нежити. Затем верните кристалл хранителю рун Дериану в лесах Вечной Песни и получите награду.", description = "Некогда древние рунические камни поддерживали защитный барьер вдоль границ лесов Вечной Песни. Многие из них были уничтожены во время нападения Артаса, а некоторые были похищены.\n\nИз трех оставшихся лишь один сохранил прежнюю мощь. Но возможно, тот рунический камень, что на востоке, тоже можно спасти.\n\nВот, возьми этот кристалл и влей его энергию в восточный рунический камень. Это займет не более минуты. Однако берегись: находящиеся поблизости твари Плети попытаются уничтожить камень. Этого нельзя допустить!", progress = "Ну что, Пригопыпа, удалось ли тебе зарядить рунный камень?", completion = "Отлично! Значит, наша оборона от Плети продержится еще немного. Спасибо тебе за помощь, Пригопыпа!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8491] = {title = "Добывание шкур", objective = "Принесите 6 шкур прыголапов Велану Светлому Тополю из деревни Легкий Ветерок, что в лесах Вечной Песни.", description = "Прыголапы, которые водятся в здешних краях, славятся своими превосходными шкурами. Порой даже эти мошенники, ночные эльфы, забредают к нам, чтобы побраконьерствовать.\n\nИз-за стычек с троллями из племени Амани все наши припасы иссякли, и нашим следопытам не до охоты. Если ты согласишься помочь нам добыть шкуры прыголапов, я вознагражу тебя надежными доспехами. Прыголапов-охотников легко встретить в лесах к северу отсюда.", progress = "О, ты уже здесь! А где шкуры?", completion = "Отлично, Гейзен! Вот, возьми в награду эту часть доспеха. Из доставленных тобою шкур я смогу сделать еще.", rewards = "Поножи из шкуры прыголапаПлащ из шкуры прыголапаОтделанная мехом плетеная рубашкаВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8492] = {title = "Альянсу не хватает медных слитков!", objective = "Принесите 20 медных слитков сержанту Камнелобу в Палаты войны Стальгорна.", description = "Здорово, <класс>! На вид ты вполне <пригоден/пригодна> к тому, чтобы принять участие в подготовке к войне! Нам пригодится любая помощь, так что наступил твой звездный час.\n\nЯ собираю медные слитки стопками по двадцать штук. Дело благое, да? Ты как, хочешь оказать помощь Альянсу?", progress = "Ну что, солдат, удалось собрать 20 медных слитков?", completion = "Похвально, солдат! Сейчас мы уложим эти слитки в штабель и используем их по назначению. Альянс будет гордиться тобой. \n\nЕсли раздобудешь еще стопку медных слитков, не раздумывай, неси мне.", rewards = nil}
MultiLanguageQuestData['ru'][8493] = {title = "Альянсу все еще не хватает медных слитков!", objective = "Принесите 20 медных слитков сержанту Каменлобу в Военный двор Стальгорна.", description = "Ты <вернулся/вернулась>, <класс>? Превосходно! Для подготовки к войне в Ан'Кираже все еще нужны медные слитки. Ты поможешь нам собрать их?", progress = "Ты уже вернулся, |3-6(Друид)? Превосходно! Слитки, которые тебе удалось достать, сослужат нам добрую службу. Я могу сказать со всей ответственностью, что медь пойдет на изготовление паровых танков, а так же вертолетов и прочей военной техники.\n\nИ пусть эти штабеля меди не смущают твой взгляд, к сожалению, их пока недостаточно, чтобы подготовится к войне в Ан'Кираже как следует. Но ведь мы еще можем рассчитывать на твою помощь?", completion = "Прекрасная работа! Добыча и выплавка всей этой меди, должно быть, была тем еще развлечением. Если, конечно, ты не купил слитки на аукционе. В любом случае, главное – результат. Приложенные тобой усилия не останутся незамеченными, |3-6(Друид). Если раздобудешь еще слитки, без малейшего колебания неси их мне.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8494] = {title = "Альянсу не хватает железных слитков!", objective = "Принесите 20 железных слитков капралу Карнсу в Палаты войны Стальгорна.", description = "Эгей, <мистер/мисс.> Красивые Штанишки, ты прямо отрада для моих измученных глаз. Пока ты <шатался/шаталась> по городам и весям в поисках приключений, у нас тут произошла прорва всего. К примеру, Альянс вот готовится к войне в Ан'Кираже, и всем резко понадобились железные слитки... чертова прорва железных слитков. Можешь таскать их мне стопками по двадцать. Ну как, могу я на тебя рассчитывать, <класс>?", progress = "Если эти двадцать железных слитков у тебя с собой, даже не рассказывай мне, куда ты умудрился их запрятать.", completion = "Ну хорошо, Лорегон, на этот раз тебе удалось вывернуться. Пожалуй, на будущее за тобой стоит приглядывать. Как ни тяжело это говорить, но спасибо тебе за помощь. Альянс тебя не забудет, и я тоже. А теперь дуй-ка отсюда и лучше помоги еще кому-нибудь в заготовках.", rewards = nil}
MultiLanguageQuestData['ru'][8495] = {title = "Альянсу по-прежнему не хватает железных слитков!", objective = "Принесите 20 железных слитков капралу Карнсу на аэродром в Дун Морог.", description = "Ты опять здесь? Не заставляй меня слишком хорошо о тебе думать, <класс>, а то я прямо таять начинаю. Как видишь, мы еще не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и все остальное-прочее, что нужно изготовить для большой драчки. Я думаю, ты сможешь принести еще слитков двадцать в перерыве между своими шатаниями в Зул'Гуруб, или где там у вас, у молодежи, сейчас модно тусоваться.", progress = "Ты опять здесь? Не заставляй меня слишком хорошо о тебе думать, |3-6(Друид), а то я буквально таю изнутри. Как видишь, мы еще не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и все остальное-прочее, что нужно изготовить для большой драчки. Я думаю, ты сможешь принести еще слитков двадцать в перерыве между своими шатаниями в Зул'Гуруб, или где там у вас, у молодежи, сейчас модно тусоваться.", completion = "Должно быть, в Пылающих Степях выпал снег. Вы только посмотрите, это же Лорегон, да не просто так, а с подарком. Двадцать железных слитков! Именно то, что мне нужно. \n\nХочу сказать тебе со всей серьезностью, Лорегон, Альянс перед тобой в долгу. А теперь давай, шлепай отсюда и помоги еще кому-нибудь в заготовках.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8496] = {title = "Запас бинтов", objective = "Принесите 30 плотных бинтов из рунической ткани, 30 плотных шелковых бинтов и 30 плотных бинтов из магической ткани призывательнице ветров Гордый Рог в крепость Кенария в Силитусе. Кроме того сдайте тыловую задачу X.", description = "В последнее время мы понесли серьезные потери, и запас бинтов стремительно иссякает. Добудь нам первоклассные перевязочные материалы и отнеси их призывательнице ветров Гордый Рог в крепость Кенария.", progress = "Что ты мне принес, Драккард?", completion = "Ты как раз вовремя. Принесенные тобой перевязочные материалы спасут немало жизней. Мы благодарны тебе за труды. Вот твое следующее задание.", rewards = "Вы получите:\n\nКенарийский знак тыловикаДополнительное задание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8497] = {title = "Неприкосновенный запас", objective = "Принесите 4 сферы воды, 4 мощных противоядия и 4 копченые пустынные клецки Каландрате в таверну в крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу I.", description = "В крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих наборов для выживания в пустыне и отнеси их Каландрате в крепость Кенария.", progress = "Что ты мне принес, Лорегон?", completion = "Отлично! Нам очень нужны эти материалы. Спасибо.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8498] = {title = "Боевые приказы Сумеречного Молота", objective = "Добудьте боевые приказы Сумеречного Молота и отнесите их командору Мар'алиту в крепость Кенария в Силитусе. Для завершения задания понадобится тактическая задача X.", description = "Разведчики донесли, что от предводителей Сумеречного Молота поступили новые приказы. Их распространяют пророки под охраной солдат. Перехвати эти приказы и принеси их командору Мар'алиту.", progress = "Что ты мне принес, Горрат?", completion = "Великолепно. Главное – опережать противника на ход. Благодаря полученным сведениям, нам известны намерения Сумеречного Молота.", rewards = "Вы получите:\n\nКенарийский знак тактикаТактическое задание"}
MultiLanguageQuestData['ru'][8499] = {title = "Альянсу не хватает ториевых слитков!", objective = "Принесите 20 ториевых слитков госпоже Двукоссе в Палаты войны Стальгорна.", description = "Крайне любезно с твоей стороны, что ты так беспокоишься о нуждах Альянса. Приготовления к войне идут полным ходом, и, помимо всего прочего, нам нужно очень много ториевых слитков. Именно за их сбор я и отвечаю. Торий необходим для изготовления различных военных машин, в основном паровых танков, которые планируется доставлять по воздуху в Силитус сразу же после сборки. За помощь в добыче ториевых слитков я была бы очень признательна, <класс>.", progress = "Я надеюсь, тебе удалось собрать необходимое количество ториевых слитков?", completion = "О, спасибо тебе, |3-6(Разбойник)! Огромное спасибо! Прибавилось еще двадцать, осталось собрать еще несчетное количество. Альянс пред тобой в долгу. Если раздобудешь еще двадцать слитков, обращайся ко мне.", rewards = nil}
MultiLanguageQuestData['ru'][8500] = {title = "Альянсу по-прежнему не хватает ториевых слитков!", objective = "Принесите 20 ториевых слитков госпоже Двукоссе на аэродром в Дун Морог.", description = "Добро пожаловать снова, <имя>. Надеюсь, у тебя все в порядке? Это правда, нам все еще нужны ториевые слитки. Если сможешь достать их, я буду очень признательна.", progress = "Добро пожаловать снова, Хэллпер. Надеюсь, у тебя все в порядке? Это правда, нам все еще нужны ториевые слитки. Если сможешь достать их, я буду очень признательна.", completion = "Отличная работа, |3-6(Разбойник)! Я прослежу, чтобы ториевые слитки были хорошо упакованы и доставлены кузнецам и инженерам, которые изготавливают для нашей армии военную технику. Спасибо тебе еще раз. Если сможешь достать еще двадцать слитков, я приму их у тебя с благодарностью.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8501] = {title = "Цель: острожалы из улья Аши", objective = "Убейте 30 острожалов из улья Аши и доложите о выполнении задания командору Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу XII.", description = "По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Аши. Твоей основной целью будут летающие острожалы из этого улья.\n\nВыполнив задание, поговори с командором Мар'алитом.", progress = "О чем ты хочешь рассказать, Таквер?", completion = "Отличная работа, Таквер. Твои подвиги в сражении при Улье Аши не прошли незамеченными.", rewards = "Вы получите:\n\nКенарийский знак бойцаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8502] = {title = "Цель: рабочие из улья Аши", objective = "Убейте 30 рабочих из улья Аши и доложите о выполнении задания командору Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу III.", description = "По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Аши. Твоей основной целью будут рабочие из этого улья.\n\nВыполнив задание, поговори с командором Мар'алитом.", progress = "Ты хочешь что-то сказать, |3-6(Воин)?", completion = "Отличная работа, Ренн. Без рабочих силитидам придется нелегко. Кто будет восстанавливать их ульи?", rewards = "Вы получите:\n\nКенарийский знак бойца"}
MultiLanguageQuestData['ru'][8503] = {title = "Альянсу не хватает удавника!", objective = "Принесите 20 стеблей удавника рядовому Драксельмеру в Палаты войны Стальгорна.", description = "Знаешь ли ты, <класс>, насколько широко и разнообразно применение удавника? Как, я тебе уже об этом рассказывал? Правда?.. Ну ладно. В любом случае, нам нужно много этой травы, и когда я говорю так, я имею в виду действительно МНОГО! Не следует ли тебе помочь нам, как ты считаешь? Я понимаю, это означает, что тебе придется остаться без всех этих чудесных штучек, которые можно приготовить из удавника... но ведь это ради благого дела!", progress = "Это грязный поклеп! Я не брал отсюда ни одной травинки! Хотя соблазн очень велик... ведь это ж практически настоящая панацея от утилитарной бесполезности. *кашляет* Да, кстати, как там насчет удавника, который ты должен был принести мне?", completion = "Урра! Еще двадцатью меньше собирать. Отлично справляешься с работой! Пойду уберу травы, пока они не засохли. Времени так мало, а удавника так много!\n\nСпасибо еще раз, |3-6(Друид)!", rewards = nil}
MultiLanguageQuestData['ru'][8504] = {title = "Альянсу по-прежнему не хватает удавника!", objective = "Принесите 20 стеблей удавника рядовому Драксельмеру на аэродром в Дун Морог.", description = "Эй, ты там... Ой... Что это было? Ах, да, <имя>! <Зашел/Зашла> поинтересоваться, не нужно ли мне еще удавника? О, тебе крупно повезло, потому что ответ на этот жизненно важный вопрос – конечно, ДА! Ну как, соберешь еще двадцать штук?", progress = "Эй, ты там... Ой... Что это было? Ах, да, Лорегон! Зашел поинтересоваться, не нужно ли мне еще удавника? О, тебе крупно повезло, потому что ответ на этот жизненно важный вопрос – конечно, ДА! Ну как, соберешь еще двадцать штук?", completion = "О мой бог, сколько у тебя тут удавника! Давай-ка по-быстрому упакуем его в коробку, чтобы не испортился. Ты оказал мне... то есть, я хотел сказать, нам, Альянсу, угромную услугу! Я приложу все усилия, чтобы все узнали, что это великий Лорегон внес неоценимый вклад в подготовку к киражской войне, пожертвовав столько удавника!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8505] = {title = "Альянсу не хватает лилового лотоса!", objective = "Принесите 20 цветков лилового лотоса мастеру Ночной Песне в Палаты войны Стальгорна.", description = "<класс>, цветы лилового лотоса где только не применяют. От имени Альянса я отвечаю за заготовку лотоса в количестве, достаточном для удовлетворения всех военных нужд.\n\nНо чтобы собирать цветы, мне нужны добровольцы. Справишься с этим заданием?", progress = "Тебе удалось собрать цветы лилового лотоса?", completion = "Твой вклад очень ценен для всех нас, |3-6(Друид). Только объединив наши усилия, мы сможем отбросить армию безжалостных силитидов и одержать победу. Даже Орда занимается сбором лилового лотоса. Если снова наберешь этих цветов, возвращайся ко мне.", rewards = nil}
MultiLanguageQuestData['ru'][8506] = {title = "Альянсу по-прежнему не хватает лилового лотоса!", objective = "Принесите 20 цветков лилового лотоса мастеру Ночной Песне на аэродром в Дун Морог.", description = "Добро пожаловать обратно, <класс>. Наши запасы лилового лотоса растут, но нам все равно нужно еще. Займись сбором цветов, если можешь, я тебя очень прошу.", progress = "Добро пожаловать обратно, |3-6(Друид). Наши запасы лилового лотоса растут, но нам все равно нужно еще. Если в твоих силах заняться сбором этих цветов, я прошу тебя это сделать.", completion = "От имени Альянса с радостью принимаю твой дар, Лорегон. Ты внес неоценимый вклад в создание снадобий, которые помогут нашим воинам на поле боя. Я благодарю тебя и прошу принести еще лилового лотоса, как только у тебя появится возможность.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8507] = {title = "Рутинное задание", objective = "Поступите в распоряжение дружины Стальгорна возле улья Зора. Подготовьте неподписанные бумаги о полевых обязанностях и получите подписанные бумаги о полевых обязанностях от капитана Черной Наковальни, вернитесь к призывателю ветров Калдону в крепость Кенария в Силитусе.\n\nВнимание: исцеление или наложение благоприятных заклинаний на бойцов дружины Стальгорна переводит в режим PvP.", description = "Приветствую тебя, <имя>. Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные.\n\nДружина Стальгорна под предводительством капитана Черной Наковальни расквартирована рядом с Ульем Зора.\n\nПоговори с капитаном и его лейтенантом, Джанелой Твердомолот, а потом возвращайся. Тем временем я подготовлю для тебя новое задание.\n\nАх да, сделай одолжение, держись подальше от легиона Оргриммара. Нам нелегко удерживать эти два войска от грызни, очень уж они друг друга не любят.", progress = "Дружина капитана Черной Наковальни расквартирована рядом с Ульем Зора. Если ты не найдешь его, поговори с Джанелой Твердомолот.", completion = "Отлично, Ренн. Я подготовила целую серию заданий, которые наилучшим образом распорядятся твоими навыками.\n\nЕсли ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!\n\nЕсли тебе понадобится новое задание, возвращайся к капитану Черной Наковальне.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБоевое заданиеЗадание по материально-техническому снабжениюТактическое задание"}
MultiLanguageQuestData['ru'][8508] = {title = "Бумаги о полевых обязанностях", objective = "Я так понимаю, мне надо подписать эти бумаги, парень?", description = nil, progress = "Я так понимаю, мне надо подписать эти бумаги, парень?", completion = "Да, в наши дни эта небольшая заварушка сойдет за рутинные обязанности. Отнеси бумаги в крепость Кенария, уверен, они уж подготовят тебе работу поинтереснее.\n\nСтупай!", rewards = "Вы получите:\n\nПодписанные бумаги о полевых обязанностях"}
MultiLanguageQuestData['ru'][8509] = {title = "Альянсу не хватает слез Артаса!", objective = "Принесите 20 слез Артаса старшему сержанту Жермен в Палаты войны Стальгорна.", description = "Я предпочитаю говорить быстро и по существу, <класс>. Альянсу нужно много слез Артаса для войны в Ан'Кираже. Не спрашивай меня, зачем, я всего лишь выполняю приказ. Собери столько этих цветов, сколько унесешь, и сдай мне. Ну что, возьмешься за это задание?", progress = "Что? Докладывай быстро и четко, |3-6(Друид)! Тебе удалось собрать необходимое количество слез Артаса?", completion = "Неплохо сработано, |3-6(Друид). Должна сказать, я приятно удивлена. Ты никогда бы не поверил, сколько людей приходят, обещают помочь и не возвращаются. Одну секунду, сейчас я упакую травы в ящик и прикреплю к нему бирку с твоим именем, а потом сможем поговорить на тему того, нужны ли мне еще эти растения.", rewards = nil}
MultiLanguageQuestData['ru'][8510] = {title = "Альянсу снова нужны слезы Артаса", objective = "Принесите 20 цветков слезы Артаса старшему сержанту Жермен на аэродром в Дун Морог.", description = "Так, похоже, слезы Артаса мне все еще нужны. Я предполагаю, что они растут там же, где и раньше. Чем быстрее мы закончим подготовку, тем быстрее начнем наступление на Ан'Кираж.\n\nЯ могу вновь рассчитывать на твою помощь, <класс>?", progress = "Так, похоже, слезы Артаса мне все еще нужны. Я предполагаю, что они растут там же, где и раньше. Чем быстрее мы закончим подготовку, тем быстрее начнем наступление на Ан'Кираж.\n\nЯ могу вновь рассчитывать на твою помощь, |3-6(Друид)?", completion = "Просто невероятно, Облизни! Альянс перед тобой в долгу. Мне нужно проследить, чтобы эти травы были упакованы и хранились надлежащим образом, пока кто-нибудь не изготовит из них что-нибудь полезное. Обращайся ко мне в любое время, особенно, если принесешь еще слез Артаса.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8511] = {title = "Альянсу не хватает легкой кожи!", objective = "Принесите 10 кусков легкой кожи Бонни Шлифовальщице в Палаты войны Стальгорна.", description = "Наш клан Обдирщиков Камня испокон века знал толк в снятии шкур, <класс>. Как говорится, и с камня снимем шкуру. Потому-то Альянс и попросил нас взяться за заготовку тонкой кожи для войны в Ан'Кираже. Я слежу, чтобы кожа была хорошо выдублена, уж не знаю, для чего она там понадобится. Но без помощи мне никак не обойтись.\n\nПока я здесь за всем надзираю, тебе придется прогуляться малость и добыть кож, а потом принести их мне. Ну что, <паренек/девушка>, возьмешься за дело?", progress = "Ну, |3-6(Друид), где обещанная кожа?", completion = "Я прямо скажу, Альянску крупно повезло, что у него есть такие искушенные специалисты по снятию шкур, как ты,|3-6(Друид). Уж я прослежу, чтобы ни одну кожу ненароком не попортили. Спасибо тебе – и не забудь, когда я пересчитаю кожу, справиться у меня, не требуется ли нам еще.", rewards = nil}
MultiLanguageQuestData['ru'][8512] = {title = "Альянсу по-прежнему не хватает легкой кожи!", objective = "Принесите 10 кусков легкой кожи Бонни Шлифовальщице на аэродром в Дун Морог.", description = "Рада снова тебя видеть, <имя>. Похоже, что мы еще не собрали достаточно кожи для наших воинских нужд. Если принесешь мне штук десять кож, это будет просто отлично.", progress = "Рада снова тебя видеть, Облизни. Похоже, что мы еще не собрали достаточно кожи для всяких воинских нужд. Если принесешь мне штук десять кож, это будет просто отлично.", completion = "Спасибо за столь щедрое пожертвование, Облизни. Пойду уложу кожи в стопку. Я думаю, их быстренько превратят в красивые доспехи, пустят на всякие заплатки, или для чего еще там нужна кожа. Возвращайся, как сможешь, и приноси еще – легкой кожи много не бывает.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8513] = {title = "Альянсу не хватает средней кожи!", objective = "Принесите 10 кусков средней кожи рядовому Портеру в Палаты войны Стальгорна.", description = "Так точно, <сэр/мэм>, я отвечаю за сбор всей средней кожи, необходимой для подготовки к войне с Ан'Киражем. Если вы можете раздобыть среднюю кожу, неважно где, сдайте ее мне, пожалуйста. Я буду благодарен за любую помощь, если у вас найдется на нее время.", progress = "Так точно, сэр, я помню вас. Вы принесли среднюю кожу?", completion = "Вау! Похоже, вы и правда решили помочь. Большое спасибо за ваш вклад в общее дело. Пойду-ка я упакую и пересчитаю кожи. Нет, вы действительно знаете, чем скрасить день простого служаки.", rewards = nil}
MultiLanguageQuestData['ru'][8514] = {title = "Альянсу по-прежнему не хватает средней кожи!", objective = "Принесите 10 средних кож рядовому Портеру на аэродром в Дун Морог.", description = "Так точно, <сэр/мэм>, к настоящему времени нам удалось собрать $2063w кусков средней кожи. Я знаю, что прошу слишком многого, но не могли бы вы снова оказать помощь? Если желаете, конечно. Мне необходимо выполнить установленную норму.", progress = "Так точно, сэр, мы собрали много средней кожи, но все равно недостаточно. Заверяю вас, мы найдем этой коже самое наилучшее применение, ни один клочок не пропадет зря. Я знаю, что требую слишком многого, но если у вас еще сохранилось желание, помогите мне набрать установленную норму.", completion = "Ничего себе, вот это кипа кожи, которую вы притащили, сэр! Я послежу, чтобы она попала точно по назначению, непременно. Если вы и дальше будете помогать нам, то мы выполним план гораздо раньше срока! \n\nСпасибо, Облизни!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8515] = {title = "Альянсу не хватает плотной кожи!", objective = "Принесите 10 кусков толстой кожи Марте Остроигл в Палаты войны Стальгорна.", description = "О, будет так здорово! <класс>, приготовления к ан'киражской войне идут вовсю, и так получилось, что я отвечаю за заготовку плотной кожи. Из нее мы сможем наделать тысячи разных вещей, но сначала надо ее достать – тоже тысячами. В буквальном смысле. И тут на сцену выходишь ты.\n\nТы ведь принесешь мне отличную увесистую кипу плотной кожи? Правда-правда?", progress = "Это же обещанной кожей у тебя сумки набиты, |3-6(Друид)? Не могу дождаться, когда же ты отдашь ее мне! Тогда все-все останутся нами довольны, правда?", completion = "О, я знала, что ты справишься, |3-6(Друид), конечно же, я это знала! Я отправлю эту кожу по нужному адресу, как только смогу. Ага, а теперь давай-ка посмотрим. Похоже, в итоге все получается очень, очень миленько. Загляни ко мне еще разочек, я сейчас проверю, не нужно ли нам еще кожи. Если понадобится, то было бы так здорово, если бы ты смог достать для нас еще!", rewards = nil}
MultiLanguageQuestData['ru'][8516] = {title = "Альянсу по-прежнему не хватает плотной кожи!", objective = "Принесите 10 плотных кож Марте Остроигл на аэродром Стальгорна.", description = "Да-да, стопки все еще не очень высокие. <имя>, мы не выполняем норму – не хватает целых $2071w кусков плотной кожи. Только подумай, сколько всего полезного из нее можно сделать! Броню и оружие на любой вкус! Она годится как на отделку паровых танков, так и на оптические винтовки. Держу пари, все закончится тем, что мы соберем столько кожи, что остаток придется отдать Орде на дирижабли.\n\nТы ведь принесешь мне еще плотной кожи?", progress = "Да-да, стопки еще не очень высокие. Лорегон, мы не выполняем норму – не хватает целых 80000 плотной кожи. Только подумай, сколько всего полезного из нее можно сделать! Броню и оружие на любой вкус! Она годится как на отделку паровых танков, так и на оптические винтовки. Держу пари, все закончится тем, что мы соберем столько кожи, что остаток придется отдать Орде на дирижабли. \n\nТы ведь принесешь мне еще плотной кожи?", completion = "У тебя снова все получилось! Просто невероятно, как ты умудряешься выбраться отсюда, собрать все, что нужно, а потом еще вернуться и сдать все мне. Когда люди узнают, сколько ты для нас сделал, они встанут в очередь за твоими автографами! \n\nБольшое-пребольшое спасибо за столь благородное и щедрое пожертвование плотной кожи, Лорегон.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8517] = {title = "Альянсу не хватает льняных бинтов!", objective = "Принесите 20 льняных бинтов часовому Серебринке Небес в Палаты войны Стальгорна.", description = "Война в Ан'Кираже будет долгой и кровавой. Прибегнуть к помощи людей, подобных тебе, было для Альянса мудрым решением. Перед тем как сломя голову ринуться в военный конфликт, надо собрать достаточно припасов.\n\nМне поручили запасать льняные бинты, и я надеюсь, что ты мне поможешь. Это не так-то легко, но по крайней мере льняные бинты проще всего изготовить. Что скажешь, <класс>?", progress = "Двадцать льняных бинтов у тебя, |3-6(Друид)?", completion = "Многим солдатам ты, считай, сослужил добрую службу, |3-6(Друид). Я лично прослежу, чтобы твои усилия не остались незамеченными. Одну минуту, сейчас я упакую эти бинты, куда надо, и внесу их в реестр, а потом посмотрим, сколько нужно ли мне еще. \n\nДа осенит тебя своим светом Элуна, ночной эльф!", rewards = nil}
MultiLanguageQuestData['ru'][8518] = {title = "Альянсу по-прежнему не хватает льняных бинтов!", objective = "Принесите 20 льняных бинтов часовому Серебринке Небес на аэродром в Дун Морог.", description = "Меня всегда изумляет самоотверженность – ведь столь многие обычно гораздо более склонны к эгоизму. <класс>, я все никак не могу выполнить свою норму по сбору льняных бинтов. Не поможешь ли мне еще раз?", progress = "Меня всегда изумляет самоотверженность, ведь многие обычно более склонны к эгоизму. Друид, я все никак не могу выполнить свою норму по сбору льняных бинтов. Не поможешь ли мне еще раз?", completion = "Прими мою благодарность, Лорегон. Пока некоторые пытаются нажиться на подготовке к войне, ты раз за разом доказываешь свою бескорыстную преданность делу Альянса, да что там, всего Азерота. \n\nДа пребудет с тобой благословение Элуны!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8519] = {title = "Пешка на Доске Вечности", objective = "Узнайте о прошлом все, что можно. Потом поговорите с Анахроносом в Пещерах Времени в Танарисе.", description = "Успокоившись и сосредоточив взгляд на кристалле, вы замечаете, что внутри что-то шевелится. Посмотрев поближе, вы осознаете, что перед вами предстало прошлое... давно забытое.", progress = nil, completion = "После предательства Оленьего Шлема я собрал осколки скипетра Зыбучих песков и вернулся сюда. Я желал охранить скипетр от посягательств тех, кто был готов воспользоваться им во зло – так были созданы драконы.\n\nМне казалось, что если разделить части скипетра между четырьмя могущественными Аспектами, то взыскующие Хаос не смогут восстановить его. Я был глупцом. Проклятые драконы охотятся на меня по сей день.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8520] = {title = "Альянсу не хватает шелковых бинтов!", objective = "Принесите 20 шелковых бинтов медсестре Стоунфилд в Палаты войны Стальгорна.", description = "На горизонте маячит война в Ан'Кираже, так что мы должны приложить все усилия, чтобы на поле боя солдаты ни в чем не нуждались. Именно этим мы и занимаемся. Я вот, например, отвечаю за заготовку шелковых бинтов.\n\nНе хочешь ли мне помочь малость?", progress = "Приветик, |3-6(Друид), ну что, удалось раздобыть двадцать шелковых бинтов?", completion = "Друид, ты молодчина! Спасибо за бинты. Благодаря тебе мы еще на шаг приблизились к нашей общей цели. Сейчас пойду уберу бинты, а потом можем еще поболтать.", rewards = nil}
MultiLanguageQuestData['ru'][8521] = {title = "Альянсу по-прежнему не хватает шелковых бинтов!", objective = "Принесите 20 шелковых бинтов медсестре Стоунфилд на аэродром в Дун Морог.", description = "Очень мило с твой стороны снова предложить мне помощь, <класс>. Мы пока собрали всего лишь $2082w шелковых бинтов, так что еще работать и работать.", progress = "Очень мило с твоей стороны снова предложить мне помощь, |3-6(Друид). Мы уже собрали очень много шелковых бинтов, но это, к сожалению, далеко не конец. Лорегон, можешь принести еще штук двадцать? Я была бы благодарна тебе от имени всего Альянса.", completion = "Приятно иметь дело с бескорыстными ребятами вроде тебя, Лорегон. Мы не забудем твой вклад в подготовку к войне. Именно от таких, как ты, и зависит, победим мы или проиграем. Я надеюсь, что наших усилий хватит для победы. \n\nЕще раз большое спасибо!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8522] = {title = "Альянсу не хватает бинтов из рунической ткани!", objective = "Принесите 20 бинтов из рунической ткани хранителю Лунному Сумраку в Палаты войны Стальгорна.", description = "Считай ведение войны сколь угодно сомнительным занятием, <класс>, но военная машина уже завертелась. Оглянись на свою семью и друзей и спроси, чем ты можешь помочь им, – ведь все мы попадем в горнило битвы, и надо будет как-то выживать.\n\nИменно поэтому я запасаюсь бинтами из рунической ткани, кто бы их ни принес. Не хочешь ли внести посильный вклад в это дело?", progress = "Проходит день за днем, а мы все продолжаем и продолжаем готовиться. Друид, тебе удалось достать бинты из рунной ткани?", completion = "Твоя настойчивость в выполнении этого задания выше всяких похвал, |3-6(Друид). Сейчас я уберу бинты на склад и вернусь. Я бы хотел побеседовать с тобой относительно возможности добыть еще бинтов из рунной ткани.", rewards = nil}
MultiLanguageQuestData['ru'][8523] = {title = "Альянсу по-прежнему не хватает бинтов из рунической ткани!", objective = "Принесите 20 бинтов из рунической ткани хранителю Лунному Сумраку на аэродром в Дун Морог.", description = "Итак, мы снова вынуждены говорить о делах, не терпящих отлагательств, <класс>. Хочу еще раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно. Но работы еще непочатый край.\n\n<имя>, можешь принести мне еще бинтов из рунической ткани?", progress = "Итак, мы слова вынуждены говорить о делах, не терпящих отлагательств, |3-6(Воин). Хочу еще раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно. Но работы еще непочатый край. \n\nЖестя, можешь принести мне еще бинтов из рунной ткани?", completion = "Я рад что этот путь мы проделали вместе, Жестя. Работать с тобой – одно удовольствие. Хочу еще раз поблагодарить за бескорыстную помощь Альянсу тебя и всех, подобных тебе. Возращайся скорей, побеседуем еще.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8524] = {title = "Альянсу не хватает радужного тунца!", objective = "Принесите 20 тушек радужного тунца Гладню Гастроному в Палаты войны Стальгорна.", description = "Эй! Если бы я спросил тебя: \"Нужно ли солдатам на войне хорошо кушать?\" – ты бы, без сомнения, <ответил/ответила>: \"Да, конечно!\". И я абсолютно с тобой согласен! Рад, что мы сошлись во мнениях. Теперь, я думаю, ты не будешь спорить, что тебе осталось только отправиться на рыбалку, наловить радужного тунца, приготовить всю порцию и принести мне. М-м-м, я уже в предвкушении.", progress = "Готов поспорить, что ты вернешься с нужным количеством радужного тунца, |3-6(Друид)!", completion = "Два для Альянса, один мне, два для Альянса, один мне... Эгей, отличная работа, рыбак! Похоже, ты отличное приобретение для нашего клуба. А мне кажется, надо б раздобыть еще тунца. Почему бы тебе не прогуляться и не принести еще рыбки? У меня уже в животе урчит...", rewards = nil}
MultiLanguageQuestData['ru'][8525] = {title = "Альянсу по-прежнему не хватает радужного тунца!", objective = "Принесите 20 тушек радужного тунца Гладню Гастроному на аэродром в Дун Морог.", description = "Что? Снова ты? Ну и дела, не будь я гном! Гладень Гастроном, чтобы быть точным. Выходит, ты <пришел/пришла>, чтобы снова помочь мне? Не могу сказать, чтобы я был этим недоволен. А может, тебе просто понравилось, как пахнет жареный тунец? <облизывается>\n\nЛадно, хватит болтать. Ступай-ка и принеси мне побольше радужного тунца!", progress = "Что? Снова ты? Ну и дела, не будь я гном! Гладень Гастрогном, чтобы быть точным. Выходит, ты пришла, чтобы снова помочь мне? Не могу сказать, чтобы я был этим недоволен. А может, тебе просто понравилось, как пахнет жареный тунец? *облизывается*\n\nЛадно, хватит болтать. Ступай-ка и принеси мне побольше радужного тунца!", completion = "Я сразу понял, что в тебе что-то такое есть, детка. Ты выглядишь, как человек, который знает, чего хочет. Да-да, с Глади Гастрогномом есть верное правило, – сделай мне приятно, и ты об этом не пожалеешь. \n\nХа-ха-ха! Ладно, сейчас пойду сложу рыбку и вернусь. Если хочешь, можешь пока приготовить еще двадцать штук.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8526] = {title = "Альянсу не хватает жареного мяса ящера!", objective = "Принесите 20 жареных ящеров Саре Грустносвист в Палаты войны Стальгорна.", description = "Как делишки, <класс>? Я вижу, ты просто рвешься принять участие в заготовке провизии для ан'киражской войны. Мой папочка решил, что ответственность за сбор чего-то там чему-то там меня научит. Как бы не так. Я мясо на дух не выношу.\n\nЛадно, если вдруг захочешь помочь, принеси побольше жареных ящеров. Несомненно, именно об этом мясе и будут мечтать все наши отважные солдаты.", progress = "Ну что, где там наши жареные ящеры?", completion = "Вот это да. Спасибо, что притащил сюда всю эту жженую плоть, |3-6(Друид). Минуточку, сейчас я его покидаю в кучу, – надеюсь, кто-нибудь о нем да позаботится. Если время найдется, может быть, еще принесешь?", rewards = nil}
MultiLanguageQuestData['ru'][8527] = {title = "Альянсу по-прежнему не хватает жареного мяса ящера!", objective = "Принесите 20 жареных ящеров Саре Грустносвист на аэродром в Дун Морог.", description = "О, снова здорово, <класс>. Я вижу, ты в восторге от всей этой беготни. Наверное, ты хочешь принести мне еще двадцать жареных ящеров? Отлично. Тогда пойди и принеси. Увидимся.", progress = "О, снова здорово, |3-6(Друид). Я вижу, ты в восторге от всей этой беготни. Наверное, хочешь принести мне еще двадцать жареных ящеров? Отлично. Так пойди и принеси. Увидимся.", completion = "Вау, ты просто бизнес-воротила. Один твой вид уже наводит на меня усталость. В любом случае, спасибо тебе от имени Альянса и все такое. Пойду позабочусь, чтобы всю эту дохлятину куда-нибудь прибрали. Думаю, ты можешь вернуться попозже, когда я проверю, сколько нам еще осталось собрать. Хотя, если честно, этим мясом уже провоняло здесь абсолютно все.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8528] = {title = "Альянсу не хватает пятнистого желтохвоста!", objective = "Принесите 20 пятнистых желтохвостов охотнице Быстрой Реке в Палаты войны Стальгорна.", description = "Возможно, заготовка вареной рыбы выглядит не особенно героически, но не стоит преуменьшать значение нашей работы, <класс>.Солдаты – такие же люди, как и все, и они хотят есть. Именно поэтому мы должны обеспечить их провиантом, пока не началась война в Ан'Кираже.\n\nЯ получила приказ заготавливать пятнистый желтохвост. Это отличный пищевой ресурс, он хорошо хранится, идет на изготовление различных блюд и совсем не пахнет, в отличие от другой морской рыбы. Ну что, поможешь мне в его заготовке?", progress = "Я уверена, что ты вернулся так быстро, потому что принес необходимое количество желтохвоста.", completion = "Спасибо за быструю и своевременную помощь, |3-6(Друид). Теперь наши солдаты не будут испытывать недостатка в провианте. Подожди немного, я позабочусь о размещении рыбы на складе, и мы обсудим доставку еще одной порции, если ты не против.", rewards = nil}
MultiLanguageQuestData['ru'][8529] = {title = "Альянсу по-прежнему не хватает пятнистого желтохвоста!", objective = "Принесите 20 пятнистых желтохвостов охотнице Быстрой Реке на аэродром в Дун Морог.", description = "Если у тебя еще не пропало желание помогать нам, то нам все еще нужен желтохвост, <имя>. Я думаю, в прошлый раз ты <приобрел/приобрела> достаточно опыта, так что сейчас дело пойдет веселее. Ну что, по рукам?", progress = "Если у тебя еще не пропало желание помогать нам, то нам опять нужен желтохвост, Бэдэльф. Я думаю, в прошлый раз ты приобрел достаточно опыта, так что сейчас дело пойдет веселее. Ну что, по рукам?", completion = "Сразу видно, что ты заботишься о нуждах Альянса, как о своих собственных, Бэдэльф. Твои старания не останутся незамеченными, и награда обязательно найдет своего героя. Спасибо за отлично приготовленную рыбу. Теперь ее можно хранить долго и без особых проблем. Пойду-ка я запишу, сколько ты принес. Когда близится война, на счету должна быть каждая рыбина!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8530] = {title = "Альянсу не хватает опаленных вулканических камней!", objective = "Принесите 50 оплавленных вулканических камней командиру Мощному Молоту на аэродром в Дун Мороге.", description = "<класс>, мне нужна твоя помощь. Есть камни, которые можно достать в Огненных Недрах, – я имею в виду опаленные вулканические камни. Они нужны нам для подготовки к войне в Ан'Кираже. Наши кузнецы и инженеры знают, как их использовать, так что мы получили на них заказ. Проберись в Огненные Недра и собери столько, сколько сможешь. Не сомневаюсь, что тебе удастся уговорить пойти с тобой штук тридцать девять близких приятелей.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][8532] = {title = "Орде не хватает медных слитков!", objective = "Принесите 20 медных слитков шахтеру Кромвелю на Аллею Духов Оргриммара.", description = "Я так рад, что ты <решил/решила> помочь нам. Не всякий бы согласился, так что я лучше еще раз уточню, правильно ли ты меня <понял/поняла>. Мне нужны медные слитки, а не просто медь. У нас недостаточно ни времени, ни людей, чтобы самим ее выплавлять, так что твои усилия не останутся незамеченными. Ну как, <класс>, справишься?", progress = "Я надеюсь, 20 медных слитков у тебя с собой, |3-6(Воин)?", completion = "Вот они, слитки, хорошо, что ты не стал полировать их. В блеске нет никакого смысла, они все равно пойдут на военные нужды. Пойду уложу их в штабели, и нужно позаботиться, чтобы они были пущены в дело. Если добудешь еще двадцать, обращайся прямо ко мне.", rewards = nil}
MultiLanguageQuestData['ru'][8533] = {title = "Орде по-прежнему не хватает медных слитков!", objective = "Принесите 20 медных слитков шахтеру Кромвелю в Дуротар.", description = "Уже <вернулся/вернулась>? Из тебя быстро бы получился отличный рудокоп, <класс>. Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь ее в слитки и возвращайся ко мне. Я знаю, что ты кое-что можешь, вопрос – хочешь ли?", progress = "Уже вернулся? Из тебя быстро получился бы отличный рудокоп, |3-6(Маг). Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь ее в слитки и возвращайся ко мне. Я знаю, что кое-что ты можешь, но вот вопрос – хочешь ли.", completion = "Ты опять доказал, что ты многого стоишь, |3-6(Маг). Я чувствую, эта медь хорошо нам послужит, когда придет время. А теперь мне надо сложить ее в штабеля и подсчитать. Если у тебя не пропало желание, ты, вероятно, сможешь помочь нам, если принесешь еще медных слитков.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8534] = {title = "Донесение разведчика из улья Зора", objective = "Свяжитесь с кенарийской разведчицей Азенель в улье Зора и отнесите ее донесение призывательнице ветров Гордый Рог в крепость Кенария. Кроме того, принесите тактическую задачу VI.", description = "Мы отправили наших лучших разведчиков к ульям силитидов. Азенель уже несколько дней наблюдает за передвижениями этих насекомых. Найди ее и забери у нее письменный отчет. Нам необходимо как можно скорее получить от нее сведения.", progress = "Разведчик Азенель находится внутри Улья Зора. Спеши! Время не ждет.", completion = "Мы очень ценим твои усилия, Лорегон. Я немедленно займусь этим донесением, а ты можешь переходить к следующему заданию.", rewards = "Вы получите:\n\nКенарийский знак тактикаДополнительное тактическое задание"}
MultiLanguageQuestData['ru'][8535] = {title = "Седой храмовник", objective = "Призовите и убейте седого храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу IV.", description = "Сумеречный Молот и повелители стихий, которым поклоняются служители культа, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан'Кираже, мы не должны терять бдительность и давать волю внешним врагам.\n\nОтыщи способ вызвать и уничтожить седого храмовника и доложи о выполнении задания Бору Буйногривому.", progress = "Ты уже выполнил задание?", completion = "Отличная работа, Ренн. Вот следующее задание.", rewards = "Вы получите:\n\nКенарийский знак тактикаТактическое задание"}
MultiLanguageQuestData['ru'][8536] = {title = "Земляной храмовник", objective = "Призовите и убейте земляного храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу III.", description = "Сумеречный Молот и повелители стихий, которым поклоняются культисты, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан'Кираже, мы не должны терять бдительность и давать волю внешним врагам.\n\nОтыщи способ вызвать и уничтожить земляного храмовника и доложи о выполнении задания Бору Буйногривому.", progress = "Ты уже выполнил задание?", completion = "Отличная работа, Ренн. Вот следующее задание.", rewards = "Вы получите:\n\nКенарийский знак тактикаДополнительное тактическое задание"}
MultiLanguageQuestData['ru'][8537] = {title = "Багровый храмовник", objective = "Призовите и убейте багрового храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу II.", description = "Сумеречный Молот и повелители стихий, которым поклоняются служители культа, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан'Кираже, мы не должны терять бдительность и давать волю внешним врагам.\n\nОтыщи способ вызвать и уничтожить багрового храмовника и доложи о выполнении задания Бору Буйногривому.", progress = "Ты уже выполнил задание?", completion = "Отличная работа, Кхалдун. Вот следующее задание.", rewards = "Вы получите:\n\nКенарийский знак тактикаТактическое задание"}
MultiLanguageQuestData['ru'][8538] = {title = "Четыре герцога", objective = "Отыщите способ вызвать и убить герцога Пепла, герцога Глубин, герцога Ветров и герцога Осколков и доложите о выполнении задания командору Мар'алиту в крепости Кенария. Для завершения задания принесите тактическую задачу V.", description = "Связь между Сумеречным Молотом и Советом Бездны оказалась куда важнее, чем нам казалось вначале.\n\nМы не сомневаемся, что повелители Стихий, именуемые герцогами Бездны, управляют служителями культа Сумеречного Молота. Найди способ выманить в наш мир четырех герцогов Бездны и убей их!\n\nМы избрали тебя за прежние заслуги и не сомневаемся, что ты справишься.", progress = "Ты уже выполнила задание?", completion = "Сегодня ты сделала великое дело, Киберка. Тебе удалось избавить нас от злейших врагов. Хвала тебе за это!", rewards = "Вы получите:\n\nДрагоценность Кенария"}
MultiLanguageQuestData['ru'][8539] = {title = "Цель: сестры-убийцы из Улья Зора", objective = "Убейте 30 сестер-убийц из улья Зора и доложите о выполнении задания командору Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу V.", description = "Мы вызвали подкрепление для сражения у улья Зора. Твоя задача – убить как можно больше сестер-убийц. Выполнив задание, поговори с командором Мар'алитом.", progress = "Ты хочешь что-то сказать, |3-6(Паладин)?", completion = "Отличная работа, Ренн. Ты очень ценный союзник.", rewards = "Вы получите:\n\nКенарийский знак бойцаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8540] = {title = "Сапоги для стражей", objective = "Принесите 3 пары изысканных мифриловых сапог Вишу Коцусу, капитану стражи крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу II.", description = "Верховому подразделению крепости Кенария не хватает изысканных мифриловых сапог. Принеси нам очередную партию и передай их капитану Вишу Коцусу из крепости Кенария.", progress = "Что ты мне принесла, Киберка?", completion = "Отлично! Как раз то, что нужно. Спасибо.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8541] = {title = "Шлифовальные камни", objective = "Принесите 10 массивных шлифовальных камней, 10 твердых шлифовальных камней и 10 тяжелых точильных камней Вишу Коцусу, капитану стражи в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу III.", description = "У стражи крепости Кенария на исходе шлифовальные камни. Добудь их и отнеси капитану Вишу Коцусу в крепость Кенария.", progress = "Что ты мне принес, Лорегон?", completion = "Отлично! Нам очень нужны эти материалы. Спасибо.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8542] = {title = "Орде не хватает оловянных слитков!", objective = "Принесите 20 оловянных слитков рубаке Маугу на Аллею Духов Оргриммара.", description = "Лок'тар, <раса>, я уверен, ты в курсе, что мы собираемся воевать с тараканами Ан'Киража. Вождь сказал, что сначала надо как следует подготовиться. Я б охотней точил мечи или подгонял броню, но мне доверили сбор оловянных слитков. Для меня это большая честь, да! Но без помощи мне не справиться.\n\nНадо, чтобы кто-то добывал эти самые слитки и приносил сюда. Нам нужно так много, что, боюсь, я и считать-то до стольких не умею.", progress = "Ну, сколько там у тебя оловянных слитков, |3-6(Чернокнижник)? Думаю, после войны надо бы научиться считать, что ли...", completion = "Хм... Выглядит так, будто слитков столько, сколько нужно... Только не пытайся обмануть меня, |3-6(Чернокнижник)! От этого счета у меня башка раскалывается. Пойду сложу слитки в штабель, а ты пока отправляйся и принеси еще столько же.", rewards = nil}
MultiLanguageQuestData['ru'][8543] = {title = "Орде все еще нужны оловянные слитки!", objective = "Принесите 20 оловянных слитков рубаке Маугу в Дуротар.", description = "Отлично, я понял, к войне ты относишься серьезно. Видишь ли, в ее предвкушении я так нервничаю, что потихоньку начинаю выходить из себя. А твоя медлительность меня просто бесит!!! Не можешь притаскивать товар быстрее, что ли? Может, мне малость с тобой поразмяться, чтобы снять стресс...\n\nХар!!! Нет, не буду, пожалуй, а то кто тогда будет носить мне слитки?", progress = "Отлично, я понял, к войне ты относишься серьезно. Видишь ли, в ее предвкушении я немного нервничаю, думаю, ты меня понимаешь, как солдат солдата, |3-6(Маг). Это будет победоносная война, когда начнется. Воины Орды преодолеют пески и с оружием в руках кинутся на киражских тараканов. В этот день все мы обретем великую славу! \n\nХар! Но сначала нужно собрать достаточное количество этих несчастных оловянных слитков. Забавно, что мы не можем начать грандиозную войну без этих маленьких штуковин, правда?", completion = "Тром'ка, Дэдоутсайд! Своими делами ты оказываешь и мне, и Орде большую честь. Сейчас я позабочусь об этих слитках. А когда мы сделаем все, что нужно, то отправимся на войну и покажем этому ничтожному Альянсу, как надо давить тараканов! \n\nТак что ступай и принеси еще слитков!", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8544] = {title = "Наплеч Завоевателя", objective = "Принесите киражские наручники властности, 2 идола Ночи, 5 каменных и 5 глиняных скарабеев Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.\n\nПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!", progress = "Тебе удалось собрать все, что мне нужно?", completion = "Я изготовил это наплечье, смертный, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8545] = {title = "Орде не хватает мифриловых слитков!", objective = "Принесите 20 мифриловых слитков старшему сержанту Ткелаху. Ткелах находится на аллее Духов Оргриммара.", description = "Война надвигается неотвратимо, и все, что нам остается, <класс>, – это как следует подготовиться к ней. В такие времена мы должны сплотиться и помогать друг другу. Как видишь, меня поставили ответственным за сбор мифриловых слитков, которые потом пойдут на нужды армии. Я стараюсь как могу, но этого пока недостаточно.\n\nСумеешь добыть мифрил на рудниках и переплавить его в слитки? Это бы нам очень пригодилось.", progress = "Хорошо бы поскорее собрать все слитки и закончить подготовку к войне в Ан'Кираже. Ты уже достал все, что мне нужно, дружище?", completion = "Ну вот, очень неплохой зачин в нашей работе, |3-6(Воин). Теперь на складе лежит еще 20 новеньких слиточков, сейчас я внесу их в список. Когда на пороге война, на счету каждая крупинка мифрила! \n\nТы заглядывай, похоже, нам скоро еще понадобятся слитки.", rewards = nil}
MultiLanguageQuestData['ru'][8546] = {title = "Орде все еще не хватает мифриловых слитков!", objective = "Ага, приятно снова тебя видеть, дружище. Я помню, ты уже помог мне разок, а теперь снова нужна твоя помощь. Мы продолжаем собирать для войны мифриловые слитки. Из них получится отличное оружие, которым мы легко передавим всех этих киражских тараканов.\n\nТак что, если ты и правда нам друг, принеси еще мифриловых слитков. Пока мы не выполнили нашу квоту, я очень на тебя рассчитываю.", description = nil, progress = "Ага, приятно снова тебя видеть, дружище. Я помню, ты уже помог мне разок, а теперь снова нужна твоя помощь. Мы продолжаем собирать для войны мифриловые слитки. Из них получится отличное оружие, которым мы легко передавим всех этих киражских тараканов.\n\nТак что, если ты и правда нам друг, принеси еще мифриловых слитков. Пока мы не выполнили нашу квоту, я очень на тебя рассчитываю.", completion = "Отлично сработано, Мард! Мы ближе к цели на целых двадцать слитков. Сейчас я прослежу, чтобы их отгрузили. Если раздобудешь еще двадцать, дружище, сразу же тащи их мне.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8547] = {title = "Привет!", objective = "Принесите подарочный сертификат площади Соколиных Крыльев Марсилле Утренней Звезде.", description = "Добро пожаловать в мир World of Warcraft!\n\nВ знак особой благодарности за приобретение коллекционного издания вы получаете подарок! Передайте этот подарочный сертификат Марсилле Утренней Звезде на площади Соколиных Крыльев. Взамен вы получите маленького спутника, который будет сопровождать вас на пути к славе.\n\nЕще раз благодарим вас и желаем приятного времяпровождения в мире World of Warcraft!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПоводок зерглингаОшейник пандыКамень Диабло"}
MultiLanguageQuestData['ru'][8548] = {title = "Броня добровольца", objective = "Принесите 5 боевых, 3 тыловых и 7 тактических знаков Кенария Варгусу из крепости Кенария в Силитусе. Требуется дружелюбие со стороны Круга Кенария.", description = "Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в крепости Кенария, нужны не для красоты, <имя>.\n\nНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Перчатки могущества землиЗемлетканый плащВам дадут возможность выбрать одну из следующих наград:\n\nКольцо гнева земли"}
MultiLanguageQuestData['ru'][8549] = {title = "Орде не хватает мироцвета!", objective = "Принесите 20 цветков мироцвета травнице Гордый Плюмаж на Аллею Духов Оргриммара.", description = "Говорят, каждое поколение должно пройти испытание огнем. Боюсь, что ан'киражская война станет для нас тем самым горном для закалки. Ничего, подготовимся как следует и покажем всем, из какого мы слеплены теста.\n\nНам нужен мироцвет, который пойдет на создание лекарственных снадобий, и я вызвалась быть ответственной за его сбор. Надеюсь, ты <пришел/пришла> предложить мне свою помощь. Собери побольше мироцвета и принеси его мне.", progress = "Уже собрал мироцвет и вернулся, |3-6(Воин)?", completion = "Подготовка близится к концу, и скоро грянет война. Спасибо за помощь, Мард. Мироцвет очень нужен нам, и твой вклад в общее дело не останется незамеченным. Если сможешь, возвращайся и помоги мне собрать еще мироцвета. А пока ступай, и пусть Мать-Земля хранит тебя.", rewards = nil}
MultiLanguageQuestData['ru'][8550] = {title = "Орде все еще не хватает мироцвета!", objective = "Приветствую тебя еще раз, Дэдоутсайд. Я рада, что ты решил снова помочь нам в этом бесконечном сборе мироцвета. Подготовка к войне идет полным ходом, поэтому эликсиры и снадобья нужны в огромных количествах.\n\nСобери столько же мироцвета, сколько и в прошлый раз, и благодарность моя не будет знать границ. Если вдруг собранный мироцвет у тебя уже с собой, то я приму его с радостью.", description = nil, progress = "Приветствую тебя еще раз, Дэдоутсайд. Я рада, что ты решил снова помочь нам в этом бесконечном сборе мироцвета. Подготовка к войне идет полным ходом, поэтому эликсиры и снадобья нужны в огромных количествах.\n\nСобери столько же мироцвета, сколько и в прошлый раз, и благодарность моя не будет знать границ. Если вдруг собранный мироцвет у тебя уже с собой, то я приму его с радостью.", completion = "Спасибо, что продолжаешь помогать нам, Дэдоутсайд. Твоя самоотдача делает честь тебе и твоим предкам. Пойду упакую травы, чтобы они не потеряли своей свежести к тому времени, когда они понадобятся. Продолжай трудиться на благо нашей победы, во имя Орды!", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"}
MultiLanguageQuestData['ru'][8551] = {title = "Сундук капитана", objective = "Верните Гекельберри Смоттсу из Пиратской Бухты его сундук.", description = "Когда-то у меня был корабль, на котором я плавал до самого Кабестана в Калимдоре, и репутация у меня была безупречная.\n\nПока…\n\nПока не появились проклятые морские великаны! Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую Бухту. А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая. Наглец!\n\nГоворят, Горлаш бродит по берегу к востоку отсюда. Найди его и верни мой сундук! Благодарность моя не будет знать предела.", progress = "Эгей, Эфром! Нашел Горлаша? Это был мой любимый сундук, к тому же в тайном отделении там лежат все мои сокровища!", completion = "О, ты нашел его! О, радость, о счастье! Спасибо, Эфром. Ко мне вернулся мой сундук, и в душе разгорается прежний огонь.\n\nНо месть моя еще не свершилась...", rewards = "Вы получите:\n\nНаручи Кровавой повязки"}
MultiLanguageQuestData['ru'][8552] = {title = "Кушак с монограммой", objective = "Верните кушак с монограммой владельцу.", description = "Вдоль каймы кушака вышита монограмма \"ГС\".", progress = "Привет. У тебя ко мне какое-то дело?", completion = "Тебе удалось вернуть мой кушак? Тогда... ты, должно быть, убил морского великана! Урааа!\n\nКак я рад, что этот негодяй мертв – Мок'раш был одним из трех великанов, которые уничтожили мои корабли и поубивали всю команду.\n\nИ так три раза подряд!\n\nТы достойный |3-6(Друид), Ыгрок.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8553] = {title = "Капитанская сабля", objective = "Поговорите с Салагой.", description = "После того как эти проклятые великаны уничтожили мой корабль, я купил еще один. Назвал его \"Месть Шмотта\", запасся продовольствием, нанял команду и отправился в поисках этих злодеев. Найти-то я их нашел, но... они снова надавали мне по шее. \"Месть Шмотта\" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку.\n\nУ другого великана, Неголаша, моя сабля.\n\nСразись с Неголашем и принеси мне мою саблю!\n\nМожешь поговорить со Салагой, поваром с \"Мести Шмотта\", который выжил в последней битве. Он поможет тебе найти великана.", progress = nil, completion = "Привет-привет, Ыгрок. Капитан говорит, что ты пойдешь на Неголаша, а?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8554] = {title = "Бой с Неголашем", objective = "Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Смоттса.\n\nУбейте Неголаша и отнесите абордажную саблю Смоттса хозяину в Тернистую долину.", description = "Неголаш – великан-обжора.\n\nКогда они уничтожили мой корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это мое коронное блюдо, рецепт я привез из самих Бесплодных земель!\n\nЕсли ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!", progress = "Тебе удалось добыть мою саблю, Сипсик?", completion = "Ты отобрал у Неголаша мою саблю! Глазам своим не верю! Я чувствую, с момента нашей встречи ветер удачи переменился, теперь он попутный!\n\nСпасибо! Если я все же куплю себе новый корабль, а ты пожелаешь поплыть в море, приходи, гостем будешь.", rewards = "Вы получите:\n\nКомпас Смоттса"}
MultiLanguageQuestData['ru'][8555] = {title = "Создание драконов", objective = "Эраникус, Веластрас и Азурегос... Не сомневаюсь, тебе приходилось слышать об этих драконах, смертный. И они не случайно сыграли очень важную роль как наблюдатели нашего мира.\n\nК сожалению (и в этом виновата отчасти моя наивность), под воздействием то ли посланников Древних Богов, то ли предательства близких людей, все они пали. Благодаря чему мое недоверие к твоим собратьям только усилилось.\n\nОтыщи их... И готовься к худшему, |3-6(ночной эльф).", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8556] = {title = "Перстень неумолимой силы", objective = "Принесите киражское кольцо власти, 2 лучистых идола, 5 бронзовых скарабеев и 5 скарабеев из бивневой кости Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария.", description = "Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности. Однако считается, что если заменить пораженные скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастет еще больше.\n\nКамни, украшающие киражских идолов, вполне подойдут – они отменного качества.\n\nПринеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, <класс>.", progress = "Ты принес мне кольцо и остальные материалы, Сиджион?", completion = "Я заменю камень в этом кольце. Увидишь, это сделает его эффективность куда более... приемлемой.", rewards = "Вы получите:\n\nПерстень Неукротимой силыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8557] = {title = "Пелерина неумолимой силы", objective = "Принесите киражскую воинскую пелерину, 2 ониксовых идола, 5 серебряных и 5 костяных скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.", description = "Я рад слышать, что ты помогаешь нам в нападении на Ан'Кираж, <имя>. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.\n\nМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.\n\nУвидишь, эта вещь тебя не разочарует.", progress = "Ты принес мне материал на мантию?", completion = "О да... Эта пелерина безукоризненна. \n\nВозьми ее, Сиджион. Пусть она защитит тебя от нечистой магии кираи.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8558] = {title = "Серп неумолимой силы", objective = "Принесите киражскую шипастую рукоять, 2 алебастровых идола, 5 хрустальных и 5 каменных скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария.", description = "Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов...\n\nПри одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них свое собственное искусство. Докажи Кругу Кенариуса свою преданность, <имя>, и я создам для тебя могучее оружие из лучших киражских материалов.", progress = "Ты принес мне необходимые материалы, Сиджион?", completion = "Ты славно потрудился, |3-6(Воин). Эта рукоять отлично сработана... Как в руке лежит! \n\nПрими это оружие, Сиджион. Пусть оно поможет тебе сокрушить наших врагов!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8559] = {title = "Наголенники Завоевателя", objective = "Принесите киражские наручники властности, 2 идола Войны, 5 золотых скарабеев и 5 скарабеев из бивневой кости Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.\n\nПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.\n\nУвидишь, насколько они окажутся полезны в схватке с врагом.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nНаголенники ЗавоевателяCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8560] = {title = "Набедренники Завоевателя", objective = "Принесите целую шкуру Оуро, 2 идола Смерти, 5 бронзовых скарабеев и 5 скарабеев из бивневой кости Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.", description = "Хочешь доказать нам, что тебе можно доверять, <смертный/смертная>? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.\n\nСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.\n\nШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.\n\nПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8561] = {title = "Корона Завоевателя", objective = "Принесите венец Век'нилаша, 2 идола Солнца, 5 каменных и 5 хрустальных скарабеев Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.", description = "Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.\n\nЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы мощи Ан'Киража будут служить нам.\n\nПринеси то, что мне нужно, <имя>. Взамен я отдам тебе головной убор, не имеющий равных по силе.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКорона Завоевателя"}
MultiLanguageQuestData['ru'][8562] = {title = "Кираса Завоевателя", objective = "Принесите панцирь древнего бога, 2 идола Войны, 5 серебряных и 5 костяных скарабеев Ветсере в Ан'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.", description = "Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.\n\nВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.\n\nКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8563] = {title = "Обучение чернокнижника", objective = "Поговорите с наставником чернокнижников – призывателем Тели'Лариеном в Солнечном Шпиле на острове Солнечного Скитальца.", description = "По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных чернокнижников на острове Солнечного Скитальца тренирует призыватель Тели'Лариен. Поговори с ним, может быть, он сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nТели'Лариен, как и все наставники острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.", progress = nil, completion = "Леповжлдапо... говорят, ты ищешь наставника в чернокнижии? Ты кажешься мне довольно способной, но первое впечатление часто бывает обманчивым. Я жду от тебя готовности ступить в поисках силы туда, куда другие страшатся даже заглянуть. Ты будешь учиться, но неудачи я не прощу.\n\nТвое обучение будет стоить определенной платы, но лучше подумай о том, какую цену придется заплатить твоему разуму за тайное знание. Если у тебя не осталось сомнений в твоем предназначении - мы начнем.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8564] = {title = "Обучение жреца", objective = "Поговорите с наставницей жрецов сестрой Ариной в Солнечном Шпиле на Острове Солнечного Скитальца.", description = "По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных жрецов на Острове Солнечного Скитальца тренирует сестра Арина. Поговори с ней, может быть, она сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nАрина, как и все наставники Острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.", progress = nil, completion = "Приветствую тебя, Акинара. Я – сестра Арина. Я предлагаю свои услуги тем, кто хочет постичь путь жреца. Многие считают, что жрецы не способны на убийство, но эльфы крови придерживаются других взглядов. Мы призваны исцелять плоть и дух, но мы и несем возмездие тем, кто преступает наши законы.\n\nЯ буду тебя обучать, но попрошу покрывать возможные расходы и уделять учебе все внимание. Если ты согласна, то начнем.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
