MultiLanguageQuestData['ru'][8689] = {title = "Накидка бесконечной мудрости", objective = "Принесите киражскую воинскую пелерину, 2 яшмовых идола, 5 золотых и 5 глиняных скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.", description = "Я рад слышать, что ты помогаешь нам в нападении на Ан'Кираж, <имя>. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.\n\nМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.\n\nУвидишь, эта вещь тебя не разочарует.", progress = "Ты принесла мне материал на мантию?", completion = "О да... Эта пелерина безукоризненна. \n\nВозьми ее, Нефер. Пусть она защитит тебя от нечистой магии кираи.", rewards = "Вы получите:\n\nНакидка бесконечной мудрости"}
