MultiLanguageQuestData['ru'][8697] = {title = "Кольцо бесконечной мудрости", objective = "Принесите киражское церемониальное кольцо, 2 обсидиановых идола, 5 серебряных и 5 костяных скарабеев Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария.", description = "Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности. Однако считается, что если заменить пораженные скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастет еще больше.\n\nКамни, украшающие киражских идолов, вполне подойдут – они отменного качества.\n\nПринеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, <класс>.", progress = "Ты принесла мне кольцо и остальные материалы, Нефер?", completion = "Я заменю камень в этом кольце. Увидишь, это сделает его эффективность куда более... приемлемой.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
