MultiLanguageQuestData['ru'][8705] = {title = "Чекан беспредельной мудрости", objective = "Принесите киражскую изысканную рукоять, 2 лучистых идола, 5 бронзовых скарабеев и 5 скарабеев из бивневой кости Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария.", description = "Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов...\n\nПри одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них свое собственное искусство. Докажи Кругу Кенариуса свою преданность, <имя>, и я создам для тебя могучее оружие из лучших киражских материалов.", progress = "Ты принесла мне необходимые материалы, Нефер?", completion = "Ты славно потрудилась, |3-6(Жрица). Эта рукоять отлично сработана... Как в руке лежит! \n\nПрими это оружие, Нефер. Пусть оно поможет тебе сокрушить наших врагов!", rewards = "Вы получите:\n\nЧекан беспредельной мудрости"}
