MultiLanguageQuestData['ru'][8728] = {title = "Хорошая новость и плохая новость", objective = "Нарайн Причуддень из Танариса хочет, чтобы вы принесли ему 20 арканитовых слитков, 10 кусков элементиевой руды, 10 азеротских бриллиантов и 10 синих сапфиров.", description = "Что же, это оказалось дольше, чем я думал. Давай-ка посмотрим, что написано в этой книге.\n\n<Нарайн молча читает книгу, периодически что-то бормоча себе под нос.>\n\nХорошая новость – я на 99% уверен, что смогу сделать арканитовый буй, который будет работать согласно твоим требованиям. А вот это полностью зависит от плохих новостей.\n\nПлохие новости заключаются в том, что мне понадобится куча арканита, элементиевой руды и редких самоцветов.\n\nПринеси мне все, что надо, и я сделаю буй.", progress = "Арканитовые буйки сами собой не делаются, Лорегон. НЕТ, денег взаймы не дам.", completion = "Уговор есть уговор. Надеюсь, вы знаете, во что лезете, Лорегон. Это вам не жук чихнул – рыбку ловить!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8729] = {title = "Гнев Нептулона", objective = "Забросьте арканитовый буй в водоворот в заливе Бурь Азшары.", description = "Я еще не говорил о плохой новости, нет? Ее зовут Каракула – 30 метров смерти и разрушения. Наверное, я забыл об этой мелочи.\n\nМое сверхпсихопсионическое ясновидение говорит мне, что лучше всего будет закинуть буек с берега Азшары, в залив Бурь.\n\nВысматривай водоворот, в котором скорее всего будет до кучи обломков кораблей.\n\nКстати, надеюсь, не в одиночку пойдешь?\n\nЕсли тебе каким-то чудесным образом повезет, отнеси обломок скипетра Анахроносу.", progress = "Время на исходе!", completion = "Славно, Лорегон. Скоро я сумею воссоздать скипетр Зыбучих Песков.", rewards = "Одеяния Темной водыВам дадут возможность выбрать одну из следующих наград:\n\nКольцо Ледяных Глубин\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][8730] = {title = "Порча Нефария", objective = "Убейте Нефариана и добудьте осколок красного скипетра. Верните осколок красного скипетра Анахроносу в Пещеры Времени в Танарис. На выполнение задания у вас есть 5 часов.", description = "Надо же, герой! Тысячу лет назад мне поручили хранить осколок, и вот, в черный час он был отнят у меня... Но какая же трагедия без жестокости?\n\n<Валестраз слабо кашляет.>\n\nОс... осколок скипетра ныне у Нефария.\n\nВремя дорого, ибо Нефарий намерен уничтожить осколок. Поторопись!", progress = "И еще один наш герой пал жертвой отродья Смертокрыла. Когда же окончатся наши страданья...", completion = "Душа Веластраса ныне спокойна, герой. Все Аспекты следят за твоими успехами с великим интересом. Знай – у тебя могучие союзники.\n\nМне было приказано даровать тебе нечто, способное помочь тебе в твоей борьбе. Воспользуйся этим во благо...", rewards = "Инкрустированные ониксом поножиВам дадут возможность выбрать одну из следующих наград:\n\nАмулет барьера теней\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][8731] = {title = "Рутинное задание", objective = "Поступите в распоряжение легиона Оргриммара возле улья Регал. Подготовьте неподписанные бумаги о полевых обязанностях и получите подписанные бумаги о полевых обязанностях, отнесите их призывателю ветров Калдону в крепость Кенария.\n\nВнимание: исцеление или наложение благоприятных заклинаний на бойцов легиона Оргриммара переводит в режим PvP.", description = "Приветствую тебя, <имя>. Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные.\n\nЛегион Оргриммара под предводительством капитана Крушителя Черепов расквартирован рядом с Ульем Регал.\n\nПоговори с капитаном и принеси мне доказательство выполнения его указаний. Тем временем я подготовлю для тебя новое задание.\n\nАх да, сделай одолжение, держись подальше от дружины Стальгорна. Добровольцы Орды и Альянса постоянно грызутся друг с другом.", progress = "Ты выполнил задание, Бхт? Капитан Расколотый Череп – рядом с Ульем Регал.", completion = "Сразу видно, что Круг немного внимания уделяет писанине. Он подписал эти бумаги кровью силитидов!\n\nХорошо, Бхт. Я подготовил для тебя задания, которые наилучшим образом используют твои способности, |3-6(Шаман).\n\nЕсли ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБоевое заданиеЗадание по материально-техническому снабжениюТактическое задание"}
MultiLanguageQuestData['ru'][8732] = {title = "Бумаги о полевых обязанностях", objective = "Бумаги о полевых обязанностях? Что за чушь, Бхт?", description = nil, progress = "Бумаги о полевых обязанностях? Что за чушь, Бхт?", completion = "В старые добрые дни в доказательство выполненного долга я пометил бы твой лоб кровью. Тралл же велит слушаться друидов.\n\nВозьми бумаги и отнеси их в крепость Кенария. Не сомневаюсь, они найдут для тебя подходящую работу.", rewards = "Вы получите:\n\nПодписанные бумаги о полевых обязанностях"}
MultiLanguageQuestData['ru'][8733] = {title = "Эраникус, Тиран Сна", objective = "Отправляйтесь на континент Тельдрассил и найдите агента Малфуриона у стен Дарнаса.", description = "Это будет расплата, <герой/героиня>. Если я сегодня погибну, то паду я за правое дело. Верни осколок зеленого жезла. Освободи Эраникуса от порчи, которой поразили его Древние боги.\n\nОтправляйся в Дарнас. Прямо у стен города ты встретишь одного из моих агентов. Он даст ход нашим делам и оповестит Тиранду о наших планах так, чтобы не прознал Олений Шлем.\n\n<Малфурион вздыхает.>\n\nУтратить милость тысячелетий...", progress = nil, completion = "Огонек молчит, только иногда тихо жужжит. Странно, но он способен ощаться с вами мысленно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8734] = {title = "Тиранда и Ремул", objective = "Отправляйтесь на Лунную поляну и поговорите с хранителем Ремулом.", description = "Тиранда будет извещена, <мертный/смертная>. Шан'до Ярость Бури подготовил меня к неожиданностям.\n\nТеперь тебе надлежит отправиться на Лунную поляну и поговорить с хранителем Ремулом. Он даст тебе дальнейшие инструкции по поводу того, как вызвать Эраникуса.\n\nМы все желаем тебе великой удачи.", progress = nil, completion = "Невозможно будет выманить Эраникуса из Сна, если он того не пожелает. Однако, его намерения заставят его прийти в наш мир. Он жаждет уничтожить живое проявление Малфуриона. Если мы добьемся успеха, это может погубить одного из самых могучих союзников Сна. Кошмар полностью поглотит все, что еще сохранилось, если Малфурион падет...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8735] = {title = "Порча Кошмара", objective = "Отправьтесь к четырем порталам Сна Азерота и добудьте фрагменты порчи Кошмара из каждого из них. Вернитесь к хранителю Ремулу на Лунную поляну по завершении задания.", description = "Тебе нужно оправиться к четырем порталам сна Азерота. Из каждого ты добудешь фрагмент порчи Кошмара. Дракониды, населяющие те места, не будут их отдавать. Возвращайся, когда добудешь все фрагменты.", progress = "*Ремулос находится в глубокой задумчивости.*", completion = "Готова ли ты? Готов ли мир встретить то, что мы собираемся призвать? Я не знаю... У меня есть долг перед Малфурионом. Я связан долгом и честью...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8736] = {title = "Явление Кошмара", objective = "Защитите Ночную гавань от Эраникуса. Не дайте погибнуть хранителю Ремулу. Не убивайте Эраникуса. Защищайте себя. Дождитесь Тиранды.", description = "Мы должны усмирить Эраникуса. Мы не можем позволить ему уничтожить себя!\n\nТиранда уже идет нам на помощь. Мы должны отбить удары дракона и спасти Ночную гавань от неминуемого уничтожения.\n\nСтой на страже! Ты и твои союзники – наша единственная надежда.", progress = nil, completion = "Он пришел в себя, Таквер. Ныне он возвращается в Сон, дабы исправить тот вред, что причинил. Эраникус станет могучим союзником Малфуриону и моему отцу.\n\nПрими эти доспехи, Таквер, они подарены мне самой Изерой. Они пригодятся тебе в сражении с киражами.", rewards = "Сапоги работягиВам дадут возможность выбрать одну из следующих наград:\n\nОжерелье Драконьих Клыков\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][8737] = {title = "Лазурный храмовник", objective = "Призовите и убейте лазурного храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу I.", description = "Сумеречный Молот и повелители стихий, которым поклоняются служители культа, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан'Кираже, мы не должны терять бдительность и давать волю внешним врагам.\n\nОтыщи способ вызвать и уничтожить лазурного храмовника и доложи о выполнении задания Бору Буйногривому.", progress = "Ты уже выполнил задание?", completion = "Отличная работа, Кхалдун. Вот следующее задание.", rewards = "Вы получите:\n\nКенарийский знак тактикаДополнительное тактическое задание"}
MultiLanguageQuestData['ru'][8738] = {title = "Донесение разведчика из улья Регал", objective = "Свяжитесь с разведчиком Кенария Ландионом в улье Регал и отнесите донесение разведчика из улья Регал призывательнице ветров Гордый Рог в крепость Кенария. Кроме того, принесите тактическую задачу VII.", description = "Мы отправили наших лучших разведчиков к ульям силитидов. Разведчик Ландион уже несколько дней наблюдает за передвижениями этих насекомых. Найди его и забери у него письменный отчет. Нам необходимо как можно скорее получить собранные сведения.", progress = "Разведчик Ландион находится внутри Улья Регал. Спеши, Фео! Время не ждет.", completion = "Мы очень ценим твои усилия, Фео. Я немедленно займусь этими донесениями, а ты можешь переходить к следующему заданию.", rewards = "Вы получите:\n\nКенарийский знак тактикаДополнительное тактическое задание"}
MultiLanguageQuestData['ru'][8739] = {title = "Донесение разведчика из улья Аши", objective = "Свяжитесь с разведчиком Кенария Джалией в улье Аши и отнесите донесение разведчика призывательнице ветров Гордый Рог в крепость Кенария. Кроме того, принесите тактическую задачу VIII.", description = "Мы отправили наших лучших разведчиков к ульям силитидов. Разведчик Джалия уже несколько дней наблюдает за передвижениями этих насекомых. Найди ее и забери у нее письменный отчет. Нам необходимо как можно скорее получить собранные сведения.", progress = "Разведчик Джалия находится внутри Улья Аши. Спеши, Драккард! Время не ждет.", completion = "Мы очень ценим твои усилия, Драккард. Я немедленно займусь этим донесением, а ты можешь переходить к следующему заданию.", rewards = "Вы получите:\n\nКенарийский знак тактикаТактическое задание"}
MultiLanguageQuestData['ru'][8740] = {title = "Сумеречные мародеры", objective = "Убейте сумеречного мародера Морну и двух сумеречных мародеров. Доложите о выполнении задания призывательнице ветров Гордый Рог. Кроме того, сдайте тактическую задачу IX.", description = "В последнее время появились верховые отряды сторонников Сумеречного Молота. Они не суются в земли, охраняемые крепостью Кенария, а грабят небольшие караваны и отряды.\n\nНайди и убей сумеречных мародеров, а заодно и их лидера, воительницу по имени Морна. О выполнении задания доложи призывательнице ветров Гордый Рог.", progress = "Ты уже выполнил задание?", completion = "Молодец, Горрат. Сумеречные мародеры причинили нам множество неприятностей. Мириться с ними было нельзя. Вот тебе следующее задание.", rewards = "Вы получите:\n\nКенарийский знак тактикаДополнительное тактическое задание"}
MultiLanguageQuestData['ru'][8741] = {title = "Возвращение победителя", objective = "Отнесите осколок зеленого скипетра Анахроносу в Пещеры Времени в Танарисе.", description = "Хранитель ждет твоего возвращения, <имя>. Отнеси этот осколок зеленого скипетра Анахроносу в Пещеры Времени.", progress = "<Анахронос кивает.>", completion = "Твои деяния станут всем известны. Тебя будут славить в песнях от Оргриммара до дальних пределов Южных морей. Все узнают о поборнике Бронзовых драконов, Таквер.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8742] = {title = "Армия Калимдора", objective = "Миновала тысяча лет и, как и было предрешено, ныне предо мной стоит избранница судьбы. Та, кто поведет свой народ в новый век.\n\nДревний бог трепещет, Киберушко. Да, он боится твоей веры. Ниспровергни пророчество К'Туна.\n\nОн знает, что ты идешь, избранница – и с тобой идет вся мощь Калимдора. Скажи мне, когда будешь готова, и я отдам тебе скипетр Зыбучих Песков.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8743] = {title = "Бей в гонг!", objective = "Гонг Скарабея зловеще нависает над тобой. Крепись духом, Киберушко – как только гонг Скарабея загудит, врата Ан'Киража откроются.\n\nДряхлая пасть этого зверя может извергнуть только хаос и разрушение. Защити свой народ!", description = nil, progress = "Гонг Скарабея зловеще нависает над тобой. Крепись духом, Киберушко – как только гонг Скарабея загудит, врата Ан'Киража откроются.\n\nДряхлая пасть этого зверя может извергнуть только хаос и разрушение. Защити свой народ!", completion = "Из земли рядом с гонгом торчит особенный кристалл. Возможно, это подарок племени Ноздорму.", rewards = "Вы получите:\n\nЧерный киражский резонирующий кристалл"}
MultiLanguageQuestData['ru'][8744] = {title = "Тщательно упакованный подарок", objective = "Надпись на подарке гласит:\n\nДорогому Блэкбукник.\n\nЖелаю счастливого праздника Зимнего Покрова.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nТщательно упакованный подарок"}
MultiLanguageQuestData['ru'][8745] = {title = "Сокровище Вневременного", objective = "Привет тебе, избранник. Я Джонатан, хранитель священного гонга и вечный страж Бронзовых драконов.\n\nВневременный дал мне право даровать тебе один предмет на выбор из его клада вне времен. Да поможет он тебе в битве с К'Туном.", description = nil, progress = nil, completion = nil, rewards = "Наследие Гребня ВоронаРунический меч КрасногоПечаль Песни тенейКлык КориалстразаВы получите:\n\n"}
MultiLanguageQuestData['ru'][8746] = {title = "Метцен-северный олень", objective = "Освободите Метцена-северного оленя от его пленителей в Промерзшей пещере, что в Предгорьях Хилсбрада.", description = "БЕДА! Похищен Метцен – северный олень!\n\nМетцен – один из восьми оленей Дедушки Зимы и собственность \"Пастбищ Дымного Леса\". Мы полагаем, что его похитил Омерзительный Гринч, который прячется в Предгорьях Хилсбрада. Праздник уже вовсю идет, и мы никак не можем отлучаться от нашей копилки! Прошу тебя – найди Метцена, срази его пленителей и верни его нам!", progress = "Транделар! Ну что, помогли тебе эти записки? Метцен нашелся? Страшно подумать, что могли сделать с ним эти бессердечные головорезы... Но мы просто не могли выплатить такой запредельный выкуп!", completion = "Ур-ра! Получилось!\n\nМетцен буквально только что прилетел обратно в свои стойла! Да-да, конечно же, Метцен умеет летать. Пыль сработала отлично! Я так и знал! Ты буквально спас нас – и не только праздник Зимнего Покрова, но и сами \"Пастбища Дымного Леса\"! Спасибо тебе, Транделар.\n\nПослушай... За свои труды ты заслуживаешь награды. Вот, держи. Это не просто приправа. Если когда-нибудь у тебя будет верховое животное, эта штука тебе пригодится. Счастливого Зимнего Покрова!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\nСушеный остролист"}
MultiLanguageQuestData['ru'][8747] = {title = "Путь защитника", objective = "Недурно, малыш. Тебе пришлось немало попотеть, чтобы заслужить благосклонность Бронзовых драконов. Мы не забудем твоих усилий.\n\nПерстень-печатка защитника охранит тебя от сил зла.\n\nЕще раз подумай хорошенько. Избрав путь, ты не сможешь сойти с него.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8748] = {title = "Путь защитника", objective = "Мы не забудем, как ты защищал детей Калимдора. Дай мне свой перстень-печатку, и я наложу на него более сложные чары.", description = nil, progress = "Мы не забудем, как ты защищал детей Калимдора. Дай мне свой перстень-печатку, и я наложу на него более сложные чары.", completion = "Твое возвышение среди Племени производит впечатление. Да не свернешь ты с пути защитника!", rewards = "Вы получите:\n\nПерстень-печатка Бронзовых драконов"}
MultiLanguageQuestData['ru'][8749] = {title = "Путь защитника", objective = "Ты оказываешь честь моему роду, Киберушко. Рази врагов Калимдора! Покажи им, что значит земля вечного звездного света.\n\nТы заработала еще одно заклятье. Дай мне свой перстень, и я усилю его.", description = nil, progress = "Ты оказываешь честь моему роду, Киберушко. Рази врагов Калимдора! Покажи им, что значит земля вечного звездного света.\n\nТы заработала еще одно заклятье. Дай мне свой перстень, и я усилю его.", completion = "Твое возвышение среди Племени производит впечатление. Да не свернешь ты с пути защитника!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8750] = {title = "Путь защитника", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПерстень-печатка Бронзовых драконов"}
MultiLanguageQuestData['ru'][8751] = {title = "Защитник Калимдора", objective = "Никогда прежде мне не случалось видеть такой стойкости! Бронзовые драконы даруют тебе свои последние чары. Этого потребовал сам Вневременной!\n\nДай мне свой перстень, и я наложу на него еще одно заклятье.", description = nil, progress = "Никогда прежде мне не случалось видеть такой стойкости! Бронзовые драконы даруют тебе свои последние чары. Этого потребовал сам Вневременной!\n\nДай мне свой перстень, и я наложу на него еще одно заклятье.", completion = "Хвала тебе, Защитник Калимдора! Великая тебе хвала!", rewards = "Вы получите:\n\nПерстень-печатка Бронзовых драконов"}
MultiLanguageQuestData['ru'][8752] = {title = "Путь победителя", objective = "Недурно, малыш. Тебе пришлось немало попотеть, чтобы заслужить благосклонность Бронзовых драконов. Мы не забудем твоих усилий.\n\nПерстень-печатка победителя придаст мощи твоим ударам.\n\nЕще раз подумай хорошенько. Избрав путь, ты не сможешь сойти с него.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПерстень-печатка Бронзовых драконовCurrency Token Test Token 4"}
