MultiLanguageQuestData['ru'][8754] = {title = "Путь победителя", objective = "Ты оказываешь честь моему роду, Киберка. Рази врагов Калимдора! Покажи им, что значит земля вечного звездного света.\n\nТы заработала еще одно заклятье. Дай мне свой перстень, и я улучшу его.", description = nil, progress = "Ты оказываешь честь моему роду, Киберка. Рази врагов Калимдора! Покажи им, что значит земля вечного звездного света.\n\nТы заработала еще одно заклятье. Дай мне свой перстень, и я улучшу его.", completion = "Твое возвышение среди Племени производит впечатление. Да не свернешь ты с пути победителя!", rewards = "Вы получите:\n\nПерстень-печатка Бронзовых драконов"}
MultiLanguageQuestData['ru'][8755] = {title = "Путь победителя", objective = "Подобное упорство нечасто встретишь. Ты доказала, что у тебя стальная воля, Эммарель. Тебя ждет награда за неусыпное бдение.\n\nДай мне свой перстень, и я укреплю наложенное на него заклинание.", description = nil, progress = "Подобное упорство нечасто встретишь. Ты доказала, что у тебя стальная воля, Эммарель. Тебя ждет награда за неусыпное бдение.\n\nДай мне свой перстень, и я укреплю наложенное на него заклинание.", completion = "Твое возвышение среди Племени производит впечатление. Да не свернешь ты с пути победителя!", rewards = "Вы получите:\n\nПерстень-печатка Бронзовых драконов"}
MultiLanguageQuestData['ru'][8756] = {title = "Победитель киражи", objective = "Никогда прежде не случалось видеть мне такой стойкости! Бронзовые драконы даруют тебе свои последние чары. Этого потребовал сам Вневременной!\n\nДай мне свой перстень, и я наложу на него еще одно заклятье.", description = nil, progress = "Никогда прежде не случалось видеть мне такой стойкости! Бронзовые драконы даруют тебе свои последние чары. Этого потребовал сам Вневременной!\n\nДай мне свой перстень, и я наложу на него еще одно заклятье.", completion = "Хвала тебе, Победитель киражей! Великая тебе хвала!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8757] = {title = "Путь заклинателя", objective = "Недурно, малыш. Тебе пришлось немало попотеть, чтобы заслужить благосклонность Бронзовых драконов. Мы не забудем твоих усилий.\n\nПерстень-печатка заклинателя поможет тебе развить магические и естественные способности.\n\nЕще раз подумай хорошенько. Избрав путь, ты не сможешь сойти с него.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПерстень-печатка Бронзовых драконовCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8758] = {title = "Путь заклинателя", objective = "Мы не забудем, как ты защищал детей Калимдора. Дай мне свой перстень-печатку, и я наложу на него более сложные чары.", description = nil, progress = "Мы не забудем, как ты защищал детей Калимдора. Дай мне свой перстень-печатку, и я наложу на него более сложные чары.", completion = "Твое возвышение среди Племени производит впечатление. Да не свернешь ты с пути заклинателя!", rewards = "Вы получите:\n\nПерстень-печатка Бронзовых драконов"}
MultiLanguageQuestData['ru'][8759] = {title = "Путь заклинателя", objective = "Ты оказываешь честь моему роду, Ренгольд. Рази врагов Калимдора! Покажи им, что значит земля вечного звездного света.\n\nТы заработал еще одно заклятье. Дай мне свой перстень, и я усилю его.", description = nil, progress = "Ты оказываешь честь моему роду, Ренгольд. Рази врагов Калимдора! Покажи им, что значит земля вечного звездного света.\n\nТы заработал еще одно заклятье. Дай мне свой перстень, и я усилю его.", completion = "Твое возвышение среди Племени производит впечатление. Да не свернешь ты с пути заклинателя!", rewards = "Вы получите:\n\nПерстень-печатка Бронзовых драконов"}
MultiLanguageQuestData['ru'][8760] = {title = "Путь заклинателя", objective = "Подобное упорство нечасто встретишь. Ты доказал, что у тебя стальная воля, Ренгольд. Тебя ждет награда за неусыпное бдение.\n\nДай мне свой перстень, и я укреплю наложенное на него заклинание.", description = nil, progress = "Подобное упорство нечасто встретишь. Ты доказал, что у тебя стальная воля, Ренгольд. Тебя ждет награда за неусыпное бдение.\n\nДай мне свой перстень, и я укреплю наложенное на него заклинание.", completion = "Твое возвышение среди Племени производит впечатление. Да не свернешь ты с пути заклинателя!", rewards = "Вы получите:\n\nПерстень-печатка Бронзовых драконов"}
MultiLanguageQuestData['ru'][8761] = {title = "Великий заклинатель", objective = "Никогда прежде не случалось видеть мне такой стойкости! Бронзовые драконы даруют тебе свои последние чары. Этого потребовал сам Вневременной!\n\nДай мне свой перстень, и я наложу на него еще одно заклятье.", description = nil, progress = "Никогда прежде не случалось видеть мне такой стойкости! Бронзовые драконы даруют тебе свои последние чары. Этого потребовал сам Вневременной!\n\nДай мне свой перстень, и я наложу на него еще одно заклятье.", completion = "Хвала тебе, Великий заклинатель! Великая тебе хвала!", rewards = "Вы получите:\n\nПерстень-печатка Бронзовых драконов"}
MultiLanguageQuestData['ru'][8762] = {title = "Метцен – северный олень", objective = "Освободите Метцена-северного оленя от его пленителей в Промерзшей пещере, что в Предгорьях Хилсбрада.", description = "БЕДА! Похищен Метцен – северный олень!\n\nМетцен – один из восьми оленей Дедушки Зимы и собственность \"Пастбищ Дымного Леса\". Мы полагаем, что его похитил Омерзительный Гринч, который прячется в Предгорьях Хилсбрада. Праздник уже вовсю идет, и мы никак не можем отлучаться от нашей копилки! Прошу тебя – найди Метцена, срази его пленителей и верни его нам!", progress = "Огневар! Тех записок в сумке, что я тебе дал, оказалось достаточно для обнаружения Метцена? Страшно подумать, что могли сделать с ним эти бессердечные головорезы... Но мы просто не могли выплатить такой запредельный выкуп!", completion = "Ты это сделал! Ура-а-а!\n\nМетцен совсем недавно прилетел обратно в свои стойла – да-да, Метцен умеет летать! Эта пыль сработала чудодейственно, я так и знал! Ты спас не только праздник Зимнего Покрова, но и Пастбища Дымного Леса! Спасибо тебе, Огневар.\n\nСлушай... за твои великие дела хочу дать тебе вот это. Это нечто ОСОБЕННОЕ – если ты заведешь себе верховое животное, эта штука тебе пригодится. Счастливого Зимнего Покрова!", rewards = "Вы получите:\n\nСушеный остролист"}
MultiLanguageQuestData['ru'][8763] = {title = "Герой дня", objective = "Принесите 1 порцию глубокоскальной соли и 5 золотых монет к любой сушилке для остролиста, чтобы получить 5 сушеных остролистов.", description = "Слушай... Вообще-то тебе об этом знать не полагается, но, раз уж ты <герой/героиня> дня и все такое…\n\nВ это время года повсюду полно свежего остролиста, но он быстро вянет. У нас есть машинка, которая заготовляет остролист таким образом, что он не портится! Знаешь, почем его можно продать летом?\n\nЯ разрешу тебе воспользоваться сушилкой, но только если ты мастер-кулинар. От тебя потребуется некоторое количество глубокоскальной соли и два-три... ну, скажем, пять золотых. И ты получишь славную партию остролиста, которую можно хранить сколько угодно.", progress = "На первый взгляд, сушилка для остролиста напоминает нечто вроде перегонного куба, но, если вглядеться повнимательнее, становится видно, что в основную конструкцию внесены типично гоблинские изменения. Тем не менее вы – достаточно опытный кулинар, чтобы разобраться, как работает эта машина.\n\nСвежий остролист в машину уже загружен – нужно только добавить глубокоскальной соли и пять золотых монет, и машинка заработает.", completion = "Машина при начале работы тихонько гудит и выпускает облачко пара. Вскоре она останавливается, и из нее выходит еще одна струйка пара. Дверца открывается, а за ней – партия сушеного остролиста!", rewards = "Вы получите:\n\nСушеный остролист"}
