MultiLanguageQuestData['ru'][8770] = {title = "Цель: защитники из Улья Аши", objective = "Убейте 30 защитников из улья Аши и доложите о выполнении задания командору Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу I.", description = "По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Аши. Твоей основной целью будут защитники из этого улья.\n\nВыполнив задание, поговори с командором Мар'алитом.", progress = "Ты хочешь что-то сказать, |3-6(Шаман)?", completion = "Отличная работа, Ренн. Мы не забудем твоих усилий.", rewards = "Вы получите:\n\nКенарийский знак бойцаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8771] = {title = "Цель: песчаные ловцы из улья Аши", objective = "Убейте 30 песчаных ловцов из улья Аши и доложите о выполнении задания командору Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу II.", description = "По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Аши. Твоей основной целью будут песчаные ловцы из этого улья.\n\nВыполнив задание, поговори с командором Мар'алитом.", progress = "Ты хочешь что-то сказать, |3-6(Воин)?", completion = "Отличная работа, Ренн. Твои подвиги в сражении при Улье Аши не прошли незамеченными.", rewards = "Вы получите:\n\nКенарийский знак бойцаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8772] = {title = "Цель: стражи дорог из Улья Зора", objective = "Убейте 30 стражей дорог из улья Зора и доложите о выполнении задания командору Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу VI.", description = "Мы вызвали подкрепление для сражения у улья Зора. Твоя задача – убить как можно больше стражей дорог. Выполнив задание, поговори с командором Мар'алитом.", progress = "Ты хочешь что-то сказать, |3-6(Шаман)?", completion = "Отличная работа, Ренн. Твои подвиги в сражении при Улье Зора не прошли незамеченными.", rewards = "Вы получите:\n\nКенарийский знак бойцаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8773] = {title = "Цель: разрушители из Улья Зора", objective = "Убейте 30 разрушителей из улья Зора и доложите о выполнении задания командору Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи IV.", description = "Мы вызвали подкрепление для сражения у улья Зора. Твоя задача – убить как можно больше разрушителей. Выполнив задание, поговори с командором Мар'алитом.", progress = "Ты хочешь что-то сказать, |3-6(Паладин)?", completion = "Я слышал немало добрых слов о твоем участии в нападении на Улей Зора. Продолжай в том же духе, и победа будет за нами.", rewards = "Вы получите:\n\nКенарийский знак бойца"}
MultiLanguageQuestData['ru'][8774] = {title = "Цель: стерегущие из Улья Регал", objective = "Убейте 30 стерегущих из улья Регал и доложите об этом командору Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи VIII.", description = "По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Регал. Твоей основной целью будут стерегущие из этого улья.\n\nВыполнив задание, отчитайся поговори с командором Мар'алитом.", progress = "О чем ты хочешь рассказать, Фео?", completion = "Отличная работа, Фео. Твои подвиги в сражении при Улье Регал не прошли незамеченными.", rewards = "Вы получите:\n\nКенарийский знак бойцаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8775] = {title = "Цель: огнеполохи из улья Регал", objective = "Убейте 30 огнеполохов из улья Регал и доложите о выполнении задания командору Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу IX.", description = "По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Регал. Твоей основной целью будут злюки из этого улья.\n\nВыполнив задание, поговори с командором Мар'алитом.", progress = "О чем ты хочешь рассказать, Ишт?", completion = "Отличная работа, Ишт. Твои подвиги в сражении при Улье Регал не прошли незамеченными.", rewards = "Вы получите:\n\nКенарийский знак бойцаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8776] = {title = "Цель: поработители из улья Регал", objective = "Убейте 30 поработителей из улья Регал и доложите о выполнении задания командору Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу X.", description = "По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Регал. Твоей основной целью будут поработители из этого улья.\n\nВыполнив задание, поговори с командором Мар'алитом.", progress = "О чем ты хочешь рассказать, Ишт?", completion = "Отличная работа, Ишт. Твои подвиги в сражении при Улье Регал не прошли незамеченными.", rewards = "Вы получите:\n\nКенарийский знак бойцаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8777] = {title = "Цель: землерои из Улья Регал", objective = "Убейте 30 землероев из улья Регал и доложите о выполнении задания командору Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу XI.", description = "По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Регал. Твоей основной целью будут землерои из этого улья.\n\nВыполнив задание, поговори с командором Мар'алитом.", progress = "О чем ты хочешь рассказать, Фео?", completion = "Отличная работа, Фео. Твои подвиги в сражении при Улье Регал не прошли незамеченными.", rewards = "Вы получите:\n\nКенарийский знак бойцаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8778] = {title = "Взрывчатка для дружины Стальгорна", objective = "Принесите 6 бутылок воспламеняющей смеси, 5 бочонков гоблинского ракетного топлива и 10 порций концентрированного взрывчатого вещества чародею Форсунчику возле улья Зора в Силитусе. Кроме того, принесите тыловое задание IV.", description = "Стальгорнская дружина прислала необычный запрос – на весьма... э-э-э... неустойчивые вещества. Собери их и принеси господину Форсунчику из Стальгорнской дружины.", progress = "Что ты мне принес, Лорегон?", completion = "Ах, да! Они очень пригодятся! Большое спасибо, Лорегон!", rewards = "Вы получите:\n\nКенарийский знак тыловикаДополнительное задание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8779] = {title = "Материалы для гадания", objective = "Принесите 1 большой сияющий осколок, 1 большой светозарный осколок и 1 огромный изумруд геологу Ехидной в крепость Кенария в Силитусе. Также принесите тыловое задание V.", description = "Исследования геолога Ехидной имели огромное значение для нашей кампании в Силитусе. Недавно она запросила материалы для своего исследования.\n\nПожалуйста, собери все необходимое и отнеси ей. Пусть она продолжает работу.", progress = "Что ты мне принес, Кхалдун?", completion = "О да... Ты мне очень помог! Достать эти материалы в пустыне невероятно сложно. Спасибо, Кхалдун.", rewards = "Вы получите:\n\nКенарийский знак тыловикаДополнительное задание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8780] = {title = "Комплекты брони", objective = "Принесите 8 комплектов грубой брони и 8 накладок из толстой кожи Джанеле Твердомолот на заставу дружины Стальгорна возле улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VII.", description = "У дружины Стальгорна на исходе запасы комплектов брони. Добудь партию таких комплектов и отнеси их Джанеле Твердомолот на заставу дружины Стальгорна, что рядом с Ульем Зора.", progress = "Что ты мне принес, Фео?", completion = "Спасибо, я передам их нашим ребятам.", rewards = "Вы получите:\n\nКенарийский знак тыловикаДополнительное задание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8781] = {title = "Нехватка оружия", objective = "Принесите 2 палаша из лунной стали Джанеле Твердомолот на заставу дружины Стальгорна возле улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VI.", description = "Дружина Стальгорна оказалась чрезвычайно полезным союзником в наших битвах в Силитусе. К сожалению, по пути они растеряли много припасов и оборудования. Добудь партию оружия и доставь ее Джанеле Твердомолот к Улью Зора.", progress = "Что ты мне принес, Гуреус?", completion = "Отлично! Мне не придется выслушивать жалобы на тупые клинки. Спасибо, Гуреус.", rewards = "Вы получите:\n\nКенарийский знак тыловикаДополнительное задание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8782] = {title = "Поставки формы", objective = "Принесите 1 кусок луноткани, 2 рулона рунической ткани и 1 железношелковую паутину призывательнице ветров Гордый Рог в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу VIII.", description = "У нас такой приток добровольцев, что не хватает формы. Принеси материалы для пошива формы и отдай их призывательнице ветров Гордый Рог.", progress = "Что ты мне принес, Кхалдун?", completion = "А, да, нам их очень не хватало. Спасибо за добрую службу, Кхалдун.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8783] = {title = "Необычные материалы", objective = "Принесите Варгусу из крепости Кенария в Силитусе 2 зачарованных ториевых слитка и 2 куска зачарованной кожи. Кроме того, принесите тыловое задание IX.", description = "Варгус, кузнец крепости Кенария, запросил партию зачарованных материалов для создания мощного оружия для наших солдат. Добудь все необходимое и отнеси их Варгусу в крепость Кенария, чтобы он снабдил войска всем необходимым.", progress = "Что ты мне принес, Драккард?", completion = "Да-да. Превосходные материалы. Спасибо, Драккард.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8784] = {title = "Секреты киражи", objective = "Принесите древний киражский артефакт драконам, которые укрылись в храме, недалеко от входа.", description = "Вам удалось обнаружить древний киражский артефакт! Возможно, один из драконов, стоящих в храме недалеко от входа, сможет найти применение этой реликвии.", progress = "Ты весь светишься! Я знаю, что это значит...", completion = "Какая поразительная находка, Кормакс. Просто изумительная! Определенно, она поможет нам проникнуть в извращенные умы наших врагов.", rewards = nil}
MultiLanguageQuestData['ru'][8785] = {title = "Амулеты для легиона Оргриммара", objective = "Принесите 6 мощных амулетов, 6 бутылей большого колдунства и 8 бутылок воспламеняющей смеси жрице Тьмы Шаи к улью Регал в Силитус. Кроме того, принесите тыловое задание IV.", description = "Легион Оргриммара послал запрос на несколько необычные вещества. Учитывая, как хорошо они проявили себя в Силитусе, мы бы хотели как можно скорее выполнить их просьбу. Собери материалы и отнеси их троллихе по имени Шаи.", progress = "Ты принес мне все материалы?", completion = "Ах, да. То что нужно! Из этих веществ я сделаю особое зелье. Оно оч-чень не понравится силитидам!", rewards = "Вы получите:\n\nКенарийский знак тыловикаДополнительное задание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8786] = {title = "Нехватка оружия", objective = "Принесите 3 массивных железных топора Мероку Долгому Шагу в лагерь легиона Оргриммара рядом с ульем Регал. Кроме того, сдайте тыловую задачу VI.", description = "Легион Оргриммара послал запрос на поставку оружия, а его нет на складе! Добудь необходимое снаряжение и отнеси его Мероку Дальнему Пути к Улью Регал.", progress = "Что ты мне принесла, Илет?", completion = "Отличная работа. Нам очень не хватало оружия.", rewards = "Вы получите:\n\nКенарийский знак тыловикаДополнительное задание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8787] = {title = "Комплекты брони", objective = "Принесите 8 комплектов грубой брони и 8 накладок из толстой кожи Мероку Долгому Шагу к улью Регал. Кроме того, сдайте тыловую задачу VII.", description = "В Силитус, к нам на подмогу, прибыли отважные добровольцы из легиона Оргриммара. По пути они растеряли свои запасы накладок на доспехи. Добудь партию таких комплектов и отнеси их Мероку Дальнему Пути, в лагерь легиона Оргриммара.", progress = "Что ты мне принесла, Илет?", completion = "Отлично... Я раздам все комплекты солдатам. Легион Оргриммара благодарит тебя, Илет!", rewards = "Вы получите:\n\nКенарийский знак тыловикаДополнительное задание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8788] = {title = "Слегка помятый подарок", objective = "Похоже, этот подарок несколько раз встряхнули. Ярлычок гласит:\n\nСамому любимому |3-2(таурен).", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nСлегка помятый подарок"}
MultiLanguageQuestData['ru'][8789] = {title = "Киражское императорское оружие", objective = "Аригос в Храме Ан'Киража создаст для вас усиленное элементием оружие, если вы принесете ему киражское имперское оружие и 3 куска элементиевой руды.", description = "Мы не то чтобы просто сидели здесь на протяжении тысячелетий, <имя>.\n\nМы наблюдали за торжеством этих тварей, пока они пировали и истощали свои ресурсы. Мы слушали, как они строят схемы и планы по уничтожению нашего мира. Мы узнали о предателях в их рядах.\n\nУ них есть слабости, и теперь мы знаем, как их использовать.\n\nНайди и принеси мне их церемониальное оружие. В сочетании с предметами, созданными непостоянством их собственного бога, оно станет силой, с которой придется считаться любому.", progress = "Найди то, что мне нужно, и ты станешь чем-то большим, чем сумма составляющих твою личность элементов, защитник.", completion = "Это оружие, усиленное элементием, одинаково легко пронзит как обычного кираи, так и их бога.", rewards = "Благословенная киражская секираБлагословенный киражский широкий кинжалБлагословенный киражский щитБлагословенный киражский мушкетВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8790] = {title = "Киражские императорские регалии", objective = "Меритра из Сна в Храме Ан'Киража может создать для вас усиленное элементием оружие, если вы принесете ей киражские имперские регалии и 3 куска элементиевой руды.", description = "Аригос предполагает, что элемент, рожденный в результате столкновения между древними богами и их прислужниками, в надлежащих условиях станет для них смертельным. Я имею в виду элементий, <смертный/смертная>.\n\nПринеси мне киражские императорские регалии и это вещество-яд, я и смогу создать оружие, обладающее великой силой.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Благословенный киражский боевой молотБлагословенный посох киражского послушникаБлагословенный посох киражского авгураВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8791] = {title = "Повергнутый Оссириан", objective = "Принесите голову Оссириана Неуязвимого командору Мар'алиту в крепость Кенария.", description = "Смертельная угроза больше не нависает над нами. Безжалостный Оссириан повержен!\n\nОб этой победе должны узнать все жители Калимдора. Отнесите голову Оссириана командору Мар'алиту в крепость Кенария.", progress = "О, Токсишка, ты уже вернулась! Целой и невредимой, могу добавить. Ну, какие новости из Ан'Киража?", completion = "Выражаю тебе нашу наиглубочайшую благодарность. Ты оказала огромную услугу жителям Калимдора. Можешь выбрать один из этих амулетов, Токсишка.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОберег зыбучих ПесковКолье зыбучих песковПодвеска зыбучих песковАмулет зыбучих песков\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][8792] = {title = "Орде нужна твоя помощь!", objective = "Поговорите с вождем Горчуком на аллее Духов Оргриммара.", description = "Приветствую, я рада, что ты <решил/решила> поговорить со мной. Если мы хотим достойно подготовиться к ан'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не следует оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, <имя>!\n\nПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, <класс>? Примешь участие в этом жизненно важном деле?", progress = nil, completion = "Тром'ка, |3-6(Воин)! Приятно видеть, что многие вроде тебя, Сокрушунг, решили помочь Орде в предстоящей ан'киражской заварухе. Она будет грандиозной, не сомневайся. Пока наши усилия вселяют надежду, что мы одолеем силитидов и их злобных правителей, которые засели в Ан'Кираже. \n\nРаз уж ты принял решение, можешь помогать запасать любые материалы, которые тебе будет проще раздобыть.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8793] = {title = "Орде нужна твоя помощь!", objective = "Поговорите с вождем Горчуком на аллее Духов Оргриммара.", description = "Приветствую! Хорошо, что ты <решил/решила> поговорить со мной. Если мы хотим достойно подготовиться к ан'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не следует оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, <имя>!\n\nПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, <класс>? Примешь участие в этом жизненно важном деле?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8794] = {title = "Орде нужна твоя помощь!", objective = "Поговорите с вождем Горчуком на аллее Духов Оргриммара.", description = "Приветствую! Хорошо, что ты <решил/решила> поговорить со мной. Если мы хотим достойно подготовиться к ан'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не следует оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, <имя>!\n\nПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, <класс>? Примешь участие в этом жизненно важном деле?", progress = nil, completion = "Тром'ка, |3-6(Воин)! Приятно видеть, что многие вроде тебя, Мард, решили помочь Орде в предстоящей ан'киражской заварухе. Она будет грандиозной, не сомневайся. Пока наши усилия вселяют надежду, что мы одолеем силитидов и их злобных правителей, которые засели в Ан'Кираже. \n\nРаз уж ты принял решение, можешь помогать запасать любые материалы, которые тебе будет проще раздобыть.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8795] = {title = "Альянсу нужна твоя помощь!", objective = "Поговорите с фельдмаршалом Снежной Лавиной, который находится в Палатах войны Стальгорна.", description = "Приветствую. Хорошо, что ты <решил/решила> поговорить со мной. В подготовке к войне в Ан'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый! Уже назначены ответственные за сбор разнообразных материалов, но без помощи простых граждан им не справиться, <имя>!\n\nЕсли хочешь поддержать Альянс, обратись с фельдмаршалу Снежной Лавине, который отвечает за сбор ресурсов. Что скажешь, <класс>? Примешь ли ты участие в этом жизненно важном деле?", progress = nil, completion = "Приветствую тебя и желаю удачи, юноша! Как хорошо, что в Альянсе есть люди вроде тебя, Димиллион. Мы будем рады любой помощи в подготовке надвигающейся грандиозной войны в Ан'Кираже. Если мы объединим наши усилия, то наверняка сможем выковырять мерзких силитидов из их укрытия. \n\nНе стесняйся предложить свою помощь лицам, ответственным за сбор материалов, которые тебе легче раздобыть.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8796] = {title = "Альянсу нужна твоя помощь!", objective = "Поговорите с фельдмаршалом Снежной Лавиной, который находится в Палатах войны Стальгорна.", description = "Приветствую. Хорошо, что ты <решил/решила> поговорить со мной. В подготовке к войне в Ан'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый! Уже назначены ответственные за сбор разнообразных материалов, но без помощи простых граждан им не справиться, <имя>!\n\nЕсли хочешь поддержать Альянс, обратись к фельдмаршалу Снегопаду, который отвечает за сбор ресурсов. Что скажешь, <класс>? Примешь ли ты участие в этом жизненно важном деле?", progress = nil, completion = "Приветствую тебя и желаю удачи, юноша! Как хорошо, что в Альянсе есть люди вроде тебя, Оксиморон. Мы будем рады любой помощи в подготовке надвигающейся грандиозной войны в Ан'Кираже. Если мы объединим наши усилия, то наверняка сможем выковырять мерзких силитидов из их укрытия. \n\nНе стесняйся предложить свою помощь лицам, ответственным за сбор материалов, которые тебе легче раздобыть.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8797] = {title = "Альянсу нужна твоя помощь!", objective = "Поговорите с фельдмаршалом Снежной Лавиной, который находится в Палатах войны Стальгорна.", description = "Приветствую. Хорошо, что ты <решил/решила> поговорить со мной. В подготовке к войне в Ан'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый! Уже назначены ответственные за сбор разнообразных материалов, но без помощи простых граждан им не справиться, <имя>!\n\nЕсли хочешь поддержать Альянс, обратись к фельдмаршалу Снегопаду, который отвечает за сбор ресурсов. Что скажешь, <класс>? Примешь ли ты участие в этом жизненно важном деле?", progress = nil, completion = "Приветствую тебя и желаю удачи, юноша! Как хорошо, что в Альянсе есть люди вроде тебя, Лорегон. Мы будем рады любой помощи в подготовке надвигающейся грандиозной войны в Ан'Кираже. Если мы объединим наши усилия, то наверняка сможем выковырять мерзких силитидов из их укрытия. \n\nНе стесняйся предложить свою помощь лицам, ответственным за сбор материалов, которые тебе легче раздобыть.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8798] = {title = "Твой собственный Йети", objective = "Ух ты! Да ты оказывается, тоже инженер! Раз ты помог мне разыграть моих друзей, я в ответ научу тебя, как создать своего собственного механического йети, чтобы ты смог продолжить забаву и напугать кого и когда захочешь. Главное, чтобы тебе удалось достать все необходимые компоненты.\n\nНу так что, Томпсон? Хочешь научиться делать механических йети?", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][8799] = {title = "Герой дня", objective = "Принесите 1 порцию глубокоскальной соли и 5 золотых монет к сушилке для остролиста, чтобы получить 5 сушеных остролистов.", description = "Слушай... Вообще-то тебе об этом знать не полагается, но, раз уж ты герой дня и все такое…\n\nВ это время года повсюду полно свежего остролиста, но он быстро вянет. У нас есть машинка, которая заготовляет остролист таким образом, что он не портится! Знаешь, почем его можно продать летом?\n\nЯ разрешу тебе воспользоваться сушилкой, но только если ты мастер-кулинар. От тебя потребуется некоторое количество глубокоскальной соли и два-три... ну, скажем, пять золотых. И ты получишь славную партию остролиста, которую можно хранить сколько угодно.", progress = "На первый взгляд сушилка для остролиста напоминает нечто вроде перегонного куба, но, если вглядеться повнимательнее, становится видно, что в основную конструкцию внесены типично гоблинские изменения. Тем не менее вы – достаточно опытный кулинар, чтобы разобраться, как работает эта машина.\n\nСвежий остролист в машину уже загружен – нужно только добавить глубокоскальной соли и пять золотых, и машинка заработает.", completion = "Машинка издала негромкий рокот, выпустила облачко пара – и работа пошла! Вскоре она остановилась, выпустив еще одно облачко пара. Открывается дверка – и вот вам сушеный остролист!", rewards = "Вы получите:\n\nСушеный остролист"}
MultiLanguageQuestData['ru'][8800] = {title = "Броня Кенария", objective = "Поговорите с Варгусом в крепости Кенария в Силитусе.", description = "Выполнив все задания, обратись к Варгусу, кузнецу. Покажи ему все заработанные знаки, и получишь награду, в зависимости от твоей преданности нашему делу.", progress = nil, completion = "Тебя прислал Калдон? Хорошо, посмотрим, чем я могу тебе помочь.", rewards = nil}
MultiLanguageQuestData['ru'][8801] = {title = "Наследие К'Туна", objective = "Принесите Глаз К'Туна Келестрасу в Храм Ан'Киража.", description = "Стены Ан'Киража содрогаются. Сила зла, более древняя, чем сам этот мир, уничтожена.\n\nПри одном взгляде на лежащие перед вами мерзкие останки стынет сердце. Даже после смерти К'Тун распространяет вокруг себя ауру зла.\n\nВам удалось совершить невозможное.\n\nВы извлекаете глаз и осторожно укладываете его в сумку.\n\nНужно доставить глаз К'Туна в соседнюю залу и отдать драконам.", progress = "*Келестрас преклоняет перед вами колени*\n\nГоспожа Киберушко, вы разбили наши оковы.", completion = "Теперь мы можем покинуть это место, Госпожа Киберушко. Великое зло полностью уничтожено, и ваши странствия, которые войдут в легенды, близятся к своему завершению.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][8802] = {title = "Спаситель Калимдора", objective = "Принесите глаз К'Туна Анахроносу в Пещеры Времени.", description = "Пришла пора вернуться в Пещеры Времени, <господин/госпожа> <имя>. Анахронос ожидает тебя. Отдай ему глаз К'Туна – не сомневаюсь, он непременно захочет поместить его в коллекцию своего хозяина.", progress = "Госпожа Киберушко! Все закончилось...", completion = "Повелитель оставил это для вас, защитник. В тайнике безвременья хранятся бесценные артифакты. Можете выбрать, что пожелаете.", rewards = "Плащ падшего богаВам дадут возможность выбрать одну из следующих наград:\n\nКольцо падшего богаАмулет падшего бога\n\nВы также получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8803] = {title = "Подарок в разноцветной упаковке", objective = "Надпись на подарке гласит:\n\nДорогому Надей.\n\nНадеюсь, это поможет тебе нести мир и радость зимних дней всему Азероту.\n\nТвой Дедушка Зима.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПодарок в разноцветной упаковке"}
MultiLanguageQuestData['ru'][8804] = {title = "Неприкосновенный запас", objective = "Принесите 4 сферы воды, 4 мощных противоядия и 4 копченые пустынные клецки Каландрате в таверну в крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу I.", description = "В крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих наборов для выживания в пустыне и отнеси их Каландрате в крепость Кенария.", progress = "Что ты мне принесла, Аирил?", completion = "Отлично! Нам очень нужны эти материалы. Спасибо.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8805] = {title = "Сапоги для стражей", objective = "Принесите 3 пары изысканных мифриловых сапог Вишу Коцусу, капитану стражи крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу II.", description = "Верховому подразделению крепости Кенария не хватает изысканных мифриловых сапог. Принеси нам очередную партию и передай их капитану Вишу Коцусу из крепости Кенария.", progress = "Что ты мне принес, Горрат?", completion = "Отлично! Как раз то, что нужно. Спасибо.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8806] = {title = "Шлифовальные камни", objective = "Принесите 10 массивных шлифовальных камней, 10 твердых шлифовальных камней и 10 тяжелых точильных камней Вишу Коцусу, капитану стражи в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу III.", description = "У стражи крепости Кенария на исходе шлифовальные камни. Добудь их и отнеси капитану Вишу Коцусу в крепость Кенария.", progress = "Что ты мне принесла, Русводка?", completion = "Отлично! Нам очень нужны эти материалы. Спасибо.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8807] = {title = "Материалы для гадания", objective = "Принесите 1 большой сияющий осколок, 1 большой светозарный осколок и 1 огромный изумруд геологу Ехидной в крепость Кенария в Силитусе. Также принесите тыловое задание V.", description = "Исследования геолога Ехидной имели огромное значение для нашей кампании в Силитусе. Недавно она запросила материалы для своего исследования.\n\nПожалуйста, собери все необходимое и отнеси ей. Пусть она продолжает работу.", progress = "Что ты мне принесла, Надэжда?", completion = "О да... Ты мне очень помогла! Достать эти материалы в пустыне невероятно сложно. Спасибо, Надэжда.", rewards = "Вы получите:\n\nКенарийский знак тыловикаДополнительное задание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8808] = {title = "Поставки формы", objective = "Принесите 1 кусок луноткани, 2 рулона рунической ткани и 1 железношелковую паутину призывательнице ветров Гордый Рог в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу VIII.", description = "У нас такой приток добровольцев, что не хватает формы. Принеси материалы для пошива формы и отдай их призывательнице ветров Гордый Рог.", progress = "Что ты мне принесла, Надэжда?", completion = "А, да, нам их очень не хватало. Спасибо за добрую службу, Надэжда.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8809] = {title = "Необычные материалы", objective = "Принесите Варгусу из крепости Кенария в Силитусе 2 зачарованных ториевых слитка и 2 куска зачарованной кожи. Кроме того, принесите тыловое задание IX.", description = "Варгус, кузнец крепости Кенария, запросил партию зачарованных материалов для создания мощного оружия для наших солдат. Добудь все необходимое и отнеси их Варгусу в крепость Кенария, чтобы он снабдил войска всем необходимым.", progress = "Что ты мне принесла, Аирил?", completion = "Да-да. Превосходные материалы. Спасибо, Аирил.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8810] = {title = "Запас бинтов", objective = "Принесите 30 плотных бинтов из рунической ткани, 30 плотных шелковых бинтов и 30 плотных бинтов из магической ткани призывательнице ветров Гордый Рог в крепость Кенария в Силитусе. Кроме того сдайте тыловую задачу X.", description = "В последнее время мы понесли серьезные потери, и запас бинтов стремительно иссякает. Добудь нам первоклассные перевязочные материалы и отнеси их призывательнице ветров Гордый Рог в крепость Кенария.", progress = "Что ты мне принесла, Надэжда?", completion = "Ты как раз вовремя. Принесенные тобой перевязочные материалы спасут немало жизней. Мы благодарны тебе за труды. Вот твое следующее задание.", rewards = "Вы получите:\n\nКенарийский знак тыловикаДополнительное задание по материально-техническому снабжению"}
MultiLanguageQuestData['ru'][8811] = {title = "Один рекомендательный жетон", objective = "Один рекомендательный жетон позволяет немного улучшить отношение жителей Дарнасса к сдавшему его искателю приключений.\n\nИмей в виду, что лучше сдавать разом десять жетонов, это гораздо выгоднее. У тех же, кто заработал не так много жетонов, мы принимаем их по одному.\n\nНу вот, я тебя предупредил, а теперь готов помочь, если ты все же хочешь сдать мне один жетон.", description = nil, progress = "Один рекомендательный жетон позволяет немного улучшить отношение жителей Дарнасса к сдавшему его искателю приключений.\n\nИмей в виду, что лучше сдавать разом десять жетонов, это гораздо выгоднее. У тех же, кто заработал не так много жетонов, мы принимаем их по одному.\n\nНу вот, я тебя предупредил, а теперь готов помочь, если ты все же хочешь сдать мне один жетон.", completion = "Отлично – твои подвиги записаны, и тебе воздастся по заслугам. Продолжай в том же духе, |3-6(Жрец)!\n\nЕсли ты хочешь сдать еще несколько жетонов, я с радостью их приму.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][8812] = {title = "Один рекомендательный жетон", objective = "Один рекомендательный жетон позволяет немного улучшить отношение изгнанников Гномрегана к сдавшему его искателю приключений.\n\nИмей в виду, что лучше сдавать разом десять жетонов, это гораздо выгоднее. У тех же, кто заработал не так много жетонов, мы принимаем их по одному.\n\nНу вот, я тебя предупредил, а теперь готов помочь, если ты все же хочешь сдать мне один жетон.", description = nil, progress = "Один рекомендательный жетон позволяет немного улучшить отношение изгнанников Гномрегана к сдавшему его искателю приключений.\n\nИмей в виду, что лучше сдавать разом десять жетонов, это гораздо выгоднее. У тех же, кто заработал не так много жетонов, мы принимаем их по одному.\n\nНу вот, я тебя предупредил, а теперь готов помочь, если ты все же хочешь сдать мне один жетон.", completion = "Отлично – твои подвиги записаны, и тебе воздастся по заслугам. Продолжай в том же духе, |3-6(Друид)!\n\nЕсли ты хочешь сдать еще несколько жетонов, я с радостью их приму.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
