MultiLanguageQuestData['ru'][8834] = {title = "Один рекомендательный жетон", objective = "Один рекомендательный жетон позволяет немного улучшить отношение жителей Стальгорна к сдавшему его искателю приключений.\n\nИмей в виду, что лучше сдавать разом десять жетонов, это гораздо выгоднее. У тех же, кто заработал не так много жетонов, мы принимаем их по одному.\n\nНу вот, я тебя предупредил, а теперь готов помочь, если ты все же хочешь сдать мне один жетон.", description = nil, progress = "Один рекомендательный жетон позволяет немного улучшить отношение жителей Стальгорна к сдавшему его искателю приключений.\n\nИмей в виду, что лучше сдавать разом десять жетонов, это гораздо выгоднее. У тех же, кто заработал не так много жетонов, мы принимаем их по одному.\n\nНу вот, я тебя предупредил, а теперь готов помочь, если ты все же хочешь сдать мне один жетон.", completion = "Отлично – твои подвиги записаны, и тебе воздастся по заслугам. Продолжай в том же духе, |3-6(Паладин)!\n\nЕсли ты хочешь сдать еще несколько жетонов, я с радостью их приму.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
