MultiLanguageQuestData['ru'][9043] = {title = "Мундир искупления", objective = "Командор Элигор Вестник Рассвета из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать мундир искупления, если вы принесете ему следующее: 1 испоганенный мундир, 25 обломков доспехов, 4 слитка арканита и 3 обработанных грубых шкуры.", description = "Убивая лордов Наксрамаса, ты найдешь остатки доспехов наших павших героев. Принеси их мне. Заодно захвати обломки лат, поврежденных в бою, и материалы, способные вдохнуть новую жизнь в оскверненные доспехи. Тогда я сделаю тебе очень неплохую броню.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМундир искупления"}
