MultiLanguageQuestData['ru'][9050] = {title = "Накулачники Искупления", objective = "Командор Элигор Вестник Рассвета из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать накулачники искупления, если вы принесете ему следующее: 1 испоганенные накулачники, 6 обломков доспехов, 1 слиток арканита и 2 обработанных грубых шкуры.", description = "Убивая лордов Наксрамаса, ты найдешь остатки доспехов наших павших героев. Принеси их мне. Заодно захвати обломки лат, поврежденных в бою, и материалы, способные вдохнуть новую жизнь в оскверненные доспехи. Тогда я сделаю тебе очень неплохую броню.", progress = "Пока ты не принесешь мне все материалы, я не смогу начать работу.", completion = "Очень выгодное занятие, делать эти запястья. Но не забывай, если постоянно мокнуть в них под дождем, они могут заржаветь!", rewards = "Вы получите:\n\nНарукавники искупления"}
MultiLanguageQuestData['ru'][9051] = {title = "Испытание яда", objective = "Уколите дьявозавра шипом дьявозавра. По выполнении задания вернитесь к землепроходцу Торве.", description = "Яд, который ты <помог/помогла> мне создать, нужен мне для особых целей. Огромные дьявозавры, обитающие в кратере, мешают мне охотиться и даже угрожают моей жизни. Даже если бы у меня хватило сил, чтобы убить дьявозавра, это было бы бесполезно – на место убитого немедленно придет другой. \n\nВозьми эту отравленную колючку и загони ее глубоко в шкуру дьявозавра. Яд усмирит зверя, хоть я и не знаю, насколько быстро...Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9052] = {title = "Яд кровоцвета", objective = "Соберите 8 кровошляпочников и 8 жал Гориши и вернитесь к Землепроходцу Торве в Кратер Ун'Горо.", description = "Мне нужна твоя помощь в создании яда, с помощью которого я собираюсь усмирять огромных чудовищ, обитающих в кратере. Не бойся, яд не смертелен. Кроме того, острые глаза <класс> будут большим подспорьем при сборе ингредиентов. \n\nГрибы-кровошляпочники растут под побегами кровоцвета - их в кратере полным полно. Жала Гориши - это жала насекомых, которые водятся в районе Скользкого оврага в южной части кратера.", progress = "Тебе удалось собрать ингредиенты?", completion = "Наконец-то! \n\nТеперь я смешаю эти ингредиенты с почвой Ун'Горо и сварю яд...", rewards = "Вы получите:\n\nСильнейшее лечебное зелье"}
MultiLanguageQuestData['ru'][9053] = {title = "Лучший ингредиент", objective = "Возьмите гнилую лозу у стража на дне затонувшего храма и вернитесь к Землепроходцу Торве.", description = "Как я и опасался – яд слишком слаб для такого большого зверя. \n\nЧтобы создать более мощный яд, мне потребуются лучшие ингредиенты. Отправляйся на дно храма Атал'Хаккар, раскрой секреты алтаря и заполучи от тамошнего стража гнилую лозу. Храм опасен, поэтому не ходи <один/одна>. \n\nВозвращайся ко мне, когда закончишь задание.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Облачение лесаСедая шкураЖезл лунной тениПосох лунной тениОблачение чащиСерая кожаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9054] = {title = "Мундир расхитителя гробниц", objective = "Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать мундир расхитителя гробниц, если вы принесете ему 1 испоганенный мундир, 25 обрывков кольчуги, 4 слитка арканита и 3 обработанных грубых шкуры.", description = "Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.\n\nПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!", progress = "Ты все необходимое принесла?", completion = "Пусть тебя боятся, Токсишка!", rewards = "Вы получите:\n\nМундир Расхитителя гробниц"}
MultiLanguageQuestData['ru'][9055] = {title = "Набедренники расхитителя гробниц", objective = "Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать набедренники расхитителя гробниц, если вы принесете ему 1 испоганенные набедренники, 20 обрывков кольчуги, 3 слитка арканита и 5 обработанных грубых шкур.", description = "Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.\n\nПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!", progress = "Ты все необходимое принес?", completion = "Чем больше частей этой брони ты соберешь, тем сильнее изменишься. У тебя появится желание убивать. Может быть, даже жажда крови.\n\nСкажем так, я не готов взять на себя ответственность за то, что ты можешь натворить...", rewards = "Вы получите:\n\nНабедренники Расхитителя гробниц"}
MultiLanguageQuestData['ru'][9056] = {title = "Головной убор расхитителя гробниц", objective = "Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать головной убор расхитителя гробниц, если вы принесете ему 1 испоганенный головной убор, 15 обрывков кольчуги, 4 слитка арканита и 2 кристалла-источника.", description = "Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.\n\nПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!", progress = "Ты все необходимое принес?", completion = "Тебя уже можно испугаться в темноте!", rewards = "Вы получите:\n\nГоловной убор Расхитителя гробниц"}
MultiLanguageQuestData['ru'][9057] = {title = "Наплеч расхитителя гробниц", objective = "Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать наплеч расхитителя гробниц, если вы принесете ему 1 испоганенный наплеч, 12 обрывков кольчуги, 2 слитка арканита и 3 обработанных грубых шкуры.", description = "Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.\n\nПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!", progress = "Ты все необходимое принес?", completion = "Я постарался сделать бармы побольше, позаметнее. Поверь мне, они тебе понравятся…", rewards = "Вы получите:\n\nНаплеч Расхитителя гробниц"}
MultiLanguageQuestData['ru'][9058] = {title = "Сапоги расхитителя гробниц", objective = "Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать сапоги расхитителя гробниц, если вы принесете ему 1 испоганенные сапоги, 12 обрывков кольчуги, 1 слиток арканита и 3 кристалла-источника.", description = "Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.\n\nПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!", progress = "Ты все необходимое принесла?", completion = "Сапоги готовы, Токсишка! Носи их с удовольствием.", rewards = "Вы получите:\n\nСапоги Расхитителя гробниц"}
MultiLanguageQuestData['ru'][9059] = {title = "Боевые рукавицы Расхитителя гробниц", objective = "Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать боевые рукавицы расхитителя гробниц, если вы принесете ему 1 испоганенные боевые рукавицы, 8 обрывков кольчуги, 1 слиток арканита и 5 обработанных грубых шкур.", description = "Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.\n\nПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!", progress = "Ты все необходимое принес?", completion = "Да передастся тебе ярость и сила некрорахнида.", rewards = "Вы получите:\n\nБоевые рукавицы Расхитителя гробниц"}
MultiLanguageQuestData['ru'][9060] = {title = "Ремень расхитителя гробниц", objective = "Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов сделать ремень расхитителя гробниц, если вы принесете ему 1 испоганенный ремень, 8 обрывков кольчуги, 1 слиток арканита и 3 кристалла-источника.", description = "Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.\n\nПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!", progress = "Ты все необходимое принесла?", completion = "Такой ремень достоен королей! А получишь ее ты, Токсишка.", rewards = "Вы получите:\n\nРемень Расхитителя гробниц"}
MultiLanguageQuestData['ru'][9061] = {title = "Накулачники расхитителя гробниц", objective = "Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать накулачники расхитителя гробниц, если вы принесете ему 1 испоганенные накулачники, 6 обрывков кольчуги, 1 слиток арканита и 2 обработанных грубых шкуры.", description = "Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.\n\nПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!", progress = "Ты все необходимое принесла?", completion = "Накулачники готовы. Наслаждайся!", rewards = "Вы получите:\n\nНакулачники Расхитителя гробниц"}
MultiLanguageQuestData['ru'][9062] = {title = "Промокшие страницы", objective = "Отыщите в реке под мостом гримуар стихий Антеола по просьбе ученика Меледора.", description = "Да уж, завидев кого-то, с кем им не справиться, проклятые Презренные разбегаются быстрее зайцев! Ладно, сейчас не о том речь. Нужно отыскать гримуар стихий моего наставника!\n\nЯ точно видел, как один из этих трусов швырнул его в реку, но вот где он теперь? Может, ты поможешь его отыскать? Я в долгу не останусь!", progress = "Что, не нашелся? Ну, ищи дальше! Это очень важная книга, |3-6(Паладин)!", completion = "Гримуар промок насквозь! Что же делать? Инструктор Антеол будет очень зол!\n\nСлушай, вот тебе деньги! И у меня есть идея.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9063] = {title = "Землепроходец Торва", objective = "Поговорите с Землепроходцем Торвой в Кратере Ун'Горо.", description = "Охотнику по имени Землепроходец Торва понадобилась помощь друида. Он сказал, что лишь у нас есть нужные навыки и должное уважение к природе.\n\nОт Кратера Ун'Горо к пустыне Танарис ведет дорога. Торва стоит у самого входа в кратер.", progress = nil, completion = "Ради встречи со мной тебе пришлось проделать долгий путь, |3-6(Друид). Ты как раз вовремя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9064] = {title = "Взять вину на себя", objective = "Принесите гримуар стихий Антеола инструктору Антеолу у пруда Тихого Шелеста в лесах Вечной Песни.", description = "Ох, то-то Антеол разъярится, как узнает, что его книжка испорчена! Слушай, есть предложение. Не бойся, ты внакладе не останешься.\n\nОтнеси ему эту книжку. О том, что произошло, ни слова. А если спросит, как это вышло, просто скажи, что ты <уронил/уронила> книжку в лужу. Тебе он не наставник, так что тебе за это ничего не будет.\n\nАнтеол читает свои лекции у пруда Тихого Шелеста, к юго-востоку от Луносвета. Ты ведь это сделаешь, ладно? Я в долгу не останусь!", progress = "С какой целью ты прерываешь мою лекцию, |3-6(Разбойник)?", completion = "Так ты говоришь, что эти два остолопа сулили тебе взятку за то, чтобы обмануть меня? Очень хорошо, что ты ко мне пришел, Аукциониус!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9065] = {title = "Задание Чоу (123)аа", objective = "Убедитесь, что вы уничтожили эту башню!", description = "Эй, ты! Убей пару кобольдов-вредителей.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9066] = {title = "Суровый урок", objective = "Накажите карающим жезлом Антеола двух его студентов, ученика Ралена и ученика Меледора. Верните жезл Антеолу у пруда Тихого Шелеста в лесах Вечной Песни.", description = "Надеюсь, что сегодня ты, <имя>, получишь ценный урок. Никогда не поручай кому-то другому лгать вместо тебя.\n\nА теперь возвращайся к моим бестолковым студентам и вразуми их с помощью этого жезла. Моя магия подсказывает мне, что ты найдешь их на дороге к западу отсюда, по ту сторону Тропы Мертвых.\n\nКогда выполнишь это, возвращайся ко мне. Я дам тебе небольшую награду за труды.", progress = "Ну что, Пригопыпа, выполнил ли ты то, о чем я просил?", completion = "Превосходно, Пригопыпа! Не волнуйся, они не останутся в этом облике навечно. Однако из числа моих учеников они исключены до тех пор, пока не докажут, что достойны у меня учиться.", rewards = "Вы получите:\n\nМешочек магистраCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9067] = {title = "Бесконечный праздник", objective = "Добудьте бутылку \"Благословения Солнца Гранд Резерв\", закуску из прыголапа и связку фейерверков и принесите все это лорду Салтерилу на виллу Салтерила, что в лесах Вечной Песни.", description = "Обожаю вечеринки! Кель'Талас будто создан для них.\n\nНо сейчас у меня возникла проблема, и мне нужна твоя помощь. Собери побольше припасов к праздничному столу.\n\nПринеси мне от винодела Благословение Солнца из таверны \"Луносвет\" бутылку его лучшего вина. У Залены Юной Зари в обители Странников возьми побольше восхитительной закуски из прыголапа. Еще, кстати, забери заказанные мной фейерверки у Халиса Рассветного Странника в деревне Легкий Ветерок!\n\nПоторопись!", progress = "Это тебя я только что послал за припасами для праздника? Или это был не ты? Ну, в конце концов, не могу же я всех в лицо помнить! У меня ведь столько... интересных знакомых!\n\nТак чего тебе надо?", completion = "О, а ты, оказывается, весьма энергичный юноша!\n\nДа, это то, что надо. Ты, несомненно, заслуживаешь награды. И, наверное, что-нибудь сверх обещанной платы...\n\nДа-да, совсем забыл: вот тебе приглашение на вечеринку! Только в следующий раз, как будешь у меня, |3-6(Паладин), прошу, переоденься во что-нибудь... более праздничное.", rewards = "Вы получите:\n\nПриглашение на вечеринку на виллу СалтерилаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9068] = {title = "Мундир Землекрушителя", objective = "Римблат Землекрушитель из часовни Последней Надежды в Восточных Чумных землях готов создать мундир землекрушителя, если вы принесете ему 1 испоганенный мундир, 25 обрывков кольчуги, 4 слитка арканита и 3 обработанных грубых шкуры.", description = "Прошу тебя, окажи мне честь и верни броню тех, кто пал, защищая эти земли.\n\nЗлые силы несомненно испоганили эти доспехи и используют их для собственных гнусных целей, однако их можно укрепить при помощи обрывков кольчуг и вновь пойти в них на войну.\n\nПринеси мне остатки брони павших и материалы для их очищения, и получишь взамен доспехи Землекрушителя.\n\nСтупай, поищи в Наксрамасе.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМундир Землекрушителя"}
