MultiLanguageQuestData['ru'][9076] = {title = "Главарь Презренных", objective = "Принесите голову Альдарона Велендрису Белому Рассвету у причала Солнечного Паруса в лесах Вечной Песни.", description = "Презренные настолько упиваются своей нечистой магией, что, наверное, даже не осознали, что нам удалось вернуть себе большую часть оружия. Однако мы не можем рассчитывать, что они будут долго пребывать в растерянности. Сейчас самое время избавиться от их предводителя, Альдарона. Его видели на верхнем этаже здания у причала. Принеси мне его голову, и я вознагражу тебя по заслугам.", progress = "Ну так что, удалось тебе добыть его голову или нет? У меня нет лишнего времени, Тсой!", completion = "Ага, тебе все-таки удалось его одолеть! Ну, конечно, вряд ли бы ты его поймал, если бы мои воины его не загнали...\n\nДа шучу я, шучу! Спасибо, |3-6(Охотник). Ты еще завоюешь себе славу.", rewards = "Наручи Солнечного ПарусаНаручники докера Долгого БерегаШелковое нарукавьеВы получите:\n\nCurrency Token Test Token 4"}
