MultiLanguageQuestData['ru'][9085] = {title = "Тени Рока", objective = "Идите к кругу призыва и убейте Тень Рока, затем возвращайтесь к командиру Томасу Элерану в Часовню Последней Надежды в Восточные Чумные земли.", description = "После разрушения защиты кругов призыва Плети, которые появляются в тех местах, где происходит нападение, тебе придется сразиться с послушниками, которые охраняют эти круги.\n\nЧестно говоря, это не живые существа, а тени, одни из самых устрашающих созданий Короля-лича. Их можно обнаружить с помощью некротических рун, которые они носят при себе, а затем уничтожить посредством магии или силой оружия.", progress = "Повезло ли тебе, Ксол?", completion = "Превосходная работа, Крев. Теперь, когда тени уничтожены, у нас остается надежда одолеть Короля-лича.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОсвященное точилоБлагословенное волшебное масло"}
MultiLanguageQuestData['ru'][9086] = {title = "Мундир сновидца", objective = "Райн из Часовни Последней Надежды в Восточных Чумных землях готова создать мундир сновидца, если вы принесете ей следующее: 1 испоганенный мундир, 25 обрывков кожи, 6 обработанных грубых шкур и 2 кристалла-источника.", description = "В последней войне пало немало героев, да и сегодня все больше славных бойцов погибает под натиском Плети. С тел погибших срывают доспехи, уносят в Наксрамас и используют для неведомых, но несомненно гнусных, целей.\n\nВерни испоганенные доспехи и их обрывки, принеси все остальные материалы, и я сделаю для тебя броню сновидца.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМундир сновидца"}
