MultiLanguageQuestData['ru'][9111] = {title = "Одеяние веры", objective = "Отец Иниго Монтой из часовни Последней Надежды готов создать одеяние веры, если вы принесете ему 1 испоганенное одеяние, 25 обрывков ткани, 4 куска луноткани и 2 кристалла-источника.", description = "*Отец Монтой делает какие-то странные пассы.*\n\nБлагослови тебя Свет, дитя мое, удалось ли тебе отыскать одежды павших? Бедные воины, лишившиеся жизни на поле битвы – у них отняли все, даже достоинство.\n\nПринеси мне оскверненные доспехи павших и все реагенты для их очищения, и ты познаешь, что такое истинная вера.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nОдеяние веры"}
