MultiLanguageQuestData['ru'][9185] = {title = "Задание мастера: накладки из грубой кожи", objective = "Доставьте 25 комплектов грубой брони и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.", description = "Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.\n\nЗаказ-наряд LW-448:\n\n25 комплектов грубой брони.\n\nВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.\n\nКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.\n\nПодпись: Командир Метц, Серебряный Рассвет", progress = "Явился с заказом, |3-6(Друид)?", completion = "Грубая броня – вещь весьма функциональная, Лорегон. Это не просто броня. Например, вот эту деталь можно использовать как чехол для чайника.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗначок Алого орденаЗначок Серебряного Рассвета"}
