MultiLanguageQuestData['ru'][9225] = {title = "Легендарное боевое снаряжение – Чтимый Рассветом", objective = "За 45 знаков Рассвета и 45 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.", description = "Приветствую тебя, <брат/сестра>. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?\n\nНо помни, даже если тебя почитают в Серебряном Рассвете, эпические вещи будут стоить недешево!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "ОчистительНаручи надеждыНаручи ухищренияВам дадут возможность выбрать одну из следующих наград:\n\nАмулет РассветаРассветный медальонТалисман Господства"}
MultiLanguageQuestData['ru'][9226] = {title = "Превосходное боевое снаряжениее – Чтимый Рассветом", objective = "За 7 значков Серебряного Рассвета и 7 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.", description = "Приветствую тебя, <брат/сестра>. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?\n\nсякий, кого почитают в Серебряном Рассвете, получает вполне ощутимые скидки на приобретение товаров! Скорее же воспользуйся своим преимуществом!", progress = "Выбирай с умом. Выбранный предмет обмену и возврату не подлежит.", completion = "Всего хорошего, Огневар. С тобой приятно иметь дело.", rewards = "Последняя надежда ВеримондыОсвященный шлемПоножи Чумного ОхотникаВам дадут возможность выбрать одну из следующих наград:\n\nКольцо благочестияКольцо решимостиСумка с припасами"}
