MultiLanguageQuestData['ru'][9244] = {title = "Наручи из ледяной чешуи", objective = "Принесите 4 морозные руны, 16 кусков толстой чешуи скорпида, 5 сущностей воды, 3 обработанных грубых шкуры и 200 золотых ремесленнику Вильгельму в часовню Последней Надежды в Восточные Чумные земли.", description = "Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать наручи из ледяной чешуи. От тебя требуются лишь материалы и скромная плата за работу.", progress = "Ты достала материалы?", completion = "Получай свой заказ, Токсишка! Все как ты просила.", rewards = "Вы получите:\n\nНаручи из ледяной чешуи"}
MultiLanguageQuestData['ru'][9245] = {title = "Рукавицы из ледяной чешуи", objective = "Принесите 5 морозных рун, 16 кусков толстой чешуи скорпида, 5 сущностей воды, 3 обработанных грубых шкуры и 200 золотых ремесленнику Вильгельму в часовню Последней Надежды в Восточные Чумные земли.", description = "Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать рукавицы из ледяной чешуи. От тебя требуются лишь материалы и скромная плата за работу.", progress = "Ты достала материалы?", completion = "Получай свой заказ, Токсишка! Все как ты просила.", rewards = "Вы получите:\n\nРукавицы из ледяной чешуи"}
MultiLanguageQuestData['ru'][9246] = {title = "Кираса из ледяной чешуи", objective = "Принесите 8 морозных рун, 24 куска толстой чешуи скорпида, 7 сущностей воды, 5 обработанных грубых шкур и 300 золотых ремесленнику Вильгельму в часовню Последней Надежды в Восточные Чумные земли. Требуется превознесение в Серебряном Рассвете.", description = "Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать кирасу из ледяной чешуи. От тебя требуются лишь материалы и скромная плата за работу.", progress = "Ты достала материалы?", completion = "Получай свой заказ, Токсишка! Все как ты просила.", rewards = "Вы получите:\n\nКираса из ледяной чешуи"}
MultiLanguageQuestData['ru'][9247] = {title = "Зов Хранителя", objective = "Отнесите письмо хранителя свитков самому хранителю в Часовню Последней Надежды в Восточные Чумные земли.", description = "<имя>,\n\nВ прошлом тебе иногда приходилось браться за поручения в интересах Серебряного Рассвета, и всегда эти поручения оказывались выполнены в наилучшем виде. Ныне, в час великой нужды, мы вновь посылаем тебе зов.\n\nПожалуйста, <имя>, если ты желаешь вновь оказать нам помощь, явись к хранителю свитков в Часовню Последней Надежды, что в Восточных Чумных землях.", progress = "А, Мард, я рад видеть тебя.", completion = "Мы в долгу перед тобой, Мард, уже за то, что ты явился на наш призыв.Серебряный Рассвет надеется, что твой блистательный пример покажет всем, кто собрался здесь ради помощи нам, истинный путь к отражению угрозы со стороны Плети!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОсвященное точилоБлагословенное волшебное масло\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9248] = {title = "Скромный подарок", objective = "Принесите 1 скипетр бездны Аурель Золотой Лист из крепости Кенария в Силитусе. Требуется уважение со стороны Круга Кенария.", description = "Ишну-ала, <раса>. Покажи мне доказательство кончины лорда Совета Бездны и получишь в награду предмет, который поможет тебе справиться с киражи.", progress = "Фэнду-дат-белоре? О, прости меня, Таквер, я не сразу тебя узнала. Ты принес мне скипетр?", completion = "Анде'торас-этиль. На моем родном языке это значит \"Да уменьшатся твои невзгоды\".\n\nПрими это кольцо и носи на здоровье!", rewards = "Вы получите:\n\nКольцо Кенария"}
MultiLanguageQuestData['ru'][9249] = {title = "40 купонов – пульт управления паровым танком", objective = "Налетай, торопись, выбирай себе приз! У кого есть купоны ярмарки Новолуния – подходите и обменяйте их на диковины волшебного свойства и исключительного качества! Ни орк, ни дворф не уйдет без призов!", description = nil, progress = "Налетай, торопись, выбирай себе приз! У кого есть купоны ярмарки Новолуния – подходите и обменяйте их на диковины волшебного свойства и исключительного качества! Ни орк, ни дворф не уйдет без призов!", completion = "Не зевай, забирай! Приз, достойный короля! Поздравляю с приобретением!\n\nЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!", rewards = nil}
MultiLanguageQuestData['ru'][9250] = {title = "Основа Атиеша", objective = "Найдите того, кто поможет отыскать недостающие части посоха и изгнать из него злого духа.", description = "Основа готова, и Атиеш собран почти полностью. Не хватает лишь набалдашника и основания. Да, и осталась небольшая проблемка – посох по-прежнему служит проводником зла Сарагаса в мир.\n\nНайди того, кто поможет тебе отыскать недостающие части, а заодно изгнать из посоха злого духа.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9251] = {title = "Атиеш, оскверненный посох", objective = "Анахронос из Пещер Времени, что в Танарисе, просит вас принести ему навершие и основание Атиеша.", description = "Ты удивляешься, почему до сих пор <жив/жива>? Ведь в твоих руках предмет, являющий собой средоточие зла. Ответ неочевиден, <имя>. Я делаю лишь то, что должно.\n\nКел'Тузад сидит на троне Наксрамаса и вынашивает коварные планы... Он ищет то, что у тебя в руках, а у него в руках то, что ищешь ты.\n\nЧто же до острия посоха, то когда дворф Бранн Бронзобород отправился в Ан'Кираж, оно было у него. Этого дворфа более нет в Ан'Кираже, но основание Атиеша все еще там.\n\nЕсли тебе удастся отыскать оставшиеся части посоха, принеси их мне.", progress = "Сейчас посоху опасно находиться в смертных руках.", completion = "В посохе заключено существо... Из другого мира.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9252] = {title = "Оборона деревни Легкий Ветерок", objective = "Убейте 4 гниющих мародеров и 4 темных призраков и вернитесь к следопыту Сарейн в деревню Легкий Ветерок, что в лесах Вечной Песни.", description = "Нападения Плети происходят все чаще, <имя>! Мы уже с трудом держим оборону - а подкрепления из Луносвета что-то не видно и не слышно. Помоги нам оборонять деревню: перебей часть нежити, что бродит по Тропе Мертвых!", progress = nil, completion = "Спасибо тебе большое, Пригопыпа. Работа у нас неблагодарная, но твоими стараниями она станет чуть-чуть полегче.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9253] = {title = "Хранитель рун Дериан", objective = "Поговорите с хранителем рун Дерианом в лесах Вечной Песни, близ границы с Призрачными землями.", description = "Ужесточение атак Плети заставляет меня предположить, что с одним из рунических камней, что стоят на границе с Призрачными землями, что-то неладно.\n\nМы использовали эти древние камни для защиты от нежити. Но большинство из них были уничтожены или пропали после нападения на Солнечный Колодец.\n\nСтупай по дороге на юг, в сторону Призрачных земель, и увидишь небольшую тропку, ведущую на запад. Там, у рунического камня, ты найдешь хранителя рун Дериана. Если что-то не в порядке, он об этом знает.", progress = nil, completion = "Должно быть, тебя прислал кто-то из деревни Легкий Ветерок? Я знал, что рано или поздно помощь непременно подоспеет.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9254] = {title = "Упрямая ученица", objective = "Поговорите с ученицей Мирведой в Восточном святилище в лесах Вечной Песни.", description = "Спасибо тебе за помощь, <имя>! Пока я буду все тут приводить в порядок, не окажешь ли мне услугу? Одна из моих бывших учениц предприняла весьма опасное исследование. Она отправилась в Восточное святилище, которое стоит посреди Тропы Мертвых.\n\nЯ опасаюсь за ее благополучие. Попробуй ее найти и убедить вернуться.", progress = nil, completion = "Очень приятно, что моя бывшая наставница обо мне не забывает. Жаль только, что она давно утратила веру в мой успех!\n\nНе пытайся уговорить меня вернуться к ней, не трать времени зря. Лучше помоги мне завершить исследование. Или уходи.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9255] = {title = "Исследовательские записи", objective = "Доставьте исследовательские записи магистру Ландре Рассветной Страннице в деревню Легкий Ветерок, что в лесах Вечной Песни.", description = "Конечно, итоги моих исследований удручающи, но все же отрицательный результат – тоже результат. Прошу тебя, отнеси эти записи магистру Ландре Рассветной Страннице в деревню Легкий Ветерок, к западу отсюда.", progress = "Вы что-то мне принесли?", completion = "Эти записи... шокируют. Если все это правда, то урон, нанесенный земле Тропы Мертвых, необратим!\n\nЯ немедленно сообщу об этом великому магистру! Тем больше причин нашему народу оставить этот мир и искать свою истинную судьбу в Запределье!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9256] = {title = "Деревня Легкий Ветерок", objective = "Поговорите со следопытом Деголиеном в деревне Легкий Ветерок в лесах Вечной Песни.", description = "У меня для тебя есть еще одно задание, <имя>. Cледопыт Деголиен послал гонца в деревню Легкий Ветерок, чтобы выяснить подробности насчет нападения Презренных на находящуюся поблизости верфь. Он просит прислать подкрепление, но мы пока не можем этого сделать. Отыщи его и окажи посильную помощь.\n\nВ деревню Легкий Ветерок можно попасть, если идти по дороге, которая ведет от площади Соколиных Крыльев на юг. Удачи, <имя>!", progress = nil, completion = "Спасибо, что пришел, Тсой. Все хуже, чем мы думали. Презренные захватили причал Солнечного Паруса!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9257] = {title = "Атиеш, большой посох Стража", objective = "Анахронос из Пещер Времени, что в Танарисе, просит вас отнести Атиеш, большой посох Стража, в Стратхольм и установить его на освященную землю. Одолейте силу, которая исторгнется из посоха, и вернитесь к Анахроносу.", description = "Последнее задание будет самым трудным. Ты уже <одолел/одолела> прихвостня древнего бога и Короля-лича, теперь же придется бросить вызов правой руке Саргераса.\n\nОтнеси посох в Стратхольм, к освященной земле, где пали величайшие рыцари Лордерона. Помести оскверененный посох на священную землю и готовься к схватке с неодолимой силой... Одержи верх над демоном, в чьей власти находится посох, и возвращайся ко мне.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nАтиеш, большой посох Стража"}
MultiLanguageQuestData['ru'][9258] = {title = "Выжженная роща", objective = "Найдите Ларианну Речной Ветер вблизи Выжженной рощи на юго-западе лесов Вечной Песни.", description = "Вторжению Плети в новые земли всегда предшествует порча, проникающая в почву. В прошлом рунические камни, стоящие вдоль границы с Призрачными землями, хранили наш край от этой напасти.\n\nОднако самый западный из камней был уничтожен во время вторжения Плети. Это вынудило нас выжечь землю вокруг него, чтобы остановить распространение порчи.\n\nМоя сестра, Ларианна Речной Ветер, следит за Выжженной рощей. Ступай, отыщи ее – возможно, у нее найдется для тебя работа.", progress = nil, completion = "Тебя прислал мой брат? Да, у меня есть дело, в котором мне пригодится помощь.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9259] = {title = "Предатель Кровавого Паруса", objective = "Этот шелудивый пес, Ревилгаз, обещал прощение всем бывшим пиратам Кровавого Паруса, которые выступят против собственного капитана! И этот шакал паршивый велел мне прирезать моих бывший товарищей и принести их банданы в доказательство.\n\nЯ не могу на это пойти, и тебя не прошу. Добудь для меня шелка и красной краски, и я сделаю точно такие же. Я скажу барону, что ты перешел на нашу сторону, только знай... пиратам Кровавого Паруса это не понравится!", description = nil, progress = "Этот шелудивый пес, Ревилгаз, обещал прощение всем бывшим пиратам Кровавого Паруса, которые выступят против собственного капитана! И этот шакал паршивый велел мне прирезать моих бывший товарищей и принести их банданы в доказательство.\n\nЯ не могу на это пойти, и тебя не прошу. Добудь для меня шелка и красной краски, и я сделаю точно такие же. Я скажу барону, что ты перешел на нашу сторону, только знай... пиратам Кровавого Паруса это не понравится!", completion = "Объявим же минуту молчания в честь павших товарищей, Корссика.\n\n*Предатель шайки Кровавого Паруса ухмыляется и подмигивает вам*\n\nОдно дело быть предателем, а другое – убивать своих... Это уж слишком позорно!", rewards = nil}
MultiLanguageQuestData['ru'][9260] = {title = "Что делает Плеть в Штормграде?", objective = "Соберите три тусклых Некротических камня Плети, которые носит при себе нежить собравшаяся у Штормграда, и исследуйте светящиеся рунические круги вблизи лагеря Плети.", description = "Войска Короля-лича стали лагерем у самых наших дверей. Мы не можем оставаться в бездействии! Выступишь ли ты на защиту Штормграда против этих проклятых захватчиков?\n\nТам, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху. Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно. Пока ты занимаешься этим, уменьши количество этих искажений природы, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!", progress = "Расследование уже завершено? Нет? Тогда за дело!", completion = "Хмм. Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то. Я содрогаюсь при мысли о том, с каким извращенным разумом осуществляется связь посредством подобной магии. Тем не менее тебе удалось остаться в живых и в здравом рассудке. Серебряный Рассвет ценит твою службу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9261] = {title = "Что делает Плеть в Стальгорне?", objective = "Соберите три тусклых Некротических камня Плети, которые носит при себе нежить, откружившая Стальгорн, и исследуйте светящиеся рунические круги вблизи лагеря Плети.", description = "Войска Короля-лича стали лагерем у самых наших дверей. Мы не можем оставаться в бездействии! Выступишь ли ты на защиту Стальгорна против этих проклятых захватчиков?\n\nТам, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху. Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно. Пока ты занимаешься этим, уменьши количество этих искажений природы, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!", progress = "Расследование уже завершено? Нет? Тогда за дело!", completion = "Хмм. Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то. Я содрогаюсь при мысли о том, с каким извращенным разумом осуществляется связь посредством подобной магии. Тем не менее тебе удалось остаться в живых и в здравом рассудке. Серебряный Рассвет ценит твою службу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9262] = {title = "Что делает Плеть в Дарнасе?", objective = "Соберите три тусклых Некротических камня Плети, которые носит при себе нежить, откружившая Дарнас, и исследуйте светящиеся рунические круги вблизи лагеря Плети.", description = "Войска Короля-лича стали лагерем у самых наших дверей. Мы не можем оставаться в бездействии! Выступишь ли ты на защиту Дарнаса против этих проклятых захватчиков?\n\nТам, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху. Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно. Пока ты занимаешься этим, уменьши количество этих искажений природы, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!", progress = "Расследование уже завершено? Нет? Тогда за дело!", completion = "Хмм. Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то. Я содрогаюсь при мысли о том, с каким извращенным разумом осуществляется связь посредством подобной магии. Тем не менее тебе удалось остаться в живых и в здравом рассудке. Серебряный Рассвет ценит твою службу.", rewards = "Вы получите:\n\n"}
