MultiLanguageQuestData['ru'][9299] = {title = "Записка с фронта", objective = "Отнесите потертую записку хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.", description = "Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...", progress = "Да? Что у тебя там?", completion = "Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9300] = {title = "Страничка с фронта", objective = "Отнесите разорванную страницу хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.", description = "Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...", progress = "Да? Что у тебя там?", completion = "Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9301] = {title = "Конверт с фронта", objective = "Отнесите конверт, запятнанный кровью, хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.", description = "Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...", progress = "Да? Что у тебя там?", completion = "Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9302] = {title = "Послание с фронта", objective = "Отнесите смятое послание хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.", description = "Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...", progress = "Да? Что у тебя там?", completion = "Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9303] = {title = "Прививка", objective = "Сделайте прививку шести совунам с Совиных холмов при помощи особого кристалла. Затем вернитесь к воздаятелю Алдару на место крушения в долине Аммен.", description = "Жаная должна починить излучатель, и ей нужны запчасти. Без нашей помощи ей не обойтись. Таэрикс приготовила особую прививку для совунов с Совиных холмов, населяющих территорию, на которой особенно много обломков корабля.\n\nПостарайся подобраться поближе к незараженным совунам и воспользуйся кристаллом. К сожалению, остальных придется убить. Совуны живут в Совиной чаще и Совиных холмах на юго-востоке.", progress = "Чем быстрее мы очистим Совиные холмы, тем быстрее Жаная сможет взяться за работу.", completion = "Большая часть совунов привита, и мы сможем сосредоточить усилия на том, чтобы выбраться отсюда, не беспокоясь об уничтожении совунов.\n\nВыбери, что тебе больше подходит. Хорошая работа заслуживает награды!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЭликсир львиной силыСлабый эликсир защиты\n\nВы также получите:\n\nКрохотный флакон с лечебным зельем"}
MultiLanguageQuestData['ru'][9304] = {title = "Документ с фронта", objective = "Отнесите испачканный документ хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.", description = "Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...", progress = "Да? Что у тебя там?", completion = "Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9305] = {title = "Запасные части", objective = "Соберите 4 запчасти для передатчика и отнесите их технику Жанае на место крушения в долине Аммен.", description = "Мы обнаружили среди обломков корабля поврежденный голографический передатчик. Если его починить, можно попытаться связаться с выжившими дренеями за пределами долины Аммен.\n\nДля ремонта нужны запчасти, которые можно вытащить из других обломков, валяющихся в округе, но их уже утащили местные совуны.\n\nОтправляйся на юг, в Совиную чащу и Совиные холмы, и найди запасные части.", progress = "Если мы соберем все детали, я смогу починить передатчик. Если повезет, нам даже найдется, с кем поговорить по нему.", completion = "Дай-ка поглядеть.\n\nДа, эти части подойдут. Спасибо, Шамакс. Передатчик - сложное устройство, так сходу его не починишь. Я сообщу тебе, когда закончу работу.\n\nПока что ты можешь заглянуть к воздаятелю Алдару, может, ему нужна твоя помощь.", rewards = "Разбитые плетеные поножиГрубые кожаные поножиСшитые вручную штаныВы получите:\n\n"}
MultiLanguageQuestData['ru'][9308] = {title = "<DEPRECATED>Blood Elf Remains?", objective = "Отнесите амулет эльфа крови воздаятелю Алдару на место крушения в долине Аммен.", description = "Вам кажется, что перед вами останки син'дорай - эльфа крови. Судя по всему, он пал жертвой когтей нескольких мутировавших совунов.\n\nОбыскав тело, вы находите на шее медальон на цепочке. Может быть, он заинтересует воздаятеля Алдара?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9309] = {title = "Пропавший разведчик", objective = "Найдите Толаана у хребта Теней в долине Аммен и поговорите с ним.", description = "У нас есть несколько сообщений о том, что на Хребте Теней творится что-то неладное.\n\nНичего хорошего в этом нет: мы ведь думали, что разведчики тщательно обследовали окрестности. Впрочем, один из них еще не вернулся.\n\nОтправляйся на юго-запад, на другую сторону Серебристого озера и найди Толаана. Узнай, что его задержало.", progress = nil, completion = "Помоги... Эльфы крови! Я... попал в засаду. Мне... недолго осталось.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9310] = {title = "Тусклый некротический кристалл", objective = "Отнесите тусклый некротический кристалл лейтенанту Рукагу во внутренний двор Подгорода.", description = "На трупе павшей твари вы находите кристалл, излучающий тусклую некротическую энергию.", progress = "Я могу чем-нибудь помочь?", completion = "Это было у одной из тварей, напавших на город?\n\nМы слышали о лагерях-некрополях, призванных Плетью. Я подозреваю, что они хотят создать такой лагерь в Подгороде. Впредь мы должны быть бдительными.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОсвященное точилоБлагословенное волшебное масло"}
MultiLanguageQuestData['ru'][9311] = {title = "Шпион эльфов крови", objective = "Убейте геодезиста Кандресс и расскажите о случившемся воздаятелю Алдару на месте крушения в долине Аммен.", description = "У меня есть план. Мы должны убить их главаря. Тогда, может быть, им придется отступить. В конце концов, наша задача – выиграть время на ремонт остатков корабля.\n\nУбей геодезиста, а потом расскажи обо всем воздаятелю Алдару – он должен быть в курсе.", progress = nil, completion = "Спасибо тебе за то, что ты убил лидера эльфов крови, Шамакс. Можешь не сомневаться, с остальными эльфами мы скоро разберемся.\n\nВыбери в награду любое оружие.", rewards = "Экзодарский меч-бастардЭкзодарский кинжалЭкзодарская кувалдаЭкзодарский короткий мечЭкзодарский арбалетЭкзодарский посохВы получите:\n\n"}
MultiLanguageQuestData['ru'][9312] = {title = "Излучатель", objective = "Поговорите с техником Жанаей на месте крушения в долине Аммен.", description = "Пока ты <бродил/бродила> по Хребту Теней, Жаная занималась голографическим излучателем. Тебе стоит поговорить с ней.", progress = nil, completion = "Получилось! Получилось! Кажется, я починила излучатель! Сейчас я активирую последний кристалл - и дело в шляпе.\n\nСмотри на излучатель, Шамакс. Похоже, он заработал... Кто-то появляется!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9313] = {title = "На Лазурную заставу", objective = "Поговорите с техником Дивууном на Лазурной заставе на острове Лазурной Дымки.", description = "Ради всего святого, <имя>, отправляйся на Лазурную заставу и поговори с Дивууном!\n\nС нашего островка есть узкая тропа на запад. Иди по ней, перейди через Хрустальную реку, и окажешься в другой части острова. Если идти дальше, не сходя с дороги, она приведет тебя на Лазурную заставу.\n\nМожет быть, они помогут нам и снабдят нас припасами? Остальные последуют за тобой, когда смогут.\n\nСпасибо, без тебя нам не справиться!", progress = nil, completion = "О, рад тебя видеть! Хорошо, что удалось починить оба излучателя, иначе бы нам не отыскать друг друга. Не беспокойся, мы позаботимся о том, чтобы в долину Аммен отправили побольше припасов и войск.\n\nКстати говоря, раз уж ты здесь, пойди, познакомься с другими обитателями форпоста. Дел здесь полно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9314] = {title = "Вести с Лазурной заставы", objective = "Поговорите с корчмарем Челланой на Лазурной заставе на острове Лазурной Дымки.", description = "<класс>! На меня напала пара зверей-мутантов и ранила меня в ногу.\n\nПосле того как нам удалось связаться с Жанаей, меня отправили с Лазурной заставы на разведку. Пожалуйста, поговори вместо меня c корчмарем Челланой. Ей нужно знать, скольких беженцев ждать в нашем поселении. Перейди Хрустальную реку и иди по дороге до самой Лазурной заставы.\n\nОбязательно скажи ей, что тебе нужно где-то остановиться.", progress = nil, completion = "О, должно быть, ты один из выживших, о которых в последнее время столько говорят!\n\nХорошо, что ты пришел. Не беспокойся, мы отправим кого-нибудь на помощь Аэуну.\n\nЯ с радостью послушаю, как умудрились выжить дренеи в соседней долине! Ты храбрец, раз решился пойти сюда.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОсвежающая ключевая водаБлестящая рыбка\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9315] = {title = "Анок'сутен", objective = "Убейте Анок'сутен и возвращайтесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.", description = "Подойди поближе... я умираю...\n\nМеня послали сюда... убивать этих нерубов, но Вандрил... не знал... что у них есть... предводительница...\n\n*Умирающий эльф крови кашляет кровью.*\n\nНайди и убей... Анок'сутен. Приведи помощь. Она рыщет вокруг... деревни Солнечной Короны...", progress = nil, completion = "Прости за неточные разведданные, |3-6(Паладин). Знай я раньше об этой Анок'сутен, то непременно тебе сказал бы.\n\nНас тут слишком мало, и многое просто проскальзывает меж пальцев!", rewards = "ОжогПоношенные штаны ВандрилаУкрепленные жаропрочные рукавицыТранквиллионские брюкиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9317] = {title = "Освященное точило", objective = "Если ты принесешь мне восемь некротических рун, отобрав их у захватчиков из Плети, я дам тебе освященное точило. Оно способно помочь тебе в борьбе против приспешников Короля-лича.", description = nil, progress = "Если ты принесешь мне восемь некротических рун, отобрав их у захватчиков из Плети, я дам тебе освященное точило. Оно способно помочь тебе в борьбе против приспешников Короля-лича.", completion = "Спасибо, Гуреус. Вот освященное точило. Используй его с толком.", rewards = "Вы получите:\n\nОсвященное точило"}
MultiLanguageQuestData['ru'][9318] = {title = "Благословленное волшебное масло", objective = "В обмен на некротические руны Плети Серебряный Рассвет дарует тебе один фиал благословенного волшебного масла.", description = nil, progress = "В обмен на некротические руны Плети Серебряный Рассвет дарует тебе один фиал благословенного волшебного масла.", completion = "Надеюсь, этот предмет пригодится тебе в грядущих битвах.", rewards = "Вы получите:\n\nБлагословенное волшебное масло"}
MultiLanguageQuestData['ru'][9319] = {title = "Свет в темных местах", objective = "Найдите костры, размещенные в пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени.", description = "Мы не единственные, кто справляет сегодня праздник, <имя>. Все создания, все народы возжигают пламя. Даже в самых темных уголках сегодня горят огни.\n\nЕсли хочешь увидеть их своими глазами, спустись в глубины. Отыщи костры, горящие в Стратхольме, Некроситете, у огров в Забытом Городе и в залах самого пика Черной горы. Я буду ждать твоего возвращения.", progress = nil, completion = "Твоя сущность поет, переполненная энергией найденного тобой пламени, Поняха. Огонь, с которым тебе пришлось столкнуться, весьма силен, и тот, кто наделен нужным знанием, может обуздать эту силу...\n\n*Хранитель праздничных костров бормочет заклинание на странном, загадочном языке, затем достает сияющую бутыль.*\n\nА, вот. Пусть это озарит твой путь, куда бы он ни лежал.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9320] = {title = "Гигантский флакон с зельем маны", objective = "Помимо других поставок, у нас есть немного сильнейших зелий маны, которые могут тебе пригодиться. Я дам тебе одну порцию зелья в обмен на пятнадцать некротических рун.", description = nil, progress = "Помимо других поставок, у нас есть немного сильнейших зелий маны, которые могут тебе пригодиться. Я дам тебе одну порцию зелья в обмен на пятнадцать некротических рун.", completion = "Вот, Корольшам. Но соблюдай осторожность. Нас не так много, чтобы мы могли позволить себе большие потери в бою.", rewards = "Вы получите:\n\nГигантский флакон с зельем маныСильнейшее зелье маны"}
MultiLanguageQuestData['ru'][9321] = {title = "Гигантский флакон с лечебным зельем", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nГигантский флакон с лечебным зельемСильнейшее лечебное зелье"}
MultiLanguageQuestData['ru'][9322] = {title = "Костры Калимдора", objective = "Посетите лагеря праздника Огненного солнцеворота, размещенные в Азшаре, Силитусе, Кратере Ун'Горо и Зимних Ключах, затем вернитесь к хранителю праздничного пламени.", description = "Праздник Огненного солнцеворота отмечается повсюду в Азероте, и различные регионы Калимдора – не исключение. Похоже, тебе приходилось много путешествовать, и у тебя есть опыт в странствиях. \n\nПраздник Середины лета нельзя оценить должным образом, пока не увидишь горячие огни синего цвета. Зажигаются костры в холодных западных регионах Зимних Ключей, в северо-восточной Азшаре, возле Покоя Доблестных в пустошах Силитуса и у входа в обширный ркатер Ун'Горо. Возвращайся по завершении путешествия.", progress = nil, completion = "Твой дух сияет жаром костров Калимдора. Разве это пламя не воодушевляет тебя?\n\nКогда тебя покинут силы, быть может, это поможет тебе вновь возжечь этот жар.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9323] = {title = "Костры Восточных королевств", objective = "Посетите лагеря Праздника Огня, размещенные в Выжженных землях, Восточных Чумных землях, во Внутренних землях и Тлеющем ущелье, затем поговорите с хранителем праздничного пламени.", description = "Огненный праздник распространился по всем землям, <класс>. Нет ни единого уголка, куда не проник бы жар этого празднества, а самые сильные огни пылают ярко-синим цветом. Найди их.\n\nОдин из них можно обнаружить к северу от пика Черной горы. Другие размещаются в глубине территории Восточных Чумных земель возле полуразрушенного города, вдоль дороги, ведущей на утесы гористых Внутренних земель, и на пути к Темному порталу в Выжженных землях.\n\nВозвращайся, когда завершишь свое путешествие.", progress = nil, completion = "А, вот и ты. Чуть больше усталости, чуть больше пыли, но внутри сияет свет! В это время года жар касается нас всех и объединяет нас. Сама твоя суть сияет силой костров, которых тебе довелось касаться.\n\nО, но в эти дни просвещение считается довольно ничтожным вознаграждением за выполнение задания, как мне кажется. Так прими это и наслаждайся праздником.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9324] = {title = "Похищение пламени Оргриммара", objective = "Верните Пламя Оргриммара хранителю мудрости Праздника.", description = "Это пламя, похищенное из сердца Оргриммара, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...", progress = "Ты поистине светишься, |3-6(человек). Что у тебя там?", completion = "Что это? Если я не ошибаюсь, это пламя добыто из самого сердца Оргриммара! Свирепая сила, наполняющая души орков и троллей, чувствуется в неистовом жаре этого огня. Какое чудесное добавление к коллекции! И сколь велика твоя отвага, позволившая тебе пробраться в самое логово врага, дабы заполучить священное пламя!\n\nИнтересно, какая сила таится в других городах?..", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖареный сморкПраздничный грогЛетняя колбаскаПоджаренная булочкаБузинный пирогГорсть летних лепестков\n\nСледующее заклинание будет наложено на вас:\n\nЗавершение всех заданий по факелу\n\nВы также получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][9325] = {title = "Похищение пламени Громового Утеса", objective = "Верните Пламя Громового Утеса хранителю мудрости Праздника.", description = "Это пламя, похищенное у шамана Громового Утеса, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...", progress = "Ты поистине светишься, |3-6(дворф). Что у тебя там?", completion = "Если я не ошибаюсь, это пламя добыто на уступах Громового Утеса! Как оно поет, исполненное силы духа! Твою ловкость можно назвать непревзойденной, Дайчи. Прими это как малую плату за свое мастерство. Если бы у нас было пламя из всех трех городов...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖареный сморкПраздничный грогЛетняя колбаскаПоджаренная булочкаБузинный пирогГорсть летних лепестков\n\nСледующее заклинание будет наложено на вас:\n\nЗавершение всех заданий по факелу\n\nВы также получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][9326] = {title = "Похищение пламени Подгорода", objective = "Верните Пламя Подгорода хранителю мудрости Праздника.", description = "Это пламя, похищенное из руин над Подгородом, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...", progress = "Ты поистине светишься, |3-6(ночной эльф). Что у тебя там?", completion = "Хм... Какой странный огонь! Он слаб, почти угасает, но его жар силен. Ты говоришь, он из Подгорода? Поразительно. Кто знает, чего мы можем достичь, заполучив пламя из всех трех городов?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖареный сморкПраздничный грогЛетняя колбаскаПоджаренная булочкаБузинный пирогГорсть летних лепестков\n\nСледующее заклинание будет наложено на вас:\n\nЗавершение всех заданий по факелу\n\nВы также получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][9327] = {title = "Отрекшиеся", objective = "Поговорите с верховным вершителем Мавреном в Транквиллионе, что в Призрачных землях.", description = "Понимаю, что это звучит странно, но Отрекшиеся готовы помогать нам. Поговори с их предводителем, верховным вершителем Мавреном. Он в башне на западной окраине города.\n\nИ, <класс>, после разговора с ним возвращайся ко мне – у меня есть одно неприятное дело, которое требует немедленного решения!", progress = nil, completion = "Я понимаю, что для тебя мы выглядим чудовищами, но уверяю, мы не хотим зла вашему народу. У нас общий враг – предатель Дар'Хан! Он вернулся и ныне командует Плетью, чьи полчища вторглись в эти края из его логова, Смертхольма, что на юге.\n\nНаша предводительница, леди Сильвана Ветрокрылая, родом из этих мест, а при жизни она была эльфийкой! У Дар'Хана перед ней должок, и она жаждет его смерти не меньше, чем вы.\n\nВместе мы разобьем его, |3-6(Паладин)!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9328] = {title = "Герой син'дорай", objective = "Принесите голову Дар'Хана Лор'темару Терону в Луносвет.", description = "<имя>, начинается новая глава в истории эльфов крови. Наконец-то мы вернем свои земли! А заодно и укрепим отношения с Сильваной и ее союзниками.\n\nОтнеси голову предателя лорду-регенту Лор'темару Терону в Луносвет и расскажи о том, что произошло.", progress = "Ты хочешь поговорить со мной, |3-6(Паладин)? Не припомню, чтобы назначал тебе встречу.", completion = "М-да... Не ожидал увидеть это лицо так скоро.\n\nЧто ж, ты принес мне весьма радостную весть, Скуфопал.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9329] = {title = "Отрекшиеся", objective = "Поговорите с верховным вершителем Мавреном в Транквиллионе, что в Призрачных землях.", description = "Понимаю, что это звучит странно, но Отрекшиеся готовы помогать нам. Поговори с их предводителем, верховным вершителем Мавреном. Он в башне на западной окраине города.\n\nИ, <класс>, после разговора с ним возвращайся ко мне – у меня есть одно неприятное дело, которое требует немедленного решения!", progress = nil, completion = "Мы, Отрекшиеся, пришли сюда потому, что у нас с вами общий враг – Дар'Хан! Он вернулся и ныне командует Плетью, чьи полчища вторглись в эти края из его логова, Смертхольма, что на юге.\n\nНаша предводительница, леди Сильвана Ветрокрылая, родом из этих мест, при жизни она была эльфийкой! У Дар'Хана перед ней должок, и она жаждет его смерти не меньше, чем вы.\n\nВместе мы разобьем его, |3-6(Маг)!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9330] = {title = "Похищение пламени Штормграда", objective = "Верните Пламя Штормграда Праздничному Сказителю.", description = "Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...", progress = "Ты поистине светишься, |3-6(орк). Что у тебя там?", completion = "И это ярко горящее пламя... ты говоришь, оно из Штормграда? Замечательно! Должно быть, это было славное приключение! Конечно же, я заплачу тебе за это. Если ты найдешь еще что-нибудь подобное, обязательно приходи поговорить со мной.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖареный сморкПраздничный грогЛетняя колбаскаПоджаренная булочкаБузинный пирогГорсть летних лепестков\n\nСледующее заклинание будет наложено на вас:\n\nЗавершение всех заданий по факелу\n\nВы также получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][9331] = {title = "Похищение пламени Стальгорна", objective = "Верните Пламя Стальгорна Праздничному Сказителю.", description = "Это пламя, похищенное из сердца Стальгорна, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...", progress = "Ты поистине светишься, |3-6(тролль). Что у тебя там?", completion = "Это сильное пламя, должно быть, явилось из залов Стальгорна; оно столь же неукротимо, как сами дворфы. Отличная добыча, Профессия. Если бы у меня был огонь из других городов... а, неважно. Вот твоя плата.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖареный сморкПраздничный грогЛетняя колбаскаПоджаренная булочкаБузинный пирогГорсть летних лепестков\n\nСледующее заклинание будет наложено на вас:\n\nЗавершение всех заданий по факелу\n\nВы также получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][9332] = {title = "Похищение пламени Дарнаса", objective = "Верните пламя Дарнаса праздничному сказителю.", description = "Это пламя, похищенное с берегов Тельдрассила, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...", progress = "Ты поистине светишься, |3-6(нежить). Что у тебя там?", completion = "Этот огонь полон древней скорби, Вертекс. Ты говоришь, он добыт от корней Тельдрассила? Невероятно! Вот награда за твое мастерство. Возвращайся ко мне, если найдешь еще что-либо подобное; возможно, у меня найдется применение этому.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖареный сморкПраздничный грогЛетняя колбаскаПоджаренная булочкаБузинный пирогГорсть летних лепестков\n\nСледующее заклинание будет наложено на вас:\n\nЗавершение всех заданий по факелу\n\nВы также получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][9333] = {title = "Перчатки Серебряного Рассвета", objective = "Если принесешь мне тридцать некротических рун, я подарю тебе защитные перчатки для рук, по твоему выбору. Они оказались очень ценными в борьбе против нежити Плети", description = nil, progress = "Если принесешь мне тридцать некротических рун, я подарю тебе защитные перчатки для рук, по твоему выбору. Они оказались очень ценными в борьбе против нежити Плети", completion = "Хорошая работа, Корольшам. Возьми выбранные тобой защитные перчатки в благодарность за твои усилия.", rewards = "Рукавицы истребления нежитиПовязки истребления нежитиБоевые рукавицы истребления нежитиПерчатки искоренения нежити"}
MultiLanguageQuestData['ru'][9334] = {title = "Благословленное волшебное масло", objective = "В обмен на некротические руны Плети Серебряный Рассвет дарует тебе один фиал благословенного волшебного масла.", description = nil, progress = "В обмен на некротические руны Плети Серебряный Рассвет дарует тебе один фиал благословенного волшебного масла.", completion = "Надеюсь, этот предмет пригодится тебе в грядущих битвах.", rewards = "Вы получите:\n\nБлагословенное волшебное масло"}
MultiLanguageQuestData['ru'][9335] = {title = "Освященное точило", objective = "Если ты принесешь мне восемь некротических рун, отобрав их у захватчиков из Плети, я дам тебе освященное точило. Оно способно помочь тебе в борьбе против приспешников Короля-лича.", description = nil, progress = "Если ты принесешь мне восемь некротических рун, отобрав их у захватчиков из Плети, я дам тебе освященное точило. Оно способно помочь тебе в борьбе против приспешников Короля-лича.", completion = "Спасибо, Элеутерококк. Вот освященное точило. Используй его с толком.", rewards = "Вы получите:\n\nОсвященное точило"}
MultiLanguageQuestData['ru'][9336] = {title = "Гигантский флакон с лечебным зельем", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nГигантский флакон с лечебным зельемСильнейшее лечебное зелье"}
MultiLanguageQuestData['ru'][9337] = {title = "Гигантский флакон с зельем маны", objective = "Помимо других поставок, у нас есть немного сильнейших зелий маны, которые могут тебе пригодиться. Я дам тебе одну порцию зелья в обмен на пятнадцать некротических рун.", description = nil, progress = "Помимо других поставок, у нас есть немного сильнейших зелий маны, которые могут тебе пригодиться. Я дам тебе одну порцию зелья в обмен на пятнадцать некротических рун.", completion = "Вот, Рансу. Но соблюдай осторожность. Нас не так много, чтобы мы могли позволить себе большие потери в бою.", rewards = "Вы получите:\n\nГигантский флакон с зельем маныСильнейшее зелье маны"}
MultiLanguageQuestData['ru'][9338] = {title = "Верность Кругу Кенария", objective = "Даже если тебе не нужны наши награды, эти знаки свидетельствуют о нашем взаимном доверии и дружбе.\n\nПринеси их мне. Я не забуду твою верную службу, особенно если ты выйдешь за пределы простого исполнения долга.", description = nil, progress = "Даже если тебе не нужны наши награды, эти знаки свидетельствуют о нашем взаимном доверии и дружбе.\n\nПринеси их мне. Я не забуду твою верную службу, особенно если ты выйдешь за пределы простого исполнения долга.", completion = "Работать с тобой – честь для нас, Oldlikeworld. Благодаря твоим усилиям, мы преодолеем все трудности.", rewards = nil}
MultiLanguageQuestData['ru'][9339] = {title = "Награда вора", objective = "Верните Пламя Штормграда персонажу (ИМЯ).Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...", description = "Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...", progress = nil, completion = "Сегодняшние твои деяния свидетельствуют сами за себя, Профессия.\n\nЯ мало что могу дать тебе помимо этого, но у меня есть вот этот венец – дар, что соответствует ловкости и дерзости. Пусть он озарит твой путь.", rewards = "Вы получите:\n\nКорона Огненного Солнцеворота"}
MultiLanguageQuestData['ru'][9340] = {title = "Глубокий Разлом", objective = "Ступайте на восток от Соколиного дозора, к Глубокому разлому, и убейте 8 детенышей камнеруба и 3 камнерубов-вожаков по приказу капитана следопытов Венн'рена.", description = "Альянс обложил нас со всех сторон. Пилигримы син'дорай все идут и идут из Азерота, так что мы должны найти дорогу, о которой наши вездесущие враги не прознают.\n\nЯ подумал немного, и кое-что придумал. Мы проложим тайный путь через Глубокий Разлом.\n\nДа, там кишмя кишат горные камнедеры, но они всего лишь звери и быстро научатся нас бояться. Отправляйся к Глубокому Разлому и убей всех камнедеров, которых встретишь. Думаю, остальных это напугает.", progress = nil, completion = "Неплохо, Джонниди. Это научит камнедеров держаться от нас подальше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9341] = {title = "Гербовая накидка Серебряного Рассвета", objective = "Твоя помощь в нашем деле была очень ценной, Трансмастер. Если пожелаешь, я могу сделать так, что ты получишь гербовую накидку Серебряного Рассвета. Мы гордимся тем, что ты в числе наших союзников.", description = nil, progress = "Твоя помощь в нашем деле была очень ценной, Трансмастер. Если пожелаешь, я могу сделать так, что ты получишь гербовую накидку Серебряного Рассвета. Мы гордимся тем, что ты в числе наших союзников.", completion = "Возьми эту гербовую накидку и носи его с гордостью. Быть может, твой пример побудит и других взяться за оружие, чтобы поддержать нас в борьбе против Плети.", rewards = "Вы получите:\n\nГербовая накидка Серебряного Рассвета"}
MultiLanguageQuestData['ru'][9343] = {title = "Гербовая накидка Серебряного Рассвета", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nГербовая накидка Серебряного Рассвета"}
MultiLanguageQuestData['ru'][9345] = {title = "Изготовление мази", objective = "Соберите 12 листьев пламенного шиполиста и возвращайтесь к Грелагу на Заставу Хребтолома.", description = "Я не добрался даже до Зет'Гора, как патруль Легиона меня засек. Я побежал, надеясь укрыться в башне неподалеку, но одна из гончих Скверны вцепилась мне под колено.\n\nСбежать-то я сбежал, но с ногой творится что-то ужасное. Каменный страж Амбелан нашел меня и перетащил сюда.\n\nМне надо хоть немного подлечиться. В Долине Костей, к северу отсюда, растет трава шиполист. Я смогу сделать из нее обезболивающую мазь, которая позволит мне ходить.", progress = "Ты принес листья?", completion = "Это должно помочь. Сейчас я приготовлю мазь, а затем наложу шину. В таком виде кое-как до Траллмара доковыляю. Могу представить, что скажет провозвестница Регулкут, когда меня увидит.\n\n&lt;Грелаг тяжело вздыхает.&gt;\n\nСпасибо тебе за помощь, Зябкин. У меня осталось несколько листьев гребнелиста, возьми с собой, если хочешь. Как знать, может, и пригодятся.", rewards = "Вы получите:\n\nПламенный шиполист"}
MultiLanguageQuestData['ru'][9349] = {title = "Сбор яиц опустошителей", objective = "Принесите 12 яиц опустошителей Легасси на место крушения дирижабля на полуострове Адского Пламени.", description = "Я есть хочу!\n\nДумаешь, голодный повар – это смешно?\n\n<Легасси саркастически хмыкает и указывает на вынутый из кармана кусок пергамента.>\n\nСудя по этой туристической карте, мы пролетали где-то здесь, пока столь стремительно не свалились вниз... К северо-западу отсюда есть одно местечко в лесу Тероккар, называется дорога Острого Шипа. Там полным-полно яиц опустошителей, которые считаются отменным деликатесом.\n\nЕсли кто-нибудь не побоится их раздобыть, у нас будет настоящий праздник живота!", progress = "Ну, где яйца?\n\n<Живот Легасси издает голодное бурчание.>", completion = "Чтобы блюдо было отменным, его надо готовить из отменных продуктов! Эти яйца прекрасны.\n\nСейчас я дочищу свою сковородку, и можешь присоединяться к трапезе!", rewards = "Вы получите:\n\nОмлет из яйца опустошителя"}
MultiLanguageQuestData['ru'][9351] = {title = "Дикие демоны Бездны", objective = "Принесите 10 конденсированных сущностей демона Бездны \"Крикуну\" Скриду Многослову на место крушения дирижабля.", description = "Даже если я восстановлю оболочку дирижабля, все равно мне нечем заправить двигатель. Топливо закончилось, и я ума не приложу, где его можно достать.\n\nРазве что, к югу отсюда находится место под названием Искривленные поля. Там полно всякой нечисти и бесконтрольных демонов Бездны, но ведь это, можно сказать, ходячие батарейки!\n\nПринеси мне сущности демонов Бездны, я запущу двигатель и мы наконец уберемся отсюда. Ставлю пять золотых, что выжму из этого демона настоящую демоническую скорость!", progress = "Удалось добыть сущности?", completion = "Отлично! Вот это мощь! Мне придется усовершенствовать двигатель, чтобы воспользоваться всеми преимуществами этой штуки. Если... в смысле, когда мы отсюда выберемся, в Зоне 52 ахнут, увидев, что я придумал!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГипнотические КамниПодвеска проворства\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9352] = {title = "Вторжение из Дарнаса", objective = "Отправляйтесь в Западное святилище, к юго-западу от площади Соколиных Крыльев, и уничтожьте всех чужаков, которых вы там встретите. Затем сообщите о результатах хранительнице энергии Велании.", description = "Помимо постоянной угрозы со стороны Презренных мне еще регулярно приходится разбираться с сообщениями об атаках ночных эльфов!\n\nБольшинство этих сообщений оказываются ложными, но один недавний инцидент требует более пристального внимания. В Западном святилище, одном из наших главных источников энергии, произошла крупная авария. Ходят слухи, что это дело рук дарнасских диверсантов!\n\nСтупай туда и разберись со всеми, кто выглядит подозрительно. Потом отправляйся к хранительнице энергии Велании, которая заведует святилищем.", progress = nil, completion = "Ночные эльфы? Здесь? Вот крысы!\n\nДумаешь, они имеют отношение к аварии в моем святилище? Если у тебя есть какие-то сведения, лучше незамедлительно передать их капитану Печати Солнца!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9353] = {title = "Подарочный купон АйКока", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЛетний подарок"}
MultiLanguageQuestData['ru'][9355] = {title = "Работа для сообразительных", objective = "Убейте 15 хищных землероев и возвращайтесь к штейгеру Большие Десны в Оплот Чести.", description = "Привет, <класс>. Наконец-то прибыло подкрепление, так что мы можем себе позволить хоть какое-то подобие нормальной жизни.\n\nОдна из первых задач – восстановить поток путников и торговых караванов по юго-западной дороге, но для этого надо очистить эту область от землероев.\n\nСыны будут тебе благодарны, если ты поможешь нам разобраться с этой напастью. Место обитания землероев очень легко опознать. Видишь вздыбленную землю – значит, внутри они и сидят.", progress = "Ну что, очистил дорогу от червей?", completion = "Хорошая работа, Крайтеен. Хотя, наверное, не стоит торопиться поздравлять нас с решением этой проблемы. Уверен, немалая часть червей затаилась и еще выползет. Но если мы опять заметим их логова, то расправимся безо всякой пощады!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПрочная цепьКольцо адепта\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9356] = {title = "Летать как птица", objective = "Принесите 12 мясистых крыльев канюка Легасси на место крушения дирижабля.", description = "Скрид любит говорить, что, дескать, он летает, как птица. Ага, как дохлая курица!\n\nТы только посмотри на эти обломки. Он называет это \"жесткой посадкой\"!\n\nКонечно, нас подстрелили, и я бы его даже пожалел, если бы он так не бахвалился своим мастерством!\n\nПожарю-ка я для него парочку птичьих крыльев, пусть он поразмыслит о своем поведении. К востоку отсюда, в Долине Костей, обитают канюки-костеклюи. У них мясистые, сочные крылья, это именно то, что надо.", progress = "Предвкушаю, какое у него будет лицо, когда он это увидит. С самого момента аварии он постоянно ворчит, что я думаю только о еде. Но кто-то же должен всех кормить, пока остальные чинят дирижабль!", completion = "Яйца опустошителей. Раз!\n\nБекон адского вепря. Два!\n\nКрылья канюка. Три!\n\nОтличное меню. Ты обязательно должен это попробовать.", rewards = "Вы получите:\n\nЗакуска из канюкаРецепт: закуска из канюка"}
MultiLanguageQuestData['ru'][9357] = {title = "Задание Аэльдона Озаренного Солнцем", objective = "Поговорите с Аэльдоном Озаренным Солнцем у Внутренних эльфийских ворот в Лесах Вечной Песни.Если ты ищешь работу, обратись к капитану Печати Солнца за Внутренними эльфийскими воротами, что у меня за спиной.\n\nА теперь оставь меня в покое, мне нужно допросить этого негодяя.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Если ты ищешь работу, обратись к капитану Печати Солнца за Внутренними эльфийскими воротами, что у меня за спиной.\n\nА теперь оставь меня в покое, мне нужно допросить этого негодяя.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9358] = {title = "Следопыт Сарейн", objective = "Поговорите со следопытом Сарейн у деревни Легкий Ветерок, что в лесах Вечной Песни.", description = "Наша деревня только выглядит мирной. На самом деле мы живем в осаде. С востока нам угрожает Плеть, с запада – Презренные.\n\nСледопыт Сарейн стережет наши границы от нежити, которая лезет с Тропы Мертвых. Ступай по дороге на восток и узнай, не нужна ли ей помощь.", progress = nil, completion = "Ты здесь, чтобы помочь нам? Так что же ты молчишь? Помощь нам всегда пригодится!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9359] = {title = "Обитель Странников", objective = "Поговорите с лейтенантом Вестницей Зари в обители Странников, что в лесах Вечной Песни.", description = "Ты <оказал/оказала> нам неоценимую помощь в борьбе с Презренными. Такие бойцы наверняка пригодились бы Странникам в их борьбе с троллями из племени Амани.\n\nСтупай в обитель Странников к северо-востоку отсюда, поговори с лейтенантом Вестницей Зари и узнай, не нужна ли ей твоя помощь.", progress = nil, completion = "Ты хочешь нам помочь? Замечательно!\n\nБорьба с племенем Амани дается нам недешево, и хорошие бойцы вроде тебя нам всегда нужны.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9360] = {title = "Вторжение племени Амани", objective = "Доставьте планы вторжения племени Амани лейтенанту Вестнице Зари в обитель Странников.", description = "Вы не понимаете языка, которым написаны эти планы, но узнаете карту, на которой отмечено расположение обители Странников и деревни Легкий Ветерок.\n\nОб этом следует сообщить лейтенанту Вестнице Зари в обитель Странников!", progress = "Что это у тебя?", completion = "Тролли отвлекали нас своими атаками, планируя нападение на деревню Легкий Ветерок? Мы этого совершенно не ожидали!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9361] = {title = "Зловепрь – тоже мясо", objective = "Легасси требует принести ему 8 кусков мяса зловепря на место крушения дирижабля. Убейте зловепря, добудьте порченое мясо зловепря, а затем очистите его с помощью микстуры очищения.", description = "Отличные яйца, но что скажешь, если мы добавим к ним еще один штрих?\n\nХороший кусок бекона станет достойным завершением нашего блюда, и я даже знаю, где его достать.\n\nЭто место просто кишит зловепрями. По-хорошему, их мясо надо бы хорошенько вымочить и замариновать, но нам повезло.\n\n<Легасси роется в своем барахле и достает оттуда фляжку.>\n\nКонечно, это вовсе не для приготовления свинины, но в поварском деле главное – импровизация!", progress = "Что там с очищенным мясом зловепря? Удалось приготовить?", completion = "Хм...\n\nВыглядит съедобным, если проперчить хорошенько. Лучше не будем говорить Скриду, откуда взялся его завтрак, ладно?", rewards = "Вы получите:\n\nЗловепревая ветчина"}
MultiLanguageQuestData['ru'][9362] = {title = "Полководец Креллиан", objective = "Принесите радужную раковину верховному магу Ксилему в башню в утесах Азшары.", description = "У меня мало времени, <имя>! С помощью чар магического зрения я обнаружил мощный источник магии. Я не могу покинуть башню, поэтому прошу тебя убить мерзкое создание, завладевшее мощным артефактом. \n\nЖалкий недоумок, известный как полководец Креллиан, прячется за широкими спинами своих стражей в храме Зин-Малор. Испепели это ничтожество и принеси мне радужную раковину, которую он прячет.", progress = "Мы не можем терять не минуты! Ты принес раковину?", completion = "Должен заметить, у этой раковины странная аура. Очень хорошо, что частью твоей награды будет уникальная возможность исследовать свойства этого артефакта.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9363] = {title = "Предупреждение деревне Легкий Ветерок", objective = "Отправляйтесь в деревню Легкий Ветерок в лесах Вечной Песни и поговорите со следопытом Деголиеном.", description = "Ступай в деревню Легкий Ветерок и предупреди следопыта Деголиена о планах Амани. Несмотря на то что Зул'Марош мертв, деревне стоит приготовиться к нападению троллей. Скажи Деголиену, что я пришлю ему подкрепление при первой же возможности.", progress = nil, completion = "Ты принес очень важные сведения, Расул. Теперь, когда мы знаем о планах троллей, мы будем готовы к нападению.\n\nНас не застанут врасплох!", rewards = "Черненый плетеный ременьЖилет следопытаОтделанные атласом сапогиВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9364] = {title = "Частицы магии", objective = "Наложите заклинание превращения на тварей Бича Злобы в Азшаре и убейте клонов, которые появятся несколько мгновений спустя. Убейте 50 клонов и возвращайтесь к верховному магу Ксилему в Азшару.", description = "В ходе исследований я выявил потрясающее свойство радужной раковины. \n\nВозьми раковину и наложи заклинание превращения на тварей Бича Злобы в Азшаре. Через несколько мгновений хаотическая аура раковины создаст нескольких маленьких клонов. Клонов надо убить – как можно скорее! – и тогда раковина вберет в себя их сущность. \n\nВозвращайся ко мне, когда раковина будет полна.", progress = "Ты выполнил мое поручение?", completion = "Прекрасно! Прекрасно! \n\nТеперь мы можем использовать собранную магическую силу для создания нового заклинания!", rewards = "Вы изучите:\n\nПревращение\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9365] = {title = "Награда вора", objective = "Верните Пламя Штормграда персонажу (ИМЯ).Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...", description = "Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...", progress = nil, completion = "Сегодняшние твои деяния свидетельствуют сами за себя, Ландэ.\n\nЯ мало что могу дать тебе помимо этого, но у меня есть вот этот венец – дар, что соответствует ловкости и дерзости. Пусть он озарит твой путь.", rewards = "Вы получите:\n\nКорона Огненного Солнцеворота"}
MultiLanguageQuestData['ru'][9366] = {title = "Оскверненная кровь", objective = "Принесите 6 образцов оскверненной крови исчадий ужаса, обитающих у прудов Аггонара, Риатену Мрачному из Соколиного дозора на полуострове Адского Пламени.", description = "К северо-востоку отсюда лежат пруды Аггонара. Когда-то там было священное место дренеев, но потом кровь демона осквернила воды этих прудов.\n\nС тех пор минуло много лет, но кровь, даже разбавленная, все еще таит в себе огромную силу. Рядом с прудами разгуливают исчадия ужаса, насыщаясь энергией, разлитой в воде. Уничтожь их и принеси мне их оскверненную кровь. Выполни это задание, и получишь награду.", progress = "Оскверненная кровь... Где она, Джонниди?", completion = "В этих образцах содержится неимоверная энергия, Джонниди. Нам необходимо наладить постоянную и беспрепятственную доставку оскверненной крови.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9367] = {title = "Праздник Огня", objective = "Прикоснитесь к пламени праздничных костров в Штормграде, Стальгорне и Дарнасе, затем поговорите с хранителем мудрости праздника в столичных городах.", description = "Вновь наступает праздник Огненного солнцеворота!\n\nКаждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажженными в наших столичных городах. По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Середине Лета.\n\nНа самом деле, если ты не против, у меня для тебя есть задание. Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах. Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!", progress = "Горят ли костры?", completion = "Превосходно! Похоже, в этом году мы избрали ответственных Хранителей праздничных костров, если огни поддерживаются так хорошо, как ты утверждаешь. Спасибо за проведенное исследование; вот, прими это как небольшой знак моей благодарности.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9368] = {title = "Праздник Огня", objective = "Прикоснитесь к пламени праздничных костров в Оргриммаре, Громовом Утесе и Подгороде, затем поговорите с Праздничным сказителем в столичных городах.", description = "Вновь наступает праздник Огненного солнцеворота!\n\nКаждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажженными в наших столичных городах. По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Середине Лета.\n\nНа самом деле, если ты не против, у меня для тебя есть задание. Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах. Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!", progress = nil, completion = "Превосходно! Похоже, в этом году мы избрали ответственных Хранителей праздничных костров, если огни поддерживаются так хорошо, как ты утверждаешь. Спасибо за проведенное исследование; вот, прими это как небольшой знак моей благодарности.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9369] = {title = "Исцеляющие кристаллы", objective = "Добудьте 6 фиалов с кровью мотылька из ближайших долинных мотыльков и принесите их Проэнтиусу на место крушения в долине Аммен.", description = "Мы дренеи. Наш корабль разбился, и поскольку раненых очень много, первым делом надо зарядить исцеляющие кристаллы. И побыстрее!\n\nК сожалению, в настоящий момент для этого придется добывать кровь долинных мотыльков, она отлично подойдет.\n\nМотыльки водятся во всей долине, особенно в северо-западной ее части.", progress = "Тебе удалось набрать достаточно крови мотыльков, чтобы зарядить исцеляющие кристаллы? Время не ждет, раненых очень много!", completion = "Жаль, что приходится обменивать жизни этих существ на наши – подобная жестокость чужда духу дренеев. Зато собранная кровь наполнит исцеляющие кристаллы, так что мотыльки погибли не зря.", rewards = "Трофейный кожаный поясПоношенные туфлиСлегка заржавевшие наручиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9370] = {title = "Остановить очищение", objective = "Поставьте сигнальный самоцвет на алтарь Аггонара, рядом с прудами Аггонара, и уничтожьте дренейского анахорета и всех, кто явится на сигнал. После выполнения задания заберите самоцвет и возвращайтесь к Риатену Мрачному в Соколиный дозор.", description = "Наши разведчики захватили у прудов Аггонара какого-то дренейского паладина. Он подготавливал ритуал по очистке прудов. Мы должны остановить дренеев, а не то потеряем бесценный источник оскверненной крови!\n\nВот этим сигнальным самоцветом он должен был пометить место, где их жрец – \"анахорет\", как они себя называют, – мог бы спокойно провести ритуал. Поставь камень на алтарь Аггонара и убей всех дренеев, которые появятся.\n\nДумаю, тебе стоит прихватить парочку друзей на помощь.", progress = "Ты вернулся, Менгиле. Что, я уже могу начинать оплакивать этих дренейских идиотов?", completion = "Пусть эти святые фанатики не лезут не в свое дело.", rewards = "Потерянный плащ АнахоретаВам дадут возможность выбрать одну из следующих наград:\n\nКольцо оскверненной кровиМедальон оскверненной силы\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9371] = {title = "Ботаник Таэрикс", objective = "Поговорите с ботаником Таэрикс на месте крушения в долине Аммен.", description = "<имя>, ботанику Таэрикс нужна твоя помощь. Она вместе с учениками расположилась на западе отсюда, рядом с кораблем.", progress = nil, completion = "О, слава Небу, что ты здесь. У нас очень много работы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9372] = {title = "Распространение демонической скверны", objective = "Соберите 6 образцов крови зловепря у крупных зловепрей по просьбе Тии Рыжей Гривы с Кенарийской заставы на полуострове Адского Пламени.", description = "Добро пожаловать на Кенарийскую заставу, <класс>. Я благодарна, что ты <зашел/зашла> сюда, нас нечасто балуют визитами. Я исходила эти земли вдоль и поперек, исследуя существ, которые их населяют.\n\nИзучая по поручению Кенарийской экспедиции наиболее опасных тварей, я сделала поразительное открытие. Многие из здешних существ уже подверглись кардинальным изменениям, но все равно продолжают мутировать. Чтобы следить за этими изменениями, мне нужны образцы крови, так что я буду рада любой помощи.", progress = "Тебе удалось выполнить мою просьбу?", completion = "Прекрасно, Выручалкин. Эти образцы крови не только помогут мне в исследованиях, но пригодятся Экпедиции для дальнейшего изучения дикого мира Запределья.\n\nЕсли мы узнаем, что заставляет обитателей этих земель постоянно мутировать, то, возможно, сможем изготовить противоядие.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9373] = {title = "Потерянное послание", objective = "Доставьте подпорченный кожаный чехол Тие Рыжей Гриве, которая стоит лагерем рядом с руинами Ша'наара на западе полуострова Адского Пламени.", description = "Взглянув на кожу чехла повнимательней, вы понимаете, что его разъели желудочные соки червя. Кажется, на чехле был какой-то узор, но детали украшений разобрать невозможно.\n\nЕдинственное, что можно опознать, так это полустертый знак Круга Кенария. О содержимом чехла ничего не известно, и вы решаете, что лучше всего отнести его кому-нибудь из Круга.", progress = "Добрый день, |3-6(Маг). Что привело тебя в наш лагерь?", completion = "Спасибо, что принес мне эту вещь, |3-6(Маг). Я-то думала, почему так долго нет вестей от Экспедиции. Хотела бы я знать, как давно было отправлено это послание и что случилось с его курьером.\n\nВозьми за труды немного денег.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9374] = {title = "Записи Арелиона", objective = "Отправляйтесь к прудам Аггонара и найдите записи Арелиона по просьбе магистра Каринды из Соколиного дозора на полуострове Адского Пламени.", description = "Мой муж Арелион заинтересовался прудами Аггонара, едва мы прибыли в Запределье. Больше всего времени он проводил, изучая свойства местного ила.\n\nНесколько дней назад его не стало. Мне сказали, что он мертв, а с этим ничего уже не поделаешь.\n\nНо я бы не хотела, чтобы исследования моего мужа бесследно сгинули после его смерти. Ступай на северо-восток, к прудам, и поищи его дневник. Арелион носил его в коричневом ранце.", progress = "Как успехи, Джонниди? Пруды Аггонара лежат к северу от цитадели Адского Пламени.", completion = "Записи моего мужа... Да там нет ни слова о научных изысканиях!\n\nКак я могла быть такой идиоткой? \"Магические свойства оскверненного ила...\" Да он просто пудрил мне мозги!", rewards = "Вы получите:\n\nПредмет #1Currency Token Test Token 4"}
MultiLanguageQuestData['ru'][9375] = {title = "Дорога к Соколиному дозору", objective = "Помогите израненной эльфийке крови – пилигриму добраться до Соколиного дозора, затем поговорите с Талерисом Созерцателем Рассвета.", description = "<Эльфийка крови смотрит на вас и на ее израненном лице появляется надежда.>\n\nПожалуйста, <класс>, помоги мне выбраться из этой клетки! Я по глупости отбилась от основной группы, идущей из Траллмара. Предупреждал же меня Мартик Тор'сельдори!\n\nНа меня напали ужасные создания, судя по всему, те самые опустошители, о которых он говорил. Мне удалось отогнать их, но это было только начало.\n\nТолько я занялась своими ранами, как меня разыскали проклятые птицелюды. Они притащили меня сюда, в пещеру, и заперли в этой клетке. Освободи меня, пожалуйста, я должна добраться до Соколиного дозора!", progress = "Что тебе нужно, |3-6(Шаман)?", completion = "&lt;Талерис рявкает, обращаясь к эльфам крови на заставе&gt;\n\nЗанесите ее внутрь и перевяжите!\n\n&lt;Затем снова обращается к вам.&gt;\n\nЕй повезло, что ты нашел ее, |3-6(Рыцарь смерти). Я думаю, она недолго бы протянула.\n\nТы понял, о чем она говорила?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9376] = {title = "Скарб пилигрима", objective = "Перозубые опустошители напали на израненную эльфийку крови – пилигрима, когда она остановилась в Лощине Пыльного Пера. Разыщите ее стоянку и потерянные вещи.", description = "Наша раненая путница все продолжает кричать о какой-то сумке.\n\nТы не <заметил/заметила> ничего похожего на том месте, где ее <нашел/нашла>? Хм...\n\nДолжно быть, она потеряла сумку, когда бежала от преследователей. Перозубые опустошители из вон той лощины на юге часто нападают на одиноких путников.\n\nЕсли она не успокоится, я не смогу наложить повязку на рану. Как она не понимает, что упрямство может стоить ей жизни!\n\nСтупай в Лощину Пыльного Пера, и попробуй разыскать место ее стоянки. Держу пари, она оставила свои сумки где-то там.", progress = "Не нравится мне все это. Вряд ли она бы кинула сумку на дороге. Ты можешь разыскать ее вещи?", completion = "Спасибо, что вернул сумки, Щук. Не знаю, что там такого важного, но она не подпускала к себе никого, пока не получила свои вещи обратно.", rewards = "Сегментированная кирасаНабедренники Солнечного СкитальцаУбор скитальцаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9377] = {title = "Жажда магической силы", objective = "Извлеките мощную сущность демона Бездны из мстительных демонов Бездны и возвращайтесь к Талерису Созерцателю Рассвета в Соколиный дозор.", description = "Соколиный дозор служит пристанищем для тех, кто странствует по Запределью. Мы находимся в самом начале пути, но многие приходят к нам, уже истомленные магической жаждой.\n\nВ этом мире необходимо уметь контролировать свою зависимость от магии. Помогают еда и питье, но полезнее всего иметь запасы магической энергии. Ее могучими источниками являются демоны Бездны, но в последнее время они встречаются все реже и реже. Сейчас их можно отыскать только на Искривленных полях к юго-западу отсюда.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9380] = {title = "В погоне за большим", objective = "Соберите 6 неповрежденных трупов астральных гончих и доставьте в Оплот Чести геологу Мурантусу.", description = "Клянусь, что если получу еще хоть одно письмо из Стальгорна...\n\nТы когда-нибудь <пытался/пыталась> что-нибудь объяснить тому, кто тебя в упор слышать не хочет, а, <класс>? Я послал этим парням из Стальгорна астральную гончую, которую они заказывали, но им, видите ли, нужна целая \"упаковка\" подобных созданий! Подумать только, - упаковка!\n\nЯ попытался им объяснить, что астральные гончие - одиночки, но они отказались меня слушать. Я уже понял, что вразумить их невозможно. Можешь собрать штук шесть самых лучших гончих, они встречаются к востоку от крепости, и принести сюда?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9381] = {title = "Стрелы, бьющие без промаха", objective = "Принесите 8 хвостовых перьев стервятника-костеклюя сокольничему Дренне Речной Ветер в Соколиный дозор.", description = "Пилигримы идут нескончаемой чередой, а силы Альянса зашевелились, так что дел в Соколином дозоре, – только успевай поворачиваться. Обычно я делаю стрелы для наших следопытов, но уже довольно давно у меня нет времени даже собрать перья на оперение.\n\nЯ дам тебе денег, если принесешь хвостовые перья стервятника-костеклюя. В последний раз я видела, как они кружили около костей каких-то огромных тварей к северу от Соколиного дозора.", progress = "Ты принес перья?", completion = "Да, это подойдет. Нашим следопытам давно не хватает стрел, так что одной головной болью стало меньше. Спасибо за помощь, |3-6(Охотник).", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9383] = {title = "Честолюбивый план", objective = "Используйте освященный кристалл против раненого неконтролируемого демона Бездны, затем возвращайтесь к Элсаане в храм Телхамат.", description = "Эльфы крови используют магию совершенно безответственно, <класс>. Они не умеют контролировать магическую энергию. Наоборот, они ее бездумные рабы, и способны на что угодно, только бы утолить свою магическую жажду. Чтобы усилить свою демоническую магию, они пожирают энергию демонов Бездны.\n\nЯ создала кристалл, заряженный заклинанием, который позволит нам нейтрализовать демонов Бездны и оборвать их связь с этим миром. Я видела демонов Бездны на Искривленных полях, к юго-востоку от цитадели Адского Пламени.", progress = "Сработала ли магия кристалла против демона Бездны?", completion = "Молодец, Назгрейм. Судя по всему, сдерживающий кристалл работает, но сколько это будет продолжаться, неизвестно. Мы будем за ним присматривать, а заодно приготовим побольше кристаллов на будущее.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9385] = {title = "Разъяренные Опустошители", objective = "Убейте 10 перозубых опустошителей и возвращайтесь к Гремни Длиннобороду на полуострове Адского Пламени.", description = "Оплот Чести послал нас разобраться с араккоа, и мы разбили здесь лагерь, думая, что никто нас не потревожит. Как выяснилось, мы встали слишком близко к перозубым опустошителям.\n\nЭти безжалостные твари сводят на нет всю нашу работу. Мы заплатим тебе, если ты с ними разделаешься. Ну что, по рукам?", progress = "Как продвигается охота на опустошителей?", completion = "Молодцом, Ёё. Пусть эти твари знают, кто тут главный!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9386] = {title = "Свет в темных местах", objective = "Найдите костры, размещенные в пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени.", description = "Неужели тебе этого так хочется? Ну что ж, если снова желаешь спуститься в глубины, я с радостью тебя вознагражу. \n\nОтыщи костры, горящие в Стратхольме, Некроситете, Забытом Городе и в залах самого пика Черной горы. Я буду ждать твоего возвращения, <имя>.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][9387] = {title = "Источник порчи", objective = "Отправляйтесь в руины Ша'наара на полуострове Адского Пламени и добудьте из иллидари-надсмотрщиков 5 демонических сущностей. После завершения задания возвращайтесь к аптекарю Азетену в Соколиный дозор.", description = "Все дренеи, не попавшие под влияние Скверны, – истинные паладины Света, и наш невезучий приятель не исключение. Но мне интересно, как Скверна смогла низвести эту великую расу до Сломленных и Заблудших.\n\nЯ слышал о теории, что мутацию вызывает энергия Скверны. Я хочу ее проверить.\n\nК северо-западу отсюда лежат руины Ша'наара. Туда иллидарские надсмотрщики согнали Сломленных. Принеси мне несколько демонических сущностей, которые можно добыть из надсмотрщиков, и я проверю их на этом дренее.", progress = "Ты добыл образцы?", completion = "Ты оказал мне большую услугу, Джонниди. А теперь посмотрим, что скажет наш синий друг.", rewards = "Клинок павшего воздаятеляВам дадут возможность выбрать одну из следующих наград:\n\nКольцо убитого отшельникаСломанное колье\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9388] = {title = "Мерцающие огни Калимдора", objective = "Посетите праздничные костры в Ясеневом лесу, Степях, на Темных берегах и в Когтистых горах, затем поговорите с хранителем праздничного пламени.", description = "Сегодня по всему миру горит множество огней, <имя>. Сложнее всего присматривать за теми кострами, которые пылают зеленым; без присмотра они не будут гореть долго. Убедись, что изумрудные огни все еще горят в Калимдоре – пусть наш Хранитель костров успокоится.\n\nТы найдешь эти костры вблизи Кабестана в Степях, неподалеку от Меча Властителя на Темных берегах, в Ясеневом лесу у моста около Аванпоста Среброкрылых, и поблизости от дороги на Утес Ветрорезов вдоль главного тракта в Когтистых горах.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖареный сморкЛетняя колбаскаПоджаренная булочкаБузинный пирог\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9389] = {title = "Мерцающие огни Восточных королевств", objective = "Посетите праздничные костры в предгорьях Хилсбрада, в Серебряном бору, Западном Крае и Болотине, затем поговорите с хранителем праздничного пламени.", description = "Во время праздника Огненного солнцеворота по всей земле традиционно зажигаются мириады огней. Кое-кто считает, что зеленое пламя является самым изящным, поскольку его труднее всего поддерживать, и оно имеет столь уникальный оттенок.\n\nУбедись, что это пламя все еще горит в Восточных королевствах, чтобы успокоить нашего хранителя огня. Эти костры размещены около Дун Модра в Болотине, поблизости от деревни Погребальных Костров в Серебряном бору, на утесах неподалеку от маяка Западного края и возле разрушенной башни в предгорьях Хиллсбрада.", progress = nil, completion = "Так ты возвращаешься, повидав изумрудное пламя, горящее в разных уголках континента... И что ты об этом думаешь? Несомненно, это редкостное и замечательное зрелище. Однако я осознаю, что весомая награда ценится больше... поэтому возьми вот это за твои труды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖареный сморкЛетняя колбаскаПоджаренная булочкаБузинный пирог\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9390] = {title = "Найти Седаи", objective = "Разыщите Седаи, брата анахорета Обадия. Седаи может находиться где-то поблизости, на востоке, на полуострове Адского Пламени.", description = "Выслушай меня, <класс>. Мой брат Седаи отправился на встречу с орками с заставы маг'харов. Этот несчастный идеалист считал, что время излечило взаимные обиды, и мы сможем договориться о мире.\n\nУже несколько дней о нем ничего не слышно, и я опасаюсь самого худшего.\n\nМожешь отправиться на его поиски и дать отдых моей измученной душе? Седаи должен быть где-то на востоке.", progress = nil, completion = "Вы находите тело юного дренейского паладина. Он убит стрелой в спину.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9391] = {title = "Осветить путь", objective = "Отправляйтесь к Глубокому разлому на полуострове Адского Пламени и зажгите южный маяк, западный маяк и центральный маяк. После выполнения задания возвращайтесь к капитану следопытов Венн'рену из Соколиного дозора вместе с зажженным факелом.", description = "Теперь, когда численность камнедеров уменьшилась, надо указать пилигримам безопасную дорогу. Возьми этот факел и возвращайся к Глубокому Разлому. Разыщи там три маяка, которые стоят вдоль дороги на восток.\n\nЗажги их, и после этого возвращайся ко мне. Будь <осторожен/осторожна> – огонь маяков наверняка привлечет камнедеров.", progress = "Ты выполнил мою просьбу, Джонниди?", completion = "Глубокий разлом все еще опасен, но, по крайней мере, там можно пройти.\n\nЕсли бы Альянс не караулил все известные нам дороги, вряд ли бы мы решились на такое дело.", rewards = "Рукавицы СветоносногоПерчатки огнебросаПояс скитальцаВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9392] = {title = "Обучение разбойника", objective = "Поговорите с наставником разбойников налетчиком Авокором в Солнечном Шпиле на острове Солнечного Скитальца.", description = "По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных разбойников на острове Солнечного Скитальца тренирует налетчик Авокор. Поговори с ним, может быть, он сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nАвокор, как и все наставники острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.", progress = nil, completion = "Твое имя прошептали мне тени, Авй. Говорят, ты ищешь опытного наставника, который покажет тебе что к чему, - то есть кого-то вроде меня. Что же, я могу тебе помочь, но это будет тебе стоить небольшого процента со всей добычи каждый раз, как я буду чему-нибудь тебя учить. Да, я расскажу тебе, что значит быть разбойником.\n\nНо запомни: если тебя уличат в воровстве, ты меня не знаешь. А теперь иди сюда и покажи, из какого теста ты сделана!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9393] = {title = "Обучение охотника", objective = "Поговорите с следопытом Саллиной в Солнечном Шпиле на Острове Солнечного Скитальца.", description = "По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных охотников на Острове Солнечного Скитальца тренирует следопыт Саллина. Поговори с ней, может быть, она сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nСаллина, как и все наставники Острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.", progress = nil, completion = "Привет тебе, Тсой. Охотник должен быть зорок как ястреб, ловок как обезьяна и быстр как гепард. Ты можешь стать таким после надлежащего обучения. Путь охотника - путь к власти над зверями этого мира, непревзойденной меткости и умения выживать в таких ситуациях, когда другие погибают.\n\nЕсли тебе это интересно, я обучу тебя - естественно, за небольшое вознаграждение. Начнем?", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9394] = {title = "Куда подевался Виллитен?", objective = "Найдите смотрителя Виллитена в землях Блеклых Сумерек, что в лесах Вечной Песни.", description = "Смотритель земель Блеклых Сумерек куда-то запропастился! Должно быть, его забыли предупредить, что надо уходить, когда магистр и все прочие покинули шпиль. Я знаю, что он до сих пор где-то здесь, однако не решаюсь отправиться на поиски: вокруг слишком много магических тварей.\n\nПрошу тебя, <класс>, найди его и убедись, что с ним все в порядке!", progress = nil, completion = "Кто ты? Ты не из учеников магистра, это точно!\n\nТебя прислали помочь мне уладить это безобразие?", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9395] = {title = "Вилла Салтерила", objective = "Поговорите с лордом Салтерилом на вилле Салтерила в лесах Вечной Песни.", description = "Клянусь, если я получу еще хоть один запрос от лорда Салтерила касательно припасов для его вечеринки, я запущу в кого-нибудь огненным шаром! Я что, похожа на массовика-затейника? Между нами говоря, этот глупец и его прихлебатели живут в убеждении, что нам тут ничто не угрожает!\n\nА ведь кое-кто из нас всерьез занят... ну, например, я не знаю, обороной того, что осталось от Кель'Таласа! Слушай, <класс>, может быть, тебе удастся угомонить Салтерила? Его вилла находится дальше по дороге, к западу отсюда...", progress = nil, completion = "О, магистр Рассветная Странница наконец-то откликнулась на мои скромные просьбы! Как мило с ее стороны. Надо будет доложить о ее поведении лорду-регенту в Луносвет. Она чудовищная грубиянка!\n\nНо тебе не о чем беспокоиться. Полагаю, твое появление означает, что я наконец-то получу долгожданные припасы для моей вечеринки!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9396] = {title = "Магия араккоа", objective = "Принесите 4 свитка племени Хаал'эш чародею Калестрису Утренней Звезде в Соколиный дозор на полуострове Адского Пламени.", description = "Запределье, <имя>, хранит множество секретов. Рано или поздно ты с ними столкнешься, это только вопрос времени.\n\nАраккоа, эти полулюди- полуптицы, владеют древним чародейным знанием, которое бы нам очень пригодилось. Отправляйся в логово Хаал'эш, к югу отсюда. Найди все магические свитки, которые хранит племя Хаал'эш, и принеси их мне.", progress = "Тебе удалось добыть свитки, Джонниди?", completion = "Неплохо сработано, Джонниди. Запределью не удасться утаить от нас свои секреты.\n\nНаше призвание - стать хозяевами этого мира!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9397] = {title = "Пух и перья", objective = "Отправляйтесь в логово Хаал'эш на полуострове Адского Пламени и найдите молодую самку калири в гнезде калири. Посадите птенца в пустую клетку и принесите сокольничему Дренне Речной Ветер в Соколиный дозор.", description = "Араккоа из логова Хаал'эш вывели необыкновенных птиц, которых они называют калири.\n\nМне удалось поймать несколько молодых самцов, и, кажется, они вполне поддаются дрессировке. Добыть самочку куда труднее, но если бы у меня была хотя бы одна, я смогла бы получить от них потомство. Лучше всего, если самочка будет очень молоденькая... совсем птенец. Взрослая дикая птица не выживет в неволе.\n\nВозьми эту клетку и ступай на юг, в логово Хаал'эш. Разыщи гнезда с яйцами, из которых должны вылупиться птенцы. Если ты раздобудешь юную самку калири, я награжу тебя по-царски.", progress = "Ты вернулся. принес самку калири?", completion = "Вот она! Настоящая юная самка калири!\n\nКакая она хорошенькая! Спасибо тебе, Щук.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9398] = {title = "Смертельно опасные хищники", objective = "Убейте 8 детенышей камнеруба и 4 камнерубов-вожаков по просьбе разведчицы Вануры из храма Телхамат на полуострове Адского Пламени.", description = "В Запределье Сломленные не испытывали ничего, кроме насилия и жестокости. Не удивительно, как только открылся Темный портал, они кинулись к нему, стремясь выбраться из этого мира.\n\nК несчастью для наших ошеломленных братьев и сестер, пришедших с юга, они стали легкой добычей для камнедеров из Глубокого разлома. Если хочешь помочь выжить моему племени, отправляйся к Разлому и уничтожь хищников.", progress = nil, completion = "Ты сделал что должно, Сотус. Ужасно, что нам приходится отнимать жизнь, даже если это жизнь таких опасных тварей, как камнедеры.\n\nЭто было необходимо, хотя и жестоко, и я благодарна тебе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9399] = {title = "Безжалостные десятники", objective = "Убейте 4 иллидари-надсмотрщиков на руинах Ша'наара и возвращайтесь к Икану в храм Телхамат на полуострове Адского Пламени.", description = "Ты думаешь, все Сломленные несут в себе семена зла? На самом деле, очень многое зависит от обстоятельств. Пока я не встретил Оменай, меня тоже можно было считать потерянным.\n\nНаш разум сильно пострадал от воздействия демонической магии орков. В таком состоянии очень легко сбиться с пути и лишиться воли.\n\nДемоны, заключившие союз с Иллиданом, день за днем обыскивали полуостров Адского Пламени, находили нас и делали своими рабами. Оменай принесли нам надежду. Если хочешь, чтобы мои родичи обрели свободу, отправляйся в руины Ша'наара, что на юго-западе отсюда, и убей иллидари-надсмотрщиков.", progress = nil, completion = "Ты сделал это! Я твой вечный должник, Нфздпал. Посмотри на это Отребье.\n\nУвидишь, я научу их жить снова.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9400] = {title = "Убийца", objective = "Ступайте по дороге к северу от цитадели Адского Пламени и разыщите убийцу по имени Крун Хребтолом по просьбе Назгрела.", description = "<имя>, недавно мы обнаружили, что готовится покушение на нашего посланника в Соколином дозоре. Цитадели Адского Пламени стали известны планы нашей экспедиции, и они решили устроить засаду.\n\nРазведчики доложили, что убийца по имени Крун Хребтолом поджидает на дороге к цитадели. Ступай и уничтожь его. Пусть орки Скверны знают, как с нами связываться!", progress = nil, completion = "Тело соответствует описанию Круна Хребтолома, убийцы из цитадели Адского Пламени. Перевернув тело, вы замечаете, что из его спины торчит каменный топор.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9401] = {title = "Странное оружие", objective = "Принесите тяжелый каменный топор Назгрелу в Траллмар на полуострове Адского Пламени.", description = "Вы вытаскиваете каменный топор из тела, чтобы рассмотреть его повнимательней. В этом оружии есть что-то необычное.\n\nВроде бы сделано орками, но вы раньше никогда не видели, чтобы орки работали с таким материалом. Возможно, топор следует показать Назгрелу.", progress = "Скажи, убийца мертв?", completion = "Он был убит этим оружием? Не может быть...\n\nНеужели... мы нашли их?", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9402] = {title = "Апорт!", objective = "Нырните на дно пруда Тихого Шелеста и добудьте лазурный фиал для инструктора Антеола.", description = "Ты кто? <имя>? Можешь не зазнаваться от того, что я знаю тебя по имени: <одна из моих студенток/один из моих студентов> только о тебе и твердит.\n\nХм... если уж ты хочешь произвести на <нее/него> впечатление, отчего бы тебе не оказать мне услугу? На дне пруда, что позади меня, лежит лазурный фиал. Нырни, добудь его и принеси сюда.", progress = "Ну, как водичка?", completion = "Что ж, молодец, молодец... Стоило мне попросить тебя прыгнуть в пруд, и ты это сделал! Интересно, чего бы ты ни сделал, если бы тебя попросил об этом один из лучших друзей!\n\nЕсли ты ждешь награды за труд, вот тебе в награду совет: никогда не берись за дело, не узнав сначала, что ты с этого будешь иметь. Главное оружие мага – это его ум. Запомни это и постарайся впредь первым делом пускать в ход мозги.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9403] = {title = "Чистейшая вода", objective = "Наполните лазурный флакон водой из водопада Элрендар для Антеола.", description = "Ну а теперь, когда ты кое-чему <научился/научилась>, я тебе предложу кое-что более существенное. Речь идет о твоей способности защищаться в ближнем бою. Разумеется, лучше вообще не вступать в бой без крайней необходимости, но нужно быть <готовым/готовой> ко всему.\n\nЯ могу помочь тебе изготовить посох, подобающий магу. Для начала возьми флакон, добытый тобою со дна, и наполни его водой у подножия водопада Элрендар. Ступай вдоль реки на юго-восток, и увидишь водопад.", progress = "Только вода из водопада Элрендар достаточно чиста, чтобы использовать ее в магии! Есть ли у тебя такая вода?", completion = "Ну-с, посмотрим, что там у тебя...\n\n&lt;Антеол рассматривает флакон на просвет.&gt;\n\nДа, это подойдет. Молодец, Гримслок.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9404] = {title = "Живая ветка", objective = "Убивайте хранителей лесов Вечной Песни, пока не найдете животворную ветвь для инструктора Антеола.", description = "Тебе, наверное, случалось видеть ходячие деревья вблизи водопада Элрендар? Эти хранители природы пронизаны первородной магией, которую мы можем использовать в собственных целях с помощью чистой воды, которую ты уже <принес/принесла> мне.\n\nК несчастью, наши хранители леса такие древние и ветхие, что тебе, возможно, придется перебить нескольких из них, прежде чем удастся найти хоть одну живую ветку.", progress = "Ну что, где ветка? Неси ее скорее!", completion = "Ты выполнил мою просьбу, Гримслок, и можешь получить заслуженную награду.", rewards = "Посох залогаВам дадут возможность выбрать одну из следующих наград:\n\nСфера залога\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9405] = {title = "Поручение Вождя", objective = "Принесите тяжелый каменный топор провозвестнице Регулкут в Траллмар на полуострове Адского Пламени.", description = "Как известно, вождь затеял экспедицию только с одной целью. Это мир, из которого мы пришли. Там наши корни.\n\nВ этом путешествии у орков и эльфов крови разные цели. В отличие от нас, они ищут землю обетованную.\n\nКто бы не создал этот топор, он знаком с прежними днями и мы должны найти его. Дело слишком важное, чтобы использовать обычный способ поиска. Покажи топор провозвестнице Регулкут, она скажет, что делать.", progress = "Скажи мне, чего ты ищещь. Может быть, я помогу тебе.", completion = "Я выполню просьбу Назгрела, |3-6(Рыцарь смерти). Больше ни слова.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9406] = {title = "Маг'хары", objective = "Доставьте письмо маг'харов Назгрелу в Траллмар на полуострове Адского Пламени.", description = "Новости, которые ты <принес/принесла> о другой земле за Темным порталом... Я должен поверить, что вся земля там принадлежит сыну Дуротана... и свободна от демонической скверны? Но как его народ смог вернуться в этот мир?\n\nНадеюсь, для твоего же блага, что это не шутка, <класс>. Новость, которую ты <принес/принесла> слишком много для нас значит. Я немедленно отправлю донесение в Награнд! Адский Крик должен узнать об этом!\n\nОтнеси письмо обратно в Траллмар, своему командиру. Скажи, что маг'хары шлют ему привет!", progress = "Какие вести ты принес нам, Выручалкин?", completion = "Ты уверен? Настоящие орки... Здесь, на полуострове Адского Пламени! Вот это новости, Рунакус.\n\nНадо немедленно доложить вождю.", rewards = "Церемониальное облачениеПоножи громовой кузниПлеменной хауберкМаска из шкуры копытняВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9407] = {title = "Через Темный портал", objective = "Пройдите через Темный портал и найдите генерал-лейтенанта Ориона. Он ждет вашего прибытия на другой стороне, в Запределье.", description = "Много лет Темный портал оставался безмолвным... забытым. Но теперь он проснулся.\n\nПосле того как наши войска отразили нападение демонов, они пробились через портал и встретились с врагом на его территории!\n\nНыне мы втянуты в безжалостную войну, и кое-кто думает, что мы не сможем победить. Наш долг, наша мрачная радость – сразиться с демонами в Запределье, обеспечив нашу победу. \n\nЕсли ты хочешь помочь нам, <имя>, то немедленно сообщи об этом генерал-лейтенанту Ориону. Он ждет тебя в Запределье...", progress = nil, completion = "Наша экспедиция благополучно прошла через портал и основала новую базу, именуемую Траллмар. Но, как ты видишь, Пылающий Легион своим вторжением отрезал нас от наших собратьев. Любому понятно, что демоны надеются отбить Темный портал и не позволить нам получить подкрепление с Азерота.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9408] = {title = "Забытые герои", objective = "Поговорите с командиром армии Данатом Троллебоем в Оплоте Чести.Мы потеряли уже столько солдат в битве за этот портал, но по-прежнему продолжаем держать оборону.\n\nТрудно поверить, но эта крепость, – живое свидетельство стойкости солдат Альянса.\n\nЗдесь находится один из великих героев – Данат Троллебой! Разыщи его, <класс>. Он поговорил с каждым солдатом, и, несомненно, захочет видеть и тебя.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Мы потеряли уже столько солдат в битве за этот портал, но по-прежнему продолжаем держать оборону.\n\nТрудно поверить, но эта крепость, – живое свидетельство стойкости солдат Альянса.\n\nЗдесь находится один из великих героев – Данат Троллебой! Разыщи его, <класс>. Он поговорил с каждым солдатом, и, несомненно, захочет видеть и тебя.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9409] = {title = "Срочная доставка", objective = "Отнесите сверток с фиалами Залдууну на место крушения в долине Аммен.", description = "Благодаря тебе мы собрали все необходимое, чтобы зарядить исцеляющие кристаллы. Отнеси эти фиалы Зальдууну, нашему жрецу. Он ухаживает за ранеными в центральной части корабля.", progress = "Привет тебе, |3-6(Шаман). Что ты несешь? Это мне?", completion = "Превосходно! Эта кровь прекрасно подойдет для наших исцеляющих кристаллов.\n\nРаз уж ты здесь, у меня найдется для тебя поручение. Ты не против?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9410] = {title = "Хранитель душ", objective = "Установите тотем духа волка на том месте, где вы нашли тело Круна Хребтолома. Когда появится дух древнего волка, следуйте за ним.", description = "Их возможности превосходят нюх наших самых лучших волков, <имя>. У духов есть свой способ отыскать кого-то. Ты призовешь существо, которое чует не запах, но сущность.\n\nА теперь ступай, <класс>. Возьми с собой этот тотем и установи его там, где <нашел/нашла> каменный топор.", progress = "Тебе повезло остаться в живых.", completion = "Кто ты, незваный гость? Я приказал своим бойцам не трогать тебя только потому, что Рига учуяла рядом с тобой духов.\n\nГовори, не бойся, но выбирай слова. Мы редко доверяем чужакам, особенно в такой близости от цитадели.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9415] = {title = "Маршал Синяя Синестен", objective = "Поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора.", description = "Ты новобранец маршала Синестена? Ну, конечно.\n\nЧего ты ждешь? Наши солдаты умирают там, в пустыне. Правда, тебе не терпится к ним присоединиться?\n\nИди, и смотри, не присохни к песку по пути.", progress = nil, completion = "Альянсу нужна помощь всех, кто способен держать оружие. Орда регулярно получает подкрепление с северной части континента, и мы изо всех сил стараемся от них не отстать.\n\nПозволь, я объясню тебе ситуацию.", rewards = nil}
MultiLanguageQuestData['ru'][9416] = {title = "Генерал Кирика", objective = "Поговорите с генералом Кирикой в лагере Орды рядом с Ульем Регал.", description = "Должно быть, ты <один/одна> из новобранцев генерала Кирики. Пора тебе браться за дело. В пустыне тела очень быстро портятся.\n\nДворфы ежедневно получают подкрепление, а мы не должны им уступать. Полезные ископаемые Силитуса наши!\n\nГенерал тебя проинструктирует. Не мое дело – учить тебя. Мне приказали только найти тебя.", progress = nil, completion = "Хорошо, что ты здесь, но на любезности времени нет. Я проведу инструктаж, и ты сразу отправляйся в бой.\n\nСлушай.", rewards = nil}
MultiLanguageQuestData['ru'][9417] = {title = "Угроза Араккоа", objective = "Убейте 4 ветроступов и 6 коготарей из племени Хаал'эш по просьбе Гремни Длинноборода с полустрова Адского Пламени.", description = "Араккоа умные твари... Почти такие же, как гномы. У них неистовый нрав, и они отлично владеют магией.\n\nНедавно они напали на патруль Оплота Чести, поэтому-то нас сюда и отправили. Миррен и я – лучшие стрелки в мире, так-то! Но обычно птички, в которых мы стреляем, не поливают нас молниями.\n\nМожет, пособишь нам немного? Я как раз нашел Логово Хаал'еш, оно на юго-востоке отсюда.", progress = nil, completion = "Великолепно, Сабантул! На сим нарекаю тебя истинным Длиннобородым!\n\nНе уходи, это непременно надо обмыть!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9418] = {title = "Сфера Авруу", objective = "Отнесите сферу Авруу на алтарь племени Хаал'эш, который находится на юго-востоке от логова Хаал'эш на полуострове Адского Пламени. После того как Аэранас обретет свободу, отдайте ему сферу.", description = "<Вы подносите сферу ближе к себе, и до вас доносится голос.>\n\nЯ чувствую, ты не араккоа, так что мы сможем договориться. Мое имя Аэранас, когда-то я правил восточным ветром. В эту сферу меня заключил Авруу, один из магов племени Хаал'эш. Я могу выкупить у тебя свою свободу.\n\nНайди алтарь, который араккоа использовали, чтобы поработить меня. Он сокрыт где-то на юго-востоке их логова. Поднеси сферу к алтарю, а когда я стану свободен, отдай ее мне. В обмен на свою свободу я отдам тебе древнее сокровище.", progress = "Наконец-то я на свободе!", completion = "Эта сфера вернула мне свободу. Вот твоя награда, смертный. Я всегда расплачиваюсь с долгами.", rewards = "Плащ заклинателя ветраВам дадут возможность выбрать одну из следующих наград:\n\nПодвеска танцующего с ветромПерстень Аэронуса\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9419] = {title = "Истощение пустыни", objective = "Найдите и принесите силитист к экстрактору силитистов и поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора.", description = "Совсем недавно мы выяснили, что Орда добывает в Силитусе полезные ископаемые. Мы думали, что в таком климате не стоит держать много войск.\n\nК сожалению, выяснилось, насколько важны эти полезные ископаемые, и теперь мы тщетно пытаемся догнать Орду по масштабам добычи.\n\nЕсли ты хочешь мне помочь, ступай в пустыню и принеси оттуда силитист.", progress = "Соблюдай осторожность, но не медли. Время на исходе.", completion = "Хвала Свету! Ты добился успеха!\n\nНачни мы добычу кристаллов раньше, не оказались бы в таком отчаянном положении. Мы не допустим, чтобы сокровища пустыни попали в руки Орды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСильнейшее зелье маныСильнейшее лечебное зелье\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9420] = {title = "Прекрасное оперение", objective = "Принесите Миррену Длиннобороду на полуострове Адского Пламени 8 перьев калири от различных калири из логова Хаал'эш.", description = "Араккоа из логова Хаал'эш, что к югу отсюда, удалось вывести невероятных птиц, которых они называют калири. Перья этих калири оторвали бы с руками на любом базаре на Азероте. Только подумай, сколько бы эля я тогда смог купить!\n\nВот что я тебе скажу. Принеси мне перьев калири, и я отдам тебе свою собственную шляпу. Соглашайся, отличная сделка, такую шляпу ты больше нигде не найдешь! Ну что, по рукам?", progress = "Ты принес мне перья калири, |3-6(Охотник)?", completion = "Ты выполнил свою часть сделки. Дело есть дело!\n\nВозьми, дружище. Заботься о ней как следует.", rewards = "Вы получите:\n\nШляпа с напитками МирренаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9421] = {title = "Обучение шамана", objective = "Я Фирманваар. Ты не зря пришел ко мне. Мое призвание - учить молодых шаманов, особенно тех, что лишь теперь ступают на этот путь.\n\nДренеи заново открывают для себя шаманизм, Шамакс. Избрание не самого накатанного пути требует особого мужества.\n\nЯ с радостью помогу тебе, как только ты сочтешь, что пришло время снова поучиться.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9422] = {title = "Истощение пустыни", objective = "Найдите и принесите силитист к экстрактору силитистов и поговорите с генералом Кирикой в лагере Орды возле Улья Регал.", description = "Мы давно начали добычу кристаллов пустыни Силитуса. Поначалу мы сталкивались лишь с опасностями, исходящими от местных жителей, песка, пыли и жары.\n\nТеперь же Альянс пронюхал, чем мы тут занимаемся, и началась гонка за добычей полезных ископаемых.\n\nУ меня каждая пара рук на счету, надеюсь, ты мне тоже поможешь.", progress = "Пустыня очень опасна,будь настороже, Снатяжкой. В барханах шныряют сторонники Альянса, и каждый шаг может оказаться последним.", completion = "Ты молодец, Таквер. Мы отправим добытые ресурсы на склад, а наши приобретения все равно что потери для наших врагов!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСильнейшее зелье маныСильнейшее лечебное зелье\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9423] = {title = "Возвращение к Обадию", objective = "Возвращайтесь к анахорету Обадию в храм Телхамат на полуострове Адского Пламени и расскажите о смерти Седаи.", description = "Вы получили подтверждение смерти Седаи, так что придется вернуться к Обадию с мрачными новостями.", progress = nil, completion = "Седай, брат мой...\n\nЭти трусливые орки! Как они могли, он же был безоружен!\n\nОставь меня, Назгрейм. Спасибо, что принес эту горькую весть, но теперь мне нужно побыть наедине с собой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9424] = {title = "Месть Макуру", objective = "Принесите 10 ожерелий предков маг'харов Макуру в храм Телхамат на полуострове Адского Пламени.", description = "Седаи был Макуру как брат. Мы все обязаны ему жизнью. Оменай называют Макуру безумным, но если они не станут мстить за Седаи, то они сами лишились ума!\n\nВ этом мире немногое принадлежит Макуру, но он отдаст тебе все, чем обладает, если ты отомстишь за Седаи.\n\nЯ видел маг'харских рубак в холмах к северо-востоку. Они нас ненавидят! Они не заслуживают нашей пощады! Ступай, отомсти за Седаи! В качестве доказательства смерти принеси их ожерелья предков.", progress = "Ты отомстил за Седаи?", completion = "Да... Месть! Ты поступил как должно.\n\nВозьми это. Теперь оно приносит Макуру только горе...", rewards = "Клинок СедаиВам дадут возможность выбрать одну из следующих наград:\n\nОжерелье СедаиКольцо Седаи\n\nВы также получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9425] = {title = "Возвращение в Мельницу Таррен", objective = "Отправляйтесь в Мельницу Таррен в предгорьях Хилсбрада и поговорите с советником Вечерней Зарей.", description = "Рад видеть тебя, <класс>! У меня есть задание как раз для тебя.\n\nМы лишь недавно вступили в Орду и должны убедить всех, что готовы их поддерживать и помогать в трудную минуту. Тогда и они с большей готовностью придут нам на помощь.\n\nСтупай в город Отрекшихся – Мельницу Таррен. Он расположен в предгорьях Хилсбрада, на юго-востоке. По прибытии поговори с советником Вечерней Зарей.", progress = nil, completion = "Ну и ну! Еще один из моих братьев. Отлично! Нам предстоит многое сделать для наших новых друзей-Отрекшихся. Пройдись по городу и выясни, кому из жителей нужна помощь.\n\nНе сомневаюсь, ты найдешь время, чтобы помочь всем!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9426] = {title = "Пруды Аггонара", objective = "Отправляйтесь к прудам Аггонара и убейте 6 исчадий ужаса и 6 волдырных гнилостней по просьбе Амаана Мудрого.", description = "Много времени прошло с тех пор, как мы назвали эту землю Дренором. Демоническая печать безвозвратно ее изменила.\n\nЯ помню одно место, сейчас его называют пруды Аггонара. Когда-то там били благословенные источники, теперь же кровь демона Аггонара запятнала их самую суть. Оскверненная кровь породила гнусных тварей, от которых надо избавиться, если мы хотим очистить эти пруды. Ступай к востоку, к прудам, и уничтожь исчадья ужаса и прочую нечисть, которая там развелась.", progress = nil, completion = "Да, я чувствую, что пруды очистились от скверны, пусть и не до конца.\n\nТы проделал большую работу, Сотус.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9427] = {title = "Очищение вод", objective = "Отправляйтесь к прудам Аггонара и используйте фиал очищения над телом Аггонара по просьбе Амаана Мудрого. После того как вода будет очищена от сущности Аггонара, возвращайтесь обратно к Амаану.", description = "Я прошу тебя закончить дело, которое мы начали. Теперь, когда демоническое влияние ослабело, ты <должен/должна> взять фиал Очищения и вылить его содержимое на сам источник скверны – тело Аггонара.\n\nКости демона лежат в самой северной части прудов. Будь <осторожен/осторожна>, я думаю, что сущность Аггонара не полностью оставила этот мир.", progress = "Ты вернулся Сотус. Воды очищены от скверны?", completion = "Сущность Аггонара воплотилась в его грязном порождении, Аггонисе. Теперь, когда демоны побеждены, мы можем начать восстановление изначальной чистоты прудов.\n\nПрими нашу благодарность, Сотус. Плоды твоих деяний изменят этот мир к лучшему.", rewards = "Нарукавники демоноубийцыВам дадут возможность выбрать одну из следующих наград:\n\nПодвеска из храма ТелхаматПерстень Амаана\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9428] = {title = "На заставу Расщепленного Дерева", objective = "Поговорите с советником Верным Солнцу на Заставе Расщепленного Дерева в Ясеневом лесу.", description = "<Посланница наклоняется поближе и переходит на шепот.>\n\nТвоя слава обгоняет тебя, <имя>! Я прошу тебя отправиться на заставу Расщепленного Дерева в Ясеневом лесу. Пешком туда проще всего добраться, если идти на запад через Дуротар и Степи, а потом на развилке повернуть на север.\n\nКогда прибудешь туда, поговори с советником Верным Солнцу. Только осторожнее, Ясеневый лес – место опасное!", progress = nil, completion = "Да, посланница мне уже сообщила, я тебя ждал.\n\nОна просто хочет, чтобы ты помог нам здесь, чем сможешь. Она что-то говорила насчет того, чтобы укрепить наши связи с остальной Ордой...\n\nПорасспрашивай здесь, на заставе - тут наверняка найдутся те, кому нужна помощь. Кроме того, я слышал, что на побережье, к западу отсюда, есть еще один форпост Орды, который называется форт Зорам'гар.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9429] = {title = "Путешествие в Темнолесье", objective = "Поговорите с анахоретом Деланом в городе Темнолесье в Сумеречном лесу.", description = "Слышал я, что у королевства Штормграда есть настоящая заноза в боку - Сумеречный лес. Местность эта наполнена страхом и зловонием нежити.\n\nПоскольку мы пытаемся помочь им по мере сил, я хотел бы, чтобы ты <отправился/отправилась> на юго-восток, в главное тамошнее поселение людей - городок под названием Темнолесье. Анахорет Делан будет ждать вас.", progress = nil, completion = "Приветствую вас, |3-6(Шаман). Хотелось бы верить, что путешествие ваше обошлось без неожиданностей?\n\nЭти несчастные со всех сторон окружены исчадиями ночи. Мы хотим, чтобы вы оказали им посильную помощь и разогнали тьму.\n\nПобродите по городу, познакомьтесь с его жителями. Пожалуйста, Будулайко, помогите им, чем сможете.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9430] = {title = "Реликвии Ша'наара", objective = "Отправляйтесь в руины Ша'наара и соберите 10 реликвий Ша'наара по просьбе Амаана Мудрого из храма Телхамат на полуострове Адского Пламени.", description = "Чтобы видеть недоступное всем остальным, мне не нужны глаза. Я не стану осуждать тебя за то, что ты <выполнил/выполнила> просьбу Макуру. Я хочу, чтобы ты <научился/научилась> не просто смотреть, но видеть.\n\nСтупай к юго-западу, в руины Ша'наара и собери все реликвии, которые там найдешь. Если судьба будет благосклонна, нам попадется то, что нужно.\n\nВозможно, тебе покажется неясным смысл моей просьбы, <имя>, но отбрось всякие сомнения. Чтобы понять, нужно иметь терпение.", progress = "Ты принес реликвии Ша'наара, Назгрейм?", completion = "Тебе сопутствовала удача. Как я и надеялся, мы нашли то, что искали.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9431] = {title = "Разный подход", objective = "Соберите 2 горсти очищающей земли с грохочущих булыжней и отнесите Визло Фингалету на заставу Белого Плеса.", description = "Что син'дорай делает здесь, на этой выветренной вершине в Тысяче Игл, так далеко от роскошных дворцов Луносвета?\n\nВсе очень просто. Мои собратья изгнали меня и сожгли все мои записи о натуральных лекарствах от магической зависимости.\n\nЗдесь я могу продолжать исследования, вот только реагентов у меня нет. Поэтому я буду бесконечно признательна, если ты соберешь немного очищающей земли с грохочущих булыжней, а потом отнесешь ее моему помощнику на заставу Белого Плеса. Булыжни обитают у западных игл.", progress = "Письмо магистра Элозай немного запутанно, но я, кажется, понял, что она хочет от меня. Если у вас есть земля, про которую она упоминала, то я могу положить ее в сосуд для воды из лунного колодца.", completion = "Что? Она не сказала про лунный колодец? Так ведь у нее именно это и было на уме. Признаться, все это выглядит немного странно, но не буду же я в здравом уме лишаться клиента! Тем более - единственного.\n\nКонечно, я бы не сказал, что это очень благоразумно - лезть в поселок ночных эльфов и воровать воду из их колодца, но раз она за это платит, то стоит попробовать.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9432] = {title = "Дорога в Астранаар", objective = "Отправляйтесь в Астранаар в Ясеневом лесу и поговорите с воздаятельницей Паланаарой.", description = "Я рад, что ты <пришел/пришла> на помощь. Тут тебе и правда найдется дело.\n\nМне хотелось бы, чтобы ты <отправился/отправилась> в городок ночных эльфов Астранаар. Он расположен в Ясеневом лесу, огромном лесу к югу от Темного Берега на Калимдоре.\n\nПожалуйста, поговори с воздаятельницей Паланаарой, когда прибудешь туда, и посмотри, чем сможешь помочь местным жителям.", progress = nil, completion = "Всегда приятно увидеть почти знакомое лицо. Наверное, ты Тхаали. Эмиссар Валастраа сообщила мне, что ты скоро будешь.\n\nНароду Ясеневого леса нужна наша поддержка, |3-6(Шаманка). Поговори с жителями Астранаара и узнай, какая помощь им нужна.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9433] = {title = "Проба из Лунного колодца", objective = "На каменной игле, ближайшей к границе с Таланааром, в кустах спрятано устройство управления Роботроном 3000. Найдите ее и включите робота при помощи устройства, которое вам дал Визло. Подведите робота к западному краю Тысячи Игл, где находится застава Альянса под названием Таланаар, и прикажите ему набрать немного воды из Лунного колодца, после чего вернитесь к Визло Фингалету на заставу Белого Плеса.", description = "Да не смотри ты на меня так! Я ж не говорил, что пошлю тебя черпать воду из колодца фляжкой!\n\nЯ вот тут как раз... гм... настраивал одно изобретение для моего клиента. Эта штука, Роботрон, двигается с помощью портативной панели управления, которую я запрятал ее в кустах на границе с Таланааром. Вот, возьми это устройство, найди ту панель и включи робота - а он сам наберет воды.\n\nЕсли бы мой клиент прознал, что мы тут вытворяем с его заказом, он бы меня за уши подвесил!", progress = "Ну и как, сработало?", completion = "Все вышло даже лучше, чем я хотел! Запиши за гоблинами еще одно гениальное изобретение!\n\nЕдинственная проблема в том, что оно безнадежно покрыто пылью. У меня вся жизнь уйдет на то, чтобы его отчистить и вернуть на место.\n\nХотя чего-чего, а времени у меня хватает.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9434] = {title = "Испытание тоника", objective = "Доставьте ящик с реагентами магистра Элозай на Заставу Вольного Ветра.", description = "*Визло берет пробу воды из робота и кладет ее в ящик, где уже лежит земля, добытая с булыжней, и несколько других вещей*\n\nНу вот, заказ магистра Элозай готов. Передай ей, что мне очень понравилось с ней работать и что я желаю ей всяческих успехов в ее исследованиях.", progress = "Вам с Визло удалось собрать реагенты?", completion = "Замечательно, все на месте. Осталось только перемешать и посмотреть, что выйдет. Если этот тоник сработает так, как я предполагаю, то, возможно, я смогу ослабить зависимость от магии у моего народа.\n\nСмотри, Скэритерри, на твоих глазах вершится история! Подумать только - без твоей помощи у меня ничего бы не вышло!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9435] = {title = "Пропавшие кристаллы", objective = "Отберите у нежити посылку с редкими кристаллами и верните ее Ураану из Южнобережья.", description = "Если что и можно с уверенностью сказать про Хилсбрад, так это то, что эти края обречены вечно жить в тени войны. Нападают даже на обозы с камнем.\n\nВ обычной ситуации нас не очень расстраивает утрата строительных материалов, но в последней поставке из Лазуритового рудника был ящик с редкими кристаллами, которые мне не терпится изучить. Отрекшиеся-налетчики перехватили обоз и угнали его на северо-восток, к недостроенной башне. Нам непременно нужны эти кристаллы, <класс>!", progress = "Тебе удалось отобрать у Отрекшихся кристаллы?", completion = "Хвала Свету! Судя по тону письма штейгера, в этом ящике содержались все кристаллы, найденные в руднике. Лишись мы их, может, таких бы и не нашлось.\n\nНе знаю, как тебя и благодарить.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9436] = {title = "Изучение Кровавого Скальпа", objective = "Немет Остроглаз из лагеря Гром'гол попросил вас принести ему тотем Кровавого Скальпа, добыв его у шамана из племени Кровавого Скальпа.", description = "Рад знакомству, <класс>. В последнее время я стал изучать боевые приемы различных племен троллей, и заметил одну особенность. Тролли племени Кровавого Скальпа, живущие в руинах Ткаши и Бал'лал, пользуются той же тактикой, что и Амани северных лесов.\n\nУ них очень необычная магия, и благодаря ей они стали самым могучим племенем в здешних краях. Благодаря этому можно создать сильное оружие против Амани, но нужно докопаться до сути.", progress = "Не подведи меня, Скэритерри. Если нам удастся овладеть магией племени Кровавого Скальпа, быть может, мой народ сможет справиться с угрозой, исходящей от племени Амани.", completion = "Молодец. Вот что любопытно...\n\nНадпись на этом тотеме сделана на языке, незнакомом троллям, зато хорошо известном нам. Она гласит, что носитель сего - союзник элементаля воды по имени Найас и достоин владеть его силой.\n\nНеожиданно, но не так уж плохо, Скэритерри. Я бы хотел, чтобы ты помог мне и на следующем этапе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9437] = {title = "Сумерки \"Гонца Рассвета\"", objective = "Верните груз с \"Гонца Рассвета\" Балиндару Ясной Звезде в деревню Гиблотопь и спасите его первого помощника Итанию из рук тераморцев, из Северной башни.", description = "От тутошних огров не жди ничего, кроме тупых шуток, дурного эля да мигрени.\n\nКогда мой корабль \"Гонец Рассвета\" пристал к здешним берегам, эти негодяи из Терамора смылись с моим грузом и последним членом экипажа. Я добрался сюда в поисках помощи, но эти самые ни на что не годные огры просто тупо смотрели на меня, пока я рассказывал им свою историю. \n\nМогу ли я надеяться на помощь <отзывчивого/отзывчивой:r> |3-1(<раса>), в выяснении того, что случилось с моим грузом и в освобождении Итании из северной башни, к северо-востоку отсюда, куда они ее посадили?", progress = "Ты освободил Итанию и спас мой груз из рук этих проклятых пиратов?", completion = "Благодарю тебя, Вертекс! Как только Итания передохнет, а я закончу подготовку к отплытию, я покину эти влажные пустоши и вернусь обратно к цивилизации.", rewards = "Нарукавники лучникаПропахшие болотным газом латные рукавицыВы получите:\n\n"}
MultiLanguageQuestData['ru'][9438] = {title = "Донесение Траллу", objective = "Отправляйтесь в Оргриммар и доставьте Траллу письмо Назгрела.", description = "Вождь ждал этой вести с того самого момента, как мы ступили в Запределье. Тебе выпала огромная честь доставить ему донесение о маг'харах.\n\nПоторопись, <имя>. Возьми письмо, на нем стоит моя собственная печать. Для Тралла нет вести желанней, чем та, которую ты ему принесешь.", progress = "Ты принес вести из Запределья? Докладывай немедленно!", completion = "*Вы видите, что напряжение уходит с лица Тралла по мере того, как он читает донесение Назгрела* \n\nМой народ... Мы должны отправиться к ним. Мы должны отправиться в Награнд как можно скорее!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9439] = {title = "Потерянный багаж", objective = "Верните советнику Сарофасу в Каргат вещи советника и рапиру советника из крепости Ангор.", description = "Это что же, Каргат? Матушки... Я ожидал что это какое-то поселение, оазис цивилизации в пустыне... \n\nДолжно быть, тут какая-то ошибка. Не может же быть эта клоака, кишащая немытыми, неотесанными дикарями, штаб-квартирой экспедиционных войск! Эти грубые варвары начали ржать во всю глотку, когда я сообщил, что меня ограбили дворфы Черного Железа и скрылись в направлении крепости Ангор. Могу ли я рассчитывать, что ты поможешь мне вернуть мое имущество?", progress = "Ну что уставился?! Я вынужден торчать в этой дыре, не имея возможности даже сменить сорочку! Ты смог добыть мои вещи из этой кротовой норы, которую клан Черного Железа гордо именуют крепостью?", completion = "О, спасибо тебе, Поверсила! Как я мечтал переодеться! \n\nИ моя рапира! Честное слово, без нее я чувствую себя просто голым! \n\nТы будешь вознагражден за труды - никто не скажет, что Сарофас неблагодарен по отношениию к низшим, оказавшим ему помощь!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9440] = {title = "Маленькие кусочки", objective = "Накормите испорченными кусочками мяса домашний скот Заблудших. Потом верните остатки Серсее Певице Заката в Каменор на Болото Печали.", description = "Я совершенствую антидренейское оружие, и ты мне в этом поможешь.\n\nЗаблудшие - родня дренеям, хотя и отсталые, поэтому экспериментирую я на них. От тебя требуется скормить несколько зараженных Скверной кусочков еды их домашнему скоту. Они в свою очередь убьют и съедят эту скотину и попадут под власть проклятия. Я покажу этому анахорету Авууну из Убежища!\n\nИди и поторопись! Ты найдешь Заблудших и их загоны для скота к северо-востоку от Болотного пристанища.", progress = "Ты скормил скоту все оскверненные кусочки? Погоди! А тому глупому человечишке, что сидит у них в клетке? Ему - нет, я надеюсь?\n\nУф! Было бы очень жаль!", completion = "Прекрасно! Жду не дождусь, когда смогу оценить эффект от последней партии!\n\nТы все сделал замечательно, прелесть моя. Я бы дала тебе и больше за то развлечение, которое ты мне устроил, но ты же знаешь, здесь на болотах денег днем с огнем не найти.\n\nНо я уверена, что забава того стоит!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9441] = {title = "Посол к маг'харам", objective = "Вернитесь к Горкану Кровопалу на заставу маг'харов на полуострове Адского Пламени и предложите ему свои услуги.", description = "Принесенные тобой вести чрезвычайно важны. Я бы тотчас отправился в Запределье, но... Неотложные дела требуют моего присутствия в Дуротаре.\n\nКонечно, я немедленно отправлю маг'харам подобающие дары. И отправлю с ними самых опытных и надежных дипломатов. Но все это потребует времени... А мне нужно, чтобы наш представитель отправился туда прямо сейчас!\n\nЯ полагаюсь на тебя, <имя>. Ступай на заставу маг'харов на полуострове Адского Пламени и помоги моим родичам, чем можешь. Не подведи меня, <имя>! От тебя зависит слишком многое.", progress = nil, completion = "Для нас очень важно, что ты предлагаешь нам свою помощь в час нужды! Мы этого не забудем - ни тебе, ни тому, кто тебя прислал.\n\nМы благодарим тебя!", rewards = "Церемониальное облачениеПоножи громовой кузниПлеменной хауберкМаска из шкуры копытняВы получите:\n\n"}
MultiLanguageQuestData['ru'][9442] = {title = "Изнуряющая слабость", objective = "Принесите гриб-сухошляпку заклинательнице земли Риге с заставы маг'харов на полуострове Адского Пламени. Сухошляпки растут только в пещере внутри Глубокого разлома.", description = "Я рада, что ты <согласился/согласилась> помочь нам, <имя>. Наши рубаки заболели, выпив зараженной воды, а у меня нет необходимых ингредиентов, чтобы создать целебную мазь. Мне нужен очень редкий гриб, который называется сухошляпка.\n\nЯ сама бы пошла его искать, но мы должны сохранять наше местоположение в строгом секрете, и рисковать никак нельзя. Единственное место, где на Полуострове Адского Пламени растут сухошляпки, - это Глубокий Разлом, он лежит к югу отсюда.\n\nБудь <осторожен/осторожна>, когда отправишься искать его.", progress = "Тебе удалось отыскать нужный гриб, Выручалкин?", completion = "Горкан хорошо отзывался о тебе. Похоже, он говорил правду.\n\nСпасибо за помощь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9443] = {title = "Так называемый знак Светоносного", objective = "Добудьте знак Светоносного и принесите его Мелару Клинку Рассвета в Бастион, что в Западных Чумных землях.", description = "Некогда я был учеником Утера Светоносного, основателя ордена рыцарей Серебряной Длани. Я сам видел, как неправильно он воспитал принца Артаса. Это привело к гибели моей родины, Кель'Таласа, и я виню Утера в трагедии моего народа! А теперь он покоится в величественной гробнице - скажите, как мило.\n\nМои шпионы доносят, что эти алые идиоты держат на одной из сторожевых башен рядом с воротами Дольного Очага \"святую\" реликвию, связанную с Утером.\n\nОтправляйся в Западные Чумные земли и принеси ее.", progress = "Когда тебе удастся добыть этот \"знак\", мы немного изменим его, сделаем получше.", completion = "Первый шаг сделан. Дай мне знак Светоносного и я превращу его в кое-что более подходящее.\n\nВот тогда-то и придет время моей мести, |3-6(Чернокнижник)!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9444] = {title = "Осквернение гробницы Утера", objective = "Оскверните гробницу Утера и возвращайтесь к Мелару Клинку Рассвета в Бастион, что в Западных Чумных землях.", description = "Вот так-то лучше. Я наложил на этот знак магию скверны.\n\nА теперь отнеси его в место его упокоения в Западные Чумные земли. Воспользуйся оскверненным священным символом перед статуем Утера и оскверни тем самым его гробницу! Для этого придется подобраться поближе.\n\nГробница находится на юго-востоке от руин Андорала. Как выполнишь мое поручение, возвращайся ко мне.\n\nИ поторапливайся, <класс>!", progress = "Итак, дело сделано? Ты уже осквернил гробницу Утера?", completion = "Он прощает меня? ПРОЩАЕТ МЕНЯ?!!!\n\nМне наплевать, что болтает этот старый призрак, но это он во всем виноват! Трагедия Кель'Таласа - результат его некомпетентности!\n\nЯсно одно, оскверненить гробницу не вышло. Убирайся! Я должен все хорошенько обдумать.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9446] = {title = "Гробница Светоносного", objective = "Проводите анахорета Трууна к гробнице Утера в Западные Чумные земли. После поговорите с верховной жрицей Макдонелл из Лагеря Промозглого Ветра.", description = "Тебе удалось добыть знак Светоносного, остается отнести его к гробнице Утера.\n\nСходишь со мной? Это недалеко, а я буду рад твоему обществу. Потом можешь вернуться и рассказать о нашем путешествии верховной жрице Макдонелл.\n\nЧто скажешь, <имя>?", progress = nil, completion = "Тебе явился Светоносный? Поразительно! Это результат твоей самоотверженной помощи анахорету.\n\nДаже если половина историй про Утера - правда, он был великим человеком. А ты, как и он, настоящий герой для всех существ доброй воли на Азероте!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9447] = {title = "Применение целебной мази", objective = "Нанесите целебную мазь на 10 изнуренных маг'харских рубак рядом с заставой маг'харов на полуострове Адского Пламени по просьбе заклинательницы земли Риги.", description = "Из того, что ты мне <принес/принесла>, я приготовила мазь, которая восстановит силу наших рубак. Вот, возьми. Нанеси ее на всех изнуренных рубак, которых увидишь, и возвращайся ко мне.", progress = "С возвращением, Менгиле. Ты выполнил мое задание?", completion = "Да благословят тебя духи, Менгиле. Маг'хары в долгу перед тобой.", rewards = "Палица заклинателя землиТотемный посохКинжал волчьего всадникаЛук маг'харовВам дадут возможность выбрать одну из следующих наград:\n\nСбалансированный каменный кортик\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9448] = {title = "Милость к проклятым", objective = "Убейте 3 проклятых из племени Заблудших, потом вернитесь к анахорету Авууну в Убежище на Болото Печали.", description = "Эта ведьма из эльфов крови - Серсея Певица Заката - заражает порчей Заблудших, я знаю это, и все тут! Я не знаю, зачем и как она это делает, но результаты ужасают. Некоторые из Заблудших еще сильнее подпали под влияние порчи, под воздействие еще более мощных энергий Скверны!\n\n<класс>, не проникаешься ли ты жалостью к этим несчастным существам? Они не должны прожить остаток дней своих под действием проклятья.\n\nТы найдешь этих несчастных в Болотном пристанище, по дороге к востоку отсюда.", progress = nil, completion = "Дело сделано. Я благодарю тебя за проявленное милосердие, однажды попав под власть того, что им скармливала Серсея, они уже были безнадежны. Сейчас они обрели покой, и я надеюсь, мое наблюдение за остальными принесет плоды, и они смогут исцелиться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9449] = {title = "Зов земли", objective = "Поговорите с духом долины в Священной роще в долине Аммен.", description = "Выслушай меня, <имя>. Пришло время тебе поговорить с духами стихий напрямую.\n\nВпрочем, соблюдай осторожность. Мы оказались в этом мире случайно и невольно принесли ему зло, разъярили духов земли и нарушили природное равновесие.\n\nЕсли ты хочешь создать тотем Земли, поговори прежде с духом долины. Он находится в Священной роще, в холмах на северо-западе отсюда.", progress = nil, completion = "Не думал, что кто-то из твоего народа отважится искать у меня мудрости, после того, что вы натворили на наших островах! Впрочем, храбрости тебе не занимать, так что знаниями я с тобой все же поделюсь.\n\nЗемля у тебя под ногами - основа всего сущего. Небо, вода, даже великий огонь - все опираются на ее плечи. Прочие стихии порой крушат все на пути своем, и лишь земля стоит крепко. Она дарует силу и стойкость всем, живущим на ней.\n\nА теперь покажи, на что ты способен, шаман.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9450] = {title = "Зов земли", objective = "Убейте 4 неупокоенных духов земли и возвращайтесь к духу долины в Священную рощу в долине Аммен.", description = "Крушение корабля дренеев привело к нарушению природного равновесия в этой долине. Духи Земли в ярости обратились против других стихий, пытающихся утихомирить их. Вскоре ты поймешь, как важна гармония стихий для их познания.\n\nИтак, я поручаю тебе восстановить исконное равновесие. За моей спиной располагается роща, в которой духи Земли воюют с тремя другими стихиями. Наведи там порядок.", progress = "Стихии так и не пришли в равновесие, Шамакс.", completion = "Что ж, молодец. Сократив число неупокоенных духов ты помог восстановить равновесие стихий, невольно нарушенное твоим народом.\n\nПомни об этом, идя путем шамана и призывая нашу силу. Храни равновесие.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9451] = {title = "Зов земли", objective = "Отнесите кристалл Земли Фирманваару на место крушения в долине Аммен.", description = "Я передам тебе частицу моего физического облика, и ты положишь ее в основу своего тотема Земли. Отнеси эту частицу тому, кто послал тебя сюда.\n\nМы с тобой будем связаны навеки. До самой смерти силы Земли будут верно служить тебе, а отплатишь ты нам в тот миг, когда самая плоть твоя станет землей.\n\nПостарайся распорядиться своей силой мудро.", progress = "Падшие и дренеи познают неведомые прежде тайны стихий.\n\nТы несешь мне все необходимое для создания тотема Земли?", completion = "Молодец, Шамакс. Восстановив природное равновесие в роще, ты достиг мира и согласия между стихиями этого мира и дренеями. Быть может, это привлечет на нашу сторону тех, кто с презрением смотрит на избравших путь шамана?\n\nЯ создам для тебя тотем, который позволит тебе подчинить силу Земли. Со временем тебе откроются и другие тайны земли.\n\nВозьми свой тотем, шаман.", rewards = "Вы также получите:\n\nТотем земли"}
MultiLanguageQuestData['ru'][9452] = {title = "Деликатесный красный луциан", objective = "Поймайте 10 красных луцианов рыболовной сетью дренеев. Отдайте рыбу и сеть Диктинне на острове Лазурной Дымки.", description = "Я обнаружила, что в этих водах много красного луциана - а это очень вкусная рыба! Сетью я могла бы наловить столько, что хватило бы на дюжину дренеев! К сожалению, недавно во время рыбалки на меня напала тварь, которую называют мурлоком. Из-за ран я не могу ловить рыбу. Помоги мне!\n\nПоставь эту сеть в водах Хрустальной реки на востоке, и у тебя будет огромный улов.\n\nЧто скажешь? Не забудь потом вернуть сеть.", progress = "Остерегайся мурлоков: это странные и крайне надоедливые существа.", completion = "Надеюсь, мурлоки тебя не тронули, Шамакс. Я глубоко тебе признательна.\n\nМожет, научить тебя ловить рыбу? Я готова подарить тебе удочку и блесну.", rewards = "Вы получите:\n\nУдочкаБлеснаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9453] = {title = "Поиски Актеона", objective = "Отнесите ящик красного луциана Актеону на Лазурную заставу.", description = "Великолепная работа, <имя>. Наш народ будет признателен тебе за рыбу. Кстати, не отнесешь ли наловленного красного луциана Актеону на Лазурную заставу?\n\nЕго будет несложно отыскать - он ждет этот улов.", progress = "Тебе нравятся мои доспехи? Я сделал их сам! Они отличаются от привычных нам, но зато очень удобные.", completion = "Бедная Диктинна... Мурлок ее сильно напугал.\n\n&lt;Актеон вздыхает.&gt;\n\nНадеюсь, она скоро оправится от ран...\n\nПолагаю, ты ищешь работу. Чего-чего, а этого на Лазурной заставе хватает!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9454] = {title = "Великая охота на лунных оленей", objective = "Принесите 6 кусков вырезки лунного оленя Актеону на Лазурную заставу.", description = "Ты начинаешь завоевывать себе репутацию, <имя>. Не хочешь поучиться охоте?\n\nВ Дреноре наши величайшие охотники гнали дичь, похожую на лунных оленей здешних мест, талбуков.\n\nЕсли ты настоящий дреней, отправляйся в лес и убей столько оленей, чтобы весь мешок набить мясом.\n\nОни пасутся на юге от Лазурной заставы. Остерегайся их рогов!", progress = "Шкура у оленей тонкая, зато мясо нежное, сочное.", completion = "Молодец, Шамакс, молодец!\n\nПока ты охотился, я приготовил тебе немного вырезки. Может, ты и от рецепта не откажешься?", rewards = "Вы получите:\n\nЖареная вырезка лунного оленяРецепт: жареная вырезка лунного оленяCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9455] = {title = "Странные находки", objective = "Отнесите слабо мерцающий кристалл экзарху Менелаусу на Лазурную заставу.", description = "Похоже, найденный тобой в теле ночного ловца-недоростка кристалл – часть \"Экзодара\". Это объясняет необычную внешность и поведение некоторых животных этих земель.\n\nОтнеси кристалл на Лазурную заставу. Экзарху следует узнать о твоей находке.", progress = "Что ты нашел? Где?", completion = "Как такая вещь могла оказаться в желудке ночного ловца? Не заражены ли и другие звери осколками от разбившегося корабля?", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9456] = {title = "Истребление ночных ловцов, остров 2...", objective = "Уничтожьте 8 зараженных ночных ловцов – недоростков и вернитесь на Лазурную заставу.", description = "Не буду скрывать от тебя горестного значения твоей находки. Здесь, несомненно, наша вина. До нас доходили сообщения об осколках кристаллов в реке на востоке, но мы не обращали на них внимания. Теперь же остается либо сидеть и сокрушаться о случившейся трагедии, либо постараться ограничить распространение заразы.\n\nЕсли тебе такое дело по плечу, отправляйся в лес и постарайся уничтожить как можно больше зараженных ночных ловцов.", progress = "Необходимо остановить распространение инфекции. Судя по сведениям с Кровавой заставы, дело плохо. Мы должны немедленно принять меры!", completion = "Надеюсь, еще не поздно...", rewards = "Усиленные плетеные сапогиНаручи охотникаСлегка поношенные наручиВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9457] = {title = "Необычный посетитель", objective = "Воспользуйтесь даром Найаса неподалеку от алтаря Найаса и призовите этого элементаля воды. Одолейте его и принесите сердце Найаса Немету Остроглазу в лагерь Гром'гол.", description = "Так значит, за племенем Кровавого Скальпа и их необычной магией стоит Найас? Признаться, не думал, что расследование пойдет таким путем, но неважно, полученные сведения нам пригодятся.\n\nНедалеко от северо-западной части побережья находится остров, населенный малыми элементалями воды. Там есть грубая каменная плита, которая, должно быть, служила троллям алтарем для поклонения. Отнеси найденный тобой тотем на этот алтарь. Посмотрим, не удастся ли выманить этого Найаса и перелить его силу в более подходящую форму.", progress = "Какие вести о Найасе ты несешь?", completion = "Я чувствую, как много первозданной силы заключено в этом камне, Таквер. Надо отправить его в Луносвет, нашим магистрам - пусть изучают. Я уверен в одном - он пригодится в нашей борьбе против Амани.\n\nТы оказал нам неоценимую помощь, добыв этот камень. Я прослежу, чтобы Странники узнали имя |3-1(таурен), нашедшего его.", rewards = "Клинок экзотической магииНаплечники дикой энергииБашмаки джунглепроходцаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9460] = {title = "Объединенными усилиями", objective = "Украдите у предводительницы часовых кружевной носовой платок и принесите его Келтусу Темному Листу.", description = "Келтус Темный Лист для доклада явился!\n\nДа, а ты, собственно, кто <такой/такая>? Если хочешь получить мои донесения, сначала помоги мне.\n\nЯ тут собираюсь напасть на часовых-шпионов, но сначала хочу выслать вперед мою верную Шептунью. Однако ей нужен запах, чтобы знать, на кого нападать.\n\nУж конечно, тебе не составит труда подкрасться и стянуть какую-нибудь вещицу у их предводительницы?", progress = "Ну что, получилось?", completion = "Отлично! По этому запаху Шептунья без труда найдет дорогу...", rewards = "Вы получите:\n\nСтопка донесений"}
MultiLanguageQuestData['ru'][9461] = {title = "Зов Огня", objective = "Найдите пророка Велена в Чертоге Света Экзодара.", description = "Пророк заинтересовался тобой, услышав об успешном прохождении испытания. Прежде чем создать Тотем огня, тебе следует поговорить с ним.\n\nМало кому выпадает эта честь, спеши в Экзодар на встречу с Пророком!", progress = nil, completion = "Приветствую, Небрить. Я ждал тебя. Надеюсь, ты сегодня в добром здравии?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9462] = {title = "Зов Огня", objective = "Поговорите с Тулууном на Лазурной заставе на острове Лазурной Дымки.", description = "<имя>! Пришло время двинуться дальше по пути духов. Отыщи Тулууна, шамана Лазурной заставы. Он начнет обучать тебя пониманию и усмирению силы пламени.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9463] = {title = "Ради науки", objective = "Принесите 8 побегов корнехватов анахоретке Фатиме на Лазурную заставу.", description = "Выяснилось, что побеги хлестунов, которые растут на острове, имеют целебные свойства. При правильной обработке из них получается сильнодействующая лечебная мазь. К сожалению, на Лазурной заставе так много раненых дренеев, что никаких запасов не хватает.\n\nНашу хрупкую гостью нашли вчера возле Хрустального ручья. Если ты принесешь мне побеги – кто знает, может быть, удастся ее спасти.\n\nКорнехватов можно отыскать на юге и на востоке от Лазурной заставы.", progress = "Боюсь, что состояние нашей больной стремительно ухудшается.", completion = "Будем надеяться, что мазь укрепит ее дух и поможет больной встать на ноги!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9464] = {title = "Зов Огня", objective = "Поговорите с Пламенравом на Тлеющей поляне на острове Лазурной Дымки.", description = "И снова тебя ожидает испытание. На сей раз ты <должен/должна> понять хаотическую составляющую огня, если собираешься создать тотем, обуздывающий его силу.\n\nНа северо-востоке находится священное место огня, именуемое Тлеющая поляна. Среди ее опаленных деревьев стоит Пламенрав, могущественный элементаль огня, и с ним-то тебе и предстоит поговорить.\n\nСтупай к нему, и да хранят тебя все стихии Азерота.", progress = nil, completion = "В твоих глазах пылает жажда расти над собой и постигать новое. Отлично!\n\nТулуун послал тебя сюда, потому что верит, что ты -способный ученик и сможешь решить проблему, вызванную крушением вашего Экзодара.\n\nПосмотрим.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9465] = {title = "Зов Огня", objective = "Верните ритуальный факел Пламенраву на Тлеющую поляну на острове Лазурной Дымки.", description = "Один из моих соплеменников, Спесивец, сошел с ума после крушения вашего корабля. Он начал требовать от местных совухов поклонения.\n\nЭто необходимо прекратить! Никто не смеет выдавать себя за бога! Придется тебе восстановить равновесие.\n\nПервым делом надо отнять у них ритуальный факел, который безумные дикие совухи утащили в логово племени Тихвой на западе.\n\nВерни мне этот факел.", progress = "И где же факел?", completion = "Видишь, он не гаснет. Это работа Спесивца, символ его заносчивости. Пламя должно поглощать то, что горит, и погибать само, чтобы возродиться вновь.\n\nЯ помог бы тебе затушить факел, но он должен пылать, чтобы ты смог справиться с Спесивцем. Пусть пока горит...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9466] = {title = "Разыскивается: Свирепая Черноскребка", objective = "Принесите когти Черноскребки капитану следопытов Венн'рену в Соколиный дозор на полуострове Адского Пламени.", description = "Согласно приказу капитана следопытов, объявлена награда за голову крайне опасной твари, матриарха камнедеров, известной как Свирепая Черноскребка.\n\nВ последний раз ее видели в пещерах на дне Глубокого Разлома. В качестве доказательства смерти Черноскребки охотники должны принести ее когти.", progress = "Ты слышал про Черноскребку?", completion = "Ты достойный, |3-6(Жрец), Менгиле. Эта тварь унесла жизни многих охотников.\n\nВозьми награду, ты ее заслужил.", rewards = "Рукавицы Солнечного СкитальцаСапоги Венн'ренаТонкий кушакВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9467] = {title = "Зов Огня", objective = "Добудьте пепел Спесивца и принесите его и ритуальный факел Пламенраву на Тлеющую поляну на острове Лазурной Дымки. Вы можете воспользоваться сферой возвращения, чтобы телепортироваться к Пламенраву.", description = "Совухи из прибежища Лунных Крыльев на острове Серебряной Дымки, что на юго-западе, приняли Спесивца за бога и начали поклоняться ему. На самом деле он - падший элементаль, которого следует остановить. Этот факел - ключ к его низвержению.\n\nСпесивец требует, чтобы совухи устраивали в его честь возжигания. Устрой возжигание, и он явится на зов. Убей его и собери пепел. Затем вернись ко мне при помощи этой сферы.", progress = "Даже не заговаривай со мной, пока не добудешь пепел Спесивца.", completion = "Сегодня ты усвоил важный урок. Это история о возрождении из пепла.\n\nВ нашем первом разговоре я упоминал, что огонь не только разрушает, но и обновляет. Благодаря тебе Спесивец не просто уничтожен;, он спасен - потому что восстанет из праха.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9468] = {title = "Зов Огня", objective = "Отнесите пепел Спесивца Тулууну на Лазурную заставу на острове Лазурной Дымки.", description = "Сегодня тебе удалось далеко продвинуться по пути постижения сути огня. Относись к нему с уважением, или пламя пожрет тебя!\n\nЯ оставил тебе немного пепла Спесивца. Используй его для создания тотема огня и помни все, чему ты <научился/научилась>.\n\nА теперь возвращайся к Тулууну.", progress = "Похоже, пламя опалило тебя. Насколько тебе удалось приобщиться к стихии огня?", completion = "Ты прошел очищение огнем и вышел из него обновленным, Небрить. Эти испытания подобны тем, через которые пришлось пройти дренеям. И, спасая Спесивца от него самого, тебе удалось установить связь со стихией огня этого мира.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9469] = {title = "Встреча с Перобородом", objective = "Навестите дворфа Пероборода в его домике. Если там его нет, то поищите, где он может быть.", description = "Когда меня, наконец, удостоят аудиенции с Фалстадом Громовым Молотом, я хочу, чтобы вместе со мной пошел один из наших лучших представителей среди дворфов.\n\nБольшим уважением среди них пользуется Перобород – во-первых, за его потрясающее мастерство дрессировки грифонов, а во-вторых, за его мудрость. Если кто и сможет убедить Фалстада Громового Молота, то только он.\n\nЯ бы сходил к Перобороду сам, но мне нельзя покидать Заоблачный Пик, потому что аудиенцию могут назначить в любой момент. Пожалуйста, сходи к нему и спроси, не согласится ли он поговорить со мной. Перобород живет на юге.", progress = nil, completion = "В дневнике Пероборода очень много записей. Вы пролистываете его до конца и ищете в тексте информацию о том, где может быть хозяин.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9470] = {title = "Жест доброй воли", objective = "Убейте знахаря Май'джина и его питомца-паука Чаказа по поручению посла Руалета с Заоблачного пика.", description = "Кроме дворфов и их грифонов во Внутренних землях живут еще и лесные тролли.\n\nЭти тролли считают, что дворфы оскверняют из священные земли, и никогда не упускают возможности напасть на грифонов. Отличный шанс снискать уважение клана Громового Молота – убить главу племени Сухокожих, знахаря Май'джина. Это поумерит у троллей наглости. Май'джин живет в гроте Богена, это к западу от Шадра'Алора.", progress = nil, completion = "Большое спасибо, Дэломар. Клан Громового Молота будет рады узнать, что противостоит племени Сухокожих не в одиночку. Пусть тролли знают, что на нашей стороне грифоны – глядишь, наглость свою и поумерят.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9471] = {title = "Охота на хищников", objective = "Убейте 10 облезлых среброгривов и 5 среброгривых волков по поручению посла Руалета с Заоблачного пика.", description = "Дворфы из клана Громового Молота - верные товарищи и отличные дрессировщики для грифонов, у которых полно врагов, в особенности среди лесных троллей.\n\nОднако помимо троллей у них есть и естественные враги, например, волки. Один волк грифону не страшен, но они часто нападают стаей, потому что другой добычи здесь мало. Если уменьшить поголовье волков, то местные леса станут чуть безопаснее для грифонов, а дворфы будут нам благодарны.", progress = nil, completion = "&lt;Посол Руалет кивает и берет у вас отчет.&gt;\n\nПрекрасная работа. Клан Громового Молота обязательно узнает о том, что поголовье среброгривов уменьшилось. Когда я встречусь с их предводителями, я непременно прослежу за тем, чтобы твои старания не прошли незамеченными перед Альянсом. Пожалуйста, прими это в знак моей благодарности, Дэломар.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9472] = {title = "Любовница Арелиона", objective = "Выманите Виеру Шепот Солнца из поселения и примените к ней свиток воздаяния Каринды по приказу магистра Каринды из Соколиного дозора.", description = "У Арелиона было столько важных дел, а он тратил свое время на какую-то любовницу!\n\nТеперь-то мне все ясно. Виера Шепот Солнца, эта маленькая потаскушка... Я покажу ей, как переходить дорогу магистру!\n\nВозьми свиток. Разыщи Виеру и вымани ее из города. Когда это удастся, прочитай над ней заклинание.\n\nАрелион упоминал, что эта маленькая дрянь обожает вино, которое делают друиды. Я думаю, его можно найти в Кенарийском приюте, как раз в Зангартопи, к западу отсюда.", progress = nil, completion = "Отлично! Теперь эта предательница больше никогда не соблазнит ничьего мужа.\n\nВот, возьми за труды. Надеюсь, все останется между нами, Джонниди.", rewards = "Вы получите:\n\nОбручальное кольцо Каринды"}
MultiLanguageQuestData['ru'][9473] = {title = "Другое решение", objective = "Принесите 5 луковиц лазурного львиного зева Дедалу на Лазурную заставу.", description = "Эта девушка слишком слаба, чтобы ей помогла мазь. Должен быть другой способ...\n\nЛеса Лазурной Дымки хранят много тайн. Например, здесь можно отыскать редкое растение, которое зовется лазурный львиный зев. Некоторые считают его настоящей панацеей от всех болезней.\n\nТы сможешь отличить его от других растений Лазурной Дымки по цвету. Кроме того, он растет только у подножия лазурных сосен. Спеши!\n\nОстерегайся корнезубов, они питаются лазурным львиным зевом.", progress = "Время на исходе! Торопись!", completion = "Смотри, как растение исцеляет больную.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9474] = {title = "Знак Светоносного", objective = "Добудьте знак Светоносного и принесите его анахорету Трууну в Лагерь Промозглого Ветра, что Западных Чумных землях.", description = "То недолгое время, что я пробыл на Азероте, я посвятил изучению великих героев. Славнейший из них Утер Светоносный, преданный самым лучшим своим учеником, Артасом.\n\nЯ бы хотел почтить его память и отнести одну из утраченных им вещей к его гробнице. Говорят, что сторонники Алого ордена держат на одной из сторожевых башен рядом с воротами Дольного Очага реликвию Утера.\n\nПрошу тебя, <класс>, ступай и принеси ее.", progress = "Знак Светоносного - могущественный символ веры Утера в Свет.", completion = "Спасибо, |3-6(Воин)! Возвращение реликвии - большая радость для всех, кто чтит память Утера Светоносного.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9475] = {title = "Похищенные яйца", objective = "Соберите 5 яиц грифона и принесите их послу Руалету на Заоблачный пик.", description = "Осмотрев скелет, вы понимаете, что это все, что осталось от бедного Пероборода. В одной руке скелет сжимает истлевший кусок бумаги, который вы осторожно вынимаете и разворачиваете. На бумаге от руки нарисована карта и нацарапаны какие-то заметки.\n\nСудя по всему, это схема Шадра'Алор, и три местных храма тут отмечены крестиками - должно быть, именно там находятся украденные яйца. Вы прячете карту в сумку, чтобы потом, в безопасном месте, рассмотреть ее поподробнее.", progress = "Судя по вашему виду, вы принесли мне дурные вести. Что вам удалось узнать?", completion = "&lt;Вы отдаете послу яйца и рассказываете о том, что обнаружили в лачуге Пероборода и в Шадра'Алоре.&gt;\n\nТролли из племени Сухокожих убили Пероборода?\n\n&lt;Риалет приходит в ужас, услышав об ужасной смерти дворфа и о ее последствиях&gt;\n\nЯ понимаю, почему он пошел искать яйца сам, но лучше бы он привел с собой подмогу. Вне всяких сомнений, его смерть приведет Фалстада Громового Молота в ярость, и моя аудиенция будет вновь отложена на неопределенный срок.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9476] = {title = "В поисках Пероборода", objective = "Отправляйтесь в Шадра'Алор и поищите следы Пероборода.", description = "В последних записях дневника Перобород выражает свое беспокойство участившимися нападениями троллей из племени Сухокожих на грифонов клана Громового Молота и постоянными кражами грифоньих яиц. Разведка в маленьком поселении Сухокожих не дала никаких результатов.\n\nВ последней записи Перобород пишет о своих подозрениях насчет того, что за этими набегами может стоять знахарь Майд'жин, а в самом последнем, поспешно накарябанном предложении говорится о том, что дворф собирался пойти в Шадра'Алор и поискать яйца там.", progress = nil, completion = "На алтаре лежит куча костей, с виду принадлежавших дворфу. Никаких особых примет не видно, но вы решаете осмотреть тело и убедиться в том, что это и впрямь останки Пероборода.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9483] = {title = "Изысканные удовольствия жизни", objective = "Мы, конечно, отправились в паломничество, но это вовсе не значит, надо отказываться от всех радостей жизни. Кажется, прошло столетие с той поры, как я пробовала хорошее вино.\n\nДа за бутылку кенарийского настойки я и убить могу!\n\nЗнаю, знаю, я очень опустилась, если готова пить вино ночных эльфов.", description = nil, progress = "Мы, конечно, отправились в паломничество, но это вовсе не значит, надо отказываться от всех радостей жизни. Кажется, прошло столетие с той поры, как я пробовала хорошее вино.\n\nДа за бутылку кенарийского настойки я и убить могу!\n\nЗнаю, знаю, я очень опустилась, если готова пить вино ночных эльфов.", completion = "Думаю, мы можем подружиться. Давай со мной, мы ведь не хотим ни с кем делиться, правда?", rewards = nil}
MultiLanguageQuestData['ru'][9484] = {title = "Приручение зверя", objective = "Приручите безумного дракондора с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.", description = "Несомненно, тебе неоднократно доводилось охотиться на зверей и убивать их как ради пропитания, так и ради самозащиты. Но теперь тебе уже по силам подружиться с ними и использовать их способности в своих целях. Я научу тебя, как это сделать.\n\nВот, возьми этот магический хлыст приручения. Он позволяет временно подчинить себе дикого зверя и заставить его сражаться на твоей стороне. Начни с безумного дракондора, сравнительно мирной птицы. Они водятся поблизости от обители Странников. Когда управишься, возвращайся ко мне.", progress = "Покорился ли тебе дракондор?", completion = "Чтобы выдержать яростные атаки дракондора, тебе потребовалось немало мужества... Ну что, хватит ли тебе сил продолжить обучение?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9485] = {title = "Приручение зверя", objective = "Приручите мрачницу с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.", description = "Молодец, <имя>! Ты быстро обучаешься понимать природу.\n\nМрачница – хитроумный охотник, она сочетает стремительность дракондора с яростью прыголапа. Мрачницы водятся к югу от реки Элрендар и нападают на злосчастных путников, которые забредают в Призрачные земли.\n\nИспользуй этот последний хлыст приручения, чтобы подружиться с мрачницей, а когда управишься, возвращайся ко мне.", progress = "Покорилась ли тебе мрачница?", completion = "Ну что ж, Тсой, как видишь, больше мне тебя учить нечему. Ты уже знаешь, как подружиться с теми, кто прежде был для тебя лишь добычей. Теперь тебе осталось лишь выбрать себе союзника, наиболее подходящего тебе по повадкам.", rewards = "Вы изучите:\n\nУрок приручения\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9486] = {title = "Приручение зверя", objective = "Приручите взрослого прыголапа с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.", description = "Взрослый прыголап - ловкий охотник. Сдружиться с ним непросто - ведь поначалу он считает тебя добычей. Но ты не отчаивайся.\n\nИспользуй хлыст приручения, подчини себе эту крупную кошку и попробуй поохотиться вместе с ней. Прыголапы водятся в Лесах Вечной Песни повсюду, и порой подходят совсем близко к жилью. Когда управишься, возвращайся ко мне.", progress = "Ну что, удалось тебе поохотиться вместе с прыголапом?", completion = "Да, у тебя достаточно сил и упорства. Тебе осталось пройти последнее испытание, после чего ты сможешь приручать зверей без помощи магии...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9487] = {title = "Волшебные разорители", objective = "Чародей Вандрил хочет, чтобы вы принесли ему 10 осколков тайной магии.", description = "Волшебные разорители – создания, наделенные неземной силой. Они защищены крепкой броней, их удары сокрушительны. Однако ты можешь обойти их защиту и избежать их атак. Твое заклинательское искусство дает тебе неоспоримые преимущества, <имя>.\n\nОтправляйся в башню Утренней Звезды и разнеси в клочья этих магических стражей. Из останков собери осколки кристаллизованной магический энергии, а потом возвращайся ко мне. Башня Утренней Звезды находится на востоке, за озером.", progress = "Надеюсь, тебе удалось подобраться к этим тварям?", completion = "Как же непродуктивно тратить магию на создание тварей, обладающих только физической силой! В конце концов, разве не ради грубой силы мы заключили союз с низшими расами?\n\nХорошо, что ты уничтожил их, теперь мы используем эти осколки для более подходящих целей.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9488] = {title = "Простое одеяние", objective = "Чародей Вандрил хочет, чтобы вы принесли ему 15 кусков льняной ткани и паутинную железу паука-прядильщика.", description = "Те осколки тайной магии, что ты <добыл/добыла>, пригодятся как нельзя лучше.\n\nСпрашиваешь, для чего? Да для изготовления замечательного одеяния для <такого/такой:c> <класс>, как ты!\n\nНам нужно всего-то немного льняной ткани и паутинная железа. Железу можно добыть у любого паука-прядильщика, лучше у предварительно убитого.", progress = "Это одеяние нельзя закончить без некоторых необходимых материалов. Но ведь ты и сам это знаешь, не так ли?", completion = "Тебе незачем знать все тонкости создания магического одеяния, Гримслок, просто запоминай, что мне от тебя нужно, и приноси.\n\nБуду с тобой честным – того, что ты уже принес, хватит на несколько одеяний. Выручка с их продажи с лихвой покроет все мои издержки на изготовление твоего одеяния, и даже останется на что-нибудь приятненькое. Похоже, это я тебя благодарить должен!", rewards = "Вы получите:\n\nОдеяние из ткани маны"}
MultiLanguageQuestData['ru'][9489] = {title = "Поднять боевой дух", objective = "Примените \"Слово Силы: Стойкость\" к 6 следопытам из лесов Вечной Песни на Тропе Мертвых.", description = "А, <имя>! Хорошо, что ты здесь. Яростные атаки Плети вселяют отчаяние в души наших городских стражей...\n\nСтупай скорее на Тропу Мертвых к югу от города. Там стоят в дозоре Джела и ее следопыты. Благослови их, наполни их силой Света!", progress = nil, completion = "Следопыты говорят о твоем приходе с почтением и благоговением! Теперь ты видишь, как служит нам Свет? Он дает нам силы помогать другим, но только после того, как мы помогли себе сами...", rewards = "Вы получите:\n\nОдеяния Луносвета"}
MultiLanguageQuestData['ru'][9490] = {title = "Матриарх камнедеров", objective = "Добудьте когти Свирепой Черноскребки, которая обитает в Глубоком Разломе и принесите их Икану в храм Телхамат на полуострове Адского Пламени.", description = "Все камнедеры – отвратительные, крайне опасные и злобные существа. Впрочем, обычные камнедеры – просто ручные зверюшки по сравнению с их матриархом Свирепой Черноскребкой.\n\nОна убила моего кузена и сожрала его безо всякой пощады. Ничего, в один прекрасный день она за это заплатит. Принеси мне доказательство ее смерти, и я отдам тебе все, что у меня есть. Договорились?\n\nЧерноскребка обитает в пещере на дне Глубокого Разлома. Удачи тебе!", progress = "Ты принес доказательство смерти Черноскребки?", completion = "Да, я помню эти ужасные когти.\n\nВот, возьми, Вродехант. Вряд ли эту тварь было так просто убить, так что ты заслужил свою награду.", rewards = "Рукавицы защитникаСапоги заклинателя землиКушак странника пустошейВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9491] = {title = "Не откажусь", objective = "Эраланна из Транквиллиона хочет, чтобы вы добыли исцарапанное золотое кольцо из катакомб Амани.", description = "Вчера сюда заявился до неприличия богатый торговец. Говорил о каком-то кольце \"чрезвычайной археологический важности\", которое вроде бы заперто в одном из бесчисленных погребальных сундуков в катакомбах Амани. Потом он еще долго рассказывал, сколько готов за это самое кольцо отвалить.\n\nДавай так: я добуду воровской инструмент, и если тебе удастся принести колечко, то отсыплю тебе столько, что на десяток колечек хватит!", progress = "Не говори мне, пожалуйста, что у тебя нет кольца! Иначе этот купец найдет другого желающего.", completion = "Так это то самое кольцо и есть? Смотреть не на что. Но ты сама знаешь, сколько слухов ходит вокруг этого эльфийского хлама...\n\nКстати, не будем забывать о твоей награде - не стесняйся, можешь прокутить ее прямо здесь, сестричка!", rewards = "Вы получите:\n\nНабитый серебром мешочек"}
MultiLanguageQuestData['ru'][9492] = {title = "Новый поворот событий", objective = "Принесите кулак вождя Каргата командиру армии Данату Троллебою в Оплот Чести.", description = "Запределье живет в постоянном ожидании нападения орков, такова печальная истина. Было время, когда Сыны Лотара думали, что смогут оплатить безопасность Оплота Чести ценой собственной крови, но и это не принесло мира.\n\nТеперь Сыны не потерпят на своих землях никаких орков - ни зеленых, ни кориченевых, ни красных! Мы победим их или умрем, сражаясь. У нас есть шансы на победу, если мы сразимся с ними в цитадели Адского Пламени. Принеси мне оружие их самозванного вождя Каргата Острорука, и я щедро награжу тебя.", progress = "Ты принес мне подтверждение гибели \"вождя\" Каргата Острорука?", completion = "Отличная работа, Эарилас. Твоя победа - это сокрушительный удар по оркам из цитадели Адского Пламени.\n\nЯ должен обсудить с боевым командиром Ромусом наши дальнейшие действия. Мы хотим вынудить орков Скверны уйти в глухую оборону. Теперь, получив подкрепление, мы способны на нечто большее, чем просто оборонять Оплот Чести.", rewards = "Мантия обновленияЖезл страдания ПустоклятаВам дадут возможность выбрать одну из следующих наград:\n\nМедальон доблестного стражаМесть Налико\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9493] = {title = "Элита Орды Скверны", objective = "Убейте 8 легионеров клана Изувеченной Длани, 4 центуриона клана Изувеченной Длани и 4 воителей клана Изувеченной Длани по приказу боевого командира Ромуса из Оплота Чести.", description = "Мы мало что знаем об Орде Скверны, хотя за информацию заплачено многими жизнями.\n\nКаргат Острорук командует безжалостными, закаленными в боях воинами, чьи возможности к тому же усилены магией скверны. У этого войска есть своя элита – легионеры, воители и центурионы из клана Изувеченной Длани. Они внушают страх обычным солдатам и исполняют роль офицерского состава.\n\nЕсли мы хотим добиться хоть каких-то успехов в сражении с Ордой Скверны, сначала надо лишить ее командования.", progress = nil, completion = "Какие хорошие новости, Эарилас, в самом деле. Если мы разберемся с цитаделью Адского Пламени, то сможем начать охоту за орками Скверны по всему полуострову, да что там – по всему Запределью!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9494] = {title = "Угли Скверны", objective = "Принесите уголь Скверны волхву Забраксис из Оплота Чести.", description = "Наши твердолобые азеротские академики слишком засиделись в своих башнях. Пришло время показать им, что такое настоящие исследования! Дескать, они боятся играть с огнем. Ничего, как только у меня окажется огонь, я вдоволь с ним поиграю!\n\nВ Разрушенных залах цитадели Адского Пламени главный чернокнижник Пустоклят достиг невероятного магического мастерства, используя силу двух странных жаровен. <имя>, возьми сосуд, в котором он хранит угли Скверны, достань один уголь и принеси мне.", progress = "*Волхв Забраксис оглядывается на Амитиэль Странницу Туманов и понижает голос\"\n\nНу что, где ээээ... уголь?", completion = "Отлично, отлично! В мои планы не входит повторять подвиги чернокнижника Пустоклята, но надо быть полным дураком, чтобы не замечать силы угля Скверны.\n\nПравда, исследования вроде моего хотят запретить, так что все нужно держать в секрете. Назгрейм, ты ведь никому не расскажешь?", rewards = "Неустрашимые боевые рукавицыПояс с выгравированными рунамиЭполеты экспедиционного разведчикаПерчатки возвращенияСапоги викарияВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][9495] = {title = "Воля Вождя", objective = "Принесите кулак вождя Каргата Назгрелу в Траллмар.", description = "Вырвать орков из уз нашей проклятой крови было не так просто, <имя>. Вождь Тралл повидал слишком много героев, которые пали под ударами судьбы. Похоже, теперь к ним следует присоединить и Каргата Острорука.\n\nВ Разрушенных залах цитадели Адского Пламени Каргата называют \"вождем\" Орды Скверны. Он и орда его безумных, жаждущих крови орков не остановятся, пока не сотрут Траллмар с лица земли. Вождь Тралл приказал нам любой ценой остановить Каргата.", progress = "Ты принес доказательство смерти Каргата?", completion = "Отличная работа, Джонниди. Когда-то Каргат был славным воином, героем и вождем своего народа.\n\nМы все скорбим об этой потере, особенно Вождь Тралл. Орки Скверны еще заплатят за то, что случилось с Каргатом. А пока что пусть его падение послужит уроком для всех нас.\n\nВВ награду за служение Орде, Джонниди, выбирай любое оружие.", rewards = "Жезл зловещих тенейПлащ викарияВам дадут возможность выбрать одну из следующих наград:\n\nКольцо завоевателяКолье изуверского кулака\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9496] = {title = "Элита Орды Скверны", objective = "Убейте 8 легионеров клана Изувеченной Длани, 4 центуриона клана Изувеченной Длани и 4 воителей из клана Изувеченной Длани по приказу темного охотника Туджина из Траллмара.", description = "Даже если не считать ругани Изуверского Кулака, с Ордой Скверны шутки плохи.\n\nКаргат Острорук командует безжалостными, закаленными в боях воинами, чьи возможности к тому же усилены магией Скверны. У этого войска есть своя элита - легионеры, воители и центурионы Изувеченной Длани. Они внушают страх обычным солдатам и исполняют роль офицерского состава.\n\nЕсли мы хотим добиться хоть каких-то успехов в сражении с Ордой Скверны, сначала надо лишить ее командования.", progress = nil, completion = "Прекрасная работа, Выручалкин. Теперь, когда Орда Скверны лишилась своих легионеров, ее будет гораздо легче одолеть на поле боя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9497] = {title = "Знамя Орды Скверны", objective = "Убейте О'мрогга Завоевателя и захватите ордынское знамя Скверны. После этого возвращайтесь к властителю Хану Изуверу в Траллмар.", description = "Когда весть о так называемой Орде Скверны достигла Вождя, он испытал не только сильную ярость, но и глубокую скорбь. Ничего, не долго осталось торжествовать этой фальшивой орде, мы расправимся с ней так же, как и с задаваками Ренда. А ее трофейное знамя украсит крепость Громмаш, во славу истинного Вождя.\n\nЭту волю Вождя выпало исполнить тебе, <имя>. Задание непростое, знамя Орды Скверны охраняет один из ее лучших воинов, О'мрогг Завоеватель, и он не отступит без яростного боя.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9498] = {title = "Соколиный дозор", objective = "Доложитесь капитану следопытов Венн'рену в Соколином дозоре на полуострове Адского Пламени.", description = "Мы отстроили Соколиный дозор совсем недавно, и теперь это наша военная база на юго-западе полуострова Адского Пламени, совсем рядом с цитаделью. Союзникам вроде тебя, <имя>, здесь всегда рады.\n\nЕсли ты ищешь работу, то отправляйся к капитану следопытов Венн'рену и скажи, что тебя послал я. Он поручит тебе что-нибудь достойное.", progress = nil, completion = "Добро пожаловать в Соколиный дозор, |3-6(нежить). Союзникам Орды здесь всегда рады, особенно, если их рекомендовал Мартик.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9499] = {title = "Соколиный дозор", objective = "Отправляйтесь в Соколиный дозор, на юго-запад полуострова Адского Пламени, и поговорите с капитаном следопытов Венн'реном.", description = "Ты что до сих пор здесь делаешь, <имя>? Не <слышал/слышала>, что ли - мы основали свою собственную, син'дорайскую заставу на полуострове Адского Пламени!\n\nПоверь, среди эльфов крови гораздо комфортнее, чем среди этой... эээ... вонищи. Соколиный дозор находится к юго-западу отсюда, как раз рядом с цитаделью Адского Пламени. Поговори с капитаном следопытов Венн'реном, он о тебе позаботится.\n\nДорога довольно опасна, к тому же патрулируется разведчиками Альянса. Я бы не рекомендовал отправляться в одиночку. Лучше присоединись к какой-нибудь компании, лучше всего эльфов крови.", progress = nil, completion = "Добро пожаловать в Соколиный дозор, брат. Не всем эльфам крови посчастливилось так далеко забраться.\n\nЧто ж, очень жаль. Впрочем, наша работа в Запределье только начинается.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9500] = {title = "Зов Воды", objective = "Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним.", description = "Я чувствую, много времени прошло с тех пор, когда тебе довелось пройти последнее испытание... О тебе спрашивал предсказатель Нобундо. Должно быть, твоя мудрость возросла – ибо ныне тебя призывают, дабы открыть тебе тайны стихии воды.\n\nПолагаю, тебе не нужно напоминать, где в Кристальном зале Экзодара ты сможешь найти предсказателя. Я права?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9501] = {title = "Зов Воды", objective = "Найдите Водяницу у Подводного Рифа возле острова Кровавой Дымки и поговорите с ней.\n\nПрилагается предмет: \n", description = "Водяница, могущественный элементаль воды, пожелала встретиться с тобой. Судя по всему, со стихией воды на острове Кровавой Дымки происходит что-то неладное. Ничего удивительного, впрочем – если принимать во внимание, насколько странно эльфы крови относятся ко всему, что их окружает.\n\nУ северного берега острова Кровавой Дымки есть подводный риф, ты найдешь Водяницу там.\n\nВозьми это зелье – когда ты войдешь в воду возле рифа, оно поможет тебе попасть к Водянице.", progress = nil, completion = "Не страшись, Артешам. Просто мы, духи, предпочитаем общаться телепатически.\n\nЯ благодарна предсказателю Нобундо за то, что он прислал тебя сюда. Воды острова Кровавой Дымки и море у его берегов отравлены скверной. Можно представить себе, что эта вода творит с животными и растениями...\n\nНадеюсь, если мы возьмемся за дело вместе, то нам удастся исцелить зло, причиненное этой земле, и очистить ее воды.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9502] = {title = "Зов Воды", objective = "Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним.", description = "Я чувствую, много времени прошло с тех пор, как тебе довелось пройти последнее испытание... О тебе спрашивал предсказатель Нобундо. Должно быть, твоя мудрость возросла – ибо ныне тебя призывают, дабы открыть тебе тайны стихии воды.\n\nПолагаю, тебе не нужно напоминать, где в Кристальном зале Экзодара ты сможешь найти предсказателя. Я права?", progress = nil, completion = "Вот мы и встретились снова. Я вижу, избранный тобою путь шамана не был ошибкой, а твои успехи доставляют мне истинную радость.\n\nИтак, для тебя настало время постижения стихии Воды: ты познаешь ее тайны, и Вода примет тебя, открыв тебе свою сокровенную суть.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9503] = {title = "Зов Воды", objective = "Принесите 6 бутылочек смрадной эссенции на остров Кровавой Дымки в храм Сокрытого Рифа и отдайте Водянице.", description = "Вода - источник жизни и залог существования всего сущего, благословение, заставляющее расцветать бесплодную землю и гасящее всепожирающий огонь... Однако отравленная вода способна нести погибель.\n\nМы должны понять, насколько велик ущерб, нанесенный источникам воды. К юго-западу отсюда находится Смрадный пруд. Тебе нужно отправиться туда и добыть смрадную эссенцию водяных духов, обитающих в пруду.", progress = "Смрадная эссенция - вот все, что осталось от моих злосчастных сестер... Неужели тебе удалось достать ее так быстро, Артешам?", completion = "Благодарю тебя, о избравший путь шамана! Полагаю, этого будет достаточно, и я смогу понять, в чем суть скверны. Тогда мы, быть может, сумеем найти пути ее исцеления...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9504] = {title = "Зов Воды", objective = "Наполните пустой бурдюк, а затем вернитесь на остров Кровавой Дымки в храм Сокрытого Рифа и отдайте бурдюк Водянице.", description = "Дела обстоят хуже, чем я думала. Скверна может распространиться до самого океана и по всему Азероту вместе с океанскими течениями...\n\nЧтобы не дать этому случиться, нам нужен образец самой чистой воды, какую только можно достать. К юго-востоку отсюда, на нетронутой скверной части острова, находятся руины. Отправляйся туда и найди фонтан, который охраняют наги из племени Зловещей Чешуи.\n\nНаполни этот бурдюк водой из фонтана. Прошу тебя, <имя>, не медли!", progress = "Ну как, принес чистую воду из руин?..", completion = "Вода легко расступается; но стремительной реке или океанской волне не сможет противостоять ни одна стихия.\n\nМы подобны реке и волне, Артешам; мы - сила воды, которой нет преград! Мы, а не те, кто отравил остров Кровавой Дымки!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9505] = {title = "Пророчество Велена", objective = "Отправляйтесь на юг и отыщите народ, о котором говорило раненое существо.", description = "Пророк предвидел наступление этого дня. Он говорил, что на острове в новом мире мы найдем союзников.\n\n\"Нам предстоит испытание. Они попросят нас искупить грехи наших отцов...\"\n\nТогда мы не поняли значения его слов, но, видя это существо и его реакцию на наше появление, мы все яснее видим, о чем было пророчество. Даже здесь почувствовали падение дренеев.\n\nСтупай на юг. Именно там мы нашли это существо. Найди ее родичей и поведай им о нашем народе.", progress = nil, completion = "Ты говоришь, что найдена одна из наших? И что она ранена? Я немедленно пошлю в вашу деревню одного из своих воинов.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9506] = {title = "Начало положено", objective = "Верните адмиралу Одиссию морской компас и морскую карту, украденные Торговой компанией.", description = "Я – адмирал Одиссий из командования ВМС Альянса. Наш корабль был вынужден причалить к острову из-за своего рода нашествия. Мне даже неловко говорить об этом, но в трюмах обоих кораблей ухитрились спрятаться гоблины.\n\nПрошлой ночью, когда большая часть команды спала, они нанесли удар!\n\nЕще удивительнее то, что они украли наши навигационные приборы и спрыгнули с корабля!\n\nВоры скрылись в чаще к востоку отсюда. Не поищешь ли ты наше оборудование? Ты <оказал/оказала> бы нам большую услугу.", progress = "Как продвигаются поиски, незнакомец?", completion = "С такими способностями ты далеко пойдешь! При помощи навигационных принадлежностей мы сможем определить, далеко ли отклонились от курса.\n\nВпрочем, стой, что это? В карту что-то завернуто. Посмотрим...\n\nЭто приказы шефа Разданка из Торговой компании. Согласно этим планам, они должны собрать на острове все кристаллы и похитить наши корабли.\n\nКлянусь кустистыми бровями Бронзоборода! Вот зачем нас заставили причалить! Но как они прознали о наших планах?!\n\nЭто предательство...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9508] = {title = "Зов Воды", objective = "Принесите голову Телатиона на остров Кровавой Дымки в храм Сокрытого Рифа и отдайте Водянице.", description = "Мне удалось определить, что является источником порчи. Это побочный продукт неких безумных опытов, которым нужно положить конец. И займешься этим ты!\n\nК юго-западу от Смрадного пруда находится небольшой лагерь. Там проводит свои \"исследования\" Телатион Нечистый - и именно оттуда распространяется мерзость, отравляющая воды острова.\n\nИспользуй чистую воду из Ясеневого леса, чтобы уничтожить бочки в его тайном хранилище. Не сомневаюсь, это выманит Телатиона из его логова.\n\nМы положим конец этой мерзости!", progress = "Надеюсь, ты добился успеха?", completion = "Итак, дело сделано! Кризис предотвращен. Благодаря тебе воды острова Кровавой Дымки снова станут чистыми, избавившись от скверны.\n\nК сожалению, эльфы крови не понимают, что, оскверняя все вокруг, они тем самым убивают и самих себя...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9509] = {title = "Зов Воды", objective = "Отнесите флакон чистейшей воды предсказателю Нобундо. Его можно найти на острове Лазурной Дымки в Экзодаре.", description = "Я сохранила немного воды из Ясеневого леса; не потому, что не верила, что ты справишься с ситуацией, нет, я даже скорее была уверена в успехе... Мне просто показалось - будет неплохо, если ты сможешь принести Нобундо что-нибудь особенное.\n\nВот, держи, <имя>, полный флакон чистейшей воды. В обмен на него ты получишь могущественный водяной тотем.\n\nПредсказатель Нобундо ждет твоего возвращения в Экзодаре.", progress = "Духи стихий поведали мне о твоих великих деяниях. Что ж, поговорим...", completion = "Ты мудр не по годам, Артешам. Я чувствую, что дух воды доволен тобой. Великой честью для меня будет воплотить самую суть принесенной тобой чистой воды в водяном тотеме.\n\nПомни уроки, что дала тебе стихия воды; надеюсь, со временем тебе удастся глубже проникнуть в ее тайны и постичь ее силу.", rewards = "Вы изучите:\n\nТотем исцеляющего потока\n\nВы также получите:\n\nТотем воды"}
MultiLanguageQuestData['ru'][9511] = {title = "Боевые планы Каргата", objective = "<TXT>В документах, обнаруженных на теле Каргата, подробно излагается план вторжения в Оплот Чести.", description = "<TXT>В документах, обнаруженных на теле Каргата, подробно излагается план вторжения в Оплот Чести.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][9512] = {title = "Крабовый супчик поваренка", objective = "Принесите 6 кусков мяса шустрых крабов \"Поваренку\" Максоусу в лагерь Одиссия.", description = "Адмирал прав, в тебе и впрямь кладезь талантов. Не поможешь Поваренку?\n\nЕсли я снова подам на обед курицу, команда меня утопит.\n\nЯ смотрю, вдоль берега бродят крабы – и сколько! Притащи мне крабьего мяска, и можешь считать – я твой должник.\n\nВыручишь бывшего пирата?", progress = "Гр-р-р... Яр-р-р... Лопни моя селезенка... Ой, прости, парень, приходится балакать иногда по-пиратски, а то совсем разучусь...", completion = "Ой, спасибо тебе огромное, незнакомец. Команда сразу взбодрится!", rewards = "Вы получите:\n\nКрабовый супчик поваренка"}
MultiLanguageQuestData['ru'][9513] = {title = "Возвращение руин", objective = "Убейте 5 мирмидонов, 5 наг и 5 сирен из клана Зловещей Чешуи для жрицы Кайлин Ил'динар.", description = "Хотя многие считают наше затруднительное положение следствием несчастливой случайности, я чувствую, что мы недаром оказались здесь. Невидимая рука судьбы подтолкнула нас к этой земле. Для чего – со временем станет ясно.\n\nК западу отсюда находится древний эльфийский город, лежащий в руинах и заселенный нагами. Мне не хотелось бы сидеть сложа руки, пока наги оскверняют земли предков.\n\nТы <наделен/наделена> неплохими способностями, <класс>. Почти мой народ и очисти руины от нежеланных обитателей.", progress = nil, completion = "Хвала Элуне! Неприкаянные души теперь могут обрести покой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9514] = {title = "Покрытая рунами табличка", objective = "Отнеcите покрытую рунами табличку жрице Кайлин Ил'динар в лагерь Одиссия на острове Лазурной Дымки.", description = "Вы не можете разобрать ни одного из символов на табличке. Быть может, прочесть таинственные руны сумела бы жрица?", progress = "Нашел что-нибудь?", completion = "Нет, я не могу прочесть эти руны, но я знаю, кто может...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9515] = {title = "Полководец Шрисс'тиз", objective = "Жрица Кайлин Ил'динар из лагеря Одиссия попросила вас убить полководца Шрисс'тиза.", description = "Вторжение наг может плохо для нас закончиться, <имя>. Мне приходилось видеть, на что они способны, и такого я ни одному живому существу не пожелала бы. Подозреваю, что их полководец Шрисс'тиз прячется в пещере - скорее всего в западной части побережья.\n\nОтыщи полководца Шрисс'тиза и положи конец его правлению.", progress = nil, completion = "Полководец Шрисс'тиз мертв, и наги не скоро оправятся от этого удара. Теперь мы в безопасности... на время.\n\nДолжна признать, что я напрасно относилась к тебе с подозрением. Ты не имеешь ничего общего с мерзавцем Архимондом. Прими этот дар от ночных эльфов.", rewards = "Сапоги из чешуи нагиПроверенный в бою клинокВы получите:\n\n"}
MultiLanguageQuestData['ru'][9516] = {title = "Уничтожить Легион!", objective = "Убейте 15 демонов на холме Демонического Огня, в каньоне Гибели Демона и гряде Гибели Демона.", description = "Я не потерплю их присутствия в нашем мире! Пылающий Легион чуть не уничтожил нашу расу, и мы бежали сюда, чтобы построить себе новый дом в новом мире. Теперь они снова пришли. И мы снова отступили, и снова, и снова!\n\nДовольно! \n\nОстатки Легиона затаились к югу и к западу от холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона. Это все, что осталось от полчищ, что некогда вторглись в этот мир.\n\nСтупай же и перебей сколько сможешь, пока еще не поздно!", progress = nil, completion = "Примите мое почтение и благодарность, |3-6(Друид). Может быть, нам все же удастся построить здесь новый дом, не страшась больше Пылающего Легиона.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9517] = {title = "Напрасные усилия", objective = "Добудьте 5 связок оскверненной древесины Сатирнаара.", description = "Добро пожаловать в Лесную Песнь, <класс>. Там, где ныне стоят палатки, однажды вырастут дома, но для этого необходимы постоянные поставки строительных материалов. Я не посмею просить никого из наших рабочих рубить древние деревья этой рощи, но наши соседи на западе не столь трепетно относятся к лесу.\n\nМы заберем немного оскверненного дерева из цитадели сатиров на западе. Доставь древесину Кривокрону на Лесозаготовки Песни Войны. Он один из Древних, и может очистить ее от порчи.", progress = "*Древний со скрипом поворачивается к вам.*\n\nАрхитектор Немос сказал, что ты можешь доставить древесину, спасенную из лагеря лесогубов и мерзостного Сатирнаара?", completion = "Дерево, поваленное орочьими грубыми клинками, изуродовано так, словно его ураганом повалило. Из него ничего путного не построишь, но я очищу его от порчи и верну архитектору Немосу и его работникам. Хоть какое-то добро выйдет из этого лиха, в конце концов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9518] = {title = "Пособники разрушения", objective = "Убейте надзирателя Гортака и 12 других сторонников Орды на лесозаготовках Песни Войны.", description = "Лесозаготовки Песни Войны – нарыв на теле нашей истерзанной земли. Каждый раз, как нам удается пресечь их работу, надзиратель Гортак приказывает своим лесорубам удвоить усилия!\n\nТеперь орки валят столько леса, что даже использовать весь не могут, рубят живые стволы, когда у них бревна гниют за ненадобностью! Это плевок нам в душу, <имя>, и мы покажем им, что не потерпим дальнейшего разорения наших земель!\n\nСтупай и не ведай покоя, пока этот надзиратель Гортак и его пособники не будут мертвы!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Наплечники Шепота ЗвездПокрытый морилкой жилетВы получите:\n\n"}
MultiLanguageQuestData['ru'][9519] = {title = "Потерянная чаша", objective = "Добудьте чашу Элуны.", description = "В области к западу отсюда, что нынче зовется Сатирнаар, некогда было прославленное святилище, которое возвел мой народ. В нем хранилась бесценная реликвия, чаша Элуны, доверенная хранителям святилища жрецами Элуны. Некогда к святилищу стекались паломники, дабы испытать целительную силу чаши, которой она, как говорят, обладала.\n\nМожет, это просто байки, но если в них есть доля правды, то эта святыня может стать ключом к возрождению нашего истерзанного леса. Мне надо точно это выяснить, <имя>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9520] = {title = "Демонические планы", objective = "Доставьте демонические планы воздаятелю Ведаару на лесозаготовки Песни Войны в Ясеневый лес.", description = "Этот пергамент выронил демон, но что странно – он написан на Всеобщем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя Ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.\n\nВ плане подробно описывается подготовка нападения демонов на Лесную Песнь на севере отсюда – место, где основали свое поселение дренеи.\n\nВозможно, это заинтересует воздаятеля Ведаара с лесозаготовок Песни Войны?", progress = "Что тут у вас, сударь?", completion = "Клянусь Семью Кристаллами Ата'мала, этого не может быть! Они хотят напасть на нас здесь, в Лесной Песне?!\n\nНе будет этого, доколе я жив!\n\n&lt;Воздаятель Ведаар сминает в кулаке пергамент с демоническими планами.&gt;\n\nНет. Мы этого не допустим!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9521] = {title = "Донесение с северного фронта", objective = "Доставьте донесение часового Мелирии часовому Дальней Песне в рощу Среброкрылых, что в Ясеневом лесу.", description = "Борьбу с Ордой ведет не только Башня в Ночных лесах, <имя>. К юго-востоку, на границе со Степями, в роще Среброкрылых, находятся Часовые Среброкрылых. Часовой Дальняя Песня из этой рощи направляет наши действия против тех, кто готов разорить наши земли.\n\nЯ немного припозднилась с отправлением моего последнего донесения часовому Дальней Песне, но боюсь оставить башню без охраны.\n\nМне крайне необходима твоя помощь в доставке этого отчета!", progress = "Что у тебя такое, |3-6(Друид)?", completion = "Благодарю за доставку этого донесения, |3-6(Друид). Из того, что пишет часовой Люсьель, видно, что оправдываются наши худшие опасения. С каждым нашим очередным успехом Орда все решительнее пытается нанести нам как можно больше урона.\n\nМы не можем позволить себе отступить. Судьба земель наших предков стоит на кону. Но если на границе будет больше таких, как ты, мы точно победим. Будешь ли ты биться вместе с нами?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9522] = {title = "Больше никогда!", objective = "Добудьте пламенеющее лезвие Горганнона и желчное копье Ищейки.", description = "<имя>, на твои плечи ложится обязанность сорвать нападение Пылающего Легиона! Ты <должен/должна> уничтожить их предводителей. Остальные демоны, по большей части – безмозглые твари. \n\nГорганнона ты найдешь в Каньоне Гибели демона к югу за Холмом Демонического Огня, близ сломанного, парящего копья Маннорота.\n\nДиатор Ищейка засел где-то в логове в холме над Грядой Гибели Демона. Чтобы найти эту гряду, отыщи уступ, по которому можно подняться из Каньона Гибели демона близ памятника Грому Адскому Крику.\n\nПринеси мне их оружие.", progress = nil, completion = "Никогда более Пылающий Легион не потревожит нас в этих местах! Вы избавили нас от битвы, которую мы наверняка проиграли бы, |3-6(Друид).\n\nЯ приношу вам благодарность и глубочайшее уважение от лица Длани Аргуса. Для меня большая честь, что вы сражаетесь на нашей стороне.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо АргасаПечать АргасаПерстень Аргаса\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9523] = {title = "Хрупкие предметы. Не кантовать!", objective = "Принесите 8 древних реликвий археологу Адаманту Железному Сердцу в лагерь Одиссия на острове Лазурной Дымки.", description = "Жрица говорит, что руины на западе отсюда – это разрушенный город ночных эльфов. Я сразу вспомнил, что говорил мой папаша про такого рода развалины: \"Сынок, если тебе попадутся эльфийские развалины, знай, что там полно эльфийских реликвий.\"\n\nЧто я за дворф, если не найму первого встречного, чтобы добыть эльфийские реликвии? Вперед!", progress = "Без реликвий можешь даже не возвращаться.", completion = "Папаша бы мной гордился! Его мальчик нагрел руки на первых же встреченных им эльфийских руинах... С твоей помощью, конечно. Да, не беспокойся, я не собираюсь присвоить себе все почести. Как тебя зовут? Шаноб? Я непременно расскажу о тебе в Стальгорне.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9524] = {title = "Узник цитадели", objective = "Спасите капитана Алину в цитадели Адского Пламени до того, как ее казнят.\n\nЭто задание выполняется только в героическом режиме.", description = "Альянс, здесь? Тогда слушай внимательно, <класс>.\n\nКаргату удалось захватить несколько наших солдат. Среди них капитан Алина, один из самых важных офицеров. Надо успеть спасти ее, пока ее не казнили.\n\nОбо мне не беспокойся, я смоюсь отсюда, как только переведу дыхание.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9525] = {title = "Узник цитадели", objective = "Спасите капитана Костолома в цитадели Адского Пламени до того, как его казнят.\n\nЭто задание выполняется только в героическом режиме.", description = "Мне удалось сбежать из тюрьмы Каргата, <имя>. Сегодня должны казнить нескольких заключенных, и среди них одного очень важного офицера.\n\nЕсли мы потеряем капитана Костолома, это будет ощутимый удар для всей нашей армии. Ты <должен/должна> сделать все, что в твоих силах, чтобы его спасти. Я бы отправился с тобой, но, к сожалению, я слишком слаб...", progress = nil, completion = "У меня прямо камень с души свалился, |3-6(Рыцарь смерти). Всегда был уверен, что умру на поле боя, покрытый кровью убитых врагов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9526] = {title = "Возрождение Холма Демонического Огня", objective = "Посадите 8 древесных саженцев в кучи плодородной земли.", description = "<Малыш/Малышка>, к юго-западу отсюда находится место, что зовется лесами Ночной Песни. С недавнего времени его называют Холмом Демонического Огня. Прискорбно видеть, как по этой земле бродят демоны и разносят везде свою порчу.\n\nНе поможешь ли ты возродить эту землю?\n\nУ меня есть несколько саженцев, которые я приберег на этот случай. Отнеси их на Холм Демонического Огня и посади их в кучи плодородной земли.", progress = nil, completion = "Добро. Хотя много твоих годов утечет прежде, чем эти саженцы превратятся в Древних, но со временем они помогут нам в борьбе против демонов на Холме Демонического Огня.\n\nСтупай же с миром, младший брат.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9527] = {title = "Все, что осталось", objective = "Верните Коулену останки его семьи.", description = "Долгие годы мы мирно жили на острове по соседству с совухами. Представь себе мое удивление, когда они наводнили наш берег и напали на нас!\n\nЯ сражался изо всех сил, но меня легко скрутили. Теряя сознание от жестоких ударов, я надеялся лишь на то, что моя семья не пострадает.\n\nКогда я пришел в себя, вокруг было тихо, но песок покраснел от крови. Их крови. Мою жену и дочь сожрали заживо.\n\nЯ не жажду мести, <имя>. Мне бы только похоронить как должно то, что от них осталось.", progress = "Мою жену звали Талриса, а дочь – Магвин.", completion = "Благодарю тебя, Небрить. Теперь их души упокоились в мире.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9528] = {title = "Крик о помощи", objective = "Проводите Магвин через остров до дома.", description = "Несколько недель назад на мою семью напали мурлоки и совуны. Мне удалось сбежать, но и мать и отца убили. Не знаю, как быть дальше, ясно одно: мне нужно вернуться домой – или в то, что осталось от дома... Помоги мне пробраться через лес!", progress = nil, completion = "&lt;По лицу Коулена струятся слезы радости.&gt;\n\nЧем я смогу отплатить тебе, Небрить? Возьми эту фамильную драгоценность. Она символизирует священные узы дружбы, доверия и любви между ночными эльфами. Отныне и вовек ты мой брат...", rewards = "Вы получите:\n\nНаручи родства Коулена"}
MultiLanguageQuestData['ru'][9529] = {title = "Камень", objective = "Добудьте камень Бездны с Тропы Мертвых.", description = "Я уверена, что твой бес оказался полезным и даже забавным слугой, однако пора тебе подчинить себе более могущественное существо - демона Бездны.\n\nСтупай по Тропе Мертвых до переправы через реку Элрендар. Перейдя через реку, отыщи на южном берегу светящийся голубой камень и возьми его. Тогда ты поймешь, что тебе делать дальше.", progress = nil, completion = "Вы смотрите на камень, и перед глазами все расплывается...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9530] = {title = "Созревший план", objective = "Принесите выдолбленный ствол и 5 охапок листьев адмиралу Одиссию в лагерь Одиссия на острове Лазурной Дымки.", description = "Я давно подозревал нечто подобное, но теперь исчезли последние сомнения.\n\nСреди нас есть предатель.\n\nГоблинские планы прямо указывают на существование заговора. Поскольку я не могу представить, кто из моих людей нас предал, мне понадобится твоя помощь. Теперь никому из команды нельзя доверять.\n\nДля осуществления плана мне понадобится выдолбленный ствол и листья. Их можно поискать неподалеку от стоянки лесорубов к северу от нас. Охапки листьев ты и <сам/сама> наберешь в лесу.", progress = "Обожаю, когда планы воплощаются в жизнь...", completion = "Предупреждаю, я собираюсь дать тебе опасное поручение. Даже если ты откажешься от него, Шаноб, я не разочаруюсь в тебе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9531] = {title = "У деревьев есть уши", objective = "Проследите за встречей Гизла с предателем.\n\nРасскажите обо всем увиденном адмиралу Одиссию.", description = "Если верить планам, предатель должен встретиться с предводителем гоблинов Гизлом в бухте на западном острове. Проследи за ними, <имя>.\n\nПомнишь, я просил тебя набрать листьев и принести выдолбленный ствол? Их-то ты и наденешь! Прекрасная маскировка.\n\nОтправляйся в бухту и посмотри, выставлен ли нагский флаг. Если да, то встреча должна вот-вот состояться. Замаскируйся и жди. В конце концов предатель заявится на встречу. Дождись окончания встречи и сообщи мне, кто этот негодяй.", progress = "Предатель еще пожалеет, что связался с ВМС Альянса!", completion = "Ушам своим не верю! Во всем виноват гном... и как я не догадался!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9532] = {title = "Найти Келтуса Темного Листа", objective = "Найдите Келтуса Темного Листа.", description = "<имя>, один из наших разведчиков чересчур увлекся своими обязанностями! Он неусыпно следит за нашими врагами, но при этом забывает присылать донесения о том, что ему удалось выяснить!\n\nНайди этого шпиона, Келтуса Темного Листа, убеди его сообщить, наконец, о том, что он узнал, и как можно быстрее возвращайся ко мне. Он далеко отсюда, на юго-западе, там, где река Элрендар расходится на два рукава и огибает деревню Золотистой Дымки. Келтус выслеживает ночных эльфов из Ан'дарота, так что, должно быть, он где-то там.", progress = nil, completion = "Надеюсь, ты соображаешь, что я надежно замаскирован... что я был надежно замаскирован?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9533] = {title = "Рука помощи", objective = "Отправляйтесь в Лесную Песнь и поговорите с архитектором Немосом.\n\nОбратитесь к воздаятельнице Паланааре, если вам требуется транспорт.", description = "Мой народ принялся за важное дело в восточной части Ясеневого леса при поддержке и помощи калдорай.\n\nПод руководством архитектора Немоса и воздаятеля Ведаара они восстанавливают древний форт ночных эльфов. Это непростая задача, <имя>, ибо кругом много врагов. Я знаю, что архитектор Немос и его сторонники в Лесной Песни будут благодарны любой помощи, и он просил меня присылать к нему всякого, кого это заинтересует.\n\nЕсли хочешь отправиться туда, окликни меня еще раз, и я организую тебе транспорт.", progress = nil, completion = "Радостно видеть нового гостя в Лесной Песни.\n\nПоборница Паланаар присылает на помощь столько народу, сколько может, и мы рады каждой паре рук.\n\nПосмотрите вокруг, |3-6(Друид). Может, сейчас вид не слишком впечатляет, но пройдет время, и при помощи наших союзников ночных эльфов мы построим здесь поселение, которое будет достойно называться домом. Сделать предстоит очень много, и любую помощь мы примем с радостью.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9534] = {title = "Уничтожить Легион!", objective = "Уничтожьте 15 любых демонов на холме Демонического Огня, в Каньоне Гибели Демона и Гряде Гибели Демона, а затем вернитесь к Валуше на Заставу Расщепленного Дерева в Ясеневом лесу.", description = "Остатки демонического Пылающего Легиона слишком долго надоедали нам.\n\nХватит!\n\nЭти демоны лезут от Холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона на востоке.\n\nСтупай и уничтожь их сколько сумеешь – и покроешь славой и себя, и Орду!", progress = nil, completion = "Это куда лучше! Нет ничего достойнее, чем очищать наш мир от демонов. Да и противники они стоящие, не то что эти дохляки из Альянса.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9535] = {title = "Демонические планы", objective = "Доставьте демонические планы Валуше на заставу Расщепленного Дерева, что в Ясеневом лесу.", description = "Этот пергамент выронил демон, но что странно – он написан на орочьем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.\n\nВ плане подробно описывается подготовка нападения демонов на заставу Расщепленного Дерева к северу отсюда.\n\nВы уверены, что это очень заинтересует Валушу на заставе Расщепленного Дерева.", progress = "Что тут у тебя, брат?", completion = "Повелители ужаса! Они хотят напасть на заставу Расщепленного Дерева?!\n\nПока жива – не допущу!\n\n&lt;Валуша сминает в кулаке пергамент с планами демонов.&gt;\n\nНет. Они не пройдут! Они – погибель для нашего мира!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9536] = {title = "Больше никогда!", objective = "Добудьте пламенеющее лезвие Горганнона и желчное копье Ищейки.", description = "<имя>, сделай так, чтобы эта атака Пылающего Легиона сорвалась! Иди и убей этих повелителей ужаса! Остальные демоны, кроме них – по большей части безмозглые твари. \n\nГорганнона ты найдешь в Каньоне Гибели Демона к югу за Холмом Демонического Огня, близ сломанного, парящего копья Маннорота.\n\nДиатор Ищейка засел где-то в логове в холме над Грядой Гибели Демона. Принеси мне их оружие в доказательство твоей победы.", progress = "Этих повелителей Ужаса надо прикончить как можно скорее, Баронгеддон!", completion = "Никогда больше Пылающему Легиону не поработить ни орков, ни какую другую расу Орды!\n\nТы отважный боец, |3-6(Паладин)! В груди твоей бьется сердце истинного сына Орды! Мы гордимся тобой!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо АргасаПечать АргасаПерстень Аргаса\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9537] = {title = "Не ведая пощады", objective = "Добудьте для адмирала Одиссия переписку предателя у инженера \"Искра\" Перемолоттера", description = "Перемолоттер должен быть привлечен к ответственности!\n\nСтупай на берег, отыщи там вероломного гнома и вытряси из него все возможные сведения!\n\nЕсли высокопоставленные представители Альянса способны на предательство, чего остается ждать от других?!\n\nИ последнее, <имя>: не колеблясь, применяй силу...", progress = "Удалось ли тебе отловить лживого шакала?", completion = "Немыслимо! Мы имеем дело с масштабным заговором!\n\nОб этом должен узнать король и ваши вожди. Последствия могут быть ужасны.", rewards = "Клинок МорестранникаКолотушка для мяса МаксоусаЛомщик заклятийАрбалет АльбатросаПалка ПослушанияВы получите:\n\n"}
MultiLanguageQuestData['ru'][9538] = {title = "Изучение языка", objective = "Изучите пергамент \"Язык фурболгов из племени Тихвой для начинающих\", полученный от Ауррена, а затем изучите тотемом Акиды на Лазурной заставе.", description = "Кажется, я докопался до сути, <имя>!\n\n<Ауррен указывает на тотем.>\n\nВсе, что нам нужно знать о языке фурболгов Тихвой, написано на их тотемах. Имея общее представление о том, как работают эти символы, мы можем изучить тотемы и научиться разговаривать с фурболгами.\n\nЗначения из таблицы символов я выписал на этот пергамент. Изучи его хорошенько, а потом займись тотемом. Он укажет тебе путь к следующему тотему языкознания.\n\nКогда изучишь язык, поговори с Аругу!", progress = "От тотема исходит негромкое гудение.", completion = "На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.\n\nВам бросается в глаза странный набор символов, и губы сами собой произносят: \"А-К-И-Д-А\".", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9539] = {title = "Тотем Ку", objective = "Найдите тотем Ку с помощью проводника.", description = "Вы начинаете читать надпись на тотеме, едва произнося непонятные слова и фразы. Постепенно смысл написанного становится ясен. Кажется, тотем велит отправиться на ближайший холм на северо-востоке.", progress = nil, completion = "На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.\n\nВам бросается в глаза странный набор символов, и губы сами собой произносят: \"Ку\".", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9540] = {title = "Тотем Тикти", objective = "Найдите тотем Тикти с помощью проводника.", description = "Вы начинаете читать надпись на тотеме, с большей легкостью произнося непонятные слова и фразы. Постепенно смысл написанного делается вам ясен. Кажется, тотем велит переправиться через Хрустальную реку на востоке. Быть может, Предназначение ждет вас по ту сторону реки.", progress = nil, completion = "На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.\n\nВам бросается в глаза странный набор символов, и губы сами собой произносят: \"Т-И-К-Т-И\".", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9541] = {title = "Тотем Йора", objective = "Найдите тотем Йора с помощью проводника.", description = "Символы этого тотема переводятся куда быстрее. Узоры и картинки превращаются в знакомые слова. Вы почти уверены, что тотем призывает вас двинуться на юг, вниз по реке. Что-то ожидает вас на дне реки.", progress = nil, completion = "На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.\n\nВам бросается в глаза странный набор символов, и губы сами собой произносят: \"Й-О-Р\".", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9542] = {title = "Тотем Варк", objective = "Найдите тотем Варк с помощью проводника.", description = "Теперь все символы языка фурболгов вам хорошо знакомы. Надписи на тотеме Йора вы читаете свободно, как на родном языке.\n\nСудя по всему, на западе отсюда располагается еще одно селение фурболгов. Совершенное знание языка позволяет вам понять, что ваша цель – деревня Косолапов. Йор поведет вас, но если вы собьетесь с пути, то знайте: через лес, точно к месту вашего назначения, ведет древняя эльфийская дорога.", progress = nil, completion = "Вы читаете надпись на тотеме, и губы сами собой произносят: \"В-А-Р-К\".", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9543] = {title = "Искупление", objective = "Поговорите с Амааном Мудрым в храме Телхамат на полуострове Адского Пламени.", description = "Сколько длится наша история, столько мы и воюем с орками, <имя>. Однажды, одержимые жаждой крови, они чуть не истребили нас поголовно, и с тех пор мы предпочитаем держаться от них подальше, пусть даже им и удалось избавиться от власти демонов.\n\nА теперь... эта новая связь... Не скажу, чтобы она нас обрадовала. Поговори с нашим старейшиной, Амааном Мудрейшим, он поможет пролить свет на эти события.", progress = nil, completion = "Что я могу сделать для тебя, Назгрейм? Ты выглядишь обеспокоенным.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9544] = {title = "Пророчество Акиды", objective = "Освободите 8 пленников из племени Тихвой из клеток в деревне Косолапов. Вернитесь к Аругу из племени Тихвой на Лазурную заставу.", description = "На тотеме изображена война между племенами Тихвой и Косолапов. Судя по всему, фурболги из племени Косолапов вытворяли немыслимые вещи с собратьями из племени Тихвой.\n\nИ вот среди хаоса начало сбываться пророчество: придет герой иной крови и спасет племя Тихвой.\n\nУбейте фурболгов из деревни Косолапов и отберите у них ключи. Отоприте клетки с пленниками из племени Тихвой. Освободив всех, возвращайтесь к Аругу из племени Тихвой.", progress = nil, completion = "&lt;язык фурболгов&gt; Пророчество гласило, что явится Избранный, который избавит нас от смертельной хватки Косолапов, и сами духи возвестят прибытие этого героя.\n\nИ вот ты здесь.\n\nПреклоняюсь пред тобой, о великий.", rewards = "Защитник племени ТихвойРазрушающий арбалет АругуОстрый жезл племени ТихвойВы получите:\n\nПредмет #8"}
MultiLanguageQuestData['ru'][9545] = {title = "Реликвия ясновидца", objective = "Вернитесь к телу Седаи, которое находится к северо-востоку от храма Телхамат, и используйте там реликвию ясновидца по просьбе Амаана Мудрого из храма Телхамат на полуострове Адского Пламени. После выполнения задания возвращайтесь к Амаану.", description = "Упрямцы ограничивают свой разум, утверждая, что истина может быть только одна. Но мудрые распахивают свой ум навстречу множеству вероятностей, которые коренятся в настоящем и прорастают в будущее.\n\nОтнеси эту реликвию туда, где ты <нашел/нашла> Седаи. Смотри глазами, но видь разумом, <имя>,", progress = "Что тебе удалось увидеть, Назгрейм?", completion = "Надеюсь, что видение, представшее твоим глазам, помогло понять, что случилось в результате смерти Седаи. Реликвия показала тебе ряд событий, которые могли бы привести к тому, что сейчас происходит. Правда может быть разной, и ее никогда нельзя знать точно.\n\nИзменился ли твой образ мысли теперь, когда ты обладаешь этим знанием?\n\nКто может сказать, продолжатся ли наши распри с орками? Важно оставаться открытым для всех возможностей.", rewards = "Плетеный шлем воздаятеляПоножи из храма ТелхаматЖилет ОменайВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9546] = {title = "Исполнение пророчества", objective = "Освободите 8 пленников из племени Тихвой из клеток в деревне Косолапов по просьбе Аругу из племени Тихвой.", description = "Пророчество гласило, что явится Избранный, который избавит нас от смертельной хватки Косолапов, и сами духи возвестят прибытие этого героя.\n\nИ вот ты здесь.\n\nПреклоняюсь перед тобой, о <великий/великая>. Умоляю, спаси наших малышей. Их захватили воины племени Косолапов, застав нас врасплох. Их держат в клетках в деревне Косолапов на юго-западе. Ключи от клеток – у фурболгов-Косолапов. Убей их и забери ключи. Освободи мой народ.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Кольчужный пояс Серебряного бораНаручи из линялого мехаНовосотканные штаныВы получите:\n\n"}
MultiLanguageQuestData['ru'][9547] = {title = "Зов воздуха", objective = "Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.<имя>, предсказатель Нобундо спрашивал о тебе. Должно быть, настало время познать тайны воздуха, последней из стихий!\n\nЯ хочу сказать, что очень горжусь твоими достижениями. Впереди тебя ждут великие свершения.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "<имя>, предсказатель Нобундо спрашивал о тебе. Должно быть, настало время познать тайны воздуха, последней из стихий!\n\nЯ хочу сказать, что очень горжусь твоими достижениями. Впереди тебя ждут великие свершения.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9548] = {title = "Украденное снаряжение", objective = "Верните Клопперу Бацбаху его оборудование. Клоппера можно найти в старом черепашьем панцире на берегу.", description = "Тсс! Говори тише, не привлекай ко мне внимания.\n\nЕсли мурлоки меня обнаружат, весь эксперимент пойдет прахом! Я и так весьма близок к тому, чтобы утратить все полученные данные...\n\nВчера, пока я пополнял запасы, один из мурлоков, надо думать, подошел слишком близко и обнаружил мой лагерь. Я возвращаюсь – и что же вижу? Эти пучеглазые куда-то волокут ящик с моим снаряжением! Уверен, они его припрятали в одном из поселений. Только мне высовываться не резон, не будет от этого добра. Может, ты мне поможешь? А?", progress = "Ну как, ты нашел мое оборудование?", completion = "Фантастика, просто фантастика! Кража моего оборудования позволила мне узнать об этих мурлоках столько, сколько я не узнал бы за недели наблюдений!\n\nЯ уже знаю, что напишу в отчете.\n\n\"Столкнувшись с элементами значительно более развитой в технологическом плане культуры, мурлоки из племени Черного Ила не проявили ни малейшего любопытства, свойственного представителям развивающихся культур гуманоидов.\" Да! Именно так!\n\nЭто же просто шедевр! Уверен, в Стальгорне будут просто восхищены моим отчетом! Словами не выразить, как я тебе благодарен, Рудель!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9549] = {title = "Артефакты племени Черного Ила", objective = "Принесите 3 варварских идола и 6 варварских ножа мурлоков Клопперу Бацбаху, который прячется в старом черепашьем панцире на берегу.", description = "Мои наблюдения и заметки о мурлоках из племени Черного Ила, несомненно, станут большим вкладом в науку, можешь мне поверить, <имя>. Однако все это – лишь начало. Я намереваюсь вернуться в Стальгорн и продемонстрировать там примитивные творения этого клана.\n\nОднако есть одно маленькое \"но\", мешающее осуществлению моих планов. Дело в том, что мурлоки постоянно носят нужные мне предметы при себе, а я не вынесу бремени убийства... Но если ты поможешь мне заполучить идолов, которые носят с собой провидцы племени Черного Ила, а также несколько ножей – из тех, которыми вооружены их воины, я не стану допытываться, как эти вещи попали к тебе.", progress = "Ну что? Ну как? Получилось у тебя, э-э, достать артефакты, которые я мог бы отправить в Стальгорн?", completion = "Ошеломляюще! Потрясающе! Сногсшибательно! Эти артефакты - само совершенство! Представь себе, Рудель, как они будут смотреться в стеклянной витрине в музее Стальгорна! Нужно только снабдить их сопроводительным текстом...\n\nТвоя помощь была поистине неоценимой! Как пишется твое имя? Обещаю тебе, в самом скором времени ты прославишься как мой соавтор!\n\nДа, кстати, один из парней с корабля в уплату карточного долга дал мне вот это - говорит, это \"карта сокровищ\" или что-то в этом роде. Ну, моряцкие легенды и прочие суеверия меня никогда особо не интересовали...", rewards = "Вы получите:\n\nПотертая карта сокровищ"}
MultiLanguageQuestData['ru'][9550] = {title = "Загадочная карта", objective = "Найдите павильон, изображенный на карте, и выясните, что в нем необычного.", description = "Небрежно нарисованная карта не может рассказать ничего о том, кто сделал ее – кроме того, что у картографа была нетвердая рука. Здесь изображен небольшой павильон с полуразрушенной колоннадой – похоже, он находится к западу от частично затопленной башни.\n\nЕсли верить карте, эти руины находятся на восточном побережье острова. Неизвестно, что там находится, но неведомый картограф, видимо, считал это достаточно важным.", progress = "Возможно, эта старая рукопись и есть то важное, ради чего была нарисована карта...", completion = "Внимательно изучив книгу, вы пришли к выводу, что это дневник. Все страницы заполнены аккуратным почерком, явно отличающимся от почерка автора, который на большинстве страниц карты делал пометки и рисунки своей рукой.\n\nИз-за его отчетов о буйных попойках на берегу разобрать первоначальный текст практически невозможно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9551] = {title = "Зов воздуха", objective = "Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.", description = "<имя>, предсказатель Нобундо спрашивал о тебе. Должно быть, настало время познать тайны воздуха, последней из стихий!\n\nЯ хочу сказать, что очень горжусь твоими достижениями. Впереди тебя ждут великие свершения.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9552] = {title = "Зов воздуха", objective = "Поговорите с Велаадой на Штормовом Пике острова Лазурной Дымки.", description = "Тебя призывает великий дух воздуха, и пришло время ответить на зов.\n\nПоднимись по Штормовому пути на северном склоне горы, в которую врезался Экзодар. На вершине ты найдешь пещеру. В ней живет одна из моих самых лучших учениц, Велаада.\n\nВыслушай ее мудрые слова и повинуйся ей. Так ты обретешь глубокое понимание стихии Воздуха.", progress = nil, completion = "Ветер нашептал мне, что ты уже в пути, |3-6(Шаман).\n\nПредсказатель, Нобундо, очень высокого мнения о тебе, и я вполне с ним согласна.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9553] = {title = "Зов воздуха", objective = "Поговорите с Шептателем на Штормовом Пике острова Лазурной Дымки.", description = "Хотя воздух неосязаем, это - могучая сила, окутывающая все вокруг и проникающая повсюду.\n\nЕго не видит око, но даже камень этой горы состоит по большей части из воздуха, воздух растворен и в морской воде, а огонь не смог бы пылать без него. Только не говори об этом другим стихиям!\n\nТот, кто может научить тебя этой мудрости, находится совсем рядом. На северном крае этого пика тебя ждет Шептатель. Благодаря ему ты познаешь суть стихии Воздуха.", progress = nil, completion = "Я ждал тебя, |3-6(Шаман). Ты ищешь мудрости и, чувствую, не только ее.\n\nЧто ж, начнем.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9554] = {title = "Зов воздуха", objective = "Отдайте Завихрение воздуха предсказателю Нобундо в Экзодаре.", description = "Хотя мои братья и сестры других стихий просили тебя выполнить различные задания, я ничего не хочу от тебя. Мне кажется, ты и так <совершил/совершила> немало, расплатившись за корабль, рухнувший в эти земли с моих небес. Я вижу, у тебя довольно мудрости, чтобы разумно распорядиться стихией воздуха.\n\nОтнеси эту часть моей сущности предсказателю Нобундо, и он поможет тебе создать тотем. Я готов отнести тебя в Экзодар по воздуху.", progress = "Уже вернулся? Вид у тебя взъерошенный!\n\n*Нобундо понимающе ухмыляется.*", completion = "Я горжусь тобой, Артешам. Ты устоял там, где пали другие. Тебе удалось обрести познание стихий и себя. Помни эти уроки всю жизнь, и сделаешься мудрее.\n\nТеперь давай мне завихрение, которое вручил тебе Шептатель, - я вложу его в твой тотем Воздуха. Так же, как и другие тотемы, он поможет тебе сосредоточиться и послужит напоминанием о связи со стихиями.", rewards = "Вы получите:\n\nТотем воздуха"}
MultiLanguageQuestData['ru'][9555] = {title = "Зов огня", objective = "Поговорите с предсказателем Нобундо в Кристальном зале Экзодара.", description = "Я рад, что ты $Gизбрал:избрала; нелегкий путь шамана. Немногие решаются на это, но я провижу, что нам не обойтись без шаманизма, который мы переняли от Сломленных.\n\nДа, теперь их называют именно так, но они некогда были дренеями. Их изменила магия Скверны, и поэтому они не могут призывать на помощь силу Света. Многие относятся к ним, а заодно и к шаманизму, с подозрением, но они не несут зла.\n\nЯ хочу, чтобы ты <побеседовал/побеседовала> с предсказателем Нобундо. Он - мудрейший из известных мне шаманов, и под его руководством ты многому научишься.", progress = nil, completion = "Приветствую тебя. Всегда отрадно встретить дренея, избравшего путь шаманизма. Увы, нас сейчас так мало.\n\nТы уже понял, что нельзя судить о пламени по его виду. И ты не суди обо мне.\n\nИтак, ты здесь, чтобы научиться создавать тотем Огня.", rewards = "Вы изучите:\n\nОпаляющий тотем\n\nВы также получите:\n\nТотем огня"}
MultiLanguageQuestData['ru'][9556] = {title = "Вода для мага", objective = "Найдите бутылку святой воды Стратхольма на улицах Стратхольма и доставьте ее Лордеронскому магу в квартал магов в Штормграде или Подгороде, если вашей стороне удалось одержать верх в Восточных Чумных землях.", description = "Ты без сомнения прекрасно <проявил/проявила> себя в борьбе за башни, <раса>, и непременно получишь свою награду за доблесть. Но сначала ты <должен/должна> доказать, что понимаешь всю глубину разыгравшейся здесь трагедии.\n\nОтправляйся на улицы Стратхольма и найди сосуд со святой водой. Отнеси его в Квартал Магов в Штормград или Подгород... Если твои сородичи одержали верх в тех землях, тебе удастся добраться до кого-то из моих коллег.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9557] = {title = "Расшифровка книги", objective = "Отнесите древние записи на Кровавую заставу и покажите анахорету Пайтеусу.", description = "Прочесть записи невозможно – изначальный текст нельзя отделить от скорописи картографа. Но, может быть, кто-нибудь все-таки сумеет это сделать?..\n\nАнахорет Пайтеус собрал множество артефактов различных культур: возможно, его опыт поможет расшифровать и эти записи?", progress = "Да озарит благословенный Свет все твои начинания, |3-6(Друид). Ну, показывай, с чем пришел...", completion = "Хмм... Непростая задача. Да, вероятно, я сумею выяснить, что же написал на этих страницах первый автор.\n\nСначала мне нужно взять все необходимое для расшифровки. Это не займет много времени...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9558] = {title = "Длиннобородые", objective = "Найдите Гремни Длинноборода на северо-западе от логова Хаал'эш на полуострове Адского Пламени.", description = "У нас тут проблемы с араккоа, которые нападают на наши караваны с продовольствием, так что пришлось нанять пару дворфов, чтобы они разобрались с птичками.\n\nЭто двое братьев, Гремни Длиннобород из них старший.\n\nНо если честно, я немного беспокоюсь. Эти чокнутые дворфы взяли с собой эля вдвое больше, чем провизии и снаряжения вместе взятых! Может быть, ты проследишь за ними?\n\nАраккоа гнездятся в логове Хаал'эш, которое находится к западу отсюда – довольно далеко, у Глубокого разлома. Дворфы должны были разбить там лагерь, к югу от лощины Пыльного Пера.", progress = nil, completion = "Как ты нас нашел, |3-6(Охотник)? Впрочем, не важно, наверное, тебя прислали нам на помощь. Ну тогда давай за работу!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9559] = {title = "Логово племени Тихвой", objective = "Поговорите с верховным вождем в логове племени Тихвой.", description = "<Избранный/Избранная>, отправляйся на север, к дому моего народа – в логово племени Тихвой. Именно там тебя ждет самое сложное испытание.\n\nСтупай, верховный вождь племени Тихвой ждет твоего прибытия.", progress = nil, completion = "Много сотен лет мы жили в относительном мире с прочими обитателями этих земель. Несколько месяцев назад Курц увидел грозные предзнаменования. Долгий мир подошел к концу. Но мы и не представляли, насколько серьезны будут последствия катастрофы!\n\nКажется, будто сами боги принесли раздор в наши края: против нас выступили и враги, и друзья. Но пророчество говорит и о другом... Среди всеобщего хаоса нам явится герой – герой не нашей крови. Избранный спасет нас от гибели.\n\nЭтот герой – ты.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9560] = {title = "Звери Судного дня!", objective = "Принесите 8 шкур опустошителей Мурдо в логово племени Тихвой.", description = "Мы с братом охотились в лесах на востоке, и на нас неожиданно напали странные твари, похожие на насекомых. Такого на острове Лазурной Дымки еще не видали! Может, грядет Судный день? И именно тебе суждено его предотвратить?\n\nЕсли ты в самом деле <Избранный/Избранная>, то легко поразишь тварей Судного дня... и принесешь мне их шкуры. Из таких шкур я смогу сделать великолепные доспехи!\n\nЗверей ты можешь найти на востоке, за дорогой.", progress = "Какие гнусные твари! Даже Слепой Наблюдатель их видит... а ведь он слеп.", completion = "Пророчество воистину сбылось, а доспехи получились великолепные! В самый раз для защитника! Я продам их тебе со скидкой, о Безволосый.\n\nШутка... Первый доспех – в подарок.", rewards = "Хитиновый мундир ОпустошителяПоножи из шкуры опустошителяУтолщенный пояс ОпустошителяВы получите:\n\n"}
MultiLanguageQuestData['ru'][9561] = {title = "Записи Нолкаи", objective = "Найдите место, описанное в дневнике Нолкаи, и отыщите его тайник.", description = "Ну вот, <имя>, перевод готов.\n\n*Анахорет Пайтеус указывает на последний переведенный фрагмент.*\n\n\"Враги уже близко. Мы собрали всех, кто выжил, и отошли на восток, к храму. Храм - наш последний оплот на этом острове. Многие думают, что именно здесь нам суждено принять последний бой. Я спрятал то немногое, что у меня было, у подножия храма - надеюсь, кто-нибудь найдет мой тайник и узнает, что здесь произошло...\"", progress = nil, completion = "Земляной холмик, явно искусственного происхождения, зарос травами и кустарником.\n\nЧерез несколько минут из-под слоя земли появляется старый ящик. Вероятно, это именно то, о чем говорилось в записях Нолкаи.", rewards = "Вы получите:\n\nШкатулка Нолкаи"}
MultiLanguageQuestData['ru'][9562] = {title = "Мурлоки... За что нам эта напасть?", objective = "Верните 5 мешков зерна племени Тихвой.", description = "Темные настали дни, <Избранный/Избранная>. Даже мурлоки наступают нам на пятки – в прямом смысле слова. К сожалению, недавно они посягнули не только на мое самолюбие.\n\nУ нас всегда были напряженные отношения с племенем Илистых Плавников, но я и помыслить не мог, что они осмелятся напасть на нас и похитить запасы продовольствия! Отправляйся на запад, к Илистому берегу, и верни наши припасы!\n\nИ если тебе попадется темнокожий мурлок с клоком белой шерсти, застрявшим между пальцами...", progress = "Мурлок дал мне пинка и плюнул на меня... среди бела дня!", completion = "М... Вкусное зерно... Паркат будет в восторге!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9563] = {title = "Доверие Миррена", objective = "Принесите Миррену Длиннобороду 1 кружку горькой настойки Стражей Пустоты. Для выполнения этого задания необходимо иметь дружелюбное отношение Оплота Чести.", description = "Хочешь, чтобы мы тебе доверяли? Да в наше время никому верить нельзя!\n\nНе так давно араккоа прикончили одного из наших, это меня здорово разозлило.\n\nВот что я тебе скажу. Если ты хочешь доказать свою верность Оплоту Чести... и... и... вообще! – то принеси мне кружку горькой настойки Стражей Пустоты... Да, пожалуй, это было бы недурно. Может быть, потом я и доверю тебе какое-нибудь несложное дело.\n\nНастойку можно достать у Берни из крепости Стражей Пустоты, у него всегда есть запасы.", progress = "У тебя проблемы с настойкой? Старый добрый Берни из крепости Стражей Пустоты обычно запасает ее бочками.\n\nЕсли, конечно, он не смылся оттуда куда подальше... Вот это была бы беда так беда!", completion = "О, да! Похоже, с тобой все в порядке, |3-6(человек). Думаю, что могу тебе доверять.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9564] = {title = "Клок шерсти Гурфа", objective = "Верните Гурфу клок его шерсти в логово племени Тихвой на острове Лазурной Дымки.", description = "Вы нашли клок шерсти, потерянный Гурфом в борьбе с мурлоками. Отнесите его Гурфу и сообщите, что ужасный Мургургул убит.", progress = "Неужели это он?", completion = "&lt;Гурф плюет на клок шерсти и пытается приспособить его к плеши на заду.&gt;\n\nПока и так сойдет! Надеюсь, кто-нибудь из наших шаманов мне поможет.", rewards = "Одеяние с меховой опушкойПоножи свирепостиТяжелые плетеные поножиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9565] = {title = "Поиски в логове племени Тихвой", objective = "Найдите в логове племени Тихвой причины предательства совухов.", description = "Я верховный вождь, и поэтому более всего меня волнует причина предательства союзников.\n\nПочему дикие совухи – наши бывшие друзья – решили на нас напасть? Почему они поселились в логове племени Тихвой?\n\nМожет быть, ответ на мой вопроc таится внутри. Попытайся докопаться до правды.", progress = nil, completion = "От кровавого кристалла исходит болезненная аура, отравляющая воды пещеры.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9566] = {title = "Кровавые кристаллы", objective = "Поговорите с верховным вождем в логове племени Тихвой.", description = "На первый взгляд этот кристалл кажется частью Экзодара. На самом деле с ним что-то не так – он кроваво-красный и быстро растворяется в пещерной воде.\n\nВозможно, именно этим объясняется необычно агрессивное поведение существ острова Лазурной Дымки. Сообщите об этом верховному вождю племени Тихвой.", progress = nil, completion = "Мои разведчики видели много таких же кристаллов на севере.\n\nБлагодарю за помощь, но теперь мне нужно посоветоваться со старейшинами. По окончании совещания я пошлю за тобой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9567] = {title = "Лицо врага", objective = "Найдите в Наззивиане монумент Наззивуса, возьмите один из иероглифов с монумента и вернитесь к воздаятельнице Аалезии на Кровавую заставу.", description = "Приветствую, <класс>. Приятно видеть на Кровавой заставе, еще <одного искателя/одну искательницу> приключений. Конечно, эльфы крови сейчас представляют наиболее явную угрозу; однако на острове Кровавой Дымки есть и другие твари, от которых нельзя ждать ничего хорошего.\n\nСатиры из племени Наззивус – источник постоянной тревоги для нас. Это ужасные существа – демонические создания, использующие черную магию; порча, порожденная падением \"Экзодара\", питает их и придает им сил.\n\nМы должны сдержать сатиров – но для этого нам нужно знать о них как можно больше. Отправляйся на юго-запад в Наззивиан, отыщи их нелепый монумент и попробуй что-нибудь разузнать.", progress = "Удалось ли тебе узнать хоть что-то новое о сатирах из племени Наззивус?", completion = "Прекрасно, Ревектор! А теперь посмотрим, о чем мне поведает этот иероглиф - от этого зависят наши дальнейшие действия.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9568] = {title = "Лучшая защита", objective = "Воздаятельница Аалезия с Кровавой заставы просит убить 10 сатиров, 5 разбойников и 5 скверноподанных из племени Наззивус.", description = "Дела обстоят хуже, чем я думала, <имя>. Нам, дренеям, хорошо известно, что происходит с теми, кто решается продать душу Легиону в обмен на обещание бессмертия и могущества...\n\nПлемя сатиров этого острова – Наззивус – это потомки злосчастных существ, вступивших в союз с Легионом. Боюсь, они найдут способ использовать оскверненные кристаллы как оружие и обратят их силу против нас.\n\nТы <видел/видела>, во что кристаллы превратили эту землю - так представь себе, на что окажутся способны сатиры, если к ним попадет такое оружие!.. Отправляйся на северо-запад, в Наззивиан, и помни: иногда нападение - лучшая защита!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9569] = {title = "Противостояние", objective = "Убейте Зевракса, 5 аксариенских тенеловов и 5 аксариенских призывателей огня, соберите 5 оскверненных кристаллов и отнесите их на Кровавую заставу воздаятельнице Аалезии.", description = "Теперь, когда мы дали сатирам понять, что не уйдем с этой земли, пора показать, что терпеть здесь отродий Пылающего Легиона мы также не намерены.\n\nСлишком долго дренеи стремились избежать столкновения с Легионом и его приспешниками, <имя>; слишком долго - и это не принесло нам ничего, кроме горестей. Когда псы Легиона находили нас, они не щадили никого.\n\nСатиры не должны воспользоваться оскверненными кристаллами, оставшимися после гибели \"Экзодара\"; тем более они не должны использовать эти кристаллы в качестве оружия. Отправляйся на север, в Аксариен, разыщи предводителя сатиров, убей его и верни нам те кристаллы, которые он уже успел собрать.", progress = "<Воздаятельница Аалезия смотрит словно бы сквозь вас; она явно обдумывает предстоящую борьбу с сатирами.>\n\nТы исполнил мою просьбу? Сразился c предводителем сатиров?", completion = "Лишившись своего предводителя, а заодно и уже собранных оскверненных кристаллов, сатиры стали значительно менее опасными для нас. Но лишь Предвечному Свету ведомо, сколько здесь еще этих злосчастных тварей...\n\nМы – я и вестник Миколаас – благодарны тебе за помощь: если бы не это, сатиры стали бы для нас слишком серьезной угрозой. Решимость и отвага – вот ключ к победе над Легионом и его приспешниками!", rewards = "Арбалет охотникаИскра светаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9570] = {title = "Куркен-жмуркен", objective = "Убейте Куркена и принесите его шкуру Курцу Прорицателю в логово племени Тихвой на острове Лазурной Дымки.", description = "Когда кристальная буря улеглась, в нашу деревню явилось чудище из древних легенд. Оказалось, что этого зверя, Куркена, привели сюда дикосовухи. Он погубил многих моих соплеменников, пытавшихся отстоять родную деревню, и с тех пор еще больше погибло, попытавшись бросить ему вызов.\n\nМне было видение, что победа над тварью близка. Я не сомневаюсь, что именно тебе суждено совершить этот подвиг, <имя>. Ты - наша последняя надежда. Ступай в логово племени Тихвой, убей Куркена и в доказательство принеси мне его шкуру.", progress = "<Курц недовольно ворчит.>", completion = "Избранный вернулся с победой!\n\nПророчество почти исполнилось. Что же до шкуры...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9571] = {title = "Шкура Куркена", objective = "Отнесите шкуру Куркена Мурдо в логово племени Тихвой.", description = "Отнесите шкуру Куркена Мурдо на другою сторону деревни. Он сделает из нее все, что вы захотите.", progress = "Привет герою!", completion = "Такой крепкой брони я еще не делал! Пусть она служит тебе верой и правдой, Небрить.", rewards = "Жакет из шкуры КуркенаБерезовые колодкиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9572] = {title = "Ослабить оборону валов", objective = "Убейте начальника стражи Гарголмара, Омора Неодолимого и дракона Назана. Принесите руку Гарголмара, копыто Омора и голову Назана Каса'ресу в Траллмар на Полуострове Адского Пламени.", description = "Нужно торопиться, у нас мало очень времени. На карту поставлено само существование Траллмара!\n\nМы зажаты между цитаделью Адского Пламени на западе и Пылающим Легионом на востоке. Если внимание Легиона окажется привлечено к Темному порталу, то мы сумеем нанести удар оркам Скверны. Но для этого надо будет прорваться через валы цитадели Адского Пламени!\n\nОтправляйся к валам, убей тех, кто командует там орками Скверны, а доказательства их смерти принеси Каза'ресу.", progress = "Менгиле, точно? Сток-Тон говорил, что ждет твоего доклада.\n\nНадеюсь, ты принес хорошие новости?", completion = "Неплохое начало. Смерть командиров внесет панику в их ряды. Обезвредив их артиллерию, мы получим достаточно времени, чтобы подобраться к самой цитадели.\n\nНо орков по-прежнему больше, чем может охватить глаз, так что жди нового задания.\n\nНо пока я тобой доволен. Можешь выбрать в оружейной Траллмара, что захочешь.", rewards = "Воинское нефритовое наплечьеБоевые рукавицы верностиСапоги уверенной походкиОплечье магической мощиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9573] = {title = "Вождь Умуру", objective = "Убейте вождя Умуру и 9 безумных диких совухов.", description = "Я – Тихвой Младший, наследник рода. Как видишь, мои защитники выстроили ловушку для буйных диких совухов, нападающих на нас изнутри логова. Пока что нам удается удерживать их, но ни один из воинов не смог проникнуть внутрь. Если ты сумеешь пробраться туда и убить их главаря, у нас появится шанс нанести им решающий удар!\n\nОтыщи вождя Умуру и уничтожь его. Прикончи всех безумных диких совухов, которые тебе встретятся.", progress = nil, completion = "Теперь у нас появилась возможность выкурить озверевших тварей из форта! Я немедленно отправляю туда бойцов! Племя Тихвой благодарит тебя за помощь, Небрить!", rewards = "Укрепленные нарукавникиПрочный кожаный поясВы получите:\n\n"}
MultiLanguageQuestData['ru'][9574] = {title = "Отравленные скверной", objective = "Принесите на Кровавую заставу 6 кусков коры, покрытой кристаллами, и отдайте Морэ.", description = "С нашим прибытием жизнь на острове Кровавой Дымки изменилась навсегда. Обломки от падения \"Экзодара\" разбросаны по всему острову – боюсь, это оказывает скверное влияние на здешнюю природу.\n\nОднако прежде чем делать окончательные выводы, мне хотелось бы получить некоторые данные. Похоже, в первую очередь действие кристаллов сказалось на деревьях; вероятно, у древней должны проявляться ярко выраженные симптомы заражения... Думаю, я смогу начать углубленные исследования, если ты принесешь мне образцы коры оскверненных древней.", progress = "Ну как, удалось тебе найти нужные образцы?", completion = "Для моих исследований здесь более чем достаточно. Благодарю, Тхаали. Если тебе удастся найти другие свидетельства того, что кристаллы являются источником скверны, отравляющей остров, - дай мне знать.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9575] = {title = "Ослабить оборону валов", objective = "Убейте начальника стражи Гарголмара, Омора Неодолимого и дракона Назана. Принесите руку Гарголмара, копыто Омора и голову Назана Пушкаренку в Оплот Чести на полуострове Адского Пламени.", description = "Нужно торопиться, у нас очень мало времени. На карту поставлено само существование Оплота Чести!\n\nМы зажаты между цитаделью Адского Пламени на западе и Пылающим Легионом на востоке. Если внимание Легиона будет привлечено к Темному порталу, то мы сумеем нанести удар оркам Скверны. Но для этого надо будет прорваться через бастионы цитадели Адского Пламени!\n\nОтправляйся на бастионы, убей тех, кто командует там орками Скверны, а доказательства их смерти принеси Пушкаренку.", progress = "Варкинсан, точно? Чадвик говорил, что ждет твоего доклада.\n\nНадеюсь, ты принес хорошие новости?", completion = "Знаешь, что я ненавижу больше, чем ошибаться? Проигрывать деньги. Я поспорил, что ты не справишься с заданием, дорогуша.\n\nНеплохое начало. Смерть командиров внесет панику в их ряды. Обезвредив их артиллерию, мы получим достаточно времени, чтобы подобраться к самой цитадели.\n\nНо орков по-прежнему больше, чем может охватить глаз, так что жди нового задания.\n\nНо пока я тобой доволен. Можешь выбрать в оружейной, что захочешь.", rewards = "Воинское нефритовое наплечьеБоевые рукавицы верностиСапоги уверенной походкиОплечье магической мощиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9576] = {title = "Ожерелье Жестокого Плавника", objective = "Покажите подвеску красного кристалла Морэ на Кровавой заставе.", description = "Грубо сработанная подвеска украшена слабо светящимся кристаллом. Хотя его пульсирующий свет еле виден, от кристалла исходит отчетливое ощущение угрозы.\n\nЧто могло заставить Жестого Плавника создать эту подвеску?.. Как бы то ни было, эта вещь кажется слишком важной, чтобы не придавать ей значения. Необходимо показать ее кому-нибудь на Кровавой заставе.", progress = "Что это у тебя?", completion = "Занятно, |3-6(Друид), чрезвычайно занятно... Кажется, нам еще никогда не приходилось видеть, чтобы мурлоки носили такие украшения.\n\nСудя по тому, что мы знаем об оскверненных кристаллах, мурлок, носивший эту подвеску, полагал, что она дает ему власть над сородичами... Не удивлюсь, если он был много крупнее и сильнее мурлоков своего клана.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9577] = {title = "DAILY TEST QUEST (PVP)", objective = "Поговорите с <QUESTGIVER> в <AREA>.<NYI>Ищите <QUESTGIVER> в <LOCATION>. Она/он желает, чтобы вы помогли им в трудном деле.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "<NYI>Ищите <QUESTGIVER> в <LOCATION>. Она/он желает, чтобы вы помогли им в трудном деле.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9578] = {title = "В поисках Галена", objective = "Найдите Галена, мужа Морэ.", description = "Скажи, <имя>, часто ли ты вспоминаешь свою семью?.. На \"Экзодаре\" было много семей, но я почти не слышала о таких, которым удалось воссоединиться.\n\nСама я пытаюсь найти хоть какие-то следы моего мужа, Галена, который работал техником в криогенном блоке. Обломки криогенного блока находятся к западу отсюда, и там тьма тьмущая эльфов крови!\n\nНо я обязана выяснить, что случилось с Галеном! Даже весть о его смерти будет лучше этой страшной неизвестности! Вот смотри: видишь эту подвеску? У моего мужа точно такая же – их нам подарила моя сестра.", progress = nil, completion = "На трупе одежда экзодарских техников, но подвески, о которой говорила Морэ, нет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9579] = {title = "Судьба Галена", objective = "Принесите на Кровавую заставу амулет Галена и отдайте его Морэ.", description = "По рассказу Морэ невозможно опознать тело; однако заметно, что его одежду разорвали, когда обыскивали труп в поисках ценностей.\n\nЭльфы крови, живущие в этих местах, несомненно, забрали бы все мало-мальски ценное, тем более драгоценный амулет Галена.\n\nКонечно, то, что Гален погиб при крушении, станет для Морэ тяжелым ударом. Но возможно, ей будет немного легче, если удастся отобрать у эльфов крови амулет ее супруга...", progress = "<Во взгляде Морэ читается надежда.>\n\nСкажи, удалось ли тебе отыскать хоть какие-то следы Галена?", completion = "&lt;Вы рассказываете Морэ о том, что удалось обнаружить среди обломков криогенного блока&gt;.\n\nЗначит... Он...\n\nГде-то в глубине души я знала, но никак не могла заставить себя поверить в это. Ты принес не те новости, которых я ждала, но прими мою искреннюю благодарность за то, что нашел Галена.", rewards = "Сапоги оператора криогенного блокаСапоги лаборантаЛегкие сетчатые сапогиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9580] = {title = "Вскормленные медвежатиной", objective = "Принесите зверолову Лисеону на Кровавую заставу 8 кусков мяса с боков старых бурых медведей.", description = "Полагаю, за время, проведенное на острове Кровавой Дымки, ты <успел/успела> понять, что после нашего прибытия все здесь переменилось. Однако мой опыт свидетельствует о том, что натуральные продукты можно использовать всегда – даже если их источником является природа, подобная здешней.\n\nРесурсов у нас мало, так что приходится полагаться исключительно на собственные умения. Я вот поставляю в лавки медвежье мясо – знаешь ведь, на острове медведей немало; а если мясо готовить, соблюдая некоторые предосторожности, оно вполне съедобно. Так вот, я тут подумал: ты все равно бродишь по всему острову – может, если тебе по дороге попадется пара медведей, поможешь нам с припасами?", progress = "Ну что, Рудель, как охота?", completion = "На некоторое время нам этих припасов хватит. Да и мне найдется чем заняться: буду готовить еду... Благодарю тебя, Рудель.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9581] = {title = "Изучение кристаллов", objective = "Добудьте образец кристалла с места крушения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте предвестнику Миколаасу.", description = "Добро пожаловать на Кровавую заставу, <класс>. Конечно, основная моя задача – защита заставы, но наши вожди в Экзодаре возложили на меня и другие обязанности.\n\nПроблема в том, что на острове слишком опасно – а мы не можем рисковать нашими исследователями, посылая их на смерть. Но при этом мне нужно добыть образцы кристаллов из разных районов острова. Понимаешь, к чему я веду?\n\nПервый образец – из тех, что мне нужны, – можно найти в обломках корабля к югу отсюда. Он недалеко, только мост перейти... правда, как я слышал, в тех местах водится множество опустошителей...", progress = "Ну как, удалось тебе раздобыть первый образец кристалла?", completion = "Этот осколок кристалла даст нашим исследователям базу для сравнения – он принесен из той части острова, которую не так сильно затронула скверна.\n\nОднако же пока не имеет смысла посылать образец в Экзодар – сначала нам нужно собрать полный набор кристаллов. Начало, безусловно, положено. Поверь, если ты поможешь мне и в остальном, я сам прослежу за тем, чтобы твои усилия были вознаграждены.", rewards = "Штаны с кристаллическими крапинкамиПокрытые осколками поножиУкрашенные кристаллами набедренникиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9582] = {title = "Силой единой", objective = "Откройте клетку смертоносного опустошителя, убейте его и вернитесь к Руаде на Лазурную заставу на острове Лазурной Дымки.", description = "Когда наш корабль разбился, весь зверинец разметало по северо-восточному побережью. Мне дали ключ от клетки одного из наиболее страшных зверей, смертоносного опустошителя. Панцирь у этой твари не очень прочный, зато на нее почти не действуют заклинания. Ее нужно убить простым клинком.\n\nВозьми этот ключ и избавь опустошителя от плена и страданий. Не допусти, чтобы он сбежал и причинил еще больший вред окружающей среде.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9583] = {title = "Omar's Test Quest", objective = "Принесите Омару ткани.", description = "Благородная душа жертвует мне ткань.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9584] = {title = "Второй образец", objective = "Добудьте образец кристалла с места столкновения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте его предвестнику Миколаасу.", description = "Теперь, когда у нас есть первый кристалл, нам понадобятся другие образцы, которые я мог бы отправить в Экзодар. Увы, там, где можно раздобыть эти кристаллы, тебя поджидает еще большая опасность, чем прежде...\n\nВторой образец ты сможешь найти в лесу Клинков, к северо-западу от Кровавой заставы. Правда, в этом лесу обосновались эльфы крови... Попытайся найти кристалл, который они еще не успели прибрать к рукам и использовать в своих целях, и отколи от него образец.", progress = "Ты сумел добыть второй образец кристалла? Он у тебя с собой?", completion = "*Предвестник Миколаас изучает образец кристалла.*\n\nДолжен сказать, этот образец сильно отличается от предыдущего.\n\n*Предвестник поднимает кристалл и рассматривает его на свет.*\n\nВидишь, как он пульсирует? Весьма, весьма тревожный признак. В своем отчете я непременно отмечу те изменения, которые эльфам крови удалось внести в этот кристалл. Прими мою благодарность, Рудель, твоя помощь неоценима.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9585] = {title = "Последний образчик", objective = "Добудьте образец кристалла с места столкновения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте предвестнику Миколаасу.", description = "Остался всего один образец, и я смогу отправить эти кристаллы в Экзодар. Послушай, <имя>: последний кристалл нужно добыть в Аксариене, оплоте сатиров – а он находится к северо-западу отсюда.\n\nНе знаю, чего можно ждать от этого кристалла, но уверен, что обнаружу в нем следы скверны. Помнишь кристаллы, от которых были отколоты предыдущие образцы? Тебе нужно найти такие же, иначе наши исследователи не смогут провести сравнительный анализ.", progress = "Ну, где последний образец для моего драгоценного набора?", completion = "*Предвестник Миколаас берет последний образец кристалла.*\n\nТеперь мой набор полон. Осталось уложить образцы в ящик и отправить их в Экзодар.\n\n*Похоже, предвестник рад, что покончил с этим заданием.*\n\nНе пойми меня неправильно, Рудель: я уверен, что это очень важные исследования, но у нас тут и без них хватает проблем.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9586] = {title = "Помощь Таваре", objective = "Найдите Тавару и исцелите ее раны.", description = "Тавара, одна из наших травниц, решила пополнить свои запасы и ушла в лес. Ее давно не видно – боюсь, бедняга нуждается в помощи. Я сам не могу пойти на поиски.\n\nПрошу тебя, <класс>, найди ее и исцели, если нужно. Она вышла с Лазурной заставы и направилась на восток, в сторону горячих источников.", progress = nil, completion = "Спасибо, что помог Таваре. Многие не освоились в этих землях и часто забредают туда, где их поджидает смертельная опасность.\n\nЯ почту за честь, если ты примешь в дар это одеяние. Его могут носить только защитники Лазурной заставы и ревностные служители Света.", rewards = "Вы получите:\n\nОдеяния Лазурной заставы"}
MultiLanguageQuestData['ru'][9587] = {title = "Предвестье беды", objective = "Доставьте угрожающее письмо боевому командиру Данату Троллебою в Оплот Чести на полуострове Адского Пламени.", description = "Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква \"И\". Взломав печать, вы с волнением заглядываете в письмо.\n\nПоложительно, его должен прочесть Данат Троллебой!", progress = "Ну, что у нас тут, парень?", completion = "Говоришь, на нем стоит подпись Иллидана? Дай-ка взглянуть.\n\n&lt;Командир читает письмо, задумывается на минуту, затем снова его перечитывает.&gt;\n\nЭто действительно зловещие новости. Мы должны как можно быстрее воплотить в жизнь наш план атаки на цитадель Адского Пламени и Кузню Крови. Ты доказал, что отлично справляешься с работой, так что именно ты этим и займешься.\n\nГанни даст тебе новое задание, думаю, оно будет куда более смертоносным, чем предыдущее.\n\nДа хранит тебя Свет, Варкинсан!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9588] = {title = "Предвестье беды", objective = "Доставьте угрожающее письмо Назгрелу в Траллмар на Полуострове Адского Пламени.", description = "Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква \"И\". Взломав печать, вы с волнением заглядываете в письмо.\n\nПоложительно, его надо доставить Назгрелу в Траллмар!", progress = "Что это за письмо, |3-6(Разбойник)?", completion = "Говоришь, на нем стоит подпись Иллидана? Дай-ка взглянуть.\n\n&lt;Назгрел читает письмо, задумывается на минуту, затем снова его перечитывает.&gt;\n\nЭто действительно зловещие новости. Мы должны как можно быстрее воплотить в жизнь наш план атаки на цитадель Адского Пламени и Кузню Крови. Ты доказал, что отлично справляешься с работой, так что именно ты этим и займешься.\n\nЦентурион Каза'рес даст тебе новое задание, думаю, оно будет куда более смертоносным, чем предыдущее.\n\nЛок'тар огар, Джонниди!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9589] = {title = "Кровь есть жизнь", objective = "Принесите 10 фиалов крови орков Скверны Пушкаренку в Оплот Чести на полуострове Адского Пламени.", description = "Это письмо всех поставит на уши. Если бы мы знали, как были созданы орки Скверны, то наверника бы придумали, как с ними справиться. Будто бы нам было недостаточно Пылающего Легиона на востоке.\n\nТак что нам крупно повезло, моя радость! Тебе придется прогуляться к так называемой Кузне Крови, в цитадель Адского Пламени. Так сказать, в самое пекло.\n\nСтупай, поубивай орков Скверны и добудь образцы их крови.\n\nНадеюсь, ты справишься.", progress = "Ну что, приятель, собрал кровь? Это очень важно, иначе мы бы тебя не просили ее достать.", completion = "Не хрена себе, сказал я себе! На данный момент ты мой самый любимый штатская штафирка из всех жалких штафирок этого жалкого мира.\n\nКлянусь, яйцеголовые выпрыгнут из штанов от радости, когда я выложу перед ними образцы крови. Кто знает, может, мы обнаружим новый способ борьбы с проклятыми скверноорками?", rewards = "Кираса воздаянияЧешуйчатые поножи разоренияГоловной убор лунного совухаПоножи смертоносного копателяВы получите:\n\n"}
MultiLanguageQuestData['ru'][9590] = {title = "Кровь есть жизнь", objective = "Принесите 10 фиалов крови орков Скверны центуриону Каса'ресу в Траллмар на Полуострове Адского Пламени.", description = "Это письмо меня беспокоит, но вовсе не потому, что его написал Предатель. Если мы будем знать, как были созданы орки Скверны, то сумеем победить их! Мало нам атак Легиона с запада, так теперь еще с востока эти проклятые орки!\n\nТы <должен/должна> пробраться в Кузню Крови в цитадели Адского Пламени. Убей орков Скверны, которые тебе попадутся, и принеси мне образцы их крови.", progress = "Ты уже принес кровь? Так быстро?", completion = "Твои способности меня поражают, Менгиле. Уже второй раз ты отправляешься в цитадель Адского Пламени, выполняешь задание и возвращаешься невредимым!\n\nЯ отправлю эту кровь к тем, кто сможет раскрыть ее секреты. Может быть, мы найдем способ все исправить.", rewards = "Кираса воздаянияЧешуйчатые поножи разоренияГоловной убор лунного совухаПоножи смертоносного копателяВы получите:\n\n"}
MultiLanguageQuestData['ru'][9591] = {title = "Приручение зверя", objective = "Используйте тотем приручения и приручите колючего краба. Вернитесь к охотнице Келле Тетиве Ночи.", description = "Когда <класс> избирает свой путь, <его/ее> учат лишь убивать. Мне кажется, тебе пора сделать следующий шаг.\n\nФурболги из племени Тихвой придумали, как можно приручить зверя, не тратя на это долгие месяцы. Они вырезают тотем в форме определенного животного, и он позволяет установить временную связь с существами этого вида.\n\nНачнем первый урок. Возьми этот тотем и приручи при его помощи одного из колючих крабов на западном побережье острова.", progress = "Помогла ли магия тотема приручить колючего краба? Эти мелкие твари на редкость вздорные!", completion = "Не сомневаюсь, первым делом тебе пришлось столкнуться с несговорчивостью крабов. Так и машут клешнями, пока не убедятся, что ты их не собираешься варить.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9592] = {title = "Приручение зверя", objective = "Используйте тотем приручения и приручите большого лесонога, после чего вернитесь к охотнице Келле Тетиве Ночи.", description = "Крабы, конечно, злобные твари, но лесоног - гораздо более сложное испытание. Чем сильнее будущий союзник, тем больше стойкости требуется от охотника во время приручения.\n\nВозьми этот тотем приручения и приручи большого лесонога. Их можно найти на севере острова Лазурной Дымки.", progress = "Лесоноги - сильные птицы. Иногда на них по ошибке нападают хищники, и последствия оказываются плачевны.", completion = "Похоже, лесоног не выклевал тебе глаза.\n\n*Келла отводит взгляд.*\n\nХотя я на это и не рассчитывала, разумеется!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9593] = {title = "Приручение зверя", objective = "Используйте тотем приручения и приручите ночного ловца. Вернитесь к охотнице Келле Тетиве Ночи.", description = "Во время приручения большого лесонога ты, должно быть, <заметил/заметила> огромных кошек, зовущихся ночными ловцами. Эти хищники смертельно опасны... но и союзники из них превосходные.\n\nПриручи ночного ловца при помощи тотема приручения, отправляйся с ним на охоту и береги его. Как закончишь - возвращайся ко мне.", progress = "The nightstalker is basically a big kitty with razor sharp claws and an appetite for flesh...", completion = "I must say, &lt;имя&gt;, you have learned far more quickly than I first imagined.  Looks like we won't need to use this last taming totem.  And honestly, I'm not even sure what it is.  It appears to be some sort of monstrous lizard with wings and a long tail.  Oh well, perhaps another time!\n\nYou've experienced enough to try it on your own now, without the aid of a taming totem.  Good luck!", rewards = "Вы изучите:\n\nУрок приручения\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9594] = {title = "Знаки Легиона", objective = "Убейте 8 сатиров из племени Наззивус и 8 скверноподданных из племени Наззивус, а затем отнесите латный доспех Тзерака воздаятельнице Аалезии на Кровавую заставу.", description = "Это обломок доспеха, выкованного из совершенно черного металла, который, похоже, поглощает свет. Вроде бы он даже не зачарован, но с первого взгляда очевидно, что с ним что-то не так.\n\nТакие доспехи носит лишь одна армия – армия Пылающего Легиона. Присутствие Легиона здесь может означать только одно – они собираются натравить островных сатиров на дренеев.\n\nСначала разберитесь с местными сатирами, затем вернитесь на Кровавую заставу и покажите этот обломок доспеха воздаятельнице Аалезии.", progress = "Да, |3-6(Маг)? Что это у тебя?", completion = "Хорошо, что ты принес мне эту броню, Ревектор. Вне всякого сомнения, это часть доспехов солдата Пылающего Легиона.\n\nКак я и опасалась, сатиры племени Наззивус снова наладили связь с Легионом. Если их не остановить, сатиры и их союзники-демоны уничтожат нас. Я должна немедленно сообщить обо всем предвестнику Миколаасу!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9595] = {title = "Контроль", objective = "Убивайте мурлоков с Илистого Берега до тех пор, пока не появится призрак кель'дорайского мага, затем уничтожьте его. После этого поговорите с Бати в Чертоге Света Экзодара.", description = "Ты <решил/решила> пойти путем <класс> и поэтому тебе надо научиться контролировать свои силы. Неразумное применение магии может совращать души и разрушать миры.\n\nТы поймешь это, когда встретишься с существом, одержимым темной стороной магии. Отправляйся на северо-западные пляжи острова Лазурной Дымки и воспользуйся силой своих заклинаний для уничтожения мурлоков. Подобная демонстрации твоей мощи обязательно привлечет внимание злобного призрака кель'дорайского мага, обитающего там. Убей его. Затем ступай к Бати, она находится в Чертоге Света Экзодара.", progress = nil, completion = "Творя заклинания, противься их соблазнам, пользуйся ими только ради благих целей. Надеюсь, что, глядя на призрака, ты поняла, в кого можешь превратиться по собственной беспечности – в бездумного раба магии.", rewards = "Посох залогаВам дадут возможность выбрать одну из следующих наград:\n\nСфера залога\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9598] = {title = "Искупление", objective = "Прочтите Фолиант Божественности и поговорите с Джоль.", description = "Я - наставница паладинов. Я та, кто ведет их стезей добродетели к Истинному Свету, дабы они защищали наш народ от любой угрозы.\n\nИ для тебя пришло время сделать первый шаг на пути праведности. Если ты решишься принять этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, чего от тебя ожидают. Постигнув мудрость, заключенную в этой книге, ты откроешь в себе новые, удивительные способности.", progress = "С возвращением, Фах.", completion = "Надеюсь, ты все это время изучал фолиант?\n\nВ таком случае ты должен быть готов к испытанию. После крушения \"Экзодара\" в этих новых землях много дел для таких, как мы: всегда есть те, кто нуждается в помощи, сострадании и понимании; всегда есть враждебные твари, которых необходимо уничтожать...\n\nДоказав, что ты обладаешь достаточным терпением, чтобы помогать ближним, ты тем самым покажешь, что твои помыслы чисты и что ты воистину служишь Свету.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9600] = {title = "Искупление", objective = "Воскресите молодого фурболга-шамана из племени Тихвой при помощи знака Жизни, а затем вернитесь к Джоль.", description = "Итак, <имя>, твоя задача - помочь нашим новым союзникам, фурболгам из племени Тихвой.\n\nНесколько молодых шаманов наткнулись на лагерь Косолапов и погибли, все до единого. Возьми этот знак жизни и воскреси одного из шаманов.\n\nАнклав Косолапов находится к востоку от дороги, сразу за мостом, соединяющим острова Лазурной и Кровавой Дымки. Когда выполнишь задание, возвращайся ко мне.", progress = nil, completion = "Не стоит смущать души тех, кому тебе довелось помочь. Видишь ли, те, кто волею судьбы был возвращен в мир живущих, некоторое время обычно пребывают в растерянности. Думаю, потрясение от встречи с чужаком, да еще и непривычного вида, может оказаться слишком большим испытанием...\n\nБлагодаря тебе юный шаман сумел пережить это жестокое испытание; полагаю, ты вполне достоин того, чтобы использовать силу священного Символа.", rewards = "Вы изучите:\n\nИскупление\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9601] = {title = "В Бастион", objective = "Поговорите с Меларом Клинком Рассвета из Бастиона.", description = "С тобой желает поговорить рыцарь крови Мелар Клинок Рассвета. Мелара можно найти в Бастионе, он охраняет проход между Тирисфальскими лугами и Западными Чумными землями.\n\nТерпение - не его сильная сторона. Не советую заставлять его ждать.", progress = nil, completion = "А... Похоже, время пришло.\n\n*Мелар с заговорщическим видом кивает.*", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9602] = {title = "Избавь их от лукавого...", objective = "Отнесите переписку предателя экзарху Менелаусу на Лазурную заставу.", description = "Сообщи об этом своему народу, <имя>. Хотя твои подвиги нарушили планы Кель'таса и его темного властителя, негодяи не оставят попыток напасть на нас.\n\nОтнеси переписку предателя вождям своего народа. Они должны взглянуть на это своими глазами. Быть может, они лучше поймут, о чем здесь идет речь.", progress = "Ты вернулся!", completion = "*Экзарх Менелаус берет у вас письмо и начинает читать.*\n\nПроклятье... проклятье на их головы. Среди нас затесался шпион, следивший за каждым нашим шагом! И давно ли?\n\nЯ немедленно сообщу об этом Велену!\n\nТы оказал нам огромную услугу, Шаноб. Будь готов, я свяжусь с тобой, как только Пророк укажет мне, что делать.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9603] = {title = "Лежанки, лекарства и прочая ерунда", objective = "Отвезите список Челланы на Лазурную заставу укротителю гиппогрифов Залдаану.", description = "Добро пожаловать на Лазурную заставу, <класс>. Не обращай внимания на беспорядок. Все почему-то считают, что, как только напишешь на вывеске \"Таверна\", так внутри сразу сами собой образуются и мебель, и припасы, и все такое. А если таверна строится с нуля?..\n\nНам удалось приспособить под таверну одну из спасательных капсул; но пока тут нет мебели и запаса лекарств, это всего лишь шикарная палатка. Нургуни из Экзодара предложила собрать для меня кое-какие припасы – хотя бы то, что необходимо на первый случай, – но мне нужно, чтобы кто-нибудь отвез ей список...", progress = "Приветствую тебя, Тэррат. Что, тебе нужен гиппогриф?", completion = "Итак, тебе нужно отправиться в Экзодар?\n\nПуть неблизкий - но ты не беспокойся, я знаю, как быстро доставить тебя туда.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9604] = {title = "На крыльях гиппогрифа", objective = "Возьмите у Залдаана гиппогрифа и летите в Экзодар. В Экзодаре отдайте Нургуни список Челланы. Нургуни можно найти у Трона Наару в Экзодаре.", description = "За небольшую плату ты можешь взять одного из моих гиппогрифов, чтобы долететь до Экзодара.\n\nНет ничего быстрее и безопаснее гиппогрифа – в особенности для тех, кому необходимо доставить важное послание. Захочешь прокатиться – подходи, и мы обо всем договоримся.", progress = "Здравствуй, друг. Похоже, тебе пришлось пройти долгий путь... Чем я могу тебе помочь?", completion = "Итак, ты привез список Тофера. Прекрасно! Я надеялась, что уже сегодня этот список будет у меня. Ну-ка, посмотрим, что там ему нужно...\n\n*Нургуни читает список и начинает складывать разные предметы в ящик.*\n\nТут большая часть вещей, которые ему нужны. Детали кроватей слишком велики, чтобы отправлять их с гиппогрифом... Ну ничего, я договорюсь и отправлю их на повозке.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9605] = {title = "Укротитель гиппогрифов Стефанос", objective = "Найдите Стефаноса у трона наару, что в Экзодаре, и наймите гиппогрифа для возвращения на Лазурную заставу.", description = "А вот и ящичек, <имя>, держи. Думаю, тут есть все, что нужно Челлане, чтобы дела в таверне пошли на лад. Передай ей, что она без стеснения может заказывать все необходимое. Лазурной заставе срочно требуется помещение, где можно было бы ухаживать за ранеными, а также место, где путешественники смогут восстановить свои силы.\n\nКогда будешь <готов/готова> вернуться на Лазурную заставу, найди сначала Стефаноса – он обычно бывает у трона наару, что в Экзодаре.", progress = "И куда же ты направляешься, |3-6(Шаман)?", completion = "Итак, ты возвращаешься на Кровавую заставу и везешь туда груз? Отлично, |3-6(Шаман), никаких проблем! Мы с тобой еще раз поговорим, а потом отправим тебя вместе с вещами туда, куда надо.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9606] = {title = "Возвращение к корчмарю Челлане", objective = "Договоритесь со Стефаносом и наймите у него гиппогрифа для путешествия на Лазурную заставу. На заставе доставьте припасы Нургуни корчмарю Тоферу Челлане.", description = "Если мне память не изменяет, укрощением гиппогрифов на Лазурной заставе занимается Залдаан. Если тебе уже приходилось с ним встречаться, значит, ты можешь отправиться к нему на одном из моих гиппогрифов.\n\nС гиппогрифами есть одна тонкость, о которой надо помнить: их обучают возвращаться в родной город, но к другому укротителю гиппогрифов они отнесут тебя только в том случае, если тебе уже доводилось у него бывать.\n\nПоскольку ты <прибыл/прибыла> сюда на одном из гиппогрифов Залдаана, тебе не составит труда вернуться на Лазурную заставу и отвезти туда припасы.", progress = "Рад твоему возвращению, Артешам. Ну как, удалось Нургуни достать все, что было в моем списке?", completion = "&lt;Тофер забирает ящик и выслушивает сообщение о том, что крупные предметы будут отправлены на повозке.&gt;\n\nВеликолепно! Теперь мне наконец-то удастся поставить у себя хотя бы несколько кроватей и обеспечить раненых первой помощью!\n\nСловами не передать, как я тебе благодарен, Артешам, и не только я, но и все защитники Кровавой заставы!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9607] = {title = "В сердце ярости", objective = "Детально изучите Кузню Крови и доложите об увиденном командиру армии Данату Троллебою в Оплот Чести на полуострове Адского Пламени.", description = "<класс>, немеденно собирай силы и отправляйся на разведку к Кузне Крови в цитадели Адского Пламени! Да-да, вот прямо сегодня, моя радость!\n\nНаши маги сумели засечь, что там происходит что-то из ряда выходящее. Но дальшейшее наблюдения оказалось заблокировано очень мощной защитной магией. Это вам не баран чихнул!\n\nТебе придется столкнуться с жестоким сопротивлением - ни одна группа из тех, что мы отправили на задание, не вернулась.\n\nРазведай все детали, вернись и доложи о результатах боевому командиру.", progress = nil, completion = "У НИХ ЕСТЬ ВЛАСТИТЕЛЬ ПРЕИСПОДНЕЙ?!\n\n&lt;Боевой командир оглядывается на остальных и понижает голос.&gt;\n\nЭто все объясняет. Должно быть, они использовали кровь этого властителя преисподней, чтобы создать орков Скверны. Значит, они тоже связаны с Пылающим Легионом. Если они смогли это сделать с коричневыми орками, значит, рано или поздно доберутся и до зеленых. Если из Темного портала выйдут орки новой Орды, нам придется несладко.\n\nМы должны нанести превентивный удар, и как можно скорее!", rewards = "Отлично изготовленная накидкаВам дадут возможность выбрать одну из следующих наград:\n\nСвятое кольцо исцеленияБагровая подвеска ясности\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9608] = {title = "В сердце ярости", objective = "Детально изучите Кузню Крови и доложите об увиденном Назгрелу из Траллмара на Полуострове Адского Пламени.", description = "<класс>, ты <должен/должна> собрать отряд и немедленно отправиться в Кузню Крови, в цитадель Адского Пламени! Магические кристаллы показывают, что там происходит что-то странное. Но понять, что именно, не удается, потому что видение заблокировано мощной защитной магией. Ясно только одно, - там творится что-то очень важное.\n\nРассчитывай, что встретишься с жестоким сопротивлением. Ни одна из групп, которые мы отправили на это задание, не вернулась.\n\nРазведай детально, что там происходит, и доложи Назгреллу, советнику Тралла.", progress = nil, completion = "У НИХ ЕСТЬ ВЛАСТИТЕЛЬ ПРЕИСПОДНЕЙ?!\n\n*Назгрел оглядывается на остальных и понижает голос.*\n\nЭто все объясняет. Должно быть, они использовали кровь этого властителя преисподней, чтобы создать орков Скверны. Значит, они тоже связаны с Пылающим Легионом. Если они смогли сделать это с коричневыми орками, значит, рано или поздно доберутся и до нас!\n\nМы должны нанести превентивный удар, и как можно скорее!", rewards = "Отлично изготовленная накидкаВам дадут возможность выбрать одну из следующих наград:\n\nСвятое кольцо исцеленияБагровая подвеска ясности\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9609] = {title = "Помощь дозорному Биггсу", objective = "Найдите дозорного Биггса на Болоте Печали.", description = "Магтур сообщил мне, что дозорному, который находится неподалеку, нужна помощь. Очевидно, караван, который он сопровождал из Темнолесья, был атакован Заблудшими. Сдается мне, он единственный, кто выжил после этого нападения.\n\nОн сейчас где-то к югу отсюда. Прошу тебя, <класс>, помоги ему.", progress = nil, completion = "Тебя послали дренеи из Убежища? Как странно.\n\nЧто же, я не в том положении, чтобы отказываться от помощи. Спасибо, что пришел, |3-6(Шаман)!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9610] = {title = "Озеро Слез", objective = "Добудьте 5 артефактов Атал'ай и вернитесь с ними к Холаару в Убежище на Болото Печали.", description = "Я интересуюсь прошлым Азерота. Не хочешь ли мне помочь?\n\nЗдесь в трясинах по соседству находится весьма интересная в историческом отношении местность, в которое я и попросил бы тебя отправиться. К юго-востоку отсюда расположено озеро Слез. Говорят, что на его берегах и в глубинах спрятаны артефакты цивилизации троллей Атал'ай.\n\nНо берегись, озеро охраняет Сомнус, древний зеленый дракон и его сородичи, а само оно просто кишит плотоядной рыбой.", progress = "Я жду, пока ты соберешь достаточно артефактов Атал'ай, чтобы можно было начать их изучение. Я просто жажду узнать, что случилось с этой некогда великой цивилизацией.", completion = "Благодарю тебя, |3-6(Друид). Изучение этих артефактов займет меня на какое-то время. Как еще мы, Падшие и дренеи сможем приспособиться к этому миру, если мы не можем понять его истории?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9612] = {title = "Большое спасибо!", objective = "Поговорите с экзархом Менелаусом на Лазурной заставе.", description = "Ты <спас/спасла> мне жизнь, <имя>! Спасибо огромное! Если бы не ты, эта тварь разорвала бы меня на части.\n\nЕсли будешь на Лазурной заставе, расскажи о своем подвиге экзарху. Не сомневаюсь, он очень обрадуется!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9616] = {title = "Бандиты!", objective = "Отнесите сообщение эльфов крови экзарху Менелаусу на Лазурную заставу.", description = "Похоже, это объявление о награде. Язык эльфов крови вам непонятен, но на картинке изображен мертвый дреней, улыбающийся эльф крови, попирающий его труп, и символ, вероятно, означающий денежные единицы.\n\nОказывается, они хотят истребить дренеев! Следует сообщить об этом экзарху.", progress = "Да? Я очень занят, Шаноб.", completion = "Клянусь безбородой кубической головой О'роса! Хорошо, что ты принес это мне, Шаноб. Эльфы крови жаждут нашей... хм, крови. Необходимо уведомить Велена! Прими это в награду.", rewards = "Иссеченные в бою рукавицыИссеченные в бою перчаткиИссеченные в бою рукавицыВы получите:\n\n"}
MultiLanguageQuestData['ru'][9617] = {title = "На поиски Странников", objective = "Поговорите с лейтенантом Вестницей Рассвета в обители Странников.", description = "Лейтенант Вестница Рассвета в обители Странников созывает к себе всех, кто посвятил себя ремеслу охотника. Тебе стоит повидаться с ней, <имя>. Она подлинный светоч мудрости для всех нас.\n\nОбитель Странников находится к югу от Луносвета.", progress = nil, completion = "Хорошо, что ты здесь, Тсой. Наших союзников все меньше, и не всем сторонникам нашего дела можно доверять. Именно поэтому мы, следопыты, обращаемся за помощью к природе.\n\nВ лесу ты найдешь помощников, которые никогда не предадут тебя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9618] = {title = "Возвращение с донесениями", objective = "Отнесите донесения Келтуса Темного Листа Зеланису в Луносвет.", description = "Да, ловкости рук тебе не занимать! Несомненно, тебе эти донесения доверить можно.", progress = "Ну что, удалось тебе обнаружить Келтуса?", completion = "Что, это все от него? Да уж, потрудился Келтус на славу!\n\nВот уж всем разбойникам разбойник! Он редко выполняет приказы буквально и часто поступает по своему разумению. Но не пойми меня неправильно: Келтус - один из наших лучших шпионов, без него мы как без рук.\n\nНу, и ты сегодня неплохо потрудилась. Вот, возьми этот клинок - и вонзи его в спину врагу!", rewards = "Вы получите:\n\nКлинок хитрости"}
MultiLanguageQuestData['ru'][9619] = {title = "Руна призыва", objective = "Используйте камень Бездны, чтобы призвать демона Бездны в деревню Золотистой Дымки, одолейте демона и вернитесь к Талионии в Луносвет.", description = "В камне Бездны проступает многоярусное здание, по которому бродят призрачные фигуры. По мере того как изображение становится отчетливее, появляются все новые здания. Судя по всему, это деревня Золотистой Дымки.\n\nВнезапно крыши и кроны деревьев проносятся мимо, и открывается путь в деревню Золотистой Дымки, ведущий вдоль реки Элрендар на запад.\n\nСтупайте туда; оказавшись там, используйте камень пустоты близ руны призыва на вершине центрального здания и повергните вызванного демона Бездны. Только после этого вы можете вернуться к своей наставнице.", progress = "Прошла ли ты по пути, указанному тебе камнем Бездны?", completion = "Я рада видеть тебя здесь, Котячий. Немало учеников погибло в битве с демоном Бездны; немало и таких, кого погубил сам камень Бездны.\n\nТеперь этот демон Бездны  подчиняется только тебе. Используй его с умом!", rewards = "Вы изучите:\n\nПризыв демона Бездны\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9620] = {title = "Пропавшие картографы", objective = "Предвестник Миколаас просит разыскать группу разведчиков, которую он послал к развалинам Лорет'Арана, и помочь группе чем только возможно.", description = "После того как мы обосновались здесь, на Кровавой заставе, я посылал разведовательные группы, чтобы составить более точные карты острова. Обычно разведчики возвращались целыми и невредимыми и исправно снабжали меня необходимыми сведениями; но группа, которую я отправил на восток, к развалинам, так и не вернулась.\n\nБоюсь, с ними что-то случилось... но нас не так много, чтобы снаряжать поисковую экспедицию. Прошу тебя, <имя>, разыщи их! Помоги им, если они нуждаются в помощи. Надеюсь, они вернутся – и не с пустыми руками...", progress = nil, completion = "Живых не осталось. Разведчики-дренеи погибли, сраженные оружием наг. Их вещи разбросаны по земле, и только кристаллы с исследовательскими данными исчезли бесследно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9621] = {title = "Посол к Орде", objective = "Отнесите письмо от Лор'темара Терона леди Сильване Ветрокрылой в Подгород, столицу Отрекшихся в Тирисфальских лесах.", description = "Наши потенциальные союзники сомневались в наших способностях. Какая им от нас польза, если мы собственные проблемы решить не можем?\n\nТеперь все изменилось. В нашей силе никто не усомнится. Мы сможем вступить в Орду как равные.\n\nОтнеси это письмо Сильване, правительнице Отрекшихся. Она и так на нашей стороне, но весть о смерти Дар'Хана будет воистину музыкой для ее ушей. Готовься к долгому пути, <имя>. Если все сложится благополучно, Сильвана пошлет тебя в Оргриммар.", progress = "А, гость из Кель'Таласа! Какие вести ты принес?", completion = "Итак, свершилось. Подлый предатель получил по заслугам.\n\nТак этот подвиг совершил ты? Подобные свершения доказывают, что ваша раса не ослабела, Скуфопал.\n\nЯ вижу, что вести Лортемара значительно улучшат его отношения с Траллом.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9622] = {title = "Предупреди свой народ", objective = "Поговорите с экзархом Менелаусом на Лазурной заставе.", description = "Форт спасен. Скоро мой народ вернется в дом предков. Пророчество исполнилось, и для племени Тихвой наступает век процветания.\n\nУвы, твой народ ожидает темный путь. Пророчество говорило не обо всем, многие вопросы остались без ответа.\n\nВозвращайся к своим правителям и расскажи им обо всем, что <видел/видела> здесь.\n\nИ помни, <Избранный/Избранная>: стоит только попросить, и племя Тихвой придет тебе на помощь.", progress = nil, completion = "Видения, говоришь? Интересно... Так пророчество сбылось?\n\nЗначит, они видели энергетическое ядро Экзодара? И О'рос тоже являлся им в видении? Что бы это значило?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9623] = {title = "Время пришло", objective = "Передайте распоряжения экзарха Тораллиусу Пастуху. Он находится у Экзодара, недалеко от входа.", description = "Ты <покорил/покорила> дикие леса нашей новой родины и <проявил/проявила> себя с лучшей стороны. Я думаю, ты <готов/готова> отправиться на остров Кровавой Дымки и вступить в бой с нашими врагами. Такие как ты нужны Длани Аргуса. \n\nПоговори с Тораллиусом Пастухом. Он присматривает за элекками неподалеку от Экзодара. Передай ему мои распоряжения, чтобы он немедленно ознакомил тебя с новыми обязанностями на острове Кровавой Дымки.", progress = "<Тораллиус поправляет повязку на глазу и пристально изучает вас.>\n\nНеужели мы не можем послать на помощь Длани Аргуса достойного героя?", completion = "&lt;Тораллиус вздыхает.&gt;\n\nЛадно, давай распоряжения – почитаем.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9624] = {title = "Любимое блюдо", objective = "Принесите 10 песчаных груш Аонару в лагерь Кессела.", description = "Послушай, <класс>, Я сделал замечательное, грандиозное открытие! В той части острова, которая не была затронута скверной, растет восхитительный фрукт, именуемый песчаной грушей. Их находят у корней деревьев.\n\nЯ готовил с ними грушевые пироги, но выяснилось, что элекки – большие охотники до песчаных груш, так что они частенько подъедали мои запасы. Тогда я решил делать запас побольше, чтобы хватало и мне, и элеккам, – но, увы, все мои запасы пропали, а пирогов-то хочется... Я вот и подумал: может, ты мне поможешь запастись песчаными грушами? А я с тобой непременно поделюсь, когда напеку пирогов, обещаю!", progress = "Найти песчаные груши все труднее – а это значит, что я могу печь все меньше пирогов, а уж элеккам и вовсе почти ничего не останется... Но, может, ты принесешь мне хоть немного груш?", completion = "Нелегко собирать груши, да? У меня на это уходит все больше и больше времени...\n\nНаверное, скоро мне и вовсе придется отказаться от грушевых пирогов. Даже не представляю, как я тогда буду жить. Но пока что, благодаря тебе, Кудзор, мне хватит груш, чтобы испечь один-два пирога...", rewards = "Жилет батракаКожи дрессировщика элекковДоспех наездника на элеккахВы получите:\n\nГрушевый пирог"}
MultiLanguageQuestData['ru'][9625] = {title = "Элекки – это серьезно", objective = "Поговорите с Ворканом Пастухом Элекков на острове Кровавой Дымки.", description = "Он что, спятил? Разве можно доверять <безвестному/безвестной:r> |3-2(<раса>) такое важное дело!\n\nИ запомни, малявка: тебе никогда не войти в ряды Длани Аргуса! Кишка у тебя тонка!\n\nВпрочем, на сей раз придется пойти у него на поводу. Поговори с Ворканом в лагере Кессела на острове Кровавой Дымки. Иди по этой дороге на север, на развилке не сворачивай, иди все время на север.", progress = nil, completion = "Ну, раз ты так далеко добрался, надо приставить тебя к работе, пока у тебя не наберется достаточно познаний.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9626] = {title = "Встреча с вождем", objective = "Отнесите письмо с печатью Леди Сильваны Ветрокрылой вождю в Оргриммар, столицу Дуротара.", description = "Я по-прежнему всей душой люблю свою родину и свой народ. Я билась зубами и когтями за то, чтобы Луносвету предоставили место за столом переговоров наравне с Подгородом и Оргриммаром.\n\nЭто должно заставить всех недовольных умолкнуть. Отнеси это письмо вождю в Оргриммар. Ему, как главе Орды, принадлежит последнее слово относительно того, будет ли удовлетворена просьба син'дорай.\n\nК этому письму приложена моя личная печать, как доказательство подлинности. Ступай на северо-запад города и у башни сядь на дирижабль до Дуротара.", progress = "Ты ко мне, |3-6(эльф крови)? Говори, да побыстрее. Мне не до ваших церемоний.", completion = "*Тралл открывает письмо и начинает читать.*\n\nЭтой леди Сильване упорства не занимать. Значит, теперь она прислала одного из героев Луносвета... Но что это меняет?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9627] = {title = "Верность Орде", objective = "Возвращайтесь в Луносвет и поговорите с Лор'темаром Тероном.", description = "Предательство Альянса навлекло на твой народ множество бед. Тебе удалось отбить нападение дарнассийцев и противостоять шпионам Стальгорна, а теперь на твоем счету еще и победа над могучим командиром Плети. Только глупец сможет усомниться в твоей силе.\n\nВозвращайся к Лортемару и скажи, что я получил его послание.\n\n*Вождь сминает письмо в руке.*\n\nДобро пожаловать в Орду, эльф.", progress = nil, completion = "Ты оказал нам неоценимую услугу. Теперь Тралл считает нашу расу сильной и могущественной и верит, что сможет с нашей помощью воззвать к своим сородичам в Запределье.\n\nЧто ж, он почти прав. Почти.\n\nНастала эпоха великих перемен, Лартренд. Теперь мы стали частью Орды.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9628] = {title = "Цена знания – жизнь", objective = "Неподалеку от того места, где были убиты картографы, обитают наги из клана Зловещей Чешуи. Отберите у них кристалл с результатами наблюдений и доставьте его на Кровавую заставу предвестнику Миколаасу.", description = "Похоже, картографам уже не понадобится никакая помощь. Однако они, скорее всего, успели собрать информацию, которая так нужна предвестнику Миколаасу. Кристалла с результатами наблюдений среди вещей убитых не обнаружилось – следовательно, он попал в руки наг из клана Зловещей Чешуи.\n\nПредвестник Миколаас, конечно, будет весьма огорчен, узнав о гибели своих картографов, но еще больше его огорчит, если все их труды пропадут впустую.", progress = "Тебе удалось выяснить, что помешало исследовательской группе вернуться?", completion = "&lt;Выслушав рассказ о судьбе исследовательской группы и забрав кристалл, предвестник Миколаас не сразу решает продолжить разговор.&gt;\n\nОни были одними из лучших, Ревектор, и знали, на что идут. Я благодарен тебе за помощь. Хотя судьба наших исследователей и оказалась столь печальной, но тебе все же удалось принести кристалл...\n\n&lt;Вестник сжимает кулаки.&gt;\n\nМы уже потеряли слишком многих - а наша миссия еще далека от завершения!..", rewards = "Вы получите:\n\nМантия геодезиста"}
MultiLanguageQuestData['ru'][9629] = {title = "Поймать и отпустить", objective = "Морэ с Кровавой заставы просит вас \"пометить\" 6 разведчиков из племени Черного Ила при помощи маркировщика мурлоков.", description = "Живущие на юго-западном побережье мурлоки из племени Черного Ила – весьма любопытные создания. В некоторых случаях они поступают почти как неразумные звери, в других же проявляют завидную организованность.\n\nУ меня на этот счет есть несколько теорий, но до сего момента я не имела возможности их проверить. Я разработала одно устройство, позволяющее следить за интересующими меня особями мурлоков, не нанося им существенного вреда и не влияя на их естественное поведение. Если ты поможешь мне с метками, можешь быть <уверен/уверена>: я хорошо тебе заплачу.", progress = "Ну как, сработал мой маркировщик? Тебе удалось поставить мурлокам метки? Это помогло бы мне существенно продвинуться в исследованиях...", completion = "Прекрасная работа, Тхаали. Я боялась, что маркировщик не сработает так, как надо, но, похоже, все прошло именно так, как задумывалось.", rewards = "Перчатки ученогоПерчатки исследователяЗащитные полевые перчаткиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9630] = {title = "Дневник Медива", objective = "По поручению верховного мага Альтура на Перевале Мертвого Ветра войдите в Каражан и поговорите с Вравьеном.", description = "Я слышал о тебе, <имя>. Ты заходишь в Каражан и выходишь обратно так свободно, как никто из смертных.\n\nЯ хочу попросить тебя об особой услуге. Аметистовое Око пыталось выяснить местонахождение собственноручных дневников Медива - это было одним из предметов наших поисков.\n\nК сожалению, никто из посланных агентов назад не вернулся. Вравьен был одним из последних, отправленных нами. Разыщи его, если сможешь, и узнай что-нибудь о записях.", progress = nil, completion = "Сколько всего нового и неизведанного! Я готов провести здесь годы! Я уверен, в Даларане поймут меня...", rewards = nil}
MultiLanguageQuestData['ru'][9631] = {title = "Взаимовыручка", objective = "Доставьте фрагмент обугленной кости Калинне Латред в Зону 52 в Пустоверти.", description = "Есть одна небольшая деталь, про которую я совершенно забыл. Остаток сущности Медива, заключенный в этом фрагменте кости, абсолютно лишен жизни - так же, как и Чарозмей.\n\nНо, тем не менее, есть способ все исправить. И я знаю человека, который может помочь нам.\n\nСтупай в Область 52 в Пустоверти и покажи эту кость Калинне Латред. Она сообразит, что можно сделать.", progress = "Вас прислал Альтур. Звезды предупредили меня о вашем прибытии.", completion = "Альтур хочет, чтобы я подняла из мертвых целого дракона? Мда, такое дело трудно даже представить.\n\nНо, думаю, я сумею вам помочь, Мечищит. Если вы, в свою очередь, поможете мне.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9632] = {title = "Новые союзники", objective = "Доставьте рекомендательное письмо охотнице Келле Тетиве Ночи на остров Лазурной Дымки.", description = "Думаю, тебе уже известно, <класс>, сколько усилий приложил предвестник Миколаас, чтобы обеспечить надежную защиту Кровавой заставе. Но несмотря на это, нам по-прежнему не хватает ресурсов, зато врагов явный избыток.\n\nВрагам хорошо известна эта наша слабость, однако они не принимают в расчет то, что мы можем заручиться поддержкой Альянса. Я подготовил рекомендательное письмо: его нужно доставить в Аубердин, ближайший к нам оплот Альянса. Надеюсь, они прислушаются к нашему предложению, и вместе мы разгромим врагов. Отнеси это письмо охотнице Келле Тетиве Ночи на пристань к западу от Экзодара.", progress = "Приветствую тебя, |3-6(Друид). У тебя ко мне дело?", completion = "Конечно, я помогу тебе попасть в Аубердин. По счастью, тут по морю совсем недалеко.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9633] = {title = "Дорога к Аубердину", objective = "Сядьте на корабль, идущий в Аубердин. Пристань находится неподалеку от дома охотницы Келлы Тетивы Ночи. В Аубердине отдайте рекомендательное письмо Тандрису Ветропряду.", description = "Подожди на пристани. Скоро из порта Аубердин, что на Темном Берегу, прибудет корабль. Когда пассажиры сойдут на берег, ты сможешь подняться на борт.\n\nПутешествие будет недолгим - конечно, если ты не страдаешь морской болезнью. Сойдешь на берег в Аубердине, а там уже доставишь письмо по назначению.\n\nДумаю, лучше всего обратиться к моему старому другу и весьма уважаемому жителю Аубердина; его зовут Тандрис Ветропряд.", progress = "Добро пожаловать в Аубердин, добрый друг. Что привело тебя на Темный Берег?", completion = "*Тандрис берет рекомендательное письмо, пробегает его глазами и кивает.*\n\nВ давние времена мой народ жил на островах, которые дренеи называют островами Лазурной и Кровавой Дымки. Анахорет Пайтеус и его братия, по всей видимости, столкнулись с древними врагами ночных эльфов...\n\nУверен, Аубердин окажет своим новым союзникам всю возможную поддержку. Я пошлю весточку Пайтеусу, как только поговорю с жителями города и часовыми.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9634] = {title = "Чужие-хищники", objective = "Убейте 10 детенышей опустошителя с острова Кровавой Дымки и вернитесь к Воркану Пастуху Элекков. Воркана можно найти на острове Кровавой Дымки в лагере Кессела.", description = "В наших странствиях мы хорошо усвоили один урок: нужно быть крайне осторожным, перенося животных и растения из одного мира в другой. На \"Экзодаре\" при крушении были образчики многих видов нездешних существ, в том числе насекомовидный хищник, который зовется опустошителем.\n\nНекоторые экземпляры погибли; другие не только выжили, но и приспособились к новым условиям. Если мы не озаботимся этим вопросом, они могут нарушить экологический баланс на островах.\n\nТы найдешь опустошителей неподалеку от лагеря Кессела, к западу отсюда. Насколько мне известно, они поселились неподалеку от берега.", progress = nil, completion = "Прекрасная работа, Ревектор! Нам придется еще некоторое время следить за местной популяцией опустошителей, но начало, безусловно, положено.", rewards = "Стрекало старого элеккаДвухпудовый кузнечный молотКлинок дрессировщика элекковДобавочный меч-бастардВы получите:\n\n"}
MultiLanguageQuestData['ru'][9635] = {title = "Удаленный конденсатор выхлопов!", objective = "Принесите 15 деталей парового насоса Маку Дайверу в Забра'джин в Зангартопи.", description = "Болотный газ – потрясающая вещь! Он может быть весьма ценным! Но сначала его нужно собрать – а вот для этого-то нам и потребуется удаленный конденсатор выхлопов!\n\nЯ могу тебе дать чертежи такого конденсатора, но сначала хочу получить что-нибудь взамен. Например, мне нужны кое-какие запчасти. Я знаю, что еще не так давно куча полезных деталей валялась вокруг сломанного парового насоса в Мертвой трясине, к северо-востоку отсюда.\n\nЯ слышал, что это иссохшие великаны растащили детали по всему дну пересохшего озера.", progress = "Ну что, где запчасти? Мой водолазный костюм нуждается в ремонте...", completion = "Отлично! Теперь, если добыть скользящую петлю, пергаментное крепление, хлебательную трубку и липкую ленту, получится то, что надо!\n\nНу ладно, ладно! Ты заслужил награду, я же и не спорю! Счастливо, Расул.", rewards = "Вы получите:\n\nСхема: удаленный конденсатор выхлопов"}
MultiLanguageQuestData['ru'][9636] = {title = "Удаленный конденсатор выхлопов!", objective = "Принесите 15 деталей парового насоса К. Ли Мелюзге в Телредор в Зангартопи.", description = "Доводилось ли вам видеть болотный газ? Блестящая штука, не правда ли?\n\nНо для того, чтобы извлечь из него все полезное, нужен удаленный конденсатор выхлопов! Я могу вам дать чертежи такого конденсатора, но мне нужны запчасти для ремонта техники.\n\nЯ знаю, что еще не так давно куча деталей валялась вокруг парового насоса в Мертвой трясине, к северо-востоку отсюда. Думаю, это иссохшие великаны разрушили насос.\n\nНу что, поможем друг другу?", progress = "Ну что, где запчасти? Мне нужно починить кольцедав, пока анахорет Ахуурн не настучал мне по голове!", completion = "Блестяще! Знаете, лишние запчасти инженеру никогда не лишние! А может быть, я продам часть из них, и куплю себе клубничного мороженого Тигуле и Форора? Обожаю клубнику! Как вы думаете, где его тут продают поблизости?\n\nАх, ну да, ну да! Думаю, вы это заслужили, Вродехант. Счастливо!", rewards = "Вы получите:\n\nСхема: удаленный конденсатор выхлопов"}
MultiLanguageQuestData['ru'][9637] = {title = "Требование Калинны", objective = "Калинна Латред требует отыскать и принести ей фолиант сумерек и книгу забытых имен. Первой владеет главный чернокнижник Пустоклят, его можно найти в Разрушенных залах цитадели Адского Пламени. Вторая принадлежит заклинателю тьмы Ситу, который находится в Сетеккских залах в Аукиндоне.\n\nЭто задание должно быть выполнено на героическом уровне сложности.", description = "Мне пришлось покинуть Кирин-Тор в поисках знаний, которые орден считал запретными. Есть некая ирония в том, что теперь орден просит моей помощи именно по этому вопросу.\n\nМожет быть, я помогу тебе. Но сначала хочу, чтобы ты кое-что для меня <сделал/сделала>. Мне нужны две книги, я уже давно пытаюсь их раздобыть \n\nПервая называется Фолиант Сумерек. Им владеет орочий чернокнижник Пустоклят. Вторая, Книга Забытых Имен, находится у араккоа, известного как Темнопряд Сит.", progress = "Ну что, ты принес мои книги?", completion = "Блестяще, Акул. Я долго пыталась завладеть этими книгами. Большая удача, что мы смогли помочь друг другу.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9638] = {title = "В хороших руках", objective = "Поговорите с Градавом в Библиотеке стража в Каражане.", description = "Мне надо было искать эти записи? Быть того не может. Не помню ничего подобного.\n\nНу конечно! Ты имеешь в виду Градава. Это он искал какую-то книгу, когда я тут торчал. Мне кажется, вряд ли он до сих пор сумел ее отыскать. А почему бы тебе не поговорить с ним лично?\n\nЯ б тебе помог, но... эти книги такие... захватывающие!", progress = nil, completion = "Не видишь, что ли, что я очень занят? Чего тебе нужно?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9639] = {title = "Камсис", objective = "Поговорите с Камсис в Библиотеке Стража в Каражане.", description = "Дневник, какой дневник? Конечно, ты имеешь в виду Камсис.\n\nСтупай и спроси ее об этом. Если я сейчас оторвусь от работы, то все пойдет насмарку!", progress = nil, completion = "Эти записи, о которых ты говоришь... Меня послали найти их, да?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9640] = {title = "Тень Арана", objective = "Добудьте дневник Медива и верните его Камсис в Библиотеку Стража в Каражане.", description = "Дай мне подумать секунду. Аметистовое Око... Журнал Медива... Да, теперь я что-то припоминаю.\n\nМне кажется, у меня был этот журнал, пока я не начала читать эти манускрипты...\n\nАран... Да, Аран тоже спрашивал меня об этой книге. Правда, какое милое совпадение? Так и есть, должно быть, я отдала книгу ему. В конце концов, он же отец Медива.", progress = "Не ищещь ли ты, часом, что-нибудь вроде журнала?", completion = "Ну как, нашел, что искал? Ты ведь искал что-то, правда?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9641] = {title = "Осколки облученного кристалла", objective = "Принесите 10 осколков облученного кристалла воздаятелю Боросу на Кровавую заставу.", description = "В результате крушения \"Экзодара\" фрагменты оскверненных кристаллов оказались разбросанными по всему острову Кровавой Дымки; их скверна отравила воды и землю.\n\nМы обнаруживали осколки кристаллов даже в плоти животных, добытых на охоте. Однако я нашел способ очищать кристаллы от скверны и использовать их по назначению. Если ты принесешь мне достаточное количество осколков, взамен я отдам тебе один из целых кристаллов. Думаю, тебе нужно знать, что осколки обнаруживались в телах медведей, опустошителей, бражников и древней, обитающих в оскверненной части острова.", progress = "Ну как, удалось тебе собрать осколки кристаллов? Я говорил, их можно найти в телах животных и на стволах деревьев...", completion = "Неплохо. Теперь у меня есть исходные материалы для воссоздания кристаллов.\n\nТы можешь выбрать один из трех видов кристаллов, которые я могу создать. Каждый вид хорош для охоты на определенную добычу...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКристалл жизненной силыКристалл прозренияКристалл лютости\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9642] = {title = "И снова облученные кристаллы", objective = "Если у тебя есть еще облученные осколки, я с радостью обменяю их на свои кристаллы.", description = nil, progress = "Если у тебя есть еще облученные осколки, я с радостью обменяю их на свои кристаллы.", completion = "Прекрасно, прекрасно! А вот и мои кристаллы, Рудель. Надеюсь, ты найдешь им применение.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКристалл жизненной силыКристалл прозренияКристалл лютости"}
MultiLanguageQuestData['ru'][9643] = {title = "Удушающая лоза", objective = "Принесите зверолову Лисеону 6 побегов колючей удушающей лозы.", description = "У хорошего лесника все идет в дело, <класс>. Даже самые странные существа зачастую обладают весьма полезными для нас особенностями.\n\nСолнечные Ястребы постоянно нападают на Кровавую заставу; тут уж все средства защиты хороши, не исключая и ловушки. Мне тут на ум пришла одна ловушка, для которой прекрасно подойдет колючая лоза. Острые шипы и смертельный яд – прекрасная комбинация, которая надолго отобъет охоту у любого соваться на заставу. Принеси мне несколько побегов мутировавшей удушающей лозы, и я немедленно примусь за работу.", progress = "Что, удалось тебе добыть побеги?", completion = "Да, похоже, лозы достаточно прочные и вполне подойдут для моих целей. Благодарю за помощь, Ревектор, ты сделал большой вклад в наше дело.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9644] = {title = "Ночная Погибель", objective = "Ступайте на террасу Мастера в Каражане и прикоснитесь к урне Калинны, чтобы призвать Ночную Погибель. Извлеките из тела Ночной Погибели слабую чародейскую сущность и доставьте ее верховному магу Альтуру.", description = "Ты <сделал/сделала> то, что <обещал/обещала>. Теперь я соединю твою сущность с сущностью мертвого синего дракона.\n\nНа Террасе Мастера находится урна, дотронувшись до которой ты высвободишь энергию, позволяющую оживить обугленные останки Арканагоса. Тебе придется немедленно сразиться с ним, а потом извлечь сущность из этой твари и отнести Альтурусу.\n\nЗвезды говорят, что если ты потерпишь поражение в бою с этим драконом, то позволишь страшной угрозе обрушиться на мир.\n\nИмя этой угрозе – Ночная Погибель!", progress = "Какие вести с фронта, Выручалкин?", completion = "Невероятно. Вам удалось добыть не только записи Медива, но даже часть его собственной сущности.\n\nХотя эта сущность невероятно слаба, она все равно сумеет дать нам жизненно важные сведения о Медиве. Мы не забудем того, что вы для нас сделали.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВневременной аметистНеустанный успокаивающий аметистЦарственный аметист\n\nВы также получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9645] = {title = "Терраса Мастера", objective = "Поднимитесь на террасу Мастера в Каражане и прочитайте дневник Медива.", description = "Дневник? Какой дневник?\n\nА, точно! Тот самый дневник! Меня послало за ним братство Аметистового Ока. Кажется, теперь что-то припоминаю.\n\n*Камсис указывает на страницу из дневниковых записей.*\n\nАльтуру нужна вот эта страница. Знаешь, если другие ведут записи, чтобы сохранить память о событиях, то Медив буквально впечатал в них собственную память.\n\n<Сам/Сама> посмотри. Поднимись на террасу Мастера, прочти эту страницу - и поймешь, что я имею в виду. Можешь рассказать об этом Альтуру, если ты все равно к нему возвращаешься. Боюсь, мне придется тут задержаться еще на некоторое время.", progress = "Ты вернулся! Какие новости ты принес мне?", completion = "Просто позор, что наши люди поддались магии Каражана. Ну, по крайней мере, тебе удалось добыть то, за чем их послали.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9646] = {title = "РАЗЫСКИВАЕТСЯ: Коготь Смерти", objective = "Принесите лапу Когтя Смерти предвестнику Миколаасу на Кровавую заставу.", description = "Указ предвестника Миколааса: \"Награда в 18 серебряных монет будет выплачена тому смельчаку, кто покончит с медведем по кличке Коготь Смерти и предоставит доказательства его смерти.\n\nЭтот медведь признан крайне опасным; имеются подтвержденные сведения о том, что именно он уничтожил отряд, исследовавший берег острова к северо-западу от Кровавой заставы. Путешественникам временно не рекомендуется посещать эту территорию\".", progress = "Я могу тебе чем-нибудь помочь, |3-6(Маг)?", completion = "Прекрасно. Я вижу, бой был не из легких... Полагаю, ты вполне заслуживаешь награды, Ревектор.", rewards = "Кулачный щит миротворцаВам дадут возможность выбрать одну из следующих наград:\n\nРезная хрустальная сфера\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9647] = {title = "Ловля бражников", objective = "Зверолов Лисеон просит убить 10 царственных синих бражников.", description = "Когда мы впервые столкнулись с бражниками, мы не заметили у них никаких отклонений. Однако скверна расползалась по острову, и вскоре у всех живых существ начали проявляться признаки заражения.\n\nДошло до того, что бражники, прежде не доставлявшие нам особого беспокойства, начали разрушать все, с чем соприкасаются. Как будто мало вреда было от кристаллов, усеявших все вокруг после крушения \"Экзодара\"!.. У нас просто не оставалось иного выбора: приходится отлавливать их, чтобы хоть немного исправить ситуацию в землях к северу от Кровавой заставы.", progress = nil, completion = "Со временем мы найдем способ вернуть этот вид к его природному состоянию, но пока что мы можем только периодически сокращать их количество. Другого выхода у нас нет. Благодарю за помощь, Рудель.", rewards = "Опояска из тканых водорослейИзысканно обработанный поясСегментированный ременьВы получите:\n\n"}
MultiLanguageQuestData['ru'][9648] = {title = "Грибная похлебочка Матпарма", objective = "Матпарм просит принести ему на Кровавую заставу по одному экземпляру водянистого смрадорога, кровавого гриба, губительной полиспоры и конусовидной поганки.", description = "А известно ли тебе, что грибная охота намного опаснее, чем поглощение грибов? Грибники подвергают себя множеству неведомых опасностей – ведь в лесу видимо-невидимо разных тварей!\n\nС другой стороны, что такое жизнь без риска? К тому же мне нужны грибы. Для коллекции. В здешних неисследованных землях можно найти четыре весьма любопытных типа грибов: водянистый смрадорог, кровавый гриб, губительную полиспору и скверноконус. В каждом регионе острова Кровавой Дымки растет только один из видов этих грибов. Принеси их мне.", progress = "Помни: в каждой части острова Кровавой Дымки растет только один из видов нужных мне грибов.", completion = "Ну, я же тебя предупреждал, верно? Впрочем, надеюсь, оплата послужит достаточной компенсацией за те небольшие неудобства, которые тебе довелось испытать. Когда восстановишь силы, возвращайся: возможно, я найду для тебя новое задание... Грибы – такая вещь, которой не бывает много!", rewards = "Грибные манжеты МатпармаГрибные поручи МатпармаГрибные наручи МатпармаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9649] = {title = "Слеза Изеры", objective = "Матпарм просит принести ему на Кровавую заставу 2 экземпляра Слезы Изеры.", description = "Рад снова тебя видеть, <имя>! Тебе просто блестяще удалось выполнить мое предыдущее задание. Так вот, я тут подумал: может, тебя не затруднит выполнить еще одну небольшую просьбу?\n\nК северо-востоку отсюда находится остров Драконьей Скорби, где можно отыскать редчайшую разновидность грибов, именуемую \"Слезой Изеры\" - это в честь зеленых дракончиков, обитающих на острове. Нет, сами грибы не зеленые. А какая тут связь?.. Хм, позволь мне не вдаваться в подробности. Мне нужен только малюсенький образец этих грибов... Да, совсем забыл: обитатели острова не слишком гостеприимны, так что будь поосторожнее...", progress = "Что, уже вернулся?", completion = "Надеюсь, это задание не было слишком обременительным, Эксордим? О да, любой |3-6(дреней) может позавидовать твоим знаниям и умению серьезно подходить к делу. Позволь заверить тебя в моей искренней благодарности - а заодно предложить небольшое вознаграждение...", rewards = "Грибной мундир МатпармаГрибной жилет МатпармаГрибной хауберк МатпармаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9663] = {title = "Дуга Кессела", objective = "Сообщите верховному вождю племени Тихвой, экзарху Менелаусу и адмиралу Одиссию о готовящемся вторжении эльфов крови, а затем возвратитесь к Кесселу. У вас есть 15 минут. Элекка следует держать подальше от воды.", description = "Ты как раз вовремя, <имя>. За последнюю неделю активность эльфов крови подозрительно возросла. Наши разведчики докладывают, что та часть эльфов, которая называет себя Солнечными Ястребами, в ближайшее время собирается напасть на остров Лазурной Дымки. Я хочу, чтобы ты <передал/передала> это предупреждение нашим союзникам и сподвижникам...\n\nТебе нужно повидать верховного вождя племени Тихвой в логове клана Тихвой, экзарха Менелауса на Лазурной заставе и адмирала Одиссия в Лагере Одиссия.\n\nВремя дорого, потому ты отправишься в путь на моем элекке. И помни: не загоняй его в воду.", progress = nil, completion = "Прекрасно, Пластырь! Конечно, для тебя это была суровая проверка, однако ты блестяще выдержал ее! Но помни: чтобы стать воином Длани, тебе придется пройти не одно испытание...", rewards = "Следующее заклинание будет наложено на вас:\n\nОтпустить элекка Кессела\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][9664] = {title = "Новые форпосты", objective = "Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и Башню Чумного леса в Восточных Чумных землях и вернитесь к посланнику Белобороду в Часовню Последней Надежды.", description = "Добро пожаловать в Чумные земли,<имя>. Как тебе известно, Отрекшиеся и их приспешники удерживают земли к западу отсюда, несмотря на все наши усилия. Командующие Альянса приняли решение укрепить наши прифронтовые позиции, завоевав новые укрепления.\n\nБашни, давно заброшенные и позабытые еще в дни Лордерона, необходимо захватить и восстановить. Это очень опасные земли, и нам потребуется твоя помощь.", progress = nil, completion = "Превосходно, Ренгольд. Теперь необходимо удерживать эти башни до прибытия подкрепления – для этого нам потребуется твоя помощь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9665] = {title = "Укрепим оборону", objective = "Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и Башню Чумного леса в Восточных Чумных землях и возвращайтесь к посланнику Гормоку в Часовню Последней Надежды.", description = "Разведчики Отрекшихся раскрыли планы Альянса создать новые форпосты в Восточных Чумных землях на базе заброшенных башен.\n\nНельзя позволить им закрепиться на наших восточных границах, поэтому необходимо помешать планам Альянса. Мы должны выманить их войска из тех башен, которые они уже успели захватить, и занять те, которые еще не были захвачены.", progress = nil, completion = "Это хорошие вести, Шпилэ. Мы будем биться в Чумных землях до конца, пока окончательно не разобьем силы Альянса.\n\nДо этого дня надеюсь на твою помощь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9666] = {title = "Демонстрация силы", objective = "Проникните в логово клана Зловещей Чешуи, убейте лорда Ксиза и пронзите его тело древком дренейского знамени.", description = "Тебе уже доводилось видеть змеелюдей? Тех самых, которые называют себя нагами?\n\n<Кессел с отвращением сплевывает.>\n\nТри ночи прошло с тех пор, как они осмелились напасть на этот лагерь. Примитивные твари! Какова наглость, а?\n\nПослушай, <имя>, я хочу, чтобы ты кое-что <сделал/сделала> для меня. На северо-востоке отсюда находится логово клана Зловещей Чешуи, где обитает лорд Ксиз. Найди его, убей и пронзи его тело древком этого знамени!\n\nПусть скользкие твари трепещут при виде нашего штандарта!", progress = nil, completion = "Мне очень жаль, что тебе пришлось сделать это, Тэррат. Насилие - не тот путь, который предпочитают дренеи; однако иногда другого пути попросту нет.\n\nЭто - одна из тех истин, понимание которых ко многим приходит слишком поздно. Так было и с нашим народом, когда орки уничтожали нас...\n\nСтав одним из братства Длани Аргуса, ты родишься вновь. Но помни, что рождение - это всегда боль...", rewards = "Поясной платок КесселаПропотевший поводок элекка КесселаПрочный пояс Кессела для верховой ездыВы получите:\n\n"}
MultiLanguageQuestData['ru'][9667] = {title = "Спасение принцессы Тихвой", objective = "Выпустите принцессу Тихвою из клетки, а затем найдите на Кровавой заставе посла племени Тихвой Олорга и поговорите с ним.\n\nЧтобы раздобыть ключ от клетки, убейте верховного вождя племени Косолапов.", description = "Умоляю тебя, <имя>, помоги мне! Меня взяли в плен фурболги из племени Косолапов. Они хотят принести меня в жертву их нечистым богам!\n\nКлюч от клетки – у вождя племени. Но он так просто здесь не объявится. Чтобы вынудить вождя сделать это, тебе придется убить обитающих здесь фурболгов – уничтожить два лагеря племени Косолапов к западу отсюда. Не сомневайся: вождь непременно придет, чтобы отомстить за смерть соплеменников – а когда это произойдет, ты убьешь его и заберешь ключ.\n\nЕсли ты спасешь меня, мой отец не поскупится на награду!", progress = nil, completion = "И вот еще одно доказательство тому, что пророчества говорили именно о тебе. Прими мою вечную благодарность, Тэррат, а в придачу – одну из реликвий племени Тихвой...", rewards = "Шокер племени ТихвойКолотунВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][9668] = {title = "Доклад экзарху Адметиусу", objective = "Поговорите с экзархом Адметиусом на Кровавой заставе.", description = "Солдат Длани Аргуса должен обладать многими качествами: быть покорным, отважным, разумным - но прежде всего благородным. Надеюсь, у тебя еще будет возможность проявить хотя бы часть этих качеств, <класс>.\n\nЕсли ты все еще хочешь присоединиться к братству Длани, отправляйся на Кровавую заставу к экзарху Адметиусу. Он и его подчиненные обучат тебя и превратят в настоящего солдата дренеев. Насколько это возможно.\n\nИ вот еще что запомни, <имя>: не всегда благородные существа ведут себя честно и благородно. Иногда они просто не могут позволить себе этого.\n\nНу, довольно болтовни, отправляйся на Кровавую заставу - это прямо по дороге на север.", progress = nil, completion = "Я чувствовал, что ты сумеешь пройти этот путь, |3-6(Друид). Что ж, если ты хочешь и дальше следовать своему предназначению, я готов учить тебя...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9669] = {title = "Пропавшая экспедиция", objective = "Убейте 8 пауков-ткачих, 8 паучих-кровопийц и матриарха пауков – Зарак. По завершении задания вернитесь на Кровавую заставу к Акелусу.", description = "Около недели назад мы проводили разведку западных пустошей острова Кровавой Дымки, когда на нас напали кровожадные пауки. Насколько я могу судить, их размеры и чрезвычайная агрессивность обусловлены действием кристаллов.\n\nМне удалось спастись, но моим спутникам повезло меньше. Нельзя допустить, чтобы и других постигла та же печальная участь. Отправляйся на запад к перевалу Янтарной Паутины: нужно уничтожить пауков и их матриарха Зарак.", progress = nil, completion = "Невероятно! А удалось тебе хоть кого-то найти, или все погибли?\n\n*Акелус понижает голос до шепота.*\n\nЯ буду с тобой откровенен, Эксордим: это задание больше никто не хотел выполнять. Отважный ты |3-6(Паладин)...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9670] = {title = "Они живы! Может быть...", objective = "Освободите 5 ученых экспедиции по просьбе ученого Корнелиуса.", description = "Ты представить себе не можешь, <имя>, что мне пришлось пережить! Ужас! Кошмарный сон!.. На нас набросились пауки, будь они прокляты, да к тому же их прародительница, чтоб у нее все лапы поотсыхали, как с неба свалилась и тут же запеленала нас всех в коконы!\n\nНо это было еще полбеды, эта членистоногая зараза пристроилась рядом с нами и начала откладывать яйца! Представляешь? Она решила, что мы – отличный корм для ее молодняка. КОРМ! Вообрази только!\n\nМне-то кое-как удалось выбраться, а мои товарищи так и валяются там, спеленутые, как младенцы. В одиночку мне их не спасти, я даже близко не могу подойти к тому проклятому месту. Ты ведь поможешь мне, верно?\n\nРаспутай коконы! Может, хоть кто-то еще из наших остался в живых!", progress = "Ну, как успехи?", completion = "Тебе удалось спасти больше половины экспедиции! Клянусь, я позабочусь о том, чтобы рассказ о твоем деянии дошел до Кровавой заставы и до самого экзарха! Благодарю тебя, Рудель!", rewards = "Вы получите:\n\nЯдовитый шелковый убор"}
MultiLanguageQuestData['ru'][9671] = {title = "Срочная доставка", objective = "Ты - Ревектор? Что ж, вовремя! Я уже и не надеялся тебя найти.\n\nЗагляни в почтовый ящик - там тебя ждет срочное письмо. Мне его передал один человек, адмирал с острова Лазурной Дымки. Как же его звали... Одиссей? Одессит?.. Нет, не помню: из головы вылетело. Но он сказал, что ты его непременно вспомнишь.\n\n<Гермесий пожимает плечами.>", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][9672] = {title = "Наследие Проклятой Крови", objective = "Адмирал Одиссий просит разыскать капитана Эдварда Хейнса и поговорить с ним.", description = "Дорогой друг!\n\nПеро дрожит в моих руках, когда я пишу эти строки. Надеюсь, ты получишь письмо вовремя.\n\nПрошлой ночью в моем шатре появился Эдвард Хейнс, капитан \"Утерянной надежды\". Да-да, тот самый Эдвард Хейнс, который умер от цинги двадцать лет назад.\n\nПризрак поведал мне историю, от которой кровь застыла у меня в жилах. Тебе непременно нужно услышать эту историю – и выполнить одно задание. Прошу тебя, разыщи Эдварда на острове Драконьей Скорби; ты сможешь найти его к северо-востоку от своего лагеря.\n\nС наилучшими пожеланиями,\n\nАдмирал Одиссий.", progress = nil, completion = "Скажи, ты, сухопутный червяк, тебе приходилось слышать о проклятии? Ну да, конечно, разумеется, ничего! А между тем именно проклятье и потопило все эти корабли; вернее сказать, это сделал риф Проклятой Крови – мерзейшее место в мире. Я и сам здесь торчу уже двадцать лет, если ты этого не знаешь.\n\nЯкорь мне в глотку!.. Вот тут-то я и помер, стал падалью, которой даже драконы брезгуют... Впрочем, это совсем другая история. Я сейчас не о том. Мы должны помочь тем злосчастным душам, которые попали в ловушку на этом рифе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9673] = {title = "Дрессировка", objective = "Поговорите с Хальтенисом в Луносвете.", description = "Тебе удалось приручить питомца, но теперь нужно его выдрессировать. Обратись к Хальтенису, лучшему дрессировщику Луносвета.\n\nХальтенис всегда рад моим ученикам. Прояви уважение - и он обязательно поможет тебе. Удачи!", progress = nil, completion = "Что ж, похоже, ты уже не новичок.\n\n*Хальтенис пристально смотрит на вас.*\n\nЯ помогу твоему питомцу освоить новое умение - потрошение врагов. Оно пригодится тебе для служения нашему великому городу.", rewards = "Вы также получите:\n\nЛук странника"}
MultiLanguageQuestData['ru'][9674] = {title = "Проклятые наги", objective = "Капитан Эдвард Хейнс с острова Драконьей Скорби просит убить 10 наг с острова Проклятой Крови.", description = "Говорят, когда мир раскололся, эти земли возопили... Именно здесь канули в бездну забвения тысячи ночных эльфов, а вместо них в мир вступили чудовищные твари, порождение ночных кошмаров – наги.\n\nНаги повиновались лишь своей королеве Азшаре; они уничтожали любого, кто решался плыть по их морям. Так было тысячи лет... но теперь, возможно, все переменится.\n\nПервым делом нужно будет истребить проклятых наг на этом рифе.", progress = nil, completion = "Отличное начало – но только начало...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9675] = {title = "Дрессировка", objective = "Поговорите с Ганааром в Торговом ряду Экзодара.", description = "Да, и еще одно! Тебе не помешает поговорить с Ганааром из Экзодара. Он научит тебя заботиться о твоем питомце и дрессировать его.\n\nГанаара можно отыскать в юго-западном углу Торгового ряда.", progress = nil, completion = "Главное - понять, что умение кормить и спасать своего питомца от смерти - не пустяк, как полагает твой учитель. Ведь дрессировка позволяет питомцу обучиться тому, что ему нипочем не постичь без тебя.\n\nФурболги меня многому научили, поэтому слушай внимательно, и я передам тебе свои знания.", rewards = "Вы также получите:\n\nСеребряный арбалет"}
MultiLanguageQuestData['ru'][9676] = {title = "Наставник паладинов", objective = "Поговорите с наставником паладинов Джестенисом Солнцесветом в Солнечном Шпиле на Острове Солнечного Скитальца.", description = "По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных паладинов на Острове Солнечного Скитальца тренирует Джестенис Солнцесвет. Поговори с ним, может быть, он сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nДжестенис, как и все наставники Острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.", progress = nil, completion = "Вижу, тебя распирает от гордости. Ты уже видишь себя среди Рыцарей крови.\n\nКогда-нибудь ты заслужишь себе место в наших рядах, но сначала тебе придется научиться управлять силой Света, отточить свое боевое мастерство и доказать, что ты достоин стать рыцарем.\n\nГотовься сносить насмешки, боязнь и неприязнь со стороны тех, кого поклянешься защищать. Ибо они не способны понять цену великой силы, что хранит их. Не теряй веры и держи меч наготове, Сиданс.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9677] = {title = "Призыв предводителя рыцарей Доблестной Крови", objective = "Поговорите с предводителем рыцарей Доблестной Кровью на площади Странников в Луносвете.", description = "<имя>, ты <преуспел/преуспела> в начале своего обучения и <сумел/сумела> отличиться среди тех, кто жаждет стать рыцарями крови. Ты <готов/готова> к следующему этапу обучения. Сам предводитель рыцарей Доблестная Кровь желает поговорить с тобой.\n\nНе сомневаюсь, предводитель устроит тебе испытание, чтобы проверить твои способности и уровень обучения. Ты найдешь его в штабе рыцарей крови на площади Странников в Луносвете. Желаю удачи, <имя>!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9678] = {title = "Первое испытание", objective = "Отправляйтесь на остров, описанный предводителем рыцарей Доблестной Кровью, найдите пещеру и разожгите огонь в жаровне. Пройдя первое испытание, возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.", description = "Ты прекрасно <освоил/освоила> искусство сражения, но этого недостаточно.\n\nСосредоточенность и несгибаемая сила воли – вот что отличает настоящего рыцаря крови от обычного головореза.\n\nХочешь закалить характер? Тогда отправляйся на Остров Напастей, к северо-востоку от Призрачных земель. Там, в одной из пещер, найди жаровню и встань перед ней на колени. Затем разожги в жаровне пламя и не своди глаз с того, что представится твоему взору.", progress = nil, completion = "Я знаю, о чем ты думаешь.\n\nДа, я действительно послал Безмолвного Клинка, чтобы убить тебя.\n\nНичего личного, Сабыч. Я просто хотел преподать тебе урок. Теперь ты знаешь, что настоящий рыцарь крови должен всегда быть начеку. Оправдывает ли это смерть Безмолвного Клинка, спросишь ты?\n\nБезусловно, оправдывает. Считай это очередной тренировкой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9680] = {title = "Тайны прошлого", objective = "Верховный маг Альтур желает, чтобы вы нашли в горах к югу от Каражана на Перевале Мертвого Ветра фрагмент обугленной кости и доставили ему.", description = "Камсис была права! Это очень, очень ценные сведения. \n\nЕсли Медив во время сражения с драконом объединил свою душу с магическими силами, то вполне возможно, что мы сумеем извлечь из останков дракона хотя бы слабый отпечаток сущности Медива. Под слоем пыли на Перевале Мертвого Ветра нас ожидают великие открытия.\n\nСтупай в горы к югу от Каражана, разыщи фрагмент драконьей кости и принеси его мне.", progress = "Ну как, удалось отыскать нужный фрагмент кости, Мечищит?", completion = "Великолепно! Этот маленький костяной обломок буквально лучится энергией, я чувствую это!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9681] = {title = "Источник силы", objective = "Поговорите с магистром Асталором Кровавой Клятвой в тайной зале, расположенной под штабом рыцарей крови.", description = "Жестоко? Ну что ты, <имя>. Безмолвный Клинок прекрасно знал, на что идет, и выполнил свой долг с честью и достоинством. Его самоотверженность должна послужить примером для всех нас.\n\nНо это далеко не последний подвиг Безмолвного Клинка, <имя>. Ему предстоят еще многие свершения. Да-да, ты не <ослышался/ослышалась> - нам нужно воскресить его. И займешься этим именно ты!\n\nДоселе ты <ограничивался/ограничивалась> простыми заклинаниями, но теперь, когда нас предал Кель'тас, когда мы утеряли источник энергии, тебе придется научиться нести Свет по-новому. Отправляйся к магистру Асталору Кровавой Клятве.", progress = nil, completion = "Добро пожаловать, юный |3-6(Паладин)!\n\nУзри источник нашей силы!\n\n*Магистр указывает на огромное существо в середине залы.*\n\nЭто прекрасное существо было преподнесено нам в дар самим принцем Кель'тасом. Оно противится нам, но мы нашли способ использовать его силу и без его согласия.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9682] = {title = "Отчаявшиеся", objective = "Капитан Эдвард Хейнс с острова Драконьей Скорби просит освободить 4 души с острова Проклятой Крови.", description = "На краю рифа, глубже, чем обитают проклятые наги, находится обитель отчаявшихся – там обитают проклятые путешественники, неупокоенные призраки тех, кого унесло проклятие...\n\nМне горько, что приходится просить тебя об этом, но... Их должно уничтожить.\n\nОтлученные души должны обрести покой. Вернись ко мне, когда исполнишь все, как нужно, – я дам тебе еще одно, последнее задание.", progress = "Не стоит оплакивать их гибель, Эксордим, по сути, они уже давно мертвы...", completion = "Ты оказал отчаявшимся неоценимую услугу, Эксордим. Осталось сделать только одно: уничтожить предводителя наг с острова Проклятой Крови.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9683] = {title = "Избавление от Проклятой Крови", objective = "Капитан Эдвард Хейнс с острова Драконьей Скорби просит уничтожить статую королевы Азшары и убить Атофа Проклятую Кровь.", description = "К югу отсюда находится остров Проклятой Крови. В центре острова расположено святилище, посвященное возлюбленной королеве наг – Азшаре. Разрушь статую! Уничтожь это чучело! Не сомневаюсь: это разъярит предводителя наг, Атофа.\n\nУбей Атофа, а потом возвращайся ко мне.", progress = "Нужно выманить Атофа из его логова!", completion = "Подумать только! Тебе это удалось!.. Благодарение сотен и сотен душ пребудет с тобой.\n\nПозволь кое-что предложить тебе...", rewards = "Вы получите:\n\nКолесо утраченной надежды"}
MultiLanguageQuestData['ru'][9684] = {title = "Получение силы Света", objective = "Используйте мерцающий сосуд на эльфах крови-магистрах, чтобы наполнить его магической силой, и возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.", description = "Прими этот зачарованный сосуд, <имя>, и наполни его магической силой, окружающей магистров, до краев. Когда-то эти магистры охраняли плененного наару, и часть его энергии еще находится в них. Этого сосуда хватит, чтобы вернуть к жизни падшего рыцаря.\n\nНе беспокойся о магистрах, за ними присмотрят. Лорд Соланар сообщил мне, что Леди Лиадрин занимается поиском нового источника магической силы.", progress = "Тебе удалось поговорить с магистром Асталором Кровавой Клятвой?", completion = "Прекрасно, Скуфопал. Каким бы могущественным не был М'ууру, он не способен противостоять воле рыцарей крови.\n\nТеперь для тебя открыт новый путь. Мало кто решается вступить на него, но я уверен, что ты справишься и станешь новой гордостью ордена.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9685] = {title = "Воскрешение", objective = "Отправляйтесь в таверну Луносвета и воскресите Сангриаса Безмолвного Клинка с помощью силы, заключенной в наполненном мерцающем сосуде.", description = "Пока ты <наполнял/наполняла> сосуд, отряд посвященных принес тело Сангриаса Безмолвного Клинка. Отправляйся на верхний этаж таверны Луносвета и воскреси Сангриаса с помощью магической силы, заключенной в сосуде.\n\nПоторопись, <имя>. Если не успеешь вовремя, даже все могущество Света не сможет вернуть его к жизни. Возвращайся ко мне, когда закончишь.", progress = nil, completion = "Рад снова видеть тебя, юный рыцарь. Ты узрел источник нашей силы и смог подчинить его себе. Теперь я научу тебя воскрешению падших непосредственно в бою.\n\nПродолжай служить ордену и оттачивай мастерство, и тебе откроются новые грани силы.", rewards = "Вы изучите:\n\nИскупление\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9686] = {title = "Второе испытание", objective = "Пройдите второе испытание, победив воителя Ярокрова, воителя Светореза, воительницу Быстромеч и воителя Солнцесвета в павильоне у наставника Келерана Алого Взмаха.", description = "От титула адепта тебя отделяет лишь одно испытание, <имя>.\n\nОно совсем не похоже на предыдущее – в этот раз все четко и понятно: брось вызов четырем лучшим рыцарям крови и победи их в честном бою.\n\nКогда будешь <готов/готова> начать, прикоснись к кристаллу, что появится посередине павильона. После этого просто дождись начала испытания.\n\nНачнем?", progress = "Рыцарь Крови скорее погибнет, чем сдастся. Не забывай об этом, Закидон.", completion = "Превосходно, Большеслэма! Ты доказал, что достоен носить почетный титул адепта и стать настоящим рыцарем Крови. Правда, перед посвещением тебе придется выполнить еще пару поручений.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9687] = {title = "Святотатство", objective = "Принц Торет с острова Драконьей Скорби просит отыскать 8 костей драконов.", description = "Не так давно на берегах этого острова стали появляться совухи. Они приходили поодиночке и с единственной целью: похитить кости павших драконов. Не знаю, что произошло с этими существами – прежде совухам никогда не приходило в голову тревожить прах ушедших; но ныне души драконов лишились покоя, не в силах вынести святотатства.\n\nЕсли ты отправишься на запад и минуешь Кровавый берег, то доберешься до гряды Яростного Пера. Там, в поселениях совухов, можно отыскать похищенные кости драконов...", progress = "Давно минули времена войн драконов. Все, что осталось, – древние кости и немногие живые из выводка Изеры...", completion = "Ритуал?.. Совухи тысячи лет жили в гармонии с природой и этой землей. Это безумие какое-то!..\n\nКак жаль...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9688] = {title = "Дорога в Сон", objective = "Принц Торет с острова Драконьей Скорби просит убить 5 темно-зеленых дракончиков и 5 детенышей зеленого дракона.", description = "То, что ты видишь, – это беспокойные духи зеленых драконов. Подобно мне, они привязаны к этой земле и не могут достичь места своего упокоения в Изумрудном Сне.\n\nТо, что тебе удалось вернуть кости погибших, немного успокоило их, однако еще рано останавливаться на достигнутом...\n\nНеобходимо уничтожить астральные тела этих заблудших драконов и освободить их души. Пока это не будет совершено, я не сумею покинуть остров!", progress = nil, completion = "Каким бы отвратительным ни было это деяние, его нужно было совершить. И теперь тебе предстоит взглянуть в лицо истинному злу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9689] = {title = "Острозуб", objective = "Принц Торет с острова Драконьей Скорби просит убить Острозуба.", description = "В битвах погибли многие черные драконы; но дух одного из них, военачальника Смертокрыла, все еще скитается в этих краях. Взгляни на небо – и ты увидишь, как его астральный образ кружит над тобой. Его ненависть так велика, что даже смерть не смогла притушить это пламя.\n\nОтнеси собранные тобой кости драконов на вершину горы и положи в неугасающий погребальный костер. Для Острозуба это будет знаком спуститься. Когда это произойдет, уничтожь его.", progress = nil, completion = "Сколько же времени прошло? Тысяча лет? Или, может, десять тысяч?.. Ты даже представить себе не можешь, Эксордим, какая это огромная услуга для меня и моего народа. Прошу тебя, прими этот волшебный предмет из Лорет'Арана в знак моей вечной благодарности.", rewards = "Одеяние истребителя драконовЖилет истребителя драконовМундир истребителя драконовВы получите:\n\n"}
MultiLanguageQuestData['ru'][9690] = {title = "Второе испытание", objective = "Поговорите с наставником Келераном Алым Взмахом.", description = "Что ж, <юный/юная> <имя>. Ты <узнал/узнала> истинную природу нашего могущества и <приложил/приложила> немало усилий, чтобы овладеть им и стать настоящим рыцарем крови.\n\nПришло время второго испытания. Выдержишь его – и я наделю тебя титулом адепта. Отправляйся к наставнику Келерану Алому Взмаху. Чтобы найти его, держи свой путь на север, через руины Луносвета, а затем сверни на восток прямо перед мостом к острову Солнечного Скитальца.", progress = nil, completion = "Подготовься как следует. Когда почувствуешь в себе силы, возвращайся ко мне, и я поведаю тебе о предстоящем испытании.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9691] = {title = "Возвращение в Луносвет", objective = "Возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.", description = "Возвращайся в Луносвет и встреться с предводителем рыцарей Доблестной Кровью. Не беспокойся: твой визит будет лучшим доказательством того, что испытание успешно пройдено.\n\nПредводитель сам расскажет тебе, что осталось совершить для получения титула адепта. Тебе есть чем гордиться, <имя>. Поверь, немногим удается пройти это испытание и остаться в живых.", progress = nil, completion = "Я знал, что в тебе есть силы пройти испытание, Большеслэма. Теперь до получения титула остались простые формальности - правда, не менее опасные, чем поединки с лучшими рыцарями ордена. Слушай внимательно, я расскажу тебе, что нужно сделать.", rewards = "Вы также получите:\n\n"}
MultiLanguageQuestData['ru'][9692] = {title = "Путь адепта", objective = "Принесите оскверненный самоцвет Кора, ящик со слитками, закаленными в крови, нужное количество крови разгневанных и знак отличия рыцаря крови предводителю рыцарей Доблестной Крови в Луносвет.", description = "Прежде вступить в орден, каждый кандидат должен собрать все необходимые компоненты для ковки особого оружия рыцарей крови – закаленного кровью протазана.\n\nКроме того, каждый рыцарь должен носить особый знак отличия. Выковать знак нельзя – его можно только получить от ветерана ордена. Знак, который будешь носить ты, принадлежал бесстрашному рыцарю, павшему при осаде Смертхольма. Но сначала тебе нужно найти его.\n\nЯ подготовил несколько записок, которые помогут тебе в поисках.", progress = "Ты принес все необходимое?", completion = "Прекрасно, Хаттоо. Все готово. Осталось лишь выковать оружие.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9693] = {title = "Что для тебя Аргус?..", objective = "Экзарх Адметиус с Кровавой заставы просит поговорить с воздаятелем Боросом.", description = "Скажи, что для тебя значит Аргус? А, <имя>?.. Многие дренеи не знают или не помнят нашей родной планеты. Именно там мы отделились от ман'ари – демонических сущностей, искаженных отражений нас самих, получивших \"дар\" от Саргераса. От тех, кто именует себя \"эредар\".\n\nЭредар... когда-то у этого слова был смысл...\n\n*Адметиус словно бы пробует слово на вкус.*\n\nОтвратительно.\n\nНу, довольно попусту тратить время. Найди воздаятеля Бороса – у него тебе предстоит начать свое обучение.", progress = nil, completion = "Ах, Тэррат... Да, я слышал о тебе. Говорят, тебе удалось дугу Кессела за 15 минут проскочить? Хотя мне как-то не очень верится.\n\nТы готов жить и умереть во имя Света? Во имя Велена? Во имя Аргуса?..\n\n&lt;Борос смеется.&gt;\n\nЛадно, ладно, что-то я увлекся.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9694] = {title = "Кровавая застава", objective = "Убейте 10 шпионов Солнечных Ястребов и сообщите об этом на Кровавую заставу воздаятелю Боросу.", description = "Кровавая застава – одна из двух застав, которыми управляет Длань Аргуса. Вторая – Лазурная застава, где тебе уже довелось побывать. Так вот, запомни: на острове Кровавой Дымки все не так, как на острове Лазурной Дымки. Когда мы прибыли сюда, эта земля была не менее прекрасной, чем земли острова Лазурной Дымки; мы даже назвали ее островом Серебряных Ветров... Но ныне эта земля отравлена; к тому же эльфы крови, с которыми мы сражались на \"Экзодаре\", выжили и стали появляться здесь. Собственно, с этим-то и связано задание, которое я хочу тебе дать. Отправляйся на северо-запад, в лес Клинков. Если тебе встретятся эльфы крови – убивай их без колебаний.", progress = nil, completion = "О, ты вернулся! Поверить не могу - цел и невредим!\n\nА у меня для тебя есть хорошие новости, Ревектор. Обнаружено еще одно место крушения. Как только я покончу с этими делами, непременно вызову тебя.", rewards = "Кулак АргусаКлинок АргусаРуки перекрестного огня АргусаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9695] = {title = "Повеление Солнечного короля", objective = "Доставьте повеление Солнечного короля воздаятелю Боросу на Кровавую заставу.", description = "Похоже, это важный документ. Жаль только, что он написан на талассийском – ведь ты не знаешь этого языка, верно?\n\nБудем надеяться, воздаятель Борос подскажет, что делать с этим письмом.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9696] = {title = "Переводы...", objective = "Доставьте послание Солнечных Ястребов дознавательнице Элизии на Кровавую заставу.", description = "Наша старшая дознавательница Элизия свободно говорит на талассийском. Отнеси ей этот документ, посмотрим, что она скажет.", progress = "Агент Рудель, вы отрываете меня от работы. Надеюсь, у вас действительно важное дело...", completion = "&lt;Элизия читает документ.&gt;\n\nЕсли то, что здесь написано, – правда, значит, эльфы крови открыли портал в Запределье. Да, это объясняет, почему их становится все больше и больше...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9697] = {title = "Наблюдательница Лиса'о", objective = "Поговорите с наблюдательницей Лиса'о у кенарийского караульного поста в Зангартопи.", description = "Экология местных существ, в особенности спорлингов и болотников, требует серьезного исследования. Казалось бы, что в этом такого? Но, занявшись полевыми исследованиями, ты обнаружишь, что дело это опасное и требует мужества и находчивости.\n\nОтыщи наблюдательницу Лиса'о у кенарийского караульного поста на юго-западе болот. Ступай по дороге на запад, и рано или поздно придешь туда. Она, правда, чересчур погружена в свои научные исследования, но не обращай на это внимания.\n\nДа, и еще: осторожнее с ее кошкой!", progress = nil, completion = "О, замечательно! Наконец-то хоть какая-то помощь! У меня так много дел, а я вынуждена сидеть здесь, чтобы организовывать работу.\n\nНадеюсь, ты не боишься грязной работы?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9698] = {title = "Аудиенция у Пророка", objective = "Доставьте переведенное послание Солнечных Ястребов Пророку Велену в Экзодар.", description = "Послушай, <имя>, мне нужно, чтобы ты лично <доставил/доставила> переведенные документы Велену. Этому ненормальному посланнику я не доверяю.\n\nОбъясни пророку, что эльфы крови получают подкрепление из Запределья и что среди дренеев в Экзодаре у них есть шпион. Ты сможешь найти Велена в Чертоге Света Экзодара.\n\nСпеши!", progress = "*Велен улыбается.*\n\nПриветствую, Эксордим. Я ждал тебя.", completion = "&lt;Велен читает документ.&gt;\n\nЛюбопытно... Это действительно многое объясняет...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9699] = {title = "Правда или вымысел", objective = "Доставьте распоряжения Велена воздаятелю Боросу на Кровавую заставу.", description = "Благодарю, <имя>, ты <успел/успела> как раз вовремя. Похоже, ты - один из лучших агентов Длани Аргуса.\n\nЕсли бы мы еще знали, с кем на острове Кровавой Дымки они поддерживают связь и где находится Солнечный портал... Где бы ни был этот портал, похоже, его надежно охраняют.\n\nНе хочешь ли заняться его поисками?\n\nЕсли ты не против, доставь эти распоряжения воздаятелю Боросу. Он расскажет тебе, что делать.", progress = "Ну что?", completion = "План неплох – но и опасен. Но, я уверен, ты справишься.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9700] = {title = "Магия против Тьмы", objective = "Воздаятель Борос с Кровавой заставы просит найти солнечный портал и убить 5 аномалий Бездны.", description = "Велен говорит, что если эльфы крови попытались создать переход между этими островами и Запредельем, то в местах открытия порталов непременно объявятся аномалии: это неизбежный побочный эффект. Тебе нужно обыскать остров и обнаружить места скопления подобных аномалий.\n\nПомни, <имя>: некоторые из этих существ – выходцы из Бездны. Если они встретятся тебе, убивай их без колебаний! Если тебе удастся выяснить что-то новое, сообщи об этом мне. Поиски лучше начать с севера, от сверхускорителя.", progress = nil, completion = "И сколько этих тварей у сверхускорителя?.. Сколько же раз они открывали этот проклятый солнечный портал?! Скверно, очень скверно...\n\nУвы, Эксордим, я научил тебя всему, чему мог. Когда придет время, Курос позовет тебя...", rewards = "Туфли воздаятеля на мягкой подошвеКожаные мокасины воздаятеляВысокие ботинки воздаятеляВы получите:\n\n"}
MultiLanguageQuestData['ru'][9701] = {title = "Наблюдение за спорлингами", objective = "Исследуйте Грибную поляну в Зангартопи, затем вернитесь к наблюдательнице Лиса'о к кенарийскому караульному посту в Зангартопи и расскажите об увиденном.", description = "Нам следует как можно больше узнать о спорлингах из Спореггара и их взаимоотношениях с окружающим миром. Один из способов это сделать – это незаметно наблюдать за спорлингами, как делаю это я.\n\nА тебя я попрошу сходить на Грибную поляну к западу отсюда. Исследуй весь тот район, вернись и расскажи мне, что тебе удалось узнать.", progress = nil, completion = "Что?! Болотники с гряды Квагг пожирают отпрысков спорлингов?! Это ужасно!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9702] = {title = "Вопросы питания", objective = "Соберите 10 образцов выброшенного корма и вернитесь к наблюдательнице Лиса'о на кенарийский караульный пост в Зангартопи.", description = "Я все не могу понять, зачем болотники переходят через дорогу на Грибную поляну. Должно быть, они голодают? В любом случае, так дело не пойдет!\n\nЯ имею в виду, что в обычных условиях не стала бы вмешиваться, но если они и дальше будут пожирать отпрысков спорлингов, спорлинги окажутся истреблены!\n\nВот как мы поступим: я останусь здесь, а ты отправляйся к гряде Квагг на востоке и попытайся выяснить, почему болотники вторгаются на территорию спорлингов.", progress = "Смотри, |3-6(Охотник), материал для исследований нужно собирать очень тщательно! Мы как бы складываем большую головоломку. И одна-единственная ошибка с твоей стороны может привести нас к ложным выводам.\n\nА нам необходимо разобраться в экологии Зангартопи!", completion = "Вот это и есть твои находки? Странно. Эти объедки грибов выглядят необычно, и в то же время как-то знакомо…\n\nПодожди минутку, мне необходимо подумать. Смотри, никуда не уходи!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9703] = {title = "Криогенный блок", objective = "Воздаятель Курос хочет, чтобы вы доставили на Кровавую заставу 12 коробок с медицинскими припасами.", description = "У нас есть кому заняться поиском порталов, <имя>. Для тебя есть другая, не менее важная задача.\n\nБоросу недавно доложили об обнаружении нового места падения обломков \"Экзодара\". Кроме того, нам удалось выяснить, что этот обломок фактически является криогенным блоком \"Экзодара\". Там находятся капсулы – точно такие же, как те, из которых некогда вышли дренеи в долине Аммен.\n\nКроме того, там находятся медицинские припасы. Отправляйся на запад от Кровавой заставы – именно там находится криогенный блок. Постарайся найти припасы – и выживших, если, конечно, они там есть.", progress = "Ну что, сведения были точны?", completion = "Только эльфы крови? И ни одного выжившего?.. Скверно, скверно... Мне нужно время, чтобы обдумать это, Эксордим. А пока, возможно, у Эсома или Бороса найдется для тебя какое-нибудь дело.", rewards = "Сокрушитель воздаятеляНож для бумаг воздаятеляТрость воздаятеляВы получите:\n\n"}
MultiLanguageQuestData['ru'][9704] = {title = "Смерть от рук Презренных", objective = "Отправляйтесь на юг, в руины Луносвета, и отыщите убитого курьера на Рассветной улице.", description = "Нелегко быть курьером и поддерживать связь между островом Солнечного Скитальца и площадью Соколиных Крыльев. Жесткие сроки, работа допоздна и, что хуже всего – Презренные!\n\nДорога на юг проходит через руины Луносвета... они кишат Презренными, которые готовы прикончить любого за пару кристаллов маны. Боюсь, эта печальная участь и постигла курьера, с которым мы сегодня отправили одну из посылок Эроны.\n\nВижу, тебе не терпится показать себя. Ступай на Рассветную улицу и попробуй найти какие-нибудь следы пропавшего курьера.", progress = nil, completion = "С тела курьера похищено все, кроме одной посылки. Судя по описанию Аларион, это и есть посылка Эроны.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9705] = {title = "Возвращение посылки", objective = "Вернитесь к курьеру Аларион с посылкой Эроны.", description = "Вы берете посылку и удостоверяетесь, что она и правда от магистра Эроны. Аларион, наверное, хотела бы, чтобы вы вернули ее.", progress = "Что тебе удалось найти, Джав?", completion = "Во имя Солнечного Колодца! Это третий курьер, которого мы потеряли за последний месяц!\n\nЯ ценю твою отвагу – не каждый осмелится сунуться на Рассветную улицу. Стражам нужно лучше следить за этими злосчастными Презренными.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9706] = {title = "Дневник Галена: судьба воздаятеля Саруана", objective = "Доберитесь до Кровавой заставы и отдайте дневник Галена воздаятелю Куросу.", description = "Когда вы поднимаете эту книжку, ваши руки дрожат. Курос непременно должен узнать об этой трагедии. Отдайте книжку ему.", progress = "Что это у тебя, Рудель? Дневник?", completion = "&lt;Читая дневник, Курос бледнеет; по его лицу катятся слезы.&gt;\n\nСаруан был моим господином... моим учителем... наставником... Я лишь недавно занял его место в Триумвирате – и только после того, как мы уверились, что самого Саруана не отыщем.\n\n&lt;Лицо Куроса искажается от гнева.&gt;\n\nАх, вот как?.. Матис!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9707] = {title = "Ковка оружия", objective = "Принесите ящик с материалами Бемаррину в Луносвет.", description = "Что ж, ты <доказал/доказала>, что <достоен/достойна> стать рыцарем нашего ордена. Для меня большая честь даровать тебе титул адепта, <имя>. Сам принц Кель'тас гордился бы тобой.\n\nТы будешь опорой для тех, кто сражается рядом с тобой, и примером для тех, кто стремится присоединиться к нам. Не щади врагов и не показывай свою слабость, защищай свой народ и стань истинным владыкой Света.\n\nА теперь пришло время выковать оружие, положенное тебе с новым титулом.", progress = "Поздравляю, Хаттоо. Заслужить титул адепта может далеко не каждый. Уж поверь моим словам - я видел много страждущих, и лишь единицам удавалось довести дело до конца.", completion = "Теперь у меня есть все, что нужно. Приступим!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9708] = {title = "Знакомые грибы", objective = "Соберите 15 образцов грибов и принесите их наблюдательнице Лиса'о на караульный пост Кенария в Зангартопи.", description = "Да-да, я же знала, что уже встречала этот тип грибов в другом районе болот!\n\nУ меня есть гипотеза... К северу отсюда есть место, которое называют Болотными вырубками. Мне лично это название кажется странным, но, с другой стороны, я же там не бывала... Так вот, мне нужны образцы тамошних грибов, чтобы проверить мои соображения.\n\nТолько смотри, <класс>, будь <осторожен/осторожна:c>! Я слышала, что в тех краях появились огры. Возможно, тебе придется отбирать образцы у них. Может быть, это из-за огров болотники больше не решаются добывать там пищу?", progress = "Ну что, образцы у тебя?", completion = "Да, все сходится... Присутствие огров и то, чем они занимаются, объясняет все. Да уж, теперь понятно, отчего та местность называется Болотными вырубками!\n\nНужно как-то исправить положение, но как? Не можем же мы просто истребить этих огров! В конце концов, они точно так же имеют право на жизнь, как и любые другие жители болот!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9709] = {title = "Ворованные грибы", objective = "Соберите 10 ящиков грибов и вернитесь с ними к наблюдательнице Лиса'о на караульный пост Кенария в Зангартопи.", description = "<класс>, у меня есть идея! Возвращайся на север и проберись на территорию огров.\n\nК северо-западу от Болотных вырубок есть место, которое называется крепость Анго'рош. Крепость находится на парящем острове, куда ведет мост из большого гриба.\n\nДолжно быть, огры хранят собранные грибы именно там. Могу поручиться, они там есть повсюду, и уж тем более у самих огров!\n\nПринеси мне побольше этих грибов, и я попытаюсь предложить болотникам новый источник пищи.", progress = "Ну что, достаточно ли у нас грибов, чтобы устроить новый сад для болотников?", completion = "Великолепно! Ох, |3-6(Охотник), спасибо тебе!\n\nТы действовал так осторожно, не нарушая естественный порядок вещей, и при этом за короткий период времени нам удалось собрать столько сведений!\n\nА теперь давай взглянем, сработал ли наш план по выращиванию новых запасов пищи для болотников...", rewards = "Зангарские эполетыШлем природной чистотыБолотный пояс выживающегоНарукавье Лиса'оВы получите:\n\n"}
MultiLanguageQuestData['ru'][9710] = {title = "Закаленный кровью протазан", objective = "Дождитесь, пока Бемаррин смастерит оружие.", description = "Все готово, <имя>. Скоро ты получишь свое новое оружие.", progress = nil, completion = "Вот твое оружие, Хаттоо. Да поможет оно в твоей праведной службе ордену и Луносвету.", rewards = "Вы получите:\n\nЗакаленный кровью протазан"}
MultiLanguageQuestData['ru'][9711] = {title = "Матис Жестокий", objective = "Воздаятель Курос с Кровавой заставы требует, чтобы Матис Жестокий был пойман.", description = "Матис должен предстать перед судом, <имя>; надеюсь, с твоей помощью он будет обнаружен и предстанет перед Триумвиратом.\n\nОбыщи остров и найди этого ублюдка. Вот тебе сигнальное ружье – выстрелишь, когда разыщешь Матиса, и мои следопыты помогут тебе задержать его. Потом возвращайся ко мне.", progress = nil, completion = "Триумвират решил немедленно предать Матиса суду. Благородный |3-6(ночной эльф), сегодня благодаря тебе мы обезвредили величайшего преступника.\n\nДва задания из трех исполнены безукоризненно; посмотрим, что поручит тебе Эсом.", rewards = "Короткие штаны воздаятеляКожаные гамаши воздаятеляЖелезные набедренники воздаятеляВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][9712] = {title = "Талассийский боевой конь", objective = "Поговорите с предводителем рыцарей Доблестной Кровью, чтобы научиться вызывать талассийского боевого коня.Тебе удалось добиться поистине впечатляющих успехов, <имя>. Магистр Асталор и его поверенные позволили тебе прикоснуться к силе Света - и ты <сумел/сумела> обратить ее себе во благо. Пришло время получить новые знания.\n\nСила Света дарует способность вызывать талассийского тяжеловоза, который станет твоим верным скакуном.\n\nПродолжай служить ордену, <имя>. Тебя ждут еще большие свершения.Вы изучите:\n\n", description = "Тебе удалось добиться поистине впечатляющих успехов, <имя>. Магистр Асталор и его поверенные позволили тебе прикоснуться к силе Света - и ты <сумел/сумела> обратить ее себе во благо. Пришло время получить новые знания.\n\nСила Света дарует способность вызывать талассийского тяжеловоза, который станет твоим верным скакуном.\n\nПродолжай служить ордену, <имя>. Тебя ждут еще большие свершения.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nПризыв боевого коня"}
MultiLanguageQuestData['ru'][9714] = {title = "Принеси мне еще одну клумбу!", objective = "Кровавый гибискус, который можно найти у шаркунов, болотоходов и подболотных скатов в Нижетопи, в резервуаре Кривого Клыка, нам всегда пригодится. Приноси его мне связками по пять штук, я буду очень тебе благодарен!", description = nil, progress = "Кровавый гибискус, который можно найти у шаркунов, болотоходов и подболотных скатов в Нижетопи, в резервуаре Кривого Клыка, нам всегда пригодится. Приноси его мне связками по пять штук, я буду очень тебе благодарен!", completion = "Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты еще раз заглянешь в Нижетопь?", rewards = nil}
MultiLanguageQuestData['ru'][9715] = {title = "Принеси мне клумбу!", objective = "Добудьте 5 растений кровавого гибискуса и отнесите их Гзхун'тту в Спореггар в Зангартопи.", description = "Нам необходимо пополнить наши запасы кровавого гибискуса. Мы его используем в самых разнообразных целях. Раньше этого гибискуса было много повсюду, но теперь, когда болота пересыхают, он водится только в Нижетопи в резервуаре Кривого Клыка, что под Змеиным озером.\n\nГоворят, что для тамошних шаркунов, болотоходов и подболотных скатов он – лучшее лакомство. Так что, если хочешь нам помочь, добудь у них эти цветы.", progress = "Ну что, удалось тебе добыть гибискус, как я просил?", completion = "Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты еще раз заглянешь в Нижетопь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9716] = {title = "Неприятности на озере Тенетопь", objective = "Выясните причину убывания воды в озере Тенетопь. Затем вернитесь к Исиэль Песни Ветра в Кенарийский приют в Зангартопи.", description = "Мы явились в Запределье, рассчитывая найти здесь крохотные островки сохранившейся жизни. Но в Зангартопи мы обнаружили обширную, процветающую экосистему!\n\nОднако наши первые радужные впечатления оказались обманчивыми. Уровень воды в озерах и болотах непрерывно понижается все то время, что мы делаем замеры!\n\nДля местных животных и растений это может обернуться катастрофой. Отправляйся на озеро Тенетопь к юго-западу отсюда и попробуй отыскать причину убывания воды.", progress = "Ну что, Уменябольшие, удалось что-нибудь выяснить?", completion = "За этим стоят наги! Но зачем им это? Судя по тому, что ты описываешь, этот паровой насос может быть причиной того, почему уровень воды в болоте падает!\n\nЭто объясняет то, отчего они относятся к нам столь враждебно... Что ж, не будем тратить времени. Я попрошу тебя выполнить для нас еще одно задание.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9717] = {title = "Удачный ход", objective = "Добудьте ветку подспорника и вернитесь с ней к Т'шу в Спореггар в Зангартопи.", description = "Мы – народ мирный, но вести войну со споровыми великанами мы просто вынуждены, нравится нам это, или нет. А у нас есть поговорка, что, когда речь идет о грибах и о войне, все средства хороши!\n\nОдин из предводителей споровых великанов, Болотоглад, уже в течение нескольких тысяч лет бережно взращивает особое растение, известное как подспорник. Если с этим растением что-то случится, дух Болотоглада, несомненно, будет сломлен!\n\nОтправляйся в Нижетопь, что в резервуаре Кривого Клыка, и укради у него это растение! Поверь мне, на это он внимание обратит непременно!", progress = "Нижетопь - очень опасное место! Я, конечно, не сочту тебя трусом, если ты не рискнешь отправиться туда. Однако, если уж ты возьмешься за дело, стыдно тебе будет вернуться с пустыми руками.", completion = "&lt;Спорлинг издает звук, отдаленно напоминающий хмыканье.&gt;\n\nВеликолепно! Несомненно, боевой дух споровых великанов упадет ниже дна болота, как только они поймут, что тебе удалось совершить.\n\nПравда, возможно, они так разгневаются, что нападут на нас снова...\n\n&lt;Т'шу делает такое движение, как будто пожимает плечами.&gt;", rewards = "Вы получите:\n\nВечная ветвь подспорника"}
MultiLanguageQuestData['ru'][9718] = {title = "С высоты птичьего полета", objective = "Используйте амулет буревестника, чтобы исследовать основные озера Зангартопи по просьбе Исиэли Песни Ветра.", description = "Нужно определить, сколько озер затронула деятельность наг, и затем уже действовать.\n\nРазумеется, обследовать каждый водоем в Зангартопи – дело долгое. С помощью магии я могу изменить твой облик, приспособив его для этой разведки.\n\nКогда будешь <готов/готова>, подойди ко мне и используй этот амулет. А когда дело будет окончено, я помогу тебе благополучно вернуться обратно.", progress = "Привет тебе, Джонниди!", completion = "Все как я подозревала! Наги установили насосы на всех крупных озерах Зангартопи!\n\nИх необходимо остановить, если мы хотим спасти болота...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9719] = {title = "Охота на Охотницу", objective = "Принесите мозг Черной Охотницы Кхн'иксу в Спореггар в Зангартопи.", description = "Испокон веков наибольшую угрозу для моего народа представляли болотоходы. Теперь, когда нам угрожают еще и споровые великаны, мы не можем допустить, чтобы на нас нападали наши старинные враги!\n\n<класс>, отваги тебе не занимать, ты <доказал/доказала> это. Как ты думаешь, ты сумеешь пробраться в Нижетопь, что в резервуаре Кривого Клыка, и уничтожить великую мать болотоходов, Черную Охотницу?\n\nА в доказательство принеси мне ее мозг!", progress = "Ты вернулся. Означает ли это, что Черной Охотницы больше нет?", completion = "Черная Охотница мертва! Нехорошо радоваться убийству, но эта великая мать и все ее племя на протяжении веков причиняли моему народу неисчислимые страдания.\n\nУвы, теперь одна из ее потомков преобразуется и займет ее место, однако это все же займет какое-то время, и мы сможет перевести дух. В течение некоторого времени болотоходы перестанут нас тревожить...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГриб СущностиМогущественный гриб\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9720] = {title = "Необходимо поддерживать равновесие!", objective = "Осыпьте семенами железной лозы пульты управления паровым насосом в Змеином озере, озере Тенетопь, озере Болотных Огоньков и в Лагуне. Затем вернитесь к Исиэль Песни Ветра в Кенарийский приют в Зангартопи и отдайте ей оставшиеся семена.", description = "Я представления не имею, для чего нагам понадобилось осушать свои собственные озера. Но знаю одно: их необходимо остановить!\n\nЭти семена несут в себе гнев самой земли. Отнеси их к паровым насосам, установленным нагами, и осыпь ими все эти рычаги и приводы.\n\nИз семян прорастут лозы толщиной в руку и прочные, как сталь. Ступай, <имя>. Восстанови природное равновесие, нарушенное нагами!", progress = "Дело сделано, |3-6(Охотник)?", completion = "Стало быть, дело сделано. Теперь болото спасено.\n\nОднако не стоит обольщаться – наверняка нам еще не раз придется столкнуться с нагами. Здесь, в Запределье, мы не должны терять бдительности ни на секунду.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][9721] = {title = "Призыв леди Лиадрин", objective = "Поговорите с Лордом Соланаром в Луносвете.", description = "Твоя преданность ордену не осталась незамеченной: Лорд Соланар Кровогнев, правая рука самой Леди Лиадрин, пожелал встретиться с тобой.\n\nТакой чести удостаиваются немногие, <имя>. Обычно новыми кандидатами занимаюсь я, но Лорд Соланар считает, что ты - <особенный/особенная>. Не упусти свой шанс, <имя>!", progress = nil, completion = "Прежде чем мы перейдем к делу, позволь выразить восхищение твоим талантом.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9722] = {title = "Путь мастера", objective = "Поговорите с Лордом Соланаром еще раз и примите предложение о покровительстве.", description = "В нашем ордене есть круг посвященных, в который входят только самые преданные, опытные и умелые рыцари. Отличить их можно по особой породе скакунов - талассийским скакунам.\n\nКаждый кандидат на титул мастера должен доказать свою верность идеалам ордена и заручиться поддержкой одного из посвященных.\n\nЕсли ты действительно желаешь стать мастером - я лично буду твоим покровителем.После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][9723] = {title = "Жест преданности", objective = "Принесите лорду Соланару в Луносвет 40 отрезов рунической ткани, 6 арканитовых слитков, 10 солнечников, 5 темных рун и 150 золотых.", description = "Истинная преданность ордену доказывается не мечом, <имя>. Настоящий рыцарь должен быть готов выполнить любые поручения - какими бы мелкими и незначительными они не казались.\n\nИ сейчас тебе предстоит выполнить одно из таких поручений. Я дам тебе список предметов, которые необходимы поверенным магистра Асталора Кровавой Клятвы для поддержания энергии Света. Найди их и вернись ко мне.", progress = "Удалось найти все материалы для магистра Асталора?", completion = "Отлично. Все готово!\n\nЧто, не терпится проверить свои силы в бою? Скоро тебе представится такая возможность. Даю слово.\n\nЯ попрошу одного из своих поверенных доставить материалы магистру Асталору. А для тебя есть задание поважнее.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9724] = {title = "Предупреждение Кругу Кенария", objective = "Поговорите с Амитиэль Странницей Туманов на Заставе Кенария на полуострове Адского Пламени.", description = "Кенарийская экспедиция теперь сделалась крупной, практически самостоятельной организацией. Однако эти события достаточно важны, чтобы предупредить о них Круг Кенария.\n\nНе тревожься, тебе не придется возвращаться обратно на Лунную поляну. Посланцы Круга Кенария есть неподалеку отсюда, на полуострове Адского Пламени.", progress = nil, completion = "Принесенные тобой новости о деятельности наг в Зангартопи воистину ужасны! Исиэль поступила разумно, что сообщила об этом нам. Она не забывает, что экспедиции не выжить без поддержки Круга...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9725] = {title = "Доказательство лояльности", objective = "Лорд Соланар Кровогнев из Луносвета просит уничтожить 3 мясных фургона и убить 15 инженеров Плети.", description = "Защита земель Кель'Таласа – священный долг рыцарей крови, <имя>. Только благодаря нам и нашим союзникам жители Луносвета могут спать спокойно. Пришло время тебе разделить с нами эту обязанность.\n\nМне сообщили, что на северо-восточной границе, на окраине Восточных Чумных земель замечены воины Плети. Инженеры готовят свои машины к нападению на Призрачные земли. Их надо остановить!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9726] = {title = "Теперь, когда мы друзья...", objective = "Убейте 12 надсмотрщиков за рабами из клана Кровавой Чешуи, 6 чародеек из клана Кровавой Чешуи и возвращайтесь к Гзхун'тту в Спореггар в Зангартопи.", description = "Наги из анклава Кровавой Чешуи, что к северо-востоку отсюда, начали истреблять наш народ! <класс>, их необходимо остановить!\n\nНаучи их уму-разуму в доказательство нашей дружбы...", progress = "Ты еще не побывал в гостях у наг?", completion = "*Гзхун'тт кивает вам.*\n\nМы рады тому, что ты действительно надежный друг, Выручалкин! Быть может, теперь, когда у нас есть такой союзник, как ты, поганые наги подумают дважды, прежде чем нападать на нас!", rewards = "Посох чащобМолот СпорофитовПика выживающегоКлеймор ЗангартопиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9727] = {title = "Раз уж мы по-прежнему друзья...", objective = "Убейте 12 надсмотрщиков за рабами из клана Кровавой Чешуи, 6 чародеек из клана Кровавой Чешуи и возвращайтесь к Гзхун'тту в Спореггар в Зангартопи.", description = "Поступили сведения, что наги из анклава Кровавой Чешуи на северо-востоке продолжают истреблять наш народ! А мы было решили, что тебе, <класс>, удалось с ними покончить!\n\nБыть может, ты поучишь их уму-разуму, в доказательство того, что наша дружба по-прежнему прочна?", progress = nil, completion = "*Гзхун'тт кивает вам.*\n\nМы рады тому, что ты продолжаешь оставаться нашим надежным другом, Маганес! Уж наверное, теперь, когда ты уже не раз дал им понять, как опасно связываться с нами, эти бессмысленные нападения на наших сородичей прекратятся?", rewards = nil}
MultiLanguageQuestData['ru'][9728] = {title = "Теплый прием", objective = "Принесите стражу Хамуту из Кенарийского приюта 30 когтей наг.", description = "Друиды из экспедиции занимаются тем, что изучают растения и исследуют озера, ну, а мое дело – разбираться с враждебными существами.\n\nС тех самых пор, как мы появились в Зангартопи, наги то и дело нападают на нас без вызова и предупреждения. Мы делаем все, что можем, чтобы противостоять им, но наши возможности ограничены.\n\nЯ бы попросил тебя побывать в нескольких крепостях наг в Зангартопи и показать этим тварям, что с нами лучше не связываться. А в доказательство твоих подвигов принеси мне их когти!", progress = "Рад видеть тебя снова, Джонниди. Как продвигается охота на наг?", completion = "Молодец, Джонниди! И если вдруг тебя терзают угрызения совести - избавься от них. Здешние наги - гнусные твари, еще хуже азеротских.", rewards = "Вы получите:\n\nФлакон с летучим лечебным зельем"}
MultiLanguageQuestData['ru'][9729] = {title = "Фхвур крушить!", objective = "Проводите Фхвура к паровому насосу на озере Болотных Огоньков, чтобы добыть ковчег Ссслита. Потом доставьте обратно Фхвура и ковчег в целости и сохранности, и вернитесь к Гзхун'тту в Спореггар в Зангартопи.", description = "Мелкие наги злить Фхвура! Спорлинг – добрый друг Фхвура, Фхвур забрать ковчег наг!\n\nИдем в ближнюю деревню наг. Ты помогать?", progress = nil, completion = "Фхвур – хороший великан. Мы когда-то спасли его от наг, и теперь он живет с нами и помогает нам.\n\nМы можем только надеяться, что наги поймут намек и осознают, что, раз мы можем проникнуть в их деревню и похитить самое ценное из их сокровищ, то мы способны и на большее. Может быть, они наконец вернутся в свой резервуар и оставят нас в покое?", rewards = "Спореггарский сокрушительРассекающий болотный топорКоготь спорлингаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9730] = {title = "Предводитель Темного Гребня", objective = "Убейте раджу Хагазеда в Лагуне и вернитесь к стражу Хамуту из Кенарийской экспедиции в Зангартопи, чтобы получить награду.", description = "Кенарийская экспедиция назначает награду за голову раджи Хагазеда, предводителя наг из клана Темного Гребня. В последний раз кенарийские разведчики видели Хагазеда в Лагуне, в центре южной части Зангартопи.\n\nКлан Темного Гребня стоит за многочисленными нападениями на Кенарийскую экспедицию, и их предводитель считается крайне опасным существом.\n\nЖелающие получить награду могут обращаться к стражу Хамуту.", progress = nil, completion = "Мне эти наги еще на Азероте не нравились, а тут - и подавно. Очень жаль, что наша экспедиция - мирная, а не военная. Но, в любом случае, над мертвой нагой я рыдать не стану.\n\nВот тебе твоя заслуженная награда за предводителя Темного Гребня!", rewards = "Экспедиционное оплечьеДружеский кенарийский поясокКенарийская обувь стремительностиМягкие кенарийские башмакиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9731] = {title = "Схема стоков", objective = "Найдите в Змеином озере признаки утечки воды. Вернитесь к Исиэли Песни Ветра в Кенарийский оплот и сообщите о своем открытии.", description = "На добытой вами схеме изображена система подземных труб и насосов, ведущих от крупных озер Зангартопи к Змеиному озеру.\n\nЕсли верить этой схеме, в центре Змеиного озера находится огромная труба, куда и уходит вода. Проверьте эту информацию и передайте ее в Кенарийский приют.", progress = "Какие вести с фронта, Менгиле?", completion = "Наги превратили Змеиное озеро в огромную дыру, куда постепенно сливаются все воды Зангартопи... Что же они задумали?\n\nТы правильно поступил, Менгиле, что поспешил сообщить нам эту новость. Мы отправим отряд, чтобы исследовать это место утечки. А для тебя у меня пока что будет другое задание...", rewards = "Плащ бдительности смотрителяВам дадут возможность выбрать одну из следующих наград:\n\nКольцо точности стражаКольцо экспедиционного заклинателяПодвеска болот\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9732] = {title = "Назад в болото", objective = "Вернитесь к Исиэль Песни Ветра в Кенарийском приюте в Зангартопи.", description = "Возвращайся к Исиэль и дай ей знать, что помощь будет прислана при первой же возможности.\n\nНаших соратников удерживали дела на Лунной поляне и в Силитусе, однако мы сделаем все, что в наших силах, чтобы отправить подкрепление в Кенарийский приют!", progress = nil, completion = "Рада тебя видеть, Выручалкин! А у нас в Кенарийском приюте после твоего ухода дела идут все хуже и хуже...", rewards = "Наплеч болотного бродягиРукавицы призывателя ветровКенарийские экспедиционные сапогиВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9733] = {title = "Предупреждение Кругу Кенария", objective = "Поговорите с Махурамом Крепким Копытом в Траллмаре на Полуострове Адского Пламени.Кенарийская экспедиция теперь сделалась крупной, практически самостоятельной организацией. Однако эти события достаточно важны, чтобы предупредить о них Круг Кенария.\n\nНе тревожься, тебе не придется возвращаться обратно на Лунную поляну. Посланцы Круга Кенария есть неподалеку отсюда, на полуострове Адского Пламени.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Кенарийская экспедиция теперь сделалась крупной, практически самостоятельной организацией. Однако эти события достаточно важны, чтобы предупредить о них Круг Кенария.\n\nНе тревожься, тебе не придется возвращаться обратно на Лунную поляну. Посланцы Круга Кенария есть неподалеку отсюда, на полуострове Адского Пламени.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9734] = {title = "Возвращение на болота", objective = "Вернитесь к Исиэль Песни Ветра в Кенарийском приюте в Зангартопи.Возвращайся к Исиэль и дай ей знать, что помощь будет прислана при первой же возможности.\n\nНаших соратников удерживали дела на Лунной поляне и в Силитусе, однако мы сделаем все, что в наших силах, чтобы отправить подкрепление в Кенарийский приют!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Возвращайся к Исиэль и дай ей знать, что помощь будет прислана при первой же возможности.\n\nНаших соратников удерживали дела на Лунной поляне и в Силитусе, однако мы сделаем все, что в наших силах, чтобы отправить подкрепление в Кенарийский приют!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Наплеч болотного бродягиРукавицы призывателя ветровКенарийские экспедиционные сапогиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9735] = {title = "Истинные владыки Света", objective = "Принесите фиал святой воды Длани Тира Лорду Соланару Кровогневу в Луносвет.", description = "Рыцари крови – настоящие владыки Света. Но те, кто называет себя \"паладинами\", отказываются верить в наше превосходство и желают подчинить Свет себе.\n\nПора показать им, что с нами шутки плохи. И я придумала, как это сделать! Сначала проберись в библиотечное крыло аббатства Длани Тира и выкради один фиал святой воды...Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9736] = {title = "Истинные владыки Света", objective = "Принесите Лорду Соланару Кровогневу в Луносвет 1 чародейский катализатор, 1 меру сумеречного порошка, 1 азеротский алмаз и 1 безупречный черный алмаз.", description = "Теперь, когда у нас есть святая вода, пора приняться за поиски недостающих реагентов. Я подскажу тебе, где отыскать два из них, <имя>.\n\nОтправляйся на площадь, что возле Тропы Мертвых, и найди в одной из лавок торговку по имени Залле. У нее сможешь купить чародейский катализатор. А за вторым реагентом, сумеречным порошком, тебе прямая дорога к Дарлии, торговке ядами. Найти ее можно неподалеку от наставников разбойников в Закоулке душегубов.\n\nОставшиеся реагенты – азеротский бриллиант и чистый черный бриллиант – тебе придется искать <самому/самой>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9737] = {title = "Истинные владыки Света", objective = "Потушите неугасимое пламя часовни Алонсия с помощью огнетушительной смеси и уничтожьте всех, кто попробует защитить часовню.", description = "Только мы можем повелевать силой Света, <имя>. Пришло время раз и навсегда объяснить это глупцам, называющим себя \"паладинами\".\n\nЧасовня Алонсия, оплот рыцарей Серебряной Длани, оказалась нетронутой даже после разрушения Стратхольма. Неугасимое пламя, что горит внутри часовни, - вот что защищает ее. Потуши пламя с помощью огнетушительной смеси, и пусть весь мир узнает, кто настоящие владыки Света!", progress = "Ты преподала этим еретикам урок?", completion = "Замечательно, Кишкодёрка. Благодаря тебе весь мир узнал, что ждет каждого, осмелившегося противостоять нам.\n\nТы доказала, что достойна титула мастера. Твои деяния послужат примером для всех рыцарей крови. Помимо нового титула, я дарую тебе способность вызывать талассийского скакуна.", rewards = "Вы изучите:\n\nПризыв талассианского скакуна\n\nВы также получите:\n\nГербовая накидка рыцаря крови"}
MultiLanguageQuestData['ru'][9738] = {title = "Пропавшие без вести", objective = "Выясните, что стало с заклинателем земли Гневвсом, натуралистом Кусом, культиватором Зеленопалом и призывателем ветров Когтем. Затем возвращайтесь к дозорному Джанг в резервуар Кривого Клыка в Зангартопь.", description = "Умоляю, помоги мне! Нас прислала сюда Исиэль, чтобы мы разгадали загадку этих паровых насосов и выяснили, зачем они откачивают воду из болота. Однако мои друзья поступили опрометчиво - они разделились и отправились в разные стороны в одиночку.\n\nЭти четверо бывают такими недоумками, и все же я очень люблю их.\n\nПожалуйста, выясни что с ними сталось - я очень беспокоюсь. Поищи их в Узилище и в Нижетопи.\n\nБлагодарю тебя, <класс>.", progress = "Ты выяснил, что стало с моими друзьями?", completion = "Я рада, что хоть кто-то из моих друзей уцелел, и все же судьба остальных разбила мне сердце... \n\nПо крайней мере они погибли, занимаясь любимыми делом. Моя благодарность тебе безгранична, Амитран. \n\nПрошу тебя, прими это в знак моей признательности.", rewards = "Темный плащ трясиныНапульсники золотой лозыВам дадут возможность выбрать одну из следующих наград:\n\nКольцо заклинаний Кенария\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9739] = {title = "Проблемы спорлингов", objective = "Соберите 10 мешочков зрелых спор по просьбе Фассна с Грибной поляны.", description = "Эй, ты! Ты <обязан/обязана> нам помочь!\n\nГрибные великаны пожирают все наши мешочки со спорами! Сделай что-нибудь, иначе мы останемся без потомства!\n\nМешочки со спорами поначалу большие, а потом уменьшаются, по мере того, как выходит наполняющий их воздух. Отыщи побольше маленьких зрелых мешочков со спорами и спаси их – столько, сколько сможешь!", progress = "Мешочки со спорами! Они у тебя?", completion = "Тебе это удалось! Мой народ несказанно благодарен тебе.\n\nНадеюсь, ты нас поймешь... ведь из этих мешочков появляются на свет наши малыши! Мы не можем допустить, чтобы эти чудовища пожирали мешочки!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9740] = {title = "Солнечные Ворота", objective = "Воздаятель Эсом с Кровавой заставы хочет, чтобы солнечные врата были уничтожены.", description = "Благодаря тебе и тому, что ты <сделал/сделала>, мои разведчики сумели отыскать солнечные врата. Эльфы постарались сделать так, чтобы их можно было переместить в любой момент – именно потому на том месте, которое ты <исследовал/исследовала>, ничего не оказалось.\n\nОднако преимущество такой системы также является и ее величайшей слабостью. Солнечные врата стабилизируются при помощи пультов управления. Если мы сможем их уничтожить, то нам удастся уничтожить и сам портал. В настоящее время солнечные врата находятся к западу отсюда, к югу от энергоблока. Найди и уничтожь их!", progress = nil, completion = "Шикарно! Мы перерезали их линии снабжения. Теперь осталось нанести последний сокрушительный удар!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9741] = {title = "Твари из Бездны", objective = "Убейте 12 тварей Бездны и сообщите об этом на Кровавую заставу воздаятелю Эсому.", description = "Несколько дней назад Эсом послал мой отряд на поиски Солнечных Ворот. Понятное дело, мы их нашли...\n\n<Лорай указывает на Джорли.>\n\nНе знаю уж, что идиоты-эльфы таскают через этот портал, но оно вызывает выброс энергии Бездны. Всякие твари из Бездны там кишмя кишат.\n\nИх нужно уничтожить, пока они не превратились в аномалии. Все эти существа ползут от Солнечных Ворот: их несложно найти, если пойдешь отсюда на юго-запад. Когда покончишь с ними, не забудь доложить Эсому.", progress = nil, completion = "Вот это драка, а?.. Но для тебя, Рудель, как я вижу, такие дела не в новинку. Что ж, а я пошлю анахоретов на помощь Лорай и Джорли.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9742] = {title = "Новые мешочки со спорами", objective = "Что, |3-6(таурен), тебе удалось спасти еще несколько мешочков со спорами?", description = nil, progress = "Что, |3-6(таурен), тебе удалось спасти еще несколько мешочков со спорами?", completion = "Да! Благодаря тебе спасено еще несколько мешочков со спорами!\n\nТы не такой, как другие пришельцы. Я поведаю моему народу о твоих деяниях!\n\n&lt;Это задание можно выполнять повторно до тех пор, пока не добьешься дружелюбного отношения.&gt;", rewards = nil}
MultiLanguageQuestData['ru'][9743] = {title = "Природные враги", objective = "Принесите Фассну с Грибной поляны в Зангартопи 6 усиков болотника.", description = "Мы, спорлинги, и болотники никогда особо не ладили. Однако в прошлом нам удавалось обороняться от них копьями и камнями. А в последнее время они сделались более агрессивными... или же более отчаянными. Они не боятся ни нас, ни нашего оружия.\n\nНо ты – ты куда страшнее, и оружие у тебя лучше нашего. Если ты согласишься сразиться за нас против болотников, мы будем твоими вечными должниками! Принеси мне их усики, чтобы знать, сколько их тебе удалось перебить.", progress = "Ну, как идет истребление болотников? Объясни этим тварям, что в земли спорлингов соваться не следует!", completion = "Ты вернулся живым! Я расскажу о тебе другим спорлингам! Джонниди - победитель великанов!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9744] = {title = "Еще усиков!", objective = "Тебе удалось перебить немало великанов, но немало их по-прежнему бродит по болотам. И они по-прежнему охотятся на наши мешочки со спорами!", description = nil, progress = "Тебе удалось перебить немало великанов, но немало их по-прежнему бродит по болотам. И они по-прежнему охотятся на наши мешочки со спорами!", completion = "Невероятно! Нужны сотни спорлингов, чтобы перебить столько же великанов, сколько ты! Я позабочусь о том, чтобы о твоих деяниях стало известно всем.\n\n&lt;Это задание можно выполнять повторно до тех пор, пока не добьешься дружелюбного отношения.&gt;", rewards = nil}
MultiLanguageQuestData['ru'][9746] = {title = "Границы возможного", objective = "Убейте 10 пиромантов и 10 защитников Солнечных Ястребов и сообщите об этом на Кровавую заставу воздаятелю Эсому.", description = "Выше голову, <имя>! Победа близка! Теперь, когда Солнечные Ворота обнаружены, мы скоро прекратим эти эльфийские поставки. Думаю, заодно пришло время и сократить количество самих эльфов крови...\n\nК западу отсюда разбито множество лагерей Солнечных Ястребов – шагу нельзя ступить, чтобы не столкнуться с их защитником или пиромантом. Найди и убей их, а потом возвращайся ко мне.", progress = nil, completion = "Это, несомненно, ослабит их оборону. Теперь эльфы Крови не раз подумают, прежде чем попытаться напасть на нас!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9747] = {title = "Племя Тенетопи", objective = "Отправляйтесь в деревню Тенетопь и убейте Катару, 8 провидцев, 6 знахарей и 6 оракулов из племени Тенетопи по просьбе Икейена из Кенарийского приюта.", description = "Да, наги ужасны. Но еще ужаснее племена предателей, Сломленных и Заблудших, которые им помогали!\n\nИ хуже всех – Заблудшие из племени Тенетопи. Они используют черную магию, чтобы захватывать и порабощать других! К беглым рабам они особенно жестоки. Если я покину убежище хоть на день, меня поймают и перережут мне горло!\n\nОтправляйся в деревню Тенетопь к югу отсюда, и перебей их и их предводителя, Катару. Пока они живы, я не перестаю опасаться за свою жизнь!", progress = nil, completion = "Спасибо тебе, Менгиле! Наконец-то я смогу спать спокойно по ночам. Не будь я так стар и слаб, я бы и сам расправился со своими врагами...\n\nВот, прими это золото. Тут немного, но твое благородство не должно остаться без награды!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9748] = {title = "Не пей эту воду!", objective = "Воздаятель Эсом на Кровавой заставе попросил вас принести пробу воды с острова Кровавой Дымки во флаконе, который он предоставил.", description = "Наш шаман утверждает, что загрязнение источника привело в замешательство духов воды. Мы знаем, что силовое ядро Экзодара сокрыто в западных горах. Должно быть, там произошла утечка летучего реагента, отравившего запасы воды... Дополнительная информация нам бы не помешала.\n\n<Эсом кивает на флакон.>\n\nТебе надо прихватить с собой этот флакон и прогуляться по берегу на север до того места, где реки острова Кровавой Дымки впадают в океан. Возьми там образец воды и принеси его мне.", progress = "Послушай меня, Эксордим, не вздумай пить эту воду!", completion = "Как я и думал, вода покраснела от примесей, просочившихся из силового ядра.\n\nНадеюсь, тебе не пришло в голову искупаться в этой водичке?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9749] = {title = "Они живы! Может быть…", objective = "Освободите 5 ученых экспедиции по просьбе ученого Корнелиуса.", description = "Ты представить себе не можешь, <имя>, что мне пришлось пережить! Ужас! Кошмарный сон!.. На нас набросились пауки, будь они прокляты, да к тому же их прародительница, чтоб у нее все лапы поотсыхали, как с неба свалилась и тут же запеленала нас всех в коконы!\n\nНо это еще полбеды: эта членистоногая зараза пристроилась рядом с нами и начала откладывать яйца! Представляешь? Она решила, что мы - отличный корм для ее молодняка. КОРМ! Вообрази только!\n\nМне-то кое-как удалось выбраться, а мои товарищи так и валяются там, спеленутые, как младенцы. В одиночку мне их не спасти: я даже близко не могу подойти к тому проклятому месту. Ты ведь поможешь мне, верно?\n\nРаспутай коконы! Может, кто-то из наших еще остался в живых!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9750] = {title = "UNUSED Urgent Delivery", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][9751] = {title = "Наследие Проклятой Крови", objective = "Адмирал Одиссий просит разыскать капитана Эдварда Хейнса и поговорить с ним.", description = "Прошлой ночью в моем шатре объявился Эдвард Хейнс, капитан \"Утерянной надежды\". Да-да, тот самый Эдвард Хейнс, который умер от цинги двадцать лет назад.\n\nПризрак поведал мне историю, от которой кровь застыла у меня в жилах. Тебе непременно нужно услышать эту историю – и выполнить одно задание. Прошу тебя, разыщи Эдварда на острове Драконьей Скорби; ты сможешь найти его к северо-востоку от Кровавой заставы.", progress = nil, completion = "Скажи, ты, сухопутный червяк, тебе приходилось слышать о проклятии? Ну да, конечно, разумеется, ничего! А между тем именно проклятье и потопило все эти корабли; вернее сказать, это сделал риф Проклятой Крови – мерзейшее место в мире. Я и сам здесь торчу уже двадцать лет, если ты этого не знаешь.\n\nЯкорь мне в глотку!.. Вот тут-то я и помер, стал падалью, которой даже драконы брезгуют... Впрочем, это совсем другая история. Я сейчас не о том. Мы должны помочь тем злосчастным душам, которые попали в ловушку на этом рифе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9752] = {title = "Спасение с озера Тенетопь", objective = "Проводите Кайру Длинную Гриву в Кенарийский приют в Зангартопи. Выполнив эту задачу, поговорите с Исиэль Песнью Ветра.", description = "Пожалуйста, помоги мне выбраться отсюда!\n\nЯ собирала травы неподалеку от этого места, когда меня похитила толпа этих маленьких дикарей! Я пыталась сопротивляться, но их было слишком много.\n\nПомоги мне вырваться от этих жестоких тварей с их гнусной магией и вернуться в Кенарийский приют!", progress = nil, completion = "Ты спас одну из моих друидов! Мы перед тобой в неоплатном долгу, Выручалкин.\n\nВ знак благодарности всей экспедиции прими от меня вот это.", rewards = "Поножи исследователяМолот хранителяВам дадут возможность выбрать одну из следующих наград:\n\nМедальон хранителя\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9753] = {title = "То, что мы знаем...", objective = "Поговорите с экзархом Адметиусом на Кровавой заставе.", description = "За последние дни мы много узнали о наших врагах. Эльфы крови хотят уничтожить нас; их предводителя зовут Сиронас. Их цель – поработить О'роса и захватить \"Экзодар\".\n\nБлагодарение Свету, нам удалось лишить их снабжения, уничтожив солнечные врата. Увы, они по-прежнему используют энергоблок, чтобы отравлять землю мутагенными веществами.\n\nУзнав об этом, Адметиус разработал план действий. Тебе нужно разыскать его.", progress = nil, completion = "Послушай, Рудель, мне необходима твоя помощь. У меня есть план, благодаря которому мы сумеем разгромить армию Солнечных Ястребов, однако для его осуществления понадобится дополнительная информация.\n\nНам необходимо найти слабое место в их обороне. К сожалению, никому еще не удалось подобраться достаточно близко к энергоблоку, чтобы это выяснить. Если нам удастся заставить пленника говорить, возможно, мы сумеем прорвать оборону и разрушить энергоблок.\n\nТы понимаешь, о чем я, не так ли? Я хочу, чтобы проклятый энергоблок был взорван!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9756] = {title = "То, чего мы не знаем...", objective = "Поговорите с пленным агентом Солнечных Ястребов, которого держат на Кровавой заставе. Передайте полученные сведения экзарху Адметиусу.", description = "Должен сказать, <имя>, что допрос не дал никаких результатов. Разумеется, пытать пленных мы не можем, ты же понимаешь... Нам нужен свой лазутчик-<раса> среди них.\n\nЯ могу использовать заклинания, чтобы придать тебе сходство с эльфами крови по облику и речи. Возможно, эта хитрость поможет нам получить информацию о захваченном в плен разведчике.\n\nНадеюсь, под личиной <эльфа/эльфийки> тебе удастся вытянуть из пленника нужные сведения.\n\nДа, кстати, <имя>, должен тебя предупредить: не покидай Кровавую заставу под чужой личиной, иначе действие заклинания немедля прекратится...", progress = nil, completion = "Ага! Отличная работа, Рудель, просто прекрасная! А теперь - как насчет того, чтобы избавить наш остров от угрозы со стороны эльфов крови?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9757] = {title = "Охотница Келла Тетива Ночи", objective = "Поговорите с охотницей Келлой Тетивой Ночи рядом с причалом Валаара.", description = "Охотница Келла Тетива Ночи ищет способных охотников. Она научит тебя приручать диких зверей - это очень важное умение для охотника.\n\nКелла живет рядом с причалом Валаара, небольшом порту на западе от Экзодара.", progress = nil, completion = "Что ж, я готова преподать тебе первый урок...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9758] = {title = "Возвращение к чародею Вандрилу", objective = "Возвращайтесь к чародею Вандрилу в Транкивиллион, что в Призрачных землях.", description = "Не окажешь ли теперь и мне любезность? Вернись к чародею Вандрилу, я знаю, что он просто жаждет отправить тебя на первое твое задание здесь, в Призрачных землях.\n\nМы очень рассчитываем на тебя, <имя>. Не подведи нас.", progress = nil, completion = "А, ты здесь! И как раз вовремя! Нам многое предстоит сделать!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9759] = {title = "Отречемся от старого мира", objective = "Подрывник Легосо собирается разрушить энергоблок и убить Сиронас. Попытайтесь защитить его и, если задание будет успешно выполнено, расскажите об этом экзарху Адметиусу на Кровавой заставе.", description = "Если тебе дорога жизнь, не берись за это задание. Силовое ядро видишь? Вон ту громадную штуку, которая выпирает из склона горы - ну, там, вдали?.. Кто возьмется за это безнадежное дело, тому нужно будет пробиться к горе, сразившись с целой армией Солнечных Ястребов, притом прикрывать меня, покуда я буду готовить эту штуковину ко взрыву. К тому же где-то там, наверху, находится эредар Сиронас.\n\nКороче, <имя>, если ты просто развернешься и уйдешь, я не буду о тебе худого думать.\n\nНо, может, ты и есть <тот/та>, кто уничтожит энергоблок и прикончит Сиронас... Как думаешь?", progress = nil, completion = "Ты спас острова Лазурной и Кровавой Дымки, Эксордим! Теперь дренеи Азерота могут жить спокойно. Нет награды, которая оказалась бы чрезмерной за такое деяние, а уж о нашей благодарности и говорить нечего, ибо она безгранична.\n\nОднако же многие и многие остались на Дреноре - их не было здесь в этот исторический момент. А потому тебе нужно вернуться. Отправляйся в Запределье, герой Аргуса. Приведи наш народ домой - в ту землю, что была спасена благодаря тебе. Домой, на Азерот...", rewards = "Палица РукиКлинок РукиАрбалет РукиПосох РукиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9760] = {title = "Привал Защитника", objective = "Поговорите с воздаятельницей Корин в селении Привал Защитника на острове Кровавой Дымки;.", description = "Конечно, <имя>, никто не ожидает от тебя, что ты в одиночку уничтожишь энергоблок или прикончишь Сиронас; однако, полагаю, ты поможешь расчистить путь для тех, кто решится выполнить это опасное задание.\n\nЗнаешь дорогу, идущую на север от Кровавой заставы? Иди по ней до развилки, а там сверни налево. Твоя цель - селение Привал Воздаятеля, расположенное чуть западнее дороги. Там тебя встретит Корин.", progress = nil, completion = "Возможно, именно ты укажешь нашему народу путь к миру и процветанию...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9761] = {title = "Расчистка пути", objective = "Убейте 8 саботажников и 8 посланников из клана Солнечных Ястребов и сообщите об этом воздаятельнице Корин в Привале Защитника.", description = "Только тот, кто закален в боях, только самый благородный и бесстрашный из дренеев сможет исполнить волю Легосо! Экзарх не станет поручать разрушение Энергоблока и уничтожение Сиронас простому агенту Руки. Он никого не желает посылать на верную смерть – а это значит, что новое задание, по сути, почти невыполнимо...\n\n*Корин вздыхает.*\n\nВпрочем, мое дело – всего лишь ослабить оборону Солнечных Ястребов. Тебе нужно убить тех из них, кто охраняет Энергоблок, и расчистить путь для того, кому суждено стать героем... или получить это звание посмертно.", progress = nil, completion = "Надеюсь, герой объявится раньше, чем Ястребы вызовут подкрепление, – а иначе и путь ему расчищать не имело смысла...", rewards = "Шелковые волнующиеся повязкиПерчатки из шкуры опустошителяБоевые рукавицы КоринаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9762] = {title = "Неписаное пророчество", objective = "Эти острова станут домом для тысяч и тысяч; многие останутся здесь на всю жизнь. Если таково твое желание, можешь присоединиться к ним - но ты ведь вовсе не этого хочешь, Эксордим?\n\n*Велен кивает.*\n\nДа, ты многое свершишь, прежде чем покинешь этот мир. Не страшись своей судьбы, шагни ей навстречу!\n\nНа прощание прими от меня два дара: гербовую накидку и перстень. Такие накидки носят только достойнейшие из братства Длани Аргуса, а права носить эти перстни-печатки удостаиваются лишь величайшие мудрецы. Ты достоин этих даров - носи их с гордостью.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерстень-печатка ДланиПерстень-печатка Длани\n\nВы также получите:\n\nГербовая накидка Длани"}
MultiLanguageQuestData['ru'][9763] = {title = "Убежище врага", objective = "Дозорный Джанг хочет, чтобы вы нашли и убили полководца Калитреша в резервуаре Кривого Клыка.", description = "Врага иногда можно уничтожить, тайком подобравшись к самому его логову.\n\nНесколько часов назад я видела, как отряд наг прошел через каменную арку во второй туннель слева. Я почти не понимаю их языка, однако одно слово сумела разобрать: Калитреш.\n\nДолжно быть, это вход в паровые подземелья, откуда полководец Калитреш осуществляет командование войсками. Найди и убей его! Я слишком слаба, чтобы помочь тебе.", progress = "Ты убил Калитреша, Ксаер?", completion = "Наконец-то самый жестокий враг наших земель мертв. Благодарю тебя за помощь, Душавдушу. Экспедиция навечно у тебя в долгу.", rewards = "Головной убор мирмидонаКапюшон хранителя землиШлем когтяТюрбан гидромантаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9764] = {title = "Приказы Леди Вайш", objective = "Отнесите приказы леди Вайш Исиэль Песни Ветра в Кенарийский приют в Зангартопи.", description = "Письмо содержит подробные указания нагам из клана Кривого Клыка, работающим в паровых подземельях. В письме сообщается о прибытии кенарийских друидов в регион и содержиться приказ уничтожать их на месте. Количество воды, перенаправляемой в резервуар Кривого Клыка из окрестных озер, велено удвоить. Приказ скреплен печатью леди Вайш.\n\nПисьмо явно будет интересно друидам из Кенарийской экспедиции. Отнесите его их предводительнице, Исиэль Песни Ветра.", progress = "Что там у тебя, Менгиле!", completion = "Вайш! \n\nВсе куда хуже, чем я думала. Все наши маленькие победы здесь - ничто по сравнению с величием врага. \n\nЕсли с этим связана госпожа Вайш, это значит, что в дело втянуты такие серьезные силы, с которыми наша экспедиция едва ли сможет тягаться. \n\nСпасибо тебе, Менгиле. Полагаю, мы должны готовиться к войне.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9765] = {title = "Готовится к войне", objective = "Добудьте оружие клана Кривого Клыка у наг в резервуаре Кривого Клыка и принесите его Исиэль Песни Ветра в Кенарийский приют в Зангартопи.", description = "Кенарийская экспедиция была начата как вполне мирное мероприятие. однако теперь мы, видимо, стоим на пороге войны с нагами.\n\nМногие из нас не против вступить в бой с врагов, но мы слишком плохо вооружены. Принеси мне оружие наг, и мы перекуем его на глефы и наконечники стрел.\n\nИмей в виду, нам подойдет только самое лучшее оружие, <имя>. Ищи наг в резервуаре Кривого Клыка.", progress = "Удалось добыть оружие, Джонниди?", completion = "О, это прекрасное оружие, Джонниди! Если удастся достать еще, непременно приноси. Мы так плохо вооружены!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9766] = {title = "Оружие Кривого Клыка", objective = "Мы выкуем из стали наг оружие, и обратим его против них! Принеси мне все оружие, которое сможешь унести из резервуара Кривого Клыка.", description = nil, progress = "Мы выкуем из стали наг оружие, и обратим его против них! Принеси мне все оружие, которое сможешь унести из резервуара Кривого Клыка.", completion = "Отлично, Oldlikeworld! Теперь-то наги поймут, что нас нельзя недооценивать.", rewards = nil}
MultiLanguageQuestData['ru'][9767] = {title = "Врага нужно знать в лицо", objective = "Добудьте книгу заклинаний клана Кривого Клыка у наг из резервуара Кривого Клыка и принесите ее Ашьену в Кенарийский приют в Зангартопи.", description = "Для того чтобы разбить врага, не всегда достаточно превосходить его силой или численностью. Часто победа основана на знании слабых мест противника, предугадывании их стратегии или тактики.\n\nМы знаем о нагах много, и все же их магия остается для нас загадкой.\n\nЯ хочу изучить магию наг резервуара Кривого Клыка. Принеси мне одну из их книг заклинаний!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9769] = {title = "Мода непредсказуема!", objective = "Принесите 8 прозрачных крыльев любых видов светлячков, обитающих в Зангартопи, Магаше с заставы Болотной Крысы.", description = "<Магаша беззвучно хихикает.>\n\nБьюсь об заклад: если бы они знали, что одеваются в мушиные крылья, эта ихняя мода быстро бы прошла!\n\nПоначалу мы истребляли насекомых просто так, чтобы не путались под руками. А тут заехал к нам какой-то ушлый торговец, покрутился – и скупил все крылья разом!\n\nГоворит, будет из них одежду шить. Ну, я-то свои доспехи ни на что не променяю... Но, если ты добудешь крылья каких-нибудь светлячков, я их с удовольствием куплю!", progress = "Ну, и чего ты тут? Какая муха тебя укусила?\n\n<Магаша хихикает над собственной шуткой.>", completion = "О, отличные крылья, Щук! Вот твоя плата.\n\n*Магаша выгибает одно из крыльев и прикладывает его к голове.*\n\nНе, не для меня это. Ну, оно и к лучшему!\n\n*Магаша пожимает плечами.*\n\nГлавное, чтоб платили!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9770] = {title = "Опасные болотные клыки", objective = "Убейте 10 болотных потрошителей по просьбе Реавижа с заставы Болотной Крысы.", description = "Иногда я жалею, что Денжай не отправил с нами шамана, или не дал нам с собой хотя бы тотема, который мог бы отпугивать болотных потрошителей.\n\nЭта местность буквально кишит ими! Просто кошмар какой-то. Такое впечатление, что у них вообще нет естественных врагов.\n\nМы все по очереди занимаемся тем, что истребляем этих тварей. Ты <пришел/пришла> как раз вовремя, <имя>. Поздравляю! Теперь засучи рукава и перебей побольше этих тварей!", progress = nil, completion = "Ну что, хватило с тебя?\n\n&lt;Реавиж смеется.&gt;\n\nВот потому-то гости у нас надолго и не задерживаются!\n\nЯ бы и сам предпочел выбрать для своей заставы местечко поприятнее, но лучше уж болотные клыки, чем гнев Денжая!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9771] = {title = "Поиски разведчика Джиобы", objective = "Найдите разведчика Джиобу в Мертвой трясине, что в Зангартопи.", description = "Теперь, когда здешние места тебе более или менее знакомы, я хотел бы попросить твоей помощи в еще одном деле. Мертвая трясина – так мы зовем топи к северо-западу отсюда, – место гиблое. Никто никогда не видел там ни единой живой души – но, с другой стороны, никто там подолгу и не задерживался.\n\nИ вот наш разведчик, Джиоба, вызвался исследовать эту местность и доложить о том, что ему удалось обнаружить. Он ушел с заставы три дня тому назад и до сих пор не вернулся. А между тем Джиоба не из тех, кто уходит надолго и не подает о себе вестей. Попытайся его найти, <имя>!", progress = nil, completion = "Да, труп действительно полностью соответствует описанию. Существо, убившее Джиобу, очевидно, застигло его врасплох, потому что оружие разведчика осталось в ножнах, а по земле разлито содержимое маленькой походной чернильницы...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9772] = {title = "Донесение разведчика Джиобы", objective = "Добудьте донесение разведчика Джиобы у высохших великанов и вернитесь с ним к Зураю на заставу Болотной Крысы.", description = "Тело разведчика Джиобы усеяно кусочками засохших грибов. Кто бы его ни убил, он явно принадлежал к той же породе гигантских вянущих грибов Мертвой трясины. Возможно, один из этих высохших великанов застал разведчика врасплох, когда тот писал свое донесение...\n\nНо не имея текста донесения, невозможно узнать, что же сумел обнаружить разведчик. Если донесение удастся найти, его необходимо доставить Зураю.", progress = "Ты вернулся, но без Джиобы. Что же с ним стало?", completion = "&lt;Зурай берет у вас донесение и пробегает его взглядом.&gt;\n\nБольшая часть этих сведений нам уже известна... Действительно, такое впечатление, что все в тех местах вянет и сохнет. Но есть и нечто новое.\n\nОн говорит, что грибные великаны, похоже, бесятся от недостатка влаги. Судя по твоему описанию, они-то его и убили...\n\nЯ прикажу своим подчиненным избегать тех мест. Мы не можем позволить себе новых потерь.", rewards = "Поручи болотоходцаМрачные наручиПояс болотоходцаПлащ топейВы получите:\n\n"}
MultiLanguageQuestData['ru'][9773] = {title = "Довольно грибов!", objective = "Добудьте 8 филе угря с угрей из озера Тенетопь и принесите их Магаше на заставу Болотной Крысы.", description = "Грибной суп, жаркое из грибов, грибной соус...\n\nГрибы, грибы, грибы! Кроме грибов, есть тут вообще нечего! Если ты говоришь, что хочешь есть, повар вручает тебе топор и велит нарубить себе грибов на ужин!\n\nТак вот, меня это достало. Я знаю: тут, в озерах, водится рыба! Конечно, она мерзкая на вид, но все лучше, чем эти грибы!\n\nСколько ты потребуешь с меня за то, чтобы я впервые за несколько недель могла нормально поесть?", progress = "Ну скажи, Щук, ты ведь не с пустыми руками, правда?", completion = "О, наконец-то хоть какое-то разнообразие! Я бы тебя расцеловала, если бы от тебя не так сильно воняло рыбой…\n\nВот увидишь, как будут мне завидовать остальные, когда почуют запах нормальной еды!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9774] = {title = "Толстая чешуя гидры", objective = "Принесите Зураю на заставу Болотной Крысы 12 толстых чешуек гидры.", description = "Реавиж правильно сделал, что привез сюда кожаные доспехи. Мой доспех от здешней сырости ржавеет на глазах. Я мало-помалу заменяю проржавевшие чешуйки. У местных гидр – отличная, прочная чешуя, и болотная сырость им нипочем.\n\nНо отыскать подходящие чешуйки не так-то просто! Самые лучшие иногда оказываются обломанными или слишком истертыми. Так что принеси мне побольше хорошей чешуи, какую сумеешь добыть у гидр, водящихся в больших озерах.", progress = "Чего ухмыляешься? Да, я знаю, мой доспех будет выглядеть странновато до тех пор, пока я не заменю все металлические чешуйки на новые, но лучше уж такой доспех, чем вовсе никакого!", completion = "Спасибо, Джонниди! Мне дорога каждая лишняя чешуйка.\n\nКонечно, возни с этим много, но посмотрим правде в глаза: чем еще тут можно заняться в перерыве между дежурствами?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9775] = {title = "Донесение темному охотнику Денжаю", objective = "Отнесите донесение Зурая темному охотнику Дэнжаю в Забра'джин, что в Зангартопи.", description = "Темный охотник Денжай, несомненно, рассчитывает получить донесение о моих успехах в обустройстве нашего форта. Я приготовил краткий отчет о том, что уже сделано здесь, но теперь, после гибели разведчика Джиобы, мне некого послать гонцом на базу Денжая, в Забра'джин на западе.\n\nЕсли тебе все равно нужно в ту сторону, может быть, занесешь ему мой доклад? Поначалу Денжай может показаться жутковатым, но, когда к нему привыкнешь, он, в сущности, неплохой малый.", progress = "Ты не похож на одного из моих подчиненных. Говори, с чем явился, |3-6(нежить)!", completion = "У тебя донесение от Зурая? Так что ж ты сразу не сказал! Я давно жду от него вестей!\n\nЯ отправил его туда, чтобы закрепить наше присутствие на восточной границе, а не затем, чтобы он сидел сложа руки! Ну, посмотрим, что он имеет сказать...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9776] = {title = "Прибежище Оребор", objective = "Поговорите с Икути в Прибежище Оребор, что в Зангартопи.", description = "Как тебе известно, среди обитателей Телредора немало беженцев той войны, в результате которой число дренеев уменьшилось вдесятеро. И моя цель – сделать Телредор безопасной гаванью для всех наших союзников в этой борьбе. Есть и такие, кто хотел бы присоединиться к нам, но пока не готов к этому.\n\nМы должны помогать им, чем можем, <имя>! Группа Сломленных под предводительством Икути укрылась в развалинах старого храма к северо-западу от Змеиного озера. Отыщи их и протяни им руку помощи!", progress = nil, completion = "Если анахорет Ахуурн считает тебя другом, возможно, ты и впрямь достоин доверия. Пожалуйста, |3-6(ночной эльф), прости мне мою недоверчивость: зачастую она бывает единственным, что спасает меня и моих товарищей от гибели. Ты можешь найти приют среди нас, и, быть может, наше взаимное доверие со временем укрепится.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9777] = {title = "Споры гриба-блескуна", objective = "Принесите 6 спор гриба-блескуна Руаму в Телредоре.", description = "Видишь ли, <раса>, у нас на болотах гореть особо нечему, поэтому приходится искать другие способы освещения. Многие из болотных животных и растений испускают слабое свечение.\n\nДержать в клетках светящихся животных сложно, да и жестоко, поэтому мы используем для освещения грибы.\n\nМы собираем и выращиваем грибы-блескуны прямо здесь, однако периодически все же приходится пополнять запасы. Эти маленькие зеленые грибочки часто растут у подножия больших грибов в окрестностях Телредора.", progress = "Судя по всему, скоро нам понадобятся новые грибы-блескуны...", completion = "Отличные споры! Их нам хватит надолго. Спасибо за помощь, Ишт!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9778] = {title = "Страж Хамут", objective = "Поговорите со стражем Хамутом в Кенарийском приюте в Зангартопи.", description = "Прежде чем покинуть Кенарийский приют, поговори-ка со стражем Хамутом. Он отвечает за безопасность экспедиции.\n\nЕсли я не отправлю к нему <такого опытного искателя приключений/такую опытную искательницу приключений>, как ты, он мне этого никогда не простит!", progress = nil, completion = "Ты от Исиэли? Ну да, разумеется, такой, как ты, мне всегда пригодится! Опытные, стойкие бойцы нам никогда не помешают.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9779] = {title = "Перехват сообщения", objective = "Найдите послание Солнечных Ястребов. Возможно, для этого придется убить нескольких из них. Послание должно быть доставлено на Кровавую заставу воздаятелю Боросу.", description = "Рад видеть тебя снова, <имя>. У меня тут возникла проблема - и, возможно, ты поможешь мне решить ее.\n\nНаши лазутчики в тылу врага доложили, что видели у Солнечных Ястребов какой-то странный документ.\n\nК сожалению, нам не удалось снять копию этого документа. А потому нужно, чтобы ты <отправился/отправилась> к этим Ястребам и <попытался/попыталась> его раздобыть. Уверен: применив соответствующие методы, ты добьешься успеха. Как понимаешь, в средствах я тебя не ограничиваю...", progress = "Что, уже вернулся? Быстро! А где же послание?", completion = "&lt;Воздаятель Борос разглядывает документ.&gt;\n\nНаписано на талассийском... По счастью, я знаю, кто это сможет перевести...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9780] = {title = "Филе угрей из озера Тенетопь", objective = "Принесите Нораани из Телредора 8 филе угря.", description = "Приятно видеть здесь новое лицо! Когда мы с Хаалруном впервые прибыли в Телредор, мы здесь были единственными чужаками, но с тех пор много воды утекло...\n\nТем не менее мы стараемся радушно принимать новоприбывших и заботимся о том, чтобы в городе не было недостатка в еде и припасах. Перед анахоретами Телредора мы в неоплатном долгу, однако мы стремимся не уступать им в великодушии и принимаем новичков так, как когда-то приняли нас.\n\nЕсли ты не против нам помочь, то в соседних озерах водится рыба, которая называется угорь из озера Тенетопь. Ею мы в основном и питаемся.", progress = "Ну что, пополнишь ли ты наши запасы рыбы?", completion = "Спасибо за помощь, Главтруп! Твоя щедрость не будет забыта.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9781] = {title = "Слишком много ртов!", objective = "Убейте 10 болотных гидр и вернитесь к Хаалруну в Телредор.", description = "Когда я в последний раз ходил на охоту, мне попалась на глаза новая застава, которую строит группа троллей. Они тоже наверняка собираются охотиться в здешних местах!\n\nЕсли они вздумали поселиться здесь навсегда, конкуренция за добычу будет жестокая. На троллей мы напасть не можем – это приведет к войне. Но мы можем хотя бы убавить количество хищников, которые тоже конкурируют с нами.\n\nКаждая убитая тобой болотная гидра – это на три голодных рта меньше!", progress = nil, completion = "Молодец! На ближайшее будущее этого должно быть достаточно, чтобы уменьшить конкуренцию. Но, конечно, со временем придется искать новые источники пищи. На одной рыбе и грибах прожить можно, но разнообразие не помешает...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9782] = {title = "Мертвая трясина", objective = "Принесите пробу почвы Мертвой трясины воздаятелю Идаару в Телредоре.", description = "Я довольно долго прожил среди анахоретов Телредора, и за это время неплохо изучил болота. В последнее время я начал замечать, что земли на северо-востоке меняются, и не в лучшую сторону.\n\nПрактически вся местная флора и фауна начала вянуть, чахнуть и гибнуть, причем без всяких видимых причин. У меня есть несколько идей относительно того, что там происходит, но все это не выходит за рамки гипотезы. Если бы тебе удалось принести мне оттуда образец почвы, я бы, возможно, сумел постичь эту тайну...", progress = "Ну что, удалось тебе добыть образец почвы Мертвой трясины?", completion = "Почва, похоже, истощена. Но это еще ничего не объясняет. В чем же дело? Отчего же все внезапно принялось вымирать?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9783] = {title = "Неестественная засуха", objective = "Убейте 12 иссохших великанов по просьбе воздаятеля Идаара из Телредора.", description = "<имя>, принесенный тобой образец почвы практически лишен влаги! Если уж сама земля теряет влагу, значит, существа, обитающие в Мертвой трясине, жестоко страдают от засухи!\n\nЯ видел, что бывает, когда грибные великаны начинают вянуть и умирать от засухи. Они впадают в бешенство от мучений и нападают на всех, кого встретят на своем пути!\n\nЭти существа не понимают, что происходит. Спасти их мы не в силах - лучшее, что мы можем сделать, это прекратить их мучения.", progress = nil, completion = "Спасибо за помощь, Сотус. Это была трудная задача. Наша работа в Мертвой трясине далеко еще не завершена, но теперь мы можем сосредоточиться на восстановлении природного равновесия в этих землях.", rewards = "Кушак воздаятеляНаручи болотного долгоногаПоручи исследователяОплечье исследователяВы получите:\n\n"}
MultiLanguageQuestData['ru'][9784] = {title = "Определение растений", objective = "Новые части растений мне всегда пригодятся! Сейчас, когда уровень воды в озерах постоянно снижается, у меня возникает чувство, что на болотах растет число пришлых растений. Однако чтобы подтвердить эту теорию, мне нужны точные цифры!", description = nil, progress = "Новые части растений мне всегда пригодятся! Сейчас, когда уровень воды в озерах постоянно снижается, у меня возникает чувство, что на болотах растет число пришлых растений. Однако чтобы подтвердить эту теорию, мне нужны точные цифры!", completion = "Отлично. Если найдешь другие части растений, приноси их мне.\n\n&lt;Это задание можно повторять, пока не будет достигнуто уважительное отношение.&gt;", rewards = "Вы получите:\n\nУпаковка с опознанными растениями"}
MultiLanguageQuestData['ru'][9785] = {title = "Благословение Древ", objective = "Призывательница ветров Черное Копыто просит вас поговорить с древами Ашьеном и Келетом в Кенарийском приюте и получить их благословение.", description = "<имя>, тебе удалось заслужить доверие Кенарийской экспедиции! Пора тебе побеседовать с древними мудрецами, Ашьеном и Келетом, и попросить их благословения.\n\nЗнак древнего мудреца даст тебе великую силу. И по мере того, как наше уважение к тебе будет расти, его действие будет только усиливаться.\n\nСтупай, <имя>, попроси благословения у древних мудрецов!", progress = "Порвань, ты уже поговорил с древними мудрецами?", completion = "Ты вернулся! Удалось ли тебе получить благословение Древ?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9786] = {title = "Руины Боха'му", objective = "Исследуйте руины Боха'му по просьбе анахорета Ахуурна из Телредора.", description = "До того как орки истребили большую часть моего народа, Телредор служил убежищем дренейским анахоретам и спиритуалистам. Небольшой орден анахретов и воздаятелей имел множество святилищ в здешних краях.\n\nВо время войны мы потеряли связь с анахоретами из святилищ, в особенности из храма Боха'му на юго-западе. До меня доходили сведения, что в тех местах обосновалась группа Заблудших, и они, возможно, даже используют развалины храма. Побывай в руинах Боха'му и расскажи мне о том, что там найдешь.", progress = nil, completion = "Так значит, в руинах поселились Заблудшие Дикотопи? Как интересно... Должно быть, они помнят что-то из своего прошлого и сознают значимость этого места. Нужно узнать об этом побольше, Печенькус! Возможно, в этом храме таится ключ к тому, чтобы вернуть Заблудших и восстановить былое величие дренеев.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9787] = {title = "Идолы Дикотопи", objective = "Соберите 6 идолов Дикотопи и вернитесь с ними к анахорету Ахуурну в Телредор.", description = "Судя по твоим рассказам о том, что происходит в руинах Боха'му, это племя Заблудших поклоняется духам животных. Но прежде, чем познакомиться с ними поближе, нам следует больше узнать об их верованиях!\n\nВозвращайся в деревню Дикотопь и добудь втайне несколько их идолов, чтобы я мог их изучить. Только постарайся не рассердить самих Заблудших – это может помешать нам установить с ними контакт...", progress = "Ну что, идолы у тебя?", completion = "Да, Нехел, этого будет более чем достаточно. Они, кажется, помешаны на птицах - это странно: ведь в Зангартопи изначально никаких птиц не водилось. Что бы это могло значить?\n\nБыть может, они встречались с араккоа? Народу шаманов араккоа могли показаться воплощением могущественного духа...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9788] = {title = "Темное, сырое место", objective = "Отыщите вещи Икейена в пещере к югу от Тенетопи. Верните их Икейену в Кенарийском приюте в Зангартопи.", description = "Вскоре после того, как мне удалось бежать от племени Тенетопи, я укрылся в пещере к югу от их деревни. Я ведь не знал, что за эту пещеру сражаются между собой болотные твари и гриболюди!\n\nМне пришлось в спешке бежать оттуда, и я оставил там сундучок со всем, что у меня было.\n\nКакая насмешка судьбы: спасти свое имущество из деревни Тенетопь, чтобы почти сразу его потерять! Если ты согласишься принести мне мой сундучок, я подарю тебе какую-нибудь ценную вещь. Что скажешь, <имя>?", progress = "Тебе удалось отыскать мои вещи, Выручалкин? Эта пещера недалеко от Тенетопи, на границе с Награндом...", completion = "Мои вещи! Все здесь, ничего не пропало!\n\nСпасибо тебе, Выручалкин! Теперь я, как и обещал, разрешу тебе выбрать одну из моих вещей. Их у меня осталось немного, но мой народ всегда делился тем немногим, что имеет!", rewards = "Наплечье ИкейнаГрязные сапогиСапоги ИкейнаЗащитная броняВы получите:\n\n"}
MultiLanguageQuestData['ru'][9789] = {title = "Охота на копытней", objective = "Убейте 12 копытней и вернитесь к Хемингу Эрнестуэю в его охотничий лагерь в Награнде.", description = "Хочешь стать $Gохотником:охотницей;? Сначала докажи, что ты этого <достоин/достойна>.\n\nМеня не волнует, сколько у тебя трофеев и как они были добыты. Если ты ни разу не <был/была> с нами на охоте – считай, ты вообще ничего в этом не смыслишь. Начни с копытней, если <ты настоящий мужчина/тебе хватит смелости>.\n\nКак раз недавно я видел поблизости стадо копытней. Еще они водятся на юге.", progress = nil, completion = "Для начала неплохо. Но лишь для начала.\n\nМелкие копытни – это несерьезно. Надо поручить тебе более сложное задание!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9790] = {title = "Прозрачные крылья", objective = "Принесите Хаалруну из Телредора 8 прозрачных крыльев любых видов светляков, обитающих в Зангартопи.", description = "Живя в такой отдаленной и дикой местности, мы научились пользоваться всем, что есть под рукой. Разумеется, поначалу мы старались не думать, из чего это все сделано...\n\nЯ обнаружил, что крылья бледносветных острожалов – отличный водооталкивающий материал. Они прочные, легкие и эластичные.\n\n<Хаалрун хмыкает.>\n\nДа-да, вижу, тебе эта идея не по вкусу! Что поделаешь, надо просто привыкнуть. Так вот, если уж ты все равно будешь шляться по болотам, не принесешь ли мне таких крыльев, если они тебе попадутся?", progress = "Ну что, удалось тебе раздобыть прозрачные крылья?", completion = "Спасибо тебе, Вэлс!\n\n*Хаалрун сочувственно улыбается.*\n\nНу, порадуйся хотя бы тому, что тебе не придется их отчищать! Это самая противная часть работы. Однако если их как следует отскоблить, ни за что не скажешь, что это крылья гигантского насекомого.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9791] = {title = "Опасные болотные клыки", objective = "Убейте 10 болотных потрошителей и вернитесь к Нораани в Телредор.", description = "Пока орки вели войну против моего народа, собиратели редко выбирались за пределы Телредора, поскольку боялись нападения или плена. Теперь мы чаще выходим за стены, но болота не стали менее опасными!\n\nТакое впечатление, что за последние несколько месяцев скаты Пустоты совершенно обнаглели. Не знаю, в чем дело, может быть, им сделалось труднее охотиться на их обычную добычу, но сейчас они то и дело нападают на наших собирателей. Если бы нам удалось уменьшить их численность в окрестностях Телредора, возможно, они оставили бы нас в покое...", progress = nil, completion = "Спасибо тебе за помощь, Сотус! Если бы болотные потрошители были хотя бы отчасти разумны, быть может, это научило бы их не связываться с нами...\n\n*Нораани пожимает плечами.*\n\nЖуки-переростки, наделенные разумом... Интересно, как бы это выглядело?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9792] = {title = "Послание в Телаар", objective = "Поговорите со стражем-смотрителем Мой'прной Джиллой в Телааре в Награнде.", description = "В нынешние времена завоевать доверие моего народа непросто, но ты, <имя>, неизменно <поступал/поступала> с нами честно и благородно.\n\nВ древнем дренейском городе Телаар в Награнде, к югу отсюда, обитает большая группа моих собратьев. Чтобы попасть в Телаар, ступай по дороге, ведущей на юг, в Награнд, а там поверни на юго-восток и иди, пока не очутишься на утесах к востоку от Ошу'гуна.\n\nВ Телааре рады будут любому, кто помогал нам так, как ты.\n\nОтыщи там стража-смотрителя Мой'прна Джилла и скажи ему, что я тебе доверяю.", progress = nil, completion = "Икути мне как брат! Его друзья - мои друзья! Добро пожаловать в Телаар, Мияру. Мы благодарны тебе за помощь нашему народу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9793] = {title = "Судьба Туурема", objective = "Отнесите письмо воздаятеля Идаара Андарлу в бастион Аллерии в лесу Тероккар.", description = "Поиски союзников, которые вел пророк Велен, ободрили дренеев, оставшихся в Запределье, и заставили их тоже приняться за поиски. Нападение Легиона заставило наш народ покинуть свои города и храмы, однако же наша цивилизация не была разрушена полностью.\n\nТуурем, мой родной город, находящийся в лесу Тероккар, был захвачен орками одним из первых. Я уже давно не получал известий о том, что там происходит. Отнеси это письмо в бастион Аллерии в лесу Тероккар и отдай его Андарлу.", progress = "Чем могу помочь?", completion = "Хм... Да, я помню, как наши разведчики упоминали о руинах дренейского поселения в северной части леса. Самому мне об этих развалинах мало что известно, но ты, если хочешь, можешь поговорить с разведчиками.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9794] = {title = "Не время для любопытства", objective = "Доставьте письмо Тимоти Киалону в Сильванаар в Острогорье.", description = "<имя>, я вынужден просить тебя об услуге. В другое время я сделал бы это сам, но у меня и без того дел невпроворот.\n\nУ меня есть соратник, по имени Киалон. Он живет в Сильванааре, что в Острогорье к северу отсюда. Он ждет от меня письма, хотя, подозреваю, ему не понравится то, что он прочтет.\n\nЕсли ты доставишь ему мой ответ, я буду тебе очень признателен. Только смотри, не вздумай читать это письмо! Оно предназначено только Киалону, и никому другому.", progress = "<Киалон смотрит на вас с подозрением.>\n\nЯ тебя не знаю, |3-6(человек). У тебя ко мне дело?", completion = "А, так ты принес ответ Тимоти?\n\n&lt;Киалон пробегает глазами письмо, потом разражается хохотом.&gt;\n\nНу конечно же, у него все под контролем, и помощь ему не нужна! Я так и знал!\n\nНекоторые все-таки никогда не меняются. Ты погляди, у него даже нашлось время указать мне на ошибки в правописании!\n\n&lt;Киалон вздыхает.&gt;\n\nНе стоило ему и писать. Я совсем забыл, что он за человек. Ну разумеется, у настоящего специалиста всегда все под контролем!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9795] = {title = "Угроза со стороны огров", objective = "Отправляйтесь в оплот Громоборцев в Острогорье и поговорите с Нехтаром.", description = "На болотах становится все больше огров. Как будто мало нам было наг и их союзников! Огры уже захватили большую территорию на северо-западе, и слишком близко подобрались к нашим землям.\n\nНа место каждого убитого нами огра тотчас встают несколько новых. Даже не знаю, долго ли мы продержимся, если им взбредет в голову напасть на Забра'джин! Ступай на север, в горы, в орочий оплот Громоборцев, и сообщи Нехтару о нашем положении. Мы были бы рады любой помощи!", progress = nil, completion = "Денжай просит о помощи? Нет, я, конечно, пошлю ему подкрепление, но у нас и тут бойцов негусто... И нас тоже донимают огры.\n\nЯ при первой же возможности сообщу ему все, что нам известно о местных племенах огров и об их тактике. Быть может, если Денжай продержится достаточно долго, мы сумеем ударить по этим гнусным тварям с двух сторон одновременно...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9796] = {title = "Новости из Зангартопи", objective = "Поговорите с Мокасой в форте Камнеломов в лесу Тероккар.", description = "Темный охотник Денжай – не единственный, кто ждет от меня вестей. Мокаса из форта Камнеломов в Тероккаре ждет не дождется известий о том, как идут наши дела, тем более, что большинство ее посланцев проходит через болота.\n\nОна просила меня прислать ей весточку, когда мы достроим заставу Болотной Крысы. Не согласишься ли ты доставить ей мое послание? Я буду тебе очень признателен. Мы тут работаем не покладая рук, но все равно дел по горло...\n\nЧтобы попасть в форт Камнеломов, ступай по дороге, что ведет из Зангартопи на юг, в лес Тероккар, за Туурем.", progress = nil, completion = "Да уж, давно пора ему достроить эту заставу! Слишком много наших гонцов погибло от рук разбойников из Альянса...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9797] = {title = "Подкрепление для Гарадара", objective = "Поговорите с капитаном Кроганом в Гарадаре в Награнде.", description = "<Посланник, все еще запыхавшийся, делает вам знак сесть.>\n\nБоюсь, им не выстоять, <раса>! Беги в Гарадар со всех ног.\n\n<Видя ваш недоумевающий взгляд, посланник поясняет.>\n\nГарадар – это поселение маг'харов, оно находится в Награнде, к югу отсюда. Ступай по дороге, ведущей с болот на юг, на первой развилке сверни на восток, и придешь в большое поселение на озере.\n\nОтыщи там нашего командира, капитана Крогана, и предложи ему помощь. Гарадар не должен пасть!", progress = nil, completion = "&lt;Кроган старается этого не показывать, но тем не менее на его лице отражается облегчение.&gt;\n\nТы как раз вовремя! Конечно, мы предпочли бы увидеть целую армию, но сейчас нам пригодится любой опытный |3-6(орк), способный носить оружие или применять заклинания. Народ Гарадара – не чужой Орде, и мы гордимся тем, что проливаем кровь, защищая их!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9798] = {title = "Планы эльфов крови", objective = "Отнесите планы эльфов крови воздаятелю Алдару на место крушения в долине Аммен.", description = "Кажется, дренеи должны узнать об этих планах. Отнесите их воздаятелю Алдару на место крушения.", progress = "Что там у тебя?", completion = "Ну-ка, дай я посмотрю на планы.\n\nНеужели эльфы крови выследили нас? Вот уж в ком зло пустило корни, так это в них. Их надо уничтожить!\n\n&lt;Воздаятель пытается сдержать волнение.&gt;\n\nПрошу прощения, это так неожиданно. На самом деле я очень благодарен тебе за эту находку.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][9799] = {title = "Сбор трав", objective = "Сорвите 3 оскверненных цветка и вернитесь к ученице Вишаэль на месте крушения в долине Аммен.", description = "На полях Аммен, что на западе отсюда, обитают здешние корнехлесты. Воды ближайшего к ним озера очень загрязнены, и ботаник Таэрикс беспокоится, что после их очистки популяция корнехлестов не восстановится.\n\nСходи на поля Аммен, сорви несколько оскверненных цветов. Я взгляну на них и подумаю, что можно сделать. Их легко отличить от других по необычным красным лепесткам.", progress = "Привет, |3-6(Шаман). Набрал цветов?", completion = "Неплохие образцы. Спасибо за помощь. Как только я найду время и проведу анализ этих растений, можно будет примерно понять, сколько усилий потребуется для восстановления полей.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9800] = {title = "Редкий деликатес", objective = "Принесите Повелителю стихий Ло'апу к Трону Стихий в Награнде 8 семян караколлы.", description = "Ты еще не $Gготов:готова; встретиться с беспокойными стихиями Награнда. Прежде чем браться за задания Служителей Земли, тебе нужно сначала помочь <самому/самой> себе.\n\nНа западе ты найдешь кучки помета, оставленные местными четвероногими. Надо просеять помет и выбрать оттуда семена награндской караколлы. Из них я смогу приготовить пилюлю, которая поможет тебе в бою с беспокойными силами природы.\n\nВозвращайся, когда наберешь две горсти семян. Горсти отмеряй по меркам огров.", progress = "<Ло'ап берет бобы в руки и неодобрительно качает головой.>\n\nЯ же сказал, по меркам огров...", completion = "Только, пожалуйста, не вздумай купаться в священных водах Трона.\n\n&lt;Ло'ап протягивает вам готовую пилюлю из семян караколлы.&gt;\n\nПоложи ее под язык и дождись, пока она полностью не растворится. После этого ты сможешь дышать под водой подобно рыбам.", rewards = "Вы получите:\n\nНаграндская вишня"}
MultiLanguageQuestData['ru'][9801] = {title = "Сбор реагентов", objective = "Принесите анахорету Ахууму в Телредоре 4 глаза спороската и 4 щупальца болотного долгонога.", description = "У меня такое ощущение, что эти Заблудшие не будут рады видеть дренея, а вот араккоа примут с распростертыми объятиями. Я могу создать зелье, которое позволит тебе ненадолго принять облик араккоа. Однако для этого требуется пара реагентов, которые нельзя хранить подолгу и необходимо использовать в течение нескольких часов после того, как они были добыты.\n\nТебе придется принести мне горсть глаз спороската и несколько щупалец болотного долгонога. Оба вида обитают поблизости от Телредора.", progress = "Ну что, реагенты при тебе?", completion = "Да, это отлично подойдет! Минутку, я сейчас приготовлю зелье...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9802] = {title = "Растения Зангартопи", objective = "Принесите 10 неопознанных частей растений Лоранне Тар'велл в Кенарийском приюте в Зангартопи.", description = "Озера Зангартопи мало-помалу пересыхают. Почему – мы точно не знаем, но известно, что многие виды растений уже находятся на грани вымирания.\n\nПоскольку я – каталогизатор экспедиции, в мои обязанности входит отслеживать и идентифицировать вымирающие растения, чтобы мы могли понять, что с ними происходит.\n\nЕсли вы хотели бы нам помочь, приносите мне неопознанные части растений. Их можно собирать самостоятельно, если вы <травник/травница>, а еще их иногда имеют при себе обитатели болот.", progress = "Ну что, Выручалкин, удалось вам найти какие-нибудь части растений?", completion = "Да, сокращение числа местных эндемиков не может не тревожить. А распространение видов, занесенных извне, может быть связано с недавними проблемами в экосистеме. У меня пока недостаточно информации, чтобы сделать окончательные выводы...\n\n&lt;Лоранна перебирает растения и делает какие-то пометки в своем дневнике.&gt;\n\nВозьми вот это, Выручалкин. Возможно, они тебе пригодятся.\n\nПриноси мне и другие части растений, которые тебе встретятся.", rewards = "Вы получите:\n\nУпаковка с опознанными растениями"}
MultiLanguageQuestData['ru'][9803] = {title = "Посланец в Дикотопь", objective = "Отправляйтесь в руины Боха'му и выпейте эликсир Ахуурна. Приняв обличье араккоа, поговорите со старейшиной Курути.", description = "Пришло время встретиться с племенем Дикотопи и внушить им, что Свет не отрекся от них. Возьми с собой приготовленное мною зелье и отправляйся в руины Боха'му.\n\nПридя в руины, выпей зелье. Оно придаст тебе облик одного из их птичьих духов. Поговори со старейшиной Курути и дай ему знать, что дренеи готовы принять его народ, как своих давно потерянных собратьев.", progress = "Ты поговорил со старейшиной Дикотопи?", completion = "Они отказались? Разумеется, они вправе сами выбирать свой путь, и все же их выбор меня изумляет. Мне казалось, что все дренеи, будь то Сломленные или Заблудшие, должны в глубине души помнить, что все мы когда-то были единым народом…\n\nПолагаю, он прав, и глупо было пытаться их обмануть, но неужели он не понимает, что мы сделали это с наилучшими намерениями?", rewards = "Повязки мистика ДикотопиХауберк повелителя зверей ДикотопиСапоги защитника ДикотопиПояс таящегося ДикотопиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9804] = {title = "Беспокойные духи озера Небесной Песни", objective = "Уничтожьте 8 озерных духов по просьбе Повелителя стихий Ло'апа, обитающего у Трона Стихий.", description = "Нарушение цикла приливов и отливов награндских вод взбудоражило водных духов озера Небесной Песни. И они, в свою очередь, тоже стали нести разрушение по водным путям.\n\nВатуусан Водный явился нам в видении и дал разрешение устранить эту проблему – при условии, что мы разберемся и с изначальным источником беспокойства...\n\nНо всему свое время. Сначала нам следует устранить опасность, непосредственно угрожающую Трону. Уничтожь взбешенных озерных духов и возвращайся ко мне.", progress = nil, completion = "&lt;Повелитель стихий Ло'ап встает на колени в воде и читает молитву.&gt;\n\nСлужители Земли скорбят о содеянном. Но мы делаем все, что в наших силах, чтобы исцелить раны земли.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9805] = {title = "Благословение Возжигателя", objective = "Спалите самый большой дом и три лачуги на западной, восточной и южной окраинах деревни Трепещущего Тростника.\n\nКогда выполните поручение, верните живой огонь повелителю стихий Ло'апу.", description = "Презренные Заблудшие до сих пор не высовывались из Зангартопи, но теперь они собираются разнести свою скверну по всему нашему миру.\n\nЯ попросил совета у сил природы и получил их благословение. Чтобы остановить нашествие, мы должны натравить на Заблудших стихии!\n\nЯ одолжу тебе живой огонь, взятый от пылающей сущности самого Возжигателя. Отправляйся на юго-восток, в деревню Трепещущего Тростника, и запусти им живой огонь под крыши! Пусть мерзавцы познают ярость стихий!", progress = "С великим стыдом я признаюсь, что это мой собственный народ пытается запрудить реки Награнда и превратить добрые земли в болото.", completion = "Твои усилия приостановили распространение скверны, но теперь возникли иные трудности.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][9806] = {title = "Прорастающие споры", objective = "Соберите 6 прорастающих спор с различных спороскатов и болотобродов. Выполнив задачу, вернитесь к Гшаффу в Спореггар.", description = "Спороскаты и болотоброды бродят среди высоких грибочков и собирают прорастающие споры своими конечностями.\n\nМы, как видишь, народец низкорослый, и сами добывать эти споры можем с большим трудом. Ищи спороскатов и болотобродов, и собирай прорастающие споры. Весь Спореггар будет тебе крайне признателен.", progress = "Ты снова здесь, Выручалкин! Удалось ли тебе раздобыть прорастающие споры?", completion = "Отличные споры, Выручалкин! Высокие грибочки необходимы нам для того, чтобы отстроить наш город. А после всех нападений болотников, которые мы пережили, их у нас осталось совсем мало...", rewards = "Вы получите:\n\nОгнешляпка"}
MultiLanguageQuestData['ru'][9807] = {title = "Новые прорастающие споры", objective = "Лишние прорастающие споры нам всегда пригодятся, |3-6(нежить)! Хвастливые грибочки чрезвычайно полезны. Если мы сможем их выращивать, это значительно расширит наши возможности.", description = nil, progress = "Лишние прорастающие споры нам всегда пригодятся, |3-6(нежить)! Хвастливые грибочки чрезвычайно полезны. Если мы сможем их выращивать, это значительно расширит наши возможности.", completion = "Мы ценим твою помощь, Комувломить. Ждем новых спор!", rewards = "Вы получите:\n\nОгнешляпка"}
MultiLanguageQuestData['ru'][9808] = {title = "Грибы-огнешляпки", objective = "Принесите 10 огнешляпок Мссхи'фну в Спореггар в Зангартопи.", description = "Я видел, как твои сородичи обменивают нужные им вещи на блестящие металлические кругляшки. Мы от вас не так сильно отличаемся. У нас тоже есть свои деньги: блестящие кругленькие грибочки.\n\nГрибы-огнешляпки растут на болотах повсюду, нужно только уметь добыть их из земли, не повредив. Я тебя этому научу, если только обещаешь принести несколько штук нам, в нашу казну. Ну что, идет?", progress = "Ну что, Выручалкин, удалось тебе добыть грибы-пламеневики? Они тут повсюду, буквально прямо под ногами!\n\nИх яркое сияние видно издалека, если внимательно приглядеться.", completion = "Это поможет нам приобретать еду и припасы у других спорлингов! Спореггар благодарит тебя, Выручалкин!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9809] = {title = "Нужно больше грибов!", objective = "Если у тебя есть еще огнешляпки, я бы взял. Нашей деревне они всегда пригодятся.", description = nil, progress = "Если у тебя есть еще огнешляпки, я бы взял. Нашей деревне они всегда пригодятся.", completion = "Спасибо тебе, Мерандир! Я, как старейшина Спореггара, должен заботиться о том, чтобы у моего народа всего было в достатке. И ты сильно облегчаешь мою задачу!", rewards = nil}
MultiLanguageQuestData['ru'][9810] = {title = "Оскверненный дух", objective = "Уничтожьте загрязненную сущность Ватуусана и 8 озерных волноплесков по просьбе Повелителя cтихий Ло'апа.", description = "Ватусану удалось остановить распространение скверны, но при этом он нечаянно создал искаженного духа. И этот дух вобрал в себя всю скверну и порчу!\n\nТебе нужно найти этого искаженного духа болот. Он укрылся в глубинах озера Солнечного Источника к юго-западу отсюда.\n\nРазыщи и уничтожь искаженного духа Ватусана, а также все его порождения, также тронутые скверной.", progress = nil, completion = "Стихии воспели твою победу в ту же секунду, когда ты уничтожил искаженного духа! Служители Земли благодарны тебе, Душавдушу. Ты можешь выбрать любую награду.", rewards = "Огромный огрский хауберкТрофейное анго'рошское наплечьеКапюшон пожирателя душ из клана Анго'рошВы получите:\n\n"}
MultiLanguageQuestData['ru'][9811] = {title = "Друг син'дорай", objective = "Принесите голову Дар'Хана Лор'темару Терону в Луносвет.", description = "<имя>, начинается новая глава в истории эльфов крови. Укрепление отношений между нашими расами - во многом твоя заслуга, <раса>.\n\nОтнеси голову предателя лорду-регенту Лор'темару Терону в Луносвет и расскажи о том, что произошло.", progress = "Ты хочешь поговорить со мной, |3-6(Маг)? Не припомню, чтобы назначал тебе встречу.", completion = "Так значит, ты убил Дар'Хана, |3-6(нежить)? Прекрасно, прекрасно. Думаю, это станет началом крепкой дружбы между нашими народами.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9812] = {title = "Посол к Орде", objective = "Отнесите письмо от Лор'темара Терона леди Сильване Ветрокрылой в Подгород, столицу Отрекшихся в Тирисфальских лесах.", description = "Наши потенциальные союзники сомневались в наших способностях. Какая им от нас польза, если мы собственные проблемы решить не можем?\n\nТеперь все изменилось. В нашей силе никто не усомнится. Мы сможем вступить в Орду как равные.\n\nОтнеси это письмо Сильване, правительнице Отрекшихся. Она и так на нашей стороне, но весть о смерти Дар'Хана будет воистину музыкой для ее ушей. Готовься к долгому пути, <имя>. Если все сложится благополучно, Сильвана пошлет тебя в Оргриммар.", progress = "Мне сказали, что прибыл гость из Кель'Таласа, и я, честно говоря, ожидала увидеть эльфа крови.\n\nКакие вести ты принес?", completion = "Итак, свершилось. Подлый предатель получил по заслугам.\n\nТы оказал огромную услугу эльфам крови и Орде. Тралл отказывался принять в наши ряды эльфов, покуда был жив Дар'Хан. Ты же открыл дорогу обновленной Орде.\n\nЯ вижу, что вести Лортемара значительно улучшат его отношения с Траллом. Превосходно!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9813] = {title = "Встреча с вождем", objective = "Отнесите письмо с печатью Сильваны вождю в Оргриммар, столицу Дуротара.", description = "Я по-прежнему всей душой люблю свою родину и свой народ. Я билась зубами и когтями за то, чтобы Луносвету предоставили место за столом переговоров наравне с Подгородом и Оргриммаром.\n\nЭто должно заставить всех недовольных умолкнуть. Отнеси это письмо вождю в Оргриммар. Ему, как главе Орды, принадлежит последнее слово относительно того, будет ли удовлетворена просьба син'дорай.\n\nК этому письму приложена моя личная печать, как доказательство подлинности. Ступай на северо-запад города и у башни сядь на дирижабль до Дуротара.", progress = "Да, |3-6(Маг)?", completion = "&lt;Тралл открывает письмо и начинает читать.&gt;\n\nАга, значит, эльфы крови наконец разобрались со своей проблемкой... Неважно, что для этого потребовалась твоя помощь и целый отряд Отрекшихся.\n\n&lt;Тралл хохочет.&gt;\n\nНу, с этим уж ничего не поделаешь. В конце концов, они нам нужны не меньше, чем мы им.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9814] = {title = "Грибы-пороховики, слышь?", objective = "Принесите знахарю Тор'геш 6 грибов-пороховиков.", description = "Любишь грибочки, а? Тут, в Зангартопи, у самого Забра'джина, растут крутые грибочки!\n\nТолько смотри, держи ухо востро! Их не зря зовут пороховиками. Если подойдешь слишком близко, и не остережешься, они взрываются прямо тебе в лицо. Бабах – и ты с головы до ног в ядовитых спорах!\n\nЯ их использовал, чтобы толковать предсказания, но мои запасы почти закончились...", progress = "Ну че, где мои грибочки?", completion = "Во, отлично!\n\nСлышь, че я тебе скажу? За эти грибочки я тебе устрою потеху!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9815] = {title = "Грязные делишки", objective = "Принесите повелителю стихий Ло'апу к Трону стихий в Награнде 5 ядер порождений грязи.", description = "Духи воды, подвергшиеся наиболее пагубному воздействию, обитают в котловине Халаани к юго-западу отсюда, у заброшенного города Халаа. И хотя некоторые зараженные духи могут быть уничтожены без вреда для окружающей среды, останки порождений грязи тоже должны быть устранены.\n\nИначе эти ядра, остающиеся после уничтожения порождений, могут снова загрязнить окружающую среду.\n\nУничтожь порождения грязи и принеси мне их ядра.", progress = "Смотри, чтобы там не осталось ни единой крупинки грязи!", completion = "Служители Земли благодарят тебя, Душавдушу. Стихии также передают тебе благодарность. Мы отметили и оценили твои усилия по очищению этого мира.", rewards = "Мундир Ло'апа для ныряния в грязьОплечье Ло'апа для ныряния в грязьНавозные галошиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9816] = {title = "Видали вы такое?", objective = "Отнесите клетку с мурлоками в деревню Остротопь и оставьте ее на плоском камне.", description = "Все в этом болоте есть, одного не хватает: мурлоков!\n\nНо ты не дрейфь: я придумал, как это уладить. Вон, видишь Булька с Гурглом, какие они прикольные? Так вот, я собираюсь подарить Заблудшим таких же забавных мурлоков!\n\nВот, бери эту клетку, тащи ее к деревне Остротопь и выпусти этих малявок среди северо-восточного скопления хижин. Нет, Булька с Гурглом я с тобой не отпущу. Но эти разноцветные мелкие мурлоки ничем не хуже! Поставь клетку на большой плоский камень, который там увидишь, и открой дверцу!", progress = nil, completion = "Ай, молодца! Надеюсь, им там теперь не скучно!", rewards = "Прочные ботинки болотного долгоногаПовязки знахаряДоспех ОстротопиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9817] = {title = "Глава клана Кровавой Чешуи", objective = "Убейте раджис Фьяше в Змеином озере и вернитесь к стражу Хамуту в Кенарийский приют в Зангартопи, чтобы получить награду.", description = "Кенарийская экспедиция назначает награду за голову раджис Фьяше, предводительницы наг из клана Кровавой Чешуи. В последний раз эту чародейку видели в Змеином озере, на севере Зангартопи.\n\nКлан Кровавой Чешуи чрезвычайно опасен, и с их предводительницей нужно быть крайне осмотрительным!\n\nЖелающие получить награду могут обращаться к стражу Хамуту в Кенарийском приюте.", progress = nil, completion = "Могу поручиться, что теперь клан Кровавой Чешуи подумает дважды, прежде чем нападать на наших разведчиков! Вот твоя награда, Менгиле. Она честно заслужена!", rewards = "Экспедиционная обувьПерчатки болотоходцаПояс лунного совухаБуйные наплечные пластиныВы получите:\n\n"}
MultiLanguageQuestData['ru'][9818] = {title = "Из глубин", objective = "Поговорите с Гордаугом.", description = "Что-то происходит там, под землей. Почва дрожит, будто ее истязают. \n\n*Унтраг бьет себя кулаком в грудь.*\n\nЭтот звук повторяется сто тысяч раз. Без конца. Земля содрогается. Она взывает к нам.\n\nГордауг говорил со мной. Он сказал, что нечто вытесняет стихии наружу. Нечто из глубин.\n\nИди и поговори с Гордаугом. Нет, не говори ничего, просто слушай Гордауга. Слушай Гордауга и услышь...", progress = nil, completion = "&lt;Гордауг, кажется, кивает вам.&gt;\n\nСадись.", rewards = nil}
MultiLanguageQuestData['ru'][9819] = {title = "Истерзанные духи земли", objective = "Уничтожьте 10 истерзанных духов земли по просьбе Гордага из Трона Стихий Награнда.", description = "Приведи узурпатора. Ты найдешь его. Иди по земляной тропе. Сначала успокой истерзанных духов земли. Пусть уснут снова.\n\n<Гордауг бьет кулаком о землю, и от удара куски дурно пахнущей почвы летят во все стороны.>\n\nПусть уснут!\n\n<Гордауг указывает на юго-восток.>\n\nИщи духов у гор. У холмов. У камней. У земли.\n\nПусть духи уснут.\n\nТелаарская котловина... На юго-востоке.", progress = nil, completion = "&lt;Гордауг одобрительно кивает.&gt;\n\nХорошо. Духи уснули.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9820] = {title = "РАЗЫСКИВАЕТСЯ: Главарь Грог'ак", objective = "Принесите голову главаря Грог'ака темному охотнику Денжаю в Забра'джин.", description = "Разыскивается живым или мертвым главарь Грог'ак из клана Анго'рош, ответственный за операцию по сбору грибов.\n\nЭтот мерзавец и его прихвостни повинны в вырубке грибов к северу от поселения! Если их не остановить, эта банда прорубит тропу к самым стенами Забра'джина!\n\nТот, кто доставит голову Грог'ака темному охотнику Денжаю, получит щедрое вознаграждение!", progress = "Что там у тебя, Нидхейм?", completion = "Молодец, Щук! Однако то, что эти огры подобрались так близко к нашему форпосту, изрядно меня тревожит. Похоже, они уже давно пробираются сюда с северных гор...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9821] = {title = "Попробовать зло на зуб", objective = "Принесите Гордаугу к Трону Стихий 10 средоточий разъяренных сокрушителей.", description = "<Гордауг берет кусок породы и пробует его на зуб.>\n\nГордауг пробует. Гордауг знает, откуда эта земля.\n\n<Гордауг поднимает тяжеленную ногу и с силой впечатывает ступню в землю.>\n\nСмотри. Это Награнд.\n\n<Гордауг указывает на отпечаток ступни. Он оказывается подробной геологической картой Награнда, где обозначено местоположение элементалей, которых Гордауг хочет уничтожить.>\n\nРАЗДАВИ ИХ! Принеси Гордаугу осколки, я их съем.\n\nВозьми карту.", progress = "Гордауг есть камни. Гордауг найти захватчика. Неси камни!", completion = "&lt;Гордауг разжевывает камни и с отвращением сплевывает их, обдавая вас градом осколков.&gt;\n\nЯд. Эти камни не из Награнда. Эти камни – яд. Уничтожь ядовитые скалы. Найди захватчика.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9822] = {title = "Угроза нападения", objective = "Принесите планы нападения клана Анго'рош темному охотнику Денжаю в Забра'джин.", description = "Сдается мне, что огры не случайно затеяли вырубать грибы именно в этом направлении. Я подозреваю, что они готовят нападение на Забра'джин!\n\n<имя>, мне нужно знать это наверняка! У огров есть еще один форпост на северо-западе, земли Анго'рош. И если они готовятся напасть, там непременно должны быть признаки этого. Ступай в земли Анго'рош, <имя>, и постарайся выяснить это. Если обнаружишь что-нибудь подозрительное, возвращайся ко мне.", progress = "Ну что, удалось ли тебе обнаружить доказательства намерений огров?", completion = "&lt;Темный охотник Денжай внимательно изучает план.&gt;\n\nЯ так и знал! Где завоняло огром – там без войны не обойдется... Ну, теперь, когда у нас есть доказательство их намерений, следует их опередить!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9823] = {title = "Мы и они", objective = "Убейте властителя Кровавого Кулака, 10 извергов из клана Анго'рош и 10 пожирателей душ из клана Анго'рош и вернитесь к темному охотнику Денжаю в Забра'джин.", description = "Чтобы покончить с угрозой клана Анго'рош, нужно убить их вождя, властителя Кровавого Кулака. Однако мы не просто убьем его – судьба властителя и его приверженцев станет примером для всего клана!\n\nСтупай в крепость Анго'рош и покончи с нашими врагами. Крепость находится на маленьком острове к северо-западу от Забра'джина. Пройди лагерь Анго'рош, и увидишь мост из поваленного гриба.\n\nНе давай им пощады, <имя>! Они нас щадить не будут.", progress = nil, completion = "Щук, твоя победа над кланом Анго'рош – большой праздник для нас! Интересно, много ли времени пройдет, прежде чем эти кровожадные огры отыщут себе нового вождя?\n\nВпрочем, неважно. Мы будем готовы отразить их нападение!", rewards = "Вы получите:\n\nЗащитный шлем капитана КрошаБагровый энергетический напиток"}
MultiLanguageQuestData['ru'][9824] = {title = "Колебания тайной магии", objective = "Активируйте кристалл ясновидения Аметистового Ока рядом с подземными источниками вод в Хозяйском погребе и вернитесь к верховному магу Альтуру, находящемуся у входа в Каражан.", description = "Я пытаюсь получить отпечаток энергии Каражана... Разумеется, для своего собственного исследования. К сожалению, здесь мне не удается ничего уловить. Если бы я мог добраться до источника подземных вод, мой кристалл принимал бы сигналы без помех.\n\nЯ слышал, что в подземельях под нами есть источник с колодцем и целое подземное озеро. Правда, это место кишит призраками, а я уже не в том возрасте, чтобы с ними сражаться. Что скажете насчет того, чтобы помочь старику – спуститься в подземелье и задействовать гадальный кристалл <самому/самой>?", progress = "Как там замеры энергии, Душавдушу? Вам удалось их провести?", completion = "Результаты ни о чем хорошем не говорят, Душавдушу. Каражан должен излучать потоки тайной магии... Вместо этого мы наблюдаем полную тишину. Никаких сигналов. Вообще ничего. За исключением очень слабого демонического эха.\n\nЭто плохие новости, Душавдушу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9825] = {title = "Неустанный труд", objective = "Принесите 10 призрачных сущностей верховному магу Альтуру, находящемуся у входа в Каражан.", description = "Как вы могли заметить, снаружи стен Каражана блуждают призраки. Почему и как они там возникли, неизвестно, и это очень меня беспокоит!\n\nДоставьте мне одну из призрачных сущностей, чтобы я мог изучить ее. В Каражане много секретов, <имя>, и я полон решимости раскрыть их все.", progress = "Удалось собрать сущности призраков, |3-6(Жрец)?", completion = "Поразительно. Теперь я смогу изучить эти сущности, Менгиле. Спасибо вам за помощь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9826] = {title = "Вести из Даларана", objective = "Доставьте письмо Альтуруса верховному магу Седрику на окраину кратера Даларана.", description = "Все это не сулит нам ничего хорошего, <имя>. Я никогда не понимал необходимости в особой секретности, поэтому расскажу тебе немного о нас, то есть об Аметистовом Оке \n\nМы все – агенты Кирин-Тора, Совета магов Даларана. Нам было поручено следить за Каражаном и Медивом – на случай, если что-нибудь пойдет наперекосяк.\n\nЧто и случилось... причем очень скоро, после того, как Медив исчез.\n\nВ этом письме изложены все подробности моего личного расследования. Доставь его верховному магу Седрику, он тоже из Аметистового Ока. Его можно отыскать на склонах даларанского кратера.", progress = "Вы знаете об Аметистовом Оке? Кажется, мы не знакомы...", completion = "Альтур доверил тебе такую важную информацию? Вот старый дурень!\n\nС другой стороны, дело уже сделано, так что все, что мы можем - надеяться, что ты окажешься нам полезен. Полагаю, ты не откажешься сотрудничать с нами?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9827] = {title = "Высохшая базидия", objective = "Отнесите высохшую базидию Руаму в Телредор, что в Зангартопи.", description = "Пристально разглядев базидию, вы обнаруживаете выемки, в которых раньше, по-видимому, что-то находилось. Ком грибной ткани представляет собой загадку. Ясно, что она поражена каким-то заболеванием, но вы не понимаете, что это такое и что с ним не так.\n\nБыть может, кто-то из тех, кто лучше вашего разбирается в обитателях Зангартопи, сумеет объяснить вам, в чем дело...", progress = "Что там у тебя, Главтруп?", completion = "It looks like the basidium of a bog giant, but I haven't seen one in this condition before. I'd heard that the giants in the Dead Mire had begun to wither, but it's far more advanced than I expected.\n\nThe Dead Mire was once a lake like the others in the marsh, and it served as the spawning ground for the giants. With the waters receding, it seems the changes are preventing the giants from sporing. If this continues, the giants may disappear entirely.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9828] = {title = "Высохшая базидия", objective = "Отнесите высохшую базидию Реавижу на заставу Болотной Крысы, что в Зангартопи.", description = "Пристально разглядев базидию, вы обнаруживаете выемки, в которых раньше, по-видимому, что-то находилось. Ком грибной ткани представляет собой загадку. Ясно, что она поражена каким-то заболеванием, но вы не понимаете, что это такое и что с ним не так.\n\nБыть может, кто-то из тех, кто лучше вашего разбирается в обитателях Зангартопи, сумеет объяснить вам, в чем дело...", progress = "Что там у тебя, Щук?", completion = "Это выглядит как базидия болотника, но мне еще никогда не встречались базидии в таком состоянии... Я слышал, что великаны Мертвой трясины начинают вянуть, но тут дело зашло куда дальше, чем я предполагал…\n\nМертвая трясина когда-то была таким же озером, как и остальные озера на болотах, и великаны как раз там и плодились. Теперь же, когда вода отступила, им, похоже, просто негде рассеивать споры. Если так пойдет и дальше, великаны могут полностью исчезнуть...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9829] = {title = "Кадгар", objective = "Доставьте письмо Альтура Кадгару в Шаттрат - город в лесу Тероккар.", description = "Альтур прислал тревожные вести. Когда Каражан закрылся от всего мира, нам это не понравилось. Там работали наши агенты, а связь с ними прервалась. А теперь этот... демонический выброс. Нужно расследовать его!\n\nЕдинственные, кто мог открыть Каражан - Кадгар и Медив, - признаны умершими.\n\nМы надеемся, что Медив исчез навсегда, но вот его ученик, Кадгар, еще жив и находится в Шаттрате. Найдите его и отдайте ему письмо Альтура.", progress = nil, completion = "Аметистовое Око? Подумать только!\n\nПокажите-ка мне это письмо.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9830] = {title = "Яд паразита", objective = "Принесите 6 порций яда болотного паразита Пулуу в прибежище Оребор.", description = "Когда я говорю с дренеями, у меня всегда создается впечатление, что они не ощущают связи с родной природой. Вот моих собратьев, Сломленных, многие жалеют, говорят, что они как будто что-то потеряли.\n\nНу, может быть, мы и впрямь лишились стремления к Свету, но зато пережитое сделало нас ближе к земле.\n\nМой народ способен найти применение многому, что дренеи считают за мусор. Вот взять, к примеру, яд болотных паразитов, что водятся к юго-западу отсюда. Его ведь можно использовать и на охоте, и в медицине...", progress = "Я надеюсь показать анахорету Ахуурну и другим жителям Телредора, как можно использовать яд болотного паразита. Но для этого мне потребуется удвоить свои запасы.", completion = "Спасибо тебе за яд, Сотус! Теперь я смогу показать дренеям все, что нужно, не исчерпав при этом своих запасов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9831] = {title = "Вход в Каражан", objective = "Пройдите в Темный лабиринт в Аукиндоне, найдите там волшебный контейнер и возьмите из него первый фрагмент ключа, после чего вернитесь к Кадгару.", description = "Меня очень взволновали эти известия, <имя>, однако пробраться в Каражан будет не так-то просто.\n\nВидишь ли, когда стало ясно, что мне придется тут задержаться, я разломил ключ на три фрагмента.\n\nКаждый фрагмент я поместил в зачарованный контейнер и поместил их в места, которые на тот момент были самыми безопасными.\n\nОднако теперь нам нужно вернуть их. Первый фрагмент находится в части Аукиндона, которой завладел Совет Теней. Принеси мне этот фрагмент.", progress = "Вы нашли фрагмент, |3-6(Паладин)? Советую вам не терять времени попусту.", completion = "Вы отлично справились, Выручалкин, я даже и не ожидал.\n\nЭти контейнеры защищены сильными чарами, скрывающими их от недобрых глаз. Рад видеть, что на вас эти чары не подействовали.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9832] = {title = "Второй и третий фрагменты", objective = "Добудьте второй фрагмент ключа из волшебного контейнера в резервуаре Кривого Клыка, а третий фрагмент ключа – из волшебного контейнера в Крепости Бурь, после чего вернитесь к Кадгару в Шаттрат.", description = "Второй фрагмент я спрятал в Змеином озере, еще задолго до того, как оно получило это название. После того как озеро захватили наги и установили там гигантский сток, контейнер, скорее всего, оказался в глубине резервуара Кривого Клыка.\n\nДостать третий фрагмент будет сложнее всего, так как его я оставил в Крепости Бурь – она тогда еще принадлежала наару. Теперь крепость захватил Кель'тас, а зал, где я оставил фрагмент, превратили в тюрьму.\n\nПринеси мне недостающие фрагменты, <имя>. От твоего успеха зависит очень многое.", progress = "Как продвигаются поиски фрагментов ключа?", completion = "Вы добыли фрагменты. Что ж, это впечатляет, Душавдушу. Несомненно, вам можно доверить ключ от Каражана.\n\nОднако есть еще одна небольшая проблема.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9833] = {title = "Линии связи", objective = "Убейте 12 болотных терзателей по просьбе Пулуу из прибежища Оребор.", description = "Одна из причин, по которой Икути привел нас в Зангартопь – это необходимость поддерживать связь между дренеями и Телааром в Награнде, родиной Куренай. А для этого дороги должны быть безопасны.\n\nПо пути сюда на нас то и дело нападали болотные терзатели. Мы-то отражали их нападения, но для одинокого путника они чрезвычайно опасны! Если бы тебе удалось уменьшить их численность, нашим гонцам было бы куда спокойнее.", progress = nil, completion = "Отличные новости! Конечно, до полной безопасности здешним дорогам пока далеко, однако же наши посланцы умны и находчивы...", rewards = "Заколдованный клинок болотного клыкаОстро отточенный зуб болотного терзателяКровавый топор болотного клыкаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9834] = {title = "Природная броня", objective = "Принесите 8 шкур болотных твердозубов Макту в прибежище Оребор.", description = "Дренеев в их блестящих доспехах Макту видит за милю, даже сквозь болотный туман!\n\nМакту хочет над ними смеяться, но потом вспоминает, что они были добры к куренай, и Макту хочет показать им, как куренай делают доспехи.\n\nИз темных чешуйчатых шкур болотных твердозубов получаются самые лучшие доспехи, какие когда-нибудь носил Макту. Если <имя> принесет Макту несколько шкур болотных твердозубов, плавающих в глубинах Змеиного озера, Макту охотно поделится своими доспехами!", progress = "У Печенькус есть шкуры для Макту?", completion = "Макту думает, это хорошие шкуры. Из них получатся отличные доспехи.\n\nКто знает? Возможно, тут хватит и на несколько доспехов для дренеев.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9835] = {title = "Вторжение клана Анго'рош", objective = "Убейте 10 огров из клана Анго'рош и 5 шаманов из клана Анго'рош и вернитесь к Икути в прибежище Оребор.", description = "Небольшой отряд Сломленных, который ты видишь, – посланцы из большого поселения в Награнде. Куренай, как мы себя называем – это Сломленные, которые стремятся воссоединиться со своими собратьями-дренеями.\n\nМы прибыли сюда, чтобы укрепить связи Куренай с дренеями Телредора.\n\nЕсли огры из клана Анго'рош возьмут верх, этот храм долго не продержится. Они вырубили все крупные грибы на Болотных вырубках, и подбираются все ближе к нашему убежищу. Если ты хочешь считаться нашим другом, помоги нам бороться с этими врагами!", progress = nil, completion = "Угроза, исходящая от клана Анго'рош, пока нейтрализована, но ясно, что просто так они не сдадутся. С тех пор как мой жизненный путь дренея завершился, я многое позабыл, но упрямство огров забывается не скоро.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9836] = {title = "Разрешение учителя", objective = "Отправляйтесь в Пещеры Времени и уговорите Медива дать разрешение на использование Восстановленного ключа.", description = "Я сумел воссоздать ключ, которым пользовался, будучи учеником. С виду он вполне рабочий - в общем-то, ключ как ключ. Но если попытаться открыть им Каражан, ключ не подействует. С тем же успехом можно использовать и обычную железку.\n\nСобственно, это и есть никчемная железка. Ключ не будет работать без согласия Медива. Да, я знаю, что Медив мертв. Но это не значит, что с ним невозможно связаться.\n\nВ Азероте есть место, которое называют Пещерами Времени. Их охраняют бронзовые драконы. Проберись в пещеры, вернись в прошлое и уговори Медива дать разрешение на пользование ключом.", progress = "Кто ты и что тебе нужно?", completion = "Ага, точно. Я его узнаю. Ключ Кадгара... Разумеется, я еще не давал ему никакого ключа.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9837] = {title = "Возвращение к Кадгару", objective = "Вернитесь в Шаттрат к Кадгару и покажите ему хозяйский ключ.", description = "Похоже, я помню кое-что о грядущих событиях, связанных с тобой и этим ключом.\n\n*Медив смотрит на вас так, будто увидел привидение.*\n\nТебя ждут нелегкие времена, <имя>. Будем надеяться, у тебя хватит сил вынести все испытания.\n\nЧто касается ключа, то я должен отдать его Кадгару, когда он придет ко мне. О таком ученике можно только мечтать.\n\nЯ так понимаю, тебе понадобится твой собственный ключ.\n\n*Медив роется в карманах своего одеяния и вручает вам ключ.* \n\nВот он. Желаю тебе удачи, <класс>.", progress = nil, completion = "Его собственный ключ? Невероятно!\n\nЯ не чувствую никаких возмущений в нашей временной линии, так что, думаю, это действительно произошло. Дороги назад нет, Менгиле. Этот ключ твой и только твой.", rewards = "Вы получите:\n\nХозяйский ключ"}
MultiLanguageQuestData['ru'][9838] = {title = "Аметистовое Око", objective = "Поговорите с верховным магом Альтуром, который находится снаружи Каражана.", description = "На тебя была возложена великая ответственность, <имя>. Если знаки, которые удалось разглядеть Аметистовому Оку, истинны, то ты <должен/должна> помочь им.\n\nНесмотря на все мои расхождения с Седриком, я признаю, что люди вроде Альтура ведут очень важную работу. Но будь <осторожен/осторожна> - они могут тебя использовать. Всегда помни о том, что ключ принадлежит тебе, а не им. Но если в Каражане и правда таится опасность, то именно они лучше всего научат, как ее одолеть. Возвращайся к Альтуру и помогай ему, чем сможешь.", progress = nil, completion = "Я послал вас, чтобы доставить письмо, а вы вернулись с ключом от этого места? Похоже, в вас скрыто нечто большее, чем кажется на первый взгляд, Душавдушу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9839] = {title = "Властитель Кровавый Кулак", objective = "Убейте властителя Кровавого Кулака и 10 извергов из клана Анго'рош по просьбе Икути. Выполнив задачу, вернитесь в прибежище Оребор.", description = "Основа любого огрского клана – это его вождь. Лишившись вождя, клан Анго'рош распадется, и огры примутся драться между собой, выясняя, кто теперь будет главным.\n\nХотя здесь немало разных огров, их основные силы сосредоточены в крепости Анго'рош на северо-западе. Крепость представляет собой пещеру на небольшом островке, на который с болота можно попасть по стволу поваленного гриба.\n\nСтупай туда и одолей властителя Кровавого Кулака! Это обеспечит нам давно заслуженную передышку.", progress = nil, completion = "Наконец-то! Мы благодарим тебя за помощь – благодаря тебе наше положение упрочилось. Я пошлю весть о твоих деяниях в куренайский город Телаар в Награнде. У наших народов еще не раз будет случай сражаться плечом к плечу!", rewards = "Плащ телаарского гонцаБолотные наручиВам дадут возможность выбрать одну из следующих наград:\n\nОжерелье сияющего кристалла\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9840] = {title = "Оценка ситуации", objective = "Найдите Корена в Каражане.", description = "Теперь, когда мы - вернее, ты -<нашел/нашла> путь обратно в Башню Медива, нам надо в первую очередь попытаться узнать, что же происходит внутри.\n\nОдна из наших агентов, которой удалось проникнуть в Каражан, вела закодированную запись событий. К несчастью, сразу после того, как Каражан закрылся, мы узнали о ее смерти. На нас работал Корен, кузнец из Каражана. Хотя он не член Аметистового Ока, думаю, он поможет нам отыскать записи Кеанны. Ты найдешь его внутри.", progress = nil, completion = "*Корен смотрит на вас непонятным взглядом.*\n\nЯ ничего не знаю про Аметистовое Око. Я всего лишь кузнец.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9841] = {title = "Поделом гнусным тварям!", objective = "Убейте 8 болотных паразитов и вернитесь к Гамбаринке в Забра'джин.", description = "Что за адское жужжание! Просто работать невозможно! Слышишь?\n\nЯ от него буквально с ума схожу. И, главное, я ведь знаю, кто это жужжит! Это все проклятые болотные паразиты! И шум всегда доносится с юго-западной стороны от деревни.\n\nЭти твари такие здоровенные, что их не прихлопнешь, не раздавишь, и отмахнуться от них тоже не получится. С ними надо воевать всерьез! В общем, меня не волнует, как ты это сделаешь, <имя>, главное - заставь их заткнуться!", progress = nil, completion = "Так я и думал. Разница сразу заметна. Наконец-то я снова смогу взяться за работу! Спасибо тебе большое! Если тебе снова понадобятся мои товары, не забудь про Гамбаринку!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9842] = {title = "Острейшие резцы", objective = "Принесите 10 зубов болотного терзателя Гамбаринке в Забра'джине.", description = "Болотная сырость не пошла на пользу моим железным инструментам. Я уже зарекся их точить. Работа по дереву не идет совершенно.\n\nОднако обнаружилось, что зубы болотных терзателей, обитающих к югу и к западу от города, куда острее любых стальных резцов, какими я когда-либо владел! Кроме того, они не тупятся и не боятся ржавчины. Правда, вделывать их в рукоятку не так-то просто, но я, кажется, решил и эту проблему. Так что приноси мне их зубы, я буду очень признателен.", progress = "Ну что, удалось тебе раздобыть резцы для меня?", completion = "О, ну, этого мне хватит надолго! Мне кажется, кое-кто догадывается, в чем дело. У меня уже несколько раз спрашивали, не продам ли я свои резцы. Может быть, продавать их на сторону окажется даже выгоднее, чем мастерить что-то самому...", rewards = "Заколдованный клинок болотного клыкаОстро отточенный зуб болотного терзателяКровавый топор болотного клыкаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9843] = {title = "Записи Кинны", objective = "Найдите Гостевые залы в Каражане, а в них - записи Кеанны, и доставьте их верховному магу Альтуру.", description = "Кого ты там <искал/искала>, повтори-ка еще разок? Кинну?\n\nКогда-то я встречал кого-то с похожим именем. Она останавливалась наверху, в Гостевых комнатах. Я не должен был болтать об этом, да?\n\nКак ты <говорил/говорила>, ты из Аметистового Ока? Никогда о таком не слыхал.\n\nА теперь я бы вернулся к своей работе, если не возражаешь.\n\n<Похоже, Корен уже забыл о вас.>", progress = "Записи Кеанны... Вам удалось их найти?", completion = "Тебе удалось найти записи. Я уверен, они содержат информацию, которая даст ответ на наши вопросы, Мротсагемо.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9844] = {title = "Присутствие демонов", objective = "Верховный маг Альтур просит вас уничтожить демона на вершине башни Каражана.", description = "Последние несколько записей Кеанны подтверждают наши предположения, что в Каражан пробрались демоны.\n\nЕй удалось засечь прибытие агента Пылающего Легиона. По ее словам, он обосновался на самом верху башни.\n\nНа этом ее записи обрываются.\n\nКаражан - это очень важное для нас место, <класс>. Это портал в бездну, маяк, сияющий для других миров. Я не хочу даже думать о том, что может случиться, если он попадет не в те руки. Необходимо остановить демонов. А ключ от Каражана, <имя>, есть только у вас.", progress = "Я боюсь услышать ваш ответ, Фэникс. Что происходит в Каражане?", completion = "Вам удалось это сделать! Наши данные снова пришли в норму!\n\nНеобходимо сообщить новости Седрику. Он будет просто поражен.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9845] = {title = "Не распугивайте рыбу!", objective = "Убейте 10 болотных твердозубов и вернитесь к Зурджайе в Забра'джин.", description = "Как же хорошо наконец очутиться в месте, где есть вода, после всех этих пустынь полуострова Адского Пламени! А то я уж боялась, что тут, в Запределье, и рыбку толком половить негде.\n\nНо, оказывается, я все-таки не зря тащила с собой снасти. Рыбалка здесь отменная, только вот болотные твердозубы из Змеиного озера жизнь отравляют страшно.\n\nМало того, что рыбу распугивают, так еще и наживку с крючка срывают. Не столько ловишь, сколько насаживаешь новых живцов!", progress = nil, completion = "Мне не терпится поскорее вернуться к рыбалке! Наконец-то я принесу в город полное ведро рыбы! А то Гамбаринка меня уже засмеял.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9846] = {title = "Духи Дикотопи", objective = "Принесите 10 тотемов-хранителей Дикотопи ясновидящей Джаниди в Забра'джин.", description = "Говорят, что самое могущественное племя Заблудших на болотах, племя Дикотопи, владеет могучей магией. Может быть, это и вранье, но я не могу пренебрегать ничем, что поможет мне управлять духами этого мира.\n\n<имя>, отыщи мистиков, охотников и друидов Дикотопи, и захвати их тотемы. Все, что мне надо знать, станет понятно по их резьбе.", progress = "И где тотемы?", completion = "Хм... Похоже, здесь наличествуют духи двух видов: в змеином обличье и в облике птицы. Разумеется, птице ни один уважающий себя тролль из племени Черного Копья поклоняться не станет. Духи птиц слабы и капризны. Оставим их в удел племени Амани.\n\nНо змея, Менгиле, змея обладает значительным могуществом! Я займусь изучением этого духа.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9847] = {title = "Дух-союзник?", objective = "Отнесите тотем Дикотопи к подножию лестницы руин Боха'му и установите его на землю. Расскажите о том, что вы видели, ясновидящей Джаниди в Забра'джине.", description = "Нужно выяснить, велико ли могущество змеиного духа Дикотопи, и можно ли его подчинить нашей воле. Только представь, что можно было бы совершить, повелевая могуществом духа Запределья!\n\nВозьми с собой этот тотем и проберись к подножию лестницы, ведущей в руины Боха'му. Установи тотем на землю, остальное он сделает сам. Дух не сможет явиться, пока кто-нибудь не воспользовался тотемом.", progress = "Удалось ли тебе призвать духа Дикотопи?", completion = "&lt;Вы рассказываете провидице Джаниди о том, что произошло, когда вы использовали тотем.&gt;\n\nДух напал на тебя? Должно быть, он теснее связан с этими Заблудшими, чем я думала... Значит, его не удастся заставить служить мне, не применяя значительных усилий... Придется искать другой источник могущества!", rewards = "Пелерина призрачного змеяБолотные наручиВам дадут возможность выбрать одну из следующих наград:\n\nДревний хрустальный талисман\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9848] = {title = "Тайны Остротопи", objective = "Принесите справочник по ядам Остротопи и фиал яда Остротопи Тимоти Даниэльсу в прибежище Оребор.", description = "Насекомые, насекомые! Болота кишат насекомыми, и мои товарищи, похоже, помешались на них.\n\nНу, а с меня довольно! Меня интересует куда более важный вопрос. К западу отсюда есть деревня Заблудших, которые называют себя кланом Остротопь.\n\nВсе они – высокопрофессиональные убийцы. Я обнаружил, что они изготовляют и применяют особенно действенный сорт яда. И мне до смерти хочется узнать побольше об этом яде. Однако для этого нужно раздобыть рецепт и фиал с образчиком...", progress = "Надеюсь, твои поиски в деревне Остротопь не были безрезультатными? Мне не терпится разрешить эту загадку!", completion = "&lt;Тимоти бросается листать справочник.&gt;\n\nОни используют в качестве основного компонента кисейницу? Ерунда какая-то. Кисейница же совершенно не ядовита!\n\nВводить в состав яда кисейницу – это все равно, что разбойнику сражаться двумя палицами. Можно, конечно, но какой смысл?! Решительно не понимаю...\n\n&lt;Тимоти прочищает горло.&gt;\n\nВ общем, спасибо большое. Попробую приготовить этот яд, как только будет время...", rewards = "Вы получите:\n\nВерный шлем ТимаБагровый энергетический напиток"}
MultiLanguageQuestData['ru'][9849] = {title = "Сорвать личину", objective = "Убейте 30 прислужников Гурока.", description = "<Гордауг отламывает кусок черного камня со своей спины.>\n\nТеперь в твоих руках сила гнева земли. Возьми камень Гордауга и метни в ядовитую скалу. Разбей их панцири – открой правду. Убей приспешников захватчика и узнай его имя.\n\nТы найдешь расколотых грохотунов на краю земли. На юго-западе.", progress = "Гордауг хочет свой камень назад.", completion = "ГУРОК! Гурок предал стихии!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][9850] = {title = "Охота на копытней", objective = "Убейте 12 самцов копытня и вернитесь к Хемингу Эрнестуэю в его охотничий лагерь в Награнде.", description = "Я уже убедился, что ты <способен/способна> разыскать и завалить обыкновенного копытня, но их самцы гораздо опаснее!\n\nУбей двенадцать самцов копытня, и тогда уже поговорим о твоем охотничьем мастерстве.\n\nЭти звери обитают в центральных районах Награнда, к западу и югу отсюда.", progress = nil, completion = "Очень даже неплохо.\n\nИз тебя может выйти хороший охотник, малыш. Пора дать тебе шанс позабавиться по-настоящему.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9851] = {title = "Охота на копытней", objective = "Добудьте рог Бантар и отнесите его Хемингу Эрнестуэю в лагерь Эрнестуэя в Награнде.", description = "Бантар – самая свирепая и самая неуловимая из всех копытней в Запределье. И самая косматая.\n\nГоворят, она сейчас отвела свое стадо на Поле Духов близ Ошу'гуна.\n\nХочешь, чтобы я убедился в твоем охотничьем мастерстве? Принеси мне ее рог!", progress = "Домашний очаг, супруга под боком, досужие сплетни – эти обывательские радости не для нас. Мы охотимся за крупной дичью и рискуем при этом жизнью.", completion = "У тебя получилось! Ты убил саму Бантар! Впрочем, я в тебе не сомневался, Выручалкин.\n\nВот, возьми. Ты заслужил награду.", rewards = "Шлем из шкуры копытняПерчатки из шкуры копытняНарукавники из шкуры копытняВы получите:\n\n"}
MultiLanguageQuestData['ru'][9852] = {title = "Опасный спорт", objective = "Принесите сердце Клыкач Хемингу Эрнестуэю в его лагерь в Награнде.", description = "Клыкач – королева животного царства Награнда. Гигантская самка элекка, равных которой нет на свете!\n\nОдно ее имя наводит страх, и ее не зазорно бояться. Хол'стяк, Потрошитель и Бантар – жалкие мошки по сравнению с ней. Говорят, ее можно найти на отвесной скале неподалеку от Ошу'гуна, на юго-западе отсюда. Если тебе хватит смелости, принеси мне сердце королевы элекков.\n\nУ тебя есть родные? Не хочешь написать им записку? Если ты не вернешься... а скорее всего, так и будет... я обязательно передам ее безутешным родственникам.", progress = "Нет ничего постыдного в том, чтобы признаться, что тебе не хватает смелости выйти на самого могучего и страшного зверя на этой земле, Душавдушу.", completion = "Душавдушу! Отрадно видеть тебя живым и невредимым!\n\nТеперь уж никто не усомнится, что ты достоин войти в ряды лучших охотников! Все остальные либо в страхе бежали, либо погибли, затоптанные свирепой зверюгой. Но ты подтвердил свое мастерство охотника, проявив ум, хитрость, смелость и решимость.\n\nВот, возьми этот подарок и знай: я всегда буду рад, если ты пожелаешь присоединиться к моей охотничьей партии!", rewards = "Ружье Хеминга для охоты на элекковОхотничья трость ЭрнестуэяВам дадут возможность выбрать одну из следующих наград:\n\nОмолаживающая брошь ГарольдаБлагословенная книга НаграндаТотем РавнинМетательный топорик Фитца\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9853] = {title = "Гурок Узурпатор", objective = "Убейте Гурока Узурпатора и принесите его голову Гордаугу к Трону стихий.", description = "Надо вызвать Гурок. Ты вызвать Гурок и убить.\n\nТы иди в северо-запад, холм Боевого Молота, и ищи место, где огр молиться Гурок. Черепа огров Боевого Молота клади на алтарь Гурок. Только потом Гурок придет. Семь черепов.\n\nБудешь <живой/живая>, приноси Гордаугу земляную голову Гурока. Гордауг разбить голову.\n\n<Гордауг топает так, что трясется земля.>", progress = "Гордауг поедать силу Гурок.", completion = "&lt;Гордауг вгрызается в голову Гурока, размалывая камень почти что в пыль.&gt;\n\nВласть Гурока кончилась. Свобода духам земли. Теперь все спать. Награду ты получать!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗемной знак разрушенияЗемной знак силыЗемной знак здоровья\n\nВы также получите:\n\nПредмет #7"}
MultiLanguageQuestData['ru'][9854] = {title = "Охота на ветрухов", objective = "Убейте 12 ветрухов и вернитесь к Фитцу в охотничий лагерь Эрнестуэя в Награнде.", description = "Ты тоже живешь лишь охотой, <класс>? Тоже ищешь покоя, что нисходит на душу охотника, когда он выслеживает добычу? Знаешь ли ты, что такое трепет перед последними ударами сердца сраженного зверя? Я помогу тебе узнать все тонкости нашего ремесла!\n\nНагранд – край, исполненный жизни. Нетронутый островок жизни посреди этого опустошенного мира. Принеси мне убитых тобою ветрухов, и тогда мы продолжим разговор.\n\nВетрухов найти легко – они бродят повсюду вокруг нашего лагеря.", progress = nil, completion = "Каждый прожитый день – это великий дар. И этим даром надо воспользоваться в полной мере. И, может быть, уже завтра наши шаги по земле станут еще стремительнее и легче. А наши руки протянутся немного дальше в извечном стремлении схватить ускользающую мечту.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9855] = {title = "Охота на ветрухов", objective = "Добудьте 12 прожорливых ветрухов и вернитесь к Фитцу в лагерь Эрнестуэя в Награнде.", description = "Только <достойнейший/достойнейшая> из достойнейших сможет приблизиться к великой добыче! Пока ты еще не <готов/готова>, я буду тебя направлять.\n\nСуществует еще один вид ветрухов – свирепее и опаснее прочих. Разыщи прожорливых ветрухов и испытай свою храбрость. Ты найдешь их в самом сердце Награнда, к западу и юго-западу отсюда.", progress = nil, completion = "Ты еще раз подтвердил свое мастерство, |3-6(Охотник). Теперь тебе предстоит охота на самого свирепого и лютого ветруха.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9856] = {title = "Охота на ветрухов", objective = "Принесите глаз Потрошительницы Фитцу в охотничий лагерь Эрнестуэя в Награнде.", description = "Теперь ты <готов/готова>, <класс>. <Готов/Готова> предстать перед матерью всех ветрухов, самой Потрошительницей! Закон чести требует, чтобы ты <дал/дала> ей возможность сразиться с тобой, после того как ты <лишил/лишила> жизни стольких ее детей! Ищи ее среди больших ветрухов далеко к западу отсюда.\n\nЕсли ты выйдешь <победителем/победительницей> из этой схватки, принеси мне глаз Потрошительницы.", progress = "Ты уже сразился с Потрошительницей?", completion = "Глаз - как живой! Как ты считаешь, может быть, Потрошительница по-прежнему заглядывает тебе прямо в душу?\n\nДушавдушу, теперь можешь считать, что тебя приняли в ряды лучших охотников. И ты приблизился еще на шаг к величайшей добыче на этой земле, гигантскому элекку!\n\nТы заслужил достойную награду.", rewards = "Наголенники ветрухаСапоги ветрухаНакидка ветрухаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9857] = {title = "Охота на талбуков", objective = "Убейте 12 талбуков-самцов и возвращайтесь к Гарольду Лейну в лагерь Эрнестуэя в Награнде.", description = "Сегодня я вряд ли пойду на охоту. Не желаешь меня заменить?\n\nЯ сказал Хемингу, что постараюсь добыть побольше талбуков, которые здесь встречаются на каждом шагу. Лучше всего охотиться на самцов. Кстати, я видел, как они собирались в ближайшей роще.\n\nНу что? Поохотишься за меня?", progress = nil, completion = "Ты славно управился... (кашляет)...с этими талбуками, |3-6(Охотник). Но мне кажется, ты способен на большее. У меня есть для тебя еще одно задание...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9858] = {title = "Охота на талбуков", objective = "Убейте 12 талбуков-шипоедов и возвращайтесь к Гарольду Лейну в лагерь Эрнестуэя в Награнде.", description = "Эта проклятая царапина меня доконает. Не хочешь еще раз... (кашляет)... меня заменить?\n\nНа этот раз твоя цель – шипоеды. Они умнее и хитрее обычных талбуков, так что их просто так не возьмешь. Ищи их... (кашляет)... в рощах в центральном Награнде, к западу и югу отсюда.\n\nИди. А потом возвращайся с добычей... (кашляет)... пусть Хеминг увидит, на что ты <способен/способна>. А за меня не волнуйся, со мной все будет в порядке.", progress = nil, completion = "*кашляет* Поздравляю, Душавдушу! Ты все-таки справился с ними! Значит, у нас остается... *кашляет*... всего одно дело.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9859] = {title = "Охота на талбуков", objective = "Добудьте копыто Хол'стяка и принесите его Гарольду Лейну в охотничий лагерь Эрнестуэя в Награнде.", description = "*Сильно кашляет.*\n\nЗа меня... *кашляет*... не волнуйся. Со мной все будет в порядке. Это просто... *кашляет*... царапина.\n\nВсе равно... *кашляет*... в любом случае тебе пришлось бы... *кашляет*...меня подменить... *кашляет*... еще раз.\n\nТебе надо будет найти Хол'стяка, короля... *кашляет*... талбуков.\n\nПринеси мне копыто Хол'стяка... *кашляет*... в подтверждение, что у тебя все получилось.\n\nТы найдешь его и его стадо... *кашляет*...на западе Награнда.", progress = "<Гарольд смотрит на вас и улыбается слабой бледной улыбкой.>\n\nТы принес... *кашляет*.. копыто?", completion = "Ничего себе! Это и вправду копыто Хол'стяка!\n\nПохоже, мне уже лучше. Вот, держи подарок. Ты его заслужил!", rewards = "Талбукская колючкаТалбукский кортикТалбукская накидкаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9860] = {title = "Новое направление", objective = "Поговорите с верховным магом Седриком на окраине кратера Даларана.", description = "Немедленно возвращайтесь к Седрику, <имя>. Ваша помощь Аметистовому Оку будет вознаграждена. \n\nМожете думать о нас и о нашей организации что хотите, <класс>, но об обретении благосклонности верховных магов Даларана вы не пожалеете.", progress = nil, completion = "Альтур рассказал мне, что случилось, Выручалкин, но это еще не все. Если Каражан так и останется запечатанным от пришельцев извне, захватить нас врасплох станет для Легиона делом времени.\n\nЕсли только вы не примете на себя ответственности, наложенной на вас самой судьбой.\n\n*Седрик протягивает вам раскрытую ладонь, на которой лежит знак с символом Аметистового Ока.*\n\nЧто скажете, Выручалкин?", rewards = "Вы получите:\n\nЗнак Аметистового Ока"}
MultiLanguageQuestData['ru'][9861] = {title = "Вой-Ветер", objective = "Разыщите у Трона стихий кого-нибудь, кто знает язык калимаг, и покажите ему или ей Вой-Ветра.", description = "Эта аморфная масса воздушной стихии говорит с вами на языке, которого вы не понимаете. Скорее всего, это язык стихий – калимаг. Может быть, у Трона стихий найдется кто-то, кто подскажет вам, что это за странная находка.", progress = "Дай это мне! Быстро!", completion = "Это крик боли и призыв о помощи, |3-6(орк). Некая внешняя сила пытается разрушить стихии.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9862] = {title = "Разлагатели Темной Крови", objective = "Убейте 5 разлагателей из племени Темной Крови по просьбе повелителя стихий Морха, находящегося у Трона Стихий.", description = "Племя Темной Крови ловит и пытает духов воздуха! Мне горько об этом говорить, ведь они – мои сородичи. Их клан продался подлому Мусел'еку, владыке болот из клана Кривого Клыка.\n\nДух воздуха утверждает, что разлагатели из племени Темной Крови ловят его сородичей и используют их, чтобы сеять хаос в рядах стихий. Насколько я знаю, недавно они захватили заставу Солнечного Источника, поселение орков к юго-западу отсюда, и используют магию стихий, чтобы потревожить озеро. Найди разлагателей и убей их.", progress = nil, completion = "Ты своими глазами видел, как они управляют стихиями? Ветер послушен их воле?\n\n*Моргх на секунду задумывается.*\n\nМне это очень не нравится, Хлуси. Надо посоветоваться с остальными.\n\nМы благодарны тебе за помощь, Хлуси. Может быть, тебе стоит вернуться в свою деревню и проверить, нет ли еще каких сведений о Падших Темной Крови и их гнусных планах.", rewards = "Наплеч кольцаРукавицы трибуналаШнурованный ремень кольцаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9863] = {title = "Вражеские святыни", objective = "Принесите 10 идолов Темной Крови предсказателю Куркашу в Гарадар.", description = "Теперь, когда мы остались без предводителя, мы открыты для нападения со всех сторон. Эти мерзавцы из клана Мертвой Крови выбрали самый что ни на есть \"подходящий\" момент для нападения!\n\nЗа последние несколько дней нам пришлось выдержать целых пять атак Сломленных. Они захватили наше единственное, помимо Гарадара, укрепленное владение в этих краях – Заставу Солнечного Источника.\n\nМы должны показать этим мерзавцам, что нас так просто не запугаешь! Проникни в лагерь этих идолопоклонников и укради их поганые идолы. Представляю, какой это будет для них удар!", progress = "Нам не хватит сил для набега, поэтому мы попросили тебя о помощи.", completion = "Ты дал надежду Сынам Молнии, Джонниди. Увы, наш вождь не способен более защитить свой народ, но быть может, найдутся герои, которые спасут нас... такие, как ты.", rewards = "Чешуйчатые поножи боевого заклинателяБригантина мстителя Темной КровиЛучезарная корона МелииВы получите:\n\n"}
MultiLanguageQuestData['ru'][9864] = {title = "Пропавший отряд", objective = "Отыщите пропавший гарадарский отряд.", description = "После набега племени Темной Крови группа наших юнцов решила им отомстить. Мы пытались их остановить, но ярость оказалась сильнее. Прошла уже неделя, а от наших детей нет ни единой весточки.\n\nПрошу тебя, <раса>, отыщи их. Они еще очень юные – куда им тягаться со свирепыми дикарями?!\n\nОни направились по западной дороге. Поезжай по ней и попытайся обнаружить следы наших юных отпрысков.\n\nИ еще одно, <имя>, если ты дорожишь своей жизнью, обходи Халаа стороной. Там идет война.", progress = nil, completion = "Я знаю предания своего народа. В них говорится, что когда-то мы были великими воинами…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9865] = {title = "Да, были воины в наше время...", objective = "Убейте 20 падальщиков из племени Темной Крови и 10 налетчиков из племени Темной Крови.", description = "Я не знаю, кто ты, <странник/прекрасная госпожа>, но молю о помощи. Мне горько говорить об этом, но я – последний из орков, оставшихся здесь.\n\nЯ ощутил что-то такое, чего не чувствовал прежде... Я... я жажду мести. Кровь за кровь. Ты когда-нибудь <чувствовал/ощущала> что-либо подобное? Меня охватывает непреодолимое желание схватить топор и сокрушить им моих врагов. Я готов сражаться до тех пор, пока рука не опустится в изнеможении.\n\nЗастава Солнечного Источника лежит к югу отсюда. Там ты найдешь наших врагов... Убей их... Убей их всех...", progress = "За каждого убитого ими сородича пусть погибнут десять моих врагов!", completion = "&lt;Саурфанг смотрит на вас.&gt;\n\nДа, я чую запах крови! Жаль, я не смог сам поучаствовать в этой битве. Тебе есть чем гордиться. Это честь для меня – знать, что ты совершил этот подвиг ради моего народа.\n\nКто ты? Откуда? В вашей стране есть герои, подобные тебе?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9866] = {title = "Он будет странствовать по земле...", objective = "Доставьте известие предсказателю Корхуку в Гарадар.", description = "Окажи мне последнюю услугу, <имя>. Я не хочу возвращаться в Гарадар. Я убежден, что судьба уготовила мне иной путь, на котором меня ждут великие свершения.\n\nПожалуйста, найди предсказателя Корхука и скажи ему, что я не вернусь. Я не могу повернуть назад. Я должен странствовать по земле... Он поймет.", progress = nil, completion = "&lt;Предсказатель Корхук смотрит себе под ноги, погруженный в раздумья. Потом кивает и вытирает скупую слезу.&gt;\n\nСын – весь в отца... И пусть духи смилостивятся над теми, кто встанет у него на пути.", rewards = "Кюлоты зеленого стражаГромоносный стражПолуперчатки контрабандиста"}
MultiLanguageQuestData['ru'][9867] = {title = "Главари Темной Крови", objective = "Принесите предсказателю Маргадешу в Гарадар голову Ортора Темной Крови.", description = "За последние недели мы потеряли многих друзей.\n\nДесятилетиями мы боролись с ограми Награнда, но теперь нам угрожает новый враг. Сломленные из племени Темной Крови напали на заставу Солнечного Источника на юго-западе. Все орки были убиты или бежали из города.\n\nМногие считают, что врагов следует убивать всех без разбора, но я уверен, что начать надо с их главаря. Не знаю, кто там у них верховодит, но подозреваю, что узнать его будет нетрудно.", progress = "Принеси мне голову их вождя, Джонниди.", completion = "Значит, я смотрю в лицо нашего врага? Я прикажу насадить эту голову на кол и выставить над воротами Гарадара. Если они соберутся напасть на нас снова, пусть видят, к чему приводят столь необдуманные шаги…", rewards = "Восемьдесят серебряных звеньевПечные рукавицы Темной КровиНожные латы мстителя Темной КровиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9868] = {title = "Тотем Кардаша", objective = "Помогите пленному маг'хару бежать с заставы Солнечного Источника. Расскажите Гаррошу в Гарадаре обо всем, что вам удалось узнать.", description = "Спасибо тебе, <чужестранец/чужестранка>. Если бы не ты, эти твари наверняка прикончили бы меня.\n\nМеня взяли в плен три ночи назад во время ночного рейда на Гарадар. За время своего пребывания здесь я выяснил ужасную вещь: оказывается, эти дикари собираются отыскать тотем Кардаша! Мы никак не можем допустить, чтобы тотем попал в руки племени Темной Крови!\n\nТы <должен/должна> помочь мне бежать отсюда. Если я не доберусь до Гарадара – ты, <чужестранец/чужестранка>, расскажешь Гаррошу о том, что здесь произошло...", progress = nil, completion = "Какая разница? Великая мать умирает. Нет смысла жить дальше...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9869] = {title = "Трон стихий", objective = "Поговорите с повелительницей стихий Шарвак у Трона стихий.", description = "Приветствую тебя, <раса>. Я – Локи, повелитель стихий из Служителей Земли. Я пришел в Телаар, чтобы рассказать куренай о состоянии стихий.\n\nМогу я тебя попросить об одной небольшой услуге? Ты не <мог/могла> бы сходить к Трону стихий – это в северных холмах Награнда, за озером Небесной Песни, – и сообщить повелительнице стихий Шарвак, что я благополучно добрался до Телаара? Без вознаграждения ты не останешься. Я уверен, что Шарвак предложит тебе компенсацию за беспокойство.", progress = nil, completion = "Большое спасибо за новости. Не желаешь ли ты оказать содействие Служителям Земли? Стихии находятся в движении. Сейчас мы не откажемся от любой помощи.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9870] = {title = "Трон стихий", objective = "Поговорите с повелительницей стихий Шарвак у Трона стихий.", description = "Приветствую тебя, <раса>. Я – повелитель стихий Ялхан из Служителей Земли. Я пришел в Гарадар, чтобы проинформировать маг'харов о состоянии стихий.\n\nМогу я попросить тебя об одной небольшой услуге? Ты не <мог/могла> бы сходить к Трону стихий – это в северных холмах Награнда, за озером Небесной Песни – и сообщить повелительнице стихий Шарвак, что я благополучно добрался до Гарадара? Без вознаграждения ты не останешься. Я уверен, что Шарвак предложит тебе компенсацию за беспокойство.", progress = nil, completion = "Большое спасибо за новости. Не желаешь ли ты оказать содействие Служителям Земли? Стихии находятся в движении. Сейчас мы не откажемся от любой помощи.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9871] = {title = "Захватчики из племени Темной Крови", objective = "Передайте планы вторжения Темной Крови Арехрону в Телаар, что в Награнде.", description = "На пергаменте нарисована грубая и схематичная карта Награнда. Телаар обозначен большим красным \"X\". Похоже, племя Темной Крови готовит вторжение в город. Передайте планы вторжения племени Темной Крови Арехрону в Телааре.", progress = "Что это?", completion = "*Арехрон бьет кулаком по ладони.*\n\nОртор... Гнусный предатель!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9872] = {title = "Захватчики из племени Темной Крови", objective = "Передайте планы вторжения Темной Крови Гаррошу.", description = "На пергаменте нарисована грубая и схематичная карта Награнда. Гарадар обозначен большим красным \"X\". Похоже, племя Темной Крови готовит вторжение в город. Передайте планы вторжения племени Темной Крови Гаррошу в Гарадаре.", progress = "Что это?", completion = "&lt;Гаррош мнет карту и бросает ее в огонь.&gt;\n\nКакая разница? Это уже далеко не новость. Они давно нас атакуют. Мы пока держимся, но...\n\nНеужели ты не понимаешь? Все кончено... Великая Матерь Гейя умирает.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9873] = {title = "Ортор, мой старый друг...", objective = "Арехрон из Телаара в Награнде поручил вам убить Ортора Темную Кровь.", description = "Эти планы вторжения составлял мой давний знакомый. Ортор Темная Кровь, некогда знатный Сломленный, посвященный в науку стихий, теперь сделался лизоблюдом Мусел'ека, этого царя пиявок.\n\nИз плана следует, что они захватили заставу Солнечного Источника, деревушку орков к северо-западу отсюда.\n\nОтправляйся на заставу Солнечного Источника и избавь мир от Ортора. Так будет лучше для всех...", progress = "Имей в виду, Савва: Ортор - могущественный шаман.", completion = "Говоришь, тысяча мертвых орков? Что могло вызвать столь дерзкое вторжение на орочьи земли? Я рад, что с этим мерзавцем покончено, но впереди нас ждет еще много серьезных дел.", rewards = "Восемьдесят серебряных звеньевПечные рукавицы Темной КровиНожные латы мстителя Темной КровиВы получите:\n\n"}
MultiLanguageQuestData['ru'][9874] = {title = "Остановить заразу", objective = "Сожгите 10 трупов жителей заставы Солнечного Источника с помощью факела жидкого огня. Когда исполните поручение, верните факел Отонбу Ведуну.", description = "Мне только что стало известно о катастрофе поистине устрашающего масштаба, <имя>. Эти мерзавцы из племени Темной Крови захватили орочью заставу Солнечного Источника... это к северо-западу отсюда... перебили всех тамошних жителей, а тела принялись сбрасывать в озеро Солнечного Источника. Если все эти тела начнут разлагаться в озере, наш главный источник пресной воды в этой области будет отравлен.\n\nЯ понимаю, что это работа не из приятных, но ее надо сделать. Возьми этот зачарованный факел, иди на заставу и сожги все трупы орков...", progress = "Орки нас не поймут. Но мы должны это сделать. Во имя общего блага – и орков, и Сломленных.", completion = "&lt;Отонбу вздыхает.&gt;\n\nПосле того что мы сделали, на ближайшие десять лет можно оставить всякую надежду заключить с орками мир. Но, во всяком случае, у нас будет шанс прожить это десятилетие. А если бы мы не уничтожили эти тела... даже страшно подумать, чем бы все это закончилось!", rewards = "Чешуйчатые поножи боевого заклинателяБригантина мстителя Темной КровиЛучезарная корона МелииВы получите:\n\n"}
MultiLanguageQuestData['ru'][9875] = {title = "Неизвестный науке вид", objective = "Принесите неизвестный науке вид Лоранне Тар'велл в Кенарийский приют в Зангартопи.", description = "А вот это растение Лоранна, очевидно, упустила из виду. Вы уверены, что обнаружили вид, еще не описанный Лоранной. Стоит показать это растение Лоранне и посмотреть, что она скажет.", progress = "Ты хочешь мне что-то показать?", completion = "Новый вид! Точно?\n\n&lt;Лоранна листает свои записи и таблицы.&gt;\n\nОтличная работа, Ондумм! Да, нам еще только предстоит занести этот вид в наши справочники. Как тебе нравится название \"Ондуммрий пурпурнолистный\"? Неплохо звучит, а?", rewards = nil}
MultiLanguageQuestData['ru'][9876] = {title = "Провалившийся рейд", objective = "По просьбе Исиэли Песни Ветра отыщите следы друидов из Кенарийской экспедиции у входа в Резервуар Кривого Клыка, что в Зангартопи.", description = "Я отправила небольшой отряд наших друидов, чтобы исследовать обнаруженную тобой трубу в Змеином озере. Я рассчитывала на их скорое возвращение. Нужно ли говорить, что они не вернулись до сих пор?\n\nТы – <один/одна> из самых способных наших союзников. Пожалуйста, отыщи их и выясни, что с ними стало.", progress = nil, completion = "Слава Кенарию, что ты здесь! Я не могла выбраться наружу из-за ран...", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][9877] = {title = "Приводящее в сознание зелье", objective = "Поговорите с аптекарем Рензитеном в Транквиллионе.", description = "В битве с Плетью не избежать потерь. Каждый день многие погибают, но еще большему числу выпадает куда более страшный удел.\n\nПлеть захватывает пленников. И лучше им умереть, чем испытать то, что ждет их в Смертхольме. Их допрашивают и пытают, используя ужасный, ломающий волю яд. \n\nАптекарь Рензитен из Транквиллиона разработал противоядие - ступай к нему и принеси его приводящее в сознание зелье.", progress = nil, completion = "Так, значит, Джанеда посылает тебя вызволить пленников Смертхольма? Стало быть, она высоко ставит тебя, Длекс.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9878] = {title = "Устранение проблемы", objective = "Убейте 10 падальщиков и 5 налетчиков из племени Темной Крови.", description = "Появление племени Темной Крови в Награнде отрицательно сказалось на наших землях. Стихии пришли в движение, что, в свою очередь, вызвало беспокойство среди животных. Мало того, разрушение заставы Солнечного Источника разбудило старую вражду между орками и моим народом.\n\nКуренай и Темная Кровь – разные племена, но орки видят в них лишь Сломленных.\n\nЭту проблему надо устранить. Отправляйся на северо-запад, на заставу Солнечного Источника, и реши этот вопрос.", progress = nil, completion = "Сомневаюсь, что орки поймут и оценят то, что ты для них сделал, но с этой поры Награнд станет намного чище. Спасибо тебе.", rewards = "Кюлоты зеленой кровиЕдкие щупальцаУбор темного шаманаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9879] = {title = "Тотем Кардаша", objective = "Помогите куренайскому пленнику бежать с заставы Солнечного Источника. Расскажите Арехрону из Телаара обо всем, что вам удалось узнать.", description = "Если бы не ты, <незнакомец/прекрасная незнакомка>, меня бы точно убили. Они перебили уже стольких куренаев в поисках своей утерянной реликвии!\n\nОни ищут тотем Кардаша. Не понимаю, с чего они взяли, что мы что-то знаем о нем. Этот тотем, как я понимаю, – реликвия орков, и уже в силу своей природы он может быть только орочьим орудием.\n\nЭти сведения нужно немедленно сообщить Арехрону. Быть может, он знает, почему Падшие из клана Темной Крови похищают куренаев и пытают их, чтобы добыть информацию об орудии орков.\n\nПомоги мне бежать.", progress = nil, completion = "Да, я знаю об этом тотеме... с ним связано очень многое. Однако это секретная информация, и я не вправе ее разглашать. Это опасное знание, которое можно доверить лишь немногим избранным.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9880] = {title = "Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin Cap", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПокровительство Оплота Чести\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][9881] = {title = "Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin Cap", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПокровительство Траллмара\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][9882] = {title = "Украсть у вора", objective = "Раздобудьте 10 осколков кристалла Ошу'гуна и отдайте их Гезхе в Небесном лагере в Награнде.", description = "Принц нексуса Харамад пока не разрешает нам работать внутри Ошу'гуна, поскольку это может разозлить некоторых влиятельных наару. Так что время идет, а работа стоит.\n\nНо я, кажется, нашел лазейку.\n\nПонимаешь, мы не единственные, кого тянет к этому гигантскому алмазу. Вор по имени Гава'кси возглавил банду головорезов, которые проникли в Ошу'гун и принялись откалывать от камня крупные куски.\n\nТвоя задача, <раса>, найти их и забрать то, что принадлежит нам по праву.", progress = "Ты принес осколки кристалла, Душавдушу?", completion = "Прекрасный цвет. И качество в основном отличное.\n\nЯ сообщу нашим людям, как ты нам помогаешь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9883] = {title = "Снова осколки кристалла", objective = "Ты принес осколки кристалла? Будь предельно внимателен и бери только те, которые откололись сами. Нам не нужны неприятности с наару.", description = nil, progress = "Ты принес осколки кристалла? Будь предельно внимателен и бери только те, которые откололись сами. Нам не нужны неприятности с наару.", completion = "Принеси нам еще осколков, Мияру. Все, которые сумеешь собрать. Нельзя позволять этим ворам расхищать нашу собственность.\n\nПусть даже она еще не совсем наша. Хотя, разумеется, уже почти наша. Во всяком случае, на бумаге.", rewards = nil}
MultiLanguageQuestData['ru'][9884] = {title = "Выгодное сотрудничество", objective = "Консорциум, как известно, не обижает своих друзей. В начале каждого месяца я буду тебе выдавать определенное количество самоцветов в счет оплаты услуг, которые ты нам окажешь.\n\nКачество самоцветов будет зависеть только от твоей преданности Консорциуму. Надеюсь, ты сделаешь правильный выбор и останешься с нами.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nНепомеченный мешок с самоцветами"}
MultiLanguageQuestData['ru'][9885] = {title = "Выгодное сотрудничество", objective = "Рад снова видеть тебя, Выручалкин. Вот твои самоцветы, плата за месяц.\n\nЯ там немного добавил сверх оговоренного... В знак нашего доброго расположения к тебе.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nНабитый самоцветами мешочек"}
MultiLanguageQuestData['ru'][9886] = {title = "Выгодное сотрудничество", objective = "Консорциум, как известно, не обижает своих друзей. В начале каждого месяца я буду тебе выдавать определенное количество самоцветов в счет оплаты услуг, которые ты нам окажешь.\n\nКачество самоцветов будет зависеть только от твоей преданности Консорциуму. Надеюсь, ты сделаешь правильный выбор и останешься с нами.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nНаполненный самоцветами конверт"}
MultiLanguageQuestData['ru'][9887] = {title = "Выгодное сотрудничество", objective = "Ба, Сабантул! Какие люди! Что такой важный господин делает в этом убогом местечке?\n\nКонечно, я уже приготовил камушки. Самоцветы высшего качества - не разбрасывайся ими попусту, |3-6(дворф).", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nМешок с превосходными самоцветами"}
MultiLanguageQuestData['ru'][9888] = {title = "Слабосильный владыка", objective = "Джорин Мертвый Глаз просит вас найти Килрата и поговорить с ним.", description = "Я избежал верной смерти. Эти трусливые сволочи из клана Тяжелого Кулака ночью напали на наш городок, и я чудом уцелел.\n\nНо скажи, <незнакомец/незнакомка>: кто виноват в нашей беде?!\n\n<Джорин указывает на Гарроша.>\n\nОн отказал нам в помощи. Огры разоряют мой город, а он сидит тут и размазывает сопли. Что с нами стало? Во что мы превратились?! И что будет дальше?\n\nЯ отправил разведчика Килрата в поселение, который теперь называют руинами Кровавой Глазницы. Сможешь разыскать Килрата и помочь ему, если нужно? Он скрывается на границе Награнда и леса Тероккар.", progress = nil, completion = "&lt;Килрат говорит, понизив голос.&gt;\n\nЭти огры какие-то странные... И на редкость тупые. Смотри, как тот толстый заставляет плясать тех, которые... э... менее толстые. Завораживающее зрелище.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9889] = {title = "Толстяка не убивать", objective = "Убейте 10 захватчиков из клана Тяжелого Кулака, затем избейте и допросите Анкора Безжалостного.", description = "Я уже несколько дней слежу за этими тварями. Толстяк говорит, что чего-то ждет. Чего конкретно – неизвестно.\n\nУ меня есть план, но тут придется применить насилие. Нужно убить нескольких его подчиненных, а потом избить его до полусмерти. После этого, я уверен, он выложит все, что нам надо узнать.", progress = "Я сдаюсь! Сдаюсь!", completion = "Не убивай меня, я все расскажу!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9890] = {title = "Готово!", objective = "Передайте все сведения, которые вы выбили из Анкора, Килрату в лес Тероккар.", description = "Долгие годы клан Тяжелого Кулака правил над всеми ограми в Запределье. При Кроле огры объединились и жили дружно. Они довольствовались теми землями, которые им были даны. Однако в последние месяцы многие огры погибли от рук их же сородичей из клана Боевого Молота. Этот клан захватил почти все наши земли в Награнде и перебил многих наших собратьев.\n\nМы должны были взять этот город. У нас просто не было выбора. Нас истребляют...\n\nКрол пропал без вести, клан Тяжелого Кулака в полной растерянности. Лантрезор Клинок правит в его отсуствие.", progress = nil, completion = "Эй, притормози, Джонниди... Я всего лишь скромный разбойник. Что мне делать с такими сведениями?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9891] = {title = "Потому что Килрат – трус", objective = "Передайте информацию, которую вы выбили из Анкора, Джорину Мертвому Глазу в Гарадаре.", description = "Расскажи обо всем Джорину в Гарадаре. Уверяю тебя, его не обрадует известие об уничтожении деревни и почти поголовном истреблении ее жителей из-за претензий огров на территорию.\n\nДа хранят тебя предки... Если я тебе снова понадоблюсь, я буду прятаться здесь в кустах. В общем, ты знаешь, где меня найти.", progress = nil, completion = "Они что, считают, у них есть право убивать орков и изгонять их с исконных земель? Надо думать, это никоим образом не связано с тем обстоятельством, что наш предводитель – сопливый щенок... Если бы в нем была хоть десятая доля той ярости, что полыхала в душе его отца...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9892] = {title = "Поиски обсидиановых боевых ожерелий", objective = "Хочешь добыть боевые ожерелья? Огров можно найти на дальнем севере, на границе с Зангартопью.", description = nil, progress = "Хочешь добыть боевые ожерелья? Огров можно найти на дальнем севере, на границе с Зангартопью.", completion = "Теперь мы получим хорошую прибыль, Вродехант. Я позабочусь о том, чтобы Хораади узнал, как ты нам помогаешь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9893] = {title = "Обсидиановое боевое ожерелье", objective = "Принесите 10 обсидиановых боевых ожерелий Гезхе в Небесный лагерь в Награнде.", description = "Гора Ошу'гун еще не готова к раскопкам, и мы теряем немалую прибыль, <имя>.\n\nК счастью, я обнаружил дополнительный источник дохода. Огры Награнда носят боевые ожерелья из обсидиана – минерала, который во многих мирах ценится весьма высоко.\n\nЗерид уже разобрался с парочкой этих громил - в интересах безопасности, разумеется. В данном случае ожерелья можно рассматривать как дополнительные премиальные... А еще лучше вообще никак их не рассматривать, а просто собрать и принести мне сюда.", progress = "Как тебя встретили эти огры, Щук? Надо думать, не слишком приветливо?", completion = "Замечательно. Теперь у нас есть чем заняться, пока Ша'тар не закончат необходимые приготовления в Ошу'гуне.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9894] = {title = "Защита наблюдателей", objective = "Убейте владыку Клака и вернитесь к призывательнице ветров Черное Копыто в Кенарийский приют.", description = "В твоих странствиях тебе наверняка случалось сталкиваться с наблюдателями экспедиции. Они выполняют колоссальное количество работы в поле: описывают уникальных обитателей болот, собирают образцы, устанавливают контакты с разумными существами.\n\nОбеспечение их безопасности – дело первостепенной важности, <класс>. Недавно из-за участившихся нападений болотных тварей нам пришлось отозвать наблюдателей, которых мы отправили в пещеру Грибгор. Страж Хамут полагает, что со смертью их предводителя владыки Клака атаки сразу должны прекратиться.", progress = nil, completion = "Я признательна тебе, Джонниди, и все наблюдатели тоже. Они воспрянут духом, узнав, что могут продолжать свои исследования на юге, не опасаясь нападений!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9895] = {title = "Гибнущее равновесие", objective = "Найдите Топехлыста и уничтожьте его, потом вернитесь к Летину Лунному Пламени в Кенарийский приют.", description = "Приглядись внимательно к природе вокруг нас, <имя>. Эти болота умирают. Они отчаянно борются за то, чтобы сохранить экологическое равновесие, но терпят поражение в этой борьбе.\n\nПризнаки этого очевидны, если знать, где искать. Представители отдельных видов достигают гигантских размеров и становятся все агрессивнее.\n\nВот взять, к примеру, болотоброда Топехлыста. Если хочешь на него посмотреть, далеко ходить не надо: достаточно выйти на болота к югу от Оплота.\n\nТолько без оружия не ходи! Эта тварь не ведает пощады.", progress = nil, completion = "Теперь ты своими глазами видел признаки нарушения равновесия. Не упускай их из виду в своих будущих странствиях.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9896] = {title = "Проклятие черной бракониды", objective = "Принесите жало черной бракониды геологу Коналлу в Телредор.", description = "Жарковато здесь, клянусь огненным чревом Каз'горота! Вполне понимаю первую экспедицию, которая отсюда сбежала. Впрочем, все знают, что сбежали они не из-за жары. Их выжила черная браконида, хотя, конечно, они в этом ни за что не признаются!\n\nОни встали лагерем на юг от светящихся дренейских башен, что к западу отсюда, чуть на север от деревни Дикотопь. И тут, откуда ни возьмись, появляется гигантская оса и нападает на них! Жду не дождусь увидеть, какие у них будут лица, когда я привезу в Стальгорн жало этой самой осы!", progress = "Ну что, удалось тебе добыть жало? Имей в виду, оно мне нужно целым и невредимым!", completion = "У меня просто слов нет, чтобы выразить, как я тебе благодарен! Ох, и потеха будет...", rewards = "Наплечники черной браконидыСтойкий ременьПерчатки черной браконидыСапоги болотного клыкаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9897] = {title = "Я спасена!", objective = "Отнесите сверток шкур Гарольду Лейну в лагерь Эрнестуэя в Награнде.", description = "Я не жадная. Могу поделиться. Главное, я спаслась от этого паршивца Ганкли! С Зангартопи я притащила целую тонну шкур, так что с меня не убудет!", progress = "Кристен такая приятная... (кашляет)... барышня... Правда? Шкурами вот поделилась... Очень мило с ее стороны.", completion = "Ну, меня там не было, так что я не знаю, действительно ли ты спас Кристен. Впрочем, если она поделилась с тобой шкурами – то больше мне ничего знать не надо.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9898] = {title = "Уважение к ближнему", objective = "Принесите жало черной бракониды Реавижу на заставу Болотной Крысы.", description = "Магаша – свирепая троллиха топи и жалует только могучих охотников.\n\nХочется произвести на нее впечатление, но мне не хватит сил одолеть такого лютого зверя, что заставил бы ее ахнуть. Ты мне не поможешь? На болотах живет гигантское насекомое, известное как черная браконида. Ее встречали к югу от светящихся дренейских башен, которые высятся на западе отсюда. Принеси жало этой осы, и тогда мне, может, разрешат стать ее охотником.\n\nПонимаю, что это не совсем по-честному, но я обещаю у нее учиться. Вы с Магашей сможете мной гордиться.", progress = "Скоро мне повезет, нутром чую!", completion = "Фантастика! Ты помог мне завоевать сердце Магаши. Я тебе этого не забуду! Ты будешь почетным гостем на нашей свадьбе.", rewards = "Наплечники черной браконидыСтойкий ременьПерчатки черной браконидыСапоги болотного клыкаВы получите:\n\n"}
MultiLanguageQuestData['ru'][9899] = {title = "Несделанное дело", objective = "Убейте Спорокрыла по просьбе Магаши с заставы Болотной Крысы.", description = "Хотелось бы, чтобы кто-нибудь нашел способ вразумить этого Реавижа! Он совершенно забыл про свои обязанности, а вместо этого посвящает все свое время и силы тому, чтобы добиться моего расположения. Я пыталась не обращать на него внимания, я умоляла его перестать, – ничто не помогает!\n\nА до тех пор, пока он не придет в себя, мне приходится разгребать за ним несделанную работу! Например, он должен был разобраться со Спорокрылом, но могу поручиться, что это чудовище до сих пор летает на свободе! Послушай, если у тебя есть время, не сходишь ли ты в западную часть Мертвой трясины, чтобы убить этого ската? А я пока что разберусь с Реавижем...", progress = nil, completion = "Ну, наконец нашелся хоть кто-то, кто готов делать дело! Спасибо тебе, Менгиле, что покончил с этой тварью. А мне надо будет поговорить насчет Реавижа с Зураем. Его фантазии и хитрости завели его чересчур далеко...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСвиток ловкости VIСвиток интеллекта VIСвиток защиты VIСвиток духа VIСвиток выносливости VIСвиток силы VI\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9900] = {title = "Гава'кси", objective = "Убейте Гава'кси, который скрывается близ Ошу'гуна, и возвращайтесь к Зериду в Небесный лагерь в Награнде.", description = "Присутствие эфириалов-мошенников в этих краях, может быть, и забавляет Гезхе, который во всем ищет выгоду... однако это серьезная угроза безопасности нашей операции.\n\nИх вождь Гава'кси – опасный преступник, и сейчас моя главная задача – нейтрализовать его как можно скорее.\n\nЕсли хочешь быть нам <полезным/полезной>, убей мерзавца Гава'кси. Я лично прослежу за тем, чтобы ты <получил/получила> достойное вознаграждение.", progress = nil, completion = "Теперь, когда ты прикончил Гава'кси, мы избавились от лишнего повода для беспокойства. Большое спасибо. А сейчас давай определимся с твоим вознаграждением.", rewards = "Старинный мушкет ЗеридаАстральный кушакВам дадут возможность выбрать одну из следующих наград:\n\nРеликвия Ошу'гуна\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9901] = {title = "Неоконченное дело", objective = "Убейте Спорокрыла по просьбе геолога Коналла из Телредора.", description = "Первая экспедиция, которую отправила сюда Лига, сообщала о встрече с гигантским зангарским скатом, которого они прозвали Спорокрылом. Экспедиции пришлось срочно уходить, поэтому они не успели убить этого ската, как собирались. Я же решил заняться этим.\n\nВ обрывках их отчета говорится, что это существо обитает в юго-западной части Мертвой трясины. Кажется, воздаятель Идаар упоминал, что это к северо-востоку от Телредора.", progress = nil, completion = "Молодец, Ишт! Мы с тобой опередили целый отряд горняков! Когда вернусь в Стальгорн, это поможет мне заметно продвинуться в карьере...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСвиток ловкости VСвиток интеллекта VСвиток защиты VСвиток духа VСвиток выносливости VСвиток силы V\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9902] = {title = "Ужас озера Болотных Огоньков", objective = "Убейте Жутеклешня и вернитесь к Пулуу в прибежище Оребор.", description = "Путешествуя по землям, захваченными нагами, я увидел, как обходятся там с моими собратьями, которым повезло меньше моего. На юго-западе озера Болотных Огоньков я наблюдал, как один особенно жестокий десятник играет в жуткую игру. Он отправляет своих рабов на острова, когда знает, что Жутеклешень, гигантский крабстер, вышел на охоту.\n\nЯ не стану описывать, чем заканчиваются эти игры. Нас слишком мало, чтобы напасть на наг, но мы, по крайней мере, можем лишить их любимой забавы, убив их страшного питомца!", progress = nil, completion = "Благодарю тебя, Гнарц. Быть может, в один прекрасный день с помощью дренеев это болото освободится от наг. Просто представить не могу, каково это - быть вынужденным служить им.\n\nМакту тоже когда-то был рабом. Он не любит об этом говорить...", rewards = "Бесстрашный ременьБроское оплечьеСапоги болотного бегунаСтрахотканое оплечьеВы получите:\n\n"}
MultiLanguageQuestData['ru'][9903] = {title = "Самый здоровенный", objective = "Убейте Мрагеша и вернитесь к Зурджайе в Забра'джин.", description = "Тебе удалось уничтожить большинство мелких гидр, но Мрагеш – дело другое! Это свирепая, коварная тварь, и в свое время он изводил многих рыбаков.\n\nНо я буду последней, кому он досаждает! Он прячется где-то в глубине Змеиного озера, на северо-востоке. Он уже покойник, хотя сам этого еще не знает!", progress = nil, completion = "Я уверена, старина понимал, что ему скоро конец. Теперь все так переменилось, что старым обитателям болот осталось жить недолго. Оно и к лучшему, что старик теперь покоится в мире.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЭликсир натискаЭликсир адепта\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9904] = {title = "Охота на Жутеклешня", objective = "Убейте Жутеклешня и вернитесь к Зурджайе в Забра'джин.", description = "Мне случалось ловить всякую рыбу, какая водится в озерах, но есть одна, которую мне поймать никак не удается. Конечно, я ловила и угрей, и илистых бешенок. Но в последний раз, как я удила на одном из островов на озере Болотных Огоньков, у меня клюнул огромный крабстер. Эта тварь перекусила мне леску и уплыла прочь.\n\nЕго зовут Жутеклешень, и я не успокоюсь, пока он не сдохнет! Он такой здоровый, что его ни одному рыбаку не поймать. Наверное, придется его просто укокошить по старинке.", progress = nil, completion = "Ну, наконец-то! Говорят, у всякого великого рыболова непременно есть история о здоровенной твари, которая перекусила леску и уплыла, но лично я еще ни разу не встречала такой рыбы, которую бы я не сумела одолеть, так или иначе.", rewards = "Бесстрашный ременьБроское оплечьеСапоги болотного бегунаСтрахотканое оплечьеВы получите:\n\n"}
MultiLanguageQuestData['ru'][9905] = {title = "Месть Макту", objective = "Найдите и убейте Мрагеша, и вернитесь к Макту в прибежище Оребор.", description = "В прошлый раз, когда Макту охотился на гидр на Змеином озере, на него напала самая здоровенная гидра, какую он видел в своей жизни. Макту потянулся было за копьем, но было слишком поздно. Гидра чудом не сожрала его.\n\nИ кто знает? Вдруг в следующий раз Макту повезет меньше? Макту хочет, чтобы следующего раза не случилось. Поможешь ли ты Макту отомстить этой гидре, Мрагешу?", progress = nil, completion = "&lt;Макту одобрительно кивает.&gt;\n\nМакту благодарит тебя за помощь. Его гордость успокоена. Больше его не застанут врасплох!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЭликсир натискаЭликсир адепта\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9906] = {title = "Клинок вместо слов", objective = "Джорин Мертвый Глаз из Гарадара в Награнде просит вас убить 8 сокрушителей и 8 мистиков из клана Тяжелого Кулака.", description = "Огры уважают лишь силу. Даже так: Силу с большой буквы. Если мы покажем им свою слабость, они тут же этим воспользуются и сметут нас с лица земли.\n\nВозможно, Гаррош готов сдаться на милость огрским псам, но только не я! Я буду драться до последней капли крови! И сейчас я посылаю тебя, <имя>, с посланием клану Тяжелого Кулака. Эти животные понимают только язык силы.\n\nОтправляйся в руины Пылающего Клинка, к юго-востоку отсюда, и покажи этим ограм, на что способны маг'хары.", progress = nil, completion = "Это только начало. Есть и другие, кому мы должны преподать урок!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9907] = {title = "Дерзкий набег", objective = "Джорин Мертвый Глаз из Гарадара в Награнде просит вас убить 10 воинов и 10 магов из клана Тяжелого Кулака.", description = "Прямо на западе отсюда лежит котловина Халаани. В котловине есть отроги-близнецы: расщелина Северного Ветра и расщелина Южного Ветра. В них огры из клана Тяжелого Кулака спрятали свои поселения.\n\nЯ хочу, чтобы ты <выследил и уничтожил/выследила и уничтожила> всех огров в этих расщелинах. Во имя маг'харов!", progress = nil, completion = "Уж если и это их не напугает - тогда нам не на что рассчитывать. Ты сослужил маг'харам достойную службу, Джонниди. И получишь достойную награду.", rewards = "Посох четырех золотых монетНаручи боевого священникаКоролевский оплотВы получите:\n\n"}
MultiLanguageQuestData['ru'][9910] = {title = "Страх и уважение", objective = "Установите по одному боевому штандарту маг'харов возле первого, второго и третьего погребальных костров клана Пылающего Клинка. Когда выполните поручение, верните Илкай'гану Мистику оставшиеся штандарты.", description = "Если ты собираешься в руины Пылающего Клинка, у меня есть для тебя поручение. Возьми эти боевые штандарты маг'харов и водрузи их на видном месте на территории огров. Лучше всего – где-нибудь на возвышении. Ищи гигантские погребальные костры на верхних уровнях. Помести по одному знамени возле первого, второго и третьего погребальных костров клана Пылающего Клинка.\n\nЭти знамена надолго запомнятся всем ограм, которые уклонились от битвы.", progress = "Боятся – значит уважают! Ты исполнил мое поручение?", completion = "Может, возьмешься еще за одну работенку? На этот раз, скажем так, более деликатного свойства?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9911] = {title = "Владыка болот", objective = "Принесите челюсть \"Графа\" Унгула наблюдательнице Лиса'о на Кенарийский караульный пост, что в Зангартопи.", description = "Эта окровавленная челюсть принадлежит гигантскому существу! Скат Пустоты, которому она принадлежала, должен быть самым огромным, какого когда-либо встречали в Зангартопи! Судя по состоянию челюсти, это существо – уже не падальщик, а хищник...\n\nКенарийская экспедиция наверняка заинтересуется подобным экземпляром. Обратитесь к наблюдательнице Лиса'о, которая живет в небольшом лагере к западу от гряды Квагг.", progress = "<Наблюдательница изумленно моргает.>\n\nОткуда у тебя... это?", completion = "Она что, действительно настоящая? Нет, я знаю, что на болотах встречаются очень крупные животные, но ведь это же великан какой-то!\n\nХотя, с другой стороны, спорлинги рассказывали байки о каком-то жутком скате Пустоты, который терроризировал их еще до появления болотников...\n\nМожет быть, это все же не байки, а правда? Ну надо же... Пожалуй, это надо сохранить. Экспедиция наверняка захочет знать об этом существе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9912] = {title = "Кенарийская экспедиция", objective = "Поговорите с Исиэль Песнью Ветра в Кенарийском приюте в Зангартопи.", description = "Главные представители Круга Кенария в Запределье – это Кенарийская экспедиция. Изначально она возникла как небольшой отряд, напрямую контролируемый Кругом Кенария. Но со временем экспедиция сделалась мощной, практически независимой организацией.\n\nГлава экспедиции, Исиэль Песнь Ветра, просила нас направлять добровольцев на ее базу. Она находится в Кенарийском приюте на востоке Зангартопи. Ступай по главной дороге, ведущей на запад, и она выведет тебя, куда нужно.", progress = nil, completion = "Добро пожаловать в Кенарийский приют, Выручалкин! Надеюсь, ты здесь затем, чтобы помогать нам? У нас тут дел по горло!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9913] = {title = "Консорциум ждет вас", objective = "Обратитесь к Гезхе. Его можно найти в Небесном лагере в Награнде.", description = "Консорциум заинтересован в предприимчивых сотрудниках вроде вас. Трудно найти более честных, работящих и милых в общении компаньонов, чем мы.\n\nВсе, что мы требуем, – это преданность, верность делу и достаточная моральная гибкость. Если вы заинтересовались, обращайтесь к Гезхе, руководителю операционного отдела. Его можно найти в Небесном лагере, к северу от Ошу'гуна.", progress = nil, completion = "Готов приступить к работе? У нас как раз есть для тебя отличное задание.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9914] = {title = "Кость на вес золота", objective = "Добудьте 3 пары бивней элекков и принесите их Шадреку в Небесный лагерь в Награнде.", description = "Кость элекка – материал весьма ценный. Мои постоянные клиенты из дальних краев уже встали в очередь и предлагают за материал хорошую цену.\n\nЯ готов поделиться с тобой долей прибыли, если ты будешь мне помогать.\n\nМне нужна кость высшего качества, а именно – бивни диких элекков, обитающих в Награнде. Кость самцов элекка не дотягивает до стандарта.\n\nИ не волнуйся, это не браконьерство. У меня есть твердая договоренность и с орками, и с дренеями.\n\nНу что, мы с тобой договорились?", progress = "Вот та самая кость, которая мне нужна. Только такая и никакая иная. Разумеется, если желаешь, мы можем пересмотреть наше давешнее соглашение насчет размера твоей доли прибыли. Однако я сомневаюсь, что ты будешь доволен результатом.", completion = "Я не сомневался в тебе ни секунды, дружище. Это именно то, что нужно, хотя бивни могли бы быть немного почище. И без царапин. Тем не менее, это хороший товар, и наш договор остается в силе.\n\nТы получишь оговоренную долю прибыли, и я очень надеюсь, что мы будем сотрудничать и в дальнейшем.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9915] = {title = "Кость на вес воздуха", objective = "Мне нужно еще несколько бивней диких элекков, обитающих в этом краю. К сожалению, мой бюджет больше не позволяет выплачивать тебе оговоренную долю прибыли. Но если ты будешь и дальше добывать для меня кость, ты заслужишь немалый почет и уважение в Консорциуме.", description = nil, progress = "Мне нужно еще несколько бивней диких элекков, обитающих в этом краю. К сожалению, мой бюджет больше не позволяет выплачивать тебе оговоренную долю прибыли. Но если ты будешь и дальше добывать для меня кость, ты заслужишь немалый почет и уважение в Консорциуме.", completion = "Отлично, отлично. Еще несколько превосходных бивней, хотя можно было и получше отыскать.\n\nТы заслужил безграничную признательность Консорциума, Небрить.", rewards = nil}
MultiLanguageQuestData['ru'][9916] = {title = "Припасы клана Кровавой Глазницы", objective = "Найдите 10 ящиков с припасами клана Кровавой Глазницы и принесите их Илкай'гану Мистику.", description = "Огры из клана Тяжелого Кулака спрятали украденные у нас припасы в расселинах Награнда, к западу отсюда, в котловине Халаани.\n\nРаз уж ты все равно туда отправляешься, поищи сундуки с припасами. Если удастся их вернуть, это сильно облегчит жизнь нашим матронам в Гарадаре.", progress = "Дети смогут протянуть еще один день без еды...", completion = "Почти все наши пожитки либо погибли, либо были украдены при нападениях. Я мало что могу тебе предложить, но кое-что интересное у меня есть... Оно тебе наверняка пригодится...", rewards = "Палка дрессировщика огровТуфли крушителя огровВам дадут возможность выбрать одну из следующих наград:\n\nЗнак огра-изверга\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9917] = {title = "Не верь глазам своим", objective = "Добудьте планы клана Тяжелого Кулака для охотницы Бинтук из Телаара.", description = "То ли зрение меня подводит, то ли там вдалеке и вправду огры? Как это они забрались так далеко от своего холма? Мне это очень не нравится, <странник/странница>. Сначала Темная Кровь, теперь огры. Нам просто не справиться со всеми напастями.\n\nПопробуй разузнать, почему огры забрались на восток. Их передовой лагерь где-то в 200 шагах восточнее отсюда. Увидишь охотников из клана Тяжелого Кулака – значит, <добрался/добралась> до места. Перебей всех и забери их планы вторжения.", progress = "Есть какие-то новости?", completion = "&lt;Бинтук просматривает планы.&gt;\n\nВо имя Света! Почерк отвратительный. Не могу понять, то ли они собираются \"съесть синекожих и захватить их деревню\", то ли испечь пирог с голубикой. И так и так можно прочесть. Надо с этим разобраться!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9918] = {title = "Только не в мою смену!", objective = "Поговорите с Глыбом. Когда получите необходимые сведения, возвращайтесь к охотнице Бинтук.", description = "План сражения составил кто-то из лейтенантов-огров по имени то ли Грыб, то ли Глыб.\n\n<Бинтук переворачивает пергамент и склоняет голову набок.>\n\nИли вообще Билли.\n\nКак бы там ни было, тебе надо пойти и переговорить с этим Билли, или Глыбом, или Грыбом, или как там его! Только не надо сразу стучать ему по голове. Для начала попробуем дипломатичный подход. Ну а уж если совсем ничего не получится, тогда можешь применить силу.", progress = nil, completion = "Вот черт! Говоришь, небольшой разведывательный отряд? Надо немедленно сообщить Мо'мору!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9919] = {title = "Спореггар", objective = "Отправляйтесь в Спореггар, что в Зангартопи, к северу от Грибной поляны, и отнесите спасенные мешочки спор Мссхи'фну.", description = "Ты <добрый/добрая:r> <раса>, <имя>. Не как другие, с которыми я встречался.\n\nТебе стоит встретиться с моими сородичами - они будут очень благодарны тебе за помощь. Отнеси эти мешочки со спорами к нашему предводителю, Мссхи'фну. Ты найдешь его в Спореггаре, к северу отсюда.", progress = "Ты хочешь мне что-то показать, Джонниди?", completion = "Нежить, ты помог защитить новое поколение спорлингов! Мы можем тебе отплатить только одним: пригласив в свои дома. Поживи у нас, познакомься с другими спорлингами. Они захотят тебя о многом расспросить – но ты, надеюсь, не будешь против?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9920] = {title = "Мо'мор Разрушитель", objective = "Охотница Бинтук из Телаара хочет, чтобы вы поговорили с Мо'мором Разрушителем.", description = "Надо немедленно рассказать обо всем Мо'мору! Ты найдешь его в центре Телаара, у фонтана. Перескажи ему все, что сказал тебе огр.", progress = nil, completion = "&lt;Мо'мор озадаченно хмурится.&gt;\n\nСтало быть, новый клан огров оттесняет клан Тяжелого Кулака все дальше и дальше на юг. Это тревожные новости. Сначала мы должны разобраться с опасностью, грозящей нашему дому...", rewards = nil}
MultiLanguageQuestData['ru'][9921] = {title = "Руины Пылающего Клинка", objective = "Мо'мор Разрушитель из Телаара желает, чтобы вы убили 8 мистиков и 8 сокрушителей из клана Тяжелого Кулака.", description = "Эти вылазки огров – явные предвестники большого вторжения. Мы должны нанести им удар до того, как они соберут армию для атаки на город.\n\nЕсли ты не боишься испачкать руки, у меня есть для тебя поручение, <раса>.\n\nСамый крупный отряд клана Тяжелого Кулака расположился сейчас в руинах Пылающего Клинка, почти прямо к востоку от Телаара, на границе леса Тероккар. Иди туда и покажи этим мерзавцам, что Телаар никогда не подчинится их воле!", progress = nil, completion = "Отлично. Кстати, тебе удалось обнаружить Лантрезора, о котором было упомянуто в письме этого болвана?\n\nКак бы там ни было, это еще далеко не конец. Мне донесли, что огры опять что-то затевают, так что у нас есть чем заняться в ближайшее время!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9922] = {title = "Расселины Награнда", objective = "Мо'мор Разрушитель из Телаара желает, чтобы вы убили 10 воинов и 10 магов клана Тяжелого Кулака.", description = "Твоя сила изумляет, <имя>! Ты <готов/готова> к новым подвигам?\n\nМне донесли, что большой отряд огров из клана Тяжелого Кулака скрывается в расселинах Награнда, в котловине Халаани к северо-западу отсюда.\n\nСпустись в расселины и разберись с ограми.", progress = nil, completion = "Отлично сработано! Я сейчас собираю сведения о клане Боевого Молота, о котором упоминал лейтенант из клана Тяжелого Кулака. Ты проделал большую работу, пришло время проверить ее результаты.", rewards = "Посох четырех золотых монетНаручи боевого священникаКоролевский оплотВы получите:\n\n"}
MultiLanguageQuestData['ru'][9923] = {title = "На помощь!", objective = "Найдите ключ клана Тяжелого Кулака и освободите Корки. После этого отправляйтесь к Арехрону в Телаар за наградой.", description = "НА ПОМОЩЬ! Они сожрут меня заживо! Точно-точно сожрут, я знаю!\n\nНайди ключ. Он у кого-то из этих огров.\n\nЕсли поможешь мне выбраться отсюда, мой отец щедро тебя наградит! Я – сын Арехрона, владыки Телаара.", progress = nil, completion = "Мне очень жаль, |3-6(человек), что все так получилось. У моего дорогого сыночка редкий талант находить приключения на свою голову. Ладно, будет ему приключение... розгой по мягкому месту...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9924] = {title = "Корки снова пропал!", objective = "Найдите и освободите Корки.", description = "<Арехрон вздыхает.>\n\nМне даже как-то неловко... Помнишь моего сына Корки? Недавно ты <спас/спасла> его из руин Пылающего Клинка. Так вот, его неуемное любопытство вновь вонзило ему шило в то самое место. Он заявил мне, что собирается провести небольшое расследование для \"дядюшки\" Мо'мора и убежал на курганы огров в котловину Халаани, к северу отсюда.\n\nСможешь его разыскать и вернуть? Я буду безмерно тебе благодарен.", progress = nil, completion = "Большое спасибо, Модерам. А Корки теперь займется его матушка. Может, хоть она его вразумит.", rewards = "Сапоги специалистаЖезл счастьяВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1Объединяющий оберег\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9925] = {title = "Вопросы безопасности", objective = "Убейте 8 отроков Бездны поблизости от Ошу'гуна по просьбе Зерида из Небесного лагеря.", description = "Гезхе разместил нас как можно ближе к Ошу'гуну, совсем не заботясь о безопасности команды. Почему? Да просто он посчитал, что тут он сможет заработать на десять процентов больше, чем если бы мы расположились в горах к югу отсюда.\n\nНаплевать на бешеных отроков Бездны, которые шастают буквально в десяти шагах от нас. Это же проблема службы безопасности, а не Гезхе.\n\nВот что. Перебьешь отроков Бездны – получишь десятую долю денег, выделенных на охрану. И не слишком радуйся: денег там ворг наплакал.", progress = nil, completion = "Благодаря тебе, Выручалкин, мое лицо вновь озарилось улыбкой. То есть озарилось БЫ, будь у меня лицо. Продолжай в том же духе, и мы станем лучшими друзьями.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9927] = {title = "Безжалостное коварство", objective = "По поручению Лантрезора Клинка из Руин Пылающего Клинка в Награнде вонзите 10 знамен клана Боевого Молота в тела защитников бастиона Вечной Скорби.\n\nВерните Лантрезору Клинку оставшиеся знамена.", description = "<Лантрезор вручает вам ранец, набитый знаменами.>\n\nЭто – знамена огров из клана Боевого Молота, которыми я недавно разжился в немалых количествах.\n\nОтправляйся в бастион Вечной Скорби, прямо к югу отсюда, и убей всех поганых прихвостней Совета Теней, которые встретятся тебе на пути. Вонзи древко знамени в сердце каждого убитого защитника бастиона. Потом возвращайся ко мне.", progress = "<Глаза Лантрезора широко раскрываются от изумления.>\n\nТы все сделал?!", completion = "Надо думать, они были изрядно удивлены, |3-6(нежить)? Ты потрудился на славу!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9928] = {title = "Военная хитрость", objective = "Принесите Лантрезору Клинку в руины Пылающего Клинка 10 ящиков с оружием бастиона Вечной Скорби.", description = "Чтобы мой план сработал, мне нужно, чтобы ты <выкрал/выкрала> оружие из бастиона Вечной Скорби.\n\nОбыщи крепость. Ищи сундуки с оружием из бастиона Вечной Скорби. Все, что найдешь, неси мне.\n\nБастион расположен прямо на юге и чуть к западу от руин Пылающего Клинка.", progress = "Мы разожжем пламя доселе невиданной ненависти между этими двумя кланами!", completion = "Замечательно! Наша следующая мишень – руины Веселого Черепа.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9931] = {title = "Взаимная вежливость", objective = "По поручению Лантрезора Клинка из Руин Пылающего Клинка в Награнде воткните 10 знамен Вечной Скорби в трупы огров клана Боевого Молота, обитающих в руинах Веселого Черепа.\n\nОставшиеся знамена верните Лантрезору.", description = "Теперь мы дадим хорошего пинка этим жирным тупицам из клана Боевого Молота. На северо-западе, у горного кряжа, ты найдешь руины Веселого Черепа.\n\n<Лантрезор указывает на содержимое сундука с оружием, который вы ему принесли.>\n\nУзнаешь? Это знамена Вечной Скорби. Возьми их с собой и воткни по одному знамени в трупы огров из клана Боевого Молота. Помнишь, где их найти? На северо-западе.", progress = "Сможешь предугадать, что будет дальше?", completion = "У меня отличный план, Щук. Я уже вижу, каковы будут плоды твоих трудов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9932] = {title = "Вещественное доказательство", objective = "По поручению Лантрезора Клинка из руин Пылающего Клинка в Награнде найдите костер клана Боевого Молота во внутреннем дворе руин Веселого Черепа. С помощью мокрого шерстяного одеяла подайте дымовой сигнал ограм.", description = "Твоя вылазка в бастион Вечной Скорби открыла нам новые возможности. Теперь у нас есть целая куча мертвых тел, с помощью которых можно инсценировать великую битву.\n\nОтправляйся на внутренний двор руин Веселого Черепа. Там горит костер. Убедись, что поблизости никого нет, и воспользуйся этим одеялом, чтобы подать дымовые сигналы. Когда мои огры увидят дым, они проникнут туда и живописно разложат повсюду трупы убитых защитников бастиона.\n\nЭто добьет наших врагов!", progress = "Теперь ты понимаешь, почему меня невозможно победить?", completion = "Давненько я ничего подобного не проворачивал! Спасибо за помощь, Щук!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9933] = {title = "Послание в Телаар", objective = "Отнесите мирное подношение Пылающего Клинка Арехрону в Телаар, что в Награнде.", description = "<Лантрезор указывает на сундук.>\n\nВозьми его. Это мой дар твоему народу. Ты <один/одна>, без какой-либо помощи, <спас/спасла> мой клан от истребления.\n\nСкажи своему предводителю, что Лантрезор из клана Пылающего Клинка и огры из клана Тяжелого Кулака принимают его предложение о мире.\n\n<Лантрезор склоняется в поклоне.>", progress = "Значит, мир?", completion = "Ты заслужил награду, Мерандир. Бери все, что хочешь, из этих даров. В конце концов, если бы не ты, никаких бы даров и не было.", rewards = "Боевой клинок ЛантрезораКушак почитателя из клана Пылающего КлинкаВам дадут возможность выбрать одну из следующих наград:\n\nКольцо сектанта из клана Пылающего Клинка\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9934] = {title = "Послание в Гарадар", objective = "Отнесите мирное подношение клана Пылающего Клинка Гаррошу в Гарадар.", description = "<Лантрезор указывает на сундук.>\n\nВозьми его. Это мой дар твоему народу. Ты <один/одна>, без какой-либо помощи, <спас/спасла> мой клан от истребления.\n\nСкажи своему предводителю, что Лантрезор из клана Пылающего Клинка и огры из клана Тяжелого Кулака принимают его предложение о мире.\n\n<Лантрезор склоняется в поклоне.>", progress = "<Гаррош, похоже, не рад подаркам.>", completion = "&lt;Гаррош с пренебрежением пинает сундук.&gt;\n\nТы только зря тратишь время, |3-6(орк). Бери все, что хочешь, из этого сундука. Или вообще забирай все, что есть. Ни мне лично, ни Гарадару не нужны эти никчемные побрякушки.", rewards = "Боевой клинок ЛантрезораКушак почитателя из клана Пылающего КлинкаВам дадут возможность выбрать одну из следующих наград:\n\nКольцо сектанта из клана Пылающего Клинка\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9935] = {title = "Разыскивается: Гизельда Колдунья", objective = "Убейте Гизельду Колдунью и 10 любых служителей бастиона Вечной Скорби. Получите награду у стража-смотрителя Быккрока в Гарадаре.", description = "Разыскиваются:\n\nГизельда Колдунья из бастиона Вечной Скорби и ее приспешники по обвинению в убийствах, ритуальных жертвоприношениях, пособничестве Легиону, похищении мирных граждан и многочисленных кражах со взломом.\n\nВ настоящее время скрывается в бастионе Вечной Скорби в юго-восточном Награнде, на окраине леса Тероккар.\n\nТот, кто сумеет поймать преступницу и предать ее в руки правосудия, получит награду от стража-смотрителя Быккрока в Гарадаре.", progress = nil, completion = "Мегера мертва! Отличные новости, Щук. Вот твоя награда.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9936] = {title = "Разыскивается: Гизельда Колдунья", objective = "Убейте Гизельда Колдунью и 10 любых служителей бастиона Вечной Скорби. Получите награду у стража-смотрителя Мой'прна Джилла в Телааре.", description = "Разыскивается:\n\nГизельда Колдунья из бастиона Вечной Скорби и ее приспешники по обвинению в убийствах, ритуальных жертвоприношениях, пособничестве Легиону, похищении мирных граждан и многочисленных кражах со взломом.\n\nВ настоящее время скрывается в бастионе Вечной Скорби в юго-восточном Награнде, на окраине леса Тероккар.\n\nТот, кто сумеет поймать преступницу и предать ее в руки правосудия, получит награду от стража-смотрителя Мой'прна Джилла в Телааре.", progress = nil, completion = "Мегера мертва! Отличные новости, Изуку. Вот твоя награда.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9937] = {title = "Разыскивается: Дарн Ненасытный", objective = "Убейте Дарна Ненасытного. Вернитесь к стражу-смотрителю Быккроку и получите награду.", description = "Ты <уничтожил/уничтожила> двух величайших злодеев, угрожавших Награнду, <имя>. Ты <готов/готова> сразиться с Дарном Ненасытным, истинным бедствием Полей Духов?\n\nДарн Ненасытный бесчинствует на землях, окружающих Ошу'гун, неся погибель всем на своем пути. Пока что никто не сумел избавить Награнд от этого лютого гронна. Отправляйся на Поля Духов далеко к юго-западу отсюда. У самого Ошу'гуна разыщи Дарна и убей его. Это будет нелегко, но награда за подвиг тебя не разочарует.", progress = nil, completion = "Ты избавил Награнд от страшной угрозы. Ты – настоящий герой, поистине величайший из всех!", rewards = "Кристаллический копешКостяная дубинка алчностиЛазурный легкий клинокВы получите:\n\n"}
MultiLanguageQuestData['ru'][9938] = {title = "Разыскивается: Дарн Ненасытный", objective = "Убейте Дарна Ненасытного. Вернитесь к стражу-смотрителю Мой'прну Джиллу и получите награду.", description = "Ты <уничтожил/уничтожила> двух величайших злодеев, угрожавших Награнду, <имя>. Ты <готов/готова> сразиться с Дарном Ненасытным, истинным бедствием Полей Духов?\n\nДарн Ненасытный бесчинствует на землях, окружающих Ошу'гун, неся погибель всем на своем пути. Пока что никто не сумел избавить Награнд от этого лютого гронна. Отправляйся на Поля Духов к западу отсюда, там разыщи Дарна и убей его. Это будет нелегко, но награда за подвиг тебя не разочарует.", progress = nil, completion = "Ты избавил Награнд от страшной угрозы. Ты – настоящий герой, поистине величайший из всех!", rewards = "Кристаллический копешКостяная дубинка алчностиЛазурный легкий клинокВы получите:\n\n"}
MultiLanguageQuestData['ru'][9939] = {title = "Разыскивается: Зорбо Советчик", objective = "Убейте Зорбо Советчика, 5 шаманов и 5 разорителей из клана Боевого Молота. Получите награду у стража-смотрителя Быккрока.", description = "Разыскивается живым или мертвым!\n\nЗорбо Советчик разыскивается за организацию ряда спланированных нападений на Гарадар. При содействии разрушителей и шаманов преступник убил бессчетное количество орков. Зорбо вооружен, беспощаден и очень опасен.\n\nСейчас он скрывается в руинах Веселого Черепа в северных горах Награнда.\n\nУбивший или поймавший Зорбо Советчика может обратиться за наградой к стражу-смотрителю Быккроку в Гарадаре.", progress = "Ты пришел за наградой?", completion = "Это великая победа для Гарадара! Ты – настоящий герой, Душавдушу!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9940] = {title = "Разыскивается: Зорбо Советчик", objective = "Убейте Зорбо Советчика, 5 шаманов и 5 разорителей из клана Боевого Молота. Получите награду у стража-смотрителя Мой'прна Джилла.", description = "Разыскивается живым или мертвым!\n\nЗорбо Советчик разыскивается за организацию ряда спланированных нападений на Телаар. При содействии разрушителей и шаманов преступник убил бессчетное количество Сломленных. Зорбо вооружен, беспощаден и очень опасен.\n\nСейчас он скрывается в руинах Веселого Черепа в северных горах Награнда.\n\nУбивший или поймавший Зорбо Советчика может обратиться за наградой к стражу-смотрителю Мой'прну Джиллу в Телаар.", progress = nil, completion = "Это великая победа для Телаара! Ты - герой, Модерам!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9944] = {title = "Пропавший маг'харский караван", objective = "Найдите пропавший маг'харский караван.", description = "Великая мать говорит, что мы не должны сидеть сложа руки. Мы должны подать пример Гаррошу – показать, что жизнь продолжается, несмотря ни на что.\n\nУ меня столько дел... особенно после того, как великая мать заболела. Может быть, ты окажешь честь маг'харам и поможешь мне?\n\nНесколько дней назад мы отправили похоронную процессию в Земли Предков, и она до сих пор не вернулись. Ты поможешь нам ее разыскать? Процессия ушла на запад от Гарадара. Иди по ее следам, но не заходи в Халаа.", progress = nil, completion = "Тридцать орков, |3-6(нежить)! Из тех тридцати в живых остались лишь Унгриз да я. Мы нашли молодого орка, Саурфанга, близ заставы Солнечного Источника. Он был едва жив. Как я понимаю, он случайно попал ограм под горячую руку...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9945] = {title = "Войной на Боевой Молот", objective = "Старейшина Йорли из Маг'харского Каравана в Награнде попросил вас убить 8 громил и 8 чернокнижников клана Боевого Молота.", description = "Мы направлялись в земли Предков, когда нас окружили огры из клана Боевого Молота. Они напали одновременно со всех сторон, убили нескольких воинов из похоронной процессии и многих других. Более того, они осквернили останки старейшины, покоившиеся в катафалке.\n\nСпрашивается, зачем? Чтобы унизить нас и продемонстрировать свою силу? Даже огры из клана Тяжелого Кулака до такого бы не опустились.\n\nЯ - благочестивый и праведный орк, <имя>, но у всякого терпения есть пределы. Ты найдешь этих негодяев к северо-западу отсюда, у холма Боевого Молота. Уничтожь их всех!", progress = nil, completion = "Для начала неплохо, но надо еще разобраться с их вожаком, чтобы закрепить результат.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9946] = {title = "Чо'вар Погромщик", objective = "Убейте Чо'вара Погромщика и принесите его голову старейшине Йорли в Маг'харский Караван.", description = "Доводилось ли тебе, <раса>, встречаться с главарем огров? Немногие остались в живых после такой встречи. Но я в тебя верю.\n\nГлаварь этих варваров – огр по имени Чо'вар. Поговаривают, что именно он выгнал гронна из пещеры. Потом Чо'вар объявил себя королем и распустил кланы огров, которыми правил гронн. Так появился клан Боевого Молота.\n\nРазыщи Чо'вара в глубинах пещер холма Боевого Молота, убей негодяя и принеси мне его голову.", progress = "Его наверняка хорошо охраняют.", completion = "Его голову выставят на всеобщее обозрение у ворот Гарадара. В следующий раз огры сто раз подумают, прежде чем прерывать священные ритуалы маг'харов.", rewards = "Убор истребителя огровВам дадут возможность выбрать одну из следующих наград:\n\nКольцо истребителя огровПодвеска истребителя огров\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9948] = {title = "Спасательная экспедиция", objective = "Освободите 5 пленных маг'харов по просьбе старейшины Унгриза из маг'харского каравана в Награнде.", description = "Огры обожают свежатинку, уж я-то знаю. А это значит, что маг'харов, которых они захватили, скорее всего, держат живыми, пока не придет время подать их к столу. Мерзко звучит, но нет худа без добра.\n\nПроберись к холму Боевого Молота и отыщи там пленных маг'харов. Ключи от их клеток, скорее всего, хранятся у огров из клана Боевого Молота, шатающихся где-то поблизости.\n\nУбей этих огров, забери ключи и освободи пленников.", progress = nil, completion = "Ты совершил невозможное, и наши братья и сестры снова с нами. Ты - благодетель маг'харов, Джонниди. Твое имя и подвиги навсегда останутся в наших сердцах.", rewards = "Оковы памятиПлащ поборника Боевого МолотаВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #5Кольцо наемника Боевого Молота\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9951] = {title = "Он следит за тобой!", objective = "Убейте Нафталара и вернитесь к хранителю Древлосу в перелесок Кенария в лесу Тероккар.", description = "Скорее, прячьтесь! Нафталар следит за вами... за всеми нами следит!\n\nЯ не смею взбираться на башню и говорить с ним, но вы... вы, похоже, знаете нужные слова. Только будьте осторожны – он не любит шуток и быстр на расправу с дураками.\n\nЕсли сможете, уговорите его спуститься и попить чайку... Но в любом случае, сделайте что-нибудь, чтобы он перестал на меня смотреть!", progress = "Не надо нам было приглашать его на ужин, это точно!\n\nИли, по крайней мере, надо было настоять хотя бы на паре блюд перед десертом, который они принесли!", completion = "Ну что ж, это только к лучшему. Если ему не хватает вежливости принять приглашение, значит, больше не будем его звать.\n\n&lt;На лице хранителя Древлоса на миг застывает растерянное выражение.&gt;\n\nКто вы и что здесь делаете? Уходите отсюда, пока не стало слишком поздно!", rewards = "Безумный кенарийский плащЛунные поручиКлинок безумцаВам дадут возможность выбрать одну из следующих наград:\n\nСчастливый венец дуракаКолье безумца\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9954] = {title = "Выкуп за Корки", objective = "Арехрон просит вас найти Корки на холме Боевого Молота.", description = "Арехрон показывает вам письмо на заляпанном грязью листе бумаги.*\n\nЭто от огров из клана Боевого Молота, который правит северо-западными землями Награнда. Они пишут, что захватили в плен Корки, и требуют выкуп. Грозятся съесть его, если мы не согласимся на их условия. Корки, конечно, редкостный идиот, но он все же мой сын, плоть от плоти, и так далее. Ты спасешь его, <имя>?\n\nКак я понимаю, его держат в клетке где-то на холме Боевого Молота.", progress = nil, completion = "На этот раз они меня заперли надежно, Модерам. А ключ - у Чо'вара, главы Боевого Молота.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9955] = {title = "Чо'вар Погромщик", objective = "Найдите Чо'вара, отберите у него ключ и освободите Корки из клетки. После этого отправляйтесь к Арехрону в Телаар за наградой.", description = "Его называют Чо'вар Погромщик, <имя>. Именно он сверг гронна, который правил местным кланом огров. Он действительно очень силен, об этом следует помнить!\n\nГоворят, Чо'вар живет в огромной пещере... знать бы еще, где она находится... Возьми ключ от клетки и освободи меня! Если ты мне поможешь отсюда выбраться, мой отец щедро тебя наградит! А потом можешь заняться поисками Чо'вара.", progress = nil, completion = "Спасибо, Изуку. Мы отправили Корки к ночным эльфам в Острогорье. Будем надеяться, они присмотрят за ним и сумеют уберечь его от неприятностей.\n\nТеперь, что касается твоей награды...", rewards = "Убор истребителя огровВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1Кольцо истребителя огровПодвеска истребителя огров\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9956] = {title = "Разграбленный караван", objective = "Помогите охотнице Киме вернуть 10 телаарских ящиков с припасами.", description = "Я сопровождала караван, направлявшийся в прибежище Оребор в Зангартопи. На подходе к болотам на нас напали огры из клана Боевого Молота. Они забрали груз, перебили всех наших, а меня взяли в плен.\n\nК счастью, они не озаботились тем, чтобы укрепить замок моей клетки. Когда они все заснули, мне удалось выбраться и сбежать.\n\nМоих мертвых товарищей уже не спасти, но мы можем хотя бы забрать груз из разграбленного каравана. Огры спрятали краденое на холме Боевого Молота в горах на северо-западе Награнда.", progress = "Вот незадача... Корки, сын Арехрона, спросил меня, что случилось. Выслушав новости, он снова пропал!", completion = "Поразительно! Как тебе удалось утащить это все в одиночку?!", rewards = "Оковы памятиПлащ поборника Боевого МолотаВам дадут возможность выбрать одну из следующих наград:\n\nКольцо наемника Боевого Молота\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9957] = {title = "Что случилось в перелеске Кенария?", objective = "Поговорите с одним из друидов в перелеске Кенария в лесу Тероккар.", description = "От друидов из Перелеска Кенария в лесу Тероккар уже давно нет никаких вестей.\n\n<имя>, я бы хотел, чтобы вы сходили туда и узнали, что происходит. В чащобу ведет несколько дорог, но быстрее всего будет пойти сначала на юг, а потом, когда доберетесь до леса, свернуть на дорогу, что идет на восток от Шаттрата.", progress = nil, completion = "Хорошо, что к нам хоть кого-то прислали. Всех местных друидов убили! Выжить удалось только мне и еще одному, да и тот сошел с ума.\n\nНе знаю, что тут стряслось, но обязательно докопаюсь до правды. Что бы это ни было, все случилось очень быстро и оставило ощущение какой-то неестественности.\n\nВы мне поможете?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9960] = {title = "Что случилось в перелеске Кенария?", objective = "Поговорите с одним из друидов в перелеске Кенария в лесу Тероккар.", description = "Здравствуй, <класс>. От друидов из перелеска Кенария уже давно нет никаких вестей.\n\nЯ прошу тебя отправиться туда и узнать, что с ними случилось. Это место к северо-западу отсюда, если ехать через лес.", progress = nil, completion = "Очень хорошо, что из форта Камнеломов кого-то наконец прислали! Всех друидов убили, выжить удалось только мне и еще одному, да и тот сошел с ума.\n\nНе знаю, что случилось, но я обязательно это расследую! Что бы это ни было, все случилось очень быстро, и оставило чувство какой-то неестественности.\n\nВы мне поможете?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9961] = {title = "Что случилось в перелеске Кенария?", objective = "Поговорите с одним из друидов в перелеске Кенария в лесу Тероккар.", description = "<класс>, у меня к тебе важное дело. От друидов из перелеска Кенария уже давно нет никаких вестей, и это тревожит меня, потому что раньше они связывались с нами довольно часто.\n\nЯ прошу тебя отправиться туда и проверить, все ли с ними в порядке. Перелесок находится к северо-западу отсюда, если ехать через лес.", progress = nil, completion = "Очень хорошо, что из бастиона Аллерии кого-то наконец прислали! Всех друидов убили, выжить удалось только мне и еще одному, да и тот сошел с ума.\n\nНе знаю, что случилось, но я обязательно докопаюсь до правды! Что бы это ни было, все случилось очень быстро, и оставило чувство какой-то неестественности.\n\nТы мне поможешь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9962] = {title = "Кольцо Крови: Хромоног", objective = "Одержите победу над Хромоногом. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.", description = "Ты <готов/готова> к своей первой битве? Дай мне знать, и я объявлю о начале боя. Тебе останется только ждать в Кольце Крови, когда появится твой противник.\n\nТы будешь сражаться против Хромонога, свирепого копытня.\n\nУдачи! Надеюсь, ты <привел/привела> с собой верных друзей.\n\nИ помни, поединок закончится только тогда, когда кто-то из вас – либо ты, либо соперник – упадет на арену и больше не встанет.", progress = "Поединок закончится только тогда, когда один из вас упадет замертво.", completion = "Гм... неплохо, неплохо... У тебя очень хорошие данные, малыш. Вот тебе немного золота – пусть звенит в карманах.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9967] = {title = "Кольцо Крови: братья Блю", objective = "Одержите победу над близнецами из племени Темной Крови, которые называют себя \"Братья Блю\". После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.", description = "В следующей схватке тебе придется сразиться сразу с двумя противниками - а точнее, с братьями-близнецами. Они называют себя \"Братья Блю.\"\n\nЕще не поздно отказаться от боя, <имя>. Если откажешься, я пойму.\n\nНо если ты <готов/готова> драться, тогда войди в Кольцо Крови и жди выхода близнецов из племени Темной Крови.\n\nКто упал и не поднялся, тот проиграл. Кто устоял, тот победитель!", progress = "Поединок закончится только тогда, когда один из вас упадет замертво.", completion = "Честно признаюсь, я уже и не верил, что ты победишь, Джонниди! Это было потрясающе! Не хочешь сразиться еще раз? У Гаргтока есть для тебя достойный противник.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9968] = {title = "Странная энергия", objective = "Соберите 4 образца пухоспинки и 4 образца агрессивной пухоспинки для землепряда Тавгрена. Его можно найти возле Перелеска Кенария в лесу Тероккар.", description = "Живущие в чащобе пухоспинки почему-то изменились.\n\nРаньше там бурлила жизнь, но теперь остались только эти бабочки, и если раньше они были очень мирными, то теперь нападают на всякого, кто приблизится к ним.\n\nМне нужно сравнить агрессивных пухоспинок с нормальными, а для этого мне понадобятся образцы и тех, и других. Обычных можно найти и к югу, и к северу отсюда.\n\nУверен, это как-то связано с гибелью всех друидов.", progress = "Вы принесли образцы?", completion = "Странно. Образцы агрессивных пухоспинок словно бы пропитаны чистейшей маной...\n\nПохоже то, что убило друидов, оставило после себя сильное энергетическое поле. Но пухоспинки почему-то не погибли от него, а только стали очень агрессивными.\n\nНо в одном я теперь уверен – эта странная энергия является побочным продуктом того, что убило всех друидов в чащобе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9970] = {title = "Кольцо Крови: Камнедар Выщербленный Повелитель", objective = "Победите Камнедара Выщербленного Повелителя. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.", description = "Это будет нелегкий бой, <имя>. Надеюсь, у тебя есть отважные друзья, которые смогут тебе помочь? Огры нашли великана в Острогорье. Его зовут Камнедар! Поверь мне на слово, <один/одна> ты не справишься. Этот Камнедар непобедим! Он тверд, как скала, в прямом смысле слова!\n\nЕсли хочешь сразиться с ним, войди в Кольцо Крови, и он примет вызов.", progress = nil, completion = "Ты хорошо погонял этих огров, малыш! Заставил их попотеть! Вот тебе кое-что сверху оговоренного – смотри, не трать все сразу!\n\nТы готов к следующей схватке? Гаргток ставит на тебя! Смотри не подведи!", rewards = "Вы получите:\n\nГигантский флакон с лечебным зельемГигантский флакон с зельем маны"}
MultiLanguageQuestData['ru'][9971] = {title = "Ответы в чащобе", objective = "Осмотрите странный предмет рядом с трупом Сломленного и постарайтесь узнать, что случилось в перелеске Кенария. Затем вернитесь к заклинателю земли Тавгрену в лес Тероккар.", description = "Ума не приложу, что же убило всех местных друидов? Меня самого тут пару дней не было – я изучал Костяные пустоши на юге.\n\nПожалуйста, помоги мне выяснить, что за трагедия здесь произошла! Нужно сходить в чащобу и поискать там какие-то улики, подсказки, которые смогут навести нас на след. Когда я был там – правда, очень не долго – то видел труп некоего Сломленного и странный предмет около него.\n\nА насчет Древлоса не волнуйся – он, возможно, и сошел с ума от того, что там произошло, но вообще он безобиден.", progress = nil, completion = "Значит, я был прав. Это и в самом деле был труп Сломленного? И вы можете точно сказать, что рядом с ним на земле лежал странный предмет?\n\nЧто-то тут не сходится... С чего бы Сломленному соваться сюда? И что за предмет он с собой притащил?\n\nИ что послужило причиной его смерти – уж не этот ли самый предмет?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9972] = {title = "Кольцо Крови: Скрагат", objective = "Одержите победу над Скрагатом. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.", description = "Ты сметаешь их всех, <малыш/красавица>! Валишь просто пачками! На следующий поединок они выставляют действительно сильного бойца. Говорят, он повелитель Бездны или как там его... В общем, они в нем уверены. Ты <слышал/слышала>, как этот слабак Могор тявкал на тебя, словно грязная шавка? Ставки взлетели до небес!\n\nНо я в тебя верю. Сейчас ты войдешь в этот круг и по-быстрому прикончишь их хваленого бойца!", progress = "Поединок закончится только тогда, когда один из вас упадет замертво.", completion = "МАЛЫШ! СВЕРШИЛОСЬ! Следующий бой будет воистину грандиозным! Бой за звание чемпиона!\n\nБрось, не стоит паниковать. Спокойствие, только спокойствие! Мы же не хотим, чтобы эти огры узнали, что у нас тут затевается кое-что интересное. В конце концов, у меня есть и свой интерес. И своя доля во всем этом деле.", rewards = "Вы получите:\n\nПлотные бинты из ткани ПустотыГигантский флакон с лечебным зельемГигантский флакон с зельем маны"}
MultiLanguageQuestData['ru'][9973] = {title = "Кольцо Крови: чемпион клана Боевого Молота", objective = "Одержите победу над чемпионом клана Боевого Молота. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.", description = "Им пришлось привезти этого бойца из гладиаторских ям Острогорья. Его тренировали на горных великанах – он выходил в одиночку против троих...\n\nЕсли ты выиграешь этот бой, то станешь новым чемпионом. Как ты думаешь, каковы твои шансы, <малыш/красавица>? Ну что, попробуешь? Скажи только слово, и я поставлю на тебя целое состояние.\n\nА теперь иди и побеждай!", progress = "Поединок закончится только тогда, когда один из вас упадет замертво.", completion = "О, боги. Герой Боевого Молота Могор желает воспользоваться своим правом выйти на бой. Тебе придется сразиться с ним!\n\nИ знаешь, молотобойцы ведь не зря так зовутся.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9977] = {title = "Кольцо Крови: последнее испытание", objective = "Одержите победу над Могором, героем клана Боевого Молота. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.", description = "<Гаргток пересчитывает монеты в большой куче золота.>\n\nТвоими стараниями, <малыш/красавица>, я сделал хорошие деньги. Если сумеешь побить Могора, даю тебе слово, что твои усилия не пропадут даром. Вся боль, которую ты <испытал/испытала> в Кольце Крови, вознаградится вдвойне!\n\nВойди в Кольцо Крови и покажи этим ограм, на что ты <способен/способна>!", progress = "Поединок закончится только тогда, когда один из вас упадет замертво.", completion = "Гаргток обещал, что ты получишь достойную награду. И он свое слово сдержит!", rewards = "Умащивающая дубина МогораДубинка боевого магаПосох зверейЗаточенный топор БездныПарадный кровавый клинок Боевого МолотаКлеймо ярости маг'харовВы получите:\n\n"}
MultiLanguageQuestData['ru'][9978] = {title = "Любыми средствами", objective = "Найдите Эмпура на дороге между и Тууремом и Шаттратом в лесу Тероккар. Убедите его рассказать вам все, что ему известно.", description = "Не знаю, что все это значит, но знаю, где нам найти еще подсказок.\n\nЕсть такой торговец – Эмпур – у него можно купить любой товар и любую информацию. Если сумеешь его разговорить, то он наверняка скажет много интересного.\n\nОн путешествует по дороге между Тууремом и Шаттратом. Но будь начеку – у Эмпура есть телохранитель.", progress = nil, completion = "Хорошо, хорошо... Я скажу тебе, что знаю, только знаю я не так уж много!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9979] = {title = "Латрай Торговец Ветром", objective = "Поговорите с торговцем ветром Латраем возле таверны \"На краю земли\" в Нижнем городе Шаттрата.", description = "Меня попросили забрать у некоего эфириала несколько коробок с товарами и доставить их по назначению.\n\nПоследний раз я видел его возле таверны \"На краю земли\" в Нижнем городе. Звать его торговец ветром Латрай, и это все, что я знаю!\n\nОб остальном расспрашивай у него!", progress = nil, completion = "Да? Чем могу помочь, |3-6(нежить)?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9982] = {title = "Его звали Алтруис...", objective = "Если у вас есть желание сразиться с Пылающим Легионом, разыщите Алтруиса Страдальца в западном Награнде.", description = "На прошлой неделе в наш город прибыл незнакомец верхом на драконе Пустоты. Он назвался Алтруисом и принялся расспрашивать про Награнд.\n\nУтверждал, что охотится на тварей Легиона. Что это безумие – его работа. Ты представляешь?! Чтобы кто-то по собственной воле охотился на демонов?!\n\nПрежде, чем покинуть нас, он просил передать всем смельчакам, что будет ждать их в западном Награнде. Так что, если тебе хочется подвигов, обратись к нему.", progress = nil, completion = "Тебя пугает мой вид? Ты знаешь, кто я?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9983] = {title = "Его звали Алтруис...", objective = "Если у вас есть желание сразиться с Пылающим Легионом, разыщите Алтруиса Страдальца в западном Награнде.", description = "На прошлой неделе в наш город прибыл незнакомец верхом на драконе Пустоты. Он назвался Алтруисом и принялся расспрашивать про Награнд.\n\nУтверждал, что охотится на тварей Легиона. Что это безумие – его работа. Ты представляешь?! Чтобы кто-то по собственной воле охотился на демонов?!\n\nПрежде, чем покинуть нас, он просил передать всем смельчакам, что будет ждать их в западном Награнде. Так что, если тебе хочется подвигов, обратись к нему.", progress = nil, completion = "Тебя пугает мой вид? Ты знаешь, кто я?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9984] = {title = "Хозяин Сокрытого Города", objective = "Отнесите приказы Луанги Андарлу в Бастион Аллерии, что в лесу Тероккар.", description = "Вы не можете прочитать текст свитка, но узорная печать внизу явно принадлежит некоему высокопоставленному араккоа. Даже если Луанга и руководил похищением и допросом Дейрома, приказы он принимал от кого-то еще.\n\nТандер упоминал, что Андарл изучает араккоа – возможно, он сумеет расшифровать содержимое свитка.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9985] = {title = "Хозяин Сокрытого Города", objective = "Отнесите приказы Луанги Каргатоку в Форт Камнеломов, что в лесу Тероккар.", description = "Вы не можете прочитать текст свитка, но узорная печать внизу явно принадлежит некоему высокопоставленному араккоа. Даже если Луанга и руководил похищением и допросом Дугара, приказы он принимал от кого-то еще.\n\nРокаг упоминал, что Каргаток изучает араккоа – возможно, он сумеет расшифровать содержимое свитка.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9986] = {title = "Сдержать араккоа", objective = "Убейте Ашказа в гнездовье Рескк, Аийта в гнездовье Шиенор и Урдака в гнездовье Скит, после чего вернитесь к Тандеру в бастион Аллерии.", description = "Нужно показать араккоа, что за нападения на наших людей их ждет быстрая и жесткая расправа. Если не остановить их сейчас, ни торговцы, ни курьеры, ни солдаты больше не смогут спокойно передвигаться по этим дорогам.\n\nМои разведчики донесли мне, что в каждом поселении араккоа есть лидер – их зовут Ашказ, Аийт и Урдак, и живут они соответственно в гнездовьях Рескк, Шиенор и Скит. Найдите их и убейте.", progress = nil, completion = "Замечательно, Паладиньдинь. Теперь можно не беспокоиться хотя бы о том, что араккоа нападут на наших торговцев и курьеров - и без этого забот полно.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГигантский флакон с лечебным зельемГигантский флакон с зельем маны\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9987] = {title = "Сдержать араккоа", objective = "Убейте Ашказа в гнездовье Рескк, Айита в гнездовье Шиенор и Урдака в гнездовье Скит, после чего вернитесь к Рокагу в форт Камнеломов.", description = "Нужно показать араккоа, что за нападения на наших людей их ждет быстрая и жесткая расправа. Если не остановить их сейчас, ни торговцы, ни курьеры, ни солдаты больше не смогут спокойно передвигаться по этим дорогам.\n\nМои разведчики донесли мне, что в каждом поселении араккоа есть лидер – их зовут Ашказ, Аийт и Урдак, и живут они соответственно в гнездовьях Рескк, Шиенор и Скит. Найдите их и убейте.", progress = nil, completion = "Замечательно, Джонниди. Теперь можно не беспокоиться хотя бы о том, что араккоа нападут на наших торговцев и курьеров - и без этого забот полно.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГигантский флакон с лечебным зельемГигантский флакон с зельем маны\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][9988] = {title = "Лучший друг щеголя", objective = "Принесите 30 перьев араккоа Роз'алете в бастион Аллерии.", description = "Не дайте Тандеру и его шайке обмануть вас! Они, может, и похожи на отряд суровых воинов, но под стальными доспехами скрываются обычные пижоны!\n\nА уж без своих шляп они в жизни на публике не покажутся. Эти шляпы сшиты из фетра и меха, и украшены самыми яркими перьями, которые только можно найти.\n\nСамые красивые перья, разумеется, у араккоа, и они-то как раз у меня и заканчиваются. Если принесете мне пучок, я с радостью заплачу вам за него.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9989] = {title = "Неведомые духи", objective = "Принесите 30 перьев араккоа Малуказу в форт Камнеломов.", description = "Когда я впервые попал в Запределье и прислушался к голосам местных духов, я был поражен тем, что услышал. Со временем я также начал замечать, что есть духи, чьих голосов я слышать не могу.\n\nНапример, несмотря на все мои старания, я так и не смог установить связь с духом предков араккоа. Их магия полностью отличается от нашей, но, думаю, поговорить с их духами все же возможно.\n\nПринесите мне побольше перьев араккоа, возможно, с их помощью мне удастся установить связь с духом.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9990] = {title = "Исследование Туурема", objective = "Найдите запечатанный ларец и отнесите его заклинателю земли Тавгрену. Тавгрена можно найти около перелеска Кенария в лесу Тероккар.", description = "Знаешь, я и правда вспомнил: около месяца назад Эмпур купил у меня несколько коробок каких-то странных деталей. Я не знаю, зачем они были нужны, но могу точно сказать, что их доставили в Туурем.\n\nМожет, там еще завалялся один из тех ящиков?", progress = "Какие вести с фронта, Менгиле?", completion = "Эфириалы? Товары, доставляемые в Туурем? Странные детали? И эльф крови, готовый доставить последний ящик в лагерь Огнекрылых?\n\nЧто все это означает?! Какое отношение это имеет к тому, что случилось с друидами в перелеске Кенария?!\n\nНадо посмотреть, что там в коробке.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9991] = {title = "Разведка", objective = "Приведите спинку кресла в вертикальное положение и пристегните ремни безопасности. Приятного полета! Когда закончите осмотр лагерей с воздуха, доложите Алтруису обо всем, что вы видели.", description = "Ты будешь моими глазами, но тебе придется проявить усердие. Нетрандамус пронесет тебя над лагерями Легиона, и ты <должен/должна> будешь запомнить все, что увидишь. Вплоть до мельчайших деталей. Каждая мелочь, на первый взгляд несущественная и неважная, может нам пригодиться и оказаться весьма полезной для наших целей.\n\nИ самое главное – я хочу знать, какие там есть постройки и оборонительные сооружения, и как вообще организована защита лагерей.\n\nНетрандамус уже готов к полету. Он ждет только тебя, <имя>. Не бойся, с тобой ничего не случится. Мой дракон позаботится о твоей безопасности.", progress = nil, completion = "Отлично сработано, Щук! Теперь мы знаем слабые места врага и можем планировать контратаку.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9992] = {title = "Семена олембы", objective = "Соберите 30 семян олембы и отнесите их Роз'алете в бастион Аллерии.", description = "Взгляните на лесные деревья, разве они не прекрасны? Я часто задаюсь вопросом, приживутся ли такие в Азероте?\n\nМне бы не хотелось отправлять туда саженцы, потому что они могут не пережить дороги. А вот мешочек семян – это самое то, их перевозить безопасно. Семена обычно содержатся в крепких шишках, которые падают с деревьев, когда созревают.\n\nЕсли вдруг увидите шишку на земле, то постарайтесь выковырять из нее семена и принесите мне, ладно?", progress = "Я начала собирать семена, но мне потребуется некоторая помощь, прежде чем я смогу отправить их в Штормград.", completion = "Спасибо за семена! У меня набралось почти достаточно для отправки первой партии!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9993] = {title = "Масло из семян олембы", objective = "Принесите 30 семян олембы Ракории в форт Камнеломов.", description = "Маслянистые семена лесной олембы обладают очень большой ценностью. Мне бы хотелось собрать их побольше, выжать масло и посмотреть, что с ним можно сделать.\n\nТолько подумайте – целый лес семян, которые пропадают зря! Неважно, где его можно использовать – в готовке, в лампах или для смазки оружия, я не позволю ему пропадать впустую!\n\nПринесите мне семена, которые сумеете собрать – они там повсюду.", progress = "Вы принесли мне семян?", completion = "Неплохо, но для того, чтобы изготовить достаточное количество масла, потребуется куда больше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9994] = {title = "Что это такое?", objective = "Доставьте ящик с деталями Дженайе Шепот Звезд в бастион Аллерии в лесу Тероккар.", description = "Не знаю, как ты, а я понятия не имею, что это за штуки, но могу сказать точно, что выглядят они опасно!\n\n<имя>, мне кажется, тебе надо отнести эту коробку Дженайе Шепот Звезд в бастион Аллерии, это к юго-востоку отсюда. Может, она знает, что это.", progress = "Вас что-то тревожит. Что такое, |3-6(Охотник)?", completion = "О нет! Какие ужасные вести! Неужели из всех наших друзей в живых осталось только двое?!\n\nХорошо, дайте-ка взглянуть на эти части. Надеюсь, это не то, о чем я думаю.\n\nДа, все именно так, как я и боялась – это детали бомбы. Наши разведчики из Шаттрата передавали нам информацию о том, что некоторые духи Астрала ввозят запрещенные товары из других измерений, с которыми у них налажены связи.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9995] = {title = "Что это такое?", objective = "Доставьте ящик с деталями Туки в форт Камнеломов в лесу Тероккар.", description = "Не знаю, как ты, а я понятия не имею, что это за штуки, но могу сказать точно, что выглядят они опасно!\n\n<имя>, мне кажется, тебе надо отнести эту коробку Туки в форт Камнеломов, это к юго-востоку отсюда. Может, он знает, что это.", progress = "Вас что-то тревожит. Что такое, |3-6(Чернокнижник)?", completion = "О нет! Какие ужасные вести! Неужели из всех наших друзей в живых осталось только двое?!\n\nХорошо, дайте-ка взглянуть на эти части. Надеюсь, это не то, о чем я думаю.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9996] = {title = "Нападение на лагерь Огнекрылых", objective = "Убейте 10 защитников, 10 кровавых стражей и 10 чернокнижников из армии Огнекрылых, после чего вернитесь к лейтенанту Меридиану на заставу Аллерии в лесу Тероккар.", description = "Мы знаем, что эльфы крови из лагеря Огнекрылых работают на Кель'таса и Иллидана. А судя по твоим рассказам, они используют Сломленных из Туурема для того, чтобы те поставляли им необходимые ресурсы для создания какого-то ужасного оружия.\n\nЧто бы они там ни затевали, самое эффективное, что мы можем сделать сейчас – это уменьшить их численность.\n\nТак что отправляйся в лагерь – это к северо-востоку отсюда – и убей как можно больше тамошних эльфов крови.", progress = nil, completion = "Для начала неплохо, но судя по тому, что вы там видели, и тому, что мне донесла разведка, у нас появилось куда более неотложное дело!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9997] = {title = "Нападение на лагерь Огнекрылых", objective = "Убейте 10 защитников, 10 кровавых стражей и 10 чернокнижников из армии Огнекрылых, после чего поговорите с сержантом Чауни в лагере Камнеломов, что в лесу Тероккар.", description = "Мы знаем, что эльфы крови из лагеря Огнекрылых работают на Кель'таса и Иллидана. А судя по твоим рассказам, они используют Сломленных из Туурема для того, чтобы те поставляли им необходимые ресурсы для создания какого-то ужасного оружия.\n\nЧто бы они там ни затевали, самое эффективное, что мы можем сделать сейчас – это уменьшить их численность.\n\nТак что отправляйся в лагерь – это к северо-востоку отсюда – и убей как можно больше тамошних эльфов крови.", progress = "Докладывай. Какие новости в лагере Огнекрылых?", completion = "Для начала неплохо, но судя по тому, что вы там видели, и тому, что мне донесла разведка, у нас появилось куда более неотложное дело!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9998] = {title = "Беспокойные соседи", objective = "Убейте 12 астральных батраков и доложите об этом Телории Плащ Теней на Заставу Аллерии.", description = "Недавнее появление орков Скверны в руинах очень озадачило и напугало Тандера. Они не покладая рук возводят укрепления и ремонтируют здания. Стройка не останавливается ни днем, ни ночью, <имя>. Я отправил туда одного из своих лучших агентов, чтобы он наблюдал за постройкой, но мы не можем оставаться в бездействии. Убейте их рабочих, а потом поговорите с Телорией Плащ Теней на Заставе Аллерии – это к северу от руин Костеглодов. Она расскажет вам, что делать дальше.", progress = nil, completion = "&lt;Высшая эльфийка кивает.&gt;\n\nНеплохо для начала, но Бертельм правильно сделал, что прислал тебя ко мне. Я обнаружила кое-что, что может объяснить присутствие здесь этих орков Скверны.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][9999] = {title = "Выиграть время", objective = "Убейте 2 стражей Скверны - легионеров, 3 мо'аргов-инжененеров и 8 ган'аргов-ремонтников.", description = "Пока у них есть транспортеры, наши набеги на Лагеря Легиона не дадут никакого результата. Надо найти способ разрушить постройки Легиона.\n\nМне нужно время на разработку плана атаки. Если ты сможешь отвлечь вражеских инженеров и ремонтников, это сильно замедлит их прогресс, и мы выиграем драгоценное время.", progress = "Что, уже вернулся?", completion = "Этого я и боялся. Железо Скверны так просто не уничтожить. Но отчаиваться рано...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10000] = {title = "Нежелательное присутствие", objective = "Убейте 12 астральных батраков и доложите об этом тенелову Кайду.", description = "Наши воины из Траллмара считали, что орки Скверны не осмелятся высунуться из цитадели Адского Пламени и прилегающих территорий, но разведчики, вернувшиеся из руин к востоку отсюда, говорят совершенно противоположное.\n\nНельзя дать им закрепиться там. Рокаг отправил в руины тенелова Кайда, но в одиночку он может лишь наблюдать.\n\nОтправляйтесь в руины, убейте их батраков и поищите Кайда в роще на севере. Он скажет, что делать дальше.", progress = nil, completion = "Для того чтобы остановить орков Скверны, недостаточно пугать их рабочих. Я обнаружил кое-что, что объясняет их присутствие здесь, и еще больше убедился в том, что действовать надо быстро.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10001] = {title = "Главный планировщик", objective = "Алтруис Страдалец из западного Награнда просит вас раздобыть чертежи главного планировщика.", description = "Все лагеря Легиона строятся по единому плану, утвержденному главным планировщиком. Он всегда таскает при себе целую кипу чертежей. Они-то нам и нужны.\n\nОбладая детальной информацией, мы сможем уговорить одного моего знакомого оказать нам содействие.\n\nРазыщи мо'арга-главного планировщика и отними у него чертежи. Ты найдешь его за кузницами.", progress = "Любым способом избегай встречи с надзирателями. Они не должны тебя заметить. Иначе может случиться беда!", completion = "Надеюсь, мой знакомый найдет способ стереть эти лагеря с лица земли. В конце концов, он когда-то был инженером в Легионе…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10002] = {title = "Посредник Огнекрылых", objective = "Найдите и убейте Лизель Огнепрядку, после чего вернитесь к Телории Плащ Теней.", description = "За последние пару дней я видела, как в крепость орков Скверны и обратно ходила эльфийка крови, а еще она разговаривала с их лидером. Судя по жестам, она явно отдавала ему приказы. Но почему? Чьи приказы она ему передает?\n\nЛюбопытство не давало мне покоя, поэтому я последовала за ней, когда она вышла из лагеря орков. Эльфийка направилась на север, в лагерь Огнекрылых, но туда я за ней не пошла.\n\nУбей эту эльфийку до того, как она в следующий раз выйдет из лагеря орков Скверны.", progress = nil, completion = "&lt;Телория кивает.&gt;\n\nПрекрасно, мы выиграли немного времени. Эльфы крови непременно захотят узнать, что произошло с их подругой, но к тому времени, надеюсь, мы сумеем разобраться в их намерениях.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10003] = {title = "Посредник Огнекрылых", objective = "Найдите и убейте Лизель Огнепрядку, после чего вернитесь к тенелову Кайду.", description = "Последнюю пару дней я видел, как в крепость орков Скверны и обратно ходила эльфийка крови, а еще она разговаривала с их лидером. Судя по их жестам, она явно отдавала ему приказы. Но почему? Чьи приказы она ему передает?\n\nМое любопытство не давало мне покоя, поэтому я последовал за ней, когда она вышла из лагеря орков. Эльфийка направилась на север, в лагерь Огнекрылых, но я не рискнул проникать внутрь.\n\nУбей эту эльфийку до того, как она еще раз выйдет из лагеря орков Скверны.", progress = nil, completion = "&lt;Кайд кивает&gt;\n\nПрекрасно, мы выиграли немного времени. Эльфы крови непременно захотят узнать, что произошло с их подругой, но к тому времени, надеюсь, мы сумеем разобраться в их намерениях.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10004] = {title = "Терпение и понимание", objective = "Покажите чертежи главного планировщика Саль'салабиму в Шаттрате и уговорите его помочь вам.", description = "Возьми чертежи и отправляйся в город Шаттрат в лесу Тероккар. Добравшись до места, ступай в Нижний город и найди там мо'арга по имени Саль'салабим. Скорее всего, он сидит в баре, пытаясь утопить печаль в стакане.\n\nКстати, тебе придется как-то склонить его к сотрудничеству. Сначала попробуй интеллигентный подход: терпение и понимание. Если не поможет, набей ему морду.", progress = "<Саль'салабим чешет в затылке.>\n\n(говорит на языке демонов) Ик ил ромат сардон.", completion = "Тихо, ясноглазый! Саль'салабим поможет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10005] = {title = "Вести для землепряда Тавгрена", objective = "Поговорите с заклинателем земли Тавгреном возле перелеска Кенария в лесу Тероккар.", description = "<имя>, когда закончишь праздновать, думаю, тебе стоит отправиться в перелесок Кенария и поговорить там с заклинателем земли Тавгреном.\n\nУверен, он захочет узнать, что здесь произошло на самом деле.", progress = nil, completion = "Бомба на чистейшей мане, способная стирать с лица земли целые города! Но зачем? Зачем эльфам крови создавать нечто подобное и сбрасывать на нас? Перелесок Кенария всегда был мирным и спокойным местом.\n\nКаковы бы ни были причины, они наверняка сокрыты в сознании хранителя Древлоса, и я не имею ни малейшего понятия о том, как вылечить его. Быть может, его разум со временем излечится сам?\n\nЯ могу лишь надеяться на то, что такое несчастье больше никогда не постигнет нас!", rewards = "Ножные латы перелеска КенарияШлем перелеска КенарияВенец перелеска КенарияЖакет перелеска КенарияВы получите:\n\n"}
MultiLanguageQuestData['ru'][10006] = {title = "Вести для землепряда Тавгрена", objective = "Поговорите с заклинателем земли Тавгреном возле перелеска Кенария в лесу Тероккар.", description = "<имя>, когда закончишь праздновать, думаю, тебе стоит отправиться в перелесок Кенария и поговорить там с заклинателем земли Тавгреном.\n\nУверен, он захочет узнать, что здесь произошло на самом деле.", progress = nil, completion = "Бомба на чистейшей мане, способная стирать с лица земли целые города! Но зачем? Зачем эльфам крови создавать нечто подобное и сбрасывать на нас? Перелесок Кенария всегда был мирным и спокойным местом.\n\nКаковы бы ни были причины, они наверняка сокрыты в сознании хранителя Древлоса, и я не имею ни малейшего понятия о том, как вылечить его. Быть может, его разум со временем излечится сам?\n\nЯ могу лишь надеяться на то, что такое несчастье больше никогда не постигнет нас!", rewards = "Ножные латы перелеска КенарияШлем перелеска КенарияВенец перелеска КенарияЖакет перелеска КенарияВы получите:\n\n"}
MultiLanguageQuestData['ru'][10007] = {title = "Ослабление врага", objective = "Убейте 10 уничтожителей и 6 спиноломов из клана Костеглодов, после чего вернитесь к Телории Плащ Теней.", description = "Зная Тандера и Бертельма, я могу сказать, что они не позволили бы врагу собрать такую армию прямо у нас под носом. Просить их выслать своих воинов, чтобы те напали на лагерь – тоже не вариант, это лишь сделает нас еще более уязвимыми.\n\nОстается только ослабить орков Скверны – ты убей, сколько сможешь, а я прослежу, чтобы к ним не прорвалось подкрепление.", progress = nil, completion = "Дело начинает проясняться. Думаю, что если мы сумеем не дать оркам закрепиться здесь, мы удержим позиции за собой.", rewards = "Прочный дубовый длинный лукСтвол Мертвого ГлазаЖезл Темного АвгураВы получите:\n\n"}
MultiLanguageQuestData['ru'][10008] = {title = "Секреты Тероккара не покидают его границ", objective = "Убейте 10 уничтожителей и 6 спиноломов из клана Костеглодов по просьбе тенелова Кайда.", description = "Если до Траллмара дойдет весть о том, что орков Скверны сдержать не удалось, у нас тут быстро нарисуется большая и веселая компания. Мне бы не хотелось привлекать столько внимания, поэтому нужно справиться с этой проблемой самим, понятно?\n\nЕсли мы сумеем нанести оркам Скверны достаточно потерь, то есть шанс, что об их присутствии не станет известно за пределами форта Камнеломов. Так что давай по-быстрому с этим разберемся.\n\nОтправляйся туда, доставай оружие, маши руками – в общем, делай, что хочешь, только поубивай этих орков.", progress = nil, completion = "Я знаю, что вы много путешествовали и о многом можете рассказать, Акул, но некоторым историям лучше оставаться на том месте, где они произошли. Понимаете, о чем я?", rewards = "Прочный дубовый длинный лукСтвол Мертвого ГлазаЖезл Темного АвгураВы получите:\n\n"}
MultiLanguageQuestData['ru'][10009] = {title = "Золото за тумаки", objective = "Взыщите долги с Ралика, Куш'куша и Флуна.", description = "<Саль'салабим смеется.>\n\nЭто все Саль'салабим придумал.\n\n<Саль'салабим показывает на строительные чертежи.>\n\nГляди – башни. Охотник за демонами ничего не видать! Бедный, бедный Алтруис. Был бы глаз – он бы плакать. \n\nДа, Саль'салабим дам помощь, но первый ты дай помощь Саль'салабиму.\n\n<Саль'салабим вручает вам список.>\n\nЭти должен Саль'салабим золотой. Много золотой. Ходи возьми золотой для Саль'салабим. Они не захочет отдать Саль'салабим золотой так просто. Надо побить, но ты – <сильный/сильная>. Ты же <побил/побила> Саль'салабим!", progress = "Обратно не ходи без золотых Саль'салабима!", completion = "Саль'салабим держит свой договор, только ты не будь злой потом, да?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10010] = {title = "Не так просто?", objective = "Вернитесь к Алтруису Страдальцу в западный Награнд.", description = "<Саль'салабим тычет в чертеж.>\n\nПушку Скверны <видел/видела>?\n\n<Саль'салабим рисует стрелку, обозначая поворот.>\n\nПовороти пушку и стреляй в дом.\n\nСтой! Не торопись! Ты <понял/поняла> не все. Для поворота пушки надзиратель имеет ключ. Сначала имей ключ! Один от каждого надзирателя!\n\nНе так легко, а?\n\nРасскажи Алтруису.", progress = nil, completion = "Ну конечно! Мы побьем их собственным оружием!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10011] = {title = "Лагеря Легиона: уничтожены", objective = "Уничтожьте лагеря Легиона: Страх и Ненависть.", description = "Соберись с силами, <имя>. Они тебе понадобятся, если ты собираешься выйти против надзирателей.\n\nКогда будешь <готов/готова>, найди в каждом из лагерей тамошних надзирателей, убей их и забери у них ключи, чтобы активировать пушки Скверны и направить их на лагеря. Когда уничтожишь оба лагеря, возвращайся ко мне.", progress = "Дело сделано?", completion = "Мы побеждаем! Нам удалось сдержать натиск Легиона!\n\nТы совершил героический подвиг и теперь можешь выбрать награду.", rewards = "Кираса предвестника войныМеталлическая головная лента Симм'онзаПоножи бесконечного нападенияМундир смотрителяВы получите:\n\n"}
MultiLanguageQuestData['ru'][10012] = {title = "Планы орков Скверны", objective = "Добудьте планы орков Скверны для Бертельма в Бастионе Аллерии, что в лесу Тероккар.", description = "Надписи на планах слишком красивые и четкие, чтобы принадлежать перу орка Скверны. Вы не можете разобрать текста, но и без этого понятно, что орки получают указания от эльфов крови из лагеря Огнекрылых.\n\nНо зачем бы им работать сообща? Наверное, стоит спросить об этом у Бертельма – нужно вернуться в бастион Аллерии и показать ему карту.", progress = "Что у вас там, Изуку?", completion = "&lt;Бертельм берет у вас планы и изучает их.&gt;\n\nЕсли бы вы не принесли мне эту карту, я бы подумал, что вы выжили из ума, однако вот она, тут! Орки Скверны не только служат эльфам крови, но им еще и приказано отвлекать нас.\n\nЭта карта дает вопросов больше, чем ответов, но, по крайней мере, мы теперь знаем, с чем имеем дело.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10013] = {title = "Невидимая длань", objective = "Добудьте планы орков Скверны для Рокага. Его можно найти в Форте Камнеломов, что в лесу Тероккар.", description = "Надписи на планах слишком красивые и четкие, чтобы принадлежать перу орка Скверны. Вы не можете разобрать текста, но и без этого понятно, что орки получают указания от эльфов крови из лагеря Огнекрылых.\n\nНо зачем бы им работать сообща? Наверное, стоит спросить об этом у Рокага – нужно вернуться в форт Камнеломов и показать ему карту.", progress = "Что у вас там, Акул?", completion = "*Рокаг берет у вас планы и изучает их*\n\nКайд все же был прав! Эти гнусные орки Скверны и впрямь что-то затевали, хотя я бы в жизни не подумал, что они скооперируются с эльфами крови.\n\nСудя по карте, орки должны отвлекать нас... но от чего? Это очень нехорошие новости, Акул. вы правильно сделали, что сразу вернулись ко мне.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10014] = {title = "Проект лагеря Огнекрылых", objective = "Украдите 4 листа кодирования мана-бомб и отнесите их лейтенанту Меридиану на заставу Аллерии в лесу Тероккар.", description = "Как я и говорил, по новым данным разведки, у нас возникла еще одна, гораздо большая проблема.\n\nЭльфы крови не покладая рук собирают в лагере Огнекрылых еще одну бомбу, и я не могу даже выразить всю серьезность последствий, которые ждут нас, сбрось они эту бомбу в бастион Аллерии.\n\nМои разведчики доложили, что коды от этой бомбы прячут в четырех зданиях вокруг центрального двора. Проберись туда и укради коды, пока еще не поздно!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10015] = {title = "Проект лагеря Огнекрылых", objective = "Украдите 4 листа кодирования мана-бомб и отнесите их сержанту Чауни в лагерь Камнеломов в лесу Тероккар.", description = "Как я и говорила, по новым данным разведки, у нас возникла еще одна, гораздо большая проблема.\n\nЭльфы крови не покладая рук собирают в лагере Огнекрылых еще одну бомбу, и я не могу даже выразить всю серьезность последствий, которые ждут нас, сбрось они эту бомбу на форт Камнеломов.\n\nМои разведчики доложили, что коды от этой бомбы прячут в четырех зданиях вокруг центрального двора. Проберись туда и укради коды, пока еще не поздно!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10016] = {title = "Хвосты лесных воргов", objective = "Принесите 12 хвостов лесных воргов Бертельму в бастион Аллерии. Хвосты можно добыть с лесных воргов или их вожаков.", description = "Не встречались ли вам в ваших путешествиях лесные ворги? Когда я составлял карту северных регионов леса, то имел возможность понаблюдать за ними. Не советую вам приближаться к этим животным, если вы не готовы к бою.\n\nОни нисколько не боятся нас, и будут яростно защищать свою территорию.\n\nИ, разумеется, у таких существ потрясающие хвосты! Я хотел бы собрать немного, чтобы украсить новый плащ, но ворги постоянно обходят мои ловушки. Не хотите ли мне помочь?", progress = "Вы не погибли в лесу, это очень хорошо! Удалось добыть хвостиков для моего плаща?", completion = "О, большое спасибо, друг мой. Эти хвостики даже еще лучше, чем я думал, из них выйдет прекрасный плащ.\n\n&lt;Бертельм бросает быстрый взгляд на таверну.&gt;\n\nО да, плащ выйдет отличный.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10017] = {title = "Нехватка припасов", objective = "Принесите 8 ядовитых желез пауков-смертеплетов Ша'нир в Шаттрат.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "С каждым днем в Шаттрат прибывает все больше и больше беженцев, и некоторые так изранены, что я удивляюсь, как они вообще смогли добраться сюда.\n\nС большинством ран я справляюсь – я прошла хорошее обучение у Алдоров, но вот с отравленными ранами дела обстоят хуже, потому что у меня кончаются запасы противоядий.\n\nПринесите мне ядовитых желез местных пауков-смертеплетов, чтобы я могла приготовить новые. Эти пауки живут на юго-востоке Тероккара.", progress = "Вы достали ядовитые железы, Елем? Без лекарств беженцы долго не протянут.", completion = "Благодарю вас, Елем. Алдоры непременно узнают о ваших деяниях.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10018] = {title = "Одежды духа волка", objective = "Принесите 12 шкур лесного ворга Малуказу в форт Камнеломов.", description = "Много поколений назад, когда орочьи кланы еще считали лес Тероккар своим домом, дух волка играл очень важную роль в их жизни. Когда орки ушли оттуда, дух остался покинутым и потерял для них свою значимость.\n\nСо временем духу стало одиноко, и он тоже покинул лес.\n\nЯ думаю, что сумею помочь духу волка вернуться в свой родной дом так же, как вернулись и мы, орки! Однако для ритуала мне понадобятся одежды из шкур местных волков, чтобы духу было легче найти дорогу домой.", progress = "Вы нашли все шкуры, какие я просил?", completion = "Отлично, Душавдушу! Лучше и быть не могло!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10019] = {title = "Больше ядовитых желез", objective = "Здесь еще очень много беженцев с отравлениями. Вы принесли мне ядовитые железы, Варец?", description = nil, progress = "Здесь еще очень много беженцев с отравлениями. Вы принесли мне ядовитые железы, Варец?", completion = "Большое спасибо, Варец. Теперь, когда эти несчастные находятся под защитой наару в Шаттрате, было бы очень жаль, если б они умерли от полученных ран.\n\n*Это задание можно повторять до тех пор, пока вы не заслужите равнодушное отношение.*", rewards = nil}
MultiLanguageQuestData['ru'][10020] = {title = "Лекарство для Залии", objective = "Принесите Ша'нир в Шаттрат кровь Камневзора.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Женщина справа от меня получила тяжелую травму головы. Она осталась жива, но потеряла зрение.\n\nСреди моего народа популярно лекарство, изготавливаемое из крови очень старого василиска.\n\nНо, к сожалению, на василисков Тероккара идет такая охота, что до старости они не доживают... Однако есть один василиск – я знаю о нем еще с детства, – его зовут \"Камневзор\", и вроде бы он живет к востоку отсюда, у края земли.\n\nПринесите мне его кровь, и тогда я смогу вернуть Залии зрение.", progress = "Вы достали кровь, Джонниди? Без нее Залия может никогда больше не увидеть своего сына.", completion = "Спасибо, Джонниди. Заботиться о больных нелегко, но со временем я поняла, что это само по себе является отличной наградой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10021] = {title = "Возрождение Света", objective = "Отправляйтесь на заставу Араккоа, что к востоку от Шаттрата, и при помощи благословленного фиала очистите восточный, западный и северный алтари, после чего вернитесь к Ишане.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Большую часть этой земли некогда населяли дренеи, а мы, Алдоры, должны были охранять наши священные города и алтари, многие из которых с тех пор были разрушены или захвачены врагами.\n\nК востоку отсюда находится застава араккоа. Предположительно, ее построили на месте наших трех священных алтарей, и теперь араккоа с помощью своей грязной магии искажают и оскверняют силу наших святынь.\n\nВозьмите с собой вот это и очистите три алтаря на заставе.", progress = "Вы выполнили свое задание, Рёи?", completion = "Благодарю вас, Менгиле. Мы - хранители света, и даже в самые трудные времена не можем пренебрегать своим долгом.", rewards = "Следующее заклинание будет наложено на вас:\n\nЗаклинание Силы - очищение благословенного фиала DND\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][10022] = {title = "Неуловимый Железнозуб", objective = "Принесите шкуру Железнозуба Бертельму в бастион Аллерии.", description = "Ну вот, мех на отделку у меня есть. Но я еще подумал, что из шкуры одного особенного волка может выйти отличный капюшон! Представьте, что вы увидели своего врага одетого в шкуру самого хитрого хищника из леса!\n\nЯ уже долго и безуспешно охочусь на Железнозуба – пытался загнать его в угол, перехитрить, приманить... Но ничего не получилось.\n\nОн бродит в северо-восточной части леса, и я с радостью награжу вас, если вам удастся сделать то, что не удалось мне.", progress = "Ну что, старина Железнозуб и вам задал трепку? Или вы сумели его перехитрить?", completion = "Снимаю шляпу перед вашим мастерством, Вродехант. Вы и впрямь превосходный охотник.\n\nЯ никогда не забуду, как вы помогли мне! Я сошью из этих шкур самый лучший плащ и буду с гордостью носить его.", rewards = "Шлем волчьей хитростиЛичина охотника на волковШлем волчьего изяществаШлем волчьей лютостиВы получите:\n\n"}
MultiLanguageQuestData['ru'][10023] = {title = "Патриарх Железнозуб", objective = "Принесите шкуру Железнозуба Малуказу в форт Камнеломов.", description = "Что ж, шкуры, которые вы собрали, очень хороши.\n\nОднако для того, чтобы закончить одежды, мне понадобится еще одна, особенная шкура. Ее можно снять только с одного, очень старого и хитрого волка, считающемся патриархом всех лесных волков. Его называют Железнозуб – великий охотник.\n\nВ видениях мне открылось, что он бродит в северо-восточной области леса. Если я украшу его шкурой свои одежды, это непременно поможет духу волка найти верную дорогу.\n\nНо не стоит скорбеть по Железнозубу. Он счел бы это за честь.", progress = "Дух ждет, Акул. Вы принесли шкуру волчьего патриарха?", completion = "Эта шкура еще прекраснее, чем я думал! Это добрый знак, Акул, и духи непременно оценят все, что вы сделали для этой церемонии.\n\nВот, я сшил для вас шлем из оставшихся шкур, Акул. Все, кто увидит вас в нем, поймут, что вы - великий охотник и союзник духа волка из леса Тероккар.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10024] = {title = "Видения Ворен'таля", objective = "Принесите 8 глаз гладкоспинных василисков чародейке Адирии в Шаттрат.\n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "Наш лидер, Ворен'таль Предсказатель, некогда был близким советником Кель'таса. Его пророческие видения указывали на то, что действия Кель'таса приведут к уничтожению нашего народа.\n\nОбычно эти видения довольно туманны и неточны, однако наши алхимики изобрели эликсир, который помогал Ворен'талю видеть более ясно. К сожалению, для этого эликсира требуется очень редкий компонент – глаза василиска, а мой обычный поставщик – жалкий эфириал – подвел меня.\n\nРазыщи гладкоспинных василисков в скалистых районах Тероккара и принеси мне их глаза.", progress = "Вы добыли глаза василисков, необходимые для изготовления эликсира для Ворен'таля?", completion = "Они в отличном состоянии, Атеистфрост! Не останавливайтесь на достигнутом, и скоро Провидцы станут воспринимать вас как друга.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10025] = {title = "Больше глаз василисков", objective = "Для крохотной порции эликсира требуется очень много глаз василисков. Чем больше вы принесете, тем лучше Провидцы будут относиться к вам.", description = nil, progress = "Для крохотной порции эликсира требуется очень много глаз василисков. Чем больше вы принесете, тем лучше Провидцы будут относиться к вам.", completion = "Спасибо, Артеус. Когда-нибудь, возможно, видения Ворен'таля решат судьбу всей нашей расы, поэтому нам нужно проследить, чтобы они были точны, как никогда.\n\n&lt;Это задание можно повторять до тех пор, пока вы не заслужите равнодушное отношение.&gt;", rewards = nil}
MultiLanguageQuestData['ru'][10026] = {title = "Нарушение магического равновесия", objective = "Убейте 10 прыгуан по просьбе Андарла из бастиона Аллерии.", description = "Мне немного неловко говорить об этом, но в лесу Тероккар со мной произошло кое-что неприятное, чего со мной не приключалось со времен студенчества.\n\nМои заклинания вдруг перестали действовать, хотя я все делал правильно! Когда это произошло в первый раз, я чуть с ума не сошел.\n\nНо, кажется, я узнал причину. В лесу полно прыгуан – эти существа очень тонко чувствуют магию и могут изменять течение ее потоков. Самый легкий способ разобраться с ними – это просто их поубивать.", progress = nil, completion = "&lt;Андарл вытирает лоб рукавом мантии.&gt;\n\nУфф... Большое спасибо! Если бы эти твари остались в живых, они бы причиняли нам массу неудобств.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10027] = {title = "Нарушение магического равновесия", objective = "Убейте 10 прыгуан и вернитесь к Каргатоку в форт Камнеломов.", description = "Когда готовишься прочитать заклинание, а его вдруг прерывает какая-то неведомая сила, это просто выводит из себя! Когда это произошло во второй раз, я понял, что это не совпадение, и отправил Кеб'езила выяснить, что происходит.\n\nУверяю вас, такого болтливого беса, как Кеб, вы не встретите никогда и нигде.\n\nОн отыскал-таки источник проблемы – мерзкую тварь под названием прыгуана. Они изменяют течение магических потоков везде, где бы ни находились, но я больше не намерен этого терпеть!", progress = nil, completion = "Кеб'езил очень рад, что вы разобрались с этой проблемой, правда, Кеб?\n\n&lt;Бес не обращает на хозяина ни малейшего внимания. Возможно, он слишком возмущен.&gt;\n\nПростите его за дурные манеры. Демоны, что с них взять...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10028] = {title = "Сосуды силы", objective = "Принесите 8 сосудов дренеев Роз'алете в бастион Аллерии.", description = "В руинах Туурема разбросано множество сосудов, в которых заключена чистая магическая энергия. Нам повезло, что Сломленные, которые захватили город, не обратили внимания на тамошние ресурсы, но, думаю, долго это не продлится.\n\nНекоторым представителям моего народа удалось выжить, и если они получат эти сосуды, то смогут сопротивляться демонической магии. Каждый кель'дорай, спасенный от злых чар нашего принца – это лишний шанс вернуть нашу былую славу. Принеси мне эти сосуды, <класс>.", progress = "Удалось найти неповрежденные сосуды?", completion = "Надеюсь, это не все сосуды, что были в том городе. На первое время этого хватит, но потом нам потребуется намного больше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10029] = {title = "Зов духов", objective = "Найдите помощника анахоретки Литиры по имени Сулавин в караване беженцев на Костяных пустошах в лесу Тероккар.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.\n\nПрилагается предмет: \n", description = "Духи мертвых взывают ко мне из Костяных пустошей, и молят избавить их от страшной боли!\n\n<класс>, тебе нужно отправиться на Костяные пустоши, к югу отсюда, и найти там моего помощника Сулавина в караване беженцев. Он, должно быть, тоже слышит зов духов, и ему потребуется твоя помощь, чтобы успокоить их.\n\nЕсли поспешишь, то сумеешь их догнать. Я знаю, что они собирались делать остановку в северной части Костяных пустошей, а потом двинуться южнее, в Аукиндон.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10030] = {title = "Сбор останков", objective = "Соберите 10 неупокоенных костей и отнесите их Рамдору Безумному на западную сторону Ритуального круга в Аукиндоне. Аукиндон находится в центре Костяных пустошей в лесу Тероккар.", description = "Костяные пустоши усеяны костями дренеев, погибших при взрыве в Аукиндоне. Их души до сих пор не упокоены и не могут перейти к следующей жизни.\n\n<класс>, помоги мне собрать их кости и похоронить их как следует. Только после этого они, наконец, обретут покой.\n\nСобери разбросанные кости и отнеси их Рамдору Безумному в Аукиндон, что в центре Костяных пустошей. Несмотря на свое имя, он как нельзя лучше позаботится о них.", progress = "Что это? Вы кто?", completion = "Отлично, именно этого мне и не хватало... еще костей.\n\n&lt;Рамдор вздыхает.&gt;\n\nДа, да, я прослежу за тем, чтобы эти останки наших высокочтимых предков были надлежащим образом захоронены, так что не беспокойся.\n\nА раз уж ты так хочешь помочь мертвым, то я могу дать тебе еще одно дело.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10031] = {title = "Возвращение заблудших душ", objective = "Уничтожьте 10 заблудших духов и 10 скелетов Сломленных, после чего поговорите с Сулавином в караване беженцев в Костяных пустошах леса Тероккар.", description = "Взрыв в Аукиндоне осквернил души многих дренеев, и теперь они в мучениях блуждают по Костяным пустошам.\n\nЯ нижайше прошу тебя даровать им покой. Уничтожь заблудших духов и скелетов сломленных, что блуждают по Костяным пустошам за стенами Аукиндона.\n\nЧто? Думаешь, лучше позволить им и дальше блуждать там и мучиться в агонии?\n\nКогда закончишь, поговори с Сулавином в караване беженцев и расскажи ему все.", progress = nil, completion = "Вы сделали то, что нужно было сделать, и прощения просить вам не за что. То, что они превратились в ужасную нежить, разумеется, очень печально, но вы упокоили их, и это хорошо.\n\nСпасибо, что освободили эти бедные души, Душавдушу. Примите этот скромный дар в знак моей благодарности за вашу работу.", rewards = "Ремень покаянияПерчатки посмертияФлотские сапоги беженцаВласяница страданийВы получите:\n\n"}
MultiLanguageQuestData['ru'][10032] = {title = "Артефакты из Туурема", objective = "Заберите 6 артефактов у тууремских падальщиков и охотников и отнесите их Ракории в форт Камнеломов.", description = "Тебе не приходилось замечать, как Заблудшие ведут себя в Тууреме? Они бродят по руинам и ищут любые крохи того, что было создано дренеями.\n\nИх хозяева – Сломленные – знают больше. Они отказались от своих прошлых жизней и превратились в совершенно других существ.\n\nДумаю, мания Заблудших может сослужить нам хорошую службу и помочь завладеть дренейскими реликвиями. Зачем рисковать жизнью и сражаться со Сломленными, когда можно выбрать куда более удобную цель?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10033] = {title = "Награда за убитых костеклювов!", objective = "Убейте 20 костеклювов и вернитесь к Тэле Вечной Страннице в бастион Аллерии в лесу Тероккар.", description = "Костеклювы с костяных пустошей – разносчики чумы, поэтому за их уничтожение назначена награда.\n\nКостеклювов можно найти на всей территории пустошей, но больше всего их скапливается на холме Падальщика, что к северу.\n\nЗа наградой обращаться к Тэле Вечной Страннице.", progress = nil, completion = "О, разумеется, вы убили целую стаю костеклювов! Вы читали сообщение капитана о том, что нужно приносить мне доказательства?\n\n&lt;Таэла смотрит на вас с сарказмом.&gt;\n\nЛадно, поверю на слово. Не знаю уж, за что мне такое наказание, но благодарю вас за ваши усилия от имени всего Альянса. Вот вам награда за труды.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10034] = {title = "Награда за убитых костеклювов!", objective = "Убейте 20 костеклювов и вернитесь к Маугу Лютострелу в форт Камнеломов в лесу Тероккар.", description = "Костеклювы с Костяных пустошей искусали Мауга, и теперь ему больно! Он хочет, чтобы все они исчезли!\n\nИх можно найти в любом месте Костяных пустошей, но больше всего живет на холме Падальщика.\n\nКогда убьете всех, приходите к Маугу Лютострелу и получите хорошую награду.", progress = nil, completion = "Вы, должно быть, убили много костеклювов! Тьфу, как я ненавижу этих тварей! С тех пор, как меня покусал один из них, у меня случаются периодические обмороки.\n\nПредставляете, как это неприятно? Вот, возьмите это в благодарность за то, что отомстили за меня.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10035] = {title = "Торгос!", objective = "Приманите Торгоса останками Трашелы, добудьте перо из его хвоста и отнесите его Тэле Вечной Страннице в бастион Аллерии в лесу Тероккар.", description = "В Костяных пустошах живет существо настолько ужасное, что едва ли кто отважится напасть на него.\n\nЯ имею в виду Торгоса, короля костеклювов – он кружит над гнездовьем Рейз, что на западном краю пустошей.\n\nХитрые араккоа поставили там пугало, назвали его Погибель Торгоса, и это пугало не дает ему приблизиться. Но если положить к подножию пугала останки самки Торгоса – Трашелы – то он спустится вниз. Самку можно найти на холме Падальщика, это на севере пустошей.\n\nПринеси мне перо из хвоста Торгоса.", progress = "Принесли перо? Вас можно достойно наградить?", completion = "Впечатляет, |3-6(Охотник)! Торгос был одним из самых страшных существ на этой стороне Награнда.\n\nЧто ж, думаю, ты заслуживаешь кое-что из сокровищницы бастиона Аллерии. Выбирай.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТероккарская табличка энергииТероккарская табличка меткости\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][10036] = {title = "Торгос!", objective = "Приманите Торгоса останками Трашелы, добудьте перо из его хвоста и отнесите его Маугу Лютострелу в форт Камнеломов в лесу Тероккар.", description = "Я хочу, чтобы Торгос, вожак костеклювов, сдох!\n\nНедавно я охотился в гнездовье Рейз, и эта тварь напала на меня!\n\n<Мауг показывает на повязку на глазу.>\n\nОн вырвал мне глаз, и за это должен умереть! Вырви из его трупа хвостовое перо и получишь хорошую награду.\n\nДля того, чтобы приманить это чудовище, тебе потребуются останки его самки, Трашелы. Положи их под пугалом, которое араккоа назвали Погибель Торгоса, он и спустится.\n\nТрашелу можно найти на холме Падальщика, это на севере пустошей.", progress = "Вы убили его? Торгос мертв?!\n\nА доказательство?", completion = "Спасибо, Джонниди! Вы отомстили за меня, а я, как и обещал, награжу вас.\n\nВот, выбирайте и пользуйтесь на здоровье.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТероккарская табличка энергииТероккарская табличка меткости\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][10037] = {title = "Без рыбалки", objective = "Принесите 8 тушек блестящих угрей Сету в Шаттрат.", description = "Кстати, об озерах – тут к северо-востоку есть отличное озеро для рыбалки! Раньше я ходил туда с друзьями, но потом мама запретила.\n\nОна говорит, что там опасно, но я ничего особо странного там не видел, разве что маленьких паучков. Да разве ж они могут как-то навредить?\n\nЭх, а я так любил есть тамошних угрей, до чего ж они вкусные... Если вдруг попадете на это озеро, может, принесете мне немного рыбки? Угри немного злые, но вообще с ними не так уж трудно справиться.", progress = "<Сет хватает вас за плащ.>\n\nВы нашли угрей? А?", completion = "Спасибо! Я уж и забыл, когда в последний раз ел угря!\n\nИ как же мне их приготовить?", rewards = "Вы получите:\n\nГрафитовая удочка Сета"}
MultiLanguageQuestData['ru'][10038] = {title = "Разговор с рядовым Виксом", objective = "Найдите рядового Викса возле северного входа в деревню Грангол'вар в лесу Тероккар и поговорите с ним.", description = "Мы только что получили донесение от разведчика из деревни Грангол'вар. Он пишет, что в тамошние руины пришла какая-то темная компания.\n\n<имя>, я хочу, чтобы вы поговорили с рядовым Виксом и помогли ему выяснить, что это за группа и что она затевает. Отправляйтесь на запад, мимо Форта Камнеломов – рядовой должен быть где-то около северного входа в деревню.", progress = nil, completion = "Наконец-то хоть кто-то пришел! Я отправил донесение в бастион Аллерии неделю назад.\n\nЧертовы бюрократы!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10039] = {title = "Разговор с разведчицей Нефтис", objective = "Найдите разведчицу Нефтис возле южного входа в деревню Грангол'вар в лесу Тероккар и поговорите с ней.", description = "Мне сообщили, что наша разведчица близ деревни Грангол'вар заметила группу неизвестных, которая недавно обосновалась там.\n\n<имя>, отправляйся туда, поговори с разведчицей Нефтис и помоги ей выяснить, что это еще за компания.\n\nОтправляйся отсюда на юг, а потом поверни на запад, чтобы пройти мимо северной части Костяных пустошей. В своем последнем донесении Нефтис писала, что расположилась около южного входа в деревню.", progress = nil, completion = "Наконец-то, хоть кто-то явился! Я ведь послала письмо в форт Камнеломов неделю назад!\n\nВечно эти эльфы крови бюрократию разведут!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10040] = {title = "Кто они?", objective = "Замаскируйтесь и поговорите с мрачным посвященным, мрачным работником и мрачным советником, после чего вернитесь к рядовому Виксу у деревни Грангол'вар в лесу Тероккар.", description = "Не знаю, кто это, но ведут они себя очень враждебно!\n\nЯ дам вам маскировочный костюм, чтобы вы пошли туда и поговорили с тремя из них, наиболее болтливыми – с посвященным, работником и советником.\n\nНо будьте осторожны – там есть несколько охотников, которые узнают вас даже в камуфляже, а с ними лучше не связываться. И что бы ни произошло, ни в коем случае не покидайте деревни, потому что маскировочный костюм очень непрочен! Если вдруг потеряете его, то приходите, я дам вам новый.", progress = "Вы со всеми поговорили? Что они сказали?", completion = "Наконец-то вы вернулись! Ну, что удалось узнать? Кто они такие?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10041] = {title = "Кто они?", objective = "Замаскируйтесь и поговорите с Мрачным посвященным, Мрачным работником и Мрачным советником, после чего вернитесь к разведчице Нефтис в деревню Грангол'вар в лесу Тероккар.", description = "Не знаю, кто это, но ведут они себя очень враждебно!\n\nЯ дам вам маскировочный костюм, чтобы вы пошли туда и поговорили с тремя из них, наиболее болтливыми – с посвященным, работником и советником.\n\nНо будьте осторожны – там есть несколько охотников, которые узнают вас даже в камуфляже, а с ними лучше не связываться. И что бы ни произошло, ни в коем случае не покидайте деревни, потому что маскировочный костюм очень непрочен! Если вдруг потеряете его, то приходите, я дам вам новый.", progress = "Вы со всеми поговорили? Что они сказали?", completion = "Наконец-то вы вернулись! Ну, что удалось узнать? Кто они такие?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10042] = {title = "Убить Совет Теней!", objective = "Убейте 10 мрачных палачей, 10 мрачных призывателей и повелителя теней Скорбного, после чего вернитесь к лейтенанту Булыжному Молоту в бастион Аллерии в лесу Тероккар.", description = "Что?! Совет Теней?!\n\n<имя>, вернись туда и убей их всех! Нужно избавиться от их главаря и от как можно большего количества призывателей и палачей.\n\nКогда закончишь, ступай к лейтенанту Булыжному Молоту в бастион Аллерии.\n\nУдачи, <класс>!", progress = nil, completion = "Это ужасные новости! Похоже, я правильно поступил, что отправил вас на помощь Виксу. Чего нам не надо, так это чтобы Совет Теней обосновался прямо у нас под носом.\n\nНехел, в знак признательности за проявленное вами мужество в деревне Грангол'вар я даю вам право выбрать себе одну из этих прекрасных наград.", rewards = "Клинок повышенной остротыТерновый разрушительПосох неодолимостиВы получите:\n\n"}
MultiLanguageQuestData['ru'][10043] = {title = "Убить Совет Теней!", objective = "Убейте 10 мрачных палачей, 10 мрачных призывателей и повелителя теней Скорбного, после чего вернитесь к советнице Файле в форт Камнеломов в лесу Тероккар.", description = "Что?! Это Совет Теней?!\n\n<имя>, вы должны вернуться туда и убить их всех! Нужно избавиться от их главаря и от как можно большего количества призывателей и палачей.\n\nКогда закончишь, поговори с советницей Файлой в форте Камнеломов.\n\nУдачи, <класс>!", progress = nil, completion = "Это ужасные новости! Похоже, я правильно поступила, что отправила вас на помощь Нефтис. Чего нам не надо, так это чтобы Совет Теней обосновался прямо у нас под носом.\n\nАкул, вы заслужили хорошую награду. Вот, выбирайте.", rewards = "Клинок повышенной остротыТерновый разрушительПосох неодолимостиВы получите:\n\n"}
MultiLanguageQuestData['ru'][10044] = {title = "Разговор с Великой матерью", objective = "Поговорите с Великой Матерью Гейей и сделайте все, о чем она вас попросит.", description = "Великая мать незамедлительно требует тебя к себе.\n\nМой дух сломлен печалью, но берегись, <имя>: если ты рассердишь Великую мать, я обрушу на тебя все силы, которые только смогу собрать. Она в главном зале.\n\n*Гаррош указывает на большое здание к северу.*\n\nВыслушай ее и выполни ее приказ.", progress = "Присядь, дорогой.", completion = "Для того чтобы общаться с предками, надо сначала открыть свое сознание.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10045] = {title = "Компоненты зелья", objective = "Принесите великой матери Гейе в Гарадар 1 корень олембы, 1 кустик клюквы, 1 телаарский папоротник и 1 побег драконьего шипа.", description = "Мать Кашур хочет поговорить с тобой, <имя>. Но это произойдет не раньше, чем ты соберешь травы. Они необходимы для изготовления снадобья, которое откроет твой разум и позволит тебе говорить с духами.\n\nТебе надо найти корень олембы в лесу Тероккар, клюкву в Зангартопи, телаарский папоротник в Награнде и драконий шип в Острогорье. Я записала инструкции на этом пергаменте, чтобы ты <сумел/сумела> распознать необходимые травы. Когда соберешь все, что нужно, возвращайся ко мне.", progress = "Здравствуй, сынок.", completion = "Ты все сделал правильно, Расул. И ты молодец. Даже самые лучшие наши травники не справились бы с этой работой быстрее тебя. !\n\n*Великая Матерь Гейя добавляет травы в напиток и подносит кубок к вашим губам, заставляя вас выпить снадобье.*\n\nНе бойся.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10046] = {title = "Через Темный портал", objective = "Пройдите через Темный портал и поговорите с Назгрелом в Траллмаре.Две недели назад наши разведчики доложили о выступлении из крепости Стражей Пустоты хорошо вооруженных сил Альянса под командованием боевого командира Ромуса. Если они отрядили столько солдат и ресурсов под управлением такого выдающегося командира, то цель может быть только одна – Запределье.\n\nВождь послал передовые отряды через портал, но если Альянс считает нужным отправить такое большое войско, возможно и нам лучше было бы послать подкрепление. Отправляйся через Темный портал и поговори с Назгрелом в Траллмаре.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Две недели назад наши разведчики доложили о выступлении из крепости Стражей Пустоты хорошо вооруженных сил Альянса под командованием боевого командира Ромуса. Если они отрядили столько солдат и ресурсов под управлением такого выдающегося командира, то цель может быть только одна – Запределье.\n\nВождь послал передовые отряды через портал, но если Альянс считает нужным отправить такое большое войско, возможно и нам лучше было бы послать подкрепление. Отправляйся через Темный портал и поговори с Назгрелом в Траллмаре.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10047] = {title = "Путь Славы", objective = "Окропите 8 истоптанных скелетов, лежащих на Пути Славы, святой водой дренеев, после чего возвращайтесь в Оплот Чести к провидцу бед Криву.", description = "Они называют ее \"Путем Славы\". Дорога, которая ведет от их ужасной крепости к Темному порталу, вымощена костями моего народа.\n\nМало того, что они травят нас, как зверей, разрушают наши города и пытают тех, кто выжил. Нет, этого им недостаточно. Они вымостили дорогу костями моих соратников, лишив их достойного погребения.\n\nИстерзанные души этих несчастных бродят по земле, не зная покоя. Умоляю тебя, <имя>, помоги мне освободить их.", progress = "Плач вроде бы стих... Милосердие Света превосходит всякое разумение смертных.", completion = "Я искренне благодарен тебе за помощь, Крайтеен. Еще многое нужно сделать, но я рад, что мы помогли кому-то обрести заслуженный и долгожданный покой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10050] = {title = "Непреклонные духи", objective = "Убейте 12 непреклонных пехотинцев, 10 непреклонных колдунов и 5 непреклонных рыцарей в оружейной экспедиции на юге по просьбе отважного стража Весилоу.", description = "Где-то в конце нашего вторжения, Оружейная на юге попала под удар коварных Рыцарей Смерти Орды. Защитники Оружейной пали от колдовства и оказались прокляты - их души застряли навеки между жизнью и смертью.\n\nМы должны освободить этих доблестных солдат. Умоляю тебя, <имя>, прекрати мучения моих соратников. Мне самому не хватает духа их уничтожить.", progress = nil, completion = "О том, что происходит в Оружейной, многие предпочитают умалчивать, но Сыны благодарны тебе за помощь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10051] = {title = "Побег из лагеря Огнекрылых", objective = "Проводите Ислу Звездную Гриву в безопасное место, после чего расскажите об этом капитану Аурику Ловчему Солнца в бастионе Аллерии в лесу Тероккар.", description = "О, наконец-то хоть кто-то появился!\n\n<класс>, помоги мне сбежать! У меня есть информация, жизненно важная для Бастиона Аллерии и, возможно, для всего Запределья!\n\nЯ прибыла сюда из Кенарийской экспедиции с дипломатической миссией, но, как видишь, меня ждал отнюдь не дружеский прием! Если ты поможешь мне спастись, то я обязательно прослежу, чтобы тебя достойно наградили!", progress = nil, completion = "Исла Звездная Грива только что ушла, но она рассказала мне обо всем, что произошло в лагере Огнекрылых. Вполне понятно, что она очень расстроена тем происшествием в перелеске Кенария... Проклятые эльфы крови!\n\nОна рассказала мне и о том, как ты помог ей спастись и донести до нас эту информацию, так что бастион Аллерии перед тобой в долгу.\n\nПожалуйста, прими это в благодарность ото всех нас.", rewards = "Тероккарский топорЛесной посох целителяКровопускающий ножВы получите:\n\n"}
MultiLanguageQuestData['ru'][10052] = {title = "Побег из лагеря Огнекрылых", objective = "Проводите Ислу Звездную Гриву в безопасное место, после чего расскажите об этом советнице Файле в форте Камнеломов в лесу Тероккар.", description = "О, наконец-то хоть кто-то появился!\n\n<класс>, помоги мне сбежать! У меня есть информация, жизненно важная для Форта Камнеломов и, возможно, для всего Запределья!\n\nЯ прибыла сюда из Кенарийской экспедиции с дипломатической миссией, но, как видишь, меня ждал отнюдь не дружеский прием! Если ты поможешь мне спастись, то я обязательно прослежу, чтобы тебя достойно наградили!", progress = nil, completion = "Исла Звездная Грива только что ушла, но она рассказала мне обо всем, что произошло в лагере Огнекрылых. Вполне понятно, что она очень расстроена тем происшествием в перелеске Кенария... Проклятые эльфы крови!\n\nОна рассказала мне и о том, как ты помог ей спастись и донести до нас эту информацию, так что форт Камнеломов перед тобой в долгу.\n\nПожалуйста, прими это в благодарность ото всех нас.", rewards = "Тероккарский топорЛесной посох целителяКровопускающий ножВы получите:\n\n"}
MultiLanguageQuestData['ru'][10055] = {title = "Ничто не пропадет даром", objective = "Принесите 8 кусков металлолома и 8 кусков древесины Болтую в Оплот Чести.", description = "Подкрепление – это хорошо, но я не вижу, чтобы они присылали металл или древесину.\n\nОглянись вокруг, <дружище/подруга>. Все деревья вырублены, а на рудниках хозяйничают приспешники Легиона.\n\nМне постоянно не хватает материалов. Поверь, я делал все, что можно, но пришло время пускать вторсырье на переработку.\n\nВ южной части Пути Славы повсюду валяются обломки техники. Некоторые из них можно снова пустить в дело. <Готов/Готова> приступить ко сбору вторсырья?", progress = "Ну как, удалось найти что-нибудь полезное среди этого пепла, пыли и хлама?", completion = "Выглядит лучше, чем я думал. Уйдет немало времени, чтобы счистить всю эту пыль и ржавчину, но выбора у меня все равно нет.", rewards = "Иллюзорный головной уборНагрудный доспех искателя битвыУкрашенный шлем легионераНаголенники мирового судьиВы получите:\n\n"}
MultiLanguageQuestData['ru'][10057] = {title = "Солдатская верность", objective = "Победите духов верховного мага Ксинтора и лейтенанта-командора Талвоса и возвращайтесь к отважному стражу Весилоу в северо-западную башню Оплота Чести.", description = "Несмотря на все твои усилия, в оружейной экспедиции по-прежнему неспокойно. Никто не знает, что же там происходит, и что вообще привело духи павших солдат в эти руины.\n\nВозможно, мы что-то сделали не так. Я чувствую, что солдаты каким-то образом связаны с этим местом. Может быть, они хранят верность своим командирам?\n\nПодчиненные всегда любили верховного мага Ксинтора и лейтенанта-командора Талвоса. Может быть, если нам удастся победить их духи, то и все остальные отправятся на вечный покой?", progress = "Тебе удалось победить призраки офицеров?", completion = "Мы можем только надеяться, что простые солдаты последуют примеру своих командиров. Еще раз благодарю тебя за помощь, Крайтеен.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДренетистовое кольеЦепь головорезаИскусно выкованная цепь\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10058] = {title = "Старый дар", objective = "Верните \"Таинства Света\" отцу Малгору Девидикусу в Оплот Чести.", description = "<Жрец медленно отрывается от кружки и подымает на вас взгляд.>\n\nНеужели тебя не учили, что не следует мешать человеку, когда он пьет?\n\nЛадно, ладно. Новое лицо – это хороший знак. Интересно, что бы подумал Туралион?\n\nЯ помню тот вечер перед нашим отправлением, когда я вручил ему \"Таинства Света\". В течение нескольких лет, пока длилась кампания, он не забывал каждый день прочитывать по главе своим людям.\n\nКогда он покидал нас, то вернул книгу обратно мне. А я, дурак, верил, что в моем доме, к югу от Оружейной, она будет в безопасности.", progress = "Кажется, я уже говорил тебе меня не трогать. Что на этот раз?", completion = "Это правда она? Невероятно, как эта книга сумела уцелеть во время битвы. Время, проведенное среди руин, не пошло ей на пользу, но я рад, что она снова ко мне вернулась.\n\nЭто моя единственная память о Туралионе.\n\n&lt;Отец Девидикус пытается сдержать слезы.&gt;\n\nЕсли ты долго сражаешься с кем-то плечом к плечу, то он становится тебе дороже, чем брат.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10061] = {title = "Непреклонные", objective = "Убейте 12 непреклонных пехотинцев, 10 непреклонных колдунов и 5 непреклонных рыцарей в оружейной экспедиции к югу от Оплота Чести по просьбе Грелага.", description = "Орки из клана Костеглодов быстро покончили с защитниками оружейной экспедиции. Произошла кровавая резня, в которой никто не уцелел.\n\nТела мертвых были преданы огню, но души поселились в этих руинах. Недавно мне было видение, что эти духи могут представлять угрозу для Траллмара.\n\nМы можем сделать только одно. Души этих солдат нужно упокоить. Сразись с ними и победи их в бою.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10063] = {title = "Лига исследователей: что здесь делают гномы?", objective = "Найдите Клоппера Бацбаха – он обосновался в старом черепашьем панцире на берегу к северу от Кровавой заставы.", description = "Я – нянька?! Нет, кому такое только в голову могло прийти?!\n\nОтрывают меня от исследований – весьма многообещающих, замечу, исследований! – и посылают в экспедицию с капитаном Одиссием. И зачем, как ты думаешь? Чтобы я нянчился с этим гномским недомерком!\n\nТо есть теперь мы в геологи берем гномов; а вот именно этот гном с ума сходит по мурлокам!\n\nХуже того, он решил устроить лавку в старом черепашьем панцире. Не веришь? А ты сходи на северный берег – увидишь своими глазами!", progress = nil, completion = "Так я и думал! Между прочим, этот старый ворчливый тип должен был мне помочь с оборудованием и сбором информации. Как же! Двадцать раз! Конечно, ему гораздо больше нравится торчать в этом дренейском городе и надираться в стельку!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10064] = {title = "Длань Аргуса", objective = "Найдите в селении Привал Защитника разведчицу Джорли.", description = "Передовая база Длани Аргуса расположена в селении Привал Воздаятеля. Увы, бойцам Длани приходится нелегко: их теснят эльфы крови и животные-мутанты. Без поддержки их оплот падет – и тогда мы потеряем последнюю возможность узнать, что же происходит возле энергоблока.\n\nНайди в Привале Воздаятеля разведчицу Джорли и предложи ей помощь.", progress = nil, completion = "Я надеялась, что как только на Кровавой заставе поймут, что нам противостоит, к нам пришлют подкрепление.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10065] = {title = "Зеленая улица", objective = "Убейте 10 разъяренных опустошителей и вернитесь на Привал Защитника к разведчице Джорли.", description = "Мы проводили разведку, выясняя, где расположились Солнечные Ястребы и где находится их портал, но, к несчастью, я была тяжело ранена. Разведчица Лорай сумела остановить кровь; надеюсь, ей удастся найти способ переправить меня на Кровавую заставу.\n\nУвы, чтобы вернуться туда живыми, нам придется покинуть наше убежище.\n\nКак только мы покинем эту освященную землю, на нас набросятся разъяренные опустошители. Однако если тебе удастся расчистить нам путь, возможно, мы сумеем добраться до Кровавой заставы в целости...", progress = nil, completion = "Похоже, вокруг стало поспокойнее... А все-таки, может, лучше остаться здесь и дождаться лекаря?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10066] = {title = "Тенета судьбы", objective = "Убейте 8 тенеплетов-мутантов и вернитесь к воздаятельнице Корин в селение Привал Защитника.", description = "Мы не смеем ни покинуть пост, ни удалиться от Привала Защитника, <раса>. Те твари, которые находились ближе всего к Энергоблоку, совершенно изменились: мутировали под влиянием энергии кристаллов.\n\nДаже тенеплеты-мутанты, похоже, обрели разум – насколько растения вообще могут быть разумными. Они научились создавать и расставлять смертоносные ловушки; к тому же ловушки эти замаскированы так, что в любую может попасться даже опытный и осторожный воин.\n\nТы <должен/должна> понимать: мы никогда не сумеем выступить против Солнечных Ястребов, если будем вынуждены в буквальном смысле слова следить за каждым своим шагом. Но ты ведь сумеешь разрешить эту небольшую проблему, верно, <имя>?", progress = nil, completion = "Прекрасно, Рудель. Теперь, когда можно не беспокоиться по поводу тенеплетов, нам будет гораздо легче привести подкрепление с Кровавой заставы и организовать атаку на Солнечных Ястребов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10067] = {title = "Смрадные водные духи", objective = "Убейте 6 смрадных водных духов и вернитесь к воздаятельнице Корин в селение Привал Защитника.", description = "С теми существами, которых коснулась энергия кристаллов, происходит в основном одно и то же: на плоти появляются странные метки, заметны впившиеся в тело осколки кристаллов, а агрессивность возрастает многократно. Однако смрадные водные духи к северу отсюда, похоже, полностью превращаются в кристаллы.\n\nНикогда не видела, чтобы живые существа так реагировали на кристаллы. Но в том мерзком озерце они были особенно агрессивны. Думаю, от этих тварей надо избавиться, пока Солнечные Ястребы не прибрали их к рукам и не использовали против нас.", progress = nil, completion = "Прекрасно, Эксордим. Нужно приложить все усилия, чтобы лишить Солнечных Ястребов поддержки.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10068] = {title = "Чародейские стрелы", objective = "Обучитесь заклинанию \"Чародейские стрелы\" у Джулии Солнцесвет. Найдите тренировочный манекен возле Солнечного Шпиля и дважды испытайте на нем Чародейские стрелы.", description = "Пришло время получить первый урок по тайным искусствам. Сейчас я покажу тебе новое заклинание – \"Чародейские стрелы\".\n\nТы не сможешь постоянно применять это заклинание, но каждый раз при сотворении какого-либо атакующего заклинания тебе будет выпадать шанс воспользоваться и Чародейскими стрелами.\n\nСтупай, найди тренировочный манекен и <сам/сама> опробуй на нем это заклинание.", progress = nil, completion = "Я ждал тебя, |3-6(Маг).\n\nУ меня есть несколько поручений, для выполнения которых ты подходишь как нельзя лучше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10069] = {title = "Пути света", objective = "Изучите заклинание \"Правосудие\" и \"Печать праведности\" под руководством Джестениса Солнцесвета. Наложите \"Печать праведности\" на себя, затем найдите тренировочный манекен возле Солнечного Шпиля и испытайте \"Правосудие\".", description = "Пришла пора дать тебе первое наставление на пути Света, <имя>. Сейчас я покажу два приема, с помощью которых ты сумеешь помочь себе и своим союзникам в бою.\n\nПервый называется \"Печать праведности\". Под его влиянием все твои удары в ближнем бою будут наносить дополнительный урон от светлой магии.\n\nПока твоя печать держится, ты можешь прибегнуть к \"Правосудию\", чтобы нанести своему противнику дополнительный урон. Ступай, найди тренировочный манекен и попрактикуйся в своих новых приемах.", progress = nil, completion = "Я ждал тебя, |3-6(Паладин).\n\nУ меня есть несколько поручений, для выполнения которых ты подходишь как нельзя лучше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10070] = {title = "Верный выстрел", objective = "Обучитесь Верному выстрелу у следопыта Саллины. Затем найдите тренировочный манекен у Солнечного Шпиля и попрактикуйтесь в использовании выстрела 5 раз.", description = "А теперь пришло время для первого урока.\n\nЯ научу тебя выстрелу, которым и сама часто пользуюсь. Уверена, ты тоже сочтешь этот навык весьма полезным.\n\nКогда мы закончим урок, найди тренировочный манекен и потренируйся на нем.", progress = nil, completion = "Я ждал тебя, |3-6(Охотник).\n\nУ меня есть несколько поручений, для выполнения которых ты подходишь как нельзя лучше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10071] = {title = "Потрошение", objective = "Научитесь Потрошению у налетчика Кариэля. Найдите тренировочный манекен возле Солнечного Шпиля и трижды проведите на нем прием потрошения.", description = "Сейчас я обучу тебя новому приему. Это отличный способ завершить комбинацию боевых маневров мощным аккордом. Попытайся сделать это после нанесения своему противнику хотя бы одного коварного удара. Чем больше ты нанесешь коварных ударов, тем сильнее будет твоя завершающая атака.\n\nНайди поблизости какой-нибудь тренировочный манекен и попрактикуйся.", progress = nil, completion = "Я ждал тебя, |3-6(Разбойник).\n\nУ меня есть несколько поручений, для выполнения которых ты подходишь как нельзя лучше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10072] = {title = "Исцеление раненых", objective = "Научитесь быстрому исцелению у сестры Арины. Пять раз испытайте \"Быстрое исцеление\" на раненых гонцах.", description = "Пришло время дать тебе первое наставление в искусстве целительства. Я обучу тебя основному целительскому заклинанию, при помощи которого ты быстро сможешь лечить раненых союзников.\n\nПосле окончания урока испытай свой новый целительский навык на одном из раненых гонцов, нашедших убежище в Солнечном Шпиле.", progress = nil, completion = "Я ждал тебя, |3-6(Жрец).\n\nУ меня есть несколько поручений, для выполнения которых ты подходишь как нельзя лучше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10073] = {title = "Жертвенный огонь", objective = "Обучитесь Жертвенному огню у призывателя Тель'Лариена. Найдите тренировочный манекен возле Солнечного Шпиля и испытайте на нем заклинание \"Жертвенный огонь\" 5 раз.", description = "Полагаю, тебе уже приходилось слышать о нас, чернокнижниках. Не обращай внимания на слухи – их распускают завистники, устрашенные нашим могуществом.\n\nДавай я покажу тебе одно новое заклинание, которое позволит опалить противника огнем и заставит его еще некоторое время гореть. Как только мы закончим урок, испытай это новое заклинание на одном из тренировочных манекенов возле Солнечного Шпиля.", progress = nil, completion = "Я ждал тебя, |3-6(Чернокнижница).\n\nУ меня есть несколько поручений, для выполнения которых ты подходишь как нельзя лучше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10074] = {title = "Порошок кристалла Ошу'гуна", objective = "Принесите старшему ученому Амерельдине в Халаа 10 порций порошка кристалла Ошу'гуна.", description = "Раньше здесь располагался исследовательский центр первородных дренеев. Они изучали кристаллы наару.\n\nНам удалось обнаружить бесценное сокровище: древние записи о кристаллах из \"алмазной\" горы Ошу'гун. Насколько мы поняли, на территориях, прилегающих к горе, все несет на себе остаточный след порошка кристалла Ошу'гуна. Если ты вдруг найдешь порошок, когда окажешься в тех краях, собери его и принеси мне сюда. В знак моей безграничной признательности ты получишь награду, которую сможешь обменять на многие полезные вещи.", progress = "Кристаллический порошок из горы зарождается в глубинах земли этой области.", completion = "Замечательно, Выручалкин. Это очень поможет нам в битве с мерзавцами из Альянса, которые недавно появились в Запределье.", rewards = "Вы получите:\n\nИсследовательский знак Халаа"}
MultiLanguageQuestData['ru'][10075] = {title = "Порошок кристалла Ошу'гуна", objective = "Раньше здесь располагался исследовательский центр дренеев. Они изучали кристаллы наару.\n\nНам удалось обнаружить бесценное сокровище: древние записи о кристаллах из \"алмазной\" горы Ошу'гун. Насколько мы поняли, на территориях, прилегающих к горе, все несет на себе остаточный след порошка кристалла Ошу'гуна. Если ты вдруг найдешь порошок, когда окажешься в тех краях, собери его и принеси мне сюда. В знак моей безграничной признательности ты получишь награду, которую сможешь обменять на многие полезные вещи.", description = nil, progress = "Раньше здесь располагался исследовательский центр дренеев. Они изучали кристаллы наару.\n\nНам удалось обнаружить бесценное сокровище: древние записи о кристаллах из \"алмазной\" горы Ошу'гун. Насколько мы поняли, на территориях, прилегающих к горе, все несет на себе остаточный след порошка кристалла Ошу'гуна. Если ты вдруг найдешь порошок, когда окажешься в тех краях, собери его и принеси мне сюда. В знак моей безграничной признательности ты получишь награду, которую сможешь обменять на многие полезные вещи.", completion = "Я всегда буду готова принять кристальный порошок, сколько бы ты ни принес, Святойчувакк. За каждую партию порошка, которую ты нам доставишь, ты получишь достойное вознаграждение.", rewards = "Вы получите:\n\nИсследовательский знак Халаа"}
MultiLanguageQuestData['ru'][10076] = {title = "Порошок кристалла Ошу'гуна", objective = "Принесите 10 порций порошка кристалла Ошу'гуна старшему ученому Картосу в Халаа.", description = "Раньше здесь располагался исследовательский центр дренеев. Они изучали кристаллы наару.\n\nНам удалось обнаружить бесценное сокровище: древние записи о кристаллах из \"алмазной\" горы Ошу'гун. Насколько мы поняли, на территориях, прилегающих к горе, все несет на себе остаточный след порошка кристалла Ошу'гуна. Если ты вдруг найдешь порошок, когда окажешься в тех краях, собери его и принеси мне сюда. В знак моей безграничной признательности ты получишь награду, которую сможешь обменять на многие полезные вещи.", progress = "Кристаллический порошок из горы зарождается в глубинах земли этой области.", completion = "Замечательно, Кипал. Это очень поможет нам в битве с мерзавцами из Орды, которые недавно появились в Запределье.", rewards = "Вы получите:\n\nИсследовательский знак Халаа"}
MultiLanguageQuestData['ru'][10077] = {title = "Порошок кристалла Ошу'гуна", objective = "Раньше здесь располагался исследовательский центр дренеев. Они изучали кристаллы наару.\n\nНам удалось обнаружить бесценное сокровище: древние записи о кристаллах из \"алмазной\" горы Ошу'гун. Насколько мы поняли, на территориях, прилегающих к горе, все несет на себе остаточный след порошка кристалла Ошу'гуна. Если ты вдруг найдешь порошок, когда окажешься в тех краях, собери его и принеси мне сюда. В знак моей безграничной признательности ты получишь награду, которую сможешь обменять на многие полезные вещи.", description = nil, progress = "Раньше здесь располагался исследовательский центр дренеев. Они изучали кристаллы наару.\n\nНам удалось обнаружить бесценное сокровище: древние записи о кристаллах из \"алмазной\" горы Ошу'гун. Насколько мы поняли, на территориях, прилегающих к горе, все несет на себе остаточный след порошка кристалла Ошу'гуна. Если ты вдруг найдешь порошок, когда окажешься в тех краях, собери его и принеси мне сюда. В знак моей безграничной признательности ты получишь награду, которую сможешь обменять на многие полезные вещи.", completion = "Спасибо за помощь, Артеус. Если найдешь еще порошок - ты знаешь, куда его нести!", rewards = "Вы получите:\n\nИсследовательский знак Халаа"}
MultiLanguageQuestData['ru'][10078] = {title = "Сжечь старье!", objective = "Используйте горящий факел и подожгите клинкометы Орды, стерегущие Путь Славы. После выполнения задания верните факел Болтую в Оплот Чести.", description = "Теперь, когда мы успешно завершили нашу операцию по сбору вторсырья, можно перейти ко второй части плана.\n\nВдоль Пути Славы все еще стоят старые самонаводящиеся клинкометы Орды. И пусть их возраст не вводит тебя в заблуждение, <имя>, они по-прежнему очень, очень опасны. Мы сами пытаемся пустить на переработку все, что возможно, так что не думаю, что Орда просто так возьмет и забудет про эти машины.\n\nВозьми факел и подожги все уцелевшие осадные орудия. Не должно остаться ни малейшего шанса, что их снова будут использовать против Оплота Чести.", progress = "Похоже, ты в хорошем настроении. Что, горящие осадные машины Орды согрели твою душу?", completion = "Вот это сила духа!\n\nЯ рад, что мы наконец получили подкрепление, но я не уверен в их отношении к Орде. На моей родине считают врагом любого, кто поднял на тебя руку, а с врагом у нас разговор короткий!", rewards = "Прошитые брюки странникаПрошитый природой килтШлем влеченияЧешуйчатая клейменая кольчугаВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][10079] = {title = "Весь рудник ходуном", objective = "Убейте 12 ган'аргов-саперов и вернитесь к штейгеру Большие Десны.", description = "На руднике просто не продохнуть от ган'аргской заразы!\n\nМало того, что они вышвырнули всех моих рабочих из штреков, так продолжают там днем и ночью вести подрывные работы! И вдобавок на меня ополчился сам Данат. Сказал, что если я не справлюсь с проблемой, и немедленно, он лишит меня поставок пива.\n\nНикто из шахтеров не работает, а стража от страха напилась до потери пульса.\n\nУмоляю, <имя>, спаси меня! Можешь меня презирать, но пиво мне дороже, чем гордость!", progress = "Скажи мне, что все уже закончилось и мои ребята могут вернуться к работе... ну пожалуйста!", completion = "Клянусь золотой бородой Бронзоборода, ты сделал это! Да ты просто герой, Крайтеен.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10081] = {title = "Встреча с Матерью Кашур", objective = "Поговорите с Матерью Кашур.", description = "Не бойся того, что увидишь, когда снадобье подействует! Духи – они всегда рядом с нами. Повсюду, всегда. Снадобье просто откроет твой разум, чтобы ты <видел их и понимал/видела их и понимала>. Иначе ты просто не сможешь поговорить с Матерью Кашур.\n\nТы найдешь ее на юго-западе, далеко-далеко отсюда, в Землях Предков.", progress = nil, completion = "Снадобье, которое ты выпил, на самом деле не дает никакого эффекта. Если дух не захочет тебе показаться, ты его не увидишь, несмотря ни на какие \"волшебные\" зелья. Снадобье – это всего лишь символ твоей веры и преданности. Это было испытание, и ты его прошел...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10082] = {title = "Покой предков", objective = "Уничтожьте 8 потревоженных духов орков по просьбе Матери Кашур.", description = "Видишь, они разгуливают среди нас? Обычно ничто не тревожит покой Земель Предков.\n\nОднако в последнее время духи предков пробудились от мирного сна, и они явно чем-то встревожены. Что-то нарушило их покой. Мы должны выяснить, что именно. Но сначала мы должны разобраться с угрозой, которую следует устранить незамедлительно.\n\nЭти призраки, которые ходят среди живых... на самом деле это не духи, а зримые образы их состояния. Я хочу, чтобы ты <уничтожил/уничтожила> потревоженных духов орков. Когда исполнишь мое поручение, возвращайся ко мне.", progress = "Тебе нужно особое зелье, для того чтобы видеть духов, Транделар.", completion = "Бесполезно. Они восстают вновь и вновь. Ладно, будем разбираться...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10085] = {title = "Навестить предков", objective = "Мать Кашур хочет, чтобы вы посетили заставу Солнечного Источника, руины Веселого Черепа, Гарадар и руины Кровавой Глазницы.", description = "Я хочу, чтобы ты, <имя>, <объехал/объехала> поселения предков. Посети их все, один за другим, и убедись, что все в порядке.\n\nЗастава Солнечного Источника на севере, руины Веселого Черепа у подножия северных гор, Гарадар на северо-востоке и, наконец, руины Кровавой Глазницы на востоке, на границе Награнда и леса Тероккар.\n\nКак закончишь, возвращайся ко мне с отчетом.", progress = "Лети быстрее ветра, Магнетрикс.", completion = "Это тревожные новости. То есть в поселениях не осталось ни одного предка? Все движутся на юг?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10086] = {title = "Я служу... Орде!", objective = "Принесите 8 кусков металлолома и 8 кусков древесины Мегзегу Крутогруду в Траллмар.", description = "Ты можешь себе это представить? Орки наняли меня чинить укрепления и изготавливать взрывчатку. Не работа, а мечта! Единственно что, – материалов не хватает, но умный гоблин всегда что-нибудь да придумает.\n\nПомоги мне немного, а? Мне нужна древесина и металл, которые можно найти в обломках вдоль Пути Славы. Отправляйся туда и собери, что сможешь, но остерегайся краснокожих орков!\n\nВернешься с добычей – о награде не пожалеешь!", progress = "Как там поживает сбор утиля? Нашел что-нибудь стоящее?", completion = "Отличный материал! Здесь немного покореженный, здесь малость обгорелый, но даже из этого старья я сооружу отличную взрывчатку.\n\nСпасибочки, Менгиле. Сразу видно, что ты знаешь толк в мусоре!", rewards = "Иллюзорный головной уборНагрудный доспех искателя битвыУкрашенный шлем легионераНаголенники мирового судьиВы получите:\n\n"}
MultiLanguageQuestData['ru'][10087] = {title = "Сжечь! Во имя Орды!", objective = "Используя горящий факел, подожгите восточную пушку Альянса и западную пушку Альянса. После выполнения задания возвращайтесь к Мегзегу Крутогруду в Траллмар.", description = "Я невероятно счастливый гоблин. Я изготавливаю взрывчатку и прочие орудия убийства, которые жизненно необходимы для ведения военных действий!\n\nКстати, что касается дел. Я только что узнал об одном приказе из Траллмара. Надо спалить все пушки Альянса на той стороне Пути Славы... слишком они близко к укреплениям Орды. Вот, возьми факел и не пропусти ни одной пушки. Подожги их как следует, и можешь наслаждаться фейерверком.", progress = "Странно, почему я ничего не слышал, – ни воплей паленых орков Скверны, ни запаха дыма...\n\nЗадание-то выполнил?", completion = "Так я и думал! Отсюда, конечно, было ничего не разглядеть, но могу представить, как оно взрывалось. Прелестно, просто прелестно!\n\nНеплохая работенка, Выручалкин. В Траллмаре будут рады слышать о твоих подвигах.", rewards = "Прошитые брюки странникаПрошитый природой килтШлем влеченияЧешуйчатая клейменая кольчугаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10091] = {title = "Инструменты души", objective = "Украдите 5 инструментов души и доставьте их повелительнице шпионов Мелисе Высокий Венец в Шаттрат на Террасу Света.", description = "Ох! Они пытали меня, хотели вытянуть из меня все, что я знаю...\n\nЯ потерпел неудачу – они скормили всех наших Адской Глотке, и я должен был быть следующим... Но я ничего, ничего им не выдал!\n\nОни просто сумасшедшие. Они упрямо призывают демонические силы, которые не могут контролировать.\n\nОни увеличивают мощность вызова при помощи специальных машин, которые усиливают их осколки души. Эти устройства нужно украсть!\n\nЯ бы присоединился к тебе, но мне нужно как можно скорее вернуться в Шаттрат и доложить начальнице разведки Нижнего города.", progress = "Да? Чем могу быть полезна, |3-6(Охотник)?", completion = "То'гун уже был здесь и доставил мне донесение. А мог бы, на самом деле, остаться и помочь тебе.\n\nЯ отослала его обратно, помогать Грик'те. Думаю, из них выйдет милая парочка...\n\nИтак, это и есть инструменты души, которые Совет Теней использует, чтобы увеличивать силу призыва? Мне кажется, что это опасные предметы. Может быть, Провидцы знают, что с ними делать?\n\nПожалуйста, прими от меня награду за то, что помешал Совету Теней делать свое черное дело.", rewards = "Боевые наручи Ша'тарАукенайские наручиНарукавники хозяйки шпионовШаттратские напульсникиВы получите:\n\n"}
MultiLanguageQuestData['ru'][10093] = {title = "Храм Телхамат", objective = "Поговорите с Амааном Мудрым в храме Телхамат, который находится на западе полуострова Адского Пламени.", description = "К счастью, Путь Славы – не единственный, по которому может пройти мой народ. К западу отсюда уцелело несколько святых мест, хотя часть из них захватили враги.\n\nПока Велен готовился к путешествию на Азерот, те из нас, кто остался на юге, пытались возродить там жизнь.\n\nНа западе полуострова Адского Пламени, в храме Телхамат, ты найдешь небольшую горстку дренеев, которую возглавляет Амаан Мудрый. Уверен, ему будет интересно с тобой познакомиться.", progress = nil, completion = "А, ты знаешь провидца Крива. Он мудр и обладает многими добродетелями. Любой |3-6(человек), который зовет его другом, станет другом и мне.\n\nРасполагайся здесь. Можешь познакомиться с остальными обитателями храма.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10094] = {title = "Кодекс Крови", objective = "Прочитайте Кодекс Крови в Темном лабиринте в Аукиндоне.", description = "Два года назад Совет Теней вызвал демона и не сумел его удержать. В результате произошел взрыв, который обрушил эту великую некогда усыпальницу. На ее месте образовались Костяные пустоши.\n\nА теперь Совет Теней собрался воевать с какими-то невероятно могучими силами.\n\n<имя>, тебе придется пробраться в Темный лабиринт и узнать, на кого они ополчились, и представляет ли это опасность для нас. Наши разведчики доносят, что они используют запретную книгу призывания нечисти, известную как Кодекс Крови.\n\nЯ думаю, на ее страницах ты найдешь ответы на все наши вопросы.", progress = nil, completion = "Как только вы открываете парящую в воздухе книгу, вас охватывает ужас.\n\nЗдесь определенно происходит что-то страшное!\n\nВы пытаетесь читать, но то, что написано в книге, кажется совершенно невероятным.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10095] = {title = "В самом сердце Лабиринта", objective = "Уничтожьте Бормотуна и доложите о том, что произошло внутри Темного лабиринта, повелительнице шпионов Мелисе Высокий Венец, которую можно найти на террасе Света в Шаттрате.", description = "Совет Теней потерял контроль над неким космическим существом, которое он призвал два года назад. Именно это привел к взрыву Аукиндона и появлению Костяных пустошей.\n\nТеперь это создание, известное как Бормотун, пытается уничтожить Совет Теней и вырваться во внешний мир.\n\nВеликий магистр и все верховное руководство Совета мертвы, так что ты – наша последняя защита от этого чудовища!\n\n<имя>, ты и твои товарищи не должны потерпеть поражение!", progress = nil, completion = "Бормотун едва не вырвался на волю? Почти два года они худо-бедно контролировали это существо... Но я знала, что рано или поздно они совершат ошибку и потеряют над ним контроль.\n\nДушавдушу, уничтожив этого монстра, ты спас всех нас. Боюсь даже подумать, что стало бы с Запредельем, если бы эта тварь вырвалась на свободу!\n\nЯ счастлива, что ты помог нам справиться с угрозой, которая пришла в Аукиндон по милости Совета Тени! Чем мы можем отблагодарить тебя?", rewards = "Скованные Ша'тар наголенникиАукенайские сапогиСапоги хозяйки шпионовШаттратские прыгуныВы получите:\n\n"}
MultiLanguageQuestData['ru'][10096] = {title = "Спасение спорлоков", objective = "Убейте 10 болотных черпальщиков и 10 болотных скрытней и вернитесь к Лоранне Тар'велл в Кенарийский приют в Зангартопи.", description = "Икейен немало рассказывал мне о том, что с ним произошло в этих пещерах. По-моему, это просто кошмар!\n\nЗнаете, наверное, мы должны что-то сделать, чтобы помочь этим бедным спорлокам. Икейен говорит, что они живут в пещере Грибгор, но недавно туда вторглись твари с болот.\n\nМожет быть, вы сходите туда и попробуете избавиться хотя бы от части болотных хищников? Пещера находится на юго-западе.", progress = nil, completion = "Отлично! Эти болотные твари не имеют никакого права захватывать дом спорлоков!\n\nКонечно, было бы лучше, если бы эти существа научились мирному сосуществованию, но, раз уж это невозможно, нам следует взять дело в свои руки!\n\nВот, пожалуйста, возьмите это в благодарность за труды.", rewards = "Стойкий шлем кругаЭкспедиционные поножи фуражираСорочка возрожденияКапюшон разведчикаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10097] = {title = "Брат на брата", objective = "Проникните в Сетеккские залы и убейте Темнопряда Сита. Освободите из плена Лакку. После этого вернитесь к Исфару, который находится неподалеку от входа в Сетеккские залы.", description = "Когда Аукиндон взорвался, племя Сетек с большой помпой покинуло Скеттис. Они сочли взрыв знаком прибытия их господина.\n\nМой брат Сит был одним из лидеров племени Сетек, и именно ему принадлежала идея, что мы должны выйти к руинам храма и встретить нашего бога.\n\nПосле того как мы поселились в руинах, назвав их Сетеккскими залами, я начал сомневаться в разумности моего брата и его союзника, Айкисса.\n\nЧерез некоторое время Сит изгнал меня из племени, но запретил забрать с собой нашу сестру Лакку. Ты поможешь мне спасти ее?", progress = "Ты сумел найти ее, Кацан? Или она все еще в плену?", completion = "Мне не хватает слов, чтобы выразить, как я тебе благодарен, Выручалкин! Теперь, когда Лакка свободна, оборвались последние нити, связывающие меня с племенем Сетекков.\n\nЯ никогда не прощу себе смерти Сета, но это должно было свершиться. По возвращении в Скеттис я сам исполню по нему похоронные ритуалы. Может быть, его дух обретет покой, когда искупит вину перед нашим народом, который он сбил с пути...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТорк сетеккского пророкаСредоточие оракула СетеккаБусы Лорда КогтяЗнак ворона-стража\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10098] = {title = "Наследство Терокка", objective = "Принесите маску Терокка, перо Терокка и \"Сказание о Терокке\" Исфару, который находится неподалеку от Сетеккских залов.", description = "Мой народ свято чтит древнего героя по имени Терокк. Птенцы араккоа упиваются историями о его подвигах и описаниями его роскошного оперения.\n\nМногие сотни лет он жил с моим народом, а потом бесследно исчез, оставив лишь маску, копье и некоторые записи.\n\nАраккоа почитают эти реликвии, и они были убиты горем, когда племя Сетекков, уходя из Скеттиса, похитило их и унесло с собой.\n\nЯ записал то немногое, что мне известно о местонахождении этих реликвий.", progress = "Реликвии, принадлежащие Терокку, слишком давно покинули Скеттис. Удалось ли тебе вырвать их из лап племени Сетекк?", completion = "Я стоял у истоков злодеяний племени Сетекк, и за это нет мне прощения. Может быть, возвращение реликвий Терокка хоть немного оправдает меня в глазах моего народа.\n\nСпасибо тебе за помощь, Джонниди. Ты даже не представляешь, сколь велико совершенное тобой дело.", rewards = "Перо ТероккаМаска ТероккаВам дадут возможность выбрать одну из следующих наград:\n\nСказание о Терокке\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10099] = {title = "Мозговой центр", objective = "Найдите и убейте З'крала в рудниках под Оплотом Чести, и доложите об этом штейгеру Большие Десны.", description = "Эти чертовы ган'арги продолжают расползаться по всему руднику! Только убьешь одного, как его место занимают сразу трое!\n\nНаверняка есть кто-то, кто руководит этим вторжением из самых глубин рудника. В прошлый раз ты <вел/вела> себя достаточно храбро, и я не исключаю, что ты <единственный/единственная> у кого достанет отваги, чтобы спуститься в рудник еще раз. Найди того, кто стоит у истоков всех этих беспорядков, и пусть он дорого нам заплатит!", progress = "Я даже боюсь спрашивать. Если ты выбрался из рудника живым, то варианта только два: тебе удалось прикончить эту сволочь, или у тебя отказали нервы. Ну так что, в итоге?", completion = "Я так рад, что ты смог позаботиться о...о... Как, ты говоришь, оно себя называло? З'Крел?\n\nПо твоему описанию я не смог понять, какого оно пола. Но это совершенно не важно, раз оно уже дохлое.", rewards = "Кушак старшиныТяжелый шахтерский поясШахтерское наплечьеВы получите:\n\n"}
MultiLanguageQuestData['ru'][10101] = {title = "Когда говорят духи", objective = "Разыщите К'уре в Ошу'гуне.", description = "Ошу'гун, алмазная гора, когда-то была святыней моего народа. Каждый год все кланы собирались у ее подножия, чтобы отпраздновать наступление весны. Именно там верховный шаман взывал к духам наших досточтимых предков. Гора была центром нашей культуры, пока сумрак не поглотил нас. Когда кланы стали дикой и неуправляемой ордой, духи Ошу'гуна умолкли. Предки отвернулись от нас.\n\nНо что-то нарушило их вечный покой. Отправляйся к Ошу'гуну и узнай у него, что потревожило покой наших предков.", progress = nil, completion = "&lt;К вам в сознание проникает нежный, мелодичный голос.&gt;\n\nЯ – наару по имени К'уре, Таквер. Ты проник в самое сердце моего древнего корабля.\n\nОшу'гун, как его называют орки, на самом деле – корабль, который впервые принес дренеев в этот мир. Хотя мы потерпели крушение много веков назад, моя энергия до сих пор заперта внутри обломков корабля. Увы, именно я и есть источник страданий орочьих духов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10102] = {title = "Раскрытая тайна", objective = "Поговорите с А'далом в Шаттрате.", description = "Долгие столетия я беспомощно наблюдал, как иссякает моя энергия, затягивая в образовавшуюся пустоту поколения орочьих душ. Но недавно мои враги подчинили себе этот водоворот и принялись пополнять Пылающий Легион бессчетными ордами тварей Бездны.\n\nИ теперь, чтобы разорвать этот круг и освободить души орков, нужна помощь другого наару – А'дала. Я ощущаю его присутствие в древнем городе Шаттрате в лесу Тероккар.", progress = nil, completion = "К'уре поступил мудро, отправив тебя сюда. Увы, мы не в силах облегчить страдания орочьих предков, но я знаю, кто сможет тебе помочь.\n\nЭто тот, кому очень скоро предстоит возродиться в лучах Света...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10103] = {title = "Донесение Зураю", objective = "Поговорите с Зураем на заставе Болотной Крысы в Зангартопи.", description = "После прибытия полевого командира Ромуса с подкреплением Альянс и его дренейские приятели чересчур осмелели. Они окопались во всех дренейских руинах отсюда и аж до Шаттрата.\n\nВ ответ тролли заложили новую заставу в восточной части Зангартопи, к югу от Мертвой трясины, и окрестили ее заставой Болотной Крысы. Они еще способны шутить, обитая в подобном месте! Я вот так не могу.\n\nКомандир заставы просил меня прислать к ним кого-нибудь из резерва.", progress = nil, completion = "Откровенно говоря, я ожидал большего, но и для тебя дело найдется. Добро пожаловать на заставу Болотной Крысы!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10104] = {title = "Опасения за судьбу Туурема", objective = "Поговорите с Андарлом в бастионе Аллерии в Тероккаре.", description = "О судьбе Туурема ходят тревожные слухи. Говорят, что в развалинах города ютятся обезумевшие Сломленные и Заблудшие, а тем временем охотники за сокровищами расхищают дренейские реликвии. Что тут правда, а что нет, сказать трудно, однако мы обязаны сберечь эти руины, насколько это возможно. Отправляйся в бастион Аллерии в лесу Тероккар и отыщи там Андарла. Он немного интересуется магическими артефактами. И если кто-то и знает, что происходит в Тууреме, то это именно Андарл.", progress = nil, completion = "Я, разумеется, польщен тем, что твой друг-сломленный считает меня специалистом по реликвиям его народа, но, если честно, с тех пор, как я сюда прибыл, у меня почти не было возможности их изучать. Конечно, я явился сюда именно ради них, но по прибытии обнаружилось, что здесь есть много куда более важных дел...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10105] = {title = "Вести для Ракории", objective = "Поговорите с Ракорией из форта Камнеломов в лесу Тероккар.", description = "Теперь, когда застава Болотной Крысы достроена, нам будет куда проще охранять дороги, ведущие на болота. А вот в лесу Тероккар все куда хуже... И тем не менее Ракория, которая живет в Форте Камнеломов, ждет известий о том, как у нас дела.\n\nОна – баба расторопная и сметливая, но ты, <имя>, держи с ней ухо востро. Она заинтересована в том, чтобы дороги были безопасны, но не думай, будто у нас с ней общие интересы. Ракорию прежде всего интересует прибыль.", progress = nil, completion = "Я рассчитывала, что его бойцы достроят заставу раньше, но ему-то куда спешить, он на этом денег не теряет. Ну, хоть теперь достроили, и на том спасибо.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10106] = {title = "Штурмовые укрепления", objective = "Захватите обзорную площадку, ристалище и Изрезанный холм, и возвращайтесь к прапорщику Трейси Праудвелл в Оплот Чести на полуострове Адского Пламени.", description = "Цитадель Адского Пламени уже долгое время отбивает все наши атаки. Мы сохраняем позиции, но не можем перейти в решительное наступление. Нам необходимо укрепить передовые.\n\nРазведчики обнаружили рядом с Цитаделью Адского Пламени три форта. Мы должны их захватить. Помоги нашим войскам и доложи мне, когда все три перейдут к нам.\n\nПусть удача сопутствует тебе в битве, <имя>. Скорее всего, Орда тоже положила глаз на эти укрепления, так что тебе придется иметь дело с ее войсками.", progress = nil, completion = "Ты славно потрудился, Мисхле. Благодаря твоим ратным подвигам мы еще долго продержимся на Полуострове Адского Пламени!", rewards = "Вы получите:\n\nПочетный знак Оплота ЧестиCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][10107] = {title = "Дипломатическая миссия", objective = "Джорин Мертвый Глаз из Гарадара в Награнде попросил вас поговорить с Лантрезором Клинком в руинах Пылающего Клинка.", description = "Килрат передал нам сведения про вождя клана Тяжелого Кулака: это орк! Древний орк, который прошел через Темный портал еще во времена наших отцов и вернулся назад. Если бы ты <нашел/нашла> его и <убедил/уговорила> отозвать огров... Его ставка находится на верхнем плато руин Пылающего Клинка на юго-востоке, на окраине леса Тероккар. Удачи, <имя>!\n\nИ будь <осторожен/осторожна>, он мастерски владеет мечом...", progress = "Говори.", completion = "Так что ты решил? Мы будем воевать или ты окажешь нам помощь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10108] = {title = "Дипломатическая миссия", objective = "Мо'мор Разрушитель из Телаара в Награнде попросил вас поговорить с Лантрезором Клинком в руинах Пылающего Клинка.", description = "Лазутчики-охотницы передали нам сведения про вождя клана Тяжелого Кулака: это орк! Древний орк, который прошел через Темный портал еще во времена наших отцов и вернулся назад. Если бы ты <нашел/нашла> его и <убедил/уговорила> отозвать огров... Его ставка находится на верхнем плато руин Пылающего Клинка на юго-востоке. Удачи, <имя>!\n\nИ будь <осторожен/осторожна>, он мастерски владеет мечом...", progress = "Говори.", completion = "Так что ты решил? Мы будем воевать или ты окажешь нам помощь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10109] = {title = "Я их достану!", objective = "Принесите 3 порции пара элементалей воздуха Вазату в Южный Награнд.", description = "Видишь? Клянусь зловонным дыханием Газлоу, я достану эти яйца! Кстати, ты мне можешь пригодиться.\n\nВот что я тебе скажу, <раса>: найди мне кое-какие детали для моего \"Прыготрона-4000\", а я дам тебе ключ для управления этим механизмом. У меня как раз есть запасной! Ты спросишь, на что способна эта штуковина? Легче сказать, чего \"Прыготрон-4000\" не может...\n\nМне понадобится пар элементалей воздуха, собранный с Награндских элементалей воздуха. И не спрашивай, как их найти: они там повсюду!", progress = "Газ достал?", completion = "Великолепно! Еще пара деталей – и будет как новенький. Ах да, вот твой ключ. Держи!\n\nПрыготрон еще не отлажен. Так что… поосторожнее с ним.", rewards = "Вы получите:\n\nКлюч от Прыготрона-4000"}
MultiLanguageQuestData['ru'][10110] = {title = "Штурмовые укрепления", objective = "Захватите Обзорную площадку, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны.", description = "Мы должны стереть проклятых орков Скверны с лица нашей земли! Но перед тем, как напасть на цитадель Адского Пламени, необходимо укрепить позиции.\n\nГонцы обнаружили три форта, которые хорошо подходят для наших целей. К сожалению, Альянсу пришла в голову та же идея, и он уже выдвинул войска, чтобы захватить эти укрепления.\n\nТы <должен/должна> отбросить силы Альянса и помочь нашему войску захватить все три форта. Когда выполнишь это задание, возвращайся ко мне.\n\nВо славу Орды!", progress = "Возвращайся, когда все укрепления будут захвачены!", completion = "Славная работа, Ушелслимба. Я как наяву слышу звуки битвы, которая там разыгралась. Хотела бы я это видеть своими глазами!", rewards = "Вы получите:\n\nПечать ТраллмараCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][10111] = {title = "Принеси мне яйцо!", objective = "С помощью Прыготрона-4000 запрыгните в гнездо на ближайшем дереве и украдите оттуда таинственное яйцо.", description = "Ну, раз уж тебя пригласили туда, постарайся добыть для меня это яйцо! Воспользуйся прыготроном и попробуй попасть в самый центр гнезда. Но будь <осторожен/осторожна>! Неудачный прыжок может закончиться серьезными травмами или неизлечимым увечьем.", progress = "Я говорил, как люблю яйца?", completion = "Э... это не яйцо... Погоди-ка! Цыпляток я тоже люблю! Их огромные коготочки так славно хрустят на зубах! Вот спасибо!", rewards = "Защитник созидателя чарТканый плащ кочевникаИзысканное зеленое пончоВы получите:\n\n"}
MultiLanguageQuestData['ru'][10112] = {title = "Личное одолжение", objective = "Найдите 5 украденных товаров Латрая и верните их хозяину. Латрая можно найти возле таверны \"На краю земли\" в Нижнем городе Шаттрата.", description = "Мммм? Коробка, говорите? Или несколько коробок? А из какого материала она была сделана?\n\nИ как звали торговца? Эмпур? Вы уверены, что он из Сломленных? Я вообще-то с ними дел не имею.\n\nХотя я мог бы сделать для вас исключение, но только в обмен на услугу!\n\nЭти примитивные колдуны – скитийские араккоа – недавно украли большую партию моих экзотических товаров, и я хочу вернуть их!\n\nОни утащили мои вещи в гнездовье Скит, это к югу от Шаттрата.", progress = "Хммм, неужто моя память улучшается?", completion = "Да, в самом деле, я все вспомнил!\n\nИ я думаю, что вы заработали чуть больше, чем ваша драгоценная информация.", rewards = "Боярышниковый плащ КонсорциумаАраккоанский пророческий жезлВам дадут возможность выбрать одну из следующих наград:\n\nКольцо ловца НексусаАстральная исцеляющая подвеска\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10113] = {title = "Охотничий лагерь Эрнестуэя", objective = "Поговорите с Хемингом Эрнестуэем в охотничьем лагере Эрнестуэя на северо-восточной границе Награнда.", description = "\"Иди и найди какие-нибудь припасы!\" – так он и сказал. Да меня раз пятнадцать чуть не укокошили, пока я сюда добирался! Эти Сломленные, конечно, не самые добродушные ребята на свете, но они хотя бы не пытаются меня освежевать.\n\nТак или иначе, назад я не вернусь. Кончились мои охотничьи деньки. Если ты направишься на северо-восток, в сторону Зангартопи, и вдруг набредешь на охотничий лагерь Эрнестуэя, передай им, что \"Дробовик\" отстрелялся!\n\nПослушай, а может, ты займешь мое место? Попробуй, и пусть тебе улыбнется удача, <незнакомец/незнакомка>.", progress = nil, completion = "М-да, придется искать нового мальчика на побегушках. Э...Ну или девочку. Ты мне подойдешь, |3-6(Охотник). Может, поработаешь на меня? Или ты собираешься охотиться?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10114] = {title = "Охотничий лагерь Эрнестуэя", objective = "Олорм Странник просит вас поговорить со Странником Шадо \"Фитцем\" в охотничьем лагере Эрнестуэя в Награнде.", description = "Эти орки никогда раньше не видели тауренов, как бы невероятно это ни звучало. Если бы не капитан Крогхан, они бы уже готовили из меня ужин.\n\nНо простите мою бестактность, я же не представился. Я – Олорм Странник, величайший из охотников! Я вхожу в экспедицию Эрнестуэя, прибывшую сюда из Азерота в поисках большой добычи. Если вас интересует охота, присоединяйтесь к моим людям в охотничьем лагере Эрнестуэя. Он находится к востоку отсюда, у границы с Зангартопью.", progress = nil, completion = "Отрадно слышать, что он в безопасности. Ты хочешь присоединиться к охоте?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10115] = {title = "Искажение Остротопи", objective = "Убейте 3 убийц Остротопи и 15 грязекопов Остротопи.", description = "Куренай и дренеи не всегда сходятся во взглядах, особенно когда речь идет о Заблудших. Мы помогаем Заблудшим, которые к нам обращаются, но не донимаем их своими наставлениями. Некоторые же дренеи слишком навязчиво пытаются их \"обратить\".\n\nОднако бывают случаи, когда Заблудшие заходят чересчур далеко. Таково и племя Остротопи. В своей деревне к западу отсюда эти Заблудшие изготовляют яды и упражняются в обмане и подлости. Эти ремесла никогда не были близки дренеям!\n\nНеобходимо это пресечь, пока подлое племя Остротопи не распространило свое влияние дальше...", progress = nil, completion = "Молодец, Рокинстар. Племя Остротопи абсолютно безнадежно, с какой стороны ни взгляни, но я не уверен, что дренеям хватило бы духу быстро принять соответствующие меры.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10116] = {title = "Разыскивается: вождь Муммаки!", objective = "Принесите тотем вождя Муммаки Икути в прибежище Оребор.", description = "Разыскивается вождь Муммаки, предводитель гнусного и выродившегося племени Заблудших, обитающего в Остротопи. Он обвиняется в жестоких нападениях на Прибежище Оребор.\n\nВождь и его банда убийц виновны в смерти множества куренай и дренеев. С ними стоит иметь дело только опытным бойцам!\n\nПутешественникам рекомендуется избегать окрестностей деревни Остротопь, расположенной к западу от Прибежища Оребор.\n\nЧтобы получить награду, следует представить Икути доказательства смерти вождя.", progress = "Так ты хочешь получить награду за вождя Муммаки?", completion = "Неплохо! До тебя были и другие, кто надеялся получить награду, но они так и не вернулись за ней. Нетрудно представить, что с ними стало.\n\nЯ рад, что Муммаки и его ублюдки больше не будут нас тревожить.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10117] = {title = "Разыскивается: вождь Муммаки!", objective = "Принесите тотем вождя Муммаки темному охотнику Денжаю.", description = "Разыскивается вождь Муммаки, предводитель гнусного и выродившегося племени Заблудших, обитающего в Остротопи. Он обвиняется в жестоких нападениях на Забра'джин и его обитателей.\n\nВождь и его банда убийц виновны в смерти множества разведчиков и гонцов. С ними стоит иметь дело только опытным бойцам!\n\nПутешественникам рекомендуется избегать окрестностей деревни Остротопь, расположенной к северо-западу от Забра'джина.\n\nЧтобы получить награду, следует представить доказательства смерти вождя темному охотнику Дэнжаю.", progress = "Так ты хочешь получить награду за вождя Муммаки?", completion = "Благодарю тебя, Щук! А то я уже начал думать, что мне придется отправиться туда самому, взяв с собой значительную часть гарнизона. А что бы тогда могло стать с Забра'джином – и думать не хочется...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10118] = {title = "Разговор с Остротопью", objective = "Убейте 3 убийц и 15 грязекопов из племени Остротопи, и вернитесь к темному охотнику Денжаю в Забра'джин.", description = "Из всех племен Заблудших в Зангартопи племя Остротопи – самое злобное и хитрое! Они хорошо организованы и не скрывают, что стремятся подчинить себе всех прочих Заблудших, что живут на болотах.\n\nОни уже не раз нападали на моих разведчиков и гонцов. Я не могу себе позволить и дальше терять воинов!\n\nЕсли мы ничего не предпримем в ближайшее время, они перекроют все дороги, и Забра'джин окажется в осаде!", progress = nil, completion = "Думаю, твоя беседа окажется для них достаточно доходчивой. Этот язык они понимают отлично. Теперь и мои бойцы не будут так страшиться встречи с племенем Остротопи. Или же, по крайней мере, они станут стыдиться своей трусости!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10119] = {title = "Через Темный портал", objective = "Пройдите через Темный портал и найдите командора Дарона. Он ждет вашего прибытия на другой стороне, в Запределье.", description = "В течение двадцати лет Темный портал оставался безмолвным монументом – памятником давно забытым временам. \n\n<Релторн оглядывается по сторонам.>\n\nНикогда не думал, что доживу до этого дня, и тем не менее мы стоим здесь и смотрим в бездну.\n\nПо другую сторону этого портала мы втянуты в жестокую войну – войну, которую без поддержки нам не выиграть. Тебе следует пройти через Темный портал и помочь нашим войскам, <класс>.\n\nНемедленно явись к командиру Дарону. Он ждет тебя в Запределье...", progress = nil, completion = "Welcome to Outland, &lt;имя&gt; -- welcome to the nightmare! Though the initial Expeditionary Force made it through unscathed, the Legion is attempting to retake the Dark Portal and prevent any of our reinforcements from coming through.\n\nAs much as I'd like your aid here, our troops and the Horde soldiers are able to fend off the Legion platoons that are attempting to take control of this platform.\n\nWe need you where your talents can best be utilized.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10120] = {title = "Прибытие в Запределье", objective = "Доставьте донесение Ориона Влагге Легкоперой у Темного портала на полуострове Адского Пламени.", description = "С помощью Альянса наши силы будут удерживать эти позиции, но ты <должен/должна> доставить мое донесение генералу Кракорку в Траллмар. Когда он присоединится к нам, мы вышвырнем демонов обратно в бездну, которая их породила! Поговори с Влаггой Легкоперой, она стоит на площадке позади нас. Она поможет тебе добраться побыстрее.", progress = "Я слышала, ты говорил с Орионом. Должно быть, важное дело.", completion = "Значит, теперь ты новый посланник Ориона. Надеюсь, ты стоишь больше, чем предыдущие, |3-6(Друид). Легион постоянно нас атакует, и идти пешком до Траллмара лучше даже не пробовать. Ничего, моя испытанная виверна доставит тебя, куда скажешь, и волос с головы не упадет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10121] = {title = "Истребить Пылающий Легион", objective = "Поговорите с сержантом Лободробом, который находится при караване к востоку от Траллмара.", description = "Эти земли полны угроз, но Пылающий Легион по-прежнему остается самым главным врагом Экспедиции. Один из моих самых верных воинов, сержант Лободроб, как-то изучал тактику Легиона – пытался понять, что же им нужно в этих землях. Его можно найти в одном из караванов рядом с южной стеной.\n\nБудь поосторожнее с Легионом, <имя>. Зло нельзя недооценивать.", progress = nil, completion = "Несомненно, ты видел войска Легиона с воздуха, когда летел от Темного портала. Лет пять назад мы разгромили их в битве за гору Хиджал, но проклятые демоны снова ползут сюда, как тараканы. Если они хотят войны, то они ее получат!\n\nУ нас, орков, солидный счет к Легиону. Что, Близарджин? Рассказать тебе о наших врагах?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10122] = {title = "Вблизи цитадели", objective = "Найдите следы рядового Имариона у самого северного лагеря орков Скверны, расположенного у Южного бастиона.День за днем цитадель Адского Пламени открывает свои врата, из нее выплескивается новая волна орков Скверны и растекается по лагерям, разбитым вдоль крепостного вала к югу.\n\nЯ отправила одного из своих самых способных разведчиков, рядового Имариона, следить за численностью орков, их передвижениями и подготовкой, но от него до сих пор нет ответа.\n\nИмарион должен был наблюдать за самым ближним лагерем у южного бастиона, там, где он соединяется с цитаделью. Найди его, <имя>. Без его сведений мы станем легкой добычей.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "День за днем цитадель Адского Пламени открывает свои врата, из нее выплескивается новая волна орков Скверны и растекается по лагерям, разбитым вдоль крепостного вала к югу.\n\nЯ отправила одного из своих самых способных разведчиков, рядового Имариона, следить за численностью орков, их передвижениями и подготовкой, но от него до сих пор нет ответа.\n\nИмарион должен был наблюдать за самым ближним лагерем у южного бастиона, там, где он соединяется с цитаделью. Найди его, <имя>. Без его сведений мы станем легкой добычей.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10123] = {title = "Лощина Вспышки Скверны", objective = "Убейте 4 бесов-поджигателей, 6 инферналов-завоевателей и 1 вестника Ужаса по просьбе сержанта Лободроба, который находится при караване к востоку от Траллмара.", description = "В Запределье Пылающий Легион возглавляет владыка судеб Каззак. До самого Каззака нам, к сожалению, не дотянуться. Но мы можем, – и должны! – убрать его лейтенантов, которые находятся здесь и отдают приказы войскам Легиона.\n\nВ Лощине Адской Искры, к востоку отсюда, расположились повелители ужаса. Именно они вызвали этот адский шторм, который обрушился на наши головы. Уничтожь их, и пусть их прислужники сочтут за лучшее убраться отсюда.", progress = "Пока чародеи и волшебники крови стоят на страже Траллмара, он может считать себя в безопасности.", completion = "Славная работа, солдат! Могу сказать точно, частота атак сократилась, – хотя бы на время, пока они не призовут новых повелителей Ужаса.\n\nА теперь плохие новости: у меня для тебя новое задание.", rewards = "Яростный разрушительВопящий кинжалПосох двойственных мировИгла АгамагганаРазрушитель враговВы получите:\n\n"}
MultiLanguageQuestData['ru'][10124] = {title = "Передовая застава: Останки Сквернобота", objective = "Доложитесь командиру передовой То'арху по прибытии к останкам Сквернобота.", description = "Верховное командование заметило твою доблесть в бою, <класс>. Тебя хотят отправить на передовую для встречи с командой Изуверского кулака. Это радикалы, твердо намеренные извести под корень Пылающий Легион, так что подойдешь...\n\nИди на восток 200 шагов, потом повернешь на юг у возвышенности. Увидишь останки Сквернобота на том месте, где прежде стояла старая ферма. Как окажешься там, докладываешься передовому командиру То'Арху.\n\nШагом марш!", progress = nil, completion = "Да ты, оказывается, один из тех, кто участвовал в зачистке лощины Вспышки Скверны? Приятно слышать. Нам нужны солдаты, способные отправить демонов обратно в Преисподнюю!", rewards = "Следующее заклинание будет наложено на вас:\n\nУстановка флага рельсов\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][10125] = {title = "Задание: разрушить связь", objective = "Уничтожьте Антенну Легиона: Злоба, Антенну Легиона: Ярость, Антенну Легиона: Ненависть, Антенну Легиона: Страх с помощью взрывчатки То'арха по приказу командира передовой То'арха в Погибели Сквернобота на Полуострове Адского Пламени.", description = "Прямо на восток отсюда проходит передовая Легиона. Одновременно она служит линией связи, - приглядись, и увидишь, что везде торчат антенны. Они обеспечивают связь между лагерями Легиона по всему Запределью, и вдобавок создают возмущения, которые не дают считывать передачи и вести магическое наблюдение.\n\nВозьми взрывчатку и уничтожь все антенны. Очень важно не пропустить ни одной, <имя>. Они тянутся вдоль всей передовой Легиона с севера на юг.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10127] = {title = "Задание: Ослабить врага", objective = "Убейте 4 укротителей Скверны, 8 гневостражей и поработительницу Ши'азив по приказу командира передовой То'арха у останков Сквернобота на Полуострове Адского Пламени.", description = "Не приказать тебе уничтожить демонов передовой Легиона, который находится к востоку от нашей базы, было бы нарушением воинского долга.\n\nОбе линии переводой организованы по одному и тому же принципу: между лагерями патрулируют укротители Скверны, которых, в свою очередь, охраняют стражи гнева. За обеспечение всей операции отвечает шиван-поработитель. Убей всех, кто тебе попадется, пусть Каззак сам разбирается, кого поутру недостанет в его войске.\n\nТолько остерегайся скверноботов. Я знаю, ты не <слабак/слабачка>, но эта штука заставит попотеть даже тебя.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10129] = {title = "Задание: Врата Муркет и Шаадраз", objective = "Поговорите с командиром звена Бракком, разбомбите Врата Муркет и Шаадраз, затем возвращайтесь к командиру передовой То'арху к останкам Сквернобота.", description = "Мы обнаружили два главных портала, через которые Пылающий Легион получает подкрепление. Это Врата Муркет и Врата Шаадраз.\n\nПосмотри на восток, туда, куда ведет Путь Славы. Порталы стоят по обе стороны от него, и я приказываю стереть их с лица земли.\n\nВозьми эти бомбы, они разработаны гоблинами Зоны 52 специально для подобных целей. И пусть командир звена Бракк даст тебе виверну.", progress = "Даже если промахнешься, не унывай, попробуй еще раз...", completion = "Теперь они долго не сумеют оклематься! Просто фантастика, Джонниди! Такого яростного сопротивления Легион точно не ждал!", rewards = "Портупея гневного духаШлем бесконечных виденийПосеченные в бою поножиКираса протекторатаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10130] = {title = "Западный фланг", objective = "Убейте 10 стражников, 10 берсерков и 5 послушников из клана Изувеченной Длани. О выполнении задания доложите лейтенанту Амади, которая будет ждать вас в западной сторожевой башне Оплота Чести.", description = "Орки Скверны получили новый приказ – готовить войска и боевую технику к наступлению.\n\nОплот Чести хотят зажать в тиски и армия боевого командира Некрогга должна сформировать западный фланг.\n\nЕсли Оплот атакуют с запада, когда гарнизон будет занят обороной восточных стен, то вряд ли мы сумеем отбиться. Единственная наша надежда – вывести из строя западный фланг еще до начала сражения.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10132] = {title = "Колоссальная угроза", objective = "Убейте 5 яростных колоссов и возвращайтесь к Тола'тиону на Кенарийскую заставу на полуострове Адского Пламени.", description = "Видишь огромный красный кристалл, там, на севере? Он недавно свалился с неба, при этом содрогнулась вся земля.\n\nКогда мы пришли посмотреть, что же случилось, вокруг кристалла уже собрались великаны. Им тоже было интересно, что такое упало с небес.\n\nВ этом кристалле есть что-то странное... и в излучаемой им энергии... но у меня нет времени разбираться. Прежде всего меня беспокоят горные великаны.\n\nНужно, чтобы ты <собрал/собрала> друзей, <отправился/отправилась> на Гряду Упавшего Неба и <разделался/разделалась> с ними.", progress = nil, completion = "Хорошо сработано.\n\nЯ считаю, что если мы уничтожим достаточно горных великанов, то можно не беспокоиться о кристалле, который свалился на самую середину хребта.\n\nПрими этот небольшой дар от Кенарийской экспедиции.", rewards = "Экспедиционный скорострельный арбалетЖезл выживающегоВам дадут возможность выбрать одну из следующих наград:\n\nИдол лесаМанускрипт разрушенияТотем Молнии\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10134] = {title = "Ключ к разгадке алого кристалла", objective = "Доставьте осколок алого кристалла Тола'тиону на Кенарийскую заставу на полуострове Адского Пламени.", description = "Глядя на убитого вами колосса, вы замечаете, что он сжимает в руке кусок красного кристалла.\n\nКристалл кажется совершенно незаметным в гигантской ладони, но с вашей точки зрения это довольно большой и тяжелый кусок. Кристалл – уменьшенная, но точная копия своего гигантского собрата, упавшего на гребень.\n\nОпределенно, здесь таится ключ к разгадке всех происходящих странностей, и вы уверены, что друиды на Кенарийской заставе должны увидеть этот странный кристалл.", progress = "Какой большой кристалл. Ты нашел его на гребне после сражения с колоссами?\n\nДай взглянуть.", completion = "Хммм... На вид просто глыба необработанного кристалла.\n\nПравда, я чувствую некую ауру зла, которая его окружает, но такими вещами я не занимаюсь. Я должен очистить это место от горных великанов, остальное – не мое дело.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10136] = {title = "Безжалостные планы", objective = "Убейте Араззиуса Безжалостного и возвращайтесь к Назгрелу в Траллмар.", description = "Магистр Кровавый Ястреб наконец раскодировал послание Легиона, которое ты нам <доставил/доставила>. Как выяснилось, мы перехватили планы наступления, за которое отвечает один из лейтенантов владыки Каззака, Араззиус Безжалостный. Этот Араззиус командует наземными войсками Легиона на полуострове. Ничего, <имя>, не долго ему осталось командовать.\n\nОтправляйся к западу от прудов Аггонара и избавь мир от этого \"владыки Легиона\". Полуостров Адского Пламени принадлежит Орде! Пусть Легион катится обратно к себе в преисподнюю.", progress = nil, completion = "Сменится много поколений, но песни о твоей отваге не смолкнут, Душавдушу. Хотел бы я, чтобы Тралл мог отпраздновать твою победу вместе с нами. Легион отступил, отныне Полуостров Адского Пламени принадлежит только Орде! Для нас снова возродилась надежда, что мы поднимем этот мир из руин.\n\nЛок'тар Огар!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОтмщение иллидариКристалл ОстрорукаМонарший протекторат\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10140] = {title = "Путешествие в Оплот Чести", objective = "Долетите до Оплота Чести и доставьте донесение Дурона маршалу Исилдору.", description = "Как только будешь <готов/готова>, я организую для тебя прямой перелет в Оплот Чести.\n\nПо прибытии доложись маршалу Исилдору и передай ему донесение Дурона. Уверен, маршал будет рад еще одному новобранцу из своих земель. К тому же в донесении речь наверняка пойдет о делах крайней важности.", progress = "Хвала Свету, ты добрался благополучно. Оплоту Чести нужны закаленные в боях солдаты.", completion = "Our expedition to this forsaken, wreck of a world has almost ground to a halt, &lt;имя&gt;. We encountered more resistance than we bargained for.\n\nAs if facing the Burning Legion again wasn't bad enough - there are horrors in this land unlike anything we've ever encountered.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10141] = {title = "Возрожденный Легион", objective = "Поговорите с сержантом Альтумой, которая находится рядом с восточным караваном, к востоку от Оплота Чести.", description = "Пока шло вторжение в Азерот, Легион не ослаблял позиций и здесь, в Запределье. Мы наблюдаем за его активностью уже много лет, но в последнее время, <класс>, творится что-то совсем невообразимое.\n\nРазыщи сержанта Альтуму, она находится при Восточном караване. Альтума долго наблюдала за Легионом, может быть, она поймет, что там сейчас происходит.\n\nДействовать надо быстро, но осторожно. Не забывай, Легион нельзя недооценивать!", progress = nil, completion = "Должно быть, командир армии Данат не понял, что я просила о подкреплении. Ты выглядишь годным для службы, но я просила целый батальон!\n\nПонимаешь, у нас тут небольшая проблема с демонами...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10142] = {title = "Путь Страданий", objective = "Убейте 4 бесов-поджигателей, 6 инферналов-завоевателей и 1 вестника ужаса по приказу сержанта Альтумы из восточного каравана, который находится на востоке от Оплота Чести на полуострове Адского Пламени.", description = "В Запределье Пылающий Легион возглавляет владыка судеб Каззак. До самого Каззака нам пока, к сожалению, не дотянуться. Но мы можем, – и должны! – убрать его лейтенантов, которые находятся здесь и отдают приказы войскам Легиона.\n\nОни расставили повелителей ужаса на Пути Страданий, к востоку отсюда. Именно они вызвали этот град из инферналов, который обрушился на наши головы. Уничтожь их, и тогда их прислужники, возможно, сочтут за лучшее убраться подальше отсюда.", progress = "Оплот Чести в безопасности, пока наше небо охраняют лучники.", completion = "Славная работа, солдат! Могу сказать наверняка, что частота атак сократится, – по крайней мере до тех пор, пока они не призовут новых повелителей Ужаса.\n\nА теперь плохие новости: у меня есть для тебя новое задание.", rewards = "Яростный разрушительВопящий кинжалПосох двойственных мировИгла АгамагганаРазрушитель враговВы получите:\n\n"}
MultiLanguageQuestData['ru'][10143] = {title = "Лагерь экспедиции", objective = "Доложитесь командиру передовой Кингстону в лагере экспедиции.", description = "Верховное командование заметило твою доблесть в бою, <класс>. Тебя хотят отправить на передовую для встречи с командой Рохамуса. Они радикалы, твердо намеренные извести под корень Пылающий Легион, так что ты подойдешь...\n\nИди на восток 400 шагов, потом повернешь на юг у возвышенности. Увидишь разрушенного сквернобота на том месте, где прежде стояла старая ферма. Как окажешься там, доложись командиру передовой Кингстону.\n\nШагом марш!", progress = nil, completion = "Рад тебя видеть, солдат!\n\nОднако хватит болтовни, слушай меня внимательно – для тебя есть важное задание, и я хочу, чтобы ты не только его успешно выполнил, но еще и вернулся живым!", rewards = "Следующее заклинание будет наложено на вас:\n\nУстановка флага рельсов\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][10144] = {title = "Лишить Легион подкрепления!", objective = "Уничтожьте врага вокруг порталов Грим и Каалез и соберите камни с рунами демонов.\n\nЗабросьте запалы Кингстона в порталы Грим и Каалез.\n\nПосле выполнения задания возвращайтесь к командиру передовой Кингстону вместе с оставшейся взрывчаткой.", description = "На северо-восток отсюда тянется передовая Легиона. По всей ее длине расположены порталы и ворота, по которым к Легиону поступает подкрепление со всего Запределья. Мы должны разрушить эти порталы!\n\nВот, возьми запал. Его разработали в Зоне 52, взрывчатым веществом для него служит собственная энергия демонов. Нужно отбросить войска Легиона от порталов Грим и Каалез, собрать камни с рунами демонов, забросить в портал запалы... и наслаждаться фейерверком.\n\nСтупай, <имя>, вернешься ко мне, когда выполнишь задание.", progress = "Хотел бы я на это посмотреть. Эти запалы взрываются будь здоров!", completion = "Отлично, Сотус. Без порталов к Легиону не скоро придет подкрепление.\n\nНо мы не можем позволить себе отдыхать...", rewards = "Шляпа путника с затеняющими полямиЧародейский окольцованный мундирОпаленная кирасаПоножи из свежесодранной шкурыБольшой шлем завоевателяВы получите:\n\nПредмет #8"}
MultiLanguageQuestData['ru'][10145] = {title = "Mission: Sever the Tie UNUSED", objective = "Уничтожьте 4 укротителя Скверны, 8 гневостражей и Поработителя Ялквиза по приказу командира передовой Кингстона из лагеря экспедиции на Полуострове Адского Пламени.", description = "Не приказать тебе уничтожить демонов с передовой Легиона, который находится к востоку от нашей базы, было бы нарушением воинского долга.\n\nОбе линии передовой организованы по одному и тому же принципу: между лагерями патрулируют укротители Скверны, которых, в свою очередь, охраняют стражи гнева. За обеспечение всей операции отвечает шиван-поработитель. Убей всех, кто тебе попадется, пусть Каззак сам разбирается, кого поутру недостанет в его войске.\n\nЕдинственно что, – остерегайся скверноботов. Я знаю, ты не <слабак/слабачка>, но эта штука заставит попотеть даже тебя.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10146] = {title = "Задание: Врата Муркет и Шаадраз", objective = "Поговорите с командиром звена Даби'ри, разбомбите Врата Муркет и Врата Шаадраз, затем возвращайтесь к командиру передовой Кингстону в Лагерь экспедиции.", description = "К западу от Темного портала находится еще два больших портала: портал Муркет и портал Шаадраз.\n\nЕсли взглянуть на восток, то увидишь их с обеих сторон Пути Славы. Я хочу, чтобы ты <разбомбил/разбомбила> их до самого основания.\n\nВозьми эти бомбы, гоблины из Зоны 52 разработали их специально для подобных целей. И отправляйся к командиру звена Даби'ри – он даст тебе грифона и подготовит тебя к вылету.", progress = "Это очень важное задание, Сотус. Я бы не всякому его доверил.", completion = "Даже дураку ясно, что теперь их продвижение существенно замедлится. Давненько я не был в таком прекрасном настроении, Сотус!", rewards = "Портупея гневного духаШлем бесконечных виденийПосеченные в бою поножиКираса протекторатаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10150] = {title = "Вблизи цитадели", objective = "Постарайтесь найти следы разведчицы Махи в одном из лагерей, расположенных вдоль Северного бастиона.День за днем цитадель Адского Пламени открывает свои врата, из нее выплескивается новая волна орков Скверны и растекается по лагерям, разбитым вдоль крепостного вала к югу.\n\nЯ отправил одну из своих самых способных разведчиц, Маху, следить за численностью орков, их передвижениями и подготовкой, но от нее до сих пор нет ответа.\n\nМаха должна была наблюдать за самым ближним лагерем у северного бастиона, там, где он соединяется с цитаделью. Найди ее, <имя>. Без информации мы станем легкой добычей.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "День за днем цитадель Адского Пламени открывает свои врата, из нее выплескивается новая волна орков Скверны и растекается по лагерям, разбитым вдоль крепостного вала к югу.\n\nЯ отправил одну из своих самых способных разведчиц, Маху, следить за численностью орков, их передвижениями и подготовкой, но от нее до сих пор нет ответа.\n\nМаха должна была наблюдать за самым ближним лагерем у северного бастиона, там, где он соединяется с цитаделью. Найди ее, <имя>. Без информации мы станем легкой добычей.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10152] = {title = "Западный фланг", objective = "Убейте 10 стражников, 10 берсерков и 5 послушников из клана Изувеченной Длани. О выполнении задания доложите каменному стражу Амбелану, который находится на заставе Раздробленного Хребта, рядом с Зет'Гором.", description = "Орки Скверны получили новый приказ – готовить войска и боевую технику к наступлению.\n\nОплот Чести планируется взять в клещи, и армия боевого командира Некрогга должна сформировать западный фланг.\n\nЕсли Оплот атакуют с запада, когда гарнизон будет занят обороной восточных стен, то вряд ли мы сумеем отбиться. Единственная наша надежда – вывести из строя западный фланг еще до начала сражения.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10159] = {title = "Очистить холм Колючего Клыка!", objective = "Убейте 8 опустошителей Колючего Клыка и 8 ядоплюев Колючего Клыка. После выполнения задания возвращайтесь к Махураму Крепкому Копыту на Кенарийскую заставу на полуострове Адского Пламени.", description = "Мы ведем бесконечную войну с опустошителями, пытаясь сохранить свободным путь на запад через холм Колючего Клыка. Недопустимо, чтобы мы оказались полностью отрезанными от убежища в Зангартопи.\n\nМы бы не стали трогать этих тварей, но они все чаще нападают на путешественников.\n\nПожалуйста, помоги нам очистить эту местность от опустошителей.", progress = "Как продвигается зачистка холма Колючего Клыка?", completion = "Теперь, когда опустошителей не стало, добираться до Кенарийского приюта в Зангартопи стало куда безопасней.\n\nКенарийская экспедиция в долгу перед тобой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10160] = {title = "Врага нужно знать в лицо", objective = "Поговорите с лейтенантом Амади в старой сторожевой башне на западе Оплота Чести.", description = "Ходят слухи, что появилась какая-то новая порода орков. Более мозговитая, чем те бугаи, с которыми нам приходилось драться. Если эти слухи подтвердятся, то нашим войскам, у которых силы и так на исходе, придется несладко.\n\nЯ поручил расследование лейтенанту Амади. Если хочешь в эти непростые времена оказать нам помощь, разыщи ее. Она находится в разрушенной башне в западной части Оплота Чести.\n\nИ еще, <имя>, будь <осторожен/осторожна>. Ты вступаешь в неведомый и очень опасный мир.", progress = nil, completion = "&lt;Лейтенант Амади кивает.&gt;\n\nОтлично, мы рады любой помощи. Меня беспокоит увеличение численности орков Скверны в Южном бастионе. Я отправила туда разведчика, но он до сих пор не вернулся.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10161] = {title = "В случае чрезвычайной ситуации...", objective = "Соберите 30 обломков дирижабля и принесите Скриду Многослову по прозвищу \"Крикун\" на место крушения дирижабля.", description = "В случае чрезвычайной ситуации основная ответственность ложится на пилота, особенно если второй пилот способен думать только о том, чем бы набить брюхо.\n\nУ меня есть две новости: хорошая и плохая. Хорошая новость – мы сможем обойтись с ремонтом своими силами. Плохая – части нашего дирижабля разбросаны отсюда и к востоку аж до самой Долины Костей.\n\nЧто еще плохого? Можно сказать, что собственно запчастей у нас нет. А что было, то попадало вниз во время нашего... хм... экстренного снижения. Поможешь нам отыскать запчасти, чтобы мы снова смогли подняться в воздух?", progress = "Удалось собрать хоть что-нибудь? Если нет, то придется конфисковать у Легасси сковородку, которой он так яро размахивает. М-да, тогда мой дирижабль можно будет смело называть летающей сковородкой...", completion = "Часть из них в ужасном состоянии, но с остальными можно работать. Немного фантазии, и я уверен, эта штука еще поднимется в воздух!", rewards = "Летные штаны Кремневого ЗатвораОбтекаемый чешуйчатый жилетУправляемый защитный шлемВы получите:\n\n"}
MultiLanguageQuestData['ru'][10162] = {title = "Задание: Косогор Бездны", objective = "Уничтожьте 20 ган'аргов-батраков, 5 мо'аргов-надзирателей и 5 пушек Скверны по приказу командира передовой То'арха у останков Сквернобота на полуострове Адского Пламени.", description = "Может быть теперь, когда у тебя есть крылья, ты захочешь снова отправиться на бомбардировку?\n\nМы обнаружили главный производственный цех Легиона, в котором куются силы для северных лагерей. Приказываю тебе взять виверну и уничтожить этот оплот Скверны!\n\nБомбы лежат вот здесь. Поговори с командиром звена Бракком, когда будешь <готов/готова> к вылету.", progress = "Пусть узнают, что небеса им тоже не рады!", completion = "Ты летаешь так, будто занимался этим всю жизнь, Менгиле. Я восхищаюсь твоим умением! На вивернах ни царапины!", rewards = "Шуршащий мундирЧародейские окольцованные наголенникиНаголенники небесного огняБольшой шлем ветеранаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10163] = {title = "Задание: Косогор Бездны", objective = "Уничтожьте 20 ган'аргов-батраков, 5 мо'аргов-надзирателей и 5 пушек Скверны по приказу командира звена Грифонгара с Парящей заставы на полуострове Адского Пламени.", description = "Может быть теперь, когда у тебя появились крылья, ты хочешь снова отправиться на бомбардировку?\n\nМы обнаружили главный производственный цех Легиона, в котором куются силы для северных лагерей. Приказываю тебе взять грифона и уничтожить этот оплот Скверны!\n\nБомбы лежат вот здесь. Поговори с грифоньером Ветроревом, когда будешь <готов/готова> к вылету.", progress = "Пусть узнают, что небеса им тоже не рады!", completion = "Ты летаешь так, будто занимался этим всю жизнь, Ландэ. Я восхищаюсь твоим умением! Ни царапины ни на одном грифоне!", rewards = "Шуршащий мундирЧародейские окольцованные наголенникиНаголенники небесного огняБольшой шлем ветеранаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10164] = {title = "Все будет в порядке", objective = "Проникните в Аукенайские гробницы и уничтожьте экзарха Маладаара по просьбе Великого Отца Алдримуса, который находится снаружи Аукенайских гробниц Аукиндона.", description = "Чувствую, тебе хватило приключений еще до того, как ты <вступил/вступила> в Аукенайские гробницы, <имя>.\n\nЯ могу назвать себя счастливым духом, - я никогда не попадался ни Левиксусу, ни экзарху Маладаару, и на мне не ставили эти ужасные некромантические эксперименты. Левиксиуса тебе удалось уничтожить, но Маладаар жив и продолжает терзать пленных духов.\n\nЯ прошу только об одном. Проберись в Аукенайские гробницы и уничтожь экзарха Маладаара, чтобы духи могли наконец упокоиться с миром.", progress = "Освободи духов, Рёи!", completion = "У тебя получилось, Снатяжкой! Духи наконец обрели свободу!\n\nУ меня нет материального тела, но я дам тебе в награду предмет из мира духов. Используй его с осторожностью, подобные предметы очень непостоянны и могут причинить вред обладателю.", rewards = "Защитник наместникаХауберк аукенайского следопытаМундир аукенайского монахаОдеяние аукенайского отшельникаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10165] = {title = "Жестокая вещь – конкуренция", objective = "Убейте принца нексуса Шаффара по просьбе принца нексуса Харамада, находящегося снаружи Гробниц маны, и принесите ему обмотки Шаффара.", description = "А этот Шаффар не дурак, как я погляжу. Ухитрился выставить отсюда весь Консорциум и теперь спокойненько обчищает гробницу! Я не верю, что мои идиоты смогут прорвать оборону Шаффара, так что предлагаю тебе сделку, <раса>.\n\nОтправляйся в Гробницы Маны и убей Шаффара. Принеси его одеяние в знак доказательства его смерти, и я щедро награжу тебя.", progress = "Я очень не люблю делиться!", completion = "Минус еще один конкурент... Для маленького кусочка плоти ты неплохо справился, |3-6(нежить). Если окажешься еще раз в Пустоверти, дай мне знать. Меня можно найти в Штормовой Вершине.", rewards = "Латные набедренники КонсорциумаПоножи Третьей монеты ХарамадаКлепаные кольчужные кюлоты ХарамадаНаножи ХарамадаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10166] = {title = "Память о Белостволе", objective = "Заройте подвеску Старого Белоствола у рунического камня в Выжженной роще по просьбе Ларианны Речной Ветер.", description = "Эта подвеска напоминает мне иные времена. Лучшие времена...\n\nУвы, сейчас мне не до воспоминаний!\n\nПрошу тебя, зарой ее возле рунического камня в Выжженной роще. Именно там я впервые встретилась со старейшиной-древнем. Пусть воспоминания о моем старом друге покоятся в мире.", progress = "Ты вернулся, Расул! Сделал ли ты то, о чем я просила?", completion = "Я более не принадлежу к этому миру и вынужден признать свое поражение. Мир изменился навеки, ничто уже не будет прежним.\n\nОставь подвеску здесь, со мной, Расул. Может быть, в один прекрасный день, когда эльфы исчезнут, на этом самом месте прорастет новое дерево - среди сгоревшего леса и остовов мертвых древней.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][10167] = {title = "Аукиндон...", objective = "Отправляйтесь в Аукенайские гробницы в Костяных пустошах леса Тероккар, убейте экзарха Маладаара и освободите дух Д'оре.", description = "В глубине Аукенайских гробниц находится могила, не похожая ни на какую другую могилу в этой разоренной стране. С этой первой гробницы началась история огромного мавзолея Аукиндона.\n\nТебе надо проникнуть в Аукенайские гробницы и разыскать эту могилу. Убей хранителя склепа и освободи заточенного внутри духа. Он – ключ к разгадке...", progress = nil, completion = "Мои воспоминания не поблекли с годами, Расул. Катастрофа полностью отняла мои силы. Когда Пророк Велен и его земляки-дренеи принесли сюда мои останки, в них теплилась лишь тусклая искорка энергии. После долгой церемонии мое истощенное воплощение упокоилось в этом саркофаге. Почти тысячу лет я потратил на восстановление. Цикл почти завершен...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10168] = {title = "Что видит душа", objective = "Найдите зеркало Души в Аукенайских гробницах и используйте его, чтобы выманить темного духа из древнего орка-предка в Награнде. Уничтожьте 15 темных духов, чтобы орочьи предки могли упокоиться с миром.\n\nКогда исполните поручение, возвращайтесь к Матери Кашур в Земли Предков.", description = "Многие века духи Аукиндона сливались с моей обессиленной душой. Большая часть несчастий, обрушившихся на эти гробницы, произошла из-за того, что я был ослаблен и немощен.\n\nК сожалению, остановить этот цикл невозможно. Это закон существования наару: без пустоты не бывает Света.\n\nТвой единственный выход – уничтожить древних духов Награнда прежде, чем они превратятся в созданий Бездны. Используй зеркала Души, которые найдешь в гробницах, чтобы освободить их...", progress = "<Мать Кашур заметно расcтроена.>\n\nЭти наару умнее всех существ в мире.", completion = "Ты завершил долгое и опасное путешествие, рисковал своей жизнью ради безопасности маг'харов и покоя наших предков. Мою благодарность невозможно выразить словами.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10169] = {title = "Проиграть с честью", objective = "Вылейте сонную сыворотку в котел Харонема на террасе Света, после чего вернитесь к магистру Фальрису.", description = "Сегодня Алдоры заслужили благорасположение Ша'тар! Тоже мне, неожиданность!\n\nТолько посмотрите, как они выставляются перед А'далом - а все для того, чтобы подлизаться к наару.\n\nУ снайперов Харонема такая строгая дисциплина, что они даже притащили свой котел, чтобы не делать долгих перерывов на обед. Думаю, надо их угостить как следует, <имя>.\n\nВот, вылейте это в их еду. Результат себя ждать не заставит... будет весело.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10170] = {title = "Возвращение к Великой Матери", objective = "Возвращайтесь в Гарадар и поговорите с великой матерью Гейей.", description = "<имя>, возвращайся в Гарадар к великой матери Гейе и сообщи ей о своей победе. Это поднимет дух маг'харов. Может быть, даже юный Адский Крик оправится от болезни.", progress = nil, completion = "Я хочу, чтобы ты лично доставил эти известия Гаррошу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10171] = {title = "Безутешный Вождь", objective = "Поговорите с Гаррошем.", description = "<имя>, ты так много <сделал/сделала> для маг'харов, что весть о твоих деяниях достигла ушей самого Гарроша. Иди к нему и расскажи о своей последней победе. Скажи, что ты делаешь все это для него и его народа. Ему понравятся такие слова. Может, он даже слегка взбодрится.", progress = nil, completion = "Все гордятся и радуются. Радуются, что увидят еще одну зиму. А дальше? Что будет дальше?\n\nМожет быть, тебе стоит возглавить мой клан, Мротсагемо? И тогда, после ухода Великой матери, мне, может быть, будет позволено умереть и вернуть честное имя моему роду. Я жажду покоя...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10172] = {title = "Надежды нет", objective = "Вернитесь к Великой Матери Гейе и передайте ей слова Гарроша.", description = "Ты <благородный/благородная:r> <раса>, <имя>. Ты много <сделал/сделала> для маг'харов и <оказал/оказала> нам поистине неоценимые услуги. Увы, время маг'харов закончилось. Ты ясно мне <показал/показала>, что я не гожусь на роль вождя своего народа. Моя проклятая кровь... Я не хочу стать вторым Адским Криком, который навлечет беду на орков.\n\nПрошу тебя, <имя>, возвращайся к Великой Матери и передай ей мои слова. Мне стыдно предстать перед ней самому... стыдно смотреть ей в глаза.", progress = nil, completion = "*Слезы текут по щекам Великой Матери.*\n\nИди к своему вождю и скажи ему, что я жду его здесь...", rewards = "Рогатый шлем ритуалиста маг'харовМундир разведчика маг'харовПоножи охотника маг'харовНожные латы вождя маг'харовВы получите:\n\nЗнак героя маг'харов"}
MultiLanguageQuestData['ru'][10173] = {title = "Посох верховного мага", objective = "Отнимите посох верховного мага Варгота у Эккораш Инквизитора и принесите Равандвиру в Зону 52. Чтобы выманить Эккораш из укрытия, бросьте волшебный порошок на жаровню в центре руин.", description = "Позволь мне представиться, <класс>.\n\nЯ Равандвир, ученик верховного мага Варгота.\n\nМой учитель... скажем так, нездоров. Я здесь по чрезвычайно важному делу. \n\nВ руинах Арклона к юго-востоку от города активно действует Пылающий Легион. Цель пребывания этих демонов в руинах не касается ни меня, ни моего учителя, однако их предводительница, Эккораш, завладела посохом верховного мага.\n\nВот волшебный порошок, он позволит тебе выманить демоницу из укрытия. Брось порошок на жаровню в центре руин.", progress = "Я не буду знать покоя, пока посох верховного мага Варгота не вернется к нему. Удалось ли тебе вырвать посох из лап демона?", completion = "А, так тебе удалось добыть посох. Великолепно, Выручалкин. Возможно, именно тебя я и искал все это время.\n\nАх да, твоя награда...\n\n*Равандвир кладет тебе на ладонь несколько монет.*\n\nНесомненно, это не оправдывает твои ожидания, но всему свое время. Отныне ищи возможность для получения истинной награды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][10174] = {title = "Проклятие Аметистовой башни", objective = "Используйте посох верховного мага Варгота, чтобы связаться с верховным магом Варготом.\n\nЕсли вы утратили посох верховного мага Варгота, поговорите с Равандвиром в Зоне 52, чтобы получить замену.\n\nПрилагается предмет: \n", description = "Теперь ты можешь использовать посох верховного мага, чтобы связаться с ним.\n\nОн обитает в Аметистовой башне, на \"острове\" к юго-востоку отсюда. Эта башня служит ему одновременно убежищем и тюрьмой – она проклята. Никто из Кирин-Тора не может ни войти туда, ни выйти оттуда, и я разлучен со своим учителем.\n\nМагия посоха может пробиться через защиту башни, но ее должен пробудить кто-то, не принадлежащий к Кирин-Тору. \n\nВозьми посох верховного мага и используй, чтобы вызвать его проекцию. Расскажи ему о том, что произошло, и скажи, что я все-таки не окончательно подвел его.", progress = nil, completion = "*Изображение верховного мага Варгота изучает тебя, пока ты пересказываешь сообщение Равандвира.*\n\nРавандвир наделен всем, что любой учиитель хотел бы видеть в своем ученике. Когда я отдал ему этот посох и приказал бежать, я надеялся, что он использует этот посох, дабы найти помощь и освободить меня, как только войска Кель'таса отступят от башни. С тех пор я многое узнал о природе проклятья.\n\nПроклятье можно разбить, Выручалкин, но для этого потребуется твоя помощь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10175] = {title = "Тралл, сын Дуротана", objective = "Отправляйтесь в Оргриммар и передайте Траллу сообщение от Гейи.", description = "Возвращайся в свой мир, <имя>. Разыщи моего внука и скажи ему, что у него еще остались близкие в этом разрушенном мире.\n\nСкажи ему, что наследие его отца продолжает жить.\n\nРасскажи ему все...", progress = nil, completion = "*Голос Тралла становится глухим и гулким, как далекий раскат грома.*\n\nУ меня... у меня есть бабушка? Она жива?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10176] = {title = "Страж Ар'келос", objective = "Войдите в Аметистовую башню, расположенную в центре деревни Кирин'Вар, и победите Ар'келоса, затем поговорите с верховным магом Варготом.", description = "Теперь, когда тебе удалось собрать все предметы, необходимые для того, чтобы снять проклятие Кель'таса, осталось сделать еще только одно. Когда Кель'тас запечатал башню, он поставил у ее подножия чародейского голема, известного как Ар'келос.\n\nТебе нужно победить голема, чтобы я вновь смог работать с магией внутри башни.\n\nКогда ты войдешь в Аметистовую башню, проклятье начнет действовать на тебя.\n\nКак только победишь Ар'келоса, поднимайся на башню и помоги мне провести приготовления к ритуалу.", progress = "Наконец-то мы встретились.", completion = "Хорошая работа, Выручалкин. Благодаря уничтожению подавляющего поля мне будет гораздо легче подготовить магию, которая наконец-то снимет проклятье с башни.", rewards = "Плащ доблестного поборникаОмолаживающий скипетрВам дадут возможность выбрать одну из следующих наград:\n\nПодвеска боевого магаСердцевина Ар'келоса\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10177] = {title = "В Аукиндоне неспокойно", objective = "Доложите о своем прибытии боевому командиру Мафууну, который находится неподалеку от входа в Темный лабиринт в Аукиндоне в Лесу Тероккар.", description = "Мои шпионы шлют очень тревожные донесения из Аукиндона. Со времени взрыва это место не доставляло нам ничего, кроме проблем.\n\nИ опять там происходит что-то ужасное. Похоже, Совет Теней вознамерился развязать войну. Хотя донесения недостаточно подробные, понятно, что приготовления идут вовсю.\n\nТебе придется пробраться в Темный Лабиринт. Боевой командир Мафуун скажет тебе, что делать.", progress = nil, completion = "Ты появился очень вовремя.\n\nМы уже довольно долго здесь сражаемся, и еще несколько дней назад Мелиса обещала прислать подкрепление.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10178] = {title = "Найти шпиона То'гуна!", objective = "Найдите шпиона То'гуна в Темном лабиринте в Аукиндоне.", description = "То'гун – идиот! Мы и здесь-то держались с трудом, а он отправился на разведку, и вдобавок решил спасти всех остальных шпионов.\n\nДаже не знаю, молиться за него или прибить, когда вернется.\n\nСовет Теней, должно быть, использовал магию, чтобы нас обнаружить, и нам пришлось бежать отсюда в ужасной спешке. Многие не сумели выбраться.\n\nПожалуйста, если у тебя хватит храбрости, чтобы войти в Темный лабиринт, глянь хотя бы одним глазком, не найдешь ли ты То'гуна! Прошло уже столько времени, и я опасаюсь худшего...", progress = nil, completion = "Что? Грук-та отправила тебя сюда за мной?\n\nНет, это, конечно, трогательно, но она с ума сошла!\n\nПоможешь мне выбраться из этой клетки? А то тут тесновато!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10179] = {title = "Смотритель Кирин'Вара", objective = "Поговорите с блюстителем Ценой Смерти в деревне Кирин'Вар в Пустоверти.Когда стало ясно, что наша экспедиция попала в ловушку в Запределье и не может вернуться обратно на Азерот, отряд Кирин-Тора отправился на равнины Фаралона и построил деревню Кирин'Вар. Я оставил дела в руках смотрителя Дайворта, но когда Кель'тас и его войска заключили меня в Аметистовой башне, я потерял с ним связь связь.\n\nОтыщи его в деревне Кирин'Вар и помоги ему во всем, в чем только сможешь, <имя>. Я уверен, что у него полно хлопот с преодолением последствий нападения.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Когда стало ясно, что наша экспедиция попала в ловушку в Запределье и не может вернуться обратно на Азерот, отряд Кирин-Тора отправился на равнины Фаралона и построил деревню Кирин'Вар. Я оставил дела в руках смотрителя Дайворта, но когда Кель'тас и его войска заключили меня в Аметистовой башне, я потерял с ним связь связь.\n\nОтыщи его в деревне Кирин'Вар и помоги ему во всем, в чем только сможешь, <имя>. Я уверен, что у него полно хлопот с преодолением последствий нападения.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10180] = {title = "Неудержимый", objective = "Поговорите с Исфаром неподалеку от входа в Сеттекских залах в Аукиндоне.", description = "Я пытался убедить Исфара, что нам лучше оставаться в безопасности в Шаттрате, но он не стал даже слушать. Наоборот, он решил, что отправится в Аукиндон в одиночку.\n\nОднажды ему посчастливилось выбраться из Сетеккских залов, но если его обнаружат, второго шанса у него не будет.\n\nЯ понимаю, что он хочет спасти сестру, но без посторонней помощи ему не справиться.\n\nНайди Исфара и поговори с ним, <имя>. Если ты не сможешь убедить его вернуться обратно, может быть, тебе удастся помочь ему спасти Лакку?", progress = nil, completion = "Я должен был догадаться, что это он отправил тебя за мной. Он пытался отговорить меня от возвращения в Сетеккские залы, но разве я смогу жить спокойно, если позволю Лакке погибнуть там?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10182] = {title = "Боевой маг Датрик", objective = "Найдите апартаменты боевого мага Датрика в переулке Волшебников и верните меч в оружейную стойку. Затем поговорите со смотрителем Дайвортом в деревне Кирин'Вар.", description = "Этот меч великолепен даже для боевого мага: он искусно откован и идеально сбалансирован. На оголовье меча выгравированы печать Кирин-Тора и имя \"Датрик\".\n\nВертя оружие в руках, ты замечаешь, что от металла исходит ощущение некой неправильности, как будто предмет разрывается между двумя мирами. Быть может, это предмет, привязывающий дух боевого мага Датрика к этому миру?\n\nВозможно, возвращение меча на должное место разорвет эту связь и освободит дух Датрика, чтобы он наконец-то мог покоиться в мире?", progress = "Что это за находка, Карагуль?", completion = "Это было доброе дело, Выручалкин. Я больше не чувствую беспокойства, исходящего от духа Датрика. Я много бы отдал за возможность еще раз поговорить с ним, но достаточно и того, что он наконец-то нашел покой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10183] = {title = "В Зону 52", objective = "Передайте записки пустолога ведущему ракетостроителю Фьюзеляжу, находящемуся в Зоне 52 в Пустоверти.", description = "Я тут изучаю Пустоту – астральные течения и все такое. Это идеальное место, вдали от городских огней и шума. Разве этот мост не великолепен? Если бы мне еще удалось заставить этот хлам работать!\n\nКстати, если ты ищешь работу, то в Зоне 52 ее полно. Иди вот по этой тропе, а на развилке сверни направо.\n\nЗаодно почему бы тебе не передать мои последние исследовательские записи ведущему ракетостроителю Фьюзеляжу? Я уверен, что у него для тебя найдется масса дел, с этим его ракетным кораблем Х-52 и всем прочим.", progress = "Занят, занят. Нет времени. Нужно построить ракетный корабль!\n\nЧто тебе нужно?", completion = "А, Медноклеппер наконец-то решил сообщить о своих открытиях? Эти мне ленивые ученые!\n\nВ чем дело?\n\n&lt;Ведущий ракетостроитель несколько раз пролистывает записки с явно недоверчивым видом.&gt;\n\nОн утверждает, что неистовая энергия, плавающая в Пустоверти, всего через несколько месяцев разнесет тут все на мелкие кусочки.\n\nЭто ужасно – нам теперь придется сдвигать график постройки ракетного корабля!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10184] = {title = "Зловещие останки", objective = "Смотритель Дайворт в деревне Кирин'Вар просит вас победить 20 покалеченных духов на площади Кирин'Вара.", description = "Большинство духов в деревне – не более, чем бледные останки магов Кирин-Тора. Они ничего не знают о своих былых \"я\" и просто блуждают среди руин в слепой ярости.\n\nОднако так было не всегда. Сразу после нападения духи были беспокойными, но не злобными. Но с течением времени они становились все более агрессивными. Я не осмеливаюсь заходить в южную часть деревни, ибо они не пощадят даже меня. Заставь их умолкнуть, и будем надеяться, что это уймет их ярость.", progress = nil, completion = "&lt;Смотритель Дайворт тихонько покачивает головой.&gt;\n\nЭто не то, чего они заслуживали, но это лучшее, что мы могли сделать.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10185] = {title = "Участь хуже, чем смерть", objective = "Убейте 10 убийц магов и 10 искателей маны и вернитесь к смотрителю Дайворту в деревню Кирин'Вар.", description = "После того как эльфы крови уничтожили деревню Кирин'Вар, они начали строительство огромного здания к северо-западу отсюда. Без знаний верховного мага мы не можем точно сказать, что там происходит.\n\nОднако ясно одно. Деятельность эльфов крови вызвало массовые нападения на деревню элементалей маны. Они, судя по всему, рыщут среди руин в переулке Волшебников, производя дальнейшее опустошение. Мы не можем допустить, чтобы это продолжалось.", progress = nil, completion = "&lt;Блюститель выглядит встревоженным.&gt;\n\nЯ уже вижу новую волну, вздымающуюся на горизонте. Истребление этих тварей поможет лишь на некоторое время, однако нужны более действенные меры.", rewards = "Мантия душеловаНаполненные маной нарукавникиРукавицы спиритуалистаУкрепленные фаралитом сапогиВы получите:\n\n"}
MultiLanguageQuestData['ru'][10186] = {title = "Тебя наняли!", objective = "Соберите 10 астраллитиевых матричных кристаллов и принесите их ведущему ракетостроителю Фьюзеляжу в Зону 52 в Пустоверти.", description = "Позволь мне первым поприветствовать тебя, младший лаборант 3-й степени <имя>!\n\nМы здесь строим мое изобретение – ракету Пустоты Х-52!\n\nНо для начала нам нужно раздобыть все детали и топливо для нее. Именно этим ты и займешься.\n\nПервым делом мне нужны кристаллы – МНОГО кристаллов – для астраллитиевой матрицы двигателя ракеты. Эти кристаллы выпадали у дренеев из ушей.\n\nТак что отправляйся на север, к Руинам Энкаата, и добудь для меня кристаллы. На призраки дренеев не обращай внимания.", progress = "Похоже ли, что ракета Х-52 готова к старту? И что я скоро буду курсировать по Круговерти Пустоты, удобно расположившись в командирском кресле? Буду исследовать новые интересные миры? Искать возможность заполучить новые технологии и наладить деловые связи? Отважно бросаться туда, где не бывал еще ни один гоблин?\n\nНет!\n\nТак где же те кристаллы, за которыми я тебя посылал?", completion = "Ха! Выглядят достаточно грубо. Может быть, мы сможем их использовать в многоцелевой камере третьей ступени двигателя. \n\nИ все же это хорошая работа, младший лаборант 3-ей степени! Похоже, ты очень скоро заслужишь 2-ю степень!", rewards = "Третьеразрядные наплечники младшего лаборантаТретьеразрядные перчатки младшего лаборантаТретьеразрядные наручи младшего лаборантаТретьеразрядные очки младшего лаборантаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10187] = {title = "Послание для верховного мага", objective = "Поговорите с Верховным магом Варготом на вершине Сиреневой башни в Пустоверти.Хотя ситуация здесь довольно мрачная, мы слегка воодушевились, услышав от тебя, что верховный маг не забыл о положении нашей деревни.\n\n<Блюститель бросает взгляд на башню.>\n\nСмешно, не так ли? Иногда кажется, что нас разделяет лишь обычная каменная стена. О стене магии довольно легко забыть.\n\nНе затруднило бы тебя подняться на башню и уведомить верховного мага Варгота о том, что у нас в деревне дела продвинулись довольно далеко и что вскоре мы составим план избавления от мана-тварей.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Хотя ситуация здесь довольно мрачная, мы слегка воодушевились, услышав от тебя, что верховный маг не забыл о положении нашей деревни.\n\n<Блюститель бросает взгляд на башню.>\n\nСмешно, не так ли? Иногда кажется, что нас разделяет лишь обычная каменная стена. О стене магии довольно легко забыть.\n\nНе затруднило бы тебя подняться на башню и уведомить верховного мага Варгота о том, что у нас в деревне дела продвинулись довольно далеко и что вскоре мы составим план избавления от мана-тварей.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10188] = {title = "Печать Краса", objective = "Заберите Печать Краса у чароплета Марианы, находящейся в Манагорне Коруу, к северо-западу от Аметистовой башни.", description = "Прежде чем мы много лет назад отбыли с Азерота, Кирин-Тор доверил нашей экспедиции мощный артефакт, Печать Краса. Она очень помогла нам в битве против орков, и может сыграть важную роль в том, чтобы разбить заклинание, удерживающее меня здесь.\n\nОднако когда Кель'тас отнял у меня мои волшебные принадлежности, он отдал печать чароплету Мариане, которая не принимала участия в битве. Если бы Кель'тас понимал, чем он завладел, он не отдал бы это так легко.", progress = "Чтобы освободиться от проклятия башни, мне необходима эта печать.", completion = "О, эта печать осталась такой же великолепной, какой я ее запомнил. Разве ты не чувствуешь силу, которую она излучает?\n\nКонечно, нужно сделать еще очень многое, но я благодарен тебе за возвращение печати.", rewards = "Пояс подмастерья из Кирин'ВараПояс разведчика из Кирин'ВараПолный шлем боевого магаШоссы защитника Кирин'ВараВы получите:\n\n"}
MultiLanguageQuestData['ru'][10189] = {title = "Манагорн Б'наар", objective = "Патрон шпионов Талодиен, находящийся в Зоне 52, хочет, чтобы вы направились в окрестности манагорна Б'наар и отобрали список персонала манагорна Б'наар у капитана Аратина.\n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "Может быть, по пути сюда тебе попался на глаза один из манагорнов Келя. Это такие большие лиловые здания, высасывающие энергию из неба. \n\nМы посланы сюда Ша'тар, дабы побольше узнать об этих манагорнах. Ты можешь помочь нам в сборе сведений, раздобыв список персонала. Это даст нам представление о том, кто находится там и что они делают; такая информация была бы бесценной.\n\nМы полагаем, что капитан Аратин, командующий отрядом баллист, который расквартирован возле манагорна Б'наар, располагает экземпляром этого списка. Добудь его для нас.", progress = "Удалось ли тебе раздобыть то, о чем я тебя просил, Девлиниум?", completion = "Превосходно! При наличии этого списка мы сможем принимать более взвешенные решения, намечая целью кого-нибудь из последоватей Келя в манагорнах.\n\nКак ни печально, мне уже начало нравиться убивать всех его приспешников без разбора.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10190] = {title = "Перезарядка батарей", objective = "Используйте зарядное устройство для батарей применительно к достаточному количеству внепространственных охотников, чтобы довести зарядку батарей до уровня 10. Затем вернитесь к роботехнику Элли в руины Энкаата в Пустоверти.", description = "У меня очень важная задача – отыскивать и забирать машины, оставшиеся в этих руинах, однако существуют проблемы с тем, чтобы подзаряжать всех моих роботов. \n\nВнепространственные охотники – эти червеподобные твари – содержат массу энергии! Их можно найти по окраинам этого острова, они приплывают из пустоты.\n\nНаполни энергией батареи, вставленные в это зарядное устройство, применив его к внепространственному охотнику, пока он слаб, а затем прикончи его, чтобы выдавить последнюю энергию.", progress = "Ну как, удалось зарядить батарейки в устройстве?", completion = "Эй, смотри, куда направляешь эту штуку! Она выставлена на смертельное поражение!!!\n\nПохоже, тебе удалось как следует подзарядить батарейки. Ну что ж, теперь мои ребятки смогут двигаться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10191] = {title = "Робот модели V жив!", objective = "Сопроводите \"Маккса А. Миллиона V\" через руины Энкаата и обратно, обеспечив ему безопасность. Потом поговорите с роботехником Элли за пределами руин Энкаата в Пустоверти.", description = "Привет тебе, <раса>. Я заряжен и полностью функционален. \n\nВ этих руинах находятся хрупкие дренейские машины, которые я должен забрать. Я оборудован точно настроенными сервоприводами в запястных механизмах и пневматическими компенсаторами сотрясений последней конструкции. Осторожное обращение с деталями – для меня не проблема.\n\nОднако призраки, обитающие в этих руинах, наверняка нападут на меня, поэтому я прошу тебя и твоих друзей обеспечить мне защиту.", progress = "Ты уже вернулся, так быстро? \n\nС \"Макксом А. Миллионом V\" все в порядке?", completion = "Получилось! Получилось! Я готова тебя расцеловать!\n\nОй... у \"Маккса А. Миллиона V\" опять кончилась энергия. Ну ладно, он сегодня хорошо поработал, а остальное неважно!\n\nВедущий ракетостроитель Фьюзеляж будет доволен – он сможет подключить эти дренейские машины к своей ракете Пустоты Х-52! А я получу повышение! Я так рада! Сейчас, я чем-нибудь тебя вознагражу.\n\nВот, выбирай из этого.", rewards = "Изогнутый лук ЭллиВыкопанный жезл из ЭнкаатаВам дадут возможность выбрать одну из следующих наград:\n\nСюрикэн Маккса Модель V\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10192] = {title = "Компендиум Краса", objective = "Заберите компендиум Краса – глава 1, компендиум Краса – глава 2 и компендиум Краса – глава 3 из района Городской площади деревни Кирин'Вар.", description = "Кирин-Тор послали с нашей экспедицией еще одну вещь, принадлежавшую Красу. Это его книга заклинаний, именуемая компендиум Краса. В ней содержатся все заклинания, которые он освоил, и она могла бы дать нам весомое преимущество в войне. \n\nЕще до того, как Кель'тас со своим войском осадил Кирин'Вар, компендиум был похищен у меня мятежным учеником, намеревавшимся заняться некромантией. Этот ученик и его последователи разделили книгу на отдельные части и втайне изучали ее, заперевшись в своих домах в южной части города.", progress = "Ты принес книгу?", completion = "*Изображение верховного мага Варгота словно бы изучает Компендиум.*\n\nДа, книга в плохом состоянии, но если учесть, как с ней обращались, чудо еще, что она вообще сохранилась. Сбереги ее, Выручалкин. Без нее у нас мало надежды пробиться через стену, ограждающую башню.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10193] = {title = "Высокие цели", objective = "Патрон шпионов Талодиен, находящийся в Зоне 52, просит вас отправиться в манагорн Б'наар и убить 2 мастеров пространственных искривлений, 6 инженеров пространственных искривлений и 8 геологов из клана Ярости Солнца.\n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "Основываясь на сведениях из этого списка, мы узнали, что \"мозгами\" во всех действиях, совершаемых в манагорнах, являются мастера искажения и инженеры искажения. Именно они присматривают за притягиванием так называемой \"энергии искажения\" в манагорн, а также передачей этой энергии на расстояние посредством системы подземных трубопроводов.\n\nПомимо них, единственными специалистами в том регионе являются геологи. Все остальные или состоят в армии, или являются приверженцами магистра; и тех, и других легко заменить.\n\nОтправляйся туда и убей специалистов Келя – это причинит ему наибольший вред.", progress = nil, completion = "Ты надежный парень, Душавдушу. Если мне что-то и нравится больше, нежели убийство приспешников Келя, - это когда кто-то убивает их вместо меня. Чем меньше крови на моей одежде, тем лучше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10194] = {title = "Незаметный полет", objective = "Поговорите с Веронией, находящейся за пределами Зоны 52, и летите к манагорну Коруу.\n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "После твоего ухода мои подчиненные обнаружили еще один манагорн. Он находится к востоку отсюда и известен как манагорн Коруу.\n\nДвое моих лучших шпионов оборудовали тайную площадку для высадки поблизости от этого манагорна. Нужно помочь им внедриться в войско Келя и собрать всю информацию, какую только возможно.\n\nПоговори с Веронией, ожидающей за городскими стенами; она нашла ветрокрыла, который отнесет тебя к манагорну Коруу. Оказавшись там, поговори с Каледисом Сияющим Рассветом, он посвятит тебя в детали задания.", progress = nil, completion = "Устроить все для твоего полета стоило немалых денег. Будем надеяться, что ты сумеешь как следует справиться со своей работой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10196] = {title = "Больше перьев араккоа", objective = "Принесите 30 перьев араккоа Малуказу в форт Камнеломов.", description = "Связь с духами араккоа потихоньку налаживается, но они все же слишком пугливы. Возможно, если я украшу свои одеяния, они согласятся приблизиться ко мне в трансе.\n\nДля этого мне понадобится еще немного перьев – тех, что вы однажды приносили. Приносите все, что удастся собрать, я с радостью приму их!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЗапасы охотника на араккоа"}
MultiLanguageQuestData['ru'][10197] = {title = "Убедительная маскировка", objective = "Добудьте комплект одеяний чародея из армии Ярости Солнца, одну пару перчаток ученого из армии Ярости Солнца и медальон охранника из армии Ярости Солнца и принесите все это Каледису Сияющему Рассвету в манагорн Коруу в Пустоверти.\n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "Проникнуть в ряды армии Келя – нелегкая задача. С моим знанием магии иллюзий я могу придать тебе вид одного из приспешников Келя, однако в их форме есть некоторые детали, которые я не могу воспроизвести. \n\nПринеси мне комплект одеяний, пару перчаток и медальон охранников из клана Ярости Солнца. Это сделает камуфляж куда более убедительным.", progress = "Удалось ли тебе добыть те детали одежды, о которых я тебе говорил?", completion = "Превосходно! Когда я закончу работу, ты сможешь неузнанным проникнуть в ряды армии Келя!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10198] = {title = "Сбор информации", objective = "Используя маскировку клана Ярости Солнца, проникните в Манагорн Коруу и подслушайте разговор между командиром Кузней Солнца и чародеем Ардонисом.\n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "Я подготовил форму вместе с добытыми тобою деталями. Она усилена магией для довершения иллюзии.\n\nМы заметили, что несколько минут назад командир Кузня Солнца в сопровождении охраны отправился на встречу с чародеем Ардонисом. Видимо, встреча будет невероятно важной; посмотрим, сможешь ли ты что-либо разузнать.\n\nО, едва не забыл: тебе нужно держаться подальше от чародейских големов, патрулирующих манагорн. Они могут видеть сквозь иллюзию.", progress = "Ну и как, удалось что-то подслушать, Выручалкин? Поспеши. У меня полно срочных дел.", completion = "Проблены в манагорне Даро? Я уверен, Талодиен не прочь услышать такие новости. Но сначала закончим работу здесь.", rewards = "Пояс мудростиНаручи яркого рассветаНаголенники кровостражаАрбалет главы шпионовВы получите:\n\n"}
MultiLanguageQuestData['ru'][10199] = {title = "Дополнительная сила", objective = "Принесите 5 шипов скатов Пустоты Бутсу, находящемуся в Зоне 52 в Пустоверти.", description = "Мне не хватает только одного ингредиента, который придаст моему составу дополнительную силу. \n\nШипы скатов Пустоты, болтающихся вокруг глиношкурых камнедеров, содержат массу действенного вещества. Принеси мне несколько таких шипов, и я извлеку яд прямо из них.\n\nЯ уверен, что результат будет просто взрывным!", progress = "Если я смогу выкачать яд из достаточного количества шипов ската, то, думаю, мы сумеем получить самое взрывчатое топливо в истории!", completion = "Ух ты! Отлично, теперь и поговорим!\n\nДай, я только возьму эту прелесть и выжму из нее всю пакость. Если добавить это в ракетное топливо, то все просто из штанов повыпрыгивают!\n\nПогоди, я только примешаю этот яд к глинистой нефти, и посмотрим, что будет...", rewards = "Наплечье переработкиПерчатки барменаПояс докиБутсы ПрибыльцаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10200] = {title = "Возвращение к Талодиену", objective = "Вернитесь к патрону шпионов Талодиену в Зону 52 в Пустоверти.", description = "Нужно, чтобы эти сведения попали к Талодиену как можно быстрее. Я останусь здесь, чтобы замести следы. \n\nБудет плохо, если Кель'тас обнаружит, что мы тут занимались шпионажем. Тайная информация всегда ценнее, если враг не знает, что она у тебя есть.", progress = nil, completion = "Ты не перестаешь удивлять меня, Выручалкин. Тебе удалось многое узнать в манагорне Коруу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10201] = {title = "Момент истины", objective = "Найдите Грека и попросите его смазать маслом свое оружие, после чего вернитесь к Ракории.", description = "Масло готово, можно испытывать. Оно достаточно густое, чтобы из него вышла высококачественная смазка для оружия.\n\nЕдинственный способ проверить это – устроить профессиональное испытание. Видишь Грека, вон там, у объявлений о розыске? Он грубоват, но в оружии разбирается, как никто.\n\nОтнеси ему немного масла и попроси, чтобы он смазал им свое оружие. Когда испробует, пусть скажет, как оно ему понравилось.", progress = "Ну, как прошло испытание?", completion = "&lt;Вы рассказываете Ракории о результатах испытания и она громко хохочет, запрокинув голову&gt;", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБлестящее масло маныБлестящее волшебное масло\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10202] = {title = "Дезертир", objective = "Отправляйтесь в манагорн Ара и поговорите с магистром Теледорном. \n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "Недавно с нами связался магистр из клана Ярости Солнца, который желает вступить в наши ряды и утверждает, что у него есть нужные нам сведения. Мы провели проверку на предмет того, не является ли он двойным агентом, и он эту проверку прошел.\n\nОн находится в манагорне Ара, что сильно затрудняет переговоры. Поговори с ним и узнай, много ли ему известно. Если он хотя бы вполовину так полезен, как утверждает, то мы найдем ему хорошее применение.", progress = nil, completion = "Ты вовремя. Я уже начал думать, что Провидцам нет никакого дела.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10203] = {title = "Захват бесценного оборудования", objective = "Используйте ультра-разуплотняющий захват, чтобы доставить гиперротационный Рой-О-Мат, сервоприводную пневматическую землечерпалку, радужный световой анализатор грунта и большой фургон с взрывчаткой обратно в Зону 52. Затем сообщите старшему саперу Бджимбуму, находящемуся на восточном конце расселины, идущей через Зону 52 в Пустоверти.", description = "Видишь расселину, идущую через Зону 52? Мы сделали это! <ухмыляется>. \n\nПосредством ее мы доставляем всякие полезные штуки для ракеты X-52, однако у нас не хватает оборудования. \n\nДо вторжения Пылающего Легиона мы проводили некую операцию в руинах Арклона к юго-востоку отсюда. Я прошу тебя отнести в эти руины ультра-разуплотняющий захват. Используй его, чтобы вернуть оттуда наши механизмы старшему саперу Бджимбуму, находящемуся на том конце расселины. \n\nМладший лаборант 3-й степени <имя>, это твой шанс на продвижение. Не упусти его!", progress = "Классное местечко, скажи? И каждый день появляется что-нибудь новое и необычное. \n\nКак удачно, что мы едва не уничтожили поселение, копаясь здесь.", completion = "Должно быть, это ты вернул нам все это саперное оборудование из руин! Ура!\n\nЯ уже распределил это оборудование по другим точкам. Теперь мы сможем выполнять наши операции по всему острову в порядке возрастания! Ракета Пустоты вот-вот будет построена.\n\nХмм, это странно. Минутку, сколько предметов ты нам послал? Я получил только три...", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][10204] = {title = "Кристаллы камня Крови", objective = "Магистр Ларинна просит вас отправиться в манагорн Б'наар и отобрать осколок камня крови у магистра из клана Ярости Солнца. Используйте этот осколок поблизости от более крупного кристалла камня крови и возвращайтесь к Ларинне в Зону 52.\n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "Магистры Келя отточили свое использование кристаллов маны до такой степени, что могут откачать большое количество энергии за несколько секунд.\n\nДля этого они настраивают осколки более мелких кристаллов камня крови на более крупные, полностью заряженные кристаллы.\n\nОтправляйся в манагорн Б'наар и отними один из этих осколков у магистра из клана Ярости Солнца, чтобы использовать его для перекачивания энергии из одного из более крупных кристаллов.\n\nВозвращайся ко мне, чтобы я могла изучить эффект ауры. Не беспокойся: любые побочные эффекты будут временными.", progress = nil, completion = "Хмм... как я и подозревала.\n\nВоздействие такого уровня сырой энергии во много раз увеличивает нашу природную зависимость от магии.\n\nЯ не удивлена, что Келю сходит с рук то, что он творит; все его подчиненные в основном упиваются этим.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10205] = {title = "Астральный налетчик Несаад", objective = "Убейте астрального налетчика Несаада, затем возвращайтесь к ловчему Пустоты Кай'джи, находящемуся в Зоне 52 в Пустоверти.", description = "С астральным налетчиком Несаадом должно быть покончено! Я понятия не имею, как он пережил мою атаку, но ему нельзя позволить продолжать творить все, что он хочет.\n\nВозвращайся и повергни Несаада. Он устроил маленький астральный лагерь поблизости от юго-западной оконечности Груды.\n\nПусть тебе повезет больше, чем мне, <класс>.", progress = "Все кончено? Астральный налетчик Несаад мертв?", completion = "Какое облегчение - услышать, что с этим негодяем наконец-то покончено. Отличная работа, Джонниди... может быть, я слишком поспешил, назвав тебя по имени?\n\nЕсли ты не против, то у меня есть еще одно задание, которое требует исполнения. Оно чрезвычайно важно, и некоторые из уже проявленных тобою умений позволят тебе справиться с ним без труда.", rewards = "Наручи братства ЗаксисСапоги братства ЗаксисПерчатки братства ЗаксисВы получите:\n\n"}
MultiLanguageQuestData['ru'][10206] = {title = "В погоне за технологиями", objective = "Соберите 10 астральных технологий и вернитесь с ними к Папаше Колесуну, находящемуся в Зоне 52 в Пустоверти.", description = "Эти астральные шуты так же предприимчивы, как мы, это я за ними признаю. Но никто – то есть именно что НИКТО – не имеет права на то, что принадлежит МОЗГу!\n\nГруда на юге – наша!\n\nЕсли мы собираемся закончить ракету Пустоты Х-52, нам потребуются все новые технологии, которые мы только сможем заполучить. А поскольку духи Астрала крадут ее у нас, я думаю, будет только честно, если мы ответим им тем же.\n\nПочему бы тебе не отправиться туда и не посмотреть, можешь ли ты похитить их технологические наработки прямо у них из-под носа?", progress = "Как ты быстро – а технологии? С этим лучше не тянуть.\n\nУспех проекта Х-52 зависит от того, сможешь ли ты доставить нам технологии!", completion = "Хе-хе, астральные неудачники!\n\nСпасибо за помощь, |3-6(Маг). Держу пари, мы сможем встроить эти штучки в ракету. Интересно, что они делают? Ну, вот и узнаем! \n\nХмм, погоди, я пороюсь в карманах и посмотрю, есть ли у меня чем заплатить тебе.", rewards = "Поручи папыНаплечники МехТехВам дадут возможность выбрать одну из следующих наград:\n\nНаследие семьи колесного мастера\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10207] = {title = "Forward Base: Reaver's Fall REUSE", objective = "Доложитесь командиру передовой То'арху по прибытии к останкам Сквернобота.Верховное командование заметило твою доблесть в бою, <класс>. Тебя хотят отправить на передовую для встречи с командой Изуверского кулака. Они радикалы, твердо намеренные извести под корень Пылающий Легион, так что подойдешь...\n\nИди на восток 200 шагов, потом повернешь на юг у возвышенности. Увидишь Гибель Скверномора на том месте, где прежде стояла старая ферма. Как окажешься там, докладываешься передовому командиру То-Арху.\n\nШагом марш!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Верховное командование заметило твою доблесть в бою, <класс>. Тебя хотят отправить на передовую для встречи с командой Изуверского кулака. Они радикалы, твердо намеренные извести под корень Пылающий Легион, так что подойдешь...\n\nИди на восток 200 шагов, потом повернешь на юг у возвышенности. Увидишь Гибель Скверномора на том месте, где прежде стояла старая ферма. Как окажешься там, докладываешься передовому командиру То-Арху.\n\nШагом марш!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10208] = {title = "Лишить Легион подкрепления!", objective = "Уничтожьте врагов вокруг портала Зилус и портала Круул, соберите камни с рунами демонов.\n\nИспользуйте запалы То'арха внутри порталов Зилус и Круул.\n\nВозвращайтесь к То'арху в Гибель Сквернобота на полуострове Адского Пламени вместе с оставшимися запалами.", description = "На восток отсюда тянется передовая Легиона. По всей ее длине расположены порталы и ворота, по которым на полуостров Адского Пламени к Легиону поступает подкрепление. Мы должны их разрушить!\n\nВот, возьми эти запалы. Их разработали в Зоне 52, взрывчатым веществом для них служит собственная сила демонов. Нужно отбросить войска Легиона от порталов Зилус и Круул, собрать камни с рунами демонов и с помощью запала и четырех камней подорвать порталы. После выполнения задания возвращайся ко мне.", progress = "Ну как Легион, обрадовался подарочку, который мы для него подготовили, а, Выручалкин?", completion = "Просто прекрасно! Я, можно сказать, чуть ли не самолично почувствовал, как земля содрогнулась от взрыва!\n\nКак насчет еще одной подрывной работенки?", rewards = "Шляпа путника с затеняющими полямиЧародейский окольцованный мундирОпаленная кирасаПоножи из свежесодранной шкурыБольшой шлем завоевателяВы получите:\n\nПредмет #8"}
MultiLanguageQuestData['ru'][10209] = {title = "Трофей призывателя Кантина", objective = "Победите призывателя Кантина, находящегося в Манагорне Даро, на острове к северу от Форта Ярости Солнца, и заберите у него камень Студенора.", description = "Следующее, что мы должны сделать – это забрать моего фамилиара, Студенора, у заклинателя из эльфов крови, который держит его в заточении. Призыватель Кантин был одним из старших магистров в войске, которое Кель'тас отправил на уничтожение Кирин'Вара. И, естественно, он забрал моего фамилиара в качестве трофея.\n\nЯ уверен, что Кантин, дурень этакий, пытался заставить Студенора служить ему. Прозрение открыло мне, что Кантин сейчас находится в так называемом \"манагорне Даро\", если это название о чем-нибудь тебе говорит.", progress = "Удалось ли тебе добыть камень Студенора?", completion = "&lt;Сложно сказать, искажается ли изображение или верховный маг действительно улыбается.&gt;\n\nТеперь, когда мне возвращено все, что было отобрано, у меня есть все необходимое, дабы пробиться сквозь магию Кель'таса. Я немедленно начинаю работать над заклинанием.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10210] = {title = "А'дал", objective = "Поговорите с А'далом, предводителем Ша'тар, в центре террасы Света.", description = "Добро пожаловать в Шаттрат, <класс>. Возможно, это единственное место во всем Запределье, где можно почувствовать себя в безопасности.\n\nГруппа наару, известная как Ша'тар, изгнала отсюда демонов.\n\nЕсли ты никогда не <видел/видела> наару, непременно зайди на террасу Света и поговори с А'далом – это предводитель Ша'тар и, пожалуй, самый харизматичное существо из тех, что я встречал. Он очень выделяется среди всех жителей этих суровых земель.", progress = nil, completion = "&lt;Когда вы приблизились к А'далу, вас пронизал внутренний свет, а когда вы обратились к нему, свет усилился и в голове зазвучала нежная мелодия.&gt;\n\n&lt;Здесь вы в безопасности.&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10211] = {title = "Город Света", objective = "Проследуйте за слугой Кадгара и выслушайте историю, которую он вам расскажет, после чего вернитесь к Кадгару.", description = "Не беспокойте А'дала незначительными вопросами, <класс>. Это, возможно, самое могущественное существо из тех, что вы встречали.\n\nОднако ваше лицо мне незнакомо... Вы, должно быть, мало знаете о нашем городе?\n\nНадеюсь, вы простите меня за то, что я не поведу вас на экскурсию лично, – мне нужно очень многое обсудить с А'далом. Вас устроит призванный слуга? Вот и отлично!", progress = "Истории о людях недолговечны, Атеистфрост. А вот истории о городах живут столетиями.", completion = "Надеюсь, вы узнали кое-что о Шаттрате, Солэтьюд. Понадобится время, чтобы информация устоялась в вашей памяти.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10212] = {title = "Герой маг'харов", objective = "Вернитесь к великой матери Гейе в Гарадар в Награнде.", description = "Перед отъездом я должен уладить кое-какие дела. Вернись к Великой матери и скажи, что ее внук скоро прибудет.", progress = nil, completion = "Ты - настоящий герой маг'харов, Магнетрикс. Если бы не ты, нас подмяли бы огры и Сломленные.\n\nМы небогаты, но у нас есть артефакты, наделенные немалой силой. Пожалуйста, я прошу... нет, я настаиваю... загляни в наш сундук и возьми, что захочешь.", rewards = "Рогатый шлем ритуалиста маг'харовМундир разведчика маг'харовПоножи охотника маг'харовНожные латы вождя маг'харовВы получите:\n\nЗнак героя маг'харов"}
MultiLanguageQuestData['ru'][10213] = {title = "Найти место крушения", objective = "Отыщите уцелевших в катастрофе.", description = "Меня ранили при отступлении, но я видел, как потерпел крушение гоблинский дирижабль. Он упал куда-то на северо-запад, за оружейной экспедиции.\n\nДирижабль был весь в огне. Пронзительно визжащие гоблины выпрыгивали из него на лету, как живые факелы. Я тогда не помнил себя от боли и вдобавок потерял много крови. Могу представить, каково пришлось этим бедолагам.\n\nЕсли ты найдешь кого-нибудь уцелевшего, мы предоставим ему убежище на заставе Хребтолома.", progress = nil, completion = "Нас подбил Пылающий Легион, хотя мы и размахивали белым флагом. Кто же знал, что они там такие тупые ублюдки?\n\nК сожалению, мы не сможем отправиться на Заставу Хребтолома. Надо чиниться и двигаться дальше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10214] = {title = "Весь рудник ходуном", objective = "Убейте 15 ган'аргов-саперов и возвращайтесь к штейгеру Разлкразу.", description = "На руднике и так было не продохнуть от ган'аргской заразы, а теперь еще все батраки решили, что сейчас самое время вздремнуть! Не представляю, как им удается спать во время этого бедлама, но это уже не мои проблемы.\n\nЕсли мы не избавимся от этих ган'аргов, поставки руды и остальных материалов в Траллмар полностью прекратятся! Я обращался к командиру стражи Кранку, но он ответил, что, дескать, не может выделить бойцов, пока город находится под угрозой. Может быть, хотя бы ты нам поможешь?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10216] = {title = "Прежде всего - безопасность!", objective = "Убейте 10 эфириалов – осквернителей гробниц, 5 эфириалов-колдунов, 5 ловчих нексуса и 5 эфириалов-чароплетов по просьбе работника Морфалиуса.\n\nПосле этого найдите эфириальский телепорт в зале, предшествующем палате Шаффара, и активируйте его.", description = "Астральные слуги Шаффара полностью перекрыли нам вход в Гробницы Маны. К счастью, у меня есть план. Мы не можем воспользоваться главным входом, но внутри должно быть несколько порталов.\n\nЯ хочу, чтобы ты сначала <расчистил/расчистила> дорогу для моей команды, а затем <активировал/активировала> один из порталов, чтобы телепортировать нас внутрь.\n\nПортал находится в комнате направо от входа в залы Шаффара. Не беспокойся, я позабочусь, чтобы ты не <остался/осталась> внакладе.", progress = "Прямо перед вами находится устройство с множеством кнопок непонятного назначения.", completion = "*Вы зажмуриваетесь и наугад нажимаете одну из кнопок.*", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10218] = {title = "Someone Else's Hard Work Pays Off", objective = "Проводите криоинженера Ша'хина в Гробницы маны, чтобы он мог собрать астральную субстанцию в коллекторах Шаффара.\n\nВ случае успеха явитесь к принцу нексуса Харамаду в лагере Консорциума.", description = "А ты кого <ждал/ждала>? Этот идиот Морфалиус разжалован. Теперь мне придется расхлебывать кашу, которую он заварил. Тебе нужно только прикрывать меня, пока я не дойду до Шаффаровых собирателей астральной субстанции и не выжму из них все, что они насобирали. Если мне это удастся, тебя наградит сам Харамад.\n\nНу, что скажешь? Проводишь меня в Гробницы Маны, где тебя ждут несметные сокровища? Ты уже и так, почитай, полдела <сделал/сделала>! Ведь позади нас никого не осталось, верно?", progress = nil, completion = "Поскольку это была идея Морфалиуса, я решил поручить ему его прежнюю работу. А ты очень неплохо поработал, маленький кусочек плоти. Совсем, совсем неплохо!\n\nЕсли опять окажешься в Пустоверти и тебе будет нужна работа, разыщи меня в Штормовой Вершине.", rewards = "Металлические наголенники плоти зверяРегулирующее оплечье КонсорциумаКрио-полуперчаткиПлаток принца-консортаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10220] = {title = "Заставь их слушать", objective = "Убейте 12 непреклонных пехотинцев, 8 непреклонных рыцарей и 6 непреклонных колдунов в оружейной экспедиции к западу от заставы Хребтолома по просьбе Мордибы.", description = "Меня послали, чтобы установить контакт с Непреклонными духами. Когда-то они были гордыми солдатами Альянса, но потерпели поражение, и теперь их проклятые души населяют западные руины.\n\nЕсли бы нам удалось уговорить их присоединиться, мы приобрели бы могучих союзников. Представь себе легион бессмертных воинов, которые атакуют наших врагов! К сожалению, Непреклонные пришли в ярость и отказались меня выслушать.\n\nМожет быть, мы заставим их сотрудничать силой?", progress = nil, completion = "Пусть эти Непреклонные знают, как иметь дело с Ордой! Не сомневаюсь, скоро они согласятся перейти на нашу сторону.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10221] = {title = "Доктор Бум!", objective = "Убейте Доктора Бума и возвращайтесь с хорошими новостями к старшему саперу Бджимбуму в Зону 52 в Пустоверти.", description = "Знаешь, <имя>, мой бывший подопечный, Живчик Вечнодвигатель, никогда не надевал шлем, находясь здесь, внизу, и в один прекрасный день превратился в печально известного Доктора Бума!\n\nОн сбежал на северо-восток, украв большую часть нашего подрывного оборудования! Он и его взрыв-боты с тех самых пор представляют собой угрозу для Зоны 52.\n\nЯ хочу послать тебя в Лагерь Бума, находящийся за городом, дабы покончить с этим негодяем. Используй эти бомбы Рока Бума, чтобы избавиться от него.\n\nИ ни в коем случае не подходи близко к нему и к его взрыв-ботам!", progress = "Удалось ли тебе спасти нас от разрушений, причиняемых Доктором Бумом? Я обещаю, что на этот раз не будет никаких взрывающихся повозок, хотя это очень весело!\n\nНеплохо бы устраивать такое почаще.", completion = "Я всегда буду тосковать по Живчику. (хлюпает носом) Но мы все будем спать спокойнее теперь, зная, что доктор Бум больше не будет терроризировать нас!\n\nПусть это послужит тебе уроком! Никогда не спускайся сюда без шлема Пустоты!\n\nНу что ж, чем я могу оплатить твои хлопоты?", rewards = "Жилет ПустотыПоножи ПустотыИскрящийся выброшенный шлемСтражи ПустотыВы получите:\n\n"}
MultiLanguageQuestData['ru'][10222] = {title = "Гарнизон Ярости Солнца", objective = "Смотритель Дайворт из деревни Кирин'Вар просит вас убить 10 лучников из армии Ярости Солнца.", description = "После того как войска принца Кель'таса уничтожили это поселение и заточили верховного мага в Аметистовой башне, они отступили на северо-восток, в форт Ярости Солнца. Те самые солдаты, которые уничтожили наши дома и убили наших товарищей, празднуют свою \"великую победу\", в то время как мы не можем даже отомстить за павших.\n\nМы не должны позволить, чтобы подобное преступление осталось без ответа. Будь орудием нашего возмездия, <имя>. Ступай в форт Ярости Солнца и отними жизни у тех, кто виновен в этом преступлении.", progress = nil, completion = "Пусть даже сделанное тобой не сможет вернуть к жизни павших, но, быть может, даст покой их душам. Хотя, правду сказать, даже море крови не угасит мой гнев, вызванный деяниями Кель'таса.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10223] = {title = "Покончить с Даэллисом", objective = "Смотритель Дайворт из деревни Кирин'Вар просит вас убить наставника Даэллиса Стрелка Рассвета.", description = "Я никогда не забуду эльфа крови, возглавлявшего ту атаку. Поверх алого доспеха на нем была гербовая накидка с эмблемой, которую я никогда прежде не видел.\n\nОн был свиреп и безжалостен и шел впереди всех, хотя большинство офицеров из эльфов крови так ни за что не поступили бы. В тот день он убил множество магов Кирин-Тора. Однако в форте Ярости Солнца он пробыл недолго. Кель'тас отослал его в манагорн Даро, дабы помочь тамошним эльфам в их попытках взять контроль над этим регионом. Найди его, <имя>, и пусть его лук никогда больше не выстрелит.", progress = nil, completion = "&lt;Может быть, вам это всего лишь кажется, но смотритель Дайворт словно бы готов разрыдаться.&gt;\n\nНаконец-то это свершилось. Если бы я мог по собственной воле завершить свое существование, я бы сделал это, но истина в том, что я не знаю, как уйти. Для обитателей деревни это сложно, однако все впереди. Я полагаю, такова цена, которую мы платим за сильную привязанность к этому месту.", rewards = "Плащ рассветной мощиНарукавники ночного ловцаВам дадут возможность выбрать одну из следующих наград:\n\nПерстень Аметистовой башниСила Аметистовой башни\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10224] = {title = "Эссенция для двигателей", objective = "Соберите 7 единиц эссенции призрака магии и доставьте главному инженеру Трепу в Зону 52 в Пустоверти.", description = "Как главный инженер проекта ракеты Пустоты Х-52 я должен сделать так, чтобы главный двигатель был в наилучшем виде.\n\nК несчастью, я его еще не построил.\n\n<класс>, я в отчаянном положении! У меня есть почти все детали. Отсутствует только ядро двигателя.\n\nК счастью, для того, чтобы запустить двигатели, мы, вероятно, можем использовать эссенцию из местных призраков магии.\n\nИх можно найти почти возле каждой светящейся канавы в северной части острова. За исключением Зоны 52, конечно.", progress = "Ну как, удалось набрать эссенции?", completion = "Ого, тут полно эссенции!\n\nОтлично, посмотрим, что будет, когда я смешаю ее с астраллитиевыми матричными кристаллами.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10225] = {title = "Рапорт главному инженеру", objective = "Передайте астраллитиевые матричные кристаллы главному инженеру Трепу, находящемуся в Зоне 52 в Пустоверти.", description = "<имя>! Я прошу тебя доставить эти астраллитиевые кристаллы главному инженеру Трепу, моему... э-э... начальнику в области инженерного дела.\n\nОн должен знать, что с ними делать. А если не знает, то поймет, вот увидишь!", progress = "А, привет. Я тут малость занят. Что там у тебя?", completion = "О-о, астраллитиевые матричные кристаллы! Да, это важное дело!\n\nДавай положим их вот сюда, и я немного над ними поразмыслю.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10226] = {title = "Извлечение силы стихии", objective = "Извлеките 5 единиц силы стихии для главного инженера Трепа, находящегося в Зоне 52 в Пустоверти.", description = "Проклятье, это не сработало!\n\nЛадно, у меня есть другая идея! Я заставил Ксирола собрать экстрактор силы стихии. Я не уверен, что именно делает эта сила, но знаю, что могу использовать ее.\n\nВыщербленные грохотуны и астральные аберрации, встречающиеся на уступе Гиблого пустыря к югу отсюда, – именно то, что мне нужно для заправки двигателей!\n\nЭкстрактор превратит их силу в нечто материальное, так что ты сможешь собрать ее – после того, как одолеешь ее носителей.", progress = "Ну как, удалось извлечь энергию элементалей? Да нет, какой смысл спешить? На кон поставлены всего лишь моя жизнь и карьера.", completion = "Вот это уже лучше! Ну ладно, теперь займемся делом.\n\nДай я только перелью всю эту субстанцию вот в эту штуковину, и я уверен, что ядро фазового двигателя будет функционировать.\n\nАга, полагаю, я тебе что-то должен за спасение моей головы? Хе-хе...", rewards = "Наплечные щитки трепаКрепкие сапоги инженераПерчатки инженера Зоны 52Пояс главного инженераВы получите:\n\n"}
MultiLanguageQuestData['ru'][10227] = {title = "Я вижу мертвых дренеев", objective = "Поговорите с Рамдором Безумным, который стоит на груде костей неподалеку от Аукенайских гробниц.", description = "Я вижу мертвых дренеев. Они тут повсюду.\n\nНо мне никто не верит, потому что я всего лишь ребенок. Даже мама, и та не верит.\n\n<Ха'лей указывает на Рамдора.>\n\nТолько он верит. Он тоже их видит. Но ему тоже не верят, и это выводит его из себя!\n\nСтранно, правда? Когда я вижу призраков, люди улыбаются и гладят меня по головке. А когда он видит призраков, все считают его чокнутым. Надеюсь, я никогда не стану, как эти взрослые!\n\nНо ты бы лучше <поговорил/поговорила> с Рамдором перед тем, как полезешь внутрь. Все-таки раньше он был жрецом мертвых.", progress = nil, completion = "Ребенок прав. Когда-то я в самом деле был \"жрецом мертвых\".\n\n&lt;Рамдор кривится.&gt;\n\nМалоприятный титул.\n\nЭтот коридор ведет в Аукенайские гробницы. Там, внутри, ты найдешь то, что осталось от моей паствы. Разумеется, теперь все они совершенно безумны. Сошли с ума, все до единого. Очевидно, я слишком выделялся среди них, будучи единственным, кто сохранил хотя бы остатки здравого смысла. Конечно же, меня изгнали за мои убеждения.\n\nХочешь знать, за какие?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10228] = {title = "Иезекииль", objective = "Найдите Иезекииля из Шаттрата в городе Шаттрат и поговорите с ним.", description = "Я полагал, что мертвецов, которыми мы занимались последние 500 лет, пора оставить в покое. Но у Маладаара другие планы. Он забрался в склеп Воспоминаний и начал там свои эксперименты... с некромантией.\n\nЯ надеюсь, ты не собираешься туда соваться? Ну, по крайней мере, для начала помоги мне избавиться от этих проклятых духов. Я знаю, где они хранят свои сокровища, <раса>! Что, интересно?\n\nТак вот, принеси мне книгу мертвых, которой владеет Алдор, Иезекииль из Шаттрата.", progress = nil, completion = "Книга мертвых? Никогда о такой не слышал... О чем вообще речь? Кто тебя прислал?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10229] = {title = "Секрет фолианта", objective = "Отнесите таинственный фолиант Альтену Историку на Заставу Хребтолома.", description = "Похоже, в этом фолианте записана некая история, но не просто так, а секретным шифром Альянса. Альтен, историк с Заставы Хребтолома, какое-то время изучал Непреклонных. Может быть, ему удастся расшифровать код и прочитать эту книгу.", progress = "Что это? Эта книга была у Непреклонного духа? Как странно. Дай-ка посмотреть. Возможно, теперь я узнаю историю Непреклонных.", completion = "Я изучаю историю древних всю свою жизнь, но не видел ничего похожего на эту книгу. В ней изложена вся история Оружейной, даже то, что произошло после ее разрушения.\n\nТела Непреклонных остались лежать на поле сражения, но они все равно продолжали вести свою летопись. Эта книга должна нам помочь понять Непреклонных, и уговорить их вступить в наши ряды.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10230] = {title = "Боевой рог", objective = "Заберите у лейтенанта-командора Талвоса Боевой рог Непреклонных и принесите его Альтену Историку на Заставу Хребтолома.", description = "Может быть, мы выбрали к Непреклонным не тот подход?\n\nВ фолианте написано, что оружейную экспедиции когда-то давным-давно разрушили рыцари смерти. И Непреклонные – это духи мщения, обреченные вести нескончаемую войну с орками Скверны.\n\nВсе их помыслы – только о мести. Мы должны пообещать, что дадим им возможность сразиться со своими самыми злейшими врагами. Отправляйся в оружейную снова и разыщи лейтенанта-командора Талвоса. У него есть боевой рог, который призывает Непреклонных. Принеси его мне.", progress = "Скоро мы сможем помочь Непреклонным. Если мы убедим их присоединиться к Орде, они станут могучими союзниками!", completion = "Ты хорошо потрудился, Джонниди. Этот древний рог позволит нам призывать Непреклонных.\n\nКонечно, если они согласятся.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10231] = {title = "Какая книга? Не вижу никакой книги", objective = "Иезекииль говорит, что книга могла быть украдена. Найдите головорезов и попытайтесь узнать что-нибудь у них.", description = "Рамдор? Хмм... Дай-ка подумать... Рамдор... Ах да, жрец мертвых. Чего он хочет, какую книгу? Ладно, это не важно. Конечно, я тебе соврал и никакой книги у меня нет. Была, а теперь нет. Ее у меня украли. Наверное, кто-то из этих мерзких беженцев.\n\nКроме того, Аукиндон давно развалился, и книгу все равно уже невозможно использовать. Если найдешь ее, смело можешь оставить себе.\n\nКак я уже говорил, на прошлой неделе тут шныряли какие-то бандиты, можешь начать поиски с них. Я думаю, они режутся в кости где-нибудь в трущобах.", progress = "Че надо?", completion = "Ладно, хватит, больно же! У нас была какая-то книга, но мы ее сбагрили...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10232] = {title = "Легион – на мусор!", objective = "Убейте 5 мо'аргов-кузнецов рока и 15 ган'аргов-инженеров. Затем возвращайтесь к Папаше Колесуну в Зону 52 в Пустоверти.", description = "Пылающий Легион ступил в наши владения на Захламленном поле, что находится вниз по тропе отсюда, а далее по мосту на восток.\n\nДля нас это может представлять серьезную проблему. Пребывание Легиона в руинах Арклона – а он сейчас находится там – несет угрозу и нам, и всему проекту по построению ракеты здесь, в Зоне 52.\n\n<имя>, отправляйся туда и покончи с этими демонами. Я бы и сам это сделал, но я не боец, а так, дилетант.\n\nНу да, если дело пойдет плохо, я это почую!", progress = nil, completion = "Ну что ж, хорошие новости и плохие новости, верно? Мы нанесли им удар, но все же Пылающий Легион продолжает заполонять всю Пустоверть и подбирается к нам все ближе. Я теперь уж и не знаю, как все обернется.\n\nУ меня такое чувство, что нам придется на некоторое время сменить курс. Надеюсь, ты сможешь нам помочь, Выручалкин.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10233] = {title = "Пожар в форте Ярости Солнца", objective = "Используя горящий факел, уничтожьте 4 баллисты и 4 шатра в форте Ярости Солнца, затем вернитесь к лейтенанту-чародею Моррану в деревню Кирин'Вар.", description = "Если даже очистить форт Ярости Солнца от гарнизона, это не помешает эльфам крови вновь занять его. Последователи Кель'таса упорны и полны решимости. Оставить в форте Ярости Солнца что-либо, что они могут использовать, равносильно приглашению вернуться.\n\nНет, это все следует уничтожить. Проследи, чтобы все их шатры и боевые орудия превратились в угли и пепел!\n\n<Призрак сжимает кулаки.>\n\nДля того чтобы выполнить эту задачу, надо похить факелы у хранителей пламени из армии Ярости Солнца, <имя>.", progress = "Дым поднимается над укреплениями форта Ярости Солнца. Это твоя работа?", completion = "&lt;Лейтенант-колдун Морран мрачно кивает.&gt;\n\nВолшебники Кирин-Тора не любят разрушение как таковое, но мы без колебаний пускаем его в ход против наших врагов, даже после смерти.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][10234] = {title = "Что одному демону мусор...", objective = "Соберите 10 деталей сквернобота и доставьте их Мамаше Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти.", description = "Похоже, ты много на что <способен/способна>! А не можешь ли ты мне помочь?\n\nК востоку отсюда находится Захламленное поле, куда вторгся Пылающий Легион. Там полно огромных частей скверноботов. И еще там целые горы более мелких деталей, которых, похоже, никому не нужны.\n\nЯ прошу тебя отправиться туда и принести мне много-много этих мелких деталей от скверноботов!", progress = "Удалось ли добыть детали? Пылающий Легион попирает все наши права, одно за другим, и у нас, увы, осталось мало времени.", completion = "Полагаю, пока что хватит. Если бы мы только могли собрать их все...\n\nАга, у меня возникла идея!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10235] = {title = "Коготь Рока? Вырвать с мясом!", objective = "Заберите руку Когтя Рока и доставьте ее Мамаше Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти.", description = "Ты знаешь, что может лишить их храбрости? Гибель их предводителя!\n\nСудя по тому, что я слышала, это срабатывает всегда и везде. А когда они увидят, как <такой/такая:c> <класс>, как ты, повергает их вожака... держу пари, они подожмут хвосты и удерут в холмы!\n\nВозвращайся туда и пристукни самого большого, которого они называют Коготь Рока. Я слышала, он прячется в восточной части Захламленного поля под трубой.\n\nПринеси мне его коготь. Может, и ему найдется применение.", progress = "Ну что, с Когтем Рока покончено?", completion = "Он... что он сказал? ОНИ СОБИРАЮТСЯ ПОЙТИ НА ЗОНУ 52?!\n\nО, это плохо... ужасно плохо!", rewards = "Вырывающая клыки лапаВоровской астральный клинокМамашина страховкаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10236] = {title = "Гадость это ваше Запределье!", objective = "Найдите 6 частей крошшера и верните их штейгеру Разлкразу на рудник, который находится к северо-западу от Траллмара.", description = "Не могу поверить, что я бросил свою родную Пиратскую Бухту и перебрался сюда, в Запределье. Мой кузен Скрид Счастливчик наобещал мне золотые горы, а сам сел на дирижабль и смылся, оставив меня в прямом смысле слова выскребать из рудника средства к существованию.\n\nНе понимаю, как можно жить, когда на тебя постоянно нападают то зловепри, то демоны, то орки Скверны? Вчера у меня сломался крошшер, а запчасти к нему сперли орки Скверны. Они отправились куда-то на юго-запад, и наверняка уронили мои драгоценные детали в одну из тамошних расщелин.", progress = "Ну как, удалось вам найти запчасти от крошшера? Если я не починю его, то не смогу работать! А мне нужны деньги, чтобы вернуться в мою драгоценную Пиратскую Бухту!", completion = "Ура, ура, запчасти снова у меня! Может быть, теперь я смогу починить крошшер. Если я заработаю достаточно денег, то смогу выбраться отсюда и вернуться домой.\n\nНадеюсь, к этому времени кузен Счастливчик наконец расколотит свой дирижабль! Не могу поверить, что он обманом затащил меня в это гадское Запределье.", rewards = "Вы получите:\n\nРуда оскверненного железа"}
MultiLanguageQuestData['ru'][10237] = {title = "Предупредить Зону 52!", objective = "Передайте плохие новости ведущему ракетостроителю Фьюзеляжу в Зоне 52 в Пустоверти.", description = "<имя>, тебе следует немедленно возвращаться в Зону 52! Живо!\n\nСкажи командующему ракетами, что Пылающий Легион идет на нас!", progress = nil, completion = "Эй, ты же шутишь, да? Пылающий Легион винит во всем этом нас?\n\nНо это же все ТВОИ деяния!\n\nОх, у меня голова распухла до размеров этой ракеты. Ладно, ладно, придется менять планы.\n\nЕсли Пылающий Легион думает, что может вот так запросто прийти сюда, уничтожить наш город и разрушить мои мечты о путешествии через Круговерть Пустоты, то они глубоко ошибаются.\n\nЯ знаю гоблина, который нам поможет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10238] = {title = "Каково работать на гоблинов", objective = "Спасите Манни, Моха и Джакка из лагерей орков Скверны и доставьте их штейгеру Разлкразу на рудник, который находится к северо-западу от Траллмара.", description = "Ну почему эти орки Скверны свистнули запчасти от моего крошшера? Как я их ненавижу! Они все время проползают в мой лагерь и прут все, что плохо лежит. Несколько дней назад они утащили даже троих батраков! А теперь все остальные поразбежались, потому что боятся, что орки Скверны тоже поймают их и сожрут.\n\nКак прикажете управлять рудником, когда на нем не осталось батраков? Если вы спасете тех, кого увели орки, может быть, и все остальные вернутся? Лагеря орков Скверны расположены вдоль стены на юго-западе.", progress = "Ну как, удалось вам спасти моих батраков? Поторопитесь, пожалуйста. Их могут съесть, а они не особенно вкусные... Страшно подумать, как на меня разозлятся орки Скверны, если рабы придутся им не по вкусу!", completion = "Спасибо, что спасли моих батраков! Может быть, теперь мне удастся заставить их починить крошшер, благо запчасти вы мне тоже вернули. И тогда я наконец заработаю денег и смогу вернуться в Пиратскую Бухту!", rewards = "Вы получите:\n\nЯдреное пойло батрака"}
MultiLanguageQuestData['ru'][10239] = {title = "Потенциальный источник энергии", objective = "Лейтенант-чародей Морран из деревни Кирин'Вар просит вас захватить 10 энергетических кубов-изоляторов, используемых эльфами крови в манагорне Коруу.", description = "Мы не единственные, кто борется со вторжением мана-тварей. Эльфы крови тоже встревожены их появлением, однако я не знаю точно, почему.\n\nОднако во что бы они ни были втянуты, похоже, они не намерены останавливаться. Напротив, я вижу, что они применяют различные методы для убиения тварей. Самые эффективные способы включают в себя установку магической защиты, питаемой каким-то видом концентрированной энергии.\n\nЗахвати несколько таких источников энергии и принеси их мне. И если представится возможность в чем-либо помешать эльфам, сделай это без колебаний.", progress = "Тебе удалось заполучить источники их энергии?", completion = "&lt;Морран осторожно берет одно из вместилищ.&gt;\n\nМне кажется, ранее я не видел ничего подобного. В нем определенно содержится множество энергии, однако в необработанном, сыром виде. Мы должны быть осторожны с ней, однако я думаю, мы найдем, как приспособить ее для защиты от мана-тварей.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10240] = {title = "Постройка периметра", objective = "Используйте устройство пробуждения рун поблизости от восточной, северо-восточной и западной руны. Руны можно найти по периметру районов переулка Волшебников и главной площади деревни Кирин'Вар. По завершении задачи вернитесь к лейтенанту-чародею Моррану.", description = "Мы решили соорудить вокруг деревни защитный периметр, используя источники энергии, отобранные у эльфов крови. Я не могу гарантировать, что это сработает, но мы должны попытаться.\n\nИначе мана-твари, несомненно, будут продолжать поглощать духов погибших магов из Кирин-Тора.\n\nИспользуй это устройство на малых рунах по периметру поселения, чтобы высвободить энергию. Если я правильно соткал это поле, то разница будет заметна сразу же после того, как ты применишь это устройство на каждой руне.", progress = "Все ли руны пробуждены? Я хочу узнать, удалось ли нам улучшить методы эльфов крови. Все, что могут сделать подчиненные Кель'таса, настоящие маги Кирин-Тора могут сделать лучше.", completion = "Отличная работа, Выручалкин. Теперь держи за меня кулаки - я собираюсь включить щит.", rewards = "Прикосновение гармонииБагровые наручиНаголенники защитника Кирин'ВараСапоги милосердияСледующее заклинание будет наложено на вас:\n\nЧародейский взрыв (декоративный эффект)\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][10241] = {title = "Отвлекающий маневр в манагорне Б'наар", objective = "Убейте 8 магистров и 8 кровостражей клана Ярости Солнца, затем возвращайтесь к экзарху Орелису в Зону 52.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Мы были посланы Ша'тар, чтобы провести расследование по поводу манагорнов, которыми управляет армия Кель'таса. К несчастью, Провидцы угрожают отказаться от своих обязанностей по сбору сведений, если мы не поддержим их путем военных действий.\n\nМы не можем позволить, чтобы эта миссия потерпела провал из-за политики, поэтому согласились ослабить защиту манагорнов, дабы Провидцы могли выполнить свою работу.\n\nПрояви свою верность Алдорам – убей магистров и кровостражей клана Ярости Солнца, которые охраняют манагорн Б'наар.", progress = nil, completion = "Превосходная работа, Мротсагемо! Благодаря твоим отвлекающим действиям Провидцы сумели добыть ценные сведения. Может быть, на этот раз они действительно поделятся этими сведениями с нами.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10242] = {title = "Застава Хребтолома", objective = "Доставьте образец крови орков из клана Кровавой Глазницы аптекарю Альбреку на заставу Хребтолома по просьбе аптекаря Зеланы из Погибели Сквернобота. Чтобы добраться до заставы на виверне, обратитесь к командиру звена Бракку.", description = "К сожалению, <имя>, у меня нет оборудования, чтобы провести все исследования, какие нужно. Но нужные инструменты есть у моего коллеги, аптекаря Альбрека, на заставе Хребтолома.\n\nАгенты Траллмара во время своей прошлой экспедиции собрали кровь орков из клана Кровавой Глазницы, и мне удалось добыть образец. Отнеси его Альбреку, пусть изучит его как следует.\n\nЕсли хочешь без помех добраться до заставы Хребтолома, разыщи командира звена Бракка. Он где-то на юге, рядом с вивернами.", progress = "Добро пожаловать на Заставу Хребтолома! Чем могу служить?", completion = "Протестировать образец крови, да? С превеликим удовольствием! Работать с кровью всегда приятно...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10243] = {title = "Технология наару", objective = "Зайдите в манагорн Б'наар и найдите панель управления манагорном.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Провидцы раздобыли список персонала манагорна Б'наар и теперь работают над тем, чтобы выбрать цели для убийства.\n\nОни упустили одну маленькую крупицу информации – запись на обратной стороне списка. Похоже, это пароль или код, используемый для доступа к созданным наару технологиям, таким как \"Экзодар\" или Крепость Бурь.\n\nИди в манагорн и взгляни на панель управления. Скопируй ее показания на этот свиток как можно точнее. Мы должны подтвердить наши подозрения относительно этой технологии.", progress = "Символы, разворачивающиеся перед тобой, выглядят чуждыми и непонятными.", completion = "Ты разворачиваешь свиток и готовишься скопировать странные символы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10244] = {title = "Учи матчасть!", objective = "Отнесите инструкцию по созданию сквернобота Мамаше Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти.", description = "Сломав печать на этом огромном томе, ты не можешь понять, что в нем говорится. Похоже, книга написана на языке демонов.\n\nОднако ты вполне понимаешь картинки, которые сами по себе говорят о многом.\n\nЯсно, что это инструкция по созданию сквернобота, и ты точно знаешь, что Мамаша Колесун очень захочет на это взглянуть!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10245] = {title = "Описание панели управления Б'наара", objective = "Передайте описание панели управления Б'наара анахорету Карже в Зону 52 в Пустоверти.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Ты пытаешься описывать рисунки и знаки, вспыхивающие у тебя перед глазами. Результаты получаются далеко не точными, однако вполне могут послужить доказательством того, насколько правильны – или неправильны – подозрения Алдоров.", progress = "Давай посмотрим, что это такое, Сотус.", completion = "Неплохая работа, Сотус. Подожди минуту, я прогляжу это описание. \n\nЖречество благодарно тебе, |3-6(Рыцарь смерти).", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10246] = {title = "Нападение на манагорн Коруу", objective = "Отправляйтесь к манагорну Коруу и убейте 8 чародеев и 5 ученых из армии Ярости Солнца. По завершении задачи возвращайтесь к экзарху Орелису.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Тебе удалось добиться примечательных успехов в манагорне Б'наар. Я уверен, что анахорет Каржа попросит тебя повторить то же самое в манагорне Коруу.\n\nМы узнали, что туда отправлено подразделение, состоящее из известных чародеев и ученых клана Ярости Солнца. Если ты выберешь это подразделение своей целью и преуспеешь в его уничтожении, то нанесешь сокрушительный удар по врагу.", progress = nil, completion = "Превосходная работа, Мротсагемо. Подобная решимость, несомненно, позволит нам победить врага.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10247] = {title = "Вомиза, доктор псевдотехнических наук", objective = "Поговорите с доктором псевдотехнических наук Вомизой на Испытательном полигоне в Пустоверти.", description = "За восточной окраиной города располагается Испытательный полигон. Наш главный экспериментатор, доктор Вомица, играл там с сочетанием технологий скверноботов, эфириалов и, конечно же, гоблинов.\n\nИ в немалой степени это удалось благодаря твоим усилиям по сбору сведений, младший лаборант 3-й степени <имя>!\n\nОтправляйся к доктору; я знаю, что он нашел решение проблемы - как спасти Зону 52.\n\nИ поскольку он скорее всего захочет задействовать тебя как объект для испытаний, то на твоем месте я на всякий случай взял бы с собой друга.", progress = nil, completion = "Ну-ну, похоже, нам повезло, юноша.\n\nЯ недавно завершил сборку моего последнего изобретения, \"Утилизатора Х6000\"!\n\nИ тебе выпала высокая честь – помочь мне испытать этот утилизатор, чтобы его можно было использовать при защите Зоны 52!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10248] = {title = "Ты, робот", objective = "Активируйте пульт управления \"Утилизатора Х6000\" и проверьте его возможности. Затем передайте результаты доктору псевдотехнических наук Вомице, находящемуся на испытательном полигоне в Пустоверти. Если возникнут проблемы, разберитесь с ними..", description = "Доктор псевдотехнических наук Вомиза к вашим услугам. Вот, возьми этот пульт управления. Активируй его и погоняй мой новоизобретенный \"Утилизатор Х6000\".\n\nТолько оставайся поблизости! Пульт связан с моей панелью управления, и если ты отойдешь слишком далеко, робот перестанет действовать.\n\nПопробуй все функции... Я буду смотреть и калибровать сервомоторы, основываясь на проведенных тобой испытаниях.", progress = "И что ты думаешь? Требуется еще доработка, ага?", completion = "Что ж, приятель, это было просто великолепно! Я бы сказал, что \"Утилизатор Х6000\" справился великолепно, невзирая на столь неуклюжее управление.\n\nХе-хе, не обижайся, я просто шучу. В конце концов, твои действия спасли Зону 52 и ракету Пустоты Х-52 от уготованной им судьбы!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10249] = {title = "Обратно к командующему!", objective = "Немедленно явитесь к ведущему ракетостроителю Фьюзеляжу в Зону 52 в Пустоверти!", description = "Я уверен, что ведущий ракетостроитель захочет перемолвиться с тобой парой слов.\n\nНа твоем месте я сразу же отправился бы в Зону 52, чтобы поговорить с ним!", progress = nil, completion = "Выручалкин! Или мне следует сказать - младший лаборант 1-й степени Выручалкин?! Но шутки в сторону. Даже повышение на две степени будет слишком маленькой наградой за твои деяния. Я собираюсь сделать тебя своим первым офицером!\n\nТы спас нас всех, более того - ракету Х-52! Я мог бы расцеловать тебя... но не буду. \n\nВместо этого позволь мне одарить тебя в знак признательности от имени всей Зоны 52! Вот твоя награда!", rewards = "Поножи пилота X-52Шлем лаборанта X-52Штаны охранника Зоны 52Вы получите:\n\nРеактивный шлем X-52"}
MultiLanguageQuestData['ru'][10250] = {title = "Кровавая месть", objective = "Подуйте в боевой рог Непреклонных рядом со знаменем Альянса. Убейте Уртрака и возвращайтесь к Альтену Историку на Заставу Хребтолома.", description = "К востоку отсюда стоит разрушенная осадная башня Альянса. Мародеры давно растащили по кусочку все, что там осталось. Когда-то давно в этой башне простились с жизнью многие солдаты Альянса, а их знамя было захвачено Уртраком, командиром орков Скверны.\n\nПодуй в боевой рог Непреклонных рядом со знаменем Альянса. Это привлечет внимание Уртрака. Но рог призовет и души тех, кто пал здесь в сражении много лет назад.", progress = "Ты протрубил в рог, найденный в осадной башне? Это нужно сделать как можно скорее. Кто знает, когда еще Непреклонные пригодятся Траллмару.", completion = "Я рад слышать, что Непреклонные присоединились к тебе в битве. Я предполагал, что они придут на звук своего старого боевого рога, но не был в этом уверен. Возможно, мы дали им насытиться местью, которой они так жаждали.\n\nО твоей победе над Уртраком необходимо доложить командиру Хогарту в оружейную экспедиции. Он должен знать, чем ты рисковал ради нас.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10251] = {title = "Великий замысел господина?", objective = "Найдите Нитрина Сведущего в Заброшенной оружейной в Награнде.", description = "Вчера вечером у нас побывала парочка дренеев. Они как-то прознали, что у нас есть эта книга, и великодушно предложили избавить нас от такой обузы.\n\nНе в наших обычаях интересоваться планами чужаков, но тот, что помоложе, все повторял что-то про \"великий замысел господина\", что бы это ни значило.\n\nКогда мне платят, я вопросов не задаю. Они дали нам кучу золота, а мы им – книгу.\n\nОн говорил, они живут где-то в Награнде, в старой заброшенной оружейной, к северу от Телаара.", progress = nil, completion = "Я видел, к чему все идет, но предпочитал не обращать внимания.\n\nС каждым днем влияние Легиона все усиливается... даже в наших краях.\n\nЕсли бы я знал... Если бы я знал, что мой мальчик свяжется с демонами... Они пообещали ему силу и дали вкусить ее... Этого ему хватило.\n\nИ вот, книга утеряна для нас. Теперь она у Левиксуса. Об его планах известно только мне и его темному владыке.\n\nО странник, я не знаю, следуешь ли ты путем добра, но того, кто служит демонам, надо остановить любой ценой!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10252] = {title = "Посмотри в глаза мертвым", objective = "Принесите Нитрину из Заброшенной оружейной Награнда 1 глаз горного гронна, 1 безупречный клюв большого вертуха и 1 сальник старого копытня.", description = "Сбылись наши самые худшие опасения. Левиксус стоит над руинами Аукиндона и читает книгу мертвых. Он призывает умерших по именам, и с помощью древнего демонического ритуала подчиняет своей воле их злосчастные души. Если его не остановить, он призовет под свои знамена души всех, кто когда-либо умер в Аукиндоне!\n\nНо... Сначала тебе нужно подготовиться. Невозможно сражаться с тем, кого ты не в состоянии даже увидеть.\n\n<Нитрин дает вам пергамент.>\n\nДостань необходимые компоненты, чтобы я смог изготовить нужное снадобье. Оно раскроет твой разум и позволит узреть мир духов.", progress = "Армия Левиксуса разрастается с каждой секундой. Тебе следует торопиться!", completion = "Странник... Я не сказал тебе всей правды. Как только ты выпьешь это зелье, ты отныне и навсегда обретешь способность видеть мир духов. Это питье давали жрецам мертвых Аукиндона во время инициации. Многие после этого сходили с ума... Видеть мертвых – это тяжелое испытание для живущего.\n\n&lt;Нитрин подносит зелье к вашим губам.&gt;\n\nТы не боишься?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10253] = {title = "Левиксус Призыватель Душ", objective = "Убейте Левиксуса и заберите у него Книгу Мертвых.\n\nОтнесите Книгу Рамдору Безумному, который находится неподалеку от входа в Аукенайские гробницы в Аукиндоне.\n\nВы ведь с ним об этом договаривались, помните?", description = "А теперь ступай, <имя>. Ты найдешь Левиксуса на самом верху руин Аукиндона. Лучше всего заходить с юга Костяных пустошей. Левиксус поднял целый смерч душ и стоит в самом его центре.\n\nУбей его и забери книгу мертвых. И как только эта проклятая книга окажется у тебя, немедленно уничтожь ее! Уничтожь, чтобы подобное зверство никогда больше не повторилось.", progress = "Кто ты, и что тебе надо? А-а... Я тебя помню...", completion = "Старый дреней велел тебе уничтожить книгу. Так почему ты этого не сделал, а?\n\n&lt;Рамдор бросает на вас мрачный взгляд.&gt;\n\nА-а... Вот в чем дело. Может быть, ты и жадный, зато честный.\n\nЯ же, надо сказать... Я солгал, чтобы завладеть этой книгой. Понятия не имею, где эти бедные духи хранят свои сокровища, а если знал бы – все равно не сказал. Впрочем, у меня найдется кое-что для тебя. Возможно, кое-что весьма стоящее. Не бойся, ты не останешься без награды.\n\nКстати, добро пожаловать в нашу компанию!\n\n&lt;Рамдор указывает на духов.&gt;", rewards = "Убор праведного неистовстваНаголенники землеломаПоножи Третьей монетыПерчатки раскаянияВы получите:\n\n"}
MultiLanguageQuestData['ru'][10254] = {title = "Командир армии Данат", objective = "Доставьте по приказу маршала Исилдора донесение командиру армии Данату Троллебою в Оплот Чести.", description = "<Маршал Исилдор сплевывает в пыль.>\n\nЧто ж, пришло время платить по счетам. Немедленно отправляйся в крепость с докладом к командиру армии Данату Троллебою.\n\n<Маршал Исилдор отдает вам честь.>\n\nВо имя Альянса!", progress = nil, completion = "Добро пожаловать, брат. Я рад тебя видеть. Мое имя Данат, я предводитель Сынов Лотара и командир армии этой крепости.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10255] = {title = "Проверка противоядия", objective = "Введите кенарийское противоядие крупному зловепрю и пронаблюдайте за результатом. После проведения эксперимента возвращайтесь к Тие Рыжей Гриве на Кенарийскую заставу на полуострове Адского Пламени.", description = "Я думаю, мы можем использовать эту кровь для создания противоядия. Не смотри на меня так, будто я сошла с ума!\n\nЭто очень распространено в природе. Часто противоядие является производным от яда. Именно это я сейчас и попытаюсь проверить.\n\nЕсли мы освободим вепрей от демонического влияния, это снизит их агрессивность и, возможно, поможет нам понять, как помочь остальным животным.", progress = "Как прошел эксперимент?", completion = "*Глаза Тии расширяются по мере того, как вы описываете результаты эксперимента*\n\nНо как это могло случиться? Я уверена, что приготовила противоядие правильно!\n\nОно срабатывало и с паучьим, и со змеиным ядом, почему же на этот раз дало сбой? Возможно, все дело в специфике Запределья, Душавдушу. Нужно сообщить о результатах всем моим соратникам.", rewards = "Посох кенарийского естествоиспытателяЯрость Клыка УжасаРежущий клинок зловепряВы получите:\n\n"}
MultiLanguageQuestData['ru'][10256] = {title = "Найти Хранителя Ключей", objective = "Выследите Камнегора и заберите у него кристальное средоточие. Вернитесь к Аметистовой башне и используйте кристальное средоточие Камнегора поблизости от шара верховного мага Варгота для того, чтобы обнаружить, у кого хранятся ключи от проклятия башни.", description = "Сейчас, несколько запоздало, я полагаю, что должен был понимать, насколько сильна магия Кель'таса. Он всегда был талантливым магом, но я никогда не видел мощи, подобной той, которую он применил во время нападения на эту башню. \n\nОграждающая магия не дает мне рассмотреть силу, поддерживающую ее, однако тебе эта ограда не будет препятствием.\n\nОднако тебе требуется фокусировка. По равнинам к западу от манагорна Даро бродит великан-кристаллоноситель по имени Камнегор. Один из его кристаллов послужит превосходным средством сосредоточения взгляда.", progress = "Что открывается твоему взору?", completion = "&lt;Вы описываете результат наблюдения.&gt;\n\nГоворишь, командир Сараннис? Хмм...\n\nОна одна из советников Кель'таса, но определенно не маг. Я помню ее – она была среди тех, кто напал на деревню Кирин'Вар. Думаю, твое прозрение оказалось верным, Акул. Она не поддерживает проклятье сама, но хранит ключи от него.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][10257] = {title = "Захват краеугольного камня", objective = "Проникните в Ботанику в Крепости Бурь и заберите ключ у командира Сараннис. Отнесите ключ верховному магу Варготу в Аметистовую башню.", description = "Меня не удивляет, что Кель'тас отдал ключ от тюрьмы в руки такой, как командир Сараннис. Принц Кель'тас горд, но он не дурак.\n\nДля того чтобы уничтожить это проклятье раз и навсегда, тебе следует войти в Крепость Бурь и забрать ключ.\n\nТолько после того, как ключ будет уничтожен, я вновь обрету свободу.", progress = "Тебе удалось добыть краеугольный камень?", completion = "&lt;Когда вы протягиваете верховному магу Ключ-камень, глаза мага озаряются светом.&gt;\n\nВеликолепно! Хотя я видел немногое из того, что случилось с Фаралоном, я не уверен, что хочу оказаться снаружи. Но это лучше, чем быть запертым здесь до конца дней своих.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10258] = {title = "Честь Павших", objective = "Явитесь к командиру Хогарду, который находится в оружейной экспедиции.", description = "Командир Оружейной Хогард находится в восточной башне. Пойди, расскажи ему о победе над Уртраком. Может, он будет к тебе благосклонен. Хотя не исключаю, что попытается пожрать твою душу. С такими духами, как этот, трудно угадать наверняка.\n\nНепреклонные так и не согласились сотрудничать с нами, так что, скорее всего, попытаются убить тебя. Будь <осторожен/осторожна>, <имя>.", progress = nil, completion = "Когда-то давно мы потерпели поражение от орков Скверны. Убив Уртрака, ты вернул нам хотя бы часть утраченной славы.\n\nПрими в награду это оружие. Обнажи его, когда будешь сражаться с нашими злейшими врагами, и тогда те из нас, кто свободен от проклятья, придут тебе на помощь.\n\nПока ты еще не ушел, – погибшие во время осады тоже хотят поблагодарить тебя.", rewards = "Клинок непреклонныхЖезл непреклонныхВы получите:\n\n"}
MultiLanguageQuestData['ru'][10259] = {title = "Битва в Проломе", objective = "Убейте 6 вторгшихся стражей Скверны и затем вернитесь к посланнику ордена Серебряного Рассвета Праудвелл.", description = "В портале неустанно кипит бой! Серебряный Рассвет отчаянно сражается - и если мы проиграем, то демонический огонь уже не остановить.\n\nПомоги нам, <имя>. Войди в пролом и протяни руку помощи нашим братьям и сестрам. Помоги остановить этот темный прилив! Серебряному Рассвету - и всему миру - нужна твоя сила!", progress = nil, completion = "Благодарю тебя, Нигилум. Среди хаоса битвы герои подобны яркому свету во тьме. И твой свет воистину сияет!", rewards = "Вы получите:\n\nГербовая накидка Защитника"}
MultiLanguageQuestData['ru'][10260] = {title = "Пустолог Медноклеппер", objective = "Поговорите с Пустологом Медноклеппером у моста, ведущего от Пустоверти к Острогорью.Твой путь, должно быть, пролегал по главному мосту, ведущему в Пустоверть от Острогорья. Не довелось ли тебе увидеть там пустолога Медноклеппера, работающего над всяким дурацким оборудованием?\n\nСтранно... Я ожидал от него рапорта уже некоторое время назад. Должно быть, он забыл. Ты ведь знаешь, каковы эти \"ученые\". \n\nОтправляйся обратно к мосту и найди пустолога. Не слушай никаких его объяснений, просто получи с него рапорт для меня.\n\nСпасибо!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Твой путь, должно быть, пролегал по главному мосту, ведущему в Пустоверть от Острогорья. Не довелось ли тебе увидеть там пустолога Медноклеппера, работающего над всяким дурацким оборудованием?\n\nСтранно... Я ожидал от него рапорта уже некоторое время назад. Должно быть, он забыл. Ты ведь знаешь, каковы эти \"ученые\". \n\nОтправляйся обратно к мосту и найди пустолога. Не слушай никаких его объяснений, просто получи с него рапорт для меня.\n\nСпасибо!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10261] = {title = "Разыскивается: аннигиляторный сервопривод!", objective = "Заберите аннигиляторный сервопривод и доставьте его Папаше Колесуну в Зону 52 Пустоверти.", description = "РАЗЫСКИВАЕТСЯ: 1 аннигиляторный сервопривод для замены сломанного в моем спектральном анализаторе Длинношеего.\n\nТы и твои друзья могут проверить, нет ли запасных сервоприводов у эльфов крови в манагорне Б'наар к западу отсюда. Кажется, у них валялись там несколько волшебных уничтожителей. \n\nПожалуйста, доставь сервопривод в хорошем состоянии Папаше Колесуну в Зону 52.", progress = "Надеюсь, ты здесь из-за того объявления о розыске, которое я вывесил!", completion = "Ура! Ты знаешь, как трудно раздобыть эти штуки? Тут у нас не существует регулярной поставки запчастей.\n\nВот что я скажу – в качестве платы можешь взять что-нибудь из моей коробки с хламом. Я уверен, там ты найдешь для себя что-нибудь полезное. А если нет, то продай.\n\nНу ладно, давай, я заберу у тебя эту штуку и встрою в свой спектральный анализатор Длинношеего прежде, чем неисправный сервопривод взорвется!", rewards = "Красная заостренная шляпаЭкзотические шипастые наплечникиУтерянная бригантина почитателяВы получите:\n\n"}
MultiLanguageQuestData['ru'][10262] = {title = "Груда духов Астрала", objective = "Соберите 10 знаков отличия братства Заксис и принесите их ловчему Пустоты Кай'джи, находящемуся в Зоне 52 в Пустоверти.", description = "Есть еще одно дело, в котором мне нужна твоя помощь.\n\nГруппа духов Астрала, известная как Заксис, разорвала свои отношения с Консорциумом и занимается бизнесом в собственных интересах. Они даже заключают сделки с эльфами крови из Ярости Солнца. Этого нельзя допустить!\n\nЯ проник в их отряд в Груде на юге отсюда. Но после того, как я убил их вожака, мне пришлось бежать сюда, в Зону 52.\n\n<класс>, отправляйся туда и принеси мне их знаки отличия. Конечно же, не все они носят такие знаки, поскольку эти типы очень трусливы.", progress = "Дело сделано? Удалось ли тебе стереть с лица Запределья этих негодяев из братства Заксис и достать их знаки отличия?", completion = "Эти знаки отличия – хорошее начало.\n\nК несчастью, за время твоего пребывания в Груде еще один мой агент в Заксис сообщил мне, что астральный налетчик Несаад все еще жив!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10263] = {title = "Содействие Консорциуму", objective = "Поговорите с ловчим Пустоты Кай'джи в Зоне 52 в Пустоверти.", description = "Наару города Шаттрат пытаются донести до Консорциума свою точку зрения.\n\nХорошо еще, что деловые отношения между духами Астрала и эльфами крови здесь, в Пустоверти, в последнее время разладились.\n\nВ городе находится представитель Консорциума ловчий Пустоты Кай'джи, который недавно попал в неприятности по вине шайки астральных духов-изменников. Как представитель Алдоров, я хотел бы попросить тебя помогать ему во всем, в чем только можно.", progress = nil, completion = "Привет тебе, |3-6(человек).\n\nНе возьмешься ли ты за довольно важную миссию по изъятию имущества?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10264] = {title = "Содействие Консорциуму", objective = "Поговорите с ловчим Пустоты Кай'джи в Зоне 52 в Пустоверти.", description = "Наару города Шаттрат пытаются донести до Консорциума свою точку зрения.\n\nХорошо еще, что деловые отношения между эфириалами и эльфами крови здесь, в Пустоверти, в последнее время разладились.\n\nВ городе находится представитель Консорциума ловчий Пустоты Кай'джи, который недавно попал в неприятности по вине шайки астральных духов-изменников. Как представитель Альдора, я хотел бы попросить тебя помочь ему во всем, в чем только можно.", progress = nil, completion = "Привет тебе, |3-6(ночной эльф).\n\nНе возьмешься ли ты за довольно важную миссию по изъятию имущества?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10265] = {title = "Добыча артефакта для Консорциума", objective = "Заполучите кристаллический артефакт Арклона и верните его ловчему Пустоты Кай'джи, находящемуся в Зоне 52 в Пустоверти.", description = "Наш предводитель, принц нексуса Харамад, поставил передо мной задачу: добыть кристаллический артефакт из руин Арклона на юго-востоке отсюда.\n\nЭто старинные руины дренейских построек. К несчастью как для меня, так и для здешних гоблинов, Пылающий Легион тоже решил заняться там раскопками.\n\nЕсли хочешь помочь мне, отправляйся в руины и забери кристаллический артефакт у повелителя ужаса по имени Пентатарон.", progress = "У меня такое впечатление, что принц ищет вполне определенный кристалл, но какой именно?\n\nУдалось ли тебе забрать артефакт у повелителя Ужаса?", completion = "Дай-ка я взгляну.\n\nХмм, не похоже, что в нем есть что-то особенное. Я сомневаюсь, что это именно то, что нужно, хотя, если судить по твоему описанию действий Пылающего Легиона в руинах, они тоже ищут нечто особенное.\n\nБудем надеяться, что предмет их поисков – не тот кристалл, который так нужен принцу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10266] = {title = "Запрос о содействии", objective = "Найдите Гаруджа и предложите ему свои услуги. Он находится на заставе внутри заповедника \"Срединные земли\" в Пустоверти.", description = "Во время твоего пребывания в руинах Арклона я получил запрос о содействии от одного из наших представителей, отправленных на задание. Похоже, у Консорциума возникли затруднения с изъятием у эльфов крови собственности, за которую те отказываются платить. \n\nПожалуйста, отправляйся на восток от Зоны 52 и по мосту перейди на следующий остров. Ты найдешь моего коллегу Гаруджа на заставе внутри заповедника \"Срединные земли\" в Пустоверти.", progress = nil, completion = "Да, это правда. Эльфы крови отказались платить за еще одну партию товаров, только что доставленную им. \n\nКак сообщил тебе ловчий Пустоты Кай'джи, я надеюсь, что ты сможешь помочь мне в этом вопросе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10267] = {title = "Изъятие по праву", objective = "Заберите 10 ящиков с геодезическим снаряжением и верните их Гаруджу, находящемуся на заставе внутри заповедника \"Срединные земли\" в Пустоверти.", description = "Похоже, нашим деловым отношениям с эльфами крови наступает конец. Несколько дней назад в манагорне Даро им была передана большая партия геодезического снаряжения. Они отказались платить за нее.\n\n<имя>, я хотел бы попросить тебя нанести визит эльфам крови в манагорн Даро. Похоже, у них там какие-то неприятности в связи с нашествием мана-тварей, так что воспользуйся этим положением. \n\nМне все равно, что случится с ними, но мне очень хотелось бы вернуть назад нашу собственность.", progress = "Удалось ли тебе изъять геодезическое снаряжение, за которое нам задолжали эльфы крови?", completion = "Ну, лично я рад, что это маленькое дельце уже улажено. Припомнить не могу, когда еще Консорциуму приходилось иметь дело с такими невоспитанными и вероломными существами.\n\nА вот тебе, Менгиле, похоже, можно доверять. Быть может, ты не против оказать мне еще одну услугу?", rewards = "Шляпа Срединных земельПоножи заповедникаИзносостойкая экспедиционная обувьВы получите:\n\n"}
MultiLanguageQuestData['ru'][10268] = {title = "Аудиенция у принца", objective = "Доставьте геодезическое снаряжение к проекции принца нексуса Харамада в Штормовую Вершину в Пустоверти.", description = "Принц нексуса Харамад сообщил мне, что он заинтересован в том, чтобы его имущество немедленно было возвращено ему лично. Я буду очень рад, если ты возьмешься доставить ему это имущество.\n\nЭто великая честь – получить аудиенцию у принца нексуса, и я уверен, что он будет чрезвычайно заинтересован в том, чтобы услышать повествование о твоих приключениях здесь, в Пустоверти.\n\nЕго залу можно отыскать на верхнем уровне Штормовой Вершины к северу отсюда. Он часто присутствует там в виде голографической проекции, к которой ты можешь обратиться.", progress = "Подойди.", completion = "Приветствую тебя в Штормовой Вершине, |3-6(Охотник). Наслаждайся гостеприимством Консорциума.\n\nСнаряжение ты можешь положить где угодно. Подозреваю, что довольно скоро ты вновь заберешь его.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10269] = {title = "Триангуляция: точка первая", objective = "Используйте триангуляционный прибор, чтобы найти путь к первой точке триангуляции. Как только найдете точку, сообщите ее местонахождение дельцу Хаззину, находящемуся на заставе Протектората на острове манагорна Ультрис в Пустоверти.", description = "Есть еще одна причина для изъятия геодезического снаряжения. Это кристалл из дренейской легенды, который очень важен для меня.\n\nГоворят, что кристалл дарует своему носителю сверхъестественную силу! Но существует опасность, что его добудут другие - а именно Пылающий Легион.\n\n<имя>, возьми это снаряжение и используй его, чтобы найти первую точку триангуляции. Мы знаем, что она должна находиться где-то к востоку отсюда поблизости от манагорна Ультрис.\n\nПосле этого отметься у моего агента, дельца Хаззина, на острове манагорна Ультрис.", progress = "Привет тебе, путешественник. Тебе нужно приобрести у Хаззина какие-то товары?", completion = "&lt;Делец Хаззин понижает голос до шепота.&gt;\n\nА, я знаю о твоей миссии. Она очень важна для принца нексуса Харамада!\n\nТеперь, когда мы знаем местонахождение первой точки триангуляции, тебе следует побыстрее отыскать вторую!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10270] = {title = "Нескромное предложение", objective = "Найдите аккумулятор для телепортатора и отнесите его к площадке астрального телепорта на Небесной гряде. Активируйте площадку и отдайте аккумулятор проекции торговца ветром Марида, чтобы он мог установить его.", description = "Просто взглянув на твое лицо, <раса>, я могу сказать, что ты ценишь хорошую выгоду.\n\nЯ составил себе репутацию как торговец экзотическими товарами, и сейчас я намереваюсь начать новое предприятие.\n\nМне нужен надежный субподрядчик для доставки товаров с Небесной гряды.\n\nСначала тебе нужно подзарядить площадку телепорта. Запасной силовой пакет есть у входа в шахту Зеон, расположенного на южной стороне манагорна Ультрис. Там действует Протекторат, так что тебе, возможно, удастся следовать их индикаторам ради собственных целей.", progress = "Как насчет того, чтобы обсудить деловые вопросы, Выручалкин?", completion = "Эта энергетическая ячейка подойдет для наших целей. Как только начнется оборот денег, мы дополнительно улучшим ее.\n\nНу, довольно. Каждый момент, проведенный за обсуждением, приводит к потере прибыли.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10271] = {title = "Деловая активность", objective = "Отправляйтесь на Небесную гряду и зарядите собиратель сущности при помощи молодых или старых драконов Пустоты, а затем возвращайтесь в зону площадки астрального телепорта.", description = "Как тебе, несомненно, удалось заметить, этот регион кишит драконами Пустоты на разных стадиях роста. Все драконы Пустоты, молодые и старые, содержат эссенцию, которая очень нужна К... одному моему клиенту.\n\nМало кто желает рисковать жизнью для сбора этой эссенции, так что это дело зарезервировано за нами. Можешь начать с любого дракона поблизости, лишь бы поставки начались немедленно – это очень важно. Возвращайся, как только добудешь первую партию.", progress = "Я уверен, у тебя множество вопросов, но все ответы будут получены в должное время.", completion = "И подумать только, этот коварный дух Астрала собирался продавать эту эссенцию эльфам Крови, словно какие-нибудь сласти...", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][10272] = {title = "Многообещающее начало", objective = "Соберите 15 яиц драконидов Пустоты, затем возвращайтесь к Тири и Джораду на Небесную гряду.", description = "Мы здесь для того, чтобы расследовать, правдивы ли слухи о странной породе драконов, которые, возможно, являются потомками самого Смертокрыла. Однако это явно не обычные черные драконы.\n\nМы узнаем больше, если у нас будет возможность изучить их яйца. Их ненависть к моему племени велика, так что я не могу подобраться достаточно близко, чтобы собрать яйца. Ты не согласишься мне помочь?", progress = "Удалось ли тебе набрать яиц?", completion = "Это прекрасно подойдет, Выручалкин. Спасибо за помощь нам.\n\nОднако прежде, чем мы сможем продолжить, нам нужно обратиться к другому вопросу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10273] = {title = "Пустые хлопоты", objective = "Поговорите с торговцем Ветром Маридом и выманите его из торгового поста. Покончите с ним, затем вернитесь к Тири и Джораду на Небесную гряду.", description = "Твой бывший наниматель, торговец ветром Марид, должно быть, плюется оттого, что ты теперь помогаешь нам. Благодаря своей проекции я вижу его странников хаоса, шныряющих по этому региону и надеющихся выследить нас.\n\nДо сих пор нам удавалось ускользать от них, но с Маридом нужно что-то делать, прежде чем проблема станет еще более серьезной.\n\nЕсли твои впечатления относительно Марида верны, он сделает почти все, чтобы обезопасить поставки своего товара. Возвращайся к нему и сообщи о своей готовности заключить сделку. Вымани его и убей.", progress = nil, completion = "Теперь, когда с этим назойливым эфириалом покончено, мы можем сосредоточить наши усилия на исследовании драконов Пустоты. У меня была возможность изучить их яйца, и я сделала несколько открытий.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10274] = {title = "Безопасность Небесной гряды", objective = "Используйте вызов синих драконов, чтобы вызвать на бой Вераку, живущего на южном склоне Небесной гряды. Победите его и возвращайтесь к Тири и Джораду, ожидающим на Небесной гряде.", description = "Драконы Пустоты отличаются тем же свирепым характером, что и их предки – черные драконы, но есть в них что-то непостижимое. Они быстро созревают и взрослеют благодаря той странной энергии, которая создала их вид во время уничтожения Дренора.\n\nМне еще очень многое нужно о них узнать, но я полагаю, что эта энергия может быть использована моим собственным родом. Если бы мы сместили вожака этих драконов, Вераку, показав свое превосходство, мы смогли бы подчинить своей власти всех остальных представителей их вида.", progress = "Удалось ли тебе вызвать на бой Вераку и победить его?", completion = "Хорошая работа, Выручалкин, поистине хорошая. Сначала драконы Пустоты не примут в свою среду синего дракона, однако со временем, при жесткой демонстрации моей власти, они придут под мое крыло. Они разъединены, разбросаны, у них нет решительного лидера. Мы должны быть бдительными, чтобы не дать им пасть под натиском злых сил. Необходимо постоянно следить за ними.", rewards = "Блистающие лазурные сапогиЭполеты драконьего гребняНаручи с золотыми сцепкамиВороненые стальные рукавицыВы получите:\n\n"}
MultiLanguageQuestData['ru'][10275] = {title = "Триангуляция: точка вторая", objective = "Используйте триангуляционный прибор, чтобы найти путь ко второй точке триангуляции. Как только найдете точку, сообщите ее местонахождение торговцу ветром Тулуману, находящемуся в лагере Тулумана, по другую сторону моста, ведущего от острова манагорна Ара в Пустоверти.", description = "Я перенастроил триангуляционный прибор, используя те сведения, которые тебе удалось добыть при поиске первой точки. Воспользуйся этим прибором точно так же, как и в первый раз, чтобы найти вторую точку.\n\nВсе, что я могу тебе сказать – это то, что вторая точка находится где-то далеко к западу отсюда. \n\nКак только засечешь ее, поговори с торговцем ветром Тулуманом – это еще один агент принца нексуса. Он изображает торговца оружием в маленьком торговом посту около моста, ведущего на тот остров, где размещается манагорн Ара.", progress = "Желаешь что-нибудь купить или продать?", completion = "Просто прекрасно. Принц будет доволен!\n\nТеперь у нас есть вторая точка, благодаря чему мы сможем найти третью, а потом – приблизительное местоположение кристалла!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10276] = {title = "Полный треугольник", objective = "Заберите кристалл Ата'мала и передайте его проекции принца нексуса Харамада, находящейся в Штормовой Вершине в Пустоверти.", description = "Если брать в расчет данные с первой и второй точки, я уверен: кристалл находится на вершине руин Фаралона к северо-востоку отсюда.\n\nК несчастью, данные указывают, что кристалл движется, то есть он уже обнаружен и, вполне вероятно, обнаружен Пылающим Легионом!\n\nНа всякий случай я советую тебе взять с собой друзей.\n\nУбей демона, у которого находится этот кристалл, и возвращайся к принцу нексуса Харамаду.", progress = "Вновь приветствую тебя. Как продвигается поиск кристалла?", completion = "Это превзошло мои самые смелые ожидания, я не думал, что тебе удастся забрать этот кристалл!\n\nИ ты отдаешь его мне? Ты понимаешь, какую силу он таит?\n\nТвое бескорыстие поистине впечатляюще и непревзойденно, Менгиле! Твое поведение заставляет меня лучше думать о разумных существах.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10277] = {title = "Пещеры Времени", objective = "Андорму попросил вас пройти по пещерам вместе с хранительницей времени.", description = "Приветствую тебя, <имя>. Пожалуйста, следуй за хранительницей. Она покажет тебе пещеры, и ты... хотя бы начнешь понимать, что происходит.", progress = "Возвращайся не раньше, чем начнешь понимать, как здесь все устроено.", completion = "Надеюсь, теперь ты составил себе представление о том, чего от тебя ожидают.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10278] = {title = "Астральные провалы", objective = "Используйте нестабильный генератор астральных провалов на Искривленных полях. Соберите три горсти пыли Пустоты с нестабильных демонов Бездны и возвращайтесь к Огафу Безумному на заставу Хребтолома.", description = "Когда-то давно я бродил по Запределью, ища истину среди пустоты. А теперь я стар и слаб. Ты мне поможешь?\n\nЯ должен изучить секреты демонов Бездны. Отыщи Искривленные поля к западу отсюда. Еще западнее оружейной экспедиции лежит темное место на самом краю бездны, где истончаются время и пространство. Запусти там мой нестабильный генератор астральных провалов и создай провал. Собери пыль Пустоты с тех созданий, которые появятся.", progress = "Ты догадался, как запустить мой прибор? Я думаю, генератор заработает, если расположить его поближе к бездне.", completion = "Невероятно. Тебе удалось прикоснуться к самой пустоте! Джонниди, ты спас дело всей моей жизни. Но, если ты и правда хочешь помочь мне, мы должны сделать еще многое и многое.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10279] = {title = "Логово господина", objective = "Поговорите с Андорму в пещерах Времени.", description = "А, <имя>. Мы тебя ждали. Сейчас один из моих братьев доставит тебя к нашему господину. Он ожидает тебя внизу...", progress = nil, completion = "Мы должны подготовить тебя к грядущим сражениям...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10280] = {title = "Специальный груз в город Шаттрат", objective = "Передайте кристалл Ата'мала А'далу на террасе Света в городе Шаттрат.", description = "Я всегда держу свое слово, <имя>. Тебе поистине удалось произвести на меня впечатление.\n\nЯ намереваюсь дать тебе кристалл Ата'мала для передачи наару. Я прошу тебя доставить его им – твой героизм делает это вполне возможным.\n\nМожешь использовать мой личный телепорт, чтобы переправиться прямо в город Шаттрат. Просто пройди через него, и окажешься там.\n\nОтдай кристалл наару по имени А'дал, обитающему на террасе Света. Пусть несут тебя попутные ветры торговли!", progress = "<Музыкальный перезвон речи наару наполняет ваш разум.>\n\nЯ чувствую, что у тебя с собой вещь великой силы, |3-6(нежить). Что ты принес мне?", completion = "Тебе удалось обрести Песню Духа! Это кристалл Ата'мала, который пророк Велен оставил на сохранение своему народу, прежде чем отправиться в свою злосчастную миссию в Экзодар.\n\nКак ни странно, он не предвидел, что кристалл попадет в руки Пылающего Легиона, пусть и на короткое время.\n\nА может быть, и нет? Может быть, он предвидел все это и оставил кристалл здесь, чтобы ты мог забрать его и доставить ко мне?\n\nЯ чувствую, что истина именно такова. Поистине велик твой героизм, Менгиле!", rewards = "Штаны нааруШаттратские поножиБригантина А'далаСледующее заклинание будет наложено на вас:\n\nБлагословение А'дала\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][10281] = {title = "Формальное представление", objective = "Найдите Тири на северной оконечности Небесной гряды и поговорите с ней.", description = "Приветствую тебя, <имя>. Не надо тревожиться. Это лишь проекция моей нынешней формы. Это единственный способ, при котором я и мой товарищ можем нести стражу, ничем не выдав себя.\n\nДух Астрала Марид, который беседовал с тобой - немногим лучше, нежели обманщик под личиной законопослушного торговца. Может быть, ты подумаешь о том, чтобы работать на меня, а не на него? Моя цель здесь - побольше узнать о необычном виде драконов, обитающих в этих горах. Встреться со мной на северной оконечности этой горной цепи, и мы обсудим этот вопрос.", progress = nil, completion = "Мое имя Тиригоса из рода Малигоса, но большинство называют меня Тири. Мой товарищ – паладин Джорад Мейс.\n\nСлухи об этих странных драконах уже распространились достаточно широко, и я боюсь, что очень многие поспешат воспользоваться этим ради выгоды, не осознавая истинной природы того, с чем имеют дело. С твоей помощью мы надеемся понять суть этих созданий, прежде чем другие обнаружат их присутствие.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10282] = {title = "Старый Хилсбрад", objective = "Отправьтесь по тропе времени в старый Хилсбрад и поговорите с Эрозионом.", description = "Дорога времени, лежащая к западу, приведет тебя в прошлое Хилсбрада – на семь лет назад, если быть точным.\n\nНекие странные силы пытаются предотвратить побег Тралла из крепости Дарнхольд. Они хотят, чтобы он остался там навсегда.\n\nЕсли Траллу не удастся вырваться на свободу, настоящее этого мира непоправимо изменится.\n\nСобери отряд таких же, как ты, искателей приключений и отправляйся в старый Хилсбрад по тропе времени. Там тебя будут ждать двое наших агентов.\n\nКогда прибудешь в Хилсбрад, обязательно поговори с Эрозионом.", progress = nil, completion = "То, чего мы больше всего боялись, может случиться уже очень скоро. Силы, которые вмешиваются в ход времени, – это новый клан драконов, что именуют себя драконами Бесконечности. Мы не знаем, откуда они появились и почему они разрушают наши линии времени.\n\nНа этом участке времени они похитили Тарету Фокстон, дочь Таммиса Фокстона. Он служит секретарем у Аделаса Блэкмура, правителя Дарнхольда и надзирателя лагерей для военнопленных в Азероте.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10283] = {title = "План Тареты", objective = "Проберитесь в крепость Дарнхольд и заложите пять зажигательных бомб возле бочек внутри каждого из бараков на выселках. Используйте упаковку зажигательных бомб, полученных от Эрозиона.\n\nПосле того как подожжете бараки, разыщите Тралла в подземной темнице.", description = "Только благодаря Тарете Тралл сумел выжить. Она воспитала его и сделала тем, кто он есть.\n\nИменно Тарета придумала первоначальный план, как помочь Траллу бежать из Дарнхольда.\n\nНо драконы Бесконечности захватили ее и сейчас держат в плену в Мельнице Таррен. Без нашей помощи Траллу вряд ли удастся сбежать. Я дам тебе зажигательные бомбы: подожги ими бараки на выселках в Дарнхольде. Потом отыщи юного Тралла – его держат в подземной темнице.", progress = "Кто ты?", completion = "Тебя прислала Тарета? То есть теперь у нее новый план? Ну хорошо...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10284] = {title = "Побег из Дарнхольда", objective = "Когда вы будете готовы идти, сообщите об этом Траллу. Помогите ему бежать из крепости Дарнхольд, освободить Тарету и исполнить свое предназначение.\n\nПосле этого возвращайтесь к Эрозиону в Старый Хилсбрад.", description = "Ты видишь во мне только мальчишку, <чужак/незнакомка>, но у этого мальчишки есть свои сокровенные мечты. Я знаю, что нужно моему народу. В один прекрасный день он сбросит своих притеснителей и встанет с колен. Мы порвем свои цепи и выкуем новую Орду, закалив ее в пламени мятежа. Я обещаю тебе, <чужеземец/незнакомка>: если мы выйдем отсюда живыми, ты получишь щедрую награду за свой самоотверженный поступок. Я буду искать тебя... и непременно найду.\n\n<Тралл кивает.>\n\nКак только будешь <готов/готова> идти, дай мне знать.", progress = nil, completion = "Тебе удалось совершить невозможное, Выручалкин. К сожалению, юный вождь этого не запомнит. В его памяти должны остаться только те события, которые случились бы, не будь искажения линии времени... Андорму ждет тебя в логове нашего господина.", rewards = "Мантия вождяКасание буриТихие сапоги ЮжнобережьяКушак защитница Мельницы ТарренВы получите:\n\n"}
MultiLanguageQuestData['ru'][10285] = {title = "Возвращение к Андорму", objective = "Возвращайтесь к маленькому Андорму в Пещеры Времени.", description = "Эта линия времени восстановлена, и нападение драконов Бесконечности на Хилсбрад провалилось.\n\nНемедленно возвращайся к Андорму. Он ждет тебя в логове нашего господина.", progress = nil, completion = "Прими этот дар от бронзовых драконов. Он поможет тебе в путешествиях во времени.", rewards = "Мантия вождяКасание буриТихие сапоги ЮжнобережьяКушак защитница Мельницы ТарренВы получите:\n\n"}
MultiLanguageQuestData['ru'][10286] = {title = "Тайна Арелиона", objective = "Расспросите магистра Аледиса, которого в последний раз видели отправляющимся из Соколиного дозора в Зангартопь, по требованию магистра Каринды.", description = "Да этот дневник ничего общего не имеет с научными изысканиями! Арелион там в деталях описывает свои развлечения с одной молоденькой эльфийкой крови. <Видал/Видала> придурка?\n\nК сожалению, он не написал, кто же была эта потаскушка. У Арелиона был друг, Аледис. Найди его и выясни, с кем же это Арелион мог развлекаться.\n\nЯ видела, как Аледис отправлялся из Соколиного дозора в Зангартопь. Дорога в Зангартопь уходит от северного выхода из города.", progress = nil, completion = "Я все расскажу, |3-6(Охотник). Опусти оружие, у меня и так проблем хватает.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10287] = {title = "Кем оказалась любовница", objective = "Возвращайтесь к магистру Каринде в Соколиный Дозор, что на Полуострове Адского Пламени.", description = "Я друг Арелиона, но не собираюсь положить за него жизнь. Его любовницей была Виера Шепот Солнца.\n\nТеперь ступай, докладывайся этой гарпии, жене Арелиона. Ну узнает она, и что дальше?", progress = nil, completion = "Виера Шепот Солнца? Эта маленькая дрянь?\n\nНу я ей покажу, как переходить мне дорогу!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10288] = {title = "Прибытие в Запределье", objective = "Доставьте донесение Дарона Амишу Громовому Молоту по приказу командира Дарона у Темного портала на полуострове Адского Пламени.", description = "Чтобы долететь до Оплота Чести, тебе надо будет поговорить с Амишем Громовым Молотом, он находится в 30 шагах отсюда к югу. Когда прибудешь в Оплот, встреться с маршалом Исилдором. Я подготовил донесение, в котором подробно описал, что у нас происходит. Отдай донесение ему и доложи, что <готов/готова> к дальнейшему несению службы.\n\nЭто приказ. А теперь, <свободен/свободна>, солдат! Я не сомневаюсь, что ты страстно желаешь помогать нам в сражениях с демонами, но в Оплоте Чести ты <нужен/нужна> больше, чем здесь.", progress = "Я видел, что с тобой говорил Дарон. Должно быть, важное дело.", completion = "Донесение в Оплот Чести? Без проблем. Мой грифон доставит тебя туда в целости и сохранности.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10289] = {title = "Путешествие в Траллмар", objective = "Долетите на ветрокрыле Влагги Легкоперой в Траллмар. Доставьте донесение Ориона генералу Кракорку.", description = "Когда будешь <готов/готова>, я призову виверну, которая отнесет тебя в Траллмар. По прибытии передай донесение Ориона генералу Кракорку.\n\nЛок'тар огар, <имя>, удачи тебе.", progress = "Донесение Ориона? Давай сюда, живо!\n\n<Нахмурившись, генерал Кракорк просматривает изорванные бумаги.>\n\nПроклятье, именно этого мы и боялись! Ориона и его армию могут в любой момент отбросить!", completion = "Я соберу все доступные резервы и отправлю их к Темному порталу, на помощь Ориону. Легион не скоро забудет боевой клич Орды! Что касается тебя, Зябкин, то ты оказал Траллмару великую услугу. Я надеюсь, ты сможешь помочь нам и здесь... Если у тебя хватит ума остаться в живых, конечно же...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10290] = {title = "В поисках фаралита", objective = "Соберите 4 куска сырого фаралита и вернитесь к Зубену Элгенуби в Штормовую Вершину.", description = "К северо-востоку отсюда находится регион, именуемый Осколки Пустоты; его не было видно, когда эта земля была зеленой и цветущей. Среди скопления кристаллов, очутившихся на поверхности земли, мы обнаружили новый минерал, который назвали фаралитом, в честь прежнего имени этих земель.\n\nХотя нам удалось добыть лишь небольшое количество фаралита, он уже оказался востребован нашими клиентами. Наиболее высококачественный минерал содержится не в отложениях – его производят великаны, обитающие по всем Осколкам Пустоты. Я предлагаю тебе долю в доходах, если ты поможешь добыть высококачественный фаралит.", progress = "Я понимаю, что собирать фаралит очень опасно, но таковы обстоятельства. Торговец, не желающий рисковать, может попросту закрыть двери и тем самым уберечься от неприятностей.", completion = "О да! Именно то качество, на которое я надеялся. Можно не разбивать скопления кристаллов, если можно добыть минерал непосредственно от производителя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10291] = {title = "Донесение Назгрелу", objective = "Поговорите с Назгрелом по приказу генерала Кракорка из Траллмара.", description = "Наши воины не знают себе равных, но наши позиции в этих пустошах по-прежнему ненадежны. Доложи Назгрелу, что нам нужны еще агенты... вроде тебя. Если мы не сумеем отстоять здесь свои позиции, от нас не будет никакой пользы. А теперь ступай!", progress = nil, completion = "Мы уже потеряли в этих проклятых степях не одну сотню отважных солдат. Посылать туда новобранцев – все равно что телят на бойню.\n\n&lt;Назгрел сверкает суровым взглядом из-под волчьей маски.&gt;\n\nЕсли уж генерал Кракорк отправил тебя ко мне, значит, он что-то в тебе разглядел. Ну, что скажешь, Менгиле? Готов верой и правдой служить нашему вождю?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10292] = {title = "Больше энергии!", objective = "Зубен Элгенуби хочет, чтобы вы захватили 8 пушек Легиона и принесли их в Штормовую Вершину.", description = "В том, чтобы собирать драгоценный товар мелкими партиями, есть что-то своеобразное, похожее на надомное производство, однако на современном рынке такое производство не выдержит конкуренции.\n\nНет, нам нужен именно массовый способ добычи фаралита! Тогда его количество на рынке будет под нашим полным контролем.\n\nУ меня есть идея, но для ее выполнения потребуется источник мощной, сфокусированной энергии. Есть только одно место, где можно добыть столь мощный источник энергии. Отправляйся в лагеря Легиона к северу отсюда и \"позаимствуй\" несколько их пушек.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10293] = {title = "Попасть на главную жилу", objective = "Зубен Элгенуби, находящийся в Штормовой Вершине, хочет, чтобы вы добыли фаралитовую сердцевину.", description = "Теперь, когда у нас есть неплохой основной продукт, мы должны получить что-то более высокого качества. Фаралит, который мы собирали до сих пор, несомненно, хорош, но я знаю, что существует и лучший.\n\nНам нужно получить образец непосредственно от Скалсаара, патриарха фаралонских великанов! Ты можешь найти его среди других великанов в Осколках Пустоты. Из спины у него торчат огромные куски фаралита – именно этот минерал нам и нужен. Напади на этого великана и добудь из его тела фаралитовую сердцевину.", progress = "Тебе удалось остаться в живых – значит, или фаралитовая сердцевина при тебе, или ты передумал. Так то или другое?", completion = "Превосходно! Жду не дождусь, когда я смогу приступить к проверке.", rewards = "Плащ сотканной энергииВам дадут возможность выбрать одну из следующих наград:\n\nКольцо небесного камняЦепь из светящихся усиков\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10294] = {title = "Пустынный обрыв", objective = "Отправляйтесь на Пустынный обрыв и убейте существ, которые там обитают. Соберите 40 осколков душ Пустынного обрыва и возвращайтесь к Огафу Безумному на Заставу Хребтолома.", description = "Мне нужно усовершенствовать нестабильный генератор астральных провалов. Отнеси его на Пустынный обрыв, к востоку отсюда. По дороге лежит Зет'Гор, и лучше обогнуть этот оплот скверны. К востоку от Зет'Гора находится небольшой горный перевал. Именно там ты и найдешь Пустынный обрыв, жуткое место, приютившееся на самом краю бездны.\n\nУбей тварей, которые там обитают, и принеси мне осколки их душ. С их помощью мы улучшим мой нестабильный генератор и откроем портал в самые глубины бездны.", progress = "Ты уже вернулся с Пустынной Гряды? Достал осколки душ?", completion = "Отлично, теперь нестабильный генератор астральных провалов работает как надо. Остался только один, самый последний компонент. Скоро, скоро мы откроем провал в самые глубины Бездны.\n\nКто знает, что за существа пожалуют к нам оттуда? Менгиле, только подумай о могуществе, которое мы обретем.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10295] = {title = "Сила бездны", objective = "Убейте Барона Бездны Галаксиса и добудьте осколок его души. Принесите осколок души Огафу Безумному на Заставу Хребтолома.", description = "Наконец-то нестабильный генератор астральных провалов работает как надо. Теперь мы призовем истинного владыку Бездны, осколок души которого сможет поведать нам столько, что трудно даже представить.\n\nСтупай на юг Пустынного обрыва и запусти генератор рядом с камнями пустоты. Наблюдай за гроздью кристаллов рядом с границей бездны. Когда астральный провал сформируется, появится Барон Бездны Галаксис.\n\nУничтожь его и принеси осколок его души.", progress = "Ты убил Барона Бездны Галаксиса? Где осколок его души?", completion = "Ты спас работу всей моей жизни, Душавдушу.\n\nМеня называют безумцем и смеются надо мной, говорят, что я одержим Пустынной грядой и Полями искривления. Теперь, с этим осколком души, я открою все секреты демонов Бездны. Силы Бездны будут повиноваться мне!", rewards = "Жезл призывателя БездныПокров БездныВам дадут возможность выбрать одну из следующих наград:\n\nВенец изгнания\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10296] = {title = "Черные топи", objective = "Пройдите сквозь Пещеры времени до Черных топей времен открытия Темного портала и поговорите с Са'атом.", description = "Драконы Бесконечности, похоже, утратили свою хваленую проницательность. Они собираются уничтожить Хранителя Медива, чтобы он не открыл Темный портал. На первый взгляд, это могло бы усилить Альянс, но на самом деле приведет к катастрофе и гибели этого мира.\n\nТебе нужно будет отправиться по тропе времени в Черные топи. Иди на запад, потом на юг, мимо будущего меня, пока не дойдешь до тоннеля, где обитают болотные жители. Пройди этот тоннель и поговори с Са'атом.", progress = nil, completion = "На самом деле, если бы в Азерот не пришли орки, то никакого Альянса и не было бы. В конечном итоге началась бы гражданская война, которая ослабила бы человеческие королевства.\n\nИ Пылающий Легион захватил бы растерзанный междоусобицами беззащитный Азерот.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10297] = {title = "Открытие Темного портала", objective = "Защищайте Медива, пока он не откроет Темный портал.\n\nКогда выполните задание, возвращайтесь к Са'ату в Черные топи.", description = "Здесь Страж Медив пытается открыть Темный портал.\n\nПо всем топям будут открываться разломы, из которых хлынут Драконы Бесконечности. Они попытаются разрушить щиты Медива и уничтожить его самого.\n\nУбивай их лидеров и повелителей временных разломов, пока Медив не закончит свою работу.", progress = "На каждом участке времени можно использовать только один маяк.", completion = "Ты отлично справился с заданием, Выручалкин. Юный Андорму снова желает с тобой говорить.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо хранителяВремягнущий самоцветКольцо благочестия хранителяСлеза Андорму\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10298] = {title = "Герой драконьего племени", objective = "Возвращайтесь к маленькому Андорму в пустыню Танарис в Пещерах Времени.", description = "Возвращайся к Андорму, <имя>. Он ожидает тебя за пределами этого участка времени, в логове нашего господина.\n\nЯ слышу какой-то шум. Похоже, драконы Песчаной Чешуи проявляют к тебе интерес. Возможно, они захотят побеседовать с тобой.", progress = nil, completion = "Ты снова спас прошлое и будущее этого мира, Джонниди. Мы благодарны тебе и просим принять эту скромную награду.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо хранителяКольцо благочестия хранителяВремягнущий самоцветСлеза Андорму\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10299] = {title = "Отключить манагорн Б'наар", objective = "Вернитесь в манагорн Б'наар и заберите кристалл доступа у надзирателя Тередиса. Используйте его на панели управления манагорна, чтобы выключить его, затем сообщите об этом анахорету Карже. \n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Мы не можем отключить манагорн силовыми методами, поскольку рискуем вызвать взрыв, который сотрясет Запределье до самой сердцевины.\n\nСогласно твоему описанию, существует аварийное отключение, которое надолго, если не навсегда, останавливает процесс – механизм безопасности, общий для всех конструкций наару.\n\nДля выполнения этой процедуры тебе нужно заполучить кристалл, который позволит тебе связаться с панелью управления. Согласно нашим сведениям, кристаллом доступа владеет инспектор по имени Тередис.", progress = "Успешно ли выполнена задача, Псевдотанк?", completion = "Свет улыбается тебе, Псевдотанк. Мы все молились за твой успех.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10300] = {title = "Восстановление посоха", objective = "Заберите 4 осколка безупречного кристалла у призраков в руинах Энкаата и принесите Равандвиру в Зону 52.", description = "<Равандвир осматривает посох и замечает, что часть навершия отсутствует.>\n\nЭто просто варварство! Эккораш, должно быть, использовала кристалл от навершия, чтобы вставить в какую-то другую безделушку, не понимая, что эта часть действует в гармонии с остальным посохом.\n\nВ отсутствие этой части сила посоха заметно уменьшается. Если бы у меня был подходящий дренейский кристалл, я смог бы его отремонтировать. Я слышал, что гоблины видели такие кристаллы у призраков, обитающих в руинах Энкаата на севере.", progress = "Удалось ли тебе найти кристаллы, пригодные для изготовления нового навершия к посоху верховного мага?", completion = "&lt;Равандвир тщательно осматривает кристаллы, затем выбирает один.&gt;\n\nЭтот кристалл подойдет. Я изменю форму гнезда посоха, чтобы закрепить новое навершие.\n\nКогда верховный маг Варгот увидит это, он будет разочарован, но я переживу разочарование учителя, если это будет означать, что мы освободим его.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10301] = {title = "Открыть Компендиум", objective = "Заберите Халцедоновое око у Рушительницы Чар Маратиль, находящейся в Форте Ярости Солнца.", description = "Хотя я рад получить обратно большую часть компендиума Краса, он бесполезен без халцедонового ока. Видишь ли, Крас хорошо сознавал всю силу заклинаний, записанных в книге, и предпринял шаги, чтобы обезопасить их от любопытных глаз.\n\nТолько знающий маг может использовать око, чтобы открыть тайны компендиума.\n\nВо время атаки Кель'таса одна из его лейтенантов, рушительница чар Маратель, захватила око и унесла его в форт Ярости Солнца, находящийся к северо-востоку от этой башни. Несомненно, она думала, что это милая побрякушка.", progress = "Удалось ли тебе заполучить око?", completion = "Превосходно, Выручалкин. Теперь у нас есть большая часть того, что необходимо для попытки разрушения магии Кель'таса.\n\nА если эльфы крови буду страдать, потеряв местное командование, то так им и надо.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10302] = {title = "Неустойчивые мутации", objective = "Убейте 8 неустойчивых мутаций и вернитесь к ботанику Таэрикс на месте крушения в долине Аммен.", description = "Радиоактивные силовые ядра Экзодара – настоящая беда для местной фауны и флоры. Например, рядом с ними появились странные, невиданные твари.\n\nМожет быть, им можно чем-то помочь, но в настоящий момент они так расплодились, что представляют собой серьезную угрозу.\n\nОтправляйся и сократи их число. Может быть, тем временем я что-нибудь придумаю.", progress = "Я скоро придумаю, что делать с этими тварями. Дай мне время.", completion = "Так быстро? Что ж, отлично. Надеюсь, скоро я придумаю, как справляться с этими мутантами, не убивая их.\n\nУ меня появилась пара идей, но без твоей помощи мне не обойтись.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10303] = {title = "Эльфы крови", objective = "Убейте 10 эльфов крови – разведчиков и вернитесь к Толаану на хребет Теней в долине Аммен.", description = "Останови... нашествие... эльфов крови. Узнай... что они замышляют!\n\nОни у хребта... у меня за спиной.", progress = nil, completion = "Эльфы крови хотят убить нас всех. Как бы им помешать?", rewards = "Потрепанная кольчужная рубахаВидавший виды кожаный жилетВидавшая виды стеганая курткаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10304] = {title = "Воздаятель Алдар", objective = "Поговорите с воздаятелем Алдаром на месте крушения в долине Аммен.", description = "С твоей помощью мы отыскали решение наших проблем гораздо быстрее, чем я надеялся.\n\nДругой работы для тебя у меня нет. Остальным займутся мои ученики.\n\nПоговори с воздаятелем Алдаром на другой стороне корабля.", progress = nil, completion = "Тебя Кольвиния зовут, верно? Я слышал про тебя много хорошего. Ты успела принести своему народу немало пользы.\n\nИ нам без твоей помощи тоже не обойтись. Например, Жанае срочно нужен подручный. Вон она стоит.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10305] = {title = "Клятвопреступница Белмара", objective = "Найдите апартаменты клятвопреступницы Белмары в переулке Волшебников и верните книгу на полку. Затем поговорите со смотрителем Дайвортом в деревне Кирин'Вар.", description = "Этот потрепанный, но все еще прочный том – не книга заклинаний, как можно было бы ожидать от фолианта, принадлежащего магу Кирин-Тора. Страницы тома покрыты рукописными строчками историй и цветными иллюстрациями.\n\nПохоже, этот том старше своей бывшей владелицы и вполне может быть фамильным наследием. Мощная привязанность к этой книге – возможно, последняя нить, привязывающая Белмару к руинам Кирин'Вара. Быть может, возвращение книги на ее законное место на полке дарует свободу неупокоенному духу Белмары.", progress = nil, completion = "Ах, да. Я слышал, что у клятвопреступницы Белмары была древняя книга историй, но я и понятия не имел, что она взяла ее с собой в Запределье. Я уверен, что душа Белмары будет спать спокойно, зная, что книга нашлась и возвращена на свое место.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10306] = {title = "Кудесник Люминрат", objective = "Найдите апартаменты кудесника Люминрата в переулке Волшебников и верните плащ в его гардероб. Затем поговорите со смотрителем Дайвортом в деревне Кирин'Вар.", description = "Этот плащ, несомненно, работы высших эльфов; он превосходно сшит даже по меркам Кирин-Тора. Символы и буквы, вышитые на ткани плаща, не имеют, с твоей точки зрения, никакого смысла, однако явно указывают на то, что плащ наделен магическими свойствами.\n\nБыть может, этот предмет привязывает своего бывшего владельца к этому миру. Если так, то возвращение этого плаща в гардероб в апартаментах кудесника Люминрата может оборвать связь духа с этим миром и даровать душе бывшего владельца плаща покой.", progress = nil, completion = "Мы всегда отмечали, что Люминрат носит этот плащ поверх практически любой одежды. Красный цвет для него в равной степени сочетался с белым, черным, пурпурным, синим, желтым, оранжевым и зеленым. Он никогда не носил одно облачение два дня подряд, но плащ был на нем всегда...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10307] = {title = "Кольен Повелитель Льда", objective = "Найдите апартаменты Кольена Повелителя Льда в переулке Волшебников и верните шляпу на вешалку. Затем поговорите со смотрителем Дайвортом в деревне Кирин'Вар.", description = "Глядя на эту шляпу, ты задаешься вопросом, мог ли кто-то из магов Кирин-Тора носить этот головной убор. Судя по виду шляпы, похоже, что в ней постоянно разгуливал гном.\n\nТы пытаешься проверить шляпу, но не обнаруживаешь у нее никаких магический свойств, кроме слабого побуждения потанцевать.\n\nДолжно быть, этот предмет, милый сердцу покойного мага, – последнее, что привязывает его дух к деревне. Если положить шляпу на вешалку в апартаментах Кольена, его дух, возможно, обретет свободу.", progress = nil, completion = "&lt;Комендант улыбается при упоминании имени Кольена.&gt;\n\nНасчет шляпы – все именно так. Он все время носил ее, а если снимал, то не спускал с нее глаз.\n\nПару раз один из его товарищей-магов, оставшийся неизвестным, \"заимствовал\" шляпу и прятал ее – просто в шутку. Но угроза получить от Кольена одну из его ледяных стрел заставила его отказаться от подобных шуток.\n\nЯ буду скучать по маленькому Кольену. Он умел найти подход к эльфийским дамам.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10308] = {title = "Еще одна группа духов Астрала", objective = "Консорциум весьма заинтересован в уничтожении всех мятежников-заксисов в Груде на юге.\n\nЧернокнижник, если хочешь вновь оказать нам помощь, возвращайся туда и принеси нам еще больше их знаков отличия.", description = nil, progress = "Консорциум весьма заинтересован в уничтожении всех мятежников-заксисов в Груде на юге.\n\nЧернокнижник, если хочешь вновь оказать нам помощь, возвращайся туда и принеси нам еще больше их знаков отличия.", completion = "Предатели, все они предатели! \n\nА ты – молодец, |3-6(Чернокнижник)! Если снова окажешься там, то приноси новые знаки отличия в мою коллекцию!", rewards = nil}
MultiLanguageQuestData['ru'][10309] = {title = "Это сквернобот, но у него есть сердце!", objective = "Заберите сердце сквернобота и отнесите Н. Д. Лагерфелту на Груду в Пустоверти.", description = "Видишь, вон разобранный сквернобот к югу отсюда? Разве это не красота?\n\nЯ хочу получить его сердце!\n\nЧто? Да, конечно, у него есть сердце... а разве нет?\n\n<На момент вид у Н. Д. становится возмущенный.>\n\nИди туда, вскрой его, принеси мне то, что я хочу, и за это я выдам тебе хорошую премию.\n\nДа, и на твоем месте я взял бы с собой одного-двух друзей. Эти Заксисы – чрезвычайно злобные создания! \n\nВозьми этот пульт управления Скверны, чтобы запустить его сердце перед тем, как приступишь к работе.", progress = "Должно быть, мое зрение ослабло от постоянного излучения Пустоты. Тебе удалось заполучить сердце сквернобота?", completion = "Ого, посмотрите-ка на это... бьющееся сердце сквернобота! Ну, на самом деле это нельзя назвать \"биением\", но ты понимаешь, что я хочу сказать.\n\nЖду не дождусь, чтобы найти этой вещи хорошее применение. А может быть, продать ее. Я знаю несколько воню... то есть клиентов, которых это может заинтересовать.\n\nНу что ж, вот твоя заслуженная плата!", rewards = "Поножи грудыГлазная повязка астрального налетчикаОчищенная кирасаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10310] = {title = "Саботаж в портале", objective = "Сопроводите Дризья до точки вторжения: Разрушитель и проследите за безопасностью во время попыток саботажа. Затем поговорите с Гаруджем на заставе в заповеднике \"Срединные земли\" в Пустоверти.", description = "Пылающий Легион находится поблизости, на Захламленном поле скверноботов, и мы должны сделать все возможное, чтобы остановить этих демонов и не дать им захватить этот регион.\n\nУ них есть портал на юге, в районе, который они назвали достаточно ясно – точка вторжения: Разрушитель.\n\nВот что мне нужно: пойдем со мной туда, будешь охранять меня, пока я занимаюсь там саботажем.\n\nПосле этого отправляйся на заставу, расположенную на севере, внутри заповедника \"Срединные земли\", и сообщи Гаруджу о нашем успехе.\n\nНам нужно взять с собой одного-двух друзей, чтобы они нам помогли.", progress = nil, completion = "Это превосходные новости, Выручалкин!\n\nТы и Дризья проделали отличную работу. Пока портал не действует, находящиеся поблизости демоны не получат подкрепления.\n\nПозволь мне вознаградить тебя, как это принято в Консорциуме.", rewards = "Одеяния бойца КонсорциумаГлазная повязка ПустовертиПоножи Среднего королевстваВы получите:\n\n"}
MultiLanguageQuestData['ru'][10311] = {title = "Дризья нужна твоя помощь", objective = "Поговорите с Дризья, находящимся около Места Вторжения \"Разрушитель\" в Пустоверти.", description = "<класс>, хорошо, что поблизости оказался хоть кто-то способный помочь.\n\nДемоны Пылающего Легиона, собравшиеся вокруг ближайшей груды скверноботов стали действовать более решительно, и я начинаю бояться за нашу безопасность здесь. Они постоянно получают подкрепления из Места Вторжения \"Разрушитель\" на юге.\n\nМой земляк Дризья отправился туда на разведку, посмотреть, нельзя ли что-нибудь сделать с порталом Пылающего Легиона.\n\nПрошу тебя, разыщи его и окажи любую помощь, какую сможешь.", progress = nil, completion = "Надеюсь, Гарудж послал тебя, чтобы помочь мне в моей миссии.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10312] = {title = "Анналы Кирин'Вара", objective = "Заберите анналы Кирин'Вара из ратуши деревни Кирин'Вар и отнесите ее смотрителю Дайворту.", description = "Заставив духов умолкнуть, мы не избавили их от агрессии, как надеялись. Укрощенные тобою злобные духи снова появились на наших улицах.\n\nМы должны понять, чем это вызвано. Уничтожение Кирин'Вара было лишь началом, иначе духи уже успокоились бы.\n\nВ городской ратуше в южной части Кирин'Вара находилась регистрационная книга, куда вносились записи обо всех обитателях деревни. Последнее, что я слышал – ее взял на хранение боевой маг Датрик. Быть может, его дух все еще хранит книгу.", progress = "Удалось ли тебе найти регистрационную книгу?", completion = "&lt;Смотритель Дайворт берет у вас книгу и пролистывает страницы.&gt;\n\nХмм...\n\nПохоже, я был прав. Есть некая закономерность.\n\nСамые агрессивные и опасные призраки принадлежат самым сильным и высокопоставленным магам Кирин-Тора, жившим в деревне. Обычные жители и торговцы в сравнении с ними почти не представлены. Что бы это могло значить?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10313] = {title = "Измерение энергии Искажения", objective = "Экзарх Орелис, находящийся в Зоне 52, просит вас отнести настроенный на энергию искривления шар к манагорну Б'наар и использовать шар у окончания четырех трубопроводов. \n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Если наши инстинкты не лгут и эти манагорны построены с использованием технологий из Крепости Бурь, тогда всему Запределью грозит страшная опасность. \n\nЭнергозарядные механизмы Крепости Бурь никогда не рассчитывались на использование так близко от суши. Энергия искривления способна уничтожить саму эту землю, даже будучи заключена в трубопроводы Келя.\n\nОтнеси этот шар в манагорн Б'наар; он приспособлен к измерению энергии искривления. Используй его возле окончания трубопровода, там, где трубы уходят в землю.", progress = "Удалось ли тебе провести нужные нам измерения, Псевдотанк?", completion = "Это мрачные новости, Псевдотанк. Уровень энергии Искажения, излучаемой трубопроводами, опасно высок.\n\nМы должны найти способ закрыть Манагорн, иначе то немногое, что осталось от Запределья, разлетится на кусочки.", rewards = "Энергетический шлемХорошо защищающий хауберкРезонирующий топорТканые перчатки из крученых нитокВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][10314] = {title = "Длительные подозрения", objective = "Соберите 10 омерзительных останков искаженных духов во дворе часовни деревни Кирин'Вар и отнесите их смотрителю Дайворту.", description = "Странное магическое устройство не напоминает ничто из того, что тебе приходилось видеть прежде. Это определенно не работа эльфов крови. \n\nКогда ты ощущаешь, как к зданию приближаются духи, шар начинает светиться сильнее, и тускнеет, когда духи уходят. Нет сомнений, что он играет какую-то роль в порче, павшей на духов.\n\nТо, как это устройство работает, остается загадкой. Быть может, смотритель Дайворт сможет что-либо прозреть, если ты предъявишь останки духов и поделишься своими наблюдениями.", progress = "Что тебе удалось обнаружить, Атеистфрост?", completion = "&lt;Смотритель Дайворт изучает останки.&gt;\n\nСудя по описанию, это устройство похоже на средоточие некромантии... Мне следовало бы знать, что этот испорченный ученик не устоит перед этим. Я думал, что обучение не даст ему зайти так далеко, но я оказался не прав.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10315] = {title = "Нейтрализовать чародеев Пустоты", objective = "Убейте 15 пустомантов клана Ярости Солнца и возвращайтесь к ловчему Пустоты Оазулу в Лагерь Тулумана в Пустоверти.", description = "Эльфы крови – глупцы! Я рад, что наши торговые отношения с ними расторгнуты. Ни в одном своем путешествии по космосу я не встречал создания столь эгоистичных.\n\nОни продолжают уничтожать эти земли при помощи своих манагорнов, так что надо бы попробовать помешать их действиям по ту сторону моста, при манагорне Ара.\n\nИх чародеи Пустоты направляют энергию в камни крови и выкачивают из них для того, чтобы стабилизировать поток силы. Отправляйся туда и уничтожь их!", progress = "Сколько чародеев Пустоты пало от твоей руки?", completion = "Что бы мы ни сделали ради того, чтобы заставить их прекратить работу манагорнов, все это будет благим делом.\n\nПохоже, разумные доводы на них не действуют. И мне ясно, что какие бы замыслы ни лелеяли их вожди, они, несомненно, безумны.\n\nВ качестве вознаграждения за твою верную службу целям Консорциума я хотел бы предложить тебе денежную единицу твоего мира, если это не оскорбит тебя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10316] = {title = "В поисках доказательств", objective = "Поищите во дворе часовни в деревне Кирин'Вар свидетельства того, кто именно манипулирует духами убитых.", description = "Тот, кто стоит за изменением духов, действует явно намеренно, выбирая своей целью, в первую очередь, души самых могущественных магов. Но почему? Магия, необходимая для того, чтобы подчинить своему влиянию убитых магов Кирин-Тора, должна быть очень могущественной. \n\nЗачем такому сильному магу брать на себя все эти хлопоты? Я склонен считать, что это еще один план Кель'таса, направленный на то, чтобы нанести нам как можно больше урона. Если здесь есть эльфы крови, они, скорее всего, скрываются в домах за крытым мостом.", progress = nil, completion = "Светящийся шар установлен на вершине квадратного пьедестала. С первого взгляда он кажется просто вместилищем магической энергии, однако какой именно энергии? И кто ею пользуется?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10317] = {title = "Покончить со штейгером", objective = "Покончите со штейгером Закатом Солнца, находящимся в руднике Треллеума под манагорном Ара в Пустоверти.", description = "Эльфы крови называют шахту, расположенную под манагорном Ара, рудником Треллеума. С тех пор, как они потеряли шахту под манагорном Ультрис, этот рудник остался последним источником материала для работы манагорнов.\n\nЧто и говорить, для нас было бы выгодно помешать работам на руднике. Быть может, мы сумеем даже сделать больше и забрать шахту себе.\n\nКак бы то ни было, я прошу тебя отправиться туда и покончить со штейгером Закатом Солнца. Рудник находится с обратной стороны острова по левую сторону.", progress = nil, completion = "&lt;Штейгер говорит едва ли не шепотом.&gt;\n\nТы здесь для того, чтобы убить меня? Ха. Полагаю, духи Астрала знают не так-то много, верно?\n\nЯ не тот, кто тебе нужен, поверь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10318] = {title = "Покончить с Подчинителем", objective = "Убейте Подчинителя Гриндгарра. Затем вернитесь к торговцу Ветром Тулуману в Лагерь Тулумана в Пустоверти.", description = "Некогда я был штейгером здесь. Но теперь, когда меня понизили в звании, я начал осознавать, что наше паломничество из Кель'Таласа в Запределье – это сплошная ложь.\n\nЛожь, изобретенная Кель'тасом для усиления его войск здесь, в Пустоверти.\n\nЯ пытался убедить моих собратьев, что нам нужно уходить прочь, особенно если учесть, что здесь находится Пылающий Легион, но все они так упрямы! \n\nНе окажешь ли ты мне услугу? Убей Подчинителя Гриндгарра. Затем возвращайся к своему духу Астрала и скажи ему, что я больше ему не враг.", progress = nil, completion = "Надсмотрщиком там был стражник Ужаса? Странно! Что здесь делает Пылающий Легион?\n\nИтак, кое-кто из эльфов крови дезертирует. Мы будет иметь это в виду, если попытаемся захватить этот регион силой. По крайней мере, хоть какие-то хорошие новости во всем этом есть, не так ли?\n\nПрими мою глубочайшую благодарность, Мротсагемо, а вместе с ней вот это.", rewards = "Перчатки ловчего ПустотыСапоги высадкиНаплечники подчинителяВам дадут возможность выбрать одну из следующих наград:\n\nКольцо торговца ветром\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10319] = {title = "Захватить талисман", objective = "Заберите филактерию Набериуса из района часовни деревни Кирин'Вар и принесите его смотрителю Дайворту.", description = "Я полагаю, необходимо объяснение. Тебе уже приходилось встречаться с одним из учеников нашего верховного мага – Рандивиром. Однако был еще один ученик, по имени Набериус. \n\nОн был весьма прилежен и талантлив, однако увлекся некромантией. Когда явился Кель'тас со своим воинством, Набериус воспользовался этой возможностью, чтобы предать верховного мага, и выдал тайну защиты башни.\n\nТеперь, похоже, он стал личом. Если мы хотим остановить его, мы должны захватить его талисман. Зная его, могу сказать, что он, вероятнее всего, зарыл его где-нибудь за пределами своих владений.", progress = "Прежде чем напасть на самого Набериуса, нужно забрать его талисман. Иначе он будет неуязвим.", completion = "Превосходная работа, Выручалкин. Обретение талисмана может стать ключом к нашей победе. Когда ты выйдешь на бой с Набериусом, я разобью талисман и лишу нашего врага защиты.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10320] = {title = "Уничтожить Набериуса!", objective = "Смотритель Дайворт в деревне Кирин'Вар просит вас сразиться с Набериусом, находящимся во дворе часовни, и уничтожить его.", description = "Верховный маг Варгот видел опасность в стремлении Набериуса к некромантии, однако вряд ли он подозревал, что его собственный ученик навлечет столько бедствий на Кирин-Тор.\n\nЕго нужно остановить, <имя>, иначе он продолжит порабощать души наших павших собратьев, лишая их покоя и уничтожая то немногое, что осталось от Кирин'Вара.\n\nСо своим талисманом он может противостоять двум-трем бойцам, но кто знает, насколько сильна его магия и что он может противопоставить большему количеству врагов?", progress = nil, completion = "Уничтожение Набериуса - великое достижение, Акул. Не могу отделаться от мысли, что мы могли бы противостоять войскам Кель'таса, если бы этот ученик мага не предал нас.", rewards = "Одеяния ученика Кирин-ТораСохраняющая жизнь кирасаКапюшон гибелиНабедренники твердого поборникаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10321] = {title = "Отключить манагорн Коруу", objective = "Отправляйтесь в манагорн Коруу к востоку от Зоны 52 и заберите кристалл доступа Коруу у надзирательницы Сейланны. Используйте его на панели управления манагорна Коруу, чтобы отключить манагорн, затем вернитесь к анахорету Карже.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Твой успех в манагорне Б'наар подарил нам великую надежду, <имя>.\n\nМы поделились нашими открытиями с Провидцами, и в ответ они предоставили нам сведения по оставшимся манагорнам.\n\nТри других манагорна еще работают, и их полностью контролирует армия Ярости Солнца.\n\nМанагорн Коруу ты найдешь к востоку отсюда. Кристалл доступа от нее хранится у надзирательницы Сейланны. Забери этот кристалл и примени его к панели управления манагорном, дабы начать аварийное отключение. \n\nВсе мы рассчитываем на тебя, <имя>.", progress = "Удалось ли тебе выполнить задачу, Мротсагемо?", completion = "Прекрасно. Теперь работают только два манагорна.\n\nВскоре Кель'тас будет отрезан от своего главного источника энергии.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10322] = {title = "Отключить манагорн Даро", objective = "Анахорет Каржа просит вас отправиться в манагорн Даро и забрать кристалл доступа у надзирателя Атанеля. Используйте этот кристалл на панели управления манагорном Даро, чтобы отключить его.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Мы получили новости с одной из двух все еще действующих манагорнов. Армия Ярости Солнца теряет контроль над манагорном Даро. \n\nУвеличившееся производство энергии привлекло туда стада блуждающих мана-тварей, и теперь там царит полный беспорядок.\n\nВзрыв на Даро, вполне вероятно, будет настолько силен, что вызовет цепную реакцию, из-за чего под угрозой окажется все Запределье. У надзирателя Атанеля хранится кристалл доступа, который нужен, чтобы безопасно отключить манагорн.", progress = "Удалось ли тебе выполнить задачу, Маганес?", completion = "Да пребудет с тобой благословение наару, Маганес. Твоя преданность нашему делу будет должным образом отмечена и вознаграждена.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10323] = {title = "Отключить манагорн Ара", objective = "Отправляйтесь в манагорн Ара и заберите кристалл доступа у надзирателя Азарада. Используйте его на панели доступа манагорна Ара, чтобы отключить его.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Один манагорн – это все, благодаря чему Крепость Бурь все еще действует. После того как мы отключим манагорн Ара, Келю придется черпать энергию из тех запасов, которые у него есть.\n\nОтправляйся к манагорну Ара, расположенному на северо-западе, и отключи ее, нанеся тем самым последний удар. \n\nПоследний кристалл доступа находится у надзирателя Азарада. Осторожно – последний из действующих манагорнов наверняка будут защищать изо всех сил. Тебе, вероятно, понадобится помощь надежных друзей.", progress = "Удалось ли тебе выполнить порученное задание, Акул?", completion = "Пылающий Легион в союзе с Кель'тасом Солнечным Скитальцем?\n\nЭто страшные новости. Они многое объясняют относительно того, что мы видели здесь и в Долине Призрачной Луны.\n\nМы должны немедленно послать известие об этом в город Шаттрат.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерстень надзирателяМедальон Каржи\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10324] = {title = "Великая охота на лунных оленей", objective = "Принесите 6 шкур самцов лунного оленя Актеону с Лазурной заставы.", description = "Молодец, <имя>! Молодец!\n\nМне кажется, что, потренировавшись на лунных оленях, ты можешь перейти к более сложной добыче. Не обманывайся спокойствием самцов лунного оленя: если их разозлить, они оказываются непростыми противниками.\n\nСамцы пасутся к северу отсюда. Доброй охоты.", progress = "У маралов чрезвычайно прочные шкуры, хотя мясо очень жесткое – практически несъедобное. Но мы их применим для других целей.", completion = "Чудесно! Ты становишься настоящим охотником, Шамакс.\n\nХочешь выглядеть, как я? Почему бы и нет! Пока ты охотился, я сделал несколько предметов из оленьих шкур. Выбирай любой!", rewards = "Сапоги из шкуры Лунного оленяМеховой плащ из Лунного оленяВы получите:\n\n"}
MultiLanguageQuestData['ru'][10325] = {title = "Знаки Кил'джедена", objective = "Принесите 10 знаков Кил'джедена Адуину Стражу Света в Шаттрат.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Как ты, наверное, уже знаешь, <имя>, Алдоры – это хранители Света и слуги наару.\n\nНаши главные враги – это Пылающий Легион, армия демонов, жаждущая разрушить и осквернить все миры.\n\nЕсли ты желаешь проявить себя перед Алдорами, принеси мне знаки различия легионеров низшего ранга и последователей Легиона из Совета Теней. Одна из баз Совета находится в Костяных пустошах, а заставы Легиона разбросаны по всему Награнду и Острогорью.", progress = "Принес ли ты, вражеские знаки отличия, Джонниди?", completion = "Сражаться с демонами Пылающего Легиона и культистами, которые им поклоняются, - задача не из легких, Джонниди, но у вас достаточно смелости и решительности. Продолжайте в том же духе, и отношение Алдоров к вам будет постоянно улучшаться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10326] = {title = "Больше знаков Кил'джедена", objective = "Вы принесли еще знаков различия наших врагов, |3-6(Маг)? Пылающий Легион все еще угрожает нам, и мы преследуем его повсеместно.", description = nil, progress = "Вы принесли еще знаков различия наших врагов, |3-6(Маг)? Пылающий Легион все еще угрожает нам, и мы преследуем его повсеместно.", completion = "Вы растете в наших глазах, Профессия. Боритесь с врагами Света повсюду, и ваши подвиги будут достойно вознаграждены.\n\n*Это задание можно выполнять до тех пор, пока вы не заслужите почтительное отношение.*", rewards = nil}
MultiLanguageQuestData['ru'][10327] = {title = "Знак Кил'джедена", objective = "Я приму любой оставшийся у тебя знак. Не волнуйся, твои усилия будут оценены должным образом.", description = nil, progress = "Я приму любой оставшийся у тебя знак. Не волнуйся, твои усилия будут оценены должным образом.", completion = "Вы растете в наших глазах, Ишт. Боритесь с врагами Света повсюду, и ваши подвиги будут достойно вознаграждены.\n\n*Это задание можно выполнять до тех пор, пока вы не заслужите уважительного отношения к себе.*", rewards = nil}
MultiLanguageQuestData['ru'][10328] = {title = "Инструкции Ярости Солнца", objective = "Отправляйтесь в манагорн Даро и заберите военные инструкции Ярости Солнца и чародейские инструкции Ярости Солнца. По завершении задачи возвращайтесь к экзарху Орелису.\n\nВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.", description = "Что-то в этих манагорнах беспокоит меня, <имя>. Технология наару чрезвычайно развита, Келю потребовались бы годы только для того, чтобы начать постигать ее.\n\nСбор сведений относительно этого вопроса очень труден, так как армия Кель'таса очень дисциплинирована и уничтожает все свидетельства письменного общения.\n\nНам сообщили, что манагорн Даро подвергается нападению мана-тварей. Возможно, что из-за необходимости обороняться там еще не успели уничтожить инструкции. Забери их и принеси мне.", progress = "Повезло ли тебе добыть инструкции из манагорна Даро?", completion = "Превосходная работа, Обдолбыши! Посмотрим, что мы можем узнать из этих инструкций.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10329] = {title = "Отключить манагорн Б'наар", objective = "Вернитесь в манагорн Б'наар и заберите кристалл доступа у надзирателя Тередиса. Используйте его на панели управления манагорна Б'наар, чтобы выключить его, затем сообщите об этом патрону шпионов Талодиену. \n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "За время твоего отсутствия у меня состоялась дружеская дискуссия с Алдорами. Манагорны выглядят точь-в-точь как несколько измененные технологии наару из Крепости Бурь. Судя по всему, в большинстве конструкций наару существовал предохранитель, позволявший в случае аварии отключить их навсегда.\n\nОбычно это действие выполнялось с панели управления через кристалл доступа. И знай, что согласно принесенному тобою списку персонала, подобный кристалл находится в руках некоего типа, известного как надзиратель Тередис. Завладей этим кристаллом и посмотри, что сумеешь сделать.", progress = "Сработал ли план? Правду говоря, я наполовину ожидал, что тебя схватят.", completion = "Конечно же, это сработало! Я глава шпионов, и мои сведения всегда точны. \n\nВ любом случае, у меня для тебя есть отличная новая работа. Хочешь услышать, что именно? Несомненно, хочешь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10330] = {title = "Отключить манагорн Коруу", objective = "Заберите кристалл доступа Коруу у надзирателя Сейланны. Используйте его на панели управления Коруу, чтобы отключить манагорн, затем вернитесь к Каледису Сияющему Рассвету.\n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "Талодиен рассказал нам, что тебе удалось отключить манагорн Б'наар. Он ожидает, что здесь произойдет то же самое, и просил нас высмотреть, у кого находится кристалл для доступа к панели управления. Мы уверены, что кристалл доступа находится у надзирателя Сейланны.\n\nОтправляйся туда и доверши дело. Больше нет необходимости в кражах; заполучи кристалл, начни отключение, убей техников, которые попытаются тебя остановить, и возвращайся.\n\nПоспеши, скоро ищейки Келя отыщут нас.", progress = "Удалось ли тебе выполнить задачу, Нуа?", completion = "Мы слышали весь этот шум и уже собирались убраться отсюда. Хорошо, что тебе досталось не очень сильно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10331] = {title = "Необходимые инструменты", objective = "Заберите кузнечный молот у кирин'варских учеников и отнесите обратно ученику Андретану в деревню Кирин'Вар.", description = "Тебе случайно не попадался на глаза тяжелый кузнечный молот – нигде там не валяется? Я принес его с собой, чтобы закончить ковать подковы для лошадей старины Армолина, но что-то никак не могу найти.\n\nЯ обыскал весь амбар полдюжины раз, но так и не нашел. Может, кто-то из учеников забрал его и отнес обратно в кузницу? Ты не сходишь туда, чтобы удостовериться? Кузница находится на северо-востоке от башни на Городской площади.", progress = "Удалось ли тебе найти мой молот?", completion = "Хвала небесам! Теперь я могу вернуться к работе. Я знаю, ты думаешь, будто я сумасшедший, поскольку работаю над изделием, которое принесет мне статус подмастерья, не в кузнице, как положено, а едва ли не в чистом поле. Но я не могу рисковать – вдруг остальные ученики скопируют мою разработку?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10332] = {title = "Мастер-кузнец Ронсус", objective = "Ученик Андретан из деревни Кирин'Вар просит вас убить призрак Ронсуса, мастера-кузнеца поселения.", description = "Наконец-то мое изделие, дающее право на звание подмастерья, готово! Не могу дождаться, чтобы официально предъявить его мастеру Ронсусу.\n\n<Ученик смотрит на вас, пока вы описываете свои действия по изъятию молота.>\n\nОни напали на тебя? Все? Во имя Света, они сошли с ума!\n\nЧто нам делать, <имя>? Мне горько говорить об этом, но, возможно, понадобится убить мастера Ронсуса. В этом случае я останусь единственным кузнецом в Кирин'Варе, но, полагаю, я достаточно обучен, чтобы справиться с работами, необходимыми поселению.", progress = nil, completion = "Мастер Ронсус научил меня всему, что я знаю о моем ремесле. Я почту его память тем, что использую свои умения на службе у живущих в Кирин'Варе.", rewards = "Молот кузнеца-мастераТонкотканые выделанные чешуйчатые поножиИскусная работа АндретанаУсиленный топхельмВы получите:\n\n"}
MultiLanguageQuestData['ru'][10333] = {title = "Помощь Мамаше Колесун", objective = "Поговорите с Мамашей Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти.", description = "Скажи, <имя>, не можешь ли ты оказать мне еще одну услугу?\n\nМоя напарница осуществляет работу непосредственно на месте, и ей, вероятно, приходится нелегко. Ты ее не проведаешь?\n\nЯ уверен, что Мамаша Колесун оценит твою помощь. Просто не обращай внимания на ее колкости.\n\nОна отстаивает наши интересы в восточной части этих земель. Ты найдешь ее в заповеднике \"Срединные земли\" на заставе.", progress = nil, completion = "Что? Он назвал меня \"напарницей\"? Я его жена!\n\nИ он утверждает, что я говорю колкости? Ну все, как только вернусь в Зону 52, отрежу его здоровенные зеленые уши!\n\nНо я рада, что ты здесь. Насчет одного он точно был прав: твоя помощь мне пригодится!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10334] = {title = "Колокольчик для коровы", objective = "Найдите Бесси в полях близ Часовенного холма деревни Кирин'Вар в Пустоверти.", description = "Где же, где же моя Бесси? После нападения я обыскал все поля и Церковный двор, но ее нигде не было!\n\nВсе, что мне осталось от нее – это вот этот старый колокольчик. Когда она слышала его звон, то обычно прибегала, но мои руки уже совсем ослабли. Даже для того, чтобы звонить в колокольчик.\n\nЯ одолжу тебе колокольчик Бесси, если ты согласишься пойти в поле и звонить в него как можно громче. Быть может, Бесси просто ждет, пока в колокольчик позвонят погромче и подольше.", progress = "<Корова недоверчиво смотрит на тебя, но стоит на месте.>", completion = "&lt;Достав колокольчик, вы несколько раз звоните в него, потом показываете его Бесси, которая, похоже, узнает этот предмет. Корова позволяет вам завязать у нее вокруг шеи веревку и выжидательно смотрит на вас.&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10335] = {title = "Исследование руин", objective = "Разместите три геодезических знака, затем возвращайтесь к Зефириону в Штормовую Вершину в Пустоверти.", description = "Я намереваюсь отправиться в руины Фаралона, чтобы начать там раскопки. Проблема в том, что это место кишит демонами. \n\nМожет быть, ты проведешь для меня кое-какую подготовительную работу?\n\nВ северо-восточной части руин находятся три точки, где нужно разместить геодезические знаки. Каждый – поблизости от дренейского знамени.\n\nВозвращайся, когда установишь все три знака.", progress = "Ого, как быстро! Ты, должно быть, работаешь очень эффективно, если установил все три знака за такое короткое время.", completion = "Это ведь не шутки, верно? Отличная новость!\n\nТеперь, когда геодезическая разметка участка проведена, я могу откомандировать бригаду в руины и посмотреть, что там можно найти. \n\nПрими мою благодарность, |3-6(Маг).", rewards = "Астральные перчаткиПояс ЗефирионаНагрудный доспех Штормовой ВершиныВы получите:\n\n"}
MultiLanguageQuestData['ru'][10336] = {title = "Приспешники Кулутаса", objective = "Убейте 10 псов Кулутаса и 5 злобоглазов Кулутаса.", description = "Несколько недель назад Пылающий Легион вторгся в руины Фаралона, нарушив наши планы относительно раскопок в поисках артефактов.\n\nА сегодня я узнал, что один из их повелителей ужаса, Кулутас, убил своих собратьев из Пылающего Легиона и с тех пор призывает демонов, которые служат ему.\n\n<класс>, я прошу тебя отправиться в эти руины, находящиеся к северо-востоку отсюда, и уничтожить кишащих там демонов.", progress = nil, completion = "Поистине отличная работа.\n\nТеперь, когда демоны Кулутаса убиты, Зефирион сможет безопасно заняться раскопками в руинах Фаралона.\n\nПрими эти деньги в знак моей признательности.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10337] = {title = "Когда коровы возвращаются домой", objective = "Благополучно сопроводите Бесси к ее владельцу, Таделлу.", description = "Осознав, что Бесси все еще смотрит на тебя, ты жестом указываешь туда, где находится Таделл. Ты считаешь, что обещание выполнено – корова благополучно прибыла домой. Но еще не закончив говорить, ты осознаешь, что корова все равно не сможет понять ни единого слова. \n\nПожав плечами, ты готовишься сопровождать скотину, пока она не вернется к Таделлу.", progress = "Удалось ли тебе найти мою Бесси?", completion = "Бесси, это ты?\n\n*Фермер поворачивается к тебе.*\n\nСпасибо за возвращение моей Бесси, Выручалкин! Я без нее жить бы не смог!", rewards = "Сапоги пастухаЕздовые перчатки ковбояЧеканная пряжка скотоводаНаручи ТаделлаЭлектрострекалоВы получите:\n\n"}
MultiLanguageQuestData['ru'][10338] = {title = "Отключить манагорн Даро", objective = "Вернитесь в манагорн Даро и заберите кристалл доступа у надзирателя Атанеля. Используйте его на панели управления манагорна Даро, чтобы отключить его, затем сообщите об этом патрону шпионов Талодиену. \n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "Так на манагорн Даро совершено нападение, и войска Ярости Солнца теряют контроль? Какая дилемма. Если Даро падет, то падет и Крепость Бурь. Единственная загвоздка... если Крепость Бурь будет разрушена, взрыв, вероятно, уничтожит то немногое, что осталось от этой проклятой земли.\n\nСмерть Кель'таса – это хорошо. Смерть всех остальных... полагаю, не очень. Мне больно просить тебя об этом, но отправляйся в манагорн Даро и отключи его прежде, чем он загорится. Кристалл доступа находится у надзирателя Атанеля.", progress = "Отключение завершено? Поспеши, пока я не передумал насчет всех этих планов!", completion = "Итак, Выручалкин, ты уже отключил три манагорна. Должно быть, у Кель'таса теперь начались настоящие проблемы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10339] = {title = "Братство Эфириум", objective = "Командир Амир просит вас уничтожить 5 убийц из Эфириума, 5 штормовиков из Эфириума, 2 ученых Эфириума и капитана Зовакса из Эфириума, затем включить передатчик Эфириума Зета.", description = "Прямо на юг отсюда ты найдешь полигон Братства Эфириум. Братство находится там, к чему-то готовясь... Возможно, к нападению на Ультрис.\n\nОднако мы не можем упускать шанс, <класс>. Нужно пробиться через их оборонительный периметр и захватить их учебную базу.\n\nКогда ты уничтожишь их солдат и капитана Зовакса, отыщи передатчик Эфириума Зета и используй его, чтобы связаться со мной для получения дальнейших указаний.", progress = nil, completion = "Мы должны собрать все данные, которые они спрятали в этом регионе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10340] = {title = "Парящая застава", objective = "По приказу командира передовой Кингстона поговорите с командиром звена Даби'ри, доберитесь на грифоне до Парящей заставы и поговорите с Рунтогом Громовым Молотом.", description = "<имя>, ты <проделал/проделала> на фронте большую работу, и отлично <управился/управилась> с тем бронированным грифоном... Я думаю, что нашел для тебя еще одно дело.\n\nНовое задание ждет тебя на Парящей заставе. Это передовой пост клана Громового Молота, этакий плавучий кусок земли рядом с порталом. Там немного неуютно, но я верю, что тебе хватит смелости. Все будет отлично.\n\nПоговори с командиром звена Даби'ри, пусть он отправит тебя на Парящую заставу. Как прибудешь, доложись Грунтогу Громовому Молоту.", progress = nil, completion = "Ха-ха-ха! Свеженький |3-6(ночной эльф) с большой земли! Не боись, сначала тебя малость поукачивает, а потом перестанет.\n\nНа моем веку застава опрокидывалась только один раз. Ну... максимум два.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10341] = {title = "Лежачего не бьют – лежачего пинают", objective = "Убейте 8 кудесников, 6 лучников и 4 центурионов клана Ярости Солнца. После завершения задачи вернитесь к магистру Ларинне, находящейся в Зоне 52.\n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "Принесенные тобой новости радуют меня, <имя>. Тебе не только удалось пробраться в манагорн Даро <незамеченным/незамеченной> – это также дает отличную возможность нанести удар по армии Келя.\n\nИспользуй это нападение мана-тварей в свою пользу и перебей всех отбившихся от основного отряда солдат Ярости Солнца, на которых наткнешься.\n\nВ отличие от Талодиена, я не вижу ничего забавного в бессмысленном убийстве своих сородичей, но тактическое преимущество слишком ценно, чтобы отказаться от такого случая.", progress = nil, completion = "Хорошая работа, Выручалкин. Армия Келя нескоро оправится от нанесенного тобою удара.", rewards = "Клинок Ярости СолнцаКувалда мастера искаженийИзукрашенная алебардаПосох фокусникаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10342] = {title = "Добыча кожи глиношкурых", objective = "Соберите 5 кусков кожи глиношкурых и отдайте Бутсу в Зоне 52 в Пустоверти.", description = "Я делаю неплохие деньги, продавая выпивку местным пьяницам. Но мне нужно кое-что еще!\n\nВедущий ракетостроитель постоянно говорит мне, что не может усовершенствовать ракетное топливо, необходимое, чтобы запустить Х-52.\n\nМы можем решить эту мелкую проблему вместо него.\n\nДля начала мне нужно извлечь нефть из кожи местных глиношкурых камнедеров! Она образует концентрированную, пусть даже несколько взрывчатую, основу для смеси, придуманной мною.\n\nКамнедеров, равно как и их кожу, можно найти повсюду около лиловых скал.", progress = "Тебе удалось собрать достаточно глины? Мне нужно довольно много, чтобы добыть то количество нефти, которое мне нужно, дабы создать топливо для ракеты Х-52.", completion = "Отлично! Ингредиент номер один получен.\n\nТеперь, если тебя интересует, мы должны перейти к тому, что придаст добытой из глины нефти дополнительную силу, необходимую, чтобы отправить ракету Пустоты в Круговерть Пустоты... или в небытие, как уж получится.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10343] = {title = "Бесконечное вторжение", objective = "Обыщите кишащий мана-тварями район деревни Кирин'Вар в поисках фрагмента мана-бомбы и принесите его лейтенант-колдуну Моррану.", description = "Атака Кель'таса на Кирин'Вар началась с громового раската и яркой вспышки света в офицерском квартале в северо-западной части поселения. Разрушения там были наиболее страшными, а после ухода эльфов крови начали происходить странные вещи. \n\nСущества, состоящие из чистой маны, буквально хлынули на деревню из этого района. Пока что мы справляемся с ними, как можем, однако я надеюсь, что если у меня будет больше сведений об этом оружии Кель'таса, я сумею прекратить вторжение мана-тварей.", progress = "Удалось ли тебе найти оружие, которое Кель'тас использовал против нашей деревни?", completion = "Мана-бомба?\n\n&lt;Морран вертит фрагмент в руках.&gt;\n\nЭто непредставимо! Даже самые светлые умы Даларана не могли придумать подобное оружие. Резкое усиление возмущений, должно быть, создало разрыв в Пустоте, позволив этим тварям проникнуть в наши земли.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10344] = {title = "Командир звена Грифонгар", objective = "Поговорите с командиром звена Грифонгаром на Парящей заставе.", description = "За старшего здесь командир звена Грифонгар. Если ты в первый раз на Парящей заставе, то следует доложить ему о прибытии.\n\nЕго можно найти во-он там, где-то среди остатков той башни.", progress = nil, completion = "Ты говорил c Рунтогом? Отличный дворф! Он хорошенько следит за своими грифонами, они должны быть всегда готовы к бою.\n\nЯ Грифонгар, я здесь самый главный. Может, тут не очень уютно, зато эта скала – важнейший опорный пункт для налетов на полуостров. Видишь грифонов, которые все время снуют туда-сюда?\n\nМогу дать совет, если хочешь. Держи вещмешок наготове, желудок впроголодь и не спускай глаз с горизонта. А когда Парящую заставу начнет раскачивать, хватайся за то, что хорошо приколочено!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10345] = {title = "Усеял мертвыми костями...", objective = "Примените поджигатель Протектората к 12 высохшим трупам. Когда задача будет завершена, верните поджигатель Протектората посланнику Араксису, находящемуся у входа в шахту Зеон.", description = "Ты видишь эти трупы, <раса>? В этом убийстве повинен Арконус. Он высосал их досуха, оставив лишь мертвую плоть. Но не дай виду этих трупов обмануть тебя! Внутри них скрываются пожиратели плоти, готовые наброситься на любого, кто подойдет поближе.\n\nУ меня есть приказ – оставаться здесь, пока не прибудет подмога. Однако ты можешь взять мой поджигатель и уничтожить эти высохшие трупы, которыми забита шахта. Так или иначе, миссия должна быть выполнена!", progress = "Удалось ли тебе найти Йасека?", completion = "Ты спас мои обмотки, Выручалкин. Протекторат узнает о твоих деяниях.", rewards = "Рукавицы мясоводаБоевой пояс протекторатаНаручи разрушителяСапоги астрального тюремщикаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10346] = {title = "Возвращение на Косогор Бездны", objective = "Уничтожьте 20 ган'аргов-батраков, 5 мо'аргов-надзирателей и 5 пушек Скверны по просьбе грифоньера Ветрорева с Парящей заставы на полуострове Адского Пламени.", description = "<имя>, ты <показал/показала> себя <отличным наездником/отличной наездницей> на грифоне, так что можешь участвовать и в дальнейших вылазках к Косогору Бездны. Что скажешь, <класс>? Хочешь еще полетать?", progress = "На Косогоре Бездны осталось еще множество отличных мишеней, Фэникс. Бери грифона да лети.", completion = "Ну, как на этот раз? Я вижу, ты в отличной форме! В самый раз для нового вылета!", rewards = nil}
MultiLanguageQuestData['ru'][10347] = {title = "Возвращение на Косогор Бездны", objective = "Уничтожьте 20 ган'аргов-батраков, 5 мо'аргов-надзирателей и 5 пушек Скверны по просьбе командира звена Бракка из Гибели Сквернобота на полуострове Адского Пламени.", description = "<имя>, <готов/готова> к очередной вылазке к Косогору Бездны? Если мы прекратим постоянные атаки на Легион, то они так укрепят свои позиции, что потом на севере мы не отобьемся от демонов.\n\nЧто скажешь, <класс>? Хочешь слетать еще раз на Косогор Бездны и размолоть в пыль все, что попадется?", progress = "И пусть Легион не думает, что наверху, на Косогоре Бездны, они в безопасности. Мы еще не раз устроим им ковровую бомбардировку!", completion = "Все пилоты ветрокрылов отзываются о тебе с уважением, Ксаер. Ты уничтожил много целей на Косогоре Бездны. Так держать!", rewards = nil}
MultiLanguageQuestData['ru'][10348] = {title = "Новые возможности", objective = "Соберите 15 \"кремовых колокольчиков\" и вернитесь к Мердаду на Заставу срединных земель.", description = "Я слышал, что группа \"друидов\" с Азерота заинтересовалась эффектами технологии наших экосфер. \n\nПредставители Кенарийской экспедиции желают получить доступ к растениям, растущим внутри экосфер, в особенности к одному из них, именуемому \"кремовый колокольчик\" и известному своими целительными средствами. Густые заросли их встречаются вокруг более крупных растений в заповеднике \"Срединные земли\".\n\nЯ поделюсь с тобой доходами, если ты соберешь этой травки для первой партии товара.", progress = "Тебе удалось собрать травку?", completion = "Интересный выбор, не так ли? Эти целительные свойства должны быть поистине чудотворными. Я вкладываю кучу денег в такую невзрачную травку.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10349] = {title = "Землепряд", objective = "Отнесите осколок алого хрусталя заклинательнице земли Галандрии Ночной Бриз на Кенарийскую заставу на полуострове Адского Пламени.", description = "Отнеси этот кусок хрусталя Галандрии, землепряду. Знаешь, вы с ней похожи. Все время пытаетесь что-то там расследовать и придумать.\n\nПо-моему, она слишком много думает.\n\nОтдай ей этот кристалл, и я даже не сомневаюсь, что она тут же нагрузит тебя работой. Будешь выяснять, что же там все-таки происходит.", progress = "Это осколок того самого гигантского кристалла, который свалился на Гряде Упавшего Неба?", completion = "О, прекрасно! Я давно хотела заполучить кусок этого кристалла, но Тола'тион все время ставил мне палки в колеса.\n\nОн должен помочь мне понять, что случилось на Гряде Упавшего неба, но способен лишь посылать простофиль вроде тебя – только без обид – на убой.\n\nОтдай мне этот кристалл. Думаю, я смогу найти связь между ним и горными гигантами.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10350] = {title = "Бехомат", objective = "Поговорите с Бехоматом в Торговом ряду Экзодара.", description = "Хотя я многому тебя научила, пришло время передать тебя более умелому учителю.\n\nБехомат наставлял меня, когда я была совсем неопытным воином, и именно ему я хочу доверить твое обучение. Я уже сообщила о твоем прибытии, и он ждет тебя.\n\nТы отыщешь его в центре Террасы воинов, в самой высокой части Торгового ряда в Экзодаре.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Большой меч наемникаШестопер наемникаМеч наемникаСтилет наемникаВы получите:\n\n"}
MultiLanguageQuestData['ru'][10351] = {title = "Целительная сила природы", objective = "Посадите Семя Возрождения в Круге землепряда, чтобы исцелить землю вокруг кристалла. После этого возвращайтесь к землепряду Галандрии Ночной Бриз на Кенарийскую заставу и расскажите о том, что получилось.", description = "Должно быть, горных великанов привлекают сюда эманации этого гигантского кристалла, которые затем и сводят их с ума.\n\nВряд ли мы сможем убрать отсюда кристалл - он слишком велик, и уничтожить его тоже не получится. Но есть один способ заглушить его излучение.\n\nЯ создала Круг на гряде к северо-западу от кристалла. Опусти туда это семечко, и пусть его сила исцелит землю с помощью дождя, растений и насекомых.\n\nОстерегайся, <имя>, я чувствую чужеродное вмешательство... так не должно быть!", progress = "Ну что, сработало? Тебе удалось что-нибудь узнать? Ты выяснил, что случилось на гряде Упавшего Неба?", completion = "Голиафон? Паталеон Вычислитель?\n\nКЕЛЬ'ТАС?!\n\nТут замешан принц Кель'тас?\n\n*Землепряд шипит от злости*\n\nДа это же просто безумие! Уронить с неба гигантский кристалл и опустошить всю землю способен только безумец!\n\nМогу тебя заверить, Кенарийская экспедиция больше не допустит ничего подобного.\n\nМы в огромном долгу пред тобой, Джонниди.", rewards = "Золотые кенарийские наголенникиЗеленеющие повязкиУкрашенные зеленые повязки на щиколоткуОплечье разрушителейВы получите:\n\n"}
MultiLanguageQuestData['ru'][10352] = {title = "Пожертвование: шерсть", objective = "Мы сейчас собираем пожертвования в виде шерстяной ткани. За щедрый дар вы получите признательность Дарнасса. Наши запасы таковы, что нам нужно от вас всего лишь шестьдесят отрезов. Мы могли бы купить их и на стороне, чтобы продолжить работу.\n\nНо если вы имеете шестьдесят отрезов шерстяной ткани и готовы пожертвовать их в дар, я с готовностью приму их у вас прямо сейчас.", description = nil, progress = nil, completion = "Прекрасно! Огневар, благодарим тебя за щедрое пожертвование!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][10353] = {title = "Арконус Ненасытный", objective = "Посланник Иасикс, находящийся у входа в шахту Зеон, просит вас убить Арконуса Ненасытного и вернуться к командиру Амиру на заставу стражи Протектората в Пустоверти.", description = "Араксес и я были отправлены в Ультрис два дня назад. Наша миссия: найти и уничтожить повелителя Бездны Арконуса. Мы проследили его до этой шахты и обнаружили, что он высасывает энергию из существ, обитающих в этом регионе.\n\nВо время последовавшей перестрелки мы с Араксесом потеряли друг друга из вида. И вот я застрял здесь, тяжело раненный. Наша миссия в опасности!\n\nЕсли ты сможешь избавиться от Арконуса, наше командование будет тебе признательно. В том случае, если ты возьмешься за эту миссию, я помогу тебе – дам тебе в охранники свое отражение.", progress = nil, completion = "А Йасек? Он это сделал?\n\nБудем надеяться, что да. Мне не удалось послать им подкрепление... Теперь весь регион захвачен Братством Эфириум.\n\nПрошу прощения, я едва не забыл про твою награду.", rewards = "Мундир наемного убийцы протекторатаГоловной убор мясоводаЛатный пояс призывателя звездПоножи путника ПустотыВы получите:\n\n"}
MultiLanguageQuestData['ru'][10354] = {title = "Пожертвование: шелк", objective = "Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.\n\nЕсли ты можешь пожертвовать шестьдесят отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!", description = nil, progress = "Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.\n\nЕсли ты можешь пожертвовать шестьдесят отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!", completion = "Прекрасно! Огневар, благодарим тебя за щедрое пожертвование!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][10355] = {title = "Иссохшее тело", objective = "Соберите 5 образцов опаленной гидры и 5 образцов ткани высохшего болотника и принесите их Руаму в Телредор.", description = "Нам необходимо определить, насколько велик причиненный урон. Принесенная тобой высохшая базидия принадлежит болотоходу. Их более крупные и мощные родичи, болотники, должны были оказаться более устойчивыми к вырождению, которое поразило великанов.\n\nХорошо было бы выяснить, как перемены в Мертвой трясине повлияли на других обитающих там созданий.\n\nВернись в Мертвую трясину и попробуй добыть образцы обитающих там болотников и гидр.", progress = "Ну что, удалось тебе собрать образцы?", completion = "*Руам изучает образцы. Вид у него озабоченный.*\n\nЭтого я и боялся, Сотус! Снижение уровня влажности окружающей среды отрицательно сказывается на всех болотных организмах. Нам придется продолжать свои наблюдения и проконсультироваться с Кенарийской экспедицией, чтобы выяснить, можно ли что-то предпринять.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10356] = {title = "Пожертвование: магическая ткань", objective = "Мы занимаемся сбором магической ткани. Если ты пожертвуешь нам на благие цели 60 отрезов, то заслужишь признательность всего народа.\n\nЕсли у тебя есть 60 отрезов, можешь сдать их нам прямо сейчас.", description = nil, progress = "Мы занимаемся сбором магической ткани. Если ты пожертвуешь нам на благие цели 60 отрезов, то заслужишь признательность всего народа.\n\nЕсли у тебя есть 60 отрезов, можешь сдать их нам прямо сейчас.", completion = "Спасибо за щедрость, Ренгольд.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][10357] = {title = "Пожертвование: руническая ткань", objective = "Мы занимаемся сбором рунической ткани. Если ты пожертвуешь на благие цели 60 отрезов, то заслужишь признательность всего нашего народа.\n\nЕсли у тебя есть 60 отрезов, можешь пожертвовать их прямо сейчас.", description = nil, progress = "Мы занимаемся сбором рунической ткани. Если ты пожертвуешь на благие цели 60 отрезов, то заслужишь признательность всего нашего народа.\n\nЕсли у тебя есть 60 отрезов, можешь пожертвовать их прямо сейчас.", completion = "Спасибо за щедрость.\n\nЕсли ты сочтешь возможным продолжать пожертвования, я прослежу, чтобы о тебе узнали наши предводители в Экзодаре.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10358] = {title = "Больше рунической ткани", objective = "И снова здравствуй, Мэлфис. Если ты готов выделить нам еще двадцать отрезов рунической ткани, то, будь уверен я постараюсь, чтобы все узнали о твоей щедрости. Если у тебя есть 20 отрезов рунической ткани, я охотно ее приму.", description = nil, progress = "И снова здравствуй, Мэлфис. Если ты готов выделить нам еще двадцать отрезов рунической ткани, то, будь уверен я постараюсь, чтобы все узнали о твоей щедрости. Если у тебя есть 20 отрезов рунической ткани, я охотно ее приму.", completion = "Благодарю за помощь, Мэлфис.", rewards = nil}
MultiLanguageQuestData['ru'][10359] = {title = "Пожертвование: шерсть", objective = "Принеси 60 отрезов шерстяной ткани. Жители Луносвета будут тебе очень благодарны!\n\nЕсли необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас.", description = nil, progress = "Принеси 60 отрезов шерстяной ткани. Жители Луносвета будут тебе очень благодарны!\n\nЕсли необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас.", completion = "Ты принес шерстяную ткань! Жители Луносвета никогда не забудут твоей щедрости.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][10360] = {title = "Пожертвование: шелк", objective = "Принеси 60 отрезов шелка. Жители Луносвета будут тебе очень благодарны!\n\nЕсли необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас.", description = nil, progress = "Принеси 60 отрезов шелка. Жители Луносвета будут тебе очень благодарны!\n\nЕсли необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас.", completion = "Ты принес шелк! Жители Луносвета никогда не забудут твоей щедрости.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][10361] = {title = "Пожертвование: магическая ткань", objective = "Принеси 60 отрезов магической ткани. Жители Луносвета будут тебе очень благодарны!\n\nЕсли необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас.", description = nil, progress = "Принеси 60 отрезов магической ткани. Жители Луносвета будут тебе очень благодарны!\n\nЕсли необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас.", completion = "Ты принес магическую ткань! Мы никогда не забудем твоей щедрости.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][10362] = {title = "Пожертвование: руническая ткань", objective = "Принеси 60 отрезов рунической ткани. Жители Луносвета будут тебе очень благодарны!\n\nЕсли необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас.", description = nil, progress = "Принеси 60 отрезов рунической ткани. Жители Луносвета будут тебе очень благодарны!\n\nЕсли необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас.", completion = "Все как договорились! Ты принес мне руническую ткань, а я замолвлю за тебя словечко перед жителями Луносвета.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10363] = {title = "Больше рунической ткани", objective = "Рунической ткани много не бывает. Принеси еще 20 отрезов – и получишь бесконечную признательность жителей Луносвета!\n\nПросто отдай ее мне, когда найдешь нужное количество.", description = nil, progress = "Рунической ткани много не бывает. Принеси еще 20 отрезов – и получишь бесконечную признательность жителей Луносвета!\n\nПросто отдай ее мне, когда найдешь нужное количество.", completion = "Что ж, вижу, ты справился с заданием. Теперь у меня еще больше рунической ткани!", rewards = nil}
MultiLanguageQuestData['ru'][10364] = {title = "Кедмос", objective = "Поговорите с Кедмосом в Чертоге Света Экзодара.Тебе удалось многого добиться за короткое время, <имя>. Гораздо больше, чем можно было надеяться. Пришло время продолжить обучение под руководством Кедмоса.\n\nОн уже получил вести о тебе и дожидается твоего прибытия в Экзодаре. Его можно найти в святилище анахоретов неподалеку от входа в Чертог Света.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Тебе удалось многого добиться за короткое время, <имя>. Гораздо больше, чем можно было надеяться. Пришло время продолжить обучение под руководством Кедмоса.\n\nОн уже получил вести о тебе и дожидается твоего прибытия в Экзодаре. Его можно найти в святилище анахоретов неподалеку от входа в Чертог Света.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10365] = {title = "Отключить манагорн Ара", objective = "Отправляйтесь в манагорн Ара, заберите кристалл доступа Ара у надзирателя Азарадда. Используйте его на панели управления манагорном Ара, чтобы отключить его. \n\nВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.", description = "Тебе удалось справиться лучше, чем ожидал кто-либо из нас. Манагорн Ара – последний работающий манагорн, оставшийся в распоряжении Келя. Он находится к северо-западу отсюда, хотя для того, чтобы попасть сюда тебе, наверное, лучше пойти кружным путем. Тебе необходимо выключить его.\n\nПоследний кристалл доступа находится в распоряжении у надзиратель Азарада. Насколько нам известно, это последний источник энергии Келя, так что сопротивление будет яростным. На твоем месте я взял бы с собой нескольких друзей.\n\nХмм... Азарад. Странное имя для син'дорай.", progress = "Удалось ли тебе выполнить задачу, о которой я говорил тебе, Демонишен?", completion = "Кель в сговоре с Пылающим Легионом? Ха! Ворен'таль по потолку будет бегать от таких сведений.\n\nТы думаешь, тысячи паломников, собравшихся со всего Азерота, захотят союзничать с Пылающим Легионом? Я думаю, нет!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо бури маныОберег Талодиена\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][10366] = {title = "Джоль", objective = "Поговорите с Джоль в Святилище поборников в Экзодаре.", description = "Следовать путем света и чистоты нелегко. Даже мне порой случается оступиться.\n\nПоговори с моей наставницей Джоль в Экзодаре. Она помогла мне сделать первые шаги на этом пути, и я не сомневаюсь, что ты станешь ее <лучшим учеником/лучшей ученицей>.\n\nДжоль можно отыскать в Чертоге Света Экзодара. Найди святилище воздаятелей – это комната, окруженная сиянием.", progress = nil, completion = "Я давно тебя поджидаю, Фах.\n\nТуллас превозносит тебя до небес, и я с радостью продолжу учить тебя пути Света. Я помогу тебе лучше разобраться в своих способностях и скрытом могуществе, когда ты будешь готов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10367] = {title = "Предатель среди нас", objective = "Добудьте ключ Ша'наара, спрятанный в лачуге в руинах Ша'наара неподалеку от Наладу.", description = "Везде, где есть пленные Сломленные, найдется и предатель. Ничтожное создание, продавшее своих собратьев в обмен на обещание власти.\n\nСреди руин, на ступенях, примостилась его жалкая лачуга.\n\nПредателя сейчас там нет, так что ты сможешь подкрасться незаметно, если будешь <осторожен/осторожна>. Внутри стоит сундук, в котором лежит ключ. Это ключ от цепей пленных старейшин Отребья. Принеси его мне.\n\nБудь <осторожен/осторожна>, где-то неподалеку бродит Арзет Безжалостный.", progress = "Тебе удалось достать ключ, Менгиле?", completion = "Спасибо тебе, Рунакус. Благодаря тебе мой народ скоро обретет свободу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10368] = {title = "Старейшины Отребья", objective = "Освободите Морода Ветродува, Акору Призывателя Огня и Айлаана Пробуждающего Водув руинах Ша'наара. После выполнения задания возвращайтесь к Наладу.", description = "Дух племени Отребья сломлен, потому что наши старейшины томятся в плену. Возьми этот ключ и ступай вниз, чтобы освободить их.\n\nИх зовут Мород Ветродув, Акору Призыватель Огня и Айлаан Пробуждающий Воду. Если они станут свободны, духи вернутся к Отребью.", progress = "Ответь мне, Джонниди. Свободны ли старейшины Отбросья?", completion = "Я чувствую, Джонниди! Духи вернулись к нам.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10369] = {title = "Наследие Арзета", objective = "Используйте посох старейшин племени Отребья против Арзета Безжалостного. После того как Арзет потеряет силу, убейте его. После выполнения задания возвращайтесь к Наладу в руины Ша'наара.", description = "Да, стихии снова вернулись к нам! Это не та сила, что была когда-то, но и немного магии в умелых руках может сделать многое.\n\nАрзет обладает великой мощью, дарованной ему исчадиями преисподней. Возьми этот посох. Когда-то он был великим символом нашего племени. Если его использовать против Арзета, посох на время лишит его силы. Уничтожь Арзета и освободи мой народ!", progress = "Ты справился Менгиле? Азрет мертв?", completion = "Да, это правда, Менгиле. Когда-то меня звали Наладу, хранитель Земли.\n\nИменно я предал старейшин Отбросья в обмен на пустое обещание силы. Можешь презирать меня, если хочешь. Мне важно только одно, - мой народ снова свободен, и духи вернулись к нам.\n\nПусть я не смогу вернуться к своим собратьям, зато умру с чистой совестью. Пусть дух земли найдет себе нового служителя среди моего народа.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10371] = {title = "Йорус Ячменовар", objective = "Поговорите с Йорусом Ячменоваром в таверне Приозерья, что в Красногорье.", description = "Воин-дворф по имени Йорус Ячменовар бросил вызов всем воинам Альянса.\n\nОн ждет в таверне Приозерья, что в Красногорье в Восточных королевствах. Путь предстоит долгий, но возможность испытать свои силы стоит того.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10372] = {title = "Деликатная просьба", objective = "Поговорите с Эраланной в Транквиллионе.", description = "Эраланна, моя поверенная из Транквиллиона, попросила помощи в выполнении какого-то срочного задания.\n\nНе знаю, что там у нее случилось, но думаю, что ты в любом случае справишься. Отправляйся в Транквиллион, что в Призрачных землях, и поговори с Эраланной. \n\nСлов она не выбирает, но можешь верить ей без опаски.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10373] = {title = "Призыв к оружию: Чумные земли!", objective = "Найдите командира Ашлама Отважного Кулака в лагере Промозглого Ветра на севере Альтеракских гор.", description = "Слушайте, слушайте все! Я обращаюсь к героям, и да услышат они мою речь!\n\nВКороль Штормграда призывает к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Стало известно, что над Чумными землями вновь сгущаются тучи!\n\nГерои королевства! Ищите командира Ашлама Отважного Кулака! Его гарнизон вы найдете в лагере Промозглого Ветра на севере Альтеракских гор!", progress = nil, completion = "Добро пожаловать в Чумные земли, героиня. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!\n\nЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10374] = {title = "Призыв к оружию: Чумные земли!", objective = "Отыщите верховного палача Деррингтона. Его базовый лагерь находится у Бастиона, к востоку от Тирисфальских лугов и Подгорода.", description = "Внимайте моим словам, о герои! Орда призывает к решительным действиям!\n\nВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.\n\nХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лугов!", progress = nil, completion = "Добро пожаловать в Чумные земли, героиня. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!\n\nЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][10375] = {title = "Обсидиановое боевое ожерелье", objective = nil, description = "Ты много <сделал/сделала> для нашего народа и всегда <был/была> для нас <верным другом/доброй подругой>, <имя>. <Готов/Готова> ли ты еще раз доказать свою преданность и выступить с нами против сильнейшего из врагов?\n\nОгры Запределья", progress = nil, completion = nil, rewards = nil}
