MultiLanguageQuestData['ru'][11114] = {title = "Зои, изумрудный дракон Пустоты", objective = "Познакомиться с тобой, Аурикка, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты сделал для племени Крыльев Пустоты.\n\nЕсли ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.\n\nНо ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПоводья зеленого дракона из стаи Крыльев Пустоты"}
MultiLanguageQuestData['ru'][11117] = {title = "Поймать дикого зайцелопа!", objective = "Голдарк Меткий Охотник попросил вас поймать 5 оглушенных диких зайцелопов с помощью особой сети. Он намекнул, что необходимо достичь состояния сильного алкогольного опьянения – или надеть Синтехмельные очки.", description = "Ну вот. Слышишь? Страшный шум в холмах. Это зайцелопы! Коварные звери так и прут на запах Хмельного фестиваля! Я хотел бы поймать парочку, да вот беда, ушиб ногу, мне их не догнать. Ты можешь мне помочь!\n\nВозьми сеть и накинь ее на мелких гадов. Принеси мне не меньше пяти, а уж за мной не заржавеет! Ах, да, еще одно – чтобы увидеть зайцелопов, тебе придется хорошенько заложить за воротник! Пей, не жалей – или хотя бы одолжи у меня Синтехмельные очки!", progress = "Ты не слишком ли трезвый? Может, поэтому ты не видишь этих гадов?", completion = "Ну, смотри-ка! Целая куча зайцелопов, любо-дорого глядеть.\n\n&lt;Он делает большой глоток из кружки.&gt;\n\nВот, что я сделаю. Раз ты так ловко их поймал, оставь себе одного!", rewards = "Вы получите:\n\nКружка зайцелопа"}
MultiLanguageQuestData['ru'][11118] = {title = "Розовые элекки на марше", objective = "Отправляйтесь в сады спелого хмеля рядом с Штормградом, Дарнасом и Экзодаром, истребите по три элекка в каждом из мест и возвращайтесь к Голдарку Меткому Охотнику. Чтобы увидеть розовых элекков, необходимо напиться или надеть Синтехмельные очки.", description = "Напиваться на Хмельном фестивале – почетная традиция! Дело в том, что со всего Азерота идут жалобы – весь праздник портят галлюцинации! Так дело не пойдет!\n\nПроклятых элекков не берет обычное оружие – проходит сквозь них – так что возьми этот образчик гномьей инженерии, обойди все сады спелого хмеля и уничтожь розовых тварей. И не забудь, для этого надо хорошенько напиться – или хотя бы одолжить у меня Синтехмельные очки!", progress = "Ну что, дурацкие розовые элекки пропали?", completion = "Прекрасно! Розовые элекки... Что за бред!", rewards = "Вы получите:\n\nПризовой жетон Хмельного фестиваля"}
MultiLanguageQuestData['ru'][11119] = {title = "Налет на лагерь Баш'ира!", objective = "Поговорите с учеником эфир-теха на заставе Стражи Небес в Острогорье.", description = "Эй, <приятель/подруга>! Хочешь поразвлечься, а?\n\nКаждые пару часов мы, эфир-техи, совершаем налет на лагерь Баш'ира, там, далеко на северо-востоке Острогорья. Говорят, что мы \"изучаем\" тамошнюю хрустальную кузницу, но на самом-то деле это налет, и ничто иное. Нам хрустальная кузница нужна для дозаправки, да еще остается на продажу.\n\nИди-ка на посадочную площадку и переговори с учеником эфир-техника. Он тебе скажет, когда очередной вылет.", progress = nil, completion = "Как бы Келлер это ни называл, я предпочитаю считать, что наша миссия – исследовательская.\n\nНо врать не стану, бывая там мы пополняем запасы Стражи Небес. Только кто же нам даст там задержаться подольше... \n\nПохоже, вы сумеете не дать духам Астрала ударить нам в спину. Если вы продержитесь достаточно долго, мы продадим вам избыток того, что сделаем в хрустальной кузнице, так что несите свои апекситовые осколки и кристаллы!\n\nВылетаем в 0 |4минуту:минуты:минут;.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11120] = {title = "Розовые элекки на марше", objective = "Отправляйтесь в сады спелого хмеля рядом с Луносветом, Громовым Утесом и Подгородом, истребите по три элекка в каждом из них и возвращайтесь к Глодраку Меткому Охотнику. Чтобы увидеть розовых элекков, необходимо напиться – или хотя бы надеть Синтехмельные очки.", description = "Слушай, мы тут на жизнь зарабатываем. Народ хочет выпить – можно денег наварить. Одна беда – галлюцинации. Ребята говорят, будто алк... постоянные клиенты видят повсюду розовых элекков.\n\nКлиенты – дело важное. Слышь, возьми этот луч и походи по другим садам спелого хмеля, разберись с элекками, а? Только хорошенько наберись перед этим или хотя бы надень Синтехмельные очки. Если они тебе нужны, обращайся.", progress = "Ну как, ты разобрался с той проблемкой, о которой я недавно упоминал?", completion = "Молодец, дружище. Вот, возьми это в уплату за проделанную работу.", rewards = "Вы получите:\n\nПризовой жетон Хмельного фестиваля"}
MultiLanguageQuestData['ru'][11121] = {title = "ЕЖЕДНЕВНОЕ ИСПЫТАТЕЛЬНОЕ ЗАДАНИЕ (РЕЙД)", objective = "Поговорите с <QUESTGIVER> в <AREA>.<NYI>Ищите <QUESTGIVER> в <LOCATION>. Она/он желает, чтобы вы помогли им в трудном деле.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "<NYI>Ищите <QUESTGIVER> в <LOCATION>. Она/он желает, чтобы вы помогли им в трудном деле.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11122] = {title = "Туда и обратно", objective = "Возьмите бочку у Флинна Огневара и верните ее Полу Янтарлену. Пока баран не сбежит от вас, постарайтесь доставить три бочки.", description = "Хочешь помочь нам на Хмельном фестивале? У меня есть отличное задание. Садись на скакового барана и дуй в Каранос. Мне надо прихватить там кой-какие бочки.\n\nНа холме рядом с грудой бочек тебя дожидается Флинн Огневар. Когда ты подойдешь поближе, он кинет тебе бочку. Тащи ее сюда и отдавай Полу Янтарлену. Больше одной бочки разом тебе не поднять.\n\n<Готов/Готова>?", progress = nil, completion = "Огромное спасибо за помощь! Пока дворфы Черного Железа не сложили оружие, а Хмельной фестиваль продолжается, мне не обойтись без помощников. Если ты хочешь еще подзаработать, приходи завтра.\n\nВпрочем, довольно болтать. Надо заплатить тебе за труды. Вот жетоны, желаю веселого Хмельного фестиваля!", rewards = "Вы получите:\n\nПризовой жетон Хмельного фестиваля"}
MultiLanguageQuestData['ru'][11123] = {title = "nspecting the Ruins", objective = "Поговорите с инспектором Таремом у трактира \"Последний привал\".", description = "Бедняга Джеймс так и не оправился после пожара в \"Последнем привале\" и гибели семьи. Мы с ребятами делаем все, что в наших силах, чтобы найти ублюдков, ответственных за это.\n\nЯ послал нашего лучшего следователя, инспектора Тарема, на пепелище, но одному там не справиться. Если вы поможете Тарему, мы этого не забудем. Видит Свет, мы все хотели бы помочь.\n\nДо таверны можно дойти по главной дороге, только будьте поосторожнее. В такую глухомань мои патрули не заходят.", progress = nil, completion = "Я рад, что капитан Ваймс наконец-то и других привлек к этому делу.\n\nЯ здесь все посыпал отражательным порошком – с его помощью можно увидеть подозрительные предметы и знаки и здорово сэкономить время. Иди и собери все, что светится от этой пыли.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11124] = {title = "nspecting the Ruins", objective = "Расследуйте дело в таверне \"Последний привал\", что стоит на границе Степей и Пылевых топей.", description = "Если ты пойдешь по дороге на юг от деревни, а затем свернешь на запад к Степям, ты найдешь пепелище таверны \"Последний привал\".\n\nТерамор направил туда следователя, чтобы разобраться, с чего бы это вдруг таверна сгорела. У меня есть наблюдатель в тех местах, к тому же, я не очень верю в то, что людям удастся раскрыть, что же там произошло.\n\nЧто бы ты ни <разузнал/разузнала>, не смей рассказывать об этом следователю. Мы сами со всем разберемся.", progress = nil, completion = "*Инспектор смотрит на вас с нескрываемым недоверием.*\n\nМне сказали, что ты будешь... помогать в расследовании. Что же, хорошо.\n\nЯ обработал тут все вот этим порошком, чтобы узнать, кто напал на гостиницу. Он поможет выявить улики, связанные с эти нападением. Обследуй все, что покажется подозрительным.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11126] = {title = "Чужой среди своих", objective = "Прогоните 5 дезертиров-подстрекателей и вернитесь к докам Терамора к Калии Гастингс.", description = "Хорошо, что я тебя встретила, <класс>. Вот, прибыла в Терамор, чтобы разобраться с дезертирством. Солдаты покидают свои посты, вражеские агенты проникают в город!\n\nОни распространяют лживую пропаганду, надеясь, что и другие к ним присоединятся!\n\nАгенты буквально повсюду – у всех сторожевых постов в городе и доках. Необходимо выявить их и дискредитировать! Пока ничего больше и сделать нельзя, иначе только вызовешь к ним еще больше доверия.", progress = "Тебе удалось прогнать подстрекателей из Терамора?", completion = "Очень хорошо, Малендис. Думаю, нам удалось застать их врасплох. Похоже, эти агенты считали себя в безопасности за городскими стенами.\n\nСо временем подстрекатели вернутся и снова будут распространять дезинформацию. А мы пока воспользуемся тем временем, что ты для нас выиграл, чтобы отогнать их как можно дальше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11128] = {title = "Пропагандистская война", objective = "Доставьте дезертирскую пропаганду Калии Гастингс к докам в Тераморе.", description = "Вражеские агенты не просто так заводят беседы со стражниками. Мы обнаружили множество листовок с призывом к дезертирству – каким-то образом их умудрились доставить в доки.\n\nКорабль, что привез листовки, еще стоит в Тераморе, в дальнем доке. Если тебе удастся проникнуть на борт и выкрасть оставшиеся пропагандистские листовки, то вражеские агенты утратят свое самое мощное оружие. Только осторожнее! Команда – опытные каперы. Груз, скорее всего, держат в капитанской каюте.", progress = "Тебе удалось найти и захватить оставшиеся пропагандистские листовки?", completion = "&lt;Агент ШРУ одобрительно кивает.&gt;\n\nБлестяще. Остается только дискредитировать дезертиров так, чтобы они больше носу не сунули в Терамор, и у меня на этот счет есть план.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11129] = {title = "Пропал Кайл!", objective = "Анаб Пшеничная Грива из деревни Кровавого Копыта в Мулгоре попросил найти его лучшего щенка, Кайла Бесноватого.\n\nПокормите Кайла нежным мясом долгонога и возвращайтесь к Анабу Пшеничной Гриве.", description = "Помоги мне, <имя>! Мой любимый щенок Кайл сбежал! Я знаю, он потерялся и теперь бегает вокруг Деревни Кровавого Копыта, голодный и несчастный.\n\nПожалуйста, отыщи его и покорми. Он поест, утешится и вернется домой.\n\nНо сначала надо найти для него еду. Его любимое блюдо - нежное мясо долгоногов. Отправляйся на восток, там их - хоть пруд пруди. Убей одного из них и принеси его сочное мясо Кайлу. Как увидишь Кайла в городе - предложи ему мясо, и он непременно подойдет к тебе.", progress = "Ну как, ты нашел Кайла?", completion = "Превосходно, Тогати! Как только Кайл наелся, он сразу вернулся домой и завалился спать. Спасибо за помощь.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11130] = {title = "Ой, блестяшечки!", objective = "Жуль хочет, чтобы вы взяли его записку и отнесли ее Бадду в Призрачные земли к Зул'Аману.", description = "Ходи сюда, <парниша/лапуля>! Дай старине Грифтаху посмотреть на твои блестяшечки...\n\nХммм. Да-да, неплохо, но ты можешь добыть больше. Куда больше.\n\n*Грифтах наклоняется к вам и шепчет.*\n\nСлавные блестяшечки - они повсюду, <имя>, только надо знать, где искать! Нынче тебе свезло так свезло - я знаю парня, который поможет тебе найти столько блестяшек, что и не унесешь.\n\nЗайди к моему старому приятелю, Бадду - он болтается близ Зул'Амана, и покажи ему вот это. Он поймет, что тебя послал старый Грифтах, и он тебя посвятит в свою затею.", progress = "*Бадд с подозорением рассматривает записку.*\n\nЧто тут у тебя, |3-6(Друид)?", completion = "*Бадд читает записку.*\n\nА, друг Жуля? Добро пожаловать!\n\nКак раз вовремя. По роковому стечению обстоятельств я недавно лишился своих партнеров. Настоящая трагедия, но большой выигрыш стоит больших затрат. Но лучше не думать о плохом!\n\nТы, несомненно, уже знаешь о моих бесчисленных изобретениях и открытиях, но все они – ничто по сравнению вот с этим! Честно говоря, мы тут в Зул'Амане, можно сказать, творим историю, и ты по велению судьбы вступаешь в дело с самого начала!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11131] = {title = "Гаси пожар!", objective = "Переодетая попечительница сирот просит вас помочь потушить пожар в деревне. Когда пожар будет потушен, снова поговорите с попечительницей сирот.", description = "Вы должны помочь нам! Всадник без головы напал на деревню! Кругом пожар! Дети в опасности!\n\nПожалуйста, <имя>, помогите пожарной бригаде. Берите ведро и заливайте пожар или передавайте ведра по цепочке! Погасите пожар, и мы, может, еще спасемся!", progress = "Милтрэй, вы обещали спасти детей!", completion = "О, спасибо! Да благословит Свет ваши добрые деяния, добрый господин. Тень Темного Всадника все еще стоит у нас за спиной, но по крайней мере хотя бы на некоторое время деревня может не опасаться пожара.", rewards = "Вы получите:\n\nТыквовинская конфетаТыквовинские сладостиУтяжеленный фонарь из тыквы"}
MultiLanguageQuestData['ru'][11132] = {title = "Все обещаешь и обещаешь", objective = "Разыщите карту Бадда Недрека на террасе верховного шамана Налоракка в Зул'Амане и верните ее хозяину.", description = "Мои изыскания подтверждают слухи об огромном сокровище, спрятанном в Зул'Амане. Там для каждого найдется своя гора золота с холмиком! Но сначала ты <должен/должна> заработать свою долю в этом пироге.\n\nНаша первая попытка достать эти сокровища пошла не так гладко, как я надеялся. Фактически, моя карта и те неумехи, которым я ее вручил, пропали без вести. Они отправились за троллем по имени Налоракк.\n\nЗабудь об этих неудачниках, мне нужна карта! Добейся успеха и ты войдешь в историю как тот, кто помог Бадду Недреку раскрыть тайны Зул'Амана.", progress = "Ну что, нашел мою карту?", completion = "*Бадд выглядит слегка ошеломленным.*\n\nЧто? Ты нашел ее?\n\nКхм... ТО есть, что это я... Конечно нашел! Отлично, |3-6(Рыцарь смерти).\n\nДай-ка взглянуть, смогу ли я найти, что-нибудь стоящее, чтобы отблагодарить тебя. О! Это подойдет.", rewards = "Вы получите:\n\nПотрепанный мешок из проклятой ткани"}
MultiLanguageQuestData['ru'][11133] = {title = "Дискредитация вражеской агентуры", objective = "Калия Гастингс просит вас всучить подправленные листовки 6 тераморским стражникам. После этого вернитесь к Калии и доложите о выполнении задания.", description = "Я кое-что изменила в листовках, которые ты <похитил/похитила> у наших заклятых друзей в доках. Теперь они пропагандируют совсем другое!\n\nЕсли мы подкинем побольше этих листовок страже, врагам вряд ли удастся так легко снова угнездиться в наших стенах.\n\n<Калия вручает вам стопку подправленных листовок.>\n\nНе займешься этим, пока я обдумываю наш очередной шаг?", progress = "Мне показалось, что я слышала смех из казарм. Ты раздал мои листовки?", completion = "&lt;Калия прищелкивает языком, когда вы описываете ей реакцию стражников на листовки.&gt;\n\nКак я и надеялась! Думаю, теперь-то уж точно любого вражеского агента, который попытается сунуться в Терамор, просто высмеют.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11134] = {title = "Конец вражеской пропаганде", objective = "Арестуйте Гависа Серого Щита, затем доложитесь Калии Гастингс у доков Терамора.", description = "С дезертирами из Терамора мы разобрались, операцию пора завершать. Местные осведомители сообщили, что база дезертиров – на корабле, который швартуется у небольшого острова к юго-востоку от пристани.\n\nЕсли арестовать их главаря Гависа Серого Щита, то у остальных отпадет всякая охота сражаться. Найди его на том корабле и заставь сдаться. Не удивлюсь, если сначала он набросится на тебя, но когда поймет, что ему не победить, то успокоится.", progress = nil, completion = "Просьба Гэвиса не так нелепа, как может показаться. Если провести операцию должным образом, то леди Джайна сумеет вернуть дезертиров на путь истинный, но решение, конечно же, за ней.\n\nПриятно было работать с тобой, Небрить. Сомневаюсь, что без твоей помощи операция прошла бы столь же гладко. Когда буду писать рапорт в Штормград, обязательно скажу, что ты - тот самый |3-6(Шаман), который покончил с угрозой дезертирства.", rewards = "Клобук подмастерьяСапоги рыскателяАрбалет наемникаШлем ученикаПлащ леди ПраудмурВы получите:\n\n"}
MultiLanguageQuestData['ru'][11135] = {title = "Всадник без головы", objective = "Найдите святилище тыквы Всадника без головы.", description = "Ты <прогнал/прогнала> Всадника без головы, но пока существует Тыквовин, он будет возвращаться. Прошу тебя, <имя>, положи конец нашим несчастьям! Сил больше нет выслушивать безумные причитания Всадника! Сразись с ним, пока голова еще сидит на его плечах!\n\nОн покоится в Покинутом ските Монастыря Алого ордена в Тирисфальских лесах. Найди его святилище тыквы и скажи такие слова:\n\nВсадник, встань\nПришла пора\nУмереть в последний раз!\n\nИди же, <имя>. И да пребудет с тобой Свет.", progress = nil, completion = "Откуда взялось это святилище, никому не ведомо, но кому оно посвящено – никаких сомнений нет...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11136] = {title = "Тревожные события", objective = "Поговорите с капитаном Ваймором на Сторожевом посту.", description = "В последнее время доклады патрульных все тревожнее. На Зловещем берегу, что к северу от стен Терамора, видели людей с красными повязками Братства Справедливости.\n\nВ том районе нашли обломки корабля, так что они могли выжить в кораблекрушении... но у нас мало сведений об этом. Капитан Ваймор со Сторожевого поста – это башня к северу от города – ищет помощников, которые возьмутся за прояснение ситуации.", progress = nil, completion = "*Капитан откровенно оценивает вас взглядом.*\n\nЗначит, вам известно о недавнем кораблекрушении? Отлично, я буду рад помощи в выяснении моих подозрений насчет выживших. Добро пожаловать на борт, Небрить.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11137] = {title = "efias in Dustwallow?", objective = "Добудьте приказы Братства Справедливости у Гарна Маферса и принесите его капитану Ваймору на Сторожевой пост.", description = "Мои разведчики донесли о кораблекрушении на северо-востоке побережья. Кораблекрушения здесь - дело обычное, но донесения говорят о том, что выжившие носят красные банданы Братства Справедливости!\n\nОни ремесленники и цеховики, но не мореходы. Что они делают на месте кораблекрушения на континенте, который не представляет для них интереса?\n\nГоворят, их предводитель живет на большом острове недалеко от побережья, к северо-востоку от города. Убей его и принеси все документы, какие удастся найти.", progress = "Удалось выследить главаря?", completion = "&lt;Капитан Ваймор берет у вас приказы и просматривает их.&gt;\n\nЧто значит \"драгоценный груз\"? Братство Справедливости по мелочам протаскивало контрабанду в Штормград, но язык, которым написаны эти поручения, указывает на богатого и знатного клиента. Это совершенно не похоже на работу Братства.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11138] = {title = "enn McGill", objective = "Отнесите приказы Братства Справедливости Ренну Макгиллу. Он плавает недалеко от Зловещего берега.", description = "Судя по содержанию раздобытых тобой приказов, главная цель Братства Справедливости – обнаружение и захват груза.\n\nУ ШРУ уже достаточно давно в Тераморе действует ныряльщик по имени Ренн Макгилл. Когда он узнал про кораблекрушение, Ренн отправился нырять на север, к островам, которые сейчас заняло Братство Справедливости.\n\nЕсли мы хотим добраться до груза раньше, чем Братство, нам нужна помощь Ренна. Ищи его у северо-восточного побережья островка, расположенного чуть севернее, чем тот остров, на котором ты <побывал/побывала> до этого.", progress = "Здорово, |3-6(Друид). Что привело тебя в такую даль?", completion = "&lt;Ренн просматривает приказы.&gt;\n\nЗначит, на борту был ценный груз! Нужно обойти Братство Справедливости и найти его первыми. Ныряльщики из этих ребят никудышные, но вот их снаряжение мне бы пригодилось.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11139] = {title = "econdhand Diving Gear", objective = "Принесите набор инструментов и испорченное водолазное снаряжение Ренну Макгиллу в Пылевые топи.", description = "Отсюда и до Алькаца все дно усеяно обломками затонувших кораблей, и водолазы Братства Справедливости уже вовсю собирают \"урожай\". С помощью их снаряжения мы и тебя отправим на охоту, но сначала его надо, так сказать, \"позаимствовать.\"\n\nВ общем, так: обойди остров, найди ящик с испорченным водолазным снаряжением и инструменты для починки. Потом тащи все это мне, и я тебя быстренько экипирую!", progress = "Ну-ка, посмотрим, что тебе удалось \"позаимствовать\" у Братства.", completion = "М-да... состояние плачевное... Я думал, что будет получше. И инструменты... ну ладно.\n\nЯ обещал починить снаряжение, и я его починю. Вот прямо сейчас и займусь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11140] = {title = "ecover the Cargo!", objective = "Принесите 6 поднятых со дна сундуков Ренну Макгиллу в Пылевые топи.", description = "Ну что ж, я кое-как заштопал снаряжение, так что немного понырять ты сможешь. Но особо долго сидеть под водой не советую.\n\nОбломки корабля разбросаны по дну, начиная от восточного побережья этого острова и до самого острова Алькац. Пока шлем держится, походи по дну между островами и поищи обломки, а потом попытайся извлечь из них груз с помощью этого набора спасателя. Но слишком близко к Алькацу не подходи, а то тебя там гидры сожрут.", progress = "Ну что, нашлось какое-нибудь добро Братства Справедливости?", completion = "&lt;Ренн копается в содержимом сейфов, которые вы нашли.&gt;\n\nТы молодец. Посмотрим, что это за ценный груз такой...", rewards = "Багровый барбютШкуродерМеч морякаВы получите:\n\n"}
MultiLanguageQuestData['ru'][11141] = {title = "aina Must Know", objective = "Поговорите с леди Джайной Праудмур в Тераморе.", description = "Немедленно оповести леди Джайну о том, что нам удалось узнать! Бандиты перевозили пленника, и мы не знаем, кто это и жив ли он или она до сих пор!\n\nНо в одном нет сомнений, <имя>. Эти бандюги в петлю по мелочам не полезут. Наверняка их пленник – очень важная персона. Леди Джайна должна знать об этом больше, чем кто-либо другой. Найди ее на вершине башни магов в центре Терамора.", progress = nil, completion = "Вы с Ренном просто молодцы, что вывели на свет эти сведения и тотчас же доложились мне. Несомненно, Братство Справедливости затевает что-то недоброе против Штормграда и его союзников. Но для них этот замысел уж слишком хитроумен, стало быть, у них где-то завелся богатенький покровитель.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11142] = {title = "urvey Alcaz Island", objective = "Поговорите с Коссой Багровое Крыло и возьмите одного из ее грифонов, чтобы обследовать остров Алькац. После выполнения поручения отрапортуйте леди Джайне Праудмур в Тераморе.", description = "Похоже, догадка Ренна насчет острова Алькац оказалась верной. Нам надо обследовать этот остров, но, чтобы пробиться туда, потребуется целый вооруженный отряд.\n\nОборона Терамора сейчас не может позволить себе такую роскошь, поэтому я договорилась с Коссой Багровое Крыло, ученицей тераморского укротителя грифонов, чтобы она дала тебе одно из своих животных для обследования Алькаца с воздуха.\n\nТолько на острове Алькац можно найти намек на то, что Братство Справедливости причастно к похищению.", progress = "Ты закончил исследование острова Алькац?", completion = "&lt;Леди Джайна внимательно выслушивает ваш доклад по результатам обследования острова Алькац.&gt;\n\nКруг рун, драконид? Я знаю, что в Братстве Справедливости есть тайные маги, но не особенно могущественные, чтобы пользоваться такими вещами!\n\nИ почему черные дракониды вдруг заинтересовались островом, кишащим нагами? Слишком много вопросов без ответов, но в одном я точно уверена: у Братства Справедливости есть сильный союзник в высшем руководстве Альянса.", rewards = "Нарукавники лучникаИскристая чешуйчатая кирасаКинжал с самоцветамиПропахшие болотным газом латные рукавицыВы получите:\n\n"}
MultiLanguageQuestData['ru'][11143] = {title = "Grim Connection", objective = "Доложитесь капитану Дариллу в Северной башне.", description = "Я говорил с инспектором Таремом по поводу информации, добытой тобой на пепелище \"Последнего привала\". Похоже, он уверен, что следы копыт и найденный тобой щит указывают на тауренское племя Зловещего Тотема.\n\nС учетом донесений об их активности на болотах это вряд ли можно считать простым совпадением. Я отправляю тебя к капитану Дариллу, он у нас что-то вроде специалиста по делам этого племени. Из города ступай по дороге на север, к Северной башне. Это вторая застава на дороге.", progress = nil, completion = "Капитан Ваймс считает, что племя Зловещего Тотема повинно в преступлении, совершенном в таверне \"Последний привал\"? Я бы не ставил их первыми в списке подозреваемых, но раз капитан Ваймс прислал тебя для дальнейшего расследования, должно быть, у него были на то причины. В любом случае, племя Зловещего Тотема давно у нас как заноза в пятке, и мы всегда рады принять любую помощь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11144] = {title = "onfirming the Suspicion", objective = "Принесите боевой план племени Зловещий Тотем капитану Дариллу в Северную башню.", description = "Возможно, Зловещий Тотем – самое воинственное из тауренских племен, но они весьма организованы. Если это они подожгли \"Последний привал\", значит, действовали по приказу одного из своих старейшин.\n\nБольшое селение племени – деревня Черного Копыта – находится на северо-западе отсюда. Там и была база для нападений на башню. Могу поклясться – в деревне ты найдешь те самые приказы, которые тебе нужны. Поищи их у старейшин.", progress = "Удалось найти какие-нибудь следы приказов?", completion = "&lt;Капитан Дарилл просматривает боевой план.&gt;\n\nЯ бы сказал, что все яснее ясного. Они берут на себя уничтожение людских поселений в этих краях, и я не сомневаюсь, что следующим в списке будет Терамор.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11145] = {title = "risoners of the Grimtotems", objective = "Сержант Лукас из Северной башни просит вас спасти 5 тераморских пленников.", description = "Мы делаем все возможное, чтобы сдерживать племя Зловещего Тотема, но они так и продолжают нападать на башню. А хуже всего то, что они похитили патрульных, которых наш капитан посылал на поиски информации и охрану дороги.\n\nЯ думаю, что заложников держат в деревне Черного Копыта, она на северо-западе. Зная племя Зловещего Тотема, можно сказать, что ключи от клеток с заложниками наверняка у стражей – защитников поселения. Делай что угодно, <класс>, только верни наших ребят живыми!", progress = nil, completion = "Освобожденные пленники уже возвращаются из деревни Черного Копыта. Информация, которую получит от них капитан, позволит нам лучше подготовиться к следующей битве с племенем Зловещего Тотема.\n\nБлагодарю тебя от себя лично и от имени всех наших солдат.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11146] = {title = "aptor Captor", objective = "Сержант Лукас из Северной башни просит вас поймать 6 ящеров. Вы можете ловить как ящеров Кровавой Топи, так и крикунов Кровавой Топи.", description = "Полоса болот к северо-востоку отсюда - гнездо особенно мерзких ящеров. Из-за них мы потеряли уже не одного беспечного солдата, однако, полагаю, нам удасться натравить их на наших соседей из племени Зловещего Тотема.\n\nВозьми эту веревку и поймай с ее помощью несколько ящеров из Кровавой топи или крикунов из Кровавой топи. Впрочем, я бы не стал пытаться ловить этих тварей, пока не удастся хотя бы немного ослабить их в драке. А драка будет нешуточная.", progress = "Удалось наловить ящеров?", completion = "Видок у тебя малость помятый, но ничего страшного. В любом случае Зловещим Тотемам придется куда круче, когда наши чешуйчатые приятели займутся ими.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11147] = {title = "nleash the Raptors", objective = "Сержант Лукас из Северной башни хочет, чтобы вы положили приманку на ящера близ ветряной мельницы в деревне Черного Копыта.", description = "Так, у нас есть ящеры, теперь их нужно как-то \"воодушевить\" на бой, чтобы они атаковали тауренов из племени Зловещего Тотема в деревне Черного Копыта на северо-западе.\n\nВот тут у меня остатки мяса... э-э... в общем, не важно, чье это мясо. Главное, что оно будет хорошей приманкой. Положи его на землю в деревне Черного Копыта, рядом с мельницей в центре поселка. А об остальном позаботятся ящеры.", progress = nil, completion = "&lt;Сержант не скрывает довольной усмешки.&gt;\n\nВот и славно. Теперь они дважды подумают, прежде чем совершить очередной набег.", rewards = "Гребневый наплечный щитокВам дадут возможность выбрать одну из следующих наград:\n\nФолиант адептаПодвеска свирепости\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11148] = {title = "rms of the Grimtotems", objective = "По просьбе капитана Дарилла из Северной башни принесите ему 7 предметов вооружения из деревни Черного Копыта.", description = "Если обнаруженное тобой на пепелище таверны снаряжение принадлежало воинам из племени Зловещего Тотема, то наверняка в их лагере на северо-западе найдется еще больше.\n\nНам не удалось собрать достаточно информации о деревне Черного Копыта, но, судя по численности нападавших, там базируются значительные силы.\n\nСделай все, чтобы получить их снаряжение и сравнить с найденным у таверны.", progress = "Ты принес вооружение из деревни Черного Копыта?", completion = "&lt;Капитан Дарилл осматривает принесенное вами из деревни Черного Копыта вооружение.&gt;\n\nСомневаться не приходится – вооружение в точности соответствует описанию. Но дело в том, что оно ни разу не побывало в бою. Должно быть, деревня Черного Копыта – не единственный аванпост племени Зловещего Тотема в топях.", rewards = "Костяной кортикКусачий топорБольшой топор жестокостиВам дадут возможность выбрать одну из следующих наград:\n\nКольцо из сверкающего турмалина\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11149] = {title = "abetha's Assistance", objective = "Поговорите с Табетой в ее доме.", description = "В помощь второй заставе племени Зловещего Тотема выделить мне некого, но я, кажется, знаю, кто тебя выручит. \n\nВ самом сердце Трясины, к югу отсюда, стоит маленький домик, хозяйку зовут Табета. На первый взгляд, просто старая отшельница, но на самом деле она волшебница и провидица, причем небезызвестная. Иди по дороге на юг до самого ее дома и попроси Табету помочь найти виновных в преступлении, совершенном в таверне \"Последний привал\".", progress = nil, completion = "Значит, ты хочешь, чтобы я предсказала будущее племени Зловещего Тотема? А если я скажу, что нужды в том нет?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11150] = {title = "aze Direhorn Post!", objective = "Сожгите северную, восточную и северо-восточную палатки на заставе Дикого Рога, затем вернитесь в усадьбу Табеты.", description = "Незачем гадать, чтобы увидеть угрозу, которая исходит от моих \"соседей\". И если это та самая банда, что сожгла \"Последний привал\", как ты говоришь, то нужно действовать немедля.\n\nБери вот этот факел и предай их лагерь огню! Ты найдешь заставу Дикого Рога к северу от моей усадьбы, возле дороги. Пропустить ее совершенно невозможно, эти варвары уже успели наставить вокруг свои драгоценные тотемы.", progress = "Ну что, хорошо разгорелось?", completion = "Надеюсь, племя Зловещего Тотема усвоило урок. Попытаются вернуться – мы их встретим не только факелом. Мои ученики помогут мне дать отпор.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11151] = {title = "ustice for the Hyals", objective = "Поговорите с капитаном Гарраном Ваймсом в цитадели в Тераморе.", description = "Пусть племя Зловещего Тотема досаждало мне немногим, капитан Ваймс захочет послушать о твоих свершениях. Доложи ему, что тебе удалось выследить и уничтожить тех, кто спалил таверну \"Последний привал\".\n\nХоть это и не воскресит семью Джима Хьяля, но, может, племя Зловещего Тотема теперь дважды подумает, перед тем как нападать на тех, кто связан с Терамором.", progress = nil, completion = "&lt;Капитан внимательно выслушивает ваш доклад.&gt;\n\nМы отомстили за Джеймса и его семью, но это их не вернет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11152] = {title = "eace at Last", objective = "По просьбе капитана Гаррана Ваймса из цитадели возложите венок к памятнику семейства Хьяль.", description = "Как бы дать знать жене и сыну Джеймса Хьяля, что мы отомстили их убийцам?\n\n*Капитан Ваймс достает маленький венок.*\n\nГоворят, что души все видят, даже если мы и не можем говорить с ними. Это малость, но если бы вы возложили этот венок на могилу семейства Хьяль, я был бы вам очень благодарен. Это один из самых больших могильных памятников на кладбище к северу от ворот Терамора.", progress = nil, completion = "&lt;Капитан Ваймс мягко улыбается, слушая ваш рассказ о событиях, произошедших у памятника семейству Хьяль.&gt;\n\nПриятно знать, что они все видят. Ты же не рассказал им о Джеймсе, правда?\n\nЯ отправлю ему послание жены, хотя сомневаюсь, что он поймет.", rewards = "Поножи дальней дорогиУбор рыскателяОкованный сталью хауберкЛезвие боевого заклятияХауберк со стальными пластинамиВы получите:\n\n"}
MultiLanguageQuestData['ru'][11153] = {title = "Прорвать блокаду", objective = "Возьмите кассетные бомбы Петрова и сбросьте их на корабли, убив 25 матросов абордажной команды и уничтожив 10 абордажных пушек. Как только задание будет выполнено, вернитесь к бомбардиру Петрову в Крепость Западной Стражи.", description = "Все наши корабли затоплены! Нам нужна твоя помощь, чтобы прорваться сквозь пиратскую блокаду в Пролив Кораблекрушений!\n\nВозьми эти кассетные бомбы и садись на дирижабль, который \"одолжил\" нам Боронайзер. На нем ты пролетишь прямо над палубами этих проклятых пиратов и раздашь им наши подарочки!\n\nТы – наша последняя надежда прорвать блокаду. Надеюсь, тебе удастся разнести их корабли в мелкие щепки!", progress = "А, это снова ты! Неужели тебе удалось прорвать блокаду? Ты ведь показал этим проклятым пиратам Северных морей, где раки зимуют?\n\nТак ведь?", completion = "Именно это я и надеялся услышать! А ты знаешь, что надо делать, Аркоман!\n\nМожет быть, ты заглянешь завтра, когда мы изготовим новую партию бомб? Я бы не стал так долго ждать, но у меня кончилось гуано летучих мышей, а мой помощник Фекнат куда-то запропастился.\n\nИнтересно, что его так задержало?", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11154] = {title = "Пусть обделаются от страха!", objective = "Соберите 10 кусков гуано темнолапых летучих мышей и отнесите их инженеру Фекнату к Стальным воротам.", description = "Эй, ты! Да, ты... иди сюда, мне нужна твоя помощь!\n\nПетров послал меня сюда собирать гуано летучих мышей для кассетных бомб, которые он мастерит в крепости, но я не собираюсь соваться прямо в лапы смерти!\n\nКороче, темнолапые летучие мыши водятся только на Вырубках к северу отсюда, но с этой платформы я сойду только в направлении дома!\n\nА вот ты... ты можешь совершить этот подвиг ради меня! Правда? Ну пожалуйста!!!\n\nВот, держи хлопушки. Основная мысль такова: бросаешь их рядом с летучими мышами, и они гадят от страха!", progress = "Пожалуйста, скажи мне, что ты принес гуано!", completion = "Фу, чем тут воняет? А, это ты! Да, пахучую работенку я тебе подбросил!\n\nСпасибо тебе, |3-6(Маг). Не волнуйся, я сам доставлю груз Петрову, как только мы выберемся отсюда.\n\n&lt;Фекнат кричит исследователям.&gt;\n\nЭй, слышите, парни? Вытаскивайте нас отсюда!!!", rewards = "Поручи ледобояПокрытая льдом накидкаУкрепленный шкурой моржа хауберкРемень кровоплетаВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11155] = {title = "Снова суп из черпорога?", objective = "Шеф-повар Дымкотел поручила вам добыть 6 кусков мяса черпорогов и принести их ей в Крепость Западной Стражи.", description = "После всех этих таинственных исчезновений домашнего скота нам не мешало бы озаботиться припасами. Иначе хищные звери станут нашей последней заботой!\n\nПоскольку я тут несколько занята приготовлением пищи, тебе придется отправиться на восток и поохотиться на черпорогов. Именно их нежное мясо я хочу сегодня приготовить. \n\nСмотри, не попадись им на рога!", progress = "Нет ничего вкуснее нежного мяса черпорога, срезанного с боков!", completion = "А, вот и обед для мальчиков!\n\n&lt;Шеф-повар наклоняется к вам и шепчет на ухо.&gt;\n\nЗнаешь, малыш, тебе тоже не помешает чашка горячей похлебки. Только посмотри на себя – кожа да кости!", rewards = "Вы получите:\n\nСуп из черпорога"}
MultiLanguageQuestData['ru'][11156] = {title = "irehorn Raiders", objective = "Убейте 12 тауренов из племени Зловещего Тотема с заставы Дикого Рога и вернитесь к ученику Морланну в усадьбу Табеты.", description = "Племя Зловещего Тотема с заставы Дикого Рога наглеет день ото дня. По ночам часто слышно, как они горланят песни о своих подвигах на ниве борьбы с теми, кто пытается тут осесть.\n\nОни твердо намерены выгнать нас из домика Табеты, хотя она тут воспитала целое поколение учеников. Мы защищали дом как могли, но ученика Гариона во время последнего нападения ранили.\n\nСтупай на заставу Дикого Рога и перебей всех, кого встретишь! С этим надо покончить!", progress = nil, completion = "&lt;Ученик Морланн кивает.&gt;\n\nЭто хорошо. И не могу сказать, что буду страдать без их общества. А то даже в сердце трясин уединения не найдешь!", rewards = "Мундир геоманта из племени Зловещего ТотемаПлащ разрушителейКушак Дикого РогаВам дадут возможность выбрать одну из следующих наград:\n\nДругая печатка МорланнаПечатка Морлана\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11157] = {title = "В тисках зла", objective = "Уничтожьте 15 яиц протодраконов и 15 детенышей протодраконов, после чего вернитесь к капитану Адамсу в Крепость Западной Стражи.", description = "<имя>, такое поручение я могу доверить только тебе. Нужно уничтожить яйца протодраконов и детенышей протодраконов в горящем лесу на юго-востоке! \n\nС тех пор, как мы прибыли сюда, в Пылающем Гнездовье не стихают пожары. Должно быть, это результат действия какой-то ужасной магии. В последнее время ситуация ухудшилась, и мои люди опасаются, что в ближайшие несколько недель мы все окажемся в огненной ловушке!\n\nОтправляйся туда и устрани угрозу, уничтожив яйца и детенышей протодраконов.", progress = nil, completion = "Отличная работа! Если нам повезет, эти чудовища испугаются за своих детенышей и отступят, остановив распространение магического огня.\n\nПогоди... что это за звук? Похоже на хлопанье крыльев.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11158] = {title = "loodfen Feathers", objective = "Принесите 5 перьев Кровавой Топи Броггу в Шестермуть.", description = "Твоя что, Брогг испугался, крошка <раса>? Не боись. Гоблины Шестермути Броггу друзья, и твоя может быть друг.\n\nБрогг ушел из Гиблотопи, когда наша новый властитель не стал делать мстю черным драконам за то, что они сломали наш старый дом и убили много друзей Брогга. Брогг сюда пришел упокоить души друзей и отомстить, но Броггу надо помогать подготовиться. Для ритуала Броггу надо перья с сильной магией, как у ящеров логова Кровавой Топи на западе от города.", progress = "<Брогг с надеждой смотрит на вас.>\n\nТвоя приносить Броггу перья?", completion = "&lt;Брогг берет перья.&gt;\n\nБрогг довольный этими перьями. Очень сильная магия. Брогг не знает, что делать ящеры, чтобы перья были сильные, но перья ящеров всегда лучшие для ритуала.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11159] = {title = "pirits of Stonemaul Hold", objective = "Брогг из Шестермути просит вас дать покой 10 духам клана Каменного Молота.", description = "Брогг закончил мастерить тотем, который поможет душам его друзей обрести покой. Когда драконоры напали на деревню Каменного Молота, они убили всех, кто не спасся бегством. Брогг бежал вместе с владыкой Мок'Морокком, надеясь повести выживших жителей деревни в контратаку.\n\nДо этого дело так и не дошло, а души убитых с тех пор не дают Броггу и всем остальным покоя. Отнеси этот тотем на север, в руины деревни Каменного Молота, и установи там рядом со скелетами огров, чтобы привлечь духов. Побежденный в бою дух сможет наконец упокоиться с миром.", progress = "Брогг должен знать, принес ли ты покой свирепым духам Каменного Молота?", completion = "Брогг благодарит тебя за помощь, хотя и знает, что от властителя Мок'Морокка ты не дождешься слов благодарности. Но теперь, по крайней мере, выжившие члены клана могут наконец заняться насущными делами, и мертвые им больше досаждать не будут. А Броггу осталось сделать одну вещь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11160] = {title = "anner of the Stonemaul", objective = "Добудьте знамя Каменного Молота и принесите его Броггу в Шестермуть.", description = "Когда пришли драконы и отняли старый дом Брогга, огры Каменного Молота бежали и все бросили, даже знамя клана.\n\nБрогг знает, что знамя хранится глубоко в могильном кургане огров Каменного Молота, но теперь он зовется Огненное логово. Брогг должен получить клановое знамя, чтобы отомстить драконам, которые убили его друзей.\n\nДревний курган клана Брогга, Огненное логово, кишащее драконидами, находится на северо-западе от Шестермути. Знамя глубоко в пещере. Будь осторожнее, <имя>.", progress = "Принес знамя Каменного Молота?", completion = "Брогг тебе благодарен, Putinlox. У Брогга большие планы на клановое знамя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11161] = {title = "he Essence of Enmity", objective = "Принесите 10 сущностей черного дракона Броггу в Шестермуть.", description = "Чтобы сделать тотем для своего ритуала, Броггу понадобятся сущности тех, кто убил его друзей. Ненависть и ярость врагов Брогга придаст мстительной магии еще больше сил.\n\nВыследи огнегривых пеплохвостов, разведчиков или чешуйчатых губителей и поставь тотем Брогга рядом с их телами. Драконы отдают свои сущности только когда умирают.\n\nЛучше всего искать их в Огненном логове на северо-западе или в руинах деревни Каменного Молота на севере.", progress = "Принес сущности? Они нужны Броггу, чтобы отомстить за друзей!", completion = "Ты получаешь благодарность Брогга, Putinlox. Как только Брогг отдает свою магию тотему, тотем освобождает духов убитых друзей Брогга.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11162] = {title = "hallenge to the Black Flight", objective = "Установите знамя Каменного Молота у входа в Логово Ониксии, затем вернитесь к Броггу в Шестермуть.", description = "Брогг лелеет мысль отомстить черным драконам болот. <имя>, ты очень <помог/помогла> в подготовке к этому мероприятию. Хочешь помочь еще?\n\nБери клановое знамя Брогга и поезжай на восток, пока не найдешь пещеру, похожую на драконью пасть. Водрузи знамя Каменного Молота у входа в пещеру и брось Ониксии вызов Брогга!\n\nБрогг и Каменные Молоты вернут себе свою землю!", progress = "Брогг свершит свою месть!", completion = "*Брогг слушает ваш рассказ о том, что произошло у входа в Логово Ониксии.*\n\nБрогг так и знал, что Ониксия побоится биться с тобой. Все черные драконы нападают, только когда победа однозначна.\n\nБрогг благодарен тебе за помощь, Putinlox. Он никогда не забудет, что ты для него сделал. Брогг никогда не отступит от своей цели вернуть Каменный Молот на родину!", rewards = "Огромный капюшон Каменного МолотаБоевая портупея БроггаПочиненные рукавицы борцаЛучшая боевая портупея БроггаВы получите:\n\n"}
MultiLanguageQuestData['ru'][11163] = {title = "Тайная Сестрица", objective = "Доберитесь до Донны Браско, чтобы получить причитающуюся вам награду. Найти Донну можно на Призрачных Землях, сразу за окраиной Зул'Амана.", description = "*Донна подозрительно оглядывается по сторонам и шепчет тебе.*\n\nТо, что я тебе сейчас скажу, должно остаться между нами, смекаешь?\n\nМеня прислали сюда мирохранители Шаттрата, чтобы я проникла в банду Бадда. С самого твоего появления, ты привлек мое пристальное внимание. Но твои действия полностью очистили тебя от всех подозрений. А за то, что ты убил Зул'джина, мне поручено вручить тебе награду.", progress = nil, completion = "*Донна подозрительно оглядывается по сторонам и шепчет тебе.*\n\nТо, что я тебе сейчас скажу, должно остаться между нами, смекаешь?\n\nМеня прислали сюда мирохранители Шаттрата, чтобы я проникла в банду Бадда. С самого твоего появления, ты привлек мое пристальное внимание. Но твои действия полностью очистили тебя от всех подозрений. А за то, что ты убил Зул'джина, мне поручено вручить тебе награду.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11164] = {title = "Клыкастые всадники", objective = "Соберите для Пригмона 10 клыков лесных троллей в Зул'Амане и принесите их ему в лагерь Бадда в Призрачных Землях.", description = "Привет, <чувак/чувиха>, ты тут типа <новенький/новенькая>? Сделаешь для меня одну штуку?\n\nБадд затеял обновить свои личины лесных троллей. Говорит, что уже почти закончил, не хватает одной небольшой детали... Клыков.\n\nМое умение снимать шкуры тут абсолютно бесполезно...\n\nПринесешь мне десяток их клыков, а, <друг/подруга>?", progress = "Поторопись, чувак, Бадд сказал, что пошлет меня в лес проверять действенность его личин, если я не принесу ему эти клыки.", completion = "Ага! Здорово! То, что надо!\n\nВот тебе обещанная награда.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11165] = {title = "Тролль в стане троллей", objective = "Найдите Зунгама и помогите ему выбраться из Зул'Амана.", description = "Послушай, <парень/подруга>, старине Пригмону нужно, чтобы ты <сделал/сделала> еще кое-что.\n\nМой никчемный кузен Зунгам не может выбраться из Зул'Амана. Но тем не менее он жив – прошлой ночью я видел в небе его сигнальную ракету!\n\nСтоило бы конечно, бросить его там, чтобы не втягивал меня в свои дела, но он мне должен нехилую сумму денег.\n\nТак что сделай, что можешь, спаси его шкуру и принеси мне должок!", progress = nil, completion = "Я свободен!\n\nОни меня ободрали как липку, Прынц, когда кинули сюда, - вот последняя моя монетка, тебе за труды.\n\nА мне видно придется пойти по миру...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11166] = {title = "Крестом на карте обозначена... твоя смерть!", objective = "Отправляйтесь в Зул'Аман и посетите чертог Халаззи, платформу Джан'алая и платформу Акил'зона. Заметьте все подробности и по возвращении доложите о них Бадду в его лагере в Призрачных землях.", description = "Нет, ну как они могли провалиться? Идиоты! Говорил я им, будьте осторожнее, и даже выдал им маскировку, чтобы было проще. Ладно, туда им и дорога. Теперь этим делом займешься ты.\n\nЕсли ты добьешься успеха, то я сочту тебя достойным вступить в ряды моей команды, молва о которой скоро прогремит по всему миру. И на меньшее я не согласен.\n\nНам осталось заполнить еще несколько участков на моей карте, и тогда мы сможем начать раскопки.", progress = nil, completion = "*Бадд пытается скрыть свое замешательство.*\n\nЭээ... Да... Прынц. Ты, да... Как раз вовремя. По правде сказать. На тебе сейчас и держится вся операция.\n\nЛадно, давай продолжим разбираться с белыми пятнами на этой карте.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11167] = {title = "Новая чума", objective = "Аптекарь Лисандер из Лагеря Возмездия просит вас собрать 10 неповрежденных флаконов с чумой с места кораблекрушения на юго-востоке.", description = "Вскоре после того, как Артас приговорил нас к этому жалкому существованию, Королевское фармацевтическое сообщество начало разрабатывать штамм новой чумы, которая могла бы растворять любую плоть, будь то человека, животного или нежити.\n\nНедавно мы закончили наши исследования в Подгороде и уже собирались передать готовый штамм Плети, когда в наши планы вмешался Альянс. Он захватил корабль, перевозивший образцы чумы. Поэтому я прошу тебя отправиться на юго-восток, к месту кораблекрушения, и поискать любые сохранившиеся образцы.", progress = "Ты принес флаконы, Визардд?", completion = "Я рад видеть тебя живым и невредимым. Видишь ли, переноска этих контейнеров не абсолютно безопасна – можно было и заразиться. Наверное, мне стоило предупредить тебя об этом.", rewards = "Торжественные перчатки БловельтаШлем власти из шкуры воргаЧешуйчатые перчатки ловкости рукДревние укрепленные набедренникиВы получите:\n\n"}
MultiLanguageQuestData['ru'][11168] = {title = "Добавить крепости", objective = "Принесите 3 гигантские ядовитые железы гигантских прибрежных крабов аптекарю Лисандеру, который будет ждать вас в Лагере Возмездия в Ревущем фьорде.", description = "Похоже, долгое путешествие через море негативно сказывается на эффективности чумы. Нам надо добавить мощный токсин, чтобы усилить воздействие штамма.\n\nМне кажется, что вот эти береговые членистоногие могут быть дальними родственниками мелких темнопанцирных прибрежных крабов. Последние водятся в тропических районах и выделяют столь мощный паралитический яд, что одного укуса хватит на целого огра.\n\nНо мы же знаем – чем больше особь, тем лучше! Возможно, эти гигантские прибрежные крабы будут нам полезны. Принеси-ка мне несколько ядовитых желез!", progress = "Ты принес мне ядовитые железы, Близарджин?", completion = "Я рад нашему сотрудничеству, Близарджин. Надеюсь, этого яда будет достаточно для того, чтобы усилить действие чумы.\n\nВ худшем случае, он хотя бы ослабит организм жертвы и сделает его более восприимчивым к болезни.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11169] = {title = "he Grimtotem Weapon", objective = "Ученик Гарион из усадьбы Табеты хочет, чтобы вы испытали захваченный тотем на 10 крапчатых кроколисках-грязекупах или грязекупах-острозубах.", description = "Во время последней атаки племени Зловещего Тотема меня ранили, но перед этим я успел захватить один любопытный тотем, который враги обращали против нас.\n\nПока шел бой, он будто испускал потоки энергии – но я так до сих пор и не смог понять принцип его работы. Я тебе одолжу этот тотем, если поможешь его испытать.\n\nВ водоемах вокруг фермы водятся крапчатые кроколиски-грязекупы и острозубы-грязекупы. Мерзкие твари. Попробуй сразиться с кроколисками, находясь рядом с тотемом.", progress = "Какие успехи в изучении тотема?", completion = "&lt;Вы подробно рассказываете о ходе эксперимента.&gt;\n\nТуман и молния? И все? Но ведь этот тотем должен вызывать еще какие-то эффекты! Тотем бы не стали нести на поле брани, не будь у него каких-то полезных свойств.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11170] = {title = "Испытания на море", objective = "Поговорите с дрессировщицей нетопырей Камиллой, возьмите ездового нетопыря и летите наперерез войскам Альянса. Когда вы будете пролетать над флотом, сбросьте склянки с чумой и заразите 16 резервистов Северного флота.", description = "Мы только что узнали, что войска Альянса выслали подкрепление. Как раз вовремя! \n\nНам не хватает подопытных особей, а эти резервисты Северного флота как раз подойдут для испытаний!\n\nВозьми эти склянки с чумой и поговори с Камиллой, дрессировщицей нетопырей. Скажи ей, что тебе нужна летучая мышь для специального задания.\n\nКак только окажешься над морем, сбрось склянки на флот Альянса. Интересно будет посмотреть на результат!", progress = "А, вот и ты!", completion = "Хммм...результаты не очень впечатляющие...", rewards = "Рукавицы с морозными узорамиЛазурный плетеный хауберкУкрашенные рогами наплечникиВам дадут возможность выбрать одну из следующих наград:\n\nРуническое колье из раковины\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11171] = {title = "Повелитель Проклятий? Пффф!", objective = "Убейте в Зул'Амане повелителя проклятий Малакрасса и вернитесь к Бадду Недреку на Холмы Томагавков.", description = "Отлично! Скоро мы триумфально войдем в Зул'Аман.\n\nТы выложился по полной для общего дела, <имя>, и я говорил со своими ребятами - они не возражают против тебя. Так что ты заслужил свое место в команде. Осталась одна небольшая заминка. Ты должен убить, этого, как его... повелителя проклятий. Ничего страшного, тебе стоит посмотреть ему в глаза, и он бросится наутек. Старые, бессильные тролли часто прибавляют к своему имени громкие титулы, чтобы скрыть свою беспомощность...", progress = nil, completion = "Наконец-то! Теперь, когда вся подготовка закончена, я впишу свое имя в историю! Но перед этим... У меня осталось еще одно незавершенное дело, - ты...\n\nБоюсь, Таквер, пришло время отпустить тебя. Я знаю, то чего ты здесь достиг, - это далеко не предел...\n\nНе страдай понапрасну. В конце концов, для таких приключений нужно обладать определенным складом характера... чтобы не растерять последние мозги, понимаешь? И, смотри, у меня есть тебе небольшая безделушка, будем считать, что это на память.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11172] = {title = "he Zeppelin Crash", objective = "Поговорите с Мокси Сталегриль на месте крушения дирижабля Бизила.", description = "Не так давно к востоку отсюда разбился гоблинский дирижабль.Несколько дней назад в ту сторону проезжала представительница картеля Хитрой Шестеренки.\n\nОна искала информацию о судьбе груза с дирижабля и его пилота, Бизила, но никто из нас на месте крушения не был. Сомневаюсь, что она самостоятельно подчистит обломки. Еще менее вероятно, что она получит груз, который переправлял дирижабль.\n\nЕсли есть время, сходи к ней на место крушения дирижабля Бизила, прямо на востоке отсюда, возле гор.", progress = nil, completion = "Так тебя прислали маги-отшельники? Почем мне знать, что тебе можно доверять?\n\nХотя помощь-то мне как раз не помешает, но вот магам это совершенно не интересно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11173] = {title = "he Reagent Thief", objective = "Принесите 6 флаконов болотного яда ученику Гариону в усадьбу Табеты.", description = "Что ученик Морланн действительно умеет делать, так это скулить о нехватке реагентов.\n\nОбычно я его нытье мимо ушей пропускаю, но это не всегда помогает! На сей раз я заткну его другим способом.\n\nМожет, если незаметно подбросить недостающий реактив, он от меня отвяжется. Наш самый распространенный реактив – болотный яд, который получают из ползунов-темножвалов и пагубных живорезов, обитающих в болотах к северу от усадьбы. Принесешь яда, и я подолью его, пока Морланн не видит.", progress = "Удалось добыть яд? Морланн в любую минуту может спохватиться, что его не хватает...", completion = "&lt;Ученик Гарион изучает яд.&gt;\n\nПросто прекрасные образцы! Он и не отличит.", rewards = "Убор странникаЗачарованный плащЗакаленный лук болотного лесаВы получите:\n\n"}
MultiLanguageQuestData['ru'][11174] = {title = "orrosion Prevention", objective = "Мокси Сталегриль хочет, чтобы вы уничтожили 10 слизнюков и доложили ей о выполнении задания на месте крушения дирижабля Бизила.", description = "Ты только посмотри! Слизнюки прям кишмя кишат. Если с ними не покончить, сожрут и обломки, и груз с дирижабля!\n\nА я не могу вернуться ни с чем, <класс>! Помоги мне разогнать этих слизнюков, пока они тут все не понадкусывали!\n\nЕсли включить это устройство, оно направит энергию на слизнюков, и они начнут взрываться. Разбитый энергетический сердечник дирижабля подпитает устройство. Тот кусок, что рядом с местом крушения, работает стабильно, остальные – не особенно.", progress = "Ну как, тебе уже удалось покончить со слизнюками?", completion = "Ну, похоже, там и правда стало немного почище...\n\nПолагаю, пора заняться делом и основательно порыться в обломках.", rewards = "Перчатки с кобальтовыми нитямиМундир болотного тюремщикаНержавеющий воинский поясЗаржавевший шлемВы получите:\n\n"}
MultiLanguageQuestData['ru'][11175] = {title = "Дочка моя", objective = "Старик Каменная Мантия попросил вас найти его дочку, надзирательницу Ирену Каменная Мантия в Стальных воротах.", description = "Скажи, это правда, что все исследователи, отправившиеся в Шепчущую теснину, сошли с ума?\n\nМоя дочка работает надзирательницей в Лиге исследователей, и ее группа отправилась куда-то на север, к месту, которое называется Стальные ворота. Честно говоря, после всех ужасных событий, обрушившихся на нас, я опасаюсь за ее безопасность. \n\nПрошу тебя, <класс>, найди Ирену и убедись, что с ней все в порядке. Я уже стар, и мне не по силам совершить такое путешествие.", progress = nil, completion = "Грр! Так я и знала! Трясется надо мной, как курица над цыпленком. Стыдно-то как!\n\nНет, ты только не подумай, что я тебе не рада... наоборот! Мы все рады тебя видеть. Нам так нужна твоя помощь!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11176] = {title = "Присматривая за работой", objective = "Надзиратель Ирена Каменная Мантия попросила вас поговорить с главным археологом Стальных ворот.", description = "Наша работа здесь только начинается, но с прибытием летающих машин из Крепости Западной Стражи дела пойдут веселее.\n\nПроблема в том, что нам не хватает опытных пилотов. Хуже того, на Вырубках к северу отсюда начались какие-то проблемы, так что мне бы хотелось побыстрее закончить дела и отправиться домой. \n\nЕсли хочешь помочь нам, поговори с одним из главных археологов. Они сейчас осматривают ветролеты к северу и югу от раскопок.", progress = nil, completion = "Тебя Ирена прислала, да? Отлично! У нас найдется для тебя работа.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11177] = {title = "he Hermit of Swamplight Manor", objective = "Поговорите с Ярлом \"Болотным глазом\" в сторожке \"Болотный огонек\".", description = "Есть тут один старикашка по имени Ярл. Его называют \"Болотный глаз.\" Живет на болоте. Не так давно он \"унаследовал\" сторожку \"Болотный огонек\", когда ее предыдущий хозяин пропал при таинственных обстоятельствах.\n\nМне нужен тот, кто будет периодически проверять, что там происходит у этого \"Болотного глаза\". Знаешь, он мне чем-то напоминает моего деда. Тоже чуток не в себе, мягко говоря.\n\nИди на северо-запад по дороге из Терамора. \"Болотный огонек\" стоит на Ведьмином холме, как раз перед тем поворотом, где дорога уходит на запад.", progress = nil, completion = "Убирайся с моей лужайки... хотя нет, погоди... Может, поможешь старому \"Болотному глазу\" приготовить обед? Ну как, согласен?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11178] = {title = "Кровь Вождя", objective = "Принесите кровь Зул'джина Бадду в его лагерь в Призрачных Землях. За пределами Зул'Амана.", description = "Пока ты изучаешь пульсирующий фиал, твои мысли обращаются к маленькому, вздорному человечку за стенами Зул'Амана.\n\nПодумать только, какое лицо будет у Бадда, когда он это увидит.", progress = "*Бадд пытается скрыть свое недовольство при виде тебя.*\n\nОпять ты...\n\nЯ не знаю, как еще тебе это сказать, - короче я сейчас слишком занят подготовкой, чтобы возиться еще и с тобой.\n\nПоверь мне. Таквер. Это все для твоего же блага. Возможно. Когда-нибудь твое имя будет известно повсюду. Тогда ты сможешь с гордостью говорить, что начинал под руководством несравненного Бадда Недрека!", completion = "К-кровь самого Зул'джина?\n\n*Собравшись, Бадд продолжает.*\n\nХмм... Ну хорошо, я ценю твои усилия, |3-6(Друид), но сам бы я наверняка справился с этим гораздо быстрее. Быть того не может, чтобы он был настолько страшен, как врут старые сказки. В конце концов, понимаешь, что все эти легенды и побасенки всегда преувеличивают. Скорее всего этот старый идиот помер сам от артрита или чего-то в этом роде.\n\nВ любом случае, это был тот минимум, которым ты мог отплатить за проявленную к тебе здесь доброту.\n\nТеперь иди, я должен разобраться с этим мерзким фиалом.", rewards = nil}
MultiLanguageQuestData['ru'][11179] = {title = "У Финлея кишка тонка", objective = "Соберите 7 безупречных кишечных струн туманных саблезубов для Финлея Флетчера из Крепости Западной Стражи.", description = "У нас так много лучников! И кто же должен следить за состоянием их оружия? Я, Финлей Флетчер!\n\nКомандир приказал мне и моим помощникам подготовить Крепость Диккор к походу, а у меня не было времени выбраться наружу и добыть кишечные струны, из которых изготавливается тетива. \n\n<класс>, <миленький/миленькая>, принеси мне несколько кишечных струн! Их можно добыть с туманных саблезубов, которые бродят возле фьорда. Только не тащи какие попало – мне подойдут только самые лучшие! Рваные кишки никуда не годятся.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11180] = {title = "Что таится на Ведьмином холме?", objective = "Моргант Мрачник из сторожки \"Болотный огонек\" хочет, чтобы вы добыли информацию у 10 восставших мертвецов или духов.", description = "Я приехал сюда навестить Ярла в его новом доме и с тех пор живу в постоянном кошмаре! С этим местом что-то неладно, наверняка не я один замечаю...\n\nТы <видел/видела> призраков и неупокоенных мертвецов вокруг Ведьминого холма? Чую, если кто и знает, что тут творится, так это они. Разыщи в окрестностях восставших мертвецов и духов, отправь их в бою на вечный покой – и посмотрим, что нам удастся выяснить, прежде чем зло окончательно сожрет Ярла!", progress = "Что тебе удалось узнать от здешних неупокоенных духов?", completion = "*Моргант достает листок бумаги и перо и набрасывает какие-то заметки по ходу вашего рассказа.*\n\nСудя по твоим словам, духами этого места должны стать все, кто тут когда-либо жил, и не только прежние владельцы.\n\nЧто-то завладевает ими и убивает их. Те, кто приезжает на это место, узнает правду слишком поздно. Мы должны положить этому конец, Анимантикс!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11181] = {title = "Ведьмина погибель", objective = "Принесите 9 ростков ведьминой погибели Морганту Мрачнику в сторожку \"Болотный огонек\".", description = "За долгие годы работы травником я часто видел, как природа сама незаметно решает самые неприятные проблемы. Я читал, что тайные маги и знахари часто изгоняют зло дымом травки, называемой ведьмина погибель.\n\nЕсли это так, то ведьмина погибель должна расти неподалеку, на мелководье близ Ведьмина холма. Ты узнаешь ее по широким листьям и красноватому стеблю. Принеси мне травы, сколько найдешь, <имя>. Может, это наша единственная надежда.", progress = "Ну как, удалось набрать травы? Действовать нужно быстро, пока зло окончательно не завладело этим местом.", completion = "&lt;Моргант принимает у вас пучок травы.&gt;\n\nЭто растение в точности соответствует описанию! Я подготовил факел, пока тебя не было. Осталось только прикрепить траву вот сюда.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11182] = {title = "В поисках первопричины", objective = "Убить 5 укротителей из клана Укротителей драконов и Скелда Сына Дракона. Если вам удастся выполнить это задание, вернитесь к древу Пылающего Гнездовья.", description = "Все в мире стремится к равновесию, и помешать этому могут лишь те, кому неведома великая гармония природы. \n\nТы зря тратишь свое время, убивая драконов и их детенышей. Истинная причина распространения магического пожара – недавно пробудившиеся врайкулы во главе с их повелителем, Скелдом Сыном Дракона.\n\nЕсли ты жаждешь обагрить свои руки кровью, начни с них. Ты найдешь логово врайкулов на южной стороне Пылающего Гнездовья.", progress = "Как твои дела, малыш? Удалось ли тебе справиться с этими назойливыми тварями?", completion = "К несчастью, я вынужден был послать одного хищника, чтобы тот убил другого, но таков естественный порядок вещей. \n\nВозможно, теперь протодраконы и их детеныши смогут вернуться к спокойной жизни. Меня беспокоят только пробужденные врайкулы.", rewards = "Усиленный кварцем наплечПоручи мерзлого камняНаделенные магией наручиВам дадут возможность выбрать одну из следующих наград:\n\nПерстень из черного железа\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11183] = {title = "Очищение Ведьминого холма", objective = "Моргант Мрачник из сторожки \"Болотный огонек\" хочет, чтобы вы установили факел в конце дока и сразились с тем, что выйдет на свет.", description = "Факел готов. Установи его в конце доков и готовься к сражению со всем, что на тебя полезет.\n\nПонятия не имею, кого именно вспугнет дым факела... если вообще хоть что-то появится. Короче, я не очень верю в эту народную магию, но ни на что другое у нас просто времени нет. Желаю удачи и тебе, и Ярлу.", progress = "Все позади?", completion = "Получилось?\n\n*Моргант прокашливается.*\n\nТо есть... получилось! Мы с Ярлом перед тобой в долгу, Анимантикс. Единственной проблемой осталась разборчивость моего приятеля в мебели, и, боюсь, ее так просто я не решу.", rewards = "Дорожный мундир МоргантаЦветастый ремень МрачникаЧешуйчатые болотные сапогиВы получите:\n\n"}
MultiLanguageQuestData['ru'][11184] = {title = "ANTED: Goreclaw the Ravenous", objective = "Уничтожьте Кровокогтя Ненасытного и сообщите об этом Драззиту Кранотеку, который находится в Шестермути.", description = "Путешественникам и персоналу Хитрой Шестеренки, работающему в поле, рекомендуется держаться подальше от логова Кровавой Топи, что к западу от города.\n\nМестность кишит ящерами, а верховодит ими очень злой и хитрый Кровокоготь Ненасытный – он уже убил по меньшей мере двух инженеров Хитрой Шестеренки.\n\nДраззит Кранотек назначил щедрое вознаграждение тому, кто избавит Шестермуть от этой напасти.", progress = nil, completion = "Хвала небесам, наконец кто-то откликнулся на это объявление! Я уж думал, что придется утроить награду за голову этого дурацкого ящера, а наш бюджет такого не потянет!", rewards = "Набедренники из шкуры ящераЗащитные поножи инженераВам дадут возможность выбрать одну из следующих наград:\n\nКольцо ока хищника\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11185] = {title = "he Apothecary's Letter", objective = "Отнесите запечатанное письмо привратнику Анделло в усадьбу Табеты.", description = "Это письмо, найденное при аптекаре Отрекшихся, говорит о тесном союзе племени Зловещего Тотема и новых хозяев Лордерона.\n\n\"В качестве демонстрации доброй воли и в знак новообретенного доверия мы посылаем вам в помощь аптекаря Силлу. Она посодействует в битве против нашего общего врага в Калимдоре. Никто не устоит перед нашей объединенной мощью и решимостью.\"\n\nПисьмо надо доставить агенту ШРУ Анделло Портеру в усадьбу Табеты.", progress = "Что там у тебя, |3-6(Друид)?", completion = "&lt;Анделло читает письмо, потрясенный его содержанием.&gt;\n\nМы давно подозревали, что Орда и Отрекшиеся в союзе, и это письмо подтверждает наши подозрения. При помощи магии и оружия Отрекшихся племя Зловещего Тотема станет еще более страшным врагом. Баланс сил в Калимдоре может сильно измениться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11186] = {title = "igns of Treachery?", objective = "Доставьте запечатанное письмо Назиру Кровавому Копью в Деревню Гиблотопь.", description = "Это письмо, найденное при аптекаре Отрекшихся, говорит о тайной связи племени Зловещего Тотема и Подгорода.\n\n\"В качестве демонстрации доброй воли и в знак новообретенного доверия мы посылаем вам в помощь аптекаря Силлу. Она посодействует в битве против нашего общего врага в Калимдоре. Никто не устоит перед нашей объединенной мощью и решимостью.\"\n\nВозможно, Назир Кровавое Копье из деревни Гиблотопь знает, как распорядиться этой информацией.", progress = "Что там у тебя, |3-6(Паладин)?", completion = "Если все и вправду так, то Отрекшимся придется объясниться!\n\nТаурены из племени Зловещего Тотема своими выходками давно испытывает терпение вождя. Мы обычно оставляли такие дела улаживать самим тауренам, но это письмо может все изменить.\n\nЭти подозрения еще надо проверить, так что никому не рассказывай о том, что видел сегодня.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11187] = {title = "Маг-лейтенант Малистер", objective = "Капитан Адамс попросил вас поговорить с его советником, магом-лейтенаном Малистером. Его можно найти в Крепости Западной Стражи.", description = "КАКОЙ УЖАС! Протодраконы напали на крепость!\n\nОбычно таких зверей легко отпугнуть, расправившись с их кладкой и детенышами.\n\nНо мы ведь все это уже испробовали, верно?\n\n<имя>, придется нам действовать более решительно. Поговори с моим советником, магом-лейтенаном Малистером. Он расскажет тебе, как разделаться с этими тварями.", progress = nil, completion = "&lt;Малистер подзывает вас к себе и приглушенно шепчет.&gt;\n\nЭтого-то я и боялся. Я пытался отговорить капитана, но он предпочитает сначала действовать, а потом думать.\n\nЛадно, давай посмотрим, что нам остается делать.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11188] = {title = "Минус на минус", objective = "Маг-лейтенант Малистер из Крепости Западной Стражи поручил вам уничтожить 3 протодраконов.", description = "Теперь, когда мы разворошили гнездо протодраконов в Пылающем Гнездовье, они будут постоянно нападать на крепость. Этого мы не можем допустить.\n\nЯ, конечно, не люблю вышибать клин клином, но в данном случае нам остается только уничтожить этих созданий. Мне жаль, но другого пути нет. \n\nВозьми мою волшебную палочку. Вообще-то я пытался увеличить радиус ее действия, но ничего путного не вышло. Однако теперь она отлично привлекает внимание протодраконов.", progress = nil, completion = "&lt;Маг-лейтенант тяжело вздыхает.&gt;\n\nДа, нелегкая тебе выпала доля. Ну, ладно – что сделано, то сделано. Надеюсь, новое поколение протодраконов из Пылающего Гнездовья не запомнит то, что мы с ними совершили.\n\nА если нам повезет, границы магического леса не будут расширяться.\n\nВот, Reng, возьми этот скромный сувенир из нашей сокровищницы. Это самое малое, что мы можем для тебя сделать.", rewards = "Фиолетовое одеяние восполненияОбшитые железом поножиРемень двойного плетенияБлаготворный шлемВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11189] = {title = "В последний раз", objective = "Сопроводите привидение исследователя Джарена к надзирательнице Ирене Каменная Мантия в Стальные ворота Ревущего фьорда.", description = "Привет. Я что, умер? Судя по тому, что я болтаюсь над собственным телом, это действительно так.\n\nМда, какая жалость. Только я собрался сделать предложение Ирене, как на нас напали солдаты Плети. \n\nНо я знаю, что она все еще жива... я чувствую это. \n\n<класс>, не <мог/могла> бы ты проводить меня к ней? Плеть все еще может видеть мою душу, и мне страшно даже подумать, что они могут со мной сделать. \n\nА мне бы так хотелось в последний раз взглянуть на ее прекрасное лицо. Прошу тебя, передай ей, что я ее люблю.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11190] = {title = "К каждой пушке затычка", objective = "Канонир Эли поручил вам собрать 10 пушечных ядер и отнести их в Крепость Западной Стражи.", description = "Вот скажи мне, $Gдружище:подруга;, какому умнику пришла в голову светлая мысль сделать наши пушки нестандартного размера? Теперь нам приходится изготавливать особые ядра каждый раз, когда кому-нибудь приспичит выстрелить из этой поганой штуковины! \n\nСлушай, я был бы тебе очень благодарен, если бы ты <походил/походила> вокруг и <собрал/собрала> уже использованные снаряды. Судя по тому, как стреляют наши пушки, земли к югу и востоку отсюда должны быть просто усеяны боеприпасами. \n\n<Канонир разводит ладони, показывая, какого размера должны быть ядра.>\n\nЕй-богу, проще собрать их, чем отливать новые!", progress = "Этак у нас скоро совсем не останется ядер, |3-6(Маг). А враги наши не спят, особенно в Скорне!\n\nНу теперь-то нам есть, чем стрелять, правда?", completion = "Слава тебе, Reng, вечная слава!\n\nСложи их прямо там, где стоишь. Я поручу нашим ребятам загрузить их в пушки, и скоро нам можно будет не волноваться о количестве ядер – хватит всему Скорну!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11191] = {title = "his Old Lighthouse", objective = "Поговорите с Бабс Шипокруткой на маяке на острове к востоку от Терамора.", description = "Старый маяк к востоку отсюда некоторое время не работал, но Бабс Шипокрутка вбила себе в голову, что надо туда залезть и снова его зажечь.\n\nНе знаю, как у нее это выйдет, но она говорит, что от этого судам будет легче входить в гавань и доставлять товары с борта на склады, поэтому я не против. Дежурить в доках – работенка непыльная, особенно по сравнению с передовой, не так ли?", progress = nil, completion = "Хорошо. Мне понадобится твоя помощь. Первым делом необходимо снова зажечь фонарь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11192] = {title = "hresher Oil", objective = "Принесите 4 контейнера жира крепкозуба Бабс Шипокрутке на маяк близ Терамора.", description = "Старый журнал, найденный на маяке, указывает, что фонарь заправляли жиром крепкозубов, обитающих вдоль здешнего побережья.\n\n<Бабс морщит нос от одного упоминания о такой устаревшей технологии.>\n\nНу, решение практичное, хотя и неизящное. В журнале говорится, что лучше всего брать жир самых молодых черных крепкозубов, а они обитают прямо в доках Терамора.\n\nЕсли ты не против, может, добудешь топливо для маяка?", progress = "Тебе удалось добыть жир крепкозуба?", completion = "Ну, хотя у меня и есть сомнения на этот счет, но сейчас это лучшее решение. Как только мы зажжем маяк, у нас наверняка найдется время подыскать другое топливо для фонаря.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11193] = {title = "astardly Denizens of the Deep", objective = "Отнесите книгу \"Подлые обитатели глубин\" в доки Терамора и отдайте \"Весельчаку\" Ленни Полечуду.", description = "Этот старый маяк – просто сокровищница! Чего здесь только ни найдешь! Вот, например, эта книга. Лежала в одном из старых сундуков.\n\n<Бабс берет книгу и читает название.>\n\n\"Подлые обитатели глубин\"!\n\nЯ, наверное, просто умру от восторга, если увижу воочию хотя бы одного. Да и книжица, думается, забавная. Но у меня сейчас просто нет времени читать.\n\nОднако я знаю, кого она может порадовать... Торговца рыбой из доков, Ленни Полечуда по прозвищу \"Весельчак.\" Он коллекционирует старые книги.", progress = "Что сегодня берем? Рекомендую морскую щуку.", completion = "Какая Бабс заботливая... помнит, что я собираю книги. Да и книга отличная. Ты сам-то ее пролистал? Там, кстати, немало правдивых историй. Да, моряки любят приврать, но не все их рассказы – выдумки.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11194] = {title = "s it Real?", objective = "Поговорите с Натом Пэглом в лагере Ната, что в Пылевых топях.", description = "О, да я уверен, что вы с Бабс животики себе надорвали, читая эти чужеземные описания да разглядывая картинки в книге. А вы не подумали о том, что в легендах есть доля истины?\n\nТы удивишься, но моряки на полном серьезе говорят о Тетуре, морском существе, которое, как написано в книге, живет прямо здесь. Ну, а если ты хочешь точно знать, то всегда можно спросить старину Ната Пэгла.\n\nОн живет в маленьком рыбацком лагере на островке в заливе Яростных волн, это если плыть на юго-запад через Пылевую бухту.", progress = nil, completion = "Так ты хочешь послушать о морских монстрах? Хм... Ну что ж, хорошо, но для этого потребуется море выпивки, а тебе потом будет немного стыдно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11195] = {title = "Игра в куклы", objective = "Отнесите потрепанную куклу вуду Жулю в Шаттрат.", description = "Я, наверное, сошел с ума, <имя>, вот в чем штука-то. Не помню, когда кто-то последний раз кто-то помогал Зунгаму за просто так.\n\nЯ стянул это у одного из дикарей, которые меня тут приковывали. На вид, штуковина неказистая, но тот, кто согласиться ее принять, будет мне хорошим другом!\n\nУж если мне свезет выбраться отсюда живым и непотресканным, я, пожалуй, стаскал бы эту штуку в Шаттрат и показал бы ему.", progress = "Здорово, Таквер! Слыхал я, ты прибился к команде Бадда. Дело хорошее, жалеть не придется, обещаю.\n\nЧто это у тебя?", completion = "Ты где это надыбал?\n\nНет, не говори мне, не хочу знать... Эта штука принадлежит повелителю Проклятий. Теперь все ясно. Мощная штука. Того, у кого есть такая фиговина, неважно, как бы нищ он при этом не был, - уважают. Глазам своим не верю! \n\n*Пока Грифтах держит куклу в воздухе, небольшой ржавый амулет срывается с его шеи. Тролль пытается отбросить его, но потом поднимает на тебя горящие глаза.*\n\nСейчас у меня монет нету, но я бы не отказался, заполучить эту штуку.", rewards = "Вы получите:\n\nЗачарованный самоцвет Амани"}
MultiLanguageQuestData['ru'][11196] = {title = "Вождь Амани", objective = "Победите нового вождя племени Амани, Даакару.", description = "Племя Амани собирает силы, и теперь у них новый вождь, <имя>. Его зовут Даакара Непобедимый. Но мы еще посмотрим, поможет ли ему выжить его имя.\n\nСначала разберись с его лейтенантами, чтобы никто тебе не мешал. А затем переходи к Даакаре. Уничтожь его и положи конец всем притязаниям племен Зандалар и Амани!", progress = "Этот новый вождя должен быть убит прежде, чем племя Зандалар обоснуется здесь.", completion = "Победа будет за нами, Ренгольд. Без вождя тролли племени Амани быстро сами перебьют друг друга.", rewards = "Одеяния инакомыслящегоНаплечье честолюбияВам дадут возможность выбрать одну из следующих наград:\n\nЗульский метательный топор\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11198] = {title = "Сразить Тетура!", objective = "Майор Миллз из доков Терамора хочет, чтобы вы покончили с Тетуром.", description = "Чудовище, не чудовище – мы не можем рисковать безопасностью морских перевозок. Я приказал лучшим стрелкам приготовиться к бою с Тетуром. Артиллеристы усилили оборону доков тремя мортирами.\n\nЯ готов отдать приказ зажечь маяк. Если Тетур пойдет в атаку, твоя задача стрелять из мортир и прикончить тварь, прежде чем она уничтожит всех наших стрелков. При этом я не советовал бы долго стоять на одном месте. Стрельба из мортир обязательно привлечет его внимание.", progress = nil, completion = "Отличная работа, Паладиньдинь! Признаюсь, когда я впервые увидел эту тварь, я засомневался, что мы сумеем защитить доки, но ты блестяще скоординировал действия защитников!", rewards = "Багровый мундирНаплеч быстрого ветраЗолотой шлемБашня ТерамораГарпун морской твариВы получите:\n\n"}
MultiLanguageQuestData['ru'][11199] = {title = "Доклад разведчика Ноулса", objective = "Капитан Адамс попросил вас разыскать разведчика Ноулса у Тлеющей башни.", description = "Теперь, <имя>, когда мы разобрались с этими проклятыми прототварями, я хочу поручить тебе другое задание. \n\nОдин из моих разведчиков доложил о некоей подозрительной деятельности Отрекшихся на юге. Похоже, что они обосновались в врайкульской деревне Халгринд и строят некие зловещие планы.\n\nЯ надеюсь, что ты лично займешься расследованием этого дела. Поговори с разведчиком Ноулсом, выясни, что ему удалось узнать, и начинай действовать.\n\nПоследний раз он докладывал свое местоположение у Тлеющей башни, к западу от Халгринда.", progress = nil, completion = "Наконец-то, помощь прибыла!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11200] = {title = "ore than Coincidence", objective = "Крог из Деревни Гиблотопь хочет, чтобы вы принесли ему 7 предметов оружия Черного Копыта.", description = "Мы выяснили на пепелище гостиницы все, что могли. Боюсь представить, куда нас заведет это расследование, но мы должны узнать правду.\n\nСледы копыт и щит с клеймом Мозарна дают повод полагать, что в это дело может быть замешано племя Зловещего Тотема. Они недавно построили на болотах, к северо-востоку отсюда, поселение, деревню Черного Копыта. Отправляйся туда и поищи еще какое-нибудь оружие работы Мозарна.", progress = "Что тебе удалось найти в деревне Черного Копыта?", completion = "&lt;Крог разглядывает оружие, которое вы принесли из деревни Черного Копыта.&gt;\n\nЭто, несомненно, работа Мозарна. Если мы учиним ему допрос, это привлечет слишком много внимания, но вот с племенем Зловещего Тотема мы можем вести себя посвободнее.", rewards = "Костяной кортикКусачий топорПлащ Зловещего ТотемаВам дадут возможность выбрать одну из следующих наград:\n\nКольцо из сверкающего турмалина\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11201] = {title = "he Grimtotem Plot", objective = "Принесите боевые планы племени Зловещего Тотема Крогу в деревню Гиблотопь.", description = "Теперь, когда дела племени Зловещего Тотема в Тысяче Игл стали известны всем, многие таурены начали косо на них поглядывать. Мы знаем, что вожди племени замешаны в убийстве и похищениях ради своих целей, и я опасаюсь, что следующей их мишенью станем именно мы.\n\nДеревня Черного Копыта, что на северо-востоке рядом с Синей топью, новое крупное поселение племени Зловещего Тотема. Их старейшины получают приказы из Громового Утеса. Сумеешь перехватить приказы и выяснить, что они задумывают?", progress = "Удалось найти какие-нибудь следы приказов?", completion = "&lt;Крог читает боевые планы.&gt;\n\nВ том, что Зловещий Тотем двинется на людей, сомнений нет. Но что они замышляют против нас? Действия этого племени давно вызывают беспокойство в рядах Орды, но вождю до сих пор удавалось рассеивать его.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11202] = {title = "Задание: вечный огонь", objective = "Разведчик Ноулс посоветовал вам воспользоваться неугасимыми факелами, чтобы уничтожить четыре контейнера с чумой, окружающих Халгринд.", description = "Насколько мне известно, Отрекшиеся задумали нечто недоброе, и эти контейнеры с чумой имеют прямое отношение к их зловещим планам. \n\nОсмелюсь предположить, <имя>, что нам следует уничтожить эти ящики прежде, чем Отрекшиеся смогут ими воспользоваться. Я взял на себя смелость принести несколько факелов из Пылающего Гнездовья. Эти штуки горят уже несколько дней!\n\nВот, возьми – у тебя лучше получится поджечь эти контейнеры.", progress = nil, completion = "Отлично!\n\nНо что нам делать с этими штуками, которые ты нашел в контейнерах? Неужели Отрекшиеся действительно распространяют чуму среди врайкулов?", rewards = "Тисненый ремень из шкуры горностаяИнкрустированные костью наручиМагданский наплечРунический латный шлемВы получите:\n\n"}
MultiLanguageQuestData['ru'][11203] = {title = "eek Out Tabetha", objective = "Поговорите с Табетой в ее доме на Трясине.", description = "Оружие, которое ты <захватил/захватила> в деревне Черного Копыта, никогда не видело других сражений, кроме тренировочных боев. А это говорит о том, что Зловещих Тотемов, разоривших \"Последний привал\", еще много.\n\nНа юге, в самом сердце Трясины, живет ведьма Табета. Хоть она и человек, но ведет себя с нами по чести и даже воспитала некоторых наших магов.\n\nПопроси у нее помощи в поисках виновных из племени Зловещего Тотема, которые сожгли таверну. Альянс должен знать, что мы не замешаны в этом преступлении.", progress = nil, completion = "&lt;Табета улыбается.&gt;\n\nЗначит, Крог хочет знать, где сейчас племя Зловещего Тотема? Что ж, магия для этого не понадобится.\n\nПохоже, это наш общий враг. Воины племени Зловещего Тотема построили неподалеку отсюда форпост и стали постоянной угрозой для меня и моих учеников.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11204] = {title = "eturn to Krog", objective = "Поговорите с Крогом в деревне Гиблотопь.", description = "Надеюсь, хоть чем-то тебе помог. Жаль, больше ничего не могу рассказать. Я со своими учениками делаю столько оружия, что вспомнить одну какую-то вещь уже просто невозможно.\n\nМы поставляем вооружение не только славным защитникам земель тауренов. Моими услугами пользуется и племя Зловещего Тотема. Опытным воинам достаточно одного взгляда, чтобы оценить качество моей работы.", progress = nil, completion = "Он сказал, что племя Зловещего Тотема – его основные покупатели? Мозарн помог нам гораздо больше, чем ему кажется. Думаю, благодаря ему у нас появились главные подозреваемые.", rewards = "Багровый барбютШкуродерМеч морякаВы получите:\n\n"}
MultiLanguageQuestData['ru'][11205] = {title = "aze Direhorn Post!", objective = "Сожгите северный, восточный и северо-западный шатры на заставе Дикого Рога, затем вернитесь в усадьбу Табеты.", description = "Незачем гадать, чтобы увидеть угрозу, которая исходит от моих \"соседей\". И если это та самая банда, что сожгла \"Последний привал\", как ты говоришь, то нужно действовать немедля.\n\nБери вот этот факел и предай их лагерь огню! Ты найдешь заставу Дикого Рога к северу от моей усадьбы, возле дороги. Пропустить ее совершенно невозможно, эти варвары уже успели наставить вокруг свои драгоценные тотемы.", progress = "Ну что, хорошо разгорелось?", completion = "Надеюсь, племя Зловещего Тотема без труда поймет, что им хотели сказать.\n\nА что касается тебя, то твой осведомитель в деревне Гиблотопь захочет узнать, каковы твои успехи. Я понимаю, что разрушение таверны \"Последний привал\" может вызвать напряжение между Ордой и Альянсом. Если я встречу следователей из Терамора, то с радостью сообщу, что племя Зловещего Тотема действовало по собственной инициативе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11206] = {title = "ustice Dispensed", objective = "Вернитесь к Крогу в деревню Гиблотопь.", description = "Сомневаюсь, чтобы Зловещий Тотем оставил свои планы выжить людей с болот. Хотя ты, я смотрю, <был/была> бы не против. Но по крайней мере, мы разобрались с ответственными за поджог \"Последнего привала\".\n\nиди и поведай своему предводителю, что правосудие свершилось.", progress = nil, completion = "&lt;Крог выслушивает ваше донесение.&gt;\n\nОчень впечатляет, Серокопыт. Мне казалось, что этих преступников из племени Зловещего Тотема будет труднее найти. \n\nСлово Табеты было услышано, но не мне карать это племя. Конечно, я доложу об этом вождю. Никому об этом не рассказывай, пока Тралл не разберется со Зловещим Тотемом. Ты славно потрудился, распутав тайну \"Сомнительного отдыха\" и сняв с нас подозрения Терамора.", rewards = "Поножи дальней дорогиУбор рыскателяОкованный сталью хауберкЛезвие боевого заклятияХауберк со стальными пластинамиВы получите:\n\n"}
MultiLanguageQuestData['ru'][11207] = {title = "ecure the Cargo!", objective = "Мокси Сталегриль попросила вас собрать 8 контейнеров груза с дирижабля и принести ей на место крушения Бизиля.", description = "Этот дирижабль вез в Шестермуть припасов на полгода! Они там, конечно, что-то на что-то выменивают, но на обмене долго не протянешь.\n\nМеня отправили сюда собрать все оставшееся от груза, да вот только обломки разбросало по всему болоту. Большая часть, конечно, аварии не пережила, но, может, поищем то, что еще на что-то годится?", progress = "<Мокси сходит с ума от волнения.>\n\nНу, как там груз? Ты хоть что-нибудь нашел?", completion = "Ого! Ты нашел куда больше, чем я ожидала! Не знаю, сколько ждал от нас Драззит, но, думаю, этому он сильно обрадуется.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11208] = {title = "Поставка для Драззита", objective = "Доставьте груз с дирижабля Драззиту Кранотеку в Шестермуть.", description = "Драззит ожидает вскорости получить от меня вести, но место мне кажется довольно опасным, чтобы ехать туда самой. Если у тебя найдется время, не свезешь ли ты часть спасенного груза ему в Шестермуть?\n\nЭто небольшое поселение к юго-западу отсюда, за руинами Деревни Каменного Молота, если тебе еще не доводилось там бывать. Также туда можно дойти по дороге от усадьбы Табеты. Когда доберешься до Шестермути, ищи парня по имени Драззит Кранотек.", progress = "Да?", completion = "&lt;Драззит принимает от вас груз.&gt;\n\nЯ так проголодался, что целого дракона бы съел! Наконец-то Мокси доставила часть груза сюда. А то я уже было начал играть в кости с огром на то, что ему удавалось добыть на охоте!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11209] = {title = "at's Bargain", objective = "Нат Пэгл из лагеря Ната хочет, чтобы вы испытали его новую наживку для рыбы.", description = "Значит, ты <нашел/нашла> экземпляр \"Подлых обитателей глубин\"? Что же, скажу по собственному опыту - все, что там написано, - правда. Кое-кого я собственными глазами видел.\n\nНо ты спрашиваешь про Тетура. Давай заключим сделку. Вот что мне от тебя надо: я тут разрабатываю новую линию наживок, но вот эту я еще не испытывал.\n\nВозьми эту пасту - да, запашок у нее не из приятных - намажься ею и плыви к тому разбитому кораблю на юго-запад. Выживешь - расскажешь, как все прошло!", progress = "Уговор такой – без улова не возвращаться!", completion = "Что ж, неплохо, неплохо, но на твоем месте я бы срочно отправился в душ.\n\nА теперь о том морском чудище...\n\nПропусти пока кружку-другую.", rewards = "Вы получите:\n\n\"Особое Новолунное\""}
MultiLanguageQuestData['ru'][11210] = {title = "h, It's Real", objective = "Поговорите с майором Миллзом в доках Терамора.", description = "Да, Тетур вполне настоящий, живет он в тераморских водах.\n\nПриходит на яркий огонь. Именно поэтому маяк там не работает...\n\nСтоит его зажечь, как чудище вернется. Но в здравом уме никто на это не пойдет.\n\nСоответственно, это работка для тебя. Приятно было с тобой выпить, но не обижайся на Ната, если Тетур на самом деле примет тебя за наживку. Если намереваешься с ним повидаться, поговори сначала с майором Миллзом из доков Терамора.", progress = nil, completion = "&lt;Вы рассказываете о вашем разговоре с Натом, тщательно обходя тему испытания наживки.&gt;\n\nЧто ж, видимо, работка как раз для нас. Я все подготовлю.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11211] = {title = "Помощь деревне Шестермуть", objective = "Поговорите с Драззитом Кранотеком в Шестермути.", description = "Когда та гоблинша... как бишь ее там... Токси, Рокси... Мокси, вот! Короче, когда она проезжала здесь к месту крушения дирижабля, то говорила, что в деревне Шестермуть какие-то проблемы.\n\nЭтот разбившийся дирижабль вез им свежие припасы. Если поедешь отсюда по южной дороге мимо руин Деревни Каменного Молота, в конце концов упрешься в Шестермуть.\n\nПочему бы тебе там не встретиться с Драззитом Кранотеком и не спросить, какая помощь нужна?", progress = nil, completion = "Хорошо, что Табета прислала тебя. Неплохо было бы, если б она передала каких-то припасов, пока сюда не доставят груз с разбившегося дирижабля, но, как мне известно, сейчас ей просто нечем поделиться. Если у тебя есть вкус к приключениям, то я назначил награду за одного особенно противного ящера.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11212] = {title = "Ферма Табеты", objective = "Поговорите с Табетой в ее доме на Трясине.", description = "Среди болот живет старая женщина по имени Табета. Мы немного знаем о ней – пожалуй, только то, что она куда старше, чем кажется. Она время от времени помогает нам, пока что ей удается поддерживать здесь мир между нашими силами и Ордой.\n\nОбычно она держала с нами постоянную связь, но недавно эта связь прервалась.\n\nЕсли у тебя выдастся минутка, может, проведаешь ее? Иди по дороге мимо Северной башни, там она сворачивает на юг к Трясине. Усадьбу Табеты видно с дороги.", progress = nil, completion = "Хорошо, что Терамор прислал сюда хоть кого-то. Опасения вашего приятеля-стража небезосновательны. У нас появились новые соседи, и добрыми их никак не назовешь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11213] = {title = "Навестить Табету", objective = "Поговорите с Табетой в ее усадьбе на Трясине.", description = "Среди болот в маленькой усадьбе живет человеческая женщина по имени Табета. Обычно я дел с людьми не веду, но она не раз нам помогала.\n\nОднако в последнее время я не могу с ней связаться, так что ищу кого-нибудь, кто пошел бы в ее усадьбу да проверил, все ли там ладно.\n\nЕсли пойдешь по дороге на юг из деревни, а затем свернешь на болота, то найдешь ее усадьбу в самом сердце Трясины.", progress = nil, completion = "Назир очень кстати решил послать кого-нибудь сюда. У нас появились новые соседи, и с тех пор жить стало просто невыносимо.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11214] = {title = "ission to Mudsprocket", objective = "Поговорите с Драззитом Кранотеком в Шестермути.", description = "Картель Хитрой Шестеренки недавно построил новый форпост в южной части Пылевых топей. Называется он вроде Шестермуть и расположен на главной дороге к югу от домика Табеты и руин деревни Каменного Молота.\n\nЭто прекрасная возможность завести новые торговые отношения, и леди Джайна хочет, чтобы я отправил туда представителя для налаживания контактов. Возьмешься?", progress = nil, completion = "Значит, Терамор хочет наладить с нами деловые отношения? Ну, от такого предложения не отказываются. Сейчас у нас как раз жутко не хватает провианта, так что мы рады любым бизнес-контактам!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11215] = {title = "Помощь Шестермути", objective = "Поговорите с Драззитом Кранотеком в Шестермути.", description = "На новом форпосте картеля Хитрой Шестеренки в южной части Трясин дела не так уж и хороши. Дирижабль с припасами для Шестермути разбился, и они остались без жизненно необходимых инструментов, провизии и медикаментов.\n\nИди по дороге на юг, прямо в глубь болот. Ты пройдешь усадьбу Табеты и руины Деревни Каменного Молота, прежде чем дорога приведет тебя в Шестермуть. Помоги городскому управлению, чем сможешь.", progress = nil, completion = "Я не откажусь от любой помощи! Мы тут как раз обживаемся, поэтому используем все доступные средства на полную катушку, пока дирижабль не доставил груз.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11216] = {title = "Верховный маг Альтур", objective = "Поговорите с верховным магом Альтуром близ Каражана на перевале Мертвого Ветра.", description = "Мой наставник прислал меня сюда искать помощи, но увы – меня не выпускают из Нижнего Города, а от тех, кто часто посещает это заведение, толку, мягко говоря, мало.\n\nНо ты другое дело, ты больше <похож/похожа> на тех, кто не боится приключений. Если ты не против помочь нам, поговори с верховным магом Альтурусом близ старой обители Медива, Каражана. \n\nА я пока постараюсь получить доступ к другим частям города. Говорят, тут сейчас находится один из наших старых помощников.", progress = nil, completion = "Благодарю за то, что уделили нам толику времени. Нам предстоит важное дело.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11217] = {title = "atch a Dragon by the Tail", objective = "Гиззикс Грязебульк из Шестермути просит принести ему 8 стеблей змейкиного хвоста.", description = "Поскольку дирижабль разбился, поставка задерживается, и мы остались без медикаментов и бинтов.\n\nКонечно, выручают подручные средства, но среди всех этих насекомых, отбиваясь от врагов и неся потери, мы вряд ли долго продержимся! Я нашел тут одну травку, которая, сдается, помогает при лечении любых ран и притупляет боль, но и ее мало.\n\nОна называется змейкин хвост, в Земле Драконов и Драконьих топях к востоку от города ее целые заросли. Сами растения представляют собой свившиеся кольцами стебли. Когда смотришь на них, кажется, будто они пульсируют.", progress = "Ты нашел, где растет змейкин хвост?", completion = "Спасибо тебе! Теперь наши парни продержатся в поле, пока Мокси не доставит груз, оставшийся после крушения дирижабля.", rewards = "Эполеты подмастерьяМасляные кожаные поножиЛезвие боевого заклятияВы получите:\n\n"}
MultiLanguageQuestData['ru'][11218] = {title = "Осторожно! Взрывчатка!", objective = "Воспользуйтесь динамитом Стальной Чеки, чтобы собрать 6 кусков руды из Шепчущей теснины и 18 драгоценных камней из Шепчущей теснины. Затем принесите руду и камни саперу Стальной Чеке в Крепость Западной Стражи.", description = "<имя>, капитан поручил мне задание, с которым мне не справиться без твоей помощи.\n\nМои товарищи из Лиги исследователей отправились на север, вести раскопки в Шепчущей теснине, и что-то в этом месте свело их с ума. Теперь они нападают на всех, кто осмеливается к ним приблизиться. \n\nА капитана заботит только руда для крепости! К счастью, я знаю, как решить эту проблему.\n\nОтправляйся туда, взорви месторождение и принеси сюда осколки руды вместе с драгоценными камнями. Эта раскопки недешево нам обходятся, знаешь ли.\n\nПравда, должен тебя предупредить – это очень странная руда!", progress = "Кажется, мы никогда не закончим возводить эту крепость. Надеюсь, ты несешь нам припасы, необходимые для продолжения строительства.", completion = "Говоришь, тебе было неприятно прикасаться к этой руде? Может быть, нам не стоит больше ее использовать.\n\n&lt;Стальная Чека бросает быстрый взгляд на вашу добычу и быстро меняет тему разговора.&gt;\n\nКакие симпатичные камешки! Интересно, сколько удастся за них выручить? Ну конечно, эти деньги пойдут на ремонт и новые инструменты...\n\nЗнаешь, с тобой довольно выгодно сотрудничать! Вот, возьми... это самое малое, что я могу для тебя сделать.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11219] = {title = "Гаси пожар!", objective = "Попечительница сирот в маске просит вас помочь потушить пожар в деревне. Когда пожар потухнет, снова поговорите с попечительницей сирот в маске в городе.", description = "Спасите детей Орды, <имя>! Всадник без головы, который некогда был человеком-паладином, а теперь стал безумным демоном, поджег нашу деревню! Вы должны потушить пожар!\n\nХватайте ведро и тушите огонь или передавайте ведра по цепочке! Потушите пожар и прогоните всадника без головы!", progress = "Вы нужны детишкам Орды! Не бросайте их!", completion = "Пожар потушен! Вы с пожарной бригадой победили! Ха!\n\nНападение Всадника без головы провалилось, но пока он и его голова не уничтожены, он будет возвращаться.\n\nА пока утешайтесь тем, что вы спасли наших детей. Для меня великая честь быть свидетельницей вашей отваги!", rewards = "Вы получите:\n\nТыквовинская конфетаУтяжеленный фонарь из тыквы"}
MultiLanguageQuestData['ru'][11220] = {title = "Всадник без головы", objective = "Найдите святилище тыквы Всадника без головы.", description = "Пока голова Всадника не уничтожена, не будет конца его неистовству.\n\nОн покоится в Покинутом ските Монастыря Алого ордена в Тирисфальских лесах. Найди его святилище тыквы и скажи такие слова:\n\nВсадник, встань\nПришла пора\nУмереть в последний раз!\n\nТогда он восстанет. Уничтожь голову Всадника, и он не будет больше преследовать нас.", progress = nil, completion = "Откуда взялось это святилище, никому не ведомо, но кому оно посвящено – никаких сомнений нет...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11221] = {title = "Донесения с полей", objective = "Поговорите с темным следопытом Лианой и стражем смерти Разаэлем на поле боя в Кровоточащей долине к югу от Лагеря Возмездия, после чего вернитесь к Верховному палачу Ансельму.", description = "Мы пришли в Нордскол, чтобы одержать победу над Артасом. Альянс – это незначительная помеха нашим планам, которую мы вскоре устраним.\n\nМы уже уничтожили их флот на востоке, но выжившие моряки укрылись на Обнажившемся дне, к югу отсюда.\n\nМы рассчитывали легко разрушить их самодельные укрепления, но недооценили их волю к жизни. Найди моих полевых офицеров, темного следопыта Лиану и стража смерти Разаэля. Мне нужен их отчет о текущей ситуации.", progress = nil, completion = "Пушки заставили нас отступить? Я им покажу, как стрелять по нашим войскам!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11222] = {title = "roof of Treachery", objective = "Поговорите с королем Варианом Ринном в крепости Штормграда.", description = "Хотя мы получили ответы отнюдь не на все вопросы, необходимо, чтобы вы оповестили о результатах наших изысканий короля Вариана Ринна немедленно!\n\nОн должен знать, что Братство Справедливости в Штормграде обзавелось влиятельным покровителем и связано с его похищением! Сомневаюсь, что после этого он пощадит причастных к этому преступлению людей.\n\nЯ могу воспользоваться магией для ускорения вашей поездки в Штормград. Просто скажите мне, когда будете готовы, <имя>.", progress = nil, completion = "*Верховный лорд Болвар выслушивает от вас сообщение Джайны.*\n\nТы уверен? Это очень серьезное обвинение...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11223] = {title = "eturn to Jaina", objective = "Поговорите в Тераморе с леди Джайной Праудмур.", description = "Мы должны составить план, как уничтожить остатки Братства Справедливости. Пожалуйста, передай мою благодарность леди Джайне в Терамор. Она всегда была мне добрым другом и надежным союзником. \n\nСтупай в Квартал Магов в западной части города и поговори с верховным магом Малином у тамошней башни. Он поможет тебе поскорее вернуться в Терамор.", progress = nil, completion = "Это замечательная новость, Паладиньдинь! Я беспокоилась, что верховный лорд станет сомневаться в достоверности нашей информации, но, вижу, зря волновалась.\n\nТы будешь щедро вознагражден за труды во благо Терамора и Альянса.", rewards = "Нарукавники лучникаИскристая чешуйчатая кирасаКинжал с самоцветамиВы получите:\n\n"}
MultiLanguageQuestData['ru'][11224] = {title = "Пришли мулов сюда", objective = "Исследовательница Эбигейл просит вас пригрозить рукой (команда /рука) 10 брошенным груженым мулам, после чего вернуться к ней в Крепость Западной Стражи.", description = "Я слышала о том, что случилось в Шепчущей теснине на севере. Туда спустились многие члены Лиги исследователей, и, говорят, сошли с ума от того, что они там обнаружили.\n\nЭто, впрочем, не меняет того факта, что они забрали с собой почти всех наших мулов и оборудование. Мулов мне особенно жалко!\n\nЕсли ты вдруг окажешься в тех краях и наткнешься на бедных животных, просто подойди к ним и пригрози рукой. Они испугаются и побегут домой.", progress = nil, completion = "Не знаю даже, как отблагодарить тебя, |3-6(Маг). Теперь, когда мы вернули большую часть мулов и оборудования, можно попытаться продолжить работу.\n\nПрошу тебя, прими эту награду.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11225] = {title = "Отшельник с Ведьминого холма", objective = "Поговорите с Ярлом \"Болотным глазом\" в сторожке \"Болотный огонек\".", description = "Болото как-то странно влияет на тамошних жителей. Многие трогаются умом.\n\nА те, кто селится в сторожке \"Болотный огонек\", просто съезжают с катушек, да еще как! Все как один. Последний хозяин, некто Ярл по прозвищу \"Болотный глаз\", уже проявляет все признаки безумия.\n\nЯ не до конца понимаю, что там происходит, и буду очень тебе благодарен, если ты сходишь и разберешься.\n\nПоместье находится на восточном краю болота. Иди на восток через Синюю топь, мимо Северной башни. Дом стоит на Ведьмином холме, где водятся призраки.", progress = nil, completion = "Пришел шпионить за мной? Нет?\n\nТогда, может, откушаешь вкусненького? Вот и славно, а то я как раз собирался добыть еды и мне нужна помощь!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11227] = {title = "Пусть едят вволю!", objective = "Понтий, псарь из Лагеря Возмездия, просит вас забрать голодного чумного пса из клетки и накормить его мясом ворон фьорда, которые кружат к западу от Лагеря Возмездия.", description = "Верховный палач требует, чтобы мои собаки отправились вынюхивать следы шпионов противника, но я-то знаю, что чумные псы и с места не сдвинутся, пока их не накормят нормальной едой. \n\nЭти тупоголовые вояки не понимают, что мои звери не будут есть всякие отбросы. Как можно требовать каких-то успехов от голодных собак?\n\nСлушай, у тебя не найдется свободной минутки? Пожалуйста, возьми одного из псов поохотиться на ворон к западу отсюда. Их мясо не очень-то вкусное, но мои песики его обожают!", progress = nil, completion = "Ты поймал самую большую ворону, малыш? Хороший песик!\n\nАх, помнится, когда-то я разводил чистокровных овчарок в Тирисфале... хорошие были времена!", rewards = "Следующее заклинание будет наложено на вас:\n\nЗаставить отослать чумного пса\n\nВы получите:\n\nПредмет #1Предмет #5"}
MultiLanguageQuestData['ru'][11228] = {title = "Во власти ледяного кошмара...", objective = "Поговорите с вице-адмиралом Келлером в Валгардском порту.", description = "Фордрагон совсем с ума сошел, если он и впрямь думает, что этот отряд зеленоротых юнцов, которых он послал на защиту Валгарда, продержится хотя бы сутки.\n\n<Макалрой с удивлением рассматривает ваше обмундирование.>\n\nА вот ты, пожалуй, справишься гораздо лучше.\n\nЯ не могу даже описать, насколько велика ценность этого порта. А после того, как на нас напали эти летающие твари, ситуация резко ухудшилась.\n\nНайди вице-адмирала Келлера на северо-западе и сообщи ему, что ты уже <вырос/выросла> из коротких штанишек.", progress = nil, completion = "Этот дворф знает, что говорит. Мы действительно не можем допустить, чтобы порт был захвачен. Это одна из двух безопасных гаваней Альянса в этом ледяном кошмаре – вторая находится на сотню миль к западу, на побережье Борейской тундры.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11229] = {title = "Флагман \"Ветрокрылая\"", objective = "Поговорите с дрессировщицей нетопырей Камиллой в Лагере Возмездия и летите к флагману \"Ветрокрылая\". Доложите о своем прибытии капитану Харкеру.", description = "Три наших фрегата – \"Ветрокрылая\", \"Месть королевы\" и \"Забвение\" стоят на якоре к востоку от Обнажившегося дна. Передай капитану флота Харкеру, что ему приказано уничтожить пушки Альянса.\n\nПоговори с нашей дрессировщицей нетопырей Камиллой и попроси ее довезти тебя до места дислокации флота. Поторопись, <имя>, ибо каждую минуту, которую мы тратим на стычки с Альянсом, мы могли бы посвятить войне с Артасом.", progress = nil, completion = "Надеюсь, ты готов к сражению, Верлоз. Флотилии Королевы нужны отважные бойцы!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11230] = {title = "Засада!", objective = "Капитан Харкер на борту \"Ветрокрылой\" просит вас убить 15 стражей бухты Северного флота.", description = "Мы думали, что это будет легкой прогулкой. Их войска плохо экипированы, солдаты изранены и страдают от голода. Однако каким-то образом мы угодили в их ловушку.\n\nМы хотели использовать южные рифы как укрытие, но на подходе были взяты на абордаж этими вонючими псами Альянса.\n\nМне очень жаль, но если ты рассчитываешь на нашу огневую поддержку, тебе придется сначала вернуть наши корабли.", progress = "Ну, и чего ты ждешь? Убей этих мерзавцев!", completion = "Молодец, поставил этих поганцев на место. С оставшимися разберутся мои люди.", rewards = "Капюшон щедростиРасшитая костями курткаВнутренний панцирь нерубаВы получите:\n\n"}
MultiLanguageQuestData['ru'][11231] = {title = "О ключах и клетках", objective = "Отец Левариол попросил вас собрать достаточное количество ключей от гьялербронских клеток, чтобы освободить 10 гьялербронских узников. Когда вы выполните задание, вернитесь к нему в Крепость Западной Стражи.", description = "Возможно, капитану это безразлично, но мы-то знаем, что врайкулы совершают какие-то омерзительные ритуалы \"пробуждения\" к северу от Гьялерброна.\n\nВ ходе этих обрядов проливается кровь невинных жертв!\n\n<класс>, ты <должен/должна> остановить это! Неважно, кого они держат в своих клетках для жертвоприношений – их надо освободить. Могу поспорить, врайкулы носят ключи при себе.\n\nВидит Свет, нам не нужны эти мерзкие врайкулы поблизости, и еще меньше нам хочется разбираться с тем злом, которое они пытаются пробудить!", progress = nil, completion = "Слава тебе, дитя мое, ибо ты несешь Свет даже в самые темные уголки этого мира!\n\nПожалуйста, прими это скромное вознаграждение твоим благим делам. Я лично прослежу за судьбой освобожденных тобой пленников, и пусть будет даровано спасение тем, кто служит Свету и Альянсу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11232] = {title = "Дайте нам знак", objective = "С помощью дымовых сигнальных ракет обозначьте местонахождение пушек Альянса вдоль северной стены Обнажившегося дна. Доложите о выполнении задания темному следопыту Лиане из Кровоточащей долины.", description = "Скорее всего, мы сможем пробиться назад, к пушкам. К несчастью, нам лучше не привлекать к себе внимания, поэтому тебе придется пометить цели с земли.\n\nВозьми с собой эти дымовые сигнальные ракеты и обозначь местонахождение пушек вдоль северной стены на контролируемой Альянсом территории к западу отсюда. Как только путь для наших наземных отрядов будет расчищен, дай знак Лиане. Об остальном мы позаботимся сами.", progress = nil, completion = "Превосходно. Я дам знать нашим наземным отрядам, что они могут выступать.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11233] = {title = "Решающий удар", objective = "Темный следопыт Лиана из Лагеря Возмездия послала вас убить капитана Ольстера, сержанта Лоррика и лейтенанта Селейну, обосновавшихся на Обнажившемся дне.", description = "Ты отлично <проявил/проявила> себя на поле боя, <имя>. Возможно, именно ты <изменил/изменила> ход битвы в нашу пользу.\n\nТеперь я хочу поручить тебе очень ответственную миссию. Не знаю, сколько еще времени понадобится противнику, чтобы прийти в себя, но времени для действий осталось не так уж много.\n\nВоспользуйся замешательством неприятеля, вызванным нашим нападением, проберись за линию фронта и уничтожь их предводителей. Вот их имена и звания: капитан Ольстер, лейтенант Селейна и сержант Лоррик. Удачи, <класс>.", progress = nil, completion = "Скоро наши войска одержат великую победу. Ансельм будет рад услышать эти вести.", rewards = "Ежевичный колючий большой посохАбордажная сабля холодного камняОстроземПробойник подавленияАрбалет из бивня элеккаСкалотрясВы получите:\n\n"}
MultiLanguageQuestData['ru'][11234] = {title = "Доложите Ансельму", objective = "Вернитесь к верховному палачу Ансельму в Лагерь Возмездия в Ревущем фьорде.", description = "Давай пошлем весточку старине Ансельму. Мы долго шли к этой победе – но лучше уж поздно, чем никогда. Скажи ему, что через несколько часов все будет кончено.\n\nСлава королеве банши!", progress = nil, completion = "Наконец-то. Войска Альянса давно уже не давали нам спать спокойно.\n\nОднако, сейчас не время праздновать. Взгляни на запад; похоже, к нам идут гости.", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11235] = {title = "Очистить Гьялерброн", objective = "Капитан Адамс поручил вам убить 15 гьялербронских воинов, 8 гьялербронских руночаров и 8 гьялербронских сноходцев. После чего вам надлежит вернуться к нему в Крепость Западной Стражи.", description = "Увы, теперь перед нами стоит другая проблема. Выжившие разведчики сообщили, что врайкулы замышляют нечто недоброе в своей главной крепости к северу отсюда. \n\nОни называют это место Гьялерброн, хотя вообще-то первая буква этого слова произносится как \"Ш\". Странные существа. \n\nНо все это не важно; важно то, что тебе надо пробраться туда и убить как можно больше этих мерзких существ, чтобы сорвать их зловещие планы. \n\nЯ знаю, что могу на тебя рассчитывать, <имя>.", progress = nil, completion = "Ты молодец, Reng. Хорошо, что мы от них избавились.\n\nНо это место все еще меня беспокоит, и я боюсь, что наша война еще не окончена.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11236] = {title = "Некровладыка Мезхен", objective = "Убейте некровладыку Мезхена. Затем вернитесь к капитану Адамсу в Крепость Западной Стражи.", description = "Армия Плети уже пришла в Гьялерброн, и в их рядах есть несколько некромантов! Должно быть, они пытаются провести врайкулов в крепость Артаса.\n\nПредводитель этих некролордов должен умереть!\n\n<имя>, на твои плечи ложится огромная ответственность – ты <должен/должна> сорвать планы некровладыки Мезхена и уничтожить его самого.\n\nЯ не допущу, чтобы эти врайкулы заключили союз с Плетью! \n\nМезхена можно найти на платформе в дальнем правом квартале Гьялерброна.", progress = nil, completion = "&lt;Капитан облегченно вздыхает.&gt;\n\nНу, теперь мы можем слегка расслабиться.\n\nReng, ты снова подтвердил свою значимость для Крепости Западной Стражи и всего Альянса. Пожалуйста, выбери себе что-нибудь из нашей сокровищницы. Это самое меньшее, что мы можем для тебя сделать!", rewards = "Наплечники из шкуры воргаПлетеные сумеречные поножиПозолоченный ремень из хладосталиПелерина необыкновенной щедростиВы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11237] = {title = "Гьялербронский план нападения", objective = "Отнесите гьялербронский план нападения магу-лейтенанту Малистеру в Крепость Западной Стражи.", description = "Вы держите в руках планы нападения на Крепость Западной Стражи. Похоже, что врайкулы собираются использовать для атаки ледяного змея, Ледиона, который кружит у вас над головой.\n\nНаверняка, маг-лейтенант Малистер сможет что-нибудь предпринять, если вы доставите эти планы к нему в южную крепость.", progress = "Что это?! Планы нападения на крепость?\n\nОНИ ПОСЫЛАЮТ ЛЕДЯНОГО ЗМЕЯ?!", completion = "Reng, мы не можем допустить, чтобы эти планы осуществились!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11238] = {title = "Ледяной змей и его повелитель", objective = "Убейте Зловещего призывателя драконов и воспользуйтесь его рогом, чтобы позвать обратно Ледиона. Убейте ледяного змея и принесите рог магу-лейтенанту Малистеру в Крепость Западной Стражи.", description = "Ты мудро <поступил/поступила>, доставив ко мне этот документ. Теперь тебе следует взять несколько помощников и отправиться на север, в Гьялерброн. Убей этого змея и его хозяина, Зловещего призывателя драконов!\n\nНадеюсь, они еще не выпустили это ледяное чудовище в небо.\n\nНо, даже если это уже произошло, и змей движется на нас, его можно отозвать обратно с помощью рога призывателя драконов. Звук рога привлечет Ледиона, и он приземлится обратно, на платформу слева от Гьялерброна. Уничтожь его!\n\nПожалуйста, <имя>, когда все закончится, принеси мне этот рог. Нельзя допустить, чтобы он попал не в те руки.", progress = "Ледяной змей и его хозяин мертвы?\n\nНо где же рог?", completion = "Ого, какой холодный!\n\nЗнаешь ли ты, что только что спас Крепость Западной Стражи от неминуемой гибели? Ах, если бы у нас в союзниках было больше таких неординарных личностей, как ты!\n\nПолагаю, ты заслуживаешь щедрой награды.", rewards = "Землистые обмоткиШлем магического пикаРукавицы из сребросталиВам дадут возможность выбрать одну из следующих наград:\n\nПерстень пропавшего врайкула\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11239] = {title = "На службе Света", objective = "Убейте 10 бессмертных дозорных, 4 чудовищных ужаса и 2 тлетворных существа по просьбе отца Левариола из Крепости Западной Стражи.", description = "Твоя помощь бесценна для нас, <имя>. Увы, наша война далека от завершения, и омерзительные создания Плети беспокоят меня больше, чем когда-либо.\n\nСвет презирает этих существ, и мы тоже не должны терпеть их присутствие. Я понимаю, что прошу от тебя слишком многого, но ты <должен/должна> вернуться на север, в Гьялерброн, и сокрушить логово этой нечестивой Плети. Не забудь проверить, не остались ли эти презренные твари в чертогах Пробуждения, что под Гьялерброном.\n\nОчищение – путь к спасению, дитя мое. Мы будем гордиться тобой!", progress = nil, completion = "&lt;Священник тихо шепчет слова молитвы.&gt;\n\nДитя мое, Reng, ты был послан в ответ на мои молитвы. Гордо стой в лучах Света, ибо подвиг твой священен!\n\nКстати, в сокровищнице храма наверняка найдется что-то, что тебе пригодится.", rewards = "Монаршие кюлотыПлеменной нагрудный доспехИзмазанные глиной наголенникиВам дадут возможность выбрать одну из следующих наград:\n\nПодвеска из зуба ворга\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11240] = {title = "Предводитель Спятивших", objective = "Убейте Сквига Идолохотника и сообщите об этом саперу Стальная Чека, который находится в Крепости Западной Стражи.", description = "Знаешь, дружище, мне тоже все это не нравится, но, пока тебя не было, капитан пересмотрел свое мнение об этом месте.\n\nПохоже, он хочет убить моего бывшего начальника Лиги исследователей. Могу предположить, что за этим последует нападение на их лагерь.\n\nМожет быть, ты окажешь мне услугу? Отправляйся назад, в Шепчущую теснину, и убей Сквига Идолохотника. Насколько я помню, он прячется в пещере на северо-западе.", progress = nil, completion = "&lt;Сапер недовольно морщится, как будто не рассчитывал на успех вашей миссии.&gt;\n\nКапитан будет рад слышать, что его задание выполнено.\n\nСпасибо тебе за помощь в Шепчущей теснине. Выбери себе что-нибудь из этого в награду.", rewards = "Гневошитые наплечные пластиныШипастый защитный шлемБоевые рукавицы из шепчущей сталиОбшитые перьями наплечные пластиныВы получите:\n\n"}
MultiLanguageQuestData['ru'][11241] = {title = "Путь огня", objective = "Выведите аптекаря Хейнса из Обнажившегося дна после чего сообщите о произошедшем аптекарю Лисандеру из Лагеря Возмездия в Ревущем фьорде.", description = "Спасибо, что <вытащил/вытащила> меня из этой передряги, <имя>. Не хотелось бы узнать, что за судьбу готовили мне эти мерзавцы из Альянса.\n\nДавай попробуем выбраться отсюда. Надеюсь, нам еще удастся с ними рассчитаться. Есть ли здесь наш лагерь поблизости?", progress = nil, completion = "Аптекарь Хейнс жив? Говоришь, вы с ним сожгли припасы Альянса? Бедняга; наверное, ему досталось в плену.\n\nВерлоз, Королевское фармацевтическое сообщество у тебя в долгу. Благодарим тебя от всего нашего черного, прогнившего сердца.", rewards = "Заиндевелый кинжалТесак с каменным лезвиемШокер из черепа дракончикаМонарший скипетрДлинный лук ледяного шипаСносившийся сокрушитель врайкуловВы получите:\n\n"}
MultiLanguageQuestData['ru'][11242] = {title = "Наконец, свободен!", objective = "Возьмите книгу Томаса Томсона и отнесите ее переодетой попечительнице сирот в Златоземье, Каранос или на Лазурную заставу.", description = "Гнев был моей темницей, <имя>, а ты $Gосвободил:освободила; меня. Хотя я считал себя правым, душа моя ныне кровоточит от всех тех ужасов и смертей, которые обрушил я на жителей Азерота.\n\nБлагодарю тебя, что ты <привел/привела> меня к Свету. Да не сверну я с этого пути!\n\nОтнеси этот потрепанный молитвенник попечительнице сирот, чтобы дети узнали, что больше я их не потревожу.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТыквовинская конфета"}
MultiLanguageQuestData['ru'][11243] = {title = "Если Валгард падет...", objective = "Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас убить 12 захватчиков из клана Укротителей драконов или воргов из клана Укротителей драконов.", description = "Если Валгард падет, мы потеряем главный источник снабжения в Нордсколе. После этого нам останется только преклонить колени перед Королем-личом. Не знаю, как насчет тебя, а у меня в Элвинне осталась жена и трое детишек. И будь я проклят, если не буду сражаться за свою жизнь до последнего вздоха!\n\nСитуация дошла до критической точки, и мы должны использовать все имеющиеся у нас ресурсы. Отправляйся к воротам и помоги нашим солдатам защитить город от захватчиков!", progress = nil, completion = "Ты оказал значительную помощь нашим защитникам и помог поднять моральный дух солдат. Надеюсь, теперь они справятся с оставшимися захватчиками. А для тебя у меня есть более важное задание...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11244] = {title = "На помощь спасателям", objective = "Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас спасти 8 валгардских разведчиков, которых проткнули гарпунами и оставили умирать.", description = "Эти жуткие великаны появились буквально из воздуха через месяц после того, как мы прибыли сюда. Мы были плохо подготовлены к нападению и дорого поплатились за свою беспечность. Мы потеряли всю археологическую бригаду и нескольких жителей, которых похитили и утащили в руины. С тех пор мы находимся на осадном положении.\n\nХуже того, наших разведчиков, которых мы послали на помощь похищенным, поймали врайкулы, насадили на гарпуны и оставили умирать в лесу к северу от Валгарда. Пожалуйста, найди их и освободи!", progress = nil, completion = "Какая дикость! Не могу поверить, что врайкулы так поступили с нашими разведчиками. Они хотели запугать нас, ослабить нашу решимость... заставить спасаться бегством.\n\nНо их замысел не удался.\n\nМы покажем этим мерзавцам, что будет с теми, кто осмелится развязать войну с Альянсом!", rewards = "Ежевичный колючий большой посохАбордажная сабля холодного камняОстроземПробойник подавленияАрбалет из бивня элеккаСкалотрясВы получите:\n\n"}
MultiLanguageQuestData['ru'][11245] = {title = "Смертельно опасные башни", objective = "Сержант из крепости Западной Стражи сообщил вам, что сторожевые башни Скорна разумнее всего разрушить с воздуха.", description = "<имя>, мы не можем двигаться дальше, не уничтожив сторожевые башни.\n\nНо на вершине каждой вышки несет стражу множество волшебников. Стоит тебе только приблизиться к башне – и мы обречены!\n\nКонечно, мы можем призвать бомбардиров из Крепости Западной Стражи, но они должны видеть цель, которую им предстоит разбомбить. Для этого тебе придется подкрасться к башням и забросить на вершину каждой дымовую сигнальную ракету.\n\nГлавное – не подходи слишком близко.", progress = nil, completion = "Какой ты меткий, Моджичек! Надо будет проставиться бомбардирам, когда мы вернемся обратно в крепость.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11246] = {title = "Тяжело, но необходимо", objective = "Сержант из крепости Западной Стражи попросил вас разрубить на куски 20 снежескорнских врайкулов в Скорне.", description = "Нам докладывали, что врайкулы могут восставать из мертвых. Нет, они не похожи на оживших мертвецов Плети, но их понятие жизни после смерти несет нам не меньшие беды.\n\nМы не можем так рисковать!\n\nВот, возьмите мой мачете. Пока мы будем продвигаться вперед, кромсайте им все трупы врайкулов, которые встретятся вам по пути. Я бы и сам это сделал, но у меня слабые нервы.\n\n<Сержант глупо ухмыляется.>\n\nЯ потратил все утро на заточку клинка, так что теперь он разрубит даже самые толстые кости.", progress = nil, completion = "Ух ты, сэр,а вы знаете, как обращаться с этой штуковиной.\n\n&lt;Сержант бросает на вас настороженный взгляд.&gt;\n\nЗнаете что, давайте-ка я заберу у вас мачете. А то вдруг вы поскользнетесь, споткнетесь, да зарубите меня ненароком!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11247] = {title = "Гори, Скорн, гори!", objective = "Сержант из крепости Западной Стражи поручил вам поджечь два больших дома и казармы в Скорне.", description = "Капитан Адамс приказал мне разрушить множество зданий в Скорне.\n\nНо теперь я могу смело доверить это ответственное задание своему командиру – то есть, вам, <имя>.\n\nПредлагаю сжечь два больших дома и казармы в нижнем квартале Скорна. Нам надо просто прокрасться в каждый дом и поджечь его факелом изнутри.", progress = nil, completion = "Отличная работа, сэр! Без вас я бы не справился с заданием.\n\nУверен, капитан будет доволен моим отчетом.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11248] = {title = "Операция: Атака на Скорн", objective = "Капитан Адамс попросил вас воспользоваться знаком отличия командира Западной Стражи в Скорне и поговорить с сержантом из крепости Западной Стражи.\n\nПрилагается предмет: \n", description = "<имя>! Только тебе я могу доверить столь рискованное и смертельно опасное поручение.\n\nНа восточной границе нашего форта находится крепость врайкулов, Скорн. Мои разведчики доложили, что эти \"великаны\" планируют нападение, которое мы вряд ли сможем отразить.\n\nГрубой силой мы ничего не добьемся, поэтому я хочу пустить в дело хитрость. Я выслал вперед сержанта и снабдил его всеми необходимыми инструкциями. Отправляйся в Скорн и покажи ему этот знак отличия командира.", progress = nil, completion = "Рад познакомиться с тобой, Reng!Это честь для меня – работать с тобой в одной команде.\n\nКстати говоря, у нас много дел!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11249] = {title = "Остановить вознесение!", objective = "Разверните врайкульский свиток вознесения рядом с погребальным костром тана, призовите и убейте его. Исходя из магической природы ритуала, вы можете предположить, что отцу Левариолу из Крепости Западной Стражи будет очень интересно взглянуть на этот свиток.", description = "Этот огромный сверток сделан из драконьей кожи. Развернув его на всю длину, вы видите таинственные знаки на чешуйчатой поверхности, изображающие ход врайкульского ритуала. \n\nТам нарисован тан врайкульского клана, поднимающийся в небо в окружении ангелоподобных существ. Позади него во мраке изображена темная, загадочная фигура.\n\nЧто-то подсказывает вам, что тан скорнского клана собирается пройти через этот ритуал. Вы должны его остановить! Напротив дома тана уже вздымается в небо огромный погребальный костер.", progress = "Чем я могу помочь тебе, дитя мое?", completion = "Да, сын мой, воистину, это странный документ! Впрочем, похоже, ты правильно расшифровал надписи.\n\nСпасибо тебе за этот свиток. Я внимательно изучу его и постараюсь постигнуть его предназначение. Пока что я могу предположить, что эти врайкулы нашли способ обмануть смерть; во всяком случае, это касается самых достойных их представителей.\n\nПобедив тана Снежескорнов, ты показал, что он был недостоин такой чести. Кто знает, какие беды принесло бы нам его перерождение, если бы он остался в живых!", rewards = "Мягкие замшевые мокасиныОмолаживающий шнурованный ременьНаплеч сковывающего шокаОниксовые захватыВы получите:\n\n"}
MultiLanguageQuestData['ru'][11250] = {title = "Слава покорителю Скорна!", objective = "Отнесите знак отличия командира Западной Стражи капитану Адамсу в Крепость Западной Стражи.", description = "Мы – точнее, ты – <сделал/сделала> все, за чем нас сюда посылали. Я горжусь тем, что мне довелось служить под началом <такого юного, но мудрого/такой юной> но мудрой:r; |3-1(<раса>). \n\nНе сомневаюсь, капитан будет рад слышать о твоих достижениях, но если ты по какой-то причине решишь остаться тут на некоторое время, то я всегда в твоем распоряжении.", progress = "Полагаю, раз ты вернулся то Скорн больше нам не угрожает?", completion = "Какие прекрасные новости! Я знал, что ты сможешь осадить их, Reng!\n\nНу, хоть на кого-то здесь можно положиться.\n\nПолагаю, ты заслужил награду. Давай, выбирай – для тебя ничего не жалко.", rewards = "Плетеный из лозы мундирСолнечные огнеступыСланцевые наручиВам дадут возможность выбрать одну из следующих наград:\n\nНаделяющая властью подвеска\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11251] = {title = "С новыми силами", objective = "Разведчица Валори просит вас узнать, что за звуки битвы доносятся из-за холма на северо-востоке Деревни Драконьего Черепа.", description = "Мы заплатили высокую цену, но все-таки закончили разведку местности.\n\nК сожалению, сведения не очень обнадеживают. Практически всех жителей захватили в плен или убили. Пропавшими без вести числятся лишь несколько опытных стражей.\n\nРазведчики сделали все, что могли – теперь настала твоя очередь действовать.\n\nИз-за холма на северо-востоке доносятся звуки сражения. Узнай, что там происходит, <класс>. Будем надеяться, мы найдем выживших, и они дадут нам информацию, которую можно будет использовать против наших врагов.", progress = nil, completion = "Ну, наконец-то, помощь пришла! Рад видеть тебя, дружище.\n\nА теперь хватит стоять столбом, принимайся за работу!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11252] = {title = "На Утгард!", objective = "Защитник Мордун поручил вам казнить Ингвара Грабителя, который обитает в Утгарде, и принести его голову вице-адмиралу Келлеру.", description = "Слушай, <юнец/девчонка>,. Я уже убил столько этих тварей, сколько тебе за всю жизнь не положить. Сечешь?...\n\nВрайкулы не знают страха в битве. Иногда кажется, что они равнодушны к смерти. Учитывая их свирепость и их численность – мы обречены. Вот так-то.\n\nЕсть, правда, среди них один врайкул, которого они уважают. Зовут его Ингвар. Не знаю уж, почему они так перед ним пресмыкаются, но твоя победа над ним повергнет их в ужас.\n\nТогда, возможно, у нас появится шанс...", progress = "Рад видеть тебя в добром здравии, Аркоман.\n\nМы и так уже потеряли слишком много славных воинов.", completion = "Потрясающе!\n\nНеужели удача наконец-то повернулась к нам лицом?\n\nТы молодец, Аркоман!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо палачаКольцо травлиПерстень быстрого приговора\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11253] = {title = "По следу врага", objective = "Воспользуйтесь ошейником чумного пса и заберите из клетки в Лагере Возмездия чумного пса-ищейку. Идите с ним по следу, куда бы он вас не привел.\n\nПрилагается предмет: \n", description = "Теперь, когда этот подлец набил свое брюхо, возможно, он захочет немного потрудиться. Вот его поводок – иди и забери его из клетки.\n\nНе знаю, что там хочет от тебя Ансельм, но этот пес точно приведет тебя к цели.", progress = nil, completion = "Этот потрепанный свиток покрыт яркими рисунками. Вы чувствуете, что собаколов говорил вам именно о такой находке.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11254] = {title = "Карта на шкуре дракона", objective = "Принесите карту на шкуре дракона верховному палачу Ансельму в Лагерь Возмездия.", description = "Внимательно изучив свиток, вы понимаете, что это подробная карта фьорда. Местонахождения различных деревень отмечены символами, напоминающими племенные знаки. \n\nЛагерь Возмездия помечен огромным рисунком, изображающим череп.\n\nЭта карта, несомненно, представляет огромный интерес для верховного палача Ансельма.", progress = "Ты хочешь мне что-то показать, |3-6(Охотник)?", completion = "&lt;Верховный палач внимательно рассматривает карту, изучая символы вокруг Фьорда.&gt;\n\nТак, это восточное побережье. Значит, деревни Укротителей драконов и Снежескорнов находятся здесь и здесь... а это, должно быть, мы, приговоренные к смерти.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11255] = {title = "Пленники в Деревне Драконьего Черепа", objective = "Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас спасти 3 пленных валгардских узников.", description = "Эта война еще не закончена, <имя>. Если наши люди в деревне все еще живы, кто-то должен пойти туда и спасти их. \n\n<Вице-адмирал Келлер указывает на вас.>\n\nОтправляйся на север, в Деревню Драконьего Черепа. Как только окажешься в поселении, ищи наших людей. Если они в плену – найди способ освободить их. \n\nВозможно, они смогут дать нам больше информации о нашем противнике.", progress = nil, completion = "Спасенные тобой солдаты предоставили нам крайне важную информацию. Эти твари называют себя \"врайкулами\". Их племя, обосновавшееся в Деревне Драконьего Черепа, возглавляет мистик по имени Янис, который провозглашает себя служителем другого врайкула, Ингвара Расхитителя.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #3\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11256] = {title = "Скорн должен пасть!", objective = "Вождь Прахтотем попросил вас воспользоваться эмблемой Заиндевевшего Копыта в Скорне и поговорить с храбрецом из Лагеря Заиндевевшего Копыта.\n\nПрилагается предмет: \n", description = "<имя>! Врайкульская крепость – Скорн – находится на юге. Недавно в ней пробудились некие странные великаны, которые теперь повсеместно атакуют наши войска.\n\nМои разведчики сообщают, что они планируют напасть на наш лагерь, и мы не сможем им противостоять. Единственный выход для моего народа – покинуть эти земли и уйти на север, в более безопасное место.\n\nЯ прошу тебя, приложи все свои умения и выиграй для нас немного времени. Я выслал вперед храбреца из нашего племени. Покажи ему эту эмблему, и он расскажет тебе, что надо сделать.", progress = nil, completion = "Интересно будет познакомиться с твоим народом, |3-6(Маг). Скоро мы будем сражаться бок о бок! \n\nНу, что, за работу?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11257] = {title = "Тяжело, но необходимо", objective = "Храбрец из лагеря Заиндевевшего Копыта попросил вас разрубить на куски 20 снежескорнских врайкулов в Скорне.", description = "Наши старейшины говорят, что врайкулы могут восставать из мертвых. Нет, они не похожи на оживших мертвецов Плети, но их понятие жизни после смерти несет нам не меньшие беды.\n\nМы не можем так рисковать!\n\nВот, возьми мое мачете. Пока мы будем продвигаться вперед, кромсай им все трупы врайкулов, которые встретятся тебе по пути.\n\nЯ потратил все утро на заточку клинка, так что теперь он разрубит даже самые толстые кости.", progress = nil, completion = "Тебе уже приходилось держать в руках мачете? Кажется, ты с ним вполне неплохо управляешься.\n\n&lt;Храбрец с опаской смотрит на вас.&gt;\n\nДавай-ка я заберу его у тебя, |3-6(Маг). На всякий случай.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11258] = {title = "Гори, Скорн, гори!", objective = "Храбрец из Лагеря Заиндевевшего Копыта поручил вам поджечь северо-восточный большой дом, северо-западный большой дом и казармы в Скорне с помощью его факела. Когда дело будет сделано, поговорите с ним еще раз.", description = "Вождь Прахтотем приказал мне разрушить множество зданий в Скорне.\n\nНо теперь я могу смело доверить это ответственное задание своему командиру – то есть тебе, <имя>.\n\nПредлагаю сжечь два больших дома и казармы в нижнем квартале Скорна. Нам надо просто прокрасться в каждый дом и поджечь его факелом изнутри.", progress = "Знаешь, когда здания загорятся, нам лучше отбежать подальше. Дух огня не знает жалости в своем стремлении разрушать.", completion = "&lt;Храбрец одобрительно кивает, увидев, как ловко вы обращаетесь с факелом&gt;\n\nПусть эти врайкулы почувствуют на себе всю ярость земли. Пусть они познают страх, который доселе вселяли в сердца других!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11259] = {title = "Смертельно опасные башни", objective = "Храбрец из Лагеря Заиндевевшего Копыта сообщил вам, что сторожевые башни Скорна разумнее всего разрушить атакой с воздуха, предварительно отметив их местонахождение с помощью сигнальной ракеты Храбреца.", description = "Продвигаясь в самое сердце Скорна, мы должны уничтожить сторожевые башни.\n\nНо на вершине каждой вышки несут стражу множество волшебников. Стоит тебе только приблизиться к башне – и ты <обречен/обречена>.\n\nНо мы можем призвать ветрокрылов из Лагеря Заиндевевшего Копыта. Правда, для этого тебе придется подкрасться к башням и забросить на их вершину сигнальную дымовую ракету.\n\nГлавное – не подходи слишком близко.", progress = nil, completion = "А у тебя неплохо получилось, Расул.\n\nНаконец-то и ветрокрылы нам пригодились. До сих пор они просто шатались по лагерю и пьянствовали круглыми сутками.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11260] = {title = "Остановить вознесение!", objective = "Разверните врайкульский свиток вознесения рядом с погребальным костром тана, призовите и убейте его. Исходя из магической природы ритуала, вы можете предположить, что Великой Матери Анкхе из Лагеря Заиндевевшего Копыта будет очень интересно взглянуть на этот свиток.", description = "Этот огромный сверток сделан из драконьей кожи. Развернув его на всю длину, вы видите таинственные знаки на чешуйчатой поверхности, изображающие ход врайкульского ритуала. \n\nТам нарисован тан врайкульского клана, поднимающийся в небо в окружении ангелоподобных существ. Позади него во мраке изображена темная, загадочная фигура.\n\nЧто-то подсказывает вам, что глава скорнского клана собирается пройти через этот ритуал. Вы должны его остановить! Напротив дома тана уже вздымается в небо огромный погребальный костер.", progress = "Да? Чем я могу помочь тебе, дитя мое?", completion = "Какая странная вещь! Впрочем, похоже, ты правильно расшифровал надписи.\n\nСпасибо тебе за этот свиток. Я внимательно изучу его и постараюсь постигнуть его предназначение. Пока что я могу предположить, что эти врайкулы нашли способ обмануть смерть; во всяком случае, это касается самых достойных их представителей.\n\nПобедив тана Снежескорнов, ты показал, что он был недостоин такой чести. Кто знает, какие беды принесло бы нам его перерождение, если бы он остался в живых!", rewards = "Мягкие замшевые мокасиныОмолаживающий шнурованный ременьНаплеч сковывающего шокаОниксовые захватыВы получите:\n\n"}
MultiLanguageQuestData['ru'][11261] = {title = "Покоритель Скорна!", objective = "Верните эмблему Зимнего Копыта вождю Прахтотему в Лагерь Заиндевевшего Копыта.", description = "Ты <сделал/сделала> все, ради чего нас сюда послали, <класс>. Должен признать, ты храбро <сражался/сражалась>. Твой народ не такой уж и странный, как мне показалось сначала.\n\nВождь Прахтотем будет рад услышать о твоей победе, но если ты по какой-то причине решишь задержаться здесь – обращайся ко мне. Я всегда к твоим услугам.", progress = "Какие вести из Скорна, Кладуц?", completion = "Отличные новости! Теперь мы можем спокойно подготовиться к отступлению.\n\nПрошу, возьми это в знак нашей благодарности.", rewards = "Плетеный из лозы мундирСолнечные огнеступыСланцевые наручиВам дадут возможность выбрать одну из следующих наград:\n\nНаделяющая властью подвеска\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11262] = {title = "Ингвар должен умереть!", objective = "Темный следопыт Марра просит вас убить Ингвара Расхитителя в Крепости Утгард.", description = "Я единственная оставшаяся в живых из всего разведывательного отряда. \n\nЭти врайкулы – безжалостные воины. Учитывая их численность и беспощадность, у нас есть единственная надежда на спасение – убить их предводителя и уповать на то, что тем самым мы повергнем их войска в хаос. \n\nЕго зовут Ингвар. Принеси мне его голову!", progress = "Выше нос, |3-6(орк). \n\nНам еще так много предстоит совершить. Грубо говоря, это всего лишь верхушка айсберга.", completion = "Отличная работа, Верлоз. После смерти предводителя врайкулов мы должны добиться более впечатляющих успехов в войне против этих тварей. \n\nТакой подвиг должен быть достойно вознагражден!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо палачаКольцо травлиПерстень быстрого приговора\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11263] = {title = "Очистить Гьялерброн", objective = "Вождь Прахтотем попросил вас убить 15 гьялербронских воинов, 8 гьялербронских руночаров и 8 гьялербронских сноходцев, после чего вернитесь в Лагерь Заиндевевшего Копыта.", description = "Выжившие гонцы сообщили, что врайкулы замышляют нечто недоброе в своей главной крепости к западу отсюда. \n\nЭто запретное место зовется Гьялерброн. Мои выносливые гонцы доложили, что врайкулы проводят там некие странные ритуалы. \n\nЭтого мы не можем допустить.\n\nХочешь помочь нам? Тогда убей врайкулов в Гьялерброне прежде, чем они закончат свои приготовления и нападут на нас!", progress = nil, completion = "Благодарю тебя, Расул. Я знаю, что ты ничем не обязан моему народу.\n\nНо это место все еще меня беспокоит, и я боюсь, что наша война еще не окончена.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11264] = {title = "Некровладыка Мезхен", objective = "Убейте некровладыку Мезхена. Затем вернитесь к вождю Прахтотему в Лагерь Заиндевевшего Копыта.", description = "Мертвецы уже пришли в Гьялерброн, и они привели с собой некромантов?\n\nПредводитель этих некролордов должен умереть!\n\n<имя>, на твои плечи ложится огромная ответственность – ты <должен/должна> сорвать планы некровладыки Мезхена и уничтожить его самого.\n\nЯ не допущу, чтобы эти врайкулы заключили союз с мертвецами! \n\nМезхена можно найти на платформе в дальнем правом квартале Гьялерброна.", progress = nil, completion = "&lt;Вождь Прахтотем облегченно вздыхает.&gt;\n\nНу, теперь мы можем вздохнуть спокойно.\n\nРасул, ты снова подтвердил свою значимость для Лагеря Заиндевевшего Копыта и всех таунка. Пожалуйста, выбери себе что-нибудь из нашей сокровищницы. Я настаиваю.", rewards = "Наплечники из шкуры воргаПлетеные сумеречные поножиПозолоченный ремень из хладосталиПелерина необыкновенной щедростиВы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11265] = {title = "О ключах и клетках", objective = "Великая Мать Анкха попросила вас собрать достаточное количество ключей от гьялербронских клеток, чтобы освободить 10 гьялербронских узников. Когда вы выполните задание, вернитесь к ней в Лагерь Заиндевевшего Копыта.", description = "Насколько нам известно, врайкулы совершают какие-то омерзительные ритуалы \"пробуждения\" к северу от Гьялерброна.\n\nВ ходе этих обрядов проливается кровь невинных жертв!\n\n<имя>, ты <должен/должна> остановить это! Неважно, кого они держат в своих клетках для жертвоприношений – их надо освободить. Могу поспорить, врайкулы носят ключи при себе.\n\nНам не нужны эти мерзкие врайкулы поблизости, и еще меньше нам хочется разбираться с тем злом, которое они пытаются пробудить!", progress = nil, completion = "Когда я услышала о твоем успехе, у меня словно камень свалился с плеч! И еще больше я рада узнать, что некоторые из освобожденных тобой пленников были из племени таунка.\n\nПожалуйста, прими это в знак признательности за все, что ты сделал для нас. А я пока позабочусь о несчастных узниках.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11266] = {title = "Гьялербронский план нападения", objective = "Отнесите гьялербронский план нападения Целее Ледогрив в Лагерь Заиндевевшего Копыта.", description = "Вы держите в руках планы нападения на Лагерь Заиндевевшего Копыта. Похоже, что врайкулы собираются использовать для атаки ледяного змея, Ледиона, который кружит у вас над головой.\n\nНаверняка, Целея Ледогрив сможет что-нибудь предпринять, если вы доставите эти планы к ней в восточный лагерь.", progress = "Что это?! Планы нападения на лагерь?\n\nОНИ ПОСЫЛАЮТ К НАМ ЛЕТУЧЕГО ЗМЕЯ?!", completion = "Близарджин, мы не можем допустить, чтобы эти планы осуществились!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11267] = {title = "Ледяной змей и его повелитель", objective = "Убейте Зловещего призывателя драконов и воспользуйтесь его рогом, чтобы позвать обратно Ледиона. Убейте ледяного змея и принесите рог Целее Ледогрив в Лагерь Заиндевевшего Копыта.", description = "Ты мудро <поступил/поступила>, доставив ко мне этот документ. Увы, мои ветрокрылы вряд ли справятся с ледяным драконом. Тебе придется <самому/самой> отправиться на запад, в Гьялерброн. Убей этого змея и его хозяина, Зловещего призывателя драконов!\n\nНадеюсь, они еще не выпустили это ледяное чудовище в небо.\n\nНо, даже если это уже произошло, и змей движется на нас, его можно отозвать обратно с помощью рога призывателя драконов. Звук рога привлечет Ледиона, и он приземлится обратно, на платформу слева от Гьялерброна. Уничтожь его!\n\nПожалуйста, <имя>, когда все закончится, принеси мне этот рог. Нельзя допустить, чтобы он попал не в те руки.", progress = "Ледяной змей и его хозяин мертвы?\n\nНо где же рог?", completion = "Этот рог холоднее льда, покрывающего землю!\n\nРасул, ты спас Лагерь Заиндевевшего Копыта от неминуемой гибели. Признаться, раньше я с предубеждением относилась к представителям твоей расы.\n\nЧто ж, ты заслужил эту награду. Выбирай!", rewards = "Землистые обмоткиШлем магического пикаРукавицы из сребросталиВам дадут возможность выбрать одну из следующих наград:\n\nПерстень пропавшего врайкула\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11268] = {title = "Ходячие мертвецы", objective = "Убейте 10 бессмертных дозорных, 4 чудовищных ужаса и 2 тлетворных существа, после чего уведомите Великую Мать Анкху из Лагеря Заиндевевшего Копыта об успешном выполнении поручения.", description = "Ты уже <сделал/сделала> для нас больше, чем мы рассчитывали, <имя>, но меня по-прежнему беспокоит одна проблема: Плеть.\n\nДухи земли и воздуха, огня и воды не переносят присутствия этих тварей, но ничего не могут им противопоставить. Это значит, что за дело должны взяться мы! \n\nВозможно, я прошу слишком многого, но ты <должен/должна> вернуться на запад, в Гьялерброн, и уничтожить логово этой омерзительной Плети! Не забудь проверить, не остались ли эти презренные твари в чертогах Пробуждения, что под Гьялерброном.", progress = nil, completion = "&lt;Великая Мать одобрительно кивает, слушая ваш рассказ.&gt;\n\nСпасибо тебе, Расул. Ты правильно поступил, и, благодаря твоим усилиям, у нас появилось время, чтобы закончить приготовления к походу. Скоро начнется наше путешествие на север.\n\nЯ уже слишком стара; мне не унести с собой все эти пожитки. Пожалуйста, возьми одну из этих вещей.", rewards = "Монаршие кюлотыПлеменной нагрудный доспехИзмазанные глиной наголенникиВам дадут возможность выбрать одну из следующих наград:\n\nПодвеска из зуба ворга\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11269] = {title = "Работаем до упора", objective = "Гил Гризерт просит вас принести ему 10 клочков пуха пятнистых гиппогрифов.", description = "Со дня на день прибудет авангард войск Альянса. Всех этих солдат надо переодеть в зимнюю униформу, а я еще не закончил шить плащи. \n\nЯ подбиваю наши плащи пухом пятнистых гиппогрифов, но мои запасы не бесконечны!\n\nПомоги мне, <имя>. Капитан Адамс с меня шкуру сдерет, если плащи не будут готовы к сроку! Принеси мне весь пух, который сможешь найти. В чаще вокруг форта всегда полно линяющих гиппогрифов. Их пух валяется повсюду.", progress = "Ты нашел пух гиппогрифов? Ох, как он мне сейчас нужен!", completion = "Слава богам! Этого хватит, чтобы закончить пошив плащей к сроку. Ночами спать не буду, но закончу работу до прибытия войск. Все лучше, чем попасться под горячую руку капитану Адамсу.\n\nНаслышан я про этого вояку!", rewards = "Мастерски выделанные поножиКираса из поющей чешуиЗакаленные льдом бронзовые ножные латыВам дадут возможность выбрать одну из следующих наград:\n\nМерцающее кольцо из хладного железа\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11270] = {title = "Ужасы войны", objective = "Верховный палач Ансельм из Лагеря Возмездия просит вас взять горящий факел и сжечь десять трупов, лежащих к западу от города.", description = "Мы постепенно заканчиваем зачистку северного флота Штормграда, высадившегося на побережье. Схватка была ожесточенной, чему свидетельствует множество мертвых тел на западе.\n\nНет, эти трупы не оскорбляют мое чувство прекрасного, но они могут стать угрозой всем нам.\n\nВидишь ли, в землях Короля-лича мертвецов очень легко превратить в оружие. Возьми этот факел и сделай все возможное, чтобы этого не произошло.", progress = nil, completion = "Рад слышать, что ты ответственно относишься к приказам. Если бы мне давали по медной монете за каждого самонадеянного дурака в нашей армии, считающего, что он умнее своего командира... пожалуй, я бы уже скопил несколько золотых.\n\nТеперь же, когда ты доказал свою дисциплинированность, я могу поручить тебе более ответственное задание.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11271] = {title = "Спешные приготовления", objective = "Ахота Белый Иней из Лагеря Заиндевевшего Копыта просит вас принести ему 10 клочков пуха пятнистых гиппогрифов.", description = "Пух пятнистых гиппогрифов очень ценится среди моего народа и используется в самых разнообразных целях – от оперения стрел до пошива церемониальной одежды. Поскольку мы готовимся покинуть аванпост, это наша последняя возможность набрать пух в сезон линьки.\n\nС твоей помощью я сделаю достаточный запас пуха, которого хватит на все путешествие. А дорога обещает быть нелегкой!\n\nИщи клочья пуха повсюду на земле вокруг аванпоста.", progress = "Ты нашел пух гиппогрифов?", completion = "С твоей помощью мы сможем хорошо подготовиться к этому нелегкому путешествию. Мне почти нечем тебя отблагодарить, но все же возьми одну из этих вещей, лежащих у меня без дела.", rewards = "Мастерски выделанные поножиКираса из поющей чешуиЗакаленные льдом бронзовые ножные латыВам дадут возможность выбрать одну из следующих наград:\n\nМерцающее кольцо из хладного железа\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11272] = {title = "Сведение счетов", objective = "Верховный палач Ансельм велел вам отправиться в Утгард и убить принца Келесета.", description = "Этот эльфийский принц Келесет полагает, что может прийти в мой город, оскорбить королеву, убить моих людей и спокойно уйти прочь? Он думает, что мы будем стоять в стороне, пока орды Утгарда будут готовиться к нападению?\n\nНе бывать этому!\n\nТы отправишься в Утгард и убьешь его. Пусть Артас знает, что намерения наши серьезны.\n\nКогда покончишь с ним, доложи темному следопыту Марре. Пусть она подчистит за тобой следы.", progress = nil, completion = "Ах, месть сладка. Подумать только – и это лишь начало!\n\nСкоро Артас получит по заслугам. Тогда и только тогда я умру счастливым.", rewards = "Напульсники Сан'лейнаНаручники кровной местиНаручи заклинателя рунТяжелые наручи несущего местьВы получите:\n\n"}
MultiLanguageQuestData['ru'][11273] = {title = "Объединение людей", objective = "Найдите Пулроя в Деревне Драконьего Черепа.", description = "Мы были на грани величайшего археологического открытия, когда эти чудовища напали на наш лагерь! Увы, вернуться в Валгард удалось только мне одному. Я даже не знаю, что стало с моими людьми, и куда пропали артефакты, которые мы достали из раскопа! Как бы то ни было, их надо вернуть!\n\nРаз уж ты все равно направляешься в Деревню Драконьего Черепа, поищи, пожалуйста, моих сослуживцев! Если есть хоть какая-то надежда сохранить полученную информацию, мы должны ей воспользоваться!\n\nПрежде всего постарайся найти Пулроя. Когда я бежал из лагеря, он был еще жив.", progress = nil, completion = "Вы нашли Пулроя – увы, слишком поздно.\n\nОбыскав тело археолога, вы видите журнал, крепко зажатый в руке Пулроя. Похоже, это предсмертные записи несчастного дворфа.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11274] = {title = "Зедд мертв, детка?", objective = "Найдите Зедда в Деревне Драконьего Черепа.", description = "Тому, кто найдет этот журнал:\n\nЭти кровожадные мерзавцы захватили руины Драконьего Черепа. Я не знаю, зачем они сюда пришли и чего добиваются. Честно говоря, мне все равно – я беспокоюсь только за сохранность артефактов.\n\nПрячась в этом месте, мы с Зеддом натолкнулись на потрясающее открытие: мы обнаружили шифр к табличкам! К несчастью, прошлой ночью Зедд отстал. Шифр все еще у него. Таблички унесли Глоренфелд и Дегарн. Где они – неизвестно...\n\nНайди Зедда.\n\n-Пулрой", progress = nil, completion = "Вы нашли Зедда. Увы, не надо быть доктором, чтобы понять, что для бедняги все кончено.\n\nПохоже, его собирались скормить воргам. Бедняга...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11275] = {title = "Охотничий рог", objective = "Нокома Заклинатель Снегов из Лагеря Заиндевевшего Копыта просит вас принести ей 6 неповрежденных рогов барана.", description = "Многие поколения мои соплеменники охотились на гигантских йети, обитающих в этих холмах. В этом году наконец-то настал мой черед присоединиться к охоте. Надеюсь, мы успеем загнать немало йети перед тем, как навсегда покинем эти края.\n\nЧтобы подготовиться к охоте, мне надо вырезать охотничий рог из рогов жутких баранов, которые бродят вокруг нашего лагеря. Старейшины сказали, что звук охотничьего рога напоминает брачный зов самки йети, но мне в это верится с трудом.\n\nВпрочем, неважно – главное, сделать рог. Давай ты принесешь мне самые лучшие рога барана, а я выберу себе один для отделки.", progress = "Ты нашел какие-нибудь подходящие рога?", completion = "Какие отличные рога, Дкд! Сейчас я осмотрю их повнимательнее и выберу один для обработки.\n\nА остальные я отдам нашим мастерам – пусть сделают из них что-нибудь красивое.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11276] = {title = "И их осталось двое...", objective = "Обыщите Катакомбы Утгард в поисках Глоренфелда.", description = "Похоже, у Зедда не было с собой шифра. Тщательно осмотрев местность, вы находите в грязи надпись, которая гласит:\n\n\"Глор и Дег в катакомбах. Шифр и таблички у них.\"\n\nПохоже, вам придется отправиться в катакомбы, которые находятся к северу от этого места, и найти Глоренфелда и Дегарна. За мостом, перекинутым через яму с воргами, виднеется туннель, который ведет прямо в катакомбы.", progress = nil, completion = "Ну наконец-то! Пулрой и Зедд мертвы.\n\nА Дегарн...\n\n&lt;Глоренфелд качает головой.&gt;\n\nВождь Укротителей драконов утащил его в глубину катакомб. Я услышал краем уха, как этот гамадрил-переросток говорил что-то о \"пожертвовании Королю ужаса\"\n\nШифр у него, спрятан в бороде.\n\nЧего-о? Дворфы всегда прячут самые ценные вещи в бороде!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11277] = {title = "Глубины порока", objective = "Глоренфелд из Катакомб Утгард просит вас собрать 10 табличек Драконьего Черепа.", description = "Они держат Дегарна в запертой клетке на огромной арене для гладиаторских боев. Насколько я понял, Укротители драконов выпускают своих пленников на эту арену, чтобы те сражались с самыми безжалостными врайкульскими бойцами. Неудачников они скидывают вниз, в подвалы, где Плеть превращает их в зомби! Ужасно, не правда ли?\n\nНо сначала мы должны решить первоочередные проблемы. Главное – собрать таблички, которые разбросаны по всему подземелью! Найди их – а потом можешь играть в героя-освободителя!", progress = "Проверь каждый уголок!", completion = "Ты молодец, дружище. Теперь, когда таблички в безопасности, мы можем попытаться спасти Дегарна и вернуть шифр, который поможет нам расшифровать тайный смысл этих древних надписей!\n\nДавай так: я буду сторожить таблички, а ты освободишь моего коллегу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11278] = {title = "Возвращение в Валгард", objective = "Отнесите сверток Глоренфелда Белтранду Максорфу в Валгардский порт.", description = "Мне горько думать о том, что мы потеряли двух наших лучших дворфов в поисках этих святынь. Они пожертвовали своими жизнями, чтобы сохранить и донести до нас эту информацию.\n\n<Глоренфелд заворачивает шифр и таблички в потрепанный платок.>\n\nОтнеси это назад, в Валгард. Максорф знает, что надо делать.\n\nЯ? Со мной все будет в порядке. Видишь – я пока что цел и невредим.", progress = "Ты вернулся!", completion = "Мне понадобится время, чтобы рассортировать эти таблички. Но я уверен, что мои исследования прольют свет на тайну происхождения людей. Я уверен, что когда-то здесь жили наши предки, но все они были уничтожены врайкулами. Как только я расшифрую надписи на этих святынях, мы узнаем правду.", rewards = "Наплеч из эластичной кожиНапульсники ДиконаЗакругленные высокие ботинкиОтслужившие тирасские латыВы получите:\n\n"}
MultiLanguageQuestData['ru'][11279] = {title = "Зеленые и светящиеся", objective = "Распространитель чумы Тилингаст попросил вас собрать 10 образцов плоти зачумленных детенышей протодраконов и отнести их к нему в Новый Агамонд.", description = "Мы разработали превосходную чуму, и мне не терпится расширить поле экспериментов. \n\nМожет быть, нам испытать ее на детенышах протодраконов?!\n\nТы только подумай о том, какие возможности открываются перед нами! Мы станем первооткрывателями штамма, способного поражать всех живых существ!\n\nВот, я отложил на всякий случай запасную канистру с чумой. Полагаю, я могу доверить ее тебе.\n\nОбрызгай яйца протодраконов в Пылающем Гнездовье на северо-западе, после чего возьми образцы зачумленных детенышей протодраконов, которые вылупятся из зараженной кладки.", progress = "Без этих образцов я не смогу доказать нашему научному сообществу, что мой штамм способен поражать все живые организмы!", completion = "Что?! Нет, не может быть!\n\nПРОКЛЯТИЕ!\n\nЭтот штамм чумы не оказал практически никакого воздействия на детенышей протодраконов – разве что теперь они стали зелеными и светящимися!\n\nА я так мечтал изобрести чуму, которая уничтожала бы любое живое существо!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11280] = {title = "Драконис гастритис", objective = "Распространитель чумы Тилингаст просит вас приманить протодракона с помощью куска зачумленного мяса Тилингаста и понаблюдать за его реакцией на угощение.", description = "У меня появилась мысль. Что если чума не убила дракончиков потому, что мы распыляли отраву снаружи?\n\n<имя>, мы должны как-то заразить их изнутри!\n\nПридумал! Вот, держи кусок зачумленного мяса. Отнеси его в Пылающее Гнездовье и скорми дракончикам!\n\nХотя нет, мы должны мыслить шире. Лучше примани с его помощью большого протодракона – пусть он спустится с неба и сожрет наше угощение.\n\nЯ гений!\n\nКстати, не отходи далеко от нашего подопытного и наблюдай, что произойдет. Он, конечно, может напасть на тебя... но такова цена прогресса!", progress = nil, completion = "НЕЕЕЕЕЕЕЕТ!!!\n\n&lt;Распространитель чумы рвет на себе волосы.&gt;\n\nМои надежды... все мои мечты пошли прахом!\n\nОставь меня, Профессия. Оставь меня наедине с моим горем. Я ничтожество.\n\nВот, забери все, что у меня есть. Когда остальные фармацевты узнают о моей неудаче, со мной будет все кончено. Все равно я не заберу эти побрякушки с собой в могилу.", rewards = "Фиолетовое одеяние восполненияОбшитые железом поножиРемень двойного плетенияБлаготворный шлемВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11281] = {title = "Подражая зову природы", objective = "Испытайте вырезанный рог и верните его Нокоме Заклинателю Снегов в Лагерь Заиндевевшего Копыта.", description = "Я обточила рог, но прежде чем наносить на него традиционную резьбу, надо убедиться, что он работает. Ахота говорил, что он испытывает свои охотничьи рога у подножия замерзшего водопада на северо-востоке лагеря. Он утверждает, что наши охотники уже много поколений используют акустику льда для этой цели.\n\nТы поможешь мне испытать рог? Если я правильно его вырезала, то на его зов может откликнуться сам великий йети! Только не забудь вернуть мне рог после проверки.", progress = "Довелось ли тебе испытать рог?", completion = "&lt;Нокома слушает о результатах испытания.&gt;\n\nПриятно слышать, что рог сработал, как надо... может быть, даже лучше, чем я рассчитывала. Но... неужели этот зверь действительно говорил с тобой? Не знаю даже, как теперь на него охотиться. Надо посоветоваться с вождем Прахтотемом.\n\nВозможно, в итоге мне никогда не придется воспользоваться этим рогом, но это не уменьшает его ценности. Спасибо тебе за помощь, Профессия.", rewards = "Гхоламская перевязьПокрытые письменами ботинки из шкуры воргаСпециальные чешуйчатые поножиВам дадут возможность выбрать одну из следующих наград:\n\nБутыль самогона Браксли\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11282] = {title = "Урок страха", objective = "По приказу Горта вам надо победить Улфа Кровопускателя, Орика Зловещего и Гуннара Торвардссона, после чего проткнуть их тела древком знамени Отрекшихся. Убивайте врайкулов вдоль баррикады, возведенной Отрекшимися, пока не появятся чемпионы.", description = "Когда ты побываешь в стольких же переделках, как и Горт, ты поймешь, что врага можно победить лишь тогда, когда он боится тебя до смерти! \n\nНо эти врайкулы нас не боятся. Убьешь одного – на его место приходит другой... только вопит еще громче, и секира у него больше в два раза.\n\nТолько смерть самого большого и страшного врайкула может напугать все это племя.\n\nИди же и сражайся со Снежескорнами, пока не появятся их чемпионы. Убей их всех и проткни трупы древком флага Отрекшихся. Пусть они узнают, что такое страх!", progress = nil, completion = "Молодец, ты хорошо потрудился. Я видел, как пали врайкулы, пронзенные древком флага Сильваны. Да, сегодня победа на нашей стороне!", rewards = "Штаны сухоходаКольчужный шлем с королевским плетениемСкалорубВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1Кольцо ловкости рук\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11283] = {title = "Кровавая бойня в Гибльхейме", objective = "Сержант Горт просит вас убить 16 снежескорнских врайкулов в Гибльхейме.", description = "Эти врайкулы так и прут из западного поселения! Можно подумать, они там почкованием размножаются – так их много.\n\nНо у Горта есть идея. Ты <сам/сама> пойдешь в этот город и перебьешь всех Снежескорнов. Тогда они перестанут лезть к нам!", progress = nil, completion = "Я гляжу, тебе не впервой убивать! Справляешься с этим делом не хуже Горта!", rewards = "Наплеч из эластичной кожиНапульсники ДиконаЗакругленные высокие ботинкиОтслужившие тирасские латыВы получите:\n\n"}
MultiLanguageQuestData['ru'][11284] = {title = "Соседство с йети", objective = "Старшина Колби из крепости Вилдервар просит вас убить Сколорога.", description = "Если охранники не желают помогать мне – может быть, ты меня поддержишь? Я – старшина шахты, которая находится за мостом. Мои люди добывают руду, которая пойдет на выплавку оружия для разведывательных отрядов. Без наших поставок они не смогут расчистить путь к Седым холмам.\n\nНо недавно шахту захватил гигантский йети, преградив путь к тоннелю, который нам необходимо расширить! Мы пытались напугать его криками и даже пробовали выкурить его оттуда, но ничего не получилось.\n\nМожет быть, ты сможешь разбудить его запахом свежей баранины? Вокруг города по снегу бродят множество ледорогих баранов. Пожалуйста, помоги нам! Мы в отчаянии!", progress = nil, completion = "Удалось? Во имя Света, ты мой спаситель! Я уж начал подбирать слова, как извиняться перед капитаном Адамсом за то, что оружие для его солдат все еще не готово!", rewards = "Гхоламская перевязьПокрытые письменами ботинки из шкуры воргаСпециальные чешуйчатые поножиВам дадут возможность выбрать одну из следующих наград:\n\nБутыль самогона Браксли\n\nВы также получите:\n\nПредмет #4Предмет #1"}
MultiLanguageQuestData['ru'][11285] = {title = "Гори, Гибльхейм!", objective = "Сержант Горт послал вас в Гибльхейм с факелом Горта, чтобы вы сожгли 1 снежескорнское здание, 1 снежескорнскую сторожевую башню, 1 снежескорнский мост и 1 снежескорнские казармы.", description = "Недостаточно просто убить Снежескорнов – мы должны сжечь их дома! Э... и мосты тоже. Давай спалим весь город – на всякий случай!\n\nВот, возьми факел. Иди в Гибльхейм, на запад, и сожги его ДОТЛА! Это научит их бояться.", progress = nil, completion = "Похоже, ты сжег почти все постройки. Осталось несколько зданий... но Горт доволен тем, что видит.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11286] = {title = "Артефакты Стальных ворот", objective = "Ведун Странник Туманов попросил вас принести 10 артефактов Стальных ворот. Когда вы соберете их все, вернитесь к ведуну в Стальные ворота.", description = "Я пришел сюда по другой причине – мой старый друг явился ко мне во сне и просил о помощи. Но когда я увидел эти штуковины, роющие огромную яму в земле, меня охватила ярость.\n\nНасколько я понимаю, эти так называемые дворфы выкапывают древние артефакты, которые могут пролить свет на наше прошлое.\n\nПожалуйста, спустись туда и принеси их мне. Надеюсь, ни один из дворфов не станет у тебя на пути.", progress = "Сколько артефактов ты нашел в Стальных Воротах?", completion = "&lt;Ведун одобрительно кивает.&gt;\n\nВозможно, мне удастся выкроить время для исследования этих артефактов и понять их предназначение.\n\nНо сейчас меня ждут более важные дела.", rewards = "Трескучий плащВам дадут возможность выбрать одну из следующих наград:\n\nКольцо ретивостиТалисман из клыка ворга\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11287] = {title = "Найти ведуна Странника Туманов", objective = "Великая Мать Анкха попросила вас найти ведуна Странника Туманов. Она полагает, что он сейчас находится где-то рядом со Стальными Воротами.", description = "<класс>, я беспокоюсь за своего сына, ведуна Странника Туманов. Земли эти жестоки и беспощадны, а от него давно не было никаких вестей.\n\nОн сказал, что видит сны про какого-то волка, после чего собрал маленькую группу выносливых гонцов и отправился на запад. Мне кажется, он упоминал некое место под названием Стальные ворота.\n\nНе <мог/могла> бы ты отправиться на его поиски? Я должна убедиться, что с ним все в порядке.", progress = nil, completion = "Ах, мама слишком заботится о моей безопасности. Но, в любом случае, спасибо за то, что разыскал меня, незнакомец.\n\nКстати, раз уж ты здесь, может быть, поможешь мне в одном деле?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11288] = {title = "Сияние света", objective = "Арес Поклявшийся, лежащий при смерти в Катакомбах Утгард, попросил вас вернуть священный артефакт.\n\nЭто задание ограничено по времени.", description = "<Арес тяжело дышит, пытаясь обратиться к вам.>\n\nЯ – посланник Серебряного Авангарда, исполняющий свой священный долг.\n\nНаши силы были уничтожены в Чумных землях. Сиянием рассвета артефакт был очищен и избавлен от скверны. Многие из нас сгинули ради возвращения этой святыни.\n\nНо надежда все еще жива... еще есть время.\n\nАртефакт был унесен в логово Павших, что вырыто глубоко под нами. Его охраняют безжалостные мертвецы.\n\n<Тело Ареса начинает светиться непереносимо ярким светом.>\n\nСвет... защитит... тебя...", progress = "<Арес без сознания.>", completion = "Вам кажется, что будет правильно положить священный клинок рядом с телом Ареса.\n\nКак только вы кладете меч, вас снова ослепляет яркий свет.", rewards = "Заиндевелый кинжалТесак с каменным лезвиемШокер из черепа дракончикаМонарший скипетрДлинный лук ледяного шипаСносившийся сокрушитель врайкуловВы получите:\n\n"}
MultiLanguageQuestData['ru'][11289] = {title = "Ведомый честью", objective = "Верните священный артефакт лорду Ирулону Верный Клинок в Валгард.", description = "<Арес улыбается.>\n\nСлава Свету. Ты <успел/успела>! \n\n<Арес кашляет.>\n\nВозьми этот артефакт и отнеси его в Валгард. Лорд Ирулон Верный Клинок ожидает его возвращения.\n\nСражайся с честью, друг мой. Всегда. Честь превыше всего.\n\n<Арес умирает.>", progress = "Во имя Света!", completion = "Многие мужчины и женщины пожертвовали своими жизнями ради возвращения этого клинка. Увы, я боюсь, что со смертью благородного Ареса кровопролитие не закончится. \n\nНо ты совершил угодный Свету поступок. Этот священный клинок возьмет в свои руки сам лорд Тирион Фордринг. Даже в эти минуты Серебряный Авангард продолжает наступление на Ледяную Корону. Лорд Фордринг поклялся самолично разрушить стены этой проклятой крепости! Теперь же он сможет обратить этот клинок против самого Короля-лича.\n\nЛорд Фордринг – это наша последняя надежда и опора.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11290] = {title = "Военные планы клана Укротителей драконов", objective = "Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде поручил вам достать военные планы клана Укротителей драконов.", description = "Хотя мы мало что знаем о местонахождении Ингвара, нам точно известно, что Янис обитает в пещере рядом с воргской ямой в Деревне Драконьего Черепа.\n\nРазведданные, полученные от спасенных солдат, подтверждают, что Янис охраняет военные планы клана Укротителей драконов.\n\nТы <должен/должна> вернуться в Деревню Драконьего Черепа и забрать эти планы. Убивай всех врайкулов, которые встретятся тебе на пути, включая Яниса!", progress = "Военные планы у тебя?", completion = "&lt;Вице-адмирал Келлер бегло проглядывает планы.&gt;\n\nНевероятно! Судя по всему, в фьорде есть несколько поселений врайкулов. Еще одно племя планирует нападение на Крепость Западной Стражи. О боги, возможно, мы уже опоздали! Я уже несколько дней не получал известий из крепости. Как бы то ни было, мы должны их предупредить!", rewards = "Капюшон щедростиРасшитая костями курткаПлетеные поножи в кровавых пятнахВнутренний панцирь нерубаВы получите:\n\n"}
MultiLanguageQuestData['ru'][11291] = {title = "В Крепость Западной Стражи!", objective = "Отнесите военные планы Укротителей драконов капитану Адамсу в Крепость Западной Стражи в Ревущем фьорде.", description = "<Вице-адмирал Келлер сворачивает тактические планы.>\n\nС помощью этой информации мы укрепим оборону Валгарда. Отнеси эти военные планы в Крепость Западной Стражи, которая выстроена на западном обрыве фьорда. Поговори с помощницей распорядителя полетов, Эмиленой Зимний Ветер. Пусть она подыщет тебе грифона, знающего путь в Крепость.\n\nКак только прибудешь на место, найди капитана Адамса. Он командует крепостью и знает, что делать с этими планами.", progress = "Валгард еще стоит на месте? Вот чудеса.\n\nСомневаюсь, что Келлер обошелся без твоей помощи.", completion = "&lt;Капитан Адамс забирает у вас планы.&gt;\n\nХорошо, что ты нашел время занести сюда эти планы. Моим советникам понадобится немало времени, чтобы изучить их досконально. Чувствую я, грядут тяжелые времена!", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11292] = {title = "Слабое звено", objective = "Зверолов Джетан из крепости Вилдервар просит вас принести ему 8 пойманных зверьков.", description = "Рад встрече, <имя>. Я пришел сюда с Седых холмов, чтобы вести дела с твоими союзниками. Мои люди раскинули огромный лагерь на севере, и я искренне рекомендую тебе заглянуть туда.\n\nКстати, по пути я расставил множество силков в лесах и на заснеженных полянах. Частенько в них попадаются зверьки, чей мех и мясо я обмениваю на всякие полезные товары.\n\nМогу предложить тебе долю от доходов, если ты согласишься время от времени приносить мою добычу. Только будь <осторожен/осторожна> – мы здесь не единственные хищники.", progress = "Надеюсь, ты вернулся не с пустыми руками. Мы же договорились!", completion = "&lt;Зверолов Джетан осматривает пойманных зверьков.&gt;\n\nЗа эту добычу я выручу хорошие деньги, но для торговли мне надо скопить побольше товара.", rewards = "Поножи силы землиЗапатентованная ушанка ВыкрутеняМагический щитСапоги главного артиллеристаВы получите:\n\n"}
MultiLanguageQuestData['ru'][11293] = {title = "Пивоварня Ячменоваров ищет зазывалу!", objective = "Зазывайте посетителей на Хмельной фестиваль у флагов в Палатах войны, в Зале исследователей и в Палатах магии.", description = "На Хмельном фестивале нам не обойтись без рекламы наших напитков. В Палатах войны, в Зале исследователей и в Палатах магии установлены флаги. Возле каждого из них нужно зычно прокричать хвалу Ячменевцам. Чтобы упростить задачу, я одолжу тебе на 4 минуты поводья и скакового барана. Подгоняй его с помощью поводьев, но не переусердствуй.", progress = nil, completion = "Молодец! Надеюсь, мы к себе переманили клиентов.\n\nА вот и обещанная награда. Мы, Ячменовары, держим слово.\n\nАх да, заходи завтра, можешь еще раз поработать зазывалой.", rewards = "Вы получите:\n\nПризовой жетон Хмельного фестиваля"}
MultiLanguageQuestData['ru'][11294] = {title = "Пивоварня Громоваров ищет зазывалу!", objective = "Зазывайте посетителей на Хмельной фестиваль у флагов в Палатах войны, в Зале исследователей и в Палатах магии.", description = "Пора сообщить народу, что его мольбы о добром пиве услышаны! В Палатах войны, в Зале исследователей и в Палатах магии установлены флаги. Возле каждого из них нужно зычно прокричать хвалу Громовару.\n\nМы решили упростить твою задачу. Тебе будет выдан баран и поводья на целых 4 минуты!\n\nТолько не очень-то гони барана, ящиков с яблоками в Стальгорне нет... Мы не позволим зазывалам Ячменевца нас обойти!", progress = nil, completion = "Отлично! Думаю, мы показали этим нахалам, Ячменоварам.\n\nМы обещали тебе награду. Вот она. Мы, семейство Громоваров, одариваем тебя призами, а Ячменовары – только вонью и ложными посулами.\n\nТы сделал правильный выбор.\n\nЕсли ты и дальше хочешь держаться нашей семьи, заходи завтра и еще раз поработай зазывалой.", rewards = "Вы получите:\n\nПризовой жетон Хмельного фестиваля"}
MultiLanguageQuestData['ru'][11295] = {title = "В наступление!", objective = "Поговорите с сержантом Гортом на баррикаде рядом с подъемником к западу от Лагеря Возмездия в Ревущем Фьорде.", description = "Мы практически ничего не знаем о врайкулах. За многие века они никак себя не проявляли, и потому не упомянуты в наших записях. Но стоило нам выступить против Артаса, как они появились на нашем пути. \n\nПринесенная тобой карта подтверждает, что мы сначала должны разделаться с ними, и только потом следовать вглубь материка. \n\nОдин из моих лучших сержантов, поганище по имени Горт, надзирает за баррикадой у подъемника, наверху. Окажи ему помощь в организации превентивного удара по Гибльхейму. Если врайкулы решат напасть на нас, то это произойдет именно там.", progress = nil, completion = "Пришел помочь нам? Это хорошо...\n\nГорту уже надоело весь день убивать врайкулов. Помощь мне пригодится!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11296] = {title = "Пленники терзающих вдов", objective = "Тученеб попросил вас освободить 7 выносливых гонцов из лагеря Заиндевевшего Копыта. Выполнив это задание, вернитесь к нему в Стальные ворота.", description = "Что-то беспокоит обитающих в этих краях существ – возможно, это живые мертвецы Плети.\n\nСопровождая ведуна, мы потеряли почти половину отряда из-за терзающих вдов – огромных и смертоносных пауков, населяющих Вырубки к северу отсюда.\n\nУвы, я не могу оставить оставшихся людей без защиты, но... ты ведь можешь узнать, что случилось с моими выносливыми гонцами? Возможно, терзающие вдовы не убили их, а только заключили в свои коконы.\n\nТы поможешь мне, <незнакомец/незнакомка>?", progress = nil, completion = "Ты совершил подвиг, |3-6(Маг). Я даже не представлял, что твой народ способен на такую жертвенность ради других.\n\nВ следующий раз я прислушаюсь к предостережениям старейшин и стану обходить Вырубки стороной. Чего и тебе советую.", rewards = "Поручи ледобояПокрытая льдом накидкаУкрепленный шкурой моржа хауберкРемень кровоплетаВы получите:\n\n"}
MultiLanguageQuestData['ru'][11297] = {title = "Слежка за нарушителями границ", objective = "Поговорите с аптекарем Малтусом в Аптекарском поселке.", description = "Даже сама земля не в силах сдержать натиск смерти. Бродят по ней мертвецы, распространяя скверну с ужасающей скоростью. \n\nОдному небольшому исследовательскому отряду нежити удалось подняться по западным склонам и разбить лагерь возле Шепчущей теснины. Скажи мне, <имя>, сможешь ли ты понять их стремление и убедить их не отравлять наши земли? Отправляйся на юго-запад от заставы и следуй к обрывам, нависающим над западным побережьем. Ты найдешь их лагерь к западу от раскопок у Стальных ворот.", progress = nil, completion = "А, тебя послали эти бизоноподобные люди, обитающие на севере. Я видел, как они пытаются следить за нами, наивно полагая, что мы их не замечаем. Полагаю, они считают эти земли своими? Увы, придется их разубедить.\n\nЯ не ожидал твоего визита, но, раз уж этот глупец послал тебя сюда, я мог бы воспользоваться твоими услугами.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11298] = {title = "Что они пьют?", objective = "Аптекарь Малтус из Аптекарского поселка просит вас принести ему 5 дворфийских бочонков.", description = "К юго-востоку отсюда пролегает Шепчущая теснина. Ее захватили обезумевшие члены Лиги исследователей! Они напали на наш караван, который следовал через их территорию, и ограбили продовольственный отряд.\n\nЯ должен понять, что свело их с ума! Может быть, всему виной то варево в бочках, которые расставлены по всей теснине? Слушай, прикати мне несколько бочонков, пока эти дворфы будут заняты раскопками.", progress = "Так ты несешь мне бочки или нет?", completion = "&lt;Аптекарь нацеживает себе большую кружку напитка.&gt;\n\nНу, поехали!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11299] = {title = "Круг Правосудия", objective = "Найдите Дегарна в Круге Правосудия. Он заперт в Катакомбах Утгард.", description = "Возможно, ты уже <видел/видела> комнату, в которой держат Дегарна – она находится рядом с тем коридором, где ты <искал/искала> таблички. Спустись по ступенькам, и ты найдешь его в запертой камере у подножия лестницы. \n\nОтправляйся туда и отыщи его. Возможно, он хотя бы сможет сообщить тебе шифр.", progress = nil, completion = "Ура. Ты меня нашел. Йо-хо-хо!\n\nВот только шифра у меня нет. Эти мерзавцы первым делом покопались у меня в бороде! Теперь шифр у Олуфа – он глава местных гладиаторов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11300] = {title = "Поражение на ринге", objective = "Победите гладиаторов в Круге Правосудия, сразитесь с Олуфом Неистовым и заберите у него древнюю тайнопись.\n\nОтнесите тайнопись Глоренфелду ко входу в Катакомбы Утгард.", description = "До Олуфа можно добраться только одним способом – перебить всех остальных гладиаторов. Иначе нам никогда не вернуть тайнопись. Так что не медли – ступай в Круг Правосудия. Если тебе удастся получить тайнопись, принеси ее Глоренфелду ко входу в эти катакомбы. \n\nА что я? Ты обо мне не беспокойся! Самое главное – найти связующее звено, которое откроет тайну происхождения всего человечества!", progress = "Где Дегарн? А тайнопись?", completion = "Какое потрясающее приключение! Так значит, кто-то действительно вершит суд над этими несчастными созданиями? Но для чего?\n\nА, не обращай на меня внимания. Пусть с этим разбирается кто-нибудь другой. Главное, мы получили тайнопись и таблички – и потеряли всего двоих людей на этом пути.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11301] = {title = "Мозги! Мозги!", objective = "Аптекарь Грик из Аптекарского поселка просит вас принести ему 12 мозгов спятивших исследователей.", description = "Малтус уже рассказывал тебе эти бредни про пивные бочонки и спятивших дворфов? \n\nНет, я не отрицаю того, что дворфы сошли с ума, но таскать у них пиво – дурная затея.\n\nЧто нам действительно надо – это мозги. Много мозгов. Скоро мы разгадаем эту тайну и, возможно, найдем новый компонент для создания чумы.\n\nВозьми эту пилу, отправляйся в Шепчущую теснину и убей несколько дворфов. Потом распили их черепные коробки, вынь мозги и принеси их мне.", progress = "Ты принес мне мозги? Нет? Тогда отдай пилу. Лучше тебе не разгуливать здесь с этой штукой.", completion = "Какие миленькие мозги! Прелесть, честное слово! То, что надо.\n\nСпасибо за помощь, Расул. Теперь я покажу Малтусу всю глубину его заблуждения.", rewards = "Поножи силы землиЗапатентованная ушанка ВыкрутеняМагический щитСапоги главного артиллеристаВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11302] = {title = "Загадочные ледяные нимфы", objective = "Поговорите с Луриэль на Заиндевевшей поляне.", description = "Впервые осматривая окрестности форта, мы заметили враждебно настроенных существ на двух полянах к северу отсюда. Когда мы проходили мимо заснеженной прогалины к югу от города, дриады с интересом наблюдали за нами, но не нападали. \n\nМестный климат порядком измотал моих людей, и они могли с легкостью уничтожить половину нашего отряда, но не стали. \n\nВозможно, эти дриады хотят стать нашими союзниками. Не желаешь ли ты отправиться на Заиндевевшую поляну и попытаться установить с ними контакт?", progress = nil, completion = "&lt;Луриэль внимательно слушает вас.&gt;\n\nЯ рада наконец-то познакомиться с тобой, Reng. Мы надеялись, что кто-нибудь из новоприбывших пришлет к нам своих представителей. Сами мы редко выходим за границы наших полян, особенно после того, как окружающий нас мир претерпел изменения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11303] = {title = "Засада", objective = "Поговорите с Лиделлом в Засаде Лиделла.", description = "Врайкулы в Гибльхейме повержены – в этом нет никаких сомнений. Но их предводители остались в городе и не собираются сдаваться.\n\nГорт послал Лиделла и его головорезов помахать кулаками на северо-западе. Иди, поговори с ним и выясни, как выманить врайкульского вождя и убить его. Смотри только, чтобы он помучился перед смертью!", progress = nil, completion = "Вечеринка в разгаре, но наш \"почетный гость\" предпочитает отсиживаться дома.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11304] = {title = "Новый Агамонд", objective = "Отнесите штамм Лисандера главному распространителю чумы Харрису в Новый Агамонд на запад Ревущего фьорда.", description = "Боюсь, что Лагерь Возмездия недостаточно хорошо оборудован. В конце концов, это всего лишь военная база.\n\nПожалуйста, отнеси этот штамм главному распространителю чумы Харрису в Новый Агамонд. Чтобы найти город, иди по южной дороге мимо Гибльхейма, а потом поверни на запад. Он располагает более совершенным оборудованием, и знает, что делать с этим штаммом. \n\nПоторопись, <имя>. Наши враги превосходят нас силой и числом. Нам надо создать оружие, с помощью которого мы одержим победу!", progress = "Что тебе, Расул?", completion = "Друг мой, это вполне эффективный штамм! Эти идиоты из Лагеря Возмездия чуть не проморгали все на свете!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11305] = {title = "Идеальная формула", objective = "Добудьте кровь патриарха Укротителей драконов – вождя Торвальда, который укрылся в Лагере Торвальда, и принесите ее главному распространителю чумы Харрису в Новый Агамонд.", description = "Мы уже несколько недель распространяем чуму в деревне врайкулов, Халгринде, а эти макаки по-прежнему живее всех живых! \n\nСкажу прямо, <имя>: на настоящий момент мы испытали штамм на людях, дворфах, собаках, домашнем скоте... на ком угодно. Но когда вирус приспосабливается к организму носителя, он изменяется и становится менее стабильным. Поэтому нам надо разработать штамм, идеально подходящий для организма врайкулов.\n\nНезадолго до того, как мы захватили Халгринд, из деревни бежал врайкульский вождь и укрылся к западу отсюда. А что может быть чище крови предводителя клана Укротителей драконов?", progress = "Ты принес образец, Расул?", completion = "Да, этот образец подойдет. А теперь, Расул, мы наконец-то приступим к работе!", rewards = "Легковесный клейморИзъеденный кислотой кастетЧеканный кинжал из хладосталиМушкетон со взрывателемВы получите:\n\n"}
MultiLanguageQuestData['ru'][11306] = {title = "Нагреть и перемешать", objective = "Наполните пустой аптекарский флакон кровью из котла с кровью врайкулов, после чего добавляйте во флакон с кровью врайкула образцы чумы Харисса, пока не получите равномерную смесь. \n\nКогда вы выполните это поручение, вернитесь к Главному распространителю чумы Харрису.", description = "<имя>, ты уже многого <достиг/достигла> на нашем поприще. Теперь я хочу обучить тебя некоторым более сложным способам изготовления чумы.\n\nВозьми эту флягу и наполни ее кровью из котла слева от меня. Смешивай ее с образцами чумы, которые лежат справа, пока не получишь однородную смесь.", progress = "Ну, как проходит эксперимент, Расул? Если возникнут какие-либо вопросы – дай мне знать!", completion = "Превосходно! Ты мой самый талантливый ученик, Расул.\n\nА теперь займемся кое-чем более интересным: опытами!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11307] = {title = "Полевые испытания", objective = "Отправляйтесь в Халгринд и заразите ассимилированным штаммом чумы 10 зачумленных врайкулов из клана Укротителей драконов, после чего вернитесь к главному распространителю чумы Харрису.", description = "Теперь, когда мы получили штамм чумы, адаптировавшийся к нашим врайкулам-переносчикам, настало время испытать его на подопытных особях в Халгринде. Если все пойдет по плану, они распадутся на части через секунду после того, как чума проникнет в их организм!\n\nХалгринд находится к северу отсюда. Ты найдешь его с легкостью – наши распространители чумы уже там поработали.", progress = nil, completion = "Чума не уничтожила наших подопытных? Ты в этом уверен?\n\nДолжно быть, мы не учли какой-то внешний фактор... может быть, климатический? Или... возможно, произошла мутация штамма!", rewards = "Оплот щедростиВам дадут возможность выбрать одну из следующих наград:\n\nФолиант Рвения\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11308] = {title = "Пора заметать следы", objective = "Поговорите с Дженни по прозвищу \"Пила\" в Новом Агамонде.", description = "Будучи человеком практичным, я могу заявить, что мы достигли успеха в наших исследованиях. В конце концов, любую армию можно остановить, если натравить ее рядовых солдат друг на друга.\n\nСкоро я доложу о наших успехах в Лагерь Возмездия. Но сначала мы должны замести следы.\n\nПопроси Дженни по прозвищу \"Пила\" сделать тебе базовое поганище. Пусть только она добавит в него побольше взрывчатки – если ты понимаешь, к чему я клоню.", progress = nil, completion = "Что тебе нужно? Не видишь – я очень занята!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11309] = {title = "Запчасти для Дженни", objective = "Принесите 6 жил черпорога и 1 килограмм свежего мяса Дженни по прозвищу \"Пила\" в Новый Агаманд.", description = "А, Харрис хочет что-то взорвать? Да, тогда он обратился по адресу. \n\nПравда, тебе придется достать мне кое-какие запчасти. Я не хочу тратить собственные запасы на штуку, подлежащую уничтожению. \n\nПрежде всего, мне понадобятся жилы черпорога... они гораздо прочнее человеческих.\n\nЕще нужно свежее мясо. Есть тут один парень – Антон – он продает дешевое мясо. Найти его легко: он часто ходит по западной дороге.", progress = "Ты достал то, что я просила?", completion = "Да, это вполне сгодится. Молодец!", rewards = "Капюшон защиты от шокаКольчато-пластинчатые перчаткиНабедренники необыкновенной щедростиВам дадут возможность выбрать одну из следующих наград:\n\nКристаллический сюрикен\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11310] = {title = "Внимание: требуется сборка", objective = "Воспользуйтесь набором для сборки поганища в Халгринде и сгоните в одно место как минимум 20 зачумленных врайкулов. Взорвите их с помощью поганища, после чего вернитесь к Дженни по прозвищу \"Пила\" в Новый Агамонд.", description = "А, вот ты где! Наш дружок получился немного... непредсказуемым. Я бы тебе порекомендовала собрать его на месте, в Халгринде.\n\nКак только доберешься туда, отправь поганище в толпу врайкулов, чтобы он уничтожил как можно больше этих тварей.\n\nКогда все закончится, подбери останки и принеси их сюда. Запчасти мне всегда пригодятся!", progress = "Ну что, зачистка в Халгринде закончена?", completion = "Отличная работа, Расул. Слушай, а тебе не хотелось бы создать нечто менее... взрывоопасное? Мне пригодилась бы твоя помощь по сбору запчастей!", rewards = "Мундир очищения огнемСапоги из мягкой кожиРемень неизбежностиВыкованный светом нагрудный доспехВы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11311] = {title = "Сопротивляясь стихиям", objective = "Укротитель ветра Каган из Лагеря Заиндевевшего Копыта просит вас убить 8 горных элементалей. Уничтожайте завывающих циклонов или осколочных ледяных элементалей.", description = "Если хочешь выжить в этом месте – научись приспосабливаться к изменениям, как это сделали мы. Количество элементалей в северных предгорьях неуклонно возрастает, что только подтверждает тот факт, что любая стихия может стать смертоносной, если мы не будем достаточно бдительны, чтобы предотвратить угрозу.\n\nПеред тем как покинуть это место, мы должны в последний раз сократить численность элементалей. Не хочешь ли ты помочь нам, пока мы завершаем подготовку к походу?\n\nУбивай всех осколочных ледяных элементалей и завывающих циклонов, которые встретятся тебе на снежных предгорьях, окружающих аванпост.", progress = nil, completion = "Влияние стихий уменьшилось, но элементали еще вернутся. К счастью, мы успели выиграть время для приготовлений к уходу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11312] = {title = "Заиндевевшая поляна", objective = "Поговорите с Луриэль на Заиндевевшей поляне.", description = "Многие поколения среди нашего народа ходили легенды о ледяных нимфах, прячущихся далеко в заснеженных чащах. Как-то ребенком я отправилась на их поиски вопреки запретам родителей, а в итоге едва не замерзла до смерти.\n\nИ вот настали дни, когда нам больше не надо прочесывать леса в поисках этих чудесных созданий. По неведомым причинам они решили открыться нам, и мы обязаны узнать, чем вызвано их появление. Отправляйся на юго-восток, к заиндевевшей поляне, и поговори с ледяными нимфами. Но будь <осторожен/осторожна> – по пути тебе придется миновать Холмистую поляну.", progress = nil, completion = "&lt;Луриэль внимательно выслушивает вас.&gt;\n\nПриятно познакомиться, |3-6(Маг). Мои сестры часто видели, как таунка искали нас в лесах, но наша королева запретила нам вступать в контакт с чужаками. Сегодня ты видишь нас только потому, что эти земли сильно изменились, и многие мои сестры ныне в опасности.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11313] = {title = "Духи льда", objective = "Луриэль с Заиндевевшей поляны просит вас принести ей 15 ледяных ядер.", description = "Ледяные элементали, охраняющие эту поляну, были нашими союзниками, но некая жестокая и разрушительная сила пронеслась по этим землям, изменяя их сущность. Теперь они обратились против нас!\n\nЭта одна из многих бед постигнувших меня и моих сестер. Мы явились к вам в надежде, что вы сможете помочь нам остановить скверну, проникшую в наши леса и отравляющую моих сестер!\n\nМы собираем ядра ледяных элементалей и складываем в безопасное место в надежде, что когда-нибудь сможем их возродить. Ты нам поможешь?", progress = "Ты принес хоть несколько ядер?", completion = "&lt;Луриэль бережно принимает ядра из ваших рук.&gt;\n\nСпасибо, Верлоз.\n\n&lt;Луриэль печально смотрит на ледяные ядра.&gt;\n\nОбещаю, друзья мои, я сделаю все возможное, чтобы возродить вас.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11314] = {title = "Падшие сестры", objective = "Луриэль с Заиндевевшей поляны попросила вас воспользоваться ее подвеской, чтобы освободить 7 морозных нимф.", description = "К юго-западу отсюда есть поляна, которая некогда была очень похожа на эту. Но странные силы и чужеродная магия изменили эту землю. Поляна исказилась, а жившие на ней сестры сошли с ума, ибо были не в состоянии принять произошедшие перемены.\n\nМы пытались воззвать к ним, но они напали на моих подручных. Боюсь, многих из моих несчастных сестер уже не спасти, но я не теряю надежды.\n\nВозьми мою подвеску, отправляйся на юго-запад, к Светлой поляне, и попытайся с ее помощью освободить моих сестер.", progress = nil, completion = "Значит, для моих сестер еще не все потеряно?\n\n&lt;Луриэль отворачивается и печально смотрит вдаль.&gt;\n\nЯ должна была сразу вспомнить про подвеску. Возможно, тогда мы могли бы спасти всех моих сестер.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11315] = {title = "Дикие ветви", objective = "Луриэль с Заиндевевшей поляны попросила вас уничтожить 8 цветков алого плюща.", description = "Сестры, жившие на Светлой поляне, что к юго-западу отсюда, любили проводить время в тени алого плюща, но та же сила, что свела их с ума, изменила и их возлюбленные цветы.\n\nОтныне ветви некогда мирных цветов хватают за ноги неосторожных путников и хлещут по лицу каждого, кто осмелится приблизиться к поляне. Если мы хотим исцелить эти земли, мы должны сначала усмирить и выкорчевать эти растения.\n\nУничтожь столько цветков алого плюща, сколько сможешь. Увы, у нас больше нет над ними власти.", progress = nil, completion = "Спасибо тебе за помощь, Расул. Светлая поляна была прекрасным местом, и я надеюсь возродить ее, когда мы сможем туда вернуться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11316] = {title = "Порождения Холмистой поляны", objective = "Луриэль с Заиндевевшей поляны просит вас убить 10 терноплющей.", description = "Некогда чудесная поляна на западе превратилась в ужасное место, которое прозвали Холмистой поляной. Там, среди деревьев, камней и озер бродят чудовищные звери.\n\nЯ не могу даже представить себе, откуда взялись эти существа и какая омерзительная магия вдохнула в них жизнь, но мы должны что-то сделать с этими тварями!\n\nБоюсь, что если мы и дальше позволим им бродить по поляне, они отравят землю настолько, что мы уже не сможем ее возродить. Очисти поляну от существ, погубивших наших сестер.", progress = nil, completion = "Ты хорошо потрудился, Reng. Если бы у нас с самого начала были такие союзники, как ты, мы бы смогли уберечь от скверны гораздо больше земель, которые ныне для нас потеряны.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11317] = {title = "Очищение", objective = "Ведун Странник Туманов у Стальных ворот посоветовал вам очиститься от внутреннего смятения путем медитации в святилище Ледяного Клинка.", description = "Мы отправились в Вырубки потому, что мне было видение про моего друга, ворга по имени Улклык. Он звал на помощь, и потому ты <должен/должна> его найти.\n\nК сожалению, ты не можешь ходить среди воргов и общаться с ними, но я могу тебя научить.\n\nСначала тебе придется изгнать свое внутреннее смятение путем медитации. \n\nДалеко на северо-востоке, на Вершине Ледяного Клинка есть святилище. К нему ведет единственная тропинка, начинающаяся от западного подножия горы.\n\nОтправляйся туда, очисти свой дух и возвращайся ко мне.", progress = nil, completion = "Я чувствую произошедшие в тебе перемены.\n\nГотов ли ты сделать следующий шаг?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11318] = {title = "А теперь гонки на баранах... Или вроде того.", objective = "У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.", description = "Хочешь попробовать себя в роли наездника на баране? Надеюсь, ты любитель быстрой езды. Но. Прежде чем допустить тебя к соревнованиям, покажи, что справишься с нашими скакунами.\n\nВот, что я предлагаю: возьми скакового барана и поводья и покажи, что умеешь ездить верхом.\n\nПусти барана рысью на 8 секунд, потом легким галопом и галопом. Если ты не знаешь, как управляться с баранами, обратись к моему ученику, Полу Янтарлену.", progress = nil, completion = "Неплохо, неплохо! Не так-то просто справиться с бараном. Но как уж научишься им управлять, сразу захочешь, чтобы все бараны были верховыми.\n\nЧто-что? Где твоя награда? Ха-ха-ха! Тебе разрешили покататься на самом быстром баране в округе! Мало? Тогда так...\n\nТебе выпал шанс помочь другим участникам Хмельного фестиваля. Молодому наезднику на баранах хватит и работы, и наград.", rewards = "Следующее заклинание будет наложено на вас:\n\nСпешиться с барана - задание\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][11319] = {title = "Семена негодующих хранителей", objective = "Луриэль с Заиндевевшей поляны поручила вам заморозить 8 спор.", description = "Раньше на Холмистой поляне, к западу отсюда, обитали хранители рощи. Вместе с сестрами они ухаживали за ее обитателями.\n\nКогда поляна изменилась, все сестры погибли, но хранителям каким-то образом удалось выжить. Однако теперь они засеивают землю ядовитыми растениями, которые губят здоровые ростки.\n\nПриближаться к этим спорам опасно, но я дам тебе ядро одного из ледяных элементалей. Как только уничтожишь спору, заморозь ее с помощью кристалла, чтобы она больше не ожила.", progress = nil, completion = "Ледяное ядро сработало? Хорошо. Боюсь, мне еще не раз придется его применить. Я уверена, что хранители не остановятся и будут продолжать засеивать поляну.", rewards = "Хауберк ожесточенного заступникаКорень бессмертияПелерина концентрированной ненавистиВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11321] = {title = "Кто сказал \"сувениры\"?", objective = "Найдите в лагере Хмельного фестиваля Белби Быстросмен, отдайте ей купон и получите бесплатную праздничную пивную кружку.", description = "Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.\n\nВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЖелтая кружка Хмельного фестиваля"}
MultiLanguageQuestData['ru'][11322] = {title = "Очищение", objective = "Дозорная Лунный Лепесток у Стальных ворот посоветовала вам очиститься от внутреннего смятения путем медитации в святилище Ледяного Клинка.", description = "Недавно мне приснился кошмарный сон про ворга по имени Улклык. Он звал меня на помощь! <имя>, ты <должен/должна> его найти.\n\nК сожалению, ты не можешь ходить среди воргов и общаться с ними, но я могу тебя научить.\n\nСначала тебе придется изгнать свое внутреннее смятение путем медитации. \n\nДалеко на северо-востоке, на Вершине Ледяного Клинка есть святилище. К нему ведет единственная тропинка, начинающаяся от западного подножия горы.\n\nОтправляйся туда на медитацию, очисти свой дух и возвращайся ко мне.", progress = nil, completion = "Я чувствую произошедшие в тебе перемены.\n\nГотов ли ты сделать следующий шаг?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11323] = {title = "В обличье ворга", objective = "Ведун Странник Туманов попросил вас найти Улклыка в Вырубках и помочь ему.\n\nЕсли вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.\n\nПрилагается предмет: \n", description = "Во сне я видел Улклыка в пещере на заснеженном краю Вырубок, где-то на северо-западе.\n\nЕму грозит страшная опасность!\n\nЯ сделал магическую личину, которая сделает тебя <похожим/похожей> на ворга. Это очень нестабильная личина, которая действует только в пределах Вырубок. Однако с ее помощью ты сможешь обмануть воргов и добраться до Улклыка.\n\nПрошу тебя, <класс>, отыщи Улклыка и помоги ему.", progress = nil, completion = "Ты как-то странно выглядишь, и запах у тебя необычный... ты не из моей стаи. Расскажи, что привело тебя сюда. Все равно мне больше нечем заняться, пока я заперт в этом месте.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11324] = {title = "Альфа-ворг", objective = "Улклык попросил вас убить Гарвала. После этого вы должны будете вернуть личину ворга ведуну Страннику Туманов в Стальные ворота.", description = "Теперь, когда ты <съел/съела> глаза Когтекрыла, ты сможешь увидеть Гарвала и вырвать его глотку!\n\nДитя |3-1(<раса>), разыщи Гарвала в западных Вырубках и убей его. Когда он умрет, вернись к ведуну Страннику Туманов и сообщи ему, что я снова стал вожаком стаи воргов!", progress = "Расул! Какие новости об Улклыке?", completion = "Гарвал был не воргом! Судя по твоему рассказу, эта тварь больше похожа на воргена!\n\nНо Улклык вроде бы упоминал, что Гарвал пришел на юг из Седых холмов? Как странно. Воргены не водятся в тех местах...\n\nКак бы то ни было, я благодарю тебя за то, что ты помог Улклыку занять подобающее ему место в стае. Теперь мы оба можем спать спокойно. \n\nПожалуйста, не откажись принять этот дар в знак благодарности.", rewards = "Гхоламские поножиНаплеч из зубов протодраконаКольчатые наголенники из темной сталиХауберк ворга-берсеркераВы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11325] = {title = "В обличье ворга", objective = "Дозорная Лунный Лепесток попросила вас найти Улклыка в Вырубках и помочь ему.\n\nЕсли вы потеряете личину ворга, вернитесь к дозорной Лунный Лепесток, и она даст вам новую.\n\nПрилагается предмет: \n", description = "Во сне я видела Улклыка в пещере на заснеженном краю Вырубок, где-то на северо-западе.\n\nЕму грозит страшная опасность!\n\nЯ сделала магическую личину, которая сделает тебя <похожим/похожей> на ворга. Это очень нестабильная личина, которая действует только в пределах Вырубок. Однако с ее помощью ты сможешь обмануть воргов и добраться до Улклыка.\n\nПрошу тебя, <класс>, отыщи Улклыка и помоги ему.", progress = nil, completion = "Ты как-то странно выглядишь, и запах у тебя необычный... ты не из моей стаи. Расскажи, что привело тебя сюда. Все равно мне больше нечем заняться, пока я заперт в этом месте.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11326] = {title = "Альфа-ворг", objective = "Улклык попросил вас убить Гарвала. После этого вы должны будете вернуть личину ворга дозорной Лунный Лепесток в Стальные ворота.", description = "Теперь, когда ты <съел/съела> глаза Когтекрыла, ты сможешь увидеть Гарвала и вырвать его глотку!\n\nДитя |3-1(<раса>), разыщи Гарвала в западных Вырубках и убей его. Когда он умрет, вернись к дозорной Лунный Лепесток и сообщи ей, что я снова стал вожаком стаи воргов!", progress = "Аркоман! Какие новости об Улклыке?", completion = "Гарвал был не воргом! Судя по твоему рассказу, эта тварь больше похожа на воргена!\n\nНо Улклык вроде бы упоминал, что Гарвал пришел на юг из Седых холмов? Как странно. Воргены не водятся в тех местах...\n\nКак бы то ни было, я благодарю тебя за то, что ты помог Улклыку занять подобающее ему место в стае. Теперь мы оба можем спать спокойно. \n\nПожалуйста, не откажись принять этот дар в знак благодарности.", rewards = "Гхоламские поножиНаплеч из зубов протодраконаКольчатые наголенники из темной сталиХауберк ворга-берсеркераВы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11327] = {title = "Задание: найти сверток", objective = "Разведчик Ноулс просит вас найти сверток аптекаря в Халгринде. Принесите его разведчику в Тлеющую башню.", description = "Ох, как же нам нужны образцы этой чумы!\n\nА, придумал!\n\nПока ты <уничтожал/уничтожала> резервуары, я проследил за одним из аптекарей из Нового Агамонда. Его утащили в Халгринд местные врайкулы. И поделом.\n\n<имя>, я могу поспорить, что у него были с собой какие-то вещи. Может быть, тебе стоит отправиться в Халгринд и достать его пожитки?", progress = "Какое ужасное место! Даже врайкулы не заслуживают страшной гибели от рук Королевского фармацевтического сообщества.\n\nХорошо, что здесь я в безопасности. Кстати, ты уже отыскал сверток?", completion = "Великий свет... это еще что?! Ты только посмотри!\n\nНам надо как можно скорее доставить этот сверток в крепость!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11328] = {title = "Задание: чума Отрекшихся", objective = "Разведчик Ноулс просит вас отнести сверток аптекаря Пеппи Нетосопло в Крепость Западной Стражи.", description = "Так вот; отнеси эту штуку обратно в крепость и отдай Пеппи Нетосопло. Она, конечно, не самый лучший алхимик, но другого у нас нет.\n\nТолько учти – она очень любит выпить, так что для начала загляни в таверну.\n\nВ общем, она знает, что делать с этой штукой.", progress = "Эй, чего надо...ик?", completion = "А... это же совершенно меняет дело!\n\nЛадно, дай-ка взглянуть... Обожаю все эти алхимические штучки!\n\nНу-ка, ну-ка... Ага, знаю! Надо всего лишь смешать эту фигню вот с этой бурдой в равных пропорциях.\n\nИ, пожалуй, не будет лишним добавить кусочек гнилых внутренностей... ик!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11329] = {title = "Я готов на все!", objective = "Принесите Кристоферу Слоану из крепости Вилдервар 5 северных рыб-шипов.", description = "Как же мне надоели эти бочки с засоленной рыбой! Я набиваю их целыми днями, а работы еще непочатый край!\n\nАх, если бы только у меня осталась эта приманка Ната Пэгла! Вот уж действительно чудесная штука. Теперь же я радуюсь, если удается поймать за час хотя бы одну рыбку. \n\nСлышал я, что из северной рыбы-шипа получается неплохая приманка, но кто же в здравом уме полезет в ледяную воду и будет бултыхаться среди водорослей в поисках этой пронырливой рыбки? Не я, это точно... разве что тебя удастся уговорить...", progress = "Ты смотри – кажется, рыбки тебя не сильно покусали. Наживку-то принес?", completion = "Фу, какие мерзкие твари! Ладно, неважно, как они выглядят – лишь бы на них кто-нибудь клюнул. Скорее бы экспедиция убралась отсюда. Тогда я смогу рыбачить для собственного удовольствия.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11330] = {title = "Это... точно сработает!", objective = "Пеппи Нетосопло предложила вам отнести ее особую смесь врайкулу-узнику из клана Укротителей драконов. Когда он выпьет смесь, вернитесь в Крепость Западной Стражи и расскажите Пеппи о результатах эксперимента.", description = "Ага, вакцина от чумы готова.\n\nПравда, я не собираюсь испытывать ее на себе. Могу предположить, что ты тоже не горишь желанием стать подопытным кроликом?\n\nО, точно!\n\nУ нас же есть врайкульский пленник в темнице под крепостью! Давай-ка ты отнесешь ему эту мешанину и заставишь его выпить...ик, до дна?", progress = nil, completion = "Что? Ой, как все плохо... Хотела как лучше, а получилось как всегда. Выходит, я даже усовершенствовала чуму...ик!\n\n&lt;Пеппи морщится и в очередной раз прикладывается к бутылке.&gt;\n\nЭх, я надеялась, что до этого дело не дойдет, но теперь...ик! – у нас нет выхода.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11331] = {title = "Ик... Ты ему и скажи!", objective = "Пеппи Нетосопло уговорила вас сообщить плохие новости о новой чуме Отрекшихся капитану Адамсу. Его можно найти в Крепости Западной Стражи.", description = "Короче, так. Я не собираюсь идти к капитану с такими новостями! В мои обязанности это не входит, и вообще, у меня перерыв. \n\nОн же такая злюка... да ты не хуже меня его знаешь!\n\nВ общем, топай в крепость <сам/сама>. Я уверена, он тебя выслушает, и все такое... ик! \n\n<Пеппи снова прикладывается к бутылке.>", progress = nil, completion = "Да, Reng, что еще ты хочешь мне доложить?\n\nЧТО?! Отрекшиеся создали чуму, которая может в считанные мгновения превратить человека в лужу? И ты расплавил моего пленного врайкула?\n\n&lt;Капитан огорченно смотрит по сторонам и презрительно сплевывает на пол.&gt;\n\nНу, ладно. Я знаю, что нам делать. Точнее, не нам, а ТЕБЕ!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11332] = {title = "Задание: уничтожить чуму!", objective = "Капитан Адамс приказал вам сбросить 5 бомб на резервуары с чумой в Новом Агамонде. Вернитесь к нему в Крепость Западной Стражи, когда это поручение будет выполнено.", description = "В Королевском фармацевтическом обществе собираются запустить новую чуму, которая может расплавить человека на месте?!\n\nТолько не во время моего дежурства!\n\nОтправляйся во внутренний двор и поговори с Гриром Рудомолотом. Он должен был уже приготовить для тебя грифона и несколько бомб. Я хочу, чтобы ты <разнес/разнесла> в щепки резервуары с чумой в Новом Агамонде.", progress = nil, completion = "Молодец, Палиандр, отличная работа!\n\n&lt;Капитан чуть ли не пляшет от радости.&gt;\n\nТеперь эти жалкие Отрекшиеся поймут, что с нами не стоит связываться!\n\nПожалуй, ты заслужил награду из нашей сокровищницы!", rewards = "Перчатки прядильщицы пламениИнкрустированный холодным камнем воинский поясНаручи точного удараНаплечье из изумрудной чешуиВы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11333] = {title = "В мир духов", objective = "Торелий Мудрый в Валгарде просит вас найти его мешочек с реагентами.", description = "Пока Лига исследователей копается в земле в поисках осколков прошлого, а вице-адмирал пытается постигнуть суть настоящего путем грубой силы, истина скрывается от нас среди призраков.\n\nС помощью особых реагентов я могу заглянуть в мир духов, где мне откроется прошлое, настоящее и будущее Нордскола.\n\nЕсли хочешь узнать больше, принеси мне мой мешочек с реагентами. Я потерял его на корабле, который ныне покоится на дне Бухты Кинжалов, к востоку отсюда.", progress = "Где мой мешочек с реагентами?", completion = "Мда, носить ее уже не придется, но содержимое в целости и сохранности.\n\n&lt;Торалиус запускает руку в сумку и достает несколько причудливых корешков.&gt;\n\nА теперь надо бросить их в огонь и вдохнуть дым!\n\n&lt;Торалиус кладет корешки в тлеющую жаровню.&gt;\n\n&lt;Он глубоко вдыхает, и тело его начинает корчиться в судорогах.&gt;\n\nЧто...Что такое... Не может... Я не могу...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11334] = {title = "В яблочко!", objective = "[PH] Rinling wants you to shoot a marked target and then return the Target Rifle to him.", description = "[PH] Shoot a marked target.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][11335] = {title = "Призыв к оружию: низина Арати", objective = "Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Беда битвы на несколько фронтов, <парень/подруга>, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!\n\nНам каждый день требуется подкрепление. Сегодня войскам в Низине Арати требуются отважные бойцы.\n\nИди, <имя>, и принеси нам победу. Мы не можем позволить Ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!", progress = nil, completion = "Прекрасная новость, |3-6(Маг)! Если наши тактические действия будут и впредь столь же успешны, Орде очень скоро придется отступать по всем фронтам!", rewards = "Вы получите:\n\nПочетный знак Низины АратиОчки арены"}
MultiLanguageQuestData['ru'][11336] = {title = "Призыв к оружию: Альтеракская долина", objective = "Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Беда битвы на несколько фронтов, <парень/подруга>, в том, что приходится растягивать силы, в результате мы рискуем потерять все!\n\nДень ото дня все необходимее подкрепление. Сегодня войскам в Альтеракской долине требуются отважные бойцы.\n\nСтупай прямо сейчас, <имя>, и помоги экспедиции клана Грозовой Вершины. Мы не можем допустить, чтобы клан Северного Волка ушел без возмездия после всего того зла, что они причинили нашим собратьям!", progress = nil, completion = "Это мне и хотелось улышать! Победа в Альтеракской долине - пусть и временная - необходимое звено в нашей общей стратегии войны с Ордой.", rewards = "Вы получите:\n\nПочетный знак Альтеракской долиныОчки арены"}
MultiLanguageQuestData['ru'][11337] = {title = "Призыв к оружию: Око Бури", objective = "Победите на поле боя Ока Бури и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Война с Ордой не ведает границ, <имя>. Даже в Запределье застарелая ненависть и территориальные претензии вынуждают нас воевать.\n\nИди в Око Бури и измени равновесие в Запределье в пользу Альянса, как в Азероте.", progress = "Поведай мне, Димплх, что за вести несешь ты с передовой?", completion = "Мы на шаг приблизились к полной победе над Ордой! Мы не можем позволить врагу завоевать плацдарм ни в этом мире, ни в каком другом!", rewards = "Вы получите:\n\nПочетный знак Ока БуриОчки арены"}
MultiLanguageQuestData['ru'][11338] = {title = "Призыв к оружию: ущелье Песни Войны", objective = "Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Среброкрылые часовые защищают лес в ущелье Песни Войны. Мы помогаем им не из любви к деревьям, а потому, что этот лес является природным защитным барьером вокруг территории Альянса.\n\nСегодня им как никогда нужна помощь. Нам нужно подкрепление прямо сейчас, иначе Ясеневый лес постигнет судьба Степей!", progress = "Какие вести с фронта, Коин?", completion = "Славная работа, Мэлфис. Мы должны любой ценой обеспечить нерушимость наших границ!", rewards = "Вы получите:\n\nПочетный знак ущелья Песни ВойныОчки арены"}
MultiLanguageQuestData['ru'][11339] = {title = "Призыв к оружию: низина Арати", objective = "Победите на поле боя Низины Арати и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Мы вот-вот отобъем Низину Арати у сил Альянса! Мы немедленно должны послать туда подкрепление, иначе все наши труды пойдут прахом.\n\nНе медли, <класс>, отправляйся в Низину Арати и сокруши врагов. Орда победит!", progress = nil, completion = "Ты принес великую славу Орде, Элеутерококк. Твоя победа сегодня принесет тысячу побед завтра!", rewards = "Вы получите:\n\nПочетный знак Низины АратиОчки арены"}
MultiLanguageQuestData['ru'][11340] = {title = "Призыв к оружию: Альтеракская долина", objective = "Победите на поле боя Альтеракской долины и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Мы почти изгнали врагов из клана Грозовой Вершины, что вторглись в Альтеракскую долину. Теперь надо перебросить наши силы на помощь клану Северного Волка.\n\nРешительная победа там высвободит ресурсы, необходимые для сокрушения этих подонков из Альянса на всех остальных фронтах.\n\nСтупай, <имя>. Заслужи великую честь, откликнувшись на зов отважных воинов клана Северного Волка.", progress = "Ты вернулся! Надеюсь, с победной вестью?", completion = "Нет высшей чести, чем изгнать захватчиков с земель Орды! Мы ныне славим твою великую отвагу в помощи нашим войскам!", rewards = "Вы получите:\n\nПочетный знак Альтеракской долиныОчки арены"}
MultiLanguageQuestData['ru'][11341] = {title = "Призыв к оружию: Око Бури", objective = "Победите в игре на поле боя Ока Бури и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Мы сражаемся с врагами везде, где только встретим - в Азероте, в Запределье, повсюду.\n\nМы не можем позволить Альянсу одолеть нас в Оке Бури! Ступай биться с ними сегодня... Завтра будет поздно!", progress = "Ты вернулся! Надеюсь, с победной вестью?", completion = "Ты принес славу всем нам, Кармаполиция. Мы должны показать врагу, что будем сражаться с ними везде и всегда!", rewards = "Вы получите:\n\nПочетный знак Ока БуриОчки арены"}
MultiLanguageQuestData['ru'][11342] = {title = "Призыв к оружию: ущелье Песни Войны", objective = "Победите на поле боя Ущелья Песни Войны и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Альянс – коварный враг, <имя>. Они говорят, что защищают Ясеневый лес, дабы оправдать свою агрессию против наших территорий в Степях.\n\nНынче у нас есть возможность вытеснить врага с наших земель раз и навсегда! Отправляйся в ущелье Песни Войны и верни то, что наше по праву!", progress = "Ты вернулся с вестями о нашей победе?", completion = "Орда в долгу перед тобой, Деретник. Твой народ гордится твоей отвагой на защите наших земель.", rewards = "Вы получите:\n\nПочетный знак ущелья Песни ВойныОчки арены"}
MultiLanguageQuestData['ru'][11343] = {title = "Эхо Имирона", objective = "Торелий Мудрый просит вас обыскать Деревню Драконьего Черепа в мире духов и найти информацию о тайнах Ниффлвара.", description = "Мир духов пал под натиском Короля-лича. Ужасные существа, порождения кошмаров, ныне сторожат владения стихий. Я чувствую, что эти валь'киры охраняют страшную тайну.\n\nЯ слишком стар и слаб, чтобы пережить еще одно путешествие, поэтому ты, <имя>, отправишься вместо меня.\n\nВозьми эту курительницу и отправляйся в Деревню Драконьего Черепа. Зажги ее, чтобы проникнуть в мир духов, и обыщи все здания в деревне на северо-востоке. Но будь <осторожен/осторожна> – валь'киры могут навсегда оставить тебя в своем мире!", progress = nil, completion = "Не понимаю. Говоришь, эти существа были похожи на врайкулов, которые нападают на Валгард?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11344] = {title = "Страдания Ниффлвара", objective = "Торелий Мудрый поручил вам осмотреть Ниффлвар из мира духов и найти информацию о тайнах Ниффлвара.", description = "Наши скромные познания о врайкулах позволяют сделать вывод, что они лишь недавно появились в Нордсколе. Почему же тогда мы видим их в пророчествах, сделанных 15,000 лет назад? Если бы врайкулы раньше обитали на этом континенте, мы бы об этом знали.\n\nТебе надо продолжить работу в Ниффлваре. Чтобы добраться туда, иди на северо-восток, через Деревню Драконьего Черепа, после чего сверни на дорогу, идущую через дамбу. Ниффлвар расположен на одном из обрывов фьорда. \n\nКак только прибудешь туда, зажги курительницу и осмотри все вокруг в поисках важной информации.", progress = nil, completion = "От врайкулов рождались человеческие дети? И Имирон приказал убить всех полукровок?\n\n&lt;На мгновение Торалиус умолкает.&gt;\n\nУвы, бессмысленно отрицать очевидное. Нет никакого \"утерянного звена\", ведущего к возникновению человека. Лига исследователей ошибалась – врайкулы и есть то самое недостающее звено. Они – прародители человечества.", rewards = "Торжественные перчатки БловельтаШлем власти из шкуры воргаЧешуйчатые перчатки ловкости рукДревние укрепленные набедренникиВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11345] = {title = "Приз за попадание", objective = "[PH] Rinling wants you to shoot a marked target and then return the Target Rifle to him.", description = "[PH] Shoot a marked target.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n[PH] Tiny Creepy Rag Doll"}
MultiLanguageQuestData['ru'][11346] = {title = "Книга Рун", objective = "Геолог Белвар из крепости Вилдервар просит вас найти Книгу Рун.", description = "Железные дворфы захватили Тропу великанов – огромное, каменистое плато на юго-востоке. Мои разведчики доложили, что видели дворфов, откапывающих каменных великанов из-под земли и вырезающих на них руны.\n\nЯ не могу постигнуть их замыслы, но смею предположить, что они пытаются превратить этих великанов в оружие. Говорят, что призыватели камня и связыватели из клана Железной Руны носят с собой толстые книги с рунами, которые они вычерчивают на телах великанов. \n\nСобери несколько отрывков из этих томов, сложи их вместе и принеси мне.", progress = "Ты достал книгу?", completion = "&lt;Геолог Белвар листает книгу Рун.&gt;\n\nОго... здесь так много информации. Мне потребуется время, чтобы изучить эту книгу. Если мы постигнем смысл этих рун, то сможем воспользоваться ими в своих целях.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11348] = {title = "Руна подчинения", objective = "Геолог Белвар из крепости Вилдервар просит вас испытать руну подчинения и сразиться с Мурдисом-обуздателем.", description = "Чувствуешь силу, исходящую от рун, которые я вырезал на этой табличке? Это всего лишь уменьшенная версия тех символов, что используют железные дворфы. Мы же обернем эти руны против них самих. \n\nОтнеси эту табличку на Тропу Великанов и используй на каменном великане, которого еще не успели изменить дворфы. \n\nВеликан будет подчиняться тебе, но недолго. Видишь ли, я вырезал такую руну, которая со временем позволит ему стать самим собой. Пока же этот великан может стать ценным союзником в борьбе против Мурдиса, предводителя железных дворфов.", progress = nil, completion = "Ты совершил великое дело, победив Мурдиса-обуздателя, но железные дворфы так просто не сдадутся. \n\nПо пути на север мы еще не раз столкнемся с этими существами. Но в следующий раз мы будем готовы дать им отпор.", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11349] = {title = "Освоение рун", objective = "Принесите геологу Белвару из крепости Вилдервар резной инструмент, который используют дворфы клана Железной Руны.", description = "У меня есть с собой несколько молотков, отверток и рубильников, но обычные орудия не подходят для вырезания этих рун. Железные дворфы используют зачарованные инструменты. \n\nКаждый раз, когда они вырезают очередную руну с помощью этих инструментов, они придают словам новое, магическое значение. С помощью таких рун можно привязать к себе, изменить и подчинить любое существо. \n\nЕсли бы мне удалось получить набор магических инструментов, я бы смог вырезать руны, изображенные в книге. Поищи их возле палаток дворфов на Тропе Великанов.", progress = "Неужели ты несешь мне инструменты?", completion = "&lt;Белвар бережно берет инструменты.&gt;\n\nЯ попробую ими воспользоваться. Если мы хотим понять логику действий Железных дворфов и победить их, мы должны знать, какое воздействие оказывают эти руны.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11350] = {title = "Книга Рун", objective = "Выносливый гонец Пембе из Лагеря Заиндевевшего Копыта просит вас принести ему Книгу Рун.", description = "Вождь Прахтотем отправил меня на разведку к Тропе Великанов. Это широкое, каменистое плато к юго-востоку отсюда, сразу за Заиндевевшей поляной.\n\nЭтот район захватили Железные дворфы, которые, похоже, каким-то образом изменяют великанов, появляющихся из-под земли. \n\nПризыватели камня и связыватели из клана Железной Руны носят с собой толстые книги с рунами, которые они вычерчивают на телах великанов. \n\nСобери несколько отрывков из этих томов, сложи их вместе и принеси мне. Тогда у нас появится шанс постигнуть их замыслы.", progress = "Ты достал книгу?", completion = "&lt;Выносливый гонец листает принесенную вами книгу.&gt;\n\nЯ не мудрец, но немного знаком с языком Железных дворфов. Кажется, эти руны, которые они вырезают на телах великанов, как-то связаны с их наречием, но различия слишком велики.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11351] = {title = "Освоение рун", objective = "Принесите выносливому гонцу Пембе из Лагеря Заиндевевшего Копыта резной инструмент, который используют дворфы клана Железной Руны.", description = "Кажется, я догадался, что делают Железные дворфы. Они используют зачарованные инструменты. \n\nКаждый раз, когда они вырезают очередную руну с помощью этих инструментов, они придают словам новое, магическое значение. С помощью таких рун можно привязать к себе, изменить и подчинить любое существо. \n\nЕсли бы мне удалось раздобыть набор магических инструментов, я бы смог вырезать руны, изображенные в книге. Мне удалось украсть ящик из палатки на Тропе Великанов, но он оказался пуст. Попробуй найти похожий ящик и принеси мне хранящийся в нем набор инструментов.", progress = "Неужели ты несешь мне инструменты?", completion = "&lt;Пембе изучает инструменты.&gt;\n\nКакие изящные орудия труда! Подожди немного, я хочу их испытать.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11352] = {title = "Руна подчинения", objective = "Выносливый гонец Пембе из Лагеря Заиндевевшего Копыта просит вас испытать руну подчинения и сразиться со Мурдисом-обуздателем.", description = "Чувствуешь силу, исходящую от рун, которые я вырезал на этой табличке? Это всего лишь уменьшенная версия тех символов, что используют железные дворфы. Мы же обернем эти руны против них самих. \n\nОтнеси эту табличку на Тропу Великанов и используй на каменном великане, которого еще не успели изменить дворфы. \n\nВеликан будет подчиняться тебе, но недолго. Видишь ли, я вырезал такую руну, которая со временем позволит ему стать самим собой. Пока же этот великан может стать ценным союзником в борьбе против Мурдиса, предводителя железных дворфов.", progress = "Ты испытал руну?", completion = "Ты совершил великий подвиг, победив Мурдиса, но Железные дворфы так просто не сдадутся. \n\nПо пути на север мы еще не раз столкнемся с этими существами. Но в следующий раз мы будем готовы дать им отпор.", rewards = "Вы получите:\n\nПрипасы для экспедиции в НордсколПредмет #1"}
MultiLanguageQuestData['ru'][11354] = {title = "Разыскивается: Ездовой хлыстик Назана", objective = "Торговец ветром Зарим просит вас добыть ездовой хлыст Назана. Доставьте его ему в Нижний город Шаттрата и получите награду.\n\nЭто задание выполняется только в героическом режиме.", description = "Мой нынешний заказчик интересуется одной штучкой, которую хранит верховое животное глашатая Иллидана. Естественно, я имею в виду Вазрудена Глашатая и его дракона Назана.\n\nЕсли хочешь получить награду, назначенную мной за этот предмет – ищи его над бастионами цитадели Адского Пламени и принеси мне хлыстик для верхового дракона.\n\nМои осведомители сообщают, что искомый предмет хранится лично у дракона. Говорят, что Назан не позволяет Вазрудену погонять себя им.", progress = "Прошу предъявить ездовой хлыст.", completion = "Значит, еще один клиент вскоре будет удовлетворен. А вы будете вознаграждены.\n\nПриходите поутру, и я подберу вам новое дельце.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11355] = {title = "Марш великанов", objective = "Ученый Адеран из крепости Вилдервар попросил вас использовать кирку поиска рун на трупах 4 рунических каменных великанов.", description = "К востоку отсюда, на Тропе Великанов, были замечены изрисованные рунами каменные великаны, бредущие на север к Вершине Ледяного Клинка. Увы, я точно не знаю, куда они стремятся.\n\nОчевидно, мерцающие руны, вырезанные на каменной плоти, управляют их движением.\n\nВоспользуйся этой киркой, чтобы отключить руны на теле великанов, и сообщи мне все, что тебе удастся узнать.", progress = nil, completion = "&lt;Ученый Адеран внимательно слушает рассказ о ваших находках.&gt;\n\nЗначит, руны со значением \"север\" и \"запад\" повторялись несколько раз? Это похоже на явный приказ двигаться в том направлении, но не только эти руны приводят их в движение. Что-то притягивает к себе великанов, но что именно?", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11356] = {title = "Переодетая попечительница сирот", objective = "Поговорите с переодетой попечительницей сирот в Златоземье, Караносе или на Лазурной заставе.", description = "Во время Тыквовина сиротские приюты людей организуют для сироток поездки по деревням Альянса. Этим бедным детишкам так приятно будет увидеть <настоящего/настоящую:c> |3-3(<класс>) вроде вас!\n\nПочему бы тебе не сходить к ним? Сироток ты найдешь в Златоземье, что в Элвиннском лесу, в Караносе, что в Дун Мороге, и на Лазурной заставе на острове Лазурной Дымки. Поговори с переодетой попечительницей сирот, и она тебя им представит.", progress = nil, completion = "Вы пришли к детишкам! Замечательно! Они столько горя испытали за свою недолгую жизнь... Хорошо, что они посмотрят на настоящих героев, вроде вас. Это так поднимет их дух!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11357] = {title = "Попечительница сирот в маске", objective = "Поговорите с попечительницей сирот в маске в Колючем Холме, Брилле или на площади Соколиных Крыльев.", description = "В Тыквовин орчат-сироток возят с экскурсией по разным поселениям Орды. Попечительницы сирот считают, что детишкам хорошо бы посмотреть на настоящих героев, совершающих подвиги.\n\nПочему бы вам не навестить их? <Такой отважный/такая отважная:c> <класс> может воодушевить их рассказами о своей доблести! Отправляйтесь в Колючий Холм в Дуротаре, Брилл в Тирисфальских лесах или на площадь Соколиных Крыльев в лесах Вечной Песни. Поговорите с попечительницей сирот в маске, и она представит вас детишкам.", progress = nil, completion = "Детям нравится наблюдать за героями в деле. Надеюсь, что однажды эти сиротки станут сильными воителями Орды и погибнут в славной битве!\n\nАх, у меня все в глазах плывет от одной мысли о столь блистательной кончине...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11358] = {title = "Магнит", objective = "Ученый Адеран из крепости Вилдервар просит вас сравнить образцы рун с надписями на разбитой скрижали.", description = "Надо узнать, почему великаны стремятся на северо-запад. Только так мы сможем остановить их до того, как они достигнут места назначения. \n\nХотя образцы рун дали мне пищу для размышлений, меня больше беспокоят эти неизвестные символы. \n\nОднажды, когда я бродил по Тропе Великанов, я заметил огромную разбитую скрижаль, выступавшую из земли на северо-востоке области, там, где у подножия Вершины Ледяного Клинка появляется снег. Возьми этот образец и сравни руны с теми, что начертаны на скрижали. Посмотрим, что нам удастся узнать.", progress = nil, completion = "&lt;Адеран внимательно слушает описание вашей находки.&gt;\n\nМегалит? Это же буквальный перевод надписи с таблички! Должно быть, все тайные замыслы железных дворфов основаны на этом Мегалите. Мы должны уничтожить его, прежде чем они примутся за воплощение своих планов!", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11359] = {title = "Уничтожить Мегалита", objective = "Уничтожьте Мегалита и вернитесь к ученому Адерану в крепость Вилдервар.", description = "Мурдис-обуздатель создал Мегалита, чтобы тот созвал рунных великанов и повел их за собой. Если мы победим Мегалита, то оставим великанов без их предводителя. Пока мы будем двигаться на север, я попрошу вождя Прахтотема выделить несколько воинов для уничтожения последних рунных великанов. Лишившись своих подручных, железные дворфы ничего не смогут нам противопоставить. \n\nОтправляйся к подножию Вершины Ледяного Клинка, разыщи Мегалита к северу от Тропы Великанов и уничтожь это создание!", progress = nil, completion = "Ты совершил подвиг, победив Мегалита, но меня крайне обеспокоили его последние слова. Ты уверен, что он упомянул Каменную Кузню?\n\nМне ничего не говорит это название, хотя по звучанию оно напоминает язык титанов. Но при чем тут Железные дворфы? Надо найти эту Каменную Кузню до того, как наши враги смогут претворить в жизнь свои планы.", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11360] = {title = "Учения пожарной бригады", objective = "Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.", description = "Пока Всадник без головы еще угрожает нам, герои Златоземья всегда готовы сформировать пожарные бригады. Не хотите ли помочь?\n\nК северу отсюда стражники организовали небольшой полигон для учений пожарных бригад. Идите туда и носите ведрами воду, чтобы тушить пожар. Воду можно черпать ведром из этих бочек с водой.\n\nУдачи, <имя>. Когда поучаствуете в учениях пожарной бригады, возвращайтесь к нам!", progress = "Здравствуйте, Бутыльок. Вы когда-нибудь совершенствовались в технике тушения пожаров? Не забывайте об учебном полигоне на севере!", completion = "Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!\n\nОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!", rewards = "Вы получите:\n\nТыквовинская конфета"}
MultiLanguageQuestData['ru'][11361] = {title = "Учения пожарной бригады", objective = "Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Колючем Холме.", description = "Рубаки устроили полигон для учений пожарной бригады около деревни. В нынешние времена дома Колючего Холма часто горят, так что помоги им и поупражняйся в тушении пожара!\n\nИди на запад от Колючего Холма, за стеной сразу сверни направо. Найди полигон, хватай ведро и туши учебный пожар!", progress = nil, completion = "Славная работа, Джонниди! Детишки, берите пример с этого |3-6(Разбойник). Растите сильными и отважными, как он и настанет день, когда вы тоже будете сражаться за Орду!", rewards = "Вы получите:\n\nТыквовинская конфета"}
MultiLanguageQuestData['ru'][11362] = {title = "Разыскивается: Украшенный перьями посох Кели'дана", objective = "Торговец ветром Зарим просит вас добыть украшенный перьями посох Кели'дана. Принесите его ему в Нижний город Шаттрата и получите награду.\n\nЭто задание выполняется только в героическом режиме.", description = "О вкусах не спорят. Взять, например, моего последнего заказчика.\n\nВ цитадели Адского Пламени есть такой орк Скверны по имени Кели'дан Разрушитель. У него есть совершенно простенький посох. Ну просто смотреть не на что. И все же моему клиенту нужен именно этот посох.\n\nКто я такой, чтобы отказывать?\n\nЕсли желаете получить компенсацию за труды, ищите его вместе с посохом в Кузне Крови.", progress = "Раз мы с вами снова беседуем... То посох у вас.", completion = "Наверное, надо будет навязать на него новых перышек прежде, чем отдавать заказчику. Думаю, с таким количеством араккоа по соседству с перьями проблем не будет. Дело невеликое, и в любом случае ваша награда от этого меньше не станет.\n\nПриходите утром, и я вам новое дельце подберу.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11363] = {title = "Разыскивается: печать Острорука", objective = "Торговец ветром Зарим просит вас добыть печать Острорука. Принесите ее ему в Нижний город Шаттрата и получите награду.\n\nЭто задание выполняется только в героическом режиме.", description = "Один мой очень богатый клиент сделал заказ на действительно уникальную вещь.\n\nВождь Каргат Острорук имеет личную печать, которой он заверяет официальные документы. Добудь ее для меня.\n\nТы найдешь Каргата в глубине Разрушенных залов. Тебе придется перебить немало орков, чтобы добраться до него, но ты справишься, я уверен.", progress = "Слышал я, что у вождя вместо на месте рук клинки... Это правда?", completion = "Воистину геройское деяние, достойное воспевания бардов! Вот, ты более чем заслужил эту награду.\n\nПриходи завтра – у меня найдется для тебя новое дельце.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11364] = {title = "Разыскиваются: Центурионы клана Изувеченной Длани", objective = "Ловчий Пустоты Ма'дуун поручает вам убить 4 центурионов из клана Изувеченной Длани. Вернитесь к нему в Нижний город Шаттрата за наградой, как только перебьете их всех.", description = "А ты споришь с хозяином? Вот и Ма'дуун тоже.\n\nМне нужна кровь центурионов из клана Изувеченной Длани. Ты найдешь их в Разрушенных залах цитадели Адского Пламени.\n\nХочешь получить награду – не возвращайся, пока всех их не перебьешь.", progress = "Ты вернулся. Все центурионы мертвы?", completion = "Очень хорошо. Ты заслужил свою награду.\n\nПриходи завтра, а ветер еще разок пошепчется с Ма'дууном.", rewards = "Вы получите:\n\nКлюч от тюрьмы братства Эфириум"}
MultiLanguageQuestData['ru'][11365] = {title = "Марш великанов", objective = "Ведун Эдан из Лагеря Заиндевевшего Копыта попросил вас использовать кирку поиска рун на трупах 4 рунных каменных великанов.", description = "К востоку отсюда, на Тропе Великанов, были замечены изрисованные рунами каменные великаны, бредущие на север к Вершине Ледяного Клинка. Увы, я точно не знаю, куда они стремятся.\n\nОчевидно, мерцающие руны, вырезанные на каменной плоти, управляют их движением.\n\nВоспользуйся этой киркой, чтобы отключить руны на теле великанов, и доложи мне все, что тебе удастся выяснить.", progress = nil, completion = "&lt;Ведун внимательно слушает рассказ о ваших находках.&gt;\n\nЗначит, руны со значением \"север\" и \"запад\" повторялись несколько раз? Это похоже на явный приказ двигаться в том направлении, но не только эти руны приводят их в движение. Что-то притягивает к себе великанов, но что именно?", rewards = "Вы получите:\n\nПрипасы для экспедиции в НордсколПредмет #1"}
MultiLanguageQuestData['ru'][11366] = {title = "Магнит", objective = "Ведун Эдан из Лагеря Заиндевевшего Копыта просит вас сравнить образцы рун с надписями на разбитой скрижали.", description = "Надо узнать, почему великаны стремятся на северо-запад. Только так мы сможем остановить их до того, как они достигнут места назначения. \n\nХотя образцы рун дали мне пищу для размышлений, меня больше беспокоят эти неизвестные символы. \n\nОднажды, гуляя по Тропе Великанов, я заметил огромную разбитую скрижаль, выступавшую из земли на северо-востоке области, на границе со снегами Вершины Ледяного Клинка. Возьми этот образец и сравни руны с теми, что начертаны на скрижали. Посмотрим, что нам удастся узнать.", progress = nil, completion = "&lt;Эдан внимательно слушает описание вашей находки.&gt;\n\nМегалит? Это же буквальный перевод надписи с таблички! Должно быть, все тайные замыслы железных дворфов основаны на этом Мегалите.", rewards = "Вы получите:\n\nПрипасы для экспедиции в НордсколПредмет #1"}
MultiLanguageQuestData['ru'][11367] = {title = "Уничтожить Мегалита", objective = "Уничтожьте Мегалита и вернитесь к ведуну Эдану в Лагерь Заиндевевшего Копыта.", description = "Мурдис-обуздатель создал Мегалита, чтобы тот стал краеугольным камнем рунных великанов и повел их за собой. Если мы победим Мегалита, то оставим великанов без их предводителя. Пока мы будем двигаться на север, я попрошу вождя Прахтотема выделить несколько воинов для уничтожения последних рунных великанов. Лишившись своих подручных, Железные дворфы ничего не смогут нам противопоставить. \n\nОтправляйся к подножию Вершины Ледяного Клинка, разыщи Мегалита к северу от Тропы Великанов и уничтожь это создание!", progress = nil, completion = "Ты совершил подвиг, победив Мегалита, но меня крайне обеспокоили его последние слова. Ты уверен, что он упомянул Каменную Кузню?\n\nИмя это не знакомо нашему народу, но по звучанию оно похоже на одно из творений \"титанов\", о которых говорят чужеземцы. Железные дворфы всегда были коварными и опасными противниками, Расул. Нам следует присматривать за великанами и найти эту Каменную Кузню до того, как наши враги смогут претворить в жизнь свои планы.", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11368] = {title = "Разыскивается: сердце Квагмирран", objective = "Добудьте сердце Зыбуна и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение. \n\nЗадание можно выполнить только в героическом режиме.", description = "У меня к тебе довольно необычная просьба, <имя>. Одна состоятельная госпожа, моя постоянная клиентка, желает приобрести довольно жуткий предмет.\n\nЭто сердце чудовища, именуемого Зыбуном.\n\nВообще-то, у твари три сердца, однако нам будет довольно одного. Полагаю, ты найдешь Зыбуна в глубоком пруду в Узилище.", progress = "Надеюсь, ты знаешь, как сохранить сердце при транспортировке?", completion = "Какая жалость, что я не догадался попросить тебя принести заодно и два других сердца... Может, в следующий раз. В любом случае, ты честно заслужил обещанную награду. \n\nЗаходи завтра – у меня найдется для тебя работа.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11369] = {title = "Разыскивается: яйцо Черной Охотницы", objective = "Добудьте яйцо Черной Охотницы и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение. \n\nЗадание можно выполнить только в героическом режиме.", description = "Это великая праматерь болотоходов в Зангартопи. Она носит имя Черная Охотница. Умирая, она откладывает яйцо, из которого появляется новая Черная Охотница.\n\nОдин из моих клиентов желает приобрести такое яйцо. Вроде бы, он собирается держать тварь в частном зоопарке.\n\nЕсли хочешь получить вознаграждение, отправляйся в Нижетопь, убей Черную Охотницу и принеси мне ее яйцо.", progress = "Что, неужто принес яйцо? Показывай скорее!", completion = "В нем пульсирует жизнь – разве это не удивительно? Я должен поторопиться доставить его покупателю, пока новая Черная Охотница не вылупилась прямо здесь! \n\nВот и твоя награда. \n\nЗаходи завтра – у меня найдется для тебя работа.", rewards = "Вы получите:\n\nЗнак справедливостиОчки справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11370] = {title = "Требуется: трактат полководца", objective = "Добудьте трактат полководца и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение. \n\nЗадание можно выполнить только в героическом режиме.", description = "Многим известно, что полководец Калитреш по праву считался величайшим воином среди наг. Однако немногие знают, что он изложил свой военный опыт в трактате.\n\nСреди моих клиентов есть один господин, великолепно разбирающийся в военной истории. Он желает приобрести этот трактат.\n\nПрошу тебя отправиться в Паровое подземелье в резервуар Кривого Клыка и найти для меня эту книгу.", progress = "Мой клиент уже нервничает. Я думаю, он хочет самолично опробовать тактические уловки Калитреша на своих недругах как можно скорее.", completion = "Да, это действительно весьма, весьма богатая работа – хорошо бы мой клиент смог поднять этот талмуд, не говоря уж о том, чтобы успеть детально изучить его, прежде чем враги пойдут на него с войной. \n\nЗаходи завтра – у меня найдется для тебя работа.", rewards = "Вы получите:\n\nЗнак справедливостиОчки справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11371] = {title = "Разыскиваются: Мирмидоны Резервуара Кривого Клыка", objective = "Ловчий Пустоты Ма'дуун требует, чтобы вы убили 14 мирмидонов из резервуара Кривого Клыка. По исполнению задания возвращайтесь к Ма'дууну в Нижний город Шаттрата за вознаграждением.", description = "Я прошу твоей помощи.\n\nМне было поручено уничтожить наг-воинов из клана Кривого Клыка. Отыщи их в сырых уголках Парового подземелья в резервуаре Кривого Клыка.\n\nИмей в виду, требуется уничтожить всех до единого!", progress = nil, completion = "Надеюсь, ты не пожалел, что в это ввязался. Принимай заслуженную награду. \n\nВозвращайся завтра – возможно, ветра подскажут мне, какую тебе дать работу.", rewards = "Вы получите:\n\nКлюч от тюрьмы братства Эфириум"}
MultiLanguageQuestData['ru'][11372] = {title = "Разыскиваются: головные перья Айкисса", objective = "Добудьте перья с головы Айкисса и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.\n\nЭто задание может быть выполнено только в героическом режиме.", description = "Недавно ко мне пришла тауренка, мужу которой предстоит стать вождем. Она хочет сделать особое украшение для его головного убора.\n\nДля этого ей нужны головные перья трусливого Короля воронов Айкисса.\n\nЕсли тебя интересует предложенная награда, отправляйся в Сетеккские залы в Аукиндоне и найди его.", progress = "Церемония все ближе.", completion = "Я уверен, эти перья подойдут к головному убору вождя. Ты заработал эти деньги, |3-6(Чернокнижник).\n\nВозвращайся завтра, у меня будет для тебя новое задание.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11373] = {title = "Разыскивается: Заговоренный Амулет Шаффара", objective = "Добудьте заговоренный амулет Шаффара и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.\n\nЭто задание может быть выполнено только в героическом режиме.", description = "Сегодня у меня есть для тебя персональное задание, и награда, конечно же, будет соответствовать уровню риска.\n\nУ моей семьи есть кое-какие \"претензии\" к принцу Шаффару и его последователям. Если кто-то принесет мне личный амулет Шаффара, это вполне убедит меня в том, что c хозяином побрякушки разобрались. \n\nЕсли тебя заинтересовало предложенное вознаграждение, отправляйся к его логову в Гробницах маны в Аукиндоне.", progress = "Немногие знают, что магические силы Шаффара напрямую связаны с его амулетом. Без него он бессилен.\n\nЕсли амулет у тебя, то Шаффар, очевидно, мертв.", completion = "&lt;Вы чувствуете, что торговец ветром вами доволен.&gt;\n\nЗамечательно. Я рад слышать о его смерти. Возможно, мне удастся самому постигнуть тайны этого амулета. Если же нет – я знаю, кому его можно продать за хорошие деньги.\n\nВозвращайся завтра, у меня будет для тебя новое задание.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11374] = {title = "Разыскивается: Самоцвет души Экзарха", objective = "Добудьте самоцвет души экзарха и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.\n\nЭто задание может быть выполнено только в героическом режиме.", description = "В Аукенайских гробницах в Аукиндоне проводится множество сомнительных экспериментов в области некромантии. Там были замучены или уничтожены многие духи.\n\nОдин мой заказчик весьма заинтересован в освобождении одного из этих духов. Он заключен в камень, который носит не кто иной, как Экзарх Маладаар.\n\nКак можно скорее разыщи его в гробницах и принеси мне этот камень.", progress = "Представляешь, каково это – быть навечно заключенным в камне.", completion = "Ты настоящий герой, Снатяжкой. Я уверен, что мой клиент найдет способ освободить дух своего любимого человека из камня. За хорошую работу и плата полагается соответствующая.\n\nВозвращайся завтра, у меня будет для тебя новое задание.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11375] = {title = "Разыскивается: Шепот Бормотуна", objective = "Добудьте шепот Бормотуна и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.\n\nЭто задание может быть выполнено только в героическом режиме.", description = "Когда я расскажу все до конца, ты можешь захотеть отказаться от этого задания.\n\nУ моего клиента весьма эксцентричное увлечение – он специализируется на погибших реальностях. Ходят слухи, что тот, кого мы знаем как Бормотуна, уничтожил мир, из которого он был вызван. Профессор хочет изучить его \"шепот\" – так он это называет, – чтобы понять, как Бормотуну это удалось.\n\nСможешь ли ты отправиться в Аукиндонский Темный лабиринт и добыть этот \"шепот\"?", progress = "Не могу себе представить, как можно поймать шепот, но профессор заявил, что ты все поймешь, как только увидишь его.\n\nВозможно, тебе понадобится что-то вроде \"бормотографа\"...", completion = "Я беспокоился о тебе. Надеюсь, ты не оглох во время поединка с Бормотуном?\n\nВот твоя награда. Профессор будет очень доволен, хотя мне страшно представить, что он собирается с этим делать.\n\nВозвращайся завтра, у меня будет для тебя новое задание.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11376] = {title = "Разыскиваются: злобные инструкторы", objective = "Убейте для ловчего Пустоты Ма'дууна 3 злобных инструкторов, по выполнении вернитесь к нему в Нижний город Шаттрата, чтобы получить свою награду.", description = "Ма'дуун слышал, будто нет никого злее шестируких демонесс из Темного лабиринта.\n\nОтправляйся в Аукиндон и убей их всех.\n\nЕсли ты не сможешь выполнить такое простое задание, то нам с тобой не о чем говорить.", progress = nil, completion = "Я доволен. И тот кто говорит со мной через Пустоту, тоже будет доволен. Ма'дуун приготовил твою награду.\n\nПриходи завтра и ветра снова будут говорить с Ма'дууном.", rewards = "Вы получите:\n\nКлюч от тюрьмы братства Эфириум"}
MultiLanguageQuestData['ru'][11377] = {title = "Месть сладка", objective = "Скалл из Нижнего города просит вас приготовить похлебку из калири в его кухонном котелке. По выполнении вернитесь к нему.", description = "Сегодня я обслуживаю одну очень необычную вечеринку. Один тип летал в Скеттис, и его сбила чудовищная калири. У него тяжелый перелом ноги.\n\nОни заказали особое блюдо для вечеринки по случаю его выздоровления – похлебку из калири.\n\nЯ готов ссудить тебе мой кухонный котелок, так что можешь припасти немного похлебки для меня. Сам рецепт несложен, но тебе придется добыть крылышко гигантской калири и несколько готовых котлет из прыгуаны.", progress = "Какой восхитительный аромат! Неужто наяву?", completion = "О, да, наяву! Надеюсь, ты превратил эту пташку в хорошую отбивную?\n\nПрошу, бери, что хочешь из моих личных запасов. Уж ты при твоих талантах сумеешь воспользоваться ими по делу!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБочка с рыбойЯщик мяса\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11378] = {title = "Разыскивается: Голова Охотника Вечности", objective = "Торговец ветром Зарим просит вас добыть голову Охотника Вечности. Доставьте ее в Нижний город Шаттрата и получите награду.\n\nЭто задание выполняется только в героическом режиме.", description = "У моих клиентов вкусы – от самых простецких до самых экзотических. А иногда им желательна совершенно экзотическая вещь для самых простецких целей.\n\nНапример, последний заказ. Мой клиент, пожелавший остаться неизвестным, желает получить голову Охотника Вечности, дабы повесить ее на стене у себя дома.\n\n<класс>, не удастся ли вам найти способ вернуться в прошлое в старые Предгорья Хилсбрада и добыть искомую голову для моего клиента – любителя охотничьих трофеев?", progress = "Голова Охотника Вечности...кому только в голову взбредет прибивать ее к стенке у себя дома?\n\nНо если даже и взбредет, то что он скажет друзьям, когда они будут спрашивать, как он ее добыл?\n\nСоврет, наверное.", completion = "Вижу, вы вернулись в настоящее целый и невредимый.\n\n&lt;Торговец ветром озирается по сторонам.&gt;\n\nВроде все как было. Но опять же – кто знает?\n\nХорошая работа – клиент будет доволен. Вот ваша награда.\n\nВозвращайтесь завтра, и у меня найдется для вас другое порученьице.", rewards = "Вы получите:\n\nЗнак справедливостиОчки справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11379] = {title = "Очень горячая похлебка", objective = "Скалл из Нижнего города просит вас приготовить немного невероятной демонической похлебки в его кухонном котелке. Вернитесь, когда приготовите.", description = "Я пытаюсь изобрести что-нибудь такое, чтобы уж вштыривало, так вштыривало. Но, честно говоря, я уже не тот гоблин, что прежде. Я утратил вкус к приключениям.\n\nНо ты напоминаешь мне меня в юности. Тогда я готов был завоевать весь мир с мечом в одной руке и сковородкой в другой.\n\nВозьми мой любимый кухонный котелок и ступай в Острогорье. Брось туда немного ребрышек и поджаристых змеек – заранее приготовленных ради аромата – и свари их над трупом демона Бездны – на свете нет ничего горячее, чтобы сварить такую похлебку.", progress = "Ну, как, удался мой экспериментик?", completion = "Посмотрим-посмотрим...\n\n&lt;Скалл отхлебывает немного варева, и на лице его рисуется невероятная смесь восторга и страданияt.&gt;\n\nА'дал сладчайший, какая вкуснотища! Такому повару, как ты, просто неприлично не обзавестись собственными припасами! Возьми из моих, и да буду я гордиться твоими успехами!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБочка с рыбойЯщик мяса\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11380] = {title = "Мания", objective = "Скалл из Нижнего города просит вас принести 15 манаягод из заповедников Пустоверти.", description = "Если хочешь знать, по мне так мои припасы первый сорт, но вот приходит ко мне некто и желает странного: манаягодной услады.\n\nУвы, манаягоды растут только в заповедниках Пустоверти. Даже не пытайся искать вокруг Штормовой Вершины – даром время потратишь, там все обобрали.\n\nЯ могу доверить сбор лучших ягод только тому, кто сведущ в кулинарии, так что не подведи меня!", progress = "Ну как, повезло?", completion = "Более сочных манаягод не видел в жизни! Умнею от одного взгляда на них.\n\nПоскольку запасы мяса и рыбы мне уже не нужны, почему бы тебе в них не порыться? Уверен, ты сможешь приготовить настоящий деликатес!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБочка с рыбойЯщик мяса\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11381] = {title = "Супчик для души", objective = "Скалл из Нижнего города просит вас приготовить суп предков в его кухонном котелке. По выполнении вернитесь к нему.", description = "В воздухе пахнет смертью. Никогда я не имел столько заказов на мой замечательный супчик – он поднимает дух и утешает душу.\n\nА собрата-повара я узнаю издалека! Не хочешь ли мне помочь – а выручку поделим! \n\nВот, бери мой кухонный котелок, бери мясо копытня, и я открою тебе один маленький секрет. Знаешь, отчего мой супчик так ублажает душу? Не из-за куриного бульона – я варю его в Землях Предков в Награнде, дабы он впитывал духовность!", progress = "Что за божественный запах?", completion = "Судя по запаху – чудесный суп предков, не будь я Скалл! Добавить щепотку перчика – и готово.\n\nКак и обещал, вот твоя доля. И поскольку ты проделал такую славную работу, я добавлю туда немножко своих собственных специй.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБочка с рыбойЯщик мяса\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11382] = {title = "Разыскиваются: песочные часы Эонуса", objective = "Торговец ветром Зарим просит вас добыть песочные часы Эонуса. Доставьте их в Нижний город Шаттрата и получите награду.\n\nЭто задание выполняется только в героическом режиме.", description = "Один из моих заказчиков точно чокнутый. Есть нормальные чокнутые, а есть такие, что и подумать страшно!\n\nНынешний мой клиент по такой шкале просто зашкаливает. Он возжелал песочных часов Эонуса!\n\nДа, вы не ослышались, Эонуса из рода Бесконечности!\n\nТаки ж разве я откажусь, если он платит по-королевски? Может, вы прогуляетесь в пещеры Времени и в Черную топь и добудете их для меня?", progress = "На вашем месте я очень осторожно бы странствовал во времени. Вы ведь не хотите случайно во что-нибудь вляпаться? Например, убьете какого-нибудь своего предка и в результате вычеркнете себя из настоящего!", completion = "Странно, что песчинки в этой штуке падают вверх. Думаю, надо как можно скорее отдать ее новому владельцу.\n\nБлагодарю за хорошую работу, |3-6(Охотник). Вы честно заработали свои комиссионные.\n\nПриходите завтра и я приготовлю для вас очередную работу.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11383] = {title = "Разыскиваются: Повелители временных разломов", objective = "Ловчий Пустоты Ма'дуун хочет, чтобы вы убили 4 повелителей временных разломов. Вернитесь к нему в Нижний город Шаттрата за наградой, когда они будут убиты.", description = "Ма'дуун знает, куда тебе идти. Ма'дуун знает, что ты <должен/должна> убить повелителей временных разломов. Но Ма'дуун не знает, когда именно.\n\nЯ понимаю, что это звучит бессмысленно, но ветер не нашептал ничего более определенного.\n\nОтправляйся в Черную топь через пещеры Времени, и путь будет чист.", progress = nil, completion = "Ты сумел попасть в прошлое и вернуться обратно. Ты наверняка великий |3-6(Воин), |3-6(человек). Награда твоя заслуженна.\n\nВозвращайся завтра, и ветер нашепчет Ма'дууну кое-что еще.", rewards = "Вы получите:\n\nКлюч от тюрьмы братства Эфириум"}
MultiLanguageQuestData['ru'][11384] = {title = "Разыскивается: Отросток Узлодревня", objective = "Торговец ветром Зарим просит вас добыть отросток Узлодревня. Доставьте его ему в Нижний город Шаттрата и получите награду.\n\nЭто задание выполняется только в героическом режиме.", description = "Не так давно со мной связался калдорайский друид по одному щекотливому дельцу. И отвалит она за работу, конечно же, кучу золота!\n\nСдается, что силы Дарнаса намерены возродить ходячее древо тайной магии, известное под именем Узлодревень. Это гигантское дерево не то свихнулось, не то подверглось порче, точно сказать не могу, но найдете вы его в Ботанике в Крепости Бурь.\n\nОна сказала, что им всего-то надо маленький отросточек от него, чтобы вырастить древо заново.", progress = "Вы сбились с пути и не нашли Ботанику? Нет. Ее не заметить нельзя... Это же в Крепости Бурь на восточном краю Пустоверти.", completion = "Ах, так вы добыли его! Какой маленький. И все же, когда друиды закончат свое дело – а я слышал, что процесс займет очень много времени – Узлодревень вырастет заново.\n\nА вот и обещанная награда.\n\nПриходите утром – у меня будет для вас новое дельце.", rewards = "Вы получите:\n\nЗнак справедливостиОчки справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11385] = {title = "Разыскиваются: Солнцеловы-чаротворцы", objective = "Ловчий Пустоты Ма'дуун хочет, чтобы вы убили 6 солнцеловов-чаротворцев. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду.", description = "Ветер нашептал Ма'дууну, что заклинатели из военного подразделения под названием Солнечные Охотники должны быть убиты непременно сегодня.\n\nИх можно найти в Ботанике в Крепости Бурь.\n\nХочешь получить награду – убей заклинателей.", progress = nil, completion = "Раз они мертвы, больше никто не будет творить заклинания. Тот, кто шепчет из Пустоты, доволен, и награда – твоя.\n\nВозвращайся утром, и ветер нашепчет Ма'дууну что-нибудь еще.", rewards = "Вы получите:\n\nКлюч от тюрьмы братства Эфириум"}
MultiLanguageQuestData['ru'][11386] = {title = "Разыскивается: Проектор Паталеона", objective = "Торговец ветром Зарим просит вас добыть проектор Паталеона. Доставьте его в Нижний город Шаттрата и получите награду.\n\nЭто задание выполняется только в героическом режиме.", description = "Я всегда думал, что Паталеон Вычислитель пользуется магией, чтобы передавать свой образ в Запределье. Очевидно, я ошибался.\n\nОдин из моих клиентов сказал, что этот проклятый эльф крови пользуется механическим прибором для связи с руководителями особых проектов принца Кель'таса. Насколько я понимаю, он забрал его у одного из отступников из братства Заксис в Пустоверти.\n\nМой клиент желает получить этот прибор. Не желаешь ли ты нанести визит Паталеону? Его можно найти в Механаре, в Крепости Бурь.", progress = "Технология проекции сама по себе не сложна, но мощность этой модели – настоящий прорыв!", completion = "Очень хочется придержать эту штуку и вернуть клиенту деньги. Проектор весьма расширит границы моей профессиональной деятельности.\n\n&lt;Торговец ветром вздыхает.&gt;\n\nНо я должен заботиться о своей репутации. Кстати, спасибо, что помог ее сохранить.\n\nВот твои комиссионные.\n\nПриходи утром, и я предложу тебе еще одно дельце.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11387] = {title = "Разыскиваются: разрушители из кузни бурь", objective = "Ловчий Пустоты Ма'дуун хочет, чтобы вы уничтожили 5 разрушителей из кузни бурь. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду.", description = "В Механаре есть механические создания которые Ма'дууну поручено разобрать.\n\nОтправляйся в Крепость Бурь, найди разрушителей из кузни бурь и разрушь их.\n\nПотом можешь вернуться за наградой.", progress = nil, completion = "Ма'дууну нравятся боевые механизмы – они не такие непредсказуемые, как органические создания.\n\nНаграда твоя.\n\nВозвращайся утром, и ветер нашепчет Ма'дууну что-нибудь еще.", rewards = "Вы получите:\n\nКлюч от тюрьмы братства Эфириум"}
MultiLanguageQuestData['ru'][11388] = {title = "Разыскивается: Свиток Скайрисса", objective = "Торговец ветром Зарим просит вас добыть свиток Скайрисса. Доставьте его в Нижний город Шаттрата и получите награду.\n\nЭто задание выполняется только в героическом режиме.", description = "Нынешний клиент хочет получить нечто воистину необычное.\n\nЕсть такой предвестник Скайрисс, слуга древних богов. Также говорят, что у него есть большой свиток, в котором содержатся их указания насчет того, как ему повелевать жизнью во вселенной от их имени.\n\nМой нынешний клиент желает заполучить этот свиток, хотя он – или она – даже прочесть его не сможет.\n\nТак что не будете ли любезны отправиться в Крепость Бурь в Аркатрац и добыть его для меня? Ну, по рукам, <класс>?", progress = "Наверняка очень опасно вмешиваться напрямую в дела древних богов.\n\nТак что лучше вы, чем я!", completion = "Я даже прикоснуться к свитку не осмелюсь, чтобы не привлечь к себе ненароком внимание древних богов. Пусть его доставит один из моих помощников.\n\nВы более чем заслужили свою награду, |3-6(Маг), и я желаю вам самой большой на свете удачи!\n\nПриходите поутру – у меня будет для вас новое дело.", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11389] = {title = "Разыскиваются: Часовые Аркатраца", objective = "Ловчий Пустоты Ма'дуун хочет, чтобы вы навсегда деактивировали 5 часовых Аркатраца. Вернитесь к нему в Нижний город Шаттрата, когда выполните задание, чтобы забрать награду.", description = "Часовые Аркатраца вышли из строя. Заключенные взбунтовались, а часовые нападают на тех, кто бы мог помочь.\n\nМа'дуун слышит шепот ветров Пустоты. Шепот велит уничтожить часовых.\n\nСделай это – и сегодняшняя награда твоя.", progress = nil, completion = "Теперь, когда часовые уничтожены, наверное, наару попросят Консорциум их заменить? Ма'дуун не знает, да ему и все равно.\n\nТы заслужил награду.\n\nВозвращайся утром, и ветер нашепчет Ма'дууну что-нибудь еще.", rewards = "Вы получите:\n\nКлюч от тюрьмы братства Эфириум"}
MultiLanguageQuestData['ru'][11390] = {title = "У меня есть ветролет!", objective = "Главный археолог Стальных ворот просит вас отвезти 3 мешка с реликвиями из раскопа на платформы к северу и югу от Стальных ворот.\n\nДля этого вам надо будет воспользоваться погрузочным крюком ветролета.\n\nВыполнив задание, вернитесь к главному археологу.", description = "Ну, и чего ты ждешь? Работы невпроворот!\n\nВот ключи от ветролета. Хватай три мешка с реликвиями и вези их на платформы к северу и югу от Стальных ворот. Я отмечу на карте их местоположение.\n\nДа поторопись! У нас нет времени!", progress = nil, completion = "Молодец, хотя вводный курс по пилотированию тебе явно не помешает. \n\nЛадно, дело сделано – и это главное. Вот твоя доля.", rewards = "Трескучий плащВам дадут возможность выбрать одну из следующих наград:\n\nКольцо ретивостиТалисман из клыка ворга\n\nВы также получите:\n\nГигантский флакон с лечебным зельем"}
MultiLanguageQuestData['ru'][11391] = {title = "Патрулирование Стальных Ворот", objective = "Теперь вы лучший пилот Стальных ворот, и главный археолог Стальных ворот поручил вам патрулировать раскопки.\n\nОтразите нападение агрессивных существ, после чего вернитесь к главному археологу.", description = "А? Хочешь еще поработать?\n\nНу ладно, держи ключи. Таскать сегодня ничего не надо, так что просто смотри по сторонам – не заметишь ли чего подозрительного. \n\nЯ прикрутил к машине парочку ракет и пулемет – на всякий случай.", progress = "горгулии?! Видел я парочку таких тварей! Надеюсь, ты с ними справился?\n\nНет, куда катится мир? Честному дворфу нельзя уже спокойно в земле покопаться, чтобы на него никто не напал!", completion = "Хорошо стреляешь! Сразу видно – профессионал.\n\nВот твоя доля. Приходи завтра за следующим заданием, ладно?", rewards = "Вы получите:\n\nГигантский флакон с лечебным зельем"}
MultiLanguageQuestData['ru'][11392] = {title = "Вызов Всадника без головы", objective = "Принесите мрачную свечу к груде рыхлой вывороченной почвы.", description = "Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...", progress = "Эта земля совсем свежая. В ней ползают черви, пытаясь спрятаться поглубже.", completion = "Осмелитесь ли вы положить свечу и вызвать Всадника без головы, пробудив его от проклятого сна?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11393] = {title = "Куда пропал исследователь Джарен?", objective = "Надзирательница Ирена Каменная Мантия попросила вас отыскать ее суженого, исследователя Джарена.", description = "<имя>! Мой возлюбленный, Джарен, отправился на запад вместе с маленьким отрядом исследователей, которые хотели проверить слухи об артефактах на Берегу Стылой Межи. Но я слышала, что там водятся мурлоки, и потому боюсь даже предполагать, что могло случиться с моим любимым. \n\nТы ведь не откажешься узнать, все ли у него в порядке? К пляжу ведет юго-западная дорога, но она не безопасна – рядом с ней по лесу бродят ворги и прочие опасные твари.", progress = nil, completion = "&lt;Узнав, кто отправил вас на поиски, исследователь радостно улыбается и тихо шепчет&gt;\n\nТак, говоришь, Ирена обо мне беспокоится? Она так похожа на своего отца!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11394] = {title = "Думаешь, мурлоки – самые вонючие существа?", objective = "Исследователь Джарен поручил вам убить 15 любых солдат Плети, которые встретятся вам вдоль Берега Стылой Межи. Когда вы выполните это задание, вернитесь к нему.", description = "Вообще-то, я приехал сюда для того, чтобы проверить слухи о погребенных здесь артефактах. Я слышал, что на побережье встречаются мурлоки, но даже не мог себе представить, с чем мне предстоит столкнуться. \n\n<Исследователь осторожно высовывает голову из-за дерева и оглядывается по сторонам.>\n\nЗдесь повсюду солдаты Плети, и они что-то делают с мурлоками и прочими тварями, превращая их в ходячих мертвецов!\n\n<класс>, мне кажется, мы должны что-то предпринять. Как ты думаешь, тебе по плечу победить несколько солдат Плети?", progress = nil, completion = "&lt;Джарен очень рад вашим успехам, но старается выражать свои эмоции как можно тише.&gt;\n\nТы молодец, Reng! Правда, твои доспехи перепачканы в слизи. Может быть, тебе сходить искупаться в проливе? Вода там холодная, но зато ты быстро смоешь с себя эту пакость.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11395] = {title = "Устройство Плети", objective = "Отнесите устройство Плети исследователю Джарену на Берег Стылой Межи.", description = "В когтях у только что убитого вами существа Плети оказалось устройство, инкрустированное драгоценными камнями, которые очень похожи на те, что украшают вершину смертоносных кристаллов.\n\nИсследователю Джарену непременно захочется изучить этот прибор.", progress = "Какое странное устройство! Дай-ка я на него взгляну...", completion = "Я знаю, что это! Имбирюша, с помощью этого прибора можно управлять смертоносными кристаллами!\n\nСпорим на что угодно, эта штука может отключить окружающие их силовые поля. Хмм.\n\n&lt;Исследователь смотрит на вас в задумчивости, прикидывая, справитесь ли вы с прибором.&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11396] = {title = "Отключи защитное поле", objective = "Исследователь Джарен поручил вам уничтожить 3 смертоносных кристалла.", description = "Взгляни вот на эту кнопку сбоку пульта. Могу поспорить, если ты нажмешь на нее в непосредственной близости от смертоносных кристаллов, ты сможешь отключить защитное поле. Затем тебе останется только уничтожить кристалл до того, как защита будет восстановлена.\n\nЧто скажешь, <имя>? Справишься? Гарантирую, щедрая награда за уничтожение кристаллов тебе обеспечена. \n\nЭто меньшее, что мы можем сделать для того, чтобы предотвратить размножение Плети.", progress = nil, completion = "Ура!\n\n&lt;Джарен испуганно оглядывается в надежде, что его радостный возглас не привлек к нему излишнего внимания.&gt;\n\nНу, дружище, ты заслужил награду. Возьми одну из этих вещей, которые я нашел здесь, на побережье.\n\nКстати, если будешь проходить мимо Стальных ворот, передай Ирене, что я ее люблю. Пусть знает, что со мной все в порядке.", rewards = "Рогатый великий шлемБотинки-вурдалакодавыВам дадут возможность выбрать одну из следующих наград:\n\nВосстанавливающее кольцо землепрядаЗаряженная руна холодного камня\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11397] = {title = "Думаешь, мурлоки – самые вонючие существа?", objective = "Аптекарь Анастасия поручила вам убить 15 любых солдат Плети, которые встретятся вам вдоль Берега Стылой Межи. Когда вы выполните это задание, вернитесь к ней в Аптекарский поселок.", description = "Ходили слухи, что в этом месте видели солдат Плети – поэтому-то я сюда и приехала. Признаться, я ожидала встретить только мурлоков на побережье, и даже не могла себе представить, с чем мне предстоит столкнуться. \n\nЗдесь повсюду солдаты Плети, и они что-то делают с мурлоками и прочими тварями, превращая их в ходячих мертвецов!\n\n<класс>, мы не можем позволить им пополнить свою армию мурлоками! К северо-западу от лагеря есть обрыв, который ведет к побережью. Посмотрим, удастся ли тебе справиться с солдатами Плети!", progress = nil, completion = "&lt;Анастасия на мгновение задумывается над вашими словами.&gt;\n\nДа, ты неплохо потрудился, но этого недостаточно. Мы должны остановить Плеть и изгнать их с побережья!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11398] = {title = "Устройство Плети", objective = "Отнесите устройство Плети аптекарю Анастасии в Аптекарский поселок.", description = "В когтях у только что убитого вами существа Плети оказалось устройство, инкрустированное драгоценными камнями, которые очень похожи на те, что украшают вершину смертоносных кристаллов.\n\nАптекарю Анастасии непременно захочется изучить этот прибор.", progress = "Какое странное устройство! Дай-ка я на него взгляну...", completion = "Я знаю, что это! Расул, с помощью этого прибора можно управлять смертоносными кристаллами!\n\nСпорим на что угодно, эта штука может отключить окружающие их силовые поля. Хмм.\n\n&lt;Аптекарь смотрит на вас в задумчивости, прикидывая, справитесь ли вы с прибором.&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11399] = {title = "Отключи защитное поле", objective = "Аптекарь Анастасия поручила вам уничтожить 3 смертоносных кристалла.", description = "Взгляни вот на эту кнопку сбоку пульта. Могу поспорить, если ты нажмешь на нее в непосредственной близости от смертоносных кристаллов, ты сможешь отключить защитное поле. Затем тебе останется только уничтожить кристалл до того, как защита будет восстановлена.\n\nЧто скажешь, <имя>? Справишься? Гарантирую, щедрая награда за уничтожение кристаллов тебе обеспечена. \n\nЭто меньшее, что мы можем сделать для того, чтобы предотвратить размножение Плети.", progress = nil, completion = "&lt;Анастасия оборачивается и с улыбкой смотрит на своего суккуба.&gt;\n\nПревосходно, Расул. Полагаю, ты заслужил награду. Выбери себе что-нибудь из этого.", rewards = "Рогатый великий шлемБотинки-вурдалакодавыВам дадут возможность выбрать одну из следующих наград:\n\nВосстанавливающее кольцо землепрядаЗаряженная руна холодного камня\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11400] = {title = "Скаковые бараны Хмельного фестиваля", objective = "Покажите штамп Полу Янтарлену у входа на территорию Хмельного фестиваля в Дун Мороге.", description = "Если ты покажешь этот штамп Дризу Неуклюге, начинающему наезднику на баранах, он позволит тебе купить скакового барана на Хмельном фестивале.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][11401] = {title = "Вызов Всадника без головы", objective = "Принесите мрачную свечу к груде рыхлой вывороченной почвы.", description = "Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...", progress = "Эта земля совсем свежая. В ней ползают черви, пытаясь спрятаться поглубже.", completion = "Осмелитесь ли вы положить свечу и вызвать Всадника без головы, пробудив его от проклятого сна?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11402] = {title = "Clayton's Quest: Extreme!", objective = "Seriously, go slay those Evil Squirrels!", description = "Clayton wants you to find and slay twenty Evil Squirrels.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11403] = {title = "Наконец, свободен!", objective = "Возьмите книгу Томаса Томсона и отнесите ее попечительнице сирот в маске в Дуротар, Брилл или на Площадь Соколиных Крыльев.", description = "Гнев был моей темницей, <имя>, а ты $Gосвободил:освободила; меня. Хотя я считал себя правым, душа моя ныне кровоточит от всех тех ужасов и смертей, которые обрушил я на жителей Азерота.\n\nБлагодарю тебя, что ты <привел/привела> меня к Свету. Да не сверну я с этого пути!\n\nОтнеси этот потрепанный молитвенник попечительнице сирот, чтобы дети узнали, что больше я их не потревожу.", progress = "Приятно снова видеть вас, Джонниди. Уверена, детишки с радостью послушают рассказы о ваших геройских подвигах!", completion = "Что это? Этот священный фолиант принадлежал недоброй памяти паладину Альянса. Он и был всадником без головы? Неужели он, наконец, побежден?\n\nЧто за радостный день! Джонниди, ваше имя будет прославлено в легендах, и пусть они проживут в два раза дольше, чем длилось ужасное владычество всадника!", rewards = "Вы получите:\n\nТыквовинская конфета"}
MultiLanguageQuestData['ru'][11404] = {title = "Вызов Всадника без головы", objective = "Принесите мрачную свечу к груде рыхлой вывороченной почвы.", description = "Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...", progress = "Эта земля совсем свежая. В ней ползают черви, пытаясь спрятаться поглубже.", completion = "Осмелитесь ли вы положить свечу и вызвать Всадника без головы, пробудив его от проклятого сна?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11405] = {title = "Вызов Всадника без головы", objective = "Принесите мрачную свечу к груде рыхлой вывороченной почвы.", description = "Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...", progress = "Эта земля совсем свежая. В ней ползают черви, пытаясь спрятаться поглубже.", completion = "Осмелитесь ли вы положить свечу и вызвать Всадника без головы, пробудив его от проклятого сна?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11406] = {title = "Все должно быть готово", objective = "Поговорите с Гилом Гризертом в крепости Вилдервар.", description = "Скоро на север будут посланы несколько исследовательских отрядов, и капитан Адамс рассчитывает, что строительство крепости Вилдервар будет завершено к тому моменту. Разведчикам и ремесленникам было поручено подготовить обмундирование и припасы для наших людей, которые отправятся покорять скалы. \n\nКапитан известен своим буйным нравом, так что я хочу послать кого-нибудь вперед проверить ход подготовки. Крепость Вилдервар находится далеко на северо-востоке, за Скорном, рядом с Седыми холмами. Найди там Гила Гризерта и убедись, что все готово.", progress = nil, completion = "А, тебя послал интендант? \n\n&lt;Гил облегченно вздыхает.&gt;\n\nЧестно говоря, мы немного отстаем от графика, так что помощь нам не помешает. \n\n&lt;Он вздрагивает.&gt;\n\nКому охота попасть под горячую руку капитану Адамсу?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11407] = {title = "Пивоварня Дрона ищет зазывалу!", objective = "Зазывайте посетителей на Хмельной фестиваль у флагов на аллее Силы, на аллее Чести, на аллее Мудрости и на аллее Духов.", description = "Значит, ты хочешь потрудиться во славу Хмельного фестиваля? Тогда поработай зазывалой возле флагов рядом с аукционным домом на Аллее Силы, на Аллее Чести, на Аллее Мудрости и на Аллее Духов.\n\nМы одолжим тебе скакового барана на 4 минуты и дадим тебе гоночные поводья.\n\nСоблюдай осторожность, жадины-гоблины не положили по дороге ни одного ящика с яблоками.", progress = "Ты уже всем рассказал о Хмельном фестивале?", completion = "Ты сдержал слово и рассказал всем вокруг о нашей винокурне. Спасибо. Мы обещали наградить тебя билетами – что ж, бери. Думаю, тролли не так охотно с ними расстаются…\n\nЗаходи завтра, поработаешь еще денек зазывалой.", rewards = "Вы получите:\n\nПризовой жетон Хмельного фестиваля"}
MultiLanguageQuestData['ru'][11408] = {title = "Пивоварня Т'чали Вуду ищет зазывалу!", objective = "Зазывайте посетителей на Хмельной фестиваль у флагов на аллее Силы, на аллее Чести, на аллее Мудрости и на аллее Духов.", description = "Пусть все узнают, что на Хмельной фестиваль прибыли и тролли! Поработай зазывалой возле флагов рядом с аукционным домом на Аллее Силы, на Аллее Чести, на Аллее Мудрости и на Аллее Духов.\n\nМы одолжим тебе скакового барана на 4 минуты и дадим тебе гоночные поводья.\n\nСоблюдай осторожность, гоблины не положили по дороге ни одного ящика с яблоками. Вот такие они жадины.", progress = "Ты уже всем рассказал о Хмельном фестивале? И, что самое главное, о чудесном тролльском пиве?", completion = "Ну дела! Во зазывала из тебя получился! Самое время готовиться к наплыву посетителей! Спасибо!\n\nАх да, мы обещали тебе награду. Помним, как же, как же…\n\nЗаходи в любой день, поработай еще зазывалой.", rewards = "Следующее заклинание будет наложено на вас:\n\nСпешиться с барана - задание\n\nВы получите:\n\nПризовой жетон Хмельного фестиваля"}
MultiLanguageQuestData['ru'][11409] = {title = "А теперь гонки на баранах... Или вроде того.", objective = "У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.", description = "Хочешь попробовать себя в роли <наездника/наездницы> на баране? Дворфы считают, что никто их не переплюнет, но будем откровенны, они же большую часть времени пьяны. Так что в этом может быть сложного? Но прежде чем я допущу тебя к соревнованиям, покажи, что справишься с нашими скакунами.\n\nВот что я предлагаю: возьми скакового барана и поводья и покажи, что умеешь ездить верхом.\n\nПусти барана на 8 секунд рысью, потом на 8 секунд легким галопом и на 8 секунд – галопом.", progress = nil, completion = "Эй, не так-то плохо... Ты точно не дворф?\n\nГонок в округе хватает, и не только здесь. На Хмельном фестивале хорошие наездники на баранах в цене. Иди, найди себе работу.\n\nИ не забывай, эти бараны куплены совершенно законным путем. Помни про это.", rewards = "Следующее заклинание будет наложено на вас:\n\nСпешиться с барана - задание\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][11410] = {title = "Та самая рыбка", objective = "Кристофер Слоан из крепости Вилдервар просит вас победить Ледяного Плавника.", description = "Принесенная тобой рыба-шип подойдет в качестве наживки, но я, признаться, боюсь, что на нее клюнет настоящее чудовище! \n\nКогда я впервые забросил тут удочку Ната Пэгла с моей любимой наживкой, из воды высунулась огромная тварь с кошмарными зубами и сосульками на плавниках!\n\nЕсли бы я не обрезал леску, она утащила бы меня под лед. Нет, я не буду экспериментировать с новой наживкой, пока старина Ледяной Плавник плавает поблизости. Впрочем, если хочешь с ним повстречаться, забрось удочку в середине озера. Он не устоит перед такой рыбкой!", progress = nil, completion = "Наконец-то я могу рыбачить спокойно! Правда, к тому времени, как мы что-то поймаем, сюда прибудет экспедиция и заберет себе всю добычу. \n\nНо ты молодец, Reng. Заходи еще, не стесняйся.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11411] = {title = "Лагерь Заиндевевшего Копыта", objective = "Поговорите с вождем Прахтотемом в Лагере Заиндевевшего Копыта.", description = "За все время работы курьером мне приходилось видеть множество странных обитателей Ревущего фьорда, но среди них особенно выделяется одна группа необычных существ. Издали они напоминают тауренов, но, изучив их внимательнее, я заметил, что они гораздо сильнее и грубее.\n\nОдно из их поселений находится на севере, за Халгриндом, Скорном и северными лесами. Зовется оно Лагерь Заиндевевшего Копыта, и располагается у подножия Гьялерхорна, рядом с Седыми холмами. Я поручаю тебе вступить в контакт с этими существами и выяснить, могут ли они оказаться нам полезны.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11412] = {title = "Туда и обратно", objective = "Возьмите бочку у гоблина, застрявшего возле Бухты Острорука, и отвезите ее помощнику Рэя, погонщика баранов. Пока баран не сбежит от вас, постарайтесь доставить три бочки.", description = "Хорошо, что ты здесь. Мы изрядно влипли! Гоблин, который подвозит пиво, попал в аварию возле Бухты Острорука! Ты непременно <должен/должна> привезти нам это пиво!\n\nЯ посажу тебя на одного из своих верховых баранов, а ты скачи по этой дороге до самой Бухты Острорука.\n\nКак только гоблин тебя увидит, сразу передаст тебе бочку, а ты привези ее сюда и отдай ее моему более толковому помощнику. Сейчас мне нужны три бочки. Хорошо поработаешь – мы тебе еще работенку подбросим.", progress = nil, completion = "Огромное спасибо за помощь! Пока дворфы Черного Железа не сложили оружие, а Хмельной фестиваль продолжается, мне не обойтись без помощников. Если ты хочешь еще подзаработать, приходи завтра.\n\nВот обещанные жетоны, желаю веселого Хмельного фестиваля!", rewards = "Следующее заклинание будет наложено на вас:\n\nСпешиться с барана - задание\n\nВы получите:\n\nПризовой жетон Хмельного фестиваля"}
MultiLanguageQuestData['ru'][11413] = {title = "Кто сказал \"сувениры\"?", objective = "Найдите в лагере Хмельного фестиваля Бликса Чиништукса, отдайте ему купон и получите бесплатную праздничную пивную кружку.", description = "Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.\n\nПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЖелтая кружка Хмельного фестиваля"}
MultiLanguageQuestData['ru'][11414] = {title = "Братья-предатели", objective = "Улклык попросил вас убить воргов-предателей, Бьомолфа и Варга. Когда вы убьете их, вернитесь к нему в Вырубки в обличье ворга.\n\nЕсли вы потеряете личину ворга, возьмите другую у дозорной Лунный Лепесток.", description = "Дозорная Лунный Лепесток являлась мне во снах! Ее друг – и мой друг.\n\nДо последнего полнолуния я считался главным самцом в стае. Затем с севера пришел этот странный белый ворг, Гарвал, и с помощью моих бывших братьев встал во главе стаи. Но что-то в нем меня беспокоит.\n\nЕсли ты хочешь помочь мне, убей тех, кто предал меня. \n\nОдного из них зовут Бьомолф, и он охотится на северо-западе от места, которое вы называете Стальные ворота. Другой, Варг, обитает на юго-востоке, рядом с Западной башней.\n\nНо их ты не обманешь своим обличьем.", progress = nil, completion = "Меня радует запах их крови на твоей морде. Братья не должны предавать друг друга.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11415] = {title = "Братья-предатели", objective = "Улклык попросил вас убить воргов-предателей, Бьомолфа и Варга. Выполнив его просьбу, наденьте личину ворга и вернитесь к Улклыку.\n\nЕсли вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.", description = "Странник Туманов являлся мне во снах! Его друг – мой друг.\n\nДо последнего полнолуния я считался главным самцом в стае. Затем с севера пришел этот странный белый ворг, Гарвал, и с помощью моих бывших братьев встал во главе стаи. Но что-то в нем меня беспокоит.\n\nЕсли ты хочешь помочь мне, убей тех, кто предал меня. \n\nОдного из них зовут Бьомолф, и он охотится на северо-западе от места, которое вы, двуногие, называете Стальные ворота. Другой, Варг, обитает на юго-востоке, рядом с Западной башней.\n\nНо их ты не обманешь своим обличьем.", progress = "<Улклык негромко рычит.>\n\nБьомолф и Варг все еще живы!", completion = "Меня радует запах их крови на твоей морде. Братья не должны предавать друг друга.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11416] = {title = "Глаза орлицы", objective = "Улклык поручил вам вырвать глаза великой орлицы. Вернитесь к нему в Вырубки, когда это задание будет выполнено.\n\nЕсли вы потеряете личину ворга, вернитесь к дозорной Лунный Лепесток, и она выдаст вам новую.", description = "Гарвал прячется под странным магическим покровом. Его невозможно увидеть, пока он сам этого не захочет. Но мы должны попытаться обойти эту защиту.\n\nГоворят, что мой старый враг, великая орлица Когтекрыл, может видеть сквозь любую магическую защиту. Если ты вырвешь ее глаза, то сможешь найти Гарвала.\n\nКогтекрыл свила гнездо у подножия водопада, к юго-западу от врайкульского поселения, которое называют Скорн. Если ты дотронешься до ее яиц, она спустится с небес, чтобы убить тебя. \n\nВырви ее глаза!", progress = "Ты принес глаза орлицы?", completion = "&lt;Улклык громко рычит, радуясь вашей победе над старым врагом.&gt;\n\nЭта победа делает тебе честь. Хотел бы я лично сомкнуть свои зубы на ее шее!\n\nНо ее смерть не должна стать напрасной. Скорее, съешь ее глаза!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11417] = {title = "Глаза орлицы", objective = "Улклык поручил вам вырвать глаза великой орлицы. Вернитесь к нему в Вырубки, когда это задание будет выполнено.\n\nЕсли вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.", description = "Гарвал прячется под странным магическим покровом. Его невозможно увидеть, пока он сам этого не захочет. Но мы должны попытаться обойти эту защиту.\n\nГоворят, что мой старый враг, великая орлица Когтекрыл, может видеть сквозь любую магическую пелену. Если ты вырвешь ее глаза, то сможешь найти Гарвала.\n\nКогтекрыл свила гнездо у подножия водопада, к юго-западу от врайкульского поселения, которое называют Скорн. Если ты дотронешься до ее кладки, она спустится с небес, чтобы убить тебя. \n\nВырви ее глаза!", progress = "Ты принес глаза орлицы?", completion = "&lt;Улклык громко рычит, радуясь вашей победе над старым врагом.&gt;\n\nЭта победа делает тебе честь. Хотел бы я лично сомкнуть свои зубы на ее шее!\n\nНо ее смерть не должна стать напрасной. Скорее, съешь ее глаза!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11418] = {title = "Мы зовем его Стальное Перо", objective = "Найдите Стальное Перо, который кружит над крепостью Вилдервар, и воспользуйтесь оперенным амулетом, чтобы разгадать тайну этого загадочного гиппогрифа. Расскажите Гилу Гризерту о вашей находке.", description = "Я как-то видел одного наглого гиппогрифа, который охотился прямо над крепостью. Джетан пытался его сбить, но стрелы буквально отскакивают от его оперения!\n\nМы так и прозвали его – Стальное Перо. Хотелось бы еще понять, почему он кружит рядом с крепостью Вилдервар. Ведь обычно гиппогрифы опасаются людей.\n\nИсследователь Адеран сделал для нас амулет из пера этого существа. Он утверждает, что с его помощью можно взглянуть на мир глазами гиппогрифа.", progress = "Ну, что? Амулет Адерана работает?", completion = "Ты видел гнездо с птенцами? Надо же! Значит, наша птичка женского рода!\n\nДа, это многое объясняет. Пожалуй, я не буду трогать целое гнездо с птенцами из-за такого неожиданного соседства. \n\n&lt;Гил одаривает зверолова Джетана насмешливым взглядом.&gt;\n\nДумаю, мы с ней славно поладим, если старина Джетан оставит свои попытки пополнить свой список трофеев.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11419] = {title = "Скаковые бараны Хмельного фестиваля", objective = "Покажите штамп Дризу Неуклюге у входа на территорию Хмельного фестиваля в Дуротаре.", description = "Если ты покажешь этот штамп Дризу Неуклюге, начинающему наезднику на баранах, он позволит тебе купить скакового барана на Хмельном фестивале.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][11420] = {title = "Путь к отмщению", objective = "Капитан стражи Зорек из Валгарда в Ревущем фьорде поручил вам вернуть руководство по управлению гарпунной пушкой.", description = "Две недели назад нашему главному инженеру удалось захватить врайкульскую гарпунную пушку. С помощью такого оружия эти мерзавцы топили наши корабли. Изучив ее, он смог составить подробное руководство по управлению этой штуковиной. \n\nК несчастью, его похитили и отвезли к северу отсюда, в Деревню Драконьего Черепа. Когда мы нашли его, едва живого, руководства при нем не оказалось. Из последних сил он поведал, что потерял свои записи в Катакомбах Утгард, находящихся к северо-западу от Деревни Драконьего Черепа. Ты <должен/должна> вернуть это руководство!", progress = "Ты нашел руководство?", completion = "&lt;Зорек листает руководство.&gt;\n\nХм, как интересно... \n\nСудя по этим записям, у врайкулов есть специальное приспособление, с помощью которого они могут нацеливать гарпунные пушки с убийственной точностью. Оно слегка напоминает штурвал наших кораблей. Оказывается, его можно переносить с одной пушки на другую. Мы должны раздобыть такое устройство!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11421] = {title = "До упора...", objective = "Лейтенант Ледяной Молот из Ревущего фьорда хочет, чтобы вы уничтожили большой дом Укротителей драконов, верфь Укротителей драконов, склад Укротителей драконов и 8 защитников из клана Укротителей драконов. Как только поручение будет выполнено, верните лейтенанту механизм управления гарпуном.", description = "Пока войска врайкулов пребывают в замешательстве, мы должны нанести удар! Отнеси этот механизм управления гарпуном в Ниффлвар и найди там самую северную гарпунную башню на обрыве.\n\nКак только окажешься внутри, возьми на себя управление одной из врайкульских гарпунных пушек, которые стоят на террасе. С ее помощью ты сотрешь с лица земли Деревню Драконьего Черепа! Уничтожь большой дом, верфь, склад и всех защитников, которых пошлют врайкулы, чтобы остановить тебя!\n\nТолько так мы сможем сделать Бухту Кинжалов более безопасным портом!", progress = "Надеюсь, ты пришел сказать мне, что Деревня Драконьего Черепа охвачена пламенем?", completion = "Прекрасно, Аркоман! Ты убил множество драконьих наездников и серьезно разозлила их предводителей. \n\nГотов вернуться в Валгард и сообщить хорошие новости Зореку? А то у меня появилась совершенно безумная идея!", rewards = "Рукавицы с морозными узорамиЛазурный плетеный хауберкУкрашенные рогами наплечникиВам дадут возможность выбрать одну из следующих наград:\n\nРуническое колье из раковины\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11422] = {title = "Трезубец сына", objective = "Старый Ледоспин просит вас принести ему трезубец Гниложабера. Он будет ждать вас на маленьком острове возле Берега Стылой Межи.", description = "<Он царапает на камне несколько символов, которые, очевидно, обозначают трезубец, мур'далака, разбившийся корабль и кусок сыра. Рядом с этими рисунками вы различаете грубое изображение самого себя.>\n\n<Вам не сразу удается понять, что хочет от вас старый мурлок. Очевидно, он просит принести ему трезубец с Берега Стылой Межи, но последнее изображение вас озадачивает. Наконец, вы понимаете, что мурлок имел в виду не кусок сыра, а своего сына.>\n\n<Все ясно! Видимо, его сына превратили в мур'далака! Он хочет, чтобы вы убили его и принесли трезубец.>", progress = "<Старый Ледоспин внимательно окидывает вас мутным взглядом. Очевидно, он ожидает увидеть в ваших руках трезубец его сына.>", completion = "&lt;Старый Ледоспин протягивает руку за трезубцем своего сына, и вы замечаете, что его пальцы слегка дрожат. Неужели этот дряхлый мурлок способен испытывать скорбь?&gt;\n\n&lt;Неужели вы видите скупые слезы в уголках его глаз – или это просто вода?&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11423] = {title = "Наследие врагов", objective = "Отправляйтесь к северу Заставы Призрачного Клинка, в Ниффлвар, и найдите три свитка: \"Сагу о проклятии зимы\", \"Сагу о валькириях\" и \"Сагу о близнецах\".", description = "Когда наши армии пройдут по Нордсколу, наши враги познают всю горечь поражения. Их дома будут сожжены, их тела будут разлагаться под воздействием нашей чумы, и сам след их существования будет стерт с лица земли. \n\nКак историк, я беспокоюсь лишь за сохранность знаний. Скоро наши войска из Лагеря Возмездия разрушат восточный город Ниффлвар. Я слышал, что этом городе жил врайкульский бард Хельгус, автор трех книг: \"Саги о близнецах\", \"Саги о проклятии зимы\" и \"Саги о валькириях\". Добудь эти произведения прежде, чем Ниффлвар будет разрушен.", progress = "Где же свитки, Посах? Ты их принес?", completion = "Эти свитки имеют огромное культурное значение, Посах. Я приложу все усилия к тому, чтобы сохранить и перевести на наш язык эти врайкульские произведения.\n\nТы только не пойми меня неправильно. Враг должен быть уничтожен... но древние знания надо сохранить.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11424] = {title = "Заградительный холм", objective = "Дженни по прозвищу \"Пила\" просит вас принести ей 5 древних врайкульских костей оживших мертвецов с Заградительного холма, который находится к югу от Нового Агамонда.", description = "Во время войны моя работа значительно упрощается – подходящие части тел валяются повсюду.\n\nПравда, их не так-то легко достать. Эти яйцеголовые болваны, изобретающие новые штаммы чумы и насылающие заразу на города противников, портят большую часть материалов.\n\nОднако я знаю место, где можно достать подходящие образцы. К югу отсюда есть Заградительный холм, на котором в древности врайкулы хоронили своих павших воинов. Чума не тронула эти земли – ни наша, ни Короля-лича. Принеси мне несколько костей, и я хорошо тебе заплачу за них.", progress = "Ну, где мои косточки?", completion = "Хммм... ладно, для начала сойдет. Странные какие-то эти кости.\n\nСкажу тебе начистоту – мне не раз приходилось держать в руках части тел, но ни разу до этого я не испытывала ничего подобного. Ладно; уговор есть уговор. Вот твоя награда.", rewards = "Перчатки прядильщицы пламениИнкрустированный холодным камнем воинский поясНаручи точного удараНаплечье из изумрудной чешуиВы получите:\n\n"}
MultiLanguageQuestData['ru'][11425] = {title = "Тестовое задание – Крейг", objective = "Паразиты, ненавижу!", description = "Ступай выполнять задание!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11426] = {title = "В поисках механизма", objective = "Капитан стражи Зорек из Валгарда в Ревущем фьорде просит вас принести механизм управления гарпуном.", description = "Не волнуйся, <имя>, нас ждет нечто потрясающее! НЕВЕРОЯТНОЕ! Ты просто слушай меня и делай так, как я тебе скажу. \n\nСначала нам надо достать механизм, упомянутый в этом руководстве. Сдается мне, что ты с легкостью обнаружишь его у одного из врайкулов, которые управляют гарпунными пушками в Деревне Драконьего Черепа. Эти пушки стоят в восточной части деревни, на террасах больших домов.", progress = "Ты нашел устройство?", completion = "Потрясающе! Скоро эти макаки-переростки поплатятся за то, что встали на пути Альянса!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11427] = {title = "Познакомьтесь с лейтенантом Ледяным Молотом", objective = "Капитан стражи Зорек просит вас отнести механизм управления гарпуном лейтенанту Ледяному Молоту, который укрывается недалеко от Ниффлвара.", description = "Видишь эти врайкульские постройки на северо-восточных склонах? Сами врайкулы называют это место Ниффлвар. Оттуда они обстреливают гарпунами наши фрегаты.\n\nЗнаешь, что? Нам это надоело, <имя>. Возьми этот механизм управления гарпуном и встреться с лейтенантом Ледяным Молотом, который прячется в одной из врайкульских хижин на северо-западе Ниффлвара.\n\nКогда будешь <готов/готова>, я посажу тебя на грифона и отправлю тебя прямо к нему!", progress = "Это еще зачем? Я что, похож на няньку?", completion = "&lt;Лейтенант Ледяной Молот забирает у вас механизм управления гарпуном.&gt;\n\nА, подарочки!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11428] = {title = "Хранитель Листопад", objective = "Луриэль с Заиндевевшей поляны просит вас убить Хранителя Листопада.", description = "<имя>, ты <стал нам добрым другом и верным союзником/стала нам доброй подругой и верной союзницей>. Поэтому я хочу обратиться к тебе еще с одной просьбой.\n\nТы собственными глазами <видел/видела> то, что случилось с Холмистой поляной, и какие жуткие твари населяют эти некогда мирные земли. Негодующие хранители не прекращают приманивать этих чудовищ, и вскоре они заполонят все земли и воды – если только мы не сможем им помешать.\n\nСамого могущественного негодующего хранителя зовут Хранитель Листопад. Убей его, <имя>, и дай этим землям шанс возродиться во всей былой красе.", progress = "Ты избавил Холмистую поляну от Хранителя Листопада?", completion = "Сердце мое обливается кровью, когда я думаю о несчастных хранителях, обративших свое оружие против нас. А ведь когда-то мы считали их братьями и самыми близкими друзьями!\n\nЯ оплакиваю братьев и сестер, которых мы потеряли, но твоя поддержка дает нам надежду на будущее. Отныне ты всегда желанный гость в наших землях, Reng.", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11429] = {title = "Защищай знамя до последнего!", objective = "Лейтенант Ледяной Молот из Ревущего фьорда хочет, чтобы вы закрепили Знамя Альянса в Гибльхейме и защищали его от нападающих.\n\nЕсли вам удастся выжить в этом испытании, верните знамя лейтенанту Ледяному Молоту.", description = "Я не собираюсь доверять столь ответственное задание непроверенным людям.\n\nЕсли хочешь доказать мне, что ты обладаешь необходимыми качествами для выполнения этой миссии, делай так, как я тебе велю.\n\nВозьми это знамя и отправляйся в Гибльхейм, который находится на севере отсюда. Как только прибудешь на место, найди центр города и установи там этот флаг. Сразись с любым врайкулом, который осмелится прикоснуться к нашему великому знамени, после чего доложи мне о победе Альянса!", progress = "Ты смотри, на тебе ни царапинки. Можно подумать, ты ни с кем не сражался!", completion = "Слава Альянсу! А ты не робкого десятка, Аркоман. Пожалуй, тебе хватит силенок, чтобы раскрошить парочку врайкульских черепов в Ниффлваре.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11430] = {title = "Мастер-гарпунщик Явус", objective = "Лейтенант Ледяной Молот из Ревущего фьорда поручил вам убить мастера-гарпунщика Явуса в Ниффлваре.", description = "Ты хорошо <проявил/проявила> себя в Гибльхейме, <имя>. Но прежде, чем ты начнешь задирать нос, я хочу поручить тебе настоящее задание в Ниффлваре.\n\nМы обнаружили врайкула, обстреливающего наши фрегаты из гарпунной пушки. Зовут этого мерзавца Явус. Его легко найти на главной гарпунной станции, выстроенной на склонах Ниффлвара к юго-востоку отсюда.\n\nВыследи его и накажи за все преступления, совершенные им против Альянса!\n\nНе подведи меня, <имя>!", progress = nil, completion = "Им понадобится какое-то время, чтобы найти Явусу замену. Самое время осуществить план Зорека! Пока они будут пытаться вышвырнуть нас из Ниффлвара, ты обратишь их гарпунные пушки против них самих!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11431] = {title = "Поймать дикого зайцелопа!", objective = "\"Дворф\", Глодрак Меткий Охотник попросил вас поймать 5 оглушенных диких зайцелопов с помощью особой сети. Он намекнул, что необходимо достичь состояния сильного алкогольного опьянения – или хотя бы надеть Синтехмельные очки.", description = "Эй ты! Я ненормальный дворф! Мы, дворфы, считаем, что если принять хорошенько в доброй компании, увидишь много интересного. И невидимого – пока ты трезвый. Небось, эти твари бродят по территории Хмельного фестиваля, а мы и знать не знаем! Они заметны только спьяну.\n\nНам, дворфам, любые поводы выпить хороши.\n\nТы ведь тоже от повода не откажешься? Ну вот, поймай в эту сеть 5 зайцелопов. Сеть мне дал один си-ильно напившийся дворф.\n\nА если ты не видишь зайцелопов, значит, надо еще выпить. Или хотя бы надеть Синтехмельные очки – у меня как раз есть парочка.", progress = "Ты несешь мне товар или ищешь повод напиться?", completion = "Что?! Они существуют! Как мне стыдно, ведь я пнул того дворфа...\n\nМинутку... Надо выпить...\n\n*Он делает долгий глоток из кружки.*\n\nПожалуй, можешь оставить себе одного... Надо доказать, что пьяные дворфы (а другие бывают?) говорят правду!", rewards = "Вы получите:\n\nКружка зайцелопа"}
MultiLanguageQuestData['ru'][11432] = {title = "Спящие великаны", objective = "Маг-лейтенант Малистер поручил вам уничтожить 5 спящих врайкулов. Когда задание будет выполнено, вернитесь к нему в Крепость Западной стражи.", description = "Я случайно услышал твой разговор с отцом Левариолом. Смею предположить, он не позволил тебе предпринять решительные действия.\n\nНо ты <должен/должна> уничтожить врайкулов, спящих в глубине чертогов Пробуждения под Гьялерброном!\n\nЯ не сомневаюсь, что ритуалы, в которых они должны принять участие, могут иметь ужасные последствия! Скорее всего, у некролордов есть некое устройство, позволяющее пробудить их на время.\n\nУничтожь спящих – и врайкулы никогда оправятся от таких потерь.", progress = nil, completion = "Ты сделал то, что должен был сделать. Хотя многие сочтут убийство беспомощных врайкулов бесчестным поступком, в нашем положении это был единственно верный выход.\n\nМы ведь не могли позволить, чтобы их пробудили в ходе неких ужасных ритуалов, верно?\n\nПоэтому ты можешь гордиться своей смелостью, Reng.", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11433] = {title = "Спящие великаны", objective = "Ахота Белый Иней поручил вам уничтожить 5 спящих врайкулов. Когда задание будет выполнено, вернитесь к нему в Лагерь Заиндевевшего Копыта.", description = "Я случайно услышал твой разговор с Великой Матерью Анкхой. Смею предположить, она не позволила тебе предпринять решительные действия.\n\nНо ты <должен/должна> уничтожить врайкулов, спящих в глубине чертогов Пробуждения под Гьялерброном!\n\nЯ не сомневаюсь, что ритуалы, в которых они должны принять участие, могут иметь ужасные последствия! Скорее всего, у некролордов есть некое устройство, позволяющее пробудить их на время.\n\nУничтожь спящих – и врайкулы никогда не оправятся от таких потерь.", progress = nil, completion = "Ты сделал то, что должен был сделать. Хотя многие сочтут убийство беспомощных врайкулов бесчестным поступком, в нашем положении это был единственно верный выход.\n\nМы ведь не могли позволить, чтобы их пробудили в ходе неких ужасных ритуалов, верно?\n\nПоэтому ты можешь гордиться своей смелостью, Расул.", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11434] = {title = "Забытое сокровище", objective = "Красавчик Терри из Лагеря Скалаваг просит вас достать аманийскую вазу и статуэтку орла с места кораблекрушения на юге.", description = "Я сколотил целое состояние на сокровищах, которыми не интересуются обычные пираты – предметы искусства, картины, антиквариат. \n\nНесколько лет назад к югу отсюда затонул флот Блэка Конрада. Ныряльщики давно уже растащили все золото и драгоценности, но два древних сокровища так и остались лежать на дне моря. Одно из них – аманийская ваза, музейная редкость, а второе – статуэтка орла. \n\nДобудь эти ценности, и я замолвлю за тебя словечко перед остальными пиратами. Я даже подброшу кое-что звонкое, чтобы твое морское приключение стало для тебя не только увлекательным, но и прибыльным.", progress = "Ты принес мои сокровища, Reng? Ничто в этой жизни не дается просто так, за красивые глаза... даже мне!", completion = "Определенно, нам стоит провернуть какое-нибудь дельце, Reng. С моей внешностью и твоей... предприимчивостью мы непременно сорвем куш.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11435] = {title = "Gathered Pumpkins NYI", objective = "Возьмите тыквы и переодетой попечительнице сирот.", description = "Привет, <имя>! Спасибо, что <прогнал/прогнала> Всадника! Теперь попечительница говорит, что нам можно побегать по деревне!\n\nМы тут нашли тыквы, что Всадник побросал. Страшные такие... Может, возьмешь и покажешь нашей попечительнице?", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][11436] = {title = "Полетаем?", objective = "Воспользуйтесь большой врайкульской пушкой в Ниффлваре и запустите себя в Валгард. Доложите о победе над врайкулами капитану стражи Зореку.", description = "Как же нелегко путешествовать по крутым обрывам Ревущего фьорда! К счастью, мне пришла в голову идея, как облегчить эту задачу. Мое устройство сочетает в себе врайкульскую технологию и дворфийскую гениальность. Тут подкрутить, здесь припаять – и вот, позвольте продемонстрировать пульт управления гарпуном имени Ледяного Молота! Конечно, я его еще не испытывал, но ты вполне с этим справишься!\n\nОтнеси эту штуку к большой пушке в Ниффлваре и отправь себя в Валгард. Доложи о своем успехе Зореку. Кстати, пульт управления можешь оставить себе!", progress = nil, completion = "Ты что, совсем с ума сошел, Reng? Только полный идиот может выстрелить собой из гарпунной пушки, чтобы таким образом добраться до места назначения!\n\nНо, я полагаю, надо быть слега сумасшедшим, чтобы так сражаться на обрывах фьорда! Потрясающе! Мне доложили, что Ингвар, предводитель Укротителей драконов, в ярости от твоей выходки! Возможно, однажды именно тебе удастся втоптать его в грязь во славу Альянса!", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11439] = {title = "Учения пожарной бригады", objective = "Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.", description = "Отважные дворфы Караноса готовы в один момент сформировать пожарную бригаду, раз поблизости Всадник без головы. Не хотите ли помочь?\n\nК югу отсюда горные пехотинцы устроили небольшой полигон для учений пожарных бригад. Идите туда и носите ведрами воду, чтобы тушить пожар. Воду можно черпать ведром из этих бочек с водой.\n\nУдачи, <имя>. Когда поучаствуете в учениях пожарной бригады, возвращайтесь к нам!", progress = nil, completion = "Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!\n\nОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!", rewards = "Вы получите:\n\nТыквовинская конфета"}
MultiLanguageQuestData['ru'][11440] = {title = "Учения пожарной бригады", objective = "Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.", description = "Пока остается угроза нападений Всадника без головы, миротворцам придется сформировать там, где необходимо, пожарные бригады. Не хотите ли помочь?\n\nК западу отсюда, в направлении Экзодара, миротворцы организовали небольшой полигон для учений пожарных бригад. Отправляйтесь туда и упражняйтесь в тушении пожаров. Воду можете набирать из бочек прямо здесь.\n\nДо свидания, <имя>. Когда закончите учения, пожалуйста, возвращайтесь к нам!", progress = nil, completion = "Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!\n\nОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!", rewards = "Вы получите:\n\nТыквовинская конфета"}
MultiLanguageQuestData['ru'][11441] = {title = "Хмельной фестиваль!", objective = "Поговорите с распорядителем Хмельного фестиваля.", description = "Поговорите с распорядителем Хмельного фестиваля на территории Хмельного фестиваля рядом со Стальгорном и получите бесплатное пиво.", progress = nil, completion = "Хо-хо! Думаешь, бесплатное пиво вкуснее?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЯчменоварское прозрачноеГром 45Грог Гордока\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11442] = {title = "Добро пожаловать на Хмельной фестиваль!", objective = "[PH] Speak to the Brewfest Organizer and receive a free beer.", description = "[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", progress = nil, completion = "Хо-хо! Думаешь, бесплатное пиво вкуснее?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЯчменоварское прозрачноеГром 45Грог Гордока\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11443] = {title = "Подводное плавание в Бухте Кинжалов", objective = "Гарольд Лаграс из Бухты Кинжалов попросил вас найти 10 валгардских ящиков с припасами.", description = "Эй... ээ... Привет! А ты что тут делаешь?\n\nКто, я? А... Ну, понимаешь... Я... типа... обчищаю... ээ... Очищаю тут от обломков, вот что! Мне Келлер поручил! Ей-богу, так и сказал: \"Гарри, я хочу, чтобы ты надел водолазный шлем и поискал наши вещички среди обломков кораблей в Бухте Кинжала...\"\n\nНо я, если что, не откажусь от твоей помощи. Здесь, в бухте, полно всяких ценностей... то есть припасов. Так что, давай, тащи все, что найдешь мне. Только не забудь водолазный шлем – иначе задохнешься и умрешь!", progress = "Ну, где припасы?", completion = "Ух ты! Хорошо работаешь. Ага, давай-ка сюда эти ящички. Я их внесу в ведомость, перепишу содержимое и займусь всякой прочей бюрократией, которой ты наверняка не обучен. Не волнуйся, я непременно расскажу Келлеру, как ты мне помог! Честное слово. Так что... это... Можешь идти! Ну давай уже, проваливай!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11446] = {title = "Хмельной фестиваль!", objective = "Поговорите с распорядителем Хмельного фестиваля.", description = "Поговорите с распорядителем Хмельного фестиваля на территории Хмельного фестиваля рядом с Оргриммаром и получите бесплатное пиво.", progress = nil, completion = "Что?! Бесплатное пиво? Да, да. Кажется, мы обещали нечто подобное.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГрог ГордокаОтвар \"Не спеша\"Речная вода из джунглей\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11447] = {title = "Добро пожаловать на Хмельной фестиваль!", objective = "[PH] Speak to the Brewfest Organizer and receive a free beer.", description = "[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", progress = nil, completion = "Что?! Бесплатное пиво? Да, да. Кажется, мы обещали нечто подобное.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГрог ГордокаОтвар \"Не спеша\"Речная вода из джунглей\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11448] = {title = "Лагерь Лиги исследователей", objective = "Отвезите сверток Максорфа Станваду в Лагерь Лиги исследователей в Ревущем фьорде.", description = "Чепуха какая-то! Даже применив шифр, я не могу разобрать, с какой стороны держать эту табличку. Надо признать, криптография никогда не была моей сильной стороной. \n\nОтнеси таблички вместе с шифром нашему криптографу, Станваду. К несчастью, я давно уже не получал от него никаких известий. Две недели назад он взял с собой группу из двадцати ученых и отправился на раскопки у юго-восточных обрывов фьорда. С тех пор о нем ничего не слышно. Остается только поручить МакГоуверу подвезти тебя на его ветролете.", progress = "<Станвад недовольно ворчит.>", completion = "&lt;Станвад берет у вас сверток и начинает сортировать таблички.&gt;\n\nОго. Сколько, говоришь, людей погибло ради этой информации?\n\n&lt;Станвад качает головой.&gt;\n\nПолагаю, ты будешь счастлив узнать, что Максорф и его команда слюнявых имбецилов обнаружили рецепт древней тундровой похлебки. Он что, не заметил этот значок, обозначающий овощи, и изображение человеческого рта над вышеупомянутой растительностью? Чтобы понять смысл этих надписей, не нужен никакой шифр!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11449] = {title = "Учения пожарной бригады", objective = "Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Брилле.", description = "Ловчие смерти устроили учебный полигон за стенами города. Мы не можем допустить, чтобы дома Брилла продолжали гореть. Выполняйте свой долг и ступайте на учения пожарной бригады.\n\nИдите по дороге на запад мимо кладбища. Там увидите полигон.", progress = nil, completion = "Отлично, Мелькордарк. Дети, посмотрите на этого |3-6(Маг). Да будет он вам примером!", rewards = "Вы получите:\n\nТыквовинская конфета"}
MultiLanguageQuestData['ru'][11450] = {title = "Учения пожарной бригады", objective = "Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске на Площади Соколиных Крыльев.", description = "Стража устроила полигон для учений пожарных бригад за стенами города. Мы не дадим Всаднику разрушить все, что мы с таким трудом восстанавливали. Исполняйте ваш долг и примите участие в учениях пожарной бригады.\n\nСтупайте за ворота на юг и идите до перекрестка. Там найдете учебный полигон.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТыквовинская конфета"}
MultiLanguageQuestData['ru'][11451] = {title = "Стишок Алисии", objective = "Вас попросили отнести стишок Алисии Кайли Дак в Шаттрат в Запределье.", description = "Привет, я тут написала стишок для моей подружки Кайли. Она любит гостить у Алдоров в Шаттрате. Ну, в Запределье, ты же знаешь?\n\nТы не отнесешь ей мои стишки? Моя мамочка говорит, что я еще слишком маленькая, чтобы ходить в Шаттрат!", progress = "Ой, стишок?", completion = "Какой трогательный стишок, спасибо!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11452] = {title = "Спящий король", objective = "Убейте королеву Ангербоду и прервите ритуал пробуждения короля Имирона. Если вам удастся сделать это, вернитесь в Крепость Западной Стражи и доложите о своей победе капитану Адамсу.", description = "Из мертвой руки некровладыки падает листок пергамента, на котором описан процесс одного из ритуалов, проходящих в подземных катакомбах. \n\nИз этого свитка вы узнаете, что королева врайкулов, Ангербода, пытается пробудить короля Имирона. Ритуал проводится в огромной палате, известной как Зимняя терраса. Она находится на севере Гьялерброна.\n\nЕсли вы поспешите, то, возможно, успеете остановить Ангербоду до того, как будет слишком поздно.", progress = nil, completion = "Не нравится мне все это! Если Король-лич объединится с Имироном, это принесет нам одни неприятности. Какая жалость, что ты не прикончил его вместе с королевой.\n\nНо все же, тебе удалось значительно нарушить их планы, тем самым выиграв для нас время.\n\nКто знает – возможно, ты еще скрестишь клинки с королем Имироном. Могу поспорить, вашей следующей встречи он не переживет.", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11453] = {title = "Спящий король", objective = "Убейте королеву Ангербоду и прервите ритуал пробуждения короля Имирона. Если вам удастся сделать это, вернитесь в Лагерь Заиндевевшего Копыта и сообщите о своей победе вождю Прахтотему.", description = "Из мертвой руки некровладыки падает листок пергамента, на котором описан процесс одного из ритуалов, проходящих в подземных катакомбах. \n\nИз этого свитка вы узнаете, что королева врайкулов, Ангербода, пытается пробудить короля Имирона. Ритуал проводится в огромной палате, известной как Зимняя терраса. Она находится на севере Гьялерброна.\n\nЕсли вы поспешите, то, возможно, успеете остановить Ангерброду до того, как будет слишком поздно.", progress = nil, completion = "Не нравится мне все это! Если Король-лич объединится с Имироном, это принесет нам одни неприятности. Какая жалость, что ты не прикончил его вместе с королевой.\n\nНо все же, тебе удалось значительно нарушить их планы, тем самым выиграв для нас время.\n\nКто знает – возможно, ты еще скрестишь клинки с королем Имироном. Могу поспорить, вашей следующей встречи он не переживет.", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11454] = {title = "Поиски диверсантов", objective = "Найдите Худовара в \"Угрюмом обжоре\" в Глубинах Черной горы.Похоже, этот листок бумаги случайно оставили захватчики Черного Железа.\n\nХотя планы очень непростые и записаны особым дворфийским кодом, подпись в самом конце – \"Корен Худовар\" – разобрать легко. Упоминание \"Угрюмого Обжоры\" из Глубин Черной горы тоже. Найди виновника этого безобразия и положи конец набегам.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Похоже, этот листок бумаги случайно оставили захватчики Черного Железа.\n\nХотя планы очень непростые и записаны особым дворфийским кодом, подпись в самом конце – \"Корен Худовар\" – разобрать легко. Упоминание \"Угрюмого Обжоры\" из Глубин Черной горы тоже. Найди виновника этого безобразия и положи конец набегам.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11455] = {title = "Запах денег", objective = "Красавчик Терри из Лагеря Скалаваг в Ревущем фьорде просит вас добыть 4 мускусные железы бешеных бурых медведей, которые бродят по всему острову.", description = "Мы, пираты, много что любим – ром и золото, паруса и мачты – но порядок и чистота не входят в этот список! На многих пиратских кораблях плавает в пять раз больше крыс, чем членов команды.\n\nНе удивительно, что все медведи на острове подхватили бешенство! Короче говоря, босс хочет от них избавиться.\n\nА тут еще такое дело... попал мне однажды в руки рецептик духов, за которые любая штормградская модница отдаст кошелек и поцелуй в придачу. И знаешь, какой ингредиент стоит там на первом месте? Медвежий мускус! Тебе не кажется, что на этом можно хорошо заработать?", progress = "Ты ведь несешь мне мускусные железы, правда?", completion = "Ай, молодчина! Может быть, это не столь захватывающе, как грабить корабли, но я буду последней сухопутной крысой, если упущу возможность обогатиться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11456] = {title = "Мясо для выживших", objective = "Предок Атуик из Камагуа в Ревущем фьорде просит вас принести 6 кусков мяса островного черпорога с Острова Копий.", description = "Мы, клыкарры, живем в основном за счет рыбной ловли. Однако во времена большой нужды мы не гнушаемся охотой на животных. \n\nНедавно на близлежащую деревню Искаал напали пираты, и с тех пор оттуда не иссякает поток беженцев.\n\nНа этой неделе наш улов был скромен, но на острове полно черпорогов, чье мясо очень питательно.\n\nПожалуйста, помоги моим людям охотиться на этих огромных животных и принеси мне как можно больше мяса.", progress = "Ты принес нам мясо?", completion = "Благодарю тебя, Аркоман. Сейчас мои люди во многом нуждаются.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11457] = {title = "Вооружая Камагуа", objective = "Старейшина Атуик просит вас добыть 3 рога химеры.", description = "Мой народ изображает Иссилрука, духа войны, в виде серебряного орла. Легенды гласят, будто однажды Иссилрук сражался с сотней воргов, чтобы спасти своего детеныша.\n\nТеперь и нам пора вступить в бой с врагами, чтобы защитить наших братьев. Но нам нужно новое оружие. Острые рога ледокрылых химер, что обитают на заснеженных частях острова, легко превратить в наконечники копий. Принеси мне самые лучшие рога, которые тебе только удастся добыть.", progress = "Я рад видеть тебя снова, |3-6(таурен).", completion = "Ты невероятно ценный союзник, Расул. Мы никогда не забудем то, что ты для нас сделал.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11458] = {title = "Месть за Искаал", objective = "Старейшина Атуик просит вас отправиться в Искаал и убить 8 поработителей – пиратов Северных морей. Если вам понадобится помощь, воспользуйтесь Рогом Камагуа.", description = "Тотем Иссилрука готов, <имя>, и я благодарю тебя за помощь в его изготовлении. В эти тревожные времена мы должны забыть о мирном пути и сразиться с теми, кто посягнул на наши земли и поднял руку на наш народ. \n\nПираты-работорговцы, совершившие налет на Искаал, сошли с ума и убили всех пленных. Отправляйся на восток, в Искаал, и выполни свой долг. Возьми с собой этот рог и призови на помощь моих братьев.", progress = "Ты выполнил мою просьбу, Баронгеддон?", completion = "Хорошо, что ты на нашей стороне, Заракир. Мой народ в долгу у тебя.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11459] = {title = "Что сказал Зех'ген", objective = "Вернитесь к Красавчику Терри и попросите объяснить, что хотел от вас Зех'ген.", description = "Трави концы, друг. Значит хочешь, чтобы я гарпунул ту скользкую салаку, которая вильнула меж лап нашей братвы?\n\nТогда тащи мне квакуху, морячок. Потом я подсеку тебе эту тухлятину. Не, не, квакуха подсечет. Сам узыришь, своими маяками, тутжещас.\n\nДа, и не забудь жилорезку, сухоход. Дуй по курсу, чайник.", progress = nil, completion = "Говоришь, ты ничего не понял из того, что сказал Зех'ген? Не удивительно.\n\nНу-ка, посмотрим...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11460] = {title = "Завоевание доверия", objective = "Идальго из Лагеря Лиги исследователей в Ревущем фьорде послал вас найти червяка фьорда и скормить его одному из соколов в клетке, стоящей у его ног.", description = "Прежде всего сокольничий должен установить связь между собой и своей птицей, завоевать ее доверие. \n\n<Идальго указывает на соколов в клетке, стоящей у его ног.>\n\nЕсли хочешь, чтобы птицы тебе доверяли – накорми их до отвала!\n\nКак тебе, должно быть, известно, скальные соколы фьорда питаются в основном червяками. По всему фьорду легко можно найти расшатанные камни, под которыми обитает множество личинок. Найди червячка и накорми им сокола в клетке.", progress = "Это очень важное упражнение, Моджичек. Если хочешь стать сокольничим – сначала научись правильно кормить птиц.", completion = "Да, Reng. Я уже чувствую дружескую связь между тобой и птицей. Она признала тебя хозяином.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11461] = {title = "ИСКЛЮЧЕНО", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][11464] = {title = "Карточный долг", objective = "Тарук из Лагеря Скалаваг просит вас взыскать долг Гарри \"Луносвета\".", description = "Говорят, ты работаешь на Терри. Я, признаться, ожидал увидеть кого-нибудь более благонадежного.\n\nВидишь ли, пираты обожают азартные игры. Правда, потом они очень не любят расплачиваться по долгам.\n\nЕсли ты не против стрясти кое с кого парочку звонких монет, то я с удовольствием отсыплю тебе твою долю.\n\nНачнем с чего-нибудь попроще – скажем, с Гарри \"Луносвета\". Эксцентричный парень, обожает всякие эльфийские побрякушки – но стоит ему увидеть меня, как он сразу прикидывается нищим и обделенным. Вытряси из него мое золото!", progress = "А, ты вернулся. Ну что, где мое золото?", completion = "Молодец, ты отлично справился. Вот твоя доля, Reng. Ты можешь заработать еще больше – на этом острове еще полно должников.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11465] = {title = "Разграбленный караван", objective = "Идальго из Лагеря Лиги исследователей в Ревущем Фьорде попросил вас поймать 5 индюков фьорда с помощью обученного скального сокола. \n\nКак только поручение будет выполнено, верните клетку сокольничему.", description = "Я вел караван из Валгарда, когда на нас напали Укротители драконов. Выжить удалось только мне. К несчастью, я не смог довезти свой груз фьордовых индеек, но для тебя это будет легкой прогулкой!\n\n<Идальго протягивает вам клетку.>\n\nВот, возьми моего скального сокола и отправляйся на запад по дороге, ведущей из лагеря. Пусть сокол поймает сбежавших индеек, а ты принесешь их мне. \n\nТолько не забудь его покормить!", progress = "Всегда корми сокола до отвала перед охотой – иначе он съест всю добычу!", completion = "Хитрые мерзавцы! Но какие терпеливые! Мы должны перестать недооценивать нашего противника. Эти врайкулы – безжалостные убийцы!\n\nВпрочем, как бы то ни было, мы свое дело сделали. А тебе пора поохотиться на более ловкую дичь. Толстый индюк – разве это дело?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #5\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11466] = {title = "Стаканчик для Джека", objective = "Тарук из Лагеря Скалаваг просит вас взыскать долг Джека Адамса.", description = "Наш следующий клиент, Джек Адамс, не такой простак, как Гарри. Он целыми днями выпивает в компании своих дружков – матерых пиратов. Силой тут действовать нельзя – можно пострадать. \n\nДавай лучше воспользуемся его пристрастием к бутылке. Рано или поздно он напьется так, что уже не сможет стоять на ногах. \n\nПоговори с девочками за стойкой – может быть, кто-нибудь из них тебе поможет. Как только он отрубится, запусти руку в его карман и забери то, что принадлежит мне.", progress = "Ты забрал то, что принадлежит мне?", completion = "Я поражен твоим успехам, Reng. А меня, знаешь ли, не так-то легко поразить.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11467] = {title = "Долг мертвеца", objective = "Тарук из Лагеря Скалаваг просит вас выкопать сокровище Блэка Конрада с северо-восточного побережья острова Копий, что к северу от Искаала.", description = "<Слышал/Слышала> о Блэке Конраде? Он, пожалуй, самый знаменитый пират в наших краях.\n\nТак вот; повадился он делать ставки на моих боях, а потом не платить за проигрыш.\n\nХотел бы я стрясти с него должок, да вот только этот подлец взял и помер.\n\nЯ уж было забыл про это дельце, как вдруг мне в руки попала занятная штучка...\n\n<Тарук разворачивает карту острова Копий, помеченную крестиком на северо-восточном плато.>\n\nВидишь, какие дела? Этот забулдыга зарыл целый клад на земле клыкарров. Достань мне это сокровище! Смерть – еще не повод не возвращать мне долги!", progress = "Ты нашел сокровище, Транделар?", completion = "Конрад задолжал мне только золото – его-то я и заберу. Остальное можешь оставить себе.\n\nКстати, если тебе вдруг захочется подзаработать, обращайся ко мне. Пожалуй, я смогу найти для тебя дельце. Попутного тебе ветра, дружище!", rewards = "Вы получите:\n\nСокровище Блэка КонрадаПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11468] = {title = "Ястреб против сокола", objective = "Идальго из Лагеря Лиги исследователей в Ревущем фьорде просит вас поймать 10 ястребов фьорда с помощью вашего обученного скального сокола.\n\nКогда вы выполните это задание, верните Идальго клетку с соколом.", description = "Ты это чувствуешь, <имя>? Сейчас ты уже <должен/должна> ощутить связь между собой и твоим соколом. Поверишь ли ты мне, если я скажу, что однажды ты сможешь взглянуть на мир глазами своей птицы? Да, это высшее мастерство, доступное лишь лучшим сокольничим. \n\nЧтобы достичь таких высот в нашем ремесле, надо много и упорно трудиться! Птица должна охотиться, оттачивать навыки и рефлексы. Выбери для нее более достойного противника! Скажем, ястребов фьорда, которые гнездятся на верхушках деревьев. Пусть они станут твоей следующей добычей!", progress = "Всегда корми сокола до отвала перед охотой – иначе он съест всю добычу!", completion = "Да, ястребы очень ревностно относятся к защите территорий и часто гнездятся большими стаями. Пожалуй, мне следовало предупредить тебя заранее.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11469] = {title = "Мыло для чистки палуб", objective = "Побегушка Мерзлонос просит вас принести ей сальник Большого Роя, чтобы она могла сварить из него мыло для чистки палуб. Она ждет вас на восточном пиратском корабле в Лагере Скалаваг.", description = "Ага, мне надо надраить палубу до того, как прибудет Безумный Иона. Только я не собираюсь ползать тут на четвереньках! \n\nУ меня, знаешь ли, мыло закончилось. Только это не моя проблема, а твоя, дружище. Ты у нас салага – так что тебе и бегать за припасами. \n\nНа северо-западном побережье острова полным-полно морских львов. Там, среди льдов, ты найдешь главного тюлева, Большого Роя. Принеси мне его сальник, и я сварганю нам лучшее мыло!", progress = "Где сальник? Только не говори, что ты его не нашел.\n\nЭтот Большой Рой такой жиртрест, что море должно выходить из берегов, когда он взмахивает плавником!", completion = "Фу, какой мерзкий запах!\n\nДавай, клади сюда эту штуку. Сейчас я произнесу нужное заклинание – и мыло появится само собой!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11470] = {title = "Птицы не знают о чести", objective = "Идальго из Лагеря Лиги исследователей в Ревущем фьорде поручил вам выкрасть восемь яиц ястреба фьорда с помощью вашего обученного скального сокола.\n\nКогда вы выполните задание, верните Идальго клетку с соколом.", description = "Думаю, ты уже <готов/готова> перейти на следующую ступень обучения соколиной охоте. \n\nОтнеси своего обученного сокола на восток, к Подъемнику Каменной стены, где гнездятся врайкульские ястребы. Они вьют гнезда в отдаленных расщелинах на обрыве. Найди, где они селятся, и поручи своему соколу украсть яйца из их гнезд.\n\nТолько остерегайся ястреба-матриарха фьорда. <имя>. Если она нападет на тебя, прикажи соколу подняться ввысь и беги!", progress = "Ты хозяин сокола, Reng. Пошли его на добычу яиц.", completion = "Молодец, Reng! Браво! Ты чувствуешь, как окрепли узы, связывающие тебя с соколом? Возможно, вскоре мы сможем посылать вас на разведку врайкульских территорий!", rewards = "Мундир очищения огнемСапоги из мягкой кожиРемень неизбежностиВыкованный светом нагрудный доспехВы получите:\n\n"}
MultiLanguageQuestData['ru'][11471] = {title = "Конец игры", objective = "Энни Бонн из Лагеря Скалаваг хочет, чтобы вы принесли ей подзорную трубу Ионы Стерлинга.", description = "Я знаю, зачем ты <пришел/пришла> сюда, <имя>. Тебя послали убить нашего предводителя, Иону Стерлинга.\n\nЯ хочу помочь тебе. Боюсь, под руководством Ионы вся наша операция провалится.\n\nНе понимаю, зачем нападать на флотилии Орды и Альянса одновременно? Это же самоубийство. А пытаться продавать пленных клыкарр, хотя на чужбине они умирают через несколько дней? Безумие какое-то.\n\nИона прячется в пещере к западу отсюда. Принеси мне подзорную трубу в доказательство его смерти – и я лично распоряжусь, чтобы нападения на твоих союзников прекратились.", progress = "Итак, Фризстайлз. Ты принес мне подзорную трубу Ионы?\n\nИзвини, я не могу поверить тебе на слово. Я же все-таки пиратка!", completion = "Наконец-то Иона Стерлинг сыграл в ящик! Эх, не предполагал он, что с ним разделается \"какая-то девка\"!\n\nКак только весть о смерти Ионы распространится среди пиратов, я возьму власть в свои руки. И я сдержу слово – мои люди больше не станут нападать на твоих союзников.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nУдарная волнаОберег морского узлаКарманные часы первого помощника\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11472] = {title = "Путь к его сердцу...", objective = "Подкиньте несколько вкусных рифовых рыб рифовому буйволу, чтобы он последовал за вами к рифовой корове. Когда эти двое одиноких сердец найдут друг друга, вернитесь к Ануниаку в Камагуа.", description = "Пираты Cеверного моря убили вожака стаи рифовых буйволов, потому что им нужен был жир для варки мыла!\n\n<Ануниак грустно вздыхает.>\n\nТеперь морские львы не смогут размножаться. Помоги мне восстановить их численность.\n\nНа северном побережье Рифа Гарвана, что на юго-востоке отсюда, водится в изобилии рифовая смакрель. Поймай дюжину вкусных рыбин на восточных и западных берегах острова и подмани одного из буйволов прямо к рифовой корове.\n\nПоймать этих мальков просто – тебе даже не понадобится удочка.", progress = nil, completion = "Это замечательно! За этим буйволом последуют другие самцы, и вскоре в наших водах будут плавать маленькие морские львята!\n\nСпасибо, дорогой |3-6(нежить). Этим поступком ты искупил все злодеяния, совершенные тобой в прошлом.\n\nНо мы должны позаботиться о том, чтобы наши труды принесли плоды. Приходи ко мне завтра – возможно, нам удастся приманить еще одного буйвола.", rewards = "Вы получите:\n\nПредмет #250Предмет #1"}
MultiLanguageQuestData['ru'][11473] = {title = "Предатель среди нас", objective = "Поговорите с Зех'геном в Лагере Скалаваг.", description = "В последнее время наша заместительница главаря, Энни Бонн, ударилась в паранойю. Всюду ей шпионы мерещатся, представляешь?\n\nА, впрочем, есть у нас давно испытанный метод выявления крыс на корабле. Видишь ли, дружище Зех'ген – да, да, вон тот старикашка – настоящий колдун! Его предки обитали в самом Зул... как его там... неважно, в общем.\n\nИди, сообщи ему, что нам нужно воспользоваться его пророческим даром. Правда, должен тебя сразу предупредить – понять его непросто.", progress = nil, completion = "Дуй сюдыть, дружище. Шта, ко мне причухал?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11474] = {title = "Беда на Крутых утесах", objective = "Поговорите с Уолтом.", description = "Ну, как всегда – вся тяжелая работа досталась мне и моим людям. К счастью, команда Максорфа погибла не напрасно. Шифр, который они обнаружили, поможет нам сделать перевод многих древних текстов, которые мы обнаружили во время раскопок – если, конечно, нам удастся до них добраться! Эти проклятые железные дворфы лезут, как вода из щелей, и пытаются забросать землей раскопы! Ты представляешь? Эти мерзавцы хотят закопать обратно все то, что мы с таким трудом подняли на поверхность!\n\nВ общем, иди и поговори с Уолтом. Он введет тебя в курс дела.", progress = nil, completion = "Слушай, мелочь – мы и так уже лишились половины команды. Здесь, на крутых утесах остался наш последний оплот. Проклятые Железные дворфы захватили Руины Ивальда и раскопки Бейлгуна. Но у меня есть план, как вернуться обратно и отстоять наши находки до того, как они будут потеряны безвозвратно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11475] = {title = "Орудия труда", objective = "Уолт из Лагеря Лиги исследователей в Ревущем фьорде просит вас вернуть его строительные инструменты.", description = "Я уже несколько дней изучаю это создание, <имя>. Пожалуй, я мог бы построить точную копию такого голема, но управлять им будет изнутри наш оператор. Думаю, так мы сможем обмануть Железных дворфов и проникнуть в Бейлгун.\n\nНо не могу же я собрать такую конструкцию с помощью молотка и кочерги! Мне нужны инструменты! Увы, мой набор остался в Руинах Ивальда, захваченных железными дворфами. Пожалуйста, верни мои инструменты!\n\nРуины Ивальда находятся далеко на северо-востоке.", progress = "Этап первый: вернуть Уолту инструменты.", completion = "Вот теперь я могу приступить к сборке. Ну, конечно, если у меня будут необходимые материалы. Полагаю, теперь ты займешься их поиском.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11476] = {title = "Нож и лягушка", objective = "Купите блестящий нож у Гарри \"Луносвета\" и поймайте скалавагскую лягушку. Отнесите все это Зех'гену в Лагерь Скалаваг.", description = "Знаешь, некоторые пираты... в общем, изъясняются на своем диалекте. Вот и Зех'ген... скажем так, говорит на особом... языке.\n\nВ общем, насколько я понял, ему нужен нож и лягушка.\n\nУ Гарри \"Луносвета\" есть парочка дешевых ножей. Лягушек же легко найти в городе – так и прыгают повсюду. Хватай любую и тащи к Зех'гену.\n\nЧестно говоря, не хотел бы я оказаться на месте этой несчастной твари.", progress = "Ну, тащишь квакуху, салага?", completion = "Мучо спасибос, парниша. Ну и зенки у квакухи!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11477] = {title = "Дворф другой породы", objective = "Донни из Руин Ивальда в Ревущем фьорде просит вас убить 10 разрушителей из клана Железной Руны, 5 работников из клана Железной Руны и 2 ведуна из клана Железной Руны.", description = "Тише, тише, <раса>. Эти железные дворфы такие вспыльчивые! Кстати, не думай, что они тут занимаются раскопками. Как раз наоборот! Эти железношкурые мерзавцы засыпают все наши находки землей! Похоже, они не хотят, чтобы кто-то обнаружил это место. \n\nНет, ну ты скажи мне – что это за дворф, который не интересуется археологическими находками? А я скажу тебе: увидишь такого дворфа – убей на месте! Иди, задай им трепку!", progress = nil, completion = "Молодец, Аркоман. Это их ненадолго замедлит.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11478] = {title = "На той заставе...", objective = "Доставьте письмо от Донни Станваду в Лагерь Лиги исследователей.", description = "Похоже, ты еще не <посетил/посетила> моих братьев из Лагеря Лиги исследователей, что находится к югу отсюда. Послушай, окажи Донни услугу и отнеси эту записку Станваду. Ему необходимо узнать про действия Железных дворфов в наших краях. \n\nКак я уже сказал, тебе надо двигаться на юг. Лагерь расположен прямо перед Бейлгуном.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11479] = {title = "\"Хромой\" Дэн", objective = "Проучите \"Хромого\" Дэна, который прячется на одном из кораблей в Лагере Скалаваг. Когда выполните это задание, поговорите с Красавчиком Терри.", description = "Квакша назвала предателя! Кракен ему в глотку, вонючей крысе. Это \"Хромой\" Дэн, который прячется вон там, на корабле.\n\nИди-ка, проучи этого сосунка. Пусть знает – с пиратами шутки плохи. Топай к Терри, как протащишь этого мерзавца под килем.", progress = nil, completion = "Какая жалость... Дэн был моим другом... И к тому же был должен мне кучу денег! Впрочем, если он действительно спутался с шайкой Южных морей, то он получил по заслугам.\n\nЧто же касается тебя, дружище – тебя ждет большое будущее. В буквальном смысле.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11480] = {title = "Познакомьтесь с номером два", objective = "Поговорите с Энни Бонн в Лагере Скалаваг.", description = "Проделанная тобой работа не осталась незамеченной, <имя>. Наш второй командир, несравненная Энни Бонн, глубоко впечатлена твоими достижениями и мечтает с тобой познакомиться.", progress = nil, completion = "Ну-ка, ну-ка... К нам пожаловал сам Аркоман. Говорят, ты явился в Лагерь Скалаваг, без рекомендаций, никто ничего о тебе не знает, кроме этого бездельника Терри.\n\nСкажем прямо – не нравится мне все это...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11481] = {title = "Чрезвычайная ситуация у Солнечного Колодца", objective = "Адиен Страж Света с возвышенности Алдоров в Шаттрате поручает вам отправиться на плато Солнечного Колодца и поговорить с Ларетором.", description = "Благодарю тебя, <раса>, от имени наару за твои труды.\n\nНо до завершения нам еще далеко, и я должен просить тебя выполнить еще одну чрезвычайно важную миссию – не менее важную, чем те, что я поручал прежде.\n\nНаши силы очень растянуты. Чтобы ослабить напряжение, нам пришлось направить отряд в Азерот для отслеживания работ на плато Солнечного Колодца.\n\nТы <нужен/нужна> там, <имя>. Найди Ларетора. Скажи ему, что больше я послать не могу.", progress = nil, completion = "Еще подмога из Шаттрата? Радостное зрелище!\n\nХотелось бы, чтобы помощь была побольше, но будем обходиться с тем, что есть. События ждать нас не будут.\n\nОглядись вокруг, |3-6(Жрец). Здесь многое надо сделать. Подключайся и делай свое дело.\n\nО, да, и не дразни этих Подлизцев... э-э, Провидцев. Сдается, сейчас мы заодно...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11482] = {title = "Зов долга", objective = "Датрис Солнцесвет с яруса Провидцев Шаттрата настаивает, чтобы вы отправились на Азерот немедленно и поговорили с Ларетором у Солнечного Колодца.", description = "Слушай меня, <раса>.\n\nДолг требует,чтобы ты <вернулся/вернулась> на Азерот. Все, способные сражаться, немедленно должны явиться на плато Солнечного Колодца.\n\nБоюсь, больше ничего тебе сказать не могу, разве что следующее:\n\nТы присоединишься к объединенным силам Алдоров. Поговори по прибытии с дренеем по имени Ларетор.\n\nПохоже, ситуация такова, что мы должны забыть о наших распрях и объединиться.\n\nГотовься. Дело, похоже, серьезное.", progress = nil, completion = "Добро пожаловать на плато Солнечного Колодца, Подлизец? Нет, не так? А, Провидец, конечно.\n\nЛадно. Тут надо кое-что привести в порядок. За этими стенами творятся непростые дела, и в интересах наших народов надо с ними разобраться. И поскольку в одиночку никто из нас не справится, мы будем трудиться ВМЕСТЕ. Понятно?\n\nНу, так начнем?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11483] = {title = "Мы тоже так можем!", objective = "Уолт из Лагеря Лиги исследователей в Ревущем фьорде просит вас достать ему большую бочку, крепкий промышленный канат и несколько слитков черного железа.", description = "Инструменты? Есть. Материалов нет!\n\nЕсли мы собираемся построить эту штуку, тебе придется достать материалы. Итак, по порядку: для возведения скелетной структуры мне потребуется большая бочка из Ниффлвара, несколько слитков черного железа из Валгарда и крепкий промышленный канат из Гибльхейма.\n\nНиффлвар и Гибльхейм – это врайкульские города к северо-западу отсюда. Валгард находится в Бухте Кинжалов, что тоже тебе по пути. Слитки получишь у МакГоувера. Он-то и отправит тебя обратно, когда ты соберешь все необходимое.", progress = "Ты принес строительные материалы?", completion = "Превосходно. Теперь мы покроем эту шутку кожей – и получим точную копию создания, которых используют Железные дворфы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11484] = {title = "Мы знаем технологию", objective = "Уолт из Лагеря Лиги исследователей просит вас достать ему безупречную шкуру черпорога и стальной каркас.", description = "Внешний вид устройства столь же важен, как и его механическая часть. Если мы хотим обмануть Железных дворфов, нам придется создать абсолютно идентичного голема! \n\nНо я знаю, как этого добиться. \n\nПринеси мне безупречную шкуру местного черпорога и отбери стальной каркас у одного из врайкулов в Ниффлваре или Гибльхейме. Оба этих поселка находятся к северо-западу отсюда.", progress = "Очень скоро мы снова займемся раскопками!", completion = "Как только механизм будет готов, я закончу работу над этим устройством.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11485] = {title = "Голем Железной руны: обучение \"Реактивному прыжку\"", objective = "Уолт из Лагеря Лиги исследователей в Ревущем фьорде просит вас воспользоваться способностью \"Реактивный прыжок\" голема Железной Руны, стоя на вырезанной Уолтом руне.\n\nПосле выполнения упражнения отпустите голема.", description = "Ну ладно, <имя>. Забирайся в эту штуковину – будем учить тебя основам управления. Как будешь <готов/готова>, садись на верстак, и я помогу тебе занять место пилота внутри голема.\n\nДля начала попробуй понять принципы передвижения. Видишь вон те руны, которые железные дворфы вырезали вокруг раскопа? Големы используют их энергию, чтобы перелетать с места на место. Потренируйся вот на этой руне, которую я вырезал для тебя.", progress = "Только не надо устраивать тут бег через барьеры на этом големе!", completion = "Скоро ты сможешь испытать эту штучку в деле, Reng!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11488] = {title = "Терраса Магистров", objective = "Экзарх Ларетор с плацдарма армии Расколотого Солнца просит вас найти на террасе Магистров своего разведчика – эльфа крови Тирита.", description = "Добро пожаловать в Солнечный Колодец, <класс>. Устраивайся и помогай чем можешь – дел невпроворот!\n\nЯ? Да, у меня есть небольшое дело, но вряд ли ты за него возьмешься.\n\nМы внедрили на террасу Магистров разведчика. В последний раз он не вышел на связь, и я начинаю тревожиться.\n\nТерраса находится вверх по склону на востоке. Информация просто необходима для нашей миссии.\n\nКак думаешь, ты справишься, <раса>?", progress = nil, completion = "...Подойди ближе, |3-6(орк)... Слушай внимательно...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11489] = {title = "Голем Железной руны: обучение \"Сбору информации\"", objective = "Уолт из Лагеря Лиги исследователей в Ревущем фьорде просит вас воспользоваться способностью голема железной руны \"Сбор информации\", стоя рядом с реликвией железных дворфов.\n\nПосле выполнения упражнения отпустите голема.", description = "Мало просто управлять этим големом – надо еще уметь собирать информацию. Вот, смотри – я кладу в тележку реликвию железных дворфов. Это такой парящий, мерцающий кристалл.\n\nСадись обратно на верстак, и я помогу тебе занять место пилота. Как только устроишься внутри, воспользуйся способностью \"Сбор информации\", чтобы поднять тренировочный образец.", progress = nil, completion = "Отлично! Это просто волшебство какое-то!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11490] = {title = "Провидец Провидцев", objective = "Тирит просит вас использовать шар на балконе террасы Магистров.", description = "Ступай на террасу... используй сферу.\n\n*Тирит жадно хватает ртом воздух.*\n\nПоспеши... Нужно остановить их... пока они не...\n\n*Тирит испускает дух.*", progress = "Иди и смотри в шар, смертный.", completion = "Не случайно наши пути сегодня пересеклись.\n\nЯ чую трепет нитей судьбы...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11491] = {title = "Голем Железной руны: обучение \"Обманке\"", objective = "Уолт из Лагеря Лиги исследователей в Ревущем фьорде просит вас потренироваться в использовании способности \"Обманка\" голема Железной руны. Для этого вам надо наступить на коврик Лебронски.\n\nПосле выполнения упражнения отпустите голема.", description = "Запомни: всегда имей наготове \"План Б\" – на случай, если основной замысел не удастся! Вот почему я встроил в этого голема кое-какие оборонительные системы. \n\nТакое новенькое, сверкающее устройство может вызвать подозрения у дворфов раскопки Бейлгуна. Вот тут-то и пригодится твоя \"Обманка\"! Пользуйся этой способностью каждый раз, когда на тебя кто-то нападет, и ты избежишь неприятностей.\n\nИди, потренируйся на Лебронски – потопчись на его коврике. А когда он начнет возмущаться, воспользуйся \"Обманкой\"! \n\nДавай, садись на верстак.", progress = "Не волнуйся насчет Лебронски. Переживет...", completion = "Эх, как ты его отделал! Ну все, теперь ты готов к работе в тылу врага.\n\nВолнуешься?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11492] = {title = "Страшный противник", objective = "Калесгос велит вам уничтожить Кель'таса на террасе Магистров. Отрубите Келю голову и вернитесь к Ларетору на плацдарм армии Расколотого Солнца.", description = "Добро пожаловать к Солнечному Колодцу, смертные. Воистину, вовремя вы пришли.\n\nКак видите, силы Легиона неустанно трудились, управляя мощью Колодца, чтобы достичь своих злых целей.\n\nКель'тас восстал из пепла поражения и вновь направляет их усилия. Найдите его, смертные. Его снова надо остановить.\n\nМеня зовут иные, не менее важные дела. Судьбу Кель'таса поручаю вам. Не подведите.\n\nЕсли удача пребудет с нами, мы еще встретимся.", progress = "Что же, |3-6(Жрец), должен признаться, я не был уверен, что мы снова свидимся.\n\nЧто за новости ты принес?", completion = "&lt;Ларетор внимательно слушает ваш рассказ о событиях на террасе Магистров.&gt;\n\nЖаль Тирита – он был хорошим эльфом. Но благодаря тебе он погиб не даром.\n\nЯ недооценивал тебя, |3-6(тролль). Прошу, прими это от имени наступательной группировки Солнечного Колодца – этот дар достоин такого героя как ты.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nХрупкая пунцовая шпинельСверкающая пунцовая шпинельСверкающая пунцовая шпинель\n\nВы так же изучите:\n\nГероический вид\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11493] = {title = "UNUSED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][11494] = {title = "Заряженные молнией артефакты", objective = "Уолт из Лагеря Лиги исследователей в Ревущем фьорде просит вас собрать 15 наборов данных о Железной Руне с помощью способности \"Сбор информации\" голема Железной Руны.\n\nПосле выполнения задания отпустите голема.", description = "Ну, все. Твой голем готов. Все механизмы смазаны, все программы проверены. Заодно я научил его понимать язык титанов.\n\nДавай, отведи его к раскопкам Бейлгуна, к югу отсюда, и собери данные о заряженных молнией артефактах, которые лежат по всему раскопу. Не забудь включать \"Обманку\" каждый раз, когда твой голем вызовет подозрение у Железных дворфов. Чтобы перепрыгивать с руны на руну, пользуйся \"Реактивным прыжком\". \n\nЗабирайся на верстак, когда будешь <готов/готова> отправиться в путь!", progress = nil, completion = "И снова Уолт доказал, что он умнее всех дворфов! Ну, что ты теперь скажешь про моего голема, Лебронски?\n\nСпасибо, Аркоман. Эта информация чрезвычайно важна. Знать бы еще, как извлечь ее из этого механизма...", rewards = "Капюшон защиты от шокаКольчато-пластинчатые перчаткиНабедренники необыкновенной щедростиВам дадут возможность выбрать одну из следующих наград:\n\nКристаллический сюрикен\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11495] = {title = "Нежный звук грома", objective = "Уолт из Лагеря Лиги исследователей в Ревущем фьорде просит вас исследовать грохочущую пещеру на раскопках Бейлгуна с помощью голема из клана Железной Руны.\n\nПосле выполнения задания отпустите голема.", description = "Во время раскопок Бейлгуна мы наткнулись на пещеру, которую до сих пор обходят стороной даже самые отважные исследователи. Честно говоря, я их понимаю... Трудно остаться хладнокровным, когда из самого чрева пещеры доносятся ужасные раскаты грома!\n\nВ итоге мы прекратили раскопки в этом месте. Страшные беды постигли тех, кто отважился войти в пещеру – многие остались там навсегда.\n\nПрошу тебя, <имя>, осмотри это место, когда окажешься на раскопках, и расскажи мне о том, что тебе удастся обнаружить. Грохочущая пещера находится возле статуи титана.", progress = nil, completion = "Невероятно! Что же еще задумали эти железные существа? Что они делают на Грозовой Гряде? И кто такой Локен?! Надо незамедлительно передать эту информацию на центральную базу в Драконьем Погосте. Не волнуйся, Аркоман, я не забуду упомянуть о твоих заслугах.", rewards = "Легковесный клейморИзъеденный кислотой кастетЧеканный кинжал из хладосталиМушкетон со взрывателемВы получите:\n\n"}
MultiLanguageQuestData['ru'][11496] = {title = "Охрана святилища", objective = "Капитан Терис Рассветное Пламя с плацдарма армии Расколотого Солнца просит вас добыть 4 клочка маны у Презренных-злобней и Презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке.", description = "Важнейшая наша задача – захватить святилище Солнечного Края. Как только мы его захватим, мы сможем использовать его энергию для открытия портала из Шаттрата.\n\nСейчас святилище захвачено Презренными – бывшими эльфами крови, которые опустились до того, что стали тупыми подобиями себя прежних. Будь все в порядке, защитное поле колодца само не пустило бы их, но Презренные украли источник энергии защитного поля колодца.\n\nПеребей Презренных и собери с них клочки маны. Используй их для подпитки защитного поля святилища.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11497] = {title = "Орлята учатся летать", objective = "Поговорите с Илсой Бурное Варево в цитадели Громового Молота в долине Призрачной Луны.", description = "Хотя в перспективе это может повредить моему бизнесу, у тебя прямо на лбу написана мечта о полете, о том, чтобы завести своего летуна, чтобы парить в небесах, а не так, чтобы тебя перевозили с места на место.\n\nПолностью тебя понимаю.\n\nТебе надо пойти в цитадель Громового Молота на юго-западном краю долины Призрачной Луны. Доберешься туда – поговори с Ильсой Бурное Варево по поводу обучения полетам. Учти – ее наставления стоят недешево. Но они того стоят.", progress = nil, completion = "Значит, тебя Нутрал послал, да? Добрый мальчик... Надо поставить ему выпивку за то, что посылает ко мне учеников.\n\nЕсли хочешь научиться летать как надо, то ты пришел в нужное место. Никто не умеет летать лучше Громовых Молотов и тех, кого мы обучаем. Я беру немало, но я обучу тебя парить как орел в небесах!\n\nА когда закончим, не забудь поговорить с Брюнном вон там насчет покупки одного из этих грифончиков-красавчиков!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11498] = {title = "Орлята учатся летать", objective = "Поговорите с Олрокком в деревне Призрачной Луны в долине Призрачной Луны.", description = "Хотя в перспективе это может повредить моему бизнесу, у тебя прямо на лбу написана мечта о полете, о том, чтобы завести своего летуна, чтобы парить в небесах, а не так, чтобы тебя перевозили с места на место.\n\nПолностью тебя понимаю.\n\nТебе надо пойти в деревню Призрачной Луны на северо-западном краю долины Призрачной Луны. Доберешься туда – поговори с Олрокком по поводу обучения полетам. Учти – его наставления стоят недешево. Но они того стоят.", progress = nil, completion = "Гром и молния, Нутрал посылает ко мне очередного сухопутного рубаку! Добрый он... для дренея.\n\n&lt;Олрокк сплевывает вам под ноги.&gt;\n\nЕсли хочешь знать, как летать на своем летуне в небесах, ты пришел в нужное место. За мешок золота я научу тебя всему, что нужно, чтобы позорно не свалиться и не разбиться в лепешку.\n\nКогда научишься, не забудь поговорить с Дамой Буйной Гривой насчет приобретения ветрокрыла из наших стойл!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11499] = {title = "Разыскивается: перстень-печатка принца Кель'таса", objective = "Торговец ветром Зарим хочет, чтобы вы добыли ему перстень-печатку принца Кель'таса. Доставьте ее в Нижний город Шаттрата и получите награду. \n\nЭто задание выполняется на террасе Магистров только в героическом режиме.", description = "Сегодня, <класс>, я буду просить тебя о невозможном. Сегодня тебе придется добыть перстень-печатку Кель'таса Солнечного Скитальца, правителя эльфов крови!\n\nНу, слухи о его гибели в Крепости Бурь не слишком-то достоверны. Он снова появился, теперь на террасе Магистров на острове Кель'Данас. Что он там делает – это пусть тебе кто-нибудь другой расскажет. А я знаю, что огромное число коллекционеров жаждет заполучить его королевское кольцо, и я собираюсь его для них добыть.\n\nТочнее, добывать его будешь ты...", progress = "Терраса Магистров, наверное, очень опасное место – слишком уж близко оно к Солнечному Колодцу.\n\nНадеюсь, ты не передумаешь?", completion = "Значит, на сей раз принц эльфов крови и правда мертв? Жаль, я всегда считал, что он умеет вести себя в обществе. Подумать только – такую личность могут убить за такую плевую сумму.\n\nНо, как говорится, дело есть дело. Вы заслужили свою награду, искатель приключений.\n\nВозвращайтесь завтра, и у меня найдется для вас другое порученьице", rewards = "Вы получите:\n\nЗнак справедливостиЗнак справедливости"}
MultiLanguageQuestData['ru'][11500] = {title = "Разыскиваются: сестры Терзаний", objective = "Ловчий Пустоты Ма'дуун хочет, чтобы вы убили 4 сестер терзаний. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду.", description = "Ветер нашептал Ма'дууну, что сестры терзаний должны быть отправлены в бездну, из которой они явились.\n\nМа'дуун знает, что этих демониц можно найти на террасе Магистров на острове Кель'Данас.\n\nХочешь получить награду – убей их.", progress = nil, completion = "Кто знает, почему должны быть убиты сестры-демоницы? Тебе не безразлично?\n\nНо Ма'дуун думает, что награда-то тебе не безразлична. \n\nВозвращайся утром, и ветер нашепчет Ма'дууну что-нибудь еще.", rewards = "Вы получите:\n\nКлюч от тюрьмы братства Эфириум"}
MultiLanguageQuestData['ru'][11501] = {title = "Вести с востока", objective = "Поговорите с капитаном Адамсом из Крепости Западной Стражи.", description = "<имя>, я хочу, чтобы ты лично <доложил/доложила> капитану Адамсу из Крепости Западной Стражи о том, что здесь происходит.\n\nДай мне знать, когда ты будешь <готов/готова> отправиться в путь, и я посажу тебя в голема. Он доставит тебя в Крепость Западной Стражи – если не развалится на полпути.\n\nБыло приятно с тобой работать...", progress = nil, completion = "Этого мне не хватало... Можно подумать, мало нам было проблем с Плетью! Нет, придется теперь еще и разбираться с какими-то древними созданиями титанов.\n\nЛадно, |3-6(гном), мне надо обдумать эту информацию. Не уходи далеко – ты мне еще понадобишься.", rewards = "Оплот щедростиВам дадут возможность выбрать одну из следующих наград:\n\nФолиант Рвения\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11502] = {title = "Защита Халаа", objective = "Победите 10 игроков вражеской фракции в Халаа и вернитесь в Телаар к Лакуру.", description = "Мы не воинственная раса, <раса>. Но когда война приходит на наш порог, мы не бежим от нее.\n\nАльянс и Орда ведут войну в Халаа, на северо-западе отсюда. Мы не знаем, что затевают эти эльфы крови, но если победит Орда – это будет катастрофа. Между нами и орками старинная вражда, кровь и предательство.\n\nИди и убивай врагов в Халаа, и получишь золото, славу и честь!", progress = "Дело сделано, Мэлфис?", completion = "Благодарю тебя, Мэлфис. Твои дела не будут забыты.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11503] = {title = "Враги старые и враги новые", objective = "Победите 10 игроков вражеской фракции в Халаа и вернитесь в Гарадар к Карртогу.", description = "Наши старинные враги, дренеи, вернулись с могущественными союзниками. Они ведут войну в Халаа, к юго-западу отсюда.\n\nМы не должны дать им победить, потому что потом они, вне всякого сомнения, ударят на Гарадар.\n\nИди и перебей тех, кто помогает нашим старинным врагам.", progress = nil, completion = "Ты принес великую честь нашему народу. Прими нашу благодарность.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11504] = {title = "Ожившие мертвецы", objective = "Орфус Камагуанский с Древнего подъемника просит вас принести ему улики из могил Фенгира, Родина, Исулдофа и Ветрана.", description = "Клыкарры обычно охотятся на восточной дороге – во всяком случае, так было раньше...\n\nНедавно наши охотники вернулись из Камагуа с ужасной вестью – будто бы мертвецы восстали из могил и жаждут нашей крови! Старейшина Атуик поручил мне и моему сыну разобраться с этой проблемой.\n\nПротянешь ли ты нам руку помощи в час нужды? Я ищу героев, которые отважатся преступить границы Заградительного холма, что к юго-востоку отсюда. Осмотри раскопанные могилы и доложи мне о своих находках.", progress = "Клыкаррам нужна твоя помощь!", completion = "&lt;Усы Орфуса гневно топорщатся.&gt;\n\nПираты... Кто положит конец их бесчинствам?\n\nМы должны разыскать украденные артефакты и вернуть их на место. Только тогда мой народ будет в безопасности.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11505] = {title = "Духи Аукиндона", objective = "Помогите Альянсу удерживать Башню духов в Костяных пустошах.", description = "Духам Аукиндона нет дела до усобиц Альянса и Орды, но заслужив их расположение, наша сторона получит преимущество в этих краях.\n\nДревний обычай велит живым поклоняться Башням духов в Костяных пустошах – но только в определенное время дня. Если ты поможешь удерживать башни в это время, то привлечешь духов на нашу сторону.\n\nЕсли мы добьемся благосклонности духов, они даруют нам покровительство, которое поможет нам в наших делах.", progress = "Духи все никак не успокоются, Будулайко. Ты выполнил свое поручение?", completion = "Теперь духи ближе к умиротворению. Хорошо, что мы заслужили их благосклонность, тем более что воюем так близко к месту их упокоения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11506] = {title = "Духи Аукиндона", objective = "Помогите Орде удерживать Башню духов в Костяных пустошах.", description = "Да, мы враждуем с дренеями, но неупокоенные духи их предков в Аукиндоне не служат никому из мира живых.\n\nОбычай дренеев требует от них поклонения Башням духов несколько раз в течение дня в определенное время. Если ты поможешь удерживать башни в это время, ты поможешь духам обрести покой в Аукиндоне.\n\nАльянс попытается захватить башни, чтобы заслужить благоволение усопших. Но победа должна быть за нами.", progress = "Вокруг нас духи Аукиндона. Даруют ли они нам свое покровительство?", completion = "Теперь духи стали ближе к умиротворению. Они благосклонны к нам.\n\nКакое унижение для наших врагов – знать, что души их предков обернулись против них, пусть и на время!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11507] = {title = "Старейшина Атуик из Камагуа", objective = "Орфус Камагуанский из Ревущего фьорда просит вас отнести узелок старейшине Атуику из Камагуа.", description = "<Орфус тщательно сворачивает принесенные улики.>\n\nМой народ давно уже не воюет с флибустьерами Северных морей. Худой мир лучше доброй драки. Так что я знаю только одного клыкарра, который может помочь нам вытрясти правду из пиратов. Зовут его старейшина Атуик из Камагуа. Отнеси ему эти доказательства.\n\nЧтобы добраться до Камагуа, тебе надо воспользоваться подъемником, который находится позади меня. Он доставит тебя прямиком в деревню, где ты и найдешь старейшину Атуика.", progress = "Есть новости от Орфуса?", completion = "Орфус – хороший клыкарр, и один из лучших наших воинов. Я знал, что на него можно положиться.\n\nНу-ка, что там он мне передал?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11508] = {title = "Греззикс Иглохруст", objective = "Поговорите с Греззиксом Иглохрустом.", description = "Воришки-пираты обосновались в Лагере Скалаваг, далеко на юге. К несчастью, их аванпост слишком хорошо охраняется.\n\nВпрочем, я знаю одного товарища, который может помочь нам туда проникнуть.\n\nНедавно в деревню пришел пират-наемник, Греззикс Иглохруст, и попросил у нас убежища. В обмен на пищу и кров он дает информацию о наших врагах и передает пиратам ложные сведения о наших планах. Его лодка находится к юго-западу от берега.", progress = nil, completion = "Хай, дружище. Греззикс никогда не любил связываться с грязными делишками! Всем хороша пиратская доля – пока не приходится пачкать руки в крови.\n\nВидел я эти артефакты – потому и сбежал из Лагеря Скалаваг. Плохие это штуки, очень плохие... \n\nВпрочем, это же твоя жизнь, верно? Хочешь пролезть в Скалаваг – пожалуйста, Греззикс тебе поможет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11509] = {title = "Чудак среди чудаков", objective = "Поговорите с Гарри \"Луносветом\" в Лагере Скалаваг и расспросите его о пропавших врайкульских артефактах.", description = "Флибустьеры Северных морей боятся и уважают Греззикса. Наверное, они просто завидуют моему интеллекту и трепещут перед моим грозным кораблем. Так что ты просто сядь на хвост моему юнге Луи, и скоро станешь своим в доску. Доска – это для пирата все.\n\nКак будешь <готов/готова> к отправлению – свистни Луи, и он отведет тебя в Скалаваг.\n\nАх да – сначала тебе стоит поболтать с Гарри \"Луносветом\". Он расскажет тебе про эти древние штучки, которые они стырили у врайкулов. Только следи за языком, когда будешь с ним разговаривать. Он такой чудак... совершенно помешался на эльфах крови.", progress = nil, completion = "&lt;Гарри удивленно смотрит на вас.&gt;\n\nА, еще один чудик в нашу команду. Добро пожаловать в клуб!\n\n&lt;Гарри понижает голос.&gt;\n\nЗнаешь, кроме нас тут никто не носит такие шмотки.\n\nА что касается артефактов... Все прикасавшиеся к этим штуковинам либо померли, либо пропали без вести.\n\nНеужели тебе все еще интересно о них узнать? Если что, я могу помочь – конечно, не за доброе слово, а за звонкую монетку.\n\n&lt;Гарри подмигивает.&gt;\n\nРука руку моет, да ножом не колет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11510] = {title = "\"Челюсти\"", objective = "Гарри \"Луносвет\" из Лагеря Скалаваг просит вас достать гадальный шар син'дорай, принадлежащий ему, из брюха косатки по прозвищу \"Челюсти\".", description = "Когда Иона Стерлинг сошел с ума, он первым делом отобрал у меня драгоценный гадальный шар син'дорай и скормил его этой проклятой твари, косатке по прозвищу \"Челюсти\".\n\nНет, это не я ее так обозвал. Я вообще ничего не знаю про эту зверюгу – помимо того, что она постоянно кружит возле наших кораблей на юго-востоке от Скалавага. Убей эту селедку-переростка, вспори ей брюхо и вытащи мой бесценный гадальный шар!\n\nПринесешь мне его – тогда и поговорим.", progress = "Ты заблудился, что ли?", completion = "&lt;Гарри бережно принимает кристалл из ваших рук и поглаживает его.&gt;\n\nАх, ты моя прелесть! Этот мерзкий кит тебя обидел? Ничего, теперь все будет хорошо. Больше я никому тебя не отдам!\n\n&lt;Гарри отрывается от созерцания шара и смотрит на вас.&gt;\n\nТак на чем мы остановились?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11511] = {title = "Посох Неистовства Бури", objective = "Найдите посох Неистовства Бури и отнесите его Орфусу Камагуанскому в Ревущий фьорд.", description = "Эти артефакты прокляты, <раса>, и надо быть сумасшедшим, чтобы решиться на их поиски. Каждый, кто прикасался к ним, либо сходил с ума, либо умирал насильственной смертью. \n\nВозьмем, к примеру, этот посох. Перевозивший его корабль наткнулся на скалы и теперь гниет на побережье Острова Копий, к северу отсюда.\n\nЕсли тебе правда нужна эта штука, ищи ее в трюме.\n\nТолько не приноси этот посох сюда, если найдешь его! И держись подальше от Абдула. Попадешься ему – распрощаешься с жизнью.", progress = "Посох у тебя?", completion = "Мы должны отыскать все четыре артефакта, Рунакус. Когда мы возвратим святыни, ты положишь их на место, в захоронения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11512] = {title = "Ледяное сердце Исулдофа", objective = "Найдите ледяное сердце Исулдофа и отнесите его Орфусу Камагуанскому в Ревущий фьорд.", description = "Кое-кто считает, что Иона всегда был сумасшедшим, но я-то знаю правду. Все дело в сердце! В этом проклятом ледяном сердце! В тот самый момент, когда он достал его из могилы, что-то в нем перемкнуло. Я буквально почувствовал, как кровь застыла в его жилах... Именно тогда безумие охватило его. \n\nОн покинул нас и скрылся в пещере на севере острова. Говорят, он забросил проклятый артефакт в глубину своей берлоги. Увы, слишком поздно...\n\nНо если ты только помыслишь притащить сюда это сердце, я лично убью тебя!", progress = "Это... это Ледяное сердце Исулдофа?", completion = "Мы должны отыскать все четыре артефакта, Reng. Когда мы возвратим святыни, ты положишь их на место, в захоронения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11513] = {title = "Перехват контейнеров с маной", objective = "Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на террасу Света в Шаттрат.", description = "Я разработал план, согласно которому мы сможем добыть достаточно сильные источники энергии для создания нашего портала.\n\nЭфириалы в лагере Баш'ира, в горах у северо-западной оконечности Острогорья, контрабандой вывозят контейнеры с маной из Крепости Бурь и отправляют их Кель'тасу к Солнечному Колодцу.\n\nОни прячут контейнеры, но их все же можно отыскать – эфириалы носят при себе синхронизаторы, при помощи которых можно увидеть контрабандный товар.\n\nОпасайся охраняющих контейнеры с маной синхзрозмей.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nФлаг заданий с порталами Солнечного Колодца\n\nВы получите:\n\nПрипасы Расколотого СолнцаПредмет #1"}
MultiLanguageQuestData['ru'][11514] = {title = "Поддержка портала Солнечного Колодца", objective = "Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на террасу Света в Шаттрат.", description = "Мы должны постоянно снабжать энергией наш портал, иначе он уничтожится. Контейнеры с маной, которые Эфириум спрятал в лагере Баш'ира, помогут нам. Лагерь расположен в горах, на северо-западной оконечности Острогорья, что далеко на севере отсюда.\n\nЗапомни: надо добыть у одного из них синхронизатор и с его помощью определить, где находится контрабанда.\n\nОстерегайся синхрозмей, которых они держат как охрану возле контейнеров с маной.", progress = "Визардд, удалось ли тебе добыть для нас контейнеры с маной?", completion = "Эти контейнеры помогут нам поддерживать портал.\n\nПриходи завтра, и я попрошу тебя добыть еще.", rewards = "Следующее заклинание будет наложено на вас:\n\nФлаг заданий с порталами Солнечного Колодца\n\nВы получите:\n\nПрипасы Расколотого СолнцаПредмет #1"}
MultiLanguageQuestData['ru'][11515] = {title = "Кровь за кровь", objective = "Магистр Сейла у трона Кил'джедена велит вам убить 4 истощенных сквернокровов при помощи конденсатора Скверны. Вам понадобится кровь демонов, которая течет по венам находящихся рядом зловещих глашатаев, чтобы наполнить конденсатор Скверны.", description = "Когда войска Келя отступили через этот портал, самые верные его приспешники получили мерзкий дар. Они остались здесь и много дней жадно пили кровь демонов.\n\nЭта кровь изменила их, дав им новую мощь. И эта кровь станет причиной их гибели.\n\nДобудь пробу крови у других демонов. Наполни ей этот конденсатор Скверны и лиши этих надменных глупцов новообретенной мощи. Они ослабнут – вот тогда ты убьешь их и вернешься ко мне!", progress = "Эти уроды - позор нашей расы. Их надо уничтожить, Куард.", completion = "Глупцы. Они научились высасывать энергию Скверны, но не умеют ее накапливать.\n\nНам повезло, Куард. Опытный эльф Крови Скверны - страшный противник.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗнак СаргерасаПерстень Ярости Солнца\n\nВы также получите:\n\nПредмет #4"}
MultiLanguageQuestData['ru'][11516] = {title = "Взрыв врат", objective = "Магистр Сейла у трона Кил'джедена велит вам взять раскаленные угли, чтобы вызвать живую вспышку и убивать рядом с ней раскаленных искр Скверны, пока она не станет нестабильной живой вспышкой. Вернитесь к вратам Легиона вместе с нестабильной живой вспышкой, чтобы уничтожить врата.", description = "Мы должны закрыть эти врата, чтобы не допустить подхода подкрепления Легиона на Кель'Данас.\n\nВозьми эти угли, в них живет одно из моих созданий – живая вспышка. Она обладает мощной разрушительной силой, если ей хватает энергии.\n\nНайди искры Скверны, что летают в тех краях, и убивай их рядом с живой вспышкой. От каждой убитой искры Скверны живая вспышка будет напитываться силой, пока не станет нестабильной.\n\nКак только живая вспышка достигнет этого состояния, иди к вратам. А живая вспышка уже сделает все сама.", progress = "Дело сделано, Куард? Мы не должны допустить подхода на помощь Кель'тасу сил Легиона.", completion = "Замечательная работа, Куард. Демоны, конечно, со временем восстановят врата. Ну, ничего, снова взорвем.", rewards = "Вы получите:\n\nПрипасы Расколотого Солнца"}
MultiLanguageQuestData['ru'][11517] = {title = "Встреча с Назууном", objective = "Торговец Портануус просит вас поговорить с экзархом Назууном на террасе Света в Шаттрате.", description = "Я рад, что ты здесь, <класс>! Теперь, когда мы захватили святилище, нам нужно срочно создать магический портал, который вел бы отсюда в Шаттрат, что в Запределье.\n\nМой господин, экзарх Назуун, возглавляет этот фронт работ наступательной группировки. Он просил меня посылать к нему любых многообещающих кандидатов, которые могли бы помочь в создании портала.\n\nПрошу тебя – отправляйся в Шаттрат и поговори с ним в чертоге А'дала на террасе Света.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11519] = {title = "Пропавший щит Эсиритса", objective = "Поговорите с капитаном Эллис на борту \"Сестренки милосердия\".", description = "Прислушайся! Слышишь канонаду на северо-востоке? Это ведет бой корабль капитана Эллис. Штука в том, что Эллис и его команда погибли около месяца назад. Смекаешь?\n\n<Гарри качает головой.>\n\nДа, это корабль-призрак...\n\nИ на нем плавает тот самый человек, который мог бы рассказать тебе про этот щит.\n\nКаждые пять минут \"Сестренка милосердия\" пристает к маленькому острову напротив Берега Сорлофа. Там они пополняют свою команду призраков, и у них никогда не бывает недостатка в неупокоенных душах.", progress = nil, completion = "Ну да, мои салаги прибрали этот щит к рукам! Да вот только проклятый сухопутный шакал Сорлоф спер его у нас. Мож, ты поможешь его отобрать, а?\n\nА то сам видишь, что у меня за команда!\n\n&lt;Капитан Эллис смеется.&gt;\n\nМне на борту требуется еще один салага – заряжать вон те большие дуры на палубе. Справишься с работенкой, дорогуша?\n\nЯкорь мне в глотку! Если свалим Сорлофа – добычу пополам! Тебе щит, мне все остальное!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11520] = {title = "Смотри в корень", objective = "Мар'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа.", description = "Привет тебе, <раса>. \n\nБоюсь, мне мало есть что предложить тебе, пока не пополню запасов своих реагентов. \n\nИ прежде всего мне нужен корень Острого Шипа, который особенно трудно добывать.\n\nНо, к счастью, я знаю один секрет...\n\nПри помощи желез острошипа-живодера, можно контролировать разорителя и использовать его для выкапывания корней.\n\nЧтобы найти корень, надо отправиться в Запределье и полететь на северо-восток от Шаттрата, до уступа Острого Шипа.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПрипасы Расколотого Солнца"}
MultiLanguageQuestData['ru'][11521] = {title = "И опять – смотри в корень", objective = "Мар'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа.", description = "Запасов мне пока хватает, но чтобы удовлетворять спрос, мне нужно много корня Острого Шипа.\n\nДобывать его нелегко Но я знаю особый способ его выкапывания.\n\nПри помощи желез острошипа-живодера, можно контролировать разорителя и использовать его для выкапывания корней.\n\nЧтобы найти корень, надо отправиться в Запределье и полететь на северо-восток от Шаттрата, до уступа Острого Шипа.\n\nКак только выкопаешь пять корней, <имя>, возвращайся.", progress = "Честное слово, Антизог, мне не до разговоров.\n\nПросто дай мне знать, когда добудешь корни.", completion = "Замечательно, Антизог.\n\nЕще раз благодарю за помощь!", rewards = "Вы получите:\n\nПрипасы Расколотого СолнцаПредмет #5"}
MultiLanguageQuestData['ru'][11523] = {title = "Подпитка для силового поля", objective = "Капитан Терис Рассветное Пламя с плацдарма армии Расколотого Солнца просит вас добыть 4 клочка маны у Презренных-злобней и Презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке.", description = "Нам удалось реактивировать кристаллы-хранители, создающие поле вокруг святилища, но зачем останавливаться на достигнутом? Мы окружим защитой и другие строения, но Презренные упрямы – они продолжают похищать силу из кристаллов-хранителей.\n\nПеребей их и забери у них клочки маны. При их помощи активируй защиту святилища – от этого зависит успех наших операций здесь.", progress = nil, completion = "Хорошая работа, Таквер. Поле постепенно набирает силу. Солнечный Край скоро будет нашим!", rewards = "Вы получите:\n\nПредмет #4"}
MultiLanguageQuestData['ru'][11524] = {title = "Хаотичное поведение", objective = "Воздаятельница Ксаяна на подготовительном плацдарме Расколотого Солнца просит, чтобы вы поместили настроенные кристаллы-сердечники в корпуса 5 побежденных магических стражей, чтобы перевести их в дружественный режим.", description = "Нас слишком мало, чтобы захватить святилище в Солнечном Крае, но у меня есть план, который качнет чашку весов в нашу сторону.\n\nПросачивающаяся из Солнечного Колодца энергия привела к сбою в функционировании стражей, патрулирующих этот остров. Кристаллические сердечники, контролирующие их поведение, уже не подлежат ремонту.\n\nЯ сделала новые кристаллы, с помощью которых мы возьмем их под собственный контроль.Их надо поместить внутрь корпуса побежденного стража. Нам нужна любая помощь.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11525] = {title = "Дальнейшая перенастройка", objective = "Воздаятельница Ксаяна на подготовительном плацдарме Расколотого Солнца просит вас поместить настроенные кристаллы-сердечники в корпуса 5 побежденных блуждающих караульных, чтобы перевести их в дружественный режим.", description = "Мой план заменить поврежденные кристаллы блуждающих караульных увенчался успехом. Мы сумели с их помощью захватить святилище Солнечного Края.\n\nЯ создала новые кристаллы, которые помогут контролировать большее их количество. Помести их в корпуса побежденных караульных. Как только мы их переделаем, мы переведем их в другие места.", progress = "Удалось перенастроить стражей, Таквер?", completion = "Замечательно. Перенастроенные стражи помогут нам защитить наш периметр.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11526] = {title = "Пропавший магистр", objective = "При помощи захваченного свитка Легиона, пройдите сквозь портал на Рассветной площади. Как только пройдете сквозь портал, найдите магистра Сейлу.", description = "Мы послали одну из наших опытных сотрудниц обследовать портал Скверны посреди Рассветной площади, к югу отсюда. Она не вернулась.\n\nВозьми вот этот свиток – мы нашли его на одном из вражеских трупов. Мы уверены, что он даст тебе возможность пройти сквозь портал. Оказавшись там, найди магистра Сейлу и помоги ей, чем сумеешь.", progress = "Тссс, |3-6(Рыцарь смерти). К югу от портала – сторожевой пост Легиона.", completion = "Конечно, очень мило, что Терис заботится о моей шкуре, но у нас тут есть проблемы поважнее. И намного.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11527] = {title = "Бунт на корабле", objective = "Капитан Эллис на борту \"Сестренки милосердия\" в Ревущем фьорде просит вас принести 5 бочек с порохом из трюма корабля.", description = "Да, дружище, у нас проблемы. У меня пушкари взбунтовались! Я тут с остальными ребятами попробую надраить корму Сорлофу, но кому-то придется разобраться с этими бунтовщиками!\n\nИ, знаешь, что? Этим кем-то будешь ты! Топай в трюм, разберись с этими морскими волками-бунтарями, да притащи пороху для большой дуры на верхней палубе.\n\nЕсли ты зарядишь эту пушенцию, Сорлоф в штаны наложит от страха, и сам притащит сюда всю добычу!", progress = "Тут слишком много великанов и морских волков-бунтарей!", completion = "Надеюсь, ты хорошенько проучил этих вероломных трюмных крыс! А теперь пора зарядить нашу пушенцию, дружище!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11528] = {title = "Подарок к Зимнему Покрову", objective = "На ярлычке подарка написано:\n\n\"С праздником, Блэкбукник!\"", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПодарок к Зимнему Покрову"}
MultiLanguageQuestData['ru'][11529] = {title = "Сокровища Сорлофа", objective = "Убейте Сорлофа из большой пушки и принесите капитану Эллис сокровища Сорлофа на борт \"Сестренки милосердия\".", description = "Ща, мои ребята начистят для тебя нашу большую дуру! Вон она валяется по другому борту. Иди, заряди пушку, да приготовься стрелять по Сорлофу!\n\nА как только мы пустим на дно эту сухопутную крысу, ты притащишь сюда всю добычу – нам-то с этого чертова корыта не сойти! Принесешь золотишко – получишь свою часть добычи. Тебе щит, нам все остальное...", progress = "Не щелкай клювом, дорогуша!", completion = "Уговор есть уговор!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11530] = {title = "Щит Эсиритса", objective = "Верните щит Эсиритса Орфусу Камагуанскому на Древний подъемник в Ревущем фьорде.", description = "Вот твой щит. Надеюсь, на тебя не падет его проклятие, как на остальную команду. Только не оставляй его здесь! Могу поспорить, кто-то хочет забрать его. \n\nА теперь – убери эту штуковину с моего корабля!", progress = "Ты вернулся!", completion = "Мы должны отыскать все четыре артефакта, Reng. Когда мы возвратим святыни, ты положишь их на место, в захоронения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11531] = {title = "Странная деталь мотора", objective = "Отнесите странную деталь мотора к К. Ли Мелюзге в Терелдор.", description = "Этот странный механизм никоим образом не напоминает паровой насос. Возможно, К. Ли Мелюзга сможет сказать о нем больше.", progress = "Мама дорогая, что это ты притащил!", completion = "&lt;К. Ли смотрит на деталь, о чем-то задумавшись.&gt;\n\nЭта штука, это что-то особенное... Сложно сказать, откуда она взялась, как будто просто с неба свалилась. Пожалуй, я оставлю ее себе, а тебе заплачу за беспокойство.\n\nМежду нами, я бы на твоем месте не болтала об это направо и налево.\n\n&lt;Она очаровательно тебе улыбается.&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11532] = {title = "Отвлекающий маневр на Тропе Мертвых", objective = "Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов.", description = "Легион двинется на нас, как только его войска на юге освободятся. Пока силы Плети на Тропе Мертвых отвлекают демонов. Но это ненадолго.\n\nЯ прошу тебя взять дракондора, пролететь над Тропой и устроить демонам прореживание при помощи этих чародейских зарядов.\n\nЕсли все пройдет хорошо, они даже не заметят, как мы отобьем оружейную у прихвостней Келя. Поговори с Айреном, укротителем дракондоров, в западной части гавани Солнечного Предела, когда будешь <готов/готова> к вылету.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11533] = {title = "Воздушные атаки должны продолжаться!", objective = "Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов.", description = "Мы захватили у врага оружейную благодаря нашим атакам с воздуха на силы Легиона на Тропе Мертвых.\n\nСобственно говоря, они были столь удачны, что мы намерены продолжать бомбардировки. Возьми эти чародейские заряды и отбомби ими вражьи силы!\n\nПоговори с Айреном Ясным Небом в гавани Солнечного Края, когда будешь <готов/готова> к вылету.", progress = "Ты исполнил свое поручение, Таквер?", completion = "Если можешь убить демона сегодня, не откладывай на завтра. Продолжай в том же духе.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11534] = {title = "Встреча с Назууном", objective = "Торговец Портануус просит вас поговорить с экзархом Назууном на террасе Света в Шаттрате.", description = "Я рад, что ты здесь, <класс>! Теперь, когда мы отбили святилище у Презренных, нам нужно срочно создать магический портал, который вел бы отсюда в Шаттрат, что в Запределье.\n\nМой господин, экзарх Назуун, возглавляет работы наступательной группировки по созданию портала. Он просил меня посылать к нему любых многообещающих кандидатов, которые могли бы помочь добывать источники энергии для портала.\n\nПрошу тебя – отправляйся в Шаттрат и поговори с ним в чертоге А'дала на террасе Света.", progress = nil, completion = "Так тебя прислал Портануус? Отлично, время не терпит!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11535] = {title = "Подготовка к работе", objective = "Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков.", description = "Припасы уже на подходе, или, по крайней мере, мне так сказали.\n\nКак бы то ни было, мы не можем сидеть сложа руки, надеясь, что помощь прибудет до того, как наше наступление завязнет. Будем обходиться тем, что есть.\n\nЛично мне нужна руда для ковки и наковальня, чтобы я могла начать совершенствовать наши оружие и доспех.\n\nНа побережье к востоку отсюда группа наг добывает руду и грузит в сундуки для отправки Легиону.\n\nЕсли мы избавим их от этой тяжести, это очень во многом поможет нам...Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11536] = {title = "Продолжаем...", objective = "Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков.", description = "Теперь, когда у меня есть наковальня, можно приступить к настоящей работе.\n\nКакие бы к нам ни поступили поставки, руда Черноспинов мне всегда пригодится. Нам нужны бесперебойные поставки оружия и доспехов, если мы хотим здесь добиться успеха.\n\nНа побережье к востоку отсюда группа наг добывает руду и грузит в сундуки для отправки Легиону.\n\nЕсли мы избавим их от этой тяжести, это очень во многом поможет нам...", progress = "Ты добыл нужную мне руду?", completion = "Великолепно! Это поможет мне снабжать наших воинов оружием и доспехами.\n\nТвоя помощь просто неоценима!", rewards = "Вы получите:\n\nПредмет #3"}
MultiLanguageQuestData['ru'][11537] = {title = "Битва должна продолжаться!", objective = "Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара Ненависти на Рассветной площади. Пригвоздите к земле древком Знамени Расколотого Солнца труп Эмиссара Ненависти.", description = "Мы должны продолжать битву с армиями Легиона и лишать их боевого духа!\n\nЭмиссары Ненависти – это штормовики Легиона, развернутые для усиления тактических позиций. К ним стекаются враги, поскольку они боятся их больше, чем нас.\n\nСегодня мы переломим ситуацию. Возьми это знамя и повергни демонов Легиона. А когда столкнешься с Посланником Ненависти, срази его и пригвозди к земле.", progress = "Была ли с тобой удача, Таквер?", completion = "Твоя преданность достойна быть примером, Таквер. Мы покажем силам Пылающего Легиона, на что мы способны!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11538] = {title = "Сражение за оружейную Солнечного Края", objective = "Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара ненависти на Рассветной площади или в оружейной Солнечного Края. Пригвоздите труп эмиссара ненависти к земле древком знамени армии Расколотого Солнца.", description = "Пылающий Легион удерживает оружейную Солнечного Края. Это – важный для наших операций пункт. Пока их боевой дух высок, нам не отбить у них это здание. \n\nЭмиссары ненависти – это штурмовики Легиона, развернутые для усиления тактических позиций. К ним стекаются враги, поскольку они боятся их больше, чем нас.\n\nСегодня мы переломим ситуацию. Возьми это знамя и повергни демонов Легиона. А когда столкнешься с эмиссаром ненависти, срази его и пригвозди к земле.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11539] = {title = "Захват гавани", objective = "Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей крови и 3 стрелков из клана Клинка Рассвета.", description = "Отборные войска Кель'таса – Клинки Рассвета – расположились в гавани Солнечного Края и в деревне Утренней Звезды.\n\nГавань чрезвычайно важна для наших планов, так что каждый убитый Клинок Рассвета – огромная помощь. Кель'тас будет проклинать тот миг, когда обратился против собственного народа и заключил союз с Пылающим Легионом!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11540] = {title = "Клинки Рассвета должны быть сокрушены!", objective = "Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей крови и 3 стрелков из клана Клинка Рассвета.", description = "Мы вытеснили Клинков Рассвета из гавани Солнечного Края. Теперь Солнечный Край полностью наш. Но я почему-то не удовлетворен...\n\nПрошу тебя отправиться в деревню Утренней Звезды, к западу отсюда, и перебить всех уцелевших бойцов Клинков Рассвета. Они сами обрекли себя, последовав сюда за Келем.", progress = nil, completion = "Интересно, что подумал принц Кель'тас Солнечный Скиталец, когда услышал о поражении своей армии?\n\nОщутил ли он отчаянье? Беспомощность? Страх? \n\nОчень на это надеюсь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11541] = {title = "Зачистить берег Зеленожабрых!", objective = "Капитан Валиндрия просит вас освободить 10 рабов из племени Зеленожабрых. Вернитесь к ней на борт \"Гордости Луносвета\" в гавань Солнечного Края по выполнении задания.", description = "Наги захватили берег Зеленожабрых к юго-востоку отсюда. Их самки, сирены из клана Черноспинов, используют магию для подчинения местных мурлоков.\n\nЯ обязана следить за тем, чтобы любая высунувшаяся нага была уничтожена. И в этом мне нужна твоя помощь.\n\n<класс>, я прошу тебя добыть сферы контроля у наг и разбросать их возле рабов из племени Зеленожабрых, разбив сферы и освободив рабов.\n\nПодозреваю, что разъяренные мурлоки набросятся на своих хозяев.", progress = nil, completion = "На сегодня хватит. Тут главное действовать неторопливо, но неотвратимо. Если им слишком сильно всыпать, они обратят на нас внимание, а нам этого не надо.\n\nПриходи завтра, и мы продолжим.", rewards = "Вы получите:\n\nПредмет #10"}
MultiLanguageQuestData['ru'][11542] = {title = "Перехватить подкрепление", objective = "Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясным Небом насчет полета до флота Клинков Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса кораблей, а приземлившись, убейте 6 резервистов из армии Клинков Рассвета.", description = "Мы изо всех сил стараемся укрепить свой контроль над Солнечным Краем. Следующая наша цель – захват гавани. К несчастью, в гавань направляется флот резервистов из армии Клинков Рассвета на помощь войскам Келя.\n\nБери это масло и возьми дракондора у Айрена Ясного Неба. Тебе надо будет подлететь почти к самым парусам – как только окажешься достаточно близко, подожги их.\n\nВысадись на один из кораблей и атакуй резервистов. Когда паруса их корабля вспыхнут, они не особо будут сопротивляться.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11543] = {title = "Загнать врага в угол", objective = "Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясным Небом насчет полета до флота Клинков Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса кораблей, а приземлившись, убейте 6 резервистов из армии Клинков Рассвета.", description = "Нам удалось полностью захватить Солнечный Край. К несчастью, в гавань направляется флот резервистов из армии Клинков Рассвета на помощь войскам Келя.\n\nБери это масло и возьми дракондора у Айрена Ясного Неба. Тебе надо будет подлететь почти к самым парусам – как только окажешься достаточно близко, подожги их.\n\nВысадись на один из кораблей и атакуй резервистов. Когда паруса их корабля вспыхнут, они не особо будут сопротивляться.", progress = "Задание выполнено, Таквер?", completion = "Хорошая работа, Таквер. Нескоро теперь гавань получит подкрепление.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11544] = {title = "Оружие Ата'мала", objective = "Кузнец Хаутаа просит вас сделать для нее 5 кусков очищенного металла Ата'мала. Сделайте это, раздробив на ее наковальне оружие Ата'мала в оружейной Солнечного Края на острове Кель'Данас.", description = "Терраса Ата'мала на востоке Долины Призрачной Луны – священное место для дренеев, но ныне его захватили орки Скверны. Они добывают в тех местах особую руду, создают оружие и доспехи, полные порчи.\n\nМне нужно это вооружение, чтобы создать сплав с рудой наг. Наши анахореты благословили мою наковальню, и она может очистить их от скверны.\n\nДобудь оружие у избранных, душегубов и темнопрядов Долины Призрачной Луны. Принеси оружие сюда, раздроби его и очисти на моей наковальне и отдай мне то, что выйдет.", progress = "Мне нужно столько очищенного металла Ата'мала, |3-6(Друид), сколько я сумею переработать.", completion = "Благодарю тебя, мой друг. Теперь я смогу сделать больше специального сплава, который пойдет на изготовление оружия и доспехов для нашей армии.\n\nИ еще у меня осталось немного лишнего сплава, который наверняка пригодится тебе на оружие. Прошу – выбирай какой хочешь кусок.\n\nИ снова приходи поутру. Мне наверняка понадобится новая порция металла.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЭмульсия благословенного оружияЭмульсия праведного оружия\n\nВы также получите:\n\nПредмет #5"}
MultiLanguageQuestData['ru'][11545] = {title = "Никто не забыт...", objective = "Анахоретка Аюри из Солнечного Края у Солнечного Колодца просит вас пожертвовать 10 золотых.", description = "Мы отбили гавань Солнечного Края у врага, и окончательная победа уже не за горами. Цену мы заплатили высокую, и многие отважные бойцы положили свои жизни ради этой победы.\n\nЯ хочу, чтобы никто из погибших не был забыт. Прошу вас подумать насчет того, чтобы внести пожертвования в мемориальный фонд. Все оставшееся золото пойдет вдовам и сиротам погибших.После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][11546] = {title = "Взаимовыгодный бизнес", objective = "Мар'на из гавани Солнечного Края просит вас принести ей 5 ягод кровяники с кустов, которые можно найти на Кель'Данасе.", description = "Добро пожаловать, <имя>.\n\nЯ много чем могу помочь тебе в твоих тутошних трудах.\n\nНапример, я недавно изобрела рецепт уникального эликсира.\n\nВо многих местах Азерота в изобилии растет дикая кровяника. Ее долгое время считали ни на что не годной. Но я узнала, что если подвергнуть это растение влиянию Солнечного Колодца, оно приобретает особые свойства. И если сделать из растения экстракт и выпить, оно будет усиливать твои способности.\n\nПринеси мне ягод с ближайшего куста, и я покажу тебе, что имела в виду.", progress = "Ну, как, принес ягод?", completion = "Замечательно, Таквер.\n\nНадеюсь, это поможет тебе в твоих трудах.", rewards = "Вы получите:\n\nЭликсир из кровяники"}
MultiLanguageQuestData['ru'][11547] = {title = "Знай свою силовую линию!", objective = "Звездочет Дарнариан из святилища Солнечного Края просит вас при помощи кристалла звездочета настроить кровавый кристалл, портал на Рассветной площади и святилище наг на берегу Зеленожабрых.", description = "Нахлебники!\n\nВам все сразу вынь да положь! Вы представления не имеете, сколько надо сил затратить, чтобы создать даже самый простенький портал!\n\nНу, ничего, я научу вас уважать мои труды!\n\nВозьми этот кристалл. Настрой его на кровавый кристалл, что на западе, на Рассветную площадь, что к югу отсюда, и на святилище наг на берегу Зеленожабрых к юго-востоку.\n\nМожет, тогда ты начнешь больше ценить дар перемещений в пространстве...", progress = "Ну как, уже настроил кристалл, |3-6(Друид)?", completion = "Да-да, давай-ка посмотрим...\n\nВроде все в порядке. Хорошо. Вот твой транслокатор.\n\nЕсли полученные тобой данные ошибочны, то куда тебя занесет – никто не знает, и виноват будешь только ты.", rewards = "Вы получите:\n\nСвиток телепортации Дарнариана"}
MultiLanguageQuestData['ru'][11548] = {title = "Щедрое пожертвование", objective = "Анахоретка Аюри из Солнечного Края у Солнечного Колодца просит вас пожертвовать 10 золотых.", description = "Мы построили мемориал в честь погибших в этой битве. Хоть какое-то утешение для семей, потерявших своих любимых.\n\nЯ собираю пожертвования для сирот и вдов героев войны. Если вы можете пожертвовать немного денег, им хватит на жизнь.", progress = "Вы хотите сделать пожертвование?", completion = "У вас благородная душа, Таквер. Среди грохота войны или ликования победы легко забыть о павших. Друзья и родственники погибших благодарят вас.", rewards = nil}
MultiLanguageQuestData['ru'][11549] = {title = "Великодушный благодетель", objective = "Анахорет Каиртос просит вас пожертвовать 1000 золотых на дело анахоретки Аюри. Вас будут называть <имя> из армии Расколотого Солнца, если вы это сделаете.", description = "Ты столько <сделал/сделала> для нас, <имя>. Мы высоко ценим твою помощь.\n\nНаверное, ты уже <заметил/заметила> анахоретку Аюри? Она великодушна и умеет убеждать, но пожертвования не так щедры, как она ожидала.\n\nЕсли ты пожертвуешь внушительную сумму, я постараюсь, чтобы известия о твоем поступке разошлись широко и далеко. Что скажешь?", progress = "Вы готовы сделать пожертвование?", completion = "У вас благородная душа, и вы - достойный союзник. Отныне вас будут называть Анвалт из Расколотого Солнца, и все, кто здесь сражается, узнают о ваших деяниях!", rewards = nil}
MultiLanguageQuestData['ru'][11550] = {title = "Входи, Искуситель...", objective = "Отнесите сообщение верховному магу Нет'улу на остров Кель'Данас, к северу от Кель'Таласа.\n\nЛюбой распорядитель полетов в Стальгорне или Луносвете доставит вас до места назначения.", description = "Несмотря на все наши усилия, страшные планы Кель'таса свершились. Солнечный Колодец снова вспыхнул, готовый к прибытию Искусителя.\n\nПредмет, находящийся передо мной и ниже А'дала представляет собой нынешнее положение дел с обороной Солнечного Колодца. Вокруг него воздвигнуты мощные преграды, не дающие нам напасть на внутренние чертоги. Если когда нашему миру и была нужна помощь, так теперь.\n\nСообщи обо всем верховному магу Нет'улу на остров Кель'Данас, что к северу от Кель'Таласа.", progress = nil, completion = "Кил'джеден ведет в этот мир все силы Пылающего Легиона. Если обряд призыва свершится, наш мир снова будет повергнут в пучину хаоса. Твоя помощь на острове Кель'Данас просто жизненно необходима для успешного противостояния Пылающему Легиону.\n\nНаши маги пытаются сокрушить преграды, блокирующие походы к Солнечному Колодцу. Внеси же свою лепту в битву с Пылающим Легионом, оказав помощь наступательной группировке Расколотого Солнца.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11554] = {title = "Солдатская дружба", objective = "Твоя помощь наступательной группировке была замечена, Ревектор. Объединенные силы Алдоров и Провидцев благодарят тебя.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nУпаковка с припасами АлдоровУпаковка с припасами Провидцев"}
MultiLanguageQuestData['ru'][11555] = {title = "Уважение союзников", objective = "Ты непрестанно проявляешь себя в этой самой важной из битв, Таквер. Прошу - прими это в знак нашей великой благодарности.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nУпаковка с припасами АлдоровУпаковка с припасами Провидцев"}
MultiLanguageQuestData['ru'][11556] = {title = "Почтение боевых друзей", objective = "Без тебя мы не смогли бы сделать того, что сделали, Арчизор. Объединенных сил Алдоров и Провидцев недостаточно, чтобы сокрушить Легион и Келя. Мы рады, что у нас есть такие могучие союзники, как ты.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nУпаковка с припасами АлдоровУпаковка с припасами Провидцев"}
MultiLanguageQuestData['ru'][11557] = {title = "Восхищение всего войска", objective = "Ты - один из наших лучших бойцов, Найммитт. Твое имя будут помнить среди нас еще долго.\n\nПрошу - прими этот небольшой подарок от имени всего войска.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nУпаковка с припасами АлдоровУпаковка с припасами Провидцев"}
MultiLanguageQuestData['ru'][11558] = {title = "Опасная любовь", objective = "Возьмите заплесневелую открытку стража и отнесите ее Фенстаду Аргайлу в Подгороде.", description = "И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.\n\nДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.\n\nОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.", progress = "Был ли я прав, когда волновался? Наши идиоты-стражи поддались этой заразе?", completion = "Так это правда! Просто не могу поверить. Как это могло случиться? Дай мне немного поразмыслить. За этим должны крыться какие-то причины.", rewards = nil}
MultiLanguageQuestData['ru'][11559] = {title = "Торговля с Зимними Плавниками", objective = "Соберите 5 моллюсков Зимних Плавников и отдайте их Ахлурглгру в Приюте Зимних Плавников.", description = "Теперь, когда ты можешь говорить с Зимними Плавниками, самое время познакомиться с ними поближе. А один из лучших способов с ними познакомиться – это вступить с ними в деловые отношения.\n\nМурлоки больше всего ценят моллюсков, а торгует ими сейчас один только Ахлурглгр. На твоем месте я набрал бы моллюсков Зимних Плавников и подарил ему.\n\nМоллюсков можно набрать во рву, а также в деревне Зимних Плавников и в пещерах.", progress = "Что это? Кто это?\n\nТы ведь |3-6(человек)! Разве ты можешь говорить по-нашему?", completion = "Это мне, да? Это что, какая-то ваша уловка, да, |3-6(человек)? Нет?\n\nА-а, ну, тогда спасибо, спасибо! Будут еще моллюски – заходи в любое время, мне нравится иметь с тобой дело!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11560] = {title = "О нет, наши бедные малыши!", objective = "По поручению короля Мргла-Мргла спасите 20 головастиков Зимних Плавников. Вернитесь к королю в Приют Зимних Плавников, когда выполните задание.", description = "Как хорошо, что ты снова здесь!\n\nКогда из-за оползня в деревне напротив, обнажились пещеры, из одной из них вылез злобный лангустин, которого называют Клаксимус, и похитил малышню Зимних Плавников.\n\nЧто-то странное произошло со всеми мурлоками, погнавшимися за ним, и когда они показались вновь, то оказались подвластны ему.\n\n<класс>, ты <должен/должна> переплыть эти воды и спасти малышей Зимних Плавников в деревне и в пещерах.\n\nБудущее племени Зимних Плавников зависит от тебя!", progress = nil, completion = "Теперь, что бы ни случилось, будущее Зимних Плавников обеспечено.\n\nТебя стоит похвалить и вознаградить за бескорыстную помощь, Транделар!", rewards = "Резак лобстудараДавящее наплечьеВам дадут возможность выбрать одну из следующих наград:\n\nМерцающее кольцоДар прилива\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11561] = {title = "Они!", objective = "По просьбе Брглмургла в Приюте Зимних Плавников убейте воинов, оракулов и гарпунеров Зимних Плавников – всего 15 мурлоков.", description = "Наши сестры и братья по ту сторону стали нашими злейшими врагами. Они похитили наших малюток, выгнали нас из деревни, а убили стольких, что и не счесть.\n\nДокажи нам, чего ты стоишь, <раса>! Переплыви расселину и убей их!\n\nНесмотря на расположение, выказанное тебе нашим новым королем, это единственное, чем ты можешь попытаться добиться нашего доверия. Если потерпишь неудачу – лучше не возвращайся!", progress = nil, completion = "Я доволен. Я чую медный запах их крови на твоих руках.\n\nНеплохо для начала, |3-6(человек).", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11562] = {title = "Меня хотят очернить!", objective = "По просьбе короля Мргла-Мргла поговорите с Мрмрглмром на северо-западной стороне Приюта Зимних Плавников.", description = "Я должен сознаться в некоем... конфузе: меня шантажируют!\n\nМрмрглмр согласился почистить кое-какие мои вещи и захватил мой запасной костюм мурлока. И теперь угрожает раскрыть мою истинную природу всем остальным мурлокам.\n\nНет нужды объяснять, какой катастрофой это было бы! Кроме того, у меня есть один план, предполагающий, что костюм нам понадобится вернуть. \n\nПрошу тебя, <имя>, пойди к Мрмрглмр на другую сторону Приюта, к северу, и сделай все, что он от тебя потребует.", progress = nil, completion = "Ах-ах, ты, должно быть, тот самый так называемый королевский помощничек? Полагаю, тот ночной эльф послал тебя меня умасливать?\n\nЛадно, у меня как раз есть дельце для такого сильного создания, как ты!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11563] = {title = "Грммурглл Мрллглл Глрггл!", objective = "Принесите Мрмрглмру в Приюте Зимних Плавников голову Глрггла.", description = "Если бы твои жалкие глазенки не были так подслеповаты, тебе не составило бы труда разглядеть, что нас истребляют косатки, живущие на севере бухты!\n\nРаз уж ваш ненаглядный король ночных эльфов желает получить обратно свой парадный костюмчик, думаю, ты согласишься оказать мне услугу и добыть голову короля косаток, Глрггла, того, кто плывет против течения судеб, губя при этом надежды тех, кто услышит песнь смерти над волнами!\n\nНе медли, <раса>, не медли: пока мы тратим время на болтовню, мурлоки Зимних Плавников гибнут один за другим!", progress = "Если у тебя нет головы Глрггла, мне с тобой говорить не о чем!", completion = "Неплохо! То-то будет праздник!\n\nТеперь, когда король косаток мертв, эти махины будут драться между собой за власть, и на время оставят нас в покое!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11564] = {title = "Наваристая похлебка из косатки", objective = "По поручению Колуна Бмурглбрма добудьте и принесите 7 кусков мясистого сальника косатки. С мясом возвращайтесь к нему в Приют Зимних Плавников.", description = "Ходят слухи, <чужеземный/чужеземная:r> <раса>, что ты, возможно, охотишься на короля косаток Глрггла.\n\nВсе это очень даже хорошо, но, если хочешь отведать похлебку, за которую можно полжизни отдать, принеси мне мясистых сальников косаток, что обитают в Мерцающей бухте.\n\nПоспеши... мне нужно будет долго обрезать мясо с костей, если ты захочешь насладиться плодами своих усилий.", progress = "Ну что, принес мне мясистые сальники?", completion = "О-o да, эти куски отлично подойдут.\n\nПлюхни их тут где-нибудь. А пока можешь попробовать остатки моего вчерашнего жаркого.", rewards = "Вы получите:\n\nНаваристая похлебка из косаткиПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11565] = {title = "Запасной комплект", objective = "Верните запасной костюм короля Мргла-Мргла королю Мрглу-Мрглу в Приют Зимних Плавников.", description = "Отлично, тайна твоего короля останется со мной до тех пор, пока он не перестанет помогать нам бороться с нашими врагами.\n\nВот это доставь ему. Я как следует отчистил эту штуку, хотя не понимаю, зачем ему понадобился второй маскировочный костюм.\n\nМожет быть, у него что-то на уме касательно тебя?", progress = "У тебя с собой мой запасной костюм, Олдфэггот?", completion = "&lt;Увидев запасной костюм мурлока, король потирает принадлежности костюма.&gt;\n\nОтлично. Теперь вернемся к неотложным делам. У меня есть для тебя дело чрезвычайной важности.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11566] = {title = "Сдаться? Ни за что!", objective = "Принесите коготь Клаксимуса королю Мргл-Мргл в Приюте Зимних Плавников.", description = "Настало время положить конец этой противоестественной ситуации, <имя>! Клаксимус должен умереть, иначе у Зимних Плавников нет будущего!\n\nВозьми мой запасной костюм мурлока и спустись в пещеры Зимних Плавников, делая вид, будто хочешь сдаться. Пока у тебя в руке будет белый флаг, мурлоки не нападут.\n\nТы найдешь Клаксимуса в самом дальнем юго-западном углу пещер. Подберись поближе и покончи с ним! И принеси мне его коготь в доказательство.", progress = "Ну что, |3-6(Жрец), дело сделано? Клаксимус мертв?", completion = "Печально, но необходимо. Я заберу этот коготь, Транделар.\n\nСпасибо тебе за оказанную нам помощь. Теперь, когда Клаксимус повержен, мы, возможно, сумеем воссоединить тех мурлоков, что остались в живых, и закрыть пещеры.\n\nПрошу тебя, друг мой, прими вот это... это самое меньшее, чем я могу отблагодарить тебя за услуги!", rewards = "Закрытый шлем затерянного моряНаплечье из вымоченных шкурРжавые сетчатые поножиПерчатки из панциря крабстераВы получите:\n\nПрипасы для экспедиции в НордсколПредмет #1"}
MultiLanguageQuestData['ru'][11567] = {title = "Древняя броня Квалдира", objective = "Найдите древнюю броню Квалдира и отнесите ее Орфусу Камагуанскому в Ревущий фьорд.", description = "Да, я работал на судне, перевозившем доспехи. Мы закончили погрузку и направились обратно в лагерь, но тут на нас напал эсминец Отрекшихся.\n\nОни взяли нас на абордаж, забрали всю добычу себе, а корабль потопили.\n\nС тех пор я эти доспехи не видел. Если хочешь, возьми мою лодку в лагере Скалаваг и отправляйся на остров, где пришвартован этот эсминец. Поговори с моей бабой, Аланией – пусть она посадит тебя на бомбардировщик.\n\nДа, если найдешь эти железяки – не вздумай притащить их сюда!", progress = "Ты нашел доспехи?", completion = "Мы должны отыскать все четыре артефакта, Reng. Когда мы возвратим святыни, ты положишь их на место, в захоронения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11568] = {title = "Возвращение святынь", objective = "Используйте мешок с врайкульскими артефактами на разграбленных курганах Заградительного холма и верните на место Ледяное сердце Исулдофа, Щит Эсиритса, Посох Неистовства Бури и Древнюю броню Квалдира. Когда поручение будет выполнено, вернитесь к Орфусу Камагуанскому на Древний подъемник.", description = "<Орфус протягивает вам сумку.>\n\nВ этой сумке находятся найденные тобой артефакты. Далеко на юго-востоке есть Заградительный холм. Найди там курганы, из которых были похищены эти святыни, и верни их на место. Надеюсь, этот благородный жест умиротворит неприкаянных духов, что бродят по нашим охотничьим угодьям.\n\nКрепись, <имя>...", progress = "Дело сделано? Духи упокоились с миром?", completion = "Печальные известия, Расул. Мои люди в опасности, и их следует предупредить. Эти морские твари не пощадят Калу'ак.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11569] = {title = "Хранитель ключей Ургргрл", objective = "По просьбе Глрглрглра в пещерах Зимних Плавников раздобудьте ключ Ургргрла.", description = "Мне нужно выбраться из этих пещер! Из Хладарры, сверху, просвечивается какая-то магическая энергия и сводит всех с ума.\n\nЯ не хочу, чтобы меня взяли под контроль, как остальных!\n\nТам, ниже и к югу, в пещере, находится хранитель ключей Ургргрл; ключ от моей клетки – у него. Забери у него ключ и принеси сюда, чтобы я мог отпереть клетку и выбраться отсюда.\n\nСкорее!", progress = "Ну, где же ключ?\n\nНет, до других мне нет никакого дела. Я просто хочу убраться отсюда!", completion = "Дай же, дай мне его скорее!", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11570] = {title = "Бегство из пещер Зимних Плавников", objective = "Проводите Лургглбра в безопасное место и вернитесь к королю Мргл-Мрглу в Приют Зимних Плавников, чтобы сообщить ему хорошую новость.", description = "Замок на моей клетке выглядит не особо прочным, но глупо было бы пытаться бежать без посторонней помощи.\n\nНе подсобишь ли мне выбраться из этих пещер? Нельзя терять ни минуты, <раса>!\n\nКогда вернешься в приют, пожалуйста, дай королю знать, что со мной все в порядке. Он наверняка вознаградит тебя!", progress = nil, completion = "Превосходное известие! Так значит, Лургглбр обнаружил, что безумие вызывают испарения этих пещер?\n\nДолжно быть, магия Хладарры становится все сильнее… Война Нексуса… битва между синими и всеми прочими драконами все разгорается.\n\nСкоро нас всех в это втянут!", rewards = "Рыбачий глазоколКлинок МрглаСкипетр Зимних ПлавниковМерцающий зуб косаткиДесантный гарпунДробитель раковинВы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11571] = {title = "Обучение коммуникации", objective = "Наполните ракушку, которую дал вам король Мргл-Мргл, над останками Скольдер. Верните наполненную ракушку короля Мрглу-Мрглу в Приют Зимних Плавников.", description = "Чтобы помочь, тебе нужно научиться говорить на диалекте Зимних Плавников. В этом нам помогут силы природы и магии.\n\nВозьми эту пустую ракушку. На дне заполненного водой рва внизу обитает Скольдер – элементаль ярости воздуха и воды.\n\nКогда сразишь ее, воспользуйся ракушкой для того, чтобы уловить волшебный пар над ее останками. Принеси наполненную ракушку мне, и тогда я смогу передать тебе знание языка Зимних Плавников.\n\nТебе повезло – один друг научил меня заклинанию подводного дыхания, которое очень тебе пригодится.", progress = "Тебе удалось наполнить ракушку паром Скольдер?", completion = "Теперь я смогу использовать сущность Скольдер для внедрения в тебя моего знания языка мурлоков Зимних Плавников.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11572] = {title = "Возвращение к Атуику", objective = "Доставьте тревожные известия старейшине Атуику в Камагуа.", description = "Вернись к Старейшине Атуику в Камагуа. Надо предупредить его и остальных об угрозе, надвигающейся на них с моря. \n\n<Орфус вздрагивает.>\n\nЧтобы добраться до него, воспользуйся Древним подъемником. Но умоляю тебя, поторопись!", progress = nil, completion = "Весь Калу'ак благодарит тебя, Аркоман. Теперь мы должны подготовиться к сражению и оповестить наших братьев и сестер на море. \n\nНадеюсь, мы еще не опоздали...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЯрость шквального ветраВызыватель рассветаРог вестника\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11573] = {title = "Орфус Камагуанский", objective = "Найдите Орфуса Камагуанского на Древнем подъемнике в Ревущем фьорде.", description = "Приветствую тебя, <путешественник/путешественница>. Я – Тупобивень из племени Калу'ак. Твой народ зовет нашу расу \"клыкарр\". Недавно меня с помощником послали разведать причину странных явлений на одной из наших охотничьих троп. Но стоило нам приблизиться к западному кладбищу, известному как Заградительный холм, как на нас напали отряды нежити. Мне повезло – я смог добраться до этого лагеря, но судьба несчастного Орфуса мне не известна.\n\nНе <мог/могла> бы ты отыскать его? Мы расстались возле Древнего подъемника, что к юго-востоку отсюда. Иди вдоль обрыва и убедись, что с ним все в порядке.", progress = nil, completion = "Тупобивень жив? Ну, хоть одна хорошая новость за весь день...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11574] = {title = "Переживания на грани", objective = "По просьбе Эндоры отправляйтесь на Янтарную Гряду к северу от Крепости Песни Войны и поблагодарите местных обитателей за ее спасение.", description = "Я рассказала им все, что помню. Почему они мне не верят?\n\nЯ собирала травы у расселины. Они появились ниоткуда – темные волшебники с магическими зверями – и окружили меня!\n\nНадо мной возник волшебный ящик, он открылся и втянул меня внутрь. И когда он уже начал закрываться, тут-то и налетели мои спасители верхом на красных драконах. У меня аж дух захватило!\n\nЯ так и не поблагодарила их за спасение. Пожалуйста, <класс>, найди их и передай мою искреннюю признательность.", progress = nil, completion = "Можешь сказать своей подруге, что ее спасение было нашей обязанностью, и притом приятной обязанностью.\n\nЕе случай был лишь маленьким фрагментом большой головоломки.\n\nДаларан не жалеет усилий для раскрытия этой тайны, и, честно говоря, нам не помешала бы кое-какая помощь...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11575] = {title = "Своевременное спасение", objective = "По просьбе Мушки из Крепости Отваги отправляйтесь на Янтарную гряду к северу и поблагодарите местных обитателей за ее спасение.", description = "Я рассказала им все, что помню. Почему они мне не верят?\n\nЯ собирала травы у расселины. Они появились ниоткуда – темные волшебники с магическими зверями – и окружили меня!\n\nНадо мной возник волшебный ящик, он открылся и втянул меня внутрь. И когда он уже начал закрываться, тут-то и налетели мои спасители верхом на красных драконах. У меня аж дух захватило!\n\nЯ так и не поблагодарила их за спасение. Пожалуйста, <класс>, найди их и передай мою искреннюю признательность.", progress = nil, completion = "Можешь сказать своей подруге, что ее спасение было нашей обязанностью, и мы исполнили ее с радостью.\n\nЕе случай был лишь маленьким фрагментом большой головоломки.\n\nДаларан не жалеет усилий для раскрытия этой тайны, и, честно говоря, нам не помешала бы кое-какая помощь...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11576] = {title = "Наблюдения за расселиной: обнаружена аномалия", objective = "По просьбе Гаррена с Янтарной гряды воспользуйтесь тайнометром у аномалии утеса Западной расселины.", description = "Приветствую тебя, <раса>. Я Гаррен, из Даларана.\n\nНе так давно Расселина была еще весьма мирным местом, по крайней мере, в геотермальном отношении.\n\nОднако недавно начались все учащающиеся землетрясения, появились разломы в земле, сквозь которые проглядывают необыкновенные поля хаотической энергии.\n\nМоя задача здесь – составить список аномалий и наблюдать за ними. Мои инструменты показывают, что еще одна аномалия появилась на утесе к юго-западу отсюда.\n\nВозьми с собой этот прибор и воспользуйся им, когда найдешь новый раскол.", progress = "Тебе удалось собрать нужные мне данные, |3-6(Жрец)?", completion = "Поразительно! Это пока что самая большая аномалия.\n\nНо, боюсь, худшее еще впереди.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11578] = {title = "The \"Chow\" Quest (123)aa COPY", objective = "Убей пару кобольдов-вредителей.", description = "Эй, ты! Убей пару кобольдов-вредителей.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nСделать цыпленком\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][11579] = {title = "The \"Chow\" Quest (123)aa COPY", objective = "Убей пару кобольдов-вредителей.", description = "Эй, ты! Убей пару кобольдов-вредителей.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nСделать цыпленком\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][11580] = {title = "Осквернение огня", objective = "Оскверните большой костер Орды в Серебряном бору!", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nЗатаптывание костра\n\nВы получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][11581] = {title = "Осквернение огня", objective = "Оскверните большой костер Альянса в Западном крае!", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nЗатаптывание костра\n\nВы получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][11582] = {title = "Наблюдения за расселиной: Расколотая бездна", objective = "По поручению Гаррена с Янтарной гряды воспользуйтесь тайнометром у Расколотой бездны и возвращайтесь к нему с полученными данными.", description = "Чувствуешь? Это был уже последний толчок... а что тут творилось несколько минут назад!\n\nБоюсь, мне снова придется попросить тебя о помощи. Мои инструменты указывают, что неподалеку, к западу отсюда, глубоко под водой образовалась огромная расщелина.\n\nКак и раньше, мне нужно, чтобы ты <взял тайнометр и зафиксировал/взяла тайнометр и зафиксировала> данные этой аномалии.\n\nЯ применю заклинание, которое позволит тебе дышать под водой. Если срок действия заклинания истечет раньше, чем ты найдешь аномалию, возвращайся ко мне – я его обновлю.", progress = nil, completion = "Какая-какая она по размеру?!\n\nНевероятно! Я должен немедленно сообщить в Даларан!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11583] = {title = "Поклонение огню", objective = "Поклонитесь огню Западного края.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][11584] = {title = "Поклонение огню", objective = "Поклонитесь огню Серебряного бора.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][11585] = {title = "Бдение Адского Крика", objective = "Поговорите с Гаррошем Адским Криком в крепости Песни Войны.", description = "Тром-ка, <раса>! Добро пожаловать в крепость Песни Войны. Мое сердце поет от радости, что столь <прославленный герой Орды откликнулся/прославленная героиня Орды откликнулась> на призыв, вняв чувству долга!\n\nЭта неприступная крепость – свидетельство невероятной стойкости Орды. Через многие препятствия пришлось нам пройти, чтобы создать этот плацдарм на Нордсколе. Именно отсюда начнется наш поход к леднику Ледяной Короны, и сын Адского Крика приведет нас к успеху!\n\nГаррош ждет твоего прибытия там, внизу.\n\nЛок'тар огар!", progress = nil, completion = "Герой Орды, ты?\n\n&lt;Гаррош обнюхивает воздух вокруг вас.&gt;\n\nСтрахом пахнет…\n\n&lt;Гаррош презрительно сплевывает.&gt;\n\nТы долго не продержишься.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11586] = {title = "Бдение Адского Крика", objective = "Поговорите с Гаррошем Адским Криком в крепости Песни Войны.", description = "Тром-ка, <раса>! Добро пожаловать в крепость Песни Войны. Мое сердце поет от радости, что столь <прославленный герой Орды откликнулся/прославленная героиня Орды откликнулась> на призыв, вняв чувству долга!\n\nЭта неприступная крепость – свидетельство невероятной стойкости Орды. Через многие препятствия пришлось нам пройти, чтобы создать этот плацдарм на Нордсколе. Именно отсюда начнется наш поход к леднику Ледяной Короны, и сын Адского Крика приведет нас к успеху!\n\nГаррош ждет твоего прибытия там, внизу.\n\nЛок'тар огар!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11587] = {title = "Побег из тюрьмы", objective = "По просьбе библиотекаря Донатана с Янтарной гряды добудьте берилловый магический ключ у охотника на магов в Берилловом лагере и используйте его, чтобы освободить пленного мага из магической клетки.", description = "Приветствую тебя, <класс>. Я – Донатан, верный слуга Даларана.\n\nИзвини, я сразу к делу. У нас крупные проблемы. По всему Азероту начали исчезать маги, и мне поручено привлекать любого, кто способен помочь разгадать эту тайну.\n\nНаше расследование начнется в лагере к югу отсюда. Я призываю тебя помочь освободить одного из пленных магов, которого там держат. Для этого надо добыть ключ от магической клетки у одного из охотников на магов...", progress = nil, completion = "You have done well, &lt;имя&gt;.\n\nThe Kirin Tor graciously accept the assistance you have rendered. Know that any service you provide us will not go unrewarded.\n\nPlease, accept this humble offering as a token of Dalaran's appreciation.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11590] = {title = "Похищение", objective = "Заключите в магические оковы раненого бериллового колдуна в Берилловом лагере и возвращайтесь вместе с ним к Донатану.", description = "<имя>, у нас тут возникла проблема.\n\nЯ только что узнал, что один из наших верховных магов по пути из Даларана пропал. Точнее, пропала. Естественно, мы полагаем, что за этим исчезновением стоят охотники на магов.\n\nВремя не ждет. Мы должны сейчас же разузнать, что случилось с леди Эванор, если хотим, чтобы у нас осталась надежда на ее спасение.\n\nВозьми этот прибор. Возвращайся в Берилловый лагерь и воздействуй этим прибором на одного из берилловых колдунов, когда он будет при смерти. Это должно связать его на достаточно долгий срок, чтобы привести его сюда для допроса.", progress = "Тебе уже удалось захватить бериллового колдуна, Имбирюша?", completion = "Excellent work, &lt;имя&gt;.\n\nWe'll have him prepared for his interrogation at once.", rewards = "Следующее заклинание будет наложено на вас:\n\nAbduction: Quest Complete (Force Cast)\n\nВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11591] = {title = "Явиться в караван Стальной Челюсти", objective = "Поговорите с рубакой Десницей Гнева в караване Стальной Челюсти.", description = "Этот слабоумный, Стальная Челюсть, попытался провести наш караван с припасами напрямик через кладбище таунка!\n\nИ это тогда, когда нам только-только удалось наладить с ними отношения!\n\nВ результате караван теперь разгромлен и разметан духами таунка, которые встали из могил, через которые он поперся.\n\nСтупай на юг, <класс>, и посмотри, не сумеешь ли ты спасти положение. Я послал с караваном рубаку Десницу Гнева и нескольких других воинов.\n\nСтупай, посмотри, может ты там пригодишься.", progress = nil, completion = "Плохо дело, |3-6(Рыцарь смерти).\n\nВыносливый гонец Гордое Копыто говорит, что тут погребены его почитаемые предки…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11592] = {title = "Мы ударим!", objective = "Помогите выносливому гонцу Гордому Копыту и его налетчикам Песни Войны выжить во время нападения на караван Стальной Челюсти и прикончить дух командира соединения Стальной Челюсти.\n\nВ случае успеха доложитесь властителю Бор'гороку на заставе Бор'горока.", description = "Один из ваших – орк по имени Стальная Челюсть – пытался сэкономить себе немного времени и срезать дорогу, пройдя по нашему кладбищу. Хорошо бы это был единичный случай, нетипичный для Орды, <раса>, а не то таунка покончат с вами!\n\nНо, как мне кажется, ты хочешь помочь исправить положение. Отлично!\n\nПроклятый дух Стальной Челюсти блуждает теперь там и беспокоит останки моих предков. Мы должны положить этому конец!\n\nЕсли мы с этим справимся, отправишься с рассказом к властителю Бор'гороку на заставу к северу отсюда.\n\nНу что, <согласен/согласна>?", progress = nil, completion = "Клянусь кровью и громом! Наши едва установленные отношения с таунка спасены благодаря тебе.\n\nСпасибо за нормализацию ситуации. Ака'Магош, Транделар!", rewards = "Пояс созерцателя закатовПерчатки объятий тениСапоги тундроходаВам дадут возможность выбрать одну из следующих наград:\n\nЖаркая Песнь Войны\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11593] = {title = "Последние почести", objective = "По просьбе рубаки Десницы Гнева близ каравана Стальной Челюсти используйте факел Десницы Гнева для сожжения мертвых стражей каравана и рабочих каравана (10 тел в любой комбинации).", description = "Наши павшие заслуживают настоящего геройского погребения, но мы не можем похоронить их на священном кладбище таунка.\n\nЯ не буду просить тебя притащить сюда их тела, но – вот, возьми этот факел и отправляйся вглубь кладбища. Когда наткнешься на останки охранников и погонщиков, сожги их с помощью факела.\n\nПочти павших, <класс>!", progress = nil, completion = "Спасибо, |3-6(Рыцарь смерти). Мы – Орда, мы не оставляем наших мертвых лежать там, где их застигла смерть!\n\nНу, для начала, всего этого вообще не должно было понадобиться... Стальная Челюсть был глупцом!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11594] = {title = "Пусть обретут покой!", objective = "Упокойте 20 духов таунка, фантомных ведунов либо восставших выносливых гонцов, и сообщите об этом рубаке Деснице Гнева, который ожидает в Караване Стальной Челюсти.", description = "Это все из-за тупости командира соединения Стальной Челюсти! Хватило же ума потащить караван через погребальный курган таунка!\n\nНу что ж, сделанного не вернешь! Остается только разгребать последствия.\n\nВластитель Бор'горок велел мне помогать выносливому гонцу Гордое Копыто, чем только можно. Гонец попросил меня помочь упокоить духов его предков.\n\nЧто скажешь, <класс>? Хватит ли тебе сил на такое несложное задание?", progress = nil, completion = "Молодец, |3-6(Охотник)! Тебе, должно быть, не впервой сражаться с нежитью. Ну, а если для тебя это был первый раз, то теперь у тебя имеется ценный опыт!\n\nЭтот опыт пригодится тебе, если ты хочешь выжить в Нордсколе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11595] = {title = "Оборона крепости Песни Войны", objective = "Явитесь к властителю Разгору в хижине у южной стены крепости Песни Войны.", description = "Адский Крик в ответе за всю Орду, <имя>. Это тяжкая ноша. Так что не отказывайся от выполнения своих обязанностей из-за его дурного нрава.\n\n<Саурфанг кивает.>\n\nА ты думаешь, я мог забыть имя героя Оргриммара? Не каждый день приходится видеть голову Нефариана на пике!\n\nПлеть начала осаду этой крепости. Наши солдаты держат оборону, но мы отчаянно нуждаемся в подкреплении. Отправляйся к Разгору. Он находится под стеной крепости Песни Войны.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11596] = {title = "Оборона крепости Песни Войны", objective = "Доложитесь властителю Разгору, находящемуся в хижине на южной стороне крепости Песни Войны.", description = "Не позволяй Адскому Крику уговорить тебя пренебречь своими обязанностями в качестве воина Орды, <раса>. Здесь, на этих стылых пустошах, он несет свое тяжкое бремя, ведь неизвестно, чем все закончится – победой над Плетью или истреблением всего живого в Азероте. Именно поэтому нам требуются твоя сила и твоя мудрость.\n\nПлеть начала штурм этой крепости. Наши воины держат оборону, но отчаянно нуждаются в подмоге. Доложи Разгору. Он находится сразу за стенами крепости Песни Войны.", progress = nil, completion = "Как раз вовремя... Нерубы, кажется, удвоились в числе буквально за неделю. Мы ни от чьей помощи не откажемся.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11597] = {title = "Оборона крепости Песни Войны", objective = "Явитесь к властителю Разгору в хижине у южной стены крепости Песни Войны.", description = "Похоже, мы с тобой всегда встречаемся в самую лихую годину, <Повелитель/Повелительница> Скарабеев! Ведь в последний раз, когда мы виделись, ты тоже <спасал/спасала> мир от какой-то смертельной опасности?\n\n<Саурфанг усмехается.>\n\nТвоя помощь очень пригодится Нордсколу, что бы там ни говорил юный вождь!\n\nБудь у нас еще хоть десяток таких воинов, как ты, мы бы сейчас спокойно сидели в Оргриммаре, у жаркого очага.\n\nОтправляйся к властителю Разгору, он у главного входа в крепость Песни Войны, на юге.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11598] = {title = "Отвоевывание карьера Камня Силы", objective = "По заданию властителя Разгора из крепости Песни Войны убейте 15 неруб'арцев.", description = "В то время как крепость Песни Войны защищает со всех сторон по три метра стали и камня, этот карьер – незащищен и является первой целью для атак нерубов.\n\n<Разгор указывает на запад.>\n\nЗа этим карьером стоят тысячи воинов Плети, только и ждущие приказа к атаке. Если нерубы уничтожат наши внутренние линии обороны, нас тут же сметут легионы нежити Артеса.\n\nМы не можем этого допустить – поэтому ты <должен напасть первым/должна напасть первой> и перебить нерубов в карьере.\n\nКровь и гром, солдат! Пусть и то, и другое сопровождают тебя в бою.", progress = nil, completion = "Тебе удалось замедлить их продвижение, но все равно скоро в битву вступит еще больше. Тебе случайно не удалось найти их яйца, пока ты был в карьере?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11599] = {title = "Тассариан, мой брат", objective = "Найти Вильяма Аллертона в шахте Далечья.", description = "Недавно Вильям Аллертон, друг нашей семьи, сообщил мне, что мой брат поступил на службу сюда, в Крепость Отваги, в тот же день, что и он сам. Но дело в том, что… мой брат уже несколько лет как мертв!\n\nЯ продала все, чем владела, и приехала сюда искать Тассариана, но местные бюрократы ничего не хотят мне сообщать. Мне даже пригрозили арестом, если я буду и дальше тут ошиваться!\n\nМне нужен кто-то, кто был бы вхож к местному начальству... кто-то вроде тебя! Если ты не откажешь мне в помощи... Я слышала, что Вильям служит на шахте Далечья.", progress = nil, completion = "Труп подходит под описание Вильяма Аллертона, которое дала вам Лерисса. Как ни странно, на нем не заметно следов ни от когтей, ни от зубов…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11600] = {title = "Последние новости о Вильяме Аллертоне", objective = "Отнесите воинское удостоверение Лериссе в Крепость Отваги в Борейской тундре.", description = "Горло Вильяма перерезано чем-то острым.\n\nПри дальнейшем осмотре тела нашлась лишь единственная зацепка для Лериссы – воинское удостоверение на имя Вильяма Аллертона.", progress = "Удалось поговорить с Вильямом, Крайтеен?", completion = "Ты думаешь, Вильям стал случайной жертвой Плети? Все это выглядит весьма подозрительно.\n\nЧто-то происходит. Нам нужно найти Тассариана.", rewards = "Сапоги мореплавателяНабедренники гласа моряТопхельм из кости морской твариВам дадут возможность выбрать одну из следующих наград:\n\nТалисман тундры\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11601] = {title = "Потерянный и обретенный", objective = "Поговорите с Джеймсом Диконом в таверне в Крепости Отваги.", description = "Возможно, бедный мистер Аллертон все-таки поможет нам отыскать моего пропавшего брата!\n\n<Лерисса достает объемистую книгу, смахивающую на ту, куда записывают рекрутов.>\n\nНу да, я ее позаимствовала, и что такого? Посмотрим, какого числа он поступил на службу?\n\nВильям видел Тассариана в списке рекрутов. Значит, они поступили почти одновременно... вот он!\n\nОн записался в... отряд С? Все прочие воинские подразделения носят названия городов Альянса...\n\nА кто еще состоит в этом отряде? Где они сражаются? Нужно разузнать. Может, хозяину таверны что-нибудь известно?", progress = nil, completion = "Я мало чем могу помочь, друг. Но я знаю кое-кого, кто может.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11602] = {title = "Прервать на корню", objective = "По поручению властителя Разгора, находящегося в крепости Песни Войны, уничтожьте 10 неруб'арских яиц.", description = "Воздушная рекогносцировка карьера показала, что нерубы откладывают свои яйца на возвышениях, окружающих основание. Хитрые твари... Яйца лежат высоко и в сухом месте, подальше от центра конфликта.\n\nТебе придется вернуться туда и отследить, где лежат яйца. Найди их, разбей и уничтожь.\n\nКаждое уничтоженное яйцо – это на двадцать меньше воинов Неруба, жирующих на наших трупах.", progress = nil, completion = "Что бы мы ни делали, они все прибывают. Еще немного, и мы можем не выдержать, Мнух.", rewards = "Змеевидный длинный посохСолдатская шипастая палицаЗловещий чародейский клинокМоргенштерн лекаряДлинный лук Песни ВойныБольшой меч бойцаВы получите:\n\n"}
MultiLanguageQuestData['ru'][11603] = {title = "Истина в вине", objective = "Раздобудьте бутылку кул-тирасского вина на месте кораблекрушения к северо-востоку от Крепости Отваги и принесите старику Колберну в таверну в Крепости Отваги.", description = "Военная служба – это все, что было у старика Колберна. Когда он вышел в отставку, то продолжал живо интересоваться всем, что связано с армией, словно это было для него жизненно важно. Он знал имя каждого генерала, отряда, бригады, подразделения... буквально все. Он – человек, который тебе нужен.\n\nПроблема в том, что у него неладно с головой. Он ни с кем не станет разговаривать, пока не глотнет своего кул-тирасского вина. Тогда он тут же вспоминает о временах, когда был моряком.\n\nЯ уже давненько не получал от поставщиков этого вина. Последний торговый корабль из Кул-Тираса затонул к северо-востоку отсюда. Посмотри – может, тебе удастся раздобыть бутылку, чтобы принести ее Колберну?", progress = "<Старик смотрит на вас с отсутствующим выражением лица.>", completion = "М-мм... не слишком горькое... и не слишком сухое... Такое же, как мы пивали с ребятами в казармах в былые времена.", rewards = "Вы получите:\n\nОбжигающее вино с тмином"}
MultiLanguageQuestData['ru'][11604] = {title = "Дезертир", objective = "Найдите тюрьму во Внутренней крепости Отваги и поговорите с дезертиром.", description = "Отряд С, отряд С… хм… ерунда какая-то… Отряды называются по городам.\n\nТемнолесцев отправили в Драконий Погост. Ребят из Златоземья послали во Фьорд. А где же я…\n\nАх, да! Дезертир! В тюрьме при казармах был перебежчик. Его засадили не так давно. Он все говорил, что \"С\" значит \"самоубийство\".\n\nОтыщи этого дезертира. Возможно, он знает что-то, что тебе пригодится!", progress = nil, completion = "Чего тебе надо? И без тебя тошно!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11605] = {title = "Досточтимые предки", objective = "По просьбе старейшины Атканока, находящегося у карьера Ледяного Булыжника, отыщите статуи, предназначенные для старейшины Кесука, старейшины Сагани и старейшины Такрета.", description = "<Далекий голос эхом звучит в вашей голове, пока вы рассматриваете каменное изваяние.>\n\nНе удивляйся, <чужеземец/чужестранка>. Я – старейшина Атканок, древний предок клыкаррского народа, прославленный в свое время мастер, уже сотни лет находящийся на страже этого карьера.\n\nКарьер был опустошен, многие статуи остались незавершенными, а духи предков стали скитальцами. Поможешь ли ты мне исправить неправильное?\n\nДля начала я должен узнать имена этих неприкаянных предков. Поищи обозначения возле статуй.", progress = "<Вы снова слышите далекий голос.>\n\nУдалось ли тебе разузнать имена неприкаянных предков?", completion = "&lt;Elder Atkanok's voice greets you as you approach his statue.&gt;\n\nWell done, &lt;имя&gt;. With the names of the wandering elders, we can continue the ceremonies disrupted during the attack. However, before the elders' spirits can be led to their stones, we must calm the spirits of the murdered craftsmen and shaman. Otherwise, the ancestor spirits may never hear the ceremony's call.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11606] = {title = "Терпение – добродетель, которая не требуется", objective = "По поручению интенданта Холгота раздобудьте 15 ящиков с боеприпасами Песни Войны.", description = "Мы можем перебить всех нерубов, каких только увидим, и передавить все их яйца, какие найдем, но эти твари не перестанут прибывать, пока мы не взорвем их туннели и проходы. Конечно, мы не сможем этого сделать, не имея в арсенале мощных боеприпасов. К сожалению, большая часть наших запасов используется гоблинами и кузнецами для изготовления осадных танков и оружия.\n\nНо к счастью, есть очень неплохой запас того, что нам нужно, в карьере Силы Камня – под всей этой нерубской чепухой. Тебе нужно просто пойти и принести мне запасы.", progress = "Время на исходе, |3-6(Рыцарь смерти).", completion = "Если мои расчеты верны – что, впрочем, бывает не так уж часто – тебе понадобится от 10 до 20 глубинных сефориевых зарядов.\n\nДа-да, ты установишь этих малюток прямо в их воронки!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11607] = {title = "Заблудшие духи", objective = "Освободите дух 3 ремесленников клана Каскала и 3 шаманов клана Каскала по просьбе старейшины Атканока в окрестностях карьера Ледяного Булыжника.", description = "Во время нападения на карьер работавшие там шаманы и ремесленники были убиты. Насилие повергло мир духов в хаос, и мы не сможем отправить предков домой, если не найдем способа утихомирить духов убитых. \n\nСами враги не обращают внимания на духов, но их спутники, берилловые гончие, чуют духов и держат их в рабстве. \n\nУбей берилловых гончих и, используя высвободившуюся чистую энергию, отпусти невинные души на волю.", progress = nil, completion = "I can sense the upheaval in the spirit world beginning to calm. You have done well, &lt;имя&gt;. The spirits of the ancestors are fortunate to have your help in this time of need.", rewards = "Вы получите:\n\nПредмет #6"}
MultiLanguageQuestData['ru'][11608] = {title = "Засыпать тараканьи норы!", objective = "По поручению интенданта Холгота используйте сверток с глубинными сефориевыми зарядами для уничтожения неруб'арских воронок к югу, востоку, западу и северу от крепости Песни Войны.", description = "Север, юг, восток и запад. Вот направления, которыми тебе предстоит заняться. Вокруг крепости в карьере Камня Силы расположены 4 неруб'арские воронки.\n\n<Холгот передает вам сверток.>\n\nОсторожнее с ними, <имя>. Стоит что-то сделать не так – и ты труп.\n\nВнутри этого свертка – глубинные сефориевые заряды. Сходи ко всем неруб'арским воронкам и установи заряды в центре каждой из них. Если все пойдет как надо, туннели завалит.\n\nДавай, вперед!", progress = nil, completion = "Это их остановит – по крайней мере, я надеюсь, что остановит. В любом случае, ты свое дело сделал. А о большем орк и просить не может, так ведь?", rewards = "Набедренники болотоходцаЛатный капюшон тундроходаКираса из камня силыВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1Ярость Песни Войны\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11609] = {title = "Сбор ритуальных предметов", objective = "Принесите 6 клыкаррских ритуальных предметов старейшине Атканоку, который стоит у карьера Ледяного Булыжника.", description = "Теперь, когда духи убитых ремесленников и шаманов упокоились, мы можем завершить ритуал, прерванный нападением. Тебе придется выполнять роль, которая по традиции отводится шаману клыкарров – а для этого тебе нужно иметь все необходимые ритуальные предметы.\n\nИзготовлять новые нет времени, поэтому нужно раздобыть те, что остались от жертв нападения. Обращайся с этими вещами бережно, <имя>, ведь некоторым из них по несколько сотен лет! Возможно, тебе придется отвоевывать их у захватчиков...", progress = "Все ли ритуальные предметы удалось тебе отыскать?", completion = "&lt;Вы принесли предметы к статуе старейшины Атканока.&gt;\n\nЭтого должно быть достаточно, хотя они и в жалком состоянии, увы! А ведь некоторые из них прослужили сотни лет – и все лишь затем, чтобы их терзали и трепали какие-то варвары!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11610] = {title = "Возвращение предков", objective = "По просьбе старейшины Атканока проведите духов старейшины Кесука, старейшины Сагани и старейшины Такрета в их каменные изваяния.", description = "С твоей помощью духи предков смогут теперь направиться в достойные их обиталища – статуи, с любовью сделанные ремесленниками Каскалы и тамошним шаманом.\n\nРитуал возвращения предков был прерван во время нападения на карьер, и теперь тебе нужно будет завершить его. Возьми с собой предметы, добытые в карьере, встань перед наделенными именами статуями и продекламируй это.\n\n<Слова на странном, незнакомом языке наполняют ваше сознание, но вы запоминаете их без всякого труда.>", progress = "Ты завершил ритуал возвращения предков?", completion = "Предки нашли свои статуи и благодарят тебя, Транделар. Ремесленники Каскалы вернутся в карьер и обеспечат непрерывность рода предков. А предки будут продолжать наблюдать за тобой с интересом: похоже, твой путь только начинается.", rewards = "Оплечье мореплавателяПоножи китобояСброшенные кандалыВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1Ошейник ледяного потока\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11611] = {title = "Захваченные Плетью", objective = "По заданию штейгера Мортия из Крепости Песни Войны освободите 5 батраков клана Песни Войны.", description = "<Мортий вздыхает.>\n\nБатраки... С таким же успехом можно поставить рекламный щит с предложением бесплатной еды для неруб'аров.\n\nПонимаешь, с батраками есть проблемы: во-первых, они тупее комка глины, а во-вторых, они слабее лепрогнома. Конечно, Плеть должна была их первыми и захватить!\n\nВ этом для меня есть небольшое затруднение – должно быть, тебе понятно: если не будет батраков, кто будет заниматься тяжелым ручным трудом? Нет батраков – нет строительства.\n\nНайди и освободи моих батраков, <раса>. Если они живы, то ты найдешь их запеленатыми в паутину по всему карьеру Камня Силы.", progress = "Нет батраков – нет зданий. И – нет, мы не собираемся заменять их гоблинами. Это нам чертовски дорого обошлось бы…", completion = "Большинству из них удалось вернуться. По крайней мере, тем, у кого хватило ума сообразить, что мы внутри этих гигантских зданий из камня и металла…\n\nКак бы там ни было, ты хорошо справился с работой. Я слышал, тебе удалось освободить немало батраков.\n\nО да, ты теперь – первый парень на... ну... на крепости.", rewards = "Выцветший рабочий плащСапоги болотоходцаКольчужные рукавицы Западной расселиныНожные латы из камня силыВы получите:\n\n"}
MultiLanguageQuestData['ru'][11612] = {title = "Бой за карьер", objective = "По просьбе Этарука, находящегося у входа в карьер Ледяного Булыжника, убейте 12 берилловых охотников за сокровищами.", description = "Рад тебя видеть, <класс>. Меня зовут Этарук, и я был ремесленником здесь, в карьере Ледяного Булыжника.\n\nЯ и мои товарищи готовили новый комплект статуй для последней серии ритуалов, когда увидели, как эти таинственные синие платформы летят над плато.\n\nКогда они приземлились, карьер заполонили охотники на магов, прилетевшие на них, убивая моих товарищей и громя карьер. Если мы не остановим их, они уничтожат все наши статуи и сбегут с нашими артефактами. Поможешь ли ты мне одолеть захватчиков?", progress = nil, completion = "Теперь, когда охотники на магов знают, что народ Каскалы и союзники не сдадут карьер просто так, мы должны удвоить наши усилия и нанести им окончательное поражение.\n\nМои братья в Каскале сами подверглись нападению и не смогут оказать нам поддержку, но с твоей помощью, Сабыч, мы сможем справиться с этими грабителями.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11613] = {title = "Клятва Карука", objective = "По просьбе Карука убейте 6 скадирских налетчиков и 5 скадирских лодочников.", description = "Они называют себя квалдирами. В моем народе бытуют легенды о них; мы называем их тук-харик – \"странники тумана\".\n\nМоя деревня была разрушена этими гигантскими туманными существами. Были убиты все, кого я знал, погиб и мой отец Ариут.\n\nСогласно клыкаррским обычаям, я должен искать мести тем, кто пролил кровь моего рода.\n\nНо я всего лишь рыбак, к тому же я даже не прошел испытание совершеннолетия... Я не выстою лицом к лицу со злобными квалдирами.\n\nЕсли бы ты <мог/могла> взыскать долг крови вместо меня, я был бы очень тебе обязан.", progress = nil, completion = "Ты оказал великую услугу моему народу, Крайтеен. Однако мне придется попросить тебя еще об одной...", rewards = "Коготь клыкарраАкулий стилетКомпактный стрелопускательЖирорезкаЖезл медиумаВам дадут возможность выбрать одну из следующих наград:\n\nЦелебная палочка\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11614] = {title = "Невысказанные истины", objective = "Отыщите тенелова Лютера в карьере Камня Силы.", description = "Мы здесь по приказу Вариматаса! Цель тенеловов проста: шпионить. Ну и еще убивать помаленьку.\n\nОдин из моих лучших агентов пропал. О нем уже несколько дней ни слуху, ни духу. Я опасаюсь худшего. Нет, не того, что его убили! Это был бы идеальный вариант. Я боюсь, что он дезертировал... возможно, даже предал нас!\n\nВ последний раз его видели на севере карьера Камня Силы. Он собирал сведения о воинах Неруба. Отыщи его.\n\nЛучше бы его убили...", progress = nil, completion = "Да, мертвее не бывает… Странно, что нерубы не сожрали труп.\n\nПосле тщательного осмотра вы приходите к выводу, что это было самоубийство – Лютер отравился. Умно. К отравленному трупу нерубы на выстрел не подойдут.\n\nВ руке у Лютера зажат дневник...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11615] = {title = "Неруб'арские тайны", objective = "Доставьте дневник Лютера тенелову Бартусу в Крепость Песни Войны.", description = "Вы листаете страницы книги в поисках чего-нибудь важного. На последней странице вы обнаруживаете нацарапанное диковинными каракулями:\n\nНекролорды. Как минимум дюжина, по моим подсчетам.\n\nФермы к западу используются как какие-то чудовищные инкубаторы Плети.\n\nЖертвы – ряд за рядом.\n\nДумаю, они теперь за мной идут. Бросился к крепости. Живым я не дамся.\n\nЖуткоядый гемотоксин. Если они решат меня погрызть, их ждет сюрприз.\n\nДоставьте эту информацию Бартусу.", progress = "Он мертв?", completion = "&lt;Бартус быстро перелистывает дневник к последней странице и начинает читать.&gt;\n\nЭто очень плохие новости. Адский Крик должен быть немедленно извещен об этом.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11616] = {title = "Послание Адскому Крику", objective = "Отнесите записку Бартуса Гаррошу Адскому Крику в крепости Песни Войны.", description = "*Бартус вырывает последнюю страницу и скатывает ее в трубочку.*\n\nНемедленно доставь это Адскому Крику! А я тем временем отправлю отряд, чтобы разведать обстановку на фермах.\n\nНепременно скажи Адскому Крику, что нам понадобится подкрепление.", progress = "Это еще что такое? Мне не до пустяков!", completion = "*Адский Крик читает записку.*\n\nЭто все?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11617] = {title = "Никто не должен уйти", objective = "По поручению Этарука из карьера Ледяного Булыжника уничтожьте Северную, Восточную и Западную платформы.", description = "Я уверен, что ты <видел/видела> эти синие и белые платформы, летающие над карьером. Эти транспортные средства охотники на магов использовали для переброски своих сил, а теперь они нагружают их нашими артефактами и фрагментами наших статуй!\n\nМы должны остановить их, пока они не покинули карьер.\n\nМаленькие создания, копающиеся в карьере, носят с собой взрывчатку. Возьми их и используй для того, чтобы уничтожить три плавающие в воздухе платформы. Их вожак наблюдает за происходящим с четвертой, приземлившейся платформы, но с ним мы разберемся потом.", progress = nil, completion = "Охотники на магов поймут, что разорить наш карьер и разграбить наши артефакты не так просто, как они думали. С твоей помощью мы отвоюем карьер и все восстановим.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #3\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11618] = {title = "Подкрепление на подходе…", objective = "Отыщите тенелова Икориса на заставе у ферм Песни Войны к западу от крепости Песни Войны.", description = "<Адский Крик качает головой.>\n\nТы, возможно, не <заметил/заметила>, <раса>, но мы тут пытаемся выиграть войну. Все, кто способен сражаться, отправлены в ключевые точки. А это значит, что на такие мелкие вторжения бойцов у нас уже не осталось.\n\n<Адский Крик делает паузу, чтобы поразмыслить.>\n\nНо Бартус требует подкрепления на ферме...\n\n<Адский Крик хлопает себя по лбу.>\n\nИ он их получит! Ступай к убийцам Бартуса на фермах, к западу отсюда. И дай им знать, что подкрепление прибыло.", progress = nil, completion = "И это все?! Один-единственный |3-6(орк)? \n\nБудь моя челюсть на месте, я уронил бы ее на пол!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11619] = {title = "Геймел Жестокий", objective = "Убейте Геймела Жестокого с Берега Терзающего Бича по просьбе Карука.", description = "Моего отца убил предводитель этих разбойников, Геймел Жестокий. Он живет в пещере на берегу.\n\nС его людьми тебе покончить удалось. Доверши же начатое, <имя>! Отомсти за моего отца, и я поделюсь с тобой тем немногим, что у меня осталось.", progress = "Удалось ли тебе одолеть Геймела, |3-6(Чернокнижник)?", completion = "Да, Крайтеен, Геймел побежден! Теперь духи убитых клыкарров могут упокоиться в мире – их смерть отомщена!", rewards = "Шляпа управляющего пристаньюОплечье гласа моряВам дадут возможность выбрать одну из следующих наград:\n\nКольцо из твердого бивняОшейник из кожи гигантской черепахи\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11620] = {title = "Отцовские слова", objective = "Поищите Вихью у святилища Чешуи на берегу Терзающего Бича.", description = "Есть кое-кто, кто мог бы пролить свет на эту тайну, <раса>. Ходят слухи, что квалдиры держат живую жрицу-нагу в храме на западной стороне берега.\n\nОна-то, без сомнения, имеет все основания взъяриться на своих незваных квалдирских гостей. Возможно, моему отцу кажется, что она будет с тобой сотрудничать.", progress = nil, completion = "Хссссссссссссс! Ты явился, чтобы насмехаться надо мной, |3-6(человек)?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11621] = {title = "Табличка Левирота", objective = "Возвращайтесь к Каруку с информацией, обнаруженной вами на табличке.Вы корпите над тем, что нацарапано на табличке, пытаясь найти хоть какой-то понятный текст. Наконец, вам удается прочесть следующий фрагмент:\n\n\"Сыновья тумана востребуют тысячу душ для того, кто обитает во мраке глубин. И тогда пробудится его посланец.\"\n\nДолжно быть, это заинтересует Карука.После выполнения этого задания вы получите:\n\n", description = "Вы корпите над тем, что нацарапано на табличке, пытаясь найти хоть какой-то понятный текст. Наконец, вам удается прочесть следующий фрагмент:\n\n\"Сыновья тумана востребуют тысячу душ для того, кто обитает во мраке глубин. И тогда пробудится его посланец.\"\n\nДолжно быть, это заинтересует Карука.После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][11622] = {title = "Тайны Терзающего Бича", objective = "Найдите Вихью на развалинах Терзающего Бича в Борейской тундре.Есть некто, кто способен пролить свет на эту тайну, <раса>. Ходят слухи, что квалдиры держали живыми в храме нескольких жриц-наг.\n\nИ верховная жрица, Вихья, явно имеет причины недолюбливать их за непрошеное гостеприимство. Быть может, она расскажет тебе, что означает надпись на табличке.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Есть некто, кто способен пролить свет на эту тайну, <раса>. Ходят слухи, что квалдиры держали живыми в храме нескольких жриц-наг.\n\nИ верховная жрица, Вихья, явно имеет причины недолюбливать их за непрошеное гостеприимство. Быть может, она расскажет тебе, что означает надпись на табличке.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11623] = {title = "Визит к смотрителю", objective = "По заданию Этарука с края карьера Ледяного Булыжника убейте смотрителя Инзивиуса.", description = "Силы охотников на магов возглавляет жуткое создание по имени смотритель Инзивиус. Бесчисленные поколения моего народа охотятся на морских тварей, но таких, как этот смотритель, мы никогда не видали. \n\nОн разместился на одном из летающих дисков на верхней кромке карьера и оттуда наблюдает за происходящим. <имя>, я могу только верить, что сами предки послали тебя мне в помощь, и надеюсь, ты поможешь мне выдворить охотников на магов из этого карьера раз и навсегда.", progress = nil, completion = "Смотритель и его подчиненные, должно быть, думали, что карьер станет для них легкой добычей, но ты показал им, как они ошибались, Палсагемо. Я глубоко благодарен тебе за помощь и уверен, что предки не лишат и впредь тебя своего благосклонного внимания.", rewards = "Наручники из тюленьей кожиПерчатки гласа моряВоинский пояс пропавшего рыцаряКулачный щит ледяной стужиВы получите:\n\n"}
MultiLanguageQuestData['ru'][11624] = {title = "Небо знает", objective = "Поговорите с Империан в руинах Элдра'ната.", description = "Мне нужно выяснить, что случилось с моим наставником, предсказателем Печальным Путником!\n\nЕще недавно он наблюдал за магнатаврами у Магмота. Но только что вернулся один из его рубак, он говорит, что отряд разбит, а предсказателя утащили в недра Магмота.\n\nНо, чтобы не отправить тебя навстречу верной смерти, мне нужно посоветоваться с духами.\n\nВ руинах Элдра'ната к западу отсюда обитает элементаль воздуха, которую зовут Империан. Она мудра и, возможно, сообщит тебе нужные сведения.", progress = nil, completion = "Не глупо ли было являться сюда, маленький |3-6(нежить)? Чего ты ищешь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11625] = {title = "Трезубец Наз'жана", objective = "Отправляйтесь к дальнему северо-восточному краю Руин Терзающего Бича. Убейте Рагнара Драккарлунда, завладейте трезубцем Наз'жана, а затем отнесите его Вихье на берег Терзающего Бича.", description = "Пятьсот лет назад Азшара заключила в подводную темницу существо по имени Левирот. А теперь эти варвары хотят уничтожить труды нашей королевы!\n\nОни заняли наш город и начали приносить в жертву моих братьев, чтобы пробудить его! Когда наги кончились, они принялись за клыкарров. Их духи не будут ведать покоя!\n\nЯ помогу тебе, потому что это так или иначе поможет мне утолить мою месть. Их капитан, Рагнар, обитает в глубине Руин Терзающего Бича, в северо-восточной их части. Он владеет золотым трезубцем. Принеси мне его!", progress = "Ты уже раздобыл трезубец?", completion = "Хорошшшшшо! Мы убьем квалдирских зверей! Я покажу эти мерзавцам, что не стоит заступать путь жрице чешуи!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11626] = {title = "Посланник", objective = "Найдите Левирота в водах под айсбергом, плавающим у северной окраины Руин Терзающего Бича. Воспользуйтесь трезубцем Наз'жана, чтобы убить Левирота, и возвращайтесь к Каруку, ожидающему вас на севере берега Терзающего Бича.", description = "Раж Наз'жан был императором Терзающего Бича, когда был пленен Левирот. Сама Азшара благословила его трезубец так, что он убил бы чудовище, если бы оно попыталось бежать.\n\nТеперь он у тебя, <раса>. Хотя мне это претит, я все же отомщу этим жестоким великанам.\n\nВозьми трезубец и отправляйся в глубины под Терзающим Бичом. Там, под ближайшим к северной части берега айсбергом, ты и найдешь Левирота.\n\nВонзи трезубец в его плоть и убей его! Возвращайся потом к тому, кто тебя послал; а я не желаю больше никогда тебя видеть.", progress = nil, completion = "Духи моих соплеменников могут наконец успокоиться. Ты помог мне отомстить за отца... Может быть, однажды я тоже стану таким же сильным, как ты.", rewards = "Напульсники ледяного потокаПерчатки китобояУкусостойкий шлемНожные латы из кости морской твариВы получите:\n\nПрипасы для экспедиции в НордсколПредмет #1"}
MultiLanguageQuestData['ru'][11627] = {title = "Точка кипения", objective = "По просьбе Империан нанесите поражение Шкварчуну и Вспеннеру, а затем вернитесь к ней в руины Элдра'ната.", description = "А, это информация, которая так тебе нужна: местонахождение и состояние твоего \"предсказателя\". Хорош предсказатель – не смог предвидеть поджидающей его самого беды.\n\nТем не менее я дам тебе средства, с помощью которых можно получить знание. Но сначала сделай кое-что для меня.\n\nБез сомнения, ты <видел/видела> битву огня и воды, что протекает к югу отсюда. Шкварчун не перестает нагревать пруд Вспеннера, и поэтому эти двое враждуют уже не первый век.\n\nОтправляйся на Обугленную вершину и Кипящий пруд и убеди каждого прекратить междоусобицу.", progress = nil, completion = "Я довольна, хотя, конечно, они еще некоторое время будут ссориться.\n\nОднако тебе, прежде чем вернуться к твоей говорящей с духами, придется выполнить кое-что еще.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11628] = {title = "Нечистое должно послужить чистому", objective = "Принесите вождю Зимней Стуже в деревню Таунка'ле 5 оскверненных шкур мамонта.", description = "К северо-востоку отсюда расположен храмовый город Эн'кила – оплот Плети в Борейской тундре. Из-за его стен командующий силами Плети послал своих нерубов, чтобы окружить нас.\n\nОстаться в обороне означает смерть для моего народа, но мои советники разошлись во мнениях касательно стратегии. Дурм считает, что надо просто кинуться в атаку, а ведунья Эйри – что лучше сделать все скрытно.\n\nХрамовый город отравил окружающие земли и их обитателей. Эйри считает, что из шкур порабощенных Плетью мамонтов можно сделать плащ, который скроет от глаз Плети того, кто туда проберется.", progress = "Ты принес шкуры мамонта?", completion = "Хотя я терпеть не могу, когда столь нечистые вещи приносят сюда, в деревню, они могут дать нам преимущество над врагами.\n\n&lt;Вождь делает знак ведунье Эйри и машет рукой, чтобы шкуры поскорее убрали.&gt;\n\nПока она обрабатывает шкуры, мы займемся добыванием еще одного компонента, необходимого для изготовления плаща.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11629] = {title = "Назад, к говорящей с духами", objective = "Доставьте изначальную сущность Империан говорящей с духами Рычеклык на заставу Бор'горока.", description = "Ты <сделал/сделала> то, о чем тебя просили, и теперь я дам тебе то, чего ты желаешь.\n\nОтнеси эту изначальную сущность говорящей с духами на заставу Бор'горока. Если она мудра, то знает, какой ритуал нужен, чтобы добыть информацию, которую ты ищешь.", progress = "Транделар, ты снова здесь. Что тебе удалось узнать?\n\nЧто это за звук?", completion = "Империан дала тебе свою собственную изначальную сущность? Да, я слышу, как ревут ее ветры!\n\nЯ знаю ритуал, который нам поможет. Но надо спешить, пока ее изначальная сущность не взорвалась изнутри!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11630] = {title = "Оскверненная Плетью земля", objective = "Принесите 8 комков оскверненной Плетью земли вождю Зимней Стуже в деревню Таунка'ле.", description = "Ведунья Эйри считает, что после обработки шкур оскверненной Плетью землей из окрестностей храмового города она сделает плащ, который поможет тебе оставаться <незамеченным/незамеченной> для приспешников Плети. Ты просто сольешься с ландшафтом, так она говорит.\n\nХорошо бы, она оказалась права. Это наш единственный шанс добыть информацию и составить план контратаки.\n\nТы <должен/должна> найти нужную ей землю, покопавшись в почве к югу и к западу от крепости. Принеси ее мне, когда соберешь столько, сколько нужно.", progress = "Тебе удалось собрать землю, которая нужна ведунье Эйри для плаща?", completion = "&lt;Вождь Зимняя Стужа с предосторожностями принимает принесенные вами комки земли.&gt;\n\nМы должны передать землю в руки ведуньи Эйри как можно скорее.\n\n&lt;Вождь ворчит, пытаясь сделать вид, что его ничуть не беспокоят эти зловещего вида грязные комья.&gt;\n\nВедь мы не знаем, когда командующий силами Плети предпримет последнюю, решительную атаку на деревню.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11631] = {title = "Воздушные видения", objective = "Воспользуйтесь изначальной сущностью Империан для проведения ритуала возле тотема говорящей с духами Рычеклык на заставе Бор'горока, чтобы получить информацию о предсказателе Печальном Путнике.\n\nПосле этого поговорите с говорящей с духами Рычеклык.", description = "Вот, <имя>, я настроила для тебя изначальную сущность.\n\nОткрой ей свою душу возле моего тотема воздуха и сконцентрируйся на судьбе предсказателя Печального Путника.\n\nДух ветра соприкасается со всем на свете. Если повезет, тебе будет даровано видение.", progress = "Когда почувствуешь, что увиденного достаточно, верни мне изначальную сущность.", completion = "Они заковали его дух! Транделар, нам нужно положить конец этой пытке!\n\nТебе нужно спуститься в недра Магмота и найти способ его освободить!", rewards = "Шлем целителяКуртка из регенерирующей шкурыЗамерзшие кольчужные сапогиВам дадут возможность выбрать одну из следующих наград:\n\nКольцо хладнокровного потрошителя\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11632] = {title = "Что несет холодный ветер?..", objective = "Отнесите отвердевший панцирь Ит'рикса верховному правителю Саурфангу в Крепость Песни Войны.", description = "Вы держите в руках фрагмент панциря Ит'рикса Жнеца и понимаете, что это только начало. Даже сейчас вас одолевает ощущение непрочности победы. Бесспорно, у Короля-лича найдется еще тысяча таких тварей, как Ит'рикс, ждущих своей очереди, чтобы обрушиться на Орду.\n\nВозьмите свой трофей и передайте верховному правителю Саурфангу в Крепость Песни Войны. Его нужно известить о вашей победе над могучим посланником Плети.", progress = "Что это у тебя?", completion = "&lt;Саурфанг ухмыляется.&gt;\n\nЧто-то знакомое... Армия Калимдора раздавила тысячи таких жуков, как этот, в пустынях Силитуса.\n\nЭто иное место – иная среда – но результат будет тем же самым.\n\n&lt;Саурфанг внимательно смотрит на вас.&gt;\n\nВ Нордсколе ты принесешь Орде честь и славу, Тендернесс.\n\n&lt;Саурфанг кивает.&gt;", rewards = "Поножи пеклаВоинский пояс болотоходцаЭполеты степного охотникаКираса боевого лидераВы получите:\n\n"}
MultiLanguageQuestData['ru'][11633] = {title = "Вписаться в ландшафт", objective = "По поручению вождя Зимней Стужи отправляйтесь в храмовый город Эн'кила, наденьте прочную накидку Плети и исследуйте Шпиль Крови, Шпиль Боли и Шпиль Порчи.", description = "Ведунья Эйри закончила накидку. Возьми ее с собой и отправляйся в храмовый город Эн'кила. Накинь плащ, когда войдешь в город – он скроет тебя от большинства созданий Плети. Это будет наилучшей возможностью собрать информацию об укреплениях и военном руководстве противника.\n\nНе снимая плаща, обследуй три высоких шпиля на территории города. В то время как накидка защитит тебя от большинства созданий Плети, поганища заметят тебя, если окажешься слишком близко к ним.", progress = "Ты закончил исследование шпилей в крепости Плети?", completion = "&lt;Вождь Зимняя Стужа внимательно слушает, пока вы описываете свои наблюдения.&gt;\n\nИнформация, которую тебе удалось добыть, поможет нам составить план атаки на храмовый город. Нам нужно будет найти способ сразить указанных тобою офицеров и войти в этот некрополь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11634] = {title = "Повелитель ветра То'бор", objective = "Явитесь к повелителю ветра То'бору в крепости Песни Войны.", description = "Да, <имя>, <отец/мать> из тебя чересчур <суровый/суровая>. Думаю, твои способности лучше пригодятся в другом деле – например, чтобы ликвидировать на корню саму эту проблему!\n\n<Разгор указывает на запад.>\n\nТысяча воинов Плети, минимум четыре полноразмерных машины смерти, и неизвестно что еще.\n\nВот ты-то и выяснишь, что именно. А потом постараешься совладать с этим... Да-да, я поручаю тебе задать перцу той самой армии, что сейчас задает жару нам.\n\nОтправляйся на вершину крепости Песни Войны и поговори с повелителем ветра То'бором. Он ждет тебя.", progress = nil, completion = "Привет! Я ждал тебя\n\n&lt;То'бор указывает на запад.&gt;\n\nГлянь-ка туда. Там, за тундрой – смерть. Смерть, понимаешь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11635] = {title = "Дух предсказателя Печального Путника", objective = "Поговорите с духом предсказателя Печального Путника в глубинах Магмота.", description = "Иди к Магмоту на восток.\n\nСпустись в глубь тамошних пещер.\n\nПоговори с духом предсказателя Печального Путника!", progress = nil, completion = "Спасибо за отсрочку, |3-6(Рыцарь смерти). Ах, если бы столь же легко достижимой была моя истинная свобода!..", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11636] = {title = "Полет на ковре-самолете", objective = "Поговорите с Янни в крепости Песни Войны, чтобы организовать вам безопасную доставку на побережье. Когда прибудете в лагерь Гарроша, поговорите с крушителем Грек'лором.", description = "Танки, <дружище/сестренка>. Я об этих осадных машинах! У нас тяжелые танки есть в лагере Гарроша – ну, там, на западном берегу. Мы тебя подбросим до танка, а ты покатаешься на нем и маленько покажешь Плети, в чем ордынская правда, <брат/сестра>!\n\nПроблема будет только в том, чтобы тебя туда доставить. На ветрокрылах мы никак тебя не пошлем, факт – слишком много риска.\n\nВидишь вон того милашку? Эльфа такого блондинистого? Янни его зовут, <брат/сестренка>. Он-то может тебя на берег доставить без проблем. А как будешь там, поговори с крушителем Грек'лором.", progress = nil, completion = "НЕТ ПОЩАДЫ МЕРТВЫМ!\n\nНи у кого не хватило духу остаться защищать наши прославленные танки после того, как Адский Крик решил, что с побережья придется уйти. Теперь здесь спокойно, хотя Плеть и собирает силы для штурма крепости Песни Войны. Иногда мне удается наткнуться на заблудившегося зомби или вурдалака, но их надолго не хватает.\n\nА еще этот туман...\n\n&lt;Грек'лор вздрагивает.&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11637] = {title = "Каганишу", objective = "Добудьте амулет Каганишу и задействуйте его над останками предсказателя Печального Путника.\n\nВам нужно будет передать амулет предсказателю Печальному Путнику в Магмоте.", description = "Когда мой небольшой отряд пехотинцев был перебит, меня притащили сюда, вниз и совершили ритуальное убийство. Снобольд, который сделал это, известен под именем Каганишу.\n\nХотя ты уже <сразил/сразила> его помощников-шаманов, мой дух по-прежнему привязан к этому месту. После того как он убил меня, он изготовил амулет из моего тела, который и держит меня здесь. Каганишу использует его, чтобы узнать все, что я знаю о шаманском искусстве.\n\nТы <должен/должна> забрать у него амулет и воздействовать им на мой дух. Каганишу обитает здесь рядом, в пещерах.\n\nТолько тогда я буду по-настоящему свободен.", progress = "Поспеши, |3-6(Жрец), используй амулет, пока не стало слишком поздно.", completion = "Я свободен. Спасибо, Транделар.\n\nА теперь у меня есть к тебе еще одна, последняя просьба.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11638] = {title = "Вернуть мои останки", objective = "Доставьте останки предсказателя Печального Путника, которые покоятся под его духом, говорящей с духами Рычеклык на заставу Бор'горока.", description = "<имя>, теперь, когда мой дух свободен, не окажешь ли ты мне честь, вернув мои останки говорящей с духами Рычеклык? Они лежат на земле подо мной.\n\nЯ чую, что говорящая с духами по-прежнему на заставе Бор'горока на западе, где мы виделись с ней в последний раз.", progress = "Ты вернулся быстрее, чем я рассчитывала. Что тебе удалось выяснить?", completion = "Спасибо тебе за то, что освободил его дух от Каганишу и вернул мне его останки. Чем же тебя вознаградить? Мы не богаты, но ты можешь взять в награду то, что тебе приглянется.\n\nТеперь же я верну его туда, где ему место.", rewards = "Ветвь вечного пламениВинтовка пропавшего снайпераВам дадут возможность выбрать одну из следующих наград:\n\nКольцо иссушенияИдол вольного ловчегоМанускрипт яростных ударовТотем тундры\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11639] = {title = "Месть в Магмоте", objective = "Убейте магмотов: 10 шаманов, 5 добытчиков, 3 сокрушителя и 3 жен Магмотрегара. Затем возвращайтесь к Орторошу на заставу Бор'горока.", description = "Властитель отказывается позволить шаману исцелить мои раны. Он говорит, что это послужит мне хорошим уроком и даст мне время поразмыслить над моим провалом.\n\nНо ты можешь отомстить за меня и за тех, кто пал у Магмота!\n\nЯ знаю, что говорящая с духами хочет, чтобы ты <отправился/отправилась> туда ради спасения предсказателя.\n\nЭто совсем недалеко, к востоку отсюда. Иди, <класс>... иди, убей магнатавров и их прислужников-снобольдов. Восстанови честь заставы!", progress = nil, completion = "Честь мертвых отмщена благодаря твоим деяниям, Совух.\n\n&lt;Раненый орк кивает, медленно выдыхая.&gt;\n\nБыть может, теперь я смогу вновь стать воином, каким был когда-то.", rewards = "Многослойные обмерзшие одеянияУкрепленный шлем из шкуры карибуШипастое магмотское оплечьеНабедренники янтарной сосныВы получите:\n\n"}
MultiLanguageQuestData['ru'][11640] = {title = "Слова могущества", objective = "Принесите свиток верховного жреца Наферсета, свиток верховного жреца Талет-Ха и свиток верховного жреца Андората вождю Зимней Стуже в деревне Таунка'ле.", description = "В описанных вами башнях живут главные приспешники предводителя Плети – верховные жрецы. Они не только командуют войсками Плети: они стерегут вход в Некрополь, и к своему хозяину.\n\nНескончаемый поток порождений Плети захлестнет нас с головой, если мы не сумеем найти и обезвредить их предводителя. Я не могу оставить свой народ без защиты, как бы сильно Дурму ни хотелось перенести войну на территорию противника. Именно вам, <имя>, придется истребить верховных жрецов и забрать свитки, которые хранятся у них.", progress = "Если мы хотим прорваться через Плеть и расчистить путь жителям деревни, нужно проникнуть в этот некрополь!", completion = "*Вождь Зимняя Стужа читает то, что написано на свитках.*\n\n\"Шабтир бакх сохнен...\"\n\nЭто слова древнего, неблагозвучного языка, на котором говорят нерубы – и весьма подходящие слова:\n\n\"Слуга преклоняется перед властью господина\". Это слова, открывающие путь в некрополь!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11641] = {title = "Смелость города берет!", objective = "Убейте 15 вурдалаков и 5 некромантов из Эн'кила и доложите об этом Дурму Ледяной Шкуре, который живет в деревне Таунка'ле.", description = "С самого начала я советовал, чтобы вождь Зимняя Стужа собрал наших могучих воинов и напал на врага на его территории. Но он остался глух к моим советам и предпочел ходить вокруг да около, как предложила ведунья Эйри.\n\nЯ не собираюсь больше ждать. Если вождь Зимняя Стужа слишком труслив, чтобы отправить наших воинов в бой, может быть, ты покажешь ему, что лобовая атака может быть успешной. Ворвись в храмовый город Эн'кила и сокруши все на своем пути, <имя>.", progress = nil, completion = "Ты доказал свое бесстрашие и продемонстрировал свое воинское мастерство. Я верю, что ты стал бы хорошим воином таунка. Хотелось бы только, чтобы и вождь был того же мнения.\n\nНам повезло, что мы можем рассчитывать на тебя как на союзника в наших попытках эвакуировать деревню раньше, чем по ней ударит Плеть.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11642] = {title = "Танк сам собой не починится!", objective = "Поговорите с Мобу в лагере Гарроша.", description = "Нам нужно, чтобы эти танки были вновь на ходу! А сами собой они, ясный перец, не починятся. Отвечать за это дело будет Мобу. Поговори с ним и узнай, что ему нужно. Может быть, тебе удастся заткнуть ему рот раньше, чем он приведет меня в бешенство, и я разрублю его пополам!", progress = nil, completion = "А, так ты новый водитель танка, дружище? Сойдет! Нам нужно просто снова заставить эти штуковины ехать. Да уж, только попробуй забраться на равнины Назама без танка – и ты, считай, труп.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11643] = {title = "Танковая пневматическая трансзажиматрица Мобу", objective = "Принесите Мобу на берег Эха в Борейской тундре его танковую пневматическую трансзажиматрицу.", description = "Эти штуки бесполезны, дружище. Чтобы поставить на ход эти машинки, мне нужна моя танковая пневматическая трансзажиматрица! К сожалению, я оставил ее на прежнем месте, на другой стороне лагеря. В покосившемся домике рядом с конюшнями. Тебе придется пойти и принести мне инструмент, потому что меня хоть огнем демоническим жги – к туману я и близко не подойду.\n\nО да, дружище, берегись тумана. Это он исковеркал это побережье.", progress = "Ну, что, удалось найти мою Т.П.Т.?", completion = "Отличная работа, дружище! Ммм, и куда ж я задевал запчасти-то...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11644] = {title = "Сверхпрочные металлические пластины!", objective = "По заданию Мобу соберите 10 сверхпрочных металлических пластин и принесите ему на берег Эха в Борейской тундре.", description = "Мне нужен металл, чтобы подлатать эти танки! Сверхпрочные металлические пластины раскиданы почти по всему лагерю Гарроша и на дне залива.\n\nТолько будь осторожнее, когда пойдешь их искать. Туман, он... ну... АГРЕССИВНЫЙ! Именно туман уничтожил лагерь и соседний городок клыкарров. Бедняжки клыкарры...", progress = "Помни, туман – плохо!", completion = "Отличная работа, дружище! Тэкс, куда ж я задевал эту пневматическую трансзажиматрицу для танков?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11645] = {title = "Грязные, вонючие снобольды!", objective = "Добудьте 10 ящиков с вещами Умейки и верните их Умейке Шестеркрут на взлетной полосе Выкрутеня.", description = "Грязные, вонючие снобольды! Они разворовали все мои припасы!\n\nТы спрашиваешь, что такое снобольды? Это те же кобольды, только они служат магнатаврам, вроде как заботятся о них. Странно, да, я знаю!\n\nНо это все неважно. Не согласишься ли ты мне помочь? Я знаю, куда эти мерзкие крысы уволокли все мое добро. Поделом мне: нечего было рассчитывать, будто на северном конце полосы припасы будут в безопасности.\n\nОкажи услугу, сходи на север, в их дурацкий Магмот! Если принесешь мое добро, я в долгу не останусь!", progress = "Ну что, все мои припасы целы, |3-6(Охотник)? Я без этих вещей как без рук!", completion = "Ох, Крайтеен, какой же ты молодчина!\n\nА вот и обещанная плата…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11646] = {title = "Борейские дознаватели", objective = "По приказу Донатана пойдите к библиотекарю Нормантису в башню магов на Янтарной гряде и предложите ему свою помощь.", description = "Слушай внимательно, <имя>, поскольку приходится дорожить каждой минутой.\n\nТвоего пленника готовят к допросу тут, в нашей башне. Если он не захочет откровенничать, может потребоваться твоя помощь.\n\nСходи туда, где его содержат, и скажи библиотекарю Нормантису, что я послал тебя ему в помощь.", progress = nil, completion = "Донатан мудро поступил, прислав тебя, |3-6(Охотник).\n\nТеперь выясняется, что мне понадобится кто-то, не входящий в Кирин-Тор.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11647] = {title = "Обезвредить чумные котлы", objective = "Используйте тотем ведуньи Эйри из деревни Таунка'ле, чтобы нейтрализовать восточный котел, центральный котел и западный котел в Храмовом городе Эн'кила.", description = "Меня крайне тревожит существование чумных котлов в Храмовом городе Эн'кила, <имя>. Очевидно, что вождь Зимняя Стужа доверяет твоему благоразумию и твоим знаниям о наших врагах. Не поможешь ли ты мне изничтожить котлы вместе с тем, что ты помогаешь вождю приводить в исполнение его планы касательно Храмового города?\n\nЯ приготовила тотем, который нападет на котлы и нейтрализует их содержимое. Тебе нужно только отыскать котлы и пустить в ход тотем возле каждого из них. Каждое орудие Плети, уничтоженное нами, – это еще один шаг к победе!", progress = nil, completion = "&lt;Ведунья Эйри принимает у вас тотем.&gt;\n\nТак тотем подействовал, как надо? Чтобы его сделать, пришлось прибегнуть к древней магии, которую ведуны не использовали поколениями. До нас дошли только обрывки древних знаний...", rewards = "Многослойный обмерзший капюшонНапульсники из шкуры люторогаШипастые магмотские перчаткиЗамерзшее наплечьеВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11648] = {title = "Искусство убеждения", objective = "Используйте генератор боли против закованного бериллового колдуна, пока тот не выдаст местонахождение леди Эванор, по просьбе библиотекаря Нормантиса с Янтарной гряды.", description = "Как удачно, что ты здесь, <раса>!\n\nВидишь ли, кодекс чести Кирин-Тора не одобряет крайних мер, даже в таких отчаянных ситуациях, как теперь.\n\nНо ты – <чужестранец/чужестранка>, тебя эти ограничения не касаются, так что тебе ничто не мешает предпринять действия, необходимые для получения информации.\n\nДелай все, что понадобится. Нам нужно немедленно узнать, где держат леди Эванор!\n\nА я пока приберусь на полочках... Да, и прихвати эту старую штуковину, она тебе может пригодиться!", progress = "Ну что? Удалось тебе выяснить, где держат леди Эванор?", completion = "Отлично! Эти сведения были жизненно важными!\n\nМолодец, друг мой!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11649] = {title = "Частицы разгневанных бурь", objective = "Добудьте 5 частиц бури и принесите Империан в руины Элдра'ната.", description = "Теперь, когда эта небольшая ссора улажена, остается только помочь тебе и твоей знакомой, говорящей с духами.\n\nКак видишь, мои подданные разгневаны непрекращающейся войной между огнем и водой. Боюсь, эта битва утихнет еще не скоро, но ты сможешь извлечь из нее пользу.\n\nЯ знаю, что может тебе помочь. Отправляйся в руины и собери частицы бури.", progress = "Когда ты принесешь частицы бурь, я смешаю с ними часть своей сущности. В результате получится как раз то, что тебе надо.", completion = "Я сожалею о гибели этих бурь, но слово мое крепко... даже данное смертному существу вроде тебя.\n\nТеперь посмотрим, смогу ли я сделать что-то, что окажется тебе полезным.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11650] = {title = "Еще кое-что...", objective = "Найдите инструменты Умейки, перегруженный конденсатор и горсть песка Рокнара. Доставьте все это Умейке Шестеркрут на взлетную полосу Выкрутеня.", description = "Как ты, должно быть, <заметил/заметила>, мы устроили взлетную полосу на южной границе логова магнатавров!\n\n*Умейка бормочет себе под нос что-то нелестное насчет Выкрутеня*\n\nНаш старикашка поручил мне найти... э-э... творческое решение проблемы, потому что если с ними не разобраться в ближайшее время, они явятся и разберут нас на запчасти!\n\nТак что нам нужна твоя помощь. Вот, держи список и раздобудь все, что тут перечислено. Пожалуйста!", progress = "Что-то мне не верится, будто ты уже собрал все, что было перечислено в списке!", completion = "А, вот так-то лучше! Теперь остается только собрать все это вместе.\n\nНу да, конечно, можно подумать, ты мне чем-то поможешь!\n\nНе суетись: теперь, когда я заполучила свои инструменты, это займет всего пару секунд!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11651] = {title = "Броня крепка, и танки наши…", objective = "Поговорите с крушителем Грек'лором на берегу Эха.", description = "Спасибо за помощь, друг! Передайте там Грек'лору, что танки готовы к бою. Есть надежда, что вам удастся расчистить это место раз и навсегда!", progress = nil, completion = "При нынешнем состоянии наших кораблей и морских путей мы никак не могли доставить эту проклятую боевую машину в Песню Войны. Эти танки – все, что у нас осталось от первоначальной экспедиции. Теперь, когда они пригодны к работе, вы можете использовать их, чтобы стереть в порошок войска Плети на равнинах Назама.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11652] = {title = "Равнины Назама", objective = "Используйте ордынский осадный танк, чтобы уничтожить 100 солдат Плети и спасти 3 раненых солдата Песни Войны на равнинах Назама. Кроме того, выясните, кто возглавляет наступление Плети.\n\nВыполнив все это, отправляйтесь к Гаррошу Адскому Крику в крепость Песни Войны.", description = "Как только будешь <готов/готова>, запрыгивай в любой из танков и выезжай на равнины Назама, к юго-востоку отсюда.\n\nИспользуй вооружение танка, чтобы крушить войска Плети. Если танк застрянет, наш Фаршеватель порвет их в клочки, а мины прикончат тех, кто остался в живых! И последнее: баки с топливом стоят на равнине повсюду.\n\nПопытайся подобраться поближе к тому зданию в центре и выяснить, что там происходит.\n\nЕсли тебе удастся выполнить все это и остаться в живых, отправляйся к Адскому Крику!", progress = nil, completion = "Кел'Тузад? Так значит, это правда – Наксрамас возвращается…\n\nВозможно, я недооценивал тебя, Милитехх. Ты оказал Орде серьезную услугу. Вождь мог бы гордиться тобой!\n\n&lt;Гаррош ненадолго задумывается.&gt;\n\nЕсли этими отрядами Плети управляет Кел'Тузад, неизвестно, что еще готовит нам Король-лич. Мне нужно поразмыслить над этим, Милитехх. Можешь идти.", rewards = "Домашняя одежда Грек'лораНаплеч разведчика Песни ВойныБотинки командира танкаКираса кровавой ярости Грек'лораВы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11653] = {title = "Ха! Не такой уж ты и большой теперь!", objective = "Испробуйте прототип ультрасовременного укорачивающего излучателя Умейки на 5 магмотах-сокрушителях или женах Магмотрегара. Когда все будет сделано, вернитесь к Умейке на взлетную полосу Выкрутеня.", description = "Все будет отлично, шеф! Итак, вот что я хочу, чтобы ты сделал…\n\nВозьми мой самострел и отправляйся на север, к Магмоту. Если мы хотим иметь хоть какие-то шансы против этих монстров, то нам надо их, так сказать, подогнать под размер.\n\nДля калибровки самострела я хочу, чтобы ты убивал магнатавров, пока самострел еще действует на них. Подойдут любые сокрушители или супруги, а с мелкими не возись... малы слишком, чтобы о них беспокоиться.", progress = nil, completion = "То ись как – не сработал?!\n\nНо... но…\n\n&lt;Умейка начинает всхлипывать и готова разрыдаться.&gt;\n\nЛадно, мы это переживем. Я уже большая девочка. Попробуем найти нестандартное решение!", rewards = "Наплечная накидка КрутиухаУкрепленный эластичный поясОкольцованные напульсникиВам дадут возможность выбрать одну из следующих наград:\n\nТонкая трубка проворства\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11654] = {title = "Шпиль Крови", objective = "Поищите на Шпиле Крови информацию касательно склянки со свежей кровью.", description = "Изучая взятую склянку с кровью, вы обнаруживаете, что ее содержимое еще теплое. Кровь у жертвы, должно быть, взяли совсем недавно, она может быть еще жива.\n\nНо зачем Плети кровь? Раньше захват пленных их никогда не интересовал. Может быть, если вам удастся установить, чья это кровь, вы сможете понять, что планируют создания Плети.", progress = "Как... как ты нашел меня?", completion = "&lt;Снежный следопыт таунка плохо выглядит и еле-еле отвечает вам.&gt;\n\nЯ не... долго. Может... может, ты сможешь остановить их... прежде чем...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11655] = {title = "В туман", objective = "Убейте квалдиров, найдите 8 реликвий клыкарров и принесите их Вальтору из Пал'ии на Берег Эха в Борейской тундре.", description = "Пройдя к северу через туман, ты доберешься до лагеря Гарроша. К югу – руины моего прежнего дома, Пал'ии. Оба эти места были разорены древней силой, известной как квалдиры.\n\nЭти жуткие дикари безжалостно убили весь мой народ, а твой заставили уйти во внутренние земли.\n\nВсе, что осталось от клыкарров Пал'ии – наши личные вещи, взятые квалдирами в качестве реликвий. Хотя мы не мстительная раса, справедливость должна быть восстановлена. Реликвии клыкарров должны быть возвращены мне. Войди в туман и найди их...", progress = "Ты должен служить кровью и честью... Верни реликвии клыкарров!", completion = "&lt;Печаль охватывает Вальтора.&gt;\n\nРуины... Это все, что квалдиры оставляют после себя. Им надо преподать урок.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11656] = {title = "Показательное сожжение", objective = "По заданию Вальтора из Пал'ии с Берега Эха сожгите квалдирские корабли у Пал'ии и у лагеря Гарроша с помощью клыкаррского факела. Нужно уничтожить следующие суда: \"Змеиная Пасть\", \"Кур Драккар\", \"Молот Бора\" и \"Наковальня Бора\".", description = "Клыкаррская магия очень похожа на то, что вы зовете шаманством. Правда, мы служим стихиям иначе, чем вы, но мощь, которую мы можем вызывать, огромна.\n\n<Вальтор помахивает перед вами похожим на факел жезлом.>\n\nЯ хочу, чтобы с помощью этого клыкаррского факела ты <вернулся/вернулась> в туман и <ударил/ударила> по квалдирским судам. Три из них стоят за туманом у лагеря Гарроша, к северу отсюда, а еще один пришвартован у берегов Пал'ии, на юге. Сожги их так, чтобы все видели!", progress = "Все сделано? Корабли запылали?", completion = "Демонстрация нашего сопротивления квалдирским дикарям – может быть, именно это и нужно, чтобы спасти моих соплеменников в других лагерях. Может быть, квалдирцы пересмотрят свои действия, если уверятся, что возмездие неизбежно.", rewards = "Сапоги мореплавателяНабедренники гласа моряТопхельм из кости морской твариВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1Талисман тундры\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11657] = {title = "Поймай факел!", objective = "Поймайте подряд 4 факела, затем поговорите с мастером-огнеглотателем.", description = "Ну, факел ты теперь бросать умеешь, так посмотри, сможешь ли ты его еще и поймать!\n\nБери эту связку незажженных факелов. Ступай к костру и подбрось факел высоко в воздух. Поймай его прежде, чем он коснется земли... затем снова подбрось его в воздух! Поймай четыре факела подряд, затем возвращайся ко мне.\n\nОсторожнее! Они опасны при ударе о землю! И не пропусти ни одного! Если пропустишь, придется вернуться к костру и начать все с начала. Удачи!", progress = "Правда, весело факелами жонглировать? Только осторожнее, а то подпалишься!", completion = "Не обжегся? Если да, то дважды подумай прежде, чем играть с огнем...\n\nШучу! Все вышло здорово! И это уже не шутка. Ты – отличный огненный жонглер! Теперь иди, веселись!", rewards = "Вы получите:\n\nПылающий цветФакел жонглера"}
MultiLanguageQuestData['ru'][11658] = {title = "План Б", objective = "По просьбе Умейки Шестеркрут со взлетной полосы Выкрутеня соберите 10 комплектов одежды и знамя клана Песни Войны.", description = "Ладно, не паникуй! Ну не сработал самострел, но у нас есть и другие варианты.\n\n<Умейка щелкает пальцами.>\n\nМы собираемся отвлечь внимание от взлетной полосы! Чтобы это сделать, нам прежде всего понадобится несколько вещей.\n\n<Шестеркрут оценивающе оглядывает вас сверху вниз.>\n\nКараван Стальной Челюсти – прямо к западу отсюда – по глупости решил срезать дорогу через кладбище таунка и был уничтожен восставшими духами.\n\nОтправляйся-ка туда и стащи с мертвых орков какую-нибудь одежку. А заодно и одно из их знамен прихвати!", progress = "Нам понадобится куча их одежд, если мы хотим, чтобы все сработало как надо. Я тебе не швея... нужно просто подобрать что-нибудь, что тебе подойдет!\n\nА потом я просто пройдусь прикосновением своего инженерного гения, и вуаля! – ты будешь выглядеть так, как и надо для твоей роли.", completion = "То, что нужно, но какая вонь!\n\nЯ лучше помру, чем надену такую дрянь. Но нам нужно порыться в этих тряпках и найти что-то что будет тебе к ли... впору.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11659] = {title = "Уничтожьте шары!", objective = "Уничтожьте 5 кровавых сфер и сообщите о случившемся снежному следопыту Джунеку в деревне Таунка'ле.", description = "Они… выпускают кровь… из пленных… и вливают… в эти шары.\n\n<Глаза Грумма на миг закрываются, он роняет голову.>\n\nКровь… относят в Некрополь… кормить кровавого принца…\n\n<Грумм задыхается.>\n\nОб-бещай… что уничтожишь… кровавые… шары… сообщи Джунеку...\n\n<Снежный следопыт теряет сознание.>", progress = nil, completion = "Я опасался, что Грумм в плену, но даже не подозревал, что с ним творят такие ужасные вещи! Никогда еще не видел, чтобы кто-то проиграл битву с Плетью и остался в живых…\n\nСпасибо, что принес весточку о его судьбе, Запахтигра. Он был могучий воин, таким мы его и запомним.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11660] = {title = "Рог старого морехода", objective = "Принесите рог старого морехода Вальтору из Пал'ии на берег Эха в Борейской тундре.", description = "Квалдирский лейтенант по имени Орабус возглавлял первую волну нашествия на моих соплеменников в Пал'ии. Под его руководством были разрушены обе наших деревни, после чего Орабус скрылся в тумане.\n\nВ те далекие дни ходили слухи о роге, который лейтенант передал ткачам тумана из племени Квалдир. С помощью этого рога можно было при необходимости призвать самого Орабуса.\n\nНам нужно заполучить этот рог, отобрав его у ткачей туманов, и провести этот ритуал. Если убить предводителя, может быть, эти дикари отступят.\n\nТкачей туманов ищи у Пал'ии, к югу отсюда.", progress = "Найди рог старого морехода!", completion = "Ты должен призвать Орабуса с помощью рога старого морехода.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11661] = {title = "Орабус Кормчий", objective = "По заданию Вальтора из Пал'ии с берега Эха в Борейской тундре протрубите в рог древнего моряка, чтобы призвать Орабуса Кормчего. Когда Орабус появится, убейте его.", description = "Возьми рог и отправляйся на запад, к пристани Песни Войны. Доберись до конца пристани и протруби в рог. Этот звук должен пробудить Орабуса.\n\nУбей эту злобную тварь и возвращайся ко мне!", progress = nil, completion = "Похоже, убийство их лейтенанта только разворошило осиное гнездо. Они стали еще злее и агрессивнее, чем раньше!\n\n&lt;Вальтор вздыхает.&gt;\n\nЧто ж, дружище, ты сделал здесь все, что мог. Тебе как минимум полагается компенсация за уменьшение их числа.", rewards = "Трансборейские наручиЖилет половодьяНаголенники терзающего бичаВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1Ошейник задиры\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11662] = {title = "Найти Карука", objective = "Найдите Карука на берегу Терзающего Бича.", description = "Еще один выживший из Пал'ии – его зовут Карук – отправился на основную квалдирскую базу в Борейской тундре, далеко на юг, где когда-то было полно снега. Карук прячется в утесах, наблюдая за берегом Терзающего Бича.\n\nНайди Карука, и пусть он узнает о том, что <сделал/сделала> ты ради моего народа здесь, на берегу Эха. Из крепости Песни Войны направляйся по дороге на юг и не сворачивай с нее, пока не доедешь до берега Терзающего Бича.", progress = nil, completion = "Вальтор поступил мудро, прислав тебя ко мне, |3-6(нежить). Боги благосклонны к тем, кто восстанавливает справедливость. Ты станешь тем, кто накажет злодеев от нашего имени!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11663] = {title = "Передача сведений", objective = "По просьбе Нормантиса отчитайтесь библиотекарю Донатану на Янтарной гряде.", description = "Спасибо, <класс>! Информация, которую тебе удалось извлечь, жизненно важна для Кирин-Тора.\n\nВозвращайся тотчас же к Донатану, пока мы составляем планы спасения леди Эванор.", progress = nil, completion = "Forgive me, &lt;имя&gt;. I know that was unpleasant work.\n\nWere it not for the desperation of our circumstance I'd never have asked you to assist us in such a manner.\n\nSo... what have you discovered?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11664] = {title = "Спастись из тумана", objective = "Выведите Муту Младшую из тумана. Если вам удастся спасти Муту Младшую, поговорите со старейшиной Муту.", description = "Я слышу снаружи тварей из тумана. Их вопли сводят меня с ума, но я не решаюсь бежать отсюда. Да и куда мне идти? Они догонят меня и казнят, как и остальных...\n\nСкажи, <чужестранец/чужестранка>, далеко ли простирается туман? Может, он накрыл уже весь этот материк?\n\nБыть может, ты согласишься помочь мне вырваться из тумана? Думаю, я сумею найти дорогу обратно к моему отцу. Я все еще чувствую его живой дух. Он близко...", progress = "Ты нашел мою дочку?", completion = "Об этом шепчутся ветра, друг. Твое имя известно стихиям. Муту не забудут твоей услуги!", rewards = "Трансборейские напульсникиНаплечные пластины половодьяНарукавники Западной расселиныВам дадут возможность выбрать одну из следующих наград:\n\nСюрикен из кости кондора\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11665] = {title = "Кроколиски в городе", objective = "Принесите старине Барло детеныша кроколиска. Он рыбачит на озере Силмир на северо-востоке от Шаттрата.", description = "Привет, <парень/девчушка>. Славно, что <остановился/остановилась> поболтать со старичком, у которого дома не все ладно.\n\nТут недавно один странствующий торговец продал партию детенышей кроколисков доверчивым детишкам. А кроколиски звери дикие, многие разбежались и теперь прячутся в городской канализации.\n\nБери-ка свою лучшую удочку и забрасывай леску в Штормграде или Оргриммаре. Притащи мне одну из этих тварюг. Уж очень посмотреть хочется.", progress = "Ну, чего, еще не выудил крока из Стоков?", completion = "Вот убогая тварь! Уверен, Скалл сумеет из него сделать что-нибудь вкусненькое.\n\nДа шучу, шучу.\n\n&lt;Старина Барло хитренько подмигивает.&gt;", rewards = "Вы получите:\n\nМешок рыбацких сокровищ"}
MultiLanguageQuestData['ru'][11666] = {title = "Поймай бандюгу", objective = "Поймайте черноперого ерша и принесите его старине Барло. Он рыбачит к северо-востоку от Шаттрата на озере Силмир.", description = "Наверное, тебе приходилось слыхать о золотом ерше – их полно в реках леса Тероккар, и жрецы любят ими полакомиться. Но вот об одной рыбине ты вряд ли <слыхал/слыхала> – о ерше чернопером.\n\nЭта рыба славится хитростью, и поймать ее нелегко. Приходится подсекать в последний момент, а то объест наживку – и поминай как звали.\n\nЗабрось удочку в одну из рек Тероккара и принеси мне черноперого ерша. В озерах ловить – пустое дело, он только в проточной воде живет.", progress = "Как улов, парнишка?", completion = "Приятно посмотреть... Ты крупную рыбку выудил! Сегодня старику достанется королевский ужин.", rewards = "Вы получите:\n\nМешок рыбацких сокровищ"}
MultiLanguageQuestData['ru'][11667] = {title = "Та самая рыбка", objective = "Поймайте величайшую ильную рыбу в мире и принесите ее старине Барло. Он рыбачит к северо-востоку от Шаттрата на озере Силмир.", description = "Ильная рыба Фиглюстера – невероятная юркая придонная рыбка. Она водится в водах Награнда. Эти рыбы всю свою жизнь растут и так просто поймать себя не дадут.\n\nМного лет назад я поймал самую большую в мире ильную рыбу... ну, по моему мнению... но она перекусила леску и удрала.\n\n<Рыбак/Рыбачка> твоего уровня знает, что делать – твоя добыча ждет тебя в озерах Награнда.", progress = "Скажи – ты ее поймал?Пожалуйста, скажи, что ты поймал эту щучью дочь!", completion = "Она! Этот шрам я везде узнаю.\n\nНо, честно говоря, я думал, что она будет... побольше. Ладно. Отпущу-ка я ее и попытаюсь выловить в другой раз.", rewards = "Вы получите:\n\nМешок рыбацких сокровищ"}
MultiLanguageQuestData['ru'][11668] = {title = "Ловить креветок – это не жук чихнул", objective = "Принесите 10 гигантских пресноводных креветок старине Барло. Он рыбачит на озере Силмир на северо-востоке от Шаттрата.", description = "В озерах Зангартопи водится много крупной рыбы. Как думаешь, кого они там жрут?\n\nКреветок. Гигантских пресноводных креветок. Скалл говорил, что из креветок можно приготовить просто необъятное количество блюд.\n\nНо креветки слишком маленькие, их на крючок не наловишь. Так что тут надо применить одну уловку: распотроши колючеусую форель – и найдешь в ней пару креветок, если повезет.", progress = "Как улов, парень?", completion = "Ты и с крючком, и с ножом славно управляешься. Давай-ка сюда этих миленьких креветочек, и я дам тебе попробовать блюдо.", rewards = "Вы получите:\n\nМешок рыбацких сокровищ"}
MultiLanguageQuestData['ru'][11669] = {title = "Филе сквернокровного луциана", objective = "Принесите старине Барло чудовищного сквернокровного луциана. Старик удит рыбу к северо-востоку от Шаттрата в озере Силмир.", description = "Старик скоро пойдет охотиться. Хочу поймать рыбу-молот на побережье Азшары.\n\nБеда в том, что мне для этого нужен яд, который не смоет с остроги водой. А чтобы сделать такой яд, мне нужны железы сквернокровного луциана.\n\nЭта ядовитая рыба водится в водах полуострова Адского Пламени и в Долине Призрачной Луны. Принеси мне такую рыбину, и я буду самым счастливым на свете стариком!", progress = "Эти сквернокровики – чудо эволюции. Выживает в любых водах, даже в лаве, и единственным природным врагом этой рыбки является рыбак.\n\nНу, как, удалось рыбку поймать?", completion = "Никогда не видел такой огромной, такой уродливой рыбы. Даже представить не могу, на какую наживку ты ее ловил.\n\nПоложи тварюгу на землю, и как подохнет, я ее разделаю.", rewards = "Вы получите:\n\nМешок рыбацких сокровищ"}
MultiLanguageQuestData['ru'][11670] = {title = "Это были орки, честно!", objective = "Переоденьтесь орком Песни Войны и водрузите знамя клана Песни Войны над трупом Магмотрегара. Затем вернитесь вместе с личиной к Умейке Шестеркрут на взлетную полосу Выкрутеня.", description = "Из всех этих одежек, что тебе удалось… э-э… раздобыть, я соорудила личину орка Песни Войны. Мне пришла в голову гениальная идея объединить это с кое-каким барахлом, завалявшимся с последнего Тыквовина, так, чтобы уж наверняка никто ни о чем не догадался!\n\nВот в этом мешке – личина и знамя, которое тебе удалось вернуть. Спустись в недра Магмота и убей вождя магнатавров, Магмотрегара.\n\nЕсли ты хочешь убедить их обратить свой гнев на орков Песни Войны, тебе нужно поднять это знамя, будучи в личине.", progress = "Ну, как? Ты сделал грязное дело и подставил орков с заставы Бор'горока?", completion = "Ура-ура, все получилось!\n\nЛадненько, пусть теперь эти жуткие магнатавры и их прихвостни-снобольды сцепятся с Ордой!\n\nДаже не знаю, как тебя и отблагодарить, Аркоман!", rewards = "Ледяной укусЗазубренная ледяная перчаткаБольшой посох алчностиПлащ морозного целителяВам дадут возможность выбрать одну из следующих наград:\n\nОшейник голоса льда\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11671] = {title = "Наперегонки со временем", objective = "По поручению Донатана с Янтарной гряды уничтожьте щит в Берилловом лагере, воспользовавшись разрушителем Бериллового щита. Затем сразите Салранд и заберите найденный у нее ключ.", description = "Так значит, это правда. Она у них.\n\nЯсно, что надо сделать, <раса>. Она БУДЕТ спасена.\n\nЯ должен оставаться здесь и помочь в подготовке спасения. Я позову тебя снова – на сей раз, чтобы добыть ключ от тюрьмы. Все, что мы знаем о личности этой Салранд, так это то, что ей нельзя повредить до тех пор, пока действует ее щит.\n\nМы сделали специальное взрывчатое вещество, которое должно снять ее защиту, позволив тебе сделать то, что должно. Возвращайся ко мне, когда раздобудешь ключ.\n\nПоспеши, <имя>. Леди Эванор страдает!", progress = "Тебе удалось добыть ключ Салранд?", completion = "Сломан? \n\nДай-ка взглянуть...", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11672] = {title = "День зачисления", objective = "Поговорите с генералом Арлосом в казармах Крепости Отваги.", description = "<Пришел/Пришла> зачисляться на службу, так? В обычном случае тебе пришлось бы встать в общую очередь, как всем новобранцам. В обычном случае тебе не повезло бы, потому что пропала книга регистрации новобранцев, а я не могу никого принять, пока не будет новых книг.\n\nК счастью для тебя, <имя>, я слышал о тебе и о твоих деяниях в Запределье. По правде говоря, ты – на порядок лучше этих бедолаг. Торчать в обороне – не для тебя.\n\nИди к казармам и поговори с генералом Арлосом. Он будет более чем доволен встретиться с такой масштабной личностью, как ты.", progress = nil, completion = "Мы ожидали твоего прибытия, Крайтеен. Добро пожаловать в Нордскол.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11673] = {title = "Вытащите меня отсюда!", objective = "Проводите Бонкера Тумблевольта в безопасное место и сообщите об этом Выкрутеню Разгоняйло со взлетной полосы Выкрутеня.", description = "А я знал, что за мной рано или поздно кого-нибудь пришлют... разумеется, скорее поздно, чем рано.\n\nЯ прибыл сюда на переговоры со снобольдами, но их главный шаман, Каганишу, решил, что из меня выйдет лакомый кусочек для их Магмотрегара...\n\nПогодите... То есть как? Вас никто не присылал?!\n\nТак что, про меня просто забыли?!!\n\nНу ладно. Главное, что вы здесь.\n\nРазбейте немедленно эту цепь и идемте обратно к взлетной полосе. И можете сказать Выкрутеню, что я благополучно вернулся обратно.\n\nЕсли он, конечно, помнит, кто я такой.", progress = nil, completion = "А? Что?\n\nБонкер? Какой Бонкер?\n\nНе знаю никакого Бонкера, но поверю вам на слово. Если вы спасли кого-то из ямы Магмота, вы, несомненно, заслуживаете награды.\n\nДайте взглянуть, у меня тут как раз валялась подходящая штуковина…", rewards = "Ветвь вечного пламениВинтовка пропавшего снайпераВам дадут возможность выбрать одну из следующих наград:\n\nКольцо иссушенияИдол вольного ловчегоМанускрипт яростных ударовТотем тундры\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11674] = {title = "Ведунья Высокий Холм пропала!", objective = "Найдите ведунью Высокий Холм близ Келий Смерти.", description = "В наших землях творятся все новые таинственные дела. Одна из наших ведуний, Высокий Холм, опрометчиво отправилась на север в сопровождении всего лишь одного выносливого гонца, чтобы выяснить, что происходит близ Келий Смерти.\n\nЧто за Кельи, говоришь? Это место, священное для магнатавров. Они уходят туда в старости, чтобы умереть. Так вот, Высокий Холм видела, как что-то упало с неба несколько дней тому назад.\n\nЕсли ты друг таунка, поди и отыщи ее. Она упряма, но не настолько, чтобы отвергнуть твою помощь.", progress = nil, completion = "Тебя прислала бабушка? Она, должно быть, недовольна мною.\n\nНо когда я увидела огромный предмет, падающий с неба, я не смогла заставить себя дождаться, пока соберется целый отряд выносливых гонцов и снежных следопытов. Знание не ждет медлительных!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11675] = {title = "Достойная смерть", objective = "Уничтожьте 10 чумных магнатавров и возвращайтесь к ведунье Высокий Холм, которая ждет вас к югу от Келий Смерти.", description = "Магнатавры в Кельях Смерти страдают от чумы. Мы должны выяснить причину заражения, но сначала нужно избавить их от страданий.\n\n<раса>, тебе нужно пойти на север, подняться по склонам, что впереди, и уничтожить как можно больше несчастных созданий.", progress = nil, completion = "Что еще мы можем сделать, кроме как таким образом облегчить их страдания? В любом случае, сюда они пришли умирать, так что не оплакивай их. По крайней мере, благодаря тебе они достойно встретили смерть.\n\nА теперь мы должны положить конец тому, что явилось причиной чумы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11676] = {title = "Наконец-то свобода!", objective = "Освободить 5 узников Плети по просьбе тенелова Канариуса с заставы у ферм Песни Войны.", description = "Солдат, которых они не убили, держат в клетках, разбросанных по этому участку. Нам удалось украсть несколько ключей, но подобраться к пленным поближе так и не вышло: нас тут же атакуют.\n\nНам нужны твои \"дарования\", чтобы раздобыть все ключи и освободить пленников. Вышиби мозги некролордам и аберрациям и забери у них ключи. Открой ключами клетки и освободи пленников Плети.", progress = nil, completion = "Каждый спасенный пленник – это одной аберрацией меньше, Скэритерри. Орда тебе многим обязана.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #5\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11677] = {title = "Остановить чуму!", objective = "Используйте очистительные семена ведуньи Высокий Холм у чумного котла в Кельях Смерти, чтобы нейтрализовать его, по просьбе ведуньи Высокий Холм, стоящей к югу от Келий Смерти.", description = "Я уверена, что чуму вызывает нечто, находящееся в тамошних пещерах.\n\n<класс>, возьми эти семена. Я обычно использую их как оберег против Плети, но, быть может, они помогут избавиться и от той напасти, что обитает в Кельях.\n\nОтыщи источник заразы и брось туда эти семена.", progress = nil, completion = "&lt;Ведунья опускает голову и вздыхает с облегчением.&gt;\n\nХорошее начало. Если бы это еще была единственная наша проблема…", rewards = "Повязки пеклаМаска из шкуры люторогаБоевой пояс степного охотникаЗамерзшие латные наплечникиВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11678] = {title = "Поиски Торчащего Рога", objective = "Найти выносливого гонца Торчащего Рога в Талрамасе.", description = "Торчащий Рог давно уже должен был вернуться!\n\nЕще одна причина, по которой мы пришли сюда – это необходимость разведать, что это за сооружение на западе, принадлежащее Плети, свалилось с неба. А Торчащий Рог нетерпелив, и, скорее всего, попал в беду…\n\nПрошу тебя, <имя>, сходи туда и найди его.", progress = nil, completion = "Мне… недолго… осталось, |3-6(нежить)…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11679] = {title = "Воссоздание ключа", objective = "По поручению Донатана поговорите с Сурристразом на Янтарной гряде.", description = "Задержки, задержки... Это единственное, чего мы никак не можем позволить себе именно сейчас!\n\nХотя мне очень не хотелось бы беспокоить лорда Сурристраза, он и только он способен спасти нашу дорогую Эванор.\n\nПринеси ему фрагменты ключа и надейся, что он будет в хорошем расположении духа.\n\nИ не задерживайся, <класс>, наша штурмовая бригада уже готова.", progress = "Ты смеешь приблизиться ко мне, смертное существо?\n\nРади твоих еще нерожденных детей – молись, чтобы твое дело стоило моего беспокойства.", completion = "Эти детские игры, в которые вы здесь играете, не имеют никакого значения…\n\nТы вместе со своими даларанскими друзьями – вы хватаетесь за отдельные болтающиеся ниточки, когда рвется ткань мироздания.\n\nОднако для моих драконов это может оказаться неплохим развлечением, в котором они нуждаются.\n\nПокажи-ка мне этот ключ...", rewards = nil}
MultiLanguageQuestData['ru'][11680] = {title = "Полетаем?", objective = "Отдайте ключ Салранд боевому магу Анзиму, когда будете готовы освободить Эванор.\n\nПрилагается предмет: \n", description = "Ключ воссоздан.\n\nА теперь внемли моему совету, <раса>. Добейся успеха или умри… потому что если хоть одна чешуйка упадет с любого из моих драконов, отвечать за это будешь лично ты. \n\n<Свободен/Свободна>.", progress = nil, completion = "Вот он! Ключ – наш!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11681] = {title = "Спасение Эванор", objective = "Отправляйтесь с боевыми магами и освободите леди Эванор из Бериллового лагеря по просьбе Анзима с Янтарной гряды. Затем явитесь к ней в башню магов на Янтарной гряде.", description = "Наконец-то мы атакуем!\n\nКак только очистим платформу, я использую ключ.\n\nА вы позаботьтесь о том, чтобы леди Эванор осталась цела и невредима после освобождения.\n\nВперед! Скорей!", progress = nil, completion = "Ваши героические деяния не будут забыты, |3-6(Охотник)!\n\nПрошу вас, примите это вместе с моей искренней благодарностью.", rewards = "Пояс пеклаОбгоревшие ботинкиМерцающие кольчатые перчаткиВымоченный воинский поясВы получите:\n\n"}
MultiLanguageQuestData['ru'][11682] = {title = "Беседа с драконом", objective = "Поговорите с Сурристразом по приказу леди Эванор с Янтарной гряды.", description = "Мне известно о твоих деяниях, <имя>. Еще раз благодарю тебя.\n\nЧто касается местной угрозы, мы уже узнали от них все, что было нужно. Вскоре с ними будет покончено. Однако впереди более важные дела…\n\nТы <нужен/нужна> Азероту. Землям к западу отсюда грозит серьезная опасность.\n\nПодробности тебе расскажет лорд Сурристраз. Тебе нужно срочно поговорить с ним.\n\nУдачи тебе, друг Даларана!", progress = nil, completion = "А, |3-6(человек), вот и довелось нам встретиться снова!\n\nВпрочем, когда ты услышишь мои слова, ты пожалеешь об этом.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11683] = {title = "Упавший некрополь", objective = "Уничтожьте 20 созданий Плети любого вида в Талрамасе и Гнойных прудах. Затем возвращайтесь к ведунье Высокий Холм, находящейся к югу от Келий Смерти.", description = "Упавший некрополь к западу отсюда наверняка по-прежнему кишит созданиями Плети.\n\nБудешь рядом с Талрамасом, <раса>, пожалуйста, разберись с любыми прислужниками Короля-лича, которых только найдешь там и в окружающих место его падения прудах.", progress = nil, completion = "Спасибо, Сабыч.\n\nКороль-лич и его Плеть – нарыв на теле Нордскола. Нам нельзя останавливаться, пока они не умрут истинной смертью, а его существованию будет положен конец!", rewards = "Многослойные обмерзшие сандалииУкрепленный нагрудный доспех из шкуры карибуВоинский пояс янтарной сосныВам дадут возможность выбрать одну из следующих наград:\n\nФиал обновления\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11684] = {title = "Исследование воронок", objective = "По просьбе Великого Отца Махана, находящегося в деревне Таунка'ле, отметьте на карте Поля Гейзеров Южную воронку, Северо-западную воронку и Северо-восточную воронку.", description = "Чувствуешь, как дрожит почва?\n\nЭто нерубы из Плети движутся глубоко под землей. Они показались к юго-западу отсюда, на Поле Гейзеров, и нападают на патрули, высланные вождем Зимней Стужей.\n\n<Старейшина таунка передает вам потрепанную карту.>\n\nМожет быть, одиночка сможет добиться успеха там, где потерпели неудачу патрули. Возьми с собой на Поле Гейзеров эту карту и отметь на ней воронки, через которые вылезают нерубы.", progress = "Ну что, все воронки отмечены на карте?", completion = "&lt;Великий Отец Махан берет у вас карту, но даже не смотрит на нее.&gt;\n\nТвою информацию мы используем позже, когда будем готовы осуществить наш план.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11685] = {title = "Сердце стихий", objective = "Принесите 5 сердец элементалей укротителю ветра Баре в деревне Таунка'ле.", description = "Теперь, когда мы точно знаем местоположение нерубских воронок, мы можем их обрушить, чтобы остановить наступление Плети. Укротитель ветра Бара знает способ подчинить себе элементалей, чтобы уничтожить туннели, которыми пользуются воины Неруба. Но ей потребуется твоя помощь.\n\nК юго-востоку от деревни, близ побережья за Студеным пределом, найдешь местность, где владычествуют замороженные земляные элементали. Укротителю ветра Баре потребуются сердца этих стихий.", progress = "Великий Отец Махан говорит мне, что ты согласился помочь обрушить туннели...", completion = "Этого должно хватить, чтобы создать основу для могущественного элементаля, однако одного камня недостаточно, чтобы вдохнуть в него жизнь…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11686] = {title = "Фермы Песни Войны", objective = "Разведать положение дел в Амбаре Песни Войны, на ферме Торпа и на скотобойне Песни Войны по просьбе тенелова Икориса с заставы у ферм Песни Войны.", description = "Согласно запискам Лютера, Плеть теперь использует это место, чтобы разводить чудищ, подобных тем, которые бродят по полю.\n\n<Икориса передергивает.>\n\nА ведь когда-то это были орки… таурены…\n\nДля того чтобы решить, как с этим бороться, нужны более точные сведения. Прошу тебя исследовать три места, сильно зараженных Плетью: Амбар Песни Войны, к юго-западу от нас, ферму Торпа, на запад отсюда, и старую скотобойню Песни Войны, что на севере.\n\nРазузнаешь, что к чему, возвращайся сюда.", progress = nil, completion = "Все куда хуже, чем описано в дневнике Лютера! Порождения Плети здесь повсюду, они заражают все, к чему прикоснутся!\n\n&lt;Икорис кивает.&gt;\n\nДело становится все хуже и хуже, хотя, казалось бы, хуже некуда…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11687] = {title = "Доктор и Лич-Лорд", objective = "Убейте доктора Щербохмыла и Лич-Лорда Хладолюта. Затем вернитесь к ведунье Высокий Холм, которая ждет вас к югу от Келий Смерти.", description = "Нужно… убить… двоих…\n\nДоктор и… лич-лорд… они наверху. Найди их… убей… пока…\n\nПока не поздно…", progress = nil, completion = "Торчащий Рог мертв?\n\nАх, не следовало отпускать его сюда одного!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11688] = {title = "Проклятые грязные свиньи", objective = "По просьбе фермера Торпа с заставы у ферм Песни Войны убейте 10 неживых кабанов.", description = "Только погляди на них! Мои красавцы кодо беспомощны и не в состоянии защититься от этих грязных свиней! Мне нужно, чтобы ты <помог/помогла> мне выиграть время, <раса>. Я думаю, что смогу вылечить кодо от их болезни, но нужно держать этих неживых кабанов подальше от них, а то лечить будет уже некого!\n\nИди и отправь хряков в землю навечно!", progress = nil, completion = "Кажется, получилось, |3-6(орк)!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11689] = {title = "Вестник печали", objective = "Поговорите с Великой Матерью Тайгой в деревне Таунка'ле.", description = "Великая Мать должна узнать об этом, <имя>.\n\nМожно попросить тебя вернуться в Таунка'ле? Скажи ей, что я вскоре прибуду.", progress = nil, completion = "Какие вести от ведуньи Высокий Холм несешь ты?\n\n&lt;Вы рассказываете о том, что вам известно, и передаете Великой Матери печальные известия о выносливом гонце Торчащем Роге.&gt;\n\nМой... мой внук!\n\n&lt;Великая Мать всеми силами пытается сдержать эмоции.&gt;\n\nОн погиб достойной смертью, как настоящий таунка!\n\nТы последний, кто был рядом с ним, Джайлор, так что часть его навеки останется с тобой. Я благодарю тебя за исполнение его последней воли.", rewards = "Укрепленные сапоги из шкуры карибуШипастый магмотский нагрудникЛатный шлем янтарной сосныВам дадут возможность выбрать одну из следующих наград:\n\nОчищающий талисман великой материКольцо мерзнущего целителя\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11690] = {title = "Верни их живыми!", objective = "Спасите 8 зараженных кодо по просьбе фермера Торпа с Заставы у ферм Песни Войны.", description = "Вот уздечка, <имя>. Внутри удил спрятан небольшой контейнер с лекарством. Это лекарство исцелит кодо, как только животное прикусит удила. Вылечив кодо, его нужно привести домой. На нем можно будет ехать верхом, но животное будет слабым после болезни, так что ехать надо медленно.\n\nПриведи моих малюток домой, <имя>!\n\nДа, и последнее: на все про все у тебя десять минут! После этого противоядие внутри удил потеряет силу.", progress = "Уведи их с этих полей, запятнанных Плетью!", completion = "Ты настоящий герой, Скэритерри! Если бы не ты, мои кодо бы все перемерли. Я тебе признателен, как и все солдаты и путники, которым эти кодо пригодятся в Нордсколе!", rewards = "Трансборейский уборНагрудник болотоходцаПоножи Западной расселиныНаплечье из камня силыВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11691] = {title = "Призовите Ахуна", objective = "Принесите тотем магмы Служителей Земли к Камню Льда.", description = "Мы с моими шаманами собрали все наши силы для борьбы с Повелителем Холода. <имя>, быть тебе <защитником/защитницей> Матери-Земли.\n\nВозьми этот тотем магмы. Установи его напротив Камня Льда, к северо-востоку от него. Ахун при помощи этого камня тянет силу. Мы надеемся, что тотем разрушит камень и разорвет связь с тем миром, где затаился этот элементаль.\n\nЕсли судьба будет к нам благосклонна, то мы, наверное. сумеем победить его.\n\nГотовься к битве, <имя>. Если придется сражаться с Ахуном, то ярость его будет неизмерима.", progress = "В кристалле льда слышится далекий отголосок скрежета наступающих ледников. Исходящий от него холод заставляет думать о бесконечной мертвой зиме.", completion = "Из тотема магмы близ камня льда вырываются три языка пламени. Камень мерцает, затем исчезает...", rewards = "Следующее заклинание будет наложено на вас:\n\nАхун - стих вызывания, аура\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][11692] = {title = "В поисках Бикси", objective = "Как и просил вас Мордл Шестеренок, отправляйтесь на поиски Бикси Винтодер к югу от Келий Смерти.", description = "У тебя репутация настоящего героя. А у меня опять проблема!\n\nМой начальник, Тинки, отправился с Бикси Винтодер на восток, а я не могу добиться, чтобы выхлоп на этой штуке шел как следует! Тинки – единственный, кто может это поправить, а нам обязательно нужно, чтобы все на сто процентов работало.\n\nКак думаешь, тебе удалось бы их найти? Бикси говорила что-то о следовании за какими-то старыми магнатаврами к месту под названием Кельи Смерти.\n\nПодозреваю, там-то ты их и найдешь.\n\nМожешь отправиться туда, поговорив с Карой Тризведкой у взлетной полосы.", progress = nil, completion = "Что тебе нужно, |3-6(Паладин)?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11693] = {title = "Только не чумной магнатавр!", objective = "Убейте 10 чумных магнатавров и возвращайтесь к Бикси Винтодер к югу от Келий Смерти.", description = "Мы с Тинки пришли сюда, выслеживая старого магнатавра. Похоже, в эти пещеры они сходятся умирать.\n\nРазумеется, мы и понятия не имели, что, входя сюда, они заражаются какой-то болезнью. Нельзя допустить, чтобы заразные твари бродили на свободе. Это нездорово!\n\nПослушайте, может, вы уложите несколько штук этих тварей, пока я соображу, что нам делать дальше?", progress = nil, completion = "Вы отлично потрудились, но на вашем месте я бы приняла душ при первой же возможности!\n\nНу, а теперь давайте разберемся с проблемой всерьез.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11694] = {title = "В пещерах что-то происходит...", objective = "По просьбе Бикси Винтодер, что прячется к югу от Келий Смерти, всыпьте лечебный порошок Бикси в чумной котел в Кельях Смерти, чтобы нейтрализовать отвар в нем.", description = "Пока ты там с этими чумными зверьми <разбирался/разбиралась>, мне удалось заглянуть в те пещеры наверху.\n\nОказывается, там засели сектанты, которые и наводят чуму на зверей!\n\nОни готовят в котле какой-то ядовитый отвар. У меня есть порошок, который я обычно использую в качестве противоядия, и я подмешала к нему еще кое-что. Я думаю, это должно нейтрализовать отраву в котле!\n\nСходи с порошком в одну из пещер и посмотри, сработает ли.", progress = nil, completion = "Я знала, что у тебя получится. А теперь – есть кое-что еще, о чем я хотела бы тебя попросить.", rewards = "Повязки пеклаМаска из шкуры люторогаБоевой пояс степного охотникаЗамерзшие латные наплечникиВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11695] = {title = "Рог неистовства стихий", objective = "Добудьте нижнюю половину рога и верхнюю половину рога у вождя Бурблгубля и вождя Гурглбугля и принесите их укротителю ветра Баре в деревне Таунка'ле.", description = "Я могу изготовить подобие элементаля из этих кусков бездушного камня, однако вдохнуть в них жизнь – дело другое. Тут нам потребуется помощь и немного удачи.\n\nВ легендах говорится о древнем артефакте, который назывался рогом неистовства стихий. Я одолжу тебе свиток с текстом легенды. Не знаю, правда ли это, но больше нам рассчитывать не на что. Если легенда не лжет, части рога могут находиться на Затопленных равнинах, прилегающих к деревне с севера и с юго-запада.", progress = "Удалось ли тебе отыскать рог? Правдива ли легенда?", completion = "&lt;Бара берет у вас обломки рога и пытается соединить их.&gt;\n\nШтормовое Копыто гордился бы тобой, Джайлор. Быть может, когда мы покончим с Плетью, я возьму с собой этот рог и отправлюсь на могилу Штормового Копыта…", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11696] = {title = "Ахун явился!", objective = "Найдите Луму Матерь Небес в Узилище.", description = "Хвала благим силам, <имя>, что ты здесь. В этой пещере затаился Ахун, собирая силы для нападения. Силы Служителей Земли уже выступили, но в одиночку им не справиться.\n\nРазведай обстановку, <имя>. Найди наших шаманов из Служителей Земли и поговори с их предводительницей, Лумой Матерью Небес. Возможно, с твоей помощью мы разгромим Ахуна прежде, чем свершится непоправимое!", progress = nil, completion = "Хлад Ахуна растекается по этим пещерам, Мерандир, семя леденящей погибели, что ждет нас, если он наберется сил. Хвала Матери Земле за то, что она прислала тебя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11697] = {title = "Тинки в некрополе!", objective = "Отыщите Тинки Свистопляс внутри Талрамаса.", description = "Говорила я Тинки, чтоб не ходила одна, но нет, ей же надо было проверить этот разрушенный Некрополь к западу отсюда!\n\nЯ на сто процентов уверена, что те сектанты выползли из этого Некрополя. А это значит, я на сто процентов уверена, что Тинки в беде!\n\nА ведь она – лучший инженер у нас на взлетной полосе! Без нее нам кранты!\n\nЯ бы сама ее отыскала, но одна из этих тварей ранила меня в ногу прежде, чем я успела смыться. <имя>, если кто может ее выручить, то только ты!", progress = nil, completion = "Ау! Ты кто?\n\nТебя Бикси прислала? Отлично, давай вытащим меня отсюда!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11698] = {title = "Может, проще уничтожить Плеть?", objective = "Уничтожьте 20 воинов Плети любого рода в Талрамасе и Гнойных прудах. Потом вернитесь к Бикси Винтодер к югу от Келий Смерти.", description = "Если сектанты в этих пещерах пережили катастрофу, то приходится предположить, что и в упавшем некрополе на западе по-прежнему кишат воины Плети. Да и в прудах их, наверное, пруд пруди!\n\nБудешь рядом с Талрамасом, <класс>, пожалуйста, разберись с любыми прислужниками Короля-лича, которых только найдешь!", progress = nil, completion = "Спасибо, Аркоман! Король-лич и Плеть действительно ужасны, но нам нельзя останавливаться, пока мы не уложим их всех обратно в могилы!", rewards = "Многослойные обмерзшие сандалииУкрепленный нагрудный доспех из шкуры карибуВоинский пояс янтарной сосныВам дадут возможность выбрать одну из следующих наград:\n\nФиал обновления\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11699] = {title = "Я застряла в проклятой клетке… но ненадолго!", objective = "Найдите кристалл энергетического ядра, магический гироскоп и направляющий камень Плети и отдайте их Тинки Свистопляс в Талрамасе.", description = "Сектанты с помощью магии засадили меня в эту клетку без дверей. Ха! Они не знают, что у себя на взлетной полосе я – главный инженер передачника!\n\nС твоей помощью, немного повозившись, я отсюда выберусь в два счета!\n\nМне потребуется кристалл энергетического ядра одного из здешних вурдалаков, магический гироскоп их доктора и направляющий камень Плети Лич-Лорда, там, наверху.\n\nС помощью всего этого добра я сумею изготовить телепортационное устройство, которое позволит смыться отсюда по-гномьи и вернуться к Выкрутеню.", progress = "Ну что, все удалось собрать?", completion = "Отлично! Так, сейчас тут подправим, тут подкрутим…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11700] = {title = "Сообщение для Бикси", objective = "Поговорите с Бикси Винтодер, находящейся рядом с Кельями Смерти, к югу от них.", description = "Моя темная сторона куда-то делась.\n\nЯ уверена, что она не вернулась на взлетную полосу. В общем, где бы она ни оказалась, там еще холоднее, чем здесь. Но я смогла \"поймать\" ее лишь на минутку.\n\nНу, да, я перенастрою эту штуку и перенесусь на взлетную полосу достаточно скоро. А пока... как думаешь, ты <мог/могла> бы направиться на восток и дать Бикси знать, что я встречусь с ней там?\n\nДа? Спасибо, <имя>!", progress = nil, completion = "У Тинки есть темная сторона?!\n\nНу, если она говорит, что в полном порядке и сможет сама вскоре добраться до взлетной полосы, я спокойна.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11701] = {title = "Возвращение к взлетной полосе", objective = "Поговорите с Выкрутенем Разгоняйло на взлетной полосе Выкрутеня в Борейской тундре.", description = "Ладно, думаю, мне пора возвращаться к взлетной полосе. Разумеется, теперь, с раненой ногой, я хожу несколько медленнее…\n\nПослушай, не трудно ли тебе будет отправиться вперед меня и сообщить старине Выкрутеню приятные новости? Могу поручиться чем угодно, что без награды тебя не отпустят!\n\nСпасибо, <имя>!", progress = nil, completion = "Вот так история, Аркоман! Тут столько проблем, что даже удивительно, как это наша взлетная полоса до сих пор не стерта с лица земли!\n\nНо теперь благодаря тебе у нас стало одним врагом меньше.\n\nУ меня тут припасены особые награды для особо отличившихся. Выбирай, что больше нравится!", rewards = "Укрепленные сапоги из шкуры карибуШипастый магмотский нагрудникЛатный шлем янтарной сосныВам дадут возможность выбрать одну из следующих наград:\n\nКольцо мерзнущего целителяСверхтехнологичный энергетический усилитель\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11702] = {title = "Король Мргл-Мргл", objective = "Поговорите с королем Мрглом-Мрглом в Приюте Зимних Плавников.", description = "Странно это звучит, должно быть, <класс>, но тут один мурлок есть, и он типа о помощи нас просит!\n\nИмя его – король Мргл-Мргл, а его подданные – мурлоки Зимних плавников. Его вместе с подданными выгнали из деревни, и теперь они хотят, чтобы ты их <спас/спасла>.\n\nКак направишься на запад да вниз по утесам – тут-то его и найдешь. Он обретается на южной стороне Приюта Зимних Плавников.", progress = nil, completion = "Наконец-то прибыла помощь! Судя по твоему виду, ты из Орды?\n\nЭто неплохо… ваши – хорошие воины. Именно это нам и нужно, причем в больших количествах.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11703] = {title = "Добраться до Гетри", objective = "Найдите тенелова Гетри у ферм Песни Войны.", description = "Посланник Плети, присматривающий за похищением и превращением воинов Орды в монструозную нежить, использует для выведения своих кошмарных созданий северо-западную ферму. Тенелов Гетри шпионил за этой тварью всю последнюю неделю и собрал немало важной информации, которая может позволить нам справиться с ситуацией.\n\nДоберись до Гетри и узнай, не можешь ли ты ему помочь остановить этот жуткий конвейер Плети. Гетри можно найти в заброшенной башне на северо-западном краю этих ферм.", progress = nil, completion = "&lt;Гетри скептически осматривает вас.&gt;\n\nА получше у Икориса никого не нашлось?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11704] = {title = "Король Мргл-Мргл", objective = "Поговорите с королем Мрглом-Мрглом у Приюта Зимних Плавников.", description = "Я понимаю, это звучит странно, <класс>, но одному мурлоку нужна наша помощь!\n\nОн известен под именем короля Мргла-Мргла и возглавляет мурлоков племени Зимних Плавников. Похоже, он вместе с подданными был вынужден бежать из своей деревни, а теперь они хотят, чтобы кто-нибудь их спас.\n\nИ этот \"кто-нибудь\" – ты!\n\nТы найдешь Приют Зимних Плавников и короля, направившись на запад по дороге, не доходя утесов. Иди к береговой линии близ Кипящего пруда.", progress = nil, completion = "Наконец-то прибыла помощь! Судя по твоему виду, ты из Альянса.\n\nЭто неплохо… у вас умелые воины. Именно это нам и нужно, в больших количествах.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11705] = {title = "Бесполезные старания", objective = "Помогите Гетри одолеть Варидуса Свежевателя у ферм Песни Войны.\n\nЕсли вам это удастся, явитесь к Гаррошу Адскому Крику.", description = "Это просто безумие. Неужели они думают, что мы справимся с некролордом Плети и всеми его приспешниками, которых там невесть сколько?\n\n<Гетри вздыхает.>\n\nРаз Икорис прислал тебя сюда, он, очевидно, полагает, будто ты <способен/способна> на великие подвиги. Может, ты и чудеса творить умеешь, а?\n\nЧто ж, когда будешь <готов/готова>, мы спустимся вниз и сразимся с Варидусом.\n\nЕсли уцелеем в этой заварухе, возвращайся к Адскому Крику в крепость Песни Войны.", progress = nil, completion = "И ты возвращаешься с победой, как я и думал! Я же говорил Саурфангу, что с тобой все будет в порядке!\n\n&lt;Адский Крик хмыкает.&gt;\n\nМожет быть, этот старый пес хоть теперь поймет, что он не всеведущ?", rewards = "Жесткий плащ из шкуры горностаяУкрепленный шлем монахаНожные латы благородного рыцаряВам дадут возможность выбрать одну из следующих наград:\n\nРезная подвеска из бивня черпорога\n\nВы также получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11706] = {title = "Обрушение", objective = "Обрушьте нерубские воронки с помощью рога неистовства стихий и уничтожьте лорда Криксиса по просьбе укротителя ветра Бары из деревни Таунка'ле.", description = "Для создания Аллювиуса использовался рог неистовства стихий. Протруби в этот рог, встав у самой южной воронки на Поле Гейзеров, и Аллювиус откликнется на зов.\n\nОн устроит землетрясение, от которого все нерубские туннели обрушатся. Это положит конец их наступлению. Не удивлюсь, если после землетрясения наружу появится сам командир воинов Неруба. И если обрушение туннелей их не остановит, то гибель командира – наверняка!", progress = "Удалось ли тебе выпустить Аллювиуса на волю и остановить наступление воинов Неруба?", completion = "Твои труды помогли нам на время остановить наступление Плети. Благодаря тебе, мы можем нанести удар по крепости Плети на северо-востоке, не опасаясь нападения с запада.\n\nЧто касается рога, я буду хранить его до тех пор, пока его мощь не понадобится снова. Штормовое Копыто отдал жизнь за то, чтобы спасти рог, и мы не можем позволить себе потерять его снова.", rewards = "Манжеты пеклаПерчатки из шкуры люторогаНагрудник степного охотникаЗамерзшие наголенникиВы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][11707] = {title = "Просьба о помощи", objective = "Поговорите с Выкрутенем Разгоняйло на взлетной полосе Выкрутеня.", description = "О, как хорошо! Ты ведь <имя>, верно?\n\nНам нужна твоя помощь на севере, на взлетной полосе Выкрутеня, причем нужна была еще вчера! Магнатавры, Плеть… а теперь еще и насосная станция!\n\nЯ тебе говорю – это безумие, чистое безумие!\n\nСтупай туда и поговори со стариком Выкрутенем на его взлетном поле. Срочно!!!", progress = nil, completion = "Ага, наконец-то Небопрыгу пришло на ум прислать помощь! Как нельзя вовремя, не могу не отметить!\n\nЧто ж, добро пожаловать, брат, мы отчаянно нуждаемся в твоей помощи!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11708] = {title = "Механогномы", objective = "Выслушайте рассказ Выкрутеня Разгоняйло и найдите на взлетной полосе Выкрутеня Джинки Гайковорот.", description = "Теперь, когда ты здесь, пришла пора рассказать тебе, что к чему.\n\nА когда выслушаешь мой рассказ, ступай наружу и отыщи моего заместителя, Джинки Гайковорот. Впредь за это отвечает она.", progress = "Эй, привет!", completion = "Что, старикан прислал тебя ко мне, да? А что к чему, объяснил?\n\nХорошо, тогда за дело!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11709] = {title = "Поручение Нока Кровавое Бешенство", objective = "Поговорите со стражем-смотрителем Ноком Кровавое Бешенство из Крепости Песни Войны в Борейской тундре.", description = "Ты немало <сделал/сделала>, чтобы помочь нам закрепиться на этих ледяных пустошах, однако же во тьме подстерегают новые опасности. Я прошу тебя помочь стражу-смотрителю Ноку Кровавое Бешенство, который находится в лагере для военнопленных под стенами крепости Песни Войны. Отыщи его и предложи свою помощь в транспортировке и обмене пленными.\n\nМожешь идти, <имя>.", progress = nil, completion = "&lt;Нок фыркает.&gt;\n\nПленные? Да какие это пленные! Это трусливые шавки! Ты только взгляни на них! Ты знаешь, что все они – все без исключения! – явились под стены нашей крепости и добровольно сложили оружие?\n\nНасколько мы поняли, если они попадают в плен, их потом разжалуют и отпускают по домам!\n\n&lt;Нок плюется.&gt;\n\nЖалкие твари!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11710] = {title = "Что такое с передачником?", objective = "Соберите 15 запасных деталей Выкрутеня и доставьте их Мордлу Шестеренку на взлетную полосу Выкрутеня.", description = "На востоке повсюду валяются запчасти: у Жгучих прудов, на Поле Гейзеров... да они, наверное, даже на насосной станции валяются! Принеси мне их, да побольше. Может, мне все-таки удастся наладить телепорт отправки в этой штуковине, не говоря уже о том, чтобы состроить порты приема.\n\nНе хотелось бы новых несчастных случаев...", progress = "Понадобится много запчастей, чтобы заставить эту штуку работать!\n\nСкажите, вы ведь достали все, что нужно, да?", completion = "Прекрасно, |3-6(Маг)! Отличные запчасти, во вполне рабочем состоянии.\n\nТеперь надо только придумать, как же починить эту хреновину…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11711] = {title = "Доставка дезертиров: от получаса ожидания – бесплатно!", objective = "Отведите дезертира Альянса к перекрестку восточнее крепости Песни Войны и выстрелите из сигнального ружья Песни Войны, чтобы дать сигнал представителям Альянса.\n\nДоложитесь разведчику Тунгоку, когда успешно доставите дезертира Альянса по месту назначения.", description = "Здесь появляется все больше дезертиров с каждым днем. У нас просто нет больше места – нам некуда сажать этих трусливых тварей. Особенно, если мы не хотим утеснять свиней.\n\n<Нок хохочет с фырканьем.>\n\nЯ хочу, чтобы ты сопроводил одного из этих трусов к востоку отсюда и выстрелил из этого светового ружья. Один из их командиров выйдет на свет выстрела и заберет дезертира у тебя.\n\nКогда доставишь его и вернешься, доложись разведчику Тунгоку на восточной дороге.", progress = "<Тунгок ворчит.>\n\nС дезертиром уже все, разобрался?", completion = "Хорошо, Сабыч. Одним грязным, бесполезным шельмецом Альянса меньше…\n\nЕсли тебе нужна еще работа, вон тем таурену и эльфу Крови неподалеку требуется помощь.\n\nВпрочем, у нас тут и своих забот-хлопот тоже хватает…", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11712] = {title = "Перепроклятие", objective = "Используйте перепроклинальную передачниковую инъекцию на 6 механогномах со станции Выкрутеня по просьбе Джинки Гайковорот со взлетной полосы Выкрутеня.", description = "Если ты <выслушал/выслушала> старика, то знаешь, что у нас тут есть гномы, которые изменились. Механизатор Механозод заразил их чем-то, что отменяет \"Проклятие Плоти\", и теперь они сделались роботами!\n\nМы думаем, что знаем способ перепроклясть их обратно, чтобы они снова стали нормальными. Возьми вот эту перепроклинальную передачниковую инъекцию и используй ее на трупах механогномов, которые тебе встретятся.\n\nМы надеемся, что эта штука их исцелит и позволит нам отправить их отсюда.\n\nЧто скажешь, а, <имя>?", progress = nil, completion = "Получилось! Сработало!\n\nПросто не верится, что тебе удалось спасти столько гномов! Как удачно, что ты здесь!", rewards = "Многослойный обмерзший капюшонНапульсники из шкуры люторогаШипастые магмотские перчаткиЗамерзшее наплечьеВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11713] = {title = "Исследование воронок", objective = "Отметьте на карте Поля Гейзеров расположение Южной воронки, Северо-западной воронки и Северо-восточной воронки по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня.", description = "Выкрутень отправил воздушную топографическую разведку, чтобы они составили карту нерубских воронок в южной части Поля Гейзеров, но они до сих пор не вернулись. Я больше не могу дожидаться, пока они вернутся, придется мне отправить кого-нибудь на разведку пешком.\n\nЯ понимаю, насколько это опасно, и ты получишь соответствующее вознаграждение. Возьми с собой эту карту и запиши важные сведения обо всех воронках, которые тебе там встретятся.", progress = "Ну что, все воронки отмечены на карте?", completion = "&lt;Абнер берет у вас карту и пристально разглядывает ее.&gt;\n\nОтлично! Это все, чего нам не хватало, чтобы начать операцию!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11714] = {title = "Дератизация", objective = "По просьбе разведчика Тунгока на равнинах Кровавых Спор в Борейской тундре убейте 8 жнецов, 5 поджигателей и 2 обжарщика из стаи Кровавых Спор.", description = "Может быть, ты не откажешься помочь мне в расчистке этих полей? Они просто кишат мелкими крысюками! Кобольды-шмобольды, как их там... они тут повсюду, повсюду! Одна вонь мне жизнь отравляет! Не говоря уже обо всем остальном… \n\nРазберись ради меня с этими вредителями, а я заплачу тебе за труды, <имя>.", progress = nil, completion = "Отличная работа, Транделар. Спасибо большое!", rewards = "Трансборейское оплечьеКапюшон половодьяНагрудный доспех терзающего бичаВам дадут возможность выбрать одну из следующих наград:\n\nПерстень-печатка разведчика\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11715] = {title = "В поисках топлива", objective = "Соберите 8 баррелей нефти в портативный нефтесборник по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня.", description = "Я планирую построить машину, способную обрушить туннели, по которым Плеть подсылает своих нерубов. Однако наша горная установка вышла из строя. Придется раздобыть топливо для машины другим способом.\n\nНа Поле Гейзеров к юго-востоку отсюда от главной горной установки растеклись лужи нефти. Если сумеешь набрать достаточно нефти из этих луж, я смогу сделать из нее какое-никакое топливо.\n\nПросто установи этот нефтесборник рядом с установкой, и он примется качать нефть в свой бак.", progress = "Ну что, удалось тебе набрать топлива?", completion = "&lt;Абнер опорожняет бак собирателя.&gt;\n\nКонечно, кустарная перегонка нефти – работа грязная, но я с этим быстро управлюсь. А пока что нам для постройки машины нужна еще одна вещь…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11716] = {title = "Удивительный кровоспор", objective = "Добудьте 10 кровоспоровых плодолистиков по просьбе волшебницы крови Лаурит с равнин Кровавых Спор в Борейской тундре.", description = "Мы стоим на пороге изумительных открытий, <раса>! Целый неисследованный мир живет и дышит всего в нескольких шагах от нас! И я подозреваю, что вся здешняя экология держится на растении под название \"кровоспор\".\n\nЯ собрала немного пыльцы с находящихся по соседству мужских растений, но никак не могу найти женских экземпляров. Набери мне побольше плодолистиков кровоспор. Ты найдешь их поблизости от более крупных растений, растущих вокруг.\n\nНо берегись! Кобольды их добром не отдадут!", progress = "Нужно продолжать эксперименты!", completion = "Великолепно! Просто великолепно!\n\n&lt;Лаурит посыпает пыльцой один из кровоспоровых плодолистиков и произносит заклинание.&gt;\n\nХм-м… Ничего не понимаю. Разве что… Ну да, конечно!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11717] = {title = "Быстродействующая пыльца", objective = "Принесите волшебнице крови Лаурит на равнины Кровавых Спор 5 щепоток пыльцы кровоспоровых мотыльков.", description = "Это же очевидно! Кровоспоровые мотыльки опыляют эти равнины. Должно быть, в организме мотылька что-то происходит, что действует на пыльцу как катализатор. Теперь все это начинает обретать смысл, <имя>. Теперь понятно, почему кобольды не убивают мотыльков, а наоборот, готовы на все, чтобы только защитить их! Эти маленькие крысы все поняли!\n\nЧто ж, нам нужно просто тоже достать себе пыльцу! Что скажешь? Принесешь мне немного – ради науки?", progress = "Пыльца – ключ к разгадке!", completion = "Агааа!\n\n&lt;Лаурит посыпает пыльцой кровоспоровые плодолистики.&gt;\n\nПогляди-ка!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11718] = {title = "Автомат в мамонтовой шкуре", objective = "Принесите Абнеру Шипокруту на взлетную полосу Выкрутеня 6 толстых шкур мамонта.", description = "Я иначе собрал корпус старого автомата, который мог бы произвести достаточно сильное землетрясение для обвала туннелей, но начинка машины очень хрупка и чувствительна к жалящему холоду Нордскола.\n\nЯ придумал средство защитить ее, используя толстенные шкуры здешних мамонтов. Они бродят по равнинам к югу от взлетной полосы и рядом с Полем Гейзеров. Принеси мне шкуры для защиты механизма, и тогда я смогу обрушить его мощь на нерубов!", progress = "Неси шкуры как можно быстрее! Я не смогу без них закончить подготовку машины!", completion = "&lt;Абнер осматривает шкуры, закашлявшись пылью, скопившейся в них.&gt;\n\nРазве у этих животных нет никаких понятий о гигиене? Некоторые из шкур просто до безобразия грязные. Эх, думаю, надо мне самому начать их чистить. Вряд ли у кого-то найдется здесь время на это...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11719] = {title = "Подопытное животное", objective = "По просьбе волшебницы крови Лаурит, находящейся на Равнинах Кровавых Спор в Борейской тундре, используйте опыленный цветок кровоспора и позвольте ей изучить полученные результаты.", description = "<Лаурит смотрит на вас, будто оценивая.>Итак, у нас есть опыленный цветок кровоспора, но никто не горит желанием испробовать его действие. Может, ты соблаговолишь стать участником эксперимента? Ну что, в конце концов, такого страшного может произойти?\n\nНе бойся, <имя>! Просто возьми образец и вотри его в кожу.", progress = "Не надо бояться.", completion = "Старец Крутой Рог будет просто в восторге! Все даже лучше, чем я ожидала!\n\nМожет быть, настало время открыть тебе правду.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11720] = {title = "Вторжение в Гаммот", objective = "Поговорите со старейшиной Крутым Рогом на равнинах Кровавых Спор в Борейской тундре.", description = "Адский Крик дал Крутому Рогу и мне тяжелое задание – истребить магнатавров у южной стороны крепости Песни Войны. С нами отправился целый взвод закаленных воинов Орды. Наше первое наступление на ближайшие логова успеха не имело – защищающие логова магнатавры смели весь отряд. Остались только мы...\n\nМы не ученые, не исследователи. Мы воины Орды – такие же, как ты. Солдаты на задании, которое нельзя провалить...\n\nПоговори со старейшиной Крутым Рогом прямо сейчас.", progress = nil, completion = "Кровоспор, что ты собрал, должно как раз хватить, чтобы дать нам шанс против магнатавров Гаммота – конечно же, с твоей помощью.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11721] = {title = "Гаммотра Мучитель", objective = "Убейте Гаммотру и вернитесь с головой Гаммотры к старейшине Крутому Рогу на равнинах Кровавых Спор в Борейской тундре.", description = "Магнатавры живут прайдами, подобно львам: один-два самца-вожака, и несколько самок с детенышами. В Гаммоте, логове магнатавров к западу отсюда, вожаком является Гаммотра. Именно Гаммотра повелевает магнатаврами, и именно его следует убить, чтобы остановить их.\n\nОтнеси этот мешочек с растертыми кровоспорами в Гаммот. Используй этот порошок, чтобы ослабить Гаммотру, а потом убей его! Принеси мне его голову в доказательство того, что задание выполнено.", progress = "Этот порошок можно использовать, чтобы ослабить всех магнатавров. Вот почему местные крысолюди так ревниво его берегут.", completion = "Молодец, Джайлор! Не окажешь ли ты честь нам с Лаурит, отнеся голову этого зверя Адскому Крику? Он будет весьма доволен.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][11722] = {title = "Трофеи из Гаммота", objective = "Отнесите голову Гаммотры Гаррошу Адскому Крику в крепость Песни Войны.", description = "Мы не можем присвоить себе всю честь этой победы, <имя>. Ведь это ты <рисковал/рисковала> жизнью, проверяя на себе кровавые споры, и именно ты, в конце концов, <покончил/покончила> с Гаммотрой!\n\nОкажи нам честь: отправляйся обратно в крепость Песни Войны и вручи голову Гаммотры лорду Адскому Крику!", progress = "Ты вернулся? Так быстро?", completion = "*Адский Крик поднимает голову Гаммотры за волосы и плюет ему в лицо.*\n\nОни еще узнают, Джайлор… Все они узнают! Все поймут, что с Ордой шутить не стоит!", rewards = "Трансборейские поножиНаплечье болотоходцаКольчатый доспех тундроходаШлем из камня силыВы получите:\n\n"}
MultiLanguageQuestData['ru'][11723] = {title = "Запустить Страх-и-ужас", objective = "Используйте Страх-и-ужас 5000, чтобы обрушить нерубские туннели и уничтожить лорда Криксикса по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня.", description = "Вот машина, которая спасет нас всех от нерубской угрозы!\n\n<Абнер сияет от гордости, демонстрируя готового робота.>\n\nВозьми с собой этот пульт дистанционного управления и отправляйся к самой южной из нерубских воронок на Поле Гейзеров. С помощью этого пульта запусти Страх-и-ужас 5000. Остальное он сделает сам.\n\nТы только не удивляйся, если вдруг устроенное им землетрясение привлечет внимание предводителя нерубов. На самом деле, это будет подходящий случай покончить с их нападениями!", progress = nil, completion = "&lt;Абнер жадно выслушивает ваш доклад о ваших собственных успехах и об успехах Страха-и-ужаса 5000.&gt;\n\nТо-то Выкрутень обрадуется! И кто знает – может, мы еще сделаем из тебя механика!", rewards = "Манжеты пеклаПерчатки из шкуры люторогаНагрудник степного охотникаЗамерзшие наголенникиВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11724] = {title = "Для гигантского омлета?", objective = "Отнесите массивное светящееся яйцо волшебнице крови Лаурит на равнины Кровавых Спор в Борейской тундре.", description = "Это яйцо, очевидно, было кому-то очень нужно, о чем свидетельствует лежащее рядом тело. Когда вы осматриваете яйцо, то замечаете, что оно уже помечено к отправке на равнины Кровавых Спор, для волшебницы крови Лаурит. Но это же совсем рядом, к востоку отсюда!\n\nВозьмите яйцо и отнесите его к ожидающей волшебнице крови.", progress = "Приветствую!", completion = "Значит, Алкора больше нет... Жаль... Что касается яйца, оно нам сейчас уже ни к чему. У нас тут возникли куда более сложные и неотложные проблемы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11725] = {title = "Поиски пилота \"Штопора\"", objective = "Отыщите Игги \"Штопора\" Шестероверта на Поле Гейзеров", description = "Я должен был сам лететь на это задание. Не то чтобы я не доверял \"Штопору\". Вовсе нет. Черт, да он был лучшим ведомым, с которым я когда-либо летал!\n\nНет, все дело в том, что выполнение такого задания – моя обязанность.\n\nЯ послал \"Штопора\" с нашей самой быстрой разведгруппой, чтобы собрать информацию о деятельности нерубов в центре Поля Гейзеров.\n\nВ их последнем донесении значилось, что группа находится у прудов далеко на юг и чуть западнее нерубских воронок.\n\nНайди \"Штопора\", <имя>.", progress = nil, completion = "Слава механическим богам... Это было ужасно.\n\nЯркая вспышка на земле, а потом следующее, что я помню – весь отряд валится наземь. Я довольно сильно расшибся, так что у меня не было даже возможности прочесать окрестности в поисках других выживших, но что-то мне подсказывает, что вряд ли их будет много, если вообще будут\n\n&lt;Лицо Игги перекашивает гримаса боли.&gt;\n\nТы поможешь мне завершить мою миссию?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11726] = {title = "Добавить специй по вкусу...", objective = "По просьбе Игги \"Штопора\" Шестероверта, что стоит возле Жгучих прудов, соберите 4 мешочка с горлокскими специями.", description = "Волки рыщут здесь с самого крушения, и я боюсь, что они могли сожрать микропленку, на которую мы снимали весь процесс.\n\nУ меня есть идея, как найти эту микропленку, но мне нужна твоя помощь, чтобы идея сработала.\n\nК югу и востоку отсюда, на Затопленных равнинах, живут существа, которых называют горлоками. Они готовят себе пищу, используя ядовитые специи, которые отравили бы любое другое существо. Если ты сможешь собрать достаточно мешочков со специями, которые носят с собой горлоки-пародувы и горлоки-хромули, я смогу сделать приманку для волков.", progress = "Удалось найти мешочки со специями?", completion = "&lt;Игги зажимает нос, опустошая мешочки со специями, и обращается к вам гнусавым голосом.&gt;\n\nТеперь, когда у нас есть все необходимое, я смешаю специи со своим аварийным пайком, чтобы сделать приманку для волков.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11727] = {title = "Время героев", objective = "Доложитесь сержанту Молотогору в Крепости Отваги.", description = "Хорошо, что у нас есть ты, <имя>. Все мы слышали о твоих деяниях.\n\nКак ты знаешь, король Ринн выдвигает в Нордскол огромное войско, чтобы сразиться с войсками Артаса. Но армии – ничто, если в них нет настоящих героев, способных вдохновить бойцов и повести их за собой.\n\nЯ хочу, чтобы таким героем для моих воинов <стал/стала> ты. Бейся плечом к плечу с ними против сил Плети, осадивших нашу крепость.\n\nДоложись сержанту Молотогору у внутренней крепости. Крепость Отваги не может пасть. От этого зависит будущее всей нашей кампании.", progress = nil, completion = "Клянусь бородой Магни! Похоже, прибыла наша тяжелая артиллерия!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11728] = {title = "Собаки-каки", objective = "Принесите 8 кусков микропленки Игги \"Штопору\" Шестероверту у Жгучих прудов.", description = "Главное, ни в коем случае не ешьте эту приманку сами! Просто выложите ее неподалеку от запятнанного нефтью волка. Если уж они такие голодные, что сожрали микропленку, то на приманку сбегутся как миленькие.\n\nА потом просто дождитесь, пока природа возьмет свое, и отыщите пленки в... э-э... побочном продукте пищеварения.\n\nЯ бы одолжил вам специальную усовершенствованную лопатку для собаки-каки, но она, увы, осталась на взлетной полосе. Боюсь, вам придется искать по старинке, дедовским способом...", progress = "Ну что, нашли пленку?", completion = "*Игги, зажав нос, берет у вас пленку.*\n\nОй, фу! Ну что, параграф 2 раздела 8.2 инструкций по действиям в чрезвычайной ситуации выполнен. Вот она, пленка. Ну, а насчет того, что я обязан ее отчищать, в инструкциях ничего не сказано!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11729] = {title = "Ультразвуковая отвертка", objective = "Принесите ультразвуковую отвертку Умейке Шестеркрут на взлетную полосу Выкрутеня.", description = "В механических недрах машины, которую вы только что разобрали по винтику, лежала странная вещица.\n\nВыглядит довольно сложным приспособлением... ясное дело, кто-нибудь на взлетной полосе с удовольствием посмотрит на это. Может, Умейка Шестеркрут?", progress = "Эй!", completion = "Моя отвертка... Ты нашел мою отвертку! А я-то гадала, куда она задевалась.\n\nХмм, говоришь, она была в одном из роботов? Это наводит меня на мысль...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][11730] = {title = "Хозяин и слуга", objective = "Используйте ультразвуковую отвертку, чтобы перепрограммировать 15 роботов, затем вернитесь к Умейке Шестеркрут на взлетной полосе Выкрутеня.\n\nНе забудьте обыскать убитых роботов прежде, чем перепрограммировать их.", description = "Ультразвуковая отвертка – это суперинструмент! С ее помощью с механизмами можно делать что угодно!\n\nВозвращайся к прудам и обезвредь несколько роботов Механозода. Затем поковыряйся в их останках нашей отверткой, и могу поручиться, что они перейдут на нашу сторону, хотя бы на короткое время.\n\nНа механогномов это почти наверняка не подействует, так что даже и не пробуй.\n\nДа, и если захочешь вытащить из роботов что-нибудь ценное, сделай это до того, как пустишь в ход отвертку!", progress = nil, completion = "Ух ты! И отвертка тоже осталась целехонька?\n\nЭти перепрограммированные роботы будут нам чрезвычайно полезны в борьбе против Механозода! Полагаю, ты заслуживаешь за это небольшой награды…", rewards = "Многослойные обмерзшие одеянияУкрепленный шлем из шкуры карибуШипастое магмотское оплечьеНабедренники янтарной сосныВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][11731] = {title = "Жонглирование факелами", objective = "Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом.", description = "Значит, ты хочешь научиться жонглировать горящими факелами? А у тебя есть необходимые для этого качества? Ловкость? Быстрая реакция? Отвага? Если ты думаешь, что да, то давай попрактикуемся немного!\n\nБери эти факелы и беги к костру. Над ним увидишь жаровни, с горящими метками. Бросай факелы в отмеченные жаровни. И делать это надо быстро! До того, как метка погаснет, если хочешь получить очко за попадание!\n\nПопади в достаточное количество отмеченных жаровен прежде, чем выйдет время, затем возвращайся назад... для следующего урока.", progress = "Быстро! Не тяни время!", completion = "Отлично! Ты научишься жонглировать факелами – не успеешь и глазом моргнуть! Ну, готовься. Следующее испытание будет погорячее...", rewards = "Вы получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][11732] = {title = "Осквернение огня", objective = "Оскверните большой костер Альянса на нагорье Арати!", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nЗатаптывание костра\n\nВы получите:\n\nПылающий цвет"}
MultiLanguageQuestData['ru'][11733] = {title = "Переход через расселину", objective = "Отправляйтесь в Хладарру по распоряжению Сурристраза. Оказавшись там, поговорите с верховным магом Беринардом.", description = "Мне известно о твоих стараниях, <смертный/смертная>. Не нужно притворяться, будто ты <удивлен/удивлена>. Неужели ты не <ощущал/ощущала> на себе моего взгляда?\n\nПришло время сорвать завесу тьмы с твоего разума. Твоя душа созрела достаточно, чтобы принять некоторые суровые истины.\n\nНо прежде, чем выслушать эту историю, тебе следует воочию увидеть то, чему мы противостоим.\n\nПриведи свои дела в порядок, <класс>.", progress = nil, completion = "Добро пожаловать в Хладарру, |3-6(Охотник)! \n\nМаскировочный щит скрывает нас от Нексуса, твердыни великого аспекта Малигоса и его синих драконов, но на самом деле туда рукой подать.\n\nРасполагайся поудобнее…", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
