MultiLanguageQuestData['ru'][12372] = {title = "Оборона Храма Драконьего Покоя", objective = "По просьбе Деврестраза из храма Драконьего Покоя убейте 3 лазурных драконоидов, 5 лазурных драконов и дестабилизируйте Лазуритовое святилище драконов.", description = "Воодушевленные избытком магической энергии, текущей сейчас через Лазуритовое святилище драконов, синие драконы осмелились напасть на сам храм Драконьего Покоя!\n\nЯ хочу, чтобы ты <полетел/полетела> на одном из наших защитников в самую гущу битвы, убивая их драконов, больших и малых, и атакуя выбросы энергий силовых линий в самом святилище с целью его дестабилизации.\n\nЗащитники Драконьего Покоя находятся снаружи, на восточной и западной террасах. Поговори с кем-нибудь из них, чтобы полететь на битву.\n\nБез твоей помощи, <имя>, нас ждет поражение.", progress = "Как протекает битва? Мы их тесним?", completion = "Невероятно! Позволь мне сказать, что я не устаю поражаться, на что способны вы, представители молодых рас.\n\nМы в долгу перед тобой. Вернешься ли ты завтра, чтобы продолжить помогать нам?", rewards = "Вы получите:\n\n"}
