MultiLanguageQuestData['ru'][13502] = {title = "Что вам надо? Шоколада!", objective = "Соберите 10 праздничных шоколадных яиц и отдайте их продавцу Сада чудес вместе с позаимствованной корзиной для яиц.", description = "Вот – возьми эту корзину для яиц и ступай искать раскрашенные яйца. Возвращайся, когда наберешь десять праздничных шоколадных яиц.", progress = "Ты принес десять шоколадных яиц?", completion = "Молодчина! Нет-нет, оставь корзину себе.\n\nЕсли найдешь еще шоколадные яйца, можешь обменять их у меня на что-нибудь полезное.", rewards = "Вы получите:\n\nКорзина для яиц"}
MultiLanguageQuestData['ru'][13503] = {title = "Что вам надо? Шоколада!", objective = "Соберите 10 праздничных шоколадных яиц и отдайте их торговцу Сада чудес вместе с позаимствованной корзиной для яиц.", description = "Вот – возьми эту корзину для яиц и ступай искать раскрашенные яйца. Возвращайся, когда наберешь десять праздничных шоколадных яиц.", progress = "Ты принес десять шоколадных яиц?", completion = "Молодчина! Нет-нет, оставь корзину себе.\n\nЕсли найдешь еще шоколадные яйца, можешь обменять их у меня на что-нибудь полезное.", rewards = "Вы получите:\n\nКорзина для яиц"}
MultiLanguageQuestData['ru'][13504] = {title = "Работники Пронзающего Копья", objective = "Убейте 10 работников из племени Пронзающего Копья.", description = "Тролли из племени Пронзающего Копья рыскают по руинам, что остались на севере и северо-востоке отсюда, но наши разведчики не обнаружили никаких значимых находок на месте раскопов. Возможно, эти тролли просто таскают боеприпасы для войска?\n\nЯсно одно: чем меньше рабочих рук будет у троллей, тем сложнее им будет вести войну против нас. Этим мы и займемся – уменьшением их количества. Ты с нами?", progress = nil, completion = "Молодец. Спасибо тебе, |3-6(Друид).", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13505] = {title = "Оставшиеся высокорожденные", objective = "Добудьте 8 реликвий высокорожденных.", description = "Здесь, на Темных берегах, есть еще много подобных руин, но на многих из них обитают неупокоенные призраки высокорожденных. Из уважения к духам мы старались обходить эти руины стороной, но в свете угрозы троллей пора отбросить предрассудки и заняться поиском артефактов. \n\nТак что пока ты будешь помогать часовым, внимательно смотри под ноги и собирай все ценности, которые тебе попадутся. Я хочу сохранить их для будущих поколений.", progress = "Удалось ли тебе найти хотя бы несколько артефактов?", completion = "Отлично! Спасибо тебе большое. Мы уже потеряли слишком много – не хотелось бы, чтобы в пламени войны сгорели и эти культурные ценности.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13506] = {title = "Причины для волнения", objective = "Принесите приказы Сумеречного Молота лейтенанту Морре Звездный Ветер на руины Матистры.", description = "Похоже, это приказы, выданные надзирателям от их начальника из Боевого лагеря Пронзающего Копья. Большая часть информации не содержит стратегически важных данных, но несколько строк привлекают ваше внимание.\n\nТам сказано:\"Мы захватили еще одного ночного эльфа, который шпионил за нами. Ее доставили в лагерь для допроса с применением пыток. Берегитесь, вокруг вас могут находиться и другие следопыты. Нельзя допустить, чтобы цель нашей операции была раскрыта.\"\n\nЭту информацию надо незамедлительно доставить лейтенанту.", progress = "Да, |3-6(Друид)?", completion = "Еще одного? Значит, у них в плену находится несколько моих людей, и я не оставлю их в беде. Мы должны действовать быстро.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13507] = {title = "Отрицание силы", objective = "Убейте 6 головорезов Орды и 6 мистиков племени Пронзающего Копья.", description = "К северу отсюда племя Пронзающего Копья разбило военный лагерь, где они сооружают свои катапульты. По последним разведданным, его охраняют не только мистики племени, но также орки и таурены. \n\nБестолку гадать, что может означать их присутствие – лучше пойди и перебей их всех до того, как они снова нападут на наших часовых.", progress = nil, completion = "Превосходная работа. Одной угрозой меньше... Мы будем продолжать в том же духе, пока они еще ничего не заподозрили.", rewards = "Нагрудный доспех ТишиНакидка из листьевВы получите:\n\n"}
MultiLanguageQuestData['ru'][13508] = {title = "Мгновенный ответ", objective = "Найдите пленных ночных эльфов в Боевом лагере Пронзающего Копья.", description = "Связь с одной из моих разведчиц прервалась несколько дней назад. Мы полагали, что она погибла, но похоже, ее захватили тролли. Они утверждают, что у них два заложника... но я даже не представляю, кто второй пленник. Может быть, это Аландариан Песня Ночи? Она отправилась туда вопреки моим предостережениям...\n\nВ любом случае, я практически уверена, что пленников держат в боевом лагере Пронзающего Копья на севере отсюда. Если сможешь, найди их и освободи.", progress = nil, completion = "&lt;Аланндариан выглядит очень бледной, и только по редким колыханиям груди можно определить, что в ней все еще теплится жизнь.&gt;\n\nТы пришел... спасти меня? Боюсь... твоя помощь запоздала...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13509] = {title = "Военный склад", objective = "Уничтожьте 12 единиц оружия троллей Пронзающего Копья.", description = "Тролли сосредотачивают свои силы в военном лагере к северу отсюда. Там же они складируют свои припасы. Оттуда они начнут атаку на Лор'данел – как только сочтут, что готовы к ней. Разделаться с ними – не проблема, но я предпочитаю не рисковать.\n\nОтправляйся в их лагерь и сожги все припасы, что попадутся тебе на глаза. Это сильно расстроит их планы и даст нам приличное время на подготовку к их контратаке.", progress = nil, completion = "Отлично! Это их немного замедлит.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13510] = {title = "Своевременное прибытие", objective = "Сопроводите часового Айнашу в безопасное место.", description = "Как я рада тебя видеть! Признаться, я не надеялась пережить то, что сотворили с Аландариан... так что безмерно благодарна за спасение.\n\nЯ видела предводителя троллей прямо перед собой, и у меня был шанс нанести смертельный удар – но он оказался защищен некоей магической броней. Мы должны сообщить об этом Морре, чтобы она учла это во время нападения. Но для начала хорошо бы выбраться отсюда живыми и невредимыми.\n\nПомоги мне добраться до пристани, и я отправлюсь в Лор'данел водным путем. А ты тогда сможешь вернуться к Морре и предупредить ее.", progress = nil, completion = "Говоришь, его защищает магическая броня? Ну ничего, мы придумаем, как ее обойти. Кажется, у Балтула была какая-то идея, как пробить любой волшебный щит шамана – возможно, она сработает и в этот раз. Спасибо за то, что ты спас Айнашу и доставил мне эти сведения: с их помощью мы сможем переломить ход битвы.", rewards = "Перчатки МоррыЗапасной меч АйнашиВы получите:\n\n"}
MultiLanguageQuestData['ru'][13511] = {title = "Последняя просьба", objective = "Убейте Рит'ко, мучителя из племени Пронзающего Копья.", description = "Тебя Морра прислала? Ах, почему я ее не послушала... но кто бы мог подумать, что троллей надо воспринимать всерьез?\n\n<Аландариан грустно усмехается.>\n\nВпрочем, для меня все уже кончено. Теперь мы смертные... и должны смотреть в лицо судьбе. У меня было время подумать об этом. \n\nУ меня есть только одна просьба... убей палача, который сделал это со мной. Они называли его Рит'ко... и он сейчас где-то там, мучает остальных заключенных.\n\n<Аландариан с трудом улыбается, но вскоре лицо ее искажает гримаса боли, и она, корчась, падает на пол.>", progress = nil, completion = "Значит, Аландариан умерла. Это печальные новости, хотя я и чувствовала, что этим все кончится. Проклятые дикари не ведают жалости к пленным – но и от нас они не дождутся пощады.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13512] = {title = "Предупредительный удар", objective = "Убейте Шейю Вьющую Грозы и Лорента Громовой Зов.", description = "Мало отсечь голову гидры, если на ее месте тут же вырастет другая. Если мы просто убьем их предводителя, кто знает, не попытается ли один из его помощников занять освободившийся трон. Сейчас они ничего не боятся, и потому ты сможешь расправиться с ними в одиночку.\n\nВозьми это дриадское копье и убей их всех: яд на острие парализует их магические способности. Мои разведчики докладывают, что одного из помощников видели в подводных палатах на востоке руин, а других – у развалин башни на юго-западе.", progress = nil, completion = "Надо же, ты талантлив не по годам! Прекрасно, но главная битва еще ждет нас впереди.", rewards = "Вы получите:\n\nЖезл дриадыПредмет #1"}
MultiLanguageQuestData['ru'][13513] = {title = "На грани", objective = "Добудьте 6 амулетов племени Пронзающего Копья.", description = "Я уже работаю над устройством, которое может разрушить их идолы защиты. Думаю, если объединить их магию и волшебство друидов, мы сможем прорвать заслон.\n\nТебе надо найти их шаманов, которые бродят к востоку и юго-востоку отсюда, и добыть несколько амулетов. Я обработаю эти предметы и заколдую стрелу, которую надо будет доставить Сандрии Закат Луны.", progress = "Ты добыл амулеты?", completion = "Да, эти вполне подойдут. Я подготовлю их для отправки Сандрии, а тебе надо будет как можно скорее отправиться в путь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13514] = {title = "Гнев Древних", objective = "Присоединитесь к мстительным заступникам, чтобы убить 30 троллей Пронзающего Копья и уничтожить 6 построек Пронзающего Копья.", description = "Хочешь присоединиться к ударной группе? А, тебе нужна Сандрия Закат Луны... Она планирует нападение на вожака племени Пронзающего Копья. Ты найдешь ее в пещере по ту сторону долины.\n\nСлушай, пока ты здесь, помоги нам разобраться с остатками племени. Присоединяйся к нашим мстительным заступникам и убедись, что в этом проклятом племени не осталось ни одного целого здания и ни одного живого тролля. Нельзя допустить, чтобы они вернулись в самый неподходящий момент и принялись мстить!", progress = nil, completion = "Как нам повезло, что ты сражаешься на нашей стороне!\n\nК сожалению, разведданные об их предводителе еще не поступили. Не забудь поговорить с Сандрией перед отъездом – она ждет тебя в пещере на окраине долины.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13515] = {title = "Покончить с угрозой", objective = "Поговорите с охотницей Сандрией Закат Луны, чтобы она отдала приказ к наступлению, и помогите ей убить Джор'кила Убийцу Душ.", description = "Прямо перед нами – их предводитель с охраной. Со стражниками разберутся мои часовые; мы ждали только этой стрелы, чтобы решить судьбу главаря.\n\nДай мне знать, когда ты будешь <готов/готова> к атаке. Как только часовые ринутся в бой, я расколю стрелой щит предводителя, и мы вместе одержим над ним верх. Пусть рука твоя будет тверда, ибо только так мы устраним угрозу, нависшую над нашими землями.\n\nНе медли, все ждут только тебя!", progress = nil, completion = "Это была великая битва, но победой в ней мы обязаны тебе.\n\nНечасто нашим врагам приходилось терпеть столь сокрушительное поражение, но мне все еще кажется, что за нападением Пронзающего Копья стоит что-то большее. Мой тебе совет, обыщи тело вождя прежде, чем покинешь это место.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13518] = {title = "Последняя группа беженцев", objective = "Найдите всех выживших беженцев из Аубердина.", description = "Увы, Лайрд не успел добраться до безопасного места.\n\nПоследняя группа ночных эльфов из Аубердина отправилась пару часов назад. Они до последнего прятались в своих разрушенных домах, ожидая спасения, но в итоге им все же пришлось бежать. Боюсь, многие из них разделили судьбу Лайрда.\n\nНо все же, я прошу тебя отправиться на западную часть побережья и поискать выживших. Мы обязательно пришлем за ними часовых на гиппогрифах, но сначала надо определить, о каком количестве беженцев идет речь. Поторопись, каждая секунда промедления может стоить им жизни!", progress = nil, completion = "Спасибо тебе, |3-6(Друид). Многие из нас обязаны тебе жизнью.\n\nКак только все доберутся до города, мы отнесем раненых в главное здание. Может быть, ты еще сможешь нам в этом помочь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13519] = {title = "Культ Сумеречного Молота", objective = "Убейте верховного сектанта Азеринна и 10 фанатиков культа Сумеречного Молота в лагере Сумеречного Молота.", description = "Служители культа Сумеречного Молота разбили лагерь на юго-западе отсюда и собирают армию элементалей воды, чтобы напасть на Лор'данел.\n\nИх повелитель, Верховный сектант Азеринн, заключил союз с жестокими древними богами, и те даровали его последователям власть над стихиями. Иди и разберись с ними, пока еще не слишком поздно.\n\nКатаклизм поверг духов стихий в смятение, но если наши враги соберут достаточно большую армию, то нам не устоять перед ними.", progress = nil, completion = "Ты все сделал правильно, Авелфорт. Культ Сумеречного Молота – опасная секта, и ее нельзя недооценивать.", rewards = "Ботфорты неистовогоПерчатки бронированного кулакаВы получите:\n\n"}
MultiLanguageQuestData['ru'][13520] = {title = "Дар морей", objective = "Соберите 16 затвердевших мышц моллюска.", description = "Я рада снова видеть тебя. Благодаря тебе наши родные и близкие смогли вернуться домой, но я тешу себя надеждой, что ты и дальше будешь помогать нашему делу.\n\nЭтого мужчину зовут Лайрд, и он один из многих воинов, которые получили тяжелые ранения в битве с элементалями на побережье. Я делаю все, что могу для того, чтобы спасти ему жизнь, но яд духов стихий проникает все глубже в его тело, ослабляя действие лекарственных средств. Есть одна мазь, которая могла бы помочь в таком случае, но для ее изготовления мне понадобятся мышцы моллюсков, обитающих на побережье. Ты можешь их достать?", progress = "Ты принес мышцы моллюсков? Послушай, у нас не так много времени...", completion = "Да, эти моллюски вполне сгодятся. Спасибо большое!\n\nПожалуйста, загляни к нам попозже – многие воины хотели бы лично отблагодарить тебя за спасение.", rewards = "Вы получите:\n\nШнурованный ремень ныряльщика"}
MultiLanguageQuestData['ru'][13521] = {title = "Жужжалка 413", objective = "Соберите 4 куска мяса зараженного прибрежного краба и отнесите их к Жужжалке 413 для анализа.", description = "Здравствуй!\n\nЯ помощник Тарнариуна, и мы с ним пытаемся выяснить, что заразило диких животных в этой местности. Для этого я установил по всему периметру некие машины, которые способны анализировать ткани живых существ на предмет источника порчи. Если ты поможешь мне добыть образцы, мы сможем приступить к исследованиям.\n\nПервая машина называется Жужжалка 413, и я установил ее на пляже к востоку от города. принеси к ней для анализа плоть зараженных прибрежных крабов.", progress = "<Жужжалка 413 выжидательно гудит.>", completion = "&lt;Аппарат громко трещит, и через статистические помехи с трудом прорывается голос Бацбаха.&gt;\n\nПрекрасно! Надеюсь, тебе не пришлось перебить их всех. Мы не собираемся устроить геноцид, нам надо просто установить источник разложения! Я немедленно приступлю к анализу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13522] = {title = "Угроза из воды", objective = "Убейте 8 коварных потоков.", description = "Не все выжившие добрались до лагеря – некоторые из них все еще пытаются обогнуть побережье. Только недавно я получила сообщение, что они собираются прибыть сюда в течение следующего часа. Ах, почему они не предупредили меня заранее?\n\nВсе побережье к западу отсюда кишит коварными потоками, маленькими, но злобными духами воды. Мы должны уничтожить их, иначе никто из пострадавших не доберется до Лор'данела. Нельзя медлить ни минуты!", progress = nil, completion = "Твоя помощь бесценна для нас. После того как Катаклизм прокатился по этим землям, духи стихий как с цепи сорвались. Если мы не уберем их с нашего пути, то никогда не отвоюем Аубердин.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13523] = {title = "Власть над приливами", objective = "Прикоснитесь Сферой Элуны к останкам 6 разъяренных духов волны.", description = "Не беспокойся обо мне. Раны мои глубоки, и смерть не заставит себя ждать.\n\nТеперь все в твоих руках... ты <должен/должна> остановить служителей культа Сумеречного Молота.\n\nДревние боги, которым они поклоняются, даровали им власть над неугомонными духами воды... но сила эта не слишком велика. Позволь духу Элуны проникнуть через этот шар, когда победишь элементалей.\n\nВоспользуйся силой Элуны, чтобы навеки успокоить духов.", progress = nil, completion = "Ты преуспел...значит, все было не напрасно.\n\nМое время пришло. Теперь ступай, Авелфорт, и пусть Элуна хранит тебя.", rewards = "Плащ приливовБлагословение ТариллВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13524] = {title = "Побег из Среброречья", objective = "Откройте деревянную клетку и помогите освобожденному разведчику Альянса сбежать из Среброречья. Доложитесь лейтенанту Думонту по прибытии в Приют Янтарной Сосны.", description = "Ты… ты не <один/одна> из них? Быстрее! Освободи меня!\n\nНам нужно немедленно отправляться в Приют Янтарной Сосны! Как только лейтенант Думонт узнает, кто эти люди на самом деле, он камня на камне не оставит от этого города!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Облачение плененного зверяСапоги душевной борьбыНарукавники страдающей душиБашмаки попранной человечностиВам дадут возможность выбрать одну из следующих наград:\n\nКольцо истребителя воргов\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13525] = {title = "Что случилось с фурболгами Чернолесья?", objective = "Поговорите со старейшиной Бролгом в логове Чернолесья.", description = "Наши предки долгие века жили бок о бок с фурболгами Чернолесья, но недавно мы потеряли связь с их поселением в глубине леса. Это целая огромная деревня, Логово Чернолесья, что находится к югу отсюда.\n\nОтправляйся туда и найди старейшину Бролга. Узнай, почему его люди отвернулись от нас, и предложи свою помощь, если она им нужна.", progress = nil, completion = "Зачем ты пришел, чужестранец? \n\n&lt;Вы говорите, что вас послал Фориел Широкий Лист из Рощи Древних, и он смотрит на вас чуть более дружелюбно.&gt;\n\nЭльф прав. Сила Оскверненного леса проникла на Темные берега и заразила мой народ.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13526] = {title = "Медвежья лапка", objective = "Принесите 8 пучков медвежьей лапы старейшине Бролгу в логово Чернолесья.", description = "Мерзкие сатиры, обитатели Оскверненного леса, начали распространять свою заразу здесь, на Темных берегах. Эта порча убивает нашу родную землю и оскверняет всех живых существ. Не избежал этой участи и мой народ...\n\nНашей магии не хватит на то, чтобы привести в чувство тех, кто пал жертвой заразы. Но в этих краях растет одна травка, медвежья лапа, которая снимает жар и придает сил больному. С ее помощью мы сможем разрушить злые чары сатиров. Как хорошо, что ее можно найти повсюду вокруг деревни!", progress = "Ты собрал стебли медвежьей лапы?", completion = "Эти стебли такие вялые и пожухшие... Видимо, порча уже перекинулась на лесные растения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13527] = {title = "Никакого вкуса", objective = "Принесите образец разложившейся медвежьей плоти на восток к Жужжалке 413.", description = "<Машина некоторое время издает гудящие звуки, через которые прорывается голос Бацбаха.>\n\nЛюбопытно! Источник этой порчи находится где-то извне – что меня не удивляет – но похоже, в данном случае они съели что-то тухлое. Возможно, закусили каким-нибудь большим млекопитающим типа медведя.\n\nОбыщи берег, там должны были остаться его кости. Полагаю, имеет смысл поискать на востоке отсюда, на внешней стороне пляжа. Побыстрее возвращайся с образцами!", progress = "Добро пожаловать обратно! Ты нашел образец медвежьей плоти?", completion = "Да, это похоже на то, чем они питаются. Дай-ка мне взглянуть поближе...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13528] = {title = "Жужжалка 723", objective = "Соберите 6 образцов внутренностей зараженных колючешерстных медведей и принесите их к Жужжалке 723 для анализа.", description = "Я обнаружил еще несколько заразившихся существ. К счастью, можно точно сказать, что крабы подцепили эту дрянь от медведей – а это означает, что источник заражения только один. Мы должны сконцентрировать наше внимание на этих косолапых.\n\nПослушай, у меня есть для тебя одно неприятное, но очень важное поручение. К востоку от водопадов я спрятал Жужжалку 723: отнеси ей для анализа свежие внутренности медведей. Как только результат будет готов, мы решим, что делать дальше.", progress = "<Жужжалка 723 выжидательно гудит.>", completion = "&lt;Среди помех пробивается искаженный голос Бацбаха.&gt;\n\nРезультаты скоро будут готовы. Еще минутка – и мы узнаем, что случилось с этими медведями.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13529] = {title = "Источник разложения", objective = "Убейте Зенна Грязное Копыто и 8 коварных греллей в Скалистой пещере.", description = "Уф! Я бежал со всех ног, как только получил сообщение от Бацбаха. Я знаю, кто стоит за всем этим! Зенн Грязное Копыто!\n\nОн явился из Тельдрассила, где его поймали за использованием некоей извращенной формы магии. Подобные практики не приветствуются среди моего народа, но похоже, на этот раз он зашел еще дальше – возможно, из мести.\n\nМы слишком часто прощали Зенна, и на этот раз он должен поплатиться жизнью за преступления против природы. Убей его, уничтожь всех его прислужников и возвращайся в Лор'данел.", progress = nil, completion = "Значит, дело сделано. Спасибо тебе. Я лишь надеюсь, что с его смертью природа обретет долгожданный покой.", rewards = "Жилет из козьей шкурыТканые кольчужные поножиПосох из рога сатираВы получите:\n\n"}
MultiLanguageQuestData['ru'][13537] = {title = "Любовь к окуням", objective = "С помощью навыка рыбной ловли поймайте 4 морских окуня Темных берегов.", description = "Все эти поездки и строительства меня ужасно измотали... мне срочно надо что-нибудь перекусить! Знаешь, о чем я сейчас думаю? О вкусной, ароматной рыбе!\n\nНа Темных берегах издавна ловили морских окуней. Если ты принесешь мне несколько штук, то не пожалеешь потраченного времени!", progress = "<Вы слышите, как живот Джонатана урчит при вашем приближении.>\n\nДа-да, он говорит за меня!", completion = "Похоже, у тебя талант рыболова! Мой желудок говорит тебе \"спасибо\". \n\nПослушай, эта удочка пригодится тебе больше, чем мне. Оставь ее у себя.", rewards = "Вы получите:\n\nУдочка Стаатса"}
MultiLanguageQuestData['ru'][13538] = {title = "Южный саботаж", objective = "Уничтожьте башню Темного Взора, башню Огненного Дозора или башню Клинка Зимы, а затем вернитесь к офицеру-стратегу Абрамису на Озере Ледяных Оков.", description = "Три башни южнее реки Ледяных Оков вытягивают энергию из Крепости!\n\nУничтожь башню Темного Взора, башню Огненного Дозора или башню Клинка Зимы, затем возвращайся ко мне. И помни, только осадные машины могут навредить башне, поэтому тебе следует защищать их от Орды!", progress = nil, completion = "Я слышал этот взрыв! Неплохо сработано! Мы уже приступили к перенаправлению энергии в реликвию титанов, чтобы наделить наши войска суперсилой.", rewards = "Вы получите:\n\nОчки честиОсколок каменного хранителя"}
MultiLanguageQuestData['ru'][13539] = {title = "Свержение башен", objective = "Уничтожьте башню Темного Взора, башню Огненного Дозора или башню Клинка Зимы, затем вернитесь к офицеру-стратегу Килрату.", description = "Хотя Альянс у нас на пороге, настоящий стратег всегда заглядывает дальше собственного носа.\n\n\"Напади там, где враг не готов дать отпор; появись там, где тебя не ждут.\"\n\n<имя>, я хочу, чтобы ты <отправился/отправилась> через Реку Ледяных Оков и <уничтожил/уничтожила> одну из башен на юге. Наши чернокнижники докладывают, что башни оттягивают энергию, которую мы могли бы использовать, чтобы укрепить наши войска.\n\nВозвращайся ко мне, как только ты разрушишь одну из башен.", progress = nil, completion = "Чтобы убивать врагов, наших воинов нужно рассердить. Они должны знать, что после победы над врагом, награда не заставит себя ждать. Надеюсь это достойная плата за твою службу Орде.", rewards = "Вы получите:\n\nОчки честиОсколок каменного хранителя"}
MultiLanguageQuestData['ru'][13542] = {title = "Против ветра", objective = "Воспользуйтесь лунным колодцем в руинах Аубердина, чтобы уничтожить 8 наручей бесноватого циклона.", description = "Если мы планируем когда-нибудь отвоевать руины Аубердина у последователей Сумеречного Молота, нам надо раз и навсегда разобраться с призванными ими элементалями.\n\nТут-то нам и понадобится твоя помощь.\n\nСлушай, никто и не ожидает, что ты в одиночку освободишь город, но пока мы тут зализываем раны, ты можешь расчистить нам дорогу.\n\nЧтобы окончательно уничтожить бесноватые циклоны, отправляйся на запад, убей элементалей, сними с них наручи и положи в лунный колодец. Если ты уничтожишь наручи, они больше не смогут возродиться.", progress = nil, completion = "Не знаю даже, как отблагодарить тебя, Авелфорт. Теперь у нас появился реальный шанс отвоевать руины, и мы непременно им воспользуемся, как только наберемся сил и залечим раны.", rewards = "Наручи затишьяНаручи невероятного спокойствияВы получите:\n\nПредмет #12"}
MultiLanguageQuestData['ru'][13543] = {title = "Три молота", objective = "Убейте подругу облаков Буйногривую, повелителя ветров Цу-Цу и повелителя небес Браакса.", description = "Меня отправили в руины Аубердина на разведку, и мне удалось засечь трех последователей культа Сумеречного Молота, которые наслали элементалей, захвативших разрушенный город.\n\nОтправляйся на запад, в руины, и убей подругу облаков Буйногривую, повелителя ветров Цу-Цу и повелителя небес Браакса. \n\nТолько тогда у часового Селарины и ее отряда появится шанс отвоевать город.", progress = nil, completion = "Со смертью этих троих поток элементалей в руины Аубердина должен иссякнуть.\n\nСпасибо тебе, Авелфорт.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13544] = {title = "Благословение медведя", objective = "Старейшина Бролг из логова Чернолесья попросил вас принести ему пучок благословенных трав.", description = "Чтобы использовать медвежью лапку для очищения зараженных, надо вплести в пучок трав еще кое-какие ингредиенты и благословить талисман. К северу от деревни бродит долгоног по имени Быстроног: именно его перья годятся для завершения талисмана.\n\nПринеси перья долгонога и пучок медвежьих лапок к древней статуе медведя, которая стоит среди руин в Роще Древних. Это на севере от того места, где бродит Быстроног.\n\nКогда найдешь святилище, свяжи вместе перья и стебли травы. Пусть дух медведя благословит этот букет.", progress = "Ты нашел древнюю статую медведя?", completion = "&lt;Старейшина Бролг принимает у вас из рук благословенный пучок и внимательно его осматривает. &gt;\n\nЭто именно то, что надо! Теперь, когда дух медведя благоволит нам, у моих братьев появилась надежда на спасение.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13545] = {title = "Очищение оскверненных", objective = "Старейшина Бролг просит вас воспользоваться пучком благословенных трав, чтобы очистить 7 фурболгов Чернолесья, после чего убейте духов осквернения, сводивших их с ума.", description = "Теперь, когда у тебя есть священные травы и благословение великого медведя, ты сможешь очистить от скверны моих братьев. Порча, охватившая весь Оскверненный лес, свела их с ума, и теперь они нападают на всех, кто осмелится приблизиться. Приготовьcя к тому, что они будут преследовать и тебя, пока ты не уничтожишь духов зла, которые в них вселились.\n\nОсвободи племя Чернолесья от оков безумия и возвращайся назад.", progress = nil, completion = "Ты хорошо справился. Мой народ постепенно начал освобождаться от оков безумия, но все будет напрасно, если мы не уничтожим источник порчи.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13546] = {title = "Осквернитель", objective = "Старейшина Бролг из логова Чернолесья просит вас убить Шаракса Осквернителя.", description = "Сатиры из племени Нефритового Пламени проникли на Темные берега и теперь оскверняют все, к чему прикасаются их нечестивые лапы – землю, воду и даже живых существ. Ты ведь уже <видел/видела>, что делает порча с моим народом и нашим домом. Если мы не сможем дать отпор сатирам, эта участь постигнет каждого из нас.\n\nШаракс Осквернитель, сатир, ответственный за все беды Чернолесья, скрывается в пещере на востоке отсюда. Убей его, <имя>, освободи эту землю от его зловещего присутствия. Мы должны показать сатирам, что не собираемся сдаваться на их милость!", progress = nil, completion = "Спасибо тебе, Эльффус! Мой народ прославит твое имя, ибо не будь тебя, нас бы ждало безумие и смерть. Пусть дух медведя хранит тебя, куда бы ты ни пошел.", rewards = "Сапоги ЧернолесьяЛук охотника из ЧернолесьяРитуальный посох ЧернолесьяВы получите:\n\n"}
MultiLanguageQuestData['ru'][13547] = {title = "Отделение душ", objective = "Отделите души Тандриса Ветропряда, Элиссы Звездный Ветер, Тальдана и Кайлаис Лунное Перо.", description = "Твои друзья из лагеря беженцев не знают о том, какую угрозу представляет культ Сумеречного Молота для всего мира.\n\nНо прежде, чем ты сможешь разобраться с ними, мы должны получить помощь от мертвецов Аубердина.\n\nОбыщи руины города и найди тела Тандриса Ветропряда, Элиссы Звездный Ветер, Тальдана и Кайлаис Лунное Перо. Отдели их души от тел и возвращайся ко мне.", progress = nil, completion = "Так много смерти и боли... Стоит ли сомневаться, что будет еще хуже?\n\nВсе, что я хочу – следовать дальше своим путем, который приведет меня в объятия богини.\n\nНо сначала давай посмотрим, сможем ли мы предотвратить дальнейшее распространение порчи и разложения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13548] = {title = "Кулек конфет", objective = "Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nКонфета или жизнь\n\nВы получите:\n\nПригоршня конфет"}
MultiLanguageQuestData['ru'][13549] = {title = "Хвост трубой", objective = "По просьбе летописца То'кини из Зим'Торги усыпляйте из воздушного ружья То'кини северных леопардов и ледолапых медведей. Возвращайтесь к нему, поймав по три самки каждого вида.", description = "Помимо артефактов Драккари, меня также интересует животный мир Зул'Драка. Мне бы очень хотелось привезти в Зандалар некоторые образцы местной фауны. У меня уже есть самцы леопарда и ледопалого медведя, но теперь мне нужно несколько самочек!\n\nК великому сожалению, мой ловчий внезапно скончался. Может быть, ты подменишь его?\n\nПожалуйста, возьми это ружье, оно стреляет усыпляющими дротиками. Усыпи зверя и загляни ему под хвост. Запомни – меня интересуют самки. Леопарды и медведи водятся возле алтарей Рунока, Кетц'лун и Хар'коа.", progress = nil, completion = "Это прекрасные экземпляры, Хаширия! теперь у моих коллег будет достаточно материала для изучений.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13554] = {title = "Излечение во тьме", objective = "Добудьте 6 образцов зараженной лимфы существ из Скалистой пещеры.", description = "<Машина издает нечленораздельные звуки, после которых вы наконец-то снова слышите голос Бацбаха.>\n\nСумеречники! Теперь оно взялось за сумеречников! Эти мелкие негодники лезут из пещеры под восточной скалой. Ее легко найти, если следовать по тропинке на северо-восток и искать углубление под водопадом.\n\nТо ли эти сумеречники чем-то отравились, то ли кто-то специально опрыскал их ядом – в любом случае, мы должны выяснить, что это такое!", progress = "Ты принес образцы? Чем раньше я приступлю к исследованиям – тем больше животных мы сможем спасти!", completion = "Этого вполне хватит! Спасибо тебе огромное! Я немедленно займусь изготовлением лекарства.", rewards = "Жилет из крысиной шерстиИспачканный лимфой жилетОскверненный посохВы получите:\n\n"}
MultiLanguageQuestData['ru'][13556] = {title = "Яйца для Дубра'джина", objective = "Соберите 12 яиц ящера Гундрака по заданию Га'ваны из Дубра'джина.", description = "Как дела, <пацан/деваха>? Думаешь, ты сможешь мне помочь? Ба'Кини понадобится много яиц ящера для жертвоприношений Дубра'джину.\n\nЕсли бы не ритуалы, нас давно бы уже поработили драккари! Дубра'джин помогает нам!\n\nСобери яйца ящеров под деревьями здесь, в Гундраке. Иногда ящеры носят их с собой, чтобы держать их в тепле.", progress = "Кто бы мог подумать, что великому Дубра'джину будет нужно столько яиц! Интересно, что он будет с ними делать?", completion = "Ха-ха, достаточно, дружище! Теперь мы надолго в безопасности!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13557] = {title = "Неожиданная удача", objective = "Освободите 8 незараженных колючешерстных медведей или незараженных сумеречников из клеток в Скалистой пещере.", description = "Похоже, это ключ от клеток с животными, которые встречаются по всей Скалистой пещере. Танариун несомненно оценит, если вы проявите инициативу и освободите нескольких незараженных сумеречников и колючешерстных медведей.", progress = "Да, |3-6(Ворген)?", completion = "Я рад слышать, что тебе удалось освободить несколько выживших животных. Если нам повезет, мы отыщем противоядие и спасем остальных.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13558] = {title = "Призывая гром", objective = "Воспользуйтесь ритуальной сферой Эфериона, чтобы добыть сущность Эфериона.", description = "Эферион почти проник в наш мир, но мы все еще можем одержать над ним верх!\n\nВ конце этого причала плавает ритуальный шар. Я прошу тебя завершить ритуал, который привяжет владыку элементалей вдали от водоворота.\n\nПоверь, <имя>, мы с прочими освобожденными душами ослабим Эфериона насколько возможно, но только ты можешь окончательно покончить с ним и спасти народ калдорай от уничтожения.\n\nОтнеси его сущность в лагерь беженцев Корвину Восходу Луны. Пусть он знает, что бояться больше нечего.", progress = "А, ты уже вернулся! Какие новости?", completion = "Айльда? И другие духи с руин Аубердина?\n\n&lt;Друид раздумывает над тем, что вы ему рассказали.&gt;\n\nЯ помню их всех... Печаль переполняет мое сердце, но отныне они обрели покой в объятиях богини, а значит – все было к лучшему.\n\nАнде'торас-этиль, да уменьшатся твои невзгоды.", rewards = "Прочный жилет ЭферионаКольчужные поножи АубердинаВы получите:\n\n"}
MultiLanguageQuestData['ru'][13559] = {title = "Подношение Ходиру", objective = "Простые подношения не были достойны Ходира, когда он еще обретался среди снежных великанов.\n\nИ пусть с нами его уже нет, мы никогда не оставим традицию подношения даров и всегда будем почитать его силу и мудрость. Ты поддерживаешь наши традиции, и это о многом говорит, крохотный |3-6(Паладин).", description = nil, progress = "Простые подношения не были достойны Ходира, когда он еще обретался среди снежных великанов.\n\nИ пусть с нами его уже нет, мы никогда не оставим традицию подношения даров и всегда будем почитать его силу и мудрость. Ты поддерживаешь наши традиции, и это о многом говорит, крохотный |3-6(Паладин).", completion = "Сыны Ходира принимают твое подношение, кроха. Ты не перестаешь доказывать свою ценность как нашего союзника.", rewards = nil}
MultiLanguageQuestData['ru'][13560] = {title = "Океан не столь глубок", objective = "Горбольд Сталерук из Лор'данела просит вас поговорить с Гари и получить у него дальнейшие указания.", description = "О, а ты не робкого десятка, как я погляжу!\n\nСлушай, тут на побережье полно разбившихся кораблей – какие-то совсем новые, какие-то уже давно тиной поросли. Представляешь, сколько там должно быть всяких сокровищ среди обломков? Я вот все думаю – негоже им гнить на берегу, пора найти им другое применение, но моим планам мешает поселение чрезвычайно воинственных мурлоков. Сколько бы я не посылал туда искателей приключений – ни один не вернулся.\n\nДа не пугайся ты так, я с тех пор усвоил урок и не собираюсь отправлять тебя на верную гибель. Тебе надо будет сплавать на север и разыскать моего дружка Гари. Он расскажет тебе, какой у нас есть план. Правда, все просто?", progress = nil, completion = "Значит, приманка сработала так, как и было задумано? Вот здорово! А про сокровища не беспокойся – мы с Гари позаботимся о них в ближайшее время.\n\nЧестно говоря, я боялся, что он вышвырнет меня из города, если я угроблю еще одного лихого искателя приключений.", rewards = "Лук кораблекрушенияВам дадут возможность выбрать одну из следующих наград:\n\nСияющий глаз мурлока\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13561] = {title = "Утешение для высокорожденного", objective = "Убейте 6 проклятых высокорожденных и 6 терзаемых высокорожденных.", description = "Я прибыла на руины Башал'Аран, чтобы даровать покой мятущимся душам высокорожденных, но с каждым ударом меча решимость моя слабеет. Если ты можешь помочь мне в этом нелегком деле, благодарность моя не будет иметь границ.", progress = nil, completion = "Спасибо, Рэтрак, и знай, что души высокорожденных тоже тебе благодарны, хотя и не могут это высказать.\n\nДа будет безопасной твоя дорога, путешественник.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13562] = {title = "Последние огни Башал'Арана", objective = "Погасите последний огонь Башал'Арана.", description = "Настало время остановиться и задуматься о нашей жизни. Отныне мы смертные, как бы нам ни хотелось обратного, и мы заслуживаем нового места в этом мире.\n\nЕсли следовать по дороге на юг, можно увидеть руины Башал'Арана, города, где некогда жили наши предки. Теперь там обитают лишь их проклятые души. Если мы хотим обрести спасение, нельзя позволить им страдать еще дольше. Настало время погасить последние огни Башал'Арана.", progress = nil, completion = "Прими мою благодарность. Для нас настало время забыть о прошлом и начать смотреть в будущее.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13563] = {title = "Вечная любовь", objective = "Освободите душу Анайи Вестницы Зари и добудьте ее подвеску.", description = "Прими мою благодарность за спасение наших жизней. Я бы считал себя счастливцем, если бы только моя возлюбленная супруга Анайя была сейчас со мной. Увы, она давно покоится в земле, и удел мой – печаль и одиночество. Не окажешь ли ты мне еще одну услугу?\n\nВскоре после нашего освобождения дороги привели меня к руинам Башал'Аран... и представь себе мой ужас, когда я увидел там мятущуюся душу моей любимой!\n\nЯ должен был освободить ее, но мне не хватило смелости. Может быть, ты сможешь уничтожить ее призрак?", progress = "Мне как-то удалось избежать заражения тем ядом, от которого страдают остальные выжившие. Я ничем не могу помочь им, только позавидовать... лучше уж умереть, чем жить целую вечность в одиночестве.\n\nЯ так скучаю по тебе, Анайя.", completion = "Благодарю тебя, Рэтрак. Может быть, было бы лучше... если бы я сам это сделал. Но даже после прошедших тысячелетий у меня нет сил поднять руку на свою возлюбленную.\n\nПожалуйста, оставь меня наедине с моим горем...", rewards = "Поножи неугомонностиВыброшенный щитВы получите:\n\n"}
MultiLanguageQuestData['ru'][13564] = {title = "Пропавший спутник", objective = "Найдите Лютого Когтя.", description = "Пожалуйста, помоги мне... видишь же, я едва могу подняться на ноги.\n\nМой единственный друг, медведь по имени Лютый Коготь, оставил меня. Я сам отослал его вперед, чтобы предупредить часовых о нашем прибытии из Аубердина, но он так и не вернулся. Я чувствовал, что что-то может пойти не так во время бегства из города... но мне не представился шанс предотвратить беду. \n\nЕсли Лютый Коготь был ранен, он мог отправиться только в одно место – в Увядающую рощу на севере Аубердина. Иди по дороге на юг, и ты непременно его отыщешь. Приведи его назад целым и невредимым... у меня нет друга ближе, чем он.", progress = nil, completion = "Приветствую тебя, путешественник. Похоже, тебя интересует мой друг. Полагаю, тебя прислал Волкор? Если он не явился сам, значит, он тоже ранен. Остается только надеяться, что он вскоре поправится.\n\nЛютый Коготь тоже не смог далеко уйти, и ему нужна срочная медицинская помощь. Боюсь, я не могу пока пустить тебя к нему, но ты можешь поспособствовать его скорейшему выздоровлению.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13565] = {title = "Уничтожить дважды", objective = "Воспользуйтесь окаменелым корнем, чтобы поднять из небытия 6 иссхоших энтов, и убейте предводительницу наг Леди Жаниру.", description = "Не в наших правилах мириться с бессмысленной жестокостью, хотя сейчас настали такие времена, когда уклонение от битвы может принести больше вреда. Я, разумеется, говорю о нагах.\n\nКогда эта земля пошатнулась, на востоке отсюда появились над поверхностью руины древнего дворца. Когда-то в нем обитали верные приспешники королевы Азшары, и теперь их потомки вернулись на это место в поисках чего-то важного.\n\nВозьми этот окаменелый корень: с его помощью ты сможешь призвать на помощь иссохших энтов. Пусть твоя армия уничтожит наг и их предводителя.", progress = nil, completion = "Спасибо тебе, друг. Мы должны готовиться к их возвращению.", rewards = "Сапоги мхаНаручи из чешуи нагиВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13566] = {title = "Ингредиенты для ритуала", objective = "Добудьте 3 уса лунопарда, 3 клочка шерсти пятнистой оленихи и 3 клочка меха колючешерстного медведя.", description = "Пока мы заботимся о Лютом когте, я хочу, чтобы ты тихо-спокойно <пособирал/пособирала> кое-какие элементы дикой природы для проведения ритуала.\n\nВо-первых, мне потребуются усы лунопардов, обитающих на западе: подкрадись к спящему зверю, выдерни несколько волосков и беги прочь.\n\nЗатем тебе надо будет добыть шерсть оленихи – да смотри, не перепутай с оленем!\n\nИ наконец, мне нужен мех медведей, что рыбачат на северо-востоке. Дождись, когда им в лапы попадется рыба, выдерни клочок меха и убегай, пока они не нашли себе еду получше.\n\nНо прошу тебя, не убивай ни одно живое существо!", progress = "Ты принес нужные мне материалы?", completion = "То, что надо! Это были последние ингредиенты, необходимые для проведения ритуала. Подожди, сейчас я тебе все объясню – только смешаю их воедино.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13567] = {title = "Дух оленя", objective = "Хранитель Каритий велел вам получить благословение великого духа оленя.", description = "В лесах этих живут три великих духа – дух Оленя, Колючешерстного медведя и Лунопарда. Они могут стать нам могущественными союзниками, если только ты сможешь получить благословение одного из них.\n\nЕсли ты хочешь пообщаться с духом Великого оленя, возьми эти благовония и отнеси в леса к северу от Башал'Аран. Помедитируй, сжигая благовония, и дух появится пред тобой, чтобы подвергнуть тебя испытанию. Если ты исполнишь его волю, возвращайся ко мне.", progress = nil, completion = "Я хранитель моего рода, и путь наш – не грубая сила, а мудрость и ловкость. Мудрость ведет нас среди непролазной чащи, где за каждым кустом поджидает опасность, а ловкость приводит в ужас наших врагов.\n\nВ мудрости своей я вижу твои истинные намерения и знаю, что ты ищешь только моего благословения, благословения ловкостью. Она может стать твоей, но знай: приняв мой дар, ты не сможешь уже обратиться к другим духам.", rewards = nil}
MultiLanguageQuestData['ru'][13568] = {title = "Дух лунопарда", objective = "Хранитель Каритий велел вам получить благословение великого духа лунопарда.", description = "В лесах этих живут три великих духа – дух Оленя, Колючешерстного медведя и Лунопарда. Они могут стать нам могущественными союзниками, если только ты сможешь получить благословение одного из них.\n\nЕсли ты хочешь пообщаться с духом Великого лунопарда, возьми эти благовония и отнеси к югу от Руин Лорнесты. Помедитируй, сжигая благовония, и дух появится пред тобой, чтобы подвергнуть тебя испытанию. Если ты исполнишь его волю, возвращайся ко мне.", progress = nil, completion = "Я по доброй воле делю эти леса с ночными эльфами, и в какой-то мере считаю их друзьями. Хотя в последнее время они отвернулись от пути света, я все еще вижу в них ту же силу духа и честь, которые так поразили меня при нашей первой встрече.\n\nЕсли тебе нужна моя ярость, чтобы преодолеть все трудности, то я с радостью назову тебя моим защитником. Но знай: если ты встанешь на мою сторону, другие духи не станут тебе помогать.", rewards = "Следующее заклинание будет наложено на вас:\n\nRitual Bond Quest Complete"}
MultiLanguageQuestData['ru'][13569] = {title = "Ритуальное грозовое облако", objective = "Вдохните эссенцию перед хранителем Каритием и примите благословение одного из великих духов: оленя, колючешерстного медведя или лунопарда.\n\nУчтите, что вы можете получить благословение только одного духа.", description = "Пока Лютый Коготь отдыхает, я буду сторожить его сон. Очень скоро он вернется к нам, но до тех пор тебе придется выполнить еще одно мое поручение. Надеюсь, ты тоже сочтешь эту миссию почетной.\n\nВокруг нас обитают великие духи дикой природы, которые ждут и надеются, что кто-то сможет помочь им остановить разрушение. Даже сейчас они присутствуют при нашем разговоре, и теперь я могу помочь тебе увидеть их. Поговори с этими духами, выбери одного из них и получи его благословение.", progress = nil, completion = "Итак, дело сделано. Ты получил благословение духа великого зверя, и я теперь могу завершить для тебя ритуал. Стой спокойно и не двигайся.", rewards = "Наручи лунопардаПлащ Короля оленейРемень колючешерстного медведяСледующее заклинание будет наложено на вас:\n\nРитуальная связь\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13570] = {title = "Воспоминания об Аубердине", objective = "Я просто хотел искренне поблагодарить тебя за все, что ты сделал для нас. Боюсь, что в своей печали мы забыли о том, что без твоей помощи мы бы не выжили.\n\nЗнай, что здесь тебя всегда ждут друзья.\n\nИ не беспокойся, что оставляешь меня одного. Лютый Коготь часто меня навещает, и, надо сказать, он оказался весьма приятным собеседником.\n\nПрими мой подарок и мои благословения. Когда-нибудь мы встретимся вновь, Авелфорт.", description = nil, progress = nil, completion = nil, rewards = "Кинжал КириллианаКинжал Белого КогтяЛук Темных береговВы получите:\n\nЧахлик"}
MultiLanguageQuestData['ru'][13571] = {title = "Бюро находок Флетчера", objective = "Вы чувствуете, как сквозь кислый запах немытого тела пробивается знакомый аромат! Похоже, этот некогда могучий искатель приключений знает толк в кунгалуше.\n\nВсматриваясь в пленника сквозь прутья решетки, вы едва различаете строки рецепта, нацарапанные у него на руке...", description = nil, progress = nil, completion = nil, rewards = "Вы изучите:\n\nКунгалуш\n\nСледующее заклинание будет наложено на вас:\n\nКунгалуш"}
MultiLanguageQuestData['ru'][13572] = {title = "Жаровни Нефритового Пламени", objective = "Грен Деримех из логова Чернолесья просит вас уничтожить 8 жаровен Нефритового Пламени.", description = "Сатиры Оскверненного леса стали распространять свою заразу на наших землях. Они послали Шаракса Осквернителя в рощу, которую мы, племена Чернолесья, зовем своим домом.\n\nЭто существо не только отравляет почву, растения и живых существ, но также вкапывает жаровни Нефритового Пламени вокруг всей деревни, чтобы подчинить себе жителей. Чтобы остановить его, недостаточно просто уничтожить жаровни... но старейшина Бролг утверждает, что это может помочь освободить разум наших братьев.", progress = nil, completion = "Спасибо тебе, Авелфорт. С твоей помощью нам, возможно, удастся спасти то, что осталось от Чернолесья.", rewards = "Рваный меховой поясВысокие ботинки пожараВы получите:\n\n"}
MultiLanguageQuestData['ru'][13573] = {title = "Возвращение Малфуриона", objective = "Найдите Малфуриона Ярость Бури в Оке Урагана, что к юго-востоку от лагеря беженцев на Темных берегах.", description = "О пробуждении Малфуриона мы узнали буквально за несколько мгновений до того, как разразился Катаклизм.\n\nПридя в себя, он немедленно изрек таинственное предупреждение о том, что земля эта может расколоться, и половина темных Берегов уйдет в океан, если мы не примем своевременные меры.\n\nЗатем он снова исчез куда-то, и меня отправили на его поиски, но для меня сейчас важнее спасти жизни этих беженцев.\n\nПослушай, может быть ты поищешь его где-нибудь на юго-востоке?", progress = nil, completion = "У нас не осталось времени, |3-6(Друид). Все мои силы уходят на то, чтобы удержать земли Темных Берегов от разрушения... поэтому слушай меня внимательно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13575] = {title = "Эта земля в их крови", objective = "Поговорите со старейшиной Карелапом в Лагере Чернолесья к юго-западу от Ока урагана.", description = "Если мы хотим привести в равновесие силы природы, нам потребуется вся помощь, которую мы только можем получить. Я хочу обратиться к фурболгам Чернолесья, которые издавна жили на этой земле.\n\nИх старейшина, шаман Карелап, имеет великую власть над стихиями, и его поддержка была бы неоценимой, если только тебе удастся привлечь его на нашу сторону.", progress = nil, completion = "Я очень уважаю великого Малфуриона, но не могу оставить свой народ в беде. Возможно, мы сможем как-то помочь друг другу?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13576] = {title = "Взаимная помощь", objective = "Воспользуйтесь успокаивающим тотемом, чтобы поглотить останки 8 вольных духов огня.", description = "Сейчас, когда большинство наших братьев ступили на путь безумия или пали жертвой порчи, нам ничего не остается, кроме как откликнуться на твой призыв, <раса>. Можешь рассчитывать на нашу помощь... если, конечно, взамен ты поможешь нашему племени.\n\nКак видишь, мои люди не могут справиться с элементалями огня. Уничтожь их и воспользуйся этим тотемом, чтобы развеять пепельные останки.\n\nПусть возвращаются туда, откуда пришли... и неважно, хотят они этого или нет.", progress = nil, completion = "Огонь коварен, Авелфорт. Попытавшись уничтожить его, можно раздуть еще более страшный пожар... но мы будем действовать осмотрительно.", rewards = "Обожженные сапогиОпаленный щитВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13577] = {title = "Последний совух", objective = "Поговорите с Арумом в Осененной луной берлоге к северу от Ока Урагана.", description = "Когда-то диких совухов было много на Темных Берегах, но после Катаклизма их связь с землей оборвалась, что не могло не сказаться на их численности.\n\nДикий совух Арум – последний из своего племени, кто еще помнит о родстве с Элуной, и его помощь в исцелении земли будет неоценима. Разыщи его на севере, в Осененной луной берлоге.", progress = nil, completion = "Весь облик существа выражает безысходную печаль. Оно смотрит куда-то поверх вас и, кажется, даже не замечает вашего приближения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13578] = {title = "Прощание с Аруном", objective = "Добудьте 8 перьев убитых совухов.", description = "<Зверь грустно ухает, поворачиваясь к вам лицом.>\n\nАрум – последний из племени...\n\nДругим не обрести покоя, пока не зажжен погребальный костер. Принеси Аруму перья других... даруй им покой.\n\nТогда Арум поможет тебе.", progress = "Ты принес перья других?", completion = "Спасибо тебе, |3-6(ночной эльф). Скоро мои родичи обретут покой.", rewards = "Кинжал из когтя совухаПояс из перьев дикого совухаВы получите:\n\n"}
MultiLanguageQuestData['ru'][13579] = {title = "Защитник Амет'Арана", objective = "Поговорите с Селенном на руинах Амет'Арана.", description = "Ничто не исцелит землю быстрее, чем жизненная сила ее обитателей. Нам, ночным эльфам, повезло иметь таких союзников, которые не только живут в этих местах, но и являются их частью.\n\nК югу отсюда обитает древо войны, известное под именем Селенн. Давным-давно ему было поручено охранять руины Амет'Арана. Разыщи его и попроси о помощи.", progress = nil, completion = "Если великому Малфуриону понадобилась моя помощь, то долг мой – откликнуться на его зов. Но я не могу оставить эти руины без защиты...\n\nМожет быть, ты поможешь мне исполнить обе мои обязанности?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13580] = {title = "Успокоение стихий", objective = "Поместите заряженный успокаивающий тотем на вершину скалы рядом с Искристым берегом и защищайте его, пока ритуал не будет завершен.", description = "Теперь их мятежные души заключены в этом тотеме. Отнеси его на вершину Острых рифов, что рядом с Искристым берегом, и установи на землю.\n\nПусть умиротворяющая сила тотема окутает духов стихий и успокоит их гнев. \n\nНо тебе придется защищать тотем, иначе огонь может прервать ритуал успокоения.", progress = nil, completion = "Мы все у тебя в долгу, Авелфорт. Возможно теперь, заручившись помощью Малфуриона, мы сможем спасти Темные берега.", rewards = "Жилет ворожеяОгненные наручиВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13581] = {title = "Дар Чернолесья", objective = "Вернитесь к Малфуриону Ярость Бури в Око Урагана.", description = "Хотя результат твоих действий появится не сразу, я знаю, что рано или поздно гнев стихий утихнет, и мой народ сможет дожить до новой битвы.\n\nВы с Малфурионом можете рассчитывать на мою помощь.", progress = nil, completion = "Нам повезло, Авелфорт. Возможно, фурболги – дикий народ, но их связь с землей уходит корнями в глубокую древность, а их шаманы никому не уступают в своей силе.", rewards = "Следующее заклинание будет наложено на вас:\n\nEye of the Vortex - Detect Quest Invisibility 1\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13582] = {title = "Огонь Элуны", objective = "Добудьте факел Элуны у Хору Хранителя пламени.", description = "Для совершения ритуала нам нужно особенное пламя – пламя Элуны.\n\nК востоку отсюда бродит неприкаянный дух Хору. Хору хранит факел Элуны. Принеси пламя сюда, помоги упокоить духов.\n\nАрум благодарен будет.", progress = "Факел у тебя?", completion = "&lt;Арум испускает долгий, протяжный вой.&gt;\n\nНаконец-то мои родичи обретут покой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13583] = {title = "Клятва совуха", objective = "Вернитесь к Малфуриону Ярость Бури в Око Урагана.", description = "Дикие совухи следуют пути Элуны. Арум в долгу у тебя.\n\nАрум поможет тебе. Возвращайся к Малфуриону, я скоро присоединюсь к вам.", progress = nil, completion = "Некогда совухи были хранителями этой земли. Хорошо, что они не забыли обычаи предков.", rewards = "Следующее заклинание будет наложено на вас:\n\nForce Reaction 1\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13584] = {title = "Колыбельная для Земли", objective = "Убейте 8 разъяренных элементалей земли.", description = "Если я сейчас оставлю пост, это будет прямым нарушением моих обязанностей. Слишком много духов стихий еще бродят по этим руинам...\n\nДавай сначала разберемся с элементалями, а потом посмотрим, чем можно помочь Малфуриону. Что скажешь, <малыш/малышка>?", progress = "Эта земля ужасно пострадала, Нфздлок. Пройдут годы, прежде чем покой воцарится в этих краях.", completion = "Теперь мне все ясно, Авелфорт. Духи стихий не успокоятся, пока Малфурион не восстановит природный баланс. В таком случае мой долг – помочь ему.", rewards = "Покрытый землей доспехСотворенный землей посохВы получите:\n\n"}
MultiLanguageQuestData['ru'][13585] = {title = "Клятва защитника", objective = "Поговорите с Малфурионом Яростью Бури в Оке Урагана, что на Темных берегах.", description = "Сначала я должен исполнить свой долг в этом месте. Пожалуйста, скажи Малфуриону, что я присоединюсь к нему, как только смогу.\n\nУдачи тебе, <имя>. Удачи всем нам.", progress = nil, completion = "Ты молодец, Фаервулф! С помощью Селенна мы, возможно, сможем удержать смерч.", rewards = "Следующее заклинание будет наложено на вас:\n\nEye of the Vortex - Detect Quest Invisibility 3\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13586] = {title = "Изумрудный сон", objective = "Пройдите сквозь портал кошмаров в Пещеру землекрушителя и поговорите с Тессерой.", description = "Похоже, наших усилий по предотвращению дальнейшего разрушения земли оказалось недостаточно. Боюсь, нам придется прибегнуть к помощи из потустороннего мира.\n\nСектанты культа Сумеречного Молота открыли проход в населенный кошмарами мир Изумрудного Сна; там они держат в плену зеленого дракона Тессеру.\n\nОтправляйся в портал кошмаров и освободи ее. Она станет нам могущественным союзником.", progress = nil, completion = "Малфурион призывает меня? Да... я слышу его голос сквозь пелену сна...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13587] = {title = "Ходячий кошмар", objective = "Добудьте изумрудный свиток у стража кошмара в Пещере землекрушителя.", description = "Малфурион говорит правду, <малыш/малышка>: эта трещина, что грозит расколоть Темные Берега, также угрожает безопасности границы между этим и твоим миром.\n\nПозволь мне помочь тебе, ибо над этим местом тоже нависла угроза уничтожения. \n\nПрежде всего тебе надо будет снять с меня эти заколдованные цепи, но сделать это можно только с помощью изумрудного свитка стражей кошмара, что бродят в залах под нами.", progress = "Ты нашел его, Авелфорт?", completion = "Спасибо тебе, Авелфорт. Благодаря тебе я обрела свободу. А теперь давай посмотрим, что я могу сделать для твоего мира.", rewards = "Вы получите:\n\nПодарок Тессеры"}
MultiLanguageQuestData['ru'][13588] = {title = "Око бурь", objective = "Оседлайте Тессеру и убейте 12 наездников из культа Сумеречного Молота, а также уничтожьте сумеречный портал.", description = "Небеса над вихрем патрулируют всадники Сумеречного Молота, и я боюсь, что их магия не дает нам укротить разрушительные силы катаклизма.\n\nПусть Тессера поднимет тебя в воздух, чтобы ты <смог/смогла> уничтожить всадников и портал, откуда они явились.", progress = nil, completion = "Мы переломили ход битвы, Авелфорт, но впереди еще много работы.", rewards = "Изумрудный жилетМолот закрывающего порталыВы получите:\n\n"}
MultiLanguageQuestData['ru'][13589] = {title = "Захватчики из племени Пронзающего Копья", objective = "Разыщите лейтенанта Морру Звездный Ветер на руинах Матистры.", description = "Кажется, будто сама земля и все стихии ополчились на нас! Можно подумать, нам было мало этих проблем – так еще и тролли с северо-запада встали на тропу войны. Не знаю, что на них нашло и чего они добиваются, но они уже напали на нескольких разведчиков и осадили служителей культа в Башне Алталакса.\n\nМы послали наших лучших часовых устранить эту угрозу, но им наверняка понадобится помощь. Их отряд можно найти на северо-востоке, возле руин.", progress = nil, completion = "Это Глинда тебя прислала? Спасибо ей, лишняя пара рук нам пригодится.\n\nЯ разрабатываю первоначальный план нападения на их войско, но ты пока можешь предложить свою помощь Тише и Балтулу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13590] = {title = "Передовая", objective = "Доложите Охотнице Сандрии Закат Луны, которую можно найти в долине Пронзающего Копья.", description = "Их силы на исходе, припасы уничтожены, а помощники командира мертвы. Настало время нанести удар в самое сердце их поселения и уничтожить предводителя. Я все еще не понимаю, что вызвало такую агрессию с их стороны, но возможно мы найдем ответы в их лагере.\n\nВозьми стрелу, которую подготовил Балтул, и присоединись к отряду охотницы Сандрии Закат Луны в долине Пронзающего Копья. Советую тебе поехать на одном из наших ночных саблезубов – дороги нынче небезопасны.", progress = "Приветствую тебя, |3-6(Друид). Ты принес стрелу?", completion = "Приятно познакомиться! До меня дошли слухи о той неоценимой помощи, которую ты оказал в борьбе с троллями. Надо сказать, я впечатлена. Но последняя битва еще ждет впереди – надеюсь, ты к ней готов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13591] = {title = "Странные совпадения", objective = "Принесите Послание Адского Крика стрелку Глинде Нал'Шие в Лор'данел.", description = "Это письмо от Гарроша Адского Крика всколыхнуло подозрения, которые возникли у нас во время нападения Пронзающего Копья. Теперь понятно, что присутствие Отрекшихся на руинах башни и припасы орды в боевом лагере – звенья одной цепочки. Гаррош сам сподвиг троллей Пронзающего Копья напасть на Лор'данел, и теперь у меня нет сомнений в том, что он продолжит наступление на юг.\n\nНочные эльфы должны быть готовы к нападению! Немедленно передай эту информацию Глинде Нал'Шие.", progress = "Ты вернулся с победой!", completion = "Воистину тревожные новости. Я немедленно пошлю гонцов в Ясеневый лес и постараюсь выделить людей им на помощь.\n\nНе знаю даже, как отблагодарить тебя за все, что ты сделал для нас в эти нелегкие времена. Такие поступки заслуживают великой награды.", rewards = "Вышитый серебром плащЧеканные серебряные сапогиЧешуйчатый серебряный поясВы получите:\n\n"}
MultiLanguageQuestData['ru'][13592] = {title = "Теория и практика", objective = "Убейте 10 обращенных героев по заданию сэра Маркуса Барлоу из Павильона Серебряного союза на Ристалище Серебряного турнира.", description = "Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.\n\nОтправляйся на юго-запад Долины павших героев, что к северу от Корп'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.", progress = "Испытал ли ты свои силы в борьбе с Плетью?", completion = "С возвращением, Ренгольд. Даже во время тренировок мы не должны забывать о реальной угрозе, с которой придется иметь дело после окончания турнира.", rewards = "Вы получите:\n\nПечать искателя славы"}
MultiLanguageQuestData['ru'][13593] = {title = "Искатель славы из Штормграда", objective = "Если вы хотите стать искателем славы Штормграда, поговорите еще раз с маршалом Якобом Алерием в Павильоне Серебряного союза.", description = "Приветствую тебя, чемпион. Я наслышан о твоих достижениях! Буду рад включить тебя в число участников делегации Штормграда, если ты желаешь к нам присоединиться.\n\nТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Штормграда позволит тебе выступать под нашим флагом.", progress = nil, completion = "Добро пожаловать, Асмариэль. Штормград рад принять тебя в ряды своих воинов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13594] = {title = "Не забывайте про Орду", objective = "Убейте 10 ордынцев в Убежище Батрана.", description = "Конечно, от Эвенара и других учеников будет мало толку в бою, чего не скажешь о тебе. Давно пора преподать урок ордынским мерзавцам, которые бродят по дороге к востоку от Убежища Батрана.\n\nИх новый вождь, Гаррош Адский Крик, явно задумал что-то недоброе. Так что, покажешь им, где раки зимуют?\n\nЧестное слово, я бы пошла вместе с тобой, но моя задача – защищать учеников Орендила, поэтому я останусь на месте.", progress = nil, completion = "&lt;Какое-то время часовой с одобрением смотрит на вас.&gt;\n\nЕще одна работа выполнена с блеском! Если бы на нашей стороне сражались только такие искатели приключений, как ты, мы бы мигом разделались с Ордой!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13595] = {title = "Ни пряди волос", objective = "Бросьте бутыль буйного огня на тело Батрана и сожгите его.", description = "Эти твари, называющие себя ордынцами... они срезали меня в самом расцвете сил, и теперь добывают мои волосы для своих зловещих планов.\n\nТы $Gдолжен:должна; положить этому конец, <маленький/маленькая:r> <раса>!\n\nЯ слышал, как их травники говорили о некоем буйном огне, стоящем на их столах. Если ты сможешь выкрасть бутылку огня и сжечь этим бесовским зельем мой труп, они не получат больше ни пряди моих волос!\n\nЯ уже мертв, так что могу заплатить столь невысокую цену за возможность остановить моих мучителей.", progress = nil, completion = "Ты помог мне вновь ощутить прикосновения земли. \n\nТеперь мои волосы придушат этих мерзких существ, и вскоре ветви мои вновь наполнятся жизненной силой.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13596] = {title = "Планы Сумеречного Молота", objective = "Добудьте 6 планов Сумеречного Молота из их лагеря.", description = "Мы не знаем, какую цель преследуют последователи культа Сумеречного Молота на юго-западе, но я боюсь, что они осмелятся напасть на Лор'данел – а то и совершить что-нибудь похуже.\n\nПослушай, отправляйся в лагерь Сумеречного Молота и раздобудь их военные планы. И поторопись, ради всего святого – возможно, у нас осталось не так уж много времени.", progress = "Планы уже у тебя в руках, Авелфорт?", completion = "Молодец, Авелфорт. А теперь дай-ка мне взглянуть на эти планы...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13597] = {title = "Дух колючешерстного медведя", objective = "Хранитель Каритий велел вам получить благословение великого духа колючешерстного медведя.", description = "В лесах этих живут три великих духа – дух Оленя, Колючешерстного медведя и Лунопарда. Они могут стать нам могущественными союзниками, если только ты сможешь получить благословение одного из них.\n\nЕсли ты хочешь пообщаться с духом колючешерстного медведя, возьми эти благовония и отнеси в пещеру к востоку от великого Водоворота. Помедитируй, сжигая благовония, и дух появится пред тобой, чтобы подвергнуть тебя испытанию. Если ты исполнишь его волю, возвращайся ко мне.", progress = nil, completion = "Бесчисленные года я бродил по этим лесам и жил среди этих гор. Сквозь огонь и лед я видел смерть великих народов: они уступали дорогу природе. Теперь, когда сама земля обернулась против нас, мы должны сражаться за наше будущее.\n\nСердце твое чисто, и потому я выбираю тебя нашим защитником. Если ты ценишь густые леса, если ты заботишься о выживании моего рода – прими мой дар. Подумай хорошо прежде, чем сделать выбор, ибо после того, как решение будет принято, другие духи не смогут принять тебя.", rewards = "Следующее заклинание будет наложено на вас:\n\nRitual Bond Quest Complete"}
MultiLanguageQuestData['ru'][13598] = {title = "Горькое лекарство", objective = "Разыщите 6 дымных поганок.", description = "За Лютого Когтя можешь не волноваться – моя исцеляющая магия поставит его на ноги, хотя не могу сказать того же о напавшем на него браконьере. Я мог бы перевязать его раны и наложить лекарственную мазь, которая уменьшит боль и поспособствует выздоровлению, но мне не хватает кое-каких компонентов для ее изготовления.\n\nОтправляйся на восток к руинам Лорнестры. Там, среди мха и камней в изобилии растут дымные поганки; собери несколько штук, и я изготовлю из них лекарство для нашего дружка.", progress = "Лютый Коготь – великий воин. Не завидую я этим браконьерам, напавшим на него.", completion = "Прими мою благодарность, малыш. С помощью этой мази Лютый Коготь гораздо быстрее встанет на ноги.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13599] = {title = "Возвращение Лютого Когтя", objective = "Вернитесь к Волкору и Лютому Когтю в Лор'данел.", description = "Итак, все ингредиенты собраны, благословение получено. Теперь тебе будет значительно проще путешествовать по этим дорогам.\n\nЧто же до Лютого Когтя, то он полностью оправился от ран и устремился в Лор'данел прежде, чем я смог его остановить. Полагаю, это значит, что и тебе пора отправиться в путь.\n\nМне было очень приятно познакомиться с тобой. Передавай привет Волкору и Лютому Когтю.", progress = nil, completion = "Ты вернулся! Рада видеть тебя снова. Полагаю, это тебя нам стоит благодарить за спасение Лютого Когтя?\n\nУвы, у меня для тебя плохие новости. Мне не удалось нейтрализовать яд, и их состояние резко ухудшилось... Гершалла умерла вскоре после твоего ухода, а Волкор... Волкор чуть-чуть тебя не дождался.\n\nНо он успел узнать о возвращении Лютого Когтя, так что он умер с улыбкой на устах. Прости, что я не смогла ему помочь.\n\nА сейчас извини меня – я все еще не теряю надежды спасти Шалдин.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13600] = {title = "Достойное оружие", objective = "Принесите меч Драк'Мара маршалу Якобу Алерию в Павильон Серебряного союза на Ристалище Серебряного турнира.", description = "Что за невезение!\n\nМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!\n\nОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул'Драком и Седыми холмами. И попроси у девы хороший клинок.", progress = "Ну что – бард не соврал? Где меч?", completion = "&lt;Маршал принимает у вас меч Драк'мара.&gt;\n\nПрекрасное оружие, отлично сбалансировано... этот клинок сослужит мне добрую службу в следующем поединке.", rewards = "Вы получите:\n\nПечать искателя славыПредмет #4"}
MultiLanguageQuestData['ru'][13601] = {title = "На помощь беженцам", objective = "Часовой Лендра из Лор'данела просит вас поговорить с жрицей Алинией в Лагере беженцев.", description = "Во имя Элуны! Люди, которых мы считали погибшими при нападении на старый Аубердин, смогли избежать смерти и укрылись в лагере за руинами города.\n\nНо последователи культа Сумеречного Молота узнали, где они прячутся, и намереваются разделаться с выжившими. Нам повезло, что твоя атака отвлекла их от этого замысла.\n\nПожалуйста, как можно скорее разыщи жрицу Алинию в Лагере беженцев. Его точное местоположение – на востоке от старого Аубердина и далеко на юге отсюда.", progress = nil, completion = "Спасибо за то, что пришел нам на помощь. Как видишь, у выживших беженцев дела плохи.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13602] = {title = "Наги Зорамского взморья", objective = "Убейте 15 наг из клана Зловещего Хвоста на Зорамском взморье.", description = "Зло обитает на западном побережье, <имя>.\n\nДавным-давно на Зорамском взморье стоял проклятый город Зорам, павший во время Раскола мира, и руины его поглотило море. Так он был потерян для ночных эльфов, и мало кто помнит о его существовании.\n\nТеперь наги вернулись, и мы не знаем, зачем они пришли. Но причины не столь важны; важно то, что надо сделать – убить этих демонов и сбросить их тела в пучину, из которой они вышли!", progress = nil, completion = "Прекрасно, Тихийпутя. Твои действия на Зорамском взморье достойны похвалы.\n\nЯ представляю, как нелегко сражаться с нагами – ночные эльфы не понаслышке знают об их силе и коварстве. Увы, но судьбы наших рас издавна переплетены.\n\nНаги – это проклятые высокорожденные. Десять тысяч лет назад Королева Азшара заключила отчаянный союз с древними богами, дабы спасти свой народ от гибели в пучине.\n\nНаги появились в результате этого союза.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13603] = {title = "Клинок, достойный чемпиона", objective = "Раздобудьте меч Ясеневого озера и принесите его маршалу Якобу Алерию в Павильон Серебряного союза на Ристалище Серебряного турнира.", description = "Честно выкованные клинки нынче не в моде. Все мои соперники обзавелись заколдованными мечами, где мне с ними тягаться. Однако не все еще потеряно.\n\nДревняя легенда рассказывает о девушке, живущей в Седых холмах, у которой есть замечательный волшебный меч... Но вот незадача, ее превратили в лягушку, чтобы никто не смог заполучить этот клинок. Теперь она живет среди лягушек на Ясеневом озере, что к востоку от Ясеневой заставы. Говорят, что чары может развеять только поцелуй. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.", progress = "Тебе удалось достать меч?", completion = "Значит, легенда оказалась правдой? Прекрасный меч! С ним я выиграю любой турнир. Большое тебе спасибо, Афлоэль.", rewards = "Вы получите:\n\nПечать искателя славы"}
MultiLanguageQuestData['ru'][13604] = {title = "Диск доступа к Архиву", objective = "Отнесите диск доступа к Архиву к панели управления Архивом в Ульдуаре.", description = "Платиновый диск правильной формы выглядит совершенно новым – на нем нет ни единой царапины. По краю его выгравирована руническая надпись: \"АРХИВ\".\n\nДолжно быть, в глубинах Ульдуара есть устройство, с помощью которого можно прочитать этот диск.", progress = "Гнездо приемника открывается, а панель управления жужжит и вибрирует.", completion = "Платиновый диск идеально подходит к гнезду на панели. Он начинает вращаться, белые лучи считывают с него какую-то информацию.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13605] = {title = "Последний выживший", objective = "Сопроводите археолога Холли в безопасное место.", description = "Земля содрогнулась... и все почернело у меня перед глазами. Я очнулась уже здесь, закованной в цепи, и вокруг было полно духов воздуха!\n\nЧто же произошло, хотелось бы мне знать? Надеюсь, эти мерзавцы-сектанты Сумеречного Молота не тронули моих друзей!\n\nА ты, <класс>, не стой столбом, возьми какой-нибудь ломик и разбей эту проклятую цепь. Вместе мы сможем добраться до лагеря беженцев.", progress = nil, completion = "А, ты тот самый славный парнишка, который спас мою Холли!\n\nЯ тут припасла для тебя кое-что: надеюсь, тебе понравится. Право же, не знаю, как еще мы можем тебя отблагодарить.", rewards = "Шаровары археологаБрюки археологаКопательный посохВы получите:\n\n"}
MultiLanguageQuestData['ru'][13606] = {title = "Печать Фрейи", objective = "Добудьте печать Фрейи по заданию геолога Дорена.\n\nЗа дополнительными сведениями обратитесь к панели управления Архивом.", description = "Печать Фрейи достать будет сложнее всего.\n\nСогласно данным из Архива, сущность печати связана с тремя старшими слугами Фрейи – Светлым Листом, Железной Ветвью и Каменной Корой. Если хоть один из них пострадает, сущность печати будет повреждена.\n\nНо если ты пощадишь слуг, силы Фрейи приумножатся.\n\nЧто еще сказать, <имя>... оказались мы между молотом и наковальней.", progress = "Ты добыл печать Фрейи, Айрендил?", completion = "Молодчина, Айрендил! Мы уже на шаг ближе к спасению Азерота!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13607] = {title = "Священный планетарий", objective = "Найдите Священный планетарий по заданию геолога Дорена из Архива в Ульдуаре.", description = "Слушай внимательно! На кону – судьба всего Азерота.\n\nТолько одно спасет нас – нужно найти Священный планетарий и помешать этому Алгалону отправить сообщение его повелителям-титанам.\n\nОтыщи Священный планетарий и возвращайся со всеми данными, которые сможешь там собрать. Может быть, мы успеем подготовиться к прибытию Алгалона.", progress = "Ты нашел его, Баронгеддон?", completion = "Закрыт? Так я и думал!\n\nДавай-ка посмотрим, что расскажет нам эта куча металлолома...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13609] = {title = "Печать Ходира", objective = "Добудьте печать Ходира по заданию геолога Дорена.\n\nЗа дополнительными сведениями обратитесь к панели управления Архивом.", description = "Печать Ходира будет нелегко раздобыть. Во-первых, тебе придется одолеть самого Ходира. А во-вторых, одолеть его нужно до того, как он уничтожит сундук с печатью!\n\nВоспользуйся панелью управления Архивом, чтобы получить дополнительные сведения. Эта премудрая штуковина стоит всех библиотек мира!", progress = "Ну что, Айрендил, где печать?", completion = "Потрясающе! Не знаю, как ты это сделал, но тебе это удалось!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13610] = {title = "Печать Торима", objective = "Добудьте печать Торима по заданию геолога Дорена.\n\nЗа дополнительными сведениями обратитесь к панели управления Архивом.", description = "Торим не в себе, <имя>. Он во власти темных сил.\n\nТемная сущность приняла обличье его погибшей жены, Сиф.\n\nНельзя позволить иллюзии свести его с ума. Если это случится, то мы никогда не сможем найти печать Торима!\n\nВразуми его, и побыстрее.\n\nКак обычно, за подробностями этой жуткой истории можешь обратиться к панели управления Архивом... но они вряд ли тебе понравятся.", progress = "Итак, Рокхан... Печать у тебя?", completion = "Ты не прекращаешь удивлять меня, Рокхан.\n\nДавай выпьем по кружечке после того, как все это закончится!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13611] = {title = "Печать Мимирона", objective = "Добудьте печать Мимирона по заданию геолога Дорена.\n\nЗа дополнительными сведениями обратитесь к панели управления Архивом.", description = "Мимирон хитер – в его комнате установлен какой-то механизм самоуничтожения.\n\nЕсли хочешь получить его печать, тебе придется победить его до того, как механизм завершит свой цикл. Если тебе нужно больше информации – воспользуйся панелью управления Архивом.", progress = "Ну что, Айрендил, где печать?", completion = "Надо отдать тебе должное, Айрендил: шансы у нас неважные, но я чувствую себя гораздо увереннее с тех пор, как ты сражаешься на моей стороне.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13612] = {title = "Защита лагеря Мор'Шан", objective = "Кадрак с заставы Мор'шан поручил вам убить 5 застрельщиков Ясеневого леса и 5 стрелков Ясеневого леса.", description = "Лок'тар, <раса>.\n\nНаконец-то мы перешли в наступление, и вскоре весь Ясеневый лес окажется во власти Орды.\n\nКак мы и ожидали, переход к агрессии заставил противника испытывать нашу защиту на каждом рубеже.\n\nНо здесь, в лагере Мор'шан, их атака захлебнулась. Мы продолжим зажимать их в тиски, но я предвижу, что они окажут жестокое сопротивление.\n\nЯ поручаю тебе, <класс>, провести разведку и обнаружить всех выживших ночных эльфов. Надо устранить их прежде, чем они подготовят новое нападение!", progress = nil, completion = "Твоя помощь важна для нас, |3-6(Друид).\n\nТвоими усилиями мы обратили врагов в бегство. Мы и не остановимся, пока не очистим эту землю от длинноухих.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13613] = {title = "Спасение павших", objective = "Исцелите врачебным зельем 5 раненых защитников заставы Мор'шан.", description = "Наши войска отважно сражаются, <класс>.\n\nНо на поле битвы осталось много раненых, которые не могут вернуться в лагерь.\n\nЯ создала целебную мазь, которая придаст сил пострадавшим и поможет им добраться до бастиона, где им окажут помощь. Прошу тебя, передай этот бальзам тем, кто в нем нуждается.", progress = nil, completion = "Спасибо, |3-6(таурен). Обещаю, я упомяну о твоей помощи в отчете Орде.\n\nА теперь мне надо поставить на ноги как можно больше солдат!", rewards = "Поножи путешествующего лекаряПерчатки полулунникаНаплечье союзникаВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13614] = {title = "Алгалон", objective = "Принесите печати хранителей к панели управления Архивом в Ульдуаре.", description = "Ты <справился/справилась>, <имя>. Теперь возьми печати, отнеси их к панели управления Архивом и попытайся получить доступ к Священному планетарию.\n\nПоторопись, <друг/подруга> – дорога каждая секунда.", progress = "Яркие лучи панели периодически освещают стеклянную поверхность, как будто ожидают ввода данных.", completion = "Ожидайте подтверждения.\n\nДоступ в Священный планетарий разрешен. Пожалуйста, возьмите ключ.", rewards = "Вы получите:\n\nКлюч к Священному планетариюМешок с ульдуарскими трофеями"}
MultiLanguageQuestData['ru'][13615] = {title = "Пустой колчан", objective = "Труун с заставы Мор'шан поручил вам собрать 10 исправных стрел вокруг Зеркала Небес.", description = "Приветствую тебя, <класс>. Добро пожаловать на Заставу.\n\nЗнаю, со стороны может показаться, что у нас тут полный бардак, но на самом деле Кадрак хорошо держит оборону. Еще ни один эльф не проник за эти стены!\n\nКстати, раз уж ты здесь... Со дня на день к нам должен поступить груз снаряжения из Оргриммара, но лучникам уже сейчас не хватает боеприпасов.\n\nЕсли найдешь подходящие стрелы, принеси их мне, и я тебя щедро вознагражу.", progress = "Ты собрал все стрелы?", completion = "Очень хорошо, |3-6(Друид).\n\nЭто поможет нам продержаться, пока не придут корабли с провизией.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13616] = {title = "Клинок Зимы", objective = "Маршал Якоб Алерий из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести Клинок Зимы.", description = "Проклятый рыцарь смерти сломал мой клинок.\n\nВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.\n\nНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты <достоин/достойна> этого меча.", progress = "Ну как? Получилось добыть меч?", completion = "Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, Воборотень.", rewards = "Вы получите:\n\nПечать искателя славыПредмет #1"}
MultiLanguageQuestData['ru'][13617] = {title = "К западу от Пучины", objective = "Поговорите с Таленом в лагере у Непроглядной Пучины в Ясеневом лесу.", description = "<имя>, у меня есть друг, который мог бы найти применение твоим талантам. Его зовут Тален, и он вроде как археолог. Недавно его вниманием завладел поднявшийся со дна морского древний город Зорам и его сокровища.\n\nЕсли хочешь помочь моему другу, ищи его в лагере у Непроглядной Пучины, что на западе вдоль этой дороги.", progress = nil, completion = "Здравствуй, |3-6(Друид).\n\nГоворишь, тебя послала Шейла?\n\n&lt;Ночной эльф с энтузиазмом потирает руки.&gt;\n\nНу хорошо, давай же начнем поскорее.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13618] = {title = "Найти Гората!", objective = "Кадрак с заставы Мор'шан попросил вас обойти Зеркало Небес в поисках Гората.", description = "Горат – один из лучших наемных убийц Орды. Одно его имя вселяет страх в сердца отважных героев Альянса, ибо многие уже пали от его руки.\n\nОн самый надежный и преданный наш союзник, который до последнего времени мог похвастаться исключительной пунктуальностью.\n\nЯ чувствую, что с ним что-то случилось. Я бы сам занялся этим делом, но мое присутствие здесь необходимо. У меня нет другого выбора, кроме как обратиться к тебе за помощью.\n\nПоследним заданием Гората было найти и уничтожить эльфа, ответственного за нападение на бастионы.\n\nОн должен быть где-то в районе Зеркала Небес.\n\nНайди его!", progress = nil, completion = "Слушай меня внимательно, |3-6(таурен)...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13619] = {title = "Последний отчет", objective = "Горат попросил вас отнести пузырек с его кровью Кадраку на заставу Мор'шан.", description = "<Горат пытается приподняться, и тут же заходится тяжелым кашлем.>\n\nЯ попал... в засаду...\n\nМы... возвращались в бастион... все... погибли...\n\nИх предводитель... мы нашли его...\n\n<Морщась от боли, Горат наполняет пузырек своей кровью, струящейся из раны.>\n\nМои люди... должны быть отомщены... Отнеси это... Кадраку...\n\nОн знает, что делать...\n\n<Горат испускает последний вздох.>", progress = "Ты нашел Гората, |3-6(Разбойник)?", completion = "&lt;Кадрак внимательно выслушивает последние слова Гората.&gt;\n\nИменно этого я и боялся. Надеюсь, когда-нибудь он сможет упокоиться с миром.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13620] = {title = "Наконец-то, к Дине!", objective = "Кадрак просит вас отнести пузырек с кровью Гората Дине на заставу Мор'шан.", description = "Орда не знала более преданного союзника, чем Горат. Он ни разу не подводил нас, и даже смерть не может помешать ему выполнить задание.\n\nОн не зря попросил тебя принести этот флакон. Его следует немедленно доставить Дине, дочери нашего почтенного шамана – и поверь мне, она гораздо более могущественная, чем кажется. Поторопись, пока еще не поздно!", progress = "Что там у тебя, |3-6(таурен)?", completion = "Дай-ка мне взглянуть, |3-6(Друид).", rewards = "Следующее заклинание будет наложено на вас:\n\nDinah Dummy Spell\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13621] = {title = "Месть Гората", objective = "Окропите тело Гората его густой кровью и убейте капитана Элендилада.", description = "Удача сопутствует нам сегодня, <раса>.\n\nКровь Гората оказалась достаточно свежей для проведения особого ритуала, суть которого я постигла еще в детстве.\n\nПриготовься, <класс>.\n\nТебе предстоит пролить эту зачарованную кровь на тело Гората, чтобы призвать его неупокоенный дух обратно. Выслушай его внимательно и сделай все, о чем он тебя попросит, после чего возвращайся сюда, к Кадраку.\n\nИ да хранят тебя стихии, <друг/подруга>.", progress = nil, completion = "Ты молодец, |3-6(таурен).\n\nКапитан эльфов мертв, и душа нашего возлюбленного брата может упокоиться с миром.\n\nЯ непременно доложу о твоем подвиге моему командиру в Оргриммар.", rewards = "Наследство ГоратаКираса КадракаВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13622] = {title = "Древняя история", objective = "Принесите расколотый Вал'анир к панели управления в Архив Ульдуара.", description = "Из кусочков вам удается сложить прекрасный боевой молот. Сразу заметно, что к созданию молота приложили руку титаны.\n\nПанель управления в Архиве наверняка содержит немало интересных сведений об этом оружии.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][13623] = {title = "Посылка для Орендила", objective = "Доставьте мешочек с Батрановым волосом Орендилу Широколисту на заставу Мейстры, что в Ясеневом лесу.", description = "Быстрее, <имя>. Я положу Батранов волос в сумку, а тебе нужно будет доставить ее моему наставнику, Орендилу Широколисту. Ты найдешь его на Заставе Мейстры, если пойдешь по левой дороге на юг.\n\nНо будь <осторожен/осторожна> – к нам доходили слухи о том, что застава находится под осадой Орды!", progress = "Учитывая все обстоятельства, надо обладать недюжинной смелостью, чтобы явиться сюда.\n\nТак что привело тебя, незнакомец?", completion = "Значит, Эвенар достиг цели. Впрочем, чего уж там – это твоя заслуга.\n\nНе знаю даже, как тебя отблагодарить. Увы, но нам еще многое придется сделать прежде, чем эти листья вновь обретут целебные свойства.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13624] = {title = "Отряд под твоим командованием", objective = "Часовой Ойнея отдает под ваше командование отряд стражников заставы Мейстры, чтобы вы убили 3 крушителей из Ясеневого леса и 10 захватчиков из Орды.", description = "Очень надеюсь, что ты <пришел/пришла> нам на помощь, <класс>. Ситуация у нас действительно плачевная. Проще говоря – мы проигрываем это сражение!\n\nМои девочки и я – вот и вся линия обороны против всех сил Орды, но мы не собираемся сдаваться без боя. Хочешь встать на нашу сторону?\n\nЯ снарядила небольшой отряд стражников, который могу отдать под твое командование. Только расчисти им путь, и их волшебные стрелы справятся с крушителями и захватчиками.\n\nОкликни меня, если тебе потребуется подкрепление.", progress = nil, completion = "Твое имя неоднократно упоминалось в отчетах моих разведчиков, но до сегодняшнего дня я и не предполагала, насколько ты можешь быть полезна.\n\nСпасибо за помощь, Тихийпутя. Ты переломила ход войны. Не сомневаюсь, что теперь мы изгоним врагов еще до заката!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13625] = {title = "Большая тренировка", objective = "Отработайте прием \"Выпад\" 5 раз на манекене для ближнего боя, прием \"Удар по щиту\" 2 раза на мишени для дальнего боя и прием \"Рывок\" 2 раза на манекене для стремительной атаки, затем вернитесь к разведчице Шалиндрии на Ристалище Серебряного турнира.\n\nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.", description = "Большая часть состязаний турнира требует от участников мастерства в управлении верховым животным. Чтобы познакомить тебя с этим видом поединков, мы разместили тренировочные манекены в северной части Ристалища турнира.\n\nЗайди в стойла на севере площадки, рядом с главной ареной, вооружись копьем и оседлай кель'дорайского скакуна. Познакомься со всеми доступными приемами и используй новые знания в тренировке. Для освоения новых приемов можешь использовать все три вида манекенов.", progress = "Как прошла твоя тренировка?", completion = "Молодец, Айерлис. Не все воины легко осваивают приемы верхового поединка. Я не сомневаюсь, что ты продолжишь тренировки и превзойдешь многих воинов в этом виде состязаний.", rewards = "Вы получите:\n\nПечать претендентаПредмет #1"}
MultiLanguageQuestData['ru'][13626] = {title = "Последние почести", objective = "Добудьте священный молот Фиро и молитвенник Очистителя.", description = "Здесь были двое людей – Фиро Железная Рука и Делгрен Очиститель, члены религозной организации, известной под именем Серебряный Рассвет. Оба они пали в битве за заставу во время первого нападения Орды.\n\nЯ одолжу тебе свой волшебный плащ – подарок Кенария. С его помощью ты сможешь незаметно перемещаться по заставе.\n\nНайди их тела и принеси мне молот Фиро и молитвенник Делгрена. Труп Фиро лежит во внутреннем дворе, а Делгрен остался лежать на вершине башни.\n\nНо будь <осторожен/осторожна> – плащ не укроет тебя от взгляда ордынского чернокнижника!", progress = "Наши потери невосполнимы.", completion = "Даже не знаю, что написать в посольство Серебряного Рассвета в Дарнас. Ну, во всяком случае, теперь мы сможем отправить вещи погибших их родственникам.\n\nНе знаю даже, как отблагодарить тебя за этот смелый поступок, Тихийпутя. Ты заслужила эту награду.", rewards = "Поножи ДелгренаПерчатки ОйнеиНаплечье ФироВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13627] = {title = "Откуда дровишки?", objective = "Принесите 12 грубо обтесанных досок Беззлу Рвизасову на Ристалище Серебряного турнира.", description = "Эй, иди сюда!.. Да не так близко, нас могут увидеть!\n\nДля постройки Колизея нужно гораздо больше дерева, чем я предполагал, а заказывать еще одну партию из Седых холмов я не стану ни за какие коврижки. В общем, слушай: на западной границе леса Хрустальной Песни, у Великого древа, растут молодые дубы.\n\nИх древесина как нельзя лучше подходит для строительства и возведения лесов. Возьми этот топор, повали несколько дубов Хрустальной Песни и принеси мне доски. Только смотри, не попадись никому на глаза!", progress = "Как там дела с поставкой \"товара\"?", completion = "Отличные досочки, да и достались почти даром! Недотепы из Серебряного Авангарда ни за что не пронюхают, откуда у меня материал! Они получат свой Колизей, а я – премию за своевременное окончание строительства. И все счастливы!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13628] = {title = "Где бревна?", objective = "Труун поручил вам оседлать Жестокого Бивня и отправиться в рабочий лагерь Песни Войны.\n\nЧтобы получить поводья для управления Жестоким Бивнем, поговорите с Кадраком.", description = "Кадрак только что получил новый приказ для наших отрядов – мы должны начать атаку на Ясеневый лес!\n\nЯ совершенно не готов перейти в наступление, да и боеприпасы из Оргриммара все еще не поступили. Придется импровизировать...\n\nЗнаешь, мне могла бы пригодиться твоя помощь, <класс>.\n\nПоговори с Кадраком – пусть он выдаст тебе Жестокого Бивня. Этот кодо знает дорогу к рабочему лагерю Песни Войны. Как только прибудешь на место, найди Горку и попроси ее нагрузить зверя свежими бревнами.", progress = nil, completion = "Добро пожаловать, |3-6(Воин). Хорошо, что дорога к заставе Мор'шан все еще безопасна.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13629] = {title = "Вал'анир, молот древних королей", objective = "Бросьте расколотый Вал'анир в пасть Йогг-Сарона во время \"Оглушающего рева\" и победите его, чтобы получить перекованный молот древних королей.\n\nЭто задание можно пройти только в героическом режиме и только в том случае, если хотя бы один из хранителей Ульдуара не помогает вам.", description = "С помощью панели управления Архивом вы узнаете способ воссоединения расколотого Вал'анира: надо поместить его внутрь физической формы существа, известного как Йогг-Сарон.\n\nЭто звучит довольно опасно, но ради артефакта такой силы можно пойти на риск.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nВал'анир, молот древних королей"}
MultiLanguageQuestData['ru'][13630] = {title = "Главная причина", objective = "Отключите синий, зеленый и красный лунные камни.", description = "Эти фурболги спустились с гор и захватили Руины Ордил'Арана на севере. Полагаю, их привлекла находка мертвых служителей культа – три лунных камня.\n\nЛиладрис Лунная Река, несомненно, посоветует тебе не церемониться с фурболгами, и я не стану с ней спорить, но прежде всего надо отправиться в руины и отключить эти лунные камни.", progress = nil, completion = "Спасибо тебе, Тихийпутя.\n\nТеперь, когда лунные камни Ордил'Арана перестали действовать, нам можно не бояться нападений со стороны фурболгов.\n\nОднако вести, которые принесли мои разведчики из их деревни, не столь обнадеживают. Похоже, что это место грозит нам еще большими бедами.\n\nМогу ли я просить тебя доставить предупреждение в Астранаар?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13631] = {title = "Все хорошо, что хорошо кончается", objective = "Доставьте код отклика \"Альфа\" Ронину в Даларан.", description = "Мы должны поторопиться, <имя> – надо передать код отклика из Даларана как можно скорее.\n\nОтнеси его Ронину, я встречу тебя там.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Пелерина небесного герольдаПелерина тусклого солнцаВам дадут возможность выбрать одну из следующих наград:\n\nПерстень-печатка БраннаПерстень звездного света\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13632] = {title = "Служба в арьергарде", objective = "Убейте 10 фурболгов на руинах Ордил'Арана.", description = "У лунной жрицы есть план, как остановить нашествие фурболгов с высокогорья. Правда, меня больше беспокоят те звери, что уже захватили руины – многие из них собираются в опасной близости от заставы.\n\nПонимаю, это неприятное поручение, но я вынуждена просить тебя отправиться к северу, к Руинам Ордил'Арана, и уничтожить фурболгов. Иначе мы не сможем сражаться на двух фронтах!\n\nЗаранее благодарю тебя, <класс>.", progress = nil, completion = "Мы все у тебя в долгу, |3-6(Друид). Если я хоть что-то понимаю в фурболгах, они вряд ли будут дожидаться, когда им расквасят носы.\n\nМогу поспорить, они скоро уберутся в свою деревню, поджав хвосты от страха.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13633] = {title = "Черный рыцарь из Западного Края?", objective = "Узнайте правду о Черном рыцаре и поделитесь информацией с рыцарем Райдаллой на Ристалище Серебряного турнира.", description = "Не сомневаюсь, до тебя уже дошли тревожные слухи об участнике турнира, которого остальные называют Черным рыцарем. Говорят, будто каждый, кому выпал жребий стать его противником в следующем бою, внезапно умирает.\n\nКонечно, мы не можем ничего утверждать, но было бы неплохо проверить все, что нам известно про этого рыцаря.\n\nОн утверждает, будто он родом из семьи Купер, которая проживает в Западном Крае. Съезди в имение Куперов на западе Луноречья, чтобы подтвердить или опровергнуть его слова.", progress = "Тебе удалось найти что-то, что могло бы подтвердить историю Черного рыцаря?", completion = "Значит, история рыцаря – это сплошной обман? Крайне подозрительная ситуация. Это бесчестно, а может стать и смертельно опасным в худшем случае. Но мы не сможем предъявить ему обвинения, пока у нас не будет доказательств.\n\nПостарайся не вызывать у него подозрений, Заракир. Если мы хотим продолжить расследование, надо делать это втайне.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13634] = {title = "Черный рыцарь из Серебряного бора?", objective = "Узнайте правду о Черном рыцаре и поделитесь информацией с рыцарем Райдаллой на Ристалище Серебряного турнира.", description = "Не сомневаюсь, до тебя уже дошли тревожные слухи об участнике турнира, которого остальные называют Черным рыцарем. Говорят, будто каждый, кому выпал жребий стать его противником в следующем бою, внезапно умирает.\n\nКонечно, мы не можем ничего утверждать, но было бы неплохо проверить все, что нам известно про этого рыцаря.\n\nПо его словам, он прибыл с Поля Валгана, что в Серебряном Бору. Это маленькая ферма на западном берегу озера Лордамер. Съезди на эту ферму, чтобы подтвердить или опровергнуть его слова.", progress = "Тебе удалось найти что-то, что могло бы подтвердить историю Черного рыцаря?", completion = "Значит, история рыцаря – это сплошной обман? Крайне подозрительная ситуация. Это бесчестно, а может стать и смертельно опасным в худшем случае. Но мы не сможем предъявить ему обвинения, пока у нас не будет доказательств.\n\nПостарайся не вызывать у него подозрений, Синдвэллер. Если мы хотим продолжить расследование, надо делать это втайне.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13635] = {title = "Отчет Южных врат", objective = "Доставьте отчет пилота Большенога капитану Ругельфассу в Долину Королей.", description = "Нам нужно отправить отчет о состоянии дел горным пехотинцам в Долину Королей.\n\nРаз уж ты все равно туда направляешься, не захватишь ли заодно и его? Воспользуйся туннелем к востоку отсюда, а потом обратись к стражникам. Передай отчет лично в руки капитану Ругельфассу.", progress = "Что заставило тебя проделать такой путь?", completion = "Отчет Южных врат? Прекрасно! Я уже некоторое время жду новостей оттуда.\n\nТроггов на холмах становится все больше, боюсь, заставы первыми почувствуют на себе их агрессию.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13636] = {title = "Заказы для Грозовой Вершины", objective = "Доставьте заказы для Грозовой Вершины горному пехотинцу Грозовой Вершине на станцию Альгаз.", description = "У меня есть кое-какие заказы для горного пехотинца Грозовой Вершины с заставы на станции Альгаз. Если тебя не затруднит отнести их ему, то отправляйся по дороге, которая ведет на северо-запад, так ты точно не пропустишь главный бункер.\n\nА если ты поможешь ему выполнить заказы, то мы будем рады наградить тебя за это.", progress = nil, completion = "Заказы! Посмотрим, что тут у нас… ха! Он хочет, чтобы я разобрался с нашествием крысолюдей. Мы как раз этим и занимаемся.\n\nПоможешь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13637] = {title = "Доставка барана", objective = "Горные пехотинцы с заставы у Южных врат попросили прислать баранов для их патрулей. Не думаю, что у нас есть много лишних баранов, но благодаря тебе мы можем послать им одного.\n\nНе доставишь ли ты его рядовому из Павшего Молота? Когда будешь <готов/готова> отправиться, дай мне знать.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Горные пехотинцы с заставы у Южных врат попросили прислать баранов для их патрулей. Не думаю, что у нас есть много лишних баранов, но благодаря тебе мы можем послать им одного.\n\nНе доставишь ли ты его рядовому из Павшего Молота? Когда будешь <готов/готова> отправиться, дай мне знать.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13638] = {title = "Плененный горный пехотинец", objective = "Капитан Ругельфасс в Телсамаре просит вас отыскать горного пехотинца Булыжного Карьера.В бою ты <показал/показала> себя как нельзя лучше. Теперь я хочу попросить тебя кое о чем более срочном.\n\nОдин из моих горных пехотинцев, Булыжный Карьер, был захвачен троггами в южных горах. Ну, то есть не то чтобы захвачен, скорее он сдался добровольно, но результат от этого не меняется. Я думаю, таким образом он пытался изнутри выяснить, кто является их предводителем.\n\nЯ хочу, чтобы ты <освободил/освободила> его. Скорее всего они держат его возле одной из своих верхних пещер глубоко в горах.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "В бою ты <показал/показала> себя как нельзя лучше. Теперь я хочу попросить тебя кое о чем более срочном.\n\nОдин из моих горных пехотинцев, Булыжный Карьер, был захвачен троггами в южных горах. Ну, то есть не то чтобы захвачен, скорее он сдался добровольно, но результат от этого не меняется. Я думаю, таким образом он пытался изнутри выяснить, кто является их предводителем.\n\nЯ хочу, чтобы ты <освободил/освободила> его. Скорее всего они держат его возле одной из своих верхних пещер глубоко в горах.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13639] = {title = "Снабжение экспедиции", objective = "Найдите Хальдара, Мирана и Сайана.", description = "Сталекрут ведет раскопки на юго-востоке и ему требуется изрядное количество взрывчатки, которую присылает Лига. Хальдар, Миран и Сайан уже отправились с последней партией груза, но, возможно, им не помещает помощь.\n\nВряд ли они ушли далеко, с их-то силенками. С такими тяжелыми бочками не пойдешь быстро.\n\nОни отправились к раскопкам обычной дорогой, из города на юг, а дальше вдоль берега озера Лок. Догони их и помоги им, хорошо?", progress = nil, completion = "Хмм, если бы все проблемы были только в засадах Черного Железа, поставкам бы ничего не грозило!\n\nНо Сайан… Я никогда не подозревал, что он один из их сторонников. Мы работали вместе почти целый год… может быть, я чего-то не заметил?\n\nЛадно, я подумаю об этом позже.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13640] = {title = "Руководящий состав", objective = "Заставьте работать несобранных батраков и соберите 5 вязанок свежесрубленного леса.", description = "Что, Трууну дровишки понадобились? В любой другой день я бы сгрузила ему пачку бревен без лишних вопросов, но только не сегодня.\n\nИз-за этих проклятых эльфов рубка леса стала опасным занятием, и мои наемные рабочие отказываются рисковать своей шкурой.\n\nТак что если тебе нужно дерево – иди и заставь их работать.\n\nДа, и охраняй их по пути – я не могу больше терять сотрудников!", progress = "Итак, |3-6(таурен), ты уже несешь бревна?", completion = "Беда не ходит поодиночке, |3-6(Друид)...", rewards = "Халат рабочего лагеряМантия управляющегоПерчатки воодушевленияВы получите:\n\n"}
MultiLanguageQuestData['ru'][13641] = {title = "Кристалл провидца", objective = "Принесите кристалл провидца рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного турнира.", description = "Теперь, когда мы знаем, что Черный рыцарь обманом проник на турнир, нужно найти доказательства его причастности к смерти других участников. \n\nЯ знаю, как нам вывести его на чистую воду, но для этого понадобится очень редкая вещь – кристалл провидца. Такие кристаллы можно найти только у диких провидцев, обитающих рядом с руинами ночных эльфов в Опустевших лесах, это в центре Леса Хрустальной Песни. <имя>, найди провидца и принеси кристалл.", progress = "Ты уже нашел кристалл провидца?", completion = "Да, этот кристалл подойдет. Осталось только зарядить его силой Света, чтобы он смог отличить правду от лжи.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13642] = {title = "Свет Элуны", objective = "Создайте Омытое светом зелье.", description = "Зелье еще не готово – прежде, чем давать его больной девочке, оно должно быть благословлено Светом Элуны.\n\nЯ знаю одно место, к западу от Озера Фалатим, где лунные лучи день и ночь касаются земли. Прошу тебя, <имя>, ради Релары – возьми это лекарство и окуни его в свет Элуны.\n\nБереги себя – говорят, в окрестностях озера творятся странные вещи. Дороги туда более не безопасны.", progress = "Тяжело было достать Свет Элуны из озера Фалатим?", completion = "Теперь, когда Свет Элуны коснулся зелья, его надо немедля отправить в Астранаар.\n\nНельзя терять ни секунды, Тихийпутя!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13643] = {title = "История погибших", objective = "Воспользуйтесь кристаллом провидца перед могилами сэра Венделла Балфура, Лориена Блеска Солнца и Коналла Железной Хватки, узнайте причину их гибели и доложите рыцарю Райдалле из Серебряного павильона.", description = "Этот кристалл откроет нам правду о том, как погибли три участника турнира. Отнеси его на кладбище на востоке Ристалища к могилам сэра Венделла Балфура, Лориена Блеска Солнца и Коналла Железной Хватки.\n\nЕсли три этих доблестных мужа действительно были убиты, мы должны будем найти доказательства причастности Черного рыцаря до того, как он совершит очередное преступление. Внимательно изучи то, что покажет тебе кристалл, ибо мы должны быть абсолютно уверены, что эти смерти не были случайными.", progress = "Ты уже посетил могилы павших рыцарей?", completion = "Значит, Лориен Блеск Солнца был отравлен, а сэр Венделл сгорел заживо? Какая ужасная смерть постигла этих доблестных мужей. Один лишь Коналл погиб, сраженный мечом – но не в честном поединке, а от руки предателя.\n\nИ все трое должны были сражаться с Черным рыцарем на турнире. Это не может быть совпадением! Осталось доказать, что он причастен к их смерти.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13644] = {title = "Тот, кто был воскрешен", objective = "Убейте предвестника Афотика.", description = "Когда я почувствовал, как эти... сущности... поднимаются из-под земли, я прибыл, чтобы отправить их обратно раз и навсегда. Здесь я нашел тело твоего друга и отнес его так далеко, как только смог. Увы, на полпути я подвернул копыто, и на том закончились мои попытки удержать распространение этих ужасных щупалец.\n\nНо я знаю, кто управляет этими отростками и глазами. Он называет себя предвестник Афотик – уверен, ты слышал его завывания, доносящиеся с юга.\n\nУвы, мне не дотянуться до него своей магией, но если тебе удастся подобраться к нему поближе... Не знаю только, хватит ли у тебя смелости.", progress = "Вестник все еще жив, Серенада. Я не могу приступить к очищению озера, пока он стоит на моем пути.", completion = "После смерти вестника я могу наконец-то приступить к очистке озера.\n\nПрими мою искреннюю благодарность, Тихийпутя. В глубине души я все еще оплакиваю смерть друга, но меня утешает та мысль, что его останки помогут возродить лес и его окрестности.", rewards = "Туфли омовенияМрачного вида башмакиБлаго Мудрого СердцаВы получите:\n\n"}
MultiLanguageQuestData['ru'][13645] = {title = "К Раэне Волкопас", objective = "Отнесите светящийся самоцвет Раэне Волкопас в Астранаар, что в Ясеневом лесу.", description = "Пожалуйста, передай этот самоцвет из рук в руки Раэне Волкопас. По моим сведениям, она все еще находится в Астранааре на юго-востоке.\n\nГоворят, дорога туда все еще безопасна, поэтому я не предвижу никаких трудностей с доставкой. Но если тебя интересует более быстрый путь, обратись к часовому Аване, и она с радостью одолжит тебе одного из верховых ночных саблезубов.\n\nКакой бы способ передвижения ты ни <предпочел/предпочла>, желаю тебе доброго пути, <имя>. Надеюсь, мы еще встретимся.", progress = "Я Раэна Волкопас. А ты кто такой?", completion = "Теронис погиб?\n\n&lt;Какое-то время девушка оплакивает павшего друга, но потом собирается с силами.&gt;\n\nЕго гибель не будет напрасной. Ты позаботишься об этом, |3-6(Друид)?\n\nДай мне подумать немного – надо составить план дальнейших действий. Я позову тебя, когда все будет готово.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13646] = {title = "Связь с Астранааром", objective = "Поговорите с часовым Луарой в Астранааре, что в Ясеневом лесу.", description = "Твоя помощь неоценима для нас, <имя>. Не будь тебя, нас бы уже стерли с лица земли.\n\nСамое малое, что я могу для тебя сделать взамен – предложить одного из моих ночных саблезубов, которые знают дорогу в Астранаар – наверх и на северо-восток. Не сомневаюсь, там тебя ждут очень важные и неотложные дела.\n\nНо я была бы тебе очень благодарна, если бы ты по прибытии <разыскал/разыскала> мою сестру, часового Луару, и <сообщил/сообщила> ей, что со мной все в порядке.\n\nСкажи мне, когда будешь <готов/готова> отправляться в путь.", progress = nil, completion = "Авана жива?! Я боялась, что она погибла при осаде заставы Мейстры.\n\nКак видишь, здесь нам тоже хватает проблем с Ордой.\n\nТы сделал мне величайший подарок, сообщив, что с ней все в порядке. Теперь мои ночные саблезубы всегда к твоим услугам, если тебе вдруг захочется вернуться на заставу Мейстры.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13647] = {title = "Присоединение к охоте", objective = "Поговорите с Мареком Железносердом в Приюте Странников.", description = "У тебя определенно дух воина.\n\nЗнаешь, в приюте к востоку отсюда, в холмах, живут охотники – тебе бы не помешали такие союзники. Почему бы тебе не навестить их и не узнать, нет ли у них какой-то работы, которая бы тебя заинтересовала?", progress = nil, completion = "Здорово, приятель! Ты от горных пехотинцев? Думаю, у нас найдется работа как раз по тебе. Добро пожаловать в Приют Странников!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13648] = {title = "РАЗЫСКИВАЕТСЯ: шпион Черного Железа", objective = "Убейте Горика Пивохлеба.", description = "Шпион Черного Железа проник в город, украл документы Лиги исследователей и сейчас прячется где-то поблизости. В последний раз его видели недалеко от вершины холма к югу от города.\n\nТому, кто предаст шпиона правосудию, обещано значительное вознаграждение. Доставьте его живым или мертвым – лучше мертвым.", progress = nil, completion = "Ты нашел этого чертового шпиона и помог свершиться правосудию! Теперь мы все можем вздохнуть с облегчением, о нем можно больше не беспокоиться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13649] = {title = "Веселая проверка Джастина", objective = "Попадите кружкой с бесплатным пивом в С.С.М. 5 раз, затем поговорите с Бокси Болтокрутом.", description = "Эй! Похоже, с выпивкой ты обращаться умеешь. А вот с пивной кружкой? \n\nЭти дворфы из клана Черного Железа опять вернулись! Мстить хотят и праздник нам порушить! Легче всего их отогнать, если запустить в них пивной кружкой, но сначала посмотрим-ка, попадешь ли ты в чучелко – С.С.М.?\n\nЭто просто – хлебни бесплатного пивка, только встань сначала лицом к С.С.М. Попади в цель пять раз, тогда поговорим.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][13650] = {title = "Руки прочь от имущества!", objective = "Проверьте состояние следующих артефактов: опрокинутого великана, нарядной женщины и разбитой скрижали.", description = "Мы нашли в этом месте поразительные артефакты. Сложно убедиться в их подлинности, но они могут обладать большой исторической ценностью.\n\nК сожалению, когда трогги заняли эту территорию, мы лишились доступа к трем наиболее ценным. Я боюсь, что в наше отсутствие трогги либо украли их, либо испортили.\n\nЕсли будешь на раскопках, постарайся найти опрокинутого великана, нарядную женщину и разбитую скрижаль и убедись, что с ними все в порядке.", progress = nil, completion = "Уф! Гора с плеч… Я опасался, что все они уничтожены. Спасибо за то, что проверил.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13651] = {title = "Надо немного смазки", objective = "Горка из рабочего лагеря Песни Войны просит вас собрать 5 порций слизи в Ясеневом лесу.", description = "Ну да, я погрузила твои бревна на кодо, но ты все равно не сможешь вернуться на заставу Мор'шан – проклятые эльфы окружают нас со всех сторон.\n\nНе волнуйся – я уже отправила гонца на Заставу Расщепленного Дерева за подмогой. Скоро их солдаты расчистят тебе путь.\n\nА пока ты можешь оказать нам маленькую услугу. Наши крошшеры совсем заржавели, но если их хорошенько смазать, они будут как новенькие.\n\nДумаю, жир гниющей слизи, обитающей на севере отсюда, вполне сгодится для этой цели.", progress = "Тебе удалось собрать жир?", completion = "Спасибо тебе за жир, |3-6(Разбойник). Увы, за время твоего отсутствия поступили плохие новости.\n\nКрепись, Магребинец – Засада Расщепленного Дерева в осаде!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13652] = {title = "Защита Каменной Плотины", objective = "Найдите главного инженера Плотиннера VII на Каменной Плотине.Мы очень ценим твою помощь. Через некоторое время мы восстановим контроль над раскопками, и я очень рад слышать, что в результате этого захвата мы не лишились всей своей работы.\n\nМы уже достаточно злоупотребили твоим временем. Но у меня есть друг, который тоже будет рад твоей помощи, если бы будешь так <добр/добра> ее оказать. Отправляйся на дальнюю оконечность озера Лок, там ты найдешь Каменную Плотину. Разыщи там главного инженера Плотиннера VII.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Мы очень ценим твою помощь. Через некоторое время мы восстановим контроль над раскопками, и я очень рад слышать, что в результате этого захвата мы не лишились всей своей работы.\n\nМы уже достаточно злоупотребили твоим временем. Но у меня есть друг, который тоже будет рад твоей помощи, если бы будешь так <добр/добра> ее оказать. Отправляйся на дальнюю оконечность озера Лок, там ты найдешь Каменную Плотину. Разыщи там главного инженера Плотиннера VII.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13653] = {title = "Кризис на заставе", objective = "Горка просит вас сопроводить ее к заставе Мор'шан и отчитаться перед Кадраком.\n\nОкликните ее, когда вы будете готовы отправиться в путь.", description = "Не будет нам помощи от Заставы Расщепленного Дерева.\n\nЭльфы организовали массированное нападение на нашу крепость и осадили заставу!\n\nМы должны сообщить об этом Кадраку любой ценой!\n\nМы уже погрузили собранную тобой древесину на кодо. Дай мне знать, когда будешь <готов/готова> отправиться в путь, и мы расчистим тебе дорогу.", progress = "Это еще что, |3-6(Друид)?", completion = "Горка...\n\nНа войне не обойтись без потерь. Но ее беззаветное служение Орде не будет забыто.\n\nИ ее жертва не должна стать напрасной!", rewards = "Стола плакальщикаПоножи потериБремя жертвоприношенияВы получите:\n\n"}
MultiLanguageQuestData['ru'][13654] = {title = "Странный оруженосец", objective = "Добудьте большую бедренную кость дровосека-скелета и оглушите Малорика. Обыщите его и доложите обо всем рыцарю Райдалле из Серебряного павильона на Ристалище Серебряного турнира.", description = "Каждый день оруженосец Черного рыцаря Малорик устраивает целое представление, торжественно отправляясь в Лес Хрустальной Песни. Он хочет убедить всех, что рубит дрова, но обратно приносит всего несколько веток.\n\nНа самом деле он ходит к руинам на юго-западе Зеркала Сумерек. Учитывая его обязанности как оруженосца, он проводит там слишком много времени.\n\nОглуши его и обыщи хорошенько. Мы должны знать, что он затевает.", progress = "Тебе удалось узнать что-нибудь об этом странном оруженосце?", completion = "&lt;Рыцарь Райдалла с отвращением изучает содержимое сумки.&gt;\n\nЗдесь все улики, Анкап: яд, которым был отравлен Лориен, набор ножей, факелы и масло. Не могу представить, зачем оруженосцу могли потребоваться эти предметы, если только он не выполнял приказ своего рыцаря. Мы нашли убийцу, Анкап, но по чьему приказанию он действовал?", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13655] = {title = "Документ Лиги исследователей (2 из 6)", objective = "Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.", description = "Документ написан на гербовой бумаге Лиги исследователей, в нем перечислены места возможных раскопок в Лок Модане. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.\n\nВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.", progress = nil, completion = "Ну надо же. Ты нашел один из наших украденных документов!\n\nМы многим тебе обязаны за его возвращение. Надеюсь, немного золота будет хорошей платой за находку?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13656] = {title = "Документ Лиги исследователей (1 из 6)", objective = "Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.", description = "Документ написан на гербовой бумаге Лиги исследователей и содержит обширную информацию о существах, обитающих в Лок Модане. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.\n\nВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.", progress = nil, completion = "Привет, сынок! Похоже, ты нашел один из наших украденных документов, да?\n\nБольшое спасибо, что вернул его нам. Вот тебе монетка.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13657] = {title = "Документ Лиги исследователей (3 из 6)", objective = "Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.", description = "Документ написан на гербовой бумаге Лиги исследователей и содержит исторические записи обо всех примечательных местах Лок Модана. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.\n\nВы вспоминаете, что в здании Лиги исследователей в Телсамаре говорили о пропавших документах.", progress = nil, completion = "Наши исторические записи! Мысль о том, что эти негодяи из Черного Железа копались в нашем прошлом, вызывает у меня тошноту.\n\nМы очень благодарны тебе за то, что ты вернул нам пропажу. Мы бы хотели вознаградить тебя за это.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13658] = {title = "Документ Лиги исследователей (4 из 6)", objective = "Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.", description = "Документ написан на гербовой бумаге Лиги исследователей, в нем перечислены транспортные пути, которыми пользуется Лига для доступа в Лок Модан. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.\n\nВы вспоминаете, что в здании Лиги исследователей в Телсамаре говорили о пропавших документах.", progress = nil, completion = "Фу, поверить не могу, что им в руки попала информация о наших транспортных путях!\n\nСпасибо, что вернул нам этот документ, пока они не успели принести нам большого вреда! Возможно, ты уберег нас от больших проблем. Пожалуйста, возьми пару монет за твои труды.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13659] = {title = "Документ Лиги исследователей (6 из 6)", objective = "Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.", description = "Документ написан на гербовой бумаге Лиги исследователей, в нем перечислены оценки различных угроз в Лок Модане. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.\n\nВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.", progress = nil, completion = "Ха! Надеюсь, им было приятно узнать о том, насколько низко мы оцениваем исходящую от них угрозу! Надо признать, что этот документ устарел, но не стал от этого менее забавным.\n\nКонечно, мы в любом случае наградим тебя за его возвращение – мы очень ценим твою помощь!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13660] = {title = "Документ Лиги исследователей (5 из 6)", objective = "Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.", description = "Документ написан на гербовой бумаге Лиги исследователей, он содержит полный список артефактов, найденных рабочими Сталекрута на юго-востоке Лок Модана. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.\n\nВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.", progress = nil, completion = "Наши записи об артефактах! Я всерьез опасался, что клан Черного Железа может попытаться украсть наши артефакты, обладая этой информацией.\n\nСпасибо, что вернула нам этот документ. Вот, возьми эти деньги в знак нашей благодарности.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13661] = {title = "Сердечная признательность", objective = "Ты нашла все документы! Мы не знаем, как и благодарить тебя за помощь… мысль о том, что клан Черного Железа сможет воспользоваться этой информацией, приводила нас в отчаяние. Приятно знать, что еще некоторое время они будут атаковать вслепую.\n\nВ благодарность за все твои свершения мы ходим сделать тебе подарок. Артефакт... один из тех, что мы нашли на раскопках. Вся Лига исследователей признательна тебе.", description = "Ты <нашел/нашла> все документы! Мы не знаем, как и благодарить тебя за помощь… мысль о том, что клан Черного Железа сможет воспользоваться этой информацией, приводила нас в отчаяние. Приятно знать, что еще некоторое время они будут атаковать вслепую.\n\nВ благодарность за все твои свершения мы ходим сделать тебе подарок. Артефакт... один из тех, что мы нашли на раскопках. Вся Лига исследователей признательна тебе.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "ЗвездострелОткрытая кирасаСтарый молот дворфовВы получите:\n\n"}
MultiLanguageQuestData['ru'][13662] = {title = "Завоевать благосклонность", objective = "Ты быстро продвигаешься по служебной лестнице в Братстве, |3-6(дворф). Ты начинаешь в самом деле завоевывать нашу благосклонность. \n\nЕсли хочешь заслужить еще большее уважение, слушай внимательно. \n\nМы хотим повысить качество нашего огненного плавня путем добавления в него окалины черного железа. Окалину можно добыть в Глубинах Черной горы. \n\nПринеси мне как можно больше!", description = nil, progress = "Ты быстро продвигаешься по служебной лестнице в Братстве, |3-6(дворф). Ты начинаешь в самом деле завоевывать нашу благосклонность. \n\nЕсли хочешь заслужить еще большее уважение, слушай внимательно. \n\nМы хотим повысить качество нашего огненного плавня путем добавления в него окалины черного железа. Окалину можно добыть в Глубинах Черной горы. \n\nПринеси мне как можно больше!", completion = "Так, давай сюда окалину!", rewards = nil}
MultiLanguageQuestData['ru'][13663] = {title = "Приказы для Черного рыцаря", objective = "Воспользуйтесь волшебной уздечкой, чтобы подчинить грифона Черного рыцаря и попасть к дому его хозяина. Как только вы попадете на место, найдите украденное приглашение на турнир и приказы для Черного рыцаря, после чего отнесите их рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного Турнира.", description = "Мы должны выяснить, кто послал Черного рыцаря на турнир, и чего именно добивался его хозяин, убивая наших участников.\n\nСовет Кирин-Тора оказал нам содействие в расследовании этого дела.\n\nОни предоставили нам эту волшебную уздечку. Отнеси ее к палатке Черного рыцаря, что на восточном краю Ристалища, с ее помощью приручи его грифона. Магия уздечки заставит грифона отнести тебя к жилищу хозяина рыцаря. Обыщи это место и возвращайся ко мне.", progress = "Что тебе удалось обнаружить?", completion = "&lt;Рыцарь Райдалла бледнеет, читая приказы.&gt;\n\nЭто может означать только одно: Черный рыцарь – член Культа Проклятых! Его послал Артас, чтобы сорвать проведение турнира.\n\nНо он уже проявил себя как могучий воин, и тебе потребуется все твое искусство, чтобы одолеть его. Возвращайся, когда получишь звание чемпиона, и мы постараемся найти способ избавиться от этой угрозы.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13664] = {title = "Падение Черного рыцаря", objective = "Одержите победу над Черным рыцарем, после чего поговорите с рыцарем Райдаллой в Серебряном павильоне на Ристалище Серебряного турнира.", description = "Мы должны положить конец зловещим планам Черного рыцаря и показать всем противникам, что мы не потерпим хладнокровного убийства наших лучших воинов!\n\nБрось вызов Черному рыцарю и одолей его в бою, <имя>.\n\nДля этой битвы я одолжу тебе моего боевого скакуна Серебряного Рассвета, который стоит в стойлах.\n\nПоговори с оруженосцем Кейвином на южной стороне Ристалища. Он вызовет Черного рыцаря на бой, и тебе останется лишь заставить того заплатить за преступления.", progress = "Дело сделано?", completion = "После смерти Черного рыцаря турниру больше ничто не угрожает. Теперь чемпионы Орды и Альянса смогут проявить себя в состязаниях и подготовиться к тому дню, когда Артас и его приспешники будут повержены навсегда.\n\nЯ благодарю тебя от лица всего Серебряного Авангарда и тех, кто откликнулся на его призыв.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13665] = {title = "Великая битва", objective = "Принесите три знака искателя славы капитану Джозефу Холли в шатер Альянса на Ристалище Серебряного турнира.\n\nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.", description = "Великая битва – одно из самых важных соревнований турнира. Люди Штормграда превозносят своих рыцарей и надеются на нашу победу. Лучший способ усовершенствовать свои навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.\n\nПослушай моего совета – иди в стойла за павильоном, оседлай штормградского скакуна и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Альянса.", progress = "Ты уже готов принять участие в великой битве?", completion = "Молодец! Тренировка вместе с другими искателями славы – это лучший способ подготовиться к турниру. Я знаю, что ты принесешь победу Штормграду, Ренгольд.", rewards = "Следующее заклинание будет наложено на вас:\n\nУбрать копье\n\nВы получите:\n\nПечать искателя славыПредмет #1"}
MultiLanguageQuestData['ru'][13666] = {title = "Клинок, достойный чемпиона", objective = "Раздобудьте меч Ясеневого озера и принесите его чародею Таэлису в шатер Альянса на Ристалище Серебряного турнира.", description = "Некоторые бойцы полагают, что древнее оружие, выкованное в Нордсколе, может принести удачу в состязании. Я же согласился помочь им в поисках этих легендарных клинков.\n\nЕсть одна древняя легенда о деве из Ясеневого озера, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.", progress = "Меч у тебя?", completion = "Значит, в старых сказках есть доля правды? Во всяком случае, меч действительно прекрасный! Молодец, Келевон. Как же повезет тому чемпиону, которому в бою послужит этот клинок!", rewards = "Вы получите:\n\nПечать претендентаПредмет #1"}
MultiLanguageQuestData['ru'][13667] = {title = "Серебряный Турнир", objective = "Чтобы принять участие в турнире, поговорите с чародеем Таэлисом в шатре Альянса на Ристалище Серебряного турнира, он внесет ваше имя в списки.", description = "Мы пригласили тебя сюда для того, чтобы испытать твою ловкость и отвагу в поединке с теми, кто противостоит Плети день за днем. До сих пор мы сражались под разными знаменами, но теперь настал день, когда все герои должны скрестить мечи и проверить свою готовность перед битвой с нашим общим врагом.\n\nЧародей Таэлис является представителем Серебряного союза на турнире. Он внесет твое имя в списки и займется начальной подготовкой. Ищи его в огромном шатре Альянса в северо-восточной части Ристалища.", progress = nil, completion = "Я внес твое имя в списки, Миккена. Теперь ты можешь тренироваться как и другие претенденты на участие в турнире и оттачивать навыки верхового поединка. Докажи, что ты достойна – и сможешь участвовать в соревнованиях низкого ранга, защищая честь своей столицы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13668] = {title = "Серебряный Турнир", objective = "Чтобы принять участие в турнире, поговорите с магистром Эдиеном Солнечной Низиной в шатре Орды на Ристалище Серебряного турнира, он внесет ваше имя в списки.", description = "Мы пригласили тебя сюда для того, чтобы испытать твою ловкость и отвагу в поединках с теми, кто противостоит Плети день за днем. До сих пор мы сражались под разными знаменами, но теперь настал день, когда все герои должны скрестить мечи и проверить свою готовность перед битвой с нашим общим врагом.\n\nМагистр Эдиен Солнечная Низина является представителем Похитителей Солнца на турнире. Он внесет твое имя в списки и займется начальной подготовкой. Ищи его в огромном шатре Орды в юго-восточной части Ристалища.", progress = nil, completion = "Я внес твое имя в списки, Анкап. Теперь ты можешь тренироваться как и другие претенденты на участие в турнире и оттачивать навыки верхового поединка. Докажи, что ты достоин – и ты сможешь участвовать в соревнованиях низкого ранга, защищая честь своей столицы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13669] = {title = "Достойное оружие", objective = "Принесите меч Драк'Мара чародею Таэлису в Павильон Серебряного союза на Ристалище Серебряного турнира.", description = "Похоже, нашим чемпионам понравились древние мечи, выкованные в Нордсколе.\n\nДо меня дошли слухи, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул'Драком и Седыми холмами. Посмотрим, одарит ли тебя дева достойным клинком.", progress = "Так барды говорят правду? Меч действительно существует?", completion = "Это на самом деле потрясающий клинок – острый и отлично сбалансированный. Теперь я понимаю, почему эти мечи так ценятся среди чемпионов Альянса.", rewards = "Вы получите:\n\nПечать претендентаПредмет #4"}
MultiLanguageQuestData['ru'][13670] = {title = "Клинок Зимы", objective = "Чародей Таэлис из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести Клинок Зимы.", description = "Один из оруженосцев Стальгорна рассказал мне занятную историю!\n\nВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.\n\nНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты <достоин/достойна> этого меча.", progress = "Ну как? Получилось добыть меч?", completion = "Искатель славы не обманул – это прекрасный клинок. И откуда он только узнал про него? Неважно; он сослужит добрую службу новому владельцу. Будет справедливо, если он достанется абсолютному чемпиону Стальгорна.", rewards = "Вы получите:\n\nПечать претендентаПредмет #1"}
MultiLanguageQuestData['ru'][13671] = {title = "Тренировка на поле боя", objective = "Убейте 8 воинов Плети в Ледяной Короне по заданию Аварета Молниеносного Удара из Павильона Серебряного союза на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны, за исключением зоны бомбардировки.", description = "Турнир – это возможность похвалиться своей силой перед другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем. Продемонстрируй свою отвагу, сразившись с Плетью – и ты заслужишь право участвовать в турнире. \n\nОтправляйся в Ледяную Корону и убей несколько приспешников Плети. Но не пересекай границы Зоны бомбардировки – тебе не удастся справиться со столь многочисленным противником.", progress = nil, completion = "Ты показал свою силу в бою, Хлуси, и твой пример вдохновит других претендентов, желающих сражаться под знаменами Альянса.", rewards = "Вы получите:\n\nПечать претендента"}
MultiLanguageQuestData['ru'][13672] = {title = "Подготовка к испытанию", objective = "Чтобы продемонстрировать свою готовность пройти испытание претендентов, покажите 15 печатей претендента чародею Таэлису из Павильона Серебряного союза на Ристалище Серебряного турнира.", description = "Закончив тренировки, ты получишь возможность пройти испытания претендентов, которые определят твой уровень ведения верхового боя и покажут, стоит ли тебе искать славы. Если ты успешно выдержишь этот экзамен, то сможешь присоединиться к делегации твоего города в качестве искателя славы.\n\nВозвращайся ко мне, когда будешь <готов/готова> к испытаниям.", progress = "Ты хочешь пройти испытание претендентов?", completion = "Хорошо, я дам необходимые распоряжения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13673] = {title = "Клинок, достойный чемпиона", objective = "Раздобудьте меч Ясеневого озера и принесите его магистру Эдиену Солнечной Низине в Павильон Похитителей Солнца на Ристалище Серебряного турнира.", description = "Некоторые бойцы полагают, что древнее оружие, выкованное в Нордсколе, может принести удачу в состязании. Я же согласился помочь им в поисках этих легендарных клинков.\n\nЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.", progress = "Меч у тебя?", completion = "Значит, в старых сказках есть доля правды? Во всяком случае, меч действительно прекрасный! Молодец, Расулх. Как же повезет тому чемпиону, которому в бою послужит этот клинок!", rewards = "Вы получите:\n\nПечать претендентаПредмет #1"}
MultiLanguageQuestData['ru'][13674] = {title = "Достойное оружие", objective = "Принесите меч Драк'Мара магистру Эдиену Солнечной Низине в Павильон Похитителей Солнца на Ристалище Серебряного турнира.", description = "Похоже, нашим чемпионам понравились древние мечи, выкованные в Нордсколе.\n\nДо меня дошли слухи, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул'Драком и Седыми холмами. Посмотрим, одарит ли тебя дева достойным клинком.", progress = "Так барды говорят правду? Меч действительно существует?", completion = "Это на самом деле потрясающий клинок – острый и отлично сбалансированный. Теперь я понимаю, почему эти мечи так ценятся среди чемпионов Альянса.", rewards = "Вы получите:\n\nПечать претендентаПредмет #4"}
MultiLanguageQuestData['ru'][13675] = {title = "Клинок Зимы", objective = "Магистр Эдиен Солнечная Низина из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.", description = "Один из искателей славы Оргриммара рассказал мне занятную историю!\n\nВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.\n\nНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты <достоин/достойна> этого меча.", progress = "Ну как? Получилось добыть меч?", completion = "Искатель славы не обманул – это прекрасный клинок. И откуда он только узнал про него? Неважно; он сослужит добрую службу новому владельцу. Будет справедливо, если он достанется абсолютному чемпиону Оргриммара.", rewards = "Вы получите:\n\nПечать претендентаПредмет #1"}
MultiLanguageQuestData['ru'][13676] = {title = "Тренировка на поле боя", objective = "Убейте 8 воинов Плети в Ледяной Короне по заданию Амариэля Верного Солнцу из Павильона Похитителей Солнца на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны, за исключением зоны бомбардировки.", description = "Турнир – это возможность похвалиться своей силой перед другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем. Продемонстрируй свою отвагу, сразившись с Плетью – и ты заслужишь право участвовать в турнире. \n\nОтправляйся в Ледяную Корону и убей несколько приспешников Плети. Но не пересекай границы Зоны бомбардировки – тебе не удастся справиться со столь многочисленным противником.", progress = "Испытал ли ты свои силы в борьбе с Плетью?", completion = "Ты показал свою силу в бою, Транделар, и твой пример вдохновит других претендентов, желающих сражаться под знаменами Орды.", rewards = "Вы получите:\n\nПечать претендента"}
MultiLanguageQuestData['ru'][13677] = {title = "Большая тренировка", objective = "Отработайте прием \"Выпад\" 5 раз на манекене для ближнего боя, прием \"Удар по щиту\" 2 раза на мишени для дальнего боя и прием \"Рывок\" 2 раза на манекене для стремительной атаки, затем вернитесь к Галатии Сияющий Рассвет в шатер Орды на Ристалище Серебряного турнира.\n\nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.", description = "Большая часть состязаний турнира требует от участников мастерства в управлении верховым животным. Чтобы познакомить тебя с этим видом поединков, мы разместили тренировочные манекены в северной части Ристалища турнира.\n\nЗайди в стойла на севере площадки, рядом с главной ареной, вооружись копьем и оседлай крылобега Похитителей Солнца. Познакомься со всеми доступными приемами и используй новые знания в тренировке. Для освоения новых приемов можешь использовать все три вида манекенов.", progress = nil, completion = "Молодец, Фастпронос. Не все воины легко осваивают приемы верхового поединка. Я не сомневаюсь, что ты продолжишь тренировки и превзойдешь многих воинов в этом виде состязаний.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\nПечать претендента"}
MultiLanguageQuestData['ru'][13678] = {title = "Подготовка к испытанию", objective = "Чтобы продемонстрировать свою готовность пройти испытание претендентов, отдайте 15 печатей претендента магистру Эдиену Солнечной Низине из Павильона Похитителей Солнца на Ристалище Серебряного турнира.", description = "Закончив тренировки, ты получишь возможность пройти испытания претендентов, которые определят твой уровень ведения верхового боя и покажут, стоит ли тебе искать славы. Если ты успешно выдержишь этот экзамен, то сможешь присоединиться к делегации твоего города в качестве искателя славы.\n\nВозвращайся ко мне, когда будешь <готов/готова> к испытаниям.", progress = "Ты хочешь пройти испытание претендентов?", completion = "Хорошо, я дам необходимые распоряжения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13679] = {title = "Испытание претендента", objective = "Поговорите с оруженосцем Давидом, чтобы вызвать на поединок вашего противника. Как только вы победите искателя славы Серебряного Авангарда, вернитесь к чародею Таэлису в шатер Альянса на Ристалище Серебряного Турнира.\n\nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.", description = "Ты очень <прилежно занимался/прилежно занималась> на тренировках, <имя>, и теперь пришло время проверить твои навыки верхового поединка в бою против опытного противника.\n\nНа Арене претендентов в северной части Ристалища тебя ждет мальчик – оруженосец Давид. Он проверит твою готовность к сражению и вызовет того, с кем тебе предстоит сразиться.\n\nУдачи, <имя>. Да не споткнется твой конь, и да будет крепкой твоя рука.", progress = nil, completion = "Мои поздравления, Нагально. Все испытания пройдены и ты полностью заслуживаешь право носить титул искателя славы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13680] = {title = "Испытание претендента", objective = "Поговорите с оруженосцем Давидом, чтобы вызвать на поединок вашего противника. Как только вы победите искателя славы Серебряного Авангарда, вернитесь к магистру Эдиену Солнечной Низине в Павильон Похитителей Солнца на Ристалище Серебряного Турнира.", description = "Ты очень <прилежно занимался/прилежно занималась> на тренировках, <имя>, и теперь пришло время проверить твои навыки верхового поединка в бою против опытного противника.\n\nВооружись копьем и оседлай крылобега Похитителей Солнца.\n\nНа Арене претендентов в северной части Ристалища тебя ждет мальчик – оруженосец Давид. Он проверит твою готовность к сражению и вызовет того, с кем тебе предстоит сразиться.\n\nУдачи, <имя>. Да не споткнется твой конь, и да будет крепкой твоя рука.", progress = "Ты прошел испытание?", completion = "Мои поздравления, Транделар. Все испытания пройдены и ты полностью заслуживаешь право носить титул искателя славы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13681] = {title = "Обломки стен Ульдуара", objective = "Принесите 15 небольших камней Боззлу Рвизасову на Ристалище Серебряного турнира.", description = "Ух, <дружище/подруга>, как же тяжело добыть камни для этой стройки! Тонны материала валяются в руинах в тихих и безопасных местах, но их святейшества паладины не позволяют к ним прикоснуться. \"Бесценные артефакты\", надо же.\n\nЛадно, жалобами делу не поможешь. В Подножии и Библиотеке Изобретателя в Грозовой Гряде некогда были постройки титанов, сейчас же там одни руины. Вот, возьми эту штуку, так называемое \"гоблинское долото\" и попробуй разбить огромные обломки на более транспортабельные куски.", progress = "Ты принес камни?", completion = "Да, неплохой материал. Только смотри, не разболтай этим святошам, откуда ты его взял. Что-то мне подсказывает, что они огорчатся. Мне же кажется, что титаны не вернутся за этими камушками, так что все честно. Молодец, Профессия.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13682] = {title = "Атака с воздуха", objective = "Эдрик Чистый из Серебряного павильона на Ристалище Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов-сектантов.", description = "После того как тебе удалось обнаружить лазутчика Культа Проклятых, верховный лорд Тирион Фордринг приказал удвоить охрану. Он не верит, что их остановит поражение Черного рыцаря.\n\nВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа. Его видели на юго-западе, между Железным валом и Алдур'таром.", progress = nil, completion = "Аркоман, ты и твои союзники защитили турнир от нападения врагов. Хотя наши воздушные разведчики не менее отважны, у них много дел по охране воздушного пространства. Мы благодарим тебя от лица Серебряного Авангарда и всех участников турнира.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКошелек чемпионаУдостоверение чемпиона\n\nВы также получите:\n\nПрипасы для экспедиции в НордсколПечать чемпионаCurrency Token Test Token 2"}
MultiLanguageQuestData['ru'][13683] = {title = "Прервать ритуалы", objective = "Уничтожьте 8 ритуальных самоцветов.", description = "Я случайно услышал слова Иллианы и таким образом узнал об ее утрате. Понимаю, она хочет отомстить. Но если она избрала тебя своим орудием, возможно, ты заодно согласишься оказать нам услугу?\n\nНе сомневаюсь, тебе уже встречались сатиры Сатирнаара и Ксавиана. Эти существа проводят зловещие ритуалы, и у меня есть все основания полагать, что с их помощью они превращают захваченных ночных эльфов в себе подобных. Мы, дренеи, не можем смириться с проявлениями магии скверны.\n\nПрошу тебя, когда отправишься туда, уничтожь их ритуальные самоцветы!", progress = nil, completion = "Мы у тебя в долгу, |3-6(Маг).\n\nТеперь, когда сатиры больше не могут проводить свои омерзительные ритуалы, они обречены на поражение.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13684] = {title = "Искатель славы из Штормграда", objective = "Если вы хотите стать искателем славы Штормграда, поговорите с маршалом Якобом Алерием на Ристалище Серебряного турнира.", description = "Ты достойно <сражался/сражалась> под знаменами Штормграда, <имя>. Теперь тебе следует предстать перед маршалом Якобом Алерием. Это глава делегации Штормграда и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.\n\nДля меня было честью работать с тобой, <имя>. Удачи тебе на состязаниях!", progress = nil, completion = "В таком случае – добро пожаловать в нашу компанию, искатель славы Нагально. Делегация Штормграда приветствует тебя в своих рядах.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13685] = {title = "Искатель славы из Стальгорна", objective = "Если вы хотите стать искателем славы Стальгорна, поговорите с Ланой Твердомолот на Ристалище Серебряного турнира.", description = "Ты достойно <сражался/сражалась> под знаменами Стальгорна, <имя>. Теперь тебе следует предстать перед Ланой Твердомолот. Это глава делегации Стальгорна и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.\n\nДля меня было честью работать с тобой, <имя>. Удачи тебе на состязаниях!", progress = nil, completion = "Приятно познакомиться, искатель славы. Стальгорну нужны такие участники, как ты.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13688] = {title = "Искатель славы из Гномрегана", objective = "Если вы хотите стать искателем славы Гномрегана, поговорите с Амброзом Искрокрутом на Ристалище Серебряного турнира.", description = "Ты достойно <сражался/сражалась> под знаменами Гномрегана, <имя>. Теперь тебе следует предстать перед Амброзом Искрокрутом. Это глава делегации Гномрегана и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.\n\nДля меня было честью работать с тобой, <имя>. Удачи тебе на состязаниях!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13689] = {title = "Искатель славы из Дарнаса", objective = "Чтобы стать искателем славы Дарнаса, поговорите с Джейлин Закатной Песней на Ристалище Серебряного турнира.", description = "Ты достойно <сражался/сражалась> под знаменами Дарнаса, <имя>. Теперь тебе следует предстать перед Джейлин Закатной Песней. Это глава делегации Дарнаса и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.\n\nДля меня было честью работать с тобой, <имя>. Удачи тебе на состязаниях!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nГодность к участию в турнире со стороны Альянса flag\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13690] = {title = "Искатель славы из Экзодара", objective = "Если вы хотите стать искателем славы Экзодара, поговорите с Колосусом на Ристалище Серебряного турнира.", description = "Ты достойно <сражался/сражалась> под знаменами Экзодара, <имя>. Теперь тебе следует предстать перед Колосусом. Это глава делегации Экзодара и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.\n\nДля меня было честью работать с тобой, <имя>. Удачи тебе на состязаниях!", progress = nil, completion = "В таком случае – добро пожаловать в нашу компанию, искатель славы Миккена. Делегация Экзодара приветствует тебя в своих рядах.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13691] = {title = "Искатель славы из Оргриммара", objective = "Если вы хотите стать искателем славы Оргриммара, поговорите с Мокрой Дробителем Черепов на Ристалище Серебряного турнира.", description = "Ты достойно <сражался/сражалась> под знаменами Оргриммара, <имя>. Теперь тебе следует предстать перед Мокрой Дробителем Черепов. Это глава делегации Оргриммара и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и проверять твои навыки.\n\nДля меня было честью работать с тобой, <имя>. Удачи тебе на состязаниях!", progress = nil, completion = "Значит, ты хочешь сражаться за Оргриммар? Если тебе удалось одолеть парочку манекенов – это еще не значит, что ты победишь в турнире, но теперь ты будешь тренироваться вместе с самыми лучшими воинами, что несколько повысит твои шансы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13692] = {title = "Меч из моря", objective = "Старина Барло из Леса Хрустальной Песни просит вас принести ему Меч Рыцарства.", description = "Мой меч канул в глубине моря. Найди его и принеси обратно!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13693] = {title = "Искатель славы из Сен'джина", objective = "Если вы хотите стать искателем славы Сен'джина, поговорите с Зул'тором в Павильоне Похитителей Солнца на Ристалище Серебряного Турнира.", description = "Ты достойно <сражался/сражалась> под знаменами Сен'джина, <имя>. Теперь тебе следует предстать перед Зул'тором, предводителем воинов и абсолютным чемпионом Сен'джина. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.\n\nДля меня было честью работать с тобой, <имя>. Удачи тебе на состязаниях!", progress = nil, completion = "Думаешь, ты можешь сражаться под флагами Сен'джина? Мы это проверим.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13694] = {title = "Искатель славы из Громового Утеса", objective = "Если вы хотите стать искателем славы Громового Утеса, поговорите с Руноком Буйногривым на Ристалище Серебряного турнира.", description = "Ты достойно <сражался/сражалась> под знаменами Громового Утеса, <имя>. Теперь тебе следует предстать перед Руноком Буйногривым. Это глава делегации Громового Утеса и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.\n\nДля меня было честью работать с тобой, <имя>. Удачи тебе на состязаниях!", progress = nil, completion = "Приветствую тебя от лица всех воинов Громового Утеса! Сражайся с честью под нашими знаменами.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13695] = {title = "Искатель славы из Подгорода", objective = "Если вы хотите стать искателем славы Подгорода, поговорите со стражем смерти Визери на Ристалище Серебряного турнира.", description = "Ты достойно <сражался/сражалась> под знаменами Подгорода, <имя>. Теперь тебе следует предстать перед стражем смерти Визери. Это глава делегации Подгорода и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.\n\nДля меня было честью работать с тобой, <имя>. Удачи тебе на состязаниях!", progress = nil, completion = "Добро пожаловать в делегацию Подгорода, Транделар. Мы беремся подготовить тебя к самым ответственным соревнованиям.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13696] = {title = "Искатель славы из Луносвета", objective = "Если вы хотите стать искателем славы Луносвета, поговорите с Эрессеей Певицей Рассвета на Ристалище Серебряного турнира.", description = "Ты достойно <сражался/сражалась> под знаменами Луносвета, <имя>. Теперь тебе следует предстать перед Эрессеей Певицей Рассвета. Это глава делегации Луносвета и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.\n\nДля меня было честью работать с тобой, <имя>. Удачи тебе на состязаниях!", progress = nil, completion = "Значит, ты хочешь сражаться за Луносвет? Отлично. Я добавлю тебя в списки, и ты немедленно сможешь приступить к тренировкам с другими искателями славы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13697] = {title = "Путь искателя славы", objective = "Принесите 25 печатей искателя славы Мокре Дробителю Черепов в Павильон Похитителей Солнца на Ристалище Серебряного Турнира.", description = "Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.\n\nИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.\n\nПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.", progress = "Ты готов продемонстрировать свое искусство искателя славы?", completion = "Впечатляюще, искатель славы! Я немедленно распоряжусь о проведении испытания.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13698] = {title = "Взрывчатые материалы на борту", objective = "Уничтожьте 8 бочонков со взрывчаткой с помощью крошшера клана Песни Войны.", description = "Мне не хотелось бы посылать тебя обратно, но если дела действительно обстоят так, как ты говоришь, мы не можем позволить им использовать всю эту взрывчатку!\n\nСоваться туда без прикрытия слишком опасно, но если тебе удастся угнать один из крошшеров, то его броня выдержит даже направленный взрыв.\n\nПосле того как уничтожишь взрывчатку, пригони крошшер сюда. Нет смысла возвращать им такую ценную машину.", progress = nil, completion = "Взрывы были видны даже отсюда! Теперь этим жалким оркам и их прислужникам-гоблинам придется попотеть, если они снова захотят ограбить наши леса.\n\nНе знаю даже, как тебя вознаградить. Как ты думаешь, эта вещь может служить достойной компенсацией за потраченное время?", rewards = "Лезвие крошшераЖилет с пороховыми подпалинамиНабедренники хранителя лесаВы получите:\n\n"}
MultiLanguageQuestData['ru'][13699] = {title = "Испытание искателя славы", objective = "Поговорите с оруженосцем Дэнни, чтобы вызвать на поединок вашего противника. Как только вы победите чемпиона Серебряного Авангарда, вернитесь к маршалу Якобу Алерию на Ристалище Серебряного Турнира.\n\nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.", description = "Скоро ты будешь <готов/готова> сразиться в великой битве во имя Штормграда. Если хочешь доказать, что <достоин/достойна> представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.\n\nОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.\n\nВозвращайся ко мне после боя, и мы обсудим результаты.", progress = nil, completion = "Ты доказал, что достоин титула чемпиона, Ренгольд. Теперь ты будешь с оружием наготове защищать честь Штормграда на самом высоком уровне и носить наш герб на своем флаге.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13702] = {title = "Рождение героя", objective = "Поговорите с вершительницей правосудия Мариэль Чистосердечной на Ристалище Серебряного турнира.", description = "Поздравляю, <имя>. Ты <прошел/прошла> все испытания и <отточил/отточила> до совершенства различные стили боя. Теперь у меня нет сомнений в том, что ты <готов/готова> сразиться с лучшими воинами турнира – чемпионами столиц.\n\nНо для того, чтобы соблюсти все формальности, тебе надо будет поговорить с вершительницей правосудия Мариэль Чистосердечной. Иди, она ждет тебя!", progress = nil, completion = "Я приветствую тебя как чемпиона турнира, Наркомани. В этом звании ты сможешь принять участие в самых крупных состязаниях. Ты также можешь стать искателем славы другого города и со временем завоевать звание его чемпиона.\n\nВсе чемпионы обязаны пользоваться услугами оруженосцев, и ты, Наркомани, не исключение. Позволь мне порекомендовать тебе надежного помощника в будущих сражениях. Он будет гордо нести флаг столицы, которая избрала тебя своей представительницей.", rewards = "Вы получите:\n\nОруженосец Серебряного АвангардаПечать чемпиона"}
MultiLanguageQuestData['ru'][13703] = {title = "Искатель славы из Стальгорна", objective = "Если вы хотите стать искателем славы Стальгорна, поговорите еще раз с Ланой Твердомолот в Павильоне Серебряного Союза.", description = "Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Не желаешь ли к нам присоединиться?\n\nТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Стальгорна позволит тебе выступать под нашим флагом.", progress = nil, completion = "Мы рады, что ты решил к нам присоединиться. Вскоре на поле битвы загорится новая звезда.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13704] = {title = "Искатель славы из Гномрегана", objective = "Если вы хотите стать искателем славы Гномрегана, поговорите еще раз с Амброзом Искрокрутом в Павильоне Серебряного Союза.", description = "Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Ты <мог/могла> бы значительно усилить делегацию Гномрегана!\n\nТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Гномрегана позволит тебе выступать под нашим флагом.", progress = nil, completion = "Мы рады приветствовать тебя среди нас, Наркомани. Надеюсь, вскоре мы будем тренироваться бок о бок.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13705] = {title = "Искатель славы из Экзодара", objective = "Если вы хотите стать искателем славы Экзодара, поговорите еще раз с Колосусом в Павильоне Серебряного Союза.", description = "Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Не желаешь к нам присоединиться?\n\nТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Экзодара позволит тебе выступать под нашим флагом.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13706] = {title = "Искатель славы из Дарнаса", objective = "Если вы хотите стать искателем славы Дарнаса, поговорите еще раз с Джейлин Закатной Песней.", description = "Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Буду рада включить тебя в число участников делегации Дарнаса, если ты желаешь к нам присоединиться.\n\nТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Дарнаса позволит тебе выступать под нашим флагом.", progress = nil, completion = "Воины Дарнаса гордятся возможностью сражаться рядом с тобой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13707] = {title = "Искатель славы из Оргриммара", objective = "Если вы хотите стать искателем славы Оргриммара, поговорите еще раз с Мокрой Дробителем Черепов в Павильоне Похитителей Солнца.", description = "Значит, ты уже <получил/получила> звание чемпиона? Должно быть, ты <проявил/проявила> себя как достойный боец, и я буду рад включить тебя в число участников делегации Оргриммара.\n\nТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Оргриммара позволит тебе выступать под нашим флагом.", progress = nil, completion = "Добро пожаловать, Акул. Жду не дождусь, когда ты начнешь тренировку с моими воинами.", rewards = "Следующее заклинание будет наложено на вас:\n\nПригодность к участию в турнире от Орды Flag\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13708] = {title = "Искатель славы из Сен'джина", objective = "Если вы хотите стать искателем славы Сен'джина, поговорите еще раз с Зул'тором в Павильоне Похитителей Солнца.", description = "Приветствую тебя, чемпион. Если желаешь, я могу записать тебя в делегацию Сен'джина.\n\nТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Сен'джина позволит тебе выступать под нашим флагом.", progress = nil, completion = "Хорошо, что ты решил к нам присоединиться! Скорее бы увидеть тебя в деле.", rewards = "Следующее заклинание будет наложено на вас:\n\nПригодность к участию в турнире от Орды Flag\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13709] = {title = "Искатель славы из Громового Утеса", objective = "Если вы хотите стать искателем славы Громового Утеса, поговорите еще раз с Руноком Буйногривым в Павильоне Похитителей Солнца.", description = "Приветствую тебя, чемпион. Как абсолютный чемпион Громового Утеса я буду рад включить тебя в число участников нашей делегации.\n\nТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Громового Утеса позволит тебе выступать под нашим флагом.", progress = nil, completion = "Это честь для нас – приветствовать тебя в составе делегации. Я знаю, что ты принесешь нам победу, Сагрис.", rewards = "Следующее заклинание будет наложено на вас:\n\nПригодность к участию в турнире от Орды Flag\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13710] = {title = "Искатель славы из Подгорода", objective = "Если вы хотите стать искателем славы Подгорода, поговорите еще раз со стражем смерти Визери в Павильоне Похитителей Солнца.", description = "Приветствую тебя, чемпион. Твое присутствие значительно усилит делегацию Отрекшихся. Не желаешь ли присоединиться к нам?\n\nТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Подгорода позволит тебе выступать под нашим флагом.", progress = nil, completion = "Мудрый выбор, Анвалт. Мы оба только выиграем от этого решения.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13711] = {title = "Искатель славы из Луносвета", objective = "Если вы хотите стать искателем славы Луносвета, поговорите еще раз с Эрессеей Певицей Рассвета в Павильоне Похитителей Солнца.", description = "Значит, ты уже <получил/получила> звание чемпиона? Должно быть, ты <проявил/проявила> себя как достойный боец, и я буду рада включить тебя в число участников делегации Луносвета.\n\nТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Луносвета позволит тебе выступать под нашим флагом.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПригодность к участию в турнире от Орды Flag\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13712] = {title = "Путь к спасению", objective = "Поговорите с Кадраком на заставе Мор'шан и сопроводите его к Заставе Расщепленного Дерева.", description = "Ты пойдешь со мной, <имя>.\n\nЯ не могу рисковать своими людьми, и не могу допустить, чтобы Застава Расщепленного Дерева была захвачена.\n\nПодготовься и возвращайся ко мне.", progress = "Дело сделано!", completion = "Мы едва не погибли, Магребинец.\n\nТолько наше вмешательство уберегло Заставу Расщепленного Дерева – а значит, смерть Горки была не напрасной.\n\nНо теперь мы должны укрепить оборону крепости. Война еще не закончена...", rewards = "Вы получите:\n\nКольцо Горки"}
MultiLanguageQuestData['ru'][13713] = {title = "Испытание искателя славы", objective = "Поговорите с оруженосцем Дэнни, чтобы вызвать на поединок вашего противника. Как только вы победите чемпиона Серебряного Авангарда, вернитесь к Лане Твердомолот в шатер Альянса на Ристалище Серебряного Турнира.\n\nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.", description = "Скоро ты будешь <готов/готова> сразиться в великой битве во имя Стальгорна. Если хочешь доказать, что <достоин/достойна> представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.\n\nОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.\n\nВозвращайся ко мне после боя, и мы обсудим результаты.", progress = "Ты одержал верх над чемпионом Серебряного Авангарда?", completion = "Ты доказал, что достоин титула чемпиона, Асмариэль. Теперь ты будешь с оружием наготове защищать честь Стальгорна на самом высоком уровне и носить наш герб на своем флаге.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13714] = {title = "Путь искателя славы", objective = "Принесите 25 печатей искателя славы Лане Твердомолот в Павильон Серебряного союза на Ристалище Серебряного Турнира.", description = "Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.\n\nИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.\n\nПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.", progress = "Ты готов продемонстрировать свое искусство искателя славы?", completion = "Впечатляюще, искатель славы! Я немедленно распоряжусь о проведении испытания.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13715] = {title = "Путь искателя славы", objective = "Принесите 25 печатей искателя славы Амброзу Искрокруту в шатер Альянса на Ристалище Серебряного Турнира.", description = "Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.\n\nИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.\n\nПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.", progress = "Ты готов продемонстрировать свое искусство искателя славы?", completion = "Впечатляюще, искатель славы! Я немедленно распоряжусь о проведении испытания.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13716] = {title = "Путь искателя славы", objective = "Принесите 25 печатей искателя славы Колосусу в шатер Альянса на Ристалище Серебряного Турнира.", description = "Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.\n\nИскатели славы – отважные воины, которые сражаются друг с другом ради почета и признания.\n\nПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.", progress = "Ты готов продемонстрировать свое искусство искателя славы?", completion = "Впечатляюще, искатель славы! Я немедленно распоряжусь о проведении испытания.", rewards = "Вы получите:\n\n"}
