MultiLanguageQuestData['ru'][13860] = {title = "У вражеских врат", objective = "Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию дрессировщика Дреча из Павильона Похитителей Солнца на Ристалище Серебряного турнира.", description = "Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.\n\nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.\n\nПусть тебя не смущают костяные пехотинцы, <имя> – копыта твоего скакуна легко переломают их истлевшие кости.", progress = nil, completion = "Рыцари Серебряного Авангарда убедились в нашей доблести и теперь знают, что мы будем стоять до конца.", rewards = "Вы получите:\n\nПечать искателя славы"}
MultiLanguageQuestData['ru'][13861] = {title = "Битва у Цитадели", objective = "По заданию Эдрика Чистого из Серебряного павильона на Ристалище Серебряного турнира убейте 3 костяных командиров.", description = "Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.\n\nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп'ретар. Бери копье, седлай турнирного скакуна и отправляйся на истребление подданных Короля-лича.\n\nПусть тебя не смущают костяные пехотинцы, <имя> – копыта твоего скакуна легко переломают их истлевшие кости.", progress = nil, completion = "Как прекрасно, что на стороне Серебряного Авангарда сражается такой доблестный |3-6(Маг), как ты.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКошелек чемпионаУдостоверение чемпиона\n\nВы также получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][13862] = {title = "Битва у Цитадели", objective = "По заданию Эдрика Чистого из Серебряного павильона на Ристалище Серебряного турнира убейте 3 костяных командиров.", description = "Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.\n\nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп'ретар. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.\n\nПусть тебя не смущают костяные пехотинцы, <имя> – копыта твоего скакуна легко переломают их истлевшие кости.", progress = nil, completion = "Как прекрасно, что на стороне Серебряного Авангарда сражается такой доблестный |3-6(Друид), как ты.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКошелек чемпионаУдостоверение чемпиона\n\nВы также получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][13863] = {title = "Битва у Цитадели", objective = "По заданию Крока Грозы Плети с Ристалища Серебряного турнира убейте 3 костяных командиров.", description = "Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.\n\nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп'ретар. Бери копье, седлай турнирного скакуна и отправляйся на истребление подданных Короля-лича.\n\nПусть тебя не смущают костяные пехотинцы, <имя> – копыта твоего скакуна легко переломают их истлевшие кости.", progress = nil, completion = "Всюду, где появляемся мы, Плеть бежит в ужасе. И следующая атака не будет исключением.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКошелек чемпионаУдостоверение чемпиона\n\nВы также получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][13864] = {title = "Битва у Цитадели", objective = "По заданию Крока Грозы Плети с Ристалища Серебряного турнира убейте 3 костяных командиров.", description = "Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.\n\nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп'ретар. Бери копье, седлай турнирного скакуна и отправляйся на истребление подданных Короля-лича.\n\nПусть тебя не смущают костяные пехотинцы, <имя> – копыта твоего скакуна легко переломают их истлевшие кости.", progress = nil, completion = "Всюду, где появляемся мы, Плеть бежит в ужасе. И следующая атака не будет исключением.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКошелек чемпионаУдостоверение чемпиона\n\nВы также получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][13865] = {title = "Мокрая работенка", objective = "Крокк просит вас убить Доринара, Арминона, Эндолара и 12 разведчиков Ясеневого леса.\n\nЕсли вы вдруг потеряете секретный порошок вызова, поговорите с Кадраком на Заставе Расщепленного Дерева.", description = "Слушай внимательно, <класс>.\n\nВ этих краях эльфами командуют трое, и внимание их сосредоточено на лесопилке. Убить их – значит посеять панику и беспорядок в рядах эльфов, и, возможно, тогда мы сможем выполнить свою задачу здесь.\n\nБудешь на месте, учти, что чем больше разведчиков ты сможешь уничтожить, тем ближе окажется наша цель.", progress = nil, completion = "Прекрасно, |3-6(Разбойник).\n\nТы только посмотри – наши враги в панике!", rewards = "Перчатки для мокрых делПояс тайных знаковСапоги замешательстваВы получите:\n\n"}
MultiLanguageQuestData['ru'][13866] = {title = "К заставе!", objective = "Поговорите с Кулгом Кровобрызгом на границе Ясеневого леса и Азшары, и он оправит вас на заставу Мор'шан. По прибытии немедленно разыщите Кадрака.", description = "Леса позади тебя только кажутся спокойными – на самом деле наши враги притаились за каждым деревом. Я видел много тел орков, подстреленных в спину – они даже не успели обнажить оружие.\n\nТам, за границей, пролегают опасные земли, но смекалка и острые клинки помогут нам выжить на заставе Мор'шан. Именно оттуда Кадрак планирует начать нападение – он всегда предпочитал действие разговорам. С этого момента вы с ним будете действовать заодно.\n\nОкликни меня, когда будешь <готов/готова> лететь, и я тебе помогу.", progress = nil, completion = "Ты как раз вовремя, |3-6(Друид). Старина Кулг уже давно бродит по чаще и видит, как разрослись деревья. Теперь их кроны поглотила тьма. Но мы не будем больше бояться этой дубравы! Настало время укротить Ясеневый лес – раз и навсегда!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13867] = {title = "Устранение угрозы фурболгов", objective = "Убейте 15 фурболгов в деревне Колючего Меха.", description = "Если идти прямо на север Астранаара, можно встретить фурболгов из племени Колючий Мех. Мои разведчики докладывают, что за прошедшие несколько месяцев их численность значительно выросла. Если их окажется слишком много, они могут попытаться собрать армию и атаковать сам Астранаар!\n\nОтправляйся в деревню Колючего Меха и убей как можно больше этих существ.\n\nЯ же останусь в Астранааре и буду ждать от тебя известий. Да пребудет с тобой Элуна, <класс>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13868] = {title = "Искажающее влияние?", objective = "Отнесите оберег троллей Раэне Волкопас в Астранаар, что в Ясеневом лесу.", description = "Обыскивая сумки мертвого фурболга, вы находите маленький оберег, явно изготовленный руками троллей.\n\nПодняв его с земли, вы внезапно ощущаете что-то странное в этом куске дерева – как будто его окружает некая темная аура проклятья\n\nОсторожно завернув его в обрывок какой-то ткани, вы кладете оберег в сумку и напоминаете себе непременно показать его Раэне Волкопас при следующем визите в Астранаар.", progress = "Что тебя беспокоит, |3-6(Охотник)?", completion = "Оберег троллей? Что он делал в руках фурболга?\n\nТы прав, здесь чувствуется след порчи...\n\nНо я знаю, кто может помочь нам разобраться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13869] = {title = "Вернуть останки", objective = "Раздобудьте 10 штабелей древесины клана Песни Войны.", description = "То, что сатиры сделали с этим деревьями, ужасно, но это не идет ни в какое сравнение с массовыми убийствами, которые учинили орки!\n\n<Великий Древний весь сотрясается от ярости, осыпая вас листьями.>\n\n<раса>, я прошу тебя отправиться по дороге, ведущей на лесопилку, и спасти хотя бы остатки этих деревьев, древней и энтов, погибших от руки высокомерной Орды.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13870] = {title = "Как нельзя лучше", objective = "Крокк просит вас проникнуть на лесопилку Песни Войны и поговорить с надзирателем Гортаком.", description = "Ну что, <класс>, все складывается как нельзя лучше.\n\nПока эльфы еще не оправились от твоей последней вылазки – самое время совершить набег на лесопилку!\n\nНайди способ проникнуть туда и поговори с надзирателем Гортаком. Он расскажет тебе, как лучше всего сопроводить дипломата в безопасное место.\n\nУдачи!", progress = nil, completion = "&lt;Гортак огорченно вздыхает.&gt;\n\nАх, где же ты был час назад... В наш лагерь прокрался ночной эльф-убийца и напал на дипломата. К сожалению, раны оказались смертельными.\n\nМы до сих пор не знаем, как наемнику удалось проскользнуть незамеченным.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13871] = {title = "Безопасность превыше всего!", objective = "Надзиратель Гортак просит вас принести ему голову калдорайской убийцы.", description = "Можно подумать, мне тут нечем заняться!\n\nНе так уж легко сохранять порядок в этом месте, когда со всех сторон атакуют эльфы и дренеи. А тут еще какой-то убийца шныряет вокруг лагеря, и уже перерезал горло чрезвычайно важному послу... причем во время моего дежурства!\n\nЭто зашло слишком далеко, <класс>. Ищи по всему лагерю, пока не найдешь наемника, и отомсти за погибшего дипломата.\n\nКогда я предстану перед Адским Криком, я хочу хотя бы предъявить ему голову убийцы в качестве оправдания.", progress = "Я хочу знать только одно, |3-6(орк) – убийца мертв?", completion = "Очень хорошо, |3-6(Шаман).\n\nУ меня к тебе последняя просьба – будет лучше, если никто из работников не узнает о том, что этот убийца вообще существовал.", rewards = "Демаскирующий щитВорованный калдорайский поясАрбалет охраныВы получите:\n\n"}
MultiLanguageQuestData['ru'][13872] = {title = "Мудрость воргена", objective = "Отнесите оберег троллей пилигриму Гефесту в Астранаар, что в Ясеневом лесу.", description = "Этот парень напротив меня известен как пилигрим Гефест. Он ворген.\n\nНе так давно он вместе с сестрой прибыл в Астранаар в поисках убежища. Насколько мне удалось понять, он хочет помочь Служителям Земли справиться с последствиями Катаклизма. Его сестра обладает еще более могущественными способностями. Ее отправили на восток усмирять вулкан.\n\nВозможно, этот ворген сможет нам помочь. Отнеси ему оберег и спроси, что он о нем думает.", progress = "<Ворген безразлично смотрит на то, как вы приближаетесь к нему.>", completion = "&lt;Ворген смотрит на резную деревяшку, лежащую у вас на ладони, и протягивает к ней руку.&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13873] = {title = "Последняя просьба Шилы", objective = "Страж Менерин просит вас отнести запечатанное послание Шилы стражу Гуртару.\n\nПрилагается предмет: \n", description = "Я... не могу поверить, что она погибла. Все случилось так быстро...\n\nПолагаю, я должен поблагодарить тебя за то, что ты <отомстил/отомстила> за смерть госпожи. Весь Луносвет в долгу перед тобой.\n\nВ безграничной мудрости своей повелительница предвидела свою смерть. Она оставила это послание и попросила доставить его по назначению, если с ней что-то случится.\n\nМы должны были присоединиться к оргриммарскому эскорту на перекрестке, что к северу от этого места. Прошу тебя, <раса>, встреть их вместо нас и убедись, что письмо попало в нужные руки.", progress = nil, completion = "&lt;Страж Гуртар внимательно выслушивает ваше сообщение о смерти Шилы.&gt;\n\nЯ лично доставлю это известие Адскому Крику. Тебе же придется заняться другим поручением...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13874] = {title = "Жизнь без оберега", objective = "Найдите 8 оберегов троллей.", description = "Фурболги опять решили наложить лапы на то, что им не принадлежит.\n\n<Гефест задумчиво крутит оберег в руках, после чего откладывает в сторону.>\n\nНа этой деревяшке есть символ, который накладывает порчу на всех, кто не принадлежит расе троллей. Как я понимаю, фурболги и раньше этим занимались. Некоторые из них ничему не учатся.\n\nНе сомневаюсь, они хранят обереги в Берлоге Колючего Меха. Она находится прямо над их деревней на севере.", progress = "Думаешь, ты собрал все тролльи обереги в Берлоге Колючего Меха? Лучше проверь еще раз.\n\nЕсли там остался хотя бы один амулет, племя Колючего Меха продолжит нападать на нас, повинуясь его нечестивой силе.", completion = "&lt;Гефест медленно наклоняет голову, не отводя от вас взгляда.&gt;\n\nТы спас фурболгов от их собственной глупости. Надеюсь, в дальнейшем они поостерегутся брать то, что им не принадлежит, особенно такие могущественные предметы.\n\nПравильно ли я понимаю, что у ночных эльфов возникли проблемы еще с одним племенем на юге? Думаю, Раэна хотела поговорить с тобой именно об этом.\n\nОднако сейчас у нас есть более важное дело, которым следует заняться немедленно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13875] = {title = "Просьба Гуртара", objective = "Страж Гуртар просит вас отдать венок из кровавых чашечек Драаке с Заставы Расщепленного Дерева.", description = "<класс>, у меня есть к тебе просьба исключительно личного характера. \n\nМного лун сменилось с тех пор, как я в последний раз видел мою возлюбленную, Драаку. Боюсь, что чувства ее угаснут со временем.\n\nЭтот венок очень дорог нам обоим, как и кровавые чашечки – цветы, что растут только в этих местах.\n\nПожалуйста, собери их, вплети в венок и передай его Драаке. Пусть он напомнит ей о моей любви.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Туфли кровавых чашечекНадежные башмакиПерчатки вечных заветовВы получите:\n\nПредмет #8Предмет #1"}
MultiLanguageQuestData['ru'][13876] = {title = "Он зашел слишком далеко", objective = "Найдите коллекцию Жилотяга.", description = "Да, <раса>, я говорю на твоем языке.\n\nМы, фурболги, уже сталкивались с такого вида порчей. Не так давно наш вождь хитростью завладел идолом Ремула. Эта оскверненная демонами святыня околдовала все племя, и если бы не друид по имени Бролл Медвежья Шкура, нам бы не видать спасения.\n\nНо на этот раз мы ничего не крали. Тролли Зорам'гара сами подарили нам эти обереги в знак дружбы. Видимо, дружба эта оказалась смертельной.\n\nНаш вождь, Дал Жилотяг, зашел слишком далеко. Войди в берлогу и забери его обереги.", progress = "Будущее племени Колючего Меха – в твоих руках, |3-6(дворф).", completion = "Что сделано – то сделано. Болезнь нашего предводителя, вызванная оберегами троллей, уничтожала все племя.\n\nНо для того, чтобы сохранить нашу честь и достоинство, вмешаться должен был кто-то посторонний. Теперь, когда угроза гражданской войны миновала, мы сможем выбрать нового вождя, который не станет больше доверять чужакам. Или в случившемся есть и моя вина?\n\nКак бы то ни было, прежде, чем наши пути разойдутся, позволь мне отблагодарить тебя за помощь.", rewards = "Плащ Зорам'гараВам дадут возможность выбрать одну из следующих наград:\n\nКольцо чертополоха\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13877] = {title = "По течению", objective = "Поговорите с Сабиной на южной границе лавового потока Громовой вершины, что в Ясеневом лесу.", description = "<Ворген окидывает вас оценивающим взглядом, и только после этого переходит к своей просьбе.>\n\nЕсли мы не будем действовать быстро, вулкан поглотит весь Ясеневый лес. Поверь мне на слово, его извержение не было вызвано естественными причинами.\n\nМоя сестра Сабина, могущественный шаман Служителей Земли, отправилась на восток, к Громовой вершине, где течет поток лавы. Она пытается объединить силы прочих стихий, чтобы противостоять повелителю пламени, который стоит за этими чудовищными разрушениями. \n\n<имя>, я прошу тебя – найди ее и предложи свою помощь.", progress = nil, completion = "Должно быть, тебя послал мой брат, а он бы не отправил с поручением того, в ком не уверен на сто процентов.\n\nВо имя всего святого, надеюсь, он в тебе не ошибся.\n\nЭти элементали – мои друзья. Выслушай их и сделай все, о чем они тебя попросят. Только так можно предотвратить гибель Ясеневого леса.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13878] = {title = "Сквозь огонь и воду", objective = "Снимите цепи с волков в горящих стойлах.", description = "Помоги мне, <класс>! Проклятые свинобразы подожгли стойла! Пожар! Пожар!\n\n<Дорак продолжает бессвязно выкрикивать что-то до тех пор, пока вам не удается успокоить его.>\n\nТам до сих пор остались волки. Кто-то должен спасти волчат!", progress = "Горячо!", completion = "Ты спас волков! Это очень храбрый поступок! Возможно, когда-нибудь и ты обзаведешься одним из таких волков.\n\n&lt;Дорак смотрит на горящие стойла, потом на реку неподалеку.&gt;\n\nЧто же мне сейчас делать?", rewards = "Противоогневой покровБашмаки хозяина волковВы получите:\n\n"}
MultiLanguageQuestData['ru'][13879] = {title = "Громовая вершина", objective = "Бройк поручил вам найти Стиквада у Громовой вершины.", description = "Приветствую тебя, <класс>.\n\nПрими мои поздравления с успешным нападением на Астранаар. Это унижение эльфы никогда не забудут.\n\nЖаль, что не только они препятствуют Орде захватить Ясеневый лес...\n\nЕще одна беда наступает с востока, и шаман Служителей Земли уже отправился туда, чтобы попытаться найти выход из кризиса. Разыщи его рядом с подножием вулкана Громовая вершина и окажи всю возможную помощь.", progress = nil, completion = "&lt;Гоблин некоторое время пялится на вас, озадаченно моргая.&gt;\n\nДухи шепнули мне, что помощь близится.\n\nПрости, но я ожидал, что они пошлют кого-нибудь более... сильного.\n\nЭти элементали – наши верные союзники. Выслушай их и сделай так, как они просят. Если мы потерпим неудачу, в Ясеневом лесу не останется ничего, за что стоило бы бороться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13880] = {title = "Горячая лава", objective = "С помощью дара земли заполните 8 лавовых разломов.", description = "<Огромный элементаль земли смотрит на вас сверху вниз.>\n\nЕсли мы хотим победить, необходимо остановить поток лавы. Я передам тебе частичку своей силы – воспользуйся ей, чтобы заполнить лавовые разломы!", progress = "Готово?", completion = "Превосходно, |3-6(тролль). Теперь сила огня лорда Магматара снова покоится в глубинах земли.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13881] = {title = "Одержимые", objective = "Убейте 6 одержимых колючешерстных медведей и обследуйте озеро, из которого они пили.", description = "Больше всего меня беспокоит судьба колючешерстных медведей, что обитают в этих оскверненных лесах. Недавно тяжелая болезнь поразила целое поселение к югу отсюда, и даже медвежье святилище не уберегло их от этой беды.\n\n<имя>, я не знаю, в чем причина этой болезни, но она пожирает их изнутри. Как бы ни было мучительно думать о том, что мы потеряем целое поколение медведей... надо положить конец их страданиям, чтобы земля вновь приняла их в свои объятья.\n\nНо что еще более важно – мы должны найти источник заразы! Возможно, это озеро, из которого все они пили...", progress = nil, completion = "&lt;Катрена выслушивает ваше описание взбесившихся животных и непонятного устройства на дне озера.&gt;\n\nКакой кошмар, Авелфорт... Что это за штука и как она туда попала? Звучит так, как будто нечто поглощает животных физически и духовно. Я подозревала, что тут замешаны сатиры, распространяющие свою заразу... но теперь мне кажется, что это нечто... неестественное.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13882] = {title = "Семена жизни", objective = "Соберите Семя Земли, Семя Моря и Семя Неба.", description = "Что-то подтачивает силы всех живых существ Темных Берегов! Я попытаюсь узнать что-нибудь об этой... штуке, которую ты <нашел/нашла>, но до тех пор надо защитить природу от дальнейшего уничтожения.\n\nМожешь собрать для меня кое-какие материалы? Мне потребуется жизнь во всех ее проявлениях. Поговори с Ону в роще, пусть он отдаст тебе Семя Земли. Затем поймай огонька Темных берегов – и у нас будет Семя воздуха. Наконец, Семя воды можно найти среди ракушек на западном побережье.", progress = "Жизнь – это великая сила, Тихийпутя. В своей чистой форме она способна превзойти все. Когда-нибудь и Темные берега исцелятся от своих ран. Ты принесла то, о чем я тебя просила?", completion = "Отлично, это все, что надо. Надеюсь, тебе понравилось гоняться за огоньками? Я так развлекалась, когда была еще совсем маленькой.\n\n&lt;На мгновение кажется, будто Катрена полностью погрузилась в воспоминания.&gt;\n\nОх... боюсь, теперь я знаю, с чем нам пришлось столкнуться...", rewards = "Шнурованный ремень ловца дымкиПерчатки сеятеляВы получите:\n\n"}
MultiLanguageQuestData['ru'][13883] = {title = "Обломки кораблей", objective = "Соберите 10 кусков затонувшего металлолома.", description = "Эти корабли строили спустя рукава – другого объяснения я не нахожу!\n\nНаверное, строители слишком торопились. Ты только посмотри – бронированная обшивка отваливается даже при непрямом попадании!\n\nДавай я тебе покажу, как это поправить – но сначала надо подобрать куски обшивки со дна моря.\n\nТы принеси обшивку, а я сделаю все остальное.", progress = "Тебе удалось добыть обшивку?", completion = "Прекрасно, |3-6(тролль).\n\nСейчас я им покажу, как надо строить корабли!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13884] = {title = "Потушить огонь", objective = "Убейте 10 лавовых яростеней. Обратитесь к Арктану, если вам потребуется еще один морозный волноход.", description = "Если мы хотим отвоевать территорию и положить конец уничтожению леса, сначала надо разобраться со слугами лорда Магматара.\n\nЯ имею в виду лавовых яростней, что купаются в магме на севере отсюда. Они питаются силой своей стихии, поэтому в одиночку тебе их не одолеть.\n\nОкликни меня, когда будешь <готов/готова> – и я вызову тебе на помощь своего элементаля.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13885] = {title = "В защиту Темных берегов", objective = "Поговорите с Орсеем возле Рощи Древних и оседлайте гиппогрифа. Пролетая над рощей, защитите 8 серых колючешерстных медведей, 8 белохвостых оленей и лунопардов-матриархов и патриархов.", description = "Теперь, когда мы знаем, что наши превентивные меры сработали, нам надо охватить как можно большее пространство.\n\nЯ уже распорядилась подготовить одного из наших гиппогрифов, но мне все равно не справиться в одиночку. Поговори с моим другом Орсеем – он ждет тебя возле распорядителя полетов за чащей. Дай ему знать, когда будешь <готов/готова> отправиться в путь, и я немедля присоединюсь к тебе. Вместе мы защитим Темные Берега с воздуха и спасем несчастных животных!", progress = nil, completion = "Значит, животные теперь в безопасности! Спасибо, спасибо тебе!\n\nТеперь мы должны обратить наше внимание на источник заразы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13886] = {title = "Вихрь", objective = "Убейте лорда Магматара с помощью Кружащегося вихря.", description = "Время пришло, <имя>. Вооружайся и приходи ко мне. Я вызову кружащийся вихрь, который в мгновение ока перенесет тебя по небу в Громовую вершину.\n\nНаправь силу Служителей Земли через элементаля, чтобы уничтожить лорда Магматара, и равновесие вновь будет восстановлено.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Перчатки усмирителяПояс равновесияВам дадут возможность выбрать одну из следующих наград:\n\nЦветок Служителей Земли\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13887] = {title = "Яйца ядошкурого равазавра", objective = "Принесите Мор'веку 4 яйца ядошкурого равазавра. Он будет ждать вас на юго-востоке Топей.", description = "Теперь, когда у тебя выработался иммунитет к яду равазавра, ты сможешь прикасаться как к самим животным, так и к ядовитым яйцам. Эти ящеры – хищные зверюги, и их надо приручать с самого рождения.\n\nТак что, если ты хочешь оседлать равазавра, найди невылупившееся яйцо – их полно в гнездах по всей Топи. Ищи яйца со светлой скорлупой – именно из таких рождаются ядошкурые равазавры.\n\nЕсли принесешь мне несколько яиц, я разрешу тебе взять одно из них и научу, как приручить твоего зверька.", progress = "Ты нашел яйца?", completion = "Молодец! Честно говоря, я удивлен тем, что тебе удалось достать так много яиц. В последнее время они встречаются все реже и реже.\n\nВот, возьми этого равазаврика. Он сам даст тебе знать, что ему нужно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13888] = {title = "Вихрь", objective = "Убейте лорда Магматара с помощью Кружащегося вихря.", description = "Время пришло, <имя>. Вооружайся и приходи ко мне. Я вызову кружащийся вихрь, который в мгновение ока перенесет тебя по небу в Громовую вершину.\n\nНаправь силу Служителей Земли через элементаля, чтобы уничтожить лорда Магматара, и равновесие вновь будет восстановлено.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Перчатки усмирителяПояс равновесияВам дадут возможность выбрать одну из следующих наград:\n\nЦветок Служителей Земли\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13889] = {title = "Бедный, голодный равазаврик", objective = "Ваш равазаврик хочет съесть 15 кусков свежего мяса динозавра.", description = "Равазаврик выжидательно смотрит на вас, после чего начинает опять что-то рисовать в грязи.\n\nКонечно, рисунки очень грубые, но вам все же удается разобрать очертания деметродонов, стегодонов и терродактилей. Когда ящер заканчивает рисунок, он ощеривает зубы и выразительно щелкает челюстью.\n\nНаверное, ваш равазаврик хочет свежего мяса. Убейте несколько любых деметродонов, стегодонов и терродактилей в Кратере Ун'Горо и накормите голодного малыша.", progress = "Малыш облизывается и выжидательно смотрит на вас.", completion = "Судя по довольному урчанию, равазаврик удовлетворен количеством мяса, но невозможно предугадать, когда он снова проголодается.", rewards = "Вы получите:\n\nМолочный зуб равазавра"}
MultiLanguageQuestData['ru'][13890] = {title = "Да будет вечное пламя", objective = "Командир Мрачный Клык из Зорам'гара поручил вам залить жир гидры-тайнохлыста в огонь на маяке.", description = "Это не просто какое-то мелкое поручение, <раса>!\n\nКорабли продолжают прибывать, и если огонь на маяке так и не загорится, они потеряются в море – а то и совсем пропадут! Только тебе я могу доверить хранить путеводный свет.\n\nДля начала собери сальники гидр, обитающих в этих водах, затем принеси их в кузню и перетопи в масло.\n\nЕсли потом ты подольешь это масло в светильник маяка, у нас появится чуть больше времени, чтобы продержаться.", progress = nil, completion = "Очень хорошо, |3-6(тролль)!\n\nТеперь наши корабли не будут идти ко дну.", rewards = "Промасленные наручиСапоги приземленияНаручи тайнохлыстаВы получите:\n\nПредмет #10Предмет #1"}
MultiLanguageQuestData['ru'][13891] = {title = "Поглотитель Темных берегов", objective = "Воспользуйтесь саженцем жизненоса на берегу обмелевшего озера к югу от Рощи Древних, чтобы уничтожить Всепожирающий артефакт и его хранителя.", description = "Теперь, когда обитатели Темных берегов в безопасности, давай обратим внимание на артефакт, который ты <нашел/нашла> в озере. Я практически уверена, что он был создан руками прислужников древних богов. С этими демонами можно сражаться только силой, дающей жизнь! Вот, отнеси Саженец жизненоса на берег обмелевшего озера, что на юге отсюда. Омой его в водах озера: это должно отключить древний артефакт.\n\nНо будь <осторожен/осторожна>! Кто знает, кто охраняет этот источник зла...Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Древние манжетыДревние боевые рукавицыНезагрязнимый платокВы получите:\n\n"}
MultiLanguageQuestData['ru'][13892] = {title = "Не оставляй следов", objective = "Проникните к Мечу Властителя, воспользовавшись магией статуэтки пантеры, и проследите за служителями культа Сумеречного Молота.", description = "На юго-западе отсюда лежит тело существа, которое имеет какое-то отношение к почитаемым культом Сумеречного Молота древним богам.\n\nОн пал в битве в стародавние времена – чуть ли не от руки самих Титанов или одного из их созданий.\n\nНо сейчас к его телу проявляют особый интерес сектанты Сумеречного Молота, и я боюсь, что они затевают что-то недоброе.\n\nНадо выяснить, что они там делают и с какими целями. Вот, возьми эту статуэтку – ее магия укроет тебя от посторонних глаз, пока ты будешь собирать сведения.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13893] = {title = "Соггот и Кронн", objective = "Вернитесь к Лариену в Рощу Древних и передайте ему полученную вами информацию.", description = "Меч Властителя – это поле древней битвы, <имя>. Титаны отправили двадцать каменных великанов, чтобы одолеть Соггота, но уцелел из них только один.\n\nСкрижали гласят, что Кронн, самый большой из каменных великанов, позволил Согготу захватить его своими щупальцами... но лишь для того, чтобы добраться до головы чудовища, которую он расколол своим могучим мечом.\n\nХорошо, что Соггот погиб. У нас больше нет двадцати каменных великанов, чтобы остановить его.", progress = nil, completion = "Рассказ дворфа встревожил меня... и дал пищу для размышлений. Похоже, у нас не так уж много вариантов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13895] = {title = "Дремлющие древни", objective = "Найдите Ароса на северо-востоке от Рощи Древних на Темных берегах.", description = "Хотя на нашей стороне нет двадцати каменных великанов, чтобы сокрушить врагов, наша древняя деревянная кожа прочнее любого гранита.\n\nПосмотри по сторонам, <раса>: здесь дремлют мои братья и сестры, но рог хранителя пробудит их в час битвы.\n\nНайди хранителя чащи Ароса возле моста, что на северо-востоке.\n\nОбъясни ему всю серьезность ситуации.", progress = nil, completion = "Тело Ароса еще не успело остыть – а значит, его убийцы где-то рядом...", rewards = nil}
MultiLanguageQuestData['ru'][13896] = {title = "Раскопанное знание", objective = "Поговорите с археологом Гроффом на Раскопках Сомнамбулера.", description = "Послушай, <имя>, мы должны понять, с чем нам придется иметь дело.\n\nЯ знаю, кто может помочь разобраться в этом деле. На юго-западе отсюда, прямо под Мечом Властителя, я видела группу дворфов-археологов, которые раскапывали близлежащие руины.\n\nЧто-то мне подсказывает, что они могли наткнуться на некие знания, которые могут оказаться полезными.", progress = nil, completion = "Ну да, мы знаем кое-что о Согготе. Вопрос лишь в том, надо ли тебе это знать...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13897] = {title = "Битва за Темные берега", objective = "Убейте аватара Соггота у Меча Властителя.", description = "Древние обитатели рощи откликнулись на наш зов, <имя>. Даже сейчас я вижу мир их глазами.\n\nСлужителям культа Сумеречного Молота пришлось ускорить свои ритуалы, и потому им удалось оживить лишь бледное подобие некогда ужасного Соггота.\n\nМы должны уничтожить его, пока еще не поздно. Мое присутствие требуется в другом месте, так что возвращайся к друидам Рощи Древних, когда Соггот будет уничтожен. Они скажут тебе, что делать дальше.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Наручи Древней рощиЩит хранителя с Темных береговВы получите:\n\n"}
MultiLanguageQuestData['ru'][13898] = {title = "Волны против нас", objective = "Убейте 8 мирмидонов клана Темной Чешуи.", description = "Убийство хранителя чащи приравнивается к объявлению войны, <имя>, и наги еще поплатятся за это.\n\nНайди их логово внутри пещеры на острове Най'вел, что на юго-западе отсюда.\n\nОни должны понять, что это им не сойдет с рук.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Ветвь хранителя рощиНож для соскабливанияВам дадут возможность выбрать одну из следующих наград:\n\nПечатка Фелроса\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13899] = {title = "Владыка Черной Чешуи", objective = "Убейте Полководца Гневного Гребня в Назж'вел.", description = "Если наги действительно решили связать свою судьбу с Сумеречным Молотом... да смилуется Элуна над их душами.\n\nОтправляйся в их логово на острове Назж'вел и найди их предводителя, полководца Гневного Гребня.\n\nВозможно, рог древних все еще можно спасти.", progress = nil, completion = "У вождя не оказалось при себе рога. Возможно, он говорил вам правду?", rewards = nil}
MultiLanguageQuestData['ru'][13900] = {title = "Дар Азшаре", objective = "Не дайте жрицам клана Темной Чешуи передать Рог Древних Азшаре над Назж'вел.", description = "Полководец сказал, что рог древних будет принесен в дар Азшаре над Назж'вел.\n\nВозможно, мы успеем спасти еще одну реликвию от уничтожения.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Туфли завершителя ритуаловРемешок от древнего рогаНаручи горнистаВам дадут возможность выбрать одну из следующих наград:\n\nКольцо Тиа\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13901] = {title = "Глубокое отчаяние", objective = "Убейте 6 жриц прилива из Непроглядной Пучины.", description = "Проблема с нагами гораздо серьезнее, чем казалось на первый взгляд, <класс>, и ее не решить простым сокращением их популяции. Чтобы угомонить их, нам придется прибегнуть к более серьезным действиям.\n\nОтправляйся на северный край Зорамского взморья, где находится Непроглядная Пучина. Когда окажешься внутри, покажи нагам, кто здесь главный. Они должны понять, что мы больше не потерпим их присутствия на нашей территории!", progress = nil, completion = "Превосходно!\n\nПусть эти мерзкие наги убираются обратно в море!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13902] = {title = "В наступление!", objective = "Поговорите с Балреном-медведем в Роще Древних на Темных берегах.", description = "Нам еще многое нужно сделать на Темных Берегах прежде, чем наша миссия будет считаться законченной. Хотя мы смогли остановить разрушение земли, наши враги все еще могут в любой момент свести на ноль все усилия.\n\nЯ попрошу тебя отыскать группу друидов в Роще Древних, что на юге отсюда. Их возглавляет мой старый друг, Балрен-медведь.\n\nСкажи ему, что настал час повергнуть наших врагов. Я присоединюсь к нему, как только мы сможем стабилизировать эту местность.", progress = nil, completion = "Если тебе доверяет сам Малфурион, то и мне негоже сомневаться. Но наши враги на юге значительно превосходят нас по численности.\n\nОднако там, где не поможет грубая сила, мы будем действовать умом и хитростью.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13903] = {title = "Обед из улья Гориши", objective = "Ваш равазаврик проголодался. Принесите ему 10 кусков мяса силитида.", description = "Равазаврик испытующе смотрит на вас, после чего начинает что-то рисовать в грязи.\n\nСреди нарисованных знаков вы разбираете изображения различных больших насекомых, например, горишских силитидов. Малыш заканчивает рисунок, после чего указывает на него короткой лапой, чавкает и облизывается.\n\nОчевидно, он хочет, чтобы вы отправились в Скользкий овраг, что на юге Кратера Ун'Горо, и принесли ему мясо силитидов. Когда соберете мясо, угостите им своего равазаврика.", progress = nil, completion = "Ваш равазаврик дарит вам ослепительно клыкастую улыбку и сыто облизывается.", rewards = "Вы получите:\n\nМолочный зуб равазавра"}
MultiLanguageQuestData['ru'][13904] = {title = "Всмятку, в мешочек или сырые?", objective = "Ваш равазаврик хочет, чтобы вы принесли ему 12 яиц силитида.", description = "Равазаврик пытается привлечь ваше внимание, и вы слышите, как бурчит у него в животе. Он рисует в грязи несколько силитидов и добавляет внизу какие-то овалы, настойчиво указывая на них когтем.\n\nСомнений нет – ему нужны яйца силитидов! К счастью, вы знаете, где раздобыть лакомство для малыша – в Ядовитом улье, который находится в западном Танарисе, рядом с Кратером Ун'Горо.", progress = nil, completion = "Ваш равазаврик довольно облизывается, расправившись с яйцами силитида. Вам показалось – или он слегка разочарован тем, что еда уже кончилась?", rewards = "Вы получите:\n\nМолочный зуб равазавра"}
MultiLanguageQuestData['ru'][13905] = {title = "Перья опаляющего руха", objective = "Ваш равазаврик хочет, чтобы вы принесли ему 5 перьев опаляющего руха.", description = "Равазаврик внимательно смотрит на вас, словно сомневается, поймете ли вы его. Затем он рисует в грязи два пера и указывает когтем сначала на рисунок, а потом на свои локти и колени.\n\nОн, вроде бы, не голоден, что бы значили эти перья?\n\nНаверное, он хочет использовать их в качестве украшения, как другие ящеры. Самыми большими перьями могут похвастаться опаляющие рухи, которых легко найти вокруг останков огромных животных в западном Танарисе, к северо-востоку от Долины Кактусов.", progress = "Ваш равазаврик выжидательно смотрит на вас.", completion = "Равазаврик берет у вас перья и начинает рассматривать их, примеряя к повязкам на коленях.", rewards = "Вы получите:\n\nМолочный зуб равазавра"}
MultiLanguageQuestData['ru'][13906] = {title = "Они так быстро растут", objective = "Вернитесь к Мор'веку на юго-восток Топей в Кратер Ун'Горо со своим равазавриком, а также принесите 20 молочных зубов равазавра, 20 отрезов рунической ткани, 20 кусков грубой кожи и 80 золотых монет.", description = "При хорошем уходе равазавры быстро растут. По мере взросления молочные зубы заменятся коренными. Если ты будешь собирать все выпавшие зубы, то сможешь легко определить, когда он достаточно окрепнет для того, чтобы его можно было тренировать как верховое животное.\n\nОн сам даст тебе знать о том, что ему нужно, так что внимательно следи за ним и тщательно ухаживай за своим малышом. А когда все его молочные зубы выпадут, возвращайся ко мне со своим равазавром и всем, что нужно для его седла.", progress = "Ты хорошо заботился о своем ящере?", completion = "Похоже, вам удалось-таки провести все это время вместе, не убив друг друга. \n\nНу, хорошо, сейчас все и закончим. Я выучил твоего ящера отвечать на команды этого свистка. \n\nМало кто способен так самоотверженно растить равазаврика, кормить его из рук, но он стоит всех этих усилий.", rewards = "Вы получите:\n\nСвисток ядошкурого равазавра"}
MultiLanguageQuestData['ru'][13907] = {title = "Зачистка руин", objective = "Убейте 10 оракулов племени Серой Мглы или беженцев из племени Серой Мглы возле Раскопок Сомнамбулера.", description = "Великие бородачи из Стальгорна послали меня на раскопки Сомнамбулера, как только до них дошли слухи о случившемся несчастье. Да ты <сам/сама> посмотри! Драгоценные артефакты в одночасье смыло в море, месяцы кропотливой работы воргену под хвост! \n\nМало того, волны разрушили поселения мурлоков, которые располагались вдоль берега. Скажешь, туда им и дорога? Ага, как же! Выжившие мурлоки пытаются пробраться под защиту руин и, если честно, наносят куда больше ущерба, чем стихии. Ну чего ты ждешь – сделай что-нибудь!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13908] = {title = "Приготовьтесь к поездке", objective = "Принесите 20 кусков грубой кожи, 20 отрезов рунической ткани и 80 золотых монет Мор'веку. Он ждет вас на юго-востоке Топей в Кратере Ун'Горо", description = "Твой равазавр окреп, возмужал и сильно к тебе привязался. Пожалуй, вскоре ты сможешь ездить на нем – как только я доделаю седло и уздечку. Правда, их тоже придется укрепить, чтобы они выдержали воздействие яда равазавра.\n\nПринеси мне немного грубой кожи, рунической ткани и денег на остальные ингредиенты – и я тут же примусь за работу.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСвисток ядошкурого равазавра"}
MultiLanguageQuestData['ru'][13909] = {title = "Обломки для бездомных", objective = "Соберите 5 подлежащих восстановлению частей строений Серой Мглы на берегу и в воде возле Раскопок Сомнамбулера.", description = "Мы сможем найти выход из ситуации. Надо только немного подумать... Мы, дворфы, издавна славились своей мудростью!\n\nЗначит, так: этим мурлокам нужен новый дом, верно? Мысли созидательно, <имя>! В буквальном смысле...\n\nВо время катаклизма на берег вынесло целую кучу всякого мусора, да и некоторые хижины все еще можно восстановить. Ну-ка, пробегись по побережью и собери все подходящие материалы для строительства. Поверь, для них особо стараться не придется!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13910] = {title = "Новый дом", objective = "Постройте лачугу для мурлоков в специальном месте на западе от раскопок рассеянного геолога.", description = "Что нам стоит дом построить? Нарисовал – и будем жить! К западу от раскопок я установил на побережье наш флаг. Песок там достаточно плотный, и вполне подходит для постройки. Возьми мои инструменты и собранные материалы, и возведи этим несчастным тварям новые хижины.", progress = "Как там строятся новые бунгало на побережье?", completion = "Ха-ха, похоже, ты построил им целую деревню! И как, они купились? Отлично, отлично! Пойдем посмотрим, как воплощаются в жизнь мои планы. \n\n&lt;Археолог хмурится, глядя как толпы мурлоков стекаются в хижину со всех сторон света.&gt;\n\nЧто же я наделал?", rewards = "Поручи копателя нишШтормовка ГроффаВы получите:\n\n"}
MultiLanguageQuestData['ru'][13911] = {title = "Рассеянный геолог", objective = "Покажите геологу Сомнамбулеру, где лежит его журнал, после чего поговорите с археологом Фердом на раскопках.", description = "Как, ты говоришь, тебя зовут? <имя>? Мы знакомы? Если тебя прислали из Лиги, можешь передать им, что я никуда отсюда не уйду без моей находки! Она была уже у меня в руках... как вдруг раздались крики, и меня захлестнуло волной...\n\nСлушай, как там тебя зовут, я все записал в моем путевом журнале, и я знаю, где он сейчас лежит! Отыщем журнал – отыщем и мою находку! Или наоборот?... Иди за мной!", progress = nil, completion = "А, так это ты помог геологу Сомнамбулеру найти его пропавший журнал! Подумать только, он все время был здесь.\n\nКогда-нибудь ты должен показать мне эти вторые руины, о которых он все время рассказывает.", rewards = "Перчатки растеряшиПоножи забвенияВам дадут возможность выбрать одну из следующих наград:\n\nКольцо плохого настроения Бахрума\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13912] = {title = "Тайны болота", objective = "Найдите покрытый грязью древний диск среди ближайших руин.", description = "Кто бы мог подумать, что вечно рассеянный Сомнамбулер – на самом деле непризнанный гений! Вот уж воистину тайна, скрытая под пылью веков. Но я не собираюсь преуменьшать заслуги старика. Смотри, что мне удалось обнаружить в его записях... нет, не то... это список покупок... нашел! Вот, смотри: на этой странице он пытается определить, который сейчас год с помощью Диска!\n\nПохоже, этот артефакт Титанов представляет собой некий диск с зашифрованными надписями. Незадолго до катастрофы мы со всеми предосторожностями выкопали его из-под земли, но не успели поднять на поверхность. Если он все еще лежит там, среди руин, пожалуйста, принеси его мне!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13913] = {title = "Они забрали наших гномов!", objective = "Спасите Буга \"Моднявого\" и Минкс из фургона Бесконечной Агонии, принадлежащего мастеру пыток Тундраку.", description = "Мы вызвали из Города Механиков команду гномов-подрывников, и она прибыла на прошлой неделе. Это было весьма кстати, потому что как раз в тот день на нас напала Орда, и мы потеряли много солдат. Большую часть подрывной команды тоже увели в плен. Теперь мы по уши в Орде, приют Серебряного Ветра потерян, а впридачу к нему около десятка гномов.\n\nПрошу, помоги нам, <имя>. Пойди на восток, в приют Серебряного Ветра, и поищи, не осталось ли там выживших гномов. Их увел огромный жестокий орк по имени Тундрак. Найдешь его – найдешь и наших гномов.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13914] = {title = "Перья опаляющего руха", objective = "Ваш равазаврик хочет, чтобы вы принесли ему 5 перьев опаляющего руха.", description = "Равазаврик внимательно смотрит на вас, словно сомневается, поймете ли вы его. Затем он рисует в грязи два пера и показывает когтем сначала на рисунок, а потом на свои локти и колени.\n\nОн, вроде бы, не голоден, что бы значили эти перья?\n\nНаверное, он хочет использовать их в качестве украшения, как другие ящеры. Самыми большими перьями могут похвастаться опаляющие рухи, которых легко найти вокруг останков огромных животных в западном Танарисе, к северо-востоку от Долины Кактусов.", progress = "Ваш равазаврик выжидательно смотрит на вас.", completion = "Равазаврик берет у вас перья и начинает рассматривать их, примеряя к своим лапам.", rewards = "Вы получите:\n\nМолочный зуб равазавра"}
MultiLanguageQuestData['ru'][13915] = {title = "Бедный, голодный равазаврик", objective = "Ваш равазаврик хочет съесть 15 кусков свежего мяса динозавра.", description = "Равазаврик выжидательно смотрит на вас, после чего начинает опять что-то рисовать в грязи.\n\nКонечно, рисунки очень грубые, но вам все же удается разобрать очертания деметродонов, стегодонов и терродактилей. Когда ящер заканчивает рисунок, он ощеривает зубы и выразительно щелкает челюстью.\n\nНаверное, ваш равазаврик хочет свежего мяса. Убейте несколько любых деметродонов, стегодонов и терродактилей в Кратере Ун'Горо и накормите голодного малыша.", progress = "Малыш облизывается и выжидательно смотрит на вас.", completion = "Судя по довольному урчанию, равазаврик удовлетворен количеством мяса, но невозможно предугадать, когда он снова проголодается.", rewards = "Вы получите:\n\nМолочный зуб равазавра"}
MultiLanguageQuestData['ru'][13916] = {title = "Всмятку, в мешочек или сырые?", objective = "Ваш равазаврик хочет, чтобы вы принесли ему 12 яиц силитида.", description = "Равазаврик пытается привлечь ваше внимание, и вы слышите, как бурчит у него в животе. Он рисует в грязи несколько силитидов и добавляет внизу какие-то овалы, настойчиво указывая на них когтем.\n\nСомнений нет – ему нужны яйца силитидов! К счастью, вы знаете, где раздобыть лакомство для малыша – в Ядовитом улье, который находится в западном Танарисе, рядом с Кратером Ун'Горо.", progress = "Малыш смотрит на вас.", completion = "Ваш равазаврик довольно облизывается, расправившись с яйцами силитида. Вам показалось – или он слегка разочарован тем, что еда уже кончилась?", rewards = "Следующее заклинание будет наложено на вас:\n\nCast Venomhide Counter\n\nВы получите:\n\nМолочный зуб равазавраПредмет #12"}
MultiLanguageQuestData['ru'][13917] = {title = "Обед из улья Гориши", objective = "Ваш равазаврик проголодался. Принесите ему 10 кусков мяса силитида.", description = "Равазаврик испытующе смотрит на вас, после чего начинает что-то рисовать в грязи.\n\nСреди нарисованных знаков вы разбираете изображения различных больших насекомых, например, горишских силитидов. Малыш заканчивает рисунок, после чего указывает на него короткой лапой, чавкает и облизывается.\n\nОчевидно, он хочет, чтобы вы отправились в Скользкий овраг, что на юге Кратера Ун'Горо, и принесли ему мясо силитидов. Когда соберете мясо, угостите им своего равазаврика.", progress = "Малыш выжидательно смотрит на вас.", completion = "Ваш равазаврик дарит вам ослепительно клыкастую улыбку и сыто облизывается.", rewards = "Вы получите:\n\nМолочный зуб равазавра"}
MultiLanguageQuestData['ru'][13918] = {title = "Терминал титанов", objective = "Используйте обнаружитель затерянных артефактов на пляже возле Раскопок Сомнамбулера, чтобы найти 5 деталей артефакта. Соберите их вместе, чтобы получить древнее устройство с прорезью.", description = "Теперь, когда диск у нас в руках, многие предыдущие находки обретают новое значение. Например, вскоре после моего прибытия, геолог Сомнамбулер откопал нечто, напоминающее доисторический тостер.\n\nЯ же всегда был убежден, что это устройство предназначено для чтения данных. К несчастью, его разбило и унесло волной вместе со всем нашим лагерем во время цунами!\n\nНо он не мог уплыть далеко – наверняка обломки все еще валяются на линии прибоя. Вот, возьми мой проверенный детектор артефактов и прочеши им весь пляж.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Тарелка с бутербродами профессораВам дадут возможность выбрать одну из следующих наград:\n\nНеопознанные столовые приборы\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13919] = {title = "Путешествие к Лунному колодцу", objective = "Очистите Слезу Элуны в Лунном колодце чистоты, что в Ясеневом лесу.", description = "Ничего не вышло...\n\n<С глубокой скорбью на лице Пельтур достает Слезу из чаши и бережно омывает ее.>\n\nДолжно быть, на святыню как-то повлияло извержение Громовой вершины. Пожалуйста, отнеси Слезу к Лунному колодцу чистоты. Это единственное место, еще не затронутое скверной – его охраняет сама сила богини. Он находится на юго-востоке от подножия вулкана.\n\nОмой святыню в водах, благословленных Элуной. Я не могу знать, что будет дальше. Я боюсь за судьбу моей дочери. Теперь она в твоих руках, <имя>.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13920] = {title = "Прежде, чем уйти...", objective = "Принесите 5 стейков из оленины командиру Мрачному Клыку в форт Зорам'гар.", description = "Здесь, в Дозоре Адского Крика, не хватает таких |3-8(<класс>), как ты. Поэтому прежде, чем ты отправишься в путь, я хочу попросить тебя об одной услуге.\n\nИз-за непрекращающихся атак Альянса мы потеряли в море множество ценных товаров, в том числе провизию, необходимую для поддержания сил наших солдат, участвующих в битве за Ясеневый лес.\n\nОднако к востоку отсюда находятся богатые охотничьи угодья. Добудь для наших отрядов самое лучшее мясо, которое только сможешь найти!", progress = "Да, |3-6(тролль)?", completion = "Что это у тебя там, дружище?\n\nАх, да! Вкусная оленина – счастливый солдат!\n\nВот, возьми пару монет за труды.", rewards = "Лента хозяина мясной лавкиОхотничий жилет Дже'неуПоножи загонщика оленейВы получите:\n\n"}
MultiLanguageQuestData['ru'][13921] = {title = "Тот, кто будет прощен", objective = "Поговорите с Аврием Дурным Толком у башни в Ночных лесах, что в Ясеневом лесу.", description = "<Вы чувствуете, как в вашей голове раздается бесконечно умиротворяющий голос, исходящий откуда-то из колодца.>\n\nТы желаешь исцелить дитя, но каждое деяние, даже самое благое, должно быть оплачено. На востоке отсюда высится Башня в Ночных лесах, а рядом с ней возле моего лунного колодца бродит существо, поддавшееся скверне.\n\nАврий Дурной Толк жаждет прощения и освобождения. Даруешь ли ты ему то, о чем он просит, если это приблизит тебя к цели?", progress = nil, completion = "&lt;Сатир презрительно ухмыляется, но вскоре понимает, что вы пришли не для того, чтобы карать его, и выражение его лица меняется.&gt;\n\nБлизок час моего искупления... Как долго я ждал этого момента! Пожалуй, я знаю, как помочь тебе в этом деле.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13922] = {title = "В оскверненных руках", objective = "Добудьте 5 лунных камней Упавшего Неба.", description = "Мой бывший клан Кабарог Скверны из Ночной поляны довольно часто охотился у Зеркала Небес и собирал лунные камни, которые встречаются только в тех местах.\n\nЭти лунные камни известны своими целебными свойствами. Не сомневаюсь, они могут помочь исцелить эту бедную девочку из Астранаара.\n\nНочная поляна находится возле дороги, ведущей на север. От нее отходит множество тропинок, огибающих холмы с восточной стороны – именно там ты найдешь моих нераскаявшихся братьев. У них есть то, что тебе нужно.", progress = "Чтобы исцелить девочку, потребуются все пять лунных камней.", completion = "Теперь у тебя есть все лунные камни. Остается только принести жертву, чтобы спасти другую невинную жизнь.\n\nНо я уверяю тебя, что это поможет вылечить Релару.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13923] = {title = "На заставу Адского Крика", objective = "Поговорите с капитаном Гоггатом в дозоре Адского Крика.", description = "Вперед, в самое пекло, <раса>!\n\nЗастава Адского Крика – самый ненадежный фронт во всем Ясеневом лесу, но ты многое узнаешь, побывав там лично... если, конечно, выживешь.\n\nКак закончишь последние приготовления, поговори с Андруком. Я поручил ему отправить тебя прямо на заставу.\n\nПрибудешь на место и немедленно разыщешь капитана Гоггата. Он выдаст тебе дальнейшие инструкции.\n\nСмерть и боль нашим врагам! За Орду!", progress = nil, completion = "Ты явился сюда беспомощным как дитя, а покинешь нас закаленным в боях воителем Орды!\n\nСо щитом или на щите...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13924] = {title = "Все в порядке", objective = "Отнесите освященные лунные камни Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.", description = "Спасибо за то, что ты <спас/спасла> меня от участи хуже, чем смерть! За то, что ты <уберег/уберегла> от погибели меня и этого несчастного ребенка.\n\nТеперь дитя почти в безопасности. Осталось только отнести лунные камни назад, на запад от Астранаара. Передай их Пельтуру – он знает, что делать дальше.\n\nСтупай с миром, и да хранит тебя Элуна!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Перчатки белой луныПояс целительных чарСапоги разносчикаВы получите:\n\n"}
MultiLanguageQuestData['ru'][13925] = {title = "Подстелить соломку", objective = "Испытайте саженец жизненоса на любом здоровом седом колючешерстном медведе, белохвостом олене, лунопарде-матриархе или патриархе.", description = "А ты никак <слышал/слышала> про Древних богов, <имя>? Мы с Ону единогласны во мнении, что найденный тобой артефакт мог быть изготовлен только ими, и теперь он поглощает Темные Берега. Что-то пробудило кошмары, которые мы считали давно позабытыми. Это неподвластно тебе и мне... но я хочу хотя бы сохранить природу от воздействия зла.\n\nВ этом побеге заключена энергия жизни, которую ты мне <принес/принесла>. Хочется верить, что она защитит местных обитателей. Испытай ее на любом медведе, олене или лунопарде, не затронутом порчей, и дай мне знать, что случится!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13926] = {title = "Ру, оракул-сиротка", objective = "Поговорите с попечительницей сирот Арией; после этого воспользуйтесь детской свистулькой оракула, чтобы позвать сиротку, о котором вы будете заботиться во время Детской недели.", description = "Дети будут очень рады такому другу, как вы, <имя>. Как замечательно, что вы станете опекать одного из них!\n\nВозьмите эту свистульку, с ее помощью вы сможете позвать своего воспитанника. Свистулька не прослужит долго, но на Детскую неделю должно хватить.\n\nПозовите сиротку, <имя>! Он будет очень рад познакомиться с вами и попутешествовать по Нордсколу.", progress = "Ты заботиться о нас?", completion = "Ты уведешь нас подальше от остальных детенышей? Хорошо. Тогда ты нам нравишься. Злые детеныши людей-собак отнимают наши игрушки.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13927] = {title = "Кекек, волчер-сиротка", objective = "Поговорите с попечительницей сирот Арией, после этого воспользуйтесь детской свистулькой волчера, чтобы позвать сиротку, о котором вы будете заботиться во время Детской недели.", description = "Дети будут очень рады такому другу, как вы, <имя>. Как замечательно, что вы станете опекать одного из них!\n\nВозьмите эту свистульку, с ее помощью вы сможете позвать своего воспитанника. Свистулька не прослужит долго, но на Детскую неделю должно хватить.\n\nПозовите сиротку, <имя>! Он будет очень рад познакомиться с вами и попутешествовать по Нордсколу.", progress = "Госпожа попечительница сказала Кекеку идти с тобой.", completion = "Ты отведешь Кекека на охоту? Хорошо бы отправиться подальше от этой старой злой попечительницы, которая не дает Кекеку охотиться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13928] = {title = "Тела павших", objective = "Соберите 10 трупов смеющихся сестер Халаннии.", description = "Хранитель Ордан поручил мне и моим часовым охранять башню. Пока нам удавалось сдерживать атаки Орды, но теперь их войска заходят с севера, чтобы напрямую напасть на крепость.\n\nХранитель отправил дриад на защиту дерева, но что они могут сделать против авангарда орков Песни Войны?\n\nПрошу тебя, отправляйся туда и принеси как можно больше тел павших сестер. Их надо отнести Халаннии в Приют. Она сможет им помочь.", progress = "Я просто потрясена тем, как тебе удалось прорваться сюда, сквозь строй ордынских воинов.", completion = "Спасибо, |3-6(Разбойник). Мы бросили все силы на защиту Приюта, но как только у меня появится свободная минутка, я воскрешу павших сестер силой богини.\n\nДоблестный |3-6(Разбойник), можешь ли ты оказать нам помощь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13929] = {title = "Самое большое дерево!", objective = "Отведите вашего подопечного Ру к Седой Пасти. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.", description = "Мы помним, что еще перед большой войной Су-сэй рассказывал нам о большом-пребольшом дереве!\n\nСу-сэй, кажется, называл его Седой Пастью, и оно в центре Серых холмов. Нет, неправильно, он говорил иначе! Мы вспомнили! Большое дерево растет прямо посреди Седых холмов! Такое не пропустишь!\n\nТы отведешь нас туда, да? И мы заберемся прямо внутрь? Су-сэй говорил, там живут большие люди-медведи. Может нам удастся их увидеть.", progress = nil, completion = "Мы никогда не думали, что деревья бывают такими большими! Может быть, Великие специально сделали их такими?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13930] = {title = "Дом людей-медведей", objective = "Отведите вашего подопечного Кекека к Седой Пасти. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.", description = "Верховный шаман Ракжак всегда рассказывал истории о великих воинах прошлого. Как-то он поведал об огромных людях-медведях, которые сражались за великий город-дерево.\n\nКекек хочет посмотреть на то дерево и место битвы! Верховный шаман Ракжак сказал Кекеку, что город-дерево называется Седая Пасть и находится в самом центре Седых холмов.\n\nКекек никогда раньше не видел городов до того, как встретился с попечительницей сирот, но в этом городе нет воинов – только мужчины в фиолетовых одеждах. Кекек хочет увидеть настоящих героев, которые сражаются за свой город!", progress = nil, completion = "Вот такой город очень нравится Кекеку. Эти люди-медведи сражаются так же отважно, как и племя Бешеного Сердца. Госпожа попечительница не разрешает Кекеку драться, но он все равно станет воином!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13931] = {title = "Новый подарок к новому году", objective = "Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.", description = "Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.\n\nПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.", progress = "Что такое, красавчик? Ты ко мне по делу?", completion = "Что это? Купон на кружку? Любишь выпить? Отлично! Я дам тебе кружку, а ты пойди и выпей за мое здоровье! А потом еще немного выпей... А потом возвращайся сюда.\n\nВсе пути ведут ко мне, знаешь ли. Тебе придется отоваривать праздничные билеты, штампы защитника бочек и так далее.\n\nКороче, вот кружка. Приходи, еще поболтаем.", rewards = "Вы получите:\n\nЗеленая кружка Хмельного фестиваля"}
MultiLanguageQuestData['ru'][13932] = {title = "Новый подарок к новому году", objective = "Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.", description = "Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.\n\nВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.", progress = "Что такое, красавчик? Ты ко мне по делу?", completion = "Аххх, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.\n\nЧао, увидимся. Ты ведь захочешь отоварить и другие праздничные купоны... Помни, я вся твоя...\n\nИли его... \n\nМожет, его...", rewards = "Вы получите:\n\nЗеленая кружка Хмельного фестиваля"}
MultiLanguageQuestData['ru'][13933] = {title = "Святилище бронзовых драконов", objective = "Отведите вашего подопечного Ру к Бронзовому святилищу драконов. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.", description = "Иногда верховный оракул Су-сэй рассказывает истории о великой святыне драконов – не такой, конечно, как Великий камень дождя, а совсем другой. Су-сэй говорит, что мы можем увидеть в ней себя – точнее, какими мы будем через много лет.\n\nОтведешь нас туда? Мы помним, что это святилище бронзовых драконов, которое находится в Драконьем Погосте. Су-сэй говорит, что Великий камень дождя показал ему святилище на северо-востоке от Храма Драконьего Покоя или на северо-западе от места, которое сухокожие зовут Крепостью Стражей Зимы. Идем?", progress = nil, completion = "Мы очень рады, что ты привел нас сюда, Модерам. Мы волновались, что случится с нами в будущем с тех пор, как попечительница нашла нас в Шолазаре.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13934] = {title = "Святилище бронзовых драконов", objective = "Отведите вашего подопечного Кекека к Бронзовому святилищу драконов. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.", description = "Когда Кекек был щенком, он слышал, как старейшины рассказывали об одном далеком святилище. Они говорили, что род бронзовых драконов, который его оберегает, может видеть будущее.\n\nКекек станет великим воином! Пойдем, посмотрим каким вырастет Кекек. Святилище бронзовых драконов находится где-то на Драконьем Погосте, на северо-восток от храма Драконьего Покоя и на северо-запад от Крепости Стражей Зимы.\n\nПойдем, увидим будущее. Плохо, что попечительница ругает Кекека. Кекек воин, а не забияка.", progress = nil, completion = "Вот видишь? Кекек был прав. Кекек всегда прав.\n\nМожет быть, теперь ты будешь слушать Кекека, даже если он говорит, что небо зеленое.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13935] = {title = "Защитить древо!", objective = "Поговорите с Халаннией, чтобы призвать тень Тенумбры, и воспользуйтесь ее силой, чтобы уничтожить 50 врагов из клана Песни Войны в приюте в Ночных Лесах.", description = "Мы использовали силу сердца леса для защиты древа от Орды, но его возможности не безграничны. Теперь мы воспользуемся святыней, чтобы дать врагам отпор!\n\nЗдесь неподалеку охотится Тенумбра, великая хищница леса. В ее силе и ловкости мы должны черпать вдохновение. Ты станешь <един/едина> с ее тенью, впитаешь в себя дух пантеры и уничтожишь тех, кто посягает на величие Ясеневого леса!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Щит Ночных ЛесовГнев ТенумбрыАрбалет ледяной тениСледующее заклинание будет наложено на вас:\n\nDefend the Tree!: Quest Completion - Exit Shade of Shadumbra\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13936] = {title = "Болван Шкрып", objective = "Капитан Гоггат просит вас поговорить с Шкрыпом в Дозоре Адского Крика.", description = "Задержки, опять задержки! Сил моих не хватает!\n\nМне сказали, что этот гоблин просто гений – мол, он изобретет такое устройство, которое с превратит в пыль наших врагов, но пока что он нас только завтраками кормит! Если он еще раз явится с пустыми руками, клянусь, сброшу его обрыва! \n\nИди поговори с ним, <класс>. Скажи ему, что мое терпение на исходе.", progress = nil, completion = "Я тебе вот что скажу, |3-6(Разбойник): начальник наш ничего не понимает в тонком искусстве изготовления превосходных бомб!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13937] = {title = "Поездка в \"Чудо чудное\".", objective = "Купите бумажный дирижаблик в магазине \"Чудо чудное\" и бросьте его вашему подопечному Ру.", description = "А у нас есть еще минутка? Мы слышали, что в Даларане есть магазин игрушек, но никогда там не были. Госпожа попечительница говорит, что сирот слишком много, и мы будем мешать покупателям. Может быть, мы могли бы заглянуть туда вдвоем?\n\nА еще мы всегда хотели бумажный дирижаблик. Как ты думаешь, они продаются в \"Чуде чудном\"? Это наша мечта... Может быть, ты подаришь нам его?", progress = "Мы идем в \"Чудо чудное\"?", completion = "Это было здорово! Нам понравился магазин игрушек. Может быть, попечительница приведет нас сюда еще раз? Мы ее попросим. И ты ее попроси, пожалуйста!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13938] = {title = "Заглянем в \"Чудо чудное\".", objective = "Купите бумажный дирижаблик в магазине \"Чудо чудное\" и бросьте его вашему подопечному Кекеку.", description = "Может Кекек тебя еще кое о чем попросить? Попечительница рассказывала, что в Даларане есть магазин игрушек \"Чудо чудное\", но Кекека туда не пускают. Говорят, если Кекек туда пойдет, придется отвести и всех остальных сирот. Но Кекек очень хочет попасть в магазин!\n\nКекек видел, как другие дети играют с бумажными дирижабликами. Говорят, их продают в \"Чуде чудном\". Ты запустишь такой дирижаблик, чтобы он летал вокруг Кекека?", progress = nil, completion = "Кекеку нравится играть с бумажным дирижабликом. Конечно, охота гораздо веселее, но теперь Кекеку будет, чем заняться в приюте.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13940] = {title = "Пробуждение ото Сна", objective = "Поговорите с Малфурионом Яростю Бури в Оке Урагана.", description = "Держись крепче, <имя>. Дорога в мир бодрствующих может оказаться тяжелой для твоего неподготовленного разума и тела.", progress = nil, completion = "Ты как раз вовремя, Авелфорт. Не знаю, сколько еще мы смогли бы продержаться.", rewards = "Следующее заклинание будет наложено на вас:\n\nEye of the Vortex - Detect Quest Invisibility 4\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13942] = {title = "Бомба на взводе", objective = "Шкрып просит вас собрать 10 образцов омытой лунным светом глины.", description = "Да я уже почти воплотил в жизнь мое великое изобретение!\n\nВот, видишь эти взрывчатые вещества? Их вполне достаточно для изготовления мега-бомбы, о которой мечтает Гоггат – осталось только собрать все части воедино.\n\nМне не хватает лишь глины, да не простой, а омытой лунным светом.\n\nТолько она сможет раскрыть весь потенциал моего изобретения. А собрать ее можно на северных берегах Астранаарского озера.", progress = "Ну-ка, посмотрим, что ты мне принес, |3-6(тролль).", completion = "Это же превосходно!\n\nПодожди, не убегай, я хочу показать тебе, что можно с этим сделать...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13943] = {title = "Превентивный удар", objective = "Капитан Гоггат хочет, чтобы вы убили 10 застрельщиков Астранаара и 3 офицеров Астранаара.", description = "Наши войска еще не готовы осадить Астранаар, <класс>. Однако наши враги знают о скором нападении и не сидят на месте. Они разбили лагерь у подножия скалы и намереваются напасть на нас при свете луны.\n\nЯ хочу, чтобы ты <вышиб/вышибла> эти мысли у них из головы – можно вместе с мозгами. Возвращайся, когда утихомиришь этих остроухих.", progress = nil, completion = "Очень хорошо, |3-6(тролль). Увы, но это – капля в море по сравнению с тем, что еще предстоит сделать.", rewards = "Плащ готовностиНаручи униженияФундаментальный щитВы получите:\n\n"}
MultiLanguageQuestData['ru'][13944] = {title = "Малый рост, короткий запал", objective = "Взорвите сломанный фургон в Дозоре Адского Крика с помощью импровизированной взрывчатки.", description = "<Шкрып оживленно размахивает руками.>\n\nВсе готово! Теперь даже Гоггат не сможет ни к чему придраться!\n\nНадо только устроить ему достойную демонстрацию нашего изобретения... знаю!\n\nМы подорвем старую телегу – все равно босс хотел избавиться от этой рухляди. Вот, бери мою взрывчатку. Посмотрим, как теперь запоет капитан!", progress = nil, completion = "Значит, Шкрып все-таки сделал что-то стоящее?\n\nСамое время…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13945] = {title = "Опасность обители", objective = "Убейте 20 фурболгов Кривой Сосны внутри и вокруг обители Бен'этиль.", description = "Агрессия племени Кривой Сосны связывает нам руки. Никто из наших не горит желанием взять на себя ответственность и выступить против существ, которые некогда были нашими друзьями, но я все больше опасаюсь того, что они планируют вскоре захватить Доланаар.\n\nБольше всего меня беспокоят фурболги в лощине Бен'этиль и обители Бен'этиль. Я хочу, чтобы ты <отправился/отправилась> на запад, <добрался/добралась> до обители и <убил/убила> так много фурболгов Кривой Сосны, как только сможешь. Может быть, у нас больше не будет возможностей уменьшить их силы, поэтому действуй без промедлений.", progress = nil, completion = "Впечатляет. Надеюсь, моя охотница справилась со своей ношей. Главное, что вы оба живы, так что мне не на что жаловаться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13946] = {title = "Возмездие природы", objective = "Используйте семена гневоплода, чтобы убить 12 греллей в Пещере Бесов.", description = "Я рада, что ты <решил/решила> исправить свою ошибку – это говорит много хорошего о твоем характере.\n\nУ меня есть для тебя еще одно задание. Я собрала несколько семян гневоплода. Они похожи на шишки Скверны, но гораздо более мощные. Природа часто очень негативно реагирует на демонов, и эти семена гневоплода являют собой яркий пример такой реакции.\n\nК северу отсюда, в Пещере Бесов находятся грелли в огромном количестве. Используй эти семена гневоплода, чтобы избавиться от них, пока они не стали совсем серьезной угрозой.", progress = nil, completion = "Хорошо. Я знаю, это была не очень приятная работа, но мы очень ценим, что ты ее выполнил.\n\nЯ боюсь за наш любимый Тельдрассил… Кажется, что с каждым днем появляется все больше порчи.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13947] = {title = "Адстранаар!", objective = "Капитан Гоггат просит вас убить 20 часовых Астранаара и 10 метателей из Астранаара с помощью импровизированной взрывчатки Шкрыпа.", description = "Так значит Шкрып все-таки изобрел хорошую взрывчатку?\n\nКак нельзя вовремя. Пока мы тут прохлаждаемся, эльфы Астранаара готовят атаку на наш лагерь.\n\nНо мы сбросим на них наши бомбы с воздуха! Гибель Астранаара станет величайшей трагедией для всех ночных эльфов.\n\nКак только завершишь последние приготовления, поговори с Тракой. И пусть рука твоя будет твердой, <класс>.", progress = "Астранаар в огне!\n\nСлава Орде!", completion = "Твои деяния будут навеки вписаны в историю Орды.\n\nСегодня мы нанесли сокрушительный удар врагу!", rewards = "Молот упреждающего удараПосох яркой судьбыПоножи Адского КрикаСледующее заклинание будет наложено на вас:\n\nSee Invis Quest Aura\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13948] = {title = "В дозор", objective = "Проникните к Мечу Властителя, воспользовавшись магией статуэтки пантеры, и проследите за предводителями культа Сумеречного Молота.", description = "Похоже, служители культа откапывают останки существа, известного как Соггот Скользящий.\n\nНаверное, их надзиратели, что стоят на вершине платформ, знают больше о том, зачем это делается.", progress = nil, completion = "Какой ужас, Тихийпутя! Если твоя информация верна, мы должны действовать незамедлительно.\n\nНельзя допустить, чтобы этот \"Соггот\" вернулся в мир живых.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13949] = {title = "Эскорт караванов до Перекрестка", objective = "Поговорите с Халгой Кровавый Глаз на Дальней Заставе о сопровождении каравана Перекрестка до фермы Гроль'дома.", description = "<Халга обезоруживающе улыбается, держа в руках огромное ружье.>\n\nТы когда-нибудь раньше <пользовался/пользовалась> такими, <имя>? Это зверь! Переносной ад! На своих двоих его, конечно, далеко не утащишь, но нет оружия лучше для сопровождения караванов. Я называю его автоматическим дробовиком. \n\nНужно доставить добытые тобой припасы в Перекресток, и без проблем по дороге нам не обойтись. Я хочу, чтобы ты <обеспечил/обеспечила> нам охрану. Без шуток. Скажи, когда будешь <готов/готова> – я отправлю тебя с ближайшим караваном.", progress = "Мок-ра, чужеземец. Ты держишь путь с Дальней заставы?", completion = "Ты – бальзам для моих глаз, |3-6(тролль). Это первый караван, которому за последнюю неделю удалось добраться сюда в целости и сохранности.", rewards = "Пояс Кровавого ГлазаЖилет КраналаПерчатки сопровождения каравановВы получите:\n\n"}
MultiLanguageQuestData['ru'][13950] = {title = "Друзья детства!", objective = "Отведите вашего подопечного Ру к Приюту Зимних Плавников. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.", description = "Знаешь, в сиротском приюте так одиноко... Иногда нам хочется увидеть другие края, встретить новых друзей.\n\nМожет быть, ты отведешь нас туда, где живут другие детеныши? Мы слышали про такое место – Приют Зимних Плавников, которое находится в огромной Борейской тундре. Мы думаем, оно может находиться на границе с островом Хладарра.\n\nГоспожа попечительница говорит, что кто-то смелый спас выводок детенышей в этом месте. Наверное, им теперь тоже одиноко, и им нужны друзья. Ты отведешь нас туда?", progress = nil, completion = "Это было весело! А мы еще сюда вернемся? Мы хотим еще раз встретиться с друзьями!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13951] = {title = "Друзья детства!", objective = "Отведите вашего подопечного Кекека на Поляну Снегопада. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.", description = "Кекеку грустно – в приюте слишком мало других щенят. Может быть, ты сводишь Кекека в гости?\n\nКекек знает племя, которое живет на Поляне Снегопада в Драконьем Погосте. Ты знаешь, где это? На севере от города людей-моржей в Гавани Моа'ки и южнее Рубинового святилища драконов.\n\n<Кекек презрительно морщится при упоминании клыкарров.>\n\nОтведи туда Кекека. Может быть, Кекек встретит других волчеров и покажет им силу Бешеного Сердца!", progress = nil, completion = "Кекеку понравились новые друзья. Кекек хочет еще как-нибудь встретиться с ними и поохотиться. Может быть, Кекек даже вместе с ними пойдет дразнить людей-моржей.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13952] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу человека на кладбище Штормграда.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестаралась... и съела все, что они приготовили для меня! Даже крошки подмела!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я была бы очень благодарна!\n\nКажется, рецепт можно купить у Чепмана.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМрачная марионетка"}
MultiLanguageQuestData['ru'][13953] = {title = "Наги среди нас", objective = "Вернитесь к Балрену-медведю в Рощу Древних в Темные берега.", description = "Похоже, череп этого существа был расколот в битве с Аросом, и внешне оно точно подходит под описание наги. \n\nГоворят, что несмотря на свой чудовищный облик, наги некогда были ночными эльфами, попавшими под власть тайной магии королевы Азшары.\n\nКажется, именно они пытаются помешать вам заполучить рог древних.", progress = nil, completion = "Значит, наги объединились с культом Сумеречного Молота? Отлично, это то, что надо...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13954] = {title = "Королева драконов", objective = "Отведите вашего подопечного Ру познакомиться с Алекстразой Связующей Жизнь, которая обитает на вершине храма Драконьего Покоя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.", description = "Верховный оракул Су-сэй говорил, что Великие создали всех драконов, и даже их королеву. Мы хотим ее увидеть! Ты отведешь нас на вершину Храма Драконьего Покоя? Мы помним, что Су-сэй рассказывал про храм – он в самом центре Драконьего Погоста.\n\nМы очень-очень хотим увидеть королеву драконов! Наверное, она очень большая и красивая. Может быть, она поможет нам найти новых родителей.\n\nПойдем?", progress = nil, completion = "Как ты думаешь, она раньше видела оракула? Может быть, она тоже встретилась с нами впервые? Кажется, мы ей понравились, но мы не уверены. Она такая молчаливая. Но это все равно было здорово!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13955] = {title = "Королева драконов", objective = "Отведите вашего подопечного Кекека познакомиться с Алекстразой Хранительницей Жизни, на вершину храма Драконьего Покоя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.", description = "Кекеку всегда нравились драконы. Кекек даже хотел превратиться в дракона, но госпожа попечительница не разрешила. Но она сказала, что ты можешь отвести Кекека познакомиться с королевой драконов.\n\nКекек думает, что госпожа попечительница наконец-то предложила что-то хорошее. Ты отведешь Кекека в Храм Драконьего Покоя, в центре Драконьего Погоста? Давай встретимся с королевой драконов! Наверное, она очень большая, раз живет на самой вершине! Кекеку не терпится познакомиться с ней!", progress = nil, completion = "Кекек ожидал, что королева будет выглядеть иначе, но Кекек понимает, почему она такая. Если бы королева всегда была большим драконом, она бы раздавила посетителей! Но Кекек все равно хочет посмотреть на нее еще раз.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13956] = {title = "Встреча с Великим", objective = "Отведите вашего подопечного Ру к Этимидиану на Террасу Создателя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.", description = "Верховный оракул Су-сэй всегда рассказывал нам про то, какие святилища строили Великие, и как мы дарили им блестяшки, но он сам никогда не видел Великих. Никто их не видел – но, может, ты знаешь, где их искать?\n\nСу-сэй говорит, что Великие построили врата и поставили их в центре южной части Шолазара. Су-сэй не знает, куда они ведут, но может быть, там мы найдем Великих! Отведи нас к вратам, <имя>, мы должны это выяснить!", progress = nil, completion = "Мы увидели Великого! Жаль, что он спал, но мы тоже любим вздремнуть! Вот бы узнать о снах, которые видят Великие – а не только о блестяшках и святилищах...\n\nА мы сможем еще навестить его, когда он не будет отдыхать?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13957] = {title = "Великий Хеминг Эрнестуэй", objective = "Отведите вашего подопечного Кекека познакомиться с Хемингом Эрнестуэем в Лагерь Эрнестуэя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.", description = "Знаешь, с кем Кекек всегда мечтал познакомиться? С Хемингом Эрнестуэем, про которого рассказывал Старейшина Харкек. Говорят, он странствует по Шолазару и охотится на огромных зверей! Даже старейшины племени Бешеного Сердца почитают Хеминга Эрнестуэя как великого охотника.\n\nСтарейшина Харкек сказал Кекеку, что Лагерь Эрнестуэя находится в центре западной части Шолазара, на берегу реки, которая называется Разлом Морского Потока. Своди Кекека туда, чтобы он спросил у Хеминга, как стать таким великим охотником!", progress = nil, completion = "Ты поможешь Кекеку прочитать книгу? Тогда Кекек сможет охотиться вместе с Хемингом Эрнестуэем!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13958] = {title = "Состояние критическое!", objective = "Гоггат поручил вам отнести боевой перевязочный набор Таггу в приют в Ночных Лесах.\n\nПрилагается предмет: \n", description = "Враги отступают, и победа уже близка!\n\nОднако не стоит праздновать заранее, <класс>. Еще многое предстоит сделать до того, как Орда окончательно заявит свои права на Ясеневый лес.\n\nЯ слышал, что возле Приюта в Ночных Лесах снова идут бои, и ордынцы несут тяжелые потери. Судя по донесениям, среди них много раненых.\n\nОтнеси туда эти лекарственные препараты и передай Таггу. Расскажи ему о нашем нападении на Астранаар. Возможно, эта новость поднимет боевой дух наших воинов.", progress = nil, completion = "&lt;Тагг внимательно слушает ваш доклад о нападении на Астранаар.&gt;\n\nИ впрямь, это радостное известие, |3-6(тролль). Увы, нам сейчас не поможешь хорошими новостями.\n\nА вот эти лекарства очень даже пригодятся!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13959] = {title = "Возвращение в приют", objective = "Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку оракула попечительнице сирот Арии.", description = "Нам было весело с тобой, <имя>. Жаль, что ты не можешь стать <нашим папочкой/нашей мамочкой>, и нам пора возвращаться к попечительнице сирот Арии в Даларан.\n\nМожет быть, ты еще навестишь нас как-нибудь? Нам очень понравилось общаться с малышами Зимних Плавников и с королевой драконов. И никто нам не поверит, что мы видели одного из Великих!\n\nМы будем скучать по тебе, <имя>. Обещаем, мы будем тебе писать!", progress = nil, completion = "Похоже, малыш Ру отлично провел время на этой неделе. Я знаю, ему одиноко в нашем приюте, и мне всегда хотелось, чтобы он завел новых друзей. Спасибо, что согласились присмотреть за ним.", rewards = "Вы получите:\n\nЛюбопытный маленький оракул\n\nПо почте вы получите: Любопытный маленький оракул"}
MultiLanguageQuestData['ru'][13960] = {title = "Возвращение в приют", objective = "Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку волчера попечительнице сирот Арии.", description = "Знаешь, а мы не так уж и плохо провели время вместе, <имя>. Ты <показал/показала> Кекеку много всяких интересных мест. Кекек нашел новых друзей и сделал много всего такого, что не снилось другим щенкам.\n\nТеперь мы друзья – Кекек, ты, Хеминг Эрнестуэй и щенки Поляны Снегопада. Может быть, ты когда-нибудь принесешь Кекеку книгу про зеленые холмы? А Кекек обещает написать тебе как-нибудь и рассказать, как идут дела. Может быть, Кекек даже не будет больше дразнить длинноязыких детей.\n\nА теперь Кекеку пора возвращаться к попечительнице Арии, в фиолетовый город людей.", progress = nil, completion = "Спасибо, что ты согласился присмотреть за Кекеком. Знаю, он может доставить много хлопот, но все, что надо этому малышу, – это немного внимания и новые друзья. Не сомневаюсь, он еще долгое время будет рассказывать истории о ваших приключениях.", rewards = "Вы получите:\n\nЛюбопытный маленький волчер\n\nПо почте вы получите: Любопытный маленький волчер"}
MultiLanguageQuestData['ru'][13961] = {title = "Допросить их", objective = "Используйте сеть Гроль'дома для поимки погромщика из племени Иглогривых и притащите его Тогрику на ферму Гроль'дома.", description = "Следуя инстинкту, мы должны были бы разорвать нападающих на куски, но мудрость подсказывает иное. Нам необходимо допросить одного из этих погромщиков свинобразов и узнать все, что можно. Возьми эту сеть, <имя>, и поймай ею одного из них. Они атакуют нашу ферму с запада. Оглуши его и принеси сюда.", progress = "Не переусердствуй, допрашивая нашего пленника – для того, чтобы отвечать на вопросы, ему определенно нужна голова.", completion = "Ох. Мы же хотим допросить этого свинобраза, а не сделать из него свиные отбивные!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13962] = {title = "Безвыходное положение", objective = "Тагг из приюта в Ночных Лесах просит вас убить хранителя Ордануса.", description = "Хотя боевые перевязочные наборы помогут нам продолжать сражаться, мы все еще находимся в безвыходном положении.\n\nДриад легко победить, но их предводитель воскрешает павших воинов, едва их тела коснутся земли. Нам приходится сражаться с бесконечным потоком этих вредителей!\n\nСам Хранитель Одан прячется вот в том мутировавшем древе. Сколько мы ни пытались пробиться к нему, все впустую. Может быть, тебе удастся добраться до этого шамана, пока мы будем расчищать тебе путь от дриад?\n\nДля покорителя Астранаара это должно быть легкой прогулкой.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13963] = {title = "Всеми правдами и неправдами", objective = "Допросите пленника из племени Иглогривых. Если он без сознания, Тогрик может привести его в чувство.", description = "Думаю, если плеснуть ему в лицо ледяной водой, он придет в себя. Как ты думаешь, что он может рассказать нам?\n\nЯ запру его в загоне для животных, что находится сзади. Не думаю, что он будет долго оставаться в сознании. Узнай все, что сможешь о том, почему свинобразы нападают на наши фермы! Методы проведения допроса можешь выбирать самостоятельно.", progress = nil, completion = "Очень интересно. Похоже, наш приятель одновременно и преклоняется перед кем-то по имени Мучеклык, и до смерти боится его. Могущественный лидер может вдохновить своих солдат как на великие, так и на ужасные поступки… нам, оркам, это известно как нельзя лучше.\n\nНадо обратить внимание на этого Мучеклыка.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13964] = {title = "К башне Звездной Пыли", objective = "Поговорите с часовой Веленой Звездный Всполох в Башне Звездной Пыли.", description = "Приют Серебряного Ветра пал! Увы, я не знаю, как это произошло – говорят, что ордынцы напали внезапно, и каким-то образом обратили на свою сторону элементалей-охранников озера Мистраль.\n\nВыжившие отступили в Башню Звездной Пыли, и им срочно нужна твоя помощь!\n\nТвой путь лежит на юго-юго-восток, к башне, которая возвышается у начала тропы Когтя, ведущей в Когтистые горы. Не сомневаюсь, часовой Велена Звездный Всполох уже готовит ответную атаку.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13965] = {title = "Весточка от Эдьюнов", objective = "Поговорите с Бенджари Эдьюном в доме Эдьюнов, что в Ясеневом лесу.", description = "<имя>, если у тебя есть свободная минутка, я бы хотел попросить тебя о небольшой услуге.\n\nДавненько я не получал весточки от своих друзей, семьи Эдьюнов. Может быть, ты сбегаешь к ним и узнаешь, как они поживают?\n\nВечная благодарность тебе обеспечена. Их дом находится на маленьком островке земли к западу от святилища Эссины.", progress = nil, completion = "Говоришь, тебя послал Фалдреас? Хороший он человек.\n\nНам и впрямь пригодится помощь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13966] = {title = "Подарок к Зимнему Покрову", objective = "На маленьком ярлычке написано:\n\nС правздниками, Машинатом!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПодарок к Зимнему Покрову"}
MultiLanguageQuestData['ru'][13967] = {title = "Проредить... стадо?", objective = "Сенани Громовое Сердце в приюте Серебряного Ветра просит вас принести Таркану 15 ушей фурболгов – тотемистов из племени Гиблой Чащи и ведмедей из племени Гиблой Чащи.", description = "В южных районах численность фурболгов превышает все наши расчеты. К тому же, они гораздо более агрессивны, чем ожидалось.\n\nУчитывая, что мы разрываемся между охотой на эльфов и добычей бесценной древесины, только ты можешь помочь нам сократить популяцию фурболгов.\n\nПока что я занимаюсь теоретическими расчетами, но вскоре ты понадобишься мне для проведения экспериментов. А пока что займись нашей мохнатой проблемой и принеси Таркану уши фурболгов в доказательство ее решения.", progress = "Итак, Зябкин... Дело сделано?", completion = "Отлично, |3-6(Друид).\n\nТеперь какое-то время они будут зализывать свои раны.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13968] = {title = "Уничтожение Мучеклыка", objective = "Уничтожьте Мучеклыка, предводителя Иглогривых.", description = "Кажется, в результате волнений на юге этот \"Мучеклык\" собрал под своими знаменами всех беженцев племени Иглогривых. Под его руководством они стали несколько опаснее обычных разбойников. С такими типами не дискутируют, его надо уничтожить и точка.\n\nЕсли наш пленник не врет, ты найдешь Мучеклыка к юго-востоку отсюда в месте, которое называется Тернистым холмом. Исследуй те утесы, откуда ему лучше всего видна дорога. Убей его, <имя>, и угроза минует.", progress = nil, completion = "Что, Мучеклык вел себя так, как я и предсказывала? Сразу попытался перерезать тебе глотку? Хорошо, что он уже покойник.\n\nСвинобраза из племени Иглогривых отстранили от руководства в Южных Степях, не хватало еще, чтобы твари типа него были у власти. Может быть, теперь у нас появится возможность договориться с выжившими... Хотя эти горячие головы могут одержать верх.", rewards = "Жезл разделенияБашмаки охотника на кабановНабедренники ТогрикВы получите:\n\n"}
MultiLanguageQuestData['ru'][13969] = {title = "Пропавший кодо Гроль'дома", objective = "Найдите пропавшего кодо Гроль'дома где-то на Тернистом холме.", description = "<Друг/Подруга>, если ты путешествуешь на юг, к Тернистому Холму, то, может быть, сможешь и поискать одного из наших пропавших кодо? Не каждый караван доходит до Дальней заставы. Эти головорезы Иглогривые угнали нагруженного кодо прошлым утром. Возможно, они уже убили его, но я надеюсь, что нет – наши стойла и без того опустели.", progress = nil, completion = "Этот несчастный искалеченный кодо находится на краю гибели. Иглогривые даже не успели разгрузить его. Если его получится привести в чувство, вам, скорее всего, удастся спасти и товары.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13970] = {title = "Животноводство", objective = "Соберите 5 мешков украденного зерна в лагерях Иглогривых на Тернистом холме.", description = "Кодо – выносливые создания. Немного еды, и этот великан придет в себя.\n\nИглогривые ограбили немало караванов, и, должно быть, награбили огромное количество зерна. Мешки с украденным зерном можно найти в их лагерях.", progress = "Животное не может поднять голову, однако с мольбой смотрит на вас большими влажными глазами.", completion = "Кодо очень прожорлив! С таким же успехом ты мог бы высыпать зерно из этих мешков в пропасть!\n\nЖивотное оживает на глазах.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13971] = {title = "Возвращение кодо", objective = "Поговорите с Краналом Фиссом с фермы Гроль'дома, чтобы быть <уверенным/уверенной>, что пропавший кодо благополучно прибыл.", description = "Огромное животное медленно поднимается, стряхивает грязь и пыль степей со своих вновь мощных лап и, повинуясь инстинкту, медленно направляется в сторону фермы Гроль'дома.\n\nТебе стоит поговорить с Краналом Фиссом и убедиться, что кодо успешно добрался до фермы.", progress = nil, completion = "Так значит это была твоя работа, |3-6(тролль)? Да, пропавший кодо добрался несколько минут назад. Пройдет еще много дней, пока раны бедного животного заживут, но благодаря тебе он по крайней мере жив. К тому же, ты спас весь груз!\n\nПожалуйста, возьми часть того, что нес кодо, себе.", rewards = "Мушкет Дальней заставыЗаморские наручиВы получите:\n\n"}
MultiLanguageQuestData['ru'][13973] = {title = "Ополчение Гроль'дома", objective = "Убейте 6 погромщиков из племени Иглогривых.", description = "Они появились из ниоткуда, <класс>! Орда Иглогривых, до самого горизонта – одни спины, рыла и клыки. Мы были вынуждены вернуться на ферму, но они продолжали наступать.\n\nЛучшие из наших защитников пали на поле боя, и мы не можем найти фермера Ралтона. Мне нужно, чтобы ты <занял/заняла> наступательную позицию. Удерживай этих свинорылых на расстоянии, а я позабочусь о раненых до тех пор, пока не прибудет помощь.", progress = "Я вижу дым, поднимающийся над соседними домами. Что там происходит?", completion = "Я видела, что ты оставил позади себя цепочку мертвых тел, |3-6(тролль). У меня бы не получилось лучше. Может быть, мы потеряли скот, но зато земля осталась нашей. Спасибо тебе!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13974] = {title = "Маленькая посылка Шкрыпа", objective = "Шкрып попросил вас отнести маленькую посылку Флузу в приют Серебряного Ветра.\n\nПрилагается предмет: \n", description = "Вах!!!\n\nТы смотри, как горит! Это же потрясающе! Настоящий прорыв во взрывотехнике – чего, собственно, я и добивался...\n\nЯ буду самым знаменитым гоблином во всем Нордсколе!\n\nВеришь, нет, но я внес корректировки в формулу, чтобы результат вышел еще более взрывоопасным!\n\nВот, держи образец вещества. Его надо доставить к юго-востоку от Приюта Серебряного Ветра моему кузену Флузу. Полагаю, он найдет способ применить его на благо Орде.", progress = nil, completion = "Неужели малыш Шкрып и впрямь изобрел что-то стоящее? Говоришь, от этой штуки весь Астранаар взлетел на воздух?\n\nНу, как видишь, нам не потребовалась помощь, чтобы захватить приют Серебряного Ветра... Но Шкрыпу недостает размаха.\n\nЕсли в этой штуке действительно заключена такая мощь, я даже представить не могу, что мы можем с ней сделать!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13975] = {title = "Доставка каравана в Перекресток", objective = "Поговорите с Рокко Хлыстоногом с фермы Гроль'дома и проводите его караван до Перекрестка.", description = "*Рокко вручает тебе кажущийся знакомым дробовик.*\n\nВот, я почистил для тебя Халгину артиллерию. Думаю, об отдаче тебя предупреждать не нужно. Когда будешь <готов/готова> двинуться к Перекрестку, говори! Тхорк ждет тебя там. Смотри, не груби ему.\n\nНе останавливайся, <имя>, а если кто-то приблизится, двинь ему прикладом. Мы хотим гордиться тобой!", progress = "Это ты размахивал пушкой за моим караваном?", completion = "Давненько же мы ждали продовольствия! Плохо быть отрезанными от Мулгора, но если мы прекратим торговлю еще с Оргриммаром, город погибнет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13976] = {title = "Три друга леса", objective = "Поговорите с Больюном в его лагере, что в Ясеневом лесу.", description = "Не хочешь совершить небольшое путешествие на юг? У меня там живут друзья, от которых давно уже не поступало вестей. Увы, я не могу покинуть свою семью и отправиться навестить их – <сам/сама> видишь, что тут творится. То какие-то щупальца лезут из-под земли, то демоны бродят по округе.\n\nОдного из моих товарищей зовут Больюн, и он разбил свой лагерь к северо-западу от этого проклятого святилища Огненной Расщелины. Аленндаар и Харлон намеревались присоединиться к нему, так что все вместе они должны быть в безопасности. Но кто сейчас может за это поручиться?\n\nЗаранее спасибо, <имя>.", progress = nil, completion = "Охотник, берегись! Калива, пленившая нас демонесса, где-то неподалеку!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13977] = {title = "Массовое производство", objective = "Флуз просит вас отнести порошок \"Пиф-паф!\" Шкрыпа Джинксу в Производственный цех.", description = "Ха-ха! Ты это <видел/видела>?!\n\nНадо немедленно запустить это в производство!\n\nВот, отнеси эти остатки Джинксу. Он строит новый склад к западу отсюда.", progress = "Что там у вас, босс?", completion = "&lt;Джинкс внимательно изучает принесенный вами порошок.&gt;\n\nХмм... Мне понадобится немного времени, но мы определенно сможем использовать его при изготовлении бомбы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13979] = {title = "Гоблинские эксперты", objective = "Добудьте голову Бдыжня.", description = "Прекратить бы хоть ненадолго эти проклятые гоблинские бомбардировки! Мы смогли бы нанести ответный удар и отвоевать приют Серебряного Ветра.\n\nЯ всегда думала, что гоблины либо слишком ленивы, чтобы создать что-то стоящее, либо столь энергичны, что подрываются на собственных изобретениях. К несчастью, этими вредителями руководит сам главный бумженер Бдыжень.\n\nПослушай, отправляйся-ка ты к Производственному цеху на западной стороне приюта и не возвращайся без головы главного бумженера!", progress = "Надеюсь, этот омерзительный, никчемный гоблин заткнулся навеки?", completion = "Так-то лучше. Теперь их механики снова предадутся лени, будут выпускать меньше бомб и устраивать меньше несчастных случаев.", rewards = "Жилет трезвого умаМеч особого отделаВам дадут возможность выбрать одну из следующих наград:\n\nНаграда Джалин\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][13980] = {title = "Они где-то рядом!", objective = "Джинкс из Производственного цеха просит вас уничтожить 12 убийц из Ясеневого леса.", description = "Они где-то рядом, <класс>, и они охотятся на нас.\n\nМоих людей находят мертвыми, и у меня нет ни тени сомнения в том, что тут замешаны длинноухие!\n\nПохоже, твои действия в Астранааре заставили их изрядно поволноваться, и они изо всех сил пытаются отсрочить свое окончательное поражение.\n\nВот, возьми эти очки – в них ты увидишь даже самых пронырливых эльфов. Не дай им подобраться со спины, пока мы не закончим со взрывчаткой.", progress = nil, completion = "Молодец, друг.\n\nТеперь у нас хватит времени изготовить бомбу. Она уже почти готова!", rewards = "Военизированный поясВам дадут возможность выбрать одну из следующих наград:\n\nКольцо прикрывающего тылы\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13981] = {title = "Они готовят бомбу!", objective = "Доложите о существовании бомбы охотнице Джалин в Башне Звездной Пыли, что в Ясеневом лесу.", description = "Это определенно самая огромная бомба из всех бомб, которые тебе когда-либо доводилось видеть. Да что там эти гоблины думали, когда создавали такое чудовище?\n\nУстройство выглядит вполне готовым. Гоблины постарались от души – похоже, этой шутке ничего не повредит, хотя вытащить ее отсюда будет проблематично.\n\nНужно как можно скорее сообщить о создании Большой Бомбы охотнице Джалин в Башню Звездной Пыли. Это к юго-западу отсюда.", progress = nil, completion = "Что? Настолько большая?!\n\nОх, не нравится мне все это...", rewards = "Следующее заклинание будет наложено на вас:\n\nDetect: Quest Invis Default\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13982] = {title = "В цепях", objective = "Добудьте сердце Каливы.", description = "Берегись, <имя>. Когда мы попали в плен к Каливе, то слышали, как она упоминала твое имя.\n\nТолько ее сердце может освободить нас из этих оков, но я боюсь, что она подстроила тебе ловушку.", progress = "Если мы хотим обрести свободу, нам нужно сердце Каливы.", completion = "Знаю, это мерзко, но если мы хотим избавиться от цепей Каливы, недостаточно убить нашу повелительницу.\n\nКаждый из нас должен проглотить кусок ее нечестивого сердца!", rewards = "Следующее заклинание будет наложено на вас:\n\nIn a Bind: See Invisibility Switch 1\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13983] = {title = "Гвозди для собственного гроба", objective = "Джинкс просит вас собрать 3 бронзовых шестеренки, 3 куска медной обшивки и 5 зажимных болта.", description = "Как только все будет готово, мы должны будем отправить эту бомбу прямиком в Саурбоз.\n\nКонечно, говоря \"мы\", я имею в виду тебя.\n\nПравда, учитывая численный перевес противников, шансы на успех невелики. Надо придумать что-нибудь серьезное, чтобы обеспечить твою безопасность.\n\nПожалуй, я мог бы переделать один из этих крошшеров, но мне потребуются запчасти. К счастью, их легко найти среди деревьев в западном лесу.\n\nЗаймись сбором, а я пока закончу работу над бомбой.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13985] = {title = "Очищение святилища", objective = "Убейте 12 демонов в святилище Огненной Расщелины.", description = "Злодеяниям Пылающего Легиона пора положить конец!\n\n<имя>, ты <победил/победила> одного из их самых могущественных прислужников, но в восточных лесах, в Святилище Огненной Расщелины, бродит еще множество омерзительных демонов.\n\nПрошу тебя, друг леса, убей этих мерзких созданий и предупреди об опасности Высокого Баобоба, древо войны из Святилища Эссины, что на северо-востоке.", progress = nil, completion = "Прекрасно, малыш. А теперь отойди в сторонку, я тут немного занят.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13986] = {title = "Раненый товарищ", objective = "Отнесите побитый фамильный щит Апони Светлой Гриве на Вершину Старейшин Громового Утеса.", description = "Думаю, ты знаешь, какие жаркие бои ведутся в этих краях, <класс>. Нам пока удается удержать позиции, но не всегда удается избежать потерь.\n\nОдин из наших воинов, Апони Светлая Грива, была ранена в руку в одном из сражений. Ее тут же отправили назад в Громовой Утес для лечения, и она была так расстроена этим решением, что забыла здесь свой щит. Не затруднит ли тебя передать его ей вместе с нашими наилучшими пожеланиями? Мы все соскучились по ее улыбке.\n\nТы найдешь ее на Вершине Старейшин.", progress = "Привет! По-моему, мы не знакомы. Могу я чем-нибудь помочь тебе?", completion = "Ах, это же мой щит! Жаль, что я еще не скоро смогу взять его в руки. Но все равно, спасибо тебе. Ты не представляешь, как мне тяжело сидеть здесь, вдали от поля боя, но с раненной рукой в бою от меня будет мало толку.\n\nТы уж береги себя, слышишь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13987] = {title = "Последний рубеж", objective = "Убейте 30 вторгшихся демонов.", description = "<имя>, мне крайне нужна твоя помощь! Я не могу вечно сдерживать наступление демонов. А если я потерплю поражение, Астранаар падет вместе со мной!\n\nУмоляю, помоги мне!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Баобабовый плащНеокольцованные поручиШкурка плода баобабаСледующее заклинание будет наложено на вас:\n\nThe Last Stand: Quest Complete\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][13988] = {title = "Растущая проблема", objective = "Возьмите орла Глаза Тонги на Громовую Вершину на юго-западе от Кабестана.", description = "Внезапно появившаяся буйная растительность на прежде бесплодной земле... Мой приятель Джеррек уже видел такое где-то в Степях. Мне бы стоило взглянуть на это, но я не могу оставить свой пост.\n\nПоэтому, <имя>, я одолжу тебе свои \"глаза\". Этот орел мне служит с тех самых пор, как мне дали имя. Пожалуйста, возьми его с собой на Громовую Вершину, где ждет Джеррек, и мы во всем разберемся.\n\nЧтобы добраться туда, иди по дороге, ведущей от Перекрестка на восток. Поверни на юг у большого покрытого рисунками камня.", progress = "Тонга знает эти земли лучше любого из нас, и я знаю, как больно ему видеть ее разорванной на части.", completion = "Я рад, что Тонга смог увидеть эти заросли своими глазами – масштабов разрушений не передать словами. Его тотем с тобой? Когда я закончу здесь, я верну его Тонге.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13989] = {title = "Король Гиблой Чащи", objective = "Поместите знамя Кровавого Клыка на тотемном кургане Гиблой Чащи и не позвольте фурболгам уничтожить его, пока не появится вождь. Одолейте вождя Мургута.", description = "Мне нет дела до того, кто ты <такой/такая>, <раса>. Меня заботит только судьба фурболгов.\n\nОтнеси это знамя Кровавого Клыка кратчайшим путем в деревню Зеленой Лапы и воткни древко в тотемный холм. Обитатели расценят это как знак агрессии и постараются уничтожить знамя, но ты оберегай его, пока на защиту чести племени не выйдет сам вождь Мургут. И тогда ты убьешь предателя!\n\nЗапомни, друг, тебе надо беречь силы и готовиться к долгому сражению.", progress = nil, completion = "Хорошо. Мургут продал свое племя Орде, присоединившись к ним после того, как они захватили приют Серебряного Ветра.\n\nХотя он оправдывает свои действия попыткой спасти свой народ, в действительности он обрек его на позорное рабство. Теперь же он получил по заслугам!\n\nВпрочем, хватит о нем. Я хочу рассказать тебе еще об одном предателе, чья сила может сделать твой жезл еще более могущественным.", rewards = "Пояс ЗеленолапаВам дадут возможность выбрать одну из следующих наград:\n\nПерстень настойчивости\n\nВы также получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13991] = {title = "Похищенное серебро", objective = "Поговорите с Газрогом у входа в Кабестан.", description = "Ну что же, <имя>. Я признаю, что для тебя найдется место в великой Орде. Ты <продемонстрировал/продемонстрировала> силу, хитрость, инициативу... И даже Тхорк недавно упоминал твое имя, а нас не так-то легко впечатлить. Хорошо.\n\nТеперь можно приступить к настоящей работе. Недавно был похищен груз серебра, предназначавшегося в уплату стражникам Перекрестка. Расследованием руководит Газрог из Кабестана. Поговори с ним!\n\nПросто следуй дорогой, ведущей отсюда на восток и попадешь на побережье.", progress = nil, completion = "Я, конечно, надеялся на отряд пехоты… но если ты заслужил доверие Сергры, я полагаю, тебя будет более, чем достаточно. Давай я объясню, что здесь происходит.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13992] = {title = "Небольшая диверсия", objective = "Убейте 8 кентавров из племени Колкар.", description = "Меня отправили сюда наблюдать за действиями кентавров. Я следил за каждым их перемещением в течение многих дней! Пришло время покинуть это место, но они окружили этот оазис.\n\nТы выглядишь довольно угрожающе. Можешь прикрыть меня? Устрой среди них переполох! Убивай всех без разбору. Пока они будут охотиться за тобой, я смогу выскользнуть отсюда незамеченным и доставлю собранную информацию Ретгару Вратам Cмерти.", progress = nil, completion = "Хо-хо! Это было прекрасно. Вероятно, мне не стоило оставаться и смотреть. Теперь, когда все их внимание обращено на тебя, я тихонько ускользну, и пыль, поднятая их бессмысленными скачками, поможет мне скрыться.\n\nУбедись, что ты нашел моих приятелей и в других прудах.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13995] = {title = "Гора короля кентавров", objective = "Защитите Горгала Злошрама, когда он нападет на кентавров. Помогите ему убить Курака.", description = "Нас прислали сюда, чтобы мы отследили перемещения кентавров из племени Колкар, но после недели наблюдений за тем, как эти грязные твари носятся по оазису, у меня руки чешутся познакомить мой топор с их шеями. Что скажешь, <класс>? Поможешь мне?\n\nМожет, это заставит показаться Курака – самого сильного из них.", progress = nil, completion = "И зачем ты так распалил Горгала? Впрочем, я не могу пожаловаться на результаты. Посмотрим, что эти зверюги будут делать без Курака.\n\nНадо еще подождать, хоть Горгалу это и не понравится.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13997] = {title = "If You're Reading This While I'm In Combat...", objective = "ELM Daze Target wants you to kill 5 ELM Attackers for Dan and Great Justice!", description = "Dan is the most awesome programmer in the world... the World of Warcraft!\n\nIsn't it weird that you used to not be able to talk with me at all while I was fighting? No longer, my friend, now that Dan has made significant improvements to one of my creature flags!\n\nCelebrate with me by snuffing out the lives of these awful creatures that perpetually have me in combat.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][13998] = {title = "Веруем в грибы", objective = "Посадите грибные культуры возле Застывшего оазиса и понаблюдайте за результатом.", description = "Я вырастил эти необычные споры, которые ты <выкопал/выкопала> для меня, в самой питательной среде...реагентов... которой я действительно горжусь. Теперь я сгораю от нетерпения узнать, как выращенные споры поведут себя в воде оазисов Перекрестка.\n\nЗастывший Оазис на юго-востоке, пожалуй, наименее загрязнен, а значит, лучше всего подходит для нашего эксперимента. Просто посади эти споры во влажную почву рядом с оазисом и пронаблюдай за результатом.\n\nДержи рот на замке, <класс>.\n\n<Хелбрим обезоруживающе улыбается.>Вы получите:\n\n", progress = nil, completion = nil, rewards = "Ворсистые перчаткиПокрытые мазью наручиВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][13999] = {title = "Кто кого дурит?", objective = "Доставьте изыскания Хелбрима Сашие в Кабестан в Северных Степях.", description = "Подумай, <имя>, какие возможности! Постоянно развивающаяся служба доставки любых ядовитых грибов. Мои компаньоны в Подгороде непременно захотят узнать об этом.\n\nВот мои заметки и дополнительные образцы. Если поторопимся, успеем к следующему кораблю в Восточные королевства. Отправляйся по дороге, которая проходит к востоку отсюда, она приведет тебя в Кабестан. Найди таверну \"Сломанный Киль\" в южной части города, а в ней мою приятельницу Сашию и доставь ей это.", progress = "Кто ты? Тебя послал Хелбрим? Веди себя тихо.", completion = "Тсс! Давай записку. За тобой не следили?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14001] = {title = "Гоблинские спасательные шлюпки", objective = "Спасите 6 уцелевших гоблинов.", description = "Ой, прости, <имя>, я думал, ты того!\n\nТут черти что творится, Орда погрызлась с Альянсом! Уж не знаю, кто это начал, но мы умудрились заплыть в самое пекло.\n\nНашим братьям и сестрам нужна помощь.\n\n<Гоблин тычет пальцем в сторону спасательных капсул, плавающих вокруг.>\n\nЯ немного посижу и соберусь с силами, а ты пока помоги потерпевшим! Возьми мои термогидратные ласты, с ними ты сможешь плавать быстрее.\n\nИ передай Хамми, что я скоро приплыву, чтоб она не волновалась.", progress = nil, completion = "Делогорячелы! Хвала небесам, ты выжил! Я уже мысленно попрощалась с тобой, когда ты свалился за борт!\n\n&lt;Глаза Хамми наполняются слезами, и она бросается к вам на шею.&gt;\n\nТы настоящий герой-спасатель!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14003] = {title = "Починка самофланжа", objective = "Отнесите сломанный самофланж к Браку Трубореву в лагере.", description = "Так-так, он работает не так, как надо. Кажется, я его сломал.\n\nВпрочем, нет оснований для беспокойства. Окажи мне услугу, сбегай к Браку тут в лагере. Он быстро разберется с этой штуковиной!", progress = "Ты сказал... Самофланж?!", completion = "Пароклапан прислал самофланж? Ну-ка, дай взглянуть на эту штуку!\n\nОкей, мы починим его. Дай-ка мне вон тот здоровый молоток...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14004] = {title = "Вернуться к создателю самофланжа", objective = "Отнесите переконструированные обломки самофланжа обратно Пароклапану в Лагерь Котельника. Чтобы попасть к нему, поговорите с Венаки.", description = "Увы, у меня ничего не вышло. Структурная целостность самофланжа крайне низка. Я могу добавить пару циферблатов и рычаг-другой, чтобы попытаться исправить это, но... от этого может стать только хуже.\n\nСмотри, что я нашла, когда заблокировала стравливающий клапан и сняла крышку с корпуса дифференциала: личное клеймо \"Начальник Медноклин\". Отнеси это обратно Пароклапану и скажи, что этот Медноклин – настоящий гений. Когда закончишь здесь, просто скажи мне, и я отправлю тебя обратно при помощи телепорта Брака.", progress = "Это мой самофланж? Я даже не узнаю его.", completion = "Что сказала Венаки? Медноклин? НАЧАЛЬНИК Медноклин? О, нет, должно быть, это будет непросто.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14005] = {title = "Месть Элуны", objective = "Используйте данные Тариндреллой силы, чтобы пробраться к источнику порчи и уничтожить его.", description = "В то время как Тельдрассил очищает себя от порчи, которая затронула все, что выросло за эти годы, какое-то злокачественное образование появилось на краю, к югу отсюда. У нас есть возможность действовать быстро и удалить источник мха Скверны, который заразил Кривую Сосну, древесников и всех остальных.\n\nВода из лунных колодцев, которую ты <принес/принесла>, и обновленная сила самого Тельдрассила помогут мне на некоторое время наделить тебя огромной мощью. Положи конец этой порче, <имя>.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Неиспорченные крагиБрюки улыбнувшейся удачиОживляющие нарукавникиНадежная пелеринаСледующее заклинание будет наложено на вас:\n\nCancel Vengeance of Elune\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14006] = {title = "Руководство по эксплуатации", objective = "Соберите руководство по эксплуатации самофланжа.", description = "Когда я был в Союзе механиков, начальник Медноклин был нашим лучшим инженером. Он переметнулся в Торговую Компанию незадолго до моего ухода, и все секреты его мастерства ушли вместе с ним. Он владел ценными знаниями, которыми понемногу делился с кругом приближенных.\n\nЕсли он сконструировал самофланж, то, наверное, у него есть и руководство по эксплуатации. Последнее, что я о нем слышал – что он работает в Каменном карьере, на северо-востоке. Возьми у него руководство и собери разрозненные страницы у его последователей.", progress = "Ты нашел Медноклина?", completion = "Ты нашел его! Ничего себе, тут больше 600 страниц и только 30 из них оставлены пустыми.\n\nПосмотрим. Глава 3: Прикручивание обратного коленвала махового колеса? Интересно. Глава 7: Регулирование клапана конденсатора высокого давления?! Да это же кладезь! А я до сих пор даже и не знал, что делает эта штука.\n\nДержи, вот немного моих старых инструментов. Давай-ка запустим эту штуковину!", rewards = "Щит из металлоломаВам дадут возможность выбрать одну из следующих наград:\n\nУстаревший справочник\n\nВы также получите:\n\nПредмет #1Предмет #5"}
MultiLanguageQuestData['ru'][14007] = {title = "\"Верный выстрел\"", objective = "Поговорите с Баммом Взрыбоммом, обучитесь приему \"Верный выстрел\" и поразите тренировочный манекен 3 раза.", description = "Я Бамм Взрыбомм, твой наставник.\n\nКак я понимаю, ты собираешься стать <великим/великой:c> |3-4(<класс>)? Ну что же, будем учиться.\n\nНачнем с \"Верного выстрела\". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху.\n\nИзучи данное умение и потренируйся на манекене.", progress = nil, completion = "Ну вот. Очень даже неплохо!\n\nЗахочешь еще поучиться, всегда обращайся. В любое время. Я тебя с радостью научу всему, что знаю.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14008] = {title = "Чародейские стрелы", objective = "Поговорите с Физзом Лихтером и обучитесь заклинанию \"Чародейские стрелы\", после чего дважды опробуйте его на тренировочном манекене.\n\nПомните, что \"Чародейские стрелы\" можно использовать только с некоторой вероятностью после применения других атакующих заклинаний. Для того чтобы активировать \"Чародейские стрелы\", вначале используйте на тренировочном манекене заклинание \"Огненный шар\".", description = "Я Физз Лихтер, твой наставник.\n\nКак я понимаю, ты собираешься стать <великим/великой:c> |3-4(<класс>)? Ну что же, будем учиться.\n\nНачнем с \"Чародейских стрел\". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное заклинание и потренируйся на манекене, что стоит в юго-восточной части двора.", progress = nil, completion = "Вот и все, босс!\n\nПриходи, если захочешь еще что-то освоить. Я тебя научу всему, что знаю.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14009] = {title = "Быстрое исцеление", objective = "Поговорите с сестрой Горазлатой и обучитесь заклинанию \"Быстрое исцеление\", после чего трижды используйте его на раненом сотруднике.", description = "Я сестра Горазлата, твой наставник.\n\nКак я понимаю, ты собираешься стать <великим/великой:c> |3-4(<класс>)? Ну что же, будем учиться.\n\nНачнем с \"Быстрого исцеления\". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное заклинание и потренируйся в исцелении раненых сотрудников во дворе.", progress = nil, completion = "Вот и все, босс!\n\nПриходи, если захочешь еще что-то освоить. Я тебя научу всему, что знаю.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14010] = {title = "Потрошение", objective = "Поговорите с Крадли Дротик и обучитесь приему \"Потрошение\", после чего трижды опробуйте его на тренировочном манекене.\n\nПомните, что данный прием является продолжением серии, поэтому для начала потребуется применить против манекена умение \"Коварный удар\".", description = "Я Крадли Дротик, твоя наставница.\n\nКак я понимаю, ты собираешься стать <великим/великой:c> |3-4(<класс>)? Ну что же, будем учиться.\n\nНачнем с \"Потрошения\". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное умение и потренируйся на манекене, что стоит в юго-восточном углу двора.", progress = nil, completion = "Вот и все, босс!\n\nПриходи, если захочешь еще что-то освоить. Я тебя научу всему, что знаю.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14011] = {title = "\"Стихийный удар\"", objective = "Поговорите с Макссом Оползнем и обучитесь приему \"Стихийный удар\", после чего дважды опробуйте его на тренировочном манекене.", description = "Я Максс Оползень, твой наставник.\n\nКак я понимаю, ты собираешься стать <великим/великой:c> |3-4(<класс>)? Ну что же, будем учиться.\n\nНачнем со \"Стихийного удара\". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное умение и потренируйся на манекене, что стоит в юго-восточном углу двора.", progress = nil, completion = "Вот и все, босс!\n\nПриходи, если захочешь еще что-то освоить. Я тебя научу всему, что знаю.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14012] = {title = "Жертвенный огонь", objective = "Поговорите с Ехидом Опальчиком и обучитесь заклинанию \"Жертвенный огонь\", после чего трижды опробуйте его на тренировочном манекене.", description = "Я Ехид Опальчик, твой наставник.\n\nКак я понимаю, ты собираешься стать <великим/великой:c> |3-4(<класс>)? Ну что же, будем учиться.\n\nНачнем с \"Жертвенного огня\". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное заклинание и потренируйся на манекене, что стоит в юго-восточной части двора.", progress = nil, completion = "Вот и все, босс!\n\nПриходи, если захочешь еще что-то освоить. Я тебя научу всему, что знаю.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14013] = {title = "Рывок", objective = "Поговорите с Воином-матиком NX-01 и обучитесь приему \"Рывок\", после чего опробуйте его на тренировочном манекене.", description = "<Воин-матик NX-01 включается в оперативный режим.>\n\nОбнаружен босс <имя>. Я Воин-матик NX-01.\n\nОпустите монету, чтобы получить сеанс массажа или обучиться приему \"Рывок\". После изучения приема потренируйтесь на манекене, что стоит поблизости.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14014] = {title = "Верните наши вещи!", objective = "Добудьте 8 ящиков инструментов.", description = "Наши бомбы и инструменты! Подлые макаки выкрали их под покровом ночи и унесли на восток!\n\nПожалуйста, доберись до обезьяних владений и конфискуй то, что принадлежит нам по праву. Я верю, ты справишься, <имя>. Без инструментов мы застрянем на этом острове навеки!", progress = "Обезьяны с гранатами?! Это конец света!!!", completion = "&lt;Хамми вздыхает с облегчением при виде найденных вами инструментов и бомб.&gt;\n\nЯ уж думала, мы обречены. Но теперь у нас есть все необходимое, чтобы выбраться с этого острова!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14016] = {title = "Проклятие Черного рыцаря", objective = "Рыцарь Райдалла из Серебряного павильона на Ристалище Серебряного Турнира просит вас осмотреть могилу Черного рыцаря.", description = "После твоей победы я было распорядилась убрать останки Черного рыцаря с Ристалища, но исповедница Пейлтресс настояла на том, чтобы похоронить его по всем правилам. И с тех пор на нашем кладбище происходят странные вещи, которые отпугивают жителей, желающих воздать почести павшим героям.\n\nТы не <мог/могла> бы лично посетить кладбище и выяснить, что там творится? Оно находится на восточном краю Ристалища.", progress = nil, completion = "&lt;Рыцарь Райдалла хмурится.&gt;\n\nДумаешь, это было запланировано? Пожалуй, это не имеет значения, но мне кажется, что нас обвели вокруг пальца. Мы должны вмешаться!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14017] = {title = "Судьба Черного рыцаря", objective = "Перехватите приказы доктора Колера на Заставе Вестника Смерти, а затем вернитесь к рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного Турнира.", description = "Говоришь, его тело забрали служители культа Проклятых? Я знаю только одно место, куда они могли бы его отнести: это Застава Вестника Смерти, что на западе от Ристалища.\n\nМы должны остановить их во что бы то ни стало. Это только подтверждает правдивость мрачных слухов... Среди них совершает свои темные обряды бесславный доктор Колер. Найди алтарь, возвышающийся над лагерем служителей культа, убей доктора и принеси мне доказательства его грязных деяний. Любой ценой замедли их работу!", progress = "Тебе удалось выяснить, что они делают с останками Черного рыцаря?", completion = "У доктора не было времени закончить свою работу, но последователи довершат начатое. Судя по твоему отчету, слуги Короля-лича воскресили Черного рыцаря и наделили его новой силой. К несчастью, мы не можем предсказать, что задумал его зловещий повелитель, но ты помог пролить свет на этот заговор. Я сообщу о твоих находках Верховному крестоносцу Аделарду, и мы вместе предупредим участников турнира о надвигающейся опасности.", rewards = "Вы получите:\n\nПечать чемпиона"}
MultiLanguageQuestData['ru'][14018] = {title = "Тот, кто будет прощен", objective = "Поговорите с Аврием Дурным Толком у башни в Ночных лесах, что в Ясеневом лесу.Это голос самой богини воззвал к тебе из колодца, <имя>! Лекарство для Релары находится к востоку от Башни в Ночных лесах. Там ты найдешь того, кто поддался скверне.\n\nАврий Дурной Толк – именно тот, кто жаждет прощения и очищения. Если ты поможешь ему, то спасешь и мою дочь.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Это голос самой богини воззвал к тебе из колодца, <имя>! Лекарство для Релары находится к востоку от Башни в Ночных лесах. Там ты найдешь того, кто поддался скверне.\n\nАврий Дурной Толк – именно тот, кто жаждет прощения и очищения. Если ты поможешь ему, то спасешь и мою дочь.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14019] = {title = "Связка спелых бананчиков", objective = "Накормите 10 обезьян с гранатой, бросив им бананы с селитрой.", description = "У нас тут вот какое дело. В джунглях на востоке водится множество обезьян. Так эти макаки стащили всю нашу взрывчатку и теперь швыряются ею куда ни попадя.\n\nИногда – прямо в нас!\n\nПо моей просьбе Физз Лихтер начинил эти бананы селитрой. Ни одна обезьяна не устоит перед связкой спелых бананчиков!\n\nТебе всего-то и нужно, что пойти в джунгли и покормить обезьянок.", progress = nil, completion = "Отведали спелых бананов и взлетели на воздух?! Хотелось бы на это посмотреть!\n\nДумаю, надо сходить самолично покормить зверюшек!", rewards = "Тапочки из банановой кожурыПатронташ для банановПерчатки охотника на обезьянВы получите:\n\nПредмет #1Currency Token Test Token 4"}
MultiLanguageQuestData['ru'][14021] = {title = "Глубинная суть проблемы", objective = "Проведите испуганного шахтера по Каджа'митовой пещере.", description = "Хитроумные обезьяны-рудокопы!\n\nВ этой пещере их полно, и они добывают руду... кирками! Это совсем не похоже на них, и я уверен, что все дело в каджа'мите!\n\nНикто из моих горняков не вернулся... У меня почти не осталось работников! <имя>, ты же видишь, ситуация безвыходная.\n\n<Штейгер понижает голос.>\n\nЭти парни и в подметки не годятся моей старой команде. Какие были тролли! Какие тролли! Сейчас таких уже не делают!\n\nНо, может, ты проводишь моего последнего шахтера в пещеру и защитишь его от обезьян? Пойми, нам очень нужен каджа'мит!", progress = nil, completion = "Мы напали на жилу!!!\n\nТак что там с этим пигмеем-знахарем? Он мертв? Потому что если он мертв, то я обозначу это место, как свое. Впрочем… все равно по гоблинским законам весь каджа'мит принадлежит нам!", rewards = "Жилет шахтера\"Лучшая\" одежда ПромокахаСледующее заклинание будет наложено на вас:\n\nMiner Troubles: Quest Complete\n\nВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14022] = {title = "Пиршество странников", objective = "Поговорите с Грегори Табором – он стоит рядом с вратами Штормграда.", description = "А ты не хочешь присоединиться к Пиршеству странников, <имя>? Когда-то в этот день мы вспоминали о былых путешествиях, рассказывали друзьям о том, как нам улыбнулась удача, и приглашали их разделить с нами пищу. Многие до сих пор соблюдают эту традицию.\n\nТы тоже можешь отметить Пиршество странников – в честь этого праздника в каждой столице накрыты пиршественные столы, ломящиеся от изобилия яств. \n\nА если ты хочешь узнать, как готовятся эти изысканные кушанья, найди Грегори Табора – он стоит рядом с вратами Штормграда.", progress = nil, completion = "Если хочешь научиться готовить особые блюда Пиршества странников – я могу тебе помочь. Главное – знать основы кулинарии!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14023] = {title = "Пряная хлебная запеканка", objective = "Приготовьте 5 порций пряной хлебной запеканки и отнесите ее Джасперу Муру, который стоит возле праздничных столов у ворот Штормграда.", description = "Наша пряная хлебная запеканка – главное блюдо праздничного стола Пиршества странников. Этот рецепт недаром включен в пиршественную поваренную книгу как самое популярное блюдо Штормграда.\n\nЕсли ты умеешь готовить, навести торговцев Пиршества странников и купи пиршественную поваренную книгу, а также все необходимые ингредиенты для приготовления праздничного угощения. А если ты не знаешь, как обращаться с кастрюлями и сковородками – самое время научиться!\n\nКак только приготовишь хлебную запеканку, принеси ее Джасперу Муру, он стоит возле праздничных столов.", progress = "Пряная хлебная запеканка никогда не будет лишней – это одно из самых любимых праздничных блюд.", completion = "Превосходно! Это то, что надо. Конечно, нелегко накрыть такой огромный стол, но праздник того стоит.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14024] = {title = "Тыквенный пирог", objective = "Испеките 5 кусков тыквенного пирога и принесите их Эдварду Уинслоу, который стоит возле праздничных столов Стальгорна.", description = "Ах, как ароматно пахнет приготовленная тобой пряная хлебная запеканка! Но праздничный стол Пиршества странников невозможно представить без огромного тыквенного пирога. Этот десерт очень популярен в Штормграде, поскольку готовится из спелых элвиннских тыкв, которые растут только в этих краях.\n\nЕсли ты еще не знаешь, как готовить тыквенный пирог, загляни в свою пиршественную поваренную книгу.\n\nКстати, тебя не затруднит испечь несколько кусочков и отнести их Эдварду Уинслоу? Он накрывает столы рядом со Стальгорном, и тыквенный пирог наверняка у него уже кончился.", progress = "Тыквенный пирог? Его-то нам и не хватало!", completion = "Тыквенный пирог идет нарасхват – первый раз вижу, чтобы дворфам так нравилось что-то, приготовленное из овощей.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14028] = {title = "Клюквенный соус", objective = "Приготовьте 5 порций клюквенного соуса и отнесите ее Джасперу Муру, который стоит возле праздничных столов у ворот Штормграда.", description = "Если ты еще не <пробовал/пробовала> клюквенный соус – ты не знаешь вкус жизни. Он делается из свежайшей клюквы, которая растет в Болотине. Если хочешь попробовать его приготовить – купи все, что тебе надо, у торговца Пиршества странников.\n\nА рецепт должен быть в твоей пиршественной поваренной книге.\n\nЕсли у тебя есть свободная минутка – может быть, ты поможешь Джасперу Муру приготовить очередную порцию соуса для штормградского стола? Я как раз собирался обменять пару порций на испеченный тобой пирог.", progress = "Мне кажется, или я чувствую запах клюквенного соуса?", completion = "Наконец-то, клюквенный соус прибыл! Ты не поверишь, как быстро он кончается.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14030] = {title = "Голодающие Дарнаса", objective = "Приготовьте 5 порций хлебной запеканки и отнесите ее Исааку Аллертону, который стоит у входа в Дарнас.", description = "Спасибо за клюквенный соус! Нам еще так много надо приготовить – я просто не успеваю за всем следить. Но самое главное – я должен заботиться о том, чтобы Исаак Аллертон из Дарнаса не испытывал недостатка в провизии, а у него как раз кончились все угощения. Я могу рассчитывать на твою помощь? Было бы неплохо, если бы ты <приготовил/приготовила> несколько порций хлебной запеканки и тыквенного пирога. Все нужные ингредиенты есть у продавца.\n\nОтнеси готовую еду к праздничным столам, которые накрыты рядом со входом в Дарнас, прямо под Террасой Воинов.", progress = "Ты хочешь поучаствовать в Пиршестве странников?", completion = "Спасибо за доставку – я уже начал волноваться.\n\nСлушай, пока ты здесь, может, займешься приготовлением засахаренного батата?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14031] = {title = "Фотоохота", objective = "Фотокамерой ТКК с ультравспышкой сделайте снимки алтаря пигмеев и наскальных рисунков в трех пещерах.", description = "Эй, <имя>, тут по всей пещере какие-то странные рисунки и другие артефакты.\n\nМожет, ты воспользуешься своей фотокамерой ТКК с ультравспышкой и сделаешь снимки в означенных местах? Кроме того, сфотографируй алтарь, который находится в глубине пещеры.\n\nУверен, Хамми это будет интересно.", progress = nil, completion = "Что это такое?\n\n&lt;Хамми разглядывает фотографии, одновременно слушая, что вы рассказываете ей о Каджа'митовой пещере.&gt;\n\nОпределенно этот пигмей-знахарь принадлежит к новой расе, которую мы еще не видели. Может, назвать их пигмеями |3-1(Чебо)?\n\nНаверняка это они оставили рисунки на стенах пещеры. Не очень-то мне нравится то, что ты рассказываешь.\n\nПохоже, что на этих рисунках изображены мы с ними на острове и извергающийся вулкан!", rewards = "Вы получите:\n\nПредмет #1Currency Token Test Token 4"}
MultiLanguageQuestData['ru'][14032] = {title = "Нападение на лагерь кобольдов", objective = "Уничтожьте 8 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.", description = "Первое твое задание, <имя>, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14033] = {title = "Засахаренный батат", objective = "Приготовьте 5 порций засахаренного батата и отнесите их Грегори Табору, который стоит у ворот Штормграда.", description = "Раз уж ты здесь, помоги нам пополнить запасы тельдрассильской сладкой картошки – она идет на изготовление самого вкусного засахаренного батата, который ты когда-либо <пробовал/пробовала>.\n\nЕсли не веришь – приготовь <сам/сама>, этот рецепт есть в твоей пиршественной поваренной книге. А если после этого у тебя останется немного угощения – можешь поделиться с Грегори Табором, который накрывает столы возле Штормграда. Он их просто обожает, хотя его послушать – так можно подумать, у него каждое блюдо самое любимое.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14034] = {title = "Припугнуть Фута", objective = "Добудьте чертеж корабля у главного инженера Фута в таверне \"Сломанный киль\", что в Кабестане.", description = "Благодаря последнему конфликту между Альянсом и Ордой я получал прибыль, пока контр-адмирал Хартли не навестил МОЙ порт и не засунул нос своего корабля в мои дела. Он разыскивал корабли Орды и лишал их возможности посещать нейтральный порт.\n\nЯ не собираюсь позволять ему загребать мои деньги своими пухлыми ручонками! Раздобудьте мне план его флагманского судна. Главный инженер Хартли пьянствует в таверне \"Сломанный киль\" вон там на холме...", progress = "Ты принес, что я просил?", completion = "Ага, то что надо! Значит, его флагманский корабль называется \"Непобедимый\", да?\n\nПосмотрим, как отправить эту посудину на дно моря.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14035] = {title = "Запеченная индейка", objective = "Приготовьте 5 запеченных индеек и отнесите их Исааку Аллертону к вратам Дарнаса.", description = "Какой же праздник Пиршества странников без главного украшения – и я вовсе не имею в виду бутафорский рог изобилия. Я говорю про огромную жареную индейку, царицу праздничного стола!\n\nПо-моему, в твоей пиршественной поваренной книге есть подходящий рецепт. Почему бы тебе не убить несколько диких индеек и не приготовить их к празднику? Индейки водятся повсюду в Элвиннском лесу, так что тебе не составит труда отыскать добычу.\n\nКак только закончишь готовить, принеси жареных индеек Исааку Аллертону к вратам Дарнаса, хорошо?Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПризыватель индейки"}
MultiLanguageQuestData['ru'][14036] = {title = "Пиршество странников", objective = "Поговорите с Майлсом Стендишом во внутреннем дворе Подгорода.", description = "Ты <пришел/пришла> сюда, чтобы отпраздновать с нами Пиршество странников? Когда-то в этот день мы вспоминали о былых путешествиях, рассказывали друзьям о том, как нам улыбнулась удача, и приглашали их разделить с нами пищу. Многие до сих пор соблюдают эту традицию.\n\nТы тоже можешь отметить Пиршество странников – в честь этого праздника в каждой столице накрыты пиршественные столы, ломящиеся от изобилия яств. \n\nА если ты хочешь узнать, как готовятся эти изысканные кушанья, найди Майлса Стендиша во внутреннем дворе Подгорода.", progress = nil, completion = "Если хочешь научиться готовить особые блюда Пиршества странников – я могу тебе помочь. Главное – знать основы кулинарии!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14037] = {title = "Пряная хлебная запеканка", objective = "Приготовьте 5 порций пряной хлебной запеканки и отнесите ее Вильяму Маллинсу, который стоит возле праздничных столов во внутреннем дворе Подгорода.", description = "Наша пряная хлебная запеканка – главное блюдо праздничного стола Пиршества странников. Этот рецепт был придуман еще во времена расцвета Лордерона, и дошел до наших дней без изменений.\n\nЕсли ты умеешь готовить, навести торговцев Пиршества странников и приобрети пиршественную поваренную книгу, а также все необходимые ингредиенты для приготовления праздничного угощения. А если ты не знаешь, как обращаться с кастрюлями и сковородками – самое время научиться!\n\nКак только приготовишь хлебную запеканку, принеси ее Вильяму Маллинсу, который стоит возле праздничных столов.", progress = "На столах явно недостает пряной хлебной запеканки.", completion = "Как же трудно следить за тем, чтобы на столах всегда была еда. Подумать только – столько хлопот, хотя в нашем состоянии пища больше не нужна. \n\n&lt;Уильям пожимает плечами.&gt;\n\nОднако традицию нельзя нарушать.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14038] = {title = "Кто не с нами, тот против нас", objective = "Прикрепите магнитную мину в самой тонкой части корпуса \"Непобедимого\".", description = "<Газлоу расстилает план на столе и после некоторого размышления тыкает пальцем в место в кормовой части судна, ниже ватерлинии>.\n\nЗдесь! Здесь, где коленвал подходит к винтовому механизму, обшивка тоньше всего. И это прямо рядом с крюйт-камерой!\n\n<имя>, я, конечно же, не буду иметь никакого отношения к тому, что <какой-то предприимчивый/какая-то предприимчивая:c> <класс> из Орды прикрепит мину к этой части судна. Даже если я сам и дал <ему/ей> эту мину. И заплатил <ему/ей>. Корабль стоит на якоре к юго-востоку отсюда... иди туда!\n\nПотом свяжись со мной по радио при помощи этого краденого ГНМ-передатчика.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14039] = {title = "Дом Калдорай", objective = "Отнесите наполненный сосуд Тиранде Шелест Ветра в Дарнас.", description = "Встретить тебя – бесспорная честь для меня. Ты доказательство благородства нашей расы.\n\nТеперь иди и закончи последнее задание. Отнеси воды Тиранде Шелест Ветра в Дарнас.", progress = "Как дела, юноша?", completion = "А, священные воды из лунных колодцев. Ты показал их духу Калдорай?\n\nС недавних пор я убедилась, что духи больше задают вопросов, чем дают ответов, но такова жажда открытий, которая движет нами в самые тяжелые минуты.\n\nЯ дам тебе самые простые ответы, какие смогу. Малфурион вернулся ко мне... к нам... но трудные времена еще не прошли. Олений Шлем ушел и мир содрогнулся от боли – Малфуриону многое предстоит сделать, и теперь ему понадобится помощь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14040] = {title = "Тыквенный пирог", objective = "Испеките 5 кусков тыквенного пирога и принесите их Фрэнсису Итону, который стоит у праздничных столов возле Оргриммара.", description = "Ты <приготовил/приготовила> отличную хлебную запеканку! Но праздничный стол Пиршества странников невозможно представить без огромного тыквенного пирога. Этот десерт очень популярен в наших краях, поскольку готовится из спелых тирисфальских тыкв, которые растут только в этих краях.\n\nЕсли ты еще не знаешь, как готовить тыквенный пирог, загляни в свою пиршественную поваренную книгу.\n\nКстати, тебя не затруднит испечь несколько кусочков и отнести их Фрэнсису Итону? Он накрывает столы рядом со Оргриммаром, и наверняка у него уже кончился тыквенный пирог.", progress = "Тыквенному пирогу мы всегда рады.", completion = "Этот пирог съедают быстрее всего – можно подумать, гости забывают про основные блюда и приступают сразу к десерту. Ты сам уже попробовал пирог?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14041] = {title = "Клюквенный соус", objective = "Приготовьте пять порций клюквенного соуса и принесите их Докину Дальнему Лугу, который ждет у подъемника на западе Громового Утеса.", description = "Ты уже <пробовал/пробовала> клюквенный соус? Он делается из свежайшей клюквы с берегов реки Строптивой. Если хочешь его приготовить – купи все необходимое у торговца Пиршества странников.\n\nА рецепт записан в твоей пиршественной поваренной книге.\n\nЕсли у тебя есть свободная минутка – может быть, ты поможешь Докину Дальнему Лугу приготовить немного соуса? Он стоит у подъемника на западе Громового Утеса.", progress = "Как идет празднование Пиршества странников?", completion = "Новая порция клюквенного соуса? Отлично, он так быстро кончается!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14042] = {title = "Оружие и контрабанда", objective = "Уничтожьте 5 Тераморских схронов боеприпасов на берегу.", description = "Должно быть, Хартли выгрузил всю свою артиллерию на берегу. Давай-ка заставим его показать зубы, <имя>!\n\nПробегись по берегу и найди его боеприпасы. Подожги их. Он останется безоружным и застрянет на берегу, пока чинят \"Непобедимый\". А я буду ждать тебя в Кабестане.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Посох рудокопаПерчатки непобедимогоВы получите:\n\n"}
MultiLanguageQuestData['ru'][14043] = {title = "Засахаренный батат", objective = "Приготовьте 5 порций засахаренного батата и принесите их Фрэнсису Итону, который стоит у праздничных столов возле Оргриммара.", description = "Раз уж ты здесь, помоги нам пополнить запасы мулгорского сочного батата – он идет на изготовление самого вкусного засахаренного деликатеса, который ты когда-либо <пробовал/пробовала>.\n\nЕсли не веришь – приготовь <сам/сама>, этот рецепт есть в твоей пиршественной поваренной книге. А если после этого у тебя останется немного угощения – можешь поделиться с Фрэнсисом Итоном, который накрывает столы возле Оргриммара. Боюсь, у него опять кончились все запасы угощений, несмотря на все мои усилия.", progress = "А, привет еще раз, Таквер.", completion = "А, Докин поручил тебе приготовить засахаренный батат?\n\n&lt;Френсис улыбается.&gt;\n\nОтлично, иначе он не справился бы. Спасибо за помощь!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14044] = {title = "Нехватка продовольствия в Подгороде", objective = "Приготовьте 5 порций пряной хлебной запеканки и 5 порций клюквенного соуса, и отнесите их Майлсу Стендишу к входу в Подгород.", description = "Спасибо за то, что <принес/принесла> нам засахаренный батат! Нам еще так много надо приготовить – я просто не успеваю за всем следить. А тут еще Майлс жалуется на то, что у него практически кончился клюквенный соус и запеканка. Я могу рассчитывать на твою помощь? Было бы неплохо, если бы ты <приготовил/приготовила> несколько порций угощения. Все нужные ингредиенты есть у продавца.\n\nОтнеси готовую еду Майлсу к праздничным столам, которые накрыты в руинах над Подгородом.", progress = "Рад снова видеть тебя, Расулл.", completion = "Спасибо за доставку – я уже начал волноваться. Плохо, когда на столах одни объедки.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14045] = {title = "Найти барона Дольноберега", objective = "Найдите упомянутого пирата барона Дольноберега и поговорите с ним.", description = "Этот грязный пират барон Дольноберег держал в страхе местные воды до тех пор, пока Альянс не потопил его флот и не повязал выживших. Думаешь, я доволен? По мне видно, что я свечусь от радости, <имя>?\n\nДо того, как его поймали, Дольноберег захватил один из моих самых ценных грузов. Я хочу получить обратно свои товары! Найди Дольноберега в лагере Альянса к югу отсюда и попробуй заставить его рассказать, где он держит мои сокровища.", progress = nil, completion = "Хе-хе! Старик Газлоу все еще не расстался с мечтой снова увидеть свои товары, да? Ну что, похоже, нам есть о чем поторговаться с этим лопоухим любителем золотишка.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14046] = {title = "Потребности истинного барона", objective = "Если вы доверяете барону Дольноберегу, поговорите с ним и освободите его от наручников.", description = "Да, <приятель/подруга>, я без сомнений отправлюсь на виселицу. На кой мне теперь эти сокровища…\n\nРазве что купить на них свою жизнь. Я заключу с тобой сделку, <раса>. Разбей эти наручники и я скажу тебе, где закопаны сокровища.\n\nО, моему слову можно верить, <приятель/подруга>. Я же был настоящим бароном.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14047] = {title = "Запеченная индейка", objective = "Приготовьте 5 запеченных индеек и принесите их Фрэнсису Итону к вратам Оргриммара.", description = "Какой же праздник Пиршества странников без главного украшения – огромной жареной индейки, царицы праздничного стола!\n\nПо-моему, в твоей пиршественной поваренной книге есть подходящий рецепт. Почему бы тебе не убить несколько диких индеек и не приготовить их к празднику? Индейки водятся повсюду в Тирисфальских лесах, так что тебе не составит труда отыскать добычу.\n\nКак только закончишь готовить, принеси жареных индеек Фрэнсису Итону к вратам Оргриммара, хорошо?", progress = "Что привело тебя в Оргриммар, Расул?", completion = "Превосходно! Спасибо тебе, Расул. Теперь тебе не составит труда накрыть свой собственный стол на праздник Пиршества странников.", rewards = "Вы получите:\n\nПризыватель индейки"}
MultiLanguageQuestData['ru'][14048] = {title = "Слишком мало индеек", objective = "Принесите 20 запеченных индеек Кэтрин Железный Чан к вратам Стальгорна.", description = "С самого начала праздника я не отхожу от плиты, но угощений надо гораздо больше, чем я могу приготовить одна. Может быть, мне удастся уговорить тебя помочь?\n\nХорошую дикую индейку тут найти очень сложно, может ты сумеешь принести мне несколько порций? Ты можешь купить несколько порций уже готового блюда или приготовить <сам/сама>. Если ты решишь их готовить, то могу посоветовать охотиться на птиц в Элвиннском лесу. Все остальные ингредиенты можно купить у любого торговца Пиршества странников.", progress = "Тебе удалось найти индеек?", completion = "Это то, что надо! Спасибо, Паоиус, ты меня спас.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлатье странникаСапоги странникаИндейкометШляпа странникаНаряд странникаОдеяние странника\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14049] = {title = "Самая необычная карта", objective = "Возьмите татуированную голову у входа в лагерь Альянса.", description = "Такое дельце, <приятель/подруга>. Чтобы защитить карту сокровищ, я вытатуировал ее на голове моего первого помощника.\n\nРазумеется, сейчас он мертв, как и все остальные члены команды. Альянс понятия не имеет, что у них в руках, и его отрубленная голова украшает сейчас дерево у входа в их лагерь.\n\nСними эту голову и принеси ее Газлоу в Кабестан.", progress = "Барон Дольноберег жив? У тебя есть что-то для меня?", completion = "Что? Что это? Я отправил тебя за сокровищами, а ты приносишь мне воняющую отрубленную голову?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14050] = {title = "Богатство Газлоу", objective = "Газлоу из Кабестана хочет, чтобы вы отправились в скалы над городом и выкопали его сокровище.", description = "Разрази меня гром! Ты <был/была> <прав/права>!\n\nЧертов Барон, а? Зарыл сокровище прямо у меня под носом. Или, вернее, прямо над головой. На карте отмечено место в скалах над Кабестаном, на юге.\n\nВыйди из города по дороге на запад, заберись на холм, поверни на юг и иди обратно к берегу, там найди огромное дерево на берегу залива. Принеси мне мое сокровище и получишь свою долю!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Гламурный посохЖилет фортуныПоножи прибылиВы получите:\n\n"}
MultiLanguageQuestData['ru'][14051] = {title = "Не забыть про запеканку!", objective = "Принесите 20 порций пряной хлебной запеканки Кэтрин Железный Чан к праздничным столам у ворот Стальгорна.", description = "Ох, как нелегко следить за тем, чтобы праздничные столы не пустовали! Одной рукой помешиваю клюквенный соус, другой готовлю засахаренный батат, а еще надо следить за тем, чтобы пироги не подгорели!\n\nИ почему у меня такое чувство, что я что-то упустила из виду? Точно, я забыла про запеканку! Ай, беда... что же делать? Я уже не успею приготовить все, что собиралась! Послушай, может быть, ты мне поможешь? Это несложно – просто купи несколько тарелок готовой запеканки или приготовь ее <сам/сама> – все ингредиенты можно купить прямо здесь.", progress = "Ну, что там с запеканкой?", completion = "Слава добрым духам! Какой же праздничный стол без хлебной запеканки?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлатье странникаСапоги странникаИндейкометШляпа странникаНаряд странникаОдеяние странника\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14052] = {title = "Встреча с Тони", objective = "Поговорите с Тони Два Клыка на Острове Битв, что в Северных Степях.", description = "Эта ситуация с пиратами мне все портит. Капитан Шпрота нападает на все корабли, какие увидит. Даже на те, чьи владельцы заплатили мне за \"покровительство\". Мы должны стрясти деньги с этих пиратов и побыстрее!\n\nЯ знаю одного парня, он лейтенант у Шпроты, такой же корыстный делец, как и Головокружилкинс. Я предложил ему устроить маленький \"мятеж\" и переманить кое-кого из пиратов на нашу сторону. Если эти ребята будут работать на нас, мы станем получать бешеные деньги, понимаешь?\n\nПоговори с Тони Два Клыка на Острове Битв к югу отсюда.", progress = nil, completion = "Эй, приятель, ты тоже работаешь на Головокружилкинса? Принес деньги? Нет? А что насчет оружия?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14053] = {title = "У нас опять кончился соус?", objective = "Принесите 20 порций клюквенного соуса Эллен Мур к праздничным столам возле Штормграда.", description = "Мой супруг, Джаспер, собирался приготовить клюквенный соус, но потом оказалось, что на столах слишком мало засахаренного батата. Похоже, ему не справиться без посторонней помощи. Если ты умеешь готовить, можешь купить клюкву у продавца Пиршества странников – он стоит рядом с вратами в Стальгорн.\n\nА если тебе не хочется браться за половник – ты всегда можешь попросить кого-нибудь приготовить соус для тебя.", progress = "Ты уже несешь клюквенный соус?", completion = "Спасибо, Паоиус. Надо же, ты справился быстрее Джаспера – только ему об этом не говори.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлатье странникаСапоги странникаИндейкометШляпа странникаНаряд странникаОдеяние странника\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14054] = {title = "Проще пареной тыквы", objective = "Принесите 20 кусков тыквенного пирога Мэри Аллертон к праздничным столам возле Дарнаса.", description = "Исаак трудится не покладая рук, чтобы все смогли отведать разнообразные угощенья в честь Пиршества странников, и научились готовить традиционные блюда из тех продуктов, что принес нам последний урожай. Я же стараюсь, чтобы гости ни в чем не испытывали недостатка, но одно из любимых блюд Исаака – тыквенный пирог – уже практически закончилось.\n\nТы сможешь принести еще? Если возьмешься лично его приготовить, купи несколько спелых элвиннских тыкв у праздничного торговца возле Штормграда.", progress = "Как там пироги, уже готовы?", completion = "Отличные пироги! Исааку и прочим гостям они очень понравятся!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлатье странникаСапоги странникаИндейкометШляпа странникаНаряд странникаОдеяние странника\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14055] = {title = "Батат – значит, батат!", objective = "Принесите 20 порций засахаренного батата Джасперу Муру к праздничным столам возле Штормграда.", description = "Моя жена Эллен попросила меня проследить за тем, чтобы столы не пустовали, а сама никак не может определиться, что же ей приготовить. Сначала она поручила мне испечь тыквенный пирог, а потом передумала и решила делать засахаренный батат.\n\nА у меня уже тесто для пирога поднялось! Послушай, может быть, ты займешься этой сладкой картошкой? Представляешь, как она обрадуется, если мы приготовим все, что ей хотелось?\n\nКстати, все необходимые ингредиенты можно приобрести у праздничного торговца в Дарнасе. Удачи, <имя>.", progress = "Засахаренный батат у тебя?", completion = "Превосходно! Спасибо за помощь, Паоиус. Эллен будет счастлива, что мы управились вовремя.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлатье странникаСапоги странникаИндейкометШляпа странникаНаряд странникаОдеяние странника\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14056] = {title = "Там мрачный Гломп над златом чахнет", objective = "Убейте Гломпа и добудьте сокровища Гломпа.", description = "Что? Мятеж по дешевке – это к Головокружилкинсу.\n\nДа, <приятель/подруга>, мы можем сделать эту работу. Но деньги вперед. Капитан Шпрота складирует все денежки, которые мы получаем. Из них я смогу заплатить мятежникам.\n\nСокровища лежат сразу за казармами. Займись сначала \"казначеем\" капитана. С Гломпом справиться нелегко. Поверь мне на слово, уж я пробовал.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14057] = {title = "Оружие. Нам нужно оружие", objective = "Соберите 6 тяжелых дворфийских винтовок.", description = "Для настоящего хорошего мятежа нужно оружие. Все лучшее капитан Шпрота взял себе: целую партию больших тяжелых дворфийских кремневых винтовок. Он хранит их где-то в другом здании на острове. Принеси мне шесть таких винтовок и я раздам их моим будущим офицерам...", progress = "Оружие, приятель. Ты его принес?", completion = "&lt;Тони берет одну из винтовок и смотрит внутрь ствола.&gt;\n\nОоо, отлично. Сверкающая. Громкая. Вот это я понимаю.\n\nОсталось не так много сделать…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14058] = {title = "Батат – значит, батат!", objective = "Принесите 20 порций засахаренного батата Вильяму Маллинсу к праздничным столам над Подгородом.", description = "Роберта Картер попросила меня помочь ей и приготовить одно из ее любимых блюд – засахаренный батат. Я бы рад помочь, но уже пообещал хозяйке накрыть на стол.\n\nМоя благодарность не будет иметь границ, если ты поможешь мне с этим. Роберта никогда не простит мне, если я ее подведу.\n\nКстати, если ты собираешься самостоятельно приготовить это блюдо, могу порекомендовать купить все необходимое у праздничного торговца в Громовом Утесе. Заранее спасибо, <имя>.", progress = "Засахаренный батат уже готов?", completion = "Спасибо, Расул. Теперь я смогу помочь хозяйке и не подведу при этом Роберту.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлатье странникаСапоги странникаИндейкометШляпа странникаНаряд странникаОдеяние странника\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14059] = {title = "У нас опять кончился соус?", objective = "Принесите 20 порций клюквенного соуса Роберте Картер, которая стоит возле праздничных столов во внутреннем дворе Подгорода.", description = "Не понимаю, куда девается весь клюквенный соус – можно подумать, его поганищам скармливают, стоит мне только отвернуться. Поможешь мне приготовить еще? Если ты умеешь готовить, можешь купить сочную мулгорскую клюкву у праздничного торговца, который стоит возле Оргриммара.\n\nА если тебе лень возиться с ягодами – просто попроси кого-нибудь приготовить соус.", progress = "Ты уже несешь клюквенный соус?", completion = "Спасибо за помощь, Расул. Кстати, если узнаешь, куда девается клюквенный соус – дай мне знать.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлатье странникаСапоги странникаИндейкометШляпа странникаНаряд странникаОдеяние странника\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14060] = {title = "Проще пареной тыквы", objective = "Принесите 20 кусков тыквенного пирога Мархаре Голдвит к праздничным столам возле Громового Утеса.", description = "Докин и Лаха трудятся не покладая рук, чтобы все смогли отведать разнообразные угощенья в честь Пиршества странников, и научились готовить традиционные блюда из тех продуктов, что принес нам последний урожай. Я же стараюсь, чтобы гости ни в чем не испытывали недостатка, но одно из наших любимых блюд – тыквенный пирог – уже практически закончилось.\n\nТы сможешь принести еще? Если возьмешься лично его приготовить, купи несколько спелых тирисфальских тыкв у торговца Пиршества странников возле Подгорода.", progress = "Как там пироги, уже готовы?", completion = "Отличные пироги! Спасибо за помощь, Таквер.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлатье странникаСапоги странникаИндейкометШляпа странникаНаряд странникаОдеяние странника\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14061] = {title = "Слишком мало индеек", objective = "Принесите 20 запеченных индеек Ондани Большой Мельнице к вратам Оргриммара.", description = "С самого начала праздника я не отхожу от плиты, но угощений надо гораздо больше, чем я могу приготовить одна. Может быть, мне удастся уговорить тебя помочь?\n\nХорошую дикую индейку достать тут очень сложно – разве что ты сумеешь принесешь мне несколько порций. Если решишь лично их приготовить, то могу посоветовать охотиться на птиц в Тирисфальских лесах. Все остальные ингредиенты можно купить у любого торговца Пиршества странников.", progress = "Как идет охота на индеек?", completion = "Чудесные индейки! Они станут прекрасным украшением праздничного стола. Спасибо за то, что выручил меня.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлатье странникаСапоги странникаИндейкометШляпа странникаНаряд странникаОдеяние странника\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14062] = {title = "Не забыть про запеканку!", objective = "Принесите 20 порций пряной хлебной запеканки Ондани Большой Мельнице к вратам Оргриммара.", description = "Ох, как нелегко следить за тем, чтобы праздничные столы не пустовали! Одной рукой помешиваю клюквенный соус, другой готовлю засахаренный батат, а еще надо следить за тем, чтобы пироги не подгорели!\n\nИ почему у меня такое чувство, что я что-то упустила из виду? Точно, я забыла про запеканку! Ай, беда... что же делать? Я уже не успею приготовить все, что собиралась! Послушай, может быть, ты мне поможешь? Это несложно – просто купи несколько тарелок готовой запеканки или приготовь ее <сам/сама> – все ингредиенты можно купить прямо здесь.", progress = "Тебе удалось достать запеканку?", completion = "Ты как раз вовремя! Самое время накрывать на стол и мне не хватает хлебной запеканки.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлатье странникаСапоги странникаИндейкометШляпа странникаНаряд странникаОдеяние странника\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14063] = {title = "Мятеж!", objective = "Используйте пиратский сигнальный рог, чтобы призвать Тони Два Клыка и его команду на \"Кинжал Девы\". Помогите ему справиться с Алисией Катберт.", description = "А теперь переходим к моей любимой части мятежа: убийства! Пиратам неважно, кто пойдет в расход, важно, кто контролирует корабли. У восточной части этого острова стоит на якоре корабль \"Кинжал девы\", бывший флагманский корабль капитана Шпроты. Он оставил там Алисию Катберт, это одна из его самых надежных офицеров. Устраним ее – и корабль наш, а вместе с ним и море.\n\nМои люди будут в лодках. Заберись на \"Кинжал девы\" и протруби там в этот рог – это будет сигнал для нас, что можно начинать. Давай!", progress = "Это случайно не \"Кинжал девы\" снимается с якоря там на горизонте? Твоя работа?", completion = "Так значит Тони закатил там представление? Хорошо! В этих водах нам пригодятся такие пираты, как он. Настоящий деловой человек.\n\n&lt;Головокружилкинс с жадностью потирает руки.&gt;\n\nПолагаю, я твой должник. Не хочешь застраховать свою добычу? В городах вроде этого никогда ни в чем нельзя быть уверенным...", rewards = "Рыцарский кинжалТуфли заговорщикаНезакрепленные наручиПлащ бунтовщикаВы получите:\n\n"}
MultiLanguageQuestData['ru'][14064] = {title = "Богатый пир", objective = "Съешьте по 5 порций каждого из праздничных блюд с пиршественного стола, пока не ощутите дух пиршества.", description = "Если ты еще не <пробовал/пробовала> блюд с пиршественного стола – считай, Пиршество странников прошло мимо тебя!\n\nПожалуйста, присаживайся, отведай наших угощений. Не стесняйся пересаживаться поближе – или просто попроси соседей передать тебе любое блюдо.\n\nКогда насытишься вдоволь, почувствуешь, как на тебя снизойдет дух пиршества.", progress = "Ты вдоволь поел угощений с пиршественного стола?", completion = "Ах, какой пир!\n\nСпасибо, что присоединился к празднованию Пиршества странников!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14065] = {title = "Богатый пир", objective = "Съешьте по 5 порций каждого из праздничных блюд с пиршественного стола, пока не ощутите дух пиршества.", description = "Если ты еще не <пробовал/пробовала> блюд с пиршественного стола – считай, Пиршество странников прошло мимо тебя!\n\nПожалуйста, присаживайся, отведай наших угощений. Не стесняйся пересаживаться поближе – или просто попроси соседей передать тебе любое блюдо.\n\nКогда насытишься вдоволь, почувствуешь, как на тебя снизойдет дух пиршества.", progress = "Ты вдоволь поел угощений с пиршественного стола?", completion = "Ах, какой пир!\n\nСпасибо, что присоединился к празднованию Пиршества странников!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14066] = {title = "Осмотр места преступления", objective = "Найдите разбитую повозку каравана возле дороги между Кабестаном и Перекрестком и поищите вокруг улики.", description = "Недавно был похищен груз серебра. Он предназначался в уплату стражам Перекрестка, и его необходимо вернуть.\n\nЯ собираю информацию среди населения здесь, а для тебя у меня есть другое задание – обыщи место преступления. Отправляйся на запад, там ты найдешь разбитую повозку из каравана. Она находится к северу от дороги, что ведет отсюда в Перекресток. Выясни, кто взял наши деньги и верни их!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14067] = {title = "Похищенное серебро", objective = "Убейте 8 яркочешуйчатых опустошителей, 4 яркочешуйчатых смертехвата и найдите украденное серебро.", description = "Совершенно ясно, что похитившие серебро Орды ящеры действовали без сообщников!\n\nПора хорошенько проучить их.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Клинок с серебряным лезвиемПоножи с серебряными узорамиВы получите:\n\n"}
MultiLanguageQuestData['ru'][14068] = {title = "Охота на яфферов", objective = "Используйте \"Ловуфку для яфферов\" Кала'мы для поимки 5 маленьких яфферов.", description = "Уфтановка ловуффек для яфферов, может быть, и опафное дело, но я разработал соверфенно новую ловуффку, которая знафительно сниффает рифк.\n\nПолофы ловуффку на землю, и она нафнет издавать виффафие звуки, тофь-в-тофь как яфферы. Таким образом мы заманим яффера в ловуффку, а как только он фтупит туда, ловуффка зафлопнется. Фсе, яффер уфе не так опафен! Фсе офень просто. Я бы и фам фделал это, но недавно перебефал дорогу королю Деруффий Коготь.", progress = "Гфе маленькие яфферы?", completion = "Ура! Ты поймал яфферов, котофых я искал! Теперь мы отпфафим их тфоллям, а те верхом на них будут бороффа с Альянфом!", rewards = "Охотник на ящевовБашмаки из кожи \"яффера\"Нагвудник из шкувы ящеваВы получите:\n\n"}
MultiLanguageQuestData['ru'][14069] = {title = "Хороших работников трудно найти", objective = "Усмирите 8 взбунтовавшихся троллей.", description = "У меня ничего не вышло! Я делал все что мог, чтобы выполнить план по производству \"Каджа-Колы\", но ты же знаешь... с этими троллями – просто беда. Сложно найти толковых помощников!\n\nДумаю, понадобится твое личное участие. Полагаю, пары ударов током от батареи твоего гоблинского все-в-одном-чудо-пояса будет достаточно. Главное, приструнить основных зачинщиков мятежа, и тогда остальные тролли быстренько придут в чувство.\n\nПроизводство \"Каджа-Колы\" должно идти без перебоев, иначе торговый принц с нас шкуру спустит!", progress = nil, completion = "Я сам бы лучше не справился! Сказать по правде, я уже не справился.\n\nВот ни капельки не сомневаюсь, что уже очень скоро все заговорят о великой, могучей и баснословно богатой торговой принцессе по имени Нефростии!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14070] = {title = "Как вразумить должников", objective = "Избейте Бруно Негорючего, Френки Скрипетельку, Джека Молотка и Судзи Магика.", description = "Все-таки надо бы разобраться с нашими должниками. Никчемные лодыри прячутся в Рабочем квартале. Я знаю, как ты не любишь шастать по трущобам, но, как говорится, кому сейчас легко?\n\n<Хамми листает какие-то бумаги.>\n\nЗдесь у меня все записано. Все имена.\n\nДумаю, стоит начать, скажем так, с \"личной беседы\". Пара-тройка стратегических избиений – даже без тяжких физических повреждений – и все остальные сразу поймут намек. И должники, и конкуренты.\n\n<имя> – не из тех гоблинов, с кем можно шутки шутить!", progress = nil, completion = "Вот и славно! Теперь твои должники дважды подумают, прежде чем уклоняться от выплаты долга.\n\n&lt;Хамми впадает в задумчивость и рассеянно постукивает карандашом по нижней губе.&gt;\n\nЯ тут вот что подумала... может, нам стоит увеличить процентную ставку по займам?", rewards = "Перчатки сборщика податейСвистящий хлыстВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14071] = {title = "Кружим по кварталу", objective = "Проедьтесь на хотроде и подвезите друзей – Туза, Гоббера и Иззи.", description = "Я слышала, <имя>, ты собираешься устроить корпоративный банкет. Всем банкетам банкет! И это правильно. Чем веселее твоя вечеринка, тем вернее твое продвижение по службе. Проверено опытом!\n\nТак что садись в свой хотрод да отправляйся собирать друзей по всему городу.\n\nНу, а когда станешь <торговым принцем/торговой принцессой>, обо мне не забудь, лады?", progress = nil, completion = "Вот и славно. У тебя такой солидный вид, когда ты разъезжаешь на этом хотроде. Думаю, ты произвел на горожан неизгладимое впечатление.", rewards = "Сигнальный пистолетМодные штаныПлотно сидящие кожаные поножиВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14072] = {title = "Против Верога", objective = "Найдите 4 документа оперативной информации кентавров в Застывшем Оазисе.", description = "Регтар Врата Смерти отправил меня сюда с заданием наблюдать за деятельностью кентавров, но я никак не могу обнаружить их главаря. Я узнала, что его зовут Верог Дервиш, но вот где он скрывается, я никак не могу выяснить.\n\nПоможешь мне кое-что разыскать? Я понимаю, что говорить об \"оперативной информации кентавров\" бессмысленно, но все же в их лагерях часто бывают разбросаны разнообразные важные сообщения. Обыщи все палатки кентавров в районе Застывшего Оазиса и принеси все, что сможешь там найти.", progress = "Обыщи эти палатки, Длекс. Постарайся не обращать внимания на вонь.", completion = "Превосходно, Длекс. Ты видел эти? Едва читаются, больше похожи на каракули, чем на стратегические планы. Ненависть, зависть, ярость, конфликты – удивительно, как Верог умудряется удерживать кентавров от того, чтобы они не перебили друг друга, что уж говорить о поддержании военной дисциплины.\n\nМы можем воспользоваться этим.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14073] = {title = "Врата Смерти получает подкрепление", objective = "Отправляйтесь с докладом к Регтару Вратам Смерти на его заставу к западу от Перекрестка, что в Северных Степях.", description = "<имя>! Тебя все больше и больше уважают в Орде. Я видел твое имя в докладах, что поступили из Застывшего Оазиса и Забытых Прудов, и везде говорится, что ты – настоящий бич кентавров. Впечатляет.\n\nРетгар Врата Смерти отвечает за наши операции, связанные с кентаврами – здесь и по всем Северным Степям. <Такому/Такой> <отважному/отважной:c> <класс>, как ты, найдется место в рядах его армии. Отправляйся к нему с докладом. Следуй по дороге на запад и найдешь его заставу. Выполняй все его приказы.", progress = nil, completion = "А, я слышал о твоей работе, |3-6(Разбойник). Очень удачно, что ты прибыл сейчас – нам нужны лишние руки.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14074] = {title = "Лапами кверху", objective = "Верните 10 украденных окорочков долгонога Нараси Снежной Заре из Павильона Серебряного союза на Ристалище Серебряного турнира.", description = "Серебряный Авангард отправил сюда крейсерский корабль, перевозивший мясо долгоногов и прочие припасы для турнира, но он так и не добрался до пункта назначения. Наши разведчики доложили, что на него напали квалдиры, безжалостные пираты, которые бороздят эти моря.\n\nОни убили всю команду и перетащили груз на остров, который теперь называется Лагерь Хротгара. Посмотри на север – и увидишь его среди туманов. Может быть, ты поможешь нам вернуть украденные припасы? Если мясо долгоногов не прибудет вовремя, у нас может кончиться провизия.", progress = "Тебе удалось найти украденные припасы?", completion = "Мда, выглядят они... не очень, но есть можно. Крестоносцы будут рады узнать, что нам удалось спасти хоть какие-то припасы с корабля.", rewards = "Вы получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14075] = {title = "Беспорядки в шахтах", objective = "Убейте 6 роющих червей.", description = "В Каджа'митовой шахте опять беспорядки. Вернулись роющие черви, и они – в прямом смысле слова – пожирают всю прибыль Торгового дома Каджаро!\n\nДобыча каджа'мита практически остановлена, а это, как ты понимаешь, отрицательно сказывается на производстве \"Каджа-Колы\"!\n\nМы пригласили истребителя червей, но он, шельмец, взял деньги вперед и сбежал.\n\nМожет быть, ты <сам/сама> очистишь три шахты? Я бы пошел вместе с тобой, да вот пока не прошел обучение на семинаре по боевому искусству.", progress = nil, completion = "Так им и надо, паразитам!", rewards = "Туфли управляющего ТККЖилет роющих червейВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14076] = {title = "Завтрак для чемпионов", objective = "Найдите 4 яйца йормунгаров и принесите их Савинии Певице Преданий на Ристалище Серебряного турнира.", description = "Теперь, когда постройка Колизея закончена, Серебряный Авангард дал нам новое поручение – позаботиться о животных, с которыми предстоит сражаться чемпионам.\n\nУ этих гигантских йормунгаров странные вкусовые предпочтения – похоже, они питаются яйцами себе подобных. Самыми питательными считаются яйца глубинных йормунгаров.\n\nВот, отнеси этот барабан к Подножию в Грозовой Гряде и ударь в него рядом со снежными курганами. Звук пробудит глубинных йормунгаров, и ты сможешь одолеть их, чтобы завладеть яйцами.", progress = "Тебе удалось добыть яйца йормунгаров? По-моему, эти червяки скоро примутся пожирать своих надсмотрщиков.", completion = "Отличная работа, Альдемир. Я отнесу их в хранилище Серебряного Авангарда, и им останется только признать, что мы вносим гораздо больший вклад в общее дело, чем эти никчемные Похитители Солнца!", rewards = "Вы получите:\n\nПредмет #1Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14077] = {title = "Милосердие Света", objective = "Воспользуйтесь Молитвенником исповедницы для проведения последнего обряда над телами 8 убитых туаликов, после чего вернитесь к Нараси Снежной Заре в шатер Альянса на Ристалище Серебряного турнира.", description = "Последняя проповедь Исповедницы Пейлтресс заставила меня задуматься о том, что нам недостаточно просто сражаться плечом к плечу с рыцарями Авангарда – мы должны помогать им исполнить свой долг.\n\nУ северного побережья находится Лагерь Хротгара – остров, который захватили морские пираты – квалдиры, убив всех обитавших на нем клыкарров. Возьми эту книгу и прочти отходную молитву рядом с телами павших жителей. Пусть их несчастные души обретут покой вдали от зловещих туманов острова.", progress = "Ты позаботился о душах убитых туаликов?", completion = "&lt;Нараси забирает у вас молитвенник.&gt;\n\nСпасибо. Этот молитвенник подарила мне сама Исповедница Пейлтресс. Она будет рада узнать, что он послужил благому делу.", rewards = "Вы получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14078] = {title = "Тотальная эвакуация", objective = "Найдите лейтенанта Вальдена в северо-западном углу Торговой площади.", description = "А ты что здесь делаешь? Разве ты не <слышал/слышала> про эвакуацию?\n\nНемедленно разыщи лейтенанта Вальдена, и он выдаст тебе дальнейшие инструкции.", progress = nil, completion = "На трупе мужчины видны глубокие раны от когтей.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14079] = {title = "Уроки верховой езды в Элвиннском лесу", objective = "Верните это рекламное сообщение Рандалу Охотнику на лесопилку Восточной долины в Элвиннском лесу.", description = "Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Рандала Охотника.\n\nЕго можно найти на лесопилке Восточной долины, в Элвиннском лесу, вдоль дороги, ведущей из Штормграда.", progress = "А, ты получил мое письмо? Отлично.", completion = "Итак, начнем тренировку?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14080] = {title = "Остановить нападение", objective = "Нараси Снежная Заря из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас убить 10 квалдиров.", description = "Квалдиры, морские твари, что захватили наши грузы, завладели островом клыкарров, который находится на севере пролива, убили его обитателей и переименовали его в Лагерь Хротгара. Если позволить им закрепиться на этой позиции, они изберут нас следующей целью.\n\nАвангард бросил все силы на борьбу с Плетью, поэтому защитить Ристалище можем только мы. Лети на север от турнирной площадки, пока не увидишь этот остров, и убей квалдиров прежде, чем они возьмутся за нас.", progress = nil, completion = "Твои действия подтвердили, что мы сражаемся плечом к плечу с Серебряным Авангардом, в то время как Похитители Солнца прохлаждаются в тени.", rewards = "Вы получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14081] = {title = "Уроки верховой езды в Лесах Вечной Песни", objective = "Верните это рекламное сообщение Пераскамину в стойла Турона в Луносвете.", description = "Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Пераскамина.\n\nЕго можно найти в Стойлах Турона, к юго-востоку от Врат Пастыря, ведущих из Луносвета.", progress = "А, ты получил мое письмо? Отлично.", completion = "Итак, начнем тренировку?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14082] = {title = "Уроки верховой езды в Экзодаре", objective = "Верните это рекламное сообщение Аалун, которая находится неподалеку от Экзодара на острове Лазурной Дымки.", description = "Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Аалун.\n\nЕе можно найти в Экзодаре на острове Лазурной Дымки", progress = "А, ты получила мое письмо? Отлично.", completion = "Итак, начнем тренировку?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14083] = {title = "Уроки верховой езды в Дун Мороге", objective = "Верните это рекламное сообщение Ультаму Громовому Рогу на ферму Янтарленов в Дун Мороге.", description = "Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Ультама Громовой Рог.\n\nЕго можно найти на ферме Янтарленов, которая расположена вдоль дороги, ведущей на восток от Стальгорна.", progress = "А, ты получил мое письмо? Отлично.", completion = "Итак, начнем тренировку?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14084] = {title = "Уроки верховой езды в Дун Мороге", objective = "Верните это рекламное сообщение Бинджи Перосвисту в поселок Сталежара в Дун Мороге.", description = "Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Бинджи Перосвиста.\n\nЕго можно найти в Поселке Сталежара к северо-востоку от Караноса в Дун Мороге.", progress = "А, ты получила мое письмо? Отлично.", completion = "Итак, начнем тренировку?", rewards = "Вы получите:\n\n"}
