MultiLanguageQuestData['ru'][14088] = {title = "Уроки верховой езды в Дуротаре", objective = "Верните это рекламное сообщение Ксар'Ти в деревню Сен'джин в Дуротаре.", description = "Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Ксар'Ти.\n\nЕго можно найти в Деревне Сен'джин, что в южном Дуротаре.", progress = "А, ты получил мое письмо? Отлично.", completion = "Итак, начнем тренировку?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14089] = {title = "Уроки верховой езды в Тирисфальских лесах", objective = "Верните это рекламное сообщение Вельме Варнам в Брилл в Тирисфальских лесах.", description = "Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Вельмы Варнам.\n\nЕе можно найти в Брилле, в Тирисфальских лесах.", progress = "А, ты получил мое письмо? Отлично.", completion = "Итак, начнем тренировку?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14090] = {title = "Гормоку нужны снобольды", objective = "Воспользуйтесь утяжеленной сетью, чтобы поймать 8 последователей с Холмов Снежной Слепоты, и приведите их Савинии Певице Преданий в Павильон Серебряного союза на Ристалище Серебряного турнира.", description = "Уже двое моих людей погибли, пытаясь угомонить магнатавра по кличке Гормок, а это животное все еще буйствует – воет без остановки и требует своего любимого снобольда.\n\nЯ бы его собственными руками придушил, но Серебряный Авангард собирается выпустить его на бой в Колизее. Похоже, придется попытаться разыскать его любимую игрушку. Возьми эту сеть и отправляйся к Побоищу Гарма, что на юго-востоке Грозовой Гряды и к северо-востоку от К-3. Поймай там несколько снобольдов – и молись Свету, чтобы среди них оказался тот самый зверек.", progress = "Ну что, снобольды у тебя с собой? Проклятый Гормок все никак не угомонится!", completion = "Чем быстрее мы уберем этих вонючих тварей в клетку, тем лучше. Жаль, что Серебряный Авангард не поручил Похитителям Солнца присматривать за этой тварью. Они так похожи, что им не составило бы труда найти общий язык.", rewards = "Вы получите:\n\nПредмет #1Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14091] = {title = "Дурной знак", objective = "Вернитесь к принцу Лиаму Седогриву на Торговую площадь.", description = "Похоже, лейтенант скончался от нанесенных ран, и эту новость надо немедленно сообщить принцу.\n\nВы слышите шум драки, доносящийся со стороны рынка.", progress = nil, completion = "А, это снова ты. Похоже, ты не из тех, кто прячет голову в песок, и это хорошо.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14092] = {title = "Завтрак для чемпионов", objective = "Принесите 4 яйца йормунгаров Тайлосу Вестнику Зари в шатер Орды на Ристалище Серебряного турнира.", description = "Теперь, когда строительство Колизея завершено, Серебряный Авангард поручил нам заботу о зверях, с которыми придется сразиться чемпионам.\n\nЭтим гигантским йормунгарам полагается странная диета – они питаются яйцами себе подобных. Самые сытные откладывают глубинные йормунгары.\n\nВот, отнеси этот барабан к Подножию, что в центре Грозовой Гряды, и ударь в них возле снежных курганов. Звук пробудит глубинных йормунгаров, и ты сможешь убить их, собрать яйца и принести на Ристалище.", progress = "Тебе удалось добыть яйца? А то йормунгары уже проявляют недовольство.", completion = "Я сообщу крестоносцам, что пока Серебряный союз прохлаждался, ты вернулся с провиантом.", rewards = "Вы получите:\n\nПредмет #1Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14093] = {title = "И разверзся ад", objective = "Принц Лиам Седогрив приказал вам убить 6 озлобленных воргенов.", description = "Воргены! Отец предупреждал меня, что создания верховного мага Аругала обезумели.\n\nНо откуда они взялись?\n\nВпрочем, наверное, это не имеет значения. Лучше помоги нам справиться с ними. Покажем им, из какого теста сделаны настоящие гилнеаcцы!", progress = nil, completion = "Все бесполезно, Эмберсан! Они не сдадутся.", rewards = "Вы получите:\n\nМеховое пальто из волчьей шкурыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14094] = {title = "Спасение припасов", objective = "Спасите 4 ящика с припасами.", description = "Послушай, <имя>, мы не можем допустить, чтобы все припасы были уничтожены.\n\nСейчас, когда Гилнеас отрезан от остального мира, мы не продержимся и зиму, если потеряем еще больше продовольствия.\n\nПожалуйста, помоги мне спасти хоть что-то!", progress = "Припасы спасены, Бысая?", completion = "Превосходно! Я отнесу их в безопасное место.", rewards = "Вы получите:\n\nСумка спасателя"}
MultiLanguageQuestData['ru'][14095] = {title = "Опознание останков", objective = "Отнесите зуб кракена Крестоносцу Серебристый Рассвет в Серебряный павильон.", description = "Неповрежденный зуб кракена – это действительно редкая находка. Наверняка она заинтересует Крестоносца Серебристый Рассвет из Серебряного павильона.", progress = "Что там у тебя, чемпион?", completion = "Я знал, что тебе не составит труда справиться с кракеном. Теперь, когда это чудовище не нападает на наши корабли, квалдирам останется только спасаться бегством. Очень хорошо, чемпион!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14096] = {title = "На этот раз ты нарвался, Кул", objective = "Спасите Кула Безрассудного и 4 пленных претендентов с Заставы Вестника Смерти и вернитесь к Нараси Снежной Заре в шатер Альянса на Ристалище Серебряного турнира.", description = "Рыцарь Кул опять угодил в беду, но на этот раз увлек за собой других. Как только он увидел, что приспешники культа Проклятых разбили лагерь на Заставе Вестника Смерти, что на западе от Ристалища, то собрал группу претендентов и повел их на бой с захватчиками.\n\nРазумеется, не имея должного подкрепления, они были разбиты и захвачены в плен. Я не сомневаюсь, что злодеи принесут их в жертву, дабы подпитать этой силой свою зловещую магию. Ключи от черных клеток, в которых держат пленников, могут храниться у любого из служителей культа. Прошу тебя, найди ключи, спаси Кула и несчастных претендентов от ужасной участи!", progress = nil, completion = "Благодаря тебе Кул и другие претенденты снова вернулись в строй, чтобы сражаться с Плетью. К несчастью, нам не впервой спасать этого доблестного мужа от самого себя. Надеюсь, претенденты выберут себе другой пример для подражания.", rewards = "Вы получите:\n\nПредмет #5Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14098] = {title = "Эвакуация Торговой площади", objective = "Помогите эвакуировать людей из 3 домов.", description = "Теперь здесь стало небезопасно – даже родные стены не могут защитить от беды.\n\nМы пытаемся не пустить воргенов в дома, но их слишком много, и за всеми невозможно уследить.\n\nПомоги нам эвакуировать жителей в тюремный квартал – армия моего отца сможет лучше их защитить.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14099] = {title = "Королевский приказ", objective = "Поговорите с Гвен Армстед в северо-восточной части Военного квартала.", description = "Теперь тебе тоже пора уходить, <имя>. Ступай в Военный квартал вместе с остальными жителями.\n\nКак только пересечешь мост, разыщи Гвен Армстед и узнай, все ли прошло благополучно.\n\nА я останусь здесь и буду прикрывать отход вместе со стражниками.\n\nИди же! Это приказ.", progress = nil, completion = "Мы в порядке! Все еще с трудом приходим в себя, но живы...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14100] = {title = "Реликвия Служителей Земли", objective = "Принесите четыре тотема Готуру Четыре Ветра в Оргриммар.", description = "Ты уже многому <научился/научилась>, <имя>. Теперь, когда тебе подвластны все четыре основных элемента, пора узнать, как сохранять между ними равновесие. Тебе пригодится это знание – потренировавшись, ты сможешь носить с собой только одну реликвию вместо четырех тотемов.\n\nПоговори с Готуром Четыре Ветра на Аллее Мудрости в Оргриммаре и обрети власть над четырьмя стихиями.", progress = "Хм... что заставило тебя искать помощь Служителей Земли?", completion = "А, так значит, у тебя есть все четыре тотема. Можешь гордиться своими достижениями, юный |3-6(тролль), но это еще только начало.\n\nВот, прими это в дар от Служителей Земли. Носи эту реликвию с собой как символ власти над четырьмя стихиями.\n\nИ продолжай свои тренировки! Смертельная опасность нависла над этим миром – я чувствую ее в дыхании ветра и дрожи земли. Мы должны готовиться к худшему.", rewards = "Вы изучите:\n\nТотем Служителей Земли"}
MultiLanguageQuestData['ru'][14101] = {title = "Дроттинн Хротгар", objective = "Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Дроттинна Хротгара.", description = "Квалдиры, морские врайкулы, которые грабят корабли и прибрежные поселения, захватили остров клыкарров, что находится на севере пролива. Их предводитель – бывалый пират Дроттинн Хротгар, который давно уже стремится установить контроль над этими морями.\n\nПока он правит шайкой бандитов, наши корабли и транспортные суда находятся в постоянной опасности. А если мы окажемся отрезанными от остального мира, нам останется только сдаться на милость Королю-личу.\n\nВозьми этот боевой рог Квалдира и отнеси его к кругу клыкаррских статуй на северо-востоке Лагеря Хротгара. С его помощью ты сможешь бросить вызов предводителю квалдиров.", progress = nil, completion = "Смерть Дроттинна приведет к стычкам среди квалдиров, стремящихся занять его место, что поможет нам выиграть время. Крестоносцы турнира в долгу у тебя, чемпион.", rewards = "Вы получите:\n\nПредмет #1Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14102] = {title = "Призыватель туманов Йингвар", objective = "Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Призывателя туманов Йингвара.", description = "Квалдиры вернулись на берега Нордскола – и это может стать для нас проблемой, если мы не обеспечим безопасность наших грузов и подкреплений. Один из их предводителей, Призыватель туманов Йингвар, поселился в пещере на западной стороне Лагеря Хротгара. Оттуда он управляет туманами, чтобы скрыть базы пиратов и подвластных квалдирам морских чудовищ.\n\nВозьми этот амулет и отправляйся на север от Ристалища, к Лагерю Хротгара. Найди пещеру призывателя туманов и воспользуйся амулетом, чтобы увидеть его.", progress = nil, completion = "Ты помог нам выиграть драгоценное время для подготовки операции против квалдиров. Когда-нибудь мы очистим от них моря. Серебряный Авангард вновь у тебя в долгу, Расул.", rewards = "Вы получите:\n\nПредмет #1Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14103] = {title = "Титановый порошок", objective = "Привет, Напрудил! Хочешь что-нибудь продать?", description = nil, progress = "Привет, Напрудил! Хочешь что-нибудь продать?", completion = "Превосходно! Еще одна порция порошка!\n\nТолько между нами, ювелирами – я знаю, как легко и непринужденно заработать много денег, продавая изделия из \"чистого титана\" незадачливым даларанским магам. Их великого ума не хватает на то, чтобы экономно относиться к золоту. Так что если добудешь еще порошка – с радостью куплю его у тебя.", rewards = "Вы получите:\n\nДаларанский знак ювелираCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14104] = {title = "Орнолф Меченый", objective = "Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Орнолфа Меченого.", description = "Орнолф Меченый – безжалостный пират, о котором со страхом отзываются даже его собратья-квалдиры. Он и его команда \"Ярости Бора\" грабят суда и убивают наших людей.\n\nОрнолф и его бандиты были среди тех, кто принял участие в расправе над обитателями острова клыкарров, который теперь носит название Лагерь Хротгара. Корабль этого пирата стоит на якоре в гавани на востоке этого острова. Возьми этот захваченный флаг и установи его на корабле. Не сомневаюсь, это приведет Орнолфа в ярость, и он попытается лично расправиться с тобой. Удачи!", progress = nil, completion = "Команда Орнолфа захочет отомстить за своего вождя, но сейчас, когда они остались без предводителя, их будет легко уничтожить. Мы должны выполнить свою миссию и дожить до того дня, когда Ледяная Корона будет очищена от Плети и прочего зла.", rewards = "Вы получите:\n\nПредмет #1Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14105] = {title = "Вестник смерти Карос", objective = "Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть вестника смерти Кароса.", description = "Культ Проклятых удвоил свои усилия, стремясь к нашему уничтожению. Они обнаглели настолько, что собрали свои силы на западе от Ристалища, на Заставе Вестника Смерти.\n\nВозглавляет их безжалостный Вестник Смерти Карос, и скоро его люди нападут на нас из-за возведенных укрытий.\n\nНаши солдаты и искатели славы готовятся отразить атаку, но только чемпионы могут обезглавить войско противника. Найди Вестника Смерти, <имя>, и убей его.", progress = "Ты одолел предводителя служителей культа?", completion = "Ты служишь примером всем, кто собрался под нашими знаменами. Вместе мы покажем Плети, что нас не одолеть!", rewards = "Вы получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14106] = {title = "Na Kada's Quest Test", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗелье маны"}
MultiLanguageQuestData['ru'][14107] = {title = "Судьба Павших", objective = "Крестоносец Серебристый Рассвет из Серебряного павильона просит вас даровать покой 6 духам павших героев.", description = "Серебряный Авангард – не единственная сила, противостоящая Королю-личу в Ледяной Короне. Но наш враг хочет обратить против нас души павших союзников...\n\nИх духи блуждают по Долине павших героев, на юго-западе от ристалища и к западу от Алдуртара. Земля там буквально усыпана кристаллами душ, которые Плеть использует для подчинения призраков. Собери эти кристаллы и освяти с помощью Благословенной светом реликвии, чтобы даровать покой неприкаянным духам. Они это заслужили.", progress = "Ты даровал покой павшим героям?", completion = "Ты оказал великую услугу нашим павшим братьям и избавил нас от печальной участи уничтожать их на поле боя. Чем больше мы сражаемся с Плетью, тем сильнее беспокоит меня собственная судьба.\n\nХотелось бы мне, чтобы кто-то позаботился о моих бренных останках, если мне суждено пасть в бою. Мне невыносима мысль о том, что моим братьям придется убивать меня бесчисленное количество раз.", rewards = "Вы получите:\n\nПредмет #6Предмет #1Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14108] = {title = "Изгнать Кракена!", objective = "Крестоносец Серебристый Рассвет просит вас оседлать серебряного гиппогрифа, бросить 8 пылающих копий в кракена Северного моря и поразить 6 квалдиров-пробудителей глубин.\n\nСеребряного гиппогрифа можно найти возле палатки Серебряного Авангарда на Ристалище Серебряного Турнира.", description = "Похитители Солнца и Серебряный союз отправили корабли на север, чтобы вступить в схватку с врайкулами, захватившими Лагерь Хротгара, но по пути были перехвачены пиратским флагманом. Хуже того, проклятые квалдиры нашли способ вызвать из глубин Северного моря свирепое чудовище – кракена. Если мы хотим спасти хоть кого-то из команды кораблей, мы должны изгнать кракена и прервать ритуал квалдиров.\n\nКрестоносец, возьми эти копья и пусть серебряный гиппогриф отнесет тебя в самую гущу битвы.", progress = "Неужели с кракеном еще не покончено? Поторопись, крестоносец – времени осталось мало!", completion = "Крестоносец, благодаря твоим действиям моряки смогли избежять ужасной участи. Возможно, в следующий раз эти сорвиголовы из Серебряного союза и Похитителей Солнца прислушаются к нашим советам прежде, чем бросаться на амбразуры.", rewards = "Вы получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14109] = {title = "Новый наряд", objective = "Купите блестящие украшения у Гэппи Серебряного Зуба, новый стильный костюмчик у Забо и модные темные очки у Миссы Фарцовщицы в переулке Дельцов.", description = "Новый наряд? Да ты что?! Твой банкет – настоящее событие! Все сливки общества этого острова соберутся! Прямо-таки взбитые сливки!\n\nНу, что же… удачных покупок! Кстати, лучшие в городе магазины – в Переулке Дельцов.", progress = "Как отоварился, Гришакастер? Жуть, как хочется увидеть новый наряд на тебе!\n\nНадеюсь, это того стоит.", completion = "Хм, ты прекрасно впишешься в обстановку банкета. Конечно, мой наряд выглядит получше… Такими темпами ты со дня на день займешь место торгового принца!\n\nПросто не могу дождаться момента, когда мне не придется больше работать! Ты же меня обеспечишь всем необходимым, милый?\n\nДавай-ка мне сюда обновки – я тебя принаряжу для банкета.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #10\n\nВы также получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14110] = {title = "Новый наряд", objective = "Купите блестящие украшения у Гэппи Серебряного Зуба, новый стильный костюмчик у Забо и модные темные очки у Миссы Фарцовщицы в переулке Дельцов.", description = "Новый наряд? Да ты что?! Твой банкет – настоящее событие! Все сливки общества этого острова соберутся! Прямо-таки взбитые сливки!\n\nНу, что же… удачных покупок! Кстати, лучшие в городе магазины – в Переулке Дельцов.", progress = "Ну что, закупилась? Уже хочу посмотреть на тебя в новом прикиде. Прям жду не дождусь!\n\nЭто будет что-то с чем-то!", completion = "О да, ты всех сразишь своим видом! С твоей-то прытью уже со дня на день займешь место торгового принца, помяни мое слово.\n\nТы уж меня не забудь, когда это случится!\n\nДавай я тебе помогу одеться.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #10\n\nВы также получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14111] = {title = "Реликвия Служителей Земли", objective = "Принесите четыре тотема Предсказателю Эанну в Стальгорн.", description = "Ты уже многому <научился/научилась>, <имя>. Теперь, когда тебе подвластны все четыре основных элемента, пора узнать, как сохрянять между ними равновесие. Тебе пригодится это знание – потренировавшись, ты сможешь носить с собой только одну реликвию вместо четырех тотемов.\n\nПоговори с Предсказателем Эанну в Стальгорне возле Великой Кузни – он поможет тебе отточить мастерство в повелевании стихиями.", progress = "Да пребудут с тобой добрые духи. Что привело тебя к Служителям Земли?", completion = "А, так значит, у тебя есть все четыре тотема. Можешь гордиться своими достижениями, юный |3-6(дреней), но это еще только начало.\n\nВот, прими это в дар от Служителей Земли. Носи эту реликвию с собой как символ власти над четырьмя стихиями.\n\nИ продолжай свои тренировки! Смертельная опасность нависла над этим миром – я чувствую ее в дыхании ветра и дрожи земли. Мы должны готовиться к худшему.", rewards = "Вы изучите:\n\nТотем Служителей Земли"}
MultiLanguageQuestData['ru'][14112] = {title = "Кстати, чем питаются йети?", objective = "Савиния Певица Преданий из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести ей 3 куска мяса акулы Северного моря.", description = "Рыцари поймали огромного йети по кличке Ледяной Рев, который будет участвовать в гладиаторских боях, и поручили нам тренировать и кормить его.\n\nЖаль, им не понравилась моя идея отдать ему на растерзание парочку Похитителей Солнца. Эта тварь предпочитает мясо акул, так что тебе придется отправиться за ним на \"Серебряный Клинок\", который стоит на якоре к северу пролива. Возьми свежую наживку из бочек на борту и брось ее в воду – она привлечет внимание акул.", progress = "Надеюсь, ты принес еду для Ледяного Рева – иначе мне придется перевести его на диету из представителей Похитителей Солнца.", completion = "Я рада, что мы справились с этой задачей. Пусть это была не самая почетная миссия на свете, но раз уж мы заключили договор с Серебряным Авангардом, мы должны выполнять все, что они от нас потребуют. Во всяком случае, это выгодно отличает нас от Похитителей Солнца.", rewards = "Вы получите:\n\nПредмет #5Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14113] = {title = "Банкет", objective = "Наденьте свой потрясный прикид для вечеринки (темные очки, новый стильный костюмчик и блестящие украшения) и отправляйтесь развлекать 10 кутил из Кезана, собравшихся у бассейна в штаб-квартире ТКК.", description = "Ничего себе! Да тут собрался весь цвет кезанского общества! Кому какое дело до дракона?\n\nМы решили устроить банкет у бассейна. Гости, похоже, довольны. И все ждут тебя!\n\nТак что давай наряжайся, иди к бассейну и общайся с гостями. Я тоже скоро приду... но сначала мне надо кое-что сделать.", progress = nil, completion = "Как все здорово получилось. Банкет удался на славу!\n\nЭ... Что это?", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14115] = {title = "Пираты-наемники", objective = "Убейте 12 пиратов-наемников, чтобы спасти свою карьеру.", description = "Ой, мама! Пираты!\n\n<имя>, к тебе на банкет заявились пираты Южных морей!\n\nНадо немедленно что-то предпринять! Иначе все твои планы стать <следующим торговым принцем/следующей торговой принцессой> накроются медным тазом!", progress = nil, completion = "Да, впечатляюще. Но, боюсь, у меня есть и другие не слишком приятные новости.\n\nТолько сразу меня не убивай...", rewards = "Кушак Южных морейНаручи полной катастрофыВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14116] = {title = "Незваный гость", objective = "Поговорите с торговым принцем Галливиксом на верхнем этаже штаб-квартиры ТКК на Кезане.", description = "Пока ты там <разбирался/разбиралась> с пиратами, я видела торгового принца. Он потихоньку поднялся по лестнице. Думал, наверное, его никто не заметит. Он сейчас на балконе на верхней площадке.\n\n<имя>, я думаю, это он подослал пиратов.\n\n<Хамми морщится.>\n\nТебе надо подняться наверх. И как можно скорее! Нельзя заставлять его ждать.", progress = nil, completion = "Так-так-так... а вот и мой своенравный протеже, господин Чебо.\n\nЯ разочарован и огорчен. Ты меня даже не пригласил на свой праздник. Прошу прощения за пиратов... ты же знаешь, какие они невоспитанные...\n\nНо давай перейдем к делу.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14117] = {title = "Глаза Ясеневого леса", objective = "Убейте 8 разведчиков с заставы Талрендис.", description = "Кругом враги, <класс>, даже тут, у самых наших дверей. Ночные эльфы прислали подкрепление на заставу Талрендис, пытаясь оcтановить наше вторжение в Ясеневый лес. В то время, как мы разговариваем, их разведчики прочесывают близлежащие холмы, докладывая о каждом движении у врат.\n\nНадо избавиться от этих глаз Ясеневого леса.\n\nИди. Они бродят возле врат, больше всего их в восточной части. Убей разведчиков, которые следят за нами!", progress = nil, completion = "Отлично! Их разведчики не смогут доставить донесения, и Талрендис станет жертвой такого же террора, какому они пытались подвергнуть нас.", rewards = "Жезл глаз холмаУкраденные с заставы Талрендис сапогиВы получите:\n\n"}
MultiLanguageQuestData['ru'][14118] = {title = "Оленина для солдат", objective = "Соберите 15 больших кусков оленины, убив ослабших мохоногих маралов.", description = "Из-за того, что мы истратили все ресурсы этих земель на наши боевые машины, местным животным негде жить. Они в любом случае умрут, поэтому пусть хотя бы их мясо не пропадет даром. Желудки воинов Оргриммара совершенно пусты.\n\nПоохоться на ослабших мохоногих маралов в округе и запасись их мясом для нашей пехоты.", progress = "От тебя пахнет свежей добычей, |3-6(Шаман).", completion = "Мясо – и много! Замечательно. Теперь нам не придется строить арсенал на голодный желудок.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14119] = {title = "Blank [PH]", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы изучите:\n\nТрансмутация: око Зула\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14120] = {title = "Миллиард деревянных?!", objective = "Поговорите с Хамми Кофельнагель в штаб-квартире ТКК на Кезане.", description = "Ты весьма <честолюбивый юнец/честолюбивая девушка>, <имя>. Может быть, даже чересчур, а это, знаешь ли, не всегда хорошо. Хотя в твоем возрасте я был точно таким же, так что ты – это я, только моложе.\n\nУ меня к тебе предложение. Ты, должно быть, <заметил/заметила>, что из-за твоего дракона началось извержение Каджаро. Все, кто останется на Кезане, умрут! Но если ты принесешь мне миллиард деревянных до того, как моя яхта отчалит от острова, я позабочусь о том, чтобы ты <оказался/оказалась> в числе немногих спасшихся счастливцев.\n\nВ общем так – хочешь жить, думай, где достать бабки!", progress = nil, completion = "Миллиард деревянных?! Где мы возьмем столько денег?\n\n&lt;Хамми на мгновение задумывается.&gt;\n\nТак... А торговый принц, когда предлагал тебе бежать на его яхте, про меня что-нибудь говорил? Ну, что меня тоже возьмут.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14121] = {title = "Грабь награбленное", objective = "Садитесь в хотрод, задавите 12 наемных грабителей и заберите у каждого украденные им вещи.", description = "Мы все умрем!!!\n\n<Вы даете Мегз пощечину, чтобы прекратить истерику.>\n\nПрошу прощения, <господин/госпожа> <имя>. Этого больше не повторится. Так... надо срочно придумать, где взять столько денег.\n\nГоворят, торговый принц нанял грабителей, и те уже бесчинствуют на улицах.\n\nСадись в свой хотрод и поезжай в город. Дави их без жалости, этих грабителей. А заодно собирай все добро, что они успели награбить. По-моему, это будет лишь справедливо.", progress = "Ну что, награбил награбленное?", completion = "Что, правда?! Ты их всех задавил? Ну, что же... так и им и надо.\n\nСлушай, тут же куча добра. Думаешь, этого хватит, чтобы купить тебе место на яхте торгового принца?\n\nА ты можешь кого-нибудь взять с собой? А то меня как-то уже не прельщает заниматься маркетингом... как ни кручусь, все гроши зарабатываю.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14122] = {title = "Ограбление банка", objective = "Взломайте хранилище Первого банка Кезана и заберите свои личные сбережения.", description = "Все твои счета заморожены, а Первый банк Кезана закрылся!\n\nТебе нужна куча денег. А где их взять? Думаю, надо просто забрать свои деньги из банка! В твоем гоблинском все-в-одном-чудо-поясе столько всяких полезных приспособлений. Наверняка там найдется какой-нибудь инструмент, чтобы вскрыть дверь в хранилище.\n\nНадеюсь, ты <слушал/слушала> мои советы и <отложил/отложила> энную сумму на черный день. Потому что сегодня – самый что ни на есть черный день. Хотя и подсвеченный раскаленной магмой!!!", progress = "Ну что, получилось? Ты забрал свои личные сбережения из банка?", completion = "Стало быть, ты не транжирил средства! Я тобой горжусь!\n\n&lt;Хамми считает ваши деревянные.&gt;\n\nЭ... слушай... но этого мало.", rewards = "Взломщик Первого банкаБотинки с кисточкамиПерчатки взломщика хранилищВы получите:\n\nСумка грабителя банковCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14123] = {title = "Антикварные ценности", objective = "Раздобудьте \"Ястреба Малди\", \"Гоблину Лизу\" и \"Платиновую бомбу\".", description = "Есть всего один способ достать миллиард деревянных: украсть у богатых!\n\nЭтот мерзавец торговый принц награбил целые горы всевозможного антиквариата и дорогущих предметов искусства. Давно пора отобрать у него эти ценности и отдать их бедным... например, нам!\n\nСейчас мы тебя замаскируем под одного из прихлебателей Галливикса. А потом ты спокойненько зайдешь на виллу торгового принца и \"приберешь\" антикварные ценности.\n\nТолько старайся не приближаться к его свиньям. Они чуют чужих. Их не обманешь никакой маскировкой!", progress = "Ну что, забрал ценности?", completion = "Ух ты! Да они стоят целое состояние!\n\n&lt;Крадли жадно разглядывает вашу добычу.&gt;\n\nОстается надеяться, что торговый принц их не признает, когда ты будешь ему отдавать все богатства...", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14124] = {title = "Каджа'митовые месторождения", objective = "Соберите 12 кусков каджа'мита.", description = "Нам нужна куча денег, чтобы расплатиться с торговым принцем и убраться с Кезана подобру-поздорову! И эти деньги – буквально у нас под ногами, в Каджа'митовой шахте. Подходи и бери!\n\nПоследние из известных нам каджа'митовых месторождений остались как раз на Кезане. Они здесь повсюду, куда ни плюнь. Собственно, благодаря им мы и стали гениальнейшими механиками и алхимиками. Если эти месторождения не стоят миллиарда деревянных, тогда я даже не знаю, что может стоить...\n\nВозьми у меня разрывные бомбы, подорви ближайшее месторождение и собери разлетевшиеся куски.\n\nТолько будь <осторожен/осторожна>. Берегись бунтующих троллей!", progress = "Сколько ты уже собрал?", completion = "Отлично, отлично! У тебя в мешках – целое состояние.\n\nКогда торговый принц это увидит, держу пари, он нас всех возьмет на свою яхту!", rewards = "Вы получите:\n\nПредмет #1Currency Token Test Token 4"}
MultiLanguageQuestData['ru'][14125] = {title = "Страховочный план", objective = "Устройте перегрузку барахлящего генератора, включите прохудившуюся печку, уроните сигару на легковоспламеняющуюся кровать и запустите газобота, чтобы поджечь штаб-квартиру ТКК!", description = "У нас уже целая куча деревянных, но этого все равно мало. Но на этот случай у меня есть план! Здание штаба застраховано, и если вдруг что случится, мы получим страховку.\n\nПосле банкета остались фейерверки, и я разложила их по всему зданию. Тебе только и нужно, что зайти в штаб и устроить маленькую диверсию.\n\nПредлагаю следующую огнеопасную комбинацию: неисправный генератор, прохудившаяся печка и легковоспламеняющаяся кровать. А потом просто выходишь наружу и посылаешь в здание газобота.\n\nПлан идеальный, а главное – надежный!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Огнеустойчивые пижамные рукаваГазообразные наручиПропитанные газом сапогиВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14126] = {title = "Сбережения", objective = "Отдайте ваши сбережения торговому принцу Галливиксу на борту его яхты на Кезане.", description = "Ну вот, мы набрали нужную сумму. Осталось только добраться до яхты торгового принца. Она уже готовится выйти из порта!\n\nНам надо поторопиться. Давай, забирайся в машину. Я – за рулем!", progress = "А, это ты, Бомбицу. Какой неожиданный сюрприз.\n\n<Торговый принц потирает руки.>", completion = "Мои поздравления, у тебя все получилось. Вижу, ты принес все, о чем я просил, включая и твой хотрод.\n\n&lt;Торговый принц злобно усмехается.&gt;\n\nМиллиард деревянных – солидная сумма. На дороге точно не валяется. Теперь я самый богатый и самый могущественный гоблин во всем Азероте! Но самое ПЕЧАЛЬНОЕ В ЭТОМ ДЛЯ ТЕБЯ – ЭТО ТО, ЧТО Я ИЗМЕНЯЮ УСЛОВИЯ СДЕЛКИ. Отныне ты мой раб. Спускайся в трюм и принимайся кидать уголь в печь. Следующая остановка: Азшара!\n\nХа-ха-ха!", rewards = "Следующее заклинание будет наложено на вас:\n\nLife Savings: Quest Complete\n\nВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14127] = {title = "Возвращение высокорожденных?", objective = "Доставьте приказы разведчика Аг'тору Кровопалу к задним вратам Оргриммара.", description = "Восковая печать на этих приказах недавно была сломана. Аккуратные записи карандашом, которые делали ночные эльфы, прочесть невозможно, но на небольшой от руки нарисованной карте изображены близлежащие руины. Ниже карты видны руны, написанные металлическими мерцающими чернилами.\n\nНет никаких сомнений, что Аг'тору будет интересно на это взглянуть.", progress = "Говоришь, ты что-то нашел на одном из тел? Давай сюда!", completion = "&lt;Аг'тор, прищурясь, смотрит на пергамент, повернув его к свету.&gt;\n\nНет, я тоже не понимаю, что тут написано. Но мне не нравится то, что я здесь вижу. Это чародейские руны?\n\nМне нужно, чтобы ты отнес это специалисту.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14128] = {title = "Возвращение высокорожденных?", objective = "Доставьте приказы разведчика Малинее Опустошительнице Небес на оргриммарскую пересадочную станцию ракетной дороги.", description = "Наши союзники эльфы крови осматривали изображенные на этой карте руины, и, вероятно, смогут понять эти таинственные записи. Найди среди них ту, кого зовут Малинея Опустошительница Небес. Она проводит исследования на оргриммарской пересадочной станции ракетной дороги к северу отсюда – это часть новой транспортной системы гоблинов, которая, извиваясь, проходит через эти земли. Давай, поторапливайся!", progress = "Надеюсь, ты отвлек меня ради чего-то серьезного?", completion = "Что? Дай это сюда, сейчас же! Аг'тор прав, это чародейские руны. Они исследуют магические места? Экспериментируют с тайной магией? Это идет вразрез с тысячелетней историей ночных эльфов.\n\nПфф! Думать, что они станут компетентными в этой области, – даже те, кто считался когда-то высокорожденными, – это же абсурд.\n\n&lt;Малинея презрительно отбрасывает свиток в сторону, но на ее лице появляется тень беспокойства.&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14129] = {title = "Сбежавшие крошшеры!", objective = "Атакуйте один из сбежавших крошшеров возле задних врат Оргриммара и заберитесь внутрь, когда он будет значительно поврежден.", description = "Я хотел продемонстрировать нашим новым союзникам из Орды легендарную эффективность гоблинской техники, но сейчас, оглядываясь назад, мне кажется, что автоматизация крошшеров была не самой лучшей из моих идей. Сейчас эти крошшеры – можно сказать, настоящие машины-убийцы – сеют в округе смерть. Не пойми меня превратно – такие штуковины вполне могут пригодиться где-то еще, но сейчас мне прямо-таки <необходим храбрый/необходима храбрая:c> <класс>, <который/которая:c> поможет мне совладать с этими махинами.\n\nЭто не так уж и сложно. В первую очередь тебе понадобится подчинить себе один из этих крошшеров. Возьмешь управление на себя, и я передам тебе по радио новые инструкции.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14130] = {title = "Друзья бывают разных цветов", objective = "Найдите Эргла в руинах храма Арккоран.", description = "Меня и моих братьев преследуют.\n\nНедавно убили нашего вожака, а сейчас черные драконы ищут тех из нас, кто остался в живых. Я здесь, чтобы найти Азурегоса и переправить его в безопасное место, если только он даст возможность это сделать.\n\nУ Азурегоса мало друзей и выбирает он их немного... странным образом. Единственный, кого я здесь знаю, это мурлок по имени Эргл. Ты сможешь найти его на берегу к северо-востоку отсюда.\n\nСделай все возможное, чтобы найти Азурегоса и прислать его ко мне.\n\nПожалуйста, торопись.", progress = nil, completion = "Привет! Новый друг! Так рад тебя видеть. Меня зовут Эргл. Для удобства \"г\" можно не произносить.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14131] = {title = "Собери мне чуть-чуть", objective = "Соберите 10 бобов кауфи с растений в руинах храма Арккоран.", description = "Азурегос… Азурегос. Азу? Дракон? Да, мы с ним друзья! Он научил меня говорить. Говорил, что ему нравится мой цвет… можно подумать, он художник, да?\n\nНе помню, куда он пошел. Ммм… у меня что-то с памятью.\n\nЯ засадил весь пляж растениями кауфи. Они любят песок. Это странно.\n\nМожешь собрать их?", progress = "Так устал, так трудно сосредоточиться.", completion = "Красивые бобы! Они так вкусно пахнут, да?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14132] = {title = "Это просто невежливо!", objective = "Убейте 10 макринни в руинах храма Арккоран.", description = "Если бы они попросили, я бы поделился. А они просто стали рвать и крошить мои растения кауфи. Это невежливо! Тебе надо научить их, как себя вести.\n\nПусть макринни замолчат.", progress = nil, completion = "Слишком жестоко? Нет, не слишком. Они это заслужили.\n\nЯ их растения не портил. Никогда.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14134] = {title = "Древесина для подрядчика", objective = "Воспользуйтесь перепрограммированным крошшером, чтобы собрать 6 штабелей азшарской древесины. Если вы потеряете свой крошшер, можно поймать и перепрограммировать другой.", description = "Теперь, когда ты <научился/научилась> управлять этой штукой, давай сделаем то, что должен был делать я, – заготовим древесину. Иначе эти орки построят катапульту из МЕНЯ!\n\nВ этой области много спиленных деревьев. Воспользуйся крошшером и собери столько, сколько сможешь.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14135] = {title = "На деревья", objective = "Воспользуйтесь циркулярной пилой крошшера, чтобы спилить азшарские молодые деревца и убейте 9 снайперов с заставы Талрендис, когда они появятся.", description = "Замри на секундочку, я подключу циркулярную пилу.\n\nСнайперы ночных эльфов с заставы Талрендис прячутся в деревьях и стреляют в моих рабочих. Я хочу, чтобы ты <занялся/занялась> этими снайперами… предварительно занявшись деревьями. Поищи азшарские молодые деревца восточнее главных ворот. Твой крошшер сам поймет, что ему делать. Поруби их!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14136] = {title = "Спасательная операция на море", objective = "Гирана Окровавленная из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас убить 8 квалдиров-берсерков и 3 квалдиров-гарпунеров, напавших на \"Огненный Ястреб\".", description = "Квалдиры захватили маленький остров на севере и переименовали его в Лагерь Хротгара. Чтобы разведать ситуацию, мы отправили туда капитана Аэртаса Огненного Ястреба, но его корабль попал в засаду к пиратам неподалеку от Ристалища! К несчастью, квалдиры значительно превосходят по численности его команду. Прошу тебя, отправляйся туда и покажи этим бандитам, что они не на тех напали. \n\n\"Огненный Ястреб\" находится к северу от Ристалища, на западной части пролива.", progress = nil, completion = "Отличная работа, Чемпион. Наша борьба еще не закончена, но теперь квалдиры поймут, что на нас нельзя нападать безнаказанно.", rewards = "Вы получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14138] = {title = "Бизнес – прежде всего", objective = "Передайте поощрение Хамми штейгеру Промокаху в штаб-квартире ТКК на Кезане.", description = "Что касается беспорядков в Каджа'митовой шахте... штейгер Промоках уже сбился с ног. Ищет тебя. Он что-то говорил о \"взбунтовавшихся вконец обнаглевших троллях\".\n\nКаджа'мит, добываемый нашими троллями, – основной компонент \"Каджа-Колы\". На этой шипучке мы делаем огромные деньги, и, кстати, благодаря ей ты <сам/сама> можешь стать <торговым принцем/торговой принцессой>!\n\nНо сначала нам нужно восстановить производство. Иди на восток, найди штейгера. Вручи ему вот это, чтобы у него был стимул к действию.", progress = "Э... все идет замечательно. Да.\n\nА это что?", completion = "Подарок от Хамми? Никак премия!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14140] = {title = "Остановить нападение", objective = "Гирана Окровавленная с Ристалища Серебряного турнира просит вас убить 10 квалдиров.", description = "Квалдиры, морские врайкулы, что захватили наши грузы, завладели островом клыкарров, который находится на севере пролива, убили его обитателей и переименовали его в Лагерь Хротгара. Если позволить им закрепиться на этой позиции, они изберут нас следующей целью.\n\nАвангард бросил все силы на борьбу с Плетью, поэтому защитить Ристалище можем только мы. Лети на север от турнирной площадки, пока не увидишь этот остров, и убей квалдиров прежде, чем они возьмутся за нас.", progress = nil, completion = "Твои действия подтвердили, что Похитители Солнца – гораздо более надежные союзники Серебряного Авангарда, нежели Серебряный союз. Вместе мы одержим победу!", rewards = "Вы получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14141] = {title = "Гормоку нужны снобольды", objective = "Воспользуйтесь утяжеленной сетью, чтобы поймать 8 последователей с Холмов Снежной Слепоты, и приведите их Тайлосу Вестнику Зари в шатер Орды на Ристалище Серебряного турнира.", description = "Уже двое моих людей погибли, пытаясь угомонить магнатавра по кличке Гормок, а это животное все еще буйствует – воет без остановки и требует своего любимого снобольда.\n\nЯ бы его собственными руками придушил, но Серебряный Авангард собирается выпустить его на бой в Колизее. Похоже, придется попытаться разыскать его любимую игрушку. Возьми эту сеть и отправляйся к Побоищу Гарма, что на юго-востоке Грозовой Гряды и к северо-востоку от К-3. Поймай там несколько снобольдов – и молись Свету, чтобы среди них оказался тот самый зверек.", progress = "Удалось словить снобольдов? Проклятый Гормок все никак не угомонится!", completion = "Чем быстрее мы уберем этих вонючих тварей в клетку, тем лучше. Жаль, что Серебряный Авангард не поручил Серебряному союзу присматривать за тварями. Вскоре им придется запачкать свои белоснежные ручки в борьбе за Цитадель Ледяной Короны, и я опасаюсь, что они окажутся слишком слабыми и ненадежными союзниками.", rewards = "Вы получите:\n\nПредмет #1Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14142] = {title = "На этот раз ты нарвался, Кул", objective = "Спасите Кула Безрассудного и 4 пленных претендентов с Заставы Вестника Смерти и вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира.", description = "Рыцарь Кул опять угодил в беду, но на этот раз увлек за собой других. Как только он увидел, что члены культа Проклятых разбили лагерь на Заставе Вестника Смерти, к западу от Ристалища, то собрал группу претендентов и повел их на бой с захватчиками.\n\nРазумеется, не имея должного подкрепления, они были разбиты и захвачены в плен. Я не сомневаюсь, что мерзавцы принесут их в жертву, дабы подпитать этой силой свою зловещую магию. Ключи от черных клеток, в которых держат пленников, могут храниться у любого из служителей культа. Прошу тебя – найди ключи, спаси Кула и несчастных претендентов от ужасной участи!", progress = nil, completion = "К сожалению, Кулу придется смириться с очередным поражением. Нам уже не раз приходилось спасать его от самого себя. Жаль, что некоторые претенденты берут с него пример и начинают вести себя как представители Серебряного союза.", rewards = "Вы получите:\n\nПредмет #5Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14143] = {title = "Лапами кверху", objective = "Верните 10 украденных окорочков долгонога Гиране Окровавленной из Павильона Похитителей Солнца на Ристалище Серебряного турнира.", description = "Серебряный Авангард отправил сюда крейсерский корабль, перевозивший мясо долгоногов и прочие припасы для турнира, но он так и не добрался до пункта назначения. Наши разведчики доложили, что на него напали квалдиры, безжалостные пираты, которые бороздят эти моря.\n\nОни убили всю команду и перетащили груз на остров, который теперь называется Лагерь Хротгара. Посмотри на север – и увидишь его среди туманов. Может быть, ты поможешь нам вернуть украденные припасы? Если мясо долгоногов не прибудет вовремя, у нас может кончиться провизия.", progress = "Тебе удалось найти украденные припасы?", completion = "Мда, выглядят они... не очень, но есть можно. Крестоносцы будут рады узнать, что нам удалось спасти хоть какие-то припасы с корабля. А эти обглоданные куски можно будет отдать Серебряному союзу, что значительно улучшит мое настроение.", rewards = "Вы получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14144] = {title = "Милосердие Света", objective = "Воспользуйтесь Молитвенником исповедницы для проведения последнего обряда над телами 8 убитых туаликов, после чего вернитесь к Гиране Окровавленной в шатер Орды на Ристалище Серебряного турнира.", description = "Последняя проповедь Исповедницы Пейлтресс заставила меня задуматься о том, что нам недостаточно просто сражаться плечом к плечу с рыцарями Авангарда – мы должны помогать им исполнить свой долг.\n\nУ северного побережья находится Лагерь Хротгара – остров, который захватили морские пираты – квалдиры, убив всех обитавших на нем клыкарров. Возьми эту книгу и прочти отходную молитву рядом с телами павших жителей. Пусть их несчастные души обретут покой вдали от зловещих туманов острова.", progress = "Ты позаботился о душах убитых туаликов?", completion = "&lt;Гирана берет у вас молитвенник.&gt;\n\nСпасибо. Мы редко общаемся с крестоносцами с глазу на глаз, но Исповедница Пейлтресс многому научила меня во время своего пребывания на Ристалище.", rewards = "Вы получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14145] = {title = "Кстати, чем питаются йети?", objective = "Тайлос Вестник Зари из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести ему 3 куска мяса акулы Северного моря.", description = "Рыцари поймали огромного йети по кличке Ледяной Рев, который будет участвовать в гладиаторских боях, и поручили нам тренировать и кормить его.\n\nЖаль, им не понравилась моя идея отдать ему на растерзание парочку представителей Серебряного союза. Эта тварь предпочитает мясо акул, так что тебе придется отправиться за ним на \"Багровый Рассвет\", который стоит на якоре к северу пролива. Возьми свежую наживку из бочек на борту и брось ее в воду – она привлечет внимание акул.", progress = "Надеюсь, ты принес еду для Ледяного Рева – иначе мне придется перевести его на диету из представителей Серебряного союза.", completion = "Я рад, что мы справились с этой задачей. Пусть это была не самая почетная миссия на свете, но раз уж мы заключили договор с Серебряным Авангардом, мы должны выполнять все, что они от нас потребуют. Во всяком случае, это выгодно отличает нас от Серебряного союза.", rewards = "Вы получите:\n\nПредмет #5Печать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14146] = {title = "Защитить врата!", objective = "Подрядчик Жаднюк просит вас поспешить к задним вратам Оргриммара и убить 20 ночных эльфов-налетчиков.", description = "Боже, что происходит?\n\n<Вопли, крики и шум битвы наполняют радиоэфир.>\n\n<имя>! Сейчас же возвращайся сюда. Спеши к вратам – на нас напали!\n\nПомоги нам дать отпор захватчикам. Я сейчас заряжу твой гранатомет!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14151] = {title = "Багровый рубин", objective = "Линзи Черноболт просит вас успешно трансмутировать пять эпических драгоценных камней с помощью алхимии. Можно трансмутировать аметрин, око Зула, страхолит, царский янтарь и величественный циркон.", description = "Багровый рубин обработать непросто – это самый изысканный камень во всем Нордсколе. На солнце он сияет подобно багровой хрустальной розе.\n\nНо прежде, чем я передам тебе рецепт, тебе придется сделать пять эпических трансмутаций драгоценных камней. Можешь создавать любые камни, даже одинаковые.\n\nВозвращайся, когда будешь <готов/готова>.", progress = nil, completion = "Отлично, Выдрыч.\n\nСмотри и учись – весь фокус в том, чтобы выровнять грани вот так...", rewards = "Вы изучите:\n\nТрансмутация: багровый рубин\n\nСледующее заклинание будет наложено на вас:\n\nТрансмутация: багровый рубин\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14152] = {title = "Спасательная операция на море", objective = "Отправляйтесь в Северное море и убейте 8 врайкулов-берсерков и 3 врайкулов-гарпунеров, напавших на \"Гребень Волны\".", description = "Послушай, чемпион: капитан Эллеан Гребень Волны повела свой корабль на север, чтобы изгнать квалдиров из Лагеря Хротгара, но по пути наткнулась на банду пиратов, направлявшихся к Ристалищу. К несчастью, квалдиры значительно превосходят по численности команду Эллеан, и нашим морякам все труднее сопротивляться натиску бандитов.\n\nОтправляйся на север, к кораблю в Проливе Хротгара, который находится между Ристалищем и Лагерем Хротгара, и помоги капитану отразить атаку пиратов. Схватка происходит на востоке пролива.", progress = nil, completion = "Похоже, дела обстоят еще хуже, чем мы предполагали. Но с твоей помощью мы смогли спасти многих членов команды \"Гребня Волны\".", rewards = "Вы получите:\n\nПечать чемпионаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14153] = {title = "Банкет", objective = "Наденьте свой потрясный прикид для вечеринки (темные очки, новый стильный костюмчик и блестящие украшения) и отправляйтесь развлекать 10 кутил из Кезана, собравшихся у бассейна в штаб-квартире ТКК.", description = "Ого! Ничего себе! Да тут собрался весь цвет кезанского общества! Кому какое дело до несчастного дракона?\n\nМы решили устроить банкет у бассейна. Гости, похоже, довольны. И все ждут тебя!\n\nТак что давай наряжайся, иди к бассейну и общайся с гостями. Я тоже скоро приду... Только схожу возьму вещи.", progress = nil, completion = "Как все здорово получилось. Банкет удался на славу!\n\nЭ... Что это?", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14154] = {title = "На расстоянии укуса", objective = "В течение 2 минут сдерживайте натиск воргенов на крыше тюрьмы Гилнеаса.", description = "Один из этих вшивых щенков хорошенько зацепил Демпси, и его все еще нельзя переносить, пока кровотечение не остановится.\n\nНам надо удержать позицию всего на несколько минут. Помоги нам дать отпор этим чудовищам, <брат/сестра>!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Наручи Врат КоролевыКушак ДарияПерчатки ДемпсиВы получите:\n\n"}
MultiLanguageQuestData['ru'][14155] = {title = "Арборицид", objective = "Воспользуйтесь крошшером, чтобы уничтожить древня с заставы Талрендис. Если потеряете крошшер, можете воспользоваться запасным, его можно взять у задних врат Оргриммара.", description = "Ну, как тебе этот крошшер? Думаю, я могу подключить аварийные источники питания – в случае чего можно будет перейти на них.\n\nСлушай, эти ночные эльфы черпают силу у древа войны, которое растет к западу от ворот. Это большое, гигантское дерево. Ты знаешь, что делать! Уничтожь его!\n\nЭто твоя миссия!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Арборицидная секираОтрубленная конечность древняКинжал дровоколаВы получите:\n\n"}
MultiLanguageQuestData['ru'][14157] = {title = "Старые распри", objective = "Поговорите с капитаном Бродериком в Каменной тюрьме, что в Гилнеасе.", description = "Как только ни называли лорда Дария Краули – мятежником, предателем, террористом...\n\nДо начала гражданской войны я считал его своим другом.\n\nЯ не виню его за то, что он возглавил восстание против меня. Мы выстроили тридцатиметровую стену между его землями и Гилнеасом... но у нас не было иного пути.\n\nКак бы то ни было, сейчас нам нужен такой человек, как Краули.\n\nПроникни в Каменную тюрьму и узнай у капитана Бродерика, где содержится Краули. Я бы послал одного из своих людей, но, боюсь, наши старые распри могут помешать переговорам.", progress = nil, completion = "Седогрив хочет спасти Краули? Неужели наш король сошел с ума?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14159] = {title = "Арсенал мятежного лорда", objective = "Поговорите с Джосайей Авери в Военном квартале Гилнеаса.", description = "Арсенал, о котором упомянул Краули – это подвал в здании, которое находится на западе от этого места.\n\nДа, меня тоже беспокоит, что находящееся там оружие было пронесено в город врагами, но сегодня оно может спасти жителей Гилнеаса.\n\nРазыщи Джосайю Авери и конфискуй арсенал мятежников. Пусть это оружие послужит благому делу.", progress = nil, completion = "Не смотри на меня! Оставь меня в покое!", rewards = "Следующее заклинание будет наложено на вас:\n\nForce Cast Summon Josiah"}
MultiLanguageQuestData['ru'][14160] = {title = "Список заслуг", objective = "Доставьте Список заслуг Тимоти Джонсу в Даларан.", description = "В этом свитке перечислены многие великие достижения, полученные |3-4(<имя>) в области ювелирного искусства.\n\nОтнесите его Тимоти Джонсу и получите причитающуюся награду.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][14161] = {title = "Удар по василискам", objective = "Убейте 10 серокаменных василисков в карьере у подножья горы.", description = "Мы передвинули целую гору из-за карьера по добыче минералов внизу. Но мы не подумали о подземных василисках, которые теперь стали, гм, наземными. Ты выглядишь <инициативным/инициативной> – отправляйся туда и устрани эту помеху, а я тебя чем-нибудь отблагодарю.", progress = nil, completion = "Хорошо, хорошо. Одной головной болью меньше.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14162] = {title = "Отчитаться Хорзаку", objective = "Найдите Хорзака Кругоглода на оргриммарской пересадочной станции ракетной дороги в Азшаре.", description = "Ты первоклассно <выполнил/выполнила> работу по лесозаготовкам. Но теперь говорят, что не хватает камней. Ты <думал/думала>, что если мы можем двигать горы, то собрать кучу камней – для нас раз плюнуть?..\n\nНу, это не моя проблема. Может быть, ты этим займешься? Поговори с Хорзаком Кругоглодом перед оргриммарской пересадочной станцией ракетной дороги. Может, ты сможешь ему помочь. Иди по дороге на северо-восток и найдешь его на ракетной башне.", progress = nil, completion = "Ты пришел помочь? Подпиши этот отказ от компенсации убытков. И вот эту статью о запрещении конкуренции. А теперь начнем!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14163] = {title = "Призыв к оружию: Остров Завоеваний", objective = "Победите на поле боя Острова Завоеваний и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Чем ближе мы к схватке с Королем-личом, тем очевиднее тот факт, что Орда стоит на пути к нашей победе в Ледяной Короне.\n\nЧтобы отрезать нам путь к Острову Завоеваний, они выслали элитную армию стражей, известную как Кор'крон. Стоит ли говорить о том, насколько стратегически важен этот клочок земли? Я поручаю тебе, <имя>, одержать победу в сражении за остров!", progress = nil, completion = "Пока на нашей стороне сражаются такие солдаты, как ты, Ренгольд, Орде никогда не взять над нами верх.", rewards = "Вы получите:\n\nОчки арены"}
MultiLanguageQuestData['ru'][14164] = {title = "Призыв к оружию: Остров Завоеваний", objective = "Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды, на Озеро Ледяных Оков, в Даларан или Шаттрат.", description = "Вскоре мы добьемся победы в Нордсколе... но для начала нам надо закрепиться в Ледяной Короне, наладить поставки продовольствия и подкреплений.\n\nОстров Завоеваний представляется мне идеальным плацдармом – это богатое ресурсами место легко защитить от нападений. Однако похоже, что Альянс пришел к такому же выводу и послал Седьмой Легион навстречу нашим войскам.\n\n<имя>, отправляйся туда и сделай все для нашей победы!", progress = nil, completion = "Ничто не помешает нашей победе. За Орду!", rewards = "Вы получите:\n\nОчки арены"}
MultiLanguageQuestData['ru'][14165] = {title = "Хладный камень", objective = "Найдите в карьере у подножья горы окаменевшего горняка и принесите его Хорзаку Кругоглоду на оргриммарскую пересадочную станцию ракетной дороги.", description = "Рабочих хлебом не корми – дай пожаловаться. То изнурительная многочасовая работа, то низкая зарплата, то василиски превращают их в камень. Вечно им что-нибудь не так!\n\nНо я тут подумал, что, может быть эти превращения – выгодное дело. А вдруг они превращаются в камень высокого качества? И тогда мои нытики принесут мне гораздо больше дохода в качестве роскошных строительных материалов, нежели в качестве рабочей силы! Найди какого-нибудь окаменевшего горняка и принеси его сюда.", progress = nil, completion = "Ну-ну, давай посмотрим, что ты тут принес…\n\n&lt;Хорзак рассматривает раздробленные остатки бедного окаменевшего рабочего.&gt;\n\nТут одни крошки! Мало толку. Даже хорошей плитки на пол из него не сделать. Работают мои шахтеры не блестяще, но кирпичи из них и вовсе никакие.\n\n&lt;Вздыхает.&gt; Думаю, надо их оживить. Тогда мои затраты хоть немного окупятся.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14166] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому даларанскому духу на кладбище Даларана.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!\n\nКажется, рецепт можно купить у Чепмана.", progress = "Ты уже принес поминальный хлеб?", completion = "Какой же все-таки вкусный этот поминальный хлеб!\n\nПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!", rewards = "Вы получите:\n\nМрачная марионетка"}
MultiLanguageQuestData['ru'][14167] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу дворфа на кладбище Стальгорна.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!\n\nКажется, рецепт можно купить у Чепмана.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМрачная марионетка"}
MultiLanguageQuestData['ru'][14168] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу гнома на кладбище Стальгорна.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!\n\nКажется, рецепт можно купить у Чепмана.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14169] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу дренея на кладбище Экзодара.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестаралась... и съела все, что они приготовили для меня! Даже крошки подмела!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я была бы очень благодарна!\n\nКажется, рецепт можно купить у Чепмана.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14170] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу ночного эльфа на кладбище Дарнаса.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!\n\nКажется, рецепт можно купить у Чепмана.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМрачная марионетка"}
MultiLanguageQuestData['ru'][14171] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу эльфийки крови на кладбище Луносвета.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестаралась... и съела все, что они приготовили для меня! Даже крошки подмела!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я была бы очень благодарна!\n\nКажется, рецепт можно купить у Чепмана.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМрачная марионетка"}
MultiLanguageQuestData['ru'][14172] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу Алдора на кладбище Шаттрата.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестаралась... и съела все, что они приготовили для меня! Даже крошки подмела!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я была бы очень благодарна!\n\nКажется, рецепт можно купить у Чепмана.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14173] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу Провидца на кладбище Шаттрата.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!\n\nКажется, рецепт можно купить у Чепмана.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14174] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу Отрекшегося на кладбище Подгорода.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!\n\nКажется, рецепт можно купить у Чепмана.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМрачная марионетка"}
MultiLanguageQuestData['ru'][14175] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу орка на кладбище Оргриммара.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!\n\nКажется, рецепт можно купить у Чепмана.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14176] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу таурена на кладбище Громового Утеса.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!\n\nКажется, рецепт можно купить у Чепмана.", progress = "Ты уже принес поминальный хлеб?", completion = "Какой же все-таки вкусный этот поминальный хлеб!\n\nПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14177] = {title = "Благодарный покойник", objective = "Принесите поминальный хлеб веселому духу тролля на кладбище Оргриммара.\n\nЧтобы увидеть дух, используйте оранжевые бархатцы.", description = "Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!\n\nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!\n\nКажется, рецепт можно купить у Чепмана.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14178] = {title = "Призыв к оружию: Низина Арати", objective = "Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Беда битвы на несколько фронтов, <парень/подруга>, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!\n\nНам каждый день требуется подкрепление. Сегодня войскам в Низине Арати требуются отважные бойцы.\n\nИди, <имя>, и принеси нам победу. Мы не можем позволить Ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!", progress = nil, completion = "Превосходные новости,|3-6(Паладин)! Еще несколько подобных тактических побед – и Орда никогда не оправится от поражения.", rewards = "Вы получите:\n\nОчки арены"}
MultiLanguageQuestData['ru'][14179] = {title = "Призыв к оружию: Око Бури", objective = "Победите на поле боя Ока Бури и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Битва с Ордой не знает границ, <имя>. Даже в Запределье старая ненависть может вспыхнуть с новой силой, склонив чаши весов войны в пользу одного из противников.\n\nОтправляйся в Око Бури и убедись, что Альянс одержит верх в Запределье, как и по всему Азероту.", progress = "Говори же, Бракоделл! Есть ли вести с фронтов?", completion = "Мы еще на шаг приблизились к победе над Ордой. Нельзя позволить, чтобы наш враг чувствовал себя в безопасности.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14180] = {title = "Призыв к оружию: Ущелье Песни Войны", objective = "Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.\n\nНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!", progress = nil, completion = "Отличная работа, Космакс. Мы должны любой ценой защищать наши границы!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14181] = {title = "Призыв к оружию: Низина Арати", objective = "Победите на поле боя Низины Арати и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Альянс вот-вот захватит Низину Арати! Мы немедленно должны послать туда подкрепление, иначе все наши труды пойдут прахом.\n\nНе медли, <класс>, отправляйся в Низину Арати и сокруши врагов. Орда победит!", progress = nil, completion = "Ты покрыл славой знамена Орды, Баронгеддон. Твоя сегодняшяя победа открыла путь к многим славным свершениям!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14182] = {title = "Призыв к оружию: Око Бури", objective = "Победите на поле боя Ока Бури и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Мы будем сражаться с врагами повсюду – в Азероте и Запределье. \n\nНельзя позволить Альянсу закрепиться в Оке Бури. Брось им вызов сегодня, ибо завтра может быть слишком поздно!", progress = "Ты вернулся с вестями о нашей победе?", completion = "Мы гордимся тобой, Рэймондс. Враг должен знать, что ему нигде не укрыться от нашего возмездия!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14183] = {title = "Призыв к оружию: Ущелье Песни Войны", objective = "Победите на поле боя Ущелья Песни Войны и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.", description = "Альянс – опасный противник, <имя>. Они заявляют, что защищают Ясеневый лес, пытаясь оправдать нападения на наши территории в Степях.\n\nНо сегодня у нас появилась возможность вытеснить противника с наших земель раз и навсегда! Отправляйся в Ущелье Песни Войны и отбери то, что по праву принадлежит нам!", progress = nil, completion = "Орда в долгу перед тобой, Баландэрси. Твой народ может гордиться отвагой, проявленной тобой на поле боя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14184] = {title = "Мое время прошло…", objective = "Выполняя последнюю волю Фуриена в Тефрис-Аране, садитесь на его дракондора, отправляйтесь на Пост Фуриена и расскажите его сестре Серелии о смерти брата.", description = "<Фуриен слабо машет рукой, подзывая вас подойти ближе, и с трудом выговаривает слова.>\n\nТак нелепо… неосторожно… попал под огонь Альянса…\n\nНужно сказать сестре… чтобы она знала…\n\nВозьми моего дракондора, <раса>… он отвезет тебя к ней…\n\n<Фуриен умирает.>", progress = nil, completion = "Что?!\n\nФуриен?! Мой брат убит?\n\nОни за это заплатят! Все до единого!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14188] = {title = "Месть за Фуриена", objective = "По просьбе Серелии поговорите с Сорремом на Посту Фуриена.", description = "Нет, я не верю!\n\nМой брат погиб… убит этими ублюдками из Альянса!\n\nОни за это заплатят, <раса>! Они еще пожалеют, что родились на свет!\n\nМогу я рассчитывать на твою помощь? Незадолго до гибели Фуриен занимался изучением древних артефактов в восточных землях. Тебе надо поговорить с Сорремом. Он должен знать, где проходили исследования брата.", progress = nil, completion = "Фуриена больше нет с нами…. Жаль… очень жаль.\n\nЯ помогу тебе отомстить за него.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14189] = {title = "Расшифровка", objective = "По поручению Соррема разыщите древние таблички.\n\nПобеседуйте с Наримаром на Посту Фуриена, чтобы отправиться туда, где Фуриен занимался своими исследованиями.\n\nПрилагается предмет: \n", description = "Да, Фуриен занимался каким-то важным исследовательским проектом. Я не знаю подробностей. Он ничего мне не рассказывал.\n\nК счастью, мне удалось получить его личный журнал. Но прочитать я его не могу – записи зашифрованы.\n\nНе исключено, что ключ к шифру найдется в восточных краях, где Фуриен проводил исследования.\n\nМожет быть, ты поможешь мне разгадать эту загадку, <класс>? Возьми записи и посоветуйся с Наримаром.", progress = nil, completion = "Сравнив знаки, начертанные на древней табличке, с записями Фуриена, вы замечаете явное сходство.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14190] = {title = "Идеальная призма", objective = "Снимите хрустальную подвеску с саботажника с заставы Талрендис в карьере у подножья горы.", description = "Должен быть способ оживить тех, кого василиски превратили в камень. Эти саботажники ночные эльфы, которые шастают вокруг моего карьера, должны что-то знать. Им-то взгляды василисков не приносят вреда!\n\nЯ хочу, чтобы ты <узнал/узнала>, в чем их секрет, <имя>. Расправься с несколькими саботажниками с заставы Талрендис, которые шатаются без дела позади карьера, и узнай, какое заклинание или что там они используют, чтобы противостоять василискам. Когда все сделаешь, сообщи мне об этом по радио из главной кузни.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14191] = {title = "По следам Фуриена", objective = "Следуя указаниям древних табличек в святилище Элуны, обойдите три места в Саргероне, где расположены самые примечательные руины.", description = "Вам удается прочесть отдельные фрагменты текста, но для того чтобы расшифровать записи в журнале, этого явно недостаточно.\n\nВы смотрите на северо-восток и вроде бы различаете вдалеке руины, изображение которых встречается в журнале.\n\nПохоже, эти развалины имели большое значение для исследований Фуриена.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14192] = {title = "Призмолом", objective = "Отнесите хрустальную подвеску в оружейный шкаф в штабе карьера у подножья горы.", description = "Если эта твоя призма настроена так, чтобы преломлять взгляд василисков, то мы можем использовать ее свойства и для обратного процесса. Нам только нужен источник энергии.\n\nВ оружейном шкафу справа от тебя есть прототип лазерного горного бура. Мне всегда нравилась эта штука, утомляло только то, что почти каждый день она кого-то разрезала на части. Возьми свой кристалл и вставь его на место линз в буре...", progress = "<Оружейный шкаф полон отвратительных сломанных механизмов, к некоторым прилипли отрезанные конечности гоблинов. Вы находите лазерный бур, заботливо уложенный в деревянный ящик, обитый бархатом.>", completion = "&lt;Вы вынимаете из бура линзы и вставляете на их место кристалл. Бур зловеще жужжит.&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14193] = {title = "Пара дынь решит любую проблему", objective = "Соберите 8 плодов дыни.", description = "Символы на руинах дают ясно понять: есть что-то особенное в древнем источнике, находящемся в святилище Элуны.\n\nТому, кто умоет в нем лицо, даются какие-то особые способности. Вот только источник давно высох... и его надо как-то наполнить, чтобы было чем умыться.\n\nРазмышляя над этой проблемой, вы замечаете плод дыни на земле под ближайшим деревом...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #8"}
MultiLanguageQuestData['ru'][14194] = {title = "Превоплощение", objective = "Воспользуйтесь превоплотителем, чтобы оживить окаменевших горняков в карьере у подножья горы.", description = "<Вас вызывают по ближайшему радио.>\n\nЭй, <имя>, ты <нашел/нашла> эту пушку? Хорошо! Только не направляй ее себе в глаз.\n\nНаправь эту малышку на моих окаменевших рабочих и преломленный свет снимет с рабочих окаменелость. Ну или расплавит их. Неважно. Верни моих рабочих в состояние, в котором они будут приносить прибыль! А если от процесса превоплощения у них поедет крыша, то надо их убить из соображений безопасности.", progress = "Ого, смотри-ка, все твои конечности на месте.", completion = "О, хорошо. Теперь эти халтурщики снова смогут работать. Ты заслужил часть прибыли – минус процент, причитающийся компании, конечно. Выбирай!", rewards = "Наручи из свежесодранной кожиОкаменяющее ружьеВы получите:\n\n"}
MultiLanguageQuestData['ru'][14195] = {title = "Многое проясняется", objective = "Воспользовавшись подсказкой, полученной из записей Фуриена, разыщите разрушенные чертоги Элуны на севере Саргерона.", description = "Что-то изменилось… может быть, это побочное действие ритуала омовения в фонтане Элуны.\n\nВы еще не до конца понимаете древний язык, на котором Фуриен вел записи в своем журнале, но вам стало значительно легче их читать.\n\nПохоже, что больше всего Фуриена интересовали руины в северных горах Саргерона. Он был уверен: там есть что-то такое, что поможет ему вытеснить силы Альянса из этих земель.\n\nВы уже знаете, что делать дальше: нужно найти эти руины и раскрыть их тайну.", progress = nil, completion = "Теперь вам понятно, почему все подсказки вели вас сюда.\n\nВы сразу узнали этот рунический камень из последней записи в журнале Фуриена:\n\n\"Древние почитали самоцветы, созданные этим таинственным объектом, поскольку считали их даром самой богини. Существовало поверье, что это не просто камни, но грозное оружие, способное защитить от любого врага\".", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14196] = {title = "Поджигатель", objective = "Создайте бушующий вихрь, убив 7 адептов Элуны рядом с огненным штормом.\n\nЕсли вы потеряете свой самоцвет вихря, возьмите еще один у древнего рунического камня вихря.", description = "Теперь вы свободно читаете и понимаете зашифрованные письмена.\n\nНа руническом камне написано, что здешние самоцветы обладают способностью вызывать огненный шторм.\n\nСуществует два способа, как превратить огненный шторм в мощнейшее оружие: либо в течение долгого времени поклоняться и верно служить Элуне, либо зарядить и усилить бурю духовной энергией павших врагов.\n\nГлядя на призрачных слуг Элуны, вы понимаете, что у вас нет ни времени, ни желания поклоняться вражеской богине…Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14197] = {title = "Выполнить план", objective = "Соберите 20 слитков железа в карьере у подножья горы в Азшаре.", description = "Железо из карьера хрупкое и содержит примеси, но если знать, кому дать взятку, то гоблинским стандартам качества оно соответствует. У Кругоглода проблемы с производительностью, но мои-то сроки никто не отменял. У меня есть план и его надо выполнить!\n\nОтправляйся в карьер у подножья горы и собери все слитки железа, какие найдешь. Должны получиться штабеля уже выплавленных и готовых к отправке слитков.", progress = "Ты подготовил груз к отправке?", completion = "Отлично! Когда речь идет о железе, количество важнее, чем качество.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14198] = {title = "Всадник бушующего вихря", objective = "Используйте силу самоцвета бушующего вихря на руинах Высоты Найджела. Призвав огненный шторм, убейте 40 защитников Высоты Найджела и сожгите 15 торговцев Высоты Найджела.\n\nЕсли вы потеряете свой самоцвет бушующего вихря, возьмите еще один у древнего рунического камня вихря.", description = "У вас есть повод гордиться: вам удалось раскрыть древнюю тайну адептов Элуны.\n\nТеперь вы владеете грозным оружием, способным причинить немалый ущерб врагу.\n\nВы смогли получить его благодаря неустанным трудам Фуриена, и будет справедливо, если мощь этого оружия обрушится на тех, кто лишил его жизни.\n\nЭти скоты из Альянса, засевшие на Высоте Найджела, сполна за все заплатят!", progress = nil, completion = "Ты молодец, |3-6(Паладин).\n\nТебе удалось завершить работу Фуриена и отомстить его убийцам.\n\nТеперь брат упокоится с миром и моя душа тоже будет спокойна. Прими это в награду за добрую службу.", rewards = "Плащ ловкости рукВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1Спокойствие ФуриенаМечущий искры ошейник\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14199] = {title = "Победный трофей: Черный рыцарь", objective = "Верховный маг Лан'далок из Даларана просит вас принести ему осколок души Черного рыцаря.\n\nЭто задание выполняется в героическом режиме.", description = "Мой коллега, Верховный маг Времиар, попросил меня предупредить тебя об опасности. Скоро ты будешь участвовать в Испытании чемпиона в Ледяной Короне. Остерегайся вмешательства со стороны соперника, известного как Черный рыцарь.\n\nПринеси мне осколок его души в доказательство того, что он больше не станет на пути Кирин-Тора. Мне было сказано, что в вашем противостоянии должен остаться лишь один.", progress = "Так Времиар был прав? Черный рыцарь действительно попытался вмешаться?", completion = "Рад видеть, что ты вернулся с победой! Воистину, ты чемпион не только Серебряного Авангарда, но и Кирин-Тора.\n\nОстается надеяться, что нанесенный тобой удар был смертельным, и мы больше не услышим об этом злодее.", rewards = "Вы получите:\n\nОчки справедливостиЭмблема триумфа"}
MultiLanguageQuestData['ru'][14201] = {title = "Тысяча историй на песке", objective = "Соберите 5 эльфийских артефактов в руинах вокруг озера Меннар в Азшаре.", description = "Руины вокруг озера Меннар, что к востоку отсюда, могут многое рассказать. Низшие расы – такие, как неуклюжие дворфы – воюют за правду кирками и лопатами. <Малинея морщит нос.> Мы прибегнем к более элегантным методам.\n\nМоя магия ясновидения, конечно, немного устарела, но все же у меня должно получиться приподнять покровы времени. Кости моих предков давно уже истлели, но какие-то их личные драгоценности еще могли уцелеть – принеси мне немного.", progress = "Сделала за меня черную работу?", completion = "&lt;Малинея сдвигает брови и начинает рассматривать артефакты, которые вы ей принесли.&gt;\n\nХм, получается, духи умерших по-прежнему навещают эти старые камни? Ну, Спящийпутя, раз это так, я рассчитываю на их помощь. Посмотрим, что они скажут…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14202] = {title = "Исследование озера", objective = "Проводите гоблина-геодезиста к трем устройствам исследовательского оборудования, установленного вокруг озера Меннар, и защищайте его, пока он снимает показания. Другого геодезиста всегда можно вызвать при помощи маяка геодезиста.", description = "Надо снести все эти грязные древние руины, если мы хотим извлечь всю пользу из Азшары. Посмотри на мою карту – видишь озеро Меннар, на востоке? Я скажу тебе, что вижу на ней я: будущий склад ракетного топлива!\n\nНо нам нужно хорошенько изучить местность, прежде чем мы начнем сносить, рыть, засыпать землей и заливать озеро асфальтом. Все мои исследователи перепуганы чем-то, что витает в тех краях. Отправляйся туда с одним из моих младших геодезистов и сними показания с оборудования, которое там установлено.", progress = "Кучка дохлых эльфов не помешает прогрессу. Не в мою смену!", completion = "Прекрасно! Теперь мы лучше знаем озеро и можем изменить его.", rewards = "Следующее заклинание будет наложено на вас:\n\nQuest Complete\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14203] = {title = "Промокший рецепт", objective = "Принесите промокший рецепт Кристи Стоктон в Даларан.", description = "Похоже, это остатки смеси, применяемой для изготовления очень крепкого вина. Возможно, владелец лавки \"Еще по сто\" заинтересуется этим рецептом...Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14204] = {title = "Из тени", objective = "Убейте 6 скрытней из стаи Кровавых Клыков.", description = "Он стал одним из них, да? Как мы можем сражаться с врагом, который может сотворить подобное с каждым из нас?\n\nЗнаешь, для начала мы могли бы воспользоваться арсеналом моего отца.\n\nПлохо только, что повсюду на улицах скрываются воргены. Возьми одного из моих мастифов – они все обучены выслеживать этих тварей.\n\nНадо расчистить путь, иначе мы не сможем вытащить пушки на поверхность.", progress = "Готово, Братецрога?", completion = "Превосходно. Я немедленно начну установку пушек.", rewards = "Палица бьющего тревогуАрбалет псаряЖезл тренера мастифовСледующее заклинание будет наложено на вас:\n\nЗаставить отослать чумного пса\n\nВы получите:\n\nВидавший виды посохПредмет #1"}
MultiLanguageQuestData['ru'][14209] = {title = "Субстанция в двигателе", objective = "Осмотрите бульдозер Дубника и соберите образцы неизвестной субстанции, которые засорили двигатель.", description = "Десять тысяч лет ветров и непогоды не разрушили эти древние руины. Поэтому я использую мой лучший и самый большой бульдозер, чтобы сравнять их с землей. Я дал ему имя – Марджен.\n\nНо недавно он меня подвел, <имя>. В тот самый момент, когда мы оказались в этих заколдованных лесах, его мотор испустил душераздирающий стон и перестал работать. И теперь мои инженеры говорят, что его клапаны чем-то забиты. Отправляйся туда и осмотри моторный отсек Марджена, а мне принеси образец того, что туда попало.", progress = "Марджен – дьявол, а не машина, не так ли?", completion = "Шарикоподшипники сломаны! Только посмотри на это – фу, ну и воняет же – мой бедный, бедный бульдозер!\n\nСпящийпутя, я хорошо разбираюсь в разных субстанциях и могу сказать, что эта не выглядит натуральной. Она сверхъестественная. Она от духов. Кажется, нам потребуется кто-то посильнее механика...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14212] = {title = "Готовность к жертве", objective = "Присоединитесь к лорду Дарию Кроули и убейте 30 ловцов из стаи Кровавого Клыка.", description = "Ты не <обязан/обязана> это делать, <имя>. Ты уже и так достаточно нам <помог/помогла>.\n\nНо если ты твердо <решил/решила> остаться... было бы глупо отсылать тебя прочь.\n\nМои люди заняли позиции внутри собора и приготовились дать отпор.\n\nЯ намереваюсь отправиться туда и лично отправить на тот свет как можно больше блохастых демонов. Если хочешь, можешь присоединиться ко мне в этой прогулке.", progress = nil, completion = "Возьми себя в руки, Братецрога.\n\nОни идут...", rewards = "Следующее заклинание будет наложено на вас:\n\nUpdate Bind Post-Sacrifices\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14213] = {title = "Десять фунтов плоти", objective = "Соберите 10 кусков плоти сатиров Саргерона и положите их на жаровню Элуны.", description = "Согласно записям Фуриена, эта древняя жаровня предназначена для жертвоприношений.\n\nЕсли вы правильно поняли расшифрованные фрагменты, всякому, кто положит в горящую жаровню плоть убитых врагов Элуны, дается божественное благословение.\n\nОглядевшись по сторонам, вы решаете, что сатиры, завладевшие этими землями, вполне подойдут в качестве жертвы.", progress = "Жаровня ждет подношения.", completion = "Вам даруется божественное благословение.", rewards = "Вы изучите:\n\nДар небес\n\nВы также получите:\n\nПредмет #10"}
MultiLanguageQuestData['ru'][14214] = {title = "Послание Седогриву", objective = "Поговорите с королем Генном Седогривом в Военном квартале.", description = "Время пришло, <имя>. Мы будем вооружаться здесь.\n\nСообщи королю Седогриву, что арсенал моего отца в его распоряжении. Здесь достаточно пушек, чтобы отбросить воргенов отсюда прямиком в северное море.", progress = nil, completion = "Я знал, что Краули примет правильное решение. Его арсенал нам очень поможет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14215] = {title = "Воспоминания мертвых", objective = "Отнесите перстень Калифы на берег озера Меннар. Прикоснитесь к духу Калифы, чтобы пережить ее воспоминания. Поговорите с другими духами, пока не узнаете секреты озера Меннар.", description = "Руны на найденном тобой перстне еще читаются: его вручили Калифе, когда ей дали доступ в Академию. Пара правильных заклинаний, и этот артефакт откроет нам ее душу.\n\nОтнеси перстень обратно на озеро Меннар. Теперь дух Калифы должен быть виден тебе на берегу. Прикоснись к ней, и перстень даст тебе возможность видеть мир ее глазами и пережить последние часы ее жизни. Изучи ее мысли, <имя>! Поговори с другими духами и узнай секреты озера Меннар...Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14216] = {title = "Загадка песчаникового камня", objective = "Достаньте песчаниковый камень со дна озера Меннар.", description = "Перед своей смертью Калифа должна была спрятать что-то на дне озера, мощный артефакт, на создание которого верховные маги потратили последние минуты своей жизни. Нет никаких сомнений в том, что Малинея Опустошительница Небес захочет увидеть этот артефакт, если, конечно, он все еще существует. Исследуй дно озера Меннар, чтобы найти его.", progress = "Ты вся мокрая. Нашла что-нибудь на озере?", completion = "Песчаниковый камень? О нем ходят легенды! Дай мне взглянуть на него.\n\nСпящийпутя, песчаниковые камни используются для изменения силовых линий магической энергии. Ты понимаешь, что это значит? Маги академии Меннар вовсе не оставались в стороне, руководствуясь ложной лояльностью. Они пожертвовали своими жизнями ради создания этого артефакта, пытаясь отвести энергию от портала, через который демоны проникали в Азерот. Тем самым они выиграли время и дали всему миру возможность собраться с силами! Никто не знал об этом. Какое открытие!", rewards = "Цаплевидные сапогиОтреставрированная меннаранская кольчугаВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14217] = {title = "Жертвоприношение сатиров", objective = "Соберите 10 кусков плоти сатиров Саргерона и положите их на жаровню Элуны.", description = "Как все забавно выходит: вы получаете благословение в храме богини ваших врагов!\n\nВпрочем, благословение никогда не лишнее, и вы собираетесь использовать эту возможность с максимальной пользой для себя.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nДар небес\n\nВы также получите:\n\nПредмет #10"}
MultiLanguageQuestData['ru'][14218] = {title = "Кровь и пепел", objective = "Убейте 80 ловцов из стаи Кровавого Клыка с помощью пушек повстанцев.", description = "Время пришло, <имя>. Если мы намереваемся сократить их численность, лучшего момента не придумаешь.\n\nМы заняли стратегически выгодную позицию, у нас есть достаточно оружия.\n\nОсталось узнать, хватит ли нам смелости... но я не думаю, что сейчас вижу перед собой труса.", progress = "Мы должны убить как можно больше этих тварей, Китбомба.", completion = "Ты молодец, Братецрога. Не каждый житель Гилнеаса мог бы совершить подобный подвиг на твоем месте.\n\nНо у нас кончаются боеприпасы. Пора перегруппироваться.", rewards = "Сапоги непреклонностиПоножи канонираВы получите:\n\n"}
MultiLanguageQuestData['ru'][14219] = {title = "Оружие поверженного врага", objective = "Соберите 20 сабель сатиров – возьмите с оружейных стоек или отберите у сатиров, обитающих в этих краях, – и сложите их у подножия статуи прислужницы Элуны.", description = "Вы сразу узнали эту статую – по рисунку в записях Фуриена.\n\nВы пока не смогли прочитать записи рядом с изображением, но по рисунку и так все ясно. После битвы оружие поверженного врага складывали у подножия статуи в обмен на какой-то божественный дар.\n\nПока вы размышляете над этим ритуалом, ваш взгляд привлекает блеск стали на ближайшей оружейной стойке…", progress = "Статуя стоит, как будто в ожидании.", completion = "Ритуал завершен, и вы получаете божественный дар.\n\nВы невольно задумываетесь о том, а что бы сказала Элуна, если бы узнала, кому она сейчас подарила свое благословение.", rewards = "Сандалии ритуалаПозолоченный панцирьОсновательный ременьВы получите:\n\nПредмет #20"}
MultiLanguageQuestData['ru'][14220] = {title = "Конец всего", objective = "Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14221] = {title = "Отступать, но не сдаваться", objective = "Поговорите с лордом Дарием Краули в Соборе Рассвета.", description = "У нас было достаточно оружия, чтобы продолжать вести гражданскую войну еще как минимум месяц, но численность воргенов так велика, что сейчас наши запасы практически на исходе.\n\nНе хотелось бы остаться без единого снаряда. Проберись обратно в собор и передай наше послание боссу – старина Краули наверняка уже знает, что делать дальше.", progress = nil, completion = "Мы отдали им все, что у нас было... но они все равно вернулись. Не беспокойся, Братецрога. Мы перебьем многих из них еще до заката.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14222] = {title = "Последний рубеж", objective = "Убейте 8 негодующих ловцов.", description = "Нас зажали в тиски, <имя>. Молись, если думаешь, что это тебе поможет.\n\nА теперь давай наберемся смелости и перебьем этих шавок.", progress = nil, completion = "Они... они куда-то делись.\n\nНе радуйся, Братецрога. Это плохая новость.", rewards = "Следующее заклинание будет наложено на вас:\n\nПроиграть ролик\n\nВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14223] = {title = "Спокойный сон капитана", objective = "Убейте Кохора по просьбе Соррема с Поста Фуриена.", description = "Мы – передовой пост сил в этом регионе, и отвечаем за то, чтобы заранее выявить возможных противников и избавить Орду от неприятных сюрпризов, когда начнется кампания в Пустошах.\n\nНедавно один из наших разведчиков был пойман и принесен в жертву адептами Пылающего Клинка в их крепости к востоку отсюда. С тех самых пор я постоянно получаю угрозы от одного из этих выскочек по имени Кохор.\n\nДни ордена сочтены, но я с удовольствием заплачу из собственного кармана тому, кто заткнет этого гада прямо сейчас!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14225] = {title = "Ты поймешь, когда увидишь", objective = "Найдите следы древнего ритуала призыва в крепости Громового Топора по просьбе Соррема с Поста Фуриена.", description = "Перед смертью Кохор упомнянул о призыве какого-то ужасного демона, который может угрожать всему региону.\n\nСкорее всего, он блефовал, но для очистки совести стоит проверить информацию.\n\nМы не можем ждать до того момента, когда вторжение Орды в Пустоши наберет силу. Обыщи крепость Громового Топора в поисках улик и предотврати трагедию, если угроза действительно существует.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14226] = {title = "Проблема под ногами", objective = "Воспользуйтесь личным чародейским помощником, чтобы обратить в насекомых 12 демонов, а затем прихлопнуть их.", description = "Посмотри на себя. Выполняешь поручения. <Такой ответственный/Такая ответственная>. Двигаешься все дальше и дальше… вперед и вперед!\n\nА впереди демоны! Разнообразные неприятные демоны. Демоны, которые бы оценили твои внутренности! Но не волнуйся. Нет-нет, нет оснований для беспокойства, я дам тебе помощника!\n\nПрицелиться, превратить в насекомое, прихлопнуть. Прицелиться, превратить в насекомое, прихлопнуть! Довольно эффективно. И довольно неопрятно... но все равно, не надо переживать. Нет-нет, не волнуйся, в конце концов не нам же это убирать!", progress = nil, completion = "&lt;Кажется, что верховный маг Ксилем исполняет какое-то подобие танца, когда поворачивается к вам.&gt;\n\nНе волнуйся и, самое главное, помни о том, что если выделения жуков попадут на тебя, ты пожалеешь… Впрочем, ты в любом случае пожалеешь. Твои ботинки и сейчас-то не очень хорошо пахнут, а завтра они будут просто вонять!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14227] = {title = "Голова на голове", objective = "Соберите 100 отбеленных черепов в Крепости Громового Топора, затем принесите их в круг призыва Пылающего Клинка, вызовите и убейте Назаргена.", description = "Так значит, это правда….\n\nНа пергаменте, найденном тобой в крепости Громового Топора, указаны подробности могущественного ритуала призыва. Это куда серьезнее, чем можно было ожидать от культа Пылающего Клинка.\n\nМы должны прервать этот ритуал любой ценой!\n\nВозможно, если нам удастся вызвать демона раньше назначенного срока, трагедии можно будет избежать.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Плащ опаленного черепаВам дадут возможность выбрать одну из следующих наград:\n\nПерстень решительного вмешательстваКолье заземления\n\nВы также получите:\n\nDeprecated Dwarven Squire's Pants"}
MultiLanguageQuestData['ru'][14230] = {title = "Физический труд", objective = "Верните Справочник изменника из лагеря Легаш.", description = "Кажется, местные демоны как следует получили и перестанут воровать наши чародейские справочники. Я сильно сомневаюсь, что большинство из них умеет читать, поэтому скорее всего они делают это просто назло нам.\n\nБольшая часть книг, которые они забрали, меня не очень беспокоит, но они похитили и Справочник изменника, который мне понадобится, если, конечно, есть какая-то надежда, что после \"испытаний\" Ксилема хоть кто-то из учеников вроде тебя останется в живых. Найди демонов в лагере Легаш к юго-востоку отсюда и отними у них Справочник изменника.\n\nЭто все. Беги.", progress = "И это снова ты… Полагаю, ты вернулся с моей книгой?", completion = "Потрясающе. Возвращайся к делам.\n\nСпасибо, малыш.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14231] = {title = "Useless quest record", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][14232] = {title = "Надрать уши", objective = "Принесите 25 ушей орков Пылающего Клинка Соррему на Пост Фуриена.", description = "Ни для кого не секрет, что Соррем презирает клан Пылающего Клинка, занявший крепость Громового Топора.\n\nДумаю, ему придется по вкусу, если кто-то задаст им трепку.", progress = "Что это такое, |3-6(Друид)?", completion = "Уши адептов Пылающего Клинка?\n\n&lt;Соррем улыбается.&gt;\n\nСпасибо, |3-6(Друид). Мы еще покажем этому проклятому культу, где мурлоки зимуют!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14233] = {title = "Орки умеют писать?", objective = "Отнесите полевой дневник Хамми Кофельнагель на Берег Кораблекрушения на Затерянных островах.", description = "Разбирая вещи мертвого орка, вы нашли полевой дневник. Он сильно намок, однако текст можно разобрать, хотя и с трудом.\n\nВы быстро пролистываете дневник и понимаете, что на его страницах изложена весьма интересная история. Как хорошо, что когда-то вы решили выучить язык орков!\n\nОказывается, боевые корабли Альянса стреляли не только по яхте торгового принца, но и по оркам. И вы припоминаете, что за минуту до того, как Альянс открыл огонь, мимо вас прошел боевой корабль орков. Может, корабли Альянса стреляли не в вас, а в орков?\n\nПроклятые орки! Это из-за них вас потопили!", progress = "Инклюзивен, тебе удалось найти что-нибудь интересное в пещере?", completion = "Орки? Их корабль потопили, и они оказались на острове? А теперь на этот остров прибыли и войска Альянса? Как ты думаешь, они убьют нас?\n\n&lt;Хамми задумчиво смотрит вдаль.&gt;\n\nЗнаешь, что? Кажется, пора потолковать с этими орками.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14234] = {title = "Враг моего врага", objective = "Доставьте полевой дневник Аггре в главный лагерь Орды на Затерянных островах.", description = "Мне жутко не хочется просить тебя об этом, но ведь не зря же тебе так много платят. Можешь отнести полевой дневник мертвого орка тому, кто всем заправляет у них в лагере?\n\nСудя по тому, что там написано, они должны быть где-то на вершине острова, так что иди вверх по склону, мимо Каджа'митовой пещеры, держи курс на юго-восток.\n\nНу, удачи, <имя>. Ты мне всегда <нравился/нравилась>.", progress = "<Орк смотрит на вас, и глаза ее сужаются.>\n\nДолжно быть, ты с того затонувшего гоблинского корабля с рабами. А что это у тебя в руке?", completion = "&lt;Аггра пытается вырвать у вас из рук полевой журнал, но потом останавливается и делает глубокий вдох.&gt;\n\nИзвини. Последняя пара дней была очень тяжелой для всех нас.\n\nМеня зовут Аггра. Мы – это все, что осталось от команды \"Ярости Дреки\".\n\nМожет быть, у нас получится сработаться. Ведь Альянс – наш общий враг. Остров кишит убийцами из ШРУ, и они не остановятся, пока хоть кто-то из нас будет жив.", rewards = "Трофейные наручиСапоги оркского разведчикаПоножи морякаВы получите:\n\n"}
MultiLanguageQuestData['ru'][14235] = {title = "Гибельная долина", objective = "Найдите Килага Жутеклыка в Гибельной долине на Затерянных островах.", description = "Наш охотник Килаг Жутеклык вместе с парой разведчиков отправился по этой тропе на запад, в долину. Они... ищут.. \"драгоценный груз\"... который мы охраняли, когда эти мерзавцы из Альянса потопили наш корабль.\n\nНо путь разведчикам преградили смертоносные растения.\n\n<имя>, докажи, что ты настоящий гоблин и <класс>. Отправляйся в Гибельную долину и найди Килага.", progress = nil, completion = "Гоблин, ты драться умеешь?\n\nРади твоего же блага надеюсь, что да. Иначе нам не пробиться через эти заросли растений-убийц.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14236] = {title = "Газонокосилка", objective = "С помощью газонокосилки в вашем гоблинском все-в-одном-чудо-поясе выкосите 100 растений в Гибельной долине.", description = "<У Килага едва находится время между выстрелами, чтобы взглянуть на вас, но на миг его взгляд останавливается на вашем гоблинском все-в-одном-чудо-поясе.>\n\nТут требуется креативное решение. Вытаскивай что-нибудь подходящее из этого пояса и приступай к работе!\n\n<По краткому размышлению вам приходит в голову одна идея, и она достаточно безумна, чтобы сработать!>", progress = nil, completion = "Я видел все собственными глазами – и все же едва могу этому поверить!\n\nМы обязаны тебе жизнью и благодарны, крошка-гоблин. Надеюсь, вскоре мы отплатим тебе за помощь.\n\nМогу я попросить тебя об одной маленькой услуге, пока мы с разведчиками продвигаемся дальше?", rewards = "Штаны из травяных волоконЖилет КилагаВысокие ботинки сорной травыСледующее заклинание будет наложено на вас:\n\nWeed Whacker: Quest Complete\n\nВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14237] = {title = "Движение вперед", objective = "Найдите Килага Жутеклыка и его разведчиков на Лесном наблюдательном пункте на Затерянных островах.", description = "Килаг уже должен был выйти на позицию. Следуй вперед, к Лесному наблюдательному пункту. Все остальные соберутся здесь и тоже скоро выдвинутся.\n\nИди по тропе на север, через Гибельную долину. Хотя благодаря твоим усилиям теперь она уже не такая и гибельная, верно?\n\nКилаг с разведчиками прячутся недалеко от тропы. Убийцы из ШРУ скоро их обнаружат, так что поторопись!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14238] = {title = "Инфракрасный = Инфрамертвый", objective = "Убейте 10 убийц из ШРУ.\n\nЕсли с вашим орком-разведчиком что-то случится, вернитесь к Килагу – возможно, он выдаст вам другого напарника.", description = "Тс-с, не шуми. Долина к северо-западу отсюда кишит убийцами Альянса.\n\nК сожалению, нам не удалось их обнаружить. Проклятые трусы! Прячутся и не хотят выходить на бой.\n\nНо гоблины славятся своими инженерными находками. Наверняка у тебя найдутся очки, которые позволят увидеть убийц!\n\nПоэтому я прошу тебя объединить усилия с одним из моих разведчиков и убить всех убийц из ШРУ, которые попадутся вам на пути.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Шпионская удавкаШпионский ломШпионские перчатки-душителиСледующее заклинание будет наложено на вас:\n\nInfrared = Infradead: Quest Complete\n\nВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14239] = {title = "Не иди к Свету!", objective = "Следующее заклинание будет наложено на вас:\n\n", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nDon't Go Into The Light!: Quest Complete\n\nВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14240] = {title = "К утесам", objective = "Поговорите с разведчиком Браксом, который находится на Затерянных Островах, на тропе, ведущей к северу от Дикой лощины.", description = "По моему приказу разведчик Бракс отправился к утесам на побережье.\n\nА тебя я посажу на Бастию. Двигайся по тропе и передай Браксу, что мы пойдем другим путем.\n\nМы попытаемся выбить Альянс с его плацдарма! Там и увидимся!", progress = nil, completion = "Привет, малыш-гоблин. Бастия быстрая, верно?\n\nПослушай, у нас есть одно очень важное дело. Ты нам поможешь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14241] = {title = "К гиролету!", objective = "Добудьте ключи от гиролета.", description = "Альянс похитил у нас кое-что очень важное для Орды. Сейчас оно находится на одном из их кораблей.\n\nНа другом краю плацдарма стоит гиролет. Иди к нему. Наши воины тебя прикроют.\n\nЗабери ключи от летающей машины у их агента.\n\nЛети к флагману, \"Караулу Возмездия\", и верни наш драгоценный груз!", progress = "Хм, это похоже на творение инженеров-гномов – с большим количеством ненужных деталей и мер предосторожности.", completion = "Проклятье, да что там с зажиганием?\n\nЭто будет просто чудо, если машина взлетит, не выкинув какой-нибудь штуки – не превратится в курицу, например, или не уменьшится до размеров муравья.\n\nСмотри, кто-то оставил мелочь в пепельнице! Интересно, что еще здесь есть?", rewards = "Перчатки пилотаПарашютная контактная манжетаРемень безопасности гиролетаВы получите:\n\n"}
MultiLanguageQuestData['ru'][14242] = {title = "Драгоценный груз", objective = "Обнаружьте местонахождение драгоценного груза в трюме корабля Альянса \"Караул Возмездия\" у побережья Затерянных островов.", description = "Они сказали, их \"драгоценный груз\", чем бы он там ни был, хранится на корабле Альянса \"Караул Возмездия\".\n\nВыход у вас только один... Забраться в эту штуковину и отправиться за грузом!", progress = nil, completion = "Если бы не ты, меня бы уже наверняка обратили в рабство и переправили в Штормград как почетный трофей.\n\nЭти псы альянсовские нашли меня на берегу без сознания и поместили в эту магическую клетку. В ней я не мог воззвать к стихиям.\n\nНо теперь ко мне вернулись силы!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14243] = {title = "Возмездие вождя", objective = "С помощью вихря стихий убейте 50 матросов Альянса.\n\nКогда это будет сделано, вас перенесут к Лесному наблюдательному пункту.", description = "Братья Земли и Огня, внимайте! Сестры Воды и Воздуха, услышьте мой зов!\n\nАзерот на краю гибели, самому его существованию угрожает опасность! Даруйте мне свою силу, как в древние времена вы наделяли ею моих предков. Позвольте мне сделать проводником вашей воли это дитя Кезана.\n\nДавайте покончим с теми, кто хочет воспрепятствовать нам в исцелении этого мира!", progress = nil, completion = "Ты справился с тем, что мало кому оказывалось под силу, Аукционер. Наш мир в долгу перед тобой – в большей степени, чем ты можешь себе представить.", rewards = "Крутящийся в вихре топорПосох смерчаВы получите:\n\n"}
MultiLanguageQuestData['ru'][14244] = {title = "Вперед и вверх!", objective = "Постарайтесь не погибнуть во время перелета через Зловещий пролив на ракете, запущенной из ракетной пращи.", description = "Пока ты <занимался/занималась> спасением вождя и всех нас от Альянса, штейгер Промоках соорудил вот эту ракетную пращу, чтобы перебросить нас через этот кишащий акулами пролив прямо на остров.\n\nК счастью, при кораблекрушении штейгеру удалось спасти Городок-из-табакерки. Когда ты его развернешь, у нас будет свой город. Хотелось бы поскорее... А то я уже и не помню, когда в последний раз спала в нормальной постели!\n\nПромоках ждет тебя на месте высадки. Отправляйся следующей ракетой.", progress = nil, completion = "Нефростии, я рад, что ты пережила полет… это не каждому удается!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14245] = {title = "Городок-из-табакерки", objective = "Заберитесь на гору взрывчатки и нажмите на поршень Городка-из-табакерки.", description = "В трюме корабля торгового принца был целый городок! Когда начался бой, мне удалось его стащить.\n\nХочешь принять участие в церемонии его развертывания? Тогда заберись на эту огромную гору взрывчатки и нажми на детонатор. И – ба-бах! – моментально построится город!", progress = nil, completion = "&lt;Кашляет.&gt;\n\nЭй! Где пристань?! Кто-то украл пристань и нефтезавод нашего Городка-из-табакерки!\n\nКто мог это сделать?\n\nГде торговый принц?", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14246] = {title = "Спасение перепелятников", objective = "Разложите 3 яйца перепелятников по гнездам и защищайте яйца от хищников, пока птицы их не увидят и не заберут.", description = "Этот когда-то бесплодный край превращается в цветущий сад, и обитателям пустыни остается все меньше пространства для жизни.\n\nОни вымирают. И больше всего нас тревожит сокращение численности перепелятников. Хищники уничтожают птиц, разоряют их гнезда, поедают яйца.\n\nЯ приобрел в Танарисе несколько яиц перепелятников и покрыл их защитным феромоном. Разложи эти яйца по гнездам – по одному в каждое гнездо – и проследи, чтобы они оставались в сохранности, пока не появится перепелятник и не заберет яйцо.\n\nЭто будет твой вклад в сохранение природного равновесия на этой земле.", progress = nil, completion = "Отлично сработано, |3-6(Друид).\n\nЭта земля у тебя в долгу.", rewards = "Легчайшие поножиСтеганые рукавицы собирателяВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14247] = {title = "Упрямые земли", objective = "По поручению Тунка из Обители Тунка отыщите необычный фрагмент ландшафта.", description = "Я выполняю задание Круга Кенария: превращаю бесплодную пустошь в цветущие сочные луга.\n\nЗемли к югу отсюда хорошо приняли перемены, но здесь что-то мешает озеленению – пустыня сопротивляется всем нашим усилиям.\n\nМожет быть, ты сумеешь найти причину.\n\nПрошу тебя, <раса>. Обойди эти края и разыщи источник сопротивления.", progress = nil, completion = "&lt;Вы смотрите по сторонам, изучаете взглядом горизонт, пытаясь понять, откуда взялся этот камень и кто мог его здесь оставить…&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14248] = {title = "Требуется помощь!", objective = "Поговорите со штейгером Промокахом у входа в Каджа'митовую пещеру на Затерянных островах.", description = "Вот это новости! Штейгер Промоках обнаружил на острове пещеру, полную каджа'мита! Это большая удача.\n\nКонечно, у всякой медали есть и оборотная сторона. Он взял с собой кое-кого из уцелевших, чтобы те помогли ему добыть руду, да только никто из них не вернулся.\n\nКаким безумием это ни кажется, но штейгер уверяет, что пещера кишмя кишит обезьянами... с кирками! И они добывают каджа'мит! Как такое вообще может быть?\n\nМожешь <сам/сама> отправиться на юго-восток, зайти в пещеру и посмотреть? Штейгера найдешь прямо у входа.", progress = nil, completion = "Босс! Э... ну, я типа понимаю, ты больше не босс, но... я рад тебя видеть!\n\nПросто не верится, да? Пещера, полная разумных и свирепых обезьян, копающих каджа'мит!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14249] = {title = "Приодеть Вилла", objective = "Добудьте 80 нетронутых перьев громоголова у гиппогрифов возле руин Нордрессы.", description = "Буду изумительным верховным магом! Великолепным! Если у меня не будет этих идиотских одеяний и шляпы, он не станет даже разговаривать со мной. Пффф.\n\nСамый необыкновенный верховный маг, какого только видела эта земля, не может быть одет во что попало. Я должен показать ему, что я особенный, и я знаю, как это сделать.\n\nИди и убей этих гиппогрифов. И принеси мне МНОГО перьев.\n\nТы меня <слышал/слышала>? Большую охапку перьев! Давай-давай, к тому моменту, когда вернешься, одеяние будет уже почти готово.", progress = "Мои одеяния выглядят неплохо. Ты принес перья?", completion = "Ха-ха! Прекрасно! Давай-ка по-быстрому соберем все вместе. Без сомнения, я произведу на архимага впечатление своим одеянием!", rewards = "Перьевые сапогиЖилет РоботроникаЛезвие ножницСледующее заклинание будет наложено на вас:\n\nForcecast Ruins of Nordressa Invs Update\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14250] = {title = "Возобновляемый ресурс", objective = "Воспользуйтесь чародейским зарядом, чтобы получить 5 порций оживленного базальта от Бальбоа в руинах Нордрессы.", description = "Нам снова нужен оживленный базальт. В округе есть только один надежный источник – это горный гигант по имени Бальбоа. Убивать его нельзя, если мы хотим получать базальт и дальше, так что нужно просто обрубить нужные куски за один раз.\n\nОн бродит к северо-востоку и к востоку отсюда. Найди его, заложи на его пути заряд, и потом прячься, пока не выстрелит. Когда он скроется, сможешь взять базальт и принести мне.", progress = "Я слышал взрывы. Не знаю, твои это были или нет… от гоблинов тоже бывает много шума.", completion = "Отлично. Теперь мы продержимся несколько часов, прежде чем придется идти за новой порцией.\n\nБальбоа не назовешь сообразительным, так что, надеюсь, мы еще некоторое время сможем пополнять запасы, пока до него не дойдет.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14251] = {title = "Новое начало", objective = "Соберите 15 жал скорпиона.", description = "Никогда раньше кентавры не забирались так далеко на север. Кто-то их надоумил!\n\nКак бы там ни было, я разорен. Я вложил все в этот груз.\n\nК счастью, ни один кентавр не сможет лишить меня гоблинской смекалки! Я начну с самого начала и построю империю!\n\n<Бизби замечает вдали скорпиона.>\n\nЯд всегда в ходу. Что скажешь, друг?", progress = "Посмотрим-ка на эти скорпионьи хвосты, друг.", completion = "Вот так я и начал.\n\nПродавал яд оргриммарским разбойникам. Ах-х, какие были деньки….", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14252] = {title = "Много золота за плохие хвосты", objective = "Соберите 15 хвостов старых василисков.", description = "Мне нужен полный ящик хвостов, <класс>! И не всякие хвосты подойдут. Мне нужны старые хвосты, даже древние. Самые дряхлые будут лучше всего.\n\nЧешуя на хвосте василиска становится крепче с возрастом, а не истончается, и в этом ее уникальность. Эти твердые чешуйки идеальны для производства брони.\n\nПрошло уже много лет с тех пор, как мне приходилось торговать чешуей ящеров, но может быть, это закалит меня! Если это возможно....", progress = "Как там поиск хвостов, Патриархкири?", completion = "Сойдет, |3-6(Друид).\n\nЕще пара таких друзей, как ты, и я вновь смогу подняться на ноги!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14253] = {title = "Оперите меня!", objective = "Соберите 25 перьев жуткого перепелятника.", description = "Скажи, <класс>, пока будешь исследовать пустыню, не сделаешь мне одолжение?\n\nПоищи жутких перепелятников. Их маслянистые перья лучше всего подойдут для оперения стрел, а правильному покупателю их можно продать за неплохую цену.\n\nК счастью для тебя, я знаю правильных покупателей!", progress = "Как продвигаются поиски перепелятников?", completion = "Ох ты, как много перьев, |3-6(Друид).\n\nПока не найду покупателя, смастерю-ка себе из них подушку!", rewards = "Наплечники длиннохвостого перепелятникаНабедренники на подкладке из перьевВысокие ботинки пронзающего когтяВы получите:\n\n"}
MultiLanguageQuestData['ru'][14254] = {title = "Тяжелый металл", objective = "Соберите 7 образцов элемента 116 и отнесите их Бизби из каравана Бизби.", description = "Вы почему-то уверены, что этот камень и есть причина того, что пустыня сопротивляется распространению растений.\n\nВы смотрите на запад и замечаете след из тлеющих обломков. Похоже, они как-то связаны с проблемой, о которой рассказывал Тунк.\n\nВас осеняет догадка, что, если убрать эти обломки, сопротивление пустыни исчезнет само собой.\n\nИ потом, их, наверное, можно как-то использовать?", progress = "Это там у тебя чего, |3-6(Друид)?", completion = "Ну-ка, ну-ка.\n\n&lt;Бизби осматривает куски руды.&gt;\n\nВот это да! У меня есть знакомый… Он отвалит за это хорошие денежки.\n\nОторвет прямо с руками и щедро заплатит.\n\nА это тебе, |3-6(Друид). Пусть это будут твои комиссионные.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14255] = {title = "Этель-Ретор", objective = "По поручению Серелии с Поста Фуриена отправляйтесь к Корре в Этель-Ретор.", description = "У нас немало врагов в этих землях – не хотелось бы еще прогневить и Круг Кенария.\n\nКогда мы построили этот форт, представители Круга обратились к нам с просьбой присмотреть за одной их исследовательницей.\n\nВ последний раз Корру видели в башне на западе. Правда, довольно давно. Так что пора бы ее навестить. Сделай мне одолжение, сходи посмотри, все ли с ней хорошо.", progress = nil, completion = "Ты пришел очень вовремя.\n\nНам грозит смертельная опасность.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14256] = {title = "Угроза с моря", objective = "Поговорите с Коррой и она вам покажет, чем опасны наги.", description = "Из всей команды, отправленной наблюдать за изменениями на этом побережье Пустошей, уцелела лишь я одна.\n\nЯ уже доложила начальству об опасном увеличении численности наг, но, похоже, без толку.\n\nОни решают другие проблемы, им явно не до моих изысканий, и поэтому я вынуждена обратиться за помощью к тебе, <чужеземец/чужестранка>.\n\nНо сначала я покажу тебе, с чем нам придется столкнуться.", progress = nil, completion = "Итак, теперь ты понимаешь. Это не просто компания из нескольких наг, а целая армия, организованная и способная причинить очень серьезный ущерб.\n\nТак ты согласишься помочь мне в моих исследованиях?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14257] = {title = "Охота на нагов", objective = "Соберите 10 костей наг, 30 образцов чешуи колдуний и 4 гребня воинов из клана Скользящего Плавника.", description = "Мы уже знаем, что наги – враги природного равновесия. И если прольется их кровь, я не стану терзаться угрызениями совести.\n\nНо их слишком много. Как бы мы ни старались, у нас все равно не получится уничтожить их всех – разве только слегка проредить их ряды.\n\nНо у меня есть план, <класс>. Ты будешь не только убивать врагов, но и собирать определенные компоненты, необходимые для моих дальнейших исследований…", progress = "Тебе удалось собрать все, что мне нужно?", completion = "Отлично сработано, |3-6(Разбойник). Но, боюсь, это только начало. Тебе предстоит еще многое сделать.\n\n&lt;Корра творит заклинание над компонентами, собранными с убитых наг.&gt;", rewards = "Следующее заклинание будет наложено на вас:\n\nСоздать костюм наги\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14258] = {title = "Обстрел", objective = "Принесите 5 снарядов для гоблинской мортиры из секретной лаборатории в Азшаре.", description = "После того как мы построили этот терминал ракетной дороги, наги начали двигаться на полуостров. Но в этом мире нет проблем, которые невозможно было бы решить при помощи огневой мощи! Мой папа всегда так говорил. До несчастного случая.\n\nКстати, у меня заканчиваются боеприпасы. Окажи мне услугу, собери снаряды для мортир, которые я сложил в секретной лаборатории к западу отсюда. Обеспечь меня боеприпасами, а я разрешу тебе пострелять!", progress = "Надеюсь, ты принес снаряды. Мне здесь абсолютно нечем стрелять!", completion = "Чудесно! Прекрасно! Прелестно!\n\nТеперь у меня есть боеприпасы для мортир, и я смогу прикрыть тебя, когда ты будешь атаковать наг к востоку отсюда. Воспользуйся этими знаками, чтобы отметить цели, а я полью огнем всю территорию. Устроим отличный, беспощадный, беспорядочный обстрел! Надеюсь, у тебя хорошая броня...", rewards = "Вы получите:\n\nСигнальная дымовая шашка"}
MultiLanguageQuestData['ru'][14260] = {title = "Под маскировкой", objective = "Используйте оберег Скользящего Плавника.", description = "Я создала колдовской амулет. Он придаст тебе облик нага, и ты сможешь проникнуть к ним под маскировкой.\n\nКроме того, ты будешь свободно говорить на их языке. Сами наги не смогут тебя разоблачить.\n\nНо будь <осторожен/осторожна>! Берегись акул и других морских тварей – избегай их любой ценой, иначе они распознают твой истинный облик и раскроют его перед нагами.\n\nИди. Встреться со жрицей Азшары, исполни ее поручение, если так будет нужно, – и, самое главное, разузнай, что им здесь надо.", progress = nil, completion = "Давай, шевелись! У нас еще столько дел!\n\nМне что, надо втолковывать каждому по отдельности, что и как делать?!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14261] = {title = "Ледяной холод", objective = "Воспользуйтесь Криохладом 16, чтобы убить 8 агатовых драконов.", description = "У меня есть идеальное решение для нашей проблемы с драконами. Мой Криохлад 16.\n\nИзначально я изобрел его для замораживания моих рабочих на время транспортировки и между сменами – в этом случае их не надо кормить, да и вообще думать о них. Правда, возникли некоторые... осложнения. Но для драконов это должно подойти!", progress = nil, completion = "Что? Ты не принес части тела драконов? Печально.\n\nТак и знал, что надо было сначала заставить тебя подписать контракт…", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14262] = {title = "Выпотрошить рыбку", objective = "Убейте 6 сынов штормов из клана Бича Злобы и 6 зовущих море из клана Бича Злобы.", description = "Борьба с существами, которые могут в любой момент исчезнуть в море и вынырнуть, где им заблагорассудится, действует мне на нервы. Но я не сдамся, пока в Азшаре не останется никого из им подобных.\n\nНаги из клана Бича Злобы забрались наверх по скалам и осаждают заставу с востока. Уничтожь их, <имя>. Вспори им брюхо, чтобы они поняли, что значит ярость Орды.", progress = nil, completion = "&lt;Торг оглядывает горизонт.&gt; А они все наступают! Они как чума, Чебоу. Но с твоей силой мы сокрушим их. Когда-нибудь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14263] = {title = "Расход тимьяна", objective = "Соберите 8 пучков тимьяна живого гнева возле руин Нордрессы.", description = "Тимьян живого гнева. Мне нужно еще! И побыстрее с этим, ладно?", progress = "Ты принес мне тимьян?", completion = "Прекрасно. Интересно, как совершенно обычные вещи становятся полезными под действием заклинаний такого рода.\n\nЕще столько надо узнать!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14264] = {title = "Морской бой", objective = "Убейте 5 слуг Нептулона. (Для того чтобы с ними сразиться, вы должны быть в обличье наги.)\n\nЕсли вы потеряете трезубец клана Скользящего Плавника, возвращайтесь к Валишж.\n\nЕсли вы потеряете оберег клана Скользящего Плавника, возвращайтесь к Корре в Этель-Ретор.", description = "Здесь появились приспешники Нептулона. Они очень стараются нам помешать и сбивают все наши планы. Очевидно, они догадались, зачем мы здесь.\n\nЧто лишь подтверждает мои подозрения: то, что мы ищем, где-то тут, в этих руинах!\n\nНашим воинам не одолеть элементалей воды! Возьми этот трезубец – он поможет тебе уничтожить никчемных прислужников Хозяина Приливов.\n\nКогда мы найдем то, что ищем, сам Нептулон содрогнется от страха!", progress = nil, completion = "Ряды врага поредели, и это отрадно.\n\nА ты, я смотрю, можешь стать нам достойным помощником…", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14265] = {title = "Твой наставник", objective = "Поговорите с сержантом Клизом в Военном квартале.", description = "Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.\n\nМы намереваемся двигаться дальше на юг, как только пересчитаем людей.\n\nКстати, чуть не забыла – тебя искал один человек. Некий Клиз утверждает, что был твоим наставником, и он хочет убедиться, что с тобой все в порядке.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14266] = {title = "Рывок", objective = "Поговорите с сержантом Клизом и выучите способность \"Рывок\". Затем используйте ее на воргене из стаи Кровавых Клыков.", description = "Ты <уцелел/уцелела>, <имя>! Значит, я хорошо тебя обучил.\n\nЖаль, что наши занятия пришлось прервать – но, если хочешь, я покажу тебе еще парочку приемов, которые могут спасти тебе жизнь в это непростое время.\n\nИспытай свои новые умения на воргенах стаи Кровавых Клыков, что обитают на западе.", progress = nil, completion = "Прекрасно!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14267] = {title = "Исследование святилища наг", objective = "Исследуйте святилище наг для Торга Двудроба.", description = "Наги построили в скалах несколько святилищ. Не знаю, зачем, <имя>, но, думаю, все это с целью укрепления сил наших противников. Мне нужен кто-то, кто бы пробрался туда и все узнал.\n\nОдно из ближайших святилищ слабо охраняется: перейди первый мост к востоку отсюда и затем направляйся на север к заливу. Увидишь небольшую площадку, там найдешь святилище. Исследуй его и сообщи мне о том, что узнаешь.", progress = nil, completion = "Камень в центре этого святилища испускает слабый свет и рокочет, как бурное море.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14268] = {title = "Глубокая тайна", objective = "По поручению жрицы Валишж разыщите древнюю гравировку Нептулона.", description = "Королева Азшара хочет отыскать вход в царство воды… уж не знаю, зачем.\n\nКак бы там ни было, она убеждена, что древние знали, где находится это место.\n\nМне поручили возглавить поисковую группу и осмотреть все руины в этом районе. Мы будем искать и не успокоимся, пока не найдем то, что ищем!\n\nНеподалеку отсюда, на севере, располагается обширный участок развалин. Возьми этот посох, он поможет тебе.\n\nИ не возвращайся, пока не найдешь то, что нужно найти!", progress = "Неужели?..", completion = "Да! Вы их нашли!\n\nГравировки Нептулона… Вне всяких сомнений, это они!", rewards = "Вы получите:\n\nПредмет #4Предмет #1"}
MultiLanguageQuestData['ru'][14269] = {title = "Кто-то ищет тебя", objective = "Поговорите с Лорен Укрывательницей в Военном квартале.", description = "Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.\n\nМы намереваемся двигаться дальше на юг, как только пересчитаем людей.\n\nКстати, чуть не забыла – тебя искала какая-то женщина. Некая Лорен... кажется, она расстроилась, узнав, что ты <уцелел/уцелела>. По-моему, она упомянула, что должна тебе денег.", progress = nil, completion = "Ой, привет! А вот и ты!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14270] = {title = "Осколок краеугольного камня", objective = "Найдите поблизости осколок краеугольного камня.", description = "Воздух вокруг этого странного камня потрескивает от избытка энергии. Сам камень гладкий и холодный, как лед. Если проносить над ним руку, он периодически пульсирует.\n\nПохоже, что от поверхности этого артефакта был отколот кусок в форме клина. Скорее всего этот \"осколок краеугольного камня\" – ключ к секретам артефакта. Обыщите земли возле храма и найдите осколок.", progress = "Камень силы наг пульсирует и жужжит.", completion = "Осколок встает на место и на поверхности камня внезапно проступают не видимые прежде руны, мерцая голубым и фиолетовым цветами. Поток чар, направленный к вашему телу, такой мощный, что у вас подгибаются колени.", rewards = "Следующее заклинание будет наложено на вас:\n\nЩит бури\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14271] = {title = "Доложиться Двудробу", objective = "Вернитесь к Торгу Двудробу на оргриммарскую южную конечную станцию ракетной дороги в Азшаре.", description = "Вокруг вас, обдавая холодком, пульсирует магическое поле. За этой волшебной стеной вы чувствуете себя в безопасности.\n\nТорг Двудроб хочет узнать, что вы тут обнаружили!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14272] = {title = "Потрошение", objective = "Поговорите с Лорен Укрывательницей и выучите способность \"Потрошение\". Затем убейте с помощью этой способности воргена из стаи Кровавых Клыков.", description = "Как я рада видеть тебя <живым и невредимым/живой и невредимой>! \n\nНет, у меня при себе нет твоего золота. <Сам/Сама> понимаешь, сейчас не время припоминать старые долги.\n\nПослушай, давай я лучше покажу тебе парочку приемов, которые могут спасти тебе шкуру в эти неспокойные времена. Согласись, это гораздо полезнее денег.\n\nА когда мы закончим урок, ты сможешь применить новые знания против воргенов из стаи Кровавых Клыков, что водятся на западе отсюда.", progress = nil, completion = "Не старайся прыгнуть выше головы. Просто помни все, чему я тебя научила.\n\nА теперь давай посмотрим, удастся ли нам выбраться из города целыми и невредимыми.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14273] = {title = "Странные знакомства", objective = "Поговорите с Витом Дарквокером в Военном квартале.", description = "Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.\n\nМы намереваемся двигаться дальше на юг, как только пересчитаем людей.\n\nКстати, чуть не забыла – тебя искал какой-то странный парень по имени Вит... жуткий тип, у меня от него мурашки по коже.\n\nОн все говорил о каком-то запретном знании.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14274] = {title = "Жертвенный огонь", objective = "Поговорите с Витом Дарквокером и выучите заклинание \"Жертвенный огонь\". Потренируйтесь применять это заклинание на воргенах из стаи Кровавых Клыков.", description = "Значит, это правда! Ты <уцелел/уцелела>!\n\nЯ уж боялся, что мне никогда больше не представится случай поделиться с тобой моим величайшим открытием. Послушай: из запретных книг Балсефота, скрытых среди демонических теней... Расшифровав сложнейшие тайнописи, я узнал великую тайну...\n\nЖертвенного огня!\n\nНу конечно, я поделюсь этим знанием с тобой... разве ты видишь здесь кого-то еще, кто мог бы оценить красоту и мощь подобного заклинания?\n\nА теперь иди и испробуй его на воргенах из стаи Кровавых Клыков, что водятся на западе.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14275] = {title = "Кто-то следит за тобой", objective = "Поговорите с ловчим Блейком в Военном квартале.", description = "Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.\n\nМы намереваемся двигаться дальше на юг, как только пересчитаем людей.\n\nКстати, чуть не забыла – тебя искал какой-то человек по имени Блейк. Сказал, что собирается искать спасения в лесах.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14276] = {title = "Верный выстрел", objective = "Поговорите с ловчим Блейком и обучитесь способности \"Верный выстрел\". Затем убейте с ее помощью двух воргенов из стаи Кровавых Клыков.", description = "Так, у меня для тебя есть хорошая и плохая новость.\n\nПлохая заключается в том, что в местных лесах воргенов еще больше, чем здесь... так что, по сути, спасаться нам негде.\n\nА хорошая новость – я все еще могу научить тебя кое-чему полезному. Кто знает, какие знания спасут нам жизнь в это нелегкое время...\n\nИспытай-ка новые навыки на воргенах из стаи Кровавых Клыков, что водятся на западе.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14277] = {title = "Зов магии", objective = "Поговорите с Мириам Пробудительницей Чар в Военном квартале.", description = "Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.\n\nМы намереваемся двигаться дальше на юг, как только пересчитаем людей.\n\nКстати, чуть не забыла – тебя искала какая-то волшебница по имени Мириам. Странная она, сказала что-то про то, что ты <должен быть готов/должна быть готова>...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14278] = {title = "В поисках сестры", objective = "Поговорите с сестрой Альмирой в Военном квартале.", description = "Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.\n\nМы намереваемся двигаться дальше на юг, как только пересчитаем людей.\n\nКстати, чуть не забыла – тебя искала сестра Альмира, одна из священнослужительниц. Она сказала, что тебе угрожает опасность, и только Свет может защитить тебя от неминуемой смерти.\n\nПо-моему, тебе надо с ней поговорить – она была очень обеспокоена.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14279] = {title = "Быстрое исцеление", objective = "Поговорите с сестрой Альмирой и выучите заклинание \"Быстрое исцеление\". Примените его дважды к раненому стражу.", description = "Тебе еще многое предстоит познать, <имя>, а я многому должна тебя научить.\n\nУвы, в эти тяжелые времена я вынуждена перейти сразу к самому главному уроку.\n\nНе бойся, <брат мой/сестра моя>: Свет укажет нам путь.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14280] = {title = "Ветра шепчут твое имя", objective = "Поговорите с Целестиной Урожайной в Военном квартале.", description = "Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.\n\nМы намереваемся двигаться дальше на юг, как только пересчитаем людей.\n\nКстати, чуть не забыла – тебя искала женщина-друид по имени Целестина. Сказала, что ветра прошептали ей твое имя.\n\nЧепуха какая-то, честное слово.", progress = nil, completion = "Благословение богам! Ты жив и в добром здравии!", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14281] = {title = "Чародейские стрелы", objective = "Поговорите с Мириам Пробудительницей Чар и выучите заклинание \"Чародейские стрелы\". Убейте с его помощью воргена из стаи Кровавых Клыков.", description = "Нас ждут нелегкие испытания, <имя>, и на этом пути потребуется вся сила духа, которой ты располагаешь.\n\nИногда даже этого оказывается недостаточно, и тогда приходится прибегать к огневой мощи.\n\nЯ знаю одно заклинание, которое может выручить тебя в подобной ситуации. Когда ты выучишь его, примени свои знания на практике и убей несколько воргенов из стаи Кровавых Клыков, что водятся на западе. Но помни, что новое заклинание получится использовать только после того, как ты применишь другое.", progress = nil, completion = "Ты так легко усваиваешь новые знания, что вскоре мне придется уступить тебе место учителя.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14282] = {title = "Раскрытая тайна", objective = "Отнесите древнюю гравировку Нептулона кенарийской исследовательнице Корре.", description = "Ты <старался/старалась> не зря, и не зря <рисковал/рисковала> жизнью.\n\nТы <узнал/узнала>, зачем наги явились к побережью у Пустошей, и <заполучил/заполучила> предмет их упорных поисков.\n\nЧто касается найденных тобой надписей, тут задача ясна…", progress = "Что тебе удалось узнать, |3-6(Разбойник)?", completion = "Я в тебе не ошиблась!\n\nВ одиночку ты сделал то, что не удавалось еще никому.\n\nОт этой находки Круг уже не отмахнется.", rewards = "Украшенный гербом ременьГоловной убор каменной бороздыКрушители мертвой хваткиСледующее заклинание будет наложено на вас:\n\nСнять костюм наги\n\nВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14283] = {title = "Омоложение", objective = "Поговорите с Целестиной Урожайной и выучите заклинание \"Омоложение\". Воспользуйтесь им, чтобы помочь раненому стражу.", description = "Наш народ и раньше пребывал на грани полного истребления, <имя>. Но тогда именно мы, друиды, хранители древнего знания, спасли всех от голодной смерти.\n\nКогда наше королевство отгородилось от остального мира, выдался особо неурожайный год. Но мы воззвали к милости земли, и она одарила нас щедрыми посевами.\n\nНынче мы тоже должны положиться на высшие силы. Подойди же ко мне и узнай, чему может научить природа.", progress = "Земля взывает к нам, Эльффус. И в эти тяжелые времена она не оставит нас без своей заботы.", completion = "Неплохо, неплохо. Возможно, у нас еще есть надежда...", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14284] = {title = "Месть загробника", objective = "Сядьте верхом на лорда Гидрониса и сразитесь со жрицей Валишж.", description = "Я Гидронис, слуга Нептулона, Хозяина Приливов, хозяина всех вод.\n\nАзшара и ее злобные наги воспротивились власти моего господина и объявили ему войну. Это лишь первая битва, а будут еще… я уверен. И борьба будет долгой и трудной.\n\nЯ сражался, как мог, <раса>, и выбился из сил.\n\nМои действия привлекли внимание их жрицы.\n\nВ одиночку мне с ней не справиться. Но вместе мы можем попробовать ее одолеть.", progress = nil, completion = "Жрицы больше нет…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14285] = {title = "Спасение в единстве", objective = "Поговорите с королем Генном Седогривом в Военном квартале.", description = "Боюсь, это все, чему я могу научить тебя сейчас, когда воргены буквально дышат нам в затылок.\n\nТеперь нам надо присоединиться к другим беженцам и направиться на юг. Нам сообщили, что там нас ждет король Седогрив.\n\nЕсли мы будем держаться вместе, то сможем выжить... особенно если ты сможешь прицепиться к кому-нибудь посильнее.", progress = nil, completion = "Ты правильно поступил, придя сюда. Если все жители Гилнеаса будут держаться вместе, никакой враг нас не одолеет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14286] = {title = "Спасение в единстве", objective = "Поговорите с королем Генном Седогривом в Военном квартале.", description = "Теперь ты <обучился/обучилась> всему, что может сохранить тебе жизнь в эти нелегкие дни.\n\nНам пора присоединиться к остальным беженцам. Кажется, кто-то упомянул, что на юге нас ждет король Седогрив со своей верной стражей.\n\nМы должны идти туда, ибо в единстве наше спасение.", progress = nil, completion = "Ты правильно поступил, придя сюда. Если все жители Гилнеаса будут держаться вместе, никакой враг нас не одолеет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14287] = {title = "Спасение в единстве", objective = "Поговорите с королем Генном Седогривом в Военном квартале.", description = "Теперь ты <обучился/обучилась> всему, что может сохранить тебе жизнь в эти нелегкие дни.\n\nНам пора присоединиться к остальным беженцам. Кажется, кто-то упомянул, что на юге нас ждет король Седогрив со своей верной стражей.\n\nМы должны идти туда, ибо в единстве наше спасение.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14288] = {title = "Спасение в единстве", objective = "Поговорите с королем Генном Седогривом в Военном квартале.", description = "Боюсь, это все, чему я могу научить тебя сейчас, когда воргены буквально дышат нам в затылок.\n\nТеперь нам надо присоединиться к другим беженцам и направиться на юг. Нам сообщили, что там нас ждет король Седогрив.\n\nЕсли мы будем держаться вместе, то сможем выжить... особенно если найдем сильных союзников.", progress = nil, completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14289] = {title = "Спасение в единстве", objective = "Поговорите с королем Генном Седогривом в Военном квартале.", description = "Теперь ты <обучился/обучилась> всему, что может сохранить тебе жизнь в эти нелегкие дни.\n\nНам пора присоединиться к остальным беженцам. Кажется, кто-то упомянул, что на юге нас ждет король Седогрив со своей верной стражей.\n\nМы должны идти туда, ибо в единстве наше спасение.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14290] = {title = "Спасение в единстве", objective = "Поговорите с королем Генном Седогривом в Военном квартале.", description = "Теперь ты <обучился/обучилась> всему, что может сохранить тебе жизнь в эти нелегкие дни.\n\nНам пора присоединиться к остальным беженцам. Кажется, кто-то упомянул, что на юге нас ждет король Седогрив со своей верной стражей.\n\nМы должны идти туда, ибо в единстве наше спасение.", progress = nil, completion = "Ты правильно поступил, придя сюда. Если все жители Гилнеаса будут держаться вместе, никакой враг нас не одолеет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14291] = {title = "Спасение в единстве", objective = "Поговорите с королем Генном Седогривом в Военном квартале.", description = "Теперь ты <обучился/обучилась> всему, что может сохранить тебе жизнь в эти нелегкие дни.\n\nНам пора присоединиться к остальным беженцам. Кажется, кто-то упомянул, что на юге нас ждет король Седогрив со своей верной стражей.\n\nМы должны идти туда, ибо в единстве наше спасение.", progress = nil, completion = "Ты правильно поступил, придя сюда. Если все жители Гилнеаса будут держаться вместе, никакой враг нас не одолеет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14292] = {title = "Враг наших врагов…", objective = "По поручению кенарийской исследовательницы Корры побеседуйте с Лордом Гидронисом.", description = "Ты <сослужил/сослужила> нам хорошую службу, <имя>.\n\nНаги по-прежнему представляют угрозу. Они сильны и опасны, но твоими стараниями мы отобрали у них очень важный артефакт.\n\nЯ сообщу о твоей находке своим коллегам. А сейчас у меня есть для тебя очередное задание. Загробник воды на острове Раназжар в одиночку противостоит непрестанному натиску нагов.\n\nРазыщи его и узнай, можем ли мы ему как-то помочь.", progress = nil, completion = "Я следил за твоими успехами, |3-6(гоблин).\n\nТы явился сюда очень вовремя. Помощь никогда не бывает лишней.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14293] = {title = "Спасти Креннана Аранаса", objective = "Спасите Креннана Аранаса.", description = "Подумать только, все эти годы после войны Краули прятал у себя в подвале достаточно оружия, чтобы сравнять с землей полгорода. \n\nИ вот теперь до этого может дойти...\n\nНо сейчас мы не можем открывать огонь – с другой стороны тюрьмы заперт в ловушке ни в чем не повинный человек.\n\nНет, он не простой житель, а самый талантливый алхимик из всех, что когда-либо ступали по этой земле. Когда-то его снадобье спасло мою новорожденную дочку, Тесс.\n\nВозьми мою лошадь и вызволи его из ловушки. Сделай все возможное, чтобы Креннан не пострадал!", progress = nil, completion = "Well done, &lt;имя&gt;.  We'll make sure Krennan makes it out of the city alive.", rewards = "Следующее заклинание будет наложено на вас:\n\nForcecast Cannon Camera\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14294] = {title = "Время перегруппироваться", objective = "Поговорите с королем Генном Седогривом на площади Седогрива в Гилнеасе.", description = "Мы сделали все, что могли. Скажи королю Седогриву, что нам удалось выиграть для него немного времени.\n\nУ меня такое чувство, что воргены недолго будут зализывать раны и скоро перейдут в наступление.\n\nВ таком случае нам придется отступить на запад к площади Седогрива. Это последнее место, которое мы можем удерживать, не чувствуя себя запертыми в ловушке.", progress = nil, completion = "У нас осталось не так уж много вариантов, Китбомба. Придется действовать решительно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14295] = {title = "Сестры моря", objective = "Убейте леди Силистру и леди Вестру, уничтожив их камни силы.", description = "Нападением на заставу руководят наги-ведьмы. Они отразили прямую атаку моих лучших пехотинцев, но там, где потерпели поражение другие, нам сможешь помочь ты.\n\nНайди и убей леди Силистру и леди Вестру на восточном краю скал, возле обломков древнего колосса ночных эльфов. Сначала тебе понадобится уничтожить камни власти, которые дают им силу. Не разочаруй меня, <класс>!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Жилет морской сестрыПерчатки сокрушителя змеевВы получите:\n\n"}
MultiLanguageQuestData['ru'][14296] = {title = "Смотри, куда идешь", objective = "Получите 6 энергетических зарядов, прикасаясь к силовым проводам при подъеме к Волшебному замку.", description = "Это одновременно и просто, и нет. Вдоль всего пути наверх тянутся силовые провода. Точно такие, как этот справа! Я знаю, что говорю.\n\nТак вот. Воспользуйся моими приспособлениями для прыжков, чтобы подняться к замку, и прикасайся ко всем проводам, какие увидишь по пути. Когда ты придешь ко мне наверх, ты <должен сам/должна сама> излучать энергию, иначе никак.\n\nИ не забывай все время двигаться, а то улетишь!", progress = "Нет-нет-нет, все не так. Ты должен был накапливать энергию, поднимаясь сюда, понимаешь?\n\nДавай еще раз и как следует!", completion = "Именно в этот момент большинство моих учеников спрашивает, есть ли какая-то внятная причина хранить энергию для портала в этих проводах, если собирать ее надо таким извращенным способом.\n\nКонечно же, причина есть! Я хочу увидеть, что вы предпримете… какую выберете стратегию, какие совершите ошибки, где будете сомневаться, в чем преуспеете. В этом истинный смысл всех испытаний.\n\nТак что, продолжим. Больше испытаний! Звучит волнующе, правда?!", rewards = "Заряженные одеянияМанящие наручиВы получите:\n\n"}
MultiLanguageQuestData['ru'][14297] = {title = "За освобождение", objective = "Воспользуйтесь железнокованными ключами сектантов и драконов, чтобы освободить 4 гоблинов-рабочих на Черной гряде.", description = "Еще когда мы начали строить эту башню, я уже знал, что от них будут одни проблемы. Присваивают наши взятки. Крадут наших рабочих.\n\nВ Азшаре многие строятся и рабочая сила недешева. Мне нужны мои люди обратно!", progress = nil, completion = "Спасибо, приятель. Вот твое вознаграждение.\n\nА теперь извини, мне надо заставить этих бездельников работать.", rewards = "Вы получите:\n\nПредмет #4"}
MultiLanguageQuestData['ru'][14299] = {title = "Пристанище Ксилема", objective = "Воспользуйтесь порталом в башню верховного мага Ксилема и найдите в башне Джоанну.", description = "Чудесно с твоей стороны! Приятно видеть. Есть, чему поучиться.\n\nТеперь ступай, возвращайся в мою башню. Джоанна тебе поможет. Я открою для тебя портал.", progress = nil, completion = "Добро пожаловать! Похоже, ты прошел все испытания и остался почти невредимым. Тем лучше для тебя, милый.\n\nТы выглядишь так, как будто пришел не просто так. С вопросом. Твои мысли так беспокойны, что мне сложно не услышать их.\n\nНу давай же, дружок. Спрашивай.", rewards = "Ботинки приютаКушак ДжоанныВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14300] = {title = "Испытание огнем", objective = "Пройдите испытание огнем, находясь среди огненных рун и не загоревшись в течение 10 последовательных вспышек.", description = "Испытание огнем… ооо… звучит пугающе, не так ли? Нет? Гм. Ну, тем не менее. Прежде всего: прикоснись к огненному кристаллу, после этого откроется портал к испытанию.\n\nЧтобы пройти испытание, тебе надо будет бегать между огненными рунами так, чтобы не загореться. Если продержишься достаточно долго, ты <победил/победила>!\n\nВот небольшая подсказка – когда руна остывает, раздается шипение, огонь перескакивает на новую руну. При желании ты сможешь разобраться. Ну или придется угадывать! Большинство именно это и делает.", progress = nil, completion = "Ого! Молодец! Это испытание тебя как следует разогрело.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14301] = {title = "Возвращение с докладом", objective = "Возвращайтесь в Этель-Ретор к кенарийской исследовательнице Корре.", description = "У нас получилось! Вместе мы одолели опасного противника.\n\nНептулон непременно узнает о твоей доблести, <класс>. Благодарю тебя от его имени… \n\nА теперь тебе надо идти. Скоро здесь будет небезопасно. Наги явятся мстить за свою жрицу.", progress = nil, completion = "Прими эту скромную награду, Магребинец.\n\nБлагодаря тебе мы выиграли драгоценное время!", rewards = "Длинный чешуйчатый лукЦелебные повязкиЖилет текущей водыПоскрипывающий ременьВы получите:\n\n"}
MultiLanguageQuestData['ru'][14302] = {title = "Рапорт начальству", objective = "Отнесите отчет Корры Карнуму в рощу Карнума.\n\nПрилагается предмет: \n", description = "Ты <сделал/сделала> немало для нашей борьбы против наг, <имя>. Но, боюсь, этого недостаточно…\n\nВот, я составила официальный рапорт о ситуации с нагами здесь, на месте.\n\nТеперь я уверена, что мои коллеги обязательно примут меры.\n\nОтнеси это донесение Карнуму. Ты найдешь его в роще в центре Кенарийских Зарослей, к юго-востоку отсюда. Он разберется, что делать дальше.\n\nСпасибо, <имя>. И прощай.", progress = nil, completion = "&lt;Карнум открывает конверт и читает отчет Корры.&gt;\n\nДействительно, тревожные новости, |3-6(гоблин), – впрочем, у нас тут других и не бывает.\n\nЭтот вопрос требует тщательного обсуждения. Я соберу совет. Если ты нам понадобишься, мы тебя позовем.", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14303] = {title = "Возвращение к Аггре", objective = "Сообщите Аггре о том, что произошло. Она находится на Затерянных островах, в главном лагере Орды.", description = "<имя>, вернись в главный лагерь Орды и передай Аггре, что мы живы.\n\nСкажи ей, я иду к Лесному наблюдательному пункту, а встретимся мы все в северо-западной части острова. Надеюсь увидеть тебя там.\n\nМы выследим воинов Альянса и перебьем их всех до одного!", progress = nil, completion = "&lt;Аггра смотрит на вас так, как будто не верит в то, что вы ей рассказываете.&gt;\n\nМеня трудно удивить, но если то, что ты говоришь, правда, то такого я никогда еще не слышала.\n\nСпасибо тебе, Нефростии.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14304] = {title = "Кровь на анализ", objective = "Принесите 10 напившихся крови пиявок.", description = "В Пустошах изменилась не только почва и флора. Животные, естественно, реагируют на изменения окружающей среды и меняются сами. Поле для изучения поистине безгранично.\n\nНо больше всего меня интересуют омоложенные рокочущие ящерицы, обитающие на западе.\n\nМне нужны образцы их крови.\n\nЕсли хочешь помочь, то возьми эту банку с пиявками и постарайся поставить их на ящериц.\n\nКогда пиявки напьются крови, собери их обратно в банку и принеси мне.", progress = "У тебя получилось взять образцы крови?", completion = "Думаю, этого хватит.\n\nСпасибо, |3-6(Маг).", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14305] = {title = "Время пожинать", objective = "Соберите 10 образцов дикого алоэ.", description = "В Круге Кенария все хорошо понимают, что этот чудесный оазис может высохнуть и исчезнуть буквально за несколько дней.\n\nМы должны соблюдать осторожность: не вмешиваться в происходящие здесь процессы, но поддерживать их и по возможности оберегать.\n\nПосле катаклизма в здешних местах появились новые виды растений.\n\nСобери мне образцы. Я хочу их изучить и понять, что они из себя представляют.", progress = "Ты принес нужные мне образцы?", completion = "Замечательные экземпляры, |3-6(нежить).\n\nЯ немедленно приступаю к работе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14306] = {title = "Прополка", objective = "Уничтожьте 7 выкорчеванных плеточников.", description = "Хотелось бы верить в лучшее, но реакция некоторых представителей флоры и фауны проходит не так, как мы планировали. В общем, этого и следовало ожидать при столь резком изменении экологической ситуации.\n\nВыкорчеванные плеточники – яркий пример упомянутой негативной реакции. Этот сорняк грозит захватить все поля на востоке и юге. Его надо уничтожить, пока он не причинил непоправимого вреда.\n\nВ связи с чем у меня к тебе просьба: если где встретишь этого паразита, вырывай его с корнем!", progress = nil, completion = "Прими мою благодарность от имени всех Пустошей, |3-6(эльф крови).\n\nСпасибо тебе!", rewards = "Шипоплеточные нарукавникиНаплеч заживления ранФитостойкий шлемВы получите:\n\n"}
MultiLanguageQuestData['ru'][14307] = {title = "Враждебный ветер", objective = "Уничтожьте 5 вихревых штормоходов.", description = "Ветер перемен дует в полную силу, <раса>. В том нет сомнений.\n\nЗдесь у нас столько дел, важных и спешных! Но самое главное на сегодняшний день – расширение нашего оазиса.\n\nМы даже не смели надеяться на столь бурный рост, и нам непонятны его причины. Однако сейчас мы столкнулись с одной проблемой.\n\nНа западе, на границе оазиса и песков, появились какие-то странные вихри, не дающие растениям проникать дальше в пустыню.\n\nТебе надо пойти туда и устранить это враждебное препятствие жизни!", progress = nil, completion = "Отлично сработано, |3-6(Паладин).\n\nТеперь я знаю, что тебе можно доверить и более важные поручения. И мы, несомненно, еще не раз обратимся к тебе за помощью.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14308] = {title = "Когда наука атакует", objective = "Воспользуйтесь огнеустранителем Х-21, чтобы потушить 8 очагов пожара и спасти 6 студентов-исследователей из пекла в секретной лаборатории.\n\nЕсли вы потеряете ваш огнеустранитель, возьмите еще один у ассистентки Грили на южной конечной станции ракетной дороги.", description = "Ты <видел/видела> взрывы по пути сюда? Секретная лаборатория охвачена огнем! Опять! Если мы не потушим этот огонь, будет достигнута критическая температура, и все расплавится.\n\nСмотри, я даю тебе канистру с экспериментальным многоцветным жидкогелем под давлением: это самый неустойчивый огненный ингибитор, какой только известен науке! (Держи канистру подальше от открытого огня.) Потуши огонь, залей водой моих студентов-исследователей и свяжись со мной при помощи переговорного устройства на центральном пульте управления.", progress = "<Скрипучий голос Грили раздается из множества колонок.>\n\nРакетная дорога – секретной лаборатории! Ракетная дорога – секретной лаборатории! Секретная лаборатория, отвечайте…", completion = "Прекрасно, Спящийпутя! А теперь надо отсоединить матрицу активной зоны реакций от топливного отстойника, а не то все это место взлетит в Запределье…", rewards = "Следующее заклинание будет наложено на вас:\n\nUpdate Zone Auras\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14309] = {title = "Успокоительное для кодо", objective = "Напоите 5 разъяренных кодо успокаивающим настоем.", description = "Как ты <сам убедился/сама убедилась>, столь стремительные изменения экологической обстановки влияют на представителей местной фауны как положительно, так и отрицательно.\n\nК востоку и югу отсюда все кодо будто взбесились. Они представляют серьезную угрозу, и надо немедленно принимать меры.\n\nЗаодно и проверим, верна ли моя теория. Я сделала настой на основе крови омоложенных рокочущих ящериц. Надеюсь, он успокоит разъяренных кодо.\n\nПомести его в тех местах, где бывают кодо. Только будь <осторожен/осторожна>! Не подходи к разъяренным кодо!", progress = nil, completion = "Отлично! Карнум будет доволен!\n\nПрими это в знак благодарности. От меня лично.", rewards = "Убор наездника кодоПыльное лассоТранквилизаторВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14310] = {title = "Ошибка сегментации: дамп памяти сохранен", objective = "Активируйте панель управления реактором и сопроводите азшаритовое ядро на южную конечную станцию ракетной дороги. Используйте огнеустранитель Х-21, когда ядро будет перегреваться.", description = "Поскольку мы выключили центральный реактор, я хочу, чтобы ты <доставил/доставила> мне его ядро. Это 100% очищенный азшаритовый кристалл, который одновременно и очень мощный, и очень опасный. И красивый. Драгоценный азшарит, формирователь миров будущего!\n\nОгромный рычаг слева от тебя освободит ядро и отправит его мне по системе рельсов. Температура ядра будет очень высока, поэтому по пути сюда тебе потребуется периодически охлаждать его при помощи огнеустранителя... и не позволяй температуре достигать критических значений!", progress = "Пусть тебя не беспокоят последствия горения химикалий в лаборатории. Волосы – не зубы, отрастут быстро.", completion = "Уф, с образцом все в порядке. И от него все еще идет пар! Спасибо тебе, Спящийпутя.\n\nАзшарит загадочен, окружен тайнами и опасен. Дрек настаивает, чтобы мы узнали побольше об этой странной субстанции.", rewards = "Следующее заклинание будет наложено на вас:\n\nUpdate Zone Auras\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14311] = {title = "Чудо своими руками", objective = "Посадите семена Кенария в 5 местах на плодородной земле в Кенарийских Зарослях.", description = "Мы живет в интересное время!\n\nКогда-то бесплодные Пустоши теперь превратились в цветущий сад. Ты только представь себе, <класс>, если бы все пустыри Азерота вдруг наполнились жизнью! Быть может, когда-нибудь…\n\nДа, тут предстоит еще многое сделать, и это будет нелегкий труд, но нам посчастливилось стать свидетелями настоящего чуда, и не только свидетелями…\n\nНо и активными участниками, понимаешь? Вот тебе семена Кенария. Посади их на самых плодородных участках.\n\nЛучшее средство для поднятия духа!", progress = nil, completion = "Возрождение! Это так окрыляет, правда?", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14312] = {title = "Позвольте представить", objective = "Гаррен Темный Ветер на Просеке Карнума хочет, чтобы вы поговорили с ханом Ле'прахом.", description = "Я наслышан о твоих деяниях в Пустошах, <имя>. Мы у тебя в долгу.\n\nНо я боюсь, что придется вновь просить твоей помощи, причем на этот раз проблема серьезнее прежних.\n\nЗдесь изменились не только ландшафты. Старые конфликты породили новые, куда более острые. Подробнее пусть расскажет наш гость….\n\nХан Ле'прах – один из последних представителей племени Колкар, которому раньше принадлежала вся восточная часть Пустошей. Мы нашли его при смерти у границы наших владений. Выслушай его.", progress = nil, completion = "Не бойся, |3-6(ночная эльфийка). Я не желаю тебе зла.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14313] = {title = "Снова среди людей", objective = "Поговорите с Креннаном Аранасом в Темной Гавани.", description = "Так снадобье Креннана тебя не прикончило? Надо же, значит, твоя человеческая часть души победила.\n\nПожалуй, я не стану тебя убивать – во всяком случае, не сейчас.\n\nИди, сообщи хорошие новости Креннану Аранасу. Он сейчас в том доме, где мы держим таких, как ты.\n\nНо помни, <имя>: я за тобой слежу. Только попробуй выкинуть какой-нибудь фокус – сразу получишь пулю промеж глаз.", progress = nil, completion = "Сработало! Хвала Свету, сработало!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14314] = {title = "Побег из плена", objective = "Уничтожьте стражей племени Маграм в деревне Маграм.", description = "Все началось со сна, который предупреждал меня о надвигающейся опасности. Я видел легионы демонов, заполоняющих наши земли и нападающих на наших собратьев.\n\nСон стал явью. Пылающий Клинок и их хозяева-демоны согнали племя Маграм с их земель на юге. В свою очередь, Маграм победили моих бойцов и заняли наши дома.\n\nБой был жестоким. В живых осталась лишь горстка Колкар. Я прошу тебя, отправляйся в земли на востоке, что раньше были моими, и освободи моих соплеменников.", progress = nil, completion = "Я благодарю тебя, |3-6(ночная эльфийка).\n\nНаше племя могло и не выжить без твоей помощи.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14316] = {title = "Имущество кентавров", objective = "Отыщите 7 ящиков с припасами Кенария в землях Маграм.", description = "С тех пор как демоны заняли их земли, Маграм разорвали соглашения со всеми другими племенами.\n\nОни стали недоверчивыми, агрессивными и крадут у других вместо того, чтобы самим себя обеспечивать.\n\nМногие наши припасы исчезли, и мы подозреваем, что в этом виноваты Маграм.\n\nПожалуйста, <имя>, пойди в их владения на востоке и разыщи украденное у нас.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14318] = {title = "Сложные переговоры", objective = "Хан Ле'прах хочет, чтобы вы вонзили Копье хана Колкар в камень Отцов и защищали его от клана Маграм, пока не появится вождь Камма.\n\nПоговорите с ханом Ле'прахом, когда будете готовы отправиться на поле боя.", description = "Есть только один способ завоевать доверие и благосклонность племени Маграм.\n\nЗаставить их уважать нашу силу!\n\nОни понесли большие потери в войне против моего клана. Сейчас они владеют незнакомой им землей, где им нелегко прокормиться.\n\nПришло время нанести удар.\n\nПоговори со мной, когда будешь <готов/готова>, затем скачи туда и вонзи мое копье в камень Отцов. Если мы сможем убить достаточное количество Маграм, их вождь подчинится нашей воле.", progress = "Чего надо?", completion = "Почему ты вмешиваешься в дела кентавров, |3-6(эльфийка крови)?", rewards = "Пелерина сновидений кентавраШипастый наплечный щиток непокорностиНабедренники упрямостиВам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nСледующее заклинание будет наложено на вас:\n\nForce Reaction Magram\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14320] = {title = "В поисках ингредиентов", objective = "Найдите ящик с эссенцией мандрагоры.", description = "Ах, да. Насколько нам известно, последствия Проклятия невозможно снять полностью.\n\nОднако с помощью лечения ты сможешь контролировать свой разум... и держать зверя на привязи.\n\nТы не представляешь, как мы рады видеть, что лекарство тебе помогло. Обычно мне удавалось вылечить только недавно заразившихся.\n\nТеперь мы должны продолжить курс лечения – если, конечно, ты хочешь обратить эффекты Проклятия.\n\nДля новой порции лекарства мне понадобится эссенция мандрагоры – к счастью, на юго-западе от города, под навесом еще остались ящики с этим снадобьем.", progress = nil, completion = "Похоже, что ящик сильно пострадал, и все находящиеся в нем склянки разбились.", rewards = "Следующее заклинание будет наложено на вас:\n\nВторжение\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14321] = {title = "Вторжение", objective = "Поговорите с Гвен Армстед в Темной Гавани.", description = "<В груди ополченца торчит длинный кинжал с узором из черепов. Оглядевшись, вы замечаете на побережье два боевых корабля устрашающего вида.>\n\n<Гилнеас под осадой! Об этом надо срочно доложить мэру Темной Гавани Гвен Армстед.>", progress = nil, completion = "Отрекшиеся! Поторопись, Братецрога! Мы должны защитить город.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14322] = {title = "Плохая наука! Плохая!", objective = "Убейте 8 заряженных электричеством гиппогрифов.", description = "Я пытался приручить местных гиппогрифов при помощи серии ослабляющих электрических ударов, а они вдруг непонятно с чего пришли в ярость! И теперь мои подопытные крушат все вокруг! <класс>, устрани результаты моих неудачных экспериментов, пока они не устранили меня.", progress = nil, completion = "То есть, мир снова безопасен для занятий наукой? Прекрасно! В следующий раз попробую раскаленные иглы или что-то вроде этого.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14323] = {title = "Абсорбент", objective = "Соберите 20 капель кипящей воды из Коварного источника восточнее руин храма Арккоран.", description = "Мне нужно еще кое-что. Горячая вода.\n\nЕе здесь найти не так-то просто. Ни горячих источников, ни друзей, которые могли бы поделиться. Хотя есть один способ. Возьми эту губку… Это исключительный абсорбент! Намочи ее в Коварном источнике на песчаной отмели к востоку отсюда.\n\nКогда соберется достаточно жидкости, отожми губку возле башни, чтобы вызвать громадного элементаля. У него есть горячая вода.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14324] = {title = "Горячая вода", objective = "Получите магическую сферу кипящей воды от повелителя кипящей воды у башни Эльдары.", description = "Эргл говорит, что теперь вы сможете использовать наполненную азшарийскую морскую губку, чтобы вызвать громадного элементаля возле башни Эльдары к северо-востоку отсюда.", progress = "А, вот и ты!", completion = "Удобно, да? Кому нужны эти горячие источники. Прекрасно.", rewards = "Жгучие перчаткиГубчатый жилетВы получите:\n\n"}
MultiLanguageQuestData['ru'][14325] = {title = "Работа за еду", objective = "Соберите 5 боков василиска.", description = "<Вождь Камма слушает вас, пока вы рассказываете про угрозу демонов и объясняете видения хана Ле'праха.>\n\nНе надо рассказывать мне о демонах, <раса>. Они изгнали наш клан из земель наших предков.\n\nИз-за них мы были вынуждены захватить земли Колкар, где теперь пытаемся выжить.\n\nВойна против Колкар стоила моему народу больших потерь. Те, кто остались в живых, измождены, и им не хватает пищи.\n\nПринеси еды моим соплеменникам, а потом, если захочешь, поговорим о демонах.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nForce Reaction Magram 4\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14326] = {title = "Встретимся наверху", objective = "Проберитесь на верхнюю палубу \"Караула Возмездия\", который стоит у Затерянных островов, и поговорите с Траллом.", description = "Кто бы мог подумать, что войска Альянса снова возьмут меня в плен. Просто слов нет, чтобы выразить благодарность... Тебя ведь зовут <имя>, верно?\n\nДавай встретимся на верхней палубе и там уже разберемся с ними.", progress = nil, completion = "У меня важное поручение, и поэтому нельзя допустить, чтобы эти негодяи мне помешали. Разберемся с ними раз и навсегда!", rewards = "Следующее заклинание будет наложено на вас:\n\nMeet Me Up Top: Quest Complete\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14327] = {title = "Я даю слово", objective = "Хан Камма хочет, чтобы вы поговорили с ханом Ле'прахом.", description = "Похоже, у нас нет выбора.\n\nХотя мне и не особо хочется сотрудничать с Колкар, в словах их вождя есть мудрость.\n\nПередай ему, что наши копья помогут ему в бою.", progress = nil, completion = "Ты хорошо справился, |3-6(Маг).\n\nТеперь надо убедить племя Гелкис…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14328] = {title = "Три принца", objective = "Расправьтесь с Рохо, Шериком и Джорретом.", description = "Клан Гелкис обитает на юго-западе Пустошей. Они настолько же упрямы, как и клан Маграм, а поскольку они не пострадали от войны и переселения, они гораздо сильнее.\n\nЧтобы укротить клан Гелкис, понадобится серьезная демонстрация силы.\n\nПравят кланом Хан Шодо и его три сына. Шодо стареет, и старые раны дают о себе знать. Он никогда не покидает своей пещеры и управляет племенем через своих сыновей.\n\nУбей их и убеди вождя присоединиться к нам.", progress = nil, completion = "Мои сыновья мертвы… мой клан уничтожен….\n\nБудь я молод, я бы порвал тебя на части!\n\nИди… Убей меня или оставь в покое, |3-6(ночная эльфийка).", rewards = "Следующее заклинание будет наложено на вас:\n\nForce Reaction Gelkis\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14329] = {title = "Не так быстро!", objective = "Хан Шодо хочет, чтобы вы убили 10 извергов из племени Мародин в Долине Копий.\n\nВы должны обыскать их тела в поисках подсказок о местонахождении Керры.", description = "<Вождь клана Гелкис смотрит на вас пустым взглядом, пока вы рассказываете об угрозе демонов и видениях Ле'праха.>\n\nМне нет дела до того, что случится с землей. Я подвел свой клан и своих предков….\n\nЕсть лишь одна вещь, которая может вернуть надежду моей старой душе.\n\nМоя драгоценная дочь, Керра, украдена кланом Мародин. Верни мне ее живой и невредимой, тогда я обдумаю твое предложение.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14330] = {title = "За закрытыми дверьми", objective = "Найдите Керру в стенах Марадона.\n\nПрилагается предмет: \n", description = "Вы узнали, где держат дочь Хана Шодо, Керру. Она томится в заточении в Мародоне!\n\nПопытка спасти ее весьма рискована, однако если вам нужна помощь клана Гелкис, придется освободить дочь вождя.", progress = nil, completion = "Я могу идти, |3-6(эльфийка крови)?", rewards = "Следующее заклинание будет наложено на вас:\n\nForce Reaction Gelkis 4\n\nВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14332] = {title = "Время перемен", objective = "Керра хочет, чтобы вы поговорили с ханом Ле'прахом.", description = "<Керра слушает вас, пока вы рассказываете о последних событиях.>\n\nЯ соглашусь со словами вождя клана Колкар. Пришло время покончить со старыми распрями. Жаль, что племена решили объединиться лишь тогда, когда появился внешний враг – демоны.\n\nЯ вернусь к своему отцу и попытаюсь убедить его присоединиться к вам. Я даю тебе слово, что он согласится.\n\nВернись к хану Ле'праху и сообщи ему, что кентавры племени Гелкис готовы сражаться вместе.", progress = nil, completion = "Ты хорошо справилась, |3-6(ночная эльфийка).\n\nИ как раз вовремя….", rewards = "Церемониальлный кинжал с тиснениемНагрудник эмиссараБесшумные сапогиВы получите:\n\n"}
MultiLanguageQuestData['ru'][14333] = {title = "Пока ты здесь", objective = "Обыщите Долину Копий и найдите 6 оскверненных реликвий.", description = "Мародин много лет нападали на лагеря Гелкис, крадя все, что плохо лежало.\n\nОдно из их любимых занятий – похищение и осквернение святых реликвий племени Гелкис.\n\nКлан Гелкис оценит, если ты найдешь и уничтожишь оскверненные артефакты.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #6"}
MultiLanguageQuestData['ru'][14334] = {title = "Брюхажира", objective = "Убейте Брюхажиру по заданию Май'Лахии.", description = "Салют, <приятель/подруга>!\n\nДумаешь, тебе удастся нам тут подсобить, а?\n\nМы легко справимся с любым китом в этих водах, но есть один, который слишком велик для нашего копья.\n\nБрюхажира все растет и растет – еще бы, она слопала всю рыбу на милю вокруг!\n\nНайди ее и заткни, наконец, эту прожорливую глотку!", progress = nil, completion = "Ух ты! У тебя получилось!\n\nСкоро в наших сетях снова появится рыба.", rewards = "Захваты с пятнами жираНаплеч из обработанной кожи косаткиВам дадут возможность выбрать одну из следующих наград:\n\nПодвеска из китового зубаПерстень из зуба косатки\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14335] = {title = "Дело нужное", objective = "Убейте 5 крабов с мертвой хваткой и 5 жестколапых клешневиков.", description = "Ты наверняка <заметил/заметила>, все эти природные катаклизмы имеют далеко идущие последствия. Некоторые из них к добру, но другие, увы… нет.\n\nК югу отсюда лангустины выбрались из моря и перекрыли дорогу в деревню.\n\nПрошу тебя, <класс>, отправляйся туда и разберись с этим тварями.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Боевой топор шабашаПанцирные одеянияБотфорты Скитающихся ДуховВы получите:\n\n"}
MultiLanguageQuestData['ru'][14336] = {title = "Убивай или будешь убит", objective = "Поговорите с принцем Лиамом Седогривом. Вы найдете его рядом с Темной Гаванью.", description = "Раньше рифы защищали нас от нападения с моря, но теперь землетрясения открыли путь кораблям Отрекшихся.\n\nБыстрее, <имя>. Мы должны замедлить продвижение врага и оповестить оставшихся ополченцев.\n\nКажется, я слышу голос принца и его людей, сражающихся с нежитью. Спроси Лиама, чем ты можешь ему помочь.\n\nДа... и постарайся защитить его. Боюсь, что в его теперешнем состоянии он несколько беспечен.", progress = nil, completion = "Братецрога! Ты и правда выжил!!!\n\nЯ уж подумал, что твой голос мне померещился.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14337] = {title = "Деревня Ночных Охотников", objective = "Поговорите с Май'Лахией по просьбе Карнума Ткача Болот.", description = "Привет, <класс>.\n\nДо меня дошли слухи, что деревне Ночных Охотников не помешает помощь. Здесь у нас лишней работы нет, так что почему бы тебе не отправиться туда и не помочь им?\n\nДеревня расположена на берегу к юго-западу отсюда. По прибытии найди Май'Лахию, она скажет тебе, что делать.", progress = nil, completion = "Добро пожаловать в деревню Ночных Охотников, |3-6(гоблин).\n\nЯ уж и не надеялась, что Круг Кенария сюда кого-нибудь пришлет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14338] = {title = "Застава Скитающихся Духов", objective = "По поручению Карнума Ткача Болот поговорите с Маурином Костоломом.", description = "Ну здравствуй, <класс>.\n\nОтрадно видеть тебя в добром здравии. Сейчас мне нужна твоя помощь.\n\nТебе придется отправиться на заставу Скитающихся духов к юго-западу отсюда и найти там Отрекшегося по имени Маурин Костолом.\n\nМожет быть, у него есть решение хотя бы одной из проблем, с которыми мы здесь столкнулись?\n\nПоговори с ним и помоги ему, чем сможешь.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14339] = {title = "Тара для перевозки", objective = "Соберите 3 полых рога умирающих кодо и отнесите их Маурину Костолому.", description = "Я сейчас занимаюсь одним важным делом – на благо Круга Кенария и для себя лично.\n\nВидишь ли, <класс>, мне надо срочно сварить… одно особое зелье. В общем и целом работа закончена, но мне еще нужно его испытать, чтобы убедиться, что все получилось.\n\nИспытывать я его буду на нагах, что угрожают нам с запада. Если получится их истребить, это будет хорошая помощь Кругу.\n\nНо для начала мне необходимо найти тару для перевозки. Думаю, полые рога умирающих кодо – это как раз то, что нужно.", progress = "Ты так быстро вернулся, |3-6(Паладин)?", completion = "Да, да.\n\nКак раз то, что нужно….", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14340] = {title = "Встречают по одежке", objective = "Наденьте вашу новую шляпу волшебника и поговорите с проекцией верховного мага Ксилема. Его можно найти к северо-востоку от северной пересадочной станции ракетной дороги.", description = "Думаю, каждый человек должен учиться.\n\nВот, возьми мою шляпу волшебника. Я не сомневаюсь, что он возьмет тебя в <ученики/ученицы>, если ты будешь выглядеть подобающе… тебе только надо умело подлизаться к нему. Попрыгать, так сказать, через обруч. Небольшой такой пылающий обруч с вращающимися лезвиями.\n\nТы найдешь проекцию Ксилема на вершине того холма к северо-востоку отсюда.", progress = "Приветствую.", completion = "Глядя на тебя, сразу думаешь о высокой моде! Довольно красивая шляпа, должен сказать.\n\nУченики. Ученики? Несколько у меня уже есть, но учеников много не бывает.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14341] = {title = "Снаряжение Смида", objective = "По поручению Натаки на Заставе Скитающихся Духов отнесите Смиду его снаряжение.\n\nПрилагается предмет: \n", description = "Прошу прощения, <юный/юная:r> <раса>.\n\nМне нужна помощь. У меня тут был срочный заказ на снаряжение, его надо как можно скорее доставить заказчику.\n\nЯ уже староват для таких путешествий, тем более, что тут у нас нынче небезопасно.\n\nУважь старика, помоги.\n\nСнаряжение надо доставить гоблину Смиду. Он живет к юго-востоку отсюда.", progress = nil, completion = "А-а, мое снаряжение!\n\nВот спасибо, дружище!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14342] = {title = "Вторжение демонов", objective = "По поручению Фелгура Бью-Двоих уничтожьте 10 младших инферналов.", description = "Демоны готовят вторжение, <раса>!\n\nЕсли мы не найдем способ остановить их сейчас, потом нам с ними уже не справиться. У нас есть пара недель, не больше. Я только что возвратился с поля Маннорок, где инферналы в прямом смысле слова валятся с неба!\n\nНужно их задержать, чтобы выиграть время. Отправляйся туда и постарайся прикончить хоть нескольких демонов!", progress = nil, completion = "Отлично, |3-6(тролль)! Это хорошие новости!\n\nУгроза по-прежнему остается, но твоими стараниями нам удалось выиграть драгоценное время.", rewards = "Кинжал темной кровиМаска убийцы демоновИсполосованный когтями щитВы получите:\n\n"}
MultiLanguageQuestData['ru'][14343] = {title = "Зелье Маурина", objective = "По поручению Маурина отнесите зелье Маурина Карнуму в Рощу Карнума.\n\nПрилагается предмет: \n", description = "<Маурин разливает зелье по полым рогам кодо и тщательно их запечатывает.>\n\nНу вот, <класс>, все готово.\n\nОтнеси их Карнуму. Он сам разберется, как применить это снадобье против наг.\n\nА я прослежу за результатом. Мне же надо понять, насколько эффективна моя формула!", progress = nil, completion = "Сказать по правде, меня как-то не радует, что приходиться применять столь жестокие меры. Но, боюсь, у нас просто нет выбора…", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14344] = {title = "Уничтожение Джукгара", objective = "Используйте источник мощи преисподней, чтобы взять под контроль лорда Азретока у алтаря Джукгара и использовать его силы для убийства Джугкара Грим'рода.", description = "Вы узнаете в этом сущность призванного демона.\n\nОпасные потоки неведанной энергии струятся по ее поверхности.\n\nВы смотрите на сущность и вам является видение, в котором вы контролируете демонов. Вас охватывет восторг, когда вы понимаете, какая огромная сила находится в ваших руках.\n\nВы погружаетесь в размышления о том, как можно использовать это сокровище против демона…Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14345] = {title = "Изматывающая учеба", objective = "Поговорите с Соратой Жонглирующим Огнем на северной пересадочной станции ракетной дороги.", description = "Изумительно!\n\nАзу всегда старается раздобыть магические артефакты. Он говорил, что он пытался подружиться с этим верховным магом. Ксилемом!\n\nУ Ксилема МНОГО учеников. Он всех берет. Изматывает их, потом они бродят тут и там. Большая текучка.\n\nПоследнего видел вчера. Он направлялся к той большой гоблинской строящейся башне, на запад. Может, он тебе поможет встретиться с Ксилемом? Может, Ксилем знает, где Азу?\n\nВеди себя хорошо!", progress = nil, completion = "Слушай, приятель, я был в твоей шкуре всего неделю назад. Да, могущественный верховный маг действительно берет учеников! Кто же упустит такую возможность?!\n\nИногда все настолько хорошо, что в это невозможно поверить.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14346] = {title = "Очищение нашей расселины", objective = "По поручению Карнума Ткача Болот убейте 10 захватчиков и 10 сирен из клана Скользящего Плавника, а также трех морских великанов при помощи зелья Маурина.", description = "Как ты <сам убедился/сама убедилась>, <имя>, наги все еще представляют серьезную угрозу для этого региона. Пора прогнать их обратно в море!\n\nКогда будешь <готов/готова>, Жутекрыл доставит тебя к расселине, где наги готовят массированную атаку. Прибыв на место, воспользуйся зельем Маурина. Пусть эти наги узнают, что с нами лучше не связываться!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Поножи ветреной лощиныНикудышные захватыНарукавники Ткача БолотВы получите:\n\n"}
MultiLanguageQuestData['ru'][14347] = {title = "Держать строй!", objective = "Убейте 10 отрекшихся-захватчиков.", description = "<имя>! Я все еще не знаю, <жив ты или мертв/жива ты или мертва>... человек ты или ворген...\n\nДа что там говорить – я даже не уверен, что это все происходит на самом деле. Но одно я знаю точно – сегодня мы убьем множество этих чертовых Отрекшихся.", progress = nil, completion = "Да, Братецрога! Совсем как в старые добрые времена...\n\nМне придется держать под контролем свои рефлексы, чтобы не пристрелить тебя ненароком. Креннан нам все объяснил про твою новую природу.", rewards = "Наручи отражателяБоевой пояс гилнеасского солдатаВы получите:\n\n"}
MultiLanguageQuestData['ru'][14348] = {title = "Одному не справиться", objective = "Воспользуйтесь черными бочонками с порохом, чтобы взорвать 4 кошмарных поганища.", description = "Смотри и запоминай, <имя>. Труднее всего справиться с этими большими толстыми тварями – поганищами, так что не нападай на них в одиночку.\n\nПравда, у меня есть одна идея, настолько безумная, что это может сработать. Должен тебя предупредить: это связано с риском для жизни.\n\nВидишь бочки с порохом, стоящие под навесом и рядом с мельницами? Хватай их и кидай прямо на головы поганищ. А дальше я с ними сам разберусь с помощью верного мушкета.", progress = nil, completion = "Мы с тобой – отличная команда, Братецрога.\n\nХорошо, что ты снова с нами.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОсвежающая ключевая водаХлеб с пряностями\n\nВы также получите:\n\nБутылка \"Даларан нуар\"Предмет #4"}
MultiLanguageQuestData['ru'][14349] = {title = "Приказ по армии", objective = "Отправляйтесь в Подгород и поговорите с леди Сильваной Ветрокрылой.", description = "<класс>, к нам поступил приказ от самой Сильваны – отправить самых надежных агентов назад в Подгород для выполнения крайне важной тактической операции.\n\nК несчастью, все агенты, на которых я мог бы положиться в этом деле, были убиты три года назад. Вместо них мне пришлось набрать шайку безмозглых головорезов.\n\n<Натанос сурово смотрит на вас.>\n\nНемедленно отправляйся в Подгород на аудиенцию к Темной Госпоже. Постарайся не опозорить мои седины, <класс>!", progress = nil, completion = "Верховный рыцарь восседает в Бастионе Алого ордена пока его войска хозяйничают в наших землях, сея скверну и разрушения.\n\nНастало время разобраться с этим червяком раз и навсегда. Ты заставишь их расплатиться за свои деяния.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14350] = {title = "Курьер из Багрового Легиона", objective = "Возвращайтесь в Восточные Чумные земли и выследите курьера из Багрового Легиона. Убейте его и заберите приказ верховного рыцаря.\n\nЗа дальнейшими указаниями обращайтесь к Натаносу Гнилостню.", description = "Мы не можем напрямую выступить против главнокомандующих Алого ордена – их слишком хорошо охраняют. Однако есть другие способы решения проблемы. Лишившись своей главной силы, они ничего не смогут нам противопоставить.\n\nМои верные стражи смерти уже давно собирают сведения о деятельности Алого ордена за пределами Стратхольма. Каждый день им присылают инструкции из центрального штаба в Длани Тира. Мы должны перехватить их, <раса>! Убей курьера из Багрового Легиона и забери бумагу. Отдашь ее Натаносу.", progress = "Если ты справишься с этой задачей, можешь считать, что почти заслужил мое уважение,|3-6(Воин).", completion = "&lt;Натанос хохочет и потирает руки.&gt;\n\nОтлично! Наконец-то! Наконец-то у меня есть возможность уничтожить Алого Оракула!", rewards = "Вы получите:\n\nПрипасы для экспедиции в Нордскол"}
MultiLanguageQuestData['ru'][14351] = {title = "Битва за Хилсбрад", objective = "Отнесите запечатанное рекомендательное письмо Дарталии Брагору Кровопалу в Подгород.", description = "Поскольку ты <проявил/проявила> немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование.\n\nОтнеси мое письмо Брагору Кровопалу в Подгород. Можешь гордиться собой, <класс>.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Щит Мертвого черепаРунический Черный клинокСвященные погребальные брюкиВы получите:\n\nКольцо Подгорода"}
MultiLanguageQuestData['ru'][14352] = {title = "Нечестивый союз", objective = "Отнесите маленький свиток Брагору Кровопалу в Подгород.", description = "Госпожа моя!\n\nНаше предложение вам прекрасно известно. Для вас это отличная возможность получить безграничную власть над Степями и окрестными землями. От вас нам требуется лишь небольшое содействие – дайте нам свободу действий в этих землях.\n\nМы убедительно просим вас рассмотреть это предложение. Мы обладаем великой силой и охотно поделимся ею с тем, кто достаточно мудр, чтобы примкнуть к нам. Я буду ждать вас у Курганов Иглошкурых.\n\nС наилучшими пожеланиями,\nПосланник Малкин.", progress = "Очень надеюсь, что у тебя действительно важное дело, Расул.", completion = "Я уже видел раньше этот знак на свитке во время моего пребывания в Нордсколе. Говоришь, он был на короне предводителя этих свиней из Лабиринтов Иглошкурых?\n\nБудь я проклят, если позволю Плети закрепиться на этих холмах. Автор этой записки – этот Малкин – станет твоей следующей целью.\n\nЯ не позволю им вторгнуться в Калимдор!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14353] = {title = "Нечестивый союз", objective = "Принести голову посла Брагору Кровопалу в Подгород.", description = "Предположительно, этот Малкин находится за пределами Курганов Иглошкурых. Это не обсуждается – он должен умереть!\n\nМой связной из Оргриммара сообщил, что их разведчики обнаружили там следы чумы. Очевидно, что Иглошкуры тоже заражены – они стали слишком сильными. Мы должны немедленно положить конец козням Плети!\n\nНайди этого Малкина и убей его. Доложи мне, когда дело будет сделано.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Пробиватель череповГвоздометОдеяние фанатикаВы получите:\n\n"}
MultiLanguageQuestData['ru'][14354] = {title = "Дары Элуны", objective = "Отправьтесь к реликвиям Элуны в Саргероне.", description = "Просто невыносимо!\n\nСатиры оскверняют наши священные земли…\n\nИх дни сочтены, <раса>. Уж в этом я могу тебя заверить. Как только у нас будет достаточно бойцов, я поведу их в атаку и избавлю землю от этих гадких созданий.\n\nА сейчас не <мог/могла> бы ты немного облегчить мне жизнь?\n\nОтправляйся на восток, в Саргерон, и изучи руины. Найди реликвии Элуны и убедись, что они находятся в хорошем состоянии.\n\nЯ щедро вознагражу тебя за это.", progress = nil, completion = "Реликвии целы! Что ж, это просто прекрасно, |3-6(Ворген).\n\nУ меня будто камень с души упал. Прошу, прими этот дар от меня.", rewards = "Перчатки заботыНаплечные щитки защитыВам дадут возможность выбрать одну из следующих наград:\n\nКолье обновленияПечатка истребителя демонов\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14355] = {title = "В монастырь Алого ордена", objective = "Убейте верховного инквизитора Вайтмейн, командира Алого ордена Могрейна, Ирода из Алого ордена и псаря Локси, после этого вернитесь с докладом к Брагору Кровопалу в Подгород.", description = "Одна из моих задач – помогать Отрекшимся охранять границы, и в этом ты, <класс>, можешь мне помочь.\n\nЖивой или мертвый – Алому ордену без разницы; они убивают моих людей наравне с нежитью. Они – моя главная проблема, с которой тебе предстоит разобраться.\n\nОтправляйся в Монастырь и убей верховного инквизитора Вайтмейн с ее лейтенантами.", progress = nil, completion = "Я уверен, что Сильвана будет счастлива узнать о благополучном решении проблемы. Я поручил тебе непростое задание, но ты вернулся с победой, Амитран. Я не забуду то, что ты для нас сделал.", rewards = "Меч ОменаВам дадут возможность выбрать одну из следующих наград:\n\nПророческая палкаОжерелье Драконьей Крови\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14356] = {title = "Силы разрушения...", objective = "Принесите книги \"Заклинания Тьмы\" и \"Заклятия Пустоты\" Брагору Кровопалу в Подгород.", description = "Послушай, <класс>.\n\nТебе это, возможно, неизвестно, но Огриммар столкнулся с неожиданной проблемой. Глубоко в Огненной Пропасти творит свои зловещие дела секта Совета Теней – Пламенеющий Клинок. Она состоит в основном из орков, поэтому я не могу доверять вот этим бугаям. Твоя помощь придется как нельзя кстати.\n\nВо владении Совета оказались две книги, которые не должны попасть в руки Пламенеющего Клинка и Отрекшихся. Принеси их мне.", progress = "Книги в безопасности? Нельзя, чтобы они попали не в те руки.", completion = "Отлично, |3-6(Маг). Ты справился с моим поручением. Эти книги я спрячу в безопасное место – меньше всего мне хочется узнать о том, что Совет Теней опять набрал силу.\n\nЗаглядывай ко мне время от времени – у нас еще полно дел, и мне может пригодиться толковый помощник.", rewards = "Мертвенные брюкиПоножи болотного черпателяПоножи горгульиВы получите:\n\n"}
MultiLanguageQuestData['ru'][14357] = {title = "Оружие поверженного врага", objective = "Соберите 20 сабель сатиров – возьмите с оружейных стоек или отберите у сатиров, обитающих в этих краях.", description = "Служанка Элуны! Она еще прекрасней, чем говорят.\n\nЛегенды, сложенные об этой реликвии, всплывают в вашей памяти, когда вы приближаетесь к ней:\n\nВ древние времена оружие врагов после боя сбрасывали в воду, чтобы получить божественный дар...\n\nПока вы вспоминаете ритуал, блеск стали от ближайшей стойки с оружием привлекает ваше внимание....", progress = "Статуя стоит, как будто в ожидании.", completion = "По завершении ритуала вы получаете божественный дар.\n\nВы ощущаете невольное восхищение, получив один из даров Элуны.", rewards = "Сандалии ритуалаПозолоченный панцирьОсновательный ременьВы получите:\n\nПредмет #20"}
MultiLanguageQuestData['ru'][14358] = {title = "Десять фунтов плоти", objective = "Добудьте 10 кусков плоти различных сатиров в Саргероне.", description = "Согласно древней легенде, эта жаровня была создана для жертвоприношений.\n\nИз глубин памяти всплывает, что благословлением будут одарены те, кто возложит плоть врагов Элуны на пылающие угли жаровни.\n\nОглядываясь по сторонам, вы приходите к заключению, что сатиры, захватившие регион, прекрасно для этого подойдут.", progress = nil, completion = "Божественная жаровня дарует вам благословение.", rewards = "Вы изучите:\n\nДар небес\n\nВы также получите:\n\nПредмет #10"}
MultiLanguageQuestData['ru'][14359] = {title = "Благословение свыше", objective = "Добудьте 10 кусков плоти различных сатиров в Саргероне и возложите на жаровню Элуны.", description = "Вы чувствуете глубокую связь с прошлым, получив древнее благословение, дарованное этой реликвией.\n\nВы решаете заслужить благословение еще раз.", progress = nil, completion = "Божественная жаровня дарует вам благословление.", rewards = "Вы изучите:\n\nДар небес\n\nВы также получите:\n\nПредмет #10"}
MultiLanguageQuestData['ru'][14360] = {title = "Пара дынь решит любую проблему", objective = "Соберите 8 плодов дыни и выжмите их сок в кубок Элуны в Саргероне.", description = "Символы на руинах Саргерона вкупе с расшифрованными фрагментами записей Фуриена определенно указывают на то, что древний источник в святилище Элуны обладает магической силой.\n\nТому, кто умоет в нем лицо, даются какие-то особые способности. Вот только источник давно высох… и его надо как-то наполнить, чтобы было чем умыться.\n\nРазмышляя над этой проблемой, вы замечаете плод дыни на земле под ближайшим деревом…Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #8"}
MultiLanguageQuestData['ru'][14361] = {title = "Спокойный сон капитана", objective = "Ликвидируйте Кохора.", description = "Мы – передовой пост сил в этом регионе, и отвечаем за то, чтобы заранее выявить возможных противников и избавить Альянс от неприятных сюрпризов, когда начнется кампания в Пустошах.\n\nНедавно один из наших разведчиков был пойман и принесен в жертву адептами Пылающего Клинка в их крепости к западу отсюда. С тех пор нам постоянно поступают угрозы и оскорбления от одного типа из этого клана по имени Кохор.\n\nПылающему Клинку уже недолго осталось, но я хорошо заплачу, если ты заставишь этого гада заткнуться прямо сейчас!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14362] = {title = "Надрать уши", objective = "Добудьте 25 ушей прислужников Пылающего Клинка.", description = "Капитан Пентигаст не скрывает своего отвращения к культу Пылающего Клинка, занявшему крепость Громового Топора.\n\nДоказательства их гибели придутся ему по душе.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14363] = {title = "Ты поймешь, когда увидишь", objective = "Найдите следы древнего ритуала призыва в крепости Громового Топора.", description = "Перед смертью Кохор рассказал о ритуале призыва демона, который может угрожать всему региону.\n\nОн мог блефовать, но рисковать не стоит.\n\nДело не может ждать до того момента, когда вторжение Альянса в Пустоши наберет силу. Вам необходимо обыскать крепость Громового Топора в поисках улик и предотвратить трагедию.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14364] = {title = "Голова на голове", objective = "Соберите 100 отбеленных черепов в Крепости Громового Топора, затем принесите их в круг призыва Пылающего Клинка, вызовите и убейте Назаргена.", description = "Так значит, это правда….\n\nНа пергаменте, найденном тобой в крепости Громового Топора, указаны подробности могущественного ритуала призыва. Это куда серьезнее, чем можно было ожидать от культа Пылающего Клинка.\n\nМы должны прервать этот ритуал любой ценой!\n\nВозможно, если нам удастся вызвать демона раньше назначенного срока, трагедии можно будет избежать.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Плащ опаленного черепаВам дадут возможность выбрать одну из следующих наград:\n\nПерстень решительного вмешательстваКолье заземления\n\nВы также получите:\n\nDeprecated Dwarven Squire's Pants"}
MultiLanguageQuestData['ru'][14365] = {title = "Этель-Ретор", objective = "Капрал Мелкис хочет, чтобы вы поговорили с Коррой у Этель-Ретора.", description = "Мы недавно получили просьбу о помощи от исследовательницы из Круга Кенария.\n\nК сожалению, мы никого не можем туда отправить, так что я попрошу тебя навестить ее от нашего имени.\n\nКорру можно найти возле разрушенной башни Этель-Ретор, находящейся на берегу на западе.", progress = nil, completion = "Хорошо, что ты пришла.\n\nНам грозит смертельная опасность.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14366] = {title = "Удержание позиций", objective = "Поговорите с Гвен Армстед в Темной Гавани.", description = "Думаю, здесь мы можем удерживать позиции. Сообщи об этом мэру Армстед.\n\nЭто только малая часть сил Отрекшихся, но если мы не нападем на них в ближайшее время, нам придется иметь дело с куда большей проблемой.\n\nУзнай, как нам завязать бой с армией Отрекшихся прямо на месте их высадки.", progress = nil, completion = "Great news, &lt;имя&gt;.  I've sent the remaining militia to the shore to meet the Forsaken force head on.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14367] = {title = "Подвал Фермы Аллена", objective = "Поговорите с лордом Годфри в подвале Фермы Аллена, что в Гилнеасе.", description = "Бой с Отрекшимися на месте их высадки ведет лорд Годфри. Узнай у него, как ты можешь помочь оттеснить врага.\n\nМне сказали, что Годфри устроил ставку в подвале Фермы Аллена, что далеко на западе. Разыщи его.", progress = nil, completion = "Отрекшиеся обрушились на нас всей своей военной мощью, Братецрога. У нас едва хватает людей, чтобы сдерживать их натиск.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14368] = {title = "Спасите детей!", objective = "Спасите Синтию, Эшли и Джеймса, которые остались где-то на ферме Хэммондов.", description = "Бедные мои детки не успели спрятаться, а проклятые военные не выпускают меня из подвала, чтобы отыскать их. Они все еще где-то там, на ферме!\n\nОтрекшиеся не пощадят даже столь невинные души...\n\nМоих детей зовут Синтия, Эшли и Джеймс. Если ты увидишь их, пожалуйста, приведи сюда – и я буду у тебя в неоплатном долгу.", progress = "Я... Не знаю, что буду делать, если потеряю моих дорогих деток...", completion = "Мои дети живы и здоровы! Ты не представляешь, как много сделал для меня, Братецрога. Не знаю даже, как мне тебя отблагодарить.", rewards = "Поножи опекунаПерчатки защитыВы получите:\n\n"}
MultiLanguageQuestData['ru'][14369] = {title = "Звериная сила", objective = "Убейте 8 рядовых или матросов Отрекшихся.", description = "Не стану лгать, <имя> – мне не нравится сражаться бок о бок с воргеном.\n\nКто знает, как долго будет действовать на тебя снадобье Креннана, и не соберешься ли ты откусить мою голову в разгар битвы.\n\nНо пока этого не произошло, мы, пожалуй, найдем применение твоей звериной силе.\n\nСтупай на поле боя и убей столько Отрекшихся, сколько сможешь.\n\nИ не стесняйся использовать самые жестокие приемы – пусть они знают, с кем связались.", progress = nil, completion = "Неплохо, неплохо. Хорошо, что ты на нашей стороне, Братецрога.", rewards = "Кинжал ГодфриРоскошные поножиВы получите:\n\n"}
MultiLanguageQuestData['ru'][14370] = {title = "Таинственный азшарит", objective = "Соберите 5 образцов азшарита в ближайших скалах.", description = "Азшарит! Эту таинственную кристаллическую субстанцию использовали, чтобы наделять оружие мощью Скверны, но мы обнаружили, что она способна удерживать огромное количество энергии. Наверное, это самое крупное открытие гоблинов со времен каджа'мита.\n\nНо что это за субстанция? Откуда она взялась? Почему ее находят только здесь? Наука требует ответов! Мне нужны еще образцы для изучения. Поищи залежи азшарита в ближайших скалах.", progress = "Ты принес образцы? В течение долгих лет беззаботные искатели приключений собирали эту субстанцию, даже не догадываясь о ее истинной ценности!", completion = "Ах, великолепно. Некоторые из этих образцов выглядят свежими. У меня будет достаточно материала, пока я буду пытаться решить эту загадку!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14371] = {title = "Гигантская закуска", objective = "Соберите 8 изуродованных туш скальных мокрокрылов.", description = "Может быть, пока ты бегаешь по скалам, ты <мог/могла> бы помочь мне с еще одним исследованием? По скалам бродят великаны, они обитают здесь с тех самых времен, когда эти горы только формировались. Может быть, им известно, откуда взялся азшарит? В наших интересах подружиться с этими великанами и узнать ответ.\n\nПодготовь гигантское количество еды, она пригодится, чтобы их задобрить. Поохоться на скальных мокрокрылов, которые так мешают нашим исследованиям, и принеси мне их туши.", progress = "Вероятно, мне стоило предупредить тебя о том, что мокрокрылы могут стрелять молниями.", completion = "Фу! Какая вонь! Ну, будем надеяться, что великанам аромат этой кучи туш покажется более соблазнительным.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14372] = {title = "Лагерь Таргада", objective = "Карнум Ткач Болот хочет, чтобы вы поговорили с Таргадом.", description = "Радует, что ты до сих пор <жив/жива>, <имя>. Мне сообщили, что активность демонов на юге увеличилась.\n\nНа границе есть лагерь, который окажется отрезанным, если демоны двинутся на север.\n\nМожет, ты сможешь помочь?\n\nЯ знаю, что лагерем руководит Таргад. Он скажет, что нужно делать.\n\nСпасибо, друг. Удачи.", progress = nil, completion = "Демоны?\n\nО, о демонах я тебе много могу рассказать!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14373] = {title = "Вторжение демонов", objective = "Уничтожьте 10 младших инферналов.", description = "Слушай сюда. И смотри сюда.\n\n<Таргад указывает на восток.>\n\nВидишь большие зеленые светящиеся шары, что падают с неба?\n\nЭто кучка демонов, которые беспрепятственно шарятся по этим землям. Ну, почти беспрепятственно... я им постоянно хвосты накручиваю, чтоб не зарывались.\n\nТы как насчет того, чтобы продолжить это дело?", progress = nil, completion = "Ну, подруга!\n\nНе бойся еще парочку уложить для профилактики!", rewards = "Кинжал темной кровиМаска убийцы демоновИсполосованный когтями щитВы получите:\n\n"}
MultiLanguageQuestData['ru'][14374] = {title = "Порталы Легиона", objective = "Закройте 6 порталов на поле Маннорок.", description = "Вот она – Рука Ируксоса.\n\nСам спер у одного из лидеров Пылающего Клинка.\n\nМощная штука! Используешь на демонических порталах, и они попросту исчезают! Страшноватая магия, но время такое....\n\nЕсли демоны с такой же скоростью будут прибывать, они ж тут весь лагерь заполонят, ты и глазом моргнуть не успеешь.\n\nВот, возьми. Время действовать.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Связующий посохНаруч порталовНаплеч опечатыванияВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14375] = {title = "Последняя капля человечности", objective = "Я тебя вытащу, Братецрога. Я тебе приготовил такую дозу, что хватит свалить лошадь, но я знаю, что делаю. Я знаю, из какого теста ты сделан. Ты выдержишь, и все будет хорошо.\n\nВерь мне, Братецрога. Я понимаю, через что тебе придется пройти...\n\nА теперь выпей это и закрой глаза.", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nForcecast Worgen Intro Completion\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14376] = {title = "Уничтожение Джукгара", objective = "Используйте источник мощи преисподней, чтобы взять под контроль лорда Азретока у алтаря Джукгара и использовать его силы для убийства Джугкара Грим'рода.", description = "Вы узнаете в этом сущность призванного демона.\n\nОпасные потоки неведанной энергии струятся по ее поверхности.\n\nВы смотрите на сущность и вам является видение, в котором вы контролируете демонов. Вас охватывет восторг, когда вы понимаете, какая огромная сила находится в ваших руках.\n\nВы погружаетесь в размышления о том, как можно использовать это сокровище против демона...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14377] = {title = "Дружба с великанами", objective = "Поговорите с Гормунганом у южной конечной станции ракетной дороги и узнайте секрет азшарита.", description = "При поверхностном изучении образцов азшарита, которые ты мне <принес/принесла>, выяснилось, что его природа и форма – не биологические. Подобными же свойствами в Азшаре обладают великаны, которые бродят по этим скалам.\n\nКажется, что один из них не против помочь нам в наших исследованиях. Отнеси собранное тобой мясо Гормунгану, его можно найти к западу отсюда. Подружись с ним, а потом расспроси – выясни, знает ли он секрет азшарита!", progress = nil, completion = "Помедленнее – так что ты говоришь? Я правильно тебя поняла? Все эти отложения азшарита образовались там, где великаны… о боже. Омерзительно! Давай не будем говорить об этом Дреку, он ведь считает это делом своей жизни.\n\nНу ладно, по крайней мере мы теперь знаем, откуда берется азшарит, и почему его так немного. Надо придумать способ увеличить его, гм, \"производство\".", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14378] = {title = "Охота на Брендола", objective = "Отыщите сумку Брендола.", description = "Я слишком занят поиском артефактов, чтобы заниматься чем-нибудь еще, но есть проблема, которую надо решить.\n\nЕсть тут один аптекарь-отрекшийся, который уже давно всюду нос сует. Так бы мне на него и наплевать, но уже три раза он пробирался в мой лагерь и тырил мое снаряжение…. Сколько можно?!\n\nНайди вора и верни мои вещи!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14379] = {title = "Удар по лобстудару!", objective = "Достаньте 7 сочных хвостов лобстудара.", description = "Таргад не знает ни сна, ни отдыха, охотясь за древними реликвиями Титанов. Он настолько занят, что если бы не я, он бы забывал есть!\n\nКстати, я бы хотела приготовить ему что-нибудь особенное. Может, ты мне поможешь?\n\nЛобстудары бродят по берегу на западе. Я бы никогда не смогла противостоять им в бою, но смогу сделать прекрасный обед, если ты мне принесешь немного их хвостов!", progress = "Тебе удалось собрать хвосты лобстударов, |3-6(ночная эльфийка)?", completion = "О-о-о-о, годится-годится!\n\nТаргад будет так удивлен!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14380] = {title = "Впечатляющее открытие", objective = "Отнесите странное зелье Карнуму на Просеку Карнума.\n\nПрилагается предмет: \n", description = "<Таргад обыскивает сумку и вынимает интересную вещичку.>\n\nА вот это странно… это полый рог кодо с каким-то зельем внутри.\n\n<Таргад нюхает зелье.>\n\nФУУУ! Уж точно не какой-нибудь хороший эликсир. Эта штука создана для одной цели… для убийства.\n\nКак насчет того, чтобы пойти к Карнуму и посмотреть, что он скажет…Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14381] = {title = "Очищение нашей расселины", objective = "Убейте 10 захватчиков и 10 сирен из клана Скользящего Плавника, а также трех морских великанов при помощи зелья Маурина.", description = "О, я узнаю это творение зла. Это зелье вызывает ужасную болезнь, которая убивает почти мгновенно и очень жестоко. Хоть я и ненавижу применять подобные средства, боюсь, выбора у нас нет.\n\nКак ты наверняка знаешь, наги являются серьезной угрозой для региона. Пришло время прогнать их обратно в море!\n\nКогда будешь <готов/готова>, Жутекрыл доставит тебя к расселине, где они готовят яростную атаку.\n\nИспользуй зелье на нагах и их союзниках, чтобы обезопасить Пустоши!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Поножи ветреной лощиныНикудышные захватыНарукавники Ткача БолотВы получите:\n\n"}
MultiLanguageQuestData['ru'][14382] = {title = "Двое у моря", objective = "Воспользуйтесь катапультой Отрекшихся, чтобы попасть на корабли и убить капитанов – Морриса и Ансона.", description = "Надо сказать, эти катапульты Отрекшихся выбили из нас всю отвагу, <имя>. Даже если мы с ними справимся – в порту стоят два корабля с заряженными пушками, нацеленными прямо на нас.\n\nНо у меня есть план, как убить двух зайцев одним выстрелом. Роль выстрела придется исполнить тебе.\n\nТы убьешь катапультчиков, а потом нацелишь орудия на корабли Отрекшихся и отправишь себя в полет. Не бойся, если ты хорошо прицелишься, то приземлишься прямо на палубу. Как только окажешься на месте, не мешкай, спускайся в трюм и перережь глотки капитанам кораблей. Удачи, <класс>.", progress = nil, completion = "Молодец, Братецрога. Может, ты и кровожадный зверь – но ты наш зверь.", rewards = "Перчатки двух зайцев\"Летящие\" одеяния воргеновВы получите:\n\n"}
MultiLanguageQuestData['ru'][14383] = {title = "Ужасные механики Опустошенного берега", objective = "Убейте Бингема Прибамбаса на Опустошенном берегу, а вместе с ним 4 гномов с сетеметами и 6 гномов с шокерами.", description = "Негодяи! Нечестивцы! С самого начала моей операции в Азшаре семейка Прибамбасов мешает моей работе и срывает мои исследования. А теперь еще и толпа второсортных механиков примчалась к ним на помощь. Так что у меня есть важное дело: принять меры, чтобы с этими гномами было покончено навсегда.\n\nОтправляйся на Опустошенный берег, который находится южнее моей секретной лаборатории, и прикати мне несколько их непропорционально огромных голов.", progress = nil, completion = "О, чудесно. Расскажи подробнее. А этот не по годам развитый юный Прибамбас? Тоже убит? Ах, прекрасно. Моя работа очень важная, но иногда я скучаю по процессу уничтожения врагов на более персональном уровне. Вот, возможно тебе пригодится что-то из моего старого оборудования.", rewards = "Запасная покрышка ХобартаВам дадут возможность выбрать одну из следующих наград:\n\nВесенний прибамбас\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14384] = {title = "Изменение маршрута!", objective = "Офицер Дженки хочет, чтобы вы, используя ее грифона, добрались до Высоты Найджела и поговорили с капралом Мелкисом.", description = "Смирно!\n\nИменем стражи Высоты Найджела мне приказано отсылать всех способных держать оружие союзников прямо к капралу Мелкису.\n\nУ меня нет полномочий предоставлять какую-либо другую информацию.\n\nЯ могу предложить лишь услуги транспортировки. Можешь использовать моего грифона. Он тебя доставит, куда нужно.\n\nВольно.", progress = nil, completion = "Добро пожаловать на Высоту Найджела, |3-6(Ворген).\n\nА теперь введем тебя в курс дела.", rewards = "Следующее заклинание будет наложено на вас:\n\nMelkins' Dummy\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14385] = {title = "Первый эксперимент с азшаритом", objective = "Заберите гигантскую порцию слабительного из башни гномов на Опустошенном берегу. Попытайтесь накормить слабительным великана Гормунгана.", description = "В общем, я знаю только один верный способ заставить великана мчаться в уборную, но тебе он не понравится. Нам нужно большое количество… слабительного. Погоди! Может быть, гномы занимаются тем же самым? Это же не может быть простым совпадением. Интересно, что они пытаются здесь провернуть?\n\nНаша разведка сообщает, что в башню Прибамбасов, что на берегу южнее секретной лаборатории, доставляли слабительное. Достань это слабительное и скорми его Гормунгану!", progress = "Теперь у тебя есть слабительное, попытайся накормить им Гормунгана. И дай ему журнальчик или что-нибудь вроде того. Сделай это для науки!", completion = "Что, не прошло? В буквальном смысле слова? Гм, Дрека такой ответ не устроит. Надо придумать что-то еще.\n\nМожет быть мои практиканты подбросят это слабительное в лагерь ночных эльфов? По крайней мере посмеемся.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14386] = {title = "Вожак стаи", objective = "Выследите темного следопыта Тиалу и убейте ее с помощью мастифов.", description = "Отлично, <имя>. Но расслабляться рано – наши разведчики засекли предводителя наземных отрядов Отрекшихся.\n\nОдна из лучших темных следопытов Сильваны руководит битвой из дома лорда Вальдена, что на побережье.\n\nВозьми этот свисток и подай сигнал моим людям, когда найдешь ее точное местоположение. Они спустят с цепи мастифов, а те уже порвут ее на кусочки. <Будь осторожен/Будь осторожна>, <имя>, и даже не пытайся справиться с ней в одиночку.", progress = nil, completion = "Ты справился, Братецрога! Надеюсь, это поумерит их прыть.", rewards = "Жилет темного следопытаСапоги лидераСледующее заклинание будет наложено на вас:\n\nForcecast Cataclysm I\n\nВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][14387] = {title = "Дела на местности", objective = "Капитан Пентигаст хочет, чтобы вы поговорили с Валлариэлем в Высоте Найджела.", description = "Да, да. Добро пожаловать в Пустоши, <раса>.\n\nПрощу прощения за настойчивость, но у нас маленький аванпост и большие проблемы, многие из которых нужно быстро решить.\n\nОпустим формальности. Нам нужна любая помощь.\n\nДля начала, наш друг Валлариэль стал каким-то беспокойным и настаивает, чтобы мы отправили кого-то обследовать руины на востоке.\n\nПочему бы тебе <самому/самой> не поговорить с ним…Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14388] = {title = "Второй эксперимент с азшаритом", objective = "Сообщите ассистентке Грили, что вы готовы быть <уменьшенным/уменьшенной> до размера крысы. Затем оседлайте крысу ракетной дороги и воспользуйтесь ею, чтобы напугать великана Гормунгана.", description = "Окей, новый план. Мы его НАПУГАЕМ! Жизненный опыт мне подсказывает, что самые большие существа обычно боятся маленьких – например, крыс. Гм. Крыс-то тут полно, а вот как уговорить их навестить великана?\n\nЭй! А ты ведь не против, чтобы я разобрала тебя на клетки и собрала заново? Больно будет только в начале. Я могу уменьшить тебя до размера крысы, а ты оседлаешь одну из них, как лошадь. Это настолько безумно, что не может не сработать! Когда будешь <готов/готова> к уменьшению, скажи...", progress = nil, completion = "То есть, испуг тоже не помог? Черт побери! Придется сообщить Дреку неприятные новости: азшарит так и останется самой редкой субстанцией на планете. Надо использовать его экономно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14389] = {title = "Разве не очевидно?", objective = "Воспользуйтесь порталом за спиной Джоанны в башне Ксилема, чтобы найти Анару целительницу душ и, возможно, Азурегоса.", description = "Азурегос! Да, конечно. Беспокойный старый дракон, но с добрым сердцем. Нападения бродяг в течение всех этих лет не пошли ему на пользу. Теперь он со странностями.\n\nНе так давно, в очередной раз возвращаясь от Анары, нашей местной целительницы душ, я заметила, что Азурегос к ней неровно дышит. Думаю, он и сейчас у нее.\n\nПортал за моей спиной – самый быстрый способ добраться туда. Правда, он немного жжется.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14390] = {title = "Когда легко – скучно", objective = "Убедите Азурегоса прекратить отшельничество и встретиться с Калесгосом.", description = "После долгих поисков со множеством затруднений вы наконец нашли Азурегоса.\n\nТеперь осталось только уговорить его встретиться с Калесгосом и положить конец исходящей от черных драконов угрозе в Азшаре.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14391] = {title = "Смена ролей", objective = "Поговорите с Анарой, чтобы вернуться в мир живых, а затем встретьтесь с Калесгосом на северной конечной станции ракетной дороги.", description = "Азурегос и Калесгос должны встретиться на северной конечной станции ракетной дороги. Вы тоже должны быть там, чтобы убедиться, что Калесгосу не потребуется дополнительная помощь.\n\nВ случае смерти поможет Анара.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14392] = {title = "Прощай, рыбка", objective = "Поговорите с Соратой Жонглирующим Огнем в Гавани Трюмных Вод.", description = "Спасибо, <малыш/малышка>.\n\nКак порой просто потерять голову от любви и забыть обо всем, даже если ты дракон. Но теперь я собираюсь снова посвятить себя тому, чтобы Кейлек никогда не смог занять место Малигоса. Нельзя придумать дело благороднее этого.\n\nОтправляйся обратно в гавань. Думаю, там тебя ждут.\n\nСмотри, чтобы по пути тебя не раздавили и не съели.", progress = nil, completion = "Привет… еще раз.\n\nСлушай, я давал тебе свою шляпу. Это был подарок. Я думал, ты найдешь ей применение. Точнее, я надеялся, что ты унесешь ее подальше от меня.\n\nМожешь представить себе мое удивление, когда явился Ксилем собственной персоной и отдал ее мне обратно? \"Хочешь больше походить на моих учеников, Сората? Дай своей шляпе второй шанс.\" Не самые приятные минуты.\n\nТак о чем это я... Неужели ты просто выбросил ее, дав ему возможность ее найти? Нет. Вряд ли. Ты возьмешь эту шляпу и ты ее полюбишь. Да.", rewards = "Вы получите:\n\nВыцветшая шляпа волшебника"}
MultiLanguageQuestData['ru'][14393] = {title = "В бой!", objective = "Хан Ле'прах хочет, чтобы вы убили 15 чернокнижников из клана Пылающего Клинка, 3 стражников ужаса -захватчиков и жрицу Тан'дариссу.\n\nПоговорите с ханом Ле'прахом, чтобы вступить в бой.", description = "Много поколений кланы кентавров сражались друг с другом, но теперь с этим покончено.\n\nБлагодаря тебе мы вместе сражаемся против общего врага. Или мы отвоюем земли наших предков, или умрем братьями.\n\nА ты, <имя>?\n\nТы <заслужил/заслужила> право сражаться вместе с нами. Я дам тебе группу лучших кентавров, чтобы ты <повел/повела> их в бой.\n\n<Готов/Готова> ли ты к битве?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14394] = {title = "Смерть Агогридону!", objective = "Убейте Агогридона.", description = "Мы уже почти у цели, <имя>!\n\nЕсли сейчас устранить вождя армии демонов, это сломит их боевой дух. И если у нас все получится, Пустоши будут наши!\n\nТеперь, что требуется от тебя: проведи отряд кентавров на юг по ущелью, в лощину Тьмы. Узнай, где скрывается Агогридон!\n\nЯ соберу остальных вождей и приведу их туда, чтобы тебе не пришлось драться с ним в одиночку.", progress = nil, completion = "Агогридона больше нет.\n\nДемоны уже никогда не захватят наши земли!", rewards = "Абордажная сабля АгогридонаПалица звездного духаКолкарский колунСледующее заклинание будет наложено на вас:\n\nDeath to Agogridon Complete\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14395] = {title = "Слушая наше дыхание", objective = "Cпасите 4 утопающих стражей.", description = "<имя>! Я как раз направлялся сюда, когда все это случилось. \n\nНельзя тратить ни минуты. Большая часть городской стражи была на том участке земли, который обвалился в воду.\n\nМы должны как можно скорее вытащить ребят на берег, и там им окажут всю возможную помощь.", progress = nil, completion = "Ты сделал все, что смог. Если повезет, еще несколько выживших смогут добраться до берега...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКрохотный флакон с лечебным зельемКрохотный флакон с зельем маны\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][14396] = {title = "И земля содрогнулась", objective = "Поговорите с принцем Лиамом Седогривом на Ферме Аллена.", description = "Это еще что за напасть, <имя>?\n\nНепохоже на очередной пушечный залп...\n\nНу-ка, выберись на поверхность и выясни, что там происходит.", progress = nil, completion = "Это океан, Братецрога. Он поглотил все... землю... Отрекшихся... наших людей!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14397] = {title = "Эвакуация", objective = "Поговорите с Гвен Армстед в Темной Гавани.", description = "Только благодаря слепой удаче нам удалось избежать гибели, <имя>, но теперь фортуна от нас отвернулась.\n\nПрямо в этот момент приливные волны накрывают побережье, да и земля под нами не кажется мне слишком надежной.\n\nМне самому трудно в это поверить, но нам снова придется убегать... Проклятье, <имя>. Как можно потерять родину дважды за такой короткий промежуток времени? Но природные катаклизмы – это тот враг, которого нам не одолеть.\n\nСкажи Гвен, пусть готовит людей к эвакуации.", progress = nil, completion = "Лиам прав. Надо переместиться на высокогорье.\n\nПомоги мне донести весть об эвакуации до наших граждан, а я пока займусь транспортом.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14398] = {title = "Бабуля Валь", objective = "Найдите бабулю Валь в ее домике.", description = "Нелегко будет уговорить бабулю Валь пойти вместе с нами, но ты <должен/должна> постараться.\n\nОна все еще в своем домике Валь. Пожалуйста, <имя>, прояви терпение. Она уже совсем старенькая и слегка выжила из ума.", progress = nil, completion = "А, дорогой гость, добро пожаловать! Не желаешь чашечку чая?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14399] = {title = "Девичья память", objective = "Найдите завернутую в холст книгу.", description = "Уйти? Сейчас?\n\nНу что ж, надо – так надо. <Милок, будь так любезен/Милочка> будь так любезна;, окажи мне одну услугу.\n\nГде-то тут лежит моя любимая книга, без которой я не могу отправиться в путь. Принеси ее мне, пожалуйста.\n\n<Сколько вы не пытаетесь убедить бабулю в серьезности ситуации и опасности промедления, она только качает головой.>\n\nДорогуша, неужели тебе так трудно просто принести мне книгу?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14400] = {title = "Мне нечего надеть!", objective = "Принесите бабушкино выходное платье.", description = "Что, ты говоришь, происходит?\n\nАх, да... Эвакуация.\n\nНо право же, я не могу выйти из дома в таком виде!\n\n<Будь добр/Будь добра>, подай мне мое выходное платье. Оно висит на бельевой веревке снаружи.\n\n<Вы пытаетесь убедить бабулю, что она одета вполне прилично, но тщетно.>\n\nАх, ну что за молодежь пошла, никакого понятия о хороших манерах! Можно подумать, тебя воспитывали огры... Так где мое платье, дорогуша?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14401] = {title = "Любимый кот бабули", objective = "Найдите кота Шанса.", description = "Ах, да! Эвакуация...\n\nНо я не могу бросить здесь моего ненаглядного котика! Он такой рыжий, полосатый...\n\nВсе любит играть в сломанной повозке рядом с деревом к северо-востоку отсюда. Быстрее, сбегай за моим дорогим Шансом, и мы отправимся в путь.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Бабушкина колотушкаОранжевое покрывалоВы получите:\n\n"}
MultiLanguageQuestData['ru'][14402] = {title = "В путь!", objective = "Поговорите с Гвен Армстед в Темной Гавани.", description = "Думаю, теперь я готова отправиться в путь.\n\nМоя любимая книжка и дорогой котик при мне, и одета я – не стыдно людям показаться.\n\nОх, надеюсь, я ничего не забыла!\n\nСкажи этому вашему мэру, что я уже выхожу. Надеюсь, мы еще увидимся в городе!", progress = nil, completion = "Без преувеличения, ты совершил невозможное! Ты убедил бабулю Валь выйти из дома.\n\nГоворю тебе, ты – нечто особенное.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14403] = {title = "Братья Хейварды", objective = "Поговорите с Себастьяном Хейвардом в Рыбном хозяйстве Хейварда.", description = "Рыбное хозяйство Хейварда находится далеко на юге, и им уже многие годы заправляют братья Хейварды.\n\nОни нечасто выбираются в город – разве только для того, чтобы привезти очередную партию рыбы на продажу. Надо сообщить им, что эвакуация началась.", progress = nil, completion = "Ты пришел нам помочь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14404] = {title = "Судно требует ремонта", objective = "Найдите доски, угольную смолу и инструменты корабельного плотника.", description = "Говоришь, началась эвакуация? Что ж, мы подумывали о том же, когда на пороге появились Отрекшиеся.\n\nПо-моему, морской путь – самый безопасный, но наши лодки сильно потрепало во время последнего подземного толчка.\n\nЧтобы закончить починку, мне потребуются кое-какие материалы и инструменты. Если ты мне поможешь, мы с братьями сможем быстро уплыть отсюда.", progress = "Принес мои припасы, Арталег?", completion = "Отлично, Китбомба. Теперь я без труда закончу ремонт.", rewards = "Вы получите:\n\nСумка корабельного плотника"}
MultiLanguageQuestData['ru'][14405] = {title = "Спасение в море", objective = "Вернитесь к Гвен Армстед в Темную Гавань.", description = "Спасибо за помощь, <имя>. Наш корабль готов к отплытию.\n\nМожешь сказать мисс Армстед, что мы не присоединимся к наземной эвакуации.\n\nМы, Хейварды, всегда были морскими волками. Если уж нам придется покинуть наши дома – мы лучше уйдем в море.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14406] = {title = "Сад Краули", objective = "Поговорите с Лорной Краули в саду Краули.", description = "Ты, наверное, помнишь дочь лорда Дария Краули, Лорну.\n\nПотеряв отца, она так никогда и не оправилась от этого удара, и все время жила затворницей в своем доме. Она разрешала навещать ее только Креннану, но он ничего не хочет о ней рассказывать.\n\nВ любом случае, надо сообщить ей о начале эвакуации.", progress = nil, completion = "Stay back! Don't make me...\n\nIs it you?  By the Light!  It's you, &lt;имя&gt;!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14407] = {title = "Тоска Азшары", objective = "Отправляйтесь к Кейлеку в Гавань Трюмных Вод.", description = "Эй! Рада видеть тебя снова.\n\nЯ пришла по поручению моего хозяина, Кейлека. Ему нужна твоя помощь. Как можно скорее найди его в трущобах под мостом!", progress = nil, completion = "Спасибо, что пришел. Прости за скрытность, но очень важно, чтобы определенные личности не знали, где я.\n\nЯ нахожусь в достаточно трудном положении и я слышал о некоторых твоих последних свершениях. Выслушай меня, помоги мне, и тебя будет ждать награда.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14408] = {title = "План объекта номер 9", objective = "Найдите чертежи секретной ракеты в здании архива в восточной части лаборатории. Воспользуйтесь дверным звонком и убейте директора лаборатории, когда он появится.", description = "Мизерного интеллекта моих благодетелей хватило на то, чтобы построить межпланетный транспорт. Спроектирована эта так называемая \"ракета\" так, что в голову приходят мысли только о гибели. Но, думаю, небольшая доработка катализаторов топлива позволит создать стабильный состав, побочным продуктом которого будет пригодный для вдыхания кислород. Чтобы произвести такие изменения, мне нужны чертежи ракеты.\n\nБудем надеяться, что они еще не сгорели. Найди архив лаборатории и попытайся проникнуть в него. Чертежи должны быть у самого директора лаборатории, если, конечно, он еще жив.", progress = "Вероятно, архив где-то рядом, Спящийпутя. Найди эти чертежи!", completion = "&lt;Ящер хватает документы своими цепкими когтями и подносит чертежи к глазам, пренебрежительно щелкая острыми зубами.&gt;\n\nПохоже на детские каракули. Никто, обладающий здравым смыслом, не стал бы проводить управление гидравликой так близко с зарядом топлива для второй ступени! Впрочем, это поправимо.\n\nТы знаешь, как изменить топливную матрицу для изменений давления при неизменном ускорении? Нет? Ну ладно, ты можешь сделать для меня что-нибудь другое, пока я модифицирую ракету...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14409] = {title = "Осторожное возвращение", objective = "Отнесите журнал Дароса Морденту Вечерней Тени в Дарнас.", description = "Удели мне минутку внимания, <класс>.\n\nГрядут большие перемены, и это предчувствие заставило нас покинуть руины Эльдре'Таласа. Я прибыл сюда для исследования этого города и не могу оторваться от своей работы, но если у тебя есть свободное время, я мог бы дать тебе поручение.\n\nОдин из моих коллег отправился в Дарнас побеседовать с Верховной жрицей – он надеется, что мы сможем найти с ней общий язык. Пожалуйста, отнеси ему этот журнал – он может помочь ему в выполнении дипломатической миссии. Моего коллегу зовут Мордент Вечерняя Тень, и сейчас он находится в храме.", progress = "Похоже, у меня еще много времени, так почему бы и не побеседовать. О чем пойдет речь?", completion = "А, это записи Дароса! Он всегда очень скурпулезно относился к своим заметкам. Пожалуй, из этого журнала можно выяснить, как далеко мы продвинулись.\n\nСпасибо, что принес мне его. Возможно, когда мне удастся убедить окружающих в том, что мы не желаем вам зла, мы будем видеться гораздо чаще.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14410] = {title = "В дебрях Фераласа", objective = "Отправляйтесь в Фералас и поговорите с Телароном Полетом Ветра в Покоях Дремлющего.", description = "Ты храбро <сражался/сражалась>, охраняя покой этих земель вместе с нами. Если не возражаешь, здесь есть и другие, кому твоя помощь придется весьма кстати.\n\nК югу отсюда лежат нетронутые леса Фераласа. Там, под сенью Двух Колоссов, ты найдешь Теларона Полет Ветра. Он со своими товарищами-друидами из Покоев Дремлющего обнаружил признаки страшного заболевания.\n\nИм понадобится твоя помощь, <класс>. Поспеши туда.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14411] = {title = "Feralas Breadcrumb [PH]", objective = "Я еще вырасту до длиного задания! За Фералас!!!", description = "Я еще вырасту до длиного задания! За Фералас!!!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][14412] = {title = "Как в море корабли", objective = "Убейте 6 Отрекшихся-изгоев.", description = "Проклятье! Эти паршивые корабли Отрекшихся затонули прямо напротив нашего рыбхозяйства! Теперь вся уцелевшая нежить плывет прямо сюда, и мы просто не в состоянии дать им отпор!\n\nПожалуйста, помоги нам, пока я не закончу ремонт корабля.", progress = nil, completion = "Превосходно. Я уже почти закончил.", rewards = "Сапоги шлюпочникаРемонтный поясВы получите:\n\n"}
MultiLanguageQuestData['ru'][14413] = {title = "Вершина обучения", objective = "Поговорите с проекцией верховного мага Ксилема у подножия Волшебного замка.", description = "Это очень увлекательно! Ты <хотел/хотела> чего-то интересного? Ты это получишь!\n\nПришло время испытаний… время ТВОИХ испытаний. Много сложных задач надо будет выполнить, многому научиться. Ты многое узнаешь об испытаниях. Я узнаю многое о тебе.\n\nА теперь иди. В мой Волшебный замок. Там мы с тобой, конечно, снова встретимся, потому что я вездесущ.", progress = nil, completion = "Так быстро! Надеюсь, прогулка была приятной. Не сильно тошнило?\n\nВпереди еще много бега и прыжков, так что крепкий желудок тебе не помешает.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14414] = {title = "Feralas Breadcrumb [PH]", objective = "Я еще вырасту до длиного задания! За Фералас!!!", description = "Я еще вырасту до длиного задания! За Фералас!!!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][14416] = {title = "Голодный эттин", objective = "Приведите 5 горных коней Лорне Краули в сад Краули.", description = "Послушай, <имя>, без средств передвижения мы далеко не уйдем.\n\nЕсли мы попробуем уйти на своих двоих, Отрекшиеся мигом нас настигнут.\n\nЕще недавно мне бы не составило труда увести нескольких лошадей из стойл к юго-востоку отсюда, но последнее землетрясение заставило огромного эттина Корота спуститься с гор и искать пропитание в другом месте. Так что если мы в ближайшее время не заберем лошадей, это сделает он.", progress = "Ты уже вернулся, Братецрога?", completion = "Я позабочусь о том, чтобы эти лошади попали в Темную Гавань.", rewards = "Перчатки ЛорныПояс КраулиВы получите:\n\n"}
MultiLanguageQuestData['ru'][14418] = {title = "Cтражи смерти", objective = "Отнесите гроссбух Андрона Алерику Хоукинсу в Зал Темной Госпожи в Подгороде.", description = "Синдикат? Никогда бы не подумал. Низко же пали владыки Альтерака после предательства.\n\nХоукинс будет доволен, и раз именно ты <совершил/совершила> это открытие – тебе и сообщать о нем.\n\nАх да, как я мог забыть?\n\nДобро пожаловать в ряды стражей смерти.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКлинок хитрости"}
MultiLanguageQuestData['ru'][14419] = {title = "Cтражи смерти", objective = "Поговорите с Андроном Гантом в Подгороде.", description = "Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал. Мне приходилось встречаться с Андроном, он не настолько умен, чтобы заподозрить неладное.\n\nНаша госпожа подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно. Хорошо бы также получить доказательства.\n\nПоговори с Андроном и вытяни из него эти сведения. Его можно найти в лавке неподалеку от Района Фармацевтов.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14420] = {title = "Cтражи смерти", objective = "Принесите рекомендательное письмо Астора Менниту Каркаду в Квартал Разбойников Подгорода.", description = "Чтобы вступить в ряды стражей смерти, элитной охраны Темной Госпожи, тебе придется сперва доказать свои способности.\n\nНе буду лгать: это задание может окончиться твоей гибелью.\n\nМне нужна помощь в нескольких вопросах. Во-первых, принеси мне личные вещи Астора Хадрена – это вестник, путешествующий между Серебряным бором и Подгородом. Как ты это сделаешь – тебе решать.\n\nПока что это все, что тебе следует знать. Справишься – узнаешь больше.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14421] = {title = "Cтражи смерти", objective = "Отнесите гроссбух Андрона Менниту Каркаду в Квартал Разбойников Подгорода.", description = "Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной. Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочел бы иметь дело с тобой.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14422] = {title = "Ракета ящеров", objective = "Освободите из клеток пять экспериментальных ящеров и доставьте их объекту №9 к ракете.", description = "Вскоре после того, как мой интеллект возрос, я воспользовалась объектом №4, чтобы обзавестись потомством и создать уникальную расу сверхумных ящеров. Впоследствии объект №4 стал избегать контактов со мной, и я решила вынуть из него все внутренности в нашу следующую встречу.\n\nТем не менее, в лаборатории осталось достаточно наших детей с отличным наборов генов, подходящим для развития моей расы. Пожалуйста, освободи их из клеток и принеси к ракете.", progress = "Когда ты будешь освобождать моих прекрасных деток, они могут попытаться тебя укусить, но на их текущей стадии физического развития маловероятно, что их укусы будут смертельными.", completion = "Чудесно! Образцовая работа, Спящийпутя! Как ты, наверное, уже догадалась, я планирую сделать из этой ракеты что-то вроде звездной колыбели, ковчега, если хочешь, который позволит моей новой расе вырваться с этой мрачной разоренной планеты и создать новый мир в соответствии с нашими желаниями. И для этого мы эффективно тобой воспользовались. Пожалуйста, прими вознаграждение в этой валюте. Свои денежные знаки я выпущу после нашего прибытия. Прощай, Спящийпутя!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14423] = {title = "Бульдозерсизм", objective = "Воспользуйтесь освященным сигнальным пистолетом, чтобы призвать жреца на помощь, а затем \"изгоните духов\" из бульдозера.", description = "…нам нужен жрец!\n\nК счастью, небольшая часть моего бюджета предусматривает освящение техники. Возьми это сигнальное ружье и отправляйся к Марджену, моему несчастному любимому сломанному бульдозеру. Дай сигнал, после чего появится один из наших жрецов-десантников и возьмет ситуацию под свой контроль. Возвращайся, когда о моем бульдозере позаботятся!", progress = "Как дела у Марджена? Снова здоров и весел?", completion = "Что? Что?..\n\nМарджен! О, мой дорогой Марджен!!", rewards = "Жилет бульдозеристаРемонтные перчатки для МардженаСтандартный пояс десантникаВы получите:\n\n"}
MultiLanguageQuestData['ru'][14424] = {title = "Снова нужна наука", objective = "Найдите ассистентку Грили на южной конечной станции ракетной дороги. Ракетная дорога гоблинов позволяет быстро перемещаться по Азшаре.", description = "<Дубник утирает слезы, а потом решительно выдвигает вперед подбородок.>\n\nБольше никогда, <имя>! Ни один бульдозер не заслуживает судьбы моего Марджена. Нам нужно позаботиться о некоторой духонепроницаемости. Это работа для наших лучших ученых, я как раз знаю одну сотрудницу, которой она будет по плечу! Поищи ассистентку Грили на южной конечной станции ракетной дороги. Она администратор всемирно известной секретной лаборатории Азшары и она мне кое-чем обязана.", progress = nil, completion = "О чем там говорит Дубник? Испорченная духами строительная техника? А что, похоже, что у меня есть время на охоту за привидениями?\n\nМоя лаборатория наполовину расплавилась, огонь повсюду, животные мутируют, и – что куда хуже – сроки проектов срываются. Мне самой не помешала бы помощь!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14427] = {title = "Item Quest", objective = "Get the items", description = "Item collection quest", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][14428] = {title = "Записи сказительницы Янтарный Ветер", objective = "Убейте сказительницу Янтарный Ветер в Лагере дарнасских эльфов и возьмите ее записи.", description = "Если моим источникам можно верить, сказительница Янтарный Ветер предсказывает, что Альянс будет исследовать руины на востоке. Я еще не выяснял, каковы границы ее возможностей: я надеюсь, что ты дашь мне полный отчет, вынудив ее на поединок и убив ее.\n\nРаз она \"сказительница\", то, наверное, при ней будут записи, в которых будет описано, что затевают эти ночные эльфы. Достань мне эти записи. И необязательно бежать обратно; воспользуйся их же собственными гадальными камнями и свяжись со мной оттуда.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14429] = {title = "Разрушение порождений тайной магии", objective = "Убейте начинающих наставников и начинающих исследователей и соберите 10 настроенных рунических камней.", description = "Порождениями тайной магии являются существа, созданные при помощи чистой маны и интеллекта. При правильном использовании порождение позволяет своему владельцу быстро усваивать огромное количество знаний тайной магии. Но порождения опасны, <имя>. Очень умны! Очень могущественны! И очень чувствительны к внешним злонамеренным воздействиям...\n\nДавай поучим этих любителей и используем против них их же собственную магию. Убей начинающих наставников и исследователей и возьми их рунические камни. Когда закончишь, свяжись со мной при помощи нижнего гадального камня.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14430] = {title = "Взлом порождений тайной магии", objective = "Обратитесь к порождению тайной магии в Лагере дарнасских эльфов и произнесите магические слова.", description = "А теперь мы возьмем под контроль их порождения тайной магии и устроим хаос. Ты раньше <слышал/слышала> о магии такого типа, <имя>? Нет? Ха! Это делает мой план еще более восхитительным. Поблизости должно находиться огромное порождение тайной магии. Благодаря собранным тобой руническим камням, мы знаем, как с ним общаться. Обратись к нему и скажи: \"Аль'тет к'толгар\". <Понял/Поняла>? Повтори. Довольно похоже. А потом снова свяжись со мной и расскажи, что происходит!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Поножи крушителяНаручи магаВы получите:\n\n"}
MultiLanguageQuestData['ru'][14431] = {title = "Овраг Черночревов", objective = "Убейте 8 биологов с заставы Талрендис, обыщите одно из тел и заберите оперативную информацию Черночревов.", description = "С тех пор, как мы обосновались в Азшаре, фурболги из племени Черночревов, которые живут в этих краях, отделились от своих собратьев Древобрюхов. Они стали дикими, <класс>, и то и дело нападают на наших воинов. Хуже того, мы видели, что они на дружеской ноге с ночными эльфами с Талрендис. Мы не можем допустить, чтобы они стали союзниками!\n\nК юго-западу отсюда ты найдешь большой овраг, где, как сообщают мои разведчики, ночные эльфы особенно активны. Убей их и собери всю оперативную информацию, какую найдешь.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14432] = {title = "Отвар из древовидного вереска", objective = "Принесите 10 порций отвара из древовидного вереска из крепости Черночревов.", description = "Похоже, что наши неприятели из Альянса продвинулись в своих переговорах с Черночревами, начав говорить на языке фурболгов. Если мы хотим помешать им достичь договоренности, нам надо сделать то же самое.\n\nЭто не так сложно, как кажется, <имя>. Черночревы делают крепкий отвар из древовидного вереска. Вдыхая его аромат, переходишь в состояние, близкое к трансу, и сможешь говорить на разных языках. В частности, на языке Черночревов. Отправляйся в крепость Черночревов к юго-западу отсюда и принеси мне этот отвар!", progress = "Как дела? Я сам пробовал как-то эти травки, но они были слишком горькие, даже для такого обладателя луженого желудка, как я.", completion = "Прекрасно, этого достаточно. Мы вскипятим все это, и ты сможешь насладиться ароматом, а потом вмиг заговоришь, как фурболг. Детали нашего плана прорисовываются…", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14433] = {title = "Обратная сторона дипломатии", objective = "Заберите из крепости Черночревов план встречи Черночревов, убейте посланницу с заставы Талрендис и заберите его одеяния посла.", description = "Чтобы помешать переговорам Черночревов, мы должны знать, где они будут проходить. Я думаю, что в крепости Черночревов к юго-западу отсюда ты найдешь послов ночных эльфов, занимающихся приготовлениями.\n\n<Хаггрум сплевывает на землю.>\n\nУбей их, когда тебе будет удобно, и обыщи территорию. Постарайся найти важные документы. Да, и захвати несколько одеяний послов, они нам понадобятся.", progress = "Принес одеяния? Андорел тут на скорую руку сообразил нам немного полезной магии.", completion = "Отлично сработано! Дай мне взглянуть на эти документы. Хм. Теперь мы точно знаем место и время проведения окончательных переговоров. Не переживай, если одеяния тебе малы или велики – я все устрою.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14434] = {title = "Деревня Рут'теран", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nTeleport to Rut'theran\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][14435] = {title = "Обман Черночревов", objective = "Наденьте маскировочные одеяния посла и обратитесь к Андорелу Верному Солнцу, чтобы он телепортировал вас в крепость Черночревов. Поговорите с Унгарлом, чтобы сорвать переговоры. Затем убейте на обратном пути 4 воинов из клана Черночревов и 4 шаманов из клана Черночревов.", description = "Андорел тут немного поколдовал для меня. Подойди сюда, встань у огня и погрузись в пары отвара. Накинь одеяния, и ты станешь выглядеть, как посол ночных эльфов.\n\nНадень маскировочные одеяния и поговори с Андорелом здесь в лагере. Он телепортирует тебя в самое сердце крепости Черночревов, где будут проходить переговоры. Поговори с вождем Унгарлом и не дай заключить соглашение. А на обратном пути убей столько Черночревов, сколько сможешь!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Дипломатический поясВысокие ботинки переговоровПерчатки нарушающего договорВы получите:\n\n"}
MultiLanguageQuestData['ru'][14436] = {title = "Дворфийские делишки", objective = "Соберите 5 кирок геолога.\n\nСломайте их в кузнице. \n\nОтнесите 5 сломанных инструментов Ахмо Громовому Рогу в деревню Кровавого Копыта.", description = "Некие дворфы готовят раскопки на северо-западе – полагают, что в земле скрыты великие тайны. В некотором роде они правы, но оскверняя и уродуя лик природы, нельзя постигнуть ее мудрость. \n\nСобери инструменты дворфов, уничтожь их и принеси мне.\n\nЛомать инструменты можно в кузнице, которая есть в Громовом Утесе, но подойдет любая, даже та, что находится в дворфийском лагере.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #5Currency Token Test Token 4"}
MultiLanguageQuestData['ru'][14437] = {title = "Обряды Матери-Земли", objective = "Отнесите тотем Соколиного Ветра Ахмо Громовому Рогу в Деревню Кровавого Копыта. Следуйте по дороге из Лагеря Нараче.", description = "Чтобы продолжить прохождение обрядов Матери-Земли, ты <должен/должна> выдержать еще два испытания. Тебе бы не помешало поднабраться опыта, <имя>.\n\nОтправляйся в Деревню Кровавого Копыта и найди Ахмо Громового Рога. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утеса. \n\nОтнеси этот тотем Ахмо. Он узнает мою руку в этой резьбе и поможет тебе в твоем путешествии.\n\nСледуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14438] = {title = "Недобрые соседи", objective = "Убейте 15 гноллов из стаи Бледногривов и возвращайтесь к Ахмо Громовому Рогу в деревню Кровавого Копыта.", description = "<имя>, нашей земле причиняют боль раздоры ее обитателей. Я надеюсь, что тебе не суждено увидеть столько войн, сколько выпало мне. И все же я вынужден просить тебя вступить в бой. Так ты поймешь, что малая угроза, если не искоренить ее, со временем разрастается.\n\nГноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора.\n\nСловами их не остановить.", progress = nil, completion = "Хорошо, что ты отнесся к моему заданию со всей серьезностью, Зябкин. Очень важно уважать землю и ее обитателей. Жизнь и смерть – это вечный цикл... Необходимость. Одно не может существовать без другого. Обдумай это хорошенько и никогда не забывай.", rewards = "Вы получите:\n\nПлащ Громового рогаCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14439] = {title = "Путешествие в Громовой Утес", objective = "Поговорите с Бейном Кровавым Копытом в Громовом Утесе.Отныне тебя будут почитать в стенах нашего великого города. <Прошедший/Прошедшая> обряды Матери-Земли заслуживает такой чести.\n\nВыполни последнее задание, отыщи нашего юного вождя Бейна Кровавое Копыто, живущего на вершине высочайшего плато в Громовом Утесе.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Отныне тебя будут почитать в стенах нашего великого города. <Прошедший/Прошедшая> обряды Матери-Земли заслуживает такой чести.\n\nВыполни последнее задание, отыщи нашего юного вождя Бейна Кровавое Копыто, живущего на вершине высочайшего плато в Громовом Утесе.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14440] = {title = "Обряды Матери-Земли", objective = "Бейн Кровавое Копыто из Громового Утеса попросил принести ему рог Арра'чеи.", description = "Ты <прошел/прошла> обряды Матери-Земли и <заслужил/заслужила> достойное место среди жителей Громового Утеса.\n\nЧтобы сохранить это таким трудом заработанное место, тебе придется и дальше служить своему народу.\n\nМы охотники, <имя>. Внизу, в Мулгоре, есть могучий кодо по имени Арра'чея. Выследи и убей его, проявив свое искусство охотника, и принеси мне рог Арра'чеи.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПоножи охотника на кодо"}
MultiLanguageQuestData['ru'][14441] = {title = "Автограф Гарроша", objective = "Отправляйтесь в Оргриммар и постарайтесь получить автограф Гарроша Адского Крика для своего подопечного.", description = "Говорят, что Гаррош Адский Крик – один из величайших героев Орды. Когда я вырасту, я тоже хочу стать героем Орды!\n\nТы <знаком/знакома> с Гаррошем? Окажи мне услугу! Возьми у него автограф! Я не знаю, как его попросить, у него нет времени для таких, как я... другое дело ты! Ты <такой же искатель/такая же искательница> приключений, как и он! Готов поспорить, что тебе получить у него автограф – раз плюнуть!\n\nПожалуйста!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14442] = {title = "Мой любимый объект", objective = "Найдите объект №9 где-то возле комплекса секретной лаборатории в Азшаре.", description = "Не знаю, <обратил/обратила> ли ты внимание на это, но весь комплекс лаборатории представляет собой весьма плачевное зрелище! Не очень жалко списать всех этих гиппогрифов, но пропал еще и результат моего лучшего эксперимента – объект №9!\n\nОбъект №9 – это самка ящера, которую мы привезли из Степей. Интересно, жива ли она еще? Посмотри у главного комплекса к западу отсюда, возле гигантской сверхсекретной ракеты. Не заметить ее нельзя.", progress = nil, completion = "Ты пришел помочь мне в моей работе? Мои когти довольно ловкие, но я с неохотой должна признать, что мои лапы уж очень короткие.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14443] = {title = "Потертая рукоять", objective = "Принесите потертую рукоять Каладису Сияющему Копью в Покой Кель'Делара к югу от ристалища Серебряного Турнира.", description = "Эта потертая рукоять меча знавала лучшие дни, но даже сейчас по ней можно сказать, что делал ее настоящий мастер.\n\nИзящная гравировка и инкрустация драгоценными камнями свидетельствует о том, что оружие некогда принадлежало знатному человеку. Серебряный союз наверняка заинтересуется этой находкой. Найдите его представителя в Покое Кель'Делара, он находится к югу от Ристалища Серебряного турнира.", progress = "Что это у тебя?", completion = "&lt;Каладис бережно забирает у вас рукоять и осматривает ее со всех сторон.&gt;\n\nЧто-то знакомое видится мне в этой вещи... как будто я знаю, откуда она могла взяться. Говоришь, нашел ее в цитадели? Очень интересно.\n\nМало осталось кузнецов, способных выковать подобный клинок, но, возможно, они прольют свет на тайну твоей находки.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14444] = {title = "То, что знают драконы", objective = "Поговорите с Красом на вершине Храма Драконьего Покоя.", description = "Ошибки быть не может – это рукоять могущественного древнего клинка. Вот только что это был за клинок? Я не могу вспомнить ни одного меча с такой гравировкой, но не все еще потеряно.\n\nМы должны обратиться к Кориалстразу, более известному тебе как Крас. Он – давний друг кель'дорай и Кирин-Тора. За его плечами мудрость рода красных драконов; наверняка, он сможет нам помочь. Отправляйся за его советом на вершину Храма Драконьего Покоя.", progress = nil, completion = "Нельзя допустить, чтобы книга осталась в руках Похитителей Солнца. Если мы рассчитываем опознать этот меч и использовать его в наших целях, надо найти способ перехватить книгу, которую одолжил им Крас.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14445] = {title = "До скорой встречи", objective = "Поговорите с Хамми Кофельнагель на Лесном наблюдательном пункте на Затерянных островах.", description = "Наши судьбы соединены навеки. То, что сейчас происходит на наших глазах, изменит облик мира и в конце концов его уничтожит. Поэтому мы должны изменить ход событий, пока не поздно.\n\nЗнай, <брат/сестра>, ты всегда можешь рассчитывать на меня! Мы встретимся на большом острове. И пусть до тех пор ничто не нарушит твой душевный покой, <имя>.", progress = nil, completion = "Ух ты! Неужели это тот, о ком я думаю?\n\nЭто ты спас Тралла, вождя Орды?!\n\n&lt;Хамми оценивающе смотрит на вас.&gt;\n\nНу что ж, как насчет того, чтобы отправиться вон на тот остров побольше? У меня нет ни малейшего желания переплывать этот пролив, кишащий акулами.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][14446] = {title = "Катаклизм!", objective = "Намбрия желает, чтобы вы взглянули в Воды предвидения.", description = "Внимай мне, <класс>!\n\nВетра перемен уже превратились в неумолимый шторм, несущийся по всему Азероту.\n\nДостанет ли тебе отваги справиться с истинной причиной наших бед?\n\nСобери всю свою решимость, <раса>, и моли, чтобы сила и удача не оставили тебя в грядущих испытаниях.\n\nНежданный союзник кинул клич всем, кто услышит. Взгляни в Воды предвидения – и узри судьбу мира!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14447] = {title = "Уж кто бы говорил!", objective = "По заданию покорителя небес Корма поговорите с Кольтирой Ткачом Смерти на борту \"Молота Оргрима\".Несмотря на то, что нам надлежит методично атаковать силы Альянса, не стоит забывать и о Плети.\n\nПусть еще несколько недель у нас не будет хватать сил для серьезного нападения на ледник, но это не должно нам помешать хорошенько изучить вражеские укрепления.\n\nЯ попросил нашего агента – одного из рыцарей смерти – помочь тебе в данном начинании. Кто может знать о противнике лучше, чем они?\n\nПозволь представить тебе Кольтиру Ткача Смерти.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Несмотря на то, что нам надлежит методично атаковать силы Альянса, не стоит забывать и о Плети.\n\nПусть еще несколько недель у нас не будет хватать сил для серьезного нападения на ледник, но это не должно нам помешать хорошенько изучить вражеские укрепления.\n\nЯ попросил нашего агента – одного из рыцарей смерти – помочь тебе в данном начинании. Кто может знать о противнике лучше, чем они?\n\nПозволь представить тебе Кольтиру Ткача Смерти.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14448] = {title = "Уж кто бы говорил!", objective = "По заданию покорителя небес Корма поговорите с Кольтирой Ткачом Смерти на борту \"Молота Оргрима\".Несмотря на то, что нам надлежит методично атаковать силы Альянса, не стоит забывать и о Плети.\n\nПусть еще несколько недель у нас не будет хватать сил для серьезного нападения на ледник, но это не должно нам помешать хорошенько изучить вражеские укрепления.\n\nЯ попросил нашего агента – одного из рыцарей смерти – помочь тебе в данном начинании. Кто может знать о противнике лучше, чем они?\n\nПозволь представить тебе Кольтиру Ткача Смерти.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Несмотря на то, что нам надлежит методично атаковать силы Альянса, не стоит забывать и о Плети.\n\nПусть еще несколько недель у нас не будет хватать сил для серьезного нападения на ледник, но это не должно нам помешать хорошенько изучить вражеские укрепления.\n\nЯ попросил нашего агента – одного из рыцарей смерти – помочь тебе в данном начинании. Кто может знать о противнике лучше, чем они?\n\nПозволь представить тебе Кольтиру Ткача Смерти.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14449] = {title = "Первый шаг", objective = "Идите по дороге на восток от Лагеря Нараче и найдите Грулла Соколиного Ветра.", description = "То, что ты видишь, <дружок/девочка>, – это работа свинобразов. Год за годом они нападают на нашу деревню. Из-за катаклизма, поразившего весь мир, они покинули свои жилища, заполонили землю, как саранча, и ты видишь, к чему это привело. Моя собственная мать погибла, став жертвой их свирепости.\n\nСегодня ты <стал совершеннолетним/стала совершеннолетней>. Сегодня ты возьмешь в руки оружие, будешь сражаться за племя и отомстишь за Великую Мать. Иди по дороге на восток и найди моего сына, Грулла. Он направит тебя в нашей борьбе против свинобразов.", progress = nil, completion = "Это будет твое первое настоящее испытание, таурен.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][14450] = {title = "Random Drop Test Progressive", objective = "Get 10 Progressive Widgets.", description = "This quest tests random drops with progressive drop percentage.", progress = nil, completion = nil, rewards = nil}
