MultiLanguageQuestData['ru'][24792] = {title = "Засланный шпион", objective = "Найдите следователя Феззена Клейстра в Крепости Темного Клыка.", description = "Кажется мне, что ты вполне можешь стать во главе этой операции. В журнале сказано, что он скрывается в Крепости Темного Клыка, и именно туда я намереваюсь тебя послать.\n\nОдин из наших людей уже проделал этот путь, но он недостаточно силен, чтобы закончить начатое. Иди же и встреться со следователем – да не забудь прихватить с собой друзей!", progress = nil, completion = "Потрясающе! Мне как раз нужна помощь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24793] = {title = "Засланный шпион", objective = "Найдите следователя Феззена Клейстра в Крепости Темного Клыка.", description = "Кажется мне, что ты вполне можешь стать во главе этой операции. В журнале сказано, что он скрывается в Крепости Темного Клыка, и именно туда я намереваюсь тебя послать.\n\nОдин из наших людей уже проделал этот путь, но он недостаточно силен, чтобы закончить начатое. Иди же и встреться со следователем – да не забудь прихватить с собой друзей!", progress = nil, completion = "Потрясающе! Мне как раз нужна помощь.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24794] = {title = "Поговорить с Мучей", objective = "Поговорите с Мучей Кусора на заставе Маршалла.", description = "Моя давняя подруга Муча последнее время сильно обеспокоена. Я бы помог ей, но, как видишь, мне тут сейчас более чем комфортно.\n\nНе <мог/могла> бы ты проведать ее и выяснить, в чем дело?", progress = nil, completion = "Что? Тебя послал Кракл?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24795] = {title = "Победа Серебряного союза", objective = "Принесите восстановленный Кель'Делар Вершительнице правосудия Мариэль Чистосердечной на ристалище Серебряного Турнира.", description = "Несмотря на дерзкие слова королевы Лана'тель, тебе удалось восстановить Кель'Делар. О, <имя>, как же долго мы ждали этого момента!\n\nСеребряный союз и все кель'дорай у тебя в неоплатном долгу.\n\nУвы, клинок почувствовал, что ты <неопытен/неопытна> в обращении с мечами, и потому не связал с тобой свою силу. Кто же станет его истинным хозяином? Только Серебряный Авангард сможет это определить. Отправляйся к ристалищу Серебряного Турнира и передай этот клинок Вершительнице правосудия Мариэль Чистосердечной.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Дубинка неистового правосудияМолот очищения огнемСпираль СветаВы получите:\n\n"}
MultiLanguageQuestData['ru'][24796] = {title = "Победа Серебряного союза", objective = "Принесите восстановленный Кель'Делар Верисе Ветрокрылой в Аметистовую цитадель Даларана.", description = "Несмотря на дерзкие слова королевы Лана'тель, тебе удалось восстановить Кель'Делар. О, <имя>, как же долго мы ждали этого момента!\n\nСеребряный союз и все кель'дорай у тебя в неоплатном долгу.\n\nВериса Ветрокрылая, предводитель Серебряного союза, просила о встрече с тобой после того, как ты вернешься из Солнечного Колодца. Захвати с собой Кель'Делар и отправляйся в Аметистовую цитадель Даларана. Она ждет тебя.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Кель'Делар, Коварство тенейКель'Делар, Око разумаКель'Делар, Могущество верныхКель'Делар, Жестокость отвергнутыхВы получите:\n\n"}
