MultiLanguageQuestData['ru'][24823] = {title = "Путь разрушения", objective = "Ты желаешь и дальше идти путем разрушения?", description = nil, progress = "Ты желаешь и дальше идти путем разрушения?", completion = "Ты по-прежнему отважно сражаешься на нашей стороне, Щук. Прими это кольцо не как дар, но как оружие в войне против Плети.", rewards = "Вы получите:\n\nПепельное кольцо непревзойденного разрушения"}
MultiLanguageQuestData['ru'][24824] = {title = "Потревоженная земля", objective = "Соберите 4 фрагмента потревоженной земли из потревоженных элементалей земли.", description = "Мы здесь для того, чтобы следить за разломами земной коры и замечать первые признаки нестабильности. Несмотря на то, что пока нам не удалось что-либо обнаружить, дополнительные подземные толчки еще возможны. Они подвергнут Степи еще большему разорению.\n\nНа северо-востоке, рядом с расселиной, неистовствуют земляные элементали. Для того, чтобы успокоить землю, их необходимо уничтожить как можно быстрее, а потом и их субстанции, проведя подобающий ритуал. Если ты поможешь нам в этом, <класс>, я буду счастлива достойно отблагодарить тебя.", progress = "Элементы должны быть тщательно сбалансированы, поэтому возвращение сущностей очень важно. Надеюсь, ты собрал их…", completion = "Спасибо, друг. Очень важно использовать все доступные способы, чтобы успокоить землю.", rewards = "Вы получите:\n\n"}
