MultiLanguageQuestData['ru'][24846] = {title = "Перемены в душе", objective = "Ты желаешь избрать другой путь, Ханнибубу?", description = nil, progress = "Ты желаешь избрать другой путь, Ханнибубу?", completion = "Надеюсь, ты обретешь то, что ищешь, брат мой.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПепельное кольцо бесконечного разрушенияПепельное кольцо безграничной мудростиПепельное кольцо безграничной отвагиПепельное кольцо безграничной мощи"}
