MultiLanguageQuestData['ru'][24848] = {title = "Фейерверки в \"Позолоченной розе\"", objective = "Поговорите с Марион Саттон в \"Позолоченной розе\", которая находится в Торговом квартале Штормграда.", description = "<Малыш/Малышка>, это не просто дурно пахнет. В этом ящике хранились ракеты, начиненные каким-то химическим реактивом. Я не могу определить на месте, что это было, но и в лабораторию тебе бежать не придется.\n\nВместо этого мы подкупим парня, который изготовил эти штуки. Я узнал марку производителя – это Снивел Ржавстер.\n\nИз достоверных источников мне стало известно, что Ржавстер сейчас находится здесь, в Штормграде. Он снял комнату в \"Позолоченной розе\", и его часто видят в компании одной молодой дамы, Марион Саттон. Отправляйся в таверну и разузнай, что ей известно.", progress = nil, completion = "Ты... А где же Ржавстер? Это он послал тебя? Слава небесам, он так задерживается, что я чуть было не впала в отчаяние...\n\n&lt;Девушка начинает понимать, что у вас нет никакого послания от Ржавстера, и глаза ее наполняются слезами.&gt;\n\nЭто так на него непохоже... но что еще мне остается думать?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24849] = {title = "По горячим следам", objective = "Поищите Снивела Ржавстера в счетной палате Штормграда, аукционном доме и парикмахерской.", description = "Это долгая история, <имя>. Я влюбилась в него с первого взгляда... понимаешь, было в этом гоблине что-то такое, особенное, что я глаз от него не могла отвести.\n\nМы провели вместе целую неделю, а потом Снивел сказал, что получил кучу денег, и потому берет меня с собой на отдых в Южных морях! Представляешь?\n\nВ общем, он велел мне собирать вещи, пока он улаживает кое-какие дела. Он собирался только зайти в банк, аукционный дом и парикмахерскую, но так и не вернулся! Я уже начинаю думать, что меня попросту обманули...", progress = "Ты его нашел?", completion = "Он говорил только о том, как смыться из города со всеми деньгами? Значит, он действительно меня бросил...\n\nАх, Варкинсан, как глупо было поверить его обещаниям, но я не могла удержаться. Он был таким обольстительным!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24850] = {title = "Возлюбленная Ржавстера", objective = "Поговорите с Рокой в \"Туристическом снаряжении Готри\", что в Волоке в Оргриммаре.", description = "<Малыш/Малышка>, это не просто дурно пахнет. В этом ящике хранились ракеты, начиненные каким-то химическим реактивом. Я не могу определить на месте, что это было, но и в лабораторию тебе бежать не придется.\n\nВместо этого мы найдем парня, который изготовил эти штуки. Я узнал марку производителя – это Снивел Ржавстер.\n\nИз достоверных источников мне стало известно, что Ржавстер сейчас находится здесь, в Оргриммаре. Его часто видели в компании одной цыпочки по имени Рока. Говорят, они должны были встретиться возле \"Туристического снаряжения Готри\", что в Волоке, а затем убежать вместе.", progress = nil, completion = "Ты явно не Ржавстер. А он должен был появиться здесь еще час назад! Что ты с ним сделал?\n\n&lt;Рока немного успокаивается, услышав, что вы тоже ищете Ржавстера, но теперь ее глаза застилают слезы.&gt;\n\nМилый мой Ржавстер, это так на него непохоже... Неужели с ним что-то случилось?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24851] = {title = "По горячим следам", objective = "Поищите Снивела Ржавстера в банке Оргриммара, что на Аллее Силы, аукционном доме и парикмахерской.", description = "Это долгая история, <имя>. Я влюбилась в него с первого взгляда... понимаешь, было в этом гоблине что-то такое, особенное, что я глаз от него не могла отвести.\n\nМы провели вместе целую неделю, а потом Снивел сказал, что получил кучу денег, и потому берет меня с собой на отдых в Южных морях! Представляешь?\n\nВ общем, он велел мне собирать вещи, пока он улаживает кое-какие дела. Он собирался только зайти в банк, аукционный дом и парикмахерскую, но так и не вернулся! Я уже начинаю думать, что меня попросту обманули...", progress = "Ты его нашел?", completion = "Он говорил только о том, как смыться из города со всеми деньгами? Значит, он действительно меня бросил...\n\nАх, Профессия, как глупо было попасться на удочку этому мерзкому гоблину. Но он был таким обольстительным при нашей первой встрече!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24852] = {title = "Наше племя в плену", objective = "Откройте 4 клетки свинобразов.", description = "Хоть свинобразы и невелики, зато они намного превосходят нас численностью. Даже самому большому из нас не справиться, если свинобразы нападут группой. Многие юные таурены взялись за оружие, чтобы защитить наш дом. Некоторые из них отдали свои жизни, а кого-то схватили живыми.\n\nПожалуйста, найди клетки, в которых сидят пленные таурены, и освободи их. Нападение собьет свинобразов с толку.", progress = nil, completion = "Благодаря тебе наши люди свободны и могут защищать наш дом.", rewards = "Перчатки Красного ОблакаУтыканные перьями сапогиВы получите:\n\n"}
MultiLanguageQuestData['ru'][24854] = {title = "В поисках Когтя Бури", objective = "Поговорите с Гарлом Когтем Бури, который находится недалеко от входа в Кратер Ун'Горо.", description = "Зен'Алири следует путем друида, <раса>. Есть надежда, что однажды Зен'Алири присоединится к друидам-воронам и сможет как буревестник парить высоко в небе над кратером.\n\nНо мой наставник говорит: сейчас я остаюсь здесь и жду. Так ждет и Зен'Алири.\n\nЯ знаю еще одного друида, кому твоя помощь может оказаться полезной. Его зовут Гарл Коготь Бури. Он изучает реагенты где-то к востоку отсюда. Может быть тебе пойти поговорить с ним?", progress = nil, completion = "Зен'Алири правильно поступил, отправив тебя сюда. Я зашел в тупик в своих исследованиях.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24855] = {title = "Ненормальная растительность", objective = "Уничтожьте 11 взрослых кровоцветов. Подойдут любые их виды.", description = "Взгляни, как странно реагирует растительность на кровоцветы в Тревожных садах, что на севере. Деревья усыпаны цветами, и побегов стало гораздо больше. Из земли тянутся огромные странные цветы, которые никогда не росли в тех местах раньше.\n\nСама земля взывает к нам, <раса>. Кровоцветы нарушают баланс.\n\nМое последнее задание тебе будет таким: доберись до скопления взрослых кровоцветов и сократи их число.", progress = nil, completion = "Ты пахнешь пыльцой кровоцветов, |3-6(Друид). Хорошо.\n\nТы заслужил свою награду.", rewards = "Конфискованное ружье браконьераПлащ кровоцветаВы получите:\n\n"}
MultiLanguageQuestData['ru'][24856] = {title = "Неотвратимое вторжение!", objective = "Поговорите с Мегз Жестекрошшер у западного входа в руины Вайш'элана на Затерянных островах.", description = "Здесь твоя работа завершена, но ты, как я понимаю, без дела грустишь и чахнешь. Покой и скука – оно не для нас, верно?\n\nПомнишь Мегз Жестекрошшер, нашу старую подругу и по совместительству – торгового представителя? Она сейчас за холмами на юго-востоке, сразу за утесом Ящеров. Если пойдешь из города по дороге на восток, а потом на развилке свернешь на юг, ты ее не пропустишь.\n\nНасколько мне известно, у нее там возникли какие-то недоразумения со змеелюдьми из руин на берегу. Может быть, сходишь туда – разберешься?", progress = nil, completion = "У нас возникла небольшая проблема.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][24857] = {title = "Нападение на Лагерь Нараче", objective = "Отнесите план нападения племени Дыбогривов вождю Соколиному Ветру в Лагерь Нараче.", description = "Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения племени Дыбогривов на Лагерь Нараче. \n\nВождь Соколиный Ветер непременно должен об этом узнать!", progress = "Ты чем-то обеспокоен, Анвалт? Какую весть ты принес?", completion = "Это и в самом деле тревожные новости! Но, зная об этих коварных планах, мы сможем призвать своих сородичей из Деревни Кровавого Копыта и отразить атаку. Сегодня ты спас жизни многих тауренов, Анвалт!", rewards = "Вы получите:\n\nУтолщенный лубяной кулачный щит"}
MultiLanguageQuestData['ru'][24858] = {title = "Представитель картеля Трюмных Вод", objective = "Уничтожьте 10 знамен наг и замените их на знамена картеля Трюмных Вод.", description = "Похоже, наги в руинах собираются напасть на наш Городок-из-табакерки. И доказательство тому – эти трупы разведчиков.\n\nНе знаю как ты, а я не собираюсь сидеть сложа руки. Давай нанесем превентивный удар!\n\nМожешь заложить основы наших прибрежных владений, заменив их флаги нашими? Ведь этой земле цены нет!", progress = nil, completion = "Как жаль, что мне не удалось увидеть их чешуйчатые морды, когда они заметили, что знамена заменили.\n\nС другой стороны, я совсем не горю желанием видеть их оскаленные пасти.", rewards = "Пояс из змеиной чешуиПлащ из знамениВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][24859] = {title = "Шкуры наг", objective = "Добудьте 5 целых шкур наг.", description = "По углам то и дело шепчутся о материале таком прочном и изящном, что гоблины, обладающие утонченным вкусом, готовы выложить за него кучу бабок.\n\nДа, конечно, я говорю о шкуре наг!\n\n<Бретт оглядывается по сторонам, чтобы убедиться в том, что никто не подслушивает.>\n\nЯ знаю, что ты идешь туда и что тебе придется сражаться с ними. Слушай, им же все равно не понадобятся их шкуры! Они же будут уже мертвы!", progress = "Ну? Сколько достанется мне? Думаю, вполне справедливо будет разделить в пропорции 95 к 5.", completion = "Мы будем купаться в деньгах, точно тебе говорю! Ну, конечно, если сумеем выбраться с этого острова.", rewards = "Вы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][24861] = {title = "Погребальный обряд", objective = "Принесите церемониальную жертву на могиле Великой Матери Соколиный Ветер.", description = "Лагерю больше ничто не угрожает, свинобразов мы с твоей помощью прогнали, за что прими мою самую искреннюю благодарность. Спасибо за все, что ты <сделал/сделала> для моей матери, сына – всех нас.\n\nА сейчас мы должны проводить Великую Мать Соколиный Ветер в последний путь. Положи жертвенное подношение к ее ногам, <имя>, а потом мы простимся.", progress = nil, completion = "Во всем должно быть равновесие. Дух Великой Матери Соколиный Ветер отправляется в последний путь, а твой – только начинается.", rewards = "Вы получите:\n\nПредмет #1Currency Token Test Token 4"}
MultiLanguageQuestData['ru'][24862] = {title = "Тяжелые испытания", objective = "Убейте 8 разведчиков Охотничьего холма.", description = "Посмотри вокруг, <класс>. Нам не удалось избавиться от слежки – эта долина испещрена тайными тропами, знакомыми лишь Орде. Они организуют засады там, где это, казалось бы, невозможно, и грабят наши караваны. А затем просто растворяются среди холмов!\n\nЯ хочу, чтобы ты как можно быстрее <добрался/добралась> до Заставы Чести и <сообщил/сообщила> им о том, что дороги все еще небезопасны. Поговори со снабженцем Маттингли, она находится у ворот.\n\nИ убей по пути тех головорезов, что встретятся!", progress = nil, completion = "Они устроили засаду и вокруг дорог в Когтистые горы тоже? Нам тут просто не передохнуть. Ну ладно, так откуда они появляются?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24863] = {title = "Прорвать осаду", objective = "Соберите 10 ящиков с припасами Каменного Когтя в руинах к западу от Заставы Чести.", description = "Разведчики Орды, что прячутся в руинах за нами, разграбили мой обоз с товарами. Лишь двое телохранителей смогли выбраться живыми. Я? Ну, а у меня раньше были волосы!\n\nТовары, которые я вез, теперь разбросаны среди руин. Собери их и отнеси Джанис Маттингли на Заставу Чести. Если уж им не суждено добраться до Скалистых гор, так пусть хотя бы не достанутся и Орде...", progress = "Что здесь происходит?", completion = "Что?.. Припасы? Они предназначались для Когтистых гор.\n\nНеважно, в текущей ситуации они будут гораздо полезнее нам здесь. Застава Чести отрезана от берега, Нфздлок. Командир Одингтон уже не знает, что и делать.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24864] = {title = "Неотразимый надувной пони", objective = "Приманите 12 маленьких наг с помощью неотразимого надувного пони.", description = "У меня есть план, и только ты достаточно <безумен/безумна>, чтобы хотя бы попытаться его осуществить!\n\nВот, возьми этого неотразимого надувного пони, отнеси его в лягушатник Вайш'элана и надуй. Затем садись на него верхом и плыви к молодняку наг. Наверняка ты сможешь приманить маленьких наг.\n\nПриведи их сюда, и тогда мы перейдем к следующему пункту нашего плана.", progress = "Этого недостаточно.", completion = "О, какие они милые! Эх, набить бы из них чучела да продать за газильон деревянных!", rewards = "Вы получите:\n\nПредмет #1Currency Token Test Token 4"}
MultiLanguageQuestData['ru'][24865] = {title = "Это еще годится в пищу?", objective = "Верните ящик с провизией Виллидену Маршаллу на заставу Маршалла.", description = "То, что вы нашли, больше всего похоже на ящик с провизией, оставленный после бегства из лагеря. На обратной стороне имеется штамп: \"СОБСТВЕННОСТЬ ЭКСПЕДИЦИИ МАРШАЛЛА\".\n\nВозможно, вам удастся найти того, кому это пригодится?", progress = "Что это, |3-6(Друид)?", completion = "Ох.. Надо же... Сколько же времени эта еда хранилась. Эй, Холания, ты только посмотри! Этот |3-6(Ворген) принес нам наши старые припасы!\n\nНет, не из тех, что мы оставили, покидая укрытие Маршалла... Из нашего старого лагеря!\n\n&lt;Виллиден вновь обращается к вам.&gt;\n\nНе могу сказать, что мечтаю заглянуть внутрь. Отдам их Волену, пожалуй... Он придумает, что с ними сделать.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24866] = {title = "Покинутый лагерь исследователей", objective = "Верните исследовательское оборудование Холании Маршалл на заставу Маршалла.", description = "То, что вы нашли, больше всего похоже на деталь исследовательского оборудования, брошенного во время бегства из лагеря. На устройстве нацарапана надпись: \"СОБСТВЕННОСТЬ ИКСПИДИТСИИ МАРШАЛЛА\".\n\nВозможно, вам удастся найти того, кому это пригодится?", progress = "Да, Нфздпал?", completion = "Черт возьми... Это же старый переносной динамометр Шиззла! Где ты достал его?\n\nНадо же, до сих пор работает, а сколько лет прошло. Нужно отдать его Шиззлу как можно быстрее.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][24868] = {title = "Сдавайся, не то хуже будет!", objective = "Разберитесь с главарем наг в руинах Вайш'элана.", description = "<имя>, тебе с Тузом нужно захватить маленьких наг и превратить их в средство убеждения. Главарь наг должен понять, что пора сдаваться.\n\nАс знает, куда идти – в южную часть развалин... следуй за ним.", progress = "И что происходит?", completion = "Безликий из глубин? Это еще что такое? По имени ВООБЩЕ на нагу не похоже!\n\nНу да ладно, ты же убил ЭТО, чем бы оно ни было. И все. У нас есть дела поважнее...", rewards = "Укротители детенышейХворостина детеныша нагиВы получите:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][24869] = {title = "Перевербовка", objective = "Убейте Леди Смертный Шепот, сохранив жизнь Дарнавану.", description = "Мы планировали заслать агента в Культ Проклятых, чтобы получить возможность следить за действиями Короля-лича напрямую, но мы… недооценили силу Артаса и его приближенной, Леди Смертный Шепот.\n\nВ итоге, один из наших людей, Дарнаван, был обращен на их сторону.\n\nЕсли ты собираешься расчистить путь в молельню, прошу тебя, поищи Дарнавана. Если тебе удастся вернуть его живым, мы постараемся устранить последствия промывки мозгов.", progress = nil, completion = "Спасибо тебе, Анкап!\n\nЯ в неоплатном долгу перед тобой за спасение друга, которого мы все считали навсегда потерянным в паутине Культа Проклятых. А Серебряный Авангард должен поблагодарить тебя за бесценные сведения, добытые Дарнаваном за то время, которое он провел в стенах Цитадели.\n\nПрошу тебя, прими это в знак нашей признательности, и пусть Свет озаряет твой путь, куда бы тебе не пришлось идти.", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
MultiLanguageQuestData['ru'][24870] = {title = "Оборона Черепного вала", objective = "Убейте гниющего ледяного великана.", description = "Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Альянса кусают нас за бока. Сколько можно воевать на два фронта!\n\nМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.\n\nСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.", progress = "Великан мертв?", completion = "Великан мертв? Слава Орде!\n\nСкоро путь будет расчищен. В знак благодарности прими эти военные трофеи – и я с нетерпением буду ждать того дня, когда мы сможем выпить за разрушение Ледяного Трона!", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
MultiLanguageQuestData['ru'][24871] = {title = "Оборона Черепного вала", objective = "Убейте гниющего ледяного великана.", description = "Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Орды кусают нас за бока. Сколько можно воевать на два фронта!\n\nМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.\n\nСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.", progress = nil, completion = "Великан мертв? Слава Свету!\n\nСкоро путь будет расчищен. В знак благодарности прими эти военные трофеи – и я с нетерпением буду ждать того дня, когда мы сможем выпить за разрушение Ледяного Трона!", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
MultiLanguageQuestData['ru'][24872] = {title = "Отдых для измученной души", objective = "Воспользуйтесь кристаллами жизни, чтобы сохранить душу Синдрагосы.", description = "Я прошу тебя и твоих спутников взять эти Кристаллы жизни. В них заключена великая сила Святилища драконов из Драконьего Погоста. Знай же, что только с их помощью мне так долго удавалось оградить это место от влияния темной магии. \n\nБрось вызов Синдрагосе, и когда силы ее истощатся в бою, четыре твоих спутника смогут активировать кристаллы, чтобы вытянуть покоящуюся внутри нее сущность. Если затем ты одержишь победу, ты сможешь вернуть ее душу в Святилище драконов.", progress = "Что у тебя в руках, смертный?", completion = "&lt;Калесгос вздыхает&gt;\n\nСколько смертей, сколько разрушений... Тяжелые времена наступили для моих братьев и сестер. Но благодаря вам, благородные искатели приключений, одна благородная, хоть и затронутая порчей душа обретет покой.\n\nСпи спокойно, Синдрагоса. Ты вернулась домой...", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
MultiLanguageQuestData['ru'][24873] = {title = "Болезненная задача", objective = "Если вы заразитесь оранжевой и зеленой порчей, вернитесь к алхимику Адрианне.", description = "Профессор Мерзоцид прячется в своей поганой лаборатории, ставит опыты и выводит все более и более смертоносные штаммы порчи, которыми он планирует заразить всех нас. Если только мы сможем получить чистые образцы этих токсинов, наши исследователи немедленно приступят к изготовлению противоядия, которое спасет множество жизней.\n\nНо есть одна проблема – для того, чтобы получить требуемый образец, надо заразить живое существо двумя активными штаммами. Но если вдруг тебе... не посчастливится... стать носителем этой заразы, немедленно возвращайся сюда, чтобы мы могли поставить на тебе опыты.", progress = nil, completion = "Наконец-то у нас есть образец для изучения! Сегодня ты спас бесчисленное множество жизней, Ханилок.\n\nПрошу, прими это в благодарность за твое великое деяние.", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
MultiLanguageQuestData['ru'][24874] = {title = "Каждая капля крови...", objective = "Спасите разведчика Минчара прежде, чем его казнят.", description = "Эти проклятые кровопийцы Плети, что именуют себя Сан'лейн... у меня от них мурашки по коже. За ними следил один из наших лучших агентов, но сегодня утром с ним случилась беда – он попал в плен. Теперь его допрашивает сама Королева, и его крики эхом разносятся по Багровым залам. Пожалуйста, спаси его, пока еще не поздно!", progress = nil, completion = "Фух! Я уж думал, что мне конец. Представляешь, я услышал о каком-то ритуале воскрешения, проходящем в этих залах, но когда я попытался взглянуть поближе, один из этих проклятых вампиров меня учуял. Они привязали меня здесь и принялись вытягивать мою жизненную энергию в надежде, что я выдам планы нападения. Можно подумать, Тирион доверяет мне такие сведения!\n\nПрими эти военные трофеи в благодарность за спасение моей жизни.", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
MultiLanguageQuestData['ru'][24875] = {title = "Перевербовка", objective = "Убейте Леди Смертный Шепот, сохранив жизнь Дарнавану.", description = "Мы планировали заслать агента в Культ Проклятых, чтобы получить возможность следить за действиями Короля-лича напрямую, но мы… недооценили силу Артаса и его приближенной, Леди Смертный Шепот.\n\nВ итоге, один из наших людей, Дарнаван, был обращен на их сторону.\n\nЕсли ты собираешься расчистить путь в молельню, прошу тебя, поищи Дарнавана. Если тебе удастся вернуть его живым, мы постараемся устранить последствия промывки мозгов.", progress = nil, completion = "Спасибо тебе, Артеус!\n\nЯ в неоплатном долгу перед тобой за спасение друга, которого мы все считали навсегда потерянным в паутине Культа Проклятых. А Серебряный Авангард должен поблагодарить тебя за бесценные сведения, добытые Дарнаваном за то время, которое он провел в стенах Цитадели.\n\nПрошу тебя, прими это в знак нашей признательности, и пусть Свет озаряет твой путь, куда бы тебе не пришлось идти.", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
MultiLanguageQuestData['ru'][24876] = {title = "Оборона Черепного вала", objective = "Убейте гниющего ледяного великана.", description = "Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Орды кусают нас за бока. Сколько можно воевать на два фронта!\n\nМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.\n\nСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.", progress = nil, completion = "Великан мертв? Слава Свету!\n\nСкоро путь будет расчищен. В знак благодарности прими эти военные трофеи – и я с нетерпением буду ждать того дня, когда мы сможем выпить за разрушение Ледяного Трона!", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
MultiLanguageQuestData['ru'][24877] = {title = "Оборона Черепного вала", objective = "Убейте гниющего ледяного великана.", description = "Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Альянса кусают нас за бока. Сколько можно воевать на два фронта!\n\nМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.\n\nСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.", progress = "Великан мертв?", completion = "Великан мертв? Слава Орде!\n\nСкоро путь будет расчищен. В знак благодарности прими эти военные трофеи – и я с нетерпением буду ждать того дня, когда мы сможем выпить за разрушение Ледяного Трона!", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
MultiLanguageQuestData['ru'][24878] = {title = "Болезненная задача", objective = "Если вы заразитесь оранжевой и зеленой порчей, вернитесь к алхимику Адрианне.", description = "Профессор Мерзоцид прячется в своей поганой лаборатории, ставит опыты и выводит все более и более смертоносные штаммы порчи, которыми он планирует заразить всех нас. Если только мы сможем получить чистые образцы этих токсинов, наши исследователи немедленно приступят к изготовлению противоядия, которое спасет множество жизней.\n\nНо есть одна проблема – для того, чтобы получить требуемый образец, надо заразить живое существо двумя активными штаммами. Но если вдруг тебе... не посчастливится... стать носителем этой заразы, немедленно возвращайся сюда, чтобы мы могли поставить на тебе опыты.", progress = "Профессор Мерзоцид – самая большая угроза для нас со стороны Плети.", completion = "Наконец-то у нас есть образец для изучения! Сегодня ты спас бесчисленное множество жизней, Краитэн.\n\nПрошу, прими это в благодарность за твое великое деяние.", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
MultiLanguageQuestData['ru'][24879] = {title = "Каждая капля крови...", objective = "Спасите разведчика Минчара прежде, чем его казнят.", description = "Эти проклятые кровопийцы Плети, что именуют себя Сан'лейн... у меня от них мурашки по коже. За ними следил один из наших лучших агентов, но сегодня утром с ним случилась беда – он попал в плен. Теперь его допрашивает сама Королева, и его крики эхом разносятся по Багровым залам. Пожалуйста, спаси его, пока еще не поздно!", progress = nil, completion = "Фух! Я уж думал, что мне конец. Представляешь, я услышал о каком-то ритуале воскрешения, проходящем в этих залах, но когда я попытался взглянуть поближе, один из этих проклятых вампиров меня учуял. Они привязали меня здесь и принялись вытягивать мою жизненную энергию в надежде, что я выдам планы нападения. Можно подумать, Тирион доверяет мне такие сведения!\n\nПрими эти военные трофеи в благодарность за спасение моей жизни.", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
MultiLanguageQuestData['ru'][24880] = {title = "Отдых для измученной души", objective = "Воспользуйтесь кристаллами жизни, чтобы сохранить душу Синдрагосы.", description = "Я прошу тебя и твоих спутников взять эти Кристаллы жизни. В них заключена великая сила Святилища драконов из Драконьего Погоста. Знай же, что только с их помощью мне так долго удавалось оградить это место от влияния темной магии. \n\nБрось вызов Синдрагосе, и когда силы ее истощатся в бою, четыре твоих спутника смогут активировать кристаллы, чтобы вытянуть покоящуюся внутри нее сущность. Если затем ты одержишь победу, ты сможешь вернуть ее душу в Святилище драконов.", progress = "Что у тебя в руках, смертный?", completion = "&lt;Калесгос вздыхает&gt;\n\nСколько смертей, сколько разрушений... Тяжелые времена наступили для моих братьев и сестер. Но благодаря вам, благородные искатели приключений, одна благородная, хоть и затронутая порчей душа обретет покой.\n\nСпи спокойно, Синдрагоса. Ты вернулась домой...", rewards = "Вы получите:\n\nМешок ледяных сокровищ"}
