MultiLanguageQuestData['ru'][28768] = {title = "Зимние Ключи!", objective = "Явитесь к Донове Снегоноре у Источников Ледяного огня в Зимних Ключах.", description = "Донова Снегонора – женщина-дворф – друг Древобрюхам.\n\nМы торгуем огненной водой.\n\nТы найдешь ее у источников Ледяного огня – это надо идти на восток через наши пещеры.\n\nОна хочет одолеть фурболгов из племени Зимней Спячки и нуждается в помощи. Может быть, ты сумеешь ей помочь.", progress = nil, completion = "Хвала Свету, ты здесь. Я разузнала тайну свирепых фурболгов из племени Зимней Спячки.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28769] = {title = "Волки и овцы", objective = "Расправьтесь с 8 шпионами клана Черной горы.", description = "Орки-захватчики – не дураки. Они следят за наши действиями, чтобы улучить удобный момент для нападения.\n\nВ лесу на северо-западе расположились шпионы из клана Черной горы. Они смотрят на нас через подзорные трубы, выжидая урочный час. Я хочу, чтобы ты <напал/напала> на них!\n\nРасправься со шпионами клана Черной горы! Нужно продемонстрировать им, что мы знаем о том, что они следят за нами, а также показать нашу боеготовность!", progress = nil, completion = "Молодчина, Кусачаявода. Ты оказалась ценным приобретением для нашего гарнизона. Настало время тренировки!", rewards = "Вы получите:\n\nОдеяние аббатства Североземья"}
MultiLanguageQuestData['ru'][28770] = {title = "Волки и овцы", objective = "Расправьтесь с 8 шпионами клана Черной горы.", description = "Орки-захватчики – не дураки. Они следят за наши действиями, чтобы улучить удобный момент для нападения.\n\nВ лесу на северо-западе расположились шпионы из клана Черной горы. Они смотрят на нас через подзорные трубы, выжидая урочный час. Я хочу, чтобы ты <напал/напала> на них!\n\nРасправься со шпионами клана Черной горы! Нужно продемонстрировать им, что мы знаем о том, что они следят за нами, а также показать нашу боеготовность!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПояс пехотинца Штормграда"}
