MultiLanguageQuestData['ru'][28812] = {title = "Не убойся зла", objective = "Исцелите 4 раненых пехотинцев Штормграда.", description = "Ты уже <открыл/открыла> свое сердце Свету, <брат мой/сестра моя>? Именно он оберегает нас! Именно Свет помогает мне исцелять всех тех израненных солдат, что ты видишь! Сияние Света поможет тебе пройти на поле к северу отсюда и спасти наших раненых собратьев!\n\nВозьми с собой в поле этот молитвенник и озари их тела живительным Светом.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nСледующее заклинание будет наложено на вас:\n\nUpdate Player Phase/Auras\n\nВы также получите:\n\nБашмаки из аббатства Североземья"}
MultiLanguageQuestData['ru'][28813] = {title = "Не убойся зла", objective = "Исцелите 4 раненых пехотинцев Штормграда.", description = "Ты уже <открыл/открыла> свое сердце Свету, <брат мой/сестра моя>? Именно он оберегает нас! Именно Свет помогает мне исцелять всех тех израненных солдат, что ты видишь! Сияние Света поможет тебе пройти на поле к северу отсюда и спасти наших раненых собратьев!\n\nВозьми с собой в поле этот молитвенник и озари их тела живительным Светом.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nСледующее заклинание будет наложено на вас:\n\nUpdate Player Phase/Auras\n\nВы также получите:\n\nЖилет охотника на волков"}
MultiLanguageQuestData['ru'][28814] = {title = "Пастыри и паства", objective = "Убейте верховную жрицу Азил и 101 верного последователя.", description = "В бумагах описывается визит верховной жрицы Азил в глубины Каменных Недр.\n\nИсходя из изложенного, Азил – высокопоставленный член Сумеречного Совета, а ее кортеж более чем из ста верных последователей готовится провести темный ритуал необыкновенно разрушительной силы.\n\nПохоже, вам стоит воспрепятствовать осуществлению их планов.", progress = "С возвращением, Нфздвар. Есть новости?", completion = "Верховная жрица, говоришь? Да к тому же член Сумеречного Совета?\n\nЧто ж, прекрасная работа! Надеюсь, ты будешь доволен наградой.", rewards = "Наплечье нечестивых ритуаловПояс ста одногоВам дадут возможность выбрать одну из следующих наград:\n\nПечатка верховной жрицы\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][28815] = {title = "Документы Сумеречного Молота", objective = "Раздобудьте документы Сумеречного Молота.", description = "Мы выследили агента Сумеречного Молота. Зовут его Миллхаус Манашторм.\n\nЕсть основания полагать, что у него при себе важные бумаги.\n\nОднако мы не можем оставить внутренний периметр Храма Земли без защиты.\n\nРазыщи Манашторма и отбери у него документы.", progress = "Похоже, это те самые бумаги.", completion = "&lt;Вы пролистываете документы в поисках важных сведений.&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28816] = {title = "В пучину", objective = "Явитесь с рапортом к командиру Тораку в бухте Острорука в Дуротаре.", description = "Служители Земли установили, что водянистый регион Вайш'ир является источником разрушительной энергии.\n\nСложно сказать, что за опасности таит в себе это место, но любые сведения о нем, что ты сможешь добыть, окажутся чрезвычайно полезными.\n\nВ это самое время Орда посылает в данный регион военную армаду. Для того чтобы попасть на корабль, обратись к командиру Тораку в бухте Острорука.\n\nДа хранят тебя духи, <имя>.", progress = nil, completion = "Лок'тар, брат! Ты прибыл как раз вовремя.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28817] = {title = "Тыл зачищен", objective = "Явитесь к маршалу Макбрайду, стоящему перед Аббатством Североземья в Элвиннском лесу.", description = "Прекрасно сработано, <имя>! Отныне тыл можно считать зачищенным. Мы сами займемся дезертирами. Я хочу, чтобы ты <пошел/пошла> к маршалу Макбрайду, стоящему перед Аббатством Североземья, что к югу отсюда, и <доложил/доложила> ему, что ситуация с гоблинами находится под контролем.\n\nПрощай, <класс>.", progress = nil, completion = "С твоей помощью нам удалось обезопасить северную и западную часть Североземья. На востоке нам все еще противостоит значительная группировка орков Черной горы, уже начавшая сжигать лес.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28818] = {title = "Тыл зачищен", objective = "Явитесь к маршалу Макбрайду, стоящему перед Аббатством Североземья в Элвиннском лесу.", description = "Прекрасно сработано, <имя>! Отныне тыл можно считать зачищенным. Мы сами займемся дезертирами. Я хочу, чтобы ты <пошел/пошла> к маршалу Макбрайду, стоящему перед Аббатством Североземья, что к югу отсюда, и <доложил/доложила> ему, что ситуация с гоблинами находится под контролем.\n\nПрощай, <класс>.", progress = nil, completion = "С твоей помощью нам удалось обезопасить северную и западную часть Североземья. На востоке нам все еще противостоит значительная группировка орков Черной горы, уже начавшая сжигать лес.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28819] = {title = "Тыл зачищен", objective = "Явитесь к маршалу Макбрайду, стоящему перед Аббатством Североземья в Элвиннском лесу.", description = "Прекрасно сработано, <имя>! Отныне тыл можно считать зачищенным. Мы сами займемся дезертирами. Я хочу, чтобы ты <пошел/пошла> к маршалу Макбрайду, стоящему перед Аббатством Североземья, что к югу отсюда, и <доложил/доложила> ему, что ситуация с гоблинами находится под контролем.\n\nПрощай, <класс>.", progress = nil, completion = "С твоей помощью нам удалось обезопасить северную и западную часть Североземья. На востоке нам все еще противостоит значительная группировка орков Черной горы, уже начавшая сжигать лес.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28820] = {title = "Тыл зачищен", objective = "Явитесь к маршалу Макбрайду, стоящему перед Аббатством Североземья в Элвиннском лесу.", description = "Прекрасно сработано, <имя>! Отныне тыл можно считать зачищенным. Мы сами займемся дезертирами. Я хочу, чтобы ты <пошел/пошла> к маршалу Макбрайду, стоящему перед Аббатством Североземья, что к югу отсюда, и <доложил/доложила> ему, что ситуация с гоблинами находится под контролем.\n\nПрощай, <класс>.", progress = nil, completion = "С твоей помощью нам удалось обезопасить северную и западную часть Североземья. На востоке нам все еще противостоит значительная группировка орков Черной горы, уже начавшая сжигать лес.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28821] = {title = "Тыл зачищен", objective = "Явитесь к маршалу Макбрайду, стоящему перед Аббатством Североземья в Элвиннском лесу.", description = "Прекрасно сработано, <имя>! Отныне тыл можно считать зачищенным. Мы сами займемся дезертирами. Я хочу, чтобы ты <пошел/пошла> к маршалу Макбрайду, стоящему перед Аббатством Североземья, что к югу отсюда, и <доложил/доложила> ему, что ситуация с гоблинами находится под контролем.\n\nПрощай, <класс>.", progress = nil, completion = "С твоей помощью нам удалось обезопасить северную и западную часть Североземья. На востоке нам все еще противостоит значительная группировка орков Черной горы, уже начавшая сжигать лес.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28822] = {title = "Тыл зачищен", objective = "Явитесь к маршалу Макбрайду, стоящему перед Аббатством Североземья в Элвиннском лесу.", description = "Прекрасно сработано, <имя>! Отныне тыл можно считать зачищенным. Мы сами займемся дезертирами. Я хочу, чтобы ты <пошел/пошла> к маршалу Макбрайду, стоящему перед Аббатством Североземья, что к югу отсюда, и <доложил/доложила> ему, что ситуация с гоблинами находится под контролем.\n\nПрощай, <класс>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28823] = {title = "Тыл зачищен", objective = "Явитесь к маршалу Макбрайду, стоящему перед Аббатством Североземья в Элвиннском лесу.", description = "Прекрасно сработано, <имя>! Отныне тыл можно считать зачищенным. Мы сами займемся дезертирами. Я хочу, чтобы ты <пошел/пошла> к маршалу Макбрайду, стоящему перед Аббатством Североземья, что к югу отсюда, и <доложил/доложила> ему, что ситуация с гоблинами находится под контролем.\n\nПрощай, <класс>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28824] = {title = "Блудный сын", objective = "Убейте Озрука.", description = "Одно из моих чад покинуло меня, <имя>.\n\nСын мой остался у Сумеречного Молота, в нижних чертогах Храма Земли – Каменных Недрах.\n\nЯ отправила его братьев освободить несчастного от пут темной магии, с помощью которой его там удерживали... но оказалось, что он не был скован ни магией, ни чем-либо еще.\n\nСпускайся в Каменные Недра и убей Озрука. Нужно вернуть его земле.", progress = nil, completion = "&lt;Глаза Теразан блестят сильнее, чем прежде.&gt;\n\nОзрук предан земле.\n\nВот твоя награда, Фростии, а теперь оставь меня. Мне нужно побыть одной.", rewards = "Поножи заблудшего сынаПояс Каменных НедрПлащ кристального светаВы получите:\n\n"}
MultiLanguageQuestData['ru'][28825] = {title = "Персональное приглашение", objective = "Разыщите Нараата Говорящего с Землей в Штормграде.", description = "<В вас нарастает незнакомое чувство, наполняя ваш разум невиданными образами и странными мыслями.>\n\nУслышь меня, <имя>.\n\nНаш мир на грани жуткой катастрофы.\n\nВзываю к тебе: окажи нам помощь в этот трудный час.\n\nЯ – Нараат.\n\nНайди меня, не медли, и я открою тебе твое предназначение.\n\nЖду тебя у Восточного святилища Земли в Штормграде.", progress = nil, completion = "Да послужит твое чувство чести и долга во славу Азерота, |3-6(Охотник).", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28826] = {title = "Око Бури", objective = "Нараат Говорящий с Землей просит вас взглянуть в Воды предвидения.", description = "Приветствую тебя, герой Азерота.\n\n\n\nСреди нас, Служителей Земли, ты <известен/известна> нам под именем <имя>.\n\nПодвигам и свершениям твоим несть числа. Азерот уже в долгу перед тобой, но нынче ему снова требуется помощь великих героев.\n\nА я лишь глашатай его воли. Могучий дух желает говорить с тобой.\n\nЗагляни в Воды предвидения и узри беды, грозящие нашему миру.", progress = "Что тебе, |3-6(Шаман)?", completion = "Теперь, когда тебе открылась истина, где ты предпочтешь служить?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28827] = {title = "В пучину", objective = "Поговорите с вербовщиком Бернсом в порту Штормграда.", description = "Служители Земли установили, что водянистый регион Вайш'ир является источником разрушительной энергии.\n\nСложно сказать, что за опасности таит в себе это место, но любые сведения о нем, что ты сможешь добыть, окажутся чрезвычайно полезными.\n\nВ это самое время Альянс посылает в данный регион военную армаду. Для того чтобы попасть на корабль, отправляйся в северо-западную часть Штормграда и обратись к вербовщику Бернсу в порту Штормграда.\n\nДа хранят тебя духи, <имя>.", progress = nil, completion = "Все наши боевые корабли сейчас в море, сражаются с Ордой. Тебе придется отправиться на корабле наемников.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28828] = {title = "Яйца – вкусная и полезная пища", objective = "Соберите 40 яиц хладнокрылых химер.", description = "У меня не очень тонкий вкус, но даже я ненавижу местных химер. А вот их яйца – это совсем другое дело.\n\nЯйца химер – самая нежная и питательная пища по эту сторону Оргриммара. Они куда вкуснее, чем скучные яйца сов.\n\nЯ куплю все яйца, которые тебе удастся собрать. Иди на северо-восток и ищи их гнезда в снегу.", progress = "Мм-м...", completion = "Замечательные яйца.\n\nОни будут отлично сочетаться с беконом из медведя. Эй, Фрэнсис, у нас медвежатина осталась?", rewards = "Кушак гурманаНаручи снежного гнездаЧешуйчатые боевые наручи Промозглого ВетраПлащ СкороцапаВам дадут возможность выбрать одну из следующих наград:\n\nПодвеска сердца химеры\n\nВы также получите:\n\nОмлет из яиц хладнокрылой химеры"}
MultiLanguageQuestData['ru'][28829] = {title = "Рога остры и клювы наши быстры", objective = "Убейте 12 совухов в Совиной чаще.", description = "Спрашиваешь, что со мной стряслось? Так слушай, <класс>, и слушай внимательно, ибо повесть моя трагична...\n\nМеня отправили в Совиную чащу на поиски реликвий. Стоило мне дойти сюда, как на меня налетел вихрь из крыльев и когтей.\n\nОни так вопили и клевались, <класс>!\n\nИ вот теперь я, поверженный орк, лежу здесь и мечтаю лишь о мести! Прошу тебя, <класс>, если ты дорожишь своей честью, отправляйся в Совиную чащу и помоги мне вернуть мою!", progress = nil, completion = "Моя честь восстановлена.\n\nЧастично.\n\nМой рассказ еще не окончен, |3-6(Друид), ибо я растерял частички своей чести по всему лесу.\n\nДа, этот поход дался мне нелегко.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28830] = {title = "Яблоко от яблони", objective = "Убейте 8 отпрысков великанов из племени Ледяного Молота.", description = "Мои таинственные покровители дали мне не единственное задание. За выполнением второго поручения я отправился дальше на юг, в теснину Ледяного Шепота. Я был озадачен, выяснив, что мост через теснину развалился надвое и по земле на другую сторону не перебраться.\n\nК тому же молодые отпрыски великанов из племени Ледяного Молота были отрезаны от своих взрослых родителей-силачей. Я подумал, что мне удастся одолеть малюток в бою.\n\nИ был неправ. Пришлось мне постыдно улепетывать.\n\nПроучи этих увальней, <имя>. Срази их в честном поединке.", progress = nil, completion = "Радуйся, что взрослые гиганты застряли на той стороне теснины. Они куда сильнее, чем эти малорослики, с которыми ты сражался.\n\nТвоя отвага, |3-6(Друид), буквально придает мне новых сил! Возможно, надежда еще не потеряна...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28831] = {title = "Будь проклят Студиликус", objective = "Убейте Студиликуса.", description = "Великаны племени Ледяного Молота не были бы помехой, если бы не этот проклятый Студиликус! Когда случилось землетрясение и мост рухнул, он со своими водными элементалями вытек из-под земли и занял низину в теснине Ледяного Шепота, выдворив оттуда великанов.\n\nБудь ты проклят, Студиликус!\n\nА ты, <класс>, окажешь мне большую услугу, если загонишь его обратно под землю. Ты найдешь его к югу отсюда, на дне теснины.", progress = nil, completion = "Если я оправлюсь от ран, |3-6(Друид), то навсегда запомню твое имя.\n\nЯ буду слышать его в каждом дуновении ветра в вершинах деревьев.\n\nСпасибо тебе.", rewards = "Клобук поющих ветровУбежище СтудиликусаПояс Совиной чащиКираса орка-поэтаВам дадут возможность выбрать одну из следующих наград:\n\nТесаки Кромсателя\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][28832] = {title = "Сумеречный берег", objective = "Поговорите с лейтенантом Фоксом на Высоком берегу, что в Сумеречном нагорье.", description = "Давай, садись в гидросамолет позади меня и полетим к нагорью.\n\nТам нам надо поговорить с каким-то лейтенантом Фоксом. Я обещал королю, что мы быстро обернемся, так что решил не брать никаких лишних вещей. Например, ремней безопасности. Парашютов. Карт. Стабилизаторов. Шасси.\n\nВсе равно все это не нужно.", progress = nil, completion = "Меньше всего я ожидал увидеть падающими с неба вас двоих. Высокий берег подвергается нападению!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28833] = {title = "Спасение Эрунака", objective = "Освободите Эрунака Говорящего с Камнем.", description = "Отлично! Ты <пришел/пришла> не одна.\n\nЕсли мы хотим спасти Эрунака, надо поторопиться.\n\nПробейся сквозь залы Нептулона. Найди шамана и освободи его от этих червей... если он еще жив.\n\nЯ прикрою тебя с тыла. Мимо меня ни одна тварь не проскочит!", progress = nil, completion = "Что такое? Ты... ты меня спасаешь?!\n\n&lt;Эрунак улыбается.&gt;\n\nЭто так неожиданно... к этому надо привыкнуть.", rewards = "Пояс тясячи смертейПоножи удачного удараВам дадут возможность выбрать одну из следующих наград:\n\nОберег морской ведьмы\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][28834] = {title = "Спасение Эрунака", objective = "Освободите Эрунака Говорящего с Камнем.", description = "Отлично! Ты <пришел/пришла> не одна.\n\nЕсли мы хотим спасти Эрунака, надо поторопиться.\n\nПробейся сквозь залы Нептулона. Найди шамана и освободи его от этих червей... если он еще жив.\n\nЯ прикрою тебя с тыла. Мимо меня ни одна тварь не проскочит!", progress = nil, completion = "Что такое? Ты... ты меня спасаешь?!\n\n&lt;Эрунак улыбается.&gt;\n\nЭто так неожиданно... к этому надо привыкнуть.", rewards = "Пояс тясячи смертейПоножи удачного удараВам дадут возможность выбрать одну из следующих наград:\n\nОберег морской ведьмы\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][28836] = {title = "Грехи морской ведьмы", objective = "Убейте Леди Наз'жар на Троне Приливов.", description = "Эта злобная тварь заслужила тысячу смертей!\n\nНо уничтожить ее совсем не просто. Она тут хорошо окопалась со своими гнусными приспешниками. Правда, сейчас она истощена после сражения с Нептулоном.\n\nТак что самое время нанести удар! Другого шанса может и не быть.\n\nУбей ее, <имя>!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Дымчатые одеянияПояс Говорящего с КамнемЖилет леса Келп’тарВы получите:\n\n"}
MultiLanguageQuestData['ru'][28837] = {title = "Мутировавшие звери", objective = "Раздобудьте 5 образцов мутировавших от магии мозгов животных.", description = "Нас, синих драконов, выдворили из собственного дома, Мазторила. Самозванец Умбранс одержал верх в минуту нашей уязвимости и оккупировал пещеру.\n\nМазторил – средоточие очень мощной магии, а он не умеет ею пользоваться. Страдает даже местная фауна.\n\nЖивотные в окрестностях преобразились. Прошу тебя об услуге, <раса>. Принеси мне мозг некоторых этих зверей: я должна понять, в силах ли я обратить хаотическое колдовство Умбранса.", progress = "Мазторил принадлежит стае синих драконов. То, что случилось, несправедливо.", completion = "Посмотрим, что я смогу выяснить...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28838] = {title = "Защита совухов", objective = "Отыщите ловушку снов совухов в Дун Мандарре.", description = "Стыдно признаться, но что бы там Умбранс ни сотворил, он не дает мне обратить его колдовство.\n\nОн оказался хитрее, чем я предполагала.\n\nВпрочем, у меня есть запасной план. Я видела, что совухи спокойно входят в Мазторил и возвращаются даже после его захвата Умбрансом. Их древняя магия друидов, должно быть, сильнее колдовства Умбранса. По счастью, я неплохо разбираюсь в их традициях.\n\nОтправляйся на юг в Дун Мандарр. Там ты найдешь сундук с ловушкой для снов.\n\nЭто то, что нам нужно для начала.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28839] = {title = "Доисторическая магия", objective = "Раздобудьте эссенцию тотема когтей, эссенцию тотема жизни и эссенцию лунного тотема.", description = "На востоке находятся священные пещеры совухов. В некоторых из них ты найдешь тотемы. Подойди к тотемам и собери их эссенции, сколько сможешь. Ловушка для снов впитает эту эссенцию, и ее можно будет поставить в Мазториле.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][28840] = {title = "Зимняя вода", objective = "Раздобудьте 7 колб зимней воды из ледяных аватар в Теснине Ледяного Шепота.", description = "Я сильно постараюсь, чтобы наша затея не провалилась, <имя>. Неудача привлечет внимание к нашим усилиям и даст Умбрансу возможность укрепить оборону. Нет, у нас будет всего одна попытка.\n\nВ теснине Ледяного Шепота, что на юге, обитают могучие ледяные элементали. Вода в этих элементалях усилит твою ловушку для снов и закрепит наш успех.\n\nРаздобудь эту воду, <имя>, и возвращайся сюда.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Теплые бриджи ХалеНабедренники аватары льдаПлащ зимней водыВы получите:\n\n"}
MultiLanguageQuestData['ru'][28841] = {title = "Чародейская буря", objective = "С помощью заряженного ловца снов закройте 5 чародейских тессерактов в Мазториле.", description = "В Мазториле скрыта великая магия, и если она выйдет из-под контроля, то причинит немыслимые беды. Бездумно творя заклинания, Умбранс создал несколько тессерактов – иными словами, порталов, ведущих в иные миры. И прежде чем я вернусь в Мазторил, эти порталы должны быть закрыты.\n\nЛовушка снов заблокирует порталы, дав тебе возможность проникнуть в логово Умбранса. Сначала уничтожь то, что выйдет из тессерактов, затем с помощью ловушки быстро закрой их – пока в этот мир не проникло еще что-нибудь.", progress = nil, completion = "Мазторил не скоро возродится... но он возродится.\n\nСиние драконы будут жить!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][28842] = {title = "Избавление Умбранса", objective = "Убейте Умбранса Ищущего Духов.", description = "В глубине Мазторила бродит Умбранс. Его время пришло.\n\nК сожалению, я не смогу пойти с тобой. Мне очень хочется проучить эту змею, но магия Мазторила сейчас так сильна, что разорвет меня на части, как только я ступлю на эту землю. Нет, покончить с ним придется тебе.\n\nКогда все сделаешь, воспользуйся этим амулетом. Он вернет тебя к выходу.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Наручи МазторилаШлем ловца сновРукавицы НамаПосох УмбрансаВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][28843] = {title = "Грехи морской ведьмы", objective = "По приказу легионера Назгрима убейте Леди Наз'жар.", description = "Наз'жар! Это она в ответе за все, что здесь произошло.\n\nОна где-то здесь. И сейчас наверняка обессилена после сражения с Нептулоном.\n\nТак что самое время нанести удар! Другого шанса может и не быть.\n\nЯ останусь здесь и прослежу, чтобы никто не пришел к ней на помощь с этой стороны.\n\nА ты разыщи ее, <имя>. Разыщи и убей!", progress = nil, completion = "Адский Крик обязательно узнает о твоих подвигах, Милитех.\n\nБез тебя нам пришлось бы туговато.\n\nЛок'тар огар, друг мой!", rewards = "Дымчатые одеянияПояс Говорящего с КамнемЖилет леса Келп’тарВы получите:\n\n"}
MultiLanguageQuestData['ru'][28845] = {title = "Вершина Смерча", objective = "Разыщите Итеша в Вершине Смерча.", description = "Один из наших вождей ополчения захвачен воздушными элементалями.\n\nСейчас они наверняка выпытывают у него сведения.\n\nОтправляйся в Вершину Смерча, где обитают эти мерзкие твари, и разыщи Итеша.\n\nВход в Вершину Смерча нависает над юго-восточным побережьем Ульдума.", progress = nil, completion = "Ты в самом деле пришел сюда за мной?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28847] = {title = "По пятам Умбранса", objective = "Обратитесь к Хале в Берилловом Уделе, что в Зимних Ключах.", description = "Мы вычислили, где в Зимних Ключах скрывается Умбранс. Там, где я и предполагал.\n\nОн в Мазториле, пещере на юго-западе, которая некогда принадлежала роду синих драконов. Моя мать Хале встретит тебя там. Она расположилась возле входа в пещеру в небольшом лагере с другими беженцами.\n\nСледуй на огонь их костра.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28848] = {title = "По следу Ищущего Духов", objective = "Поговорите с Нимном в Зимних Ключах, в Круговзоре.", description = "Мне рассказывали про Умбранса, но видеть его не доводилось. По слухам, он собирает магические артефакты, однако с какой целью – неизвестно. \n\nПохоже, стоит сообщить об этом верному союзнику. В Круговзоре, большом городе гоблинов на северо-востоке, живет высший эльф по имени Нимн. Расскажи ему все, что мы узнали сегодня.", progress = nil, completion = "Умбранс... Понятно. Я предупрежу об этом свой народ.\n\nЕсли ты нам понадобишься, мы тебе сообщим.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28849] = {title = "Сумеречные небеса", objective = "Доложите Фризу Штопору на южной конечной станции ракетной дороги в Азшаре.", description = "Из Оргриммара только что доложили: вождь приказывает нам выступать. Если бы не твоя помощь, мы сейчас были бы к этому совсем не готовы!\n\nПлан таков: сперва отправляется военно-воздушный флот, а сразу следом за ним – военно-морской. Адский Крик летит с воздушными войсками и передал тебе персональное приглашение присоединиться.\n\nВремя не ждет! Отправляйся на южную конечную станцию ракетной дороги в Азшаре и доложи Фризу Штопору. А я подведу дирижабль, и мы тебя подхватим.", progress = nil, completion = "Очередной |3-6(Друид) держит путь к нагорью, стало быть? На вот, подпиши отказ от претензий...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28850] = {title = "На крыше тюрьмы", objective = "Поговорите с лордом Дарием Краули на верхней террасе Каменной тюрьмы Гилнеаса.", description = "Не знаю, почему король тратит свое драгоценное время ради спасения его шкуры, но если ты хочешь рискнуть жизнью – твое дело, не стану мешать.\n\nКраули и его люди сидят наверху, строят заговоры против его величества.", progress = nil, completion = "Седогрив прав. Этим животным наплевать на наши политические дрязги.\n\nГилнеас должен объединиться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28852] = {title = "Ослабить противника", objective = "Освободите красного дракона, плененного в Грим Батоле, и воспользуйтесь им, чтобы расправиться с 30 троггами и 15 адептами культа Сумеречного Молота.", description = "Наконец-то прибыло подкрепление! Кто бы мог подумать, что сектанты Сумеречного Молота способны дать такой отпор! Кроме того, враг оказался гораздо многочисленнее, чем мы полагали!\n\nНескольких наших драконов пленили внутри главного зала. Прошу тебя, разбей их оковы и освободи их!\n\nОсвободившись, драконы помогут нам выжечь врага из этих залов. Просто взберись на спину красного дракона и укажи ему цель для атаки. Думаю, тебе захочется основательно потрепать силы противника перед тем, как спуститься глубже.", progress = "Ты обнаружил раненых драконов? Были ли они в силах тебе помочь?", completion = "Чудесные новости, Заракир! Рада, что наши драконы смогли тебе помочь. Благодарю тебя за их спасение из пут сектантов Сумеречного Молота.", rewards = "Вы получите:\n\nСокровища Грим Батола"}
MultiLanguageQuestData['ru'][28853] = {title = "Устранение гонца", objective = "Убейте Драгха Горячего Мрака и заберите у него послание Чо'Галлу.", description = "Спасибо за то, что <вызвался/вызвалась> помочь нам справиться с ужасами, терзающими это мрачное место, <класс>.\n\nВ недрах Грим Батола сокрыт командный центр всеми военными операциями Чо'Галла.\n\nОтыщи там Драгха Горячего Мрака. Это гонец Чо'галла, связующее звено между Грим Батолом и Сумеречным бастионом. Нужно выведать, что за тайны он скрывает.", progress = "Что тебе удалось узнать, |3-6(Охотник)?", completion = "&lt;Тоорану просматривает принесенные вами документы&gt;.\n\nТут все, Крайтеен. Сведения о том, как культ разрушает нагорье, имена агентов, их местонахождение и планы. Эта информация просто бесценна.\n\nЯ незамедлительно передам эти сведения другим Служителям Земли. Спасибо тебе, друг.", rewards = "Шлем тайных знанийСандалии курьераНаплеч ТоорануВы получите:\n\n"}
MultiLanguageQuestData['ru'][28854] = {title = "Конец кошмара", objective = "Убейте властителя недр Эрудакса.", description = "Это ужасное место было кошмаром Алекстразы. В эпоху, которую смертные называют Второй войной, она была закована в кандалы глубоко в недрах земли, в то время как ее потомство было вынуждено служить мучителям из оскверненной демонами Орды.\n\nПусть Алекстраза ныне свободна, но чудовище по имени Эрудакс все еще вредит ее потомству, находящемуся внизу.\n\n<Тело Пламегона напряжено от гнева.>\n\nУничтожь его, <класс>. Расправься с ним, чтобы мы наконец-то забыли свои кошмары!", progress = nil, completion = "Наконец-то.\n\nЯ был готов уничтожить эту гору ради нашей цели.", rewards = "Кираса свидетеляПерчатки пламегонаНаручи искоренителяВы получите:\n\n"}
MultiLanguageQuestData['ru'][28856] = {title = "Пески Силитуса", objective = "Явитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.", description = "Так-с, посмотрим... ага, вот неплохое! Силитус!\n\nПохоже, Кругу Кенария требуется помощь в чем-то вроде нашествия насекомых.\n\n<Виззи поеживается.>\n\nФу, гадость какая! Нет уж, спасибо, это не по мне. Я буду и дальше с радостью замерзать тут в Круговзоре, если альтернатива – насекомые.\n\nХм... тут сказано, что вновь прибывшим следует обратиться к призывательнице ветров Гордый Рог, а добраться туда проще всего по горной тропе на северо-западе Кратера Ун'Горо.\n\nБерешься?", progress = nil, completion = "Добро пожаловать в крепость Кенария.\n\n&lt;Призывательница ветров Гордый Рог стряхивает снег с вашего плеча.&gt;\n\nА ты определенно прибыл издалека.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28857] = {title = "Выжженные земли: на другом краю света", objective = "Поговорите с интендантом Лунгерцом в Крепости Стражей Пустоты.", description = "А теперь кое-что интересное. Тут говорится о том, что гражданам Альянса надлежит явиться к интенданту Лунгерцу в Крепости Стражей Пустоты, что в Выжженных землях. Это самое отдаленное место, куда можно добраться отсюда!\n\nСказано, что им докучают нападения Орды. Хм! Для меня стало открытием, что у Орды вообще есть аванпост в Выжженных землях! Как я поняла, их больше заботят демоны, а не здешние противники.\n\nНе <согласился/согласилась> бы ты пересечь Великое море и затем отправиться на юг из Болота Печали?\n\nЧто скажешь?", progress = nil, completion = "Гарнизон Крепости Стражей Пустоты десятилетиями давал отпор набегам Орды. Мы не сдадимся перед лицом врага и сейчас.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28858] = {title = "Выжженные земли: на другом краю света", objective = "Поговорите с Окриллой в Форте Молота Ужаса, что находится в Выжженных землях.", description = "Вот это интересно. Здесь говорится о том, что подданные Орды должны явиться в форт Молота Ужаса и поговорить с Окриллой.\n\nХм! Я даже не знала, что форт Молота Ужаса находится в руках Орды!\n\nДумаю, этой Окрилле нужна помощь в борьбе с ограми и Альянсом. Надо полагать, у нее и так хлопот полон рот с тамошними демонами!\n\nЛучший способ попасть в форт Молота Ужаса – это пересечь Великое море, а затем идти по дороге на юг от Болота Печали.\n\nНу что, возьмешься за это дело?", progress = nil, completion = "У наших врагов несметная армия, |3-6(Жрица). От нас потребуется умение и отвага, чтобы сокрушить их.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28859] = {title = "Дюны Силитуса", objective = "Сообщите о своем прибытии призывательнице ветров Гордый Рог в Крепости Кенария, что в Силитусе.", description = "Крепость Кенария – одно из самых крупных поселений друидов в Калимдоре. Почти такое же большое, как Лунная поляна.\n\nМожет быть, когда-нибудь Зен'Алири отправится в Крепость Кенария... сражаясь с Сумеречным Молотом и исцеляя землю, изуродованную силитидами... но пока учитель Зен'Алири говорит ему ждать.\n\nИ Зен'Алири ждет.\n\nПроще всего туда попасть по дороге из Кратера Ун'Горо через северо-западные скалы.\n\nРаз у тебя нет учителя... значит ничто тебе не мешает отправиться туда.", progress = nil, completion = "Добро пожаловать в Крепость Кенария, путник.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28860] = {title = "Захлопни Драконью Пасть", objective = "Отправляйтесь в руины Громтара, убивайте мародеров Драконьей Пасти и соберите 8 знаков Драконьей пасти. Персонажи, у которых есть имена, тоже носят знаки различия.", description = "С твоей помощью мы крепко наподдали этим тварям из Драконьей Пасти, однако они по-прежнему совершают ежедневные набеги на окрестности Громтара. Нельзя ослаблять натиск!\n\nСтупай в бой, бушующий на юге и юго-западе руин Громтара. Убей мародеров Драконьей Пасти и собери знаки отличия их сильнейших воинов.", progress = "Ну что, как воюется,|3-6(Маг)?", completion = "Молодчина, так держать! Когда герои вроде тебя берутся за дело, меня исполняет гордость оттого, что я состою в Альянсе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28861] = {title = "Боевой эль", objective = "Отправляйтесь в руины Громтара и принесите 10 бочонков эля. И не вздумайте пробовать этот эль – с непривычки он валит с ног с двух глотков!", description = "<Бланди переворачивает кружку и трясет ее.>\n\nЭля ни капли не осталось, <имя>!\n\nСходи-ка на руины Громтара и посмотри, не осталось ли там немного, покуда эти мерзавцы из Драконьей Пасти все не выхлебали.\n\n<Сам/Сама>-то можешь отведать, не убудет. Кружечка старого доброго громтарского придаст тебе боевой сноровки.", progress = "Раздобыл чего-нибудь?", completion = "Ух ты ж, вот это улов!\n\nЭтого мне, пожалуй, хватит... до завтра точно.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28862] = {title = "Вылазка за продовольствием", objective = "Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.", description = "Потоки беженцев с фронта все стекаются и стекаются в Громтар, а я есть хочу! В смысле, они хотят... ну, беженцы... голодные, понимаешь.\n\nРаздобудь-ка чего-нибудь пожевать в руинах Громтара! Прочеши руины на юге, востоке и юго-западе – вдруг уцелели какие-нибудь припасы. В особенности дюжие окорока. Обожаю! То есть беженцы любят ветчину.\n\nДа посмотри, не попадется ли там чуток коктейльных сосисок!", progress = "Ну что? Добыл продовольствие?", completion = "Чудненько, ты поспел вовремя! Я как раз нагулял зверский аппетит... пока думал, чем же накормить наших горемычных беженцев. Да-да, так и было.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28863] = {title = "Полководец Халтар вернулся", objective = "Убейте полководца Халтара.", description = "Он снова взялся за свое, <имя>. Полководец Халтар... гроза графства. Его верхом на драконе видели на юге, среди руин Громтара.\n\nУбей Халтара, <имя>! Мы отправим передовых бойцов тебе на подмогу, когда ты вступишь в бой.", progress = nil, completion = "Печальная работенка, но сделана на славу. Спасибо, Венатарри.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28864] = {title = "За пивком", objective = "Встретьте Молоторука на дороге к юго-востоку от горы Громового Удара и сопроводите караван в Кирт.", description = "На свадьбе моей сестры больно полюбилось мне светлое громоварское, которое Курдран заказывает в Дун Мороге. Новую партию должны вот-вот доставить, но на наши обозы вечно нападают твари из Драконьей Пасти!\n\nОтправляйся на юго-восточный склон горы Громового Удара и встреть караван. Найди молодчика по имени Молоторук и помоги ему провезти выпивку через ущелье.\n\nСопроводи их до Кирта, а там уж мы вас подхватим.", progress = nil, completion = "Вот и поди угадай... Никогда бы не подумал, что полюблю импортное пиво. Спасибо, Аркоман!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28865] = {title = "Клич предводительницы", objective = "Поговорите с Окриллой в Форте Молота Ужаса в Выжженных землях.", description = "Наш досточтимая предводительница Окрилла направила меня в дальние уголки света на поиски истинных героев, готовых бороться за наше дело. <Готов/Готова> ли ты оказать помощь в расширении владений Орды в Восточных королевствах? Тогда зайди в этот портал, чтобы попасть в Выжженные земли, после чего найди Окриллу в Форте Молота Ужаса.", progress = nil, completion = "Силитус… бесполезный клочок земли. Удивительно, как великий катаклизм не разрушил его до основания!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28866] = {title = "В Каменные Недра", objective = "Обратитесь к Хранителю земли Изре в Каменных Недрах.", description = "Говоришь, Миллхаус Манашторм и верховная жрица Азил должны встретиться в Каменных Недрах?\n\nЭто, наверное, чертовски важно. Нужно скорее следовать за ними. Нельзя допустить, чтобы Сумеречный Молот проворачивал свои темные делишки прямо у нас под носом.\n\nДоложи это Хранителю земли Изре в Каменных Недрах. Она обосновалась там, чтобы помешать Сумеречному Молоту напасть на Храм Земли, если те все же отважатся.", progress = nil, completion = "Как вовремя прислали подмогу.\n\nМиллхаус Манашторм? Похоже, он нужен нам обоим.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28867] = {title = "Стражи Пустоты взывают к тебе!", objective = "Поговорите с интендантом Лунгерцом в Крепости Стражей Пустоты, что в Выжженных землях.", description = "Стражи Пустоты взывают к тебе, <класс>! Интендант Лунгерц направил меня сюда на поиски истинных героев Альянса, способных бороться с гнусными прихвостнями Окриллы из Орды! Помоги нам совладать с Ордой!\n\nЕсли есть на то желание, зайди в портал, открытый передо мной, чтобы попасть в Выжженные земли и поговори там с интендантом.", progress = nil, completion = "Силитус… бесполезный клочок земли. Удивительно, как великий катаклизм не разрушил его до основания!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28868] = {title = "Вид снизу", objective = "Примените сжиматик к 5 строителям из племени Мерзлогривов в Укрытии Мерзлогривов.", description = "Мы должны помешать строительству, которое идет в этой деревне Мерзлогривов. Если мы позволим им как следует укрепить свои позиции, то потом будет трудно помешать им обосноваться здесь навсегда.\n\nПришло время познакомить этих мерзавцев с точкой зрения гномов! Возьми вот этот сжиматик и с его помощью сожми строителей Мерзлогривов до нашего размера. После этого они не смогут удержать в руках инструменты и строительство заглохнет.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][28869] = {title = "Камешек", objective = "Поговорите с Камешком в Дрожащих Вершинах. Если вы некоторое время постоите неподвижно, он выйдет из укрытия и сам подойдет к вам.Если ты еще не <заметил/заметила>, ты <понравился/понравилась> одному очень маленькому элементалю. Если ты постоишь спокойно несколько минут, то наверняка увидишь его.\n\nПохоже, у тебя хорошо получается заводить новых друзей. Это замечательное качество.", description = "Если ты еще не <заметил/заметила>, ты <понравился/понравилась> одному очень маленькому элементалю. Если ты постоишь спокойно несколько минут, то наверняка увидишь его.\n\nПохоже, у тебя хорошо получается заводить новых друзей. Это замечательное качество.", progress = nil, completion = "&lt;Кажется, Камешек очень рад встретить вас.&gt;", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28870] = {title = "Возвращение в затерянный город", objective = "Обратитесь к капитану Хадану в Затерянном городе Тол'вире.", description = "Нам удалось захватить город Неферсет, но у противника остался еще один оплот.\n\nБлагодаря Сиамату, могущественному джинну южного ветра, жители Неферсета стали гораздо опаснее.\n\nМы только что узнали, что остатки разведотряда принца Надуна пробились ко входу в Затерянный город Тол'вир.\n\nРазыщи капитана Хадана и узнай у него всю необходимую информацию, чтобы расправиться с Сиаматом и его приверженцами из Неферсета.", progress = nil, completion = "Приветствую тебя, Саарух. Надун о тебе высокого мнения.\n\nТы пришел нам помочь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28871] = {title = "Сокрушение Громового Молота", objective = "Отправляйтесь в руины Громтара, убейте нескольких передовых бойцов Громового Молота и соберите 8 знаков Громового Молота. Персонажи, у которых есть имена, тоже носят знаки различия.", description = "Клан Громового Молота вконец обнаглел, став союзником Альянса. Они даже осмеливаются пересекать реку. Оттесни их!\n\nРазыщи и сокруши передовых бойцов Громового Молота, которые ведут бой в русле реки и в руинах Громтара на северном берегу. Самые заслуженные их бойцы носят знаки различия – отбери их и принеси мне. Этим ты докажешь свою преданность делу Драконьей Пасти.", progress = "Ну, показывай, сколько знаков различия ты набрал, |3-6(Разбойник).", completion = "Вы только полюбуйтесь: |3-6(Разбойник)-одиночка с легкостью расправляется с дюжиной громомольцев. На что они только надеются...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28872] = {title = "Дотла", objective = "Отправляйтесь в руины Громтара и разбейте 10 бочонков громтарского эля.", description = "Кое-кто в Громовом Молоте все еще надеется отвоевать руины Громтара на северном берегу реки. Выжги их! Бей по открытым бочонкам эля из Громтара. Это адское варево достаточно крепкое: отлично взрывается, если его поджечь.\n\nНе спрашивай – почему.\n\nИ не задавайся вопросом, как они умудряются пить эту отраву.", progress = nil, completion = "Да, да. Пусть все сгорит дотла!\n\nОтлично сработано, Лошади.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28873] = {title = "Еще один голодный рот", objective = "Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.", description = "<У Гриффа урчит в животе.>\n\nВсе еще зверски голоден. И вот так каждый день: жрать хочу – спасу нет...\n\nСлыхал я, на руинах Громтара остались еще съестные припасы. Это на севере, на другом берегу реки, где сейчас идут бои. Принеси чего-нибудь перекусить, сделай милость.", progress = "<Грифф жадно облизывает губы.>", completion = "&lt;Грифф жадно набрасывается на гору еды, которой хватило бы паре десятков дюжих молодцев.&gt;\n\nТак-то лучше! Теперь перекантуюсь... пару часиков.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28874] = {title = "На крючке", objective = "Убейте 4 наездников Громтара, предварительно сбросив их на землю с помощью шипастого крюка для плоти.", description = "Клан Громового Молота тренирует боевых грифонов быстрее, чем мы ловим и приручаем драконов. Нельзя позволить им и дальше брать нас числом!\n\nПеребей всадников на грифонах, что кружат над рекой к северу от Кровавого ущелья. Вот, держи крюк. Метай его в наездников, пролетающих мимо. Ускорение не позволит всаднику удержаться на грифоне, и когда он рухнет к твоим ногам, прикончи его!", progress = nil, completion = "Как у тебя все споро выходит, Лошади.\n\nСкинул громомольца с грифона – и он, считай, сыграл в ящик!", rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][28875] = {title = "Смерть верховному шаману", objective = "Убейте верховного шамана Маккиллигана.", description = "Наши разведчики докладывают с поля боя, что верховный шаман Маккиллиган выступил из Громтара и участвует в сражении в руинах Громтара, что к северо-западу отсюда на другом берегу реки.\n\nОн опасен, <имя>. Он ответствен за кровь многих наших собратьев из Драконьей Пасти. Его необходимо уничтожить, это не обсуждается.\n\nСтанешь ли ты тем героем, на счету которого будет эта славная победа?..", progress = nil, completion = "Верховный шаман повержен! Из Громтара, несомненно, пришлют новых сильных бойцов, но сегодня Драконья Пасть празднует победу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28876] = {title = "На заставу Мор'шан", objective = "Явитесь к Кадраку на заставу Мор'шан, что на границе между Северными Степями и Ясеневым лесом.Кадраку с заставы Мор'шан нужна твоя помощь!\n\nЗастава расположена на границе Северных Степей и Ясеневого леса – прямо на линии фронта.\n\nМы ведем кровопролитную борьбу с Альянсом, чтобы выжить лесных эльфов из леса и завладеть ресурсами на благо Орды!\n\nЧтобы добраться до заставы Мор'шан, следуй по Золотому Пути на север от Перекрестка в Северных Степях.\n\nСудьба зовет!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Кадраку с заставы Мор'шан нужна твоя помощь!\n\nЗастава расположена на границе Северных Степей и Ясеневого леса – прямо на линии фронта.\n\nМы ведем кровопролитную борьбу с Альянсом, чтобы выжить лесных эльфов из леса и завладеть ресурсами на благо Орды!\n\nЧтобы добраться до заставы Мор'шан, следуй по Золотому Пути на север от Перекрестка в Северных Степях.\n\nСудьба зовет!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28877] = {title = "Его называют Быстрый Нож. Он убивает гарпий.", objective = "Найдите Дарсока Быстрого Ножа в Северных Степях.К западу отсюда живет один орк. На самой границе территории, изуродованной катаклизмом.\n\nЕго называют Быстрый Нож, <имя>. Зовут его так потому, что… что… вообще я думаю, что это и есть его имя.\n\n<Котельник пожимает плечами.>\n\nВ общем, он – это машина по уничтожению гарпий. Он убивает гарпий. Он обожает это. Это его жизнь. Иди и посмотри на него! Посмотри, как это делается. Воплоти в жизнь мечту. Может, даже сделаешь на этом карьеру.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "К западу отсюда живет один орк. На самой границе территории, изуродованной катаклизмом.\n\nЕго называют Быстрый Нож, <имя>. Зовут его так потому, что… что… вообще я думаю, что это и есть его имя.\n\n<Котельник пожимает плечами.>\n\nВ общем, он – это машина по уничтожению гарпий. Он убивает гарпий. Он обожает это. Это его жизнь. Иди и посмотри на него! Посмотри, как это делается. Воплоти в жизнь мечту. Может, даже сделаешь на этом карьеру.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28878] = {title = "Подарок к Зимнему Покрову", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][28879] = {title = "Возвращение в приют", objective = "Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку оракула попечительнице сирот Арии.Нам было весело с тобой, <имя>. Жаль, что ты не можешь стать <нашим папочкой/нашей мамочкой>, и нам пора возвращаться к попечительнице сирот Арии в Даларан.\n\nМожет быть, ты еще навестишь нас как-нибудь? Нам очень понравилось общаться с малышами Зимних Плавников и с королевой драконов. И никто нам не поверит, что мы видели одного из Великих!\n\nМы будем скучать по тебе, <имя>. Обещаем, мы будем тебе писать!Вам дадут возможность выбрать одну из следующих наград:\n\n", description = "Нам было весело с тобой, <имя>. Жаль, что ты не можешь стать <нашим папочкой/нашей мамочкой>, и нам пора возвращаться к попечительнице сирот Арии в Даларан.\n\nМожет быть, ты еще навестишь нас как-нибудь? Нам очень понравилось общаться с малышами Зимних Плавников и с королевой драконов. И никто нам не поверит, что мы видели одного из Великих!\n\nМы будем скучать по тебе, <имя>. Обещаем, мы будем тебе писать!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВолшебное печенье для питомцаОткупные для скряги\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][28880] = {title = "Возвращение в приют", objective = "Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку волчера попечительнице сирот Арии.Знаешь, а мы не так уж и плохо провели время вместе, <имя>. Ты <показал/показала> Кекеку много всяких интересных мест. Кекек нашел новых друзей и сделал много всего такого, что не снилось другим щенкам.\n\nТеперь мы друзья – Кекек, ты, Хеминг Эрнестуэй и щенки Поляны Снегопада. Может быть, ты когда-нибудь принесешь Кекеку книгу про зеленые холмы? А Кекек обещает написать тебе как-нибудь и рассказать, как идут дела. Может быть, Кекек даже не будет больше дразнить длинноязыких детей.\n\nА теперь Кекеку пора возвращаться к попечительнице Арии, в фиолетовый город людей.Вам дадут возможность выбрать одну из следующих наград:\n\n", description = "Знаешь, а мы не так уж и плохо провели время вместе, <имя>. Ты <показал/показала> Кекеку много всяких интересных мест. Кекек нашел новых друзей и сделал много всего такого, что не снилось другим щенкам.\n\nТеперь мы друзья – Кекек, ты, Хеминг Эрнестуэй и щенки Поляны Снегопада. Может быть, ты когда-нибудь принесешь Кекеку книгу про зеленые холмы? А Кекек обещает написать тебе как-нибудь и рассказать, как идут дела. Может быть, Кекек даже не будет больше дразнить длинноязыких детей.\n\nА теперь Кекеку пора возвращаться к попечительнице Арии, в фиолетовый город людей.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВолшебное печенье для питомцаОткупные для скряги\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][28881] = {title = "Геолог Ганстен", objective = "Отчитайтесь геологу Ганстену в Руинах Южной Луны, что в Танарисе.", description = "Говоришь, ты еще не <бывал/бывала> в Руинах Южной Луны? Это упущение стоит исправить. Там у них полно разнообразных артефактов титанов. Отправляйся на запад и ищи палатки Лиги исследователей.", progress = nil, completion = "Ты прибыл нам на помощь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28882] = {title = "Победа на Тол Бараде", objective = "Выиграйте битву за Тол Барад и вернитесь к майору Марсдену в Лагерь Барадин на полуостров Тол Барад.", description = "Мы долго сражались, чтобы закрепиться на этом проклятом острове, поэтому не допустим, чтобы Орда вмешалась в наши планы. Контроль над Тол Барадом имеет первостепенное значение для Альянса, <имя>. Нам нужна твоя помощь! Одержи победу на Тол Бараде и вернись сюда, чтобы сообщить мне эту радостную весть.", progress = "Ты вернулся с победой над Ордой?", completion = "Чем это пахнет? Ах, это запах победы! Твои подвиги на Тол Бараде принесли победу всему Альянсу! Мы не забудем о твоих заслугах.", rewards = "Вы получите:\n\nРекомендательный значок Тол БарадаОчки чести"}
MultiLanguageQuestData['ru'][28884] = {title = "Победа на Тол Бараде", objective = "Выиграйте битву за Тол Барад и вернитесь к полковнику Карзагу в Хватку Адского Крика на полуостров Тол Барад.", description = "Контроль над Тол Барадом имеет ключевое значение в реализации нашей военной кампании в Восточных королевствах, <раса>. Требуется сделать все возможное, чтобы отвадить Альянс от этого острова, поэтому нам нужна твоя помощь. Задействуй любые средства, чтобы разгромить врага на Тол Бараде, а затем явись ко мне с вестью о победе.", progress = nil, completion = "Как я и ожидал, ты явился с радостной вестью! Всякий раз, как мы тесним врага на Тол Бараде, мы приближаем день окончательной победы Орды. Будь уверен, ты получишь заслуженное вознаграждение за свои подвиги.", rewards = "Вы получите:\n\nРекомендательный значок Тол БарадаОчки чести"}
MultiLanguageQuestData['ru'][28885] = {title = "Прокатимся с ветерком", objective = "Вместе с посвященным Клондацком прокатитесь на вагонетке до конца маршрута.", description = "Значит, так, <имя>. Нам надо добраться до портала земли в самом дальнем конце пещеры.\n\nЯ сделал умно – \"раздобыл\" транспорт. Зачем трудить ноги, когда можно проехаться с ветерком? Надеюсь, твоя религия не запрещает кататься на шахтерских вагонетках?\n\nВ общем, как будешь <готов/готова>, скажи – и поедем.", progress = nil, completion = "О, нет! Мое оружие и тотемы!\n\nОни уничтожены!!!", rewards = "Вы получите:\n\n"}
