MultiLanguageQuestData['ru'][28909] = {title = "Сауранок укажет путь", objective = "Поговорите с Сауранком Мистиком в Крепости Громмаш в Оргриммаре.", description = "Вижу, ты еще не <говорил/говорила> с Сауранком Мистиком. Он является моим советником с начала кампании в Нордсколе.\n\nЧтобы напасть на Сумеречное нагорье, нам нужен план побережья. Я попросил Сауранка раздобыть эту информацию. Узнай, не нужна ли ему твоя помощь! Он тут, недалеко от меня.", progress = nil, completion = "&lt;Сауранок кивает в вашу сторону.&gt;\n\nДруид.", rewards = "Вы получите:\n\n"}
