MultiLanguageQuestData['ru'][28934] = {title = "Конец Королевской компании", objective = "Убейте 5 техников химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами на заброшенной ферме к востоку от гробницы Хартута, рядом со входом со стороны Танариса. После этого вернитесь к инспектору Кромсу Гвоздезубу в Штормград.", description = "В этом гроссбухе указано множество мест, и ты, <парень, должен/подруга> должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.\n\nВот запись, которая меня особенно волнует: в ней говорится о месте в Ульдуме, которое находится к востоку от гробницы Хартута, рядом со входом со стороны Танариса. Не нравится мне это. Иди туда и разберись.\n\nДа, если увидишь что-то большое и опасное – брось в него эту бомбу.", progress = nil, completion = "Отлично, малыш. Ты заслуживаешь небольшой награды. Загляни ко мне завтра – вдруг у меня найдется еще какое-нибудь поручение для тебя.", rewards = "Вы получите:\n\nЗнак любвиПредмет #1"}
MultiLanguageQuestData['ru'][28935] = {title = "Конец Королевской компании", objective = "Убейте 5 техников химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами на заброшенной ферме к востоку от гробницы Хартута, рядом со входом со стороны Танариса. После этого вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.", description = "В этом гроссбухе указано множество мест, и ты, <парень, должен/подруга> должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.\n\nВот запись, которая меня особенно волнует: в ней говорится о месте в Ульдуме, которое находится к востоку от гробницы Хартута, рядом со входом со стороны Танариса. Не нравится мне это. Иди туда и разберись.\n\nДа, если увидишь что-то большое и опасное – брось в него эту бомбу.", progress = "Ты их проучил?", completion = "Отлично, малыш. Ты заслуживаешь небольшой награды. Загляни ко мне завтра – вдруг у меня найдется еще какое-нибудь поручение для тебя.", rewards = "Вы получите:\n\nЗнак любвиПредмет #1"}
MultiLanguageQuestData['ru'][28936] = {title = "Дилемма дивы", objective = "Убейте 6 наг.", description = "TBD.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][28937] = {title = "Хлебные крошки Альянса", objective = "Поговорите с Леди Гаргой в бухте Фальдира.Чудовища! Просто чудовища!\n\nНаш корабль зашел в порт к югу от Cтромгарда, но на берегу нас ждала стая странных созданий.\n\nПеред тем как смыться оттуда, я успел обратить внимание на их противные морды и странные булькающие звуки, которые они издавали. Лучше поспеши на помощь моим товарищам, <имя>!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Чудовища! Просто чудовища!\n\nНаш корабль зашел в порт к югу от Cтромгарда, но на берегу нас ждала стая странных созданий.\n\nПеред тем как смыться оттуда, я успел обратить внимание на их противные морды и странные булькающие звуки, которые они издавали. Лучше поспеши на помощь моим товарищам, <имя>!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
