MultiLanguageQuestData['ru'][29261] = {title = "Вуду Зул'Амана", objective = "Тот, кто возводил эту груду черепов, погиб, не закончив работы. Если вы завершите начатое, духи будут хранить вас…", description = nil, progress = "Тот, кто возводил эту груду черепов, погиб, не закончив работы. Если вы завершите начатое, духи будут хранить вас…", completion = "Именно этой таблички и не хватало, чтобы магические формулы заработали, и магия от груды черепов перешла к вам и вашей группе!", rewards = "Вы изучите:\n\nСила Амани\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29262] = {title = "Вуду Зул'Гуруба", objective = "От этой кучи черепов исходит ощущение сильного колдунства…", description = nil, progress = "От этой кучи черепов исходит ощущение сильного колдунства…", completion = "Именно этой таблички и не хватало, чтобы магические формулы заработали, и магия от кучи черепов перешла к вам и вашей группе!", rewards = "Вы изучите:\n\nПризыв ящера\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29263] = {title = "Горькая пилюля", objective = "Найдите подземного магмачервя по пузырькам от его дыхания. Затем убейте его, заставив проглотить горькую пилюлю.", description = "Если тебе интересно мое мнение, то я считаю, что нет такой проблемы, которую бы нельзя было решить при помощи бомб. А если с первого раза бомба не решает твою проблему – просто в следующий раз возьми бомбу побольше.\n\nТак вот, у лавовых озер, к северу отсюда, завелся большой червь, который пожирает людей. Чтобы его найти, следи за пузырями на поверхности лавы – это он дышит. Напади на него, а когда он приготовится тебя укусить, положи перед ним бомбу. Затем можешь отойти и полюбоваться фейерверком.\n\nЧто-то я еще хотела тебе сказать... Ах, да! Смотри, чтобы он тебя не сожрал.", progress = nil, completion = "Что я говорила! Бомбы Рикет решают любую проблему. Нужно лишь подобрать правильный размер.", rewards = "Вы получите:\n\nПредмет #1Знак Древа ЖизниCurrency Token Test Token 2"}
MultiLanguageQuestData['ru'][29264] = {title = "Поджигатели из Расплавленного потока", objective = "Убейте 8 поджигателей в Расплавленном потоке.", description = "Поджигатели – самые преданные приспешники Рагнароса. Почти все они обитают в этой пещере и готовятся к новой атаке. Наш опорный пункт неплохо защищен, но нам не нужны никакие внезапные нападения этих червей.\n\nНет, это мы должны нанести первый удар.\n\nУничтожь их, <имя>.", progress = nil, completion = "Мне нравится, как ты работаешь, Лошади.", rewards = "Вы получите:\n\nЗнак Древа ЖизниCurrency Token Test Token 2"}
MultiLanguageQuestData['ru'][29265] = {title = "Огненные цветы", objective = "Соберите 5 чертопоротников.", description = "Моя подруга-друид, Чолуна, попросила нас собрать образцы растений, которые встретятся нам в Огненных Просторах…\n\n…Не знаю, кому принадлежала идея отправить ученых на передовую.\n\nТак или иначе – тебе же все равно нужно в пещеру, чтобы убить там разных существ. Посматривай заодно и под ноги, ладно?", progress = "Они растут повсюду. Просто будь внимательнее.", completion = "Я никогда не перестану им удивляться. Может это настоящие цветы, а может просто хрупкие каменные образования, но в любом случае тот факт, что они умудряются расти в таких неблагоприятных условиях, просто поразителен.\n\nНемедленно отправлю эти растения Аврилле для изучения.", rewards = "Вы получите:\n\nЗнак Древа ЖизниCurrency Token Test Token 2"}
