MultiLanguageQuestData['ru'][29342] = {title = "Зимняя рыбалка", objective = "Поймайте 5 арктических гольцов в озере Хельмово Ложе, что в Дун Мороге.", description = "Самая вкусная рыба водится в холодных водах Дун Морога, <имя>. С этим никто не поспорит! Арктический голец пользуется у жителей Стальгорна особенной популярностью. Я и сам его обожаю.\n\nДумаю, это дар Стальгорна всему миру!\n\nНе хочешь <сам/сама> наловить гольца? Он облюбовал озеро Хельмово Ложе в восточной части Дун Морога.", progress = "Ну что, наловил гольца?", completion = "Чудесная рыбка, Галькожор! Думаю, ты поднаторел в рыбной ловле.", rewards = "Вы получите:\n\nСума блестяшек"}
MultiLanguageQuestData['ru'][29343] = {title = "Легендарная рыба", objective = "Поймайте молодого сталезуба в Заброшенном гроте Стальгорна и выставьте его на обозрение над пустой табличкой в Библиотеке.", description = "Думаю, тебе доводилось слышать легенду о старом сталезубе – самой известной и неуловимой рыбе, обитающей в Заброшенном гроте Стальгорна. Долгие годы эта рыбина плодила молодых сталезубов. Только не обольщайся, <имя>, несмотря на свое название, они так же хитры, как и их прародитель.\n\nДумаю, при достаточном терпении ты <мог/могла> бы выловить молодого сталезуба. Когда поймаешь рыбу, принеси ее в музей при Библиотеке Стальгорна для всеобщего обозрения.", progress = nil, completion = "Великолепно, Найммитт! Надеюсь, теперь многие дворфы последуют твоему примеру и займутся рыбной ловлей!", rewards = "Вы получите:\n\nСума блестяшекПредмет #1"}
MultiLanguageQuestData['ru'][29344] = {title = "Рыба для Трескунчика", objective = "Поймайте 3 слепые ледоспинки в Заброшенном гроте и накормите ими Трескунчика.", description = "Я успел познакомить тебя с моим питомцем, Трескунчиком? Я учу его ловить рыбу. Кормлю ледоспинками, которых можно поймать в этом гроте.\n\nХочешь тоже попробовать? Налови рыбы здесь в гроте и покорми Трескунчика любыми ледоспинками, которых поймаешь. Он навсегда тебя полюбит!", progress = nil, completion = "Ты славно потрудился. Трескунчик очень доволен, а у меня было время на изготовление новых приманок. Спасибо за помощь!", rewards = "Вы получите:\n\nСума блестяшекПредмет #3"}
MultiLanguageQuestData['ru'][29345] = {title = "Хищники в пруду", objective = "Ках Вестник Туманов из Громового Утеса просит вас выловить 8 азшарских змееголовов из пруда Громового Утеса.", description = "Один преисполненный самых лучших намерений гоблин запустил в наш пруд азшарских змееголовов, и теперь водоем просто кишит ими.\n\nЕсли тебе удастся уменьшить численность этих прожорливых тварей до того, как они уничтожат всех илистых луцианов и блестящих рыбок в Громовом Утесе, я буду тебе очень признателен.", progress = "Удалось поймать хоть сколько-нибудь азшарских змееголовов?", completion = "Молодец, Няман. Избавить пруды Мулгора от этих прожорливых тварей – долг каждого рыбака Громового Утеса!", rewards = "Вы получите:\n\nСума блестяшек"}
MultiLanguageQuestData['ru'][29346] = {title = "Дело в кольце", objective = "Отправляйтесь на рыбалку на Пруды Видений в Громовом Утесе. Когда поймаете слепоглазку, выпотрошите ее и поищите внутри кольцо.", description = "Ко мне приходил один из Отрекшихся с Прудов Видений и что-то говорил про кольцо, которое он уронил в воду, а его затем проглотила слепоглазка.\n\nИли он имел в виду свой палец? Трудно сказать точно – его челюсть еле двигалась, а на орочьем он говорит не лучше меня.\n\nТак или иначе, я думаю, нам стоит попытаться поймать эту слепоглазку, выпотрошить ее и найти то ли его палец, то ли кольцо.\n\nТы не поможешь?", progress = "Не попадалось ли тебе кольцо? Наверняка его проглотила одна из слепоглазок…", completion = "Ты нашел мое кольцо? Я так благодарен!\n\nЧестно говоря, не знаю, зачем я храню его. Я даже точно не помню, откуда оно у меня… Наверное, просто сила привычки.\n\nВ общем, я рад получить его назад. Вот, посмотри… Пока я сам искал его, нашел кое-какие полезные штуки. Может быть, что-то из этого пригодится тебе?", rewards = "Вы получите:\n\nСума блестяшекПредмет #1"}
MultiLanguageQuestData['ru'][29347] = {title = "На живца", objective = "Намажьтесь наживкой Мрачнура, а затем прыгайте в озеро Хельмово Ложе, что в Дун Мороге.", description = "Если тебе приходилось когда-нибудь ловить раков, ты <должен/должна> знать, что охотнее всего они клюют на живую приманку. И чем этой приманки больше, тем лучше. Не хочешь испытать мою новую наживку? Просто намажься вот этим и прыгай в озеро Хельмово Ложе, что в восточной части Дун Морога.\n\nНаловишь раков – отнеси их моему приятелю, повару Гильму в карьер Гол'Болар, что к западу от озера. Он эксперт по приготовлению этих членистоногих!", progress = nil, completion = "Отличные раки, Венатарри! Мрачнур будет очень горд, когда узнает об этом!\n\nДа, он просил передать тебе это в том случае, если его план сработает.", rewards = "Следующее заклинание будет наложено на вас:\n\nОтмена ловли раков\n\nВы получите:\n\nСума блестяшекПредмет #1"}
MultiLanguageQuestData['ru'][29348] = {title = "Заселить водоем", objective = "Поймайте в озере Каменного Быка 2 страстные блестящие рыбки и 2 любвеобильных илистых луцианов и отнесите их Каху Вестнику Туманов.", description = "В пруду Громового Утеса кишмя кишат азшарские змееголовы и они сожрали уже почти всех блестящих рыбок и илистых луцианов.\n\nНаши рыбаки уже вовсю ловят змееголовов, чтобы уменьшить их численность, а ты можешь помочь заселить пруды новыми рыбами.\n\nВылови немного рыбы из озера Каменного Быка. Я буду очень признателен тебе за это.", progress = "Ты принес рыбу из озера Каменного Быка?", completion = "Большое спасибо за помощь, Усамыч.\n\nБудем надеяться, эти рыбки расплодятся в нашем пруду.", rewards = "Вы получите:\n\nСума блестяшек"}
MultiLanguageQuestData['ru'][29349] = {title = "Деликатесные раки", objective = "Ках Вестник Туманов из Громового Утеса просит вас поймать 10 раков из озера Каменного Быка в Мулгоре.", description = "Один из главных деликатесов Мулгора – раки, которые живут в местных озерах и ручьях. Особенно большой популярностью блюда из этих раков пользуются на свадьбах и на праздниках в честь рождения детей.\n\nНе наловишь ли ты раков для поваров Громового Утеса?\n\nМожно выловить их на удочку из озера Каменного Быка, а можно просто нырнуть и собрать раков со дна.", progress = "Раки очень вкусны. Много поймал?", completion = "О, как много раков!\n\nТы их на удочку поймал? Или нырял за ними?\n\nНе имеет значения. Отличный результат, Куард.", rewards = "Вы получите:\n\nСума блестяшек"}
MultiLanguageQuestData['ru'][29350] = {title = "Гномский блесн-о-матик", objective = "Возьмите 5 блесен, взрыватель и 3 крысоловки и с помощью чертежей соберите гномский блесн-о-матик.", description = "Один из гномских учителей инженерного дела дал мне чертеж отличного устройства, которое поможет мне быстрее ловить рыбу и не давать ей сорваться с крючка. Выглядит оно немного странно, но попробовать хотя бы раз стоит.\n\nДержи, вот чертежи. Тебе понадобятся блесны, их можно купить у моего ассистента внутри здания. Взрыватель можно приобрести у торговца товарами для инженеров в Городе Механиков. А крысоловки можно найти в Подземном поезде.", progress = "Ну как там эта новая блесна?", completion = "Не очень-то похоже, чтобы рыба могла заинтересоваться этим. Но как знать. Рыбы – странные создания. Спасибо, что помог с этой затеей, Рен.", rewards = "Вы получите:\n\nСума блестяшекПредмет #1Предмет #3"}
MultiLanguageQuestData['ru'][29351] = {title = "Забота о стражниках", objective = "Раздайте стальгорнский паек 6 стражникам Стальгорна.", description = "Стражники, которые защищают Стальгорн от врагов, каждый день рискуют своими жизнями. Забота об их пропитании лежит на наших плечах. На сегодняшний день их паек включает в себя два любимых блюда дворфов – рулет с потрошками и стальгорнский светлый эль. Не поможешь ли ты мне обеспечить стражников их любимыми продуктами? В таком случае все получат свой паек вовремя, и мы сможем уделить внимание другим задачам.", progress = nil, completion = "Я всегда говорю, что хороший солдат – это сытый солдат. Спасибо тебе за помощь, Кидбомба.", rewards = "Вы получите:\n\nПредмет #1Жетон Железной ЛапыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][29352] = {title = "Нужны цыплята", objective = "Поймайте 6 дунморогских цыплят у входа в Стальгорн.", description = "О, нет, <имя>, если мы как можно быстрее не найдем цыплят, произойдет катастрофа… Как же я сварю куриный суп без цыплят? Это просто невозможно!\n\nНо если быстро раздобыть свежих цыплят, я еще успею сварить и суп, и бульон. Поможешь мне? У главного входа в город почти всегда бегает несколько штук. Принеси, скажем, шесть, и мой суп спасен!", progress = "Цыплята, Анроризз, цыплята! Ты их принес?", completion = "Прекрасно, именно то, что надо. Спасибо тебе, Анроризз, и прости, что я был с тобой резок. Просто не выношу, когда не успеваю приготовить еду в срок.", rewards = "Вы получите:\n\nПредмет #1Жетон Железной ЛапыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][29353] = {title = "Рулета с потрошками много не бывает", objective = "Купите мешок бараньих потрохов, 5 пакетиков пряных трав и 4 мешка толокна.", description = "Рулет с потрошками должен литься рекой. Нет, это, конечно, просто фигура речи, рулеты ведь не текут! Но ты даже представить себе не можешь, что будет, если жителям Стальгорна не хватит потрошков.\n\nЯ как раз занимаюсь приготовлением очередной партии. Мне не хватает пары ингредиентов.\n\nБараньи потроха – именно такие, как мне нужно, – можно купить у Согнара Скалоборода, торговца мясом из Военного квартала. И еще купи пряных трав у любого торговца товарами для кулинарии. А толокно ты сможешь найти в любой таверне или в продуктовых лавках города.", progress = "Ты принес ингредиенты?", completion = "Все принес? Чудесно! Я прямо сейчас и начну.", rewards = "Вы получите:\n\nПредмет #1Жетон Железной ЛапыCurrency Token Test Token 2"}
MultiLanguageQuestData['ru'][29354] = {title = "Блестящие камешки", objective = "Соберите 20 блестящих камешков у подножия центрального уступа для Нахари Заоблачной Охотницы.", description = "Блесна – одна из самых простых, но эффективных рыболовных снастей. Даже самый зеленый новичок с блесной уж что-нибудь да поймает.\n\nА рыбаков в Громовом Утесе в последнее время стало видимо-невидимо. И мои запасы подходят к концу!\n\nМогу ли я попросить тебя об одолжении? Пособирай блестящие камешки у подножия центрального уступа. А потом отнеси их Нахари Заоблачной Охотнице, чтобы она сделала из них блесны.", progress = "Ты принес мне блестящие камешки?", completion = "Какие замечательные камешки! Из них получатся отличные блесны. Спасибо тебе.\n\nПостой… Ках говорил мне, что ты зайдешь и принесешь камешки, и просил передать тебе вот это.", rewards = "Вы получите:\n\nСума блестяшек"}
MultiLanguageQuestData['ru'][29355] = {title = "Хлеба с пряностями много не бывает", objective = "Приготовьте сами или купите 10 хлебов с пряностями.", description = "Ты можешь подумать – ну что особенного в хлебе? – но тем не менее жители Стальгорна с давних пор очень любят хлеб с пряностями. Порой не так-то просто поддерживать его запасы на нужном уровне!\n\nНе хочешь потренироваться в кулинарии и испечь немного хлеба? Заодно и мне поможешь. Все необходимые ингредиенты можно купить у моего брата, Эмруля Рикнуссена. Ты найдешь его внизу.", progress = "Ты принес хлеб?", completion = "Выглядит очень аппетитно. Спасибо, Кидбомба.", rewards = "Вы получите:\n\nЖетон Железной ЛапыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][29356] = {title = "Доставка бочонка", objective = "Заберите бочонок стальгорнского светлого эля Драгана, который стоит у пивоварни в Караносе, и доставьте его в Стальгорн.", description = "Мои запасы стальгорнского светлого эля подходят к концу. К счастью, пивоварня отсюда недалеко и у них всегда найдется несколько бочонков эля для нас.\n\nУ меня сегодня не получится отправиться в Каранос, но, может быть, ты туда сбегаешь и принесешь сюда бочонок? Что скажешь?", progress = "Ты принес бочонок?", completion = "Прекрасно! Я всегда говорю, что Драган – это просто находка! Историк, исследователь, да еще и пиво варит. Есть ли что-то, чего он не умеет?", rewards = "Вы получите:\n\nПредмет #1Жетон Железной ЛапыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][29357] = {title = "Хлеба с пряностями хоть отбавляй", objective = "Приготовьте сами или купите 10 хлебов с пряностями.", description = "Разве не удивительно, что такая простая вещь, как хлеб с пряностями, пользуется такой популярностью среди жителей Дарнаса? Его едят каждый день. Когда я не занят чем-то другим, я всегда пеку немного хлеба с пряностями, чтобы не терять навыка.\n\nНе хочешь тоже попробовать? Все необходимые ингредиенты можно купить здесь же в магазине.\n\nСколько бы хлеба мы ни испекли, лишним он не будет. Когда закончишь, принеси свой хлеб сюда. Я поделюсь им с нашими новыми друзьями из Гилнеаса.", progress = "Обожаю аромат свежевыпеченного хлеба, особенно хлеба с пряностями. А ты?", completion = "Прекрасный хлеб, Найммитт. Надеюсь, выпечка доставляет тебе столько же удовольствия, сколько и мне.", rewards = "Вы получите:\n\nЖетон Железной ЛапыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][29358] = {title = "Недостаток орехов", objective = "Соберите 30 кедровых орешков, подержав над огнем мулгорские кедровые шишки, затем отнесите их Аске Вестнице Туманов в Громовой Утес.", description = "Шу'хало используют кедровые орешки во многих блюдах – добавляют их к мясу, к рыбе, к овощам, даже хлеб с ними пекут и в другую выпечку добавляют.\n\nБлагодаря Матери-Земле САМЫЕ ЛУЧШИЕ кедровые орешки растут на деревьях вот на этих самых плато. Просто подбирай шишки, а затем подержи их над огнем, чтобы они раскрылись.\n\nНе будешь ли ты так <добр/добра> собрать немного орешков? Достаточно просто пройтись по округе...", progress = "Много ли тебе удалось собрать этих прекрасных кедровых орешков?", completion = "Как быстро!\n\nЯ прослежу за тем, чтобы эти орешки попали к лучшим поварам и пекарям Громового Утеса.\n\nСпасибо тебе!", rewards = "Вы получите:\n\nПредмет #10Жетон Железной ЛапыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][29359] = {title = "Любимая рыба", objective = "Отправляйтесь в деревню Рут'теран и поймайте 8 калдорайских сельдей.", description = "Сельдь — самый популярный вид рыбы в Дарнасе. Но не любая сельдь, а только настоящая калдорайская, которая обитает лишь в водах, окружающих Тельдрассил.\n\nЯ стараюсь держать ее про запас, ведь у нее столько различных способов приготовления! Недавно я закончила коптить очередную партию рыбы, так что нужно снова наловить свежей. Не хочешь мне в этом помочь? Калдорайская сельдь водится вблизи деревни Рут'теран.", progress = "Ну что, клюет?", completion = "Спасибо! Что же мне приготовить в этот раз…", rewards = "Вы получите:\n\nСума блестяшек"}
MultiLanguageQuestData['ru'][29360] = {title = "Как насчет того, чтобы добавить мух?", objective = "Соберите 25 жирных мух с \"мяса\", лежащего рядом с мясными фургонами. Затем вернитесь к Эвнике Барч в Подгород.", description = "Готовить еду для орков непросто, <класс>. Но на этот раз мы будем готовить еду для их потенциальной замены.\n\nНачинать надо с малого – поймать мух. Мухам нравится гниющее мясо. И нам нравится мясо… когда мясные фургоны забрасывают им врагов.\n\nПроверь, не осталось ли в мясных фургонах лишнего мяса. Найдешь мясо – найдешь и мух.\n\nПринеси мне 25 жирных мух, и мы сможем перейти ко второй части нашего кулинарного плана.", progress = "Готова поспорить, что какие-то куски\"мяса\" там еще вполне съедобны.", completion = "Чудесно! Жирные, неповоротливые, готовые к употреблению. В следующий раз будем ими откармливать наших пауков. А потом пауками попробуем откармливать наших жаб…\n\nТебе не обязательно быть в курсе всех подробностей. Это лишь ступенька на пути к вершинам кулинарного мастерства.", rewards = "Вы получите:\n\nЖетон Железной ЛапыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][29361] = {title = "Канавный монстр!", objective = "Воспользуйтесь набором для ловли на живца, чтобы приманить канавного монстра в Руинах Лордерона. Затем скормите ему жирных жаб.", description = "Иногда улов нужно бросать обратно, <класс>.\n\nCледуя этому правилу рыбалки, мы и откармливали этих жаб. Мы взяли жирных мух и откормили ими пауков, потом пауками откормили жаб, и вот теперь мы собираемся кормить ими настоящего монстра.\n\nВ Руинах Лордерона есть канава, в ней живет наш собственный канавный монстр.\n\nИ сегодня как раз день кормежки. Но монстра надо еще и обучать. Держи эту сумку. В ней набор, который поможет приманить монстра, и несколько жирных жаб. Воспользуйся набором, а затем, когда появится монстр, бросай ему жаб.", progress = nil, completion = "Мертвечина пошла на корм мухам. Мух съели пауки. Пауками мы откормили жаб. А жабы идут в пищу нашему канавному монстру… Какая прекрасная пищевая цепочка, которая в конечном итоге снова приведет к смерти.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #1\n\nВы также получите:\n\nСума блестяшекПредмет #1"}
MultiLanguageQuestData['ru'][29362] = {title = "\"Волшебные\" грибочки", objective = "Соберите 6 \"волшебных\" грибочков у Прудов Видений в Громовом Утесе. Отнесите их Аске Вестнице Туманов.", description = "Тебе же знакомы Пруды Видений, не правда ли?\n\nВокруг них растут одни грибы… Нет, я говорю не о крепких, больших грибах, которые можно найти повсюду в тех местах, а о маленьких грибочках, которые растут под ними.\n\nОни довольно вкусны, но встречаются редко. Если добавить их к мясу, оно приобретает такой прекрасный вкус, что многие называют блюдо волшебным.\n\nЧто?.. Нет-нет, это совсем не то, о чем ты <подумал/подумала>. Просто эти грибочки очень вкусные. Вот и все.", progress = "Тебе удалось собрать грибочки?", completion = "Спасибо тебе, Вульватер! Уверена, с этими грибочками любое блюдо получится волшебным.\n\nЧто? Прекрати смотреть на меня так!", rewards = "Вы получите:\n\nЖетон Железной ЛапыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][29363] = {title = "Мулгорский хлеб с пряностями", objective = "Возьмите обычный хлеб с пряностями, мулгорские пряности и приготовьте мулгорский хлеб с пряностями. Обычный хлеб с пряностями вы можете либо купить, либо испечь самостоятельно. Отнесите готовый хлеб Аске Вестнице Туманов в Громовой Утес.", description = "Меня часто спрашивают: \"Аска, а кто же печет весь этот мулгорский хлеб с пряностями?\".\n\nРезонный вопрос! Наш знаменитый изысканный хлеб продается повсюду, в том числе и в очень далеких землях. Его покупают даже наши враги. Настолько он хорош!\n\nА каков ответ?..\n\nПечь хлеб будешь ТЫ. Вот, возьми этот пакетик мулгорских пряностей и преврати с их помощью банальный хлеб с пряностями в МУЛГОРСКИЙ хлеб с пряностями!", progress = "Мулгорский хлеб с пряностями готов?", completion = "Ммм, какой аромат! А ты, оказывается, прекрасно печешь, Саарух.\n\nИнтересно, к кому на стол попадет этот хлеб… Я слышала, что он нравится даже дренеям с острова Лазурной Дымки!", rewards = "Вы получите:\n\nПредмет #1Жетон Железной ЛапыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][29364] = {title = "Перемолка зерна", objective = "Помогите жителям Громового Утеса перемолоть зерно в муку.", description = "Самый важный продукт в Громовом Утесе – это мука. Вряд ли найдется дом, в котором бы не было муки.\n\nМестные мельницы частенько подвергаются атакам гарпий, гноллов, каких-то безрассудных проходимцев и Мать-Земля знает, кого еще. Поэтому я частенько прошу своих учеников помочь мне перемалывать зерно в муку.\n\nНе хочешь ли помочь и ты?", progress = nil, completion = "Чтобы намолоть муки для всех, нужно много трудиться. Спасибо тебе за помощь, Усамыч.", rewards = "Вы получите:\n\nЖетон Железной ЛапыCurrency Token Test Token 2"}
MultiLanguageQuestData['ru'][29365] = {title = "Самые лучшие продукты", objective = "Обойдите торговцев Громового Утеса и принесите Аске Вестнице Туманов самые лучшие мясо, рыбу, овощи и травы.", description = "Даже поваренок знает, что для вкусного блюда нужны качественные ингредиенты.\n\nУ меня есть долгосрочные договоренности о поставке продуктов почти со всеми торговцами Громового Утеса, но я хочу посмотреть, как ты справишься с этой задачей – выбрать лучшее из того, что они предлагают.\n\nПожалуйста, обойди их всех и возвращайся с лучшими мясом, рыбой, овощами и травами из местных лавок.", progress = "Все необходимые продукты у тебя?", completion = "&lt;Аска рассматривает принесенные вами продукты.&gt;\n\nМмм. Да. Неплохо!\n\nЛучше я бы и сама не смогла выбрать.", rewards = "Вы получите:\n\nЖетон Железной ЛапыCurrency Token Test Token 4"}
MultiLanguageQuestData['ru'][29371] = {title = "Время терять", objective = "Отправляйтесь в Руины Лордерона и облейте Плетеного человека гасящим веществом.", description = "Приветствую, <класс>. Раз мы тоже хотим провести церемонию сжигания Плетеного человека, неудивительно, что Орда попытается помешать нашему празднику.\n\nБыло бы благоразумно решить, что мы выше этого, и не обращать внимания на агрессию с их стороны.\n\nЯ восхищаюсь теми, кто способен вести себя так благородно, но ничем не могу им помочь. А вот тем, кто на удар отвечает ударом, я помочь могу. Если это интересует тебя, <класс>, то возьми это гасящее вещество и облей им Плетеного человека Орды в Руинах Лордерона.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТыквовинские сладостиПредмет #1"}
MultiLanguageQuestData['ru'][29372] = {title = "Переполох в захолустье", objective = "Спасите шерифа.", description = "Шерифа похитили!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29373] = {title = "Переполох в захолустье", objective = "Спасите шерифа.", description = "We never paid no heed to Sheriff Blundy, what with his gettin' all up-in-arms at all times 'bout his \"laws\" and his \"mis-de-meanors.\" But them dirty ol' McClintocks, and their cattle-rustlin' pappy up in Truckshaw ridge done had it up to here with the frequent incarcerations and trials and posse-gatherin' and dead-or-alive-wantin', and come this past week they done took the law into their own hands – in the most literal of senses – by haulin' up and hi-jackin' the good Sheriff. As you can see, our humbleВы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29374] = {title = "Сбросить бомбы-вонючки", objective = "Поговорите с Криной Фэнлоу, затем садитесь на метлу и бросайте бомбы-вонючки на Штормград.", description = "Идиоты-альянсовцы прибегли к помощи ведьм в тщетной попытке атаковать наш город. Что ж, моя сестра всегда говорила мне: \"Посмотри на ситуацию с другой стороны\".\n\nМы с удовольствием отплатим им той же монетой. Поговори с моей сестрой, она даст тебе метлу для полета над Штормградом. Когда будешь над городом, сбрасывай бомбы-вонючки. Пусть им придется несладко!\n\nМы покажем этим штормградским ведьмам, кто сильнее.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТыквовинские сладости"}
MultiLanguageQuestData['ru'][29375] = {title = "Уборка в Подгороде", objective = "Воспользуйтесь чародейским нейтрализатором и очистите Подгород от бомб-вонючек.", description = "Здравствуй, <класс>! Тебе нравится Тыквовин? Похоже, что после того, как мы сбросили бомбы-вонючки на Штормград, Альянс решил отплатить нам той же монетой.\n\nК счастью, в нашем распоряжении магия, которая может справиться со всей этой вонью. Воспользуйся чародейским нейтрализатором, чтобы убрать бомбы и вонь.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТыквовинские сладостиПредмет #1"}
MultiLanguageQuestData['ru'][29376] = {title = "Время созидать", objective = "Воспользуйтесь большим костром, чтобы поджечь Плетеного человека. Потом воспользуйтесь пеплом, который появится на земле возле Плетеного человека.", description = "Мы сжигаем Плетеного человека, как знак нашей борьбы с теми, кто выступает против нас. Мы раскрашиваем лица пеплом, что символизирует нашу нескончаемую борьбу с теми, кто хочет поработить нас.\n\nВоспользуйся костром и подожги Плетеного человека. Потом возьми пепел и раскрась им лицо.\n\nПусть все это напомнит нашим врагам о том, что мы никогда не сдадимся.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТыквовинские сладости"}
MultiLanguageQuestData['ru'][29377] = {title = "Время разрушать", objective = "Отправляйтесь в Штормград и облейте Плетеного человека гасящим веществом.", description = "Приветствую тебя, <класс>! Нет никаких сомнений, что когда мы будем проводить церемонию сожжения Плетеного человека, Альянс попытается испортить нам праздник.\n\nНо у нас есть возможность отплатить им той же монетой. Если хочешь нам помочь, возьми это гасящее вещество и потуши Плетеного человека Альянса, который стоит перед вратами Штормграда.\n\nПотуши их огонь и порадуйся их несчастью, <класс>.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТыквовинские сладостиПредмет #1"}
MultiLanguageQuestData['ru'][29385] = {title = "Подарок к Зимнему Покрову", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПодарок к Зимнему Покрову"}
MultiLanguageQuestData['ru'][29386] = {title = "Воззвание к героям: гора Хиджал!", objective = "Поговорите с кенарийской посланницей Нефритовой Луной, чтобы попасть на Лунную поляну.", description = "По приказу его королевского высочества короля Вариана Ринна, все годные к военной службе граждане Альянса обязаны явиться к посланнице Песне Ветра на Лунную поляну.\n\nНаши собратья из круга Кенария сообщают о том, что приспешники Смертокрыла намереваются сжечь дотла Древо Жизни!\n\nЧтобы попасть на Лунную поляну, поговорите с кенарийской посланницей Нефритовой Луной в крепости Штормграда.\n\nЗа честь и славу Альянса! В бой, <брат/сестра>!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29387] = {title = "Стражи Хиджала: нападение на Огненные Просторы!", objective = "Доложите о своем прибытии Мате Коготь в Святилище Малорна, что на горе Хиджал.", description = "Стражам Хиджала под предводительством верховного друида Малфуриона Ярости Бури требуется помощь храбрых воинов для полномасштабного нападения на Огненные Просторы.\n\nВсем годным к военной службе гражданам Альянса, которые готовы откликнуться на этот призыв, необходимо незамедлительно явиться в Святилище Малорна, что на горе Хиджал.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][29388] = {title = "Стражи Хиджала: нападение на Огненные Просторы!", objective = "Доложите о своем прибытии Мате Коготь в Святилище Малорна, что на горе Хиджал.", description = "Стражам Хиджала под предводительством верховного друида Малфуриона Ярости Бури требуется помощь храбрых воинов для полномасштабного нападения на Огненные Просторы.\n\nВсем годным к военной службе героям Орды, которые готовы откликнуться на этот призыв, необходимо незамедлительно явиться в Святилище Малорна, что на горе Хиджал.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][29389] = {title = "Стражи Хиджала: нападение на Огненные Просторы!", objective = "Доложите о своем прибытии Мате Коготь в Святилище Малорна, что на горе Хиджал.", description = "Твои усилия дали нам необходимое преимущество в подготовке нападения на Огненные Просторы. Мы собираем силы для нападения на юг от того места, где ты сейчас.\n\nТвоя сила, <раса>, нам совсем не помешает. Поговори с Матой Коготь в Святилище Малорна. Она командует силами вторжения.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][29390] = {title = "Стражи Хиджала: призыв древних защитников!", objective = "Помогите Ло'гошу, Тортолле, Авиане и Эссине на горе Хиджал.", description = "Стражам Хиджала под предводительством верховного друида Малфуриона Ярости Бури требуется помощь храбрых воинов для защиты горы Хиджал от вторжения элементалей. Их нужно отбросить до начала нападения на Огненные Просторы.\n\nВсем годным к военной службе героям, которые готовы откликнуться на этот призыв, необходимо незамедлительно явиться на гору Хиджал и помочь древним защитникам: Ло'гошу, Тортолле, Авиане и Эссине.\n\nНовичкам, которые еще не были на горе Хиджал, следует обратить внимание на доску приказов вождя.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][29391] = {title = "Стражи Хиджала: призыв древних защитников!", objective = "Помогите Голдринну, Тортолле, Авиане и Эссине на горе Хиджал.", description = "Стражам Хиджала под предводительством верховного друида Малфуриона Ярости Бури требуется помощь храбрых воинов для защиты горы Хиджал от вторжения элементалей. Их нужно отбросить до начала нападения на Огненные Просторы.\n\nВсем желающим и годным к военной службе героям необходимо незамедлительно явиться на гору Хиджал и помочь древним защитникам: Голдринну, Тортолле, Авиане и Эссине.\n\nНовичкам, которые еще не были на горе Хиджал, следует обратить внимание на доску объявлений для героев.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][29392] = {title = "Пропавшие фамильные ценности", objective = "Осмотрите каюту на корабле наемного курьера, чтобы понять, что могло его задержать.", description = "Сегодня из Терамора должна прибыть последняя часть принадлежащих мне вещей. Корабль уже причалил, но курьер до меня пока не добрался. А в ящике, который он должен был доставить, были фамильные ценности, которые моя семья передавала из поколения в поколение.\n\nНе сходишь ли ты в порт Штормграда и не узнаешь ли, что задерживает курьера?", progress = nil, completion = "Вряд ли теперь этот курьер сможет встретиться с тем, кто его нанял. Ящик, который он вез, очевидно, исчез.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29396] = {title = "Новый продавец сувениров", objective = "Найдите в лагере Хмельного фестиваля Бликса Чиништукса, отдайте ему купон и получите бесплатную праздничную пивную кружку.", description = "<Дриз вздыхает.>\n\nДаже не напоминай мне о прошлогодних пивных кружках…\n\nУ меня есть ощущение, что наши подозрительные продавцы кружек имели какое-то отношение к сектантам Сумеречного Молота и всему тому, что тут произошло непосредственно перед нашествием элементалей.\n\nПоэтому теперь у нас новый продавец и кружки – лучше прежних!\n\nВот тебе купон на получение одной кружки.\n\nПоговори с Бликсом в лагере Хмельного фестиваля. Он слегка странноват и в последнее время постоянно носит эти свои очки. Отдай ему купон и получишь бесплатную праздничную кружку. Кроме того, у него можно купить и другие праздничные товары.", progress = "Что такое, красавчик? Ты ко мне по делу?", completion = "Что это? Купон на кружку? Любишь выпить? Отлично! Я дам тебе кружку, а ты пойди и выпей за мое здоровье! А потом еще немного выпей... А потом возвращайся сюда.\n\nВсе пути ведут ко мне, знаешь ли. Тебе придется отоваривать праздничные билеты, штампы защитника бочек и так далее.\n\nКороче, вот кружка. Приходи, еще поболтаем.", rewards = "Вы получите:\n\nПереполненная фиолетовая кружка Хмельного фестиваля"}
MultiLanguageQuestData['ru'][29397] = {title = "Новый продавец сувениров", objective = "Найдите в лагере Хмельного фестиваля Белби Быстросмен, отдайте ей купон и получите бесплатную праздничную пивную кружку.", description = "Даже не напоминай мне о прошлогодних пивных кружках, <имя>.\n\nСкажу тебе начистоту, наши предыдущие продавцы кружек оказались подозрительными личностями. Они были связаны с сектантами Сумеречного Молота…\n\nМы не можем иметь дело с теми, кто хочет разрушить наш мир!\n\nПоэтому теперь у нас новые продавцы и кружки нового образца.\n\nОтнеси этот купон Белби Быстросмен в лагерь Хмельного фестиваля. Взамен она даст тебе бесплатную праздничную кружку. Кроме того, у нее можно купить и другие праздничные товары.", progress = "Что такое, красавчик? Ты ко мне по делу?", completion = "Ах-х, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.\n\nЕще увидимся. Ты ведь захочешь отоварить и другие праздничные купоны... Помни, я вся твоя...\n\nИли его... \n\nМожет, его...", rewards = "Вы получите:\n\nПереполненная фиолетовая кружка Хмельного фестиваля"}
MultiLanguageQuestData['ru'][29398] = {title = "Скупка краденного", objective = "Следуйте за пауками и допросите того, кого вы найдете в конце пути.", description = "Вы быстро осматриваете каюту, но не находите ничего, что помогло бы установить личность убийцы или его мотивы. Ящик, за которым вас отправили, исчез.\n\nВы поворачиваете к выходу и уже собираетесь выйти из каюты, как вдруг замечаете под ногами что-то маленькое и движущееся. Из-под койки убитого курьера движется цепочка пауков. Куда же они направляются?", progress = "Что тебе от меня нужно?", completion = "Тише! Не говори ничего об этом деле. Или конец моей карьере аукциониста!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29399] = {title = "Прицениться", objective = "Отправляйтесь в лавку \"Загадка\", расположенную в Квартале Дворфов Штормграда, и найдите подтверждения того, что там побывал вор, укравший ящик.", description = "Я уже говорил тому \"джентльмену\", что в Квартале Дворфов есть лавка, который подойдет ему гораздо лучше. Она называется \"Загадка\", ее можно найти недалеко от каналов, в западной части квартала.\n\nТебе нужен Квинси Катлер. Он торгует такими товарами, к которым честный торговец даже не прикоснется!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29400] = {title = "Время праздника", objective = "Поговорите с зовущей Тьму Янкой в Руинах Лордерона у входа в Подгород.", description = "Как дела, <класс>? Тыквовин – время празднований и размышлений, хотя многие совершенно не в курсе, почему это так. В частности, церемония сжигания Плетеного человека тоже является загадкой почти для всех, кроме Отрекшихся.\n\nОтправляйся в Руины Лордерона, расположенные над Подгородом, и поговори с зовущей Тьму Янкой. Она расскажет тебе о церемонии сжигания Плетеного человека подробнее.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29401] = {title = "Улетевшие шарики", objective = "Джага просит вас найти в Оргриммаре 5 унесенных ветром воздушных шариков.", description = "Пожалуйста, помоги мне!\n\nПапа купил мне воздушные шарики на ярмарке Новолуния. Это был самый лучший подарок в моей жизни! Они волшебные и никогда не сдуваются!\n\nНо только...\n\nПодул сильный ветер, я случайно отпустил шарики, и они улетели! Они разлетелись по всему Оргриммару!\n\nЯ бы пробовал собрать их сам, но этот город такой большой, я точно в нем потеряюсь.\n\nПожалуйста, помоги мне найти шарики, пока они не улетели совсем далеко.\n\nПожалуйста!", progress = "Ты нашел все мои шарики?", completion = "Ты нашел их! Как здорово!\n\nСпасибо!", rewards = "Следующее заклинание будет наложено на вас:\n\nПризыв ребенка с воздушным шаром\n\nВы получите:\n\nВоздушный шар Орды"}
MultiLanguageQuestData['ru'][29402] = {title = "Меры предосторожности", objective = "Соберите 5 хрустальных колб, 5 порций порошка чар и 5 стеблей кровавой крапивы.", description = "Я бы на твоем месте остерегался любого, кто скажет, что он владелец этого ящика и его содержимого. Тебя не предупредили об опасности?\n\nУ меня есть идея получше: давай будем искать ящик вместе, а когда найдем, сделаем так, чтобы его содержимое никому не навредило. А чтобы не пострадать самим, нам понадобится зелье. Ингредиенты для его приготовления можно найти в городе. Купи немного порошка чар у торговца реагентами, несколько хрустальных колб у торговца товарами для алхимиков и собери кровавой крапивы на полях к северу от города.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nВыпить зелье защиты\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][29403] = {title = "Помощник того, кто интересуется ящиком", objective = "Помешайте встрече Саната Лим-Йо и вора, укравшего ящик, в катакомбах под Собором Света.", description = "Если верить Квинси, ящик хочет заполучить не кто иной, как безумный верховный маг Ксилем из Азшары.\n\nВерный слуга Ксилема собирается встретиться с обладателем ящика в катакомбах под Собором Света.\n\nНужно успеть туда вовремя, чтобы помешать им и забрать ящик, пока он не попал к Ксилему и не оказался для нас навеки потерян. Когда завладеешь ящиком, возвращайся ко мне в таверну \"Золотой бочонок\".Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29411] = {title = "И что теперь?", objective = "Верните ящик Ансону Гастингсу в \"Позолоченную розу\" в Штормграде.\n\nИЛИ\n\nВерните ящик Хадсону Барнсу, которого можно найти в \"Золотом бочонке\" в Штормграде.", description = "В конце концов вы нашли ящик, за которым вас послал Ансон. Однако все говорит о том, что предупреждения ученика археолога относительно природы содержимого ящика были основаны не на пустом месте.\n\nНет никаких сомнений, что ваш наниматель солгал вам, когда говорил, что дело совсем неопасное. Правда ли вы хотите отнести этот ящик ему? Может быть, лучше передать его Хадсону Барнсу, который позаботится о том, чтобы содержимое ящика никому не навредило?Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nHaunted Box Turnin\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][29412] = {title = "Улетевшие шарики", objective = "Вин просит вас найти в Штормграде 5 унесенных ветром шариков.", description = "Пожалуйста, помоги мне!\n\nПапа купил мне воздушные шарики на ярмарке Новолуния. Они волшебные и никогда не сдуваются!\n\nНо только...\n\nПодул сильный ветер, я случайно отпустила шарики, и они улетели! Они разлетелись по всему Штормграду!\n\nЯ бы пробовала сама собрать их, но этот город такой большой, я точно в нем потеряюсь.\n\nПожалуйста, помоги мне найти шарики, пока они не улетели совсем далеко.\n\nПожалуйста!", progress = "Ты нашел все мои шарики?", completion = "Ты нашел их! Как здорово!\n\nСпасибо!", rewards = "Следующее заклинание будет наложено на вас:\n\nПризыв ребенка с воздушным шаром\n\nВы получите:\n\nВоздушный шар Альянса"}
MultiLanguageQuestData['ru'][29413] = {title = "Страшный ящик", objective = nil, description = "Этот ящик теряли, находили, крали и продавали. Всякий, кто попытается иметь дело с заключенной в нем магией, непременно почувствует, как эта сила оборачивается против него.\n\nЯщик выглядит неповрежденным и наполненным магической энергией. Время от времени он вздрагивает или подпрыгивает, как будто в нем заключено что-то живое.\n\nОн словно привязан к вам, и вот теперь он ваш.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29415] = {title = "Пропавшие фамильные ценности", objective = "Осмотрите каюту на корабле наемного курьера, чтобы понять, что могло его задержать. Корабль находится в порту, в восточной части Оргриммара.", description = "Я говорил курьеру лететь на дирижабле, но нет же, он предпочел плыть на этом гоблинском корабле! И вот теперь он где-то запропастился вместе с моими фамильными ценностями.\n\nЕсли ты хочешь помочь, не сходишь ли ты в порт в восточной части Оргриммара и не узнаешь ли, что задерживает курьера?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29426] = {title = "Меры предосторожности", objective = "Соберите 5 хрустальных колб, 5 порций порошка чар и 5 стеблей кровавой крапивы.", description = "Так тебя кто-то нанял, чтобы ты <нашел/нашла> ящик? Не нравится мне все это.\n\nСодержимое этого ящика принадлежит Реликварию. Предметы, которые в нем лежат, несут в себе огромную силу и очень опасны.\n\nНам необходимо помешать встрече вора и того, кто планирует забрать ящик. Но сначала нужно позаботиться о своей безопасности.\n\nКупи у торговца реагентами немного порошка чар, у торговца товарами для алхимиков – несколько хрустальных колб и собери кровавую крапиву на Аллее Мудрости.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nВыпить зелье защиты\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][29429] = {title = "Страшный ящик", objective = nil, description = "Этот ящик теряли, находили, крали и продавали. Всякий, кто попытается иметь дело с заключенной в нем магией, непременно почувствует, как эта сила оборачивается против него.\n\nЯщик выглядит неповрежденным и наполненным магической энергией. Время от времени он вздрагивает или подпрыгивает, как будто в нем заключено что-то живое.\n\nОн словно привязан к вам, и вот теперь он ваш.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29430] = {title = "Друг в беде", objective = "Поговорите с Ансоном Гастингсом в таверне \"Позолоченная роза\" в Торговом квартале Штормграда.", description = "Знаешь, я давненько не видела Ансона.\n\nВ последнее время он по большей части напивается в стельку в таверне \"Позолоченная роза\".\n\nНаверное, что-то случилось с ним. Не узнаешь, как у него дела?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29431] = {title = "Друг в беде", objective = "Поговорите с Эдгаром Гудвином в \"Сломанном клыке\" в Оргриммаре.", description = "Что-то не так с моим другом Эдгаром. Обычно он с удовольствием принимает участие во всех праздничных мероприятиях Тыквовина, но в последнее время он ходит угрюмый и замкнутый.\n\nИ почти все время он сидит в \"Сломанном клыке\", напиваясь там с орками. Не заглянешь к нему узнать, что случилось?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29433] = {title = "Испытай свою силу", objective = "Керри Хикс хочет, чтобы вы добыли 250 жутких трофеев. Вы можете получать трофеи, убивая существ, за победу над которыми полагается опыт, если у вас при себе есть справочник ярмарки Новолуния.", description = "Многие толком и драться-то не умеют – все хиханьки да хаханьки, а как кровь увидят – сразу чуть не в обморок падают. Это слабаки.\n\nА чтобы быть сильным – надо не бояться причинять боль. Ты причиняешь боль себе, когда закаляешь свое тело. Ты причиняешь боль другим, если от них исходит угроза.\n\nЕсли хочешь стать <сильным/сильной> – ты <должен/должна> драться. Насколько сильно ты этого хочешь?\n\nСокруши всех, кто осмелится бросить тебе вызов, и возвращайся ко мне с доказательствами своей победы.", progress = "Работай, Нерев!", completion = "Ты искал себе достойных противников? Или просто нашел лесок с кабанами и вырезал их всех до единого?\n\nВидишь ли, есть причина, почему я сильнее всех.\n\nМожет быть, ты когда-нибудь увидишь, насколько я сильна, |3-6(Паладин). А пока что продолжай в том же духе. Однако и отдыхать не забывай.\n\nВот как сейчас, например. Давай, повеселись как следует на ярмарке Новолуния.", rewards = "Вы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29434] = {title = "Командир танка", objective = "Управляя паровым танком, поразите 30 целей за отведенное время.", description = "Испытав наш скромный боевой симулятор, ты окажешь нам огромную честь.\n\nТы сможешь продемонстрировать нам свое тактическое мастерство, потратив всего лишь один купон. Будешь следить за курсом и поражать цели.", progress = "Есть танк - вперед, в путешествие!", completion = "Впечатляющее зрелище… Правда, не настолько впечатляющее, как можно было бы ожидать…\n\nНу что ж, возможно, в следующий раз у тебя получится лучше.\n\nВот твое вознаграждение.", rewards = "Вы получите:\n\nПредмет #1Призовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29436] = {title = "Человек-пушка", objective = "Наберите 5 очков, приземляясь рядом с мишенью для пушки.", description = "По глазам твоим вижу, что ты хочешь взлететь в небеса! Всего один игровой купон Новолуния – залезай в \"Ультрапушку \"Подрывайстер 5000\", и бабах! – ты уже летишь к звездам! Но и это еще не все, <класс>. Мы разместили в воде неподалеку от пристани специальную мишень.\n\nЕсли при приземлении ты наберешь пять очков, то сможешь выиграть призовые купоны.\n\nЗа попадание прямо в яблочко дается пять очков, за приземление просто в черте мишени – 3 очка, ну а если совсем промажешь – 1 очко.\n\nПриятного полета и мягкой посадки!", progress = "Мягкой посадки!", completion = "5 очков? Очень неплохо! Вот твои купоны.\n\nЖелаю тебе хорошенько повеселиться на ярмарке Новолуния!", rewards = "Вы получите:\n\nПредмет #1Призовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29437] = {title = "Падшая стражница", objective = "Сразитесь с Алисрой в Руинах Лар'донира на горе Хиджал и убейте ее.", description = "Фэндрал Олений Шлем содержался в тюрьме здесь, на Хиджале. Алисра из стаи зеленых драконов занималась его охраной.\n\nМы можем сделать только один вывод – она перешла на сторону Сумеречного Молота. Тебе нужно сразиться с ней, <имя>. Если понадобится, убей Алисру. Я не могу ее больше видеть.\n\nВ последний раз ее видели в Руинах Лар'донира, это к западу от Древа Жизни.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29438] = {title = "В яблочко!", objective = "Выбейте 25 очков за 60 секунд.", description = "Считаешь себя хорошим стрелком? Как насчет быстрого состязания?\n\nЯ знаю, как испытать тебя – на это потребуется всего один жетон ярмарки Новолуния.\n\nНу, что скажешь? Насколько ты <меток/меткая>?", progress = "Стрелять по мишеням не так-то просто, как может показаться.", completion = "Я знал, что у тебя получится, |3-6(Воин)! Вот твой приз. Веселись на ярмарке!", rewards = "Следующее заклинание будет наложено на вас:\n\n[DND] Cancel Action Bars on Quest Complete\n\nВы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29439] = {title = "Зов шамана", objective = "Поговорите с Траллом южнее Древа Жизни, что на горе Хиджал.", description = "Служители Земли снова обращаются к тебе, <имя>.\n\nПоскольку твоя фракция – Альянс, ты, вероятно, можешь сомневаться, стоит ли иметь дело с бывшим вождем Орды, тем, кого ты называешь Траллом. Но он попросил именно члена Альянса помогать ему в его следующем предприятии – целительном ритуале, который повлияет на весь наш мир.\n\nОтбрось свои сомнения, <класс>, и откликнись на призыв шамана.\n\nТы найдешь его под ветвями Нордрассила, на горе Хиджал, с южной стороны дерева.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29440] = {title = "Зов шамана", objective = "Поговорите с Траллом южнее Древа Жизни, что на горе Хиджал.", description = "Служители Земли снова обращаются к тебе, <имя>.\n\nТралл больше не вождь Орды, но в своей новой роли он более, чем когда-либо нуждается в поддержке своего народа. Он попросил кого-нибудь из ордынцев помогать ему в его следующем предприятии – целительном ритуале, который повлияет на весь наш мир.\n\nТы найдешь его под ветвями Нордрассила, на горе Хиджал, с южной стороны дерева. Откликнись на его зов!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29441] = {title = "Из чрева чудовища", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][29443] = {title = "Интересный кристалл", objective = "Отнесите зачарованный кристалл профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.", description = "В этом странном кристалле заключена какая-то сила. Возможно, раньше он был сосредоточием магических сил, источником энергии или просто амулетом на счастье. Невозможно узнать наверняка.\n\nСудя по тому, что написано в справочнике ярмарки Новолуния, этим кристаллом может заинтересоваться профессор Таддеус Палео с ярмарки Новолуния.", progress = "Что это у тебя?", completion = "Где ты взял этот кристалл?\n\nКоллекционеры охотятся за такими редкими кристаллами. Я бы хотел изучить этот камень и показать его на ярмарке. Не согласишься ли ты обменять его на купоны ярмарки Новолуния? Я щедро заплачу.", rewards = "Вы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29444] = {title = "Необычное яйцо", objective = "Отнесите громадное яйцо Эббу Ниблгиру на ярмарку Новолуния, проходящую на Острове Новолуния.", description = "Вы точно не знаете, какое существо должно вылупиться из этого яйца, но вне всякого сомнения это будет необычное животное.\n\nВ справочнике ярмарки Новолуния говорится, что отважные искатели приключений нередко находят яйца диковинных животных во время своих странствий. Далее в нем сказано, что сотрудники чудного зоопарка ярмарки Новолуния очень заинтересованы в приобретении подобных видов.\n\nОтнесите яйцо Эббу Ниблгиру на Ярмарку Новолуния.", progress = "Что это у тебя?", completion = "Где ты нашел это яйцо? Очевидно, что внутри него какое-то очень большое и необычное существо! Отличное добавление к нашему зоопарку. Уступишь его за пачку купонов ярмарки Новолуния?", rewards = "Вы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29445] = {title = "Загадочный гримуар", objective = "Отнесите загадочный гримуар Воржею на ярмарку Новолуния, проходящую на Острове Новолуния.", description = "Трудно сказать, кому принадлежала эта массивная книга. Ее страницы испещрены разнообразными заклинаниями и описаниями чар, лишь немногие из которых вам кажутся знакомыми.\n\nВ справочнике ярмарки Новолуния сказано, что подобные книги могут представлять интерес для Воржея, ярмарочного предсказателя.", progress = "Что это у тебя?", completion = "Загадочный гримуар, как интересно! Кажется, я раньше не видел подобных. Я с удовольствием добавил бы его в свою коллекцию. Не откажешься ли ты уступить его за купоны ярмарки Новолуния?", rewards = "Вы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29446] = {title = "Изумительное оружие", objective = "Отнесите богато украшенный клинок профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.", description = "Вы рассматриваете клинок и украшающую его замысловатую инкрустацию, и понимаете, что он создан рукой настоящего мастера. Но это не церемониальный меч. Царапины и еле видные отметины на лезвии свидетельствуют о том, что этим оружием пользовались в бою.\n\nСправочник ярмарки Новолуния, в котором перечислены различные типы редкого и ценного оружия, не оставляет никаких сомнений в том, что профессор Таддеус Палео с интересом взглянул бы на этот клинок.", progress = "Что это у тебя?", completion = "Где ты достал такой прекрасный клинок?\n\nСразу видно, что это работа выдающегося мастера. Оружие, достойное любого героя. Я бы с радостью приобрел его.\n\nСогласишься ли ты уступить мне его за пачку купонов ярмарки Новолуния?", rewards = "Вы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29451] = {title = "Великий стратег", objective = "Отнесите трактат о стратегии профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.", description = "Этот фундаментальный трактат о стратегии принадлежит перу известного генерала Андуина Лотара. По словам самого генерала, научный труд описывает правильную расстановку войск и рассказывает о различных стратегиях, способных гарантировать победу практически в любой битве.\n\nПрофессору Таддеусу Палео с ярмарки Новолуния наверняка будет интересно взглянуть на такую редкую книгу.", progress = "Это совсем не похоже на обычную книгу…", completion = "Не знаю, как это попало к тебе в руки, но не буду и спрашивать. Не согласишься ли ты продать мне эту книгу за купоны ярмарки Новолуния?", rewards = "Вы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29452] = {title = "Твое время пришло", objective = "Поговорите с Зирадорми в Оргриммаре.", description = "<Перед вашим мысленным взором появляется прекрасное видение, внутри себя вы слышите тихий голос.>\n\n<Юный/Юная:c> <класс>, слушай внимательно то, что я скажу тебе.\n\nМне предназначено забрать тебя и отвести к тому, от чьего взора не может укрыться ничто.\n\nЯ жду тебя в Оргриммаре, <смертный/смертная>. Твое время пришло.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29453] = {title = "Твое время пришло", objective = "Поговорите с Корридорми в Штормграде.", description = "<Перед вашим мысленным взором появляется прекрасное видение, внутри себя вы слышите тихий голос.>\n\n<Юный/Юная:c> <класс>, слушай внимательно то, что я скажу тебе.\n\nМне предназначено забрать тебя и отвести к тому, от чьего взора не может укрыться ничто.\n\nЯ жду тебя в Штормграде, <смертный/смертная>. Твое время пришло.", progress = nil, completion = "Давай же начнем, смертная.\n\nУ нас мало времени.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29455] = {title = "Цель: черепаха", objective = "Набросьте 3 кольца на черепаху ярмарки Новолуния.", description = "Эй, ты! Иди-ка сюда!\n\nПочему бы не продемонстрировать всем остальным свои умения? Набрось три кольца на черепаху ярмарки Новолуния и получишь приз.\n\nВсего за один жетон ярмарки Новолуния я дам тебе целую стопку колец и все смогут узнать, почему мы называем тебя \"<класс> – глаз, как у орла\".", progress = "Как успехи?", completion = "Так тебе удалось набросить несколько колец на черепаху. У меня не было никаких сомнений, что тебе это удастся, |3-6(Воин). А теперь верни мне оставшиеся кольца и получи свой приз.\n\nВеселись!", rewards = "Следующее заклинание будет наложено на вас:\n\n[DND] Cancel Action Bars on Quest Complete\n\nВы получите:\n\nПредмет #10Призовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29456] = {title = "Захваченное знамя", objective = "Отнесите знамя павших профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.", description = "На этом изорванном знамени видно поблекшее изображение герба гильдии. Похоже, старое знамя повидало на своем веку множество сражений.\n\nПрофессор Таддеус Палео с ярмарки Новолуния коллекционирует знамена и прочие военные реликвии, так что он может заинтересоваться вашим трофеем.", progress = "Что это у тебя?", completion = "Великолепное знамя! Я бы с радостью присоединил его к своей коллекции.\n\nСогласишься ли ты уступить мне его за несколько купонов ярмарки Новолуния?", rewards = "Вы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29457] = {title = "Вражеский знак различия", objective = "Отнесите захваченный знак различия профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.", description = "Этот поцарапанный знак различия, вероятно, принадлежал вражескому офицеру. Для вас ценность представляет разве что металл, из которого изготовлен знак. Но для какого-нибудь коллекционера этот трофей может оказаться весьма ценным.\n\nПрофессор Таддеус Палео с ярмарки Новолуния на весь Азерот известен своей коллекцией военных трофеев.", progress = "Что это у тебя?", completion = "Это прекрасный образец знака различия офицера Альянса. Многие из них посещают ярмарку Новолуния, но никто не хочет продавать свои знаки различия. Может быть, ты уступишь мне свой за купоны ярмарки Новолуния?", rewards = "Вы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29458] = {title = "Захваченный дневник", objective = "Отнесите дневник профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.", description = "Потрепанная кожаная обложка этой тетради заляпана грязью и залита кровью. Перелистывая страницы, вы понимаете, что в руках у вас личный дневник некого искателя приключений. Автор явно был высокого мнения о собственной персоне и о своих деяниях.\n\nПрофессор Таддеус Палео с ярмарки Новолуния наверняка не отказался бы заглянуть в этот дневник.", progress = "Что это у тебя?", completion = "Потрясающая находка!\n\n&lt;Профессор перелистывает страницы дневника.&gt;\n\nНе все строки легко прочесть, но если хотя бы треть описанного в этом дневнике правда, то это настоящее сокровище. Я готов дать за него целую пачку купонов ярмарки Новолуния. Продашь?", rewards = "Вы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29463] = {title = "Гноллобой", objective = "Наберите 30 очков, колошматя гноллов.", description = "Хочешь хорошенько отдубасить несколько гноллов? Ты <пришел/пришла> в нужное место.\n\nТвоя задача проста – за минуту набрать 30 очков.\n\nВозьми вот этот молоток и приготовься. Когда будешь <готов/готова> – скажи мне.", progress = "Ну что, как все прошло?", completion = "Итак, тебе удалось перебить гноллов – ведь правда же, забавно было?\n\nВот твой приз. Желаю тебе приятно провести время на ярмарке Новолуния!", rewards = "Следующее заклинание будет наложено на вас:\n\n[DND] Cancel Action Bars on Quest Complete\n\nВы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29464] = {title = "Инструменты ворожбы", objective = "Отнесите руны ворожея профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.", description = "Эта коллекция потертых рунических камней немало повидала на своем веку. Камни выглядят старыми, различить, что было выгравировано на их поверхности, невозможно.\n\nВероятно, какой-нибудь коллекционер или ученый сможет рассказать о них больше. Отнесите рунические камни профессору Таддеусу Палео на ярмарку Новолуния.", progress = "Что это у тебя?", completion = "Где ты нашел такие руны? Вот уже много лет я не видел ничего подобного. Предстоит разгадать эту загадку!\n\nНе согласишься ли ты обменять эти руны на купоны ярмарки Новолуния?", rewards = "Вы получите:\n\nПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29470] = {title = "Отскоблить шкуры", objective = "Отскоблите 4 растянутые шкуры на ярмарке Новолуния.", description = "На ярмарке Новолуния всегда повышенный спрос на кожу – нужны палатки, обувь и много всего другого, что тебе даже и в голову не придет! Я поймал несколько животных, убил их и растянул шкуры на земле для дальнейшей обработки.\n\nПохоже, ты умеешь работать с кожей. Если поможешь отскоблить эти шкуры, я тебя награжу.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29475] = {title = "Гоблинское инженерное дело", objective = "Принесите 20 больших железных бомб, 20 шашек твердого динамита и 5 взрывоопасных овец учителю инженерного дела в любой столице.", description = "Опытный инженер может выбрать ОДНУ специализацию, и я могу научить тебя всем премудростям гоблинского инженерного дела.\n\nЯ не сомневаюсь в твоей квалификации, но мне все равно нужно будет взглянуть на сделанные тобой штуковины. Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек твердого динамита и пять взрывоопасных овец – и смотри <сам/сама> не подорвись!\n\nСдай эти предметы учителю инженерного дела в любой из столиц, и тогда будешь официально <признан/признана> гоблином-инженером с правом доступа ко всем чертежам!Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nГоблин-инженер\n\nСледующее заклинание будет наложено на вас:\n\nГоблинское инженерное дело"}
MultiLanguageQuestData['ru'][29477] = {title = "Гномское инженерное дело", objective = "Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени учителю инженерного дела в любой столице.", description = "Опытный инженер может выбрать ОДНУ специализацию, и я могу научить тебя всем тонкостям гномьего инженерного дела.\n\nЯ не сомневаюсь в твоей квалификации, но мне все равно нужно будет взглянуть на примеры изготовленных тобой изделий. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.\n\nСдай эти предметы учителю инженерного дела в любой из столиц, и тогда будешь официально <признан/признана> гномом-инженером с правом доступа ко всем чертежам!Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nГном-инженер\n\nСледующее заклинание будет наложено на вас:\n\nГномское инженерное дело"}
MultiLanguageQuestData['ru'][29481] = {title = "Мастер эликсиров", objective = "Принесите несколько разных настоев учителю алхимии в любой столице.", description = "В эликсире главное – его сила! Если ты хочешь стать настоящим мастером в эликсирах, я могу тебя научить.\n\nТолько знай, что я не учу кого попало, так что прежде чем мы продолжим, мне понадобится подтверждение того, что ты действительно собираешься заниматься этим серьезно. Думаю, нескольких настоев для начала будет достаточно.\n\nИ помни, <имя>: ты можешь изучить только ОДНУ специализацию, так что если ты завершишь свое образование в области эликсиров, ты уже не сможешь изучать зелья и трансмутацию.", progress = "Настои у тебя при себе?", completion = "Превосходно!", rewards = "Вы изучите:\n\nМастер эликсиров\n\nСледующее заклинание будет наложено на вас:\n\nМастер эликсиров"}
MultiLanguageQuestData['ru'][29482] = {title = "Мастер трансмутации", objective = "Принесите необходимые материалы учителю алхимии в любой столице.", description = "Превратить железо в золото, заставить воду стать огнем... Если ты хочешь стать мастером трансмутации, я могу тебе в этом помочь.\n\nНо обучение стоит очень дорого, поэтому я попрошу тебя сначала принести мне немного бесценной субстанции – истинного золота.\n\nИ помни, <имя>: ты можешь изучить только ОДНУ специализацию, так что если ты завершишь свое образование в области трансмутации, ты уже не сможешь изучать эликсиры и зелья.", progress = "Золото у тебя с собой?", completion = "Превосходно!", rewards = "Вы изучите:\n\nМастер трансмутации\n\nСледующее заклинание будет наложено на вас:\n\nМастер трансмутации"}
MultiLanguageQuestData['ru'][29506] = {title = "Коктейль с пузырьками", objective = "Воспользуйтесь шейкером для коктейлей, чтобы смешать ярмарочную шипучку с соком луноягоды и приготовить 5 порций луноягодного лимонада.", description = "Не сомневаюсь, что в бытность свою алхимиком ты <приготовил/приготовила> много разных зелий. А как насчет помочь нам с приготовлением несколько менее серьезных продуктов?\n\nМне всегда хотелось попытаться изобрести новый вид столь популярной у нас шипучки – с фруктовым вкусом. Если ты <готов/готова> помочь, то купи несколько порций обычной шипучки и смешай ее с соком луноягоды.\n\nСок можно купить у любого трактирщика в Элвиннском лесу или в Мулгоре.", progress = "Как обстоят дела с луноягодным лимонадом?", completion = "Вышло неплохо. Если повезет, скоро этот новый лимонад станет популярным!\n\nСпасибо за помощь!", rewards = "Следующее заклинание будет наложено на вас:\n\n[DNT] Quest Complete: A Fizzy Fusion TRACKER\n\nВы получите:\n\nЖетон ярмарки НоволунияПредмет #1Призовой купон ярмарки НоволунияCurrency Token Test Token 5"}
MultiLanguageQuestData['ru'][29507] = {title = "Развлечения для самых маленьких", objective = "Принесите 15 фрагментов окаменелостей профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.", description = "Дети всегда задают множество вопросов о том, что и как делает археолог, так что я приготовил для них игру.\n\nЯ возьму артефакты и окаменелости и закопаю их в песок возле шатра. Дети смогут их раскапывать, делать свои маленькие открытия, они увидят, как кости соединяются друг с другом, и поймут, как через археологию можно многое узнавать об истории.\n\nЕсли у тебя есть какие-нибудь ненужные окаменелости, может, отдашь мне их для осуществления моего замысла?", progress = "Ну что? Есть ли у тебя окаменелости, которыми ты хочешь поделиться?", completion = "Они превосходны! Как раз такие, какие детям особенно понравится находить.", rewards = "Следующее заклинание будет наложено на вас:\n\n[DNT] Quest Complete: Fun for the Little Ones TRACKER\n\nВы получите:\n\nЖетон ярмарки НоволунияПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29508] = {title = "Малышке нужны новые подковы", objective = "Воспользуйтесь железным сырьем, чтобы выковать 4 подковы. Затем используйте подковы, чтобы подковать Малышку на ярмарке Новолуния.", description = "Ты, наверное, уже <видел/видела> мою лошадку, там, возле телег. Ее зовут Малышка. Она тащит фургон, в котором мы перевозим всех животных нашего чудного зоопарка.\n\nОна большая труженица, и <знал/знала> бы ты, как быстро снашиваются ее подковы! Вот и опять пришло время заново подковать ее. Все необходимое я уже купил.\n\nОт тебя требуется только изготовить подковы и подковать Малышку. Много времени это не займет, к тому же, за работу я заплачу тебе купонами. Что скажешь?", progress = "Как дела у Малышки?", completion = "Спасибо тебе за помощь, Игдежехилл! Вот обещанная плата.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПредмет #4Призовой купон ярмарки НоволунияCurrency Token Test Token 5"}
MultiLanguageQuestData['ru'][29509] = {title = "Лягушки с хрустящей корочкой", objective = "Купите простой муки для панировки жирных лягушек и приготовьте 5 хрустящих лягушек, поджарив их в котле позади Стомпа Громового Рога.", description = "Кто в Азероте не слышал о хрустящих лягушках ярмарки Новолуния!\n\nМы как раз получили очередную партию свежих лягушек. Как насчет того, чтобы помочь нам на кухне и заодно попрактиковаться в приготовлении блюд?\n\nМуку для кляра можно купить у торговцев потребительскими товарами в Элвиннском лесу или в Мулгоре.", progress = "Чем это пахнет? Хрустящими лягушечками?", completion = "Приготовлено как полагается, Аркоман. Ты славно поработал.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПредмет #1Предмет #5Призовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29510] = {title = "Утилизация хлама", objective = "Соберите 6 порций пыли Воржея, распылив выброшенное оружие, которое можно найти на территории ярмарки Новолуния.", description = "Люди приходят на ярмарку не только затем, чтобы повеселиться и узнать свое будущее, <имя>. Многие хотят еще и унести что-то с собой на память. Поэтому я помогаю изготавливать магические аксессуары, которые бы наши гости могли приобрести на свои подарочные купоны.\n\nНо для этого нужно, чтобы у меня постоянно был запас пыли Воржея. Посмотри по сторонам – ты увидишь много выброшенного оружия. С твоими-то навыками наложения чар ты легко сможешь распылить эти предметы. Поможешь мне?", progress = "У тебя получилось собрать пыль Воржея?", completion = "Это поддержит мои запасы на нужном уровне. Если тебе еще как-нибудь захочется помочь, просто разыщи старину Воржея во время следующей ярмарки Новолуния.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПредмет #6Призовой купон ярмарки НоволунияCurrency Token Test Token 5"}
MultiLanguageQuestData['ru'][29511] = {title = "Кстати, о танках", objective = "Почините 5 сломанных паровых танков на территории ярмарки Новолуния.", description = "Паровые танки – одно из самых популярных развлечений на ярмарке Новолуния. Посетители ярмарки могут часами участвовать в танковых сражениях, но нередко танки от этого ломаются.\n\nТы, похоже, знаешь, как пользоваться отверткой. Так может быть ты починишь несколько танков? Я заплачу тебе за работу.", progress = "Ты закончил с ремонтом? Посетители не слишком-то бережно с ними обращались. А мне нужно, чтобы танки работали.", completion = "Ты неплохо потрудился, ремонтируя эти танки. Вот, держи обещанную плату.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПредмет #1Призовой купон ярмарки НоволунияCurrency Token Test Token 5"}
MultiLanguageQuestData['ru'][29512] = {title = "Поставить работников на ноги", objective = "Воспользуйтесь бинтами ярмарки Новолуния, чтобы вылечить 4 раненых работников.", description = "Работать на ярмарке Новолуния небезопасно, <имя>. Не секрет, что многие из наших работников получают травмы при установке, разборке или транспортировке всех этих аттракционов.\n\nНекоторые из пострадавших находятся прямо здесь, у фургонов. Остальные – в лечебном шатре неподалеку, там им оказывают первую помощь. Сможешь помочь раненым работникам при помощи этих бинтов?", progress = "Ты позаботился о раненых работниках?", completion = "Спасибо за помощь, Колекционер. Чтобы ярмарка действовала, все мы должны прикладывать усилия.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПредмет #1Призовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29513] = {title = "Морской хот-дог", objective = "Поймайте 5 селедок Великого моря в океане неподалеку от Острова Новолуния.", description = "Мы только что ввели в меню новый пункт – морской хот-дог. Мы едва справляемся со спросом!\n\nТы производишь впечатление <расторопного/расторопной:r> |3-1(<раса>) и к тому же <отличного рыбака/отличной рыбачки>. Не поможешь мне пополнить запасы рыбы?\n\nМы же ведь не хотим лишить посетителей ярмарки возможности полакомиться новым деликатесом?", progress = "Ты принес рыбу?", completion = "Они превосходны! Вот, держи свои купоны, как договаривались.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПризовой купон ярмарки Новолуния"}
MultiLanguageQuestData['ru'][29514] = {title = "Целебные травы", objective = "Соберите 6 темноцветов на территории ярмарки Новолуния.", description = "Небольшие лиловые цветочки, которые в изобилии растут здесь, не просто красивы.\n\nИх можно использовать для самых разных нужд – от лечения ран до приправ к блюдам.\n\nДумаю, ты умеешь собирать травы. Поможешь мне восполнить мои запасы темноцвета?", progress = "Как идет сбор трав?", completion = "Спасибо тебе, Арталег. Если захочешь еще раз помочь нам, заглядывай, когда ярмарка Новолуния будет в городе.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПризовой купон ярмарки НоволунияCurrency Token Test Token 5"}
MultiLanguageQuestData['ru'][29515] = {title = "Предсказание будущего", objective = "Воспользуйтесь пучком экзотических трав, чтобы изготовить пророческие чернила. Затем возьмите чернила и тонкий пергамент, и напишите предсказания для Воржея.", description = "С ростом популярности ярмарки Новолуния у нас все больше и больше посетителей, которые хотят узнать свое будущее.\n\nПо большей части они интересуются такими вещами, которые лучше бы и дальше оставались скрытыми в тумане времени. Но не мне давать им такие советы.\n\nМой запас карточек с предсказаниями подходит к концу. А у тебя, кажется, глаз наметанный. Возьми вот эти травы, сделай из них чернила и напиши для меня несколько предсказаний. Пергамент купишь у любого торговца потребительскими товарами в Элвиннском лесу или в Мулгоре.", progress = "Предсказания написаны?", completion = "Не отличишь от моих. У тебя отличный глаз! Спасибо за помощь, Палиандр.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПредмет #1Призовой купон ярмарки НоволунияCurrency Token Test Token 5"}
MultiLanguageQuestData['ru'][29516] = {title = "Пусть ярмарка сверкает", objective = "Найдите на территории ярмарки Новолуния осколки стекла и изготовьте 5 сверкающих \"самоцветов\".", description = "Актерам и животным ярмарки Новолуния требуется намного больше самоцветов, чем я мог подумать. К счастью, вместо самоцветов используются просто ограненные куски стекла, но кому-то все равно нужно этим заниматься.\n\nРаз ты не новичок в ювелирном деле, может быть, ты поможешь нам изготовить некоторое количество сверкающих стеклянных \"самоцветов\" для актеров?\n\nКрасивые осколки стекла иногда валяются прямо под ногами. Если взяться за дело умеючи, то из них могут получиться прекрасные \"самоцветы\".", progress = "Получилось изготовить стеклянные \"самоцветы\" для костюмов актеров?", completion = "Прекрасная работа, Дыкалыч. Сразу видно, что у тебя талант.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПредмет #5Призовой купон ярмарки НоволунияCurrency Token Test Token 5"}
MultiLanguageQuestData['ru'][29517] = {title = "Изготовление призов", objective = "Воспользуйтесь набором ремесленника ярмарки Новолуния, чтобы изготовить 5 призов Новолуния. Вам понадобится грубая нить, блесны и синяя краска.", description = "Популярность ярмарочных развлечений растет, и это означает, что призы у нас расходятся все быстрее и быстрее!\n\nТак что нам нужны дополнительные призы и поскорее. Если ты умеешь работать с кожей, я могу дать тебе набор ремесленника. Придется докупить кое-что у торговцев потребительскими товарами в Элвиннском лесу или в Мулгоре, но это будут небольшие расходы.\n\nПоможешь?", progress = "Получилось сделать призы?", completion = "Отлично получилось! Не отличишь от остальных. Спасибо тебе за помощь.\n\nЕсли тебе еще когда-нибудь захочется помастерить, загляни ко мне, когда ярмарка Новолуния снова будет в городе.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПредмет #1Призовой купон ярмарки НоволунияCurrency Token Test Token 5"}
MultiLanguageQuestData['ru'][29518] = {title = "Повторное использование и переработка", objective = "Соберите 6 деталей паровых танков на территории ярмарки Новолуния.", description = "Посетители ярмарки обожают паровые танки! А после закрытия ярмарки здесь все будет завалено их деталями.\n\nБыло бы неправильно просто бросить в грязи такой качественный металл.\n\nЕсли ты поможешь мне собрать самые крупные детали, я смогу переплавить их на запчасти для еще действующих паровых танков. Покупать каждый раз новый металл слишком дорого. Что скажешь?", progress = "Ты собрал детали? Здесь же их полно.", completion = "Отличные детали. Спасибо тебе за помощь. Они мне очень пригодятся, когда я примусь за ремонт паровых танков.\n\nВот, возьми это за работу.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПризовой купон ярмарки НоволунияCurrency Token Test Token 5"}
MultiLanguageQuestData['ru'][29519] = {title = "Отскоблить шкуры", objective = "Отскоблите 4 растянутые шкуры на ярмарке Новолуния.", description = "На ярмарке Новолуния всегда повышенный спрос на кожу – нужны палатки, обувь и много всего другого, что тебе даже и в голову не придет! Я поймал несколько животных, убил их и растянул шкуры на земле для дальнейшей обработки.\n\nПохоже, ты умеешь работать с кожей. Если поможешь отскоблить эти шкуры, я тебя награжу.", progress = nil, completion = "Спасибо за помощь, Колекционер. Я никогда не забуду то, что ты сделал для ярмарки Новолуния.\n\nЕсли хочешь, приходи как-нибудь еще, когда ярмарка будет в городе.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПризовой купон ярмарки НоволунияCurrency Token Test Token 5"}
MultiLanguageQuestData['ru'][29520] = {title = "Флаги, флаги повсюду!", objective = "Воспользуйтесь набором для изготовления флага ярмарки Новолуния, чтобы сшить флаг ярмарки. Затем установите флаг, закрепив его в груде камней на территории ярмарки Новолуния.", description = "Разве не чудесно видеть повсюду флаги ярмарки Новолуния? Это моя самая любимая часть приготовлений. Но многие наши флаги уже старые и потрепанные. Нужно их заменить.\n\nЕсли ты умеешь держать в руках иголку с ниткой, то, может быть, сделаешь новый флаг при помощи этого набора, а потом закрепишь его в одной из груд камней на территории ярмарки?\n\nОстальные необходимые тебе вещи можешь приобрести у торговцев потребительскими товарами в Элвиннском лесу или в Мулгоре.", progress = "Удалось найти место для твоего новенького флага?", completion = "Спасибо за помощь с флагами. У тебя определенно талант к портняжному делу. Когда ярмарка Новолуния в следующий раз будет в городе, приходи и помоги нам еще раз.", rewards = "Вы получите:\n\nЖетон ярмарки НоволунияПредмет #1Призовой купон ярмарки НоволунияCurrency Token Test Token 5"}
MultiLanguageQuestData['ru'][29527] = {title = "Взятие укреплений", objective = "Убейте начальника стражи Гарголмара, Вазрудена Глашатая и дракона Вазрудена, Назана. Принесите руку Гарголмара и голову Назана каменному стражу Сток'тону.", description = "Начальник стражи Гарголмар и Вазруден Глашатай отвечают за защиту этих бастионов.\n\nЕсли расправиться с ними, то в рядах их подчиненных наступит полная паника.\n\nУбей их и предоставь мне доказательство того, что можно начинать атаку!", progress = "Эта операция зависит от твоего успеха, Расулхз.", completion = "После смерти военачальников в их рядах должно наступить смятение.\n\nНо убить нескольких стражей – это еще не все, |3-6(Друид).", rewards = "Воинское нефритовое наплечьеБоевые рукавицы верностиСапоги уверенной походкиОплечье магической мощиВы получите:\n\n"}
MultiLanguageQuestData['ru'][29528] = {title = "Взятие укреплений", objective = "Убейте начальника стражи Гарголмара, Вазрудена Глашатая и дракона Вазрудена, Назана. Принесите руку Гарголмара и голову Назана главному разведчику Чадвику.", description = "Защитная система Цитадели Адского Пламени полностью зависит от этих бастионов, которые позволяют заранее узнать о приближении противника.\n\nЕсли уничтожить начальника стражи Гарголмара и Вазрудена Глашатая, то мы с легкостью возьмем бастионы. Убей их!", progress = "Ты справился с задачей, Крайтеен? От успеха этой операции зависит очень многое.", completion = "Я знал, что на тебя можно положиться!\n\nТеперь, когда в рядах врага царит смятение, можно начинать атаку.", rewards = "Воинское нефритовое наплечьеБоевые рукавицы верностиСапоги уверенной походкиОплечье магической мощиВы получите:\n\n"}
MultiLanguageQuestData['ru'][29529] = {title = "Демоны в цитадели", objective = "Убейте Омора Неодолимого и принесите его копыто главному разведчику Чадвику.", description = "Один из наших разведчиков предположительно заметил агента Пылающего Легиона на укреплениях. Если это правда, то Оплоту Чести может грозить серьезная опасность комбинированного нападения!\n\nУбей этого демона прежде, чем он успеет передать сведения о наших действиях тем, кому он подчиняется.", progress = "Ты видел там демонов?", completion = "Так это правда. Орки Скверны и Пылающий Легион объединились.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29530] = {title = "Демоны в цитадели", objective = "Убейте Омора Неодолимого и принесите его копыто каменному стражу Сток'тону.", description = "Один из наших разведчиков вернулся с неприятными известиями. Он заметил могучего агента Пылающего Легиона на укреплениях!\n\nУбей этого демона прежде, чем он успеет передать сведения о наших действиях тем, кому он подчиняется.", progress = "Ты расправился с порождением зла?", completion = "Чудесно! Ты позволил нам выиграть время, чтобы выяснить связь между орками Скверны и Пылающим Легионом. Расправившись с демоном, ты спас сотни жизней.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29531] = {title = "Kill Stuff", objective = "Kill stuff for Questvendor.", description = "I really need you to kill some stuff for me. It's pretty important.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29535] = {title = "Пустить кровь", objective = "Достаньте для Каса'реса 10 фиалов крови орков и жезл вливания Скверны.", description = "Мастер создает все больше и больше орков Скверны, заражая их кровью демонов.\n\nМои руководители полагают, что мы можем обратить этот процесс, но для начала нам нужны образцы орочьей крови и жезл Мастера, чтобы все проверить.", progress = "Ты вернулся! Да еще и цел и невредим! Молодец. Ты справился с заданием намного лучше остальных.", completion = "Возможно, эти фиалы помогут нам покончить с орками Скверны. Надеюсь, ты понимаешь, что от этого во многом зависит успех всей кампании.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29536] = {title = "В сердце ярости", objective = "Детально изучите Кузню Крови и доложите о результатах Каса'ресу.", description = "Мы знаем, что орки Скверны наращивают силы, заражая других орков кровью демонов.\n\nЯ хочу, чтобы ты <проник/проникла> в это темное место и <узнал/узнала>, как они это делают. Рискованно посылать туда армию, пока мы не знаем, что нас ждет.", progress = nil, completion = "&lt;Вы рассказываете Каса'ресу об увиденном в Кузне Крови.&gt;\n\nПонятно.\n\nЕсли они творят подобные вещи с маг'харскими коричневыми орками, то могут добраться и до нас! Нужно сохранять бдительность, иначе весь Траллмар превратиться в сборище безголовых монстров.", rewards = "Отлично изготовленная накидкаВам дадут возможность выбрать одну из следующих наград:\n\nСвятое кольцо исцеленияБагровая подвеска ясности\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29537] = {title = "Найти просвет", objective = "Убейте Кели'дана Разрушителя и вернитесь к Каса'ресу.", description = "\"Несмотря на все усилия, наши шпионы не могут проникнуть в одну область в Кузне Крови.\n\nОни называют ее \"просветом\". Это достаточно большая область, в которой, видимо, и держат Магтеридона.\n\nНайди источник просвета и уничтожь его.", progress = nil, completion = "Преграда устранена, но мы все еще не можем проникнуть в эту область. Мы продолжим искать причину неудачи. Спасибо за помощь!", rewards = "Кираса воздаянияЧешуйчатые поножи разоренияГоловной убор лунного совухаПоножи смертоносного копателяВы получите:\n\n"}
MultiLanguageQuestData['ru'][29538] = {title = "Пустить кровь", objective = "Достаньте для Пушкаренка 10 фиалов крови орков и жезл вливания Скверны.", description = "Мастер использует кровь демонов и специальный жезл, чтобы превращать коричневых и зеленых орков в красных. Мы хотим набрать немного этой крови, немного с ней поработать и затем испытать ее на орках всех цветов. Возможно, так у нас получится превратить их в безобидных и безвольных болванов.\n\nПринеси мне образцы их крови – посмотрим, что у нас получится сделать. Да – и не забудь прихватить жезл!", progress = "Ну что, приятель, собрал кровь? Это очень важно, иначе мы бы тебя не просили ее достать.", completion = "Умопомрачительно! Все, теперь ты мой восьмой лучший друг в этих тлеющих останках жалкой планетенки!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29539] = {title = "В сердце ярости", objective = "Детально изучите Кузню Крови и доложите о результатах Пушкаренку.", description = "Похоже, что болваны, сидящие в Оплоте Чести, вообще не представляют, что здесь происходит. Да это просто горстка никчемных, ленивых магов! По-другому их не назовешь!\n\nВ любом случае, мы и сами не можем понять, что тут творится. Нужно все выяснить!", progress = nil, completion = "&lt;Вы рассказываете Пушкаренку об увиденном в Кузне Крови.&gt;\n\nНадесь, ты принес что-нибудь старине Пушкаренку?\n\nЛадно, ладно. Ты прав. Я тебя должен отблагодарить за нелегкую работу. Я тут кое-что припас для тебя заранее.", rewards = "Отлично изготовленная накидкаВам дадут возможность выбрать одну из следующих наград:\n\nСвятое кольцо исцеленияБагровая подвеска ясности\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29540] = {title = "Разрушитель", objective = "Убейте Кели'дана Разрушителя и вернитесь к Пушкаренку.", description = "Поступают донесения, что они держат там большого страшного демона, за которым следит специальный орк.\n\nОрк есть орк. Значит его нужно убить, <согласен/согласна>? Не важно, натворил он что-то или нет. Орков можно вырезать без разбору!", progress = nil, completion = "Ты что, серьезно? Награду за какого-то несчастного орка? Хочешь славы, денег и благородных скакунов?\n\nА вот в мои годы убийство орка само по себе было наградой!", rewards = "Кираса воздаянияЧешуйчатые поножи разоренияГоловной убор лунного совухаПоножи смертоносного копателяВы получите:\n\n"}
MultiLanguageQuestData['ru'][29541] = {title = "Take Care of It", objective = "Resolve the dispute any way you see fit.", description = "This looks bad... you'd better do something.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][29542] = {title = "Захват крепости", objective = "Поговорите с каменным стражем Сток'тоном в Бастионах Адского Пламени.", description = "С одной стороны Траллмару угрожает Легион, с другой – орки Скверны, и крепость непременно захватят, если мы ничего не предпримем.\n\nОтправляйся на запад, к Бастионам Адского Пламени, и поговори с каменным стражем Сток'тоном. Он координирует секретную операцию по началу наступления Орды на цитадель.", progress = nil, completion = "Если следовать общепринятым канонам красоты, Лободроб не очень-то привлекателен. Но дело свое он знает. Давай-ка найдем тебе работу.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29543] = {title = "Захват крепости", objective = "Поговорите с главным разведчиком Чадвиком в Бастионах Адского Пламени.", description = "С одной стороны Оплоту Чести угрожает Легион, с другой – орки Скверны, и крепость непременно захватят, если мы ничего не предпримем.\n\nОтправляйся на запад, к Бастионам Адского Пламени, и поговори с главным разведчиком Чадвиком. Он координирует секретную операцию по началу наступления Альянса на цитадель.", progress = nil, completion = "Альтума просто молодец, не правда ли? Но никого из нас не было бы в живых, если бы мы не умели сражаться.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29548] = {title = "Задание", objective = "Поговорите с адмиралом Роджерс на борту \"Небесного огня\".", description = "Что ж, ты <слышал/слышала> короля. Последний раз адмирал Тейлор выходил на связь откуда-то из южных морей.\n\nМы начнем наши поиски с воздуха. Обнаружение принца – Белой Пешки – задача первостепенной важности.\n\n\"Небесный огонь\" заправлен топливом, загружен припасами и готов к отбытию. Он парит в северной части гавани.\n\nЗаканчивай приготовления и поговори с адмиралом Роджерс на палубе. Отправляемся без промедления.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29552] = {title = "Критическое состояние", objective = "Помогите 6 раненым пилотам в роще Лап'дон. Для этого можно использовать целительные заклинания или бинты.", description = "Мы вышли победителями из первой битвы, но ситуация остается критической.\n\nВо время первого воздушного боя десятки членов команды \"Небесного огня\" были ранены.\n\nЕсли не оказать им медицинскую помощь, то состояние их будет только ухудшаться вплоть до их кончины. Мы – их единственная надежда на спасение.\n\nОтправляйся в рощу и помоги всем матросам, кому только сможешь.\n\nМы не бросим ни одного из них.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Батрацкий колунБинторез МишкиЩит спасательного отрядаРотор упавшего гирокоптераБольшой меч Кофинны КоттрЩит небесного стражаВы получите:\n\n"}
MultiLanguageQuestData['ru'][29563] = {title = "Пропавшие без вести", objective = "Выясните, что случилось с натуралистом Кусом и культиватором Зеленопалом, после чего возвращайтесь к дозорной Джанг.", description = "Ты <должен/должна> мне помочь! Нас отправили сюда, чтобы мы осмотрели различные части резервуара, но мои друзья до сих пор не вернулись, а времени уже прошло очень много.\n\nМне нужно, чтобы ты <узнал/узнала>, что с ними стряслось. Натуралист Кус и культиватор Зеленопал отправились вон туда.", progress = nil, completion = "Как больно видеть еще одну смерть...\n\n&lt;Дозорная Джанг вздыхает.&gt;\n\nСпасибо тебе, Близарджин. Когда мы все объединимся, у наг не останется ни единого шанса..", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29564] = {title = "Преданный брат", objective = "Убейте Менну Предателя и возвращайтесь к Нахууду.", description = "Моя деревня поначалу кое-как держалась под натиском наг. Наверное, мы все смогли бы пробиться в Награнд, кабы не мой брат. В обмен на свою свободу он продал всех нас.\n\nА теперь он служит здесь надсмотрщиком, и его кнут без устали гуляет по спинам его же братьев. Пусть Менну сполна заплатит за предательство, <раса>.", progress = nil, completion = "Смерть Менну не залечит шрамов от его бича на спинах моих родственников и друзей – но теперь у них хотя бы будет возможность дожить свой век на свободе.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29565] = {title = "Суть дела", objective = "Принесите дозорной Джанг Коготь захватчика и Глаз повелителя рабов.", description = "Нахууд поведал мне, что два могучих создания, Рокмар Трескун и Зыбун, стали одними из первых, кого поработили вторгшиеся наги. Потом они помогли им покорить множество обитателей Зангартопи.\n\nМне больно просить тебя об этом, но их необходимо уничтожить.", progress = "Ты убил их?", completion = "Отрадно, что их души наконец-то освободились – жаль только, что многим из их сородичей пока не суждено обрести покоя.\n\nНам предстоит еще очень многое сделать – особенно здесь, в Кривом Клыке.", rewards = "Темный плащ трясиныНапульсники золотой лозыВам дадут возможность выбрать одну из следующих наград:\n\nКольцо заклинаний Кенария\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29566] = {title = "Наведение справок", objective = "Поговорите с дозорной Джанг в Узилище.", description = "Эти болота так прекрасны, правда? Вот если бы еще эти наги не осушали их...\n\nЯ послал небольшой отряд в Резервуар Кривого Клыка, чтобы они выяснили, чем занимаются наги, но они так и не вернулись. Я опасаюсь, что с ними могла приключиться беда.\n\nТы можешь отправиться в Узилище, что под Змеиным озером, и отыскать дозорную Джанг?", progress = nil, completion = "Что ты здесь делаешь? Ты что, не видишь, что это очень опасное место?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29567] = {title = "Охота на Охотницу", objective = "Принесите Тшу мозг Черной Охотницы.", description = "Споровые великаны, может, и нападают на моих сородичей, но болотоброды отняли больше невинных жизней, чем кто бы то ни было. Это наши древние враги.\n\nИх прародительница, Черная Охотница, обитает в самой глубине топей. Если ты убьешь ее и принесешь мне в качестве доказательства ее мозг, я буду рассказывать о твоей храбрости своим внукам.", progress = "Ты вернулся. Означает ли это, что Черной Охотницы больше нет?", completion = "Черная Охотница мертва! Обычно гибель врагов не доставляет мне такой радости, но за многие столетия она и ее племя причинила столько горя моему народу, что я не могу удержаться от ликования.\n\nПрими мою глубочайшую благодарность, храбрый |3-6(Охотник).", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМогущественный грибГриб Сущности\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29568] = {title = "Необходимое зло", objective = "Убейте Топеглада, после чего возвращайтесь к натуралисту Кусу.", description = "Топеглад и Зыбун в былые времена вместе правили, стали одними из первых, кого поработили вторгшиеся наги. Потом они помогли им покорить множество обитателей Зангартопи.\n\nМне больно просить тебя об этом, но их необходимо уничтожить.", progress = nil, completion = "Сегодня ты оказал услугу всей Зангартопи, Зябкин. Споровые гиганты могут быть агрессивны, но они все равно являются важной частью экосистемы.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29570] = {title = "Спасение экспедиции", objective = "Выясните, что случилось с землепрядом Гневвсом и призывателем ветров Когтем, после чего возвращайтесь к дозорной Джанг.", description = "Последние члены моей экспедиции должны быть где-то поблизости. Без них и собранных ими сведений у нас против наг не будет никаких шансов.\n\nПостарайся отыскать землепряда Гневвса и призывателя ветров Когтя. Я очень надеюсь, что с ними все в порядке.", progress = "Тебе удалось найти хотя бы кого-нибудь из них? С ними все в порядке?", completion = "Скоро мы все снова соберемся вместе, и этим я обязана тебе!\n\nТеперь нагам точно придет конец. Против нас у них не будет ни единого шанса!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29571] = {title = "Защита природы", objective = "Поговорите с дозорной Джанг в Нижетопи.", description = "Служителям Земли часто доводилось сотрудничать с друидами Круга Кенария. Сейчас тоже как раз такой случай.\n\nОтправляйся на север в Нижетопь, отыщи там дозорную Джанг и поговори с ней. Она руководит экспедицией в Резервуар Кривого Клыка, задача которой – остановить наг и спасти Зангартопь.", progress = nil, completion = "Нижетопь вот-вот станет очередной частью насосной системы наг в Кривом Клыке! Ты должен нам помочь!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29573] = {title = "Прежде всего – безопасность!", objective = "Убейте 10 эфириалов – осквернителей гробниц, 5 эфириалов-колдунов, 5 ловчих нексуса и 5 эфириалов-чароплетов, а затем вернитесь к работнику Морфалиусу.", description = "Теперь почти ничего не мешает нашей команде проникнуть внутрь и взять то, что и так принадлежит нам по праву. Теперь главную опасность представляет личная охрана Шаффара.\n\nМне нужно восстановить силы. А ты пока займись его войсками.", progress = nil, completion = "Великолепно! Харамад будет счастлив услышать хорошие новости! Теперь все это принадлежит ему!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29574] = {title = "Интригующие образцы", objective = "Принесите сущность Пандемония и сердце Таварока Мамди по кличке \"Олог\".", description = "В этих залах, не очень далеко отсюда, обитает существо по имени Пандемоний, которое черпает силы из энергии Бездны.\n\nА немного дальше находится Таварок, существо, которое ту же самую энергию Бездны превращает в кристаллическую структуру, крепче которой я еще никогда не видел!\n\nМне непременно нужно получить образцы для изучения.", progress = "Если у тебя нет того, что мне нужно, то не отнимай у меня времени.", completion = "Потрясающие образцы! Они прекрасно подойдут.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29575] = {title = "Жестокая вещь – конкуренция", objective = "Принесите обмотки Шаффара работнику Морфалиусу.", description = "Установив оберег и собрав свое войско, принц Шаффар сумел обчистить это место вообще безо всяких проблем.\n\nНеудивительно, что принц Харамад остался очень недоволен этим и назначил за голову Шаффара неплохую награду.", progress = "Ты хотел получить награду за голову Шаффара?", completion = "Я, честно говоря, не думал, что дворф сумеет одолеть принца. Ты удивил меня. Вот твоя награда – полностью заслуженная.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29576] = {title = "Запах тревоги", objective = "Поговорите с Дерзким Шао в Саду Сладкого Ветерка.Пусть я уже плохо вижу, но каждый раз при удачной погоде я ощущаю благоухание Сада Сладкого Ветерка так, словно он находится в двух шагах отсюда.\n\nСегодня же ветер принес иной запах – запах гари. Если можешь, сходи туда и проверь, все ли там в порядке. Может, это просто старческий нюх меня подводит.\n\nСад расположен к юго-западу отсюда, за статуей Нефритовой Змеи.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Пусть я уже плохо вижу, но каждый раз при удачной погоде я ощущаю благоухание Сада Сладкого Ветерка так, словно он находится в двух шагах отсюда.\n\nСегодня же ветер принес иной запах – запах гари. Если можешь, сходи туда и проверь, все ли там в порядке. Может, это просто старческий нюх меня подводит.\n\nСад расположен к юго-западу отсюда, за статуей Нефритовой Змеи.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29578] = {title = "Противление злу", objective = "Убейте 8 гормальских налетчиков и 8 гормальских поджигателей в Саду Сладкого Ветерка.", description = "Чертовы могу нападают на нас из ниоткуда! Тех, кого не убили на месте, они тащат в лес.\n\nЭто наше последнее убежище, и все, что я могу сделать, это запереться внутри.\n\nЧто скажешь? Желаешь постоять за слабых?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29579] = {title = "Сбор выживших", objective = "Поговорите с 5 фермерами около Сада Сладкого Ветерка и отправьте их в тайное убежище.", description = "В этой деревне живут не воины, как мы с тобой, а простые крестьяне. Но все же они делают все, чтобы защитить свои дома.\n\nОбойди деревню, найди всех, кто еще может стоять на ногах, и скажи им, чтобы собирались здесь, в доме Ханьай.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nOrchard Survivor Turn-in\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][29580] = {title = "Садовые инструменты", objective = "Соберите 6 садовых инструментов в Саду Сладкого Ветерка.", description = "И пусть они не мастера боя, но со своими инструментами, будь то простая мотыга или грабли, они сроднились.\n\nЕсли к этому мы добавим еще и правильную мотивацию, то получим войско, способное отразить все атаки могу.\n\nЕсли ты принесешь из сада несколько инструментов, я раздам их любому, кто захочет сражаться.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29582] = {title = "Безумная ночь Грека", objective = "Поговорите с работником Морфалиусом в гробницах Маны в Аукиндоне.", description = "Грек плохо спал прошлой ночью.\n\nВ дом Грека пришла светящаяся мумия и сказала ему, что он должен отправиться в Аукиндон, в гробницы Маны. Но Грек по-прежнему пытается узнать, что написано в этом объявлении!\n\n<Лицо Грека озаряется.>\n\nГрек придумал! Ты пойдешь и найдешь светящуюся мумию и скажешь ей, что ты вместо Грека. Прекрасный план!", progress = nil, completion = "Этот остолоп прислал тебя?\n\n&lt;Работник Морфалиус изучающе смотрит на вас.&gt;\n\nПолагаю, тебе придется сделать это.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29583] = {title = "Сумасшедший Акерт", objective = "Поговорите с работником Морфалиусом в гробницах Маны в Аукиндоне.", description = "Я опытный инженер, гениальный изобретатель, душа любой компании и самый лучший танцор Азерота.\n\nНо разве они меня так называют? Нет.\n\nА стоит только один единственный раз подраться с эфириалом, и тебе на каждом углу начинают кричать: \"Сумасшедший\".\n\nЯ видел одного из них здесь вчера, клянусь! Он сказал, что если я пойду за ним в Аукиндон к гробницам Маны, то там меня будут ждать сокровища и древние знания!", progress = nil, completion = "Вообще-то я надеялся увидеть того гнома.\n\n&lt;Работник Морфалиус оглядывает вас.&gt;\n\nВпрочем, ты тоже сгодишься.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29585] = {title = "Плюнь-тушение", objective = "Потушите сидром Сладкого Ветерка 12 костров в Саду Сладкого Ветерка.", description = "В течение многих поколений наши предки ухаживали за этими садами, собирали нектар и делали из него сидр. За это время мы научились в случае необходимости быстро тушить пожары.\n\n<Ханьай дает вам кувшин сидра.>\n\nЕсли сидр смешать с раздавленным имбирным листом и слюной, он быстро становится вязким и липким. Идеальное средство для \"удушения\" пламени.\n\nПожалуйста, постарайся усмирить огонь. Я уже смешала сидр с имбирным листом, так что тебе остается лишь набрать его в рот и выплюнуть.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Бамбуковые перчаткиПерчатки из листьев бамбукаБоевые рукавицы нефритовой ведьмыПерчатки из коры бамбукаБоевые рукавицы из коры бамбукаБамбуковые латные перчаткиБоевые рукавицы Лисьей рощиРукавицы из листьев бамбукаРукавицы из бамбукаСледующее заклинание будет наложено на вас:\n\nUpdate Zone Auras\n\nВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][29590] = {title = "Страж Мертвых", objective = "Убейте Ширрака Стража Мертвых, затем возвращайтесь к духу дренея.", description = "Ужасное создание, которое мы зовем Ширрак, сеет ужас как в материальном мире, так и в мире духов.\n\nТолько в твоем мире ему можно причинить вред. Пожалуйста, помоги нам избавиться от этого кошмара.", progress = nil, completion = "Быть может, теперь мы, наконец, сумеем обрести покой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29591] = {title = "Разъяренные духи", objective = "Убейте 5 разгневанных скелетов, 5 разъяренных скелетов и 3 аукенайских некроманта, после чего возвращайтесь к истязаемому жрецу душ в Аукенайские гробницы.", description = "Аукенайцы предали все наши идеалы. Они начали воскрешать мертвых и использовать их в качестве своих неживых слуг!\n\nМы не можем допустить, чтобы это продолжалось. Упокой духов и перебей всех тех, кто призвал их к нежизни.", progress = nil, completion = "Мертвым место в мире духов – точно так же, как тебе должно пребывать в этом мире.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29593] = {title = "Удар по уязвимой точке", objective = "Украдите 3 связки припасов Адского Пламени, а затем вернитесь к каменному стражу Сток'тону в Бастионы Адского Пламени.", description = "Орки Скверны устроили тут большой склад припасов.\n\nЕсли их украсть, то это нанесет серьезный удар по их планам и значительно поднимет наш боевой дух. Возьмешься за это поручение, <класс>?", progress = "Сколько связок тебе удалось украсть?", completion = "Славная работа! Это гораздо эффективнее, чем перебить парочку орков. Они еще долго будут чувствовать последствия кражи.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29594] = {title = "Удар по уязвимой точке", objective = "Украдите 3 связки припасов Адского Пламени, а затем вернитесь к главному разведчику Чадвику в Бастионы Адского Пламени.", description = "Орки Скверны устроили тут большой склад припасов.\n\nЕсли их украсть, то это нанесет серьезный удар по их планам и значительно поднимет наш боевой дух. Возьмешься за это поручение, <класс>?", progress = "Сколько связок тебе удалось украсть?", completion = "Славная работа! Это гораздо эффективнее, чем перебить парочку орков. Они еще долго будут чувствовать последствия кражи.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29595] = {title = "Все будет в порядке", objective = "Проникните в Аукенайские гробницы и поговорите с духом дренея по просьбе Великого Отца Алдримуса, который находится снаружи Аукенайских гробниц Аукиндона.", description = "Чувствую, тебе хватило приключений еще до того, как ты <вошел/вошла> в Аукенайские гробницы, <имя>.\n\nЯ могу назвать себя счастливым духом, – я никогда не попадался ни Левиксусу, ни экзарху Маладаару, и на мне не ставили эти ужасные некромантические эксперименты. Левиксиуса тебе удалось уничтожить, но Маладаар жив и продолжает терзать пленных духов.\n\nЯ прошу только об одном. Проберись в Аукенайские гробницы и поговори там с духом дренея. Ты <должен/должна> уничтожить экзарха Маладаара.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29596] = {title = "Конец экзарху", objective = "Убейте экзарха Маладаара и вернитесь к духу дренея в Аукенайские гробницы.", description = "Экзарх Маладаар занимается своими нечистыми делами в самой дальней части гробниц. Он представляет собой угрозу для обоих наших миров. Его нужно остановить.\n\nТы <должен/должна> убить его во имя всех нас, живых и мертвых.", progress = nil, completion = "Ты оказал нашему миру огромную услугу. Мы всегда будем помнить об этом.", rewards = "Защитник наместникаХауберк аукенайского следопытаМундир аукенайского монахаОдеяние аукенайского отшельникаВы получите:\n\n"}
MultiLanguageQuestData['ru'][29598] = {title = "План Тареты", objective = "Проберитесь в крепость Дарнхольд и заложите пять зажигательных бомб возле бочек внутри каждого из бараков на выселках. Используйте упаковку зажигательных бомб, полученных от Эрозиона.\n\nПосле того как подожжете бараки, разыщите Тралла в подземной темнице.", description = "Именно Тарета придумала первоначальный план, как помочь Траллу бежать из Дарнхольда.\n\nНо драконы Бесконечности захватили ее в плен. Без нашей помощи Траллу вряд ли удастся сбежать. Я дам тебе зажигательные бомбы – тебе нужно будет с их помощью поджечь бараки.", progress = "Ты кто?", completion = "Вы с Таретой друзья? Это, значит, ее новый план? Ну хорошо...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29599] = {title = "Побег из Дарнхольда", objective = "Когда вы будете готовы идти, сообщите об этом Траллу. Помогите ему бежать из крепости Дарнхольд, освободить Тарету и исполнить свое предназначение.\n\nПосле этого возвращайтесь к Эрозиону в Старый Хилсбрад.", description = "Я знаю, что нужно моему народу, <чужак/незнакомка>\n\nВ один прекрасный день он сбросит своих притеснителей и встанет с колен. Мы порвем свои цепи и выкуем новую Орду, закалив ее в пламени мятежа.\n\nКак только будешь <готов/готова> идти, дай мне знать.", progress = nil, completion = "Ты сделал великое дело, Близарджин. Однако память юного вождя об этих событиях должна оставаться такой же, как была прежде...", rewards = "Мантия вождяКасание буриТихие сапоги ЮжнобережьяКушак защитница Мельницы ТарренВы получите:\n\n"}
MultiLanguageQuestData['ru'][29600] = {title = "Решительные меры", objective = "Уничтожьте 16 шипастых крепкохватов в Пруду Чистоты.", description = "Эти водоемы – особенные: ни одна другая река или озеро не поит водой столько живности во всей Пандарии.\n\nК сожалению, они привлекают к себе не только безобидных животных. Недавно выяснилось, что в верхнем водоеме стали гнездиться драконьи черепахи. Они там просто беспредельничают, честное слово – топчут лотосы и пугают моих работников.\n\nОтдельные особи, конечно, не представляют никакой опасности, но с целой стаей таких лучше не встречаться, поверь мне. Пожалуйста, не откажи в просьбе – уж очень нужна твоя помощь в очистке водоемов.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Атласные манжеты шелкоделовПронизанные солнцем наручникиЧешуйчатые поручи ХуаньцзыВороненые наручи ПаоцюаньШелковые манжеты Золоченого ВеераНаручные обмотки из перьев равнинного ястребаНарукавники диких равнинТяжелые наручи Громовой ПятыБронированные наручи Солнечной ПесниВы получите:\n\n"}
MultiLanguageQuestData['ru'][29605] = {title = "Брат на брата", objective = "Освободите из плена Лакку. После этого вернитесь к Исфару, который находится в Сетеккских залах.", description = "Когда Аукиндон взорвался, племя Сетекк покинуло Скеттис.\n\nМой брат Сит был одним из лидеров племени Сетекк, и именно ему принадлежала идея, что мы должны выйти к руинам храма и встретить нашего бога.\n\nЧерез некоторое время Сит изгнал меня из племени и запретил забрать с собой нашу сестру Лакку. Ты поможешь мне спасти ее?", progress = nil, completion = "Теперь, когда Лакка свободна, оборвались последние нити, связывающие меня с племенем Сетекк.\n\nЯ никогда не прощу себе смерти Сита, но это нужно было сделать. По возвращении в Скеттис я сам исполню по нему похоронные ритуалы.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТорк сетеккского пророкаСредоточие оракула СетеккаБусы Лорда КогтяЗнак ворона-стража\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29606] = {title = "Наследство Терокка", objective = "Принесите маску Терокка, перо Терокка и \"Сказание о Терокке\" Исфару, который находится в Сетеккских залах.", description = "Мой народ свято чтит древнего героя по имени Терокк.\n\nВ один прекрасный день он бесследно исчез, оставив после себя лишь маску, копье и некоторые записи.\n\nАраккоа почитают эти реликвии, но племя Сетекк, уходя из Скеттиса, похитило их и унесло с собой.", progress = "Реликвии, принадлежащие Терокку, слишком давно покинули Скеттис. Удалось ли тебе вырвать их из лап племени Сетекк?", completion = "Я принял участие в злодеяниях племени Сетекк, и за это нет мне прощения. Может быть, возвращение реликвий Терокка хоть немного оправдает меня в глазах моего народа.", rewards = "Перо ТероккаМаска ТероккаВам дадут возможность выбрать одну из следующих наград:\n\nСказание о Терокке\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29607] = {title = "Глаза желания", objective = "Делец Вийяд из Сетеккских залов хочет, чтобы вы принесли ему 3 кобальтовых глаза.", description = "Я знаю одного покупателя, который очень заинтересован в приобретении глаз кобальтовых змеев, что обитают здесь.\n\nЕсли бы ты <принес/принесла> мне несколько этих редких самоцветов, я бы поделился с тобой прибылью.\n\nИдет?", progress = "Ты принес глаза?", completion = "То что надо. Молодец!\n\nВот твоя доля, как и обещал.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29608] = {title = "Союзники в Даларане", objective = "Прилетите на грифоне в Даларан и поговорите с Изирами Попутный Ветер в таверне \"Благодарность за отвагу\".", description = "Добро пожаловать в Нордскол, <имя>. Меня попросили обеспечить тебя транспортом до Даларана, чтобы ты <встретился/встретилась> там с нашими союзниками.\n\nЛети в Даларан на грифоне, и, как прибудешь туда, сразу ступай в нашу таверну, \"Благодарность за отвагу\". Там разыщи Изирами Попутный Ветер и поговори с ней.\n\nОна поможет тебе привязать твой камень возвращения к городу, чтобы ты <мог/могла> быстро возвращаться в Штормград через портал Серебряного Анклава.", progress = nil, completion = "Добро пожаловать в Даларан! Эта таверна – часть Серебряного Анклава, штаб-квартиры представительства Альянса в нашем городе.\n\nНе забудь привязать здесь свой камень возвращения, чтобы быстро возвращаться в город и получить доступ к находящемуся поблизости порталу Штормграда.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29609] = {title = "Друзья в Даларане", objective = "Летите в Даларан и поговорите с Удой Зверюгой в трактире \"Грязное животное\".", description = "Добро пожаловать в Нордскол. Меня попросили обеспечить тебя транспортом до Даларана, чтобы ты <встретился/встретилась> там с нашими друзьями.\n\nПоговори со мной, чтобы лететь в Даларан. Как прибудешь туда, отправляйся в кабак \"Грязное животное\". Там разыщи Уду Зверюгу и поговори с ней.\n\nОна поможет тебе привязать твой камень возвращения к городу, чтобы ты <мог/могла> быстро возвращаться в Оргриммар через портал в Прибежище Похитителя Солнца.", progress = nil, completion = "Я ждала тебя! Эта таверна – часть Прибежища Похитителя Солнца, анклава Орды в Даларане.\n\nНе забудь привязать здесь свой камень возвращения, чтобы быстро возвращаться в город и получить доступ к порталу Оргриммара, который находится у фонтана.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29611] = {title = "Искусство войны", objective = "Поговорите с генералом Назгримом в крепости Громмаш.", description = "Лок'тар огар, <раса>. Я – Назгрим.\n\nПо приказу вождя Адского Крика тебе надлежит немедленно явиться в крепость Громмаш.\n\nПо его распоряжению каждый ордынец должен принести клятву верности новому вождю.\n\nНе заставляй его ждать, <раса>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29612] = {title = "Искусство войны", objective = "Поговорите с генералом Назгримом в крепости Громмаш в Оргриммаре.", description = "Лок'тар огар, дружище. Как же давно мы не виделись!\n\nЯ рад, что ты <вернулся/вернулась> из глубин Вайш'ира <живым/живой> и <невредимым/невредимой>.\n\nВождь Адский Крик направил меня сюда, в крепость Громмаш.\n\nПо его приказу каждый ордынец обязан принести клятву верности новому вождю.\n\nНе заставляй его ждать, <имя>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29613] = {title = "Бесславный конец", objective = "Убейте полководца Калитреша и возвращайтесь к дозорной Джанг в Паровое подземелье.", description = "Полководец Калитреш руководит всей операцией в Паровом подземелье.\n\nЯ хочу, чтобы ты <убил/убила> его, <имя>. Наги не оставили нам иного выбора, кроме насилия.\n\nПусть твоя рука не дрогнет.", progress = nil, completion = "Мне жаль, что до этого дошло, но наги не дали нам ни одного шанса решить дело миром.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29614] = {title = "Сдерживание заразы", objective = "Убейте 3 властителя болот, 6 лепрогномов из резервуара Кривого Клыка, а также достаньте облученный механизм Анжинера Паропуска, после чего возвращайтесь к натуралисту Кусу в Паровое подземелье.", description = "Наги снюхались с лепрогномами – вместе они пытаются распространить по всей Зангартопи ужасную болезнь. Зараза уже охватила почти все Паровое подземелье.\n\nУничтожь все, что заражено, и принеси мне центральный механизм Анжинера Паропуска. Поспеши!", progress = "Постарайся сделать все как можно тщательнее. От этого зависит судьба всей Зангартопи.", completion = "Я рад, что нам удалось остановить эту заразу, пока она не успела расползтись по всей Зангартопи. Спасибо.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29615] = {title = "Призыватель ветра Коготь и водокрад", objective = "Убейте гидроманта Теспию и возвращайтесь к призывателю ветра Когтю в Паровое подземелье.", description = "Основные усилия по осушению Зангартопи наги сосредоточили в Паровом подземелье. За ходом операции наблюдает лично гидромант Теспия.\n\nЕсли убрать ее, операции наг будет нанесен серьезный удар.", progress = nil, completion = "Может быть, теперь нам удастся обеспечить исстрадавшуюся землю столь необходимой ей водой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29616] = {title = "Штурм Парового подземелья", objective = "Поговорите с дозорной Джанг в Паровом подземелье.", description = "Пока что нам так и не удалось остановить наг в Паровом подземелье, где находится основная часть их насосной системы.\n\nНо отправленная туда экспедиция уже приступила к работе, так что будем надеяться, что вскоре ситуация переменится. Может, отправишься в Паровое подземелье, отыщешь там дозорную Джанг и предложишь ей и ее людям свою помощь?", progress = nil, completion = "Хвала звездам, ты здесь! Нам нужна твоя помощь!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29617] = {title = "Монастырь Тянь", objective = "Поговорите с Линь Мягкой Лапой, которая находится в монастыре Тянь в Нефритовом лесу.Со всех концов Пандарии жители стекаются сюда, чтобы пройти тренировку в монастыре Тянь – он находится чуть к северу отсюда. Возможно, это потому, что монахи принимают всех – цзинь-юй, хозенов... Даже <раса> вроде тебя найдет там приют!\n\nМоя подруга детства Линь стала послушницей несколько недель назад. Если хочешь узнать, чему учат в монастыре, поговори с ней!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Со всех концов Пандарии жители стекаются сюда, чтобы пройти тренировку в монастыре Тянь – он находится чуть к северу отсюда. Возможно, это потому, что монахи принимают всех – цзинь-юй, хозенов... Даже <раса> вроде тебя найдет там приют!\n\nМоя подруга детства Линь стала послушницей несколько недель назад. Если хочешь узнать, чему учат в монастыре, поговори с ней!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29618] = {title = "Верховный старейшина", objective = "Поговорите с верховным старейшиной Дождевой Тучей в монастыре Тянь в Нефритовом лесу.Как странно, в нашем монастыре –<класс>. Ты хочешь учиться?\n\nПохоже, сил тебе не занимать... так что можешь не беспокоиться – тебя непременно примут. Поговори с Верховным старейшиной – он на балконе.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Как странно, в нашем монастыре –<класс>. Ты хочешь учиться?\n\nПохоже, сил тебе не занимать... так что можешь не беспокоиться – тебя непременно примут. Поговори с Верховным старейшиной – он на балконе.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29640] = {title = "Найти шпиона То'гуна!", objective = "Найдите шпиона То'гуна в Темном лабиринте в Аукиндоне.", description = "Члены Совета Теней уже убили большинство наших шпионов. То'гуну удалось сбежать, но он оказался настолько беспечен, что после этого снова вернулся к своей деятельности. \n\nТы <должен/должна> найти его. Возможно он и глуп, но нам нужна информация, которую он раздобыл.", progress = nil, completion = "Поможешь мне выбраться из этой клетки? А то тут тесновато!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29641] = {title = "Инструменты души", objective = "Украдите 5 инструментов душ и принесите их шпиону Грик'те в Темный лабиринт Аукиндона.", description = "Ох! Они пытали меня, хотели вытянуть из меня все, что я знаю...\n\nЯ потерпел неудачу – они скормили всех наших Гиблочреву, и я должен был быть следующим... Но я ничего, ничего им не выдал!\n\nОни увеличивают мощность вызова при помощи специальных предметов. Эти устройства нужно украсть!", progress = "Тебе удалось отыскать То'гуна?", completion = "Это и есть инструменты душ, которые Совет Теней использует для усиления силы призыва? Интересно...", rewards = "Боевые наручи Ша'тарАукенайские наручиНарукавники хозяйки шпионовШаттратские напульсникиВы получите:\n\n"}
MultiLanguageQuestData['ru'][29642] = {title = "В Аукиндоне неспокойно", objective = "Отправляйтесь к боевому командиру Мафууну в Темный Лабиринт Аукиндона в Лесу Террокар.", description = "Мои шпионы шлют очень тревожные донесения из Аукиндона. Со времени взрыва это место не доставляло нам ничего, кроме проблем.\n\nИ опять там происходит что-то ужасное. Похоже, Совет Теней вознамерился развязать войну. Хотя донесения недостаточно подробные, понятно, что приготовления идут вовсю.\n\nТебе придется пробраться в Темный лабиринт. Полевой командир Мафуун скажет тебе, что делать.", progress = nil, completion = "Ты появился очень вовремя.\n\nМы уже довольно долго здесь сражаемся, и еще несколько дней назад Мелиса обещала прислать подкрепление.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29643] = {title = "Кодекс Крови", objective = "Прочитайте Кодекс Крови в Темном лабиринте в Аукиндоне.", description = "Два года назад совет призвал существо, которое разрушило Аукиндон до основания.\n\nПрочитайте Кодекс Крови, чтобы узнать эту историю. Но будьте осторожны: Великий мастер Ворпил будет защищать его не щадя собственной жизни.", progress = nil, completion = "Вы открываете фолиант, и вас внезапно охватывает ужас.\n\nЧто-то здесь определенно не так!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29644] = {title = "В самом сердце Лабиринта", objective = "Уничтожьте Бормотуна и доложите об этом боевому командиру Мафууну в Темном лабиринте в Аукиндоне.", description = "Совет Теней потерял контроль над неким космическим существом, которое он призвал два года назад.\n\nТеперь это создание, известное как Бормотун, пытается уничтожить Совет Теней и вырваться во внешний мир", progress = nil, completion = "Я содрогаюсь от одной мысли о том, что могло случиться, если бы Бормотун вырвался во внешний мир.\n\nСпасибо тебе, храбрый герой.", rewards = "Скованные Ша'тар наголенникиАукенайские сапогиСапоги хозяйки шпионовШаттратские прыгуныВы получите:\n\n"}
MultiLanguageQuestData['ru'][29645] = {title = "Посол Гиблочрев", objective = "Убейте 12 кабалистов-ритуалистов и посла Гиблочрева, а затем вернитесь к боевому командиру Мафууну, его можно найти около Темного Лабиринта Аукиндона.", description = "Когда кабалисты поймали наших шпионов, они скормили их живьем послу Гиблочреву.\n\nМы должны отомстить за наших людей. Перебей ритуалистов, что удерживают Гиблочрева, а после прикончи его самого.\n\nДругой участи он не заслужил.", progress = nil, completion = "Это не вернет погибших, но, по крайней мере, мы свершили правосудие.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29649] = {title = "Спасение жизни", objective = "Передовой разведчик Чадвик, находящийся в Разрушенных Залах, что в Цитадели Адского Пламени, хочет, чтобы вы принесли ему уголь Скверны.", description = "Пушкаренка убивает могучее проклятие, <имя>.\n\nСилу главного чернокнижника Пустоклята увеличивают две таинственных жаровни. Быть может, если ты принесешь мне уголек из такой жаровни, мы сможем как-то противодействовать темной магии?", progress = "Ты принес угли? У нас мало времени!", completion = "Он был славным солдатом.", rewards = "Неустрашимые боевые рукавицыПояс с выгравированными рунамиЭполеты экспедиционного разведчикаПерчатки возвращенияСапоги викарияВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][29650] = {title = "Уголь Скверны", objective = "Каменный страж Сток'тон, находящийся в Разрушенных Залах, что в Цитадели Адского Пламени, хочет, чтобы вы принесли ему уголь Скверны.", description = "Каса'рес умирает, как трус.\n\nГлавный чернокнижник Пустоклят наложил на него могучее проклятье. Быть может, если ты принесешь мне уголек из его жаровни, мы сможем как-то противодействовать темной магии, пока еще не слишком поздно?", progress = "Ты принес угли? Каса'рес заслужил смерть, достойную воина.", completion = "Я спою множество песен о его славе.", rewards = "Неустрашимые боевые рукавицыПояс с выгравированными рунамиЭполеты экспедиционного разведчикаПерчатки возвращенияСапоги викарияВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][29651] = {title = "Почтить память погибших", objective = "Убейте 4 легионеров клана Изувеченной Длани, 2 центурионов клана Изувеченной Длани и 2 воителей клана Изувеченной Длани по просьбе Каса'реса, находящегося в Разрушенных залах Цитадели Адского Пламени.", description = "Их элитные воины беспощадны... и очень сильны.\n\n*Каса'рес сплевывает кровь.*\n\nТебе нужно будет убить их... иначе нам не победить Каргата...", progress = nil, completion = "Каса'реса... больше нет.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29652] = {title = "Последняя услуга", objective = "Убейте 4 легионеров клана Изувеченной Длани, 2 центурионов клана Изувеченной Длани и 2 воителей клана Изувеченной Длани по просьбе Пушкаренка, находящегося в Разрушенных залах Цитадели Адского Пламени.", description = "Старина Пушкаренок долго не протянет...\n\nОкажи мне услугу, убей напоследок самых крупных и подлых орков Скверны, что тебе попадутся.\n\nКак в старые времена, а?", progress = nil, completion = "Если бы только мы смогли его спасти...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29653] = {title = "Воля Вождя", objective = "Принесите кулак вождя Каргата каменному стражу Сток'тону в Разрушенные Залы в Цитадели Адского Пламени,", description = "Каргат в свое время был одним из величайших героев орды.\n\nСейчас он носит плащ лже-вождя. Принеси мне его именное оружие, чтобы в нашей памяти он остался великим воителем, каким он был когда-то, а не тем чудовищем, в которое превратился сейчас.", progress = "Ты принес доказательство смерти Каргата?", completion = "Мы должны запомнить Каргата таким, каким он был раньше, и извлечь для себя уроки их его падения.", rewards = "Жезл зловещих тенейПлащ викарияВам дадут возможность выбрать одну из следующих наград:\n\nКолье изуверского кулакаКольцо завоевателя\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29654] = {title = "Новый поворот событий", objective = "Принесите кулак вождя Каргата передовому разведчику Чадвику в Разрушенные Залы в Цитадели Адского Пламени,", description = "Орки Скверны представляют большую угрозу для Оплота Чести и всего Альянса. Покончить с ней можно лишь одним способом.\n\nНадо убить их вождя.\n\nИ принеси мне его именное оружие, чтобы день его гибели навсегда остался в нашей памяти.", progress = "Ты принес мне подтверждение гибели \"вождя\" Каргата Острорука?", completion = "С твоей помощью мы сумели нанести врагу сокрушительный удар.\n\nВпервые за последние годы в Оплоте Чести стало относительно безопасно.", rewards = "Мантия обновленияЖезл страдания ПустоклятаВам дадут возможность выбрать одну из следующих наград:\n\nМедальон доблестного стражаМесть Налико\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29655] = {title = "Особая ткань", objective = "Убейте Омрогга Завоевателя и принесите его боевое облачение каменному стражу Сток'тону в Разрушенные Залы в Цитадели Адского Пламени,", description = "Омрогг Завоеватель убил больше храбрых воинов, чем любой другой враг, с которыми меня сводила судьба. Он безжалостен, хитер и невероятно могуч.\n\nУбей его и принеси мне его боевое облачение. Из него мы сделаем знамя, которое вселит в сердца наших врагов страх перед Ордой!", progress = "Ты принес мне облачение?", completion = "Хорошо. Пусть эти обезумевшие кровожадные твари знают, с кем связались.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29656] = {title = "Боевое облачение Омрогга", objective = "Убейте Омрогга Завоевателя и принесите его боевое облачение передовому разведчику Чадвику в Разрушенные Залы в Цитадели Адского Пламени,", description = "Штормграду нужны доказательства наших успехов в военной кампании.\n\nДумаю, что вместо мешков для трупов стоит продемонстрировать ему боевое облачение Омрогга, самого свирепого воина Каргата. Как думаешь, тебе по силам будет его одолеть?", progress = "Ты принес мне облачение?", completion = "Моих начальников это очень порадует. Спасибо.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29657] = {title = "Кому многое дано, с того много и спросится", objective = "А'дал попросил вас убить механолорда Конденсарона в Механаре, в Крепости Бурь.", description = "<В вашей голове внезапно начинают звенеть колокольчики.*\n\nМеханар использует технологии моей расы для изготовления аккумуляторов маны, мощнейших источников энергии.\n\nМне нужно, чтобы ты <уничтожил/уничтожила> механолорда Конденсарона – тогда силы Кель'таса не смогут воспользоваться этой энергией.>", progress = nil, completion = "Ты отлично поработал, Киберушко, но предстоит сделать еще немало.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29658] = {title = "Паталеон Вычислитель", objective = "А'дал попросил вас убить Паталеона Вычислителя в Механаре, в Крепости Бурь.", description = "<Легкий ветерок обдувает ваше лицо.>\n\nОсталось еще одно дело.\n\nПаталеон Вычислитель надзирает за выполнением многих поручений своего повелителя. Он лично повинен во множестве несчастий, что недавно обрушились на этот мир.\n\nЯ попрошу тебя уничтожить его.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29659] = {title = "Потерянное сокровище", objective = "Добудьте для А'дала Ослепляющую ярость со Склада Легиона в Механаре, в Крепости Бурь.", description = "Я чувствую, что один из артефактов моего народа был похищен и помещен на Склад Легиона.\n\nМы не можем позволить им открыть для себя его истинную мощь. Если ты убьешь стражей ворот и достанешь артефакт, я буду тебе очень благодарен.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29660] = {title = "Спасение Ботаники", objective = "А'дал попросил вас убить командира Саранниса, верховного ботаника Фрейвина и Скалезуба Скорбного в Ботанике, в Крепости Бурь.", description = "Силы Кель'таса в Ботанике не сумели обуздать множество содержавшихся там созданий. Мы должны действовать немедленно, чтобы исправить их ошибки.\n\nПервое, что нужно будет сделать – это уничтожить их силы, чтобы в будущем они не доставили проблем.", progress = nil, completion = "Кабы мы не вмешались, их бы скоро все равно убили содержавшиеся там существа. Это было сделано во имя большего блага.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29667] = {title = "Истребление безнадежных", objective = "А'дал попросил вас убить 6 мутантных плотохлестов, 6 мутантных страховизгов и 6 мутантных ужасов, а также достать быстрорастущую ветку Ладжа в Ботанике, в Крепости Бурь.", description = "Похоже, силы Кель'таса испортили содержащихся в Ботанике особей настолько, что их уже не спасти. Я не хочу, чтобы они вырвались оттуда на волю и хлынули в Запределье.\n\nСреди них есть некий Ладж. Он не такой, как все, и я хочу изучить его. Возможно, мы что-то узнаем.", progress = "Я вижу, ветка у тебя. Это прекрасно.", completion = "Ты уже оказал нам огромную помощь, Фростии. Есть еще одно дело, и я должен просить тебя сделать его.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29669] = {title = "Нерадостное поручение", objective = "А'дал попросил вас убить Узлодревня в Ботанике, в Крепости Бурь.", description = "То, о чем я тебя сейчас попрошу, пронзает мое сердце болью, но у меня нет выбора.\n\nКогда-то Узлодревень был хранителем всей Ботаники, но сейчас и его коснулась скверна. Его нужно будет уничтожить.", progress = nil, completion = "Раньше он был почтенным стражем. Нам будет его очень не хватать.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29674] = {title = "Бездонная тьма", objective = "А'дал попросил вас убить Зерекета Бездонного в Аркатраце, в Крепости Бурь.", description = "*В вашей голове внезапно начинает звенеть колокольный набат.*\n\nМы заточили наиболее опасных созданий, с которыми столкнулись в своих странствиях.\n\nЗерекет – могучий лорд Бездны. Если он сумеет сбежать в Пустоверть, то подпитается там могучей энергией Бездны.", progress = nil, completion = "Существа Бездны по натуре своей всегда хаотичны. Они тоже являются необходимой частью Вселенной, но Свет должен все время приглядывать за ними.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29675] = {title = "Пока, Даллия", objective = "А'дал попросил вас убить Провидца Гнева Соккората и Даллию Глашатая Судьбы в Аркатраце, в Крепости Бурь.", description = "Двое могучих союзников Пылающего Легиона, Провидец Гнева Соккорат и Даллия Глашатай Судьбы, начали собирать из заключенных демонов небольшую армию.\n\nНельзя допустить, чтобы она разрослась – иначе Аркатрац скоро станет очередным оплотом Легиона.", progress = nil, completion = "Легион хочет забрать себе все. Они могут только потреблять; их не заботит баланс.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29681] = {title = "Брешь в системе безопасности", objective = "А'дал попросил вас убить предвестника Скайрисса в Аркатраце, в Крепости Бурь.", description = "Предвестник Скайрисс – вот главная причина несчастья, случившегося в Аркатраце.\n\nОн совратил с истинного пути начальника тюрьмы Мелличара и заставил его выпустить на свободу множество заключенных. Скоро и предвестник окажется на воле – это лишь вопрос времени.\n\n<имя>, ты <должен/должна> уничтожить слугу Древних Богов!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМогущественная подвеска Ша'тарШаттратское колье властиОжерелье восстановления А'дала\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29682] = {title = "Терраса Магистров", objective = "Капитан Терис Рассветное Пламя хочет, чтобы вы отыскали экзарха Ларетора на Террасе Магистров.", description = "Недавно мы отправили к Террасе Магистров экспедиционный отряд, чтобы остановить там силы Легиона.\n\nОднако с тех пор мы не получали от них никаких вестей, и я опасаюсь, что могло произойти самое страшное.\n\nТы можешь отправиться туда и разыскать экзарха Ларетора, руководителя экспедиции?", progress = nil, completion = "Рассветное пламя решил, что мы погибли? Ха!\n\nЯ не посылал ему рапортов только потому, что мы не продвинулись ни на йоту!\n\nНо, может быть, ты поможешь нам изменить ситуацию?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29684] = {title = "Обрыв связи", objective = "Экзарх Ларетор с Террасы Магистров хочет, чтобы вы отыскали Тирита, шпиона эльфов крови.", description = "У нас на Террасе Магистров есть свой агент, который собирал для нас разведданные, но мы потеряли с ним контакт.\n\nИнформация, которой он располагает, очень важна для нашей миссии.", progress = nil, completion = "...Подойди ближе, |3-6(дворф)... Слушай внимательно...", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29685] = {title = "Страшный противник", objective = "Калесгос попросил вас победить Кель'таса на Террасе Магистров. Вы должны будете принести Ларетору на Террасе Магистров голову Келя.", description = "Ты <сам видел/сама видела>, что силы Легиона без устали выкачивают силу из Солнечного Колодца, пытаясь направить ее на осуществление своих зловещих планов.\n\nКель'тас оправился от поражения и снова возглавил армию своих слуг. Его нужно остановить.", progress = "Да, Паладин, должен признаться, я не был уверен, что увижу тебя снова.", completion = "*Ларетор внимательно слушает ваш рассказ о том, что произошло на Террасе Магистров.*\n\nНам будет очень не хватать Тирита. Славный был воин – и надежный товарищ. Но, благодаря тебе, его смерть не стала напрасной.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nХрупкая пунцовая шпинельСверкающая пунцовая шпинель\n\nВы также получите:\n\n"}
MultiLanguageQuestData['ru'][29686] = {title = "Радикальный взгляд", objective = "Экзарх Ларетор с Террасы Магистров хочет, чтобы вы убили Вексалиуса и добыли его сущность.", description = "Мы не имеем права проиграть эту войну. Я хочу задействовать наших дозорных, чтобы не посылать на смерть наших храбрецов.\n\nЛегиону недавно удалось заполучить в свои ряды могучее создание стихий, и для нашего дела нам понадобится его сущность.", progress = "Тебе удалось раздобыть нужную нам сущность?", completion = "Прекрасно! Я как можно скорее представлю этот проект своим начальникам!", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29687] = {title = "Порочные связи", objective = "Экзарх Ларетор с Террасы Магистров хочет, чтобы вы убили Селина Огненное Сердце и жрицу Делриссу.", description = "Легион и силы Кель'таса последнее время стали сотрудничать слишком тесно, и это меня очень беспокоит.\n\nПо имеющимся у нас данным, Селин Огненное Сердце и жрица Делрисса сейчас пытаются объединить две армии вместе. Их нужно остановить.", progress = nil, completion = "Отлично, солдат. Шаг за шагом – к цели.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29688] = {title = "Переход в наступление", objective = "Темный охотник Туджин приказал вам обратиться к каменному стражу Сток'тону, который находится в Разрушенных залах в Цитадели Адского Пламени.", description = "Обычно я слушаю, <класс>. Я выслушиваю всех, чтобы они не беспокоили Вождя.\n\nЯ слышал отчет о текущей ситуации с наступлением на Цитадель Адского Пламени. Настало время атаковать Разрушенные залы, оплот орков Скверны.\n\nПоговорите с каменным стражем Сток'тоном, который командует войсками на месте.", progress = nil, completion = "Держи голову пониже, а то и глазом не моргнешь, как ее проткнет стрелой.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29689] = {title = "Переход в наступление", objective = "Командир армии Данат Троллебой приказал вам поговорить с главным разведчиком Чадвиком, который находится в Разрушенных залах в Цитадели Адского Пламени.", description = "Настало время нанести оркам Скверны последний удар.\n\nГлавный разведчик Чадвик будет ждать тебя внутри Разрушенных залов в Цитадели Адского Пламени. Поторопись, противник может атаковать Оплот Чести в любой момент!", progress = nil, completion = "Тихо! Если они заметят нас сейчас – у нас не будет никаких шансов.", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29690] = {title = "Сквозь туман", objective = "Поговорите с генералом Назгримом на борту \"Кулака Адского Крика\".", description = "<Назгрим вдыхает морской воздух.>\n\nЧувствуешь, <имя>? Это запах родного дома – земли, за которую наш род пролил много крови.\n\nИ прислушайся... ты слышишь это? Так звучат мир и спокойствие в созданном нами прибежище, куда наши враги боятся ступить.\n\nЗапомни это ощущение, оно вернется к тебе не скоро. Нас ждет война, в которой мы должны победить.\n\nА теперь иди собираться – мы отправляемся!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29691] = {title = "Принеси мне клумбу!", objective = "Соберите 5 цветков кровавого гибискуса и принесите их Тшу в Нижетопь.", description = "Мой народ использует кровавый гибискус для многих вещей.\n\nК несчастью, после понижения уровня вод осталось только одно место, где его можно найти.\n\nЕсли ты принесешь мне немного гибискуса, я буду тебе очень признателен.", progress = "Удалось ли тебе собрать гибискус?", completion = "Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты еще раз заглянешь в Нижетопь?", rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29692] = {title = "Принеси мне еще одну клумбу!", objective = "Нам все еще нужен кровавый гибискус. Найти его – огромная проблема.\n\nПринеси мне пять гибискусов – и моя благодарность будет безграничной.", description = nil, progress = "Нам все еще нужен кровавый гибискус. Найти его – огромная проблема.\n\nПринеси мне пять гибискусов – и моя благодарность будет безграничной.", completion = "Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты еще раз заглянешь в Нижетопь?", rewards = nil}
MultiLanguageQuestData['ru'][29694] = {title = "Перегруппировка!", objective = "Спасите Темного мастера Кирин, Риветта Сталехвата, Шокию и сержанта Горрока с Поляны Медовой Росы.", description = "Стало быть, у них есть авиабаза! На этот раз я недооценил капитана Альянса. Погибло так много хороших бойцов...\n\nНекоторым удалось пережить крушение, а нам сейчас пригодится любая помощь.\n\nРазыщи в лесу всех, кого сможешь, и осмотри место крушения. Собери бойцов в ближайшей деревне для контратаки.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Тлеющая корабельная балкаДворфоруб Зин'ДжунаЛопатка разобранного ротораПоврежденный пушкой щитХозенская колотильная палицаАбордажная доска морякаВы получите:\n\n"}
MultiLanguageQuestData['ru'][29696] = {title = "Мои звездочки!", objective = "Отнимите 100 метательных звезд Кирин у коварных лесных духов.", description = "Вещи Кирин растащили лесные духи – но ваше внимание привлекло именно это.\n\nКогда-то сумка, набитая метательными звездочками, висела у нее на поясе. \"Звездочки\" составляли важную часть ее арсенала.\n\nИ если вам удастся отнять это оружие у местного зверья, это очень поможет в дальнейшем.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29715] = {title = "Ведьма в лесу", objective = "Найдите Ань Воздушный Мех на дороге, к северу от хижины Нефритовой ведьмы.<раса>, ты мне поможешь? Ну, пожалуйста!\n\nДеревенские ребятишки убежали играть в лес и не вернулись. Если пойдешь в ту сторону, может, поищешь их?\n\nСто раз сорванцам было сказано, чтобы они оставили в покое вдову, которая живет в лесу. Думаю, они сейчас там. Им кажется, что она ведьма, вот и дразнят ее.", description = "<раса>, ты мне поможешь? Ну, пожалуйста!\n\nДеревенские ребятишки убежали играть в лес и не вернулись. Если пойдешь в ту сторону, может, поищешь их?\n\nСто раз сорванцам было сказано, чтобы они оставили в покое вдову, которая живет в лесу. Думаю, они сейчас там. Им кажется, что она ведьма, вот и дразнят ее.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][29725] = {title = "Отчет ШРУ: небесный огонь", objective = "Выслушайте доклад Салли.", description = "Да, Эмбер мы нашли, она жива и с ней все в порядке. На этом хорошие новости заканчиваются.\n\nПосмотрим, удастся ли мне продолжить историю старины Релла...Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][29732] = {title = "Что упало, то не пропало", objective = "Добудьте припасы с помощью гоблинского автотранспортера рядом с Обнажившимся корнем.\n\nПримечание: для каждого использования необходим один закрученный хвост горного летуна.", description = "Риветт оставил какую-то важную машину. На ее ручке вы смогли разобрать слова: \"Гоблинский автотранспортер\".\n\nЕсли это устройство немного откалибровать, оно сможет доставить роботов в главный лагерь Назгрима.\n\nЭто просто...\n\nНо есть одна сложность.\n\nВо время аварии ящики с припасами оказались на уступе, ниже места падения.\n\nРазмышляя над тем, как их достать, краем глаза вы замечаете длинный свернутый кольцами хвост пролетающего мимо горного летуна...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #5Предмет #1"}
