MultiLanguageQuestData['ru'][30181] = {title = "Охота на мушанов", objective = "Убейте 15 серобоких мушанов.", description = "Мушаны! И какие огромные! Им, наверное, столько же лет, сколько и этой земле. Замечательные трофеи.\n\nЕсли хочешь попробовать свои силы в охоте на крупную дичь, начни с них.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][30183] = {title = "Охота на тигров", objective = "Убейте 15 горных хищников.", description = "Тигры! Куда бы я ни пошла, постоянно слышу про этих клыкастых тварей. Но шанса поохотиться на них у меня пока не было.\n\nТак что давай устроим охоту на тигров. Я пойду на восток, ты иди на запад. Кажется, я видела какую-то стаю около Серого ущелья. Ну и возле мушанов их, наверняка, полно.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Атласные поножи ХемингаПрочные кожаные набедренники ХемингаКольчатые поножи ХемингаВороненые ножные латы ХемингаШелковые брюки ХемингаКожаные набедренники ХемингаПоножи диких равнинТяжелые набедренники ХемингаБронированные набедренники ХемингаВы получите:\n\n"}
MultiLanguageQuestData['ru'][30197] = {title = "Поездка на повозке", objective = "Отвезите повозку с припасами в деревню XXX.Тихо сегодня в нашем доле. Я пошлю Рука на повозке с припасами в деревню XXX. Отправляйся с ним.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Тихо сегодня в нашем доле. Я пошлю Рука на повозке с припасами в деревню XXX. Отправляйся с ним.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
