MultiLanguageQuestData['ru'][30311] = {title = "Выше знамена!", objective = "Поднимите 6 знамен Золотого Лотоса.", description = "Если бы меня попросили назвать самое важное качество для боевого знамени, я бы сказал, что оно должно быть поднято и видно каждому издали. И видно не потому, что оно горит, а потому что оно высоко и уверенно вздернуто. Само собой разумеется, я обеспокоен ситуацией со знаменами на данный момент.\n\nЕсли бы <господин неизвестный/госпожа неизвестная:c> <класс> <вызвался/вызвалась> пройтись через поле боя на северо-запад и установить знамена, то и моей благодарности, и, конечно же, благодарности моей чертовски сексуальной жены-командира не было бы предела.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
