MultiLanguageQuestData['ru'][30534] = {title = "Вторые руки", objective = "Уговорите одного из своих друзей поработать на Ферме Солнечной Песни.", description = "Несмотря на все ваши усилия, дел только прибавляется.\n\nВозможно, вы могли бы пригласить на Ферму Солнечной Песни одного из своих друзей.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
