MultiLanguageQuestData['ru'][31611] = {title = "Куньлайский сногсшибатель", objective = "Защитите фестиваль Хмельнолуния.", description = "Ты <был/была> когда-нибудь на фестивале Хмельнолуния?\n\nДобрые жители деревни Бинан устраивают славную пирушку. И сегодня напитки для нее предоставит никто иной, как твой покорный слуга.\n\nЯ приготовлю свой знаменитый куньлайский сногсшибатель!\n\nНе желаешь ли повеселиться вместе с нами? Праздник обещает быть очень радостным, мы забудем обо всех заботах – ведь опасность нам не грозит.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31613] = {title = "Отвар Зеленой Скалы", objective = "Помогите защитить деревню Зеленой Скалы.", description = "Я сейчас готовлю свой знаменитый отвар Зеленой Скалы.\n\nОн пригодится нам в борьбе с негодяями и всякими злодеями, которых сейчас полно в шахтах.\n\nВот что я скажу – может, соберешь друзей да и приведешь их сюда, чтобы попробовали мой напиток?\n\nПервая кружка – за счет заведения!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31660] = {title = "Обуза для роя", objective = "Убейте 30 роерожденных во Владениях Шек'зир.", description = "У только что появившихся на свет богомолов есть только два инстинкта: есть и убивать. Они нападают на сородичей, пожирая слабых и оставляя в живых сильнейших.\n\nВсе меняется, когда приходит время роя: роерожденные нападают лишь на врагов.\n\nНо роерожденные из Владений Шек'зир осквернены. Они появляются на свет в тенях и кошмарах, их ведет не голод, а ужас.\n\nОни обуза для роя, и они должны быть уничтожены.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nCancel Aura: Angel of Death Preview\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][31685] = {title = "Долина Четырех Ветров", objective = "Телепортируйтесь в Долину Четырех Ветров и поговорите с рядовым В. Ременным.", description = "Арр! Нефритовый лес закрыт на принудительную реконструкцию, зато Долина Четырех Ветров созрела для исследований. Скажешь, когда будешь <готов/готова>, и я подброшу тебя, куда захочешь. На той стороне мой приятель подкинет тебе вещичек в дорогу.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nLevel to 86"}
MultiLanguageQuestData['ru'][31690] = {title = "Покрытый письменами тигриный посох", objective = "Принесите ваш покрытый письменами тигриный посох мастеру каллиграфии Глень-цзу в Дендрарий.", description = "Этот посох очень мощный, но вы понимаете, что рано или поздно \"перерастете\" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][31691] = {title = "Покрытый письменами журавлиный посох", objective = "Принесите ваш покрытый письменами журавлиный посох мастеру каллиграфии Цзо По в Дендрарий.", description = "Этот посох очень мощный, но вы понимаете, что рано или поздно \"перерастете\" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][31692] = {title = "Покрытый письменами змеиный посох", objective = "Принесите ваш покрытый письменами змеиный посох мастеру каллиграфии Вэю в Дендрарий.", description = "Этот посох очень мощный, но вы понимаете, что рано или поздно \"перерастете\" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][31694] = {title = "Хисинген Блюз", objective = "test log desc ! 1 Джулия Стивенс Джулия Стивенс 1 test cona Джулия Стивенс fodasse $o1x caracois $o1 crl\n\n*DO NOT LOCALIZE*", description = "test desc! $1oa $1oo $1oo $1oa test cona $oo fodasse $oa caracois $1ox $9o crl\n\n*DO NOT LOCALIZE*", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][31723] = {title = "Долина Четырех Ветров", objective = "Поговорите с рядовым В. Ременным в Долине Четырех Ветров.", description = "Арр! Нефритовый лес закрыт на принудительную реконструкцию, зато Долина Четырех Ветров созрела для исследований. Я могу помочь, если захочешь посетить ее. В моих закромах найдется немало полезных вещичек в дорогу.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nLevel to 86"}
MultiLanguageQuestData['ru'][31726] = {title = "Эрик Дэвидсон", objective = "Победите Эрика Дэвидсона в битве питомцев.", description = "Все мои друзья говорят об ужасном воргене по имени Эрик Дэвидсон из Сумеречного леса, с которым еще никто не устраивал битв питомцев.\n\nДумаю, если тебе удастся найти и победить его, то после этой победы все будут говорить только о тебе!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31727] = {title = "Поиск припасов", objective = "Поговорите с боцманом Ари в Приюте капитана, что в Жутких пустошах.Если мы хотим выиграть эту войну, нельзя упустить ни единой мелочи.\n\nВдоль побережья были замечены посторонние. Нам не нужны чужаки, но их припасы могут пригодиться.\n\nЕсли там есть что-то полезное, мы должны опередить императрицу и завладеть этим.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Если мы хотим выиграть эту войну, нельзя упустить ни единой мелочи.\n\nВдоль побережья были замечены посторонние. Нам не нужны чужаки, но их припасы могут пригодиться.\n\nЕсли там есть что-то полезное, мы должны опередить императрицу и завладеть этим.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31732] = {title = "Да разверзнется ад", objective = "Летите на гирокоптере \"Небесного огня\", чтобы уничтожить 60 солдат лагеря Гаррош'ар и 8 крошшеров лагеря Гаррош'ар, а затем потопите \"Жнец Кровавого Кулака\" и \"Адский Шрам\".", description = "Я не позволю Орде закрепиться на этих берегах раньше нас! Если ищешь приключений на свою голову, то можешь взять гирокоптер, который стоит на корме. Он уже подготовлен к атаке, так что от тебя просто требуется пострелять.\n\nЗадай жару этим оркам!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Взламывающий нож СаллиСнайперская винтовка моряка воздушного суднаДубинка крушителя баррикадПосох рассекающего туманПосох небесного магаЗагадочная палица вечного движенияПосох лекаря \"Небесного огня\"Боевой топор штурмовикаПостукивающая трость капитана РоджерсаПалица бойца \"Небесного огня\"Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31734] = {title = "Яркая встреча", objective = "Используйте сигнальный пистолет Салли, чтобы уничтожить 5 боевых повозок Орды.", description = "Ты <видел/видела>, какого размера эти боевые повозки? Там напихано столько взрывчатки, что можно подумать, будто Орда хочет не захватить континент, а разнести его на кусочки!\n\nНам надо обезвредить эти повозки, пока они еще в лагере Гаррош'ар.\n\nВот, возьми эти карманные ракеты. Выпусти их в повозку и полюбуйся фейерверком!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][31736] = {title = "Посланник Альянса", objective = "Найдите мэра деревни Лап'дон и поговорите с ним.", description = "К северу от этого лагеря находится вишневый сад, а за ним прячется деревенька. Нам надо будет остановиться там и перевязать раненых, пока мы будем готовить наш следующий ход.\n\nОтправляйся в эту деревню и поговори с тамошним предводителем. Мы с агентом Мишкой встретим тебя там.\n\nИ будь повежливей, <имя>! Я возлагаю на тебя честь представлять весь Альянс. Не заставь меня пожалеть об этом.\n\nНадеюсь, что <такой могущественный герой/такая могущественная воительница> как ты произведет на них хорошее впечатление.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nEnvoy of the Alliance: Completion Event\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][31737] = {title = "Цена войны", objective = "Убейте 15 наваждений ша и 5 ша – вестников ужаса в лагере Гаррош'ар.", description = "Тут все пылает, а с \"Небесного огня\" докладывают, что еще больше этих... теней выползает из земли. Нам надо уводить всех прочь отсюда.\n\nРасчисти путь через лагерь по дороге на север и направляйся в город. Я встречу тебя там.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nThe Cost of War: Summon Rell\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][31738] = {title = "Батраки-мародеры", objective = "Убейте 12 надсмотрщиков или батраков Двух Башен.", description = "Как наша деревня стала полем боя?\n\nК западу отсюда негодяи из Орды вырубают наш бесценный сад. Без яблоневых деревьев пропадет вся деревня – не будет ни урожая, ни еды, ни заработка.\n\nЕсли ты действительно не <такой/такая> как они, докажи нам это! Защити сад и накажи тех, кто бесчинствует на нашей земле!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31739] = {title = "Приоритеты!", objective = "Соберите 6 бочек сидра Яблоневого Цвета.", description = "Эти так называемые \"орки\" разграбили хмелеварню и сбежали с бочками моего лучшего сидра!\n\nЯ знаю, что повсюду война, но я не тот хмелевар, который будет стоять и смотреть на то, как его коллекционный напиток пьют недостойные его личности!\n\nЭта \"Орда\" получит отпор.\n\nПочему бы тебе не обратить свое оружие на доброе дело и не помочь мне вернуть мой сидр?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31741] = {title = "Крепость Двух Башен", objective = "Убейте 15 солдат Орды в Крепости Двух Башен.", description = "Я не доверяю Орде. Ее представители используют темную магию и явно не с добрыми намерениями. Мы больше не можем терпеть их присутствие в Крепости Двух Башен, в двух шагах от деревни Лап'дон.\n\nУмоляю, <чужестранец/чужестранка>, помоги нам, а не то с нашей деревней случится что-то ужасное.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31742] = {title = "Разрозненные силы", objective = "Убить Далгана и Белландру Бурю Скверны.", description = "Орда сама делает за нас всю работу. Их грызня и разрозненность раскололи лагерь надвое: орки на западе, нежить на востоке.\n\nОрки подчиняются своему командиру Далгану, а нежить следует за Белландрой Бурей Скверны, могучей чернокнижницей. Если повезет, то внутренние стычки отвлекут их, и ты сможешь пробраться внутрь и убить обоих. Салли уже засел в руинах. Найди его там, когда закончишь.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31743] = {title = "Дым над Ордой", objective = "Используйте сигнальный огонь Альянса, чтобы вызвать воздушный удар по груде боеприпасов, разрушителям Двух Башен, диким бесам и Ксу'даггабе.", description = "Салли обнаружил лагерь Орды к северу отсюда и доложил, что видел огромную кучу взрывчатки, а также небольшую группу разрушителей. И это не считая демонов, которых призвали чернокнижники.\n\nК счастью, мы были готовы к этому. \"Небесный огонь\" поддержит нас с воздуха. Надо только показать нашим пилотам, куда бить.\n\n<Релл подает дымовую сигнальную ракету и со значением кивает.>Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][31744] = {title = "Нечестная торговля", objective = "Освободите 8 захваченных юных пандаренов из Крепости Двух Башен, уничтожив демонические очи, которые их сторожат.", description = "Хоть мы и только познакомились, у нас есть общий враг – так называемая \"Орда\".\n\nНесколько дней назад их командир предложил нам сделку. Когда мы отказались, его прислужники похитили наших детей, чтобы выбить из нас согласие.\n\nМы обратились за помощью к монахам Шадо-Пан, но вершина Кунь-Лай от нас в нескольких днях пути. Ты можешь нам помочь?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31752] = {title = "Блескотрон-4000", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['ru'][31765] = {title = "Раскрась мир красным!", objective = "Используйте башню боевого корабля, чтобы уничтожить 80 солдат и 9 пушек Громовой крепости.", description = "Они вырубили наши двигатели, и мы упали здесь... здесь! Прямо на вражеской линии огня!\n\nТы знаешь, что надо делать, <имя>. Спускайся под палубы и встань за орудия!\n\nПокажи этим уродам, что они на нашей линии огня!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Отсекатель парашютного тросаЗапасное корабельное орудиеДубина покорителя земельПосох идущего сквозь туманыПосох громовых раскатовБоевая дубина призывателя бурьПосох полевого лекаряБоевой топор авангарда ГаррошаБольшой топор из арсенала корабляВы получите:\n\n"}
MultiLanguageQuestData['ru'][31766] = {title = "Коснуться земли", objective = "Используйте канат для спуска, чтобы добраться до земли.", description = "Назгрим возглавил наземную операцию и попросил немедленно прислать тебя к нему.\n\nУ нас есть несколько канатов для спуска, привязанных возле орудий. Это самый быстрый путь вниз – ну, из тех, что заканчиваются удачно.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31767] = {title = "Прикончить их!", objective = "Уничтожьте 15 солдат Громовой крепости.", description = "Мы их потрепали. Пора их прикончить!\n\nЭту крепость надо очистить от Альянса, и нам негде держать пленников.\n\n<На лице Назгрима мелькает тень улыбки.>\n\nТы знаешь, что делать, <имя>. Эти трусы побегут, если дать им шанс.\n\nПостарайся им его не дать!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31768] = {title = "Огонь – лучший ответ", objective = "Уничтожьте 10 штабелей боеприпасов Громовой крепости.", description = "Уничтожить их силы недостаточно. Нельзя оставить им ни единого шанса на спасение!\n\nВозьми это ружье и выстрели из него в боеприпасы. Пусть останутся ни с чем!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][31769] = {title = "Завершающий удар!", objective = "Уничтожьте капитана Дорена в Громовой крепости.", description = "Мы узнали, что их капитан забаррикадировался над нами.\n\nЭтот трус отправил свои отряды на смерть, а сам спрятался от нашего гнева! Типично для Альянса! Неважно. Он больше не сможет бежать от судьбы.\n\nЯ поведу своих пехотинцев на стены, а ты возглавишь основную атаку на крепостные валы. Используй ружье для подрыва взрывчатки, чтобы пробить себе дорогу.\n\nВстретимся наверху и вместе расправимся с этим ничтожеством, которое называет себя капитаном!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nAirship Crash 2\n\nВы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][31770] = {title = "Или с нами, или...", objective = "Попытайтесь заручиться поддержкой мэра Медовая Роса в Деревне Медовой Росы.", description = "Помощь жителей соседней деревушки стала необходимостью, <имя>.\n\nНам нужна эта деревня, чтобы позаботиться о раненых и перегруппироваться.\n\nМожет быть, ее жители помогут нам после того, как стали свидетелями жестокости Альянса.\n\nТы будешь посланником Орды. Обеспечь нам помощь со стороны их главы. И не разочаруй меня!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31771] = {title = "Лицом к лицу с последствиями", objective = "Убейте 20 наваждений ша и 7 ша – вестников ужаса.", description = "Я не знаю предыстории вашей войны, да и не хочу ее знать. Наша земля живо реагирует на любую отрицательную энергию. Ненависть, сомнение и насилие, которые вы принесли с собой, яростно хлещут из ран Пандарии.\n\nТо, что вы натворили, посеяло хаос в руинах! Иди же туда и приведи все в порядок, а затем возвращайся ко мне. Я постараюсь объяснить тебе, что произошло.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nPing Taran Zhu Completion Event\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][31773] = {title = "Докучливые хищники", objective = "Уничтожьте 10 зараженных ша хищников на Поляне Медовой Росы.", description = "Все животные взбесились!\n\nОбычно хищники держатся подальше от деревни, но теперь мы не можем их отогнать! Они себя раньше так никогда не вели!\n\nМэр даже позвал на помощь Шадо-Пан, но пока еще никто не приехал. Не <мог/могла> бы ты разобраться с хищниками, пока они не задрали одного из фермеров?Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nPing Taran Zhu Completion Event\n\nВы получите:\n\n"}
