MultiLanguageQuestData['ru'][31886] = {title = "Жуткое место", objective = "Поговорите с лучницей Ли на Змеином хребте.Лучники Шадо-Пан неотступно следят за Жуткими пустошами с вершин Змеиного хребта. Им очень пригодится помощь <хорошего/хорошей:c> <класс>.\n\nВозьми воздушный змей и зайди к лучнице Ли.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Лучники Шадо-Пан неотступно следят за Жуткими пустошами с вершин Змеиного хребта. Им очень пригодится помощь <хорошего/хорошей:c> <класс>.\n\nВозьми воздушный змей и зайди к лучнице Ли.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
MultiLanguageQuestData['ru'][31936] = {title = "Поливная система \"Принцесса цзинь-юй\"", objective = "Отнесите поливную систему \"Принцесса цзинь-юй\" фермеру Юну, который находится на ферме Солнечной Песни или на рынке Полугорья.\n\nПрилагается предмет: \n", description = "<На обратной стороне коробки рисунок – девушка-цзинь-юй в окружении рекламных проспектов.>\n\n\"Эй, огородник! Все еще грустишь по засохшим тыквам? Плачешь над увядшей капустой? У тебя луковые страдания и дынная меланхолия?\n\nТогда купи \"Принцессу цзинь-юй\"! Она омоет твой сад, словно чудесный весенний дождь, она напоит...\"\n\n<И так далее в том же духе еще шесть абзацев.>\"Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][31937] = {title = "Инсектицид \"Властелин Грома\"", objective = "Отнесите инсектицид \"Властелин Грома\" фермеру Юну, который находится на Ферме Солнечной Песни или на рынке Полугорья.\n\nПрилагается предмет: \n", description = "<На коробке изображена грозная физиономия могу – существо смотрит вниз, на аккуратные строчки.>\n\n\"НЕ ДАЙТЕ СЛАБЫМ, ОТВРАТИТЕЛЬНЫМ НАСЕКОМЫМ СОЖРАТЬ ВАШ ПРЕКРАСНЫЙ УРОЖАЙ. ОБРУШЬТЕ НА НИХ ВСЮ МОЩЬ \"ВЛАСТЕЛИНА ГРОМА\" И ЗАЩИТИТЕ СВОЕ ИМУЩЕСТВО\".\n\n<Остальное место занято изображением различных насекомых, которые рыдают от ужаса или спасаются бегством.>Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][31938] = {title = "Суперплуг \"Бороздящий землю\"", objective = "Отнесите суперплуг \"Бороздящий землю\" фермеру Юну, который находится на ферме Солнечной Песни или на рынке Полугорья.\n\nПрилагается предмет: \n", description = "<На коробке изображен неестественно мускулистый крестьянин-пандарен, идущий за плугом. За ним тянется широкая борозда. На руках и плечах пандарена повисли шаловливые дети.\n\nРядом с крестьянином – столь же мускулистая женщина; на голове она изящно удерживает рог изобилия, а ногой ловко бьет по морде гну-синя.>\n\n\"Бороздящий землю. Вы – хозяин земли. Вы – хозяин жизни\".Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #1"}
MultiLanguageQuestData['ru'][31978] = {title = "Приоритеты!", objective = "Найдите 6 бочек медового хмеля на поляне Медовой Росы.", description = "Только посмотрите на этот бардак! Весь хмель пропал!\n\nТажань Чжу предупреждал, чтобы мы держались от подальше от чужаков, но сейчас нам пригодится любая помощь.\n\nМы везли хмель в Цветущую Зарю, как вдруг начался бой. И все наше добро пропало!\n\nХочешь помочь нам? Может быть, ты найдешь какие-нибудь уцелевшие бочки с медовым хмелем? Тогда наши потери не будут столь ужасными.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
