MultiLanguageQuestData['ru'][32246] = {title = "Встреча с разведчицей", objective = "Поговорите с разведчицей Линной в Красарангской бухте, что в Красарангских джунглях.Прошло уже два месяца с того момента, как разошлась пелена туманов. В поисках подходящего места для высадки разведчики Альянса столкнулись с отрядом Орды на берегах Красарангских джунглей.\n\nПовстречайся с разведчицей Линной и помоги защитить место для высадки.Следующее заклинание будет наложено на вас:\n\n", description = "Прошло уже два месяца с того момента, как разошлась пелена туманов. В поисках подходящего места для высадки разведчики Альянса столкнулись с отрядом Орды на берегах Красарангских джунглей.\n\nПовстречайся с разведчицей Линной и помоги защитить место для высадки.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nMeet the Scout: Varian Lands\n\nВы получите:\n\n"}
MultiLanguageQuestData['ru'][32249] = {title = "Встреча с разведчицей", objective = "Поговорите с разведчицей Роклой в Точке высадки Орды, что в Красарангских джунглях.Прошло уже два месяца с того момента, как разошлась пелена туманов. В поисках подходящего места для высадки флота, разведчики Орды столкнулись с отрядом Альянса на небольшом островке недалеко от Красарангских джунглей.\n\nВстреться с разведчицей Роклой и помоги защитить место для высадки.Следующее заклинание будет наложено на вас:\n\n", description = "Прошло уже два месяца с того момента, как разошлась пелена туманов. В поисках подходящего места для высадки флота, разведчики Орды столкнулись с отрядом Альянса на небольшом островке недалеко от Красарангских джунглей.\n\nВстреться с разведчицей Роклой и помоги защитить место для высадки.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nMeet the Scout: Garrosh Lands\n\nВы получите:\n\n"}
