MultiLanguageQuestData['ru'][82988] = {title = "Талантливый герой", objective = "Откройте интерфейс талантов и распределите 5 очков талантов.", description = "Каждый из нас использует свой собственный набор способностей и талантов, <класс>. Мы отличаемся друг от друга, у нас разные задатки и наклонности.\n\nСтав сильнее, ты сможешь усиливать и специализировать свои способности, выбирая таланты, – для этого тебе даже не понадобится наставник.\n\nА вот если ты захочешь сменить таланты, тебе придется посетить наставника.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСвиток телепортации: Оргриммар"}
MultiLanguageQuestData['ru'][82989] = {title = "Доска приказов вождя", objective = "Воспользуйтесь свитком из вашей сумки, чтобы телепортироваться в Оргриммар, и поговорите с глашатаем вождя.", description = "По приказу вождя Гарроша Адского Крика я призываю всех |3-8(<класс>) взяться за оружие и помочь Орде в кампаниях по всему Азероту!\n\n\n Ты <готов/готова>, $p.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"}
